INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('vn-canh-01', 'canh-chua-ca-loc-nam-bo', 0, 'Canh chua cá lóc Nam Bộ', 'Canh cá lóc chua thanh từ me chín, ngọt dịu dứa thơm cùng đậu bắp, bạc hà và rau thơm đặc trưng miền Tây', 'Bát canh chua cá lóc Nam Bộ đậm đà với thịt cá trắng ngọt săn chắc, nước dùng thanh nhẹ hòa quyện vị chua dịu từ me chín, ngọt thanh của dứa chín và rau củ giòn tươi.', 'Dọn canh nóng vào tô lớn, rắc tỏi phi thơm cùng rau ngổ, ngò gai; ăn kèm cơm trắng và chén nước mắm ớt mặn để chấm thịt cá.', 'Nên dùng hết trong ngày để giữ độ giòn của rau; nếu bảo quản tủ mát tối đa 24 giờ, nên vớt riêng phần rau sống/giá đỗ và đun sôi lại phần nước canh cùng cá trước khi ăn.', 'vietnamese', 'mon_canh', 'nam', 'medium', 20, 25, 4, 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=800&q=80', '["Món canh","Nam Bộ","Thanh nhiệt","Cá tươi","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 262, 262.3, 1097, 22.6, 7.9, 1.5, 27.3, 3.8, 17.8, 1278, 3.2, '["NIN VN Doc Mung Ref","USDA FDC 169124","USDA FDC 169230","USDA FDC 169260","USDA FDC 169655","USDA FDC 169918","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","VN Culinary Herb Ref","VN Herb Ref"]', '3a3ad657206f987f6806c371e38da6a65eae87d0214f2686ecd072a3817f0533', 'c9e27ff168ca194acc847981e540d9900d783f2bb253fd7c863ddc6d411de725', 4),
('vn-canh-02', 'canh-cua-dong-rau-day-mong-toi', 1, 'Canh cua đồng rau đay mồng tơi mướp hương', 'Món canh giải nhiệt trứ danh mùa hè miền Bắc với tảng riêu cua đồng béo ngậy nấu cùng rau đay, mồng tơi và mướp hương thơm ngọt', 'Bát canh cua đồng thanh mát chuẩn vị Bắc Bộ với phần riêu cua kết mảng dày béo thơm, gạch cua chưng vàng óng quyện cùng rau đay, mồng tơi mềm mướt và mướp hương ngọt dịu.', 'Dọn canh nóng vào tô lớn, gạt nhẹ tảng riêu cua nổi lên mặt cho đẹp mắt; ăn kèm cơm trắng và đĩa cà pháo muối giòn.', 'Canh cua rau đay ngon nhất khi dùng hết trong ngày vì rau dễ bị nhớt và xuống màu; nếu bảo quản tủ mát, chỉ giữ phần nước riêu tối đa 12 giờ và đun sôi lại kỹ.', 'vietnamese', 'mon_canh', 'bac', 'medium', 25, 20, 4, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món canh","Miền Bắc","Mùa hè","Cua đồng","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crab","crustaceans","fish","shrimp"]', 124, 123.5, 517, 15.3, 4.2, 0.7, 6.9, 2.6, 1.8, 1420, 3.55, '["Asian Shrimp Paste Ref","USDA FDC 168421","USDA FDC 169249","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '5eec2917a08d21f741299b6de1690b65e5f63840a73fab47c56db3fd8115dc93', 'b930d88edece775932bda17c441e2ab6dabeb1d3fc85ee2dc884535695bb4bc1', 4),
('vn-canh-03', 'canh-kho-qua-nhoi-thit', 2, 'Canh khổ qua nhồi thịt thanh mát', 'Khổ qua xanh giòn dịu vị đắng, ôm trọn nhân thịt heo xay quyện mộc nhĩ thơm bùi trong nước dùng trong ngọt thanh nhiệt', 'Món canh truyền thống thanh mát với từng khoanh khổ qua xanh mềm vừa phải, giảm hẳn vị đắng gắt, bao bọc nhân thịt heo xay đậm đà giòn sần sật mộc nhĩ cùng nước canh ngọt dịu.', 'Cắt khúc khổ qua nhồi thịt thành khoanh vừa ăn, xếp vào tô chan nước dùng nóng, rắc hành ngò và tiêu xay; dùng kèm cơm trắng hoặc chén nước mắm ớt.', 'Mở hé nắp khi canh vừa nguội để tránh đọng hơi nước làm canh nhanh chua; bảo quản ngăn mát tối đa 24 giờ và đun sôi kỹ trước khi dùng lại.', 'vietnamese', 'mon_canh', 'nam', 'medium', 25, 30, 4, 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món canh","Nam Bộ","Thanh nhiệt","Truyền thống","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["egg","pork"]', 240, 240.1, 1004, 14.5, 14.7, 5.3, 13.8, 7.8, 3.7, 984, 2.46, '["USDA FDC 167902","USDA FDC 168393","USDA FDC 168437","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '0de3c6ecd03c2f29ddd622ca434d51afd492038b3e0d628c8130417b73283ff6', '6abd7d7a9fc37b760601f15afc8859b80df857bc21ae0d32410ecc383888e229', 4),
('vn-canh-04', 'canh-suon-bi-dao', 3, 'Canh sườn hầm bí đao ngọt thanh', 'Sườn non heo ninh mềm róc xương hòa quyện vị ngọt mát tự nhiên của bí đao xanh, thơm mùi hành lá và ngò gai', 'Món canh gia đình quen thuộc với nước hầm sườn non trong veo, thịt sườn mềm tơi thấm vị, kết hợp bí đao chín tới trong mướt, giữ trọn vị ngọt mát và thanh nhẹ.', 'Múc canh sườn bí đao ra tô lớn khi còn nóng, rắc hành lá, ngò gai và chút tiêu xay; dọn cùng cơm trắng và các món mặn như thịt kho hoặc cá chiên.', 'Canh sườn bí đao bảo quản trong hộp kín ở ngăn mát tủ lạnh được 1–2 ngày; khi ăn lại chỉ cần đun sôi lăn tăn vừa đủ nóng để bí không bị nhũn nát.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 35, 4, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=800&q=80', '["Món canh","Cơm nhà","Bổ dưỡng","Thanh mát","Dễ nấu"]', '["lunch","dinner"]', '["boil","simmer"]', '["fish","pork"]', 260, 260.4, 1089, 12.7, 20.6, 6.8, 6.1, 3.3, 2.3, 1458, 3.65, '["USDA FDC 167861","USDA FDC 169214","USDA FDC 169231","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', '8241f864d7db77000fc64fe6c0c64fedbada174536a0cc6c4b3173bc74311c55', '93d56a3a6a6c3b3e6f53f0df50d388ba59e9795201ef2abb5db486c50f44aee3', 4),
('vn-canh-05', 'canh-bi-do-thit-bam', 4, 'Canh bí đỏ thịt bằm hạt sen', 'Bí đỏ chín bùi sánh mịn nấu cùng thịt heo nạc băm ngọt đậm và hạt sen bở thơm, giàu dinh dưỡng cho mọi lứa tuổi', 'Tô canh vàng óng bắt mắt với từng miếng bí đỏ mềm bùi tan nhẹ, hạt sen bở thơm quyện cùng thịt heo băm xào tơi đậm đà và mùi thơm dịu của hành lá, ngò gai.', 'Dọn canh nóng vào tô lớn, rắc thêm ngò gai thái nhỏ và chút tiêu xay; ăn kèm cơm trắng rất hợp cho bữa tối gia đình có trẻ nhỏ và người lớn tuổi.', 'Để canh nguội hoàn toàn rồi bảo quản trong hộp kín ở ngăn mát tối đa 24 giờ; khi hâm lại nên đun lửa nhỏ và khuấy nhẹ để phần bí sánh không bén đáy nồi.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 22, 4, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món canh","Bổ dưỡng","Cơm nhà","Trẻ em thích","Nhanh gọn"]', '["lunch","dinner"]', '["simmer"]', '["fish","pork"]', 231, 230.6, 965, 11.2, 14.2, 4.5, 15.6, 1.4, 5.8, 1282, 3.21, '["USDA FDC 167902","USDA FDC 168448","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170148 Fresh","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', 'eb715f5672a55698fa18e87c1af029e5e17ae8287d8e9a983fa9644f4e859131', '2f8650c56faac564cd7ca5190567ebcafaa5bf78f7380470babc0b3e4c8b6a95', 4),
('vn-canh-06', 'canh-ngao-nau-chua-thi-la', 5, 'Canh ngao nấu chua thì là', 'Nước luộc ngao ngọt khiết kết hợp vị chua dịu từ dứa, cà chua và hương thơm nồng đặc trưng của rau thì là chuẩn vị Bắc', 'Món canh giải nhiệt thanh đạm quen thuộc trong mâm cơm miền Bắc với phần nước luộc ngao trong vắt ngọt tự nhiên, chua dịu hài hòa từ dứa và cà chua cùng mùi thơm quyến rũ của thì là.', 'Múc canh ngao ra tô lớn khi vừa chín tới, ăn nóng cùng cơm trắng hoặc chan bún tươi đều rất bắt vị; dùng kèm rau sống hoặc cà muối càng thêm đưa cơm.', 'Canh hải sản ngon nhất khi ăn ngay trong bữa; không nên để qua đêm vì ngao dễ có mùi tanh và rau thì là bị úa màu.', 'vietnamese', 'mon_canh', 'bac', 'easy', 20, 20, 4, 'https://images.unsplash.com/photo-1534939561126-855b8675edd7?auto=format&fit=crop&w=800&q=80', '["Món canh","Miền Bắc","Hải sản","Thanh mát","Dễ nấu"]', '["lunch","dinner"]', '["boil","simmer"]', '["fish","molluscs"]', 180, 179.6, 752, 18.1, 4.7, 0.6, 16.7, 1.9, 8.8, 1382, 3.46, '["USDA FDC 169124","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 174212","VN/Asian Seasoning Powder Avg"]', '5c17f77b7c3bfd8f61d1d5e1eb434cae477589a6d1c8de3393660a2edc1e3fd9', '2d3bc431fb2ce9462ef188afe54d92bcaf740675305e6d7f1940f64c75368655', 4),
('vn-kho-01', 'thit-kho-trung', 6, 'Thịt kho tàu nước dừa trứng gà', 'Thịt ba chỉ cắt vuông kho nhừ cùng nước dừa xiêm và trứng gà luộc, lên màu cánh gián óng ả chuẩn vị Nam Bộ', 'Nồi thịt kho tàu Nam Bộ mềm rệu với phần mỡ trong veo không ngấy, thịt nạc thấm vị mặn ngọt hài hòa từ nước dừa tươi và nước mắm ngon, quyện cùng trứng gà bùi thơm.', 'Múc thịt và trứng ra tô sâu lòng, chan nước kho óng ả, dùng nóng với cơm trắng dẻo và dưa giá hoặc cải chua giải ngấy.', 'Để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 4 ngày trong hộp kín; khi ăn hâm lại trên lửa nhỏ cho thịt nóng đều, nước kho càng kho lại càng đậm đà.', 'vietnamese', 'mon_kho', 'nam', 'medium', 25, 65, 4, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món kho","Nam Bộ","Cơm nhà","Món Tết","Thịt heo"]', '["lunch","dinner"]', '["braise","boil"]', '["egg","fish","pork"]', 819, 818.6, 3424, 20.4, 74.9, 26.5, 14.9, 1.5, 11.5, 1256, 3.14, '["USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170174","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'de8d934322eee9a2246700b4161fc4288eb1199c02d632affe549f1db9357c3b', '5b0c2b906316a39470d9ac647dfa6324a3f842bac19c336ee3174711029d2ccc', 4),
('vn-kho-02', 'ca-loc-kho-to-tieu-den', 7, 'Cá lóc kho tộ tiêu đen', 'Cá lóc đồng cắt khứa kho săn trong tộ đất cùng tóp mỡ giòn béo, nước mắm đường sánh kẹo và tiêu đen cay nồng', 'Khứa cá lóc đồng chắc thịt thấm đẫm nước sốt kho sánh bóng màu cánh gián, béo thơm tóp mỡ rán giòn, cay ấm vị ớt hiểm và tiêu đen xay.', 'Dọn nguyên tộ cá nóng hổi lên bàn ăn cùng cơm trắng hoặc cơm cháy giòn, kèm dưa leo và đĩa rau luộc chấm nước kho.', 'Bảo quản tộ cá trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn thêm 1–2 muỗng nước ấm và đun lửa nhỏ cho nước sốt sánh bóng lại.', 'vietnamese', 'mon_kho', 'nam', 'medium', 20, 35, 3, 'https://images.unsplash.com/photo-1617093727343-374698b1b08d?auto=format&fit=crop&w=800&q=80', '["Món kho","Niêu đất","Nam Bộ","Cá lóc","Đậm đà"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["fish","pork"]', 417, 416.8, 1743, 30.6, 27.2, 9, 11.2, 0.8, 8.2, 1403, 3.51, '["USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '7dc7bc1032f3c2af9796fe30c400fc6071a2f3d8a90c954003680554c2566f83', '777da9d686e142d26bbbe889280f1deabca2292407b72cd10e43e7ea7d763dfd', 4),
('vn-kho-03', 'ga-ta-kho-gung-sa', 8, 'Gà ta kho gừng sả', 'Thịt đùi gà ta dai ngọt kho săn cùng gừng tươi thái sợi và sả băm thơm nồng, nước sốt sánh óng cực bắt cơm', 'Thịt đùi gà ta giữ nguyên da dai giòn, từng thớ thịt thấm đẫm vị mặn ngọt hài hòa quyện mùi thơm cay ấm của gừng thái sợi và sả băm vàng ruộm.', 'Múc gà kho ra đĩa sâu lòng, rưới nước sốt gừng sả óng vàng lên trên và ăn nóng cùng cơm trắng, canh rau cải xanh.', 'Bảo quản trong hộp đậy kín ở ngăn mát tối đa 3 ngày; khi dùng thêm 1 muỗng canh nước lọc và đun lửa nhỏ đến khi gà nóng đều.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 25, 4, 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=800&q=80', '["Món kho","Gà ta","Gừng sả","Ấm bụng","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["chicken","fish"]', 318, 317.6, 1329, 25.1, 18.3, 4.4, 12.7, 0.6, 6.2, 1312, 3.28, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'b9671283feb805c51afb893ec88f2a23b1850532f3ae99da86773afaf6e6fbe4', 'c7375faf000974751aa0584fd29a91768141fedfadbb800b65f64c72469f3a1f', 4),
('vn-kho-04', 'suon-heo-xao-chua-ngot', 9, 'Sườn heo xào chua ngọt', 'Sườn non chiên vàng giòn bên ngoài, mềm róc xương bên trong, áo đẫm nước sốt cà chua giấm đường sánh bóng đậm vị', 'Từng dẻ sườn non chiên xém vàng quyện lớp sốt đỏ cam sánh mịn có vị chua thanh từ giấm gạo, ngọt dịu từ đường và cà chua chín, thịt mềm ngọt dễ tách xương.', 'Bày sườn ra đĩa lớn, rưới đều sốt chua ngọt và rắc hành lá thái nhỏ cùng tiêu xay; ăn nóng với cơm trắng và canh rau ngót.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn cho thêm 1–2 muỗng canh nước lọc và đảo lại trên chảo lửa nhỏ cho sốt sánh nóng.', 'vietnamese', 'mon_kho', 'bac', 'medium', 20, 25, 4, 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Sườn non","Chua ngọt","Bắc Bộ","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","pan_fry","boil"]', '["fish","pork"]', 387, 387.4, 1621, 15.8, 28.3, 8.8, 17.6, 1.5, 13.3, 1283, 3.21, '["USDA FDC 167861","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '98d6bef98544fab9ed73df043e58483dde6947c373466e03cb335dec25902c81', 'c9f7886eed78dfa0d9f31cd5eb7c0de60c616a80cf29aee453bdba55b2e885e6', 4),
('vn-kho-05', 'tom-rim-man-ngot', 10, 'Tôm rim mặn ngọt tỏi ớt', 'Tôm tươi vỏ giòn thịt ngọt rim săn cùng nước mắm đường sánh keo và tỏi ớt thơm lừng, món mặn nhanh gọn cho bữa cơm gia đình', 'Tôm tươi giữ nguyên vỏ rang săn rồi rim kẹo với nước mắm ngon và đường thắng cánh gián, vị mặn ngọt hài hòa, thịt tôm săn chắc thơm mùi hành tỏi phi.', 'Trút tôm rim ra đĩa, rắc hành lá và tiêu xay; ăn nóng với cơm trắng cùng rau muống luộc hoặc canh chua thanh mát.', 'Ngon nhất khi ăn trong bữa; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa nhỏ với chút nước lọc.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 10, 15, 3, 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món rim","Hải sản","Nhanh gọn","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","shrimp"]', 195, 194.9, 816, 24.8, 6.2, 0.9, 10.9, 0.6, 8.7, 1241, 3.1, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179"]', '41b7213a4c5c8d49f45de7f3ea3f41a6b72a218b15314482cd37383a8c437dce', 'a033e72763755cd86724fe240f41ad8d88e9d9f4c04d2fd17452b7a648f4bc93', 4),
('vn-kho-06', 'thit-ba-chi-kho-cu-cai', 11, 'Thịt ba chỉ kho củ cải trắng', 'Thịt ba chỉ heo mềm béo kho hai lần lửa cùng củ cải trắng ngọt thanh, nước kho hổ phách sóng sánh chuẩn cơm nhà Bắc Bộ', 'Những miếng thịt ba chỉ đan xen nạc mỡ mềm tan hòa cùng từng khúc củ cải trắng thấm vị ngọt thanh và nước màu hổ phách đậm đà, cực kỳ hao cơm trong những ngày se lạnh.', 'Múc thịt và củ cải ra đĩa sâu lòng, chan nước kho óng ả và rắc hành lá, tiêu xay; ăn nóng cùng cơm trắng và đĩa rau cải luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi ăn đun nóng lại trên lửa nhỏ, thịt và củ cải thấm vị càng mềm ngon.', 'vietnamese', 'mon_kho', 'bac', 'easy', 20, 45, 4, 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món kho","Bắc Bộ","Mùa đông","Cơm nhà","Thịt heo"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["fish","pork"]', 739, 739.2, 3092, 13.4, 70.6, 24.8, 12.6, 2.2, 9, 1513, 3.78, '["USDA FDC 167820","USDA FDC 168452","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'b91e783ed6acd2a35a38516f81070643a25c53c38d90ec7fff228bfc45ec2ade', '0286660156bbe2f9cbba0690eb825eb6d29f1902beda66b678037e82f5e983a5', 4),
('vn-xao-01', 'rau-muong-xao-toi', 12, 'Rau muống xào tỏi xanh giòn', 'Rau muống ngọn non xanh mướt giòn sần sật, dậy mùi thơm nồng của tỏi ta phi vàng và chút tỏi tươi đảo cuối', 'Đĩa rau muống xào tỏi chuẩn vị cơm nhà với cọng rau xanh mướt không bị thâm đen, giòn ngọt tự nhiên quyện vị đậm đà của nước mắm ngon và hương tỏi phi vàng ruộm thơm lừng.', 'Gắp rau muống ra đĩa, rắc thêm vài lát ớt sừng đỏ lên trên; ăn nóng ngay cùng cơm trắng và chấm kèm nước tương tỏi ớt hoặc nước mắm chanh ớt.', 'Món rau xào ngon nhất khi ăn ngay lúc vừa bắc xuống để giữ độ giòn và màu xanh; hạn chế để qua đêm hoặc hâm lại nhiều lần vì rau dễ bị nhũn và sẫm màu.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 12, 8, 3, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món xào","Rau xanh","Thanh đạm","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["fish"]', 115, 115, 481, 3.3, 8.6, 1.3, 8.2, 2, 2, 945, 2.36, '["USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 170106","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'b8210bec08577514fd03576f30f5d7970c28c2710e8e7481154c5581133f0d0f', 'e4fa01e17a4e3a0c553743e572b0709d55fca5f2b45993bbec40afd2e8b9ac58', 4),
('vn-xao-02', 'bo-xao-can-toi-hanh-tay', 13, 'Bò xào cần tỏi hành tây mềm ngọt', 'Thịt thăn bò thái mỏng xào lửa lớn giữ trọn độ mềm mọng nước, quyện hương thơm nồng đặc trưng của cần tây, tỏi tây và hành tây giòn ngọt', 'Món bò xào cần tỏi hành tây kiểu Bắc đậm đà truyền thống với những lát thịt bò thăn mềm mọng, không hề bị dai, hòa quyện cùng sắc xanh giòn của cần tây, tỏi tây và vị ngọt thanh từ hành tây, cà chua.', 'Trút thịt bò xào ra đĩa rộng, rắc thêm tiêu đen xay lên trên; ăn nóng kèm cơm trắng dẻo và chén nước tương dầm ớt.', 'Ngon nhất khi ăn nóng ngay sau khi xào; nếu còn dư, cất hộp kín trong ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo lửa lớn trong 1 phút trước khi ăn để thịt bò không bị chín kỹ quá mức.', 'vietnamese', 'mon_xao', 'bac', 'easy', 18, 12, 3, 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Miền Bắc","Cơm nhà","Giàu đạm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","celery","molluscs","soybean","wheat"]', 345, 345.4, 1445, 23.4, 20.7, 5.6, 17.1, 3.1, 6.7, 1161, 2.9, '["USDA FDC 169230","USDA FDC 169246","USDA FDC 169655","USDA FDC 169988","USDA FDC 170000","USDA FDC 170187","USDA FDC 170457","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'fa07e902d49b5fd75329c964adb92f486caf1afd826a6d1fdb1809f0df746184', '673fac71b7b05d2ee74f2cf36fc698319e5d9776a53ac8843c9c9156944dcb6f', 4),
('vn-xao-03', 'muc-xao-can-toi-dua', 14, 'Mực ống xào cần tỏi dứa chua ngọt', 'Mực ống tươi dày mình giòn sần sật xào lửa lớn cùng dứa chín, cà chua, cần tây và tỏi tây đậm đà hương vị biển', 'Món mực ống xào cần tỏi dứa hài hòa sắc màu đỏ cam của cà chua, vàng tươi của dứa chín và xanh mướt của cần tỏi tây. Từng miếng mực giòn ngọt sần sật, thấm vị nước mắm thơm ngon mà không hề bị tanh hay ra nước.', 'Dọn mực xào ra đĩa bầu dục khi còn bốc khói, rắc tiêu xay và vài lát ớt sừng; ăn nóng với cơm trắng hoặc chấm thêm nước mắm ớt gừng.', 'Mực xào nên dùng hết trong bữa để giữ độ giòn đặc trưng; nếu bảo quản tủ mát trong ngày, hâm nóng lại rất nhanh trên chảo lửa lớn khoảng 1 phút để tránh mực bị dai.', 'vietnamese', 'mon_xao', 'toan_quoc', 'medium', 20, 12, 3, 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món xào","Hải sản","Chua ngọt","Đãi khách","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["celery","fish","molluscs","squid"]', 304, 303.5, 1270, 23.3, 10.6, 1.8, 30.1, 3.9, 12.6, 1017, 2.54, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169246","USDA FDC 169655","USDA FDC 169988","USDA FDC 170000","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '4d7b7c10adae4a05ff60fc48351103f50bf9e9328c7e4130939c5f3a570f1e29', 'd321d932925a72b1fdfb4bb61f94ab8c6723f2b6ee9774d5fe563ce3e9186305', 4),
('vn-xao-04', 'thit-bo-xao-bong-cai', 15, 'Thịt bò xào bông cải xanh cà rốt', 'Bông cải xanh giòn mát và cà rốt ngọt thanh xào lửa lớn cùng thịt thăn bò mềm thơm đậm vị dầu hào', 'Đĩa thịt bò xào bông cải xanh cà rốt bắt mắt với sắc xanh ngọc của súp lơ, cam tươi của cà rốt và lát thịt bò mềm mọng nước thấm sốt dầu hào, vừa thanh mát giàu chất xơ vừa đủ đạm cho bữa cơm gia đình.', 'Bày thịt bò xào bông cải ra đĩa lớn khi còn nóng, rắc hành lá và tiêu xay; ăn kèm cơm trắng và chén nước tương ớt lát.', 'Dùng ngon nhất ngay sau khi nấu; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy đảo nhanh lại trên chảo nóng trong 1 phút trước khi ăn.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 12, 3, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Rau xanh","Giàu chất xơ","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["beef","fish","molluscs","soybean","wheat"]', 325, 325.2, 1361, 24.5, 19.4, 5.4, 14.4, 3.6, 5, 1233, 3.08, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170187","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '15e87e3fef83f1df41088209d666edadc003ab6af5fd48648a20cf1ff92747a1', 'dbd512ab1e1f4c18119ba49ac42322bd375a93b50cedd3e36f4da06f8ee4fb01', 4),
('vn-xao-05', 'su-su-xao-trung-ga', 16, 'Su su xào trứng gà thanh ngọt', 'Su su non thái sợi giòn ngọt tự nhiên ôm lấy từng mảng trứng gà vàng ươm béo nhẹ, thơm mùi hành tím và ngò rí', 'Su su xào trứng gà là món xào mộc mạc quen thuộc của mâm cơm miền Bắc. Từng sợi su su giữ được độ giòn ngọt thanh mát quyện cùng lớp trứng gà tơi mềm vàng óng và hương thơm dịu của hành lá, ngò rí.', 'Múc su su xào trứng ra đĩa phẳng, rắc ngò rí thái nhỏ và chút tiêu đen xay lên trên; dùng nóng cùng cơm trắng và chén nước mắm ớt.', 'Món xào trứng nên ăn hết ngay trong bữa khi còn nóng để không bị tanh và su su giữ được độ giòn; tránh để qua đêm.', 'vietnamese', 'mon_xao', 'bac', 'easy', 15, 10, 3, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', '["Món xào","Rau củ","Tiết kiệm","Dưới 20 phút","Miền Bắc"]', '["lunch","dinner"]', '["stir_fry"]', '["egg","fish"]', 187, 186.9, 781, 7.9, 12.8, 2.7, 11.9, 3.9, 4.4, 1176, 2.94, '["USDA FDC 169990","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'a77d2b3e81d45150e5ca4600198ff4903f3f09f25163d1a7494bf0dbc55b76e6', 'e52004f1799a9f27034437332931523b62ea80aa3752b48f1fb2902943210803', 4),
('vn-xao-06', 'dau-cove-xao-thit-bo', 17, 'Đậu cô ve xào thịt bò giòn ngọt', 'Đậu cô ve tước xơ xào vừa chín tới giữ màu xanh non mướt, quyện thịt thăn bò mềm thơm đậm đà sốt dầu hào', 'Đậu cô ve xào thịt bò là món xào kinh điển của bữa cơm Việt với những khúc đậu giòn sần sật, xanh mướt không bị hăng kết hợp cùng lát thịt thăn bò mềm ngọt đậm vị tỏi phi và dầu hào.', 'Bày đậu cô ve xào thịt bò ra đĩa lớn, rắc hành lá và tiêu đen xay; ăn nóng với cơm trắng cùng chén nước tương dầm ớt.', 'Món ăn ngon nhất khi dùng nóng ngay; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo lửa lớn 1 phút khi ăn.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 12, 3, 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Rau xanh","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["beef","fish","molluscs","soybean","wheat"]', 353, 353.1, 1478, 26.7, 22.4, 6.3, 12, 2.9, 5, 1371, 3.43, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '9719d53b601c3db5f71b97d1b1104c84aafe595bec82415c7bd76294630b5509', '331a3279e32e6d2e69b3c3d0f31ee3ccd657272862d6acd01907540b36234aaa', 4),
('vn-chien-01', 'dau-phu-sot-ca-chua', 18, 'Đậu phụ lướt ván sốt cà chua', 'Đậu phụ chiên vàng vỏ ngoài mềm núng nính bên trong, quyện sốt cà chua đỏ sánh thơm hành lá', 'Đậu phụ lướt ván sốt cà chua là món cơm nhà dân dã quen thuộc khắp ba miền. Miếng đậu phụ trắng được thấm khô và chiên nhanh lửa vừa để lớp vỏ vàng mỏng giòn nhẹ, ruột vẫn mềm béo, sau đó om dịu trong sốt cà chua chín đỏ đậm vị nước mắm và hành lá.', 'Dọn nóng ra đĩa sâu lòng, rưới phần sốt cà chua sánh mịn lên mặt đậu, rắc tiêu xay và ăn kèm cơm trắng nóng cùng rau muống luộc.', 'Món ngon nhất khi dùng ngay trong bữa; nếu còn dư, cất hộp kín trong ngăn mát tủ lạnh tối đa 24 giờ và hâm lại trên chảo lửa nhỏ với chút nước lọc để sốt không khô cháy.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 10, 15, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chiên","Đậu phụ","Cơm nhà","Tiết kiệm","Dưới 30 phút"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["fish","molluscs","soybean","wheat"]', 262, 262.1, 1096, 18.3, 15.7, 2.3, 17.2, 3.6, 8, 1303, 3.26, '["USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '68e886d5f176160904065430a905bc5a59aef0804e273b6a1b3b4519afeec8d9', '0a896a530add4f15a1a418658443afe13f916473040e45928bb272f7aa391880', 4),
('vn-chien-02', 'trung-chien-thit-bam-nam-rom', 19, 'Trứng chiên thịt bằm nấm rơm', 'Trứng gà đánh sữa tươi chiên phồng mềm xốp, quyện nhân thịt heo xay đậm đà và nấm rơm giòn ngọt', 'Trứng chiên thịt bằm nấm rơm là món ăn nhanh giàu dinh dưỡng rất được yêu thích trong bữa cơm gia đình Việt. Nhân thịt bằm và nấm rơm được xào ráo nước trước khi hòa cùng hỗn hợp trứng gà đánh sữa tươi và chút dầu mè, giúp miếng trứng chiên phồng dày, thơm béo mà không bị chảy nước.', 'Cắt miếng trứng thành hình tam giác như miếng bánh, bày ra đĩa cùng vài lát dưa leo, dùng nóng với cơm trắng và nước tương ớt hoặc nước mắm tỏi ớt.', 'Ngon nhất ngay sau khi chiên khi mặt trứng còn phồng mềm. Có thể bảo quản hộp kín trong ngăn mát tủ lạnh 24 giờ và hâm áp chảo lửa nhỏ 2–3 phút mỗi mặt không cần thêm dầu.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 12, 3, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Món chiên","Trứng chiên","Nhanh gọn","Cơm nhà","Dưới 30 phút"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","fish","milk","pork","sesame"]', 395, 395.2, 1653, 22.5, 30.9, 9.1, 6.3, 1.1, 2.3, 1025, 2.56, '["USDA FDC 167902","USDA FDC 169230","USDA FDC 169251","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', '3f739d82232247a2cf22e750db1a35f587b990c125207b0455a9ae93bd269984', '0681f57394935147485f01dbb818a3cdcb2c453b2b3358a3e2a75bee12dff821', 4),
('vn-chien-03', 'canh-ga-chien-nuoc-mam', 20, 'Cánh gà chiên nước mắm tỏi ớt', 'Cánh gà chiên ngập dầu da giòn rụm thịt mọng nước, áo đều sốt nước mắm tỏi ớt chua ngọt óng ánh', 'Cánh gà chiên nước mắm tỏi ớt là món khoái khẩu của cả trẻ nhỏ lẫn người lớn nhờ lớp da vàng giòn rụm bên ngoài, thịt gà bên trong vẫn giữ độ mọng mềm không khô bã, quyện sốt nước mắm tỏi ớt cân bằng vị mặn, ngọt, cay nhẹ rất bắt cơm.', 'Xếp cánh gà ra đĩa lót xà lách và cà chua thái lát, rưới phần tỏi ớt phi thơm còn lại trong chảo lên trên, ăn nóng cùng cơm trắng hoặc bánh mì.', 'Nên ăn nóng ngay sau khi xóc sốt để giữ độ giòn của da gà. Nếu bảo quản tủ lạnh tối đa 2 ngày, làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'medium', 15, 25, 4, 'https://images.unsplash.com/photo-1527477396000-e27163b481c2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Cánh gà","Món nhậu","Trẻ em thích","Đậm đà"]', '["lunch","dinner"]', '["deep_fry","pan_fry"]', '["chicken","fish","wheat"]', 478, 478.3, 2001, 26.4, 32, 7.5, 20.2, 0.9, 7.1, 1215, 3.04, '["Panko / Batter Mix Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171080","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC Sriracha Ref"]', '9e56f9cba2cbfe234ef7c625290e674d086dbd8fa9857aaff882a4e39806aadf', 'dea084be57237c16209dea3708cc6402438f6f54a65438a19b8f5ad5565199c8', 4),
('vn-chien-04', 'cha-ca-hai-phong', 21, 'Chả cá chiên thì là hạt tiêu', 'Chả cá thác lác quết dai giòn cùng mỡ heo hạt lựu, thơm nức mùi thì là tươi và tiêu xay cay ấm', 'Chả cá chiên thì là hạt tiêu mang hương vị đặc trưng của ẩm thực vùng duyên hải Bắc Bộ. Thịt cá tươi được giữ lạnh rồi quết nhuyễn cùng thịt nạc vai và mỡ heo hạt lựu, hòa quyện hương thơm nồng nàn của rau thì là tươi và hạt tiêu xay, tạo nên từng miếng chả vàng phồng dai giòn hấp dẫn.', 'Dọn chả cá chiên nóng hổi ra đĩa, chấm cùng tương ớt hoặc nước mắm chanh tỏi ớt, ăn kèm cơm trắng nóng hoặc kẹp bánh mì, rau sống.', 'Chả cá chiên sơ có thể bọc kín bảo quản ngăn mát 2 ngày hoặc cấp đông 2 tuần; khi ăn chỉ cần chiên lại lửa vừa 4–5 phút hoặc quay nồi chiên không dầu ở 180°C trong 5 phút.', 'vietnamese', 'mon_chien', 'bac', 'medium', 25, 15, 4, 'https://images.unsplash.com/photo-1534766555764-ce878a5e3a2b?auto=format&fit=crop&w=800&q=80', '["Món chiên","Chả cá","Bắc Bộ","Hải sản","Đặc sản"]', '["lunch","dinner"]', '["deep_fry","boil"]', '["egg","fish","pork"]', 436, 435.6, 1823, 31.7, 29, 8, 11.2, 1.1, 3.6, 1399, 3.5, '["USDA FDC 167820","USDA FDC 167847","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 175148","USDA FDC Sriracha Ref","VN/Asian Seasoning Powder Avg"]', '6805b7bec90940e090ccc0a7c0b6362b28f76a8a308aca3df2b46f65617314a6', '7112704967a85a7cd37cfce73f27f39d92b60e4ac057400db1fbc2d9919e9742', 4),
('vn-chien-05', 'nem-ran-truyen-thong-ha-noi', 22, 'Nem rán truyền thống Hà Nội', 'Vỏ bánh đa nem giòn tan vàng ruộm nhờ chiên hai lần, ôm trọn nhân thịt tôm nấm củ ngọt thơm chấm mắm chua ngọt', 'Nem rán truyền thống Hà Nội là món ăn tinh hoa không thể thiếu trong mâm cỗ ngày Tết và bữa cơm sum họp. Nhân nem kết hợp hài hòa thịt nạc vai xay, tôm tươi, mộc nhĩ, nấm hương, miến dong cùng củ đậu, cà rốt, su hào và lòng đỏ trứng, gói bằng bánh đa nem phết nước giấm loãng rồi rán hai lửa để vỏ giòn lâu.', 'Cắt nem thành khúc vừa ăn, bày lên đĩa cùng rau sống, kinh giới, tía tô và chén nước mắm chua ngọt tỏi ớt nổi đẹp, ăn kèm cơm nóng hoặc bún rối.', 'Sau khi rán sơ lần một và để nguội hẳn, có thể xếp nem vào hộp có lót giấy nến cấp đông tới 1 tháng; khi ăn rã đông sơ rồi rán lần hai ở lửa vừa đến khi vàng giòn rụm.', 'vietnamese', 'mon_chien', 'bac', 'hard', 35, 25, 4, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món chiên","Nem rán","Hà Nội","Truyền thống","Tiệc tùng"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["crustaceans","egg","fish","pork","shrimp"]', 748, 748.1, 3130, 31.4, 40.3, 11.7, 64.8, 5.2, 9.1, 1636, 4.09, '["USDA FDC 167902","USDA FDC 168436","USDA FDC 168437","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170072","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref","VN/Asian Seasoning Powder Avg"]', 'c944a310cea20c00d5d3ff57e718205e8170a3c39fce8c99b5e1c5d285c71331', '45b82a5e1ec3659b620dc477a5d6185d5f36cae5f2294973967c827ff1135dbd', 4),
('vn-chien-06', 'ca-ro-phi-chien-gion-mam-gung', 23, 'Cá rô phi chiên giòn chấm mắm gừng', 'Cá rô phi khía vảy áo lớp bột mì mỏng chiên vàng giòn rụm, thịt trắng ngọt chấm nước mắm gừng tỏi ớt ấm nồng', 'Cá rô phi chiên giòn chấm mắm gừng là món ăn quen thuộc trong mâm cơm Việt nhờ nguyên liệu bình dân nhưng cực kỳ đưa cơm. Cá được làm sạch kỹ màng đen, khía sâu thân, áo lớp bột mì mỏng pha gia vị rồi chiên lửa vừa cho lớp da phồng giòn rụm, thịt cá bên trong vẫn mềm ngọt tự nhiên.', 'Bày cá nguyên con ra đĩa lớn, dùng nóng cùng cơm trắng, rau muống luộc hoặc cuốn bánh tráng rau sống, chấm đẫm chén nước mắm gừng chanh tỏi ớt.', 'Món ngon nhất khi ăn nóng ngay sau khi chiên để cảm nhận độ giòn tan của da cá; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và làm nóng bằng nồi chiên không dầu ở 180°C trong 6 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 20, 4, 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Cá tươi","Cơm nhà","Dễ làm","Đưa cơm"]', '["lunch","dinner"]', '["deep_fry"]', '["fish","wheat"]', 326, 325.9, 1363, 36.3, 12.7, 2.4, 15.3, 0.9, 5, 1400, 3.5, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169761","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '6830c3d9044ab33d82fd1aac59794a32ea5b34d18ce3320ac8d5bc54b71463ee', 'aa1e4e091a39b466f05d5027bd50ab239e3a53cd57e8cebacdb685a3b7456aec', 4),
('vn-hap-01', 'ga-ta-hap-la-chanh', 24, 'Gà ta hấp lá chanh da giòn thịt ngọt', 'Gà ta thả vườn hấp cách thủy cùng sả gừng thơm lừng, da vàng giòn mọng nước quyện hương lá chanh thái chỉ', 'Gà ta hấp cách thủy giữ trọn vị ngọt thanh tự nhiên của thịt săn chắc, lớp da vàng óng giòn sần sật, thấm đẫm hương thơm ấm nồng từ sả cây, gừng tươi và lá chanh bánh tẻ.', 'Chặt gà thành miếng vừa ăn xếp ra đĩa, rắc đều lá chanh thái chỉ và vài lát ớt sừng lên trên; dọn nóng kèm chén muối tiêu chanh ớt.', 'Gà hấp ngon nhất khi dùng ngay trong ngày. Nếu còn dư, bọc kín bảo quản ngăn mát tối đa 24 giờ rồi hấp lại 5–7 phút ở lửa vừa để thịt nóng mà không bị khô.', 'vietnamese', 'mon_hap_luoc', 'bac', 'medium', 20, 30, 4, 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món hấp","Gà ta","Thanh đạm","Đãi tiệc","Cơm nhà"]', '["lunch","dinner"]', '["steam"]', '["chicken"]', 312, 311.7, 1305, 25.8, 20.6, 5.9, 4.7, 0.6, 1.3, 1175, 2.94, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '80050a49f8622bf81450665feb58cac70447d431f8bed1143736f7958b6ac512', 'ffea52549a962b3529bdeabbbd4be000d974a3f79f1d13350f268e9ad4cee92b', 4),
('vn-hap-02', 'thit-ba-chi-luoc-mam-tom', 25, 'Thịt ba chỉ luộc chấm mắm tôm cà pháo', 'Thịt ba chỉ rút sườn luộc trắng giòn, thái lát mỏng đều chấm mắm tôm đánh sủi bọt bông cùng cà pháo muối chua giòn', 'Thịt ba chỉ rút sườn nạc mỡ đan xen luộc chín tới giữ được độ trắng ngần và giòn sần sật phần bì, ăn kèm cà pháo muối giòn tan, rau sống mát lành và bát mắm tôm chanh ớt đánh bông thơm lừng.', 'Xếp thịt ba chỉ thái mỏng ra đĩa hoặc mẹt lót lá chuối, dọn cạnh đĩa cà pháo muối, đĩa rau thơm dưa leo và bát mắm tôm sủi bọt ăn kèm cơm trắng nóng.', 'Thịt luộc bảo quản nguyên khối trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn chỉ thái lát vừa dùng hoặc trụng nhanh qua nước sôi nóng 1 phút cho mềm ẩm rồi thái.', 'vietnamese', 'mon_hap_luoc', 'bac', 'easy', 15, 25, 4, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món luộc","Cơm nhà","Món Bắc","Thanh đạm","Kinh điển"]', '["lunch","dinner"]', '["boil"]', '["crustaceans","pork","shrimp","sulphites"]', 635, 635.2, 2658, 12.9, 61, 21.7, 8.8, 2, 4.7, 784, 1.96, '["Asian Shrimp Paste Ref","USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169228","USDA FDC 169230","USDA FDC 169231","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 171413","USDA FDC 172238","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647"]', '23eecb1e63a74a9cfa9ca4beca1c68dc8fdf9bbf4946326c518500a07703fa12', '23fb1a29a07a3d1e2e7b859914536aeda85c98878f0e251bdd0c10fd06366431', 4),
('vn-hap-03', 'ca-dieu-hong-hap-hanh-gung', 26, 'Cá điêu hồng hấp hành gừng xì dầu', 'Cá điêu hồng tươi nguyên con hấp chín tới mềm ngọt, rưới sốt xì dầu dầu hào thơm nức hành gừng xối dầu nóng', 'Cá điêu hồng nguyên con làm sạch kỹ hấp cách thủy vừa chín tới cho thớ thịt trắng ngần ngọt dịu, hòa quyện sốt xì dầu dầu hào sánh nhẹ cùng hương thơm nồng nàn của gừng sợi, hành lá và nấm hương.', 'Đặt đĩa cá hấp nóng hổi lên bàn ăn, rưới đều dầu hành gừng thơm lừng; dùng nóng với cơm trắng hoặc cuốn bánh tráng cùng bún tươi và rau sống.', 'Món cá hấp ngon nhất khi ăn nóng ngay sau khi chế biến. Nếu còn thừa, tách bỏ xương rồi bảo quản ngăn mát tối đa 24 giờ, khi dùng hấp cách thủy lại 5 phút.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'medium', 20, 25, 4, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món hấp","Cá tươi","Đãi khách","Thanh đạm","Cơm nhà"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","sesame","soybean","wheat"]', 271, 270.6, 1132, 32.7, 10.7, 2, 10, 1.3, 3.3, 1155, 2.89, '["Shaoxing Wine Ref","USDA FDC 168436","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '57dc6dcaf2c49474819fa72da12630d11267d9c77683c309f2c3273e34926d8f', 'a893fcffbf82fe4a8277249c503cad9d70083fdaeaa40797e58da2c8003cba93', 4),
('vn-hap-04', 'rau-cu-luoc-kho-quet', 27, 'Rau củ luộc thập cẩm chấm kho quẹt tóp mỡ', 'Súp lơ xanh, cà rốt, su su luộc giòn xanh mướt chấm cùng niêu kho quẹt tóp mỡ tôm khô đậm đà chuẩn vị Nam Bộ', 'Đĩa rau củ luộc giòn ngọt giữ trọn sắc xanh cam tươi tắn chấm ngập trong niêu kho quẹt sánh kẹo mặn ngọt hài hòa, thơm lừng tóp mỡ giòn rụm, tôm khô dai ngọt và tiêu xanh cay nồng.', 'Bày súp lơ xanh, cà rốt và su su luộc ra đĩa lớn, đặt bên cạnh niêu kho quẹt nóng hổi còn sôi lăn tăn, ăn kèm cơm trắng hoặc cơm cháy giòn.', 'Rau củ luộc nên ăn hết trong bữa để giữ độ giòn và màu sắc tươi ngon. Phần kho quẹt có thể bảo quản hũ kín trong ngăn mát 3–4 ngày, hâm nóng trên lửa nhỏ cùng 1 muỗng nước trước khi dùng.', 'vietnamese', 'mon_hap_luoc', 'nam', 'easy', 20, 25, 4, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món luộc","Rau củ","Kho quẹt","Món Nam","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["crustaceans","fish","pork","shrimp"]', 336, 336.4, 1407, 11.8, 23.2, 8.3, 22.1, 4.5, 12.5, 1525, 3.81, '["Green Peppercorn Ref","USDA / Asian Dried Shrimp Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 169990","USDA FDC 170005","USDA FDC 170106","USDA FDC 170379","USDA FDC 170393","USDA FDC 170499","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'a83ef6f2d387fe9c8ea90a15835d5c6bc473a73cf56cec54a728e390a5f23ab8', '03ccdf1e6fa7cc16b3f8f4d44f1b665c586f04397b5e04e0891b4dae03ead8ac', 4),
('vn-hap-05', 'muc-hap-gung-sa', 28, 'Mực ống hấp gừng sả giòn ngọt', 'Mực ống tươi dày mình hấp nhanh cùng sả đập dập và gừng non thái chỉ giữ trọn độ giòn sần sật, chấm muối tiêu chanh', 'Mực ống tươi làm sạch khéo léo hấp cách thủy lửa lớn cùng sả cây, gừng non và lá chanh, từng miếng mực trắng ngần giòn sần sật, mọng nước tự nhiên, thơm dịu không hề tanh.', 'Gắp mực hấp ra đĩa lớn, rắc thêm vài sợi gừng và ớt sừng trang trí; dọn ăn ngay khi còn nóng chấm cùng chén muối tiêu chanh hoặc nước mắm gừng.', 'Mực hấp ngon nhất khi thưởng thức nóng ngay để giữ độ giòn sần sật. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hấp lại nhanh 2–3 phút, tránh hấp lâu làm mực dai.', 'vietnamese', 'mon_hap_luoc', 'trung', 'easy', 15, 12, 3, 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Miền Trung","Tươi ngọt"]', '["lunch","dinner"]', '["steam"]', '["molluscs","squid","sulphites"]', 179, 179.3, 750, 27.1, 2.5, 0.7, 10.7, 0.8, 0.8, 1124, 2.81, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223"]', '4d5f1acbbd3cfe923434eaf42ee64cf738406e850db6bef0650a9b7ff9291de4', '941a101cc187b292e7c505f554296096dee4f5fe83505b0fffae4966e2a6c426', 4),
('vn-hap-06', 'tom-hap-nuoc-dua-tuoi', 29, 'Tôm sú hấp nước dừa tươi ngọt lịm', 'Tôm sú tươi roi rói hấp cùng nước dừa xiêm thanh ngọt và sả đập dập, thịt tôm săn chắc đỏ au dậy hương dừa dịu nhẹ', 'Tôm sú tươi sống hấp trực tiếp trong nước dừa xiêm ngọt thanh cùng sả cây và gừng lát giúp vỏ tôm lên màu đỏ cam bắt mắt, thịt tôm săn chắc giòn ngọt và thấm vị dừa dịu mát đặc trưng miền Tây.', 'Xếp tôm đỏ au ra đĩa hoặc quanh vành trái dừa xiêm, trang trí ớt sừng thái chỉ và vài cọng rau thơm, ăn nóng chấm muối tiêu chanh ớt.', 'Tôm hấp ngon nhất khi dùng nóng ngay sau khi chín. Nếu còn dư, bóc vỏ rồi bảo quản ngăn mát tối đa 24 giờ và hấp lại nhanh 2–3 phút hoặc dùng chế biến món xào, salad.', 'vietnamese', 'mon_hap_luoc', 'nam', 'easy', 15, 10, 3, 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Đặc sản Nam Bộ","Đãi tiệc"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","shrimp"]', 152, 151.5, 634, 29.6, 1, 0.3, 6.9, 1.4, 3.4, 962, 2.41, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170174","USDA FDC 170499","USDA FDC 170931","USDA FDC 173468","USDA FDC 175179"]', '4666e450ee9b1e7bb2b4754ed22ef632da1f053e6fb7ff627290deb5f4dc8bde', '24ff694cfd9c5834568e14ef1fdc7698dcccf4a7f64ae02e6f97141345ca95b9', 4),
('vn-cuon-01', 'goi-cuon-tom-thit-nam-bo', 30, 'Gỏi cuốn tôm thịt chấm tương phộng Nam Bộ', 'Bánh tráng dẻo trong veo cuốn tôm sú đỏ au, thịt ba chỉ béo mềm, bún tươi và rau thơm mát lành cùng tương đen bơ đậu phộng bùi béo', 'Gỏi cuốn tôm thịt Nam Bộ hấp dẫn với lớp bánh tráng mỏng dai bọc trọn tôm sú đỏ au, thịt ba chỉ luộc thái mỏng, bún tươi, dưa leo giòn mát và hẹ lá xanh, chấm cùng chén tương đen bơ đậu phộng thơm bùi sánh mịn.', 'Xếp gỏi cuốn ra đĩa, dọn kèm chén tương đen bơ đậu phộng rắc lạc rang giã dập, ớt băm và đĩa đồ chua cà rốt củ cải giòn ngọt.', 'Gỏi cuốn ngon nhất khi ăn ngay sau khi cuốn; nếu cần giữ trong vài giờ, bọc từng cuốn bằng màng bọc thực phẩm hoặc khăn ẩm sạch trong ngăn mát tủ lạnh và hâm ấm nhẹ nước chấm trước khi dùng.', 'vietnamese', 'mon_cuon_nom', 'nam', 'medium', 25, 20, 4, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món cuốn","Nam Bộ","Thanh mát","Khai vị","Tương đậu phộng"]', '["lunch","dinner"]', '["boil","assemble"]', '["crustaceans","peanut","pork","sesame","shrimp","soybean","wheat"]', 777, 777.4, 3253, 26.4, 46, 14.6, 66.5, 4.3, 16.4, 899, 2.25, '["NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 168409","USDA FDC 168452","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169994","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171370","USDA FDC 171413","USDA FDC 172232","USDA FDC 172238","USDA FDC 172430","USDA FDC 172470","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref"]', '44b2991bde1bbe1234f5537c66e3900b9caaa5c36f75d889d87f29e79e2f3b7e', 'f8e2f68c90a7a9807b9ed2f8f55fb2d7137593f87fa1858baf14b9d2bbdaa4a5', 4),
('vn-cuon-02', 'pho-cuon-bo-ha-noi', 31, 'Phở cuốn bò xào rau thơm Hà Nội', 'Bánh phở tươi vuông mềm mượt cuốn gọn thịt bò thăn xào tỏi thơm lừng cùng xà lách, húng Láng và ngò rí, chấm nước mắm dưa góp chua ngọt', 'Phở cuốn bò xào rau thơm mang đậm phong vị phố Trúc Bạch Hà Nội với lá bánh phở tươi trắng mượt ôm lấy thịt bò thăn xào tỏi mềm ngọt, quyện cùng xà lách giòn tươi, húng Láng thơm nồng và bát nước mắm dưa góp đu đủ cà rốt chua ngọt thanh tao.', 'Xếp phở cuốn nguyên cuốn hoặc cắt đôi vát chéo ra đĩa, dọn ăn ngay khi thịt bò còn ấm cùng chén nước mắm chua ngọt thả dưa góp đu đủ cà rốt giòn sần sật.', 'Nên thưởng thức ngay sau khi cuốn để bánh phở giữ độ mềm mượt và thịt bò không bị nguội; nếu chưa dùng ngay, bọc kín đĩa phở cuốn bằng màng bọc thực phẩm để ngăn mát tối đa 4 giờ.', 'vietnamese', 'mon_cuon_nom', 'bac', 'easy', 20, 10, 3, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Phở cuốn","Hà Nội","Thịt bò","Khai vị","Món cuốn"]', '["lunch","dinner"]', '["stir_fry","assemble"]', '["beef","fish"]', 501, 501.2, 2098, 27, 23.1, 6.1, 46.4, 3.9, 10.3, 1627, 4.07, '["NIN VN Fresh Pho Noodle Ref","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169997","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref","USDA FDC Sriracha Ref","VN/Asian Seasoning Powder Avg"]', 'c2db10ef69ce7ead3cb13bb81fd5bd98fabca80a5627409c2a47bf0ae329813a', 'b5cec0d6ff4dc86da8364e14005a9f1e1d6a3adb99229c0abcd8b39a40f3f237', 4),
('vn-cuon-03', 'nom-hoa-chuoi-tai-heo', 32, 'Nộm hoa chuối tai heo giòn sần sật', 'Hoa chuối tây bào mỏng trắng giòn quyện tai heo luộc sần sật, cà rốt, giá đỗ cùng nước trộn chua ngọt tỏi ớt và lạc rang bùi thơm', 'Nộm hoa chuối tai heo là món khai vị truyền thống miền Bắc với từng sợi hoa chuối trắng muốt không chát thâm, kết hợp tai heo luộc giòn sần sật, rau củ thanh mát, nước mắm chanh tỏi ớt đậm đà cùng lạc rang và hành phi thơm nức.', 'Gắp nộm ra đĩa sâu lòng, rắc lạc rang giã dập, hành phi vàng giòn và vài lát ớt sừng lên mặt; dùng ngay làm món khai vị hoặc ăn kèm bánh phồng tôm.', 'Nên trộn nộm ngay trước bữa ăn để hoa chuối và rau giữ độ giòn; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 12 giờ nhưng lưu ý nộm sẽ dịu mềm và tiết thêm nước.', 'vietnamese', 'mon_cuon_nom', 'bac', 'medium', 30, 20, 4, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món nộm","Khai vị","Giòn sần sật","Miền Bắc","Chống ngán"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["fish","peanut","pork"]', 479, 478.7, 2003, 30.7, 26.7, 7, 30.6, 9.3, 14.1, 1391, 3.48, '["SE Asian Banana Blossom Ref","USDA FDC 167879","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169963","USDA FDC 170000","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","VN Rau Ram Ref"]', '08c2c2598afb14bc323632fbca15b0ac00877dcc928e044eb364d9621a6e35d0', 'b118cf65452b8828eeb37675d7f78d7cb4aab80ce969fd5caf336d9757a6bead', 4),
('vn-cuon-04', 'goi-ga-xe-phay-bap-cai', 33, 'Gỏi gà xé phay bắp cải hành tây', 'Thịt gà ta luộc mềm ngọt xé sợi trộn cùng bắp cải bào giòn, hành tây ngâm giấm đá thanh dịu, rau răm và lá chanh thơm lừng', 'Gỏi gà xé phay bắp cải hành tây hài hòa giữa thịt gà ta luộc dai ngọt xé sợi, bắp cải trắng bào mỏng giòn rụm, hành tây ngâm giấm đá dịu hăng và hương thơm đặc trưng của rau răm, lá chanh thái chỉ cùng nước trộn chua ngọt vừa vặn.', 'Bày gỏi ra đĩa lớn, rắc hành phi, đậu phộng rang giã dập và ớt sừng thái sợi lên mặt; có thể ăn kèm bánh phồng tôm hoặc cháo gà nóng.', 'Gỏi ngon nhất ngay sau khi trộn; nếu làm trước cho bữa tiệc, bảo quản riêng gà xé, rau củ ráo nước và nước trộn trong ngăn mát tủ lạnh rồi trộn trước khi dọn 10 phút.', 'vietnamese', 'mon_cuon_nom', 'trung', 'easy', 20, 25, 4, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', '["Gỏi gà","Miền Trung","Thanh mát","Khai vị","Đãi tiệc"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["chicken","fish","peanut"]', 395, 394.7, 1652, 29.3, 20.5, 4.6, 25, 5, 15.9, 1471, 3.68, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170000","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172385","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","VN Rau Ram Ref"]', '80290697fd37f7de83e491f4fe20dc55495d4b0bc00f6370b142e3b5e56f292c', '1c6a40ca10a060d76792ba3e2fd43a2ccb2aafb44ee423817c11e3d971747f5f', 4),
('vn-cuon-05', 'nom-du-du-bo-kho', 34, 'Nộm đu đủ bò khô phố cổ Hà Nội', 'Sợi đu đủ xanh và cà rốt nạo giòn sần sật quyện nước mắm giấm đường chua ngọt cay nhẹ, điểm thịt bò khô xé sợi, rau thơm và lạc rang', 'Nộm đu đủ bò khô mang nét đặc trưng ẩm thực phố cổ Hà Nội với sợi đu đủ xanh và cà rốt giòn tan không chát, thấm đẫm nước trộn mắm chanh chua ngọt dịu cay, kết hợp thịt bò khô xé sợi thơm lừng, rau kinh giới và lạc rang bùi ngậy.', 'Gắp nộm đu đủ ra đĩa sâu lòng, xếp thêm thịt bò khô xé sợi, rắc lạc rang giã dập và hành phi giòn lên trên; trộn đều ngay trước khi thưởng thức.', 'Không nên rưới nước trộn quá lâu trước khi ăn vì đu đủ sẽ tiết nước và làm ỉu lạc rang; bảo quản phần nguyên liệu khô và nước trộn riêng trong ngăn mát tủ lạnh tối đa 24 giờ.', 'vietnamese', 'mon_cuon_nom', 'bac', 'easy', 20, 10, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món nộm","Phố cổ Hà Nội","Đu đủ xanh","Ăn vặt","Khai vị"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["beef","fish","peanut"]', 315, 314.6, 1317, 16.2, 15.7, 3.4, 30.8, 5.2, 20.9, 1517, 3.79, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref"]', '5007af4b39dd747b39696ef4d069bc54ee0a58c15f862a6a35da972abc1eaeb6', 'dc0a447c57936908896a5f40196a75c35dc392ca5380bcb6216faf85ae27fd7a', 4),
('vn-cuon-06', 'nem-lui-hue-nuong-sa', 35, 'Nem lụi Huế nướng sả cuốn bánh tráng', 'Nem thịt heo giò sống quết dẻo bọc thân cây sả nướng vàng xém cạnh thơm lừng, cuốn bánh tráng bún tươi, rau sống, chuối chát chấm nước mắm tỏi ớt', 'Nem lụi Huế nướng sả thơm nức với lớp nhân thịt nạc vai xay, giò sống và tôm tươi quết dẻo bọc quanh thân sả nướng xém cạnh, quét mật ong dầu điều bóng đẹp, cuốn bánh tráng cùng bún tươi, chuối chát, dứa thơm và rau sống.', 'Dọn nem lụi nóng hổi ra đĩa cùng bánh tráng, bún tươi, đĩa rau sống thái lát chuối chát, dưa leo, dứa thơm và chén nước mắm tỏi ớt chua ngọt.', 'Nem lụi đã nướng có thể bảo quản ngăn mát tối đa 2 ngày trong hộp kín; khi ăn làm nóng lại bằng nồi chiên không dầu ở 160°C khoảng 4–5 phút cho nóng thơm.', 'vietnamese', 'mon_cuon_nom', 'trung', 'medium', 40, 30, 4, 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Nem lụi Huế","Món nướng","Món cuốn","Miền Trung","Đặc sản"]', '["lunch","dinner"]', '["grill_roast","assemble"]', '["crustaceans","fish","molluscs","pork","shrimp","soybean","wheat"]', 604, 603.8, 2526, 29, 23.3, 6.9, 71.6, 3.7, 17.3, 1698, 4.25, '["Annatto Infused Oil Ref","NIN VN Fresh Bun Ref","NIN VN Gio Lua Ref","SE Asian Banana Blossom Ref","USDA FDC 167902","USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169124","USDA FDC 169230","USDA FDC 169247","USDA FDC 169640","USDA FDC 169655","USDA FDC 169717","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref","VN/Asian Seasoning Powder Avg"]', '0259185d3e4bc592624bcf846a5504313df7aa795e09149229cdee4c8605053c', '5ac38bfbc1b0f4bde396e88afefd7a9501c996a1ddd34044c042ddff382e668f', 4),
('vn-bun-01', 'pho-bo-tai-lan-ha-noi', 36, 'Phở bò tái lăn Hà Nội', 'Thịt thăn bò đảo nhanh tay trên chảo lửa lớn dậy mùi tỏi gừng, chan nước dùng ninh xương ống bò thơm hoa hồi, quế thanh và thảo quả', 'Phở bò tái lăn chuẩn vị Hà Nội nổi bật với thịt thăn bò ướp tỏi gừng xào nhanh trên lửa lớn cho mặt thịt săn thơm xém cạnh, hòa cùng nước dùng ninh xương ống bò quyện hương thảo mộc nướng.', 'Dọn tô phở nóng hổi kèm chanh tươi, ớt tươi thái lát, hành tây ngâm đá, giá đỗ và rau thơm để thưởng thức ngay khi nước dùng còn nghi ngút khói.', 'Nước dùng hầm xong có thể bảo quản ngăn mát 2 ngày hoặc cấp đông 1 tháng; khi ăn đun sôi sùng sục nước dùng, xào tái lăn thịt bò tươi và trụng bánh phở mới.', 'vietnamese', 'mon_bun_pho', 'bac', 'hard', 35, 180, 4, 'https://images.unsplash.com/photo-1582878826629-29b7ad1cdc43?auto=format&fit=crop&w=800&q=80', '["Phở bò","Hà Nội","Nước dùng ninh xương","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["simmer","stir_fry","boil","assemble"]', '["beef","fish"]', 634, 633.9, 2653, 35.7, 26.9, 9.1, 62.4, 4.2, 10.7, 1983, 4.96, '["NIN VN Fresh Pho Noodle Ref","USDA Beef Rib / Bone Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169963","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170499","USDA FDC 170919","USDA FDC 170922","USDA FDC 170931","USDA FDC 171316","USDA FDC 171320","USDA FDC 171321","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC Sucrose Ref","VN Culinary Herb Ref"]', '914ec5170cac36d8d75e8f4a89e9f1746d6685fd665b4f4a0fd7bf422db0fcbc', 'aae7c45468b9619c4a6101573f7dbe14029ab2ecedeb9d1e09818e421525901b', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('vn-bun-02', 'bun-cha-ha-noi-than-hoa', 37, 'Bún chả nướng than hoa Hà Nội', 'Chả miếng ba chỉ và chả viên nạc vai nướng xém vàng ươm thơm mùi sả hành, thả trong bát nước mắm ấm chua ngọt cùng dưa góp đu đủ cà rốt', 'Bún chả Hà Nội chuẩn vị với thịt ba chỉ thái miếng và thịt nạc vai xay nặn viên ướp đậm nước cốt sả hành, mắm tôm và nước hàng, nướng than hoa xém cạnh thơm lừng, ăn cùng nước mắm pha ấm, dưa góp giòn và rau sống.', 'Xếp chả miếng và chả viên nóng hổi vào bát nước mắm ấm cùng dưa góp đu đủ cà rốt, rắc thêm chút tiêu xay nếu thích rồi ăn kèm bún tươi và đĩa rau sống tía tô, kinh giới.', 'Thịt đã ướp có thể bảo quản ngăn mát qua đêm; chả đã nướng bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút trước khi thả vào nước mắm ấm.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 35, 35, 4, 'https://images.unsplash.com/photo-1569058242253-92a9c755a0ec?auto=format&fit=crop&w=800&q=80', '["Bún chả","Hà Nội","Món nướng","Đặc sản miền Bắc"]', '["lunch","dinner"]', '["grill_roast","toss_mix","assemble"]', '["crustaceans","fish","pork","shrimp"]', 856, 855.9, 3581, 23.7, 53.3, 18.8, 71.4, 5.3, 19, 2168, 5.42, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 167902","USDA FDC 168155","USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref","VN/Asian Seasoning Powder Avg"]', 'f2b4c33d2e5794ff019853d26640f0db6cdd7664c70bdf601bcb23b5f01ec235', 'c173276e266cb419e5c6a9f9bb334bb458997f18117f8fdc59119dc9bb319c5b', 4),
('vn-bun-03', 'bun-bo-hue-chuan-vi', 38, 'Bún bò Huế giò heo chả cua', 'Nước dùng ninh xương bò giò heo đậm đà hương sả và mắm ruốc Huế, nổi bật cùng bắp bò thái lát, chả cua dai ngọt và sa tế ớt đỏ au', 'Tô bún bò Huế trứ danh có nước dùng trong veo ánh sắc cam đẹp mắt từ dầu màu điều và sa tế sả ớt, hòa quyện vị thanh ngọt của xương bò giò heo cùng mùi thơm nồng đặc trưng của mắm ruốc Huế.', 'Chan nước dùng thật nóng lên tô bún, rắc hành tây thái mỏng, hành lá và ngò rí; dọn kèm hoa chuối bào, giá đỗ, chanh tươi và chén sa tế ớt để điều chỉnh độ cay theo khẩu vị.', 'Nước dùng, giò heo và bắp bò luộc bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nước dùng, thả giò heo vào làm nóng rồi chan lên tô bún vừa trụng.', 'vietnamese', 'mon_bun_pho', 'trung', 'hard', 35, 120, 4, 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Bún bò Huế","Ẩm thực miền Trung","Cay nồng","Món nước"]', '["breakfast","lunch","dinner"]', '["simmer","boil","stir_fry","assemble"]', '["beef","crustaceans","fish","pork","shrimp"]', 871, 871.1, 3645, 46.6, 42.6, 14.3, 76.3, 6.3, 9.4, 2292, 5.73, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","SE Asian Banana Blossom Ref","USDA / MEXT Fish Cake Ref","USDA Beef Rib / Bone Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169963","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170198","USDA FDC 170499","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC Pork Leg Ref","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', '16caf93c618eaeba3bf83331dc14c3ff561962f5971582dce46984523ed2e8e1', 'ddfd5b316feb5fac3a188ff9da6838f6806419a59fce78034dae520b3c52c925', 4),
('vn-bun-04', 'bun-rieu-cua-dong', 39, 'Bún riêu cua đồng bắp bò giấm bỗng', 'Nước dùng riêu cua đồng béo ngậy đóng tảng vàng ruộm hòa vị chua dịu từ giấm bỗng và cơm mẻ, ăn kèm đậu phụ rán giòn và bắp bò chần tái', 'Bún riêu cua đồng truyền thống miền Bắc có phần riêu cua đóng tảng xốp mềm, nước dùng đỏ cam tự nhiên từ gạch cua xào cà chua, dậy vị chua thanh từ giấm bỗng và cơm mẻ ăn cùng thịt bò chần mềm và đậu phụ rán vàng.', 'Múc bún vào tô, xếp tảng riêu cua, đậu phụ rán, cà chua và thịt bò chần nóng, chan nước riêu ngập mặt bún rồi rắc hành lá; ăn kèm rau xà lách, kinh giới, tía tô, ớt tươi và chút mắm tôm.', 'Nước riêu cua và đậu rán bảo quản ngăn mát tối đa 24 giờ; khi dùng hâm nóng nhẹ lửa vừa tránh khuấy mạnh làm vỡ mảng riêu, sau đó mới chần thịt bò và trụng bún.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 30, 35, 4, 'https://images.unsplash.com/photo-1552611052-33e04de081de?auto=format&fit=crop&w=800&q=80', '["Bún riêu","Cua đồng","Miền Bắc","Món nước"]', '["breakfast","lunch","dinner"]', '["simmer","pan_fry","boil","assemble"]', '["beef","crab","crustaceans","fish","shrimp","soybean"]', 636, 636.3, 2662, 47.4, 21.5, 5.2, 64.8, 6.3, 7.1, 2324, 5.81, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","USDA FDC 169247","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 174208","VN Com Me Ref","VN/Asian Seasoning Powder Avg"]', 'acb7379335f1a5e71423cf91c0fb87b5aaf9116746968e1a7fb5c3fe771a0b2e', 'a8ae362535e6540628d6230396ec4e4d808154bfd2e0796706250940c826ef78', 4),
('vn-bun-05', 'bun-thit-nuong-nam-bo', 40, 'Bún thịt nướng Nam Bộ chả giò mỡ hành', 'Thịt nạc dăm ướp sả mật ong nướng vàng xém thơm lừng, ăn kèm chả giò chiên giòn rụm, mỡ hành béo thơm, đậu phộng rang và nước mắm chua ngọt', 'Tô bún thịt nướng Nam Bộ đầy đặn sắc màu với thịt nạc dăm nướng sả mật ong mềm thơm, chả giò cuốn thịt heo giòn tan, đồ chua củ cải cà rốt, mỡ hành xanh mướt và chén nước mắm tỏi ớt chua ngọt sánh vị.', 'Lót rau xà lách và rau thơm thái nhỏ dưới đáy tô, xếp bún tươi, thịt nướng, chả giò cắt khúc, dưa leo, giá đỗ, đồ chua, rưới mỡ hành và đậu phộng rang giã dập rồi chan nước mắm chua ngọt trộn đều.', 'Thịt đã ướp và chả giò cuốn sẵn có thể bảo quản ngăn mát 1 ngày; thịt nướng xong hoặc chả giò dư khi ăn lại làm nóng bằng nồi chiên không dầu ở 180°C trong 4 phút để giữ độ giòn thơm.', 'vietnamese', 'mon_bun_pho', 'nam', 'medium', 40, 30, 4, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Bún thịt nướng","Nam Bộ","Chả giò","Món trộn"]', '["lunch","dinner"]', '["grill_roast","deep_fry","toss_mix","assemble"]', '["fish","molluscs","peanut","pork","soybean","wheat"]', 874, 874.3, 3658, 35.3, 39.8, 11.6, 95.9, 6.4, 22.3, 1911, 4.78, '["NIN VN Fresh Bun Ref","USDA FDC 167847","USDA FDC 167902","USDA FDC 168409","USDA FDC 168452","USDA FDC 168573","USDA FDC 169230","USDA FDC 169247","USDA FDC 169640","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Rice Paper Ref"]', 'cf825f7eca83ca34b52302ef8e34ec14289b7f73309942a8266533c86860b598', '998ca95a1b5eb4f4a5d226b1d39f7b07d8e771423e0373fa3cb2001384e8e602', 4),
('vn-bun-06', 'mien-ga-nam-huong', 41, 'Miến gà nấm hương mộc nhĩ', 'Sợi miến dong dai trong chan nước luộc gà ta ngọt thanh, thơm lừng nấm hương khô, mộc nhĩ giòn sần sật và thịt gà xé phay mềm ngọt', 'Tô miến gà nấm hương mộc nhĩ thanh tao chuẩn vị Bắc có nước dùng trong veo ngọt tự nhiên từ gà ta luộc cùng gừng hành nướng, kết hợp sợi miến dong dai mịn và thịt gà xé xào nấm thơm nức.', 'Chia miến đã chần ra tô, xếp thịt gà xào nấm hương mộc nhĩ lên trên, chan nước dùng gà đang sôi nóng, rắc hành lá, rau răm và tiêu đen xay.', 'Nên bảo quản riêng phần nước dùng, thịt gà xào nấm và miến chưa chần trong ngăn mát tối đa 2 ngày; khi ăn đun sôi nước dùng, trụng miến mới và làm nóng thịt gà.', 'vietnamese', 'mon_bun_pho', 'bac', 'easy', 25, 45, 4, 'https://images.unsplash.com/photo-1612927601601-6638404737ce?auto=format&fit=crop&w=800&q=80', '["Miến gà","Nấm hương","Món nước thanh nhẹ","Ẩm thực miền Bắc"]', '["breakfast","lunch","dinner"]', '["boil","simmer","stir_fry","assemble"]', '["chicken","fish"]', 749, 748.6, 3133, 41.1, 36.8, 9.7, 63.2, 7.8, 2.8, 2132, 5.33, '["USDA FDC 168436","USDA FDC 168437","USDA FDC 168952","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', '118dde6310dd3b831e37bf148ab4ce7a6569f85ba1a48567dc7ad5ab1c0e99ff', '7441852c5ae8f7e65ef0ed41ac701d228a9137c3f8e2bf4b7261f6d350aec14a', 4),
('vn-chay-01', 'dau-phu-kho-nam-dong-co', 42, 'Đậu phụ kho nấm đông cô tiêu đen', 'Đậu phụ rán vàng ươm kho sánh cùng nấm đông cô ngọt bùi, dậy hương nước tương, dầu mè và tiêu đen cay ấm', 'Đậu phụ chiên vàng giòn bên ngoài nhưng giữ trọn độ mềm béo bên trong, kho liu riu cùng nấm đông cô tươi giòn ngọt trong phần nước sốt tương sánh bóng, thơm lừng hành boa-rô, dầu mè và tiêu đen cay nồng.', 'Dọn nóng ngay trong nồi đất hoặc đĩa sâu lòng, rắc thêm tiêu đen xay và ớt sừng thái lát; dùng kèm cơm trắng dẻo nóng và rau luộc.', 'Để nguội hoàn toàn rồi bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ và thêm 1–2 muỗng canh nước lọc nếu sốt đặc.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 20, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Món kho","Đậu phụ","Nấm đông cô","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 227, 226.9, 949, 14.9, 14.7, 2.1, 13.1, 2.8, 7, 1271, 3.18, '["USDA FDC 169246","USDA FDC 169251","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', '9490a52629f558e5207701d43c8ad51861441a5cbe221fec7c023afeea7ae356', '7e757d0e68c91ef5fb1d227c8ea807a463d79ac06431bde95530884ab5c43bba', 4),
('vn-chay-02', 'canh-nam-hat-sen-tao-do', 43, 'Canh nấm hạt sen táo đỏ thanh lọc', 'Nước canh trong ngọt thanh từ củ sen, bắp ngọt, hạt sen bở bùi, táo đỏ, kỷ tử và hai loại nấm tươi giòn ngọt', 'Bát canh chay thanh mát giàu dưỡng chất với nước dùng trong veo ngọt dịu tự nhiên từ củ sen giòn bùi, bắp ngọt, cà rốt và táo đỏ, kết hợp hạt sen ninh mềm tơi cùng nấm đùi gà và nấm kim châm giòn sần sật.', 'Múc canh ra tô lớn khi còn nóng hổi, rắc mùi tàu thái nhỏ và lá boa-rô xanh; thưởng thức cùng cơm trắng hoặc ăn riêng như món canh bồi bổ.', 'Dùng hết trong ngày để nấm kim châm giữ độ giòn ngọt; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại trên lửa vừa 3–5 phút trước khi dùng.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 20, 30, 4, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món chay","Món canh","Thanh lọc","Hạt sen","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer"]', '[]', 201, 200.7, 840, 6.2, 4.3, 0.6, 38.6, 6.8, 11.3, 1110, 2.78, '["USDA FDC 168580","USDA FDC 169246","USDA FDC 169248","USDA FDC 169253","USDA FDC 169998","USDA FDC 170148 Fresh","USDA FDC 170393","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC Jujube Ref","VN Culinary Herb Ref","Vegetarian Seasoning Powder Ref"]', '3df5b97c8d14f1651b80f2c55ab5ae11932558eb3defedb367cc5c36de2e38c2', '5b7aeb5a623cff7471d8b6c2d9766918dcd70545127f4aaf5dcd79475aa9e284', 4),
('vn-chay-03', 'mi-xao-chay-rau-nam', 44, 'Mì xào giòn chay nấm rau củ', 'Sợi mì vàng chiên phồng giòn rụm phủ nước sốt nấm đùi gà, cải ngọt và cà rốt sánh bóng đậm đà hương dầu hào chay', 'Đĩa mì xào giòn chay hấp dẫn với sợi mì vàng chiên phồng giòn tan, không ngấm dầu, kết hợp phần nhân xào nóng hổi gồm nấm đùi gà dai ngọt, cải ngọt xanh mướt, cà rốt giòn sần sật hòa quyện trong lớp sốt dầu hào chay sánh bóng.', 'Xếp mì chiên giòn ra đĩa lớn rồi rưới sốt nấm rau củ nóng hổi lên trên ngay trước khi ăn, rắc thêm ngò rí và tiêu đen; ăn kèm chén nước tương ớt.', 'Nên bảo quản riêng phần mì đã chiên trong hộp kín ở nhiệt độ phòng và phần sốt rau củ trong ngăn mát tủ lạnh (tối đa 24 giờ); hâm nóng sốt trên chảo rồi mới chan lên mì khi ăn.', 'vietnamese', 'mon_chay', 'toan_quoc', 'medium', 15, 15, 3, 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=800&q=80', '["Món chay","Mì xào giòn","Nấm đùi gà","Rau củ","Đổi vị"]', '["breakfast","lunch","dinner"]', '["deep_fry","stir_fry"]', '["sesame","soybean","wheat"]', 341, 341.4, 1428, 7.1, 13.2, 1.9, 50.7, 3.8, 4.6, 1277, 3.19, '["NIN VN Fresh Rice Noodle Ref","USDA FDC 168580","USDA FDC 169246","USDA FDC 169655","USDA FDC 169717","USDA FDC 169997","USDA FDC 170390","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', '4f044ada5b9efac080102cfda241bfcf11628a5a7c1132769562ce1f436f8e25', '69f59c33f1ef62b31af878aa70258bd61d8df2b543b61db7c3b952ceee2c333d', 4),
('vn-chay-04', 'ca-tim-nuong-mo-hanh', 45, 'Cà tím nướng mỡ hành nước tương tỏi ớt', 'Cà tím nướng mềm mọng ngọt thơm quyện mỡ hành xanh mướt, nước tương tỏi ớt đậm đà và đậu phộng rang bùi béo', 'Món cà tím nướng mỡ hành dân dã chuẩn vị Nam Bộ với phần thịt cà trắng mềm mọng ngọt tự nhiên, thơm nhẹ hương khói, phủ lớp mỡ hành xanh bóng béo ngậy, rưới sốt nước tương tỏi ớt chua mặn ngọt hài hòa và đậu phộng rang giòn bùi.', 'Bày cà tím nướng nóng hổi ra đĩa dài, rưới thêm nước tương tỏi ớt và rắc đậu phộng rang giã dập cùng tiêu xay; ăn kèm cơm trắng nóng.', 'Món ngon nhất khi dùng ngay lúc vừa nướng xong; nếu còn dư có thể bọc kín bảo quản ngăn mát tối đa 24 giờ và làm nóng lại bằng lò nướng ở 170°C trong 5 phút.', 'vietnamese', 'mon_chay', 'nam', 'easy', 10, 25, 3, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món chay","Nam Bộ","Món nướng","Cà tím","Dân dã"]', '["lunch","dinner"]', '["grill_roast"]', '["peanut","soybean","wheat"]', 184, 184, 771, 4.9, 12.9, 1.8, 15.5, 6, 8, 980, 2.45, '["USDA FDC 169228","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '020aa2d7430620bff82eabf7fa88aa7ebfcd7a16184150ea97c552c7be6bcd20', '151b7bb79a79cc49c8ce6f1e586342ad48ea95e98b78f36a18a18df3bb370879', 4),
('vn-chay-05', 'dau-hu-non-sot-nam-rom', 46, 'Đậu hũ non sốt nấm rơm dầu hào chay', 'Những khoanh đậu hũ non hấp nóng mềm mịn như lụa, phủ sốt nấm rơm xào dầu hào chay và xì dầu sánh bóng', 'Từng khoanh đậu hũ non hấp nóng giữ trọn độ mềm mịn tan ngay đầu lưỡi, kết hợp phần sốt nấm rơm búp giòn ngọt được xào thơm với hành tím, tỏi băm cùng dầu hào chay và nước tương đậm đà sánh bóng.', 'Rưới sốt nấm rơm nóng hổi phủ kín đĩa đậu hũ non vừa hấp xong, rắc hành lá, ngò rí, tiêu xay và ớt lát; dùng ngay cùng cơm trắng nóng.', 'Món ăn ngon nhất ngay khi vừa chế biến vì đậu hũ non để lâu dễ tiết nước làm loãng sốt; nếu còn dư nên đun sôi lại phần sốt trước rồi rưới lên đậu đã hấp ấm.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 15, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Đậu hũ non","Nấm rơm","Mềm mịn","Nhanh gọn"]', '["lunch","dinner"]', '["steam","stir_fry"]', '["soybean","wheat"]', 185, 184.9, 773, 9.9, 10.2, 1.5, 14.7, 1.8, 5.7, 913, 2.28, '["USDA FDC 169230","USDA FDC 169251","USDA FDC 169655","USDA FDC 169698","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172476","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', '389623c58be403a2bc276b70ce7332dac8d3a34021fcef8d03d3d2be98aa5d2a', '9ee2c7caf10b8271048311cdf5606397a5ed09850d03ca29bd5341d7b91c6594', 4),
('vn-chay-06', 'canh-cai-nau-dau-phu-non', 47, 'Canh cải xanh gừng đậu phụ thanh mát', 'Bát canh cải bẹ xanh giữ sắc xanh mướt cùng đậu phụ trắng béo mềm và gừng già đập dập cay ấm bụng', 'Bát canh cải bẹ xanh thanh đạm mà ấm bụng với vị hăng ngọt dịu nhẹ đặc trưng của rau cải non, hòa quyện hương gừng già cay thơm nồng giúp làm ấm cơ thể cùng những miếng đậu phụ trắng béo mềm thấm vị.', 'Múc canh ra tô lớn khi còn bốc khói, rắc hành lá, ngò rí và chút tiêu đen xay; dùng nóng trong bữa cơm chay gia đình.', 'Canh cải xanh ngon nhất khi ăn nóng trong ngày vì để lâu hoặc hâm lại nhiều lần rau dễ ngả màu vàng và tăng vị đắng.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 12, 4, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món chay","Món canh","Cải bẹ xanh","Ấm bụng","Dưới 20 phút"]', '["lunch","dinner"]', '["simmer"]', '["soybean","wheat"]', 132, 132.1, 552, 11.1, 8.3, 1.2, 6.5, 2.2, 2.6, 830, 2.08, '["USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170390","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '44e292f9764c33808acc4ef1cfa60944714ca154cf320ab72cc8ad44070e55c8', '01c4f8b61dbf7432c6ad25d359c08567041bd55c1dffcf39132056639133d743', 4),
('vn-sang-01', 'com-chien-trung-toi-hanh-hoa', 48, 'Cơm chiên trứng tỏi phi hành hoa', 'Cơm nguội rang tơi vàng óng bọc trứng gà béo thơm, dậy mùi tỏi phi giòn rụm và hành lá tươi', 'Đĩa cơm chiên trứng tỏi phi vàng ươm với từng hạt cơm săn tơi rời rạc, áo lớp trứng gà mượt mà, thơm nức hương tỏi phi giòn tan, hành lá xanh mát và nước mắm dậy mùi.', 'Múc cơm chiên ra đĩa ngay khi còn nóng giòn, rắc thêm tiêu xay và hành lá, ăn kèm dưa leo thái lát, cà chua bi và chén xì dầu ớt.', 'Ngon nhất khi thưởng thức ngay sau khi rang để hạt cơm và tỏi phi giữ độ giòn. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ rồi đảo lại trên chảo nóng không dầu 3 phút.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 2, 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=800&q=80', '["Ăn sáng","Cơm chiên","Nhanh gọn","Tiết kiệm","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","fish"]', 442, 442.4, 1851, 12, 17.3, 3.4, 58.8, 1.7, 2.8, 1079, 2.7, '["USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', '7f0e7bd407d6a215419d22b17b64dc7762e26d38e33e1963fd6b6ac634ed167c', '15a0af0b7daa6b1f020e3fa177f32d8fd430f274edd946b64d67500a0b442ca7', 4),
('vn-sang-02', 'banh-mi-op-la-pate', 49, 'Bánh mì ốp la pate dưa leo', 'Ổ bánh mì vỏ giòn rụm phết pate gan béo mịn, kẹp trứng ốp la lòng đào chiên bơ và dưa leo ngò rí mát lành', 'Món sáng quốc dân chuẩn vị quán Việt với hai ổ bánh mì nóng giòn, lớp pate gan mịn béo phủ đều ruột bánh, trứng gà ốp la lòng đào chiên bơ thơm ngậy cùng dưa leo giòn mát, ngò rí, xì dầu và tương ớt cay dịu.', 'Kẹp nhẹ ổ bánh mì và thưởng thức ngay khi vỏ bánh còn giòn rụm và lòng đỏ trứng còn ấm sóng sánh; dùng kèm ly cà phê sữa đá hoặc sữa đậu nành.', 'Bánh mì ốp la ngon nhất khi ăn liền sau khi làm. Nếu cần chuẩn bị trước, chỉ nên nướng giòn bánh và chiên trứng ngay trước khi ăn; phần pate và rau rửa sạch bảo quản riêng trong ngăn mát tối đa 2 ngày.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 6, 8, 2, 'https://images.unsplash.com/photo-1626804475297-41608ea09aeb?auto=format&fit=crop&w=800&q=80', '["Bánh mì","Ăn sáng","Nhanh gọn","Quốc dân","Dưới 20 phút"]', '["breakfast","lunch"]', '["pan_fry","grill_roast","assemble"]', '["egg","milk","pork","soybean","wheat"]', 435, 435.3, 1821, 23.4, 13.1, 5.7, 54.9, 3, 5.6, 1398, 3.5, '["USDA FDC 167871","USDA FDC 168409","USDA FDC 169997","USDA FDC 170106","USDA FDC 170931","USDA FDC 171287","USDA FDC 172686","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC Sriracha Ref"]', '7b7076981a3efe4065aa2f9e32b5b9a1626b4e9ba471be9dd55f49f6338a8126', '4cafb25782c35857efb3413889f8453723ba5bd549ff2f40a30168e34f8a7469', 4),
('vn-sang-03', 'chao-thit-bam-gung-tia-to', 50, 'Cháo thịt bằm gừng tía tô giải cảm', 'Cháo gạo rang sánh mịn nấu thịt heo nạc băm ngọt thanh cùng lá tía tô và gừng già ấm bụng', 'Tô cháo thịt bằm nóng hổi với hạt gạo tẻ kết hợp gạo nếp rang thơm nở bung sánh mịn, thịt heo nạc băm mềm ngọt không vón cục, hòa quyện hương cay ấm của gừng già, tiêu đen và lá tía tô giải cảm hiệu quả.', 'Múc cháo nóng sôi lên bát đã lót sẵn lá tía tô, hành lá và gừng thái chỉ, rắc nhiều tiêu đen xay rồi dùng ngay khi còn nóng để ra mồ hôi nhẹ.', 'Nên ăn nóng ngay sau khi nấu. Nếu còn dư, để nguội rồi cất hộp kín trong ngăn mát tối đa 24 giờ; khi hâm lại trên lửa nhỏ cần thêm chút nước sôi khuấy đều tránh khê đáy và chỉ rắc tía tô tươi lúc ăn.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 25, 3, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Cháo nóng","Giải cảm","Ăn sáng","Ấm bụng","Dễ tiêu"]', '["breakfast","dinner"]', '["simmer","boil"]', '["fish","pork"]', 324, 323.9, 1355, 14, 13.1, 4.8, 36.2, 1.7, 1.2, 1301, 3.25, '["MEXT Shiso Ref","USDA FDC 167902","USDA FDC 168881","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '84e9b48bdef89661ade44837bafecab38d877cf0f5594b2a38717aea4500d945', 'e1c873b76448ec53784b6d3a15ab83906520aeaae1d14e6327628be4fcfbada0', 4),
('vn-sang-04', 'mi-tom-xao-bo-trung-long-dao', 51, 'Mì gói xào bò trứng lòng đào', 'Sợi mì dai giòn xào lửa lớn cùng thịt bò thăn mềm ngọt, cải ngọt xanh giòn và trứng ốp la lòng đào béo ngậy', 'Món mì xào bò trứng lòng đào hấp dẫn với từng sợi mì săn dai không bết dính, thịt bò thăn xào tái mềm đậm đà nước tương dầu hào, rau cải ngọt giòn xanh và quả trứng ốp la lòng đào tan chảy béo mượt.', 'Bày mì xào bò ra đĩa lớn, đặt trứng ốp la lên trên cùng vài cọng ngò rí, rắc tiêu đen xay và thưởng thức nóng kèm tương ớt hoặc ớt tươi thái lát.', 'Ngon nhất khi dùng ngay lúc sợi mì còn săn dai và lòng đỏ trứng còn chảy béo. Không nên để qua đêm vì sợi mì sẽ hút ẩm và bị mềm nhũn.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 2, 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Mì xào","Ăn nhanh","Dưới 20 phút","Bò xào","Sinh viên"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry","pan_fry"]', '["beef","egg","molluscs","soybean","wheat"]', 667, 666.5, 2789, 38.6, 29.7, 7.9, 60.7, 3.9, 4.1, 1729, 4.32, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170390","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '5ca50b7b588852f676f56c11c30fe59c5e5bbe32e9d814c72540acbde10e1203', '276a431d4168d3353edd66d61fce98959ee9198ea03a8db2df7723c76bbc0f44', 4),
('vn-sang-05', 'trung-cuon-rau-cu-han-quoc', 52, 'Trứng cuộn rau củ mềm mịn', 'Trứng gà đánh tan lọc rây pha sữa tươi, tráng nhiều lớp cuộn tròn cùng cà rốt, hành tây và hành lá đẹp mắt', 'Món trứng cuộn rau củ mềm mịn từng lớp, vàng ươm bắt mắt điểm xuyết màu cam tươi của cà rốt, xanh non của hành lá và vị ngọt dịu từ hành tây cùng sữa tươi không đường.', 'Xếp từng khoanh trứng cuộn dày dặn ra đĩa, dùng nóng kèm cơm trắng hoặc bánh mì; chấm cùng tương ớt, tương cà hoặc xốt mayonnaise.', 'Nên ăn nóng hoặc ấm trong ngày để giữ độ ẩm xốp của trứng. Nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, khi dùng có thể hấp cách thủy nhẹ 2 phút cho trứng mềm trở lại.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 8, 10, 2, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Trứng cuộn","Ăn sáng","Dưới 20 phút","Giàu đạm","Bé thích"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","fish","milk"]', 217, 217.1, 908, 12.6, 14.9, 3.9, 8.2, 1.6, 4, 939, 2.35, '["USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', '535e7a632d705e9345d785766560c07be579229d1d4b82008948f5e3dd01e37f', '5a4cfbfe4cf87a4bfbe852f66959131412933dae5f09e0867e4e6ab76db91a84', 4),
('vn-sang-06', 'sup-ga-ngo-non-nam-huong', 53, 'Súp gà ngô non nấm hương trứng hoa', 'Nước dùng gà ngọt thanh quyện hạt ngô ngọt giòn, nấm hương thái chỉ và những vân hoa trứng mềm mịn', 'Nồi súp gà ngô non nấm hương nóng hổi sánh nhẹ óng ả với vị ngọt tự nhiên từ ức gà ta luộc xé sợi và hạt ngô ngọt, thơm nồng hương nấm hương khô, điểm xuyết những dải vân trứng hoa mềm mượt, dầu mè và tiêu trắng.', 'Múc súp nóng ra bát sâu lòng, nhỏ vài giọt dầu mè, rắc thêm ngò rí, hành lá và tiêu trắng xay; dùng nóng ngay để cảm nhận độ sánh mượt.', 'Súp ngon nhất khi ăn nóng vừa nấu xong. Nếu bảo quản ngăn mát tối đa 24 giờ, khi hâm lại trên lửa nhỏ cần khuấy liên tục và thêm 2–3 muỗng nước lọc nếu súp đặc lại.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 20, 4, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Súp nóng","Ăn sáng","Khai vị","Thanh nhẹ","Dễ tiêu"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["chicken","egg","sesame"]', 242, 242.2, 1013, 22.2, 8.3, 1.7, 20.9, 2.1, 4.2, 905, 2.26, '["USDA FDC 168436","USDA FDC 169717","USDA FDC 169997","USDA FDC 169998","USDA FDC 170005","USDA FDC 170499","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '388e059f16dff7358380e001fa0bad8640c6281aeb89ccd24caa1d2d5fc2e1e5', '8b1d6dbbffe79a42bc0e742db07b1e8106178b298773a78d2dcde5398fb248e3', 4),
('vn-lau-01', 'lau-rieu-cua-dong-bap-bo-suon-sun', 54, 'Lẩu riêu cua đồng sườn sụn bắp bò', 'Nồi lẩu riêu cua Bắc Bộ thơm nồng giấm bỗng, tảng riêu cua béo ngậy nhúng cùng bắp bò hoa giòn và sườn sụn heo sần sật', 'Lẩu riêu cua đồng sườn sụn bắp bò là đặc sản trứ danh đất Bắc. Nước lẩu chua thanh thơm nức mùi giấm bỗng và mắm tôm, nổi bật với lớp riêu cua đồng vàng ươm béo bùi, kết hợp sườn sụn ninh mềm giòn, bắp bò hoa thái mỏng, đậu phụ rán vàng và rổ rau sống tươi mát.', 'Đặt nồi lẩu sôi lăn tăn giữa bàn trên bếp từ hoặc bếp ga mini; nhúng bắp bò, đậu rán, váng đậu, rau muống chẻ và hoa chuối bào ăn kèm bún tươi cùng rau kinh giới, tía tô.', 'Nếu còn dư nước lẩu, lọc tách riêng rau và bún, để nguội rồi bảo quản ngăn mát tối đa 24 giờ; khi dùng lại đun sôi 3–5 phút và nhúng phần thịt, rau mới.', 'vietnamese', 'mon_lau_tiec', 'bac', 'hard', 35, 45, 6, 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Riêu cua đồng","Bắc Bộ","Bắp bò","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","pan_fry","boil"]', '["beef","crab","crustaceans","fish","pork","shrimp","soybean"]', 720, 719.6, 3010, 52.9, 35.4, 9.7, 48.4, 6.2, 4.9, 1640, 4.1, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","Chili Oil / Satay Ref","MEXT Shiso Ref","NIN VN Fresh Rice Noodle Ref","SE Asian Banana Blossom Ref","USDA / MEXT Fish Cake Ref","USDA FDC 167861","USDA FDC 169378","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172472","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '829dd0c22b82199533e9b110f1beca7584bec832ae8dbfa13e9e47a5bf285646', 'd1408e19aa26f4c656afcda20baef90787134e461c1a02fc3b91f14ce541a380', 4),
('vn-lau-02', 'lau-ga-la-giang-chua-cay', 55, 'Lẩu gà ta lá giang chua cay Nam Bộ', 'Thịt gà ta săn chắc da giòn hòa quyện nước lẩu lá giang vò dập chua thanh dịu mát, thơm nồng mùi sả ớt và rau ngổ miền Tây', 'Lẩu gà ta lá giang là món lẩu đặc sản Nam Bộ rất được ưa chuộng trong những bữa tiệc sum họp hay ngày mưa se lạnh. Nước dùng hầm từ thịt gà ta ngọt đậm, kết hợp vị chua thanh tự nhiên của lá giang vò dập cùng hương thơm sả, ớt hiểm và ngò gai, rau ngổ.', 'Dọn nồi lẩu nóng giữa bàn trên bếp giữ sôi lăn tăn, nhúng rau muống chẻ và hoa chuối bào; ăn kèm bún gạo tươi và chén muối ớt hoặc nước mắm ớt mặn chấm thịt gà.', 'Nếu còn dư nước lẩu và thịt gà, vớt bỏ phần lá giang để tránh nước bị chua gắt thêm, để nguội rồi bảo quản ngăn mát tối đa 24 giờ và đun sôi lại 5 phút trước khi dùng.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 40, 5, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Gà ta","Lá giang","Nam Bộ","Chua cay"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","fish"]', 634, 634.3, 2654, 37.1, 30.5, 7.9, 53, 6.6, 6.6, 1692, 4.23, '["Chili Oil / Satay Ref","NIN VN Fresh Bun Ref","SE Asian Banana Blossom Ref","USDA FDC 168573","USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171413","USDA FDC 171711","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', '42cd3e2abca824757ad4354e956d4adc163dd02c5b399339b918ac805731a3ce', 'e48f58e80a256085f35b6d02707c33b17b18f1f06a476ead6c627ccf859133ed', 4),
('vn-lau-03', 'lau-hai-san-thap-cam-chua-cay', 56, 'Lẩu hải sản tôm mực chua cay', 'Nước lẩu chua cay đậm đà từ me chín, sả riềng và lá chanh, nhúng tôm sú tươi giòn, mực ống sần sật và cá phi lê ngọt thịt', 'Lẩu hải sản tôm mực chua cay có nồi nước dùng sóng sánh màu đỏ cam hấp dẫn, hòa quyện hương thơm nồng nàn của sả, riềng, lá chanh cùng vị chua thanh của me chín và dứa. Hải sản tươi sống nhúng vừa chín tới giữ trọn độ giòn ngọt mọng nước.', 'Bày đĩa tôm sú, mực ống, cá phi lê, nấm tươi, rau muống và cải thảo quanh nồi lẩu sôi trên bàn; nhúng chín tới và thưởng thức cùng bún tươi, chấm muối tiêu chanh hoặc nước mắm ớt.', 'Hải sản chỉ nên nhúng đủ ăn trong bữa; phần nước lẩu chưa nhúng hải sản có thể bảo quản ngăn mát tối đa 24 giờ và đun sôi lại 3 phút khi dùng tiếp.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'medium', 25, 35, 5, 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Hải sản","Tôm mực","Chua cay","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["crustaceans","fish","molluscs","shrimp","squid"]', 541, 540.7, 2262, 46.6, 8.7, 1.6, 72.3, 6.8, 15.6, 1319, 3.3, '["Citrus Leaf Culinary Ref","NIN VN Fresh Rice Noodle Ref","USDA / SE Asian Galangal Ref","USDA FDC 168573","USDA FDC 168580","USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169253","USDA FDC 169378","USDA FDC 169655","USDA FDC 169918","USDA FDC 169977","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 175148","USDA FDC 175179","USDA FDC Sriracha Ref"]', '104e325901f970349c52433310e6f8b884f00e5f57c59b912ec9e83cd322d79c', 'fb770647253158181263da2e39acd9136d645159e8a78ef502eadf53f551733e', 4),
('vn-lau-04', 'lau-nam-thap-cam-thanh-dam', 57, 'Lẩu nấm thập cẩm gà ta thanh đạm', 'Nước dùng ninh từ gà ta, xương heo cùng táo đỏ, kỷ tử và củ cải ngọt thanh, nhúng cùng nhiều loại nấm tươi giòn dai bổ dưỡng', 'Lẩu nấm thập cẩm gà ta là món lẩu thanh đạm, ít dầu mỡ và giàu dưỡng chất. Nước lẩu ngọt tự nhiên từ xương ống, gà ta thả vườn kết hợp bắp ngọt, củ cải, cà rốt và vị thảo mộc nhẹ của táo đỏ kỷ tử, tôn lên độ giòn ngọt tinh tế của các loại nấm tươi.', 'Bày khay nấm tươi thập cẩm, đậu phụ non, cải thảo, rau cải cúc và mì trứng vắt trụng ráo quanh nồi lẩu; nhúng nấm chín vừa trong 2–3 phút rồi dùng nóng với nước tương ớt hoặc muối tiêu chanh.', 'Nước dùng gà và nấm chưa nhúng rau có thể để nguội, bảo quản ngăn mát tối đa 24 giờ; khi dùng lại đun sôi 5 phút và nhúng rau nấm mới.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'medium', 25, 45, 5, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Lẩu nấm","Gà ta","Thanh đạm","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","egg","fish","pork","soybean","wheat"]', 717, 717, 3000, 48.6, 33.4, 8.9, 58.3, 8.2, 11.9, 1635, 4.09, '["Pork Bone Stock Extraction Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 168452","USDA FDC 168580","USDA FDC 169230","USDA FDC 169249","USDA FDC 169251","USDA FDC 169253","USDA FDC 169977","USDA FDC 169998","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171413","USDA FDC 172185","USDA FDC 172476","USDA FDC 173468","USDA FDC 173647","USDA FDC Jujube Ref","VN/Asian Seasoning Powder Avg"]', '87490711f30e6eb4fd84516b2237176e3b5d9c83e36dc40077c7455b4f11bf19', 'c3b77b88bf61ebbd78b79053a87fde8215b5799de7367956fb168e5d0156d78b', 4),
('vn-lau-05', 'lau-ca-thac-lac-kho-qua', 58, 'Lẩu cá thác lác khổ qua thanh mát', 'Chả cá thác lác quết dai dẻo thơm mùi thì là hành tiêu, thả vào nước dùng xương ngọt trong nhúng cùng khổ qua bào mỏng giòn mát', 'Lẩu cá thác lác khổ qua là món ăn giải nhiệt đặc sắc của miền Nam. Nước lẩu hầm từ xương heo cùng hành tây và cà rốt ngọt thanh trong veo, kết hợp những viên chả cá thác lác quết dai sần sật và từng lát khổ qua ướp lạnh bào mỏng giòn rụm dịu đắng.', 'Múc từng viên cá thác lác thả vào nồi lẩu sôi cho đến khi nổi phồng, nhúng nhanh khổ qua bào mỏng, cải cúc và nấm khoảng 15–20 giây để giữ độ giòn ngọt; dùng nóng với bún gạo tươi và nước mắm ớt nguyên chất.', 'Nếu còn dư nước dùng và viên chả cá đã luộc chín, bảo quản riêng với khổ qua trong ngăn mát tối đa 24 giờ; khi ăn đun sôi nước dùng rồi mới thả khổ qua tươi vào.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 35, 4, 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Cá thác lác","Khổ qua","Nam Bộ","Thanh mát"]', '["lunch","dinner"]', '["simmer","boil"]', '["fish","pork"]', 438, 437.8, 1832, 35.3, 10.5, 2.6, 52.2, 8.4, 8.6, 1693, 4.23, '["NIN VN Fresh Bun Ref","Pork Bone Stock Extraction Ref","USDA FDC 168393","USDA FDC 169249","USDA FDC 169251","USDA FDC 169253","USDA FDC 169378","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170933","USDA FDC 171413","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', 'b3823fa6d30a2ad712f1077df3272163880217167ec7fb8fb251ad5184b2e9f6', 'abbe4c1e99b1532036954fb89139bb92a1bc8c9db4fd55611b8900583d32641c', 4),
('gl-01', 'pasta-pomodoro', 59, 'Mì Ý sốt cà chua Pomodoro', 'Mì Spaghetti dai vừa chuẩn Ý hòa quyện sốt cà chua ninh sánh mịn, thơm mùi tỏi phi dầu ô liu và lá húng quế tươi', 'Mì Ý sốt cà chua Pomodoro là biểu tượng tối giản của ẩm thực Ý với vị chua ngọt tự nhiên từ cà chua chín lột vỏ ninh chậm, thơm dịu tỏi phi dầu ô liu nguyên chất và lá húng quế Tây tươi mát.', 'Chia mì ra đĩa sâu lòng đã làm ấm, rắc thêm phô mai Parmesan bào mịn và vài lá húng quế tươi lên trên, dùng nóng ngay khi sợi mì còn bóng sốt.', 'Phần sốt cà chua có thể bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; khi ăn đun nóng lại sốt trên chảo rồi trộn với mì mới luộc để giữ độ dai ngon.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 25, 2, '/frigo/recipes/global/pasta-pomodoro.webp', '["Món Ý","Mì Ý","Sốt cà chua","Thanh đạm","Nấu nhanh"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["milk","wheat"]', 605, 604.9, 2531, 20.5, 18.6, 4, 91, 7.2, 11.6, 997, 2.49, '["USDA FDC 168927","USDA FDC 169072","USDA FDC 169230","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647"]', '57f35b2d9e1efad53f79716ccc3496baf9d081ed63603e453d4939990a42849e', 'fc1a46b441522ada0f516fa151c0d4d833948df8c227c09f6b9b019954be4cbb', 4),
('gl-02', 'mapo-tofu', 60, 'Đậu phụ sốt Mapo Tofu Tứ Xuyên', 'Đậu phụ non mềm mịn hòa quyện thịt heo băm xào giòn trong sốt tương ớt đậu bản cay nồng và hoa tiêu tê đầu lưỡi', 'Đậu phụ sốt Mapo Tofu Tứ Xuyên nổi tiếng với sự kết hợp hài hòa giữa đậu phụ non béo mịn, thịt heo xay săn thơm và lớp sốt đỏ óng từ tương ớt đậu bản, đậu tương đen lên men cùng hoa tiêu tê nồng.', 'Dọn nóng trong đĩa sâu lòng, rắc phần lá hành xanh và bột hoa tiêu còn lại lên mặt; thưởng thức cùng cơm trắng dẻo nóng.', 'Ngon nhất khi dùng ngay lúc nóng. Nếu bảo quản tủ mát trong hộp kín tối đa 2 ngày, hâm lại bằng chảo trên lửa nhỏ và thêm 1–2 muỗng canh nước lọc để sốt không bị khô.', 'chinese', 'mon_kho', NULL, 'medium', 15, 20, 4, '/frigo/recipes/global/mapo-tofu.webp', '["Tứ Xuyên","Cay tê","Đậu phụ","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry","braise"]', '["pork","sesame","soybean","wheat"]', 305, 304.5, 1274, 14.8, 22.1, 5, 12.3, 1.8, 2.6, 1232, 3.08, '["Douchi Reference","Pixian Doubanjiang Ref","Spice Reference","USDA FDC 167902","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 171028","USDA FDC 171319","USDA FDC 171413","USDA FDC 172476","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'de3870eb0a7cf7152e859aff991cd0b76b8086a321d42eceea2af2f084d5bea8', 'dbd0608a0c31c2952692a42faaf9a2cd11a74351d9b92701edf107b423395585', 4),
('gl-03', 'tomato-egg-stir-fry', 61, 'Cà chua xào trứng kiểu Trung Hoa', 'Trứng gà đánh với rượu Thiệu Hưng chiên xốp mềm, hòa quyện sốt cà chua đỏ mọng chua ngọt thanh nhẹ chuẩn bữa cơm gia đình', 'Cà chua xào trứng kiểu Trung Hoa là món ăn gia đình kinh điển với lớp trứng chiên tơi xốp ngấm trọn nước sốt cà chua đỏ sánh, vị chua ngọt dịu nhẹ và mùi thơm thoang thoảng của dầu mè cùng rượu Thiệu Hưng.', 'Dùng nóng ngay sau khi tắt bếp, rắc thêm hành lá xanh và ăn kèm cơm trắng nóng hoặc mì trộn.', 'Món ăn ngon nhất khi dùng trong bữa; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa vừa với 1 muỗng canh nước lọc.', 'chinese', 'mon_xao', NULL, 'easy', 8, 10, 2, '/frigo/recipes/global/tomato-egg-stir-fry.webp', '["Trung Hoa","Nhanh gọn","Cà chua trứng","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","sesame","wheat"]', 339, 338.9, 1417, 13.4, 25.6, 5.2, 15.1, 3.3, 10.9, 914, 2.29, '["Shaoxing Wine Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'c0f76c1cb5240e6fa59947ecfb566f725eb14c76a63f94895cc6e0bb528ed5d6', '90009ddd3488d3e5aabf2acdb087499fd949491c0abad7f40d2224cdd082d932', 4),
('gl-04', 'oyakodon', 62, 'Cơm gà trứng Oyakodon Nhật Bản', 'Cơm donburi Nhật truyền thống với thịt đùi gà mềm ngọt om nước dùng dashi, quyện lớp trứng gà đánh lướt mịn mượt trên nền cơm trắng dẻo nóng', 'Oyakodon là món cơm tô gia đình quen thuộc của Nhật Bản, kết hợp thịt đùi gà cắt miếng vừa ăn nấu cùng hành tây ngọt mềm trong nước dùng dashi đậm vị xì dầu và rượu ngọt mirin, phủ lớp trứng đánh nhẹ chín tới mịn mượt.', 'Xới cơm Nhật nóng ra hai tô sâu lòng, nhẹ nhàng trút trọn phần gà trứng còn nóng hổi lên trên, rắc hành lá thái nhỏ và ớt bột Shichimi rồi thưởng thức ngay.', 'Nên dùng ngay khi trứng còn mềm mịn; nếu dư, tách riêng phần cơm và nhân gà trứng cho vào hộp kín bảo quản tủ lạnh tối đa 1 ngày, hâm nóng bằng lò vi sóng hoặc chảo nhỏ có nắp trước khi ăn.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 15, 2, '/frigo/recipes/global/oyakodon.webp', '["Nhật Bản","Cơm donburi","Thịt gà","Nhanh gọn","Bữa trưa"]', '["lunch","dinner"]', '["simmer"]', '["chicken","egg","fish","sesame","soybean","wheat"]', 672, 672.2, 2813, 42.8, 21.8, 6.3, 68.2, 1.8, 12.7, 1380, 3.45, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 168878","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 171287","USDA FDC 172385","USDA FDC 174277"]', '5404e3189ccd13e8d38f2831f6768cf2ce3320ae978bf19955aa882b0baf955b', '82378c9b6531fdd69f26b28ce3a562a18de77317838e12ad12ef69071b92e139', 4),
('gl-05', 'kimchi-fried-rice', 63, 'Cơm chiên kim chi Hàn Quốc', 'Cơm chiên kim chi chua cay đậm vị tương ớt Gochujang, hạt cơm săn tơi phủ trứng ốp la lòng đào béo ngậy', 'Cơm chiên kim chi Hàn Quốc là món ăn nhanh gọn nhưng tròn vị nhờ sự kết hợp giữa cơm nguội hạt săn tơi, kim chi cải thảo ủ chua giòn sần sật và sốt tương ớt Gochujang cay ngọt hài hòa. Lớp trứng ốp la lòng đào bên trên giúp món ăn thêm béo thơm hấp dẫn.', 'Xới cơm nóng ra đĩa, đặt trứng ốp la lòng đào lên trên, rắc hạt mè trắng rang và rong biển lá khô xé nhỏ; ăn ngay khi còn nóng và trộn đều lòng đỏ trứng vào cơm.', 'Món ngon nhất khi dùng ngay sau khi chiên. Phần cơm còn dư có thể bảo quản hộp kín trong ngăn mát tối đa 24 giờ và áp chảo lại trên lửa vừa 3–4 phút với chút dầu ăn trước khi dùng.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 10, 15, 2, '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Món nhanh","Chua cay","Cơm chiên","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["egg","sesame","soybean","wheat"]', 508, 508.2, 2127, 14.8, 15.3, 3.1, 77.1, 4.4, 6.1, 1210, 3.03, '["USDA / Korean Gochujang Ref","USDA FDC 168456","USDA FDC 168878","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 174277"]', 'e180571a64206c91489bd3e7da92daf18d12ebd4de535036f2ddeb998d97bc54', '892cd104c8842994b37e0c4c607ce72bec5078f45beec3fa4128c7b93edc4c11', 4),
('gl-06', 'pad-krapow', 64, 'Thịt heo băm xào lá quế kiểu Thái (Pad Krapow)', 'Thịt heo băm xào tỏi ớt thơm nồng hương húng quế Thái, đậm vị nước tương và nước mắm, ăn kèm cơm trắng trứng ốp la giòn viền', 'Pad Krapow là món cơm đĩa đường phố trứ danh của Thái Lan với thịt heo băm xào săn trên lửa lớn cùng tỏi ớt giã dập, đậu que giòn ngọt, sốt nước tương đậm đà và lá húng quế thơm nồng.', 'Xới cơm trắng nóng ra đĩa sâu lòng, múc thịt heo xào húng quế lên bên cạnh, đặt trứng gà ốp la viền giòn lên trên và dọn kèm chén nước mắm ớt chanh.', 'Ngon nhất khi ăn nóng ngay sau khi xào; phần thịt xào có thể bảo quản hộp kín trong ngăn mát 2 ngày, hâm nóng bằng chảo lửa lớn và chiên trứng mới khi dùng.', 'thai', 'mon_xao', NULL, 'easy', 10, 12, 2, '/frigo/recipes/global/pad-krapow.webp', '["Thái Lan","Món xào","Cay nồng","Cơm đĩa","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["egg","fish","pork","soybean","wheat"]', 813, 812.9, 3401, 38.2, 48.8, 15.1, 53.4, 2.3, 6.1, 1578, 3.95, '["Dark Soy Sauce Label Ref","USDA FDC 167902","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170106","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277"]', '76b23f3e7bc5408231bcdb454b1e9942ddabdbb2035f37618a9201a42ee36870', '028df0d24c7c63e643d13bb5ce435c77e2c59fef920a04654cca3b26f0814f84', 4),
('gl-07', 'kimbap-han-quoc', 65, 'Cơm cuộn Kimbap Hàn Quốc', 'Cuộn rong biển chắc tay với cơm dẻo thơm dầu mè, thịt bò xào đậm đà, trứng tráng, rau chân vịt, cà rốt và củ cải vàng giòn', 'Cơm cuộn Kimbap Hàn Quốc hài hòa sắc màu và dinh dưỡng với lớp cơm trắng trộn dầu mè thơm bùi, ôm trọn nhân thịt bò xào xì dầu, trứng gà rán vàng, rau chân vịt chần, cà rốt giòn ngọt và thanh củ cải muối vàng chua dịu.', 'Cắt cuộn Kimbap thành từng khoanh tròn dày khoảng 1,5–2 cm, bày ra đĩa cùng chút củ cải muối vàng hoặc kim chi ăn kèm.', 'Gói kín từng cuộn bằng màng bọc thực phẩm và bảo quản ngăn mát tối đa 24 giờ; không nên hâm nóng bằng lò vi sóng quá lâu để tránh dai lá rong biển, chỉ cần để nhiệt độ phòng 15 phút trước khi ăn.', 'korean', 'mon_cuon_nom', NULL, 'easy', 25, 20, 3, '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Cơm cuộn","Dã ngoại","Meal prep","Rong biển"]', '["breakfast","lunch"]', '["pan_fry","boil","assemble"]', '["beef","egg","sesame","soybean","wheat"]', 683, 683, 2858, 29.4, 30.1, 6.9, 72.9, 4.1, 5.1, 1702, 4.26, '["MEXT Takuan Ref","USDA FDC 168456","USDA FDC 168462","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'dcd097ef76bce9e3c6c65e2b0932d100a0225ac6a153142f242fe85428d9b642', 'afdc1eddfcc34bf64597d910ef75f5eaba5cc340f4a5c166d78be0086f50df2c', 4),
('gl-08', 'tokbokki-cay-ngot', 66, 'Bánh gạo Tokbokki sốt cay ngọt', 'Bánh gạo dẻo mềm quyện sốt tương ớt Gochujang cay ngọt sánh đỏ cùng chả cá Hàn Quốc, bắp cải ngọt dịu và trứng gà luộc', 'Bánh gạo Tokbokki sốt cay ngọt chuẩn vị đường phố Seoul với từng thỏi bánh gạo dẻo bùi thấm đẫm nước sốt Gochujang đỏ óng sánh mịn, hòa quyện vị ngọt thanh của bắp cải, chả cá mềm dai và trứng gà luộc béo bùi.', 'Múc Tokbokki nóng hổi ra đĩa sâu lòng, cắt đôi trứng gà luộc đặt lên trên và rắc thêm chút hạt mè trắng rang, dùng ngay khi nước sốt còn sánh ấm.', 'Nếu còn dư, cất hộp kín trong ngăn mát tối đa 2 ngày; khi ăn lại thêm 2–3 muỗng canh nước lọc vào chảo rồi đun nhỏ lửa 4–5 phút cho bánh gạo mềm dẻo trở lại.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 10, 20, 2, '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Ăn vặt","Cay ngọt","Bánh gạo","Đường phố"]', '["lunch","dinner"]', '["boil","simmer"]', '["egg","fish","sesame","soybean","wheat"]', 646, 646, 2703, 22.5, 9.7, 2.3, 117, 4.4, 24.3, 1722, 4.31, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","Korean Tteok Ref","USDA / Korean Gochujang Ref","USDA / MEXT Fish Cake Ref","USDA FDC 168836","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171287","USDA FDC 174277"]', '36b39d26d4528a39803b3e102890771109e4a56391158ed5ad4f5fdec73ae925', 'ab9f053061a47942160f5c1219eb77e309f71d477303a35579d428250f46f386', 4),
('gl-09', 'chawanmushi', 67, 'Trứng hấp Chawanmushi tôm nấm Nhật Bản', 'Trứng hấp custard mặn kiểu Nhật mềm mịn như thạch lụa, hòa quyện vị ngọt thanh của tôm tươi, thịt đùi gà, nấm hương và nước dùng dashi', 'Chawanmushi là món trứng hấp khai vị tinh tế của ẩm thực Nhật Bản, nổi bật với kết cấu custard mịn màng không rỗ bọt khí nhờ tỷ lệ trứng và nước dùng dashi chuẩn xác cùng kỹ thuật hấp lửa nhỏ cách thủy.', 'Dọn nguyên chén sứ hấp nóng hổi lên bàn ăn cùng thìa nhỏ, rắc thêm hành lá tươi lên mặt chén và dùng làm món khai vị hoặc ăn kèm cơm trắng.', 'Ngon nhất khi thưởng thức ngay sau khi hấp; phần chưa dùng hết đậy kín nắp chén bảo quản tủ lạnh tối đa 1–2 ngày và hấp cách thủy lại lửa nhỏ 3–4 phút cho nóng đều.', 'japanese', 'mon_hap_luoc', NULL, 'easy', 15, 25, 2, '/frigo/recipes/global/oyakodon.webp', '["Nhật Bản","Món hấp","Thanh đạm","Hải sản","Bữa tối nhẹ"]', '["lunch","dinner"]', '["steam"]', '["chicken","crustaceans","egg","fish","shrimp","soybean","wheat"]', 214, 214.4, 897, 22.7, 8.5, 2.5, 9, 1.2, 2.5, 943, 2.36, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA / MEXT Fish Cake Ref","USDA FDC 168436","USDA FDC 169251","USDA FDC 170005","USDA FDC 171287","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '3da81fc2d0c9bac89140870fb368c7a9f4d8eebb11623b710679a20d4deea784', '2dfffdcadb918a1ab59dc5f018d63d7ca85fac722696e3245259877be09580fa', 4),
('gl-10', 'thai-green-curry', 68, 'Cà ri xanh thịt gà kiểu Thái (Green Curry)', 'Thịt đùi gà om mềm trong nước cốt dừa béo ngậy hòa quyện sốt cà ri xanh, lá chanh Thái thơm nồng và cà tím giòn ngọt', 'Cà ri xanh (Kaeng Khiao Wan) nổi bật với màu xanh ngọc tự nhiên của ớt xanh và rau thơm, nước sốt cốt dừa tách dầu béo mịn quyện cùng đùi gà mềm ngọt, cà tím và hương lá chanh Thái.', 'Múc cà ri xanh nóng ra tô sâu lòng, rắc thêm vài lá húng quế Thái tươi và ớt đỏ thái lát; dọn ăn kèm cơm trắng gạo lài hoặc bún gạo tươi.', 'Cà ri ngon hơn khi để nghỉ 1–2 giờ cho thấm vị; bảo quản ngăn mát tối đa 2 ngày trong hộp kín, khi ăn đun nóng lại trên lửa nhỏ và khuấy đều để cốt dừa không tách lớp.', 'thai', 'mon_kho', NULL, 'medium', 15, 25, 3, '/frigo/recipes/global/pad-krapow.webp', '["Thái Lan","Cà ri","Cốt dừa","Cay nồng","Món om"]', '["lunch","dinner"]', '["simmer"]', '["chicken","crustaceans","fish","shrimp"]', 544, 544.4, 2278, 31, 39.2, 25.3, 19.9, 5, 13.3, 1473, 3.68, '["Asian Shrimp Paste Ref","Citrus Leaf Culinary Ref","Thai Curry Paste Ref","USDA FDC 169228","USDA FDC 170106","USDA FDC 170108","USDA FDC 170172","USDA FDC 172185","USDA FDC 172232","USDA FDC 172385","USDA FDC 172883","USDA FDC Palm Sugar Ref"]', '448a3c4b018afa2d937a5bc0ced993742499bc0b4dc367d4ffb8fb7e36f0302f', '5ba88aab04ed1c87188debb87454d34094772613cebefbcdbb0e8650b2377899', 4),
('gl-11', 'spaghetti-bolognese', 69, 'Mì Ý sốt bò bằm Bolognese', 'Mì Spaghetti dai ngon thấm đẫm sốt thịt bò xay hầm chậm cùng ba chỉ xông khói, rau củ soffritto, rượu vang trắng và sữa tươi béo dịu', 'Món mì Ý sốt bò bằm Bolognese chuẩn vị với nền rau củ cà rốt, cần tây, hành tây xào ngọt, kết hợp thịt bò xay và ba chỉ xông khói hầm chậm cùng sốt cà chua Passata, rượu vang trắng và sữa tươi tạo độ béo mượt tròn vị.', 'Bày mì Ý ra đĩa sâu lòng, chan ngập sốt thịt bò Bolognese nóng hổi lên trên, rắc thêm phô mai Parmesan bào mịn và ít tiêu đen xay.', 'Sốt Bolognese bảo quản trong hộp kín ở ngăn mát được 3 ngày hoặc cấp đông đến 1 tháng; khi dùng hâm nóng sốt trên lửa nhỏ với chút nước lọc rồi trộn mì mới luộc.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 60, 3, '/frigo/recipes/global/carbonara.webp', '["Món Ý","Mì Ý","Thịt bò bằm","Sốt cà chua","Gia đình"]', '["lunch","dinner"]', '["boil","braise","simmer"]', '["beef","celery","milk","pork","sulphites","wheat"]', 777, 776.8, 3250, 38.4, 31.7, 11.3, 77.9, 5.8, 11, 1477, 3.69, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169072","USDA FDC 169988","USDA FDC 170000","USDA FDC 170393","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 171593","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 174036"]', '925c81e34822c95c39b075ac74d3ba4f938f5356176c8205847f25f613378e2c', '1a1c522311074da7a5627214324d311d092356c45167a8b4598aa757beaed704', 4),
('gl-12', 'chinese-tomato-egg', 70, 'Trứng xào cà chua sốt tương kiểu Quảng Đông', 'Biến tấu kiểu quán cơm Hồng Kông với trứng đánh sữa tươi béo mượt, cà chua hai kiểu cắt hòa quyện tương cà, xì dầu và dầu hào', 'Khác với phiên bản truyền thống dùng muối và rượu Thiệu Hưng, trứng xào cà chua kiểu Quảng Đông kết hợp sữa tươi giúp miếng trứng mềm mịn như kem, quyện cùng nước sốt đậm vị từ tương cà, xì dầu nhạt, dầu hào và gừng thơm.', 'Dọn nóng ra đĩa hoặc chan trực tiếp lên tô cơm trắng nóng hổi, rắc hành lá thái nhỏ lên mặt.', 'Nên dùng ngay trong bữa để giữ độ mềm mịn của trứng; nếu bảo quản tủ mát tối đa 24 giờ, hâm lại nhẹ nhàng trên chảo lửa nhỏ.', 'chinese', 'mon_xao', NULL, 'easy', 10, 12, 2, '/frigo/recipes/vietnam/dau-phu-sot-ca-chua.webp', '["Quảng Đông","Nhanh gọn","Cà chua trứng","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","milk","molluscs","soybean","wheat"]', 297, 297.1, 1242, 11.8, 20.3, 4.2, 18.8, 3, 13.2, 905, 2.26, '["USDA FDC 169076","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170933","USDA FDC 171265","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277"]', 'ea7e0eb62b2be5003789bf95bb399eda7a64a0201cc45979960aa74031eccece', '94473a9416d77bfe679402fc255ff3b3427400e6d20b78e6e88d8608dca1f003', 4),
('imp-199ff78d3d8c8ab3', 'canh-bi-do-nau-tom-tuoi-ngot-nuoc', 71, 'Canh bí đỏ nấu tôm tươi ngọt nước', 'Bí đỏ chín mềm bùi quyện cùng nước dùng lọc từ đầu tôm và thịt tôm tươi săn ngọt, dễ nấu cho bữa cơm gia đình', 'Món canh dân dã Nam Bộ có màu vàng cam đẹp mắt, vị bùi ngọt tự nhiên của bí đỏ hòa cùng nước ngọt thanh từ đầu tôm ninh kỹ và thịt tôm tươi săn giòn.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay lên mặt; dùng kèm cơm trắng và đĩa cá kho hoặc thịt ram.', 'Để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 24 giờ; khi hâm lại nên đun lửa vừa vừa đủ sôi lăn tăn để bí đỏ không bị nát vụn và tôm không bị dai.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Bổ dưỡng","Cơm nhà","Dễ nấu"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 106, 106.2, 445, 11.4, 3.7, 0.6, 8.2, 0.9, 3.1, 1229, 3.07, '["USDA FDC 168448","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '03da674d31a12b4e08a29cd88c8136bf4b487f80a5d10e075b75a7778303025d', 'a8081ff83a2ac825f385bff7669e57af39fc52c59efb56603a87e98075b4296b', 4),
('imp-ab36e38b07f3a57b', 'suon-non-kho-dua-chua-ngot-dam-vi', 72, 'Sườn non kho dứa chua ngọt', 'Sườn non heo kho mềm cùng dứa chín vàng thơm, nước kho sánh màu cánh gián chua ngọt hài hòa chuẩn vị cơm nhà Nam Bộ', 'Từng dẻ sườn non thấm đẫm nước cốt dứa tự nhiên giúp thịt nhanh mềm ngọt, kết hợp cùng miếng dứa xào chín dịu vị chua và nước sốt kho cánh gián sánh bóng.', 'Múc sườn kho dứa ra đĩa sâu lòng, rắc hành lá và tiêu đen xay lên mặt, dùng nóng với cơm trắng và đĩa dưa leo thái lát.', 'Để nguội hoàn toàn và bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi ăn đun nóng lại trên lửa nhỏ với 1–2 muỗng nước ấm.', 'vietnamese', 'mon_kho', 'nam', 'medium', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Sườn non","Nam Bộ","Chua ngọt","Đưa cơm"]', '["lunch","dinner"]', '["braise","stir_fry","boil"]', '["fish","pork"]', 378, 378.4, 1583, 16.6, 28, 9.2, 15.2, 1.1, 11.8, 1340, 3.35, '["USDA FDC 167861","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647"]', '034d85de96b214769eed94699a2a243c719d673a409f026f3bd2f487bdb9086f', 'd0f7485cdbb43ce2dc5613af94e477cffb777a6d3ad1a8a67fe20255d5355595', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-26a36c69306143bc', 'tom-xao-bong-cai-xanh-toi-gion-ngot', 73, 'Tôm xào bông cải xanh tỏi giòn ngọt', 'Tôm tươi săn chắc quyện sốt sánh nhẹ cùng bông cải xanh giòn mướt, thơm lừng tỏi phi và vài giọt dầu mè', 'Tôm tươi lột vỏ rút chỉ xào nhanh lửa lớn giữ được độ ngọt giòn săn chắc, kết hợp cùng bông cải xanh chần sốc nhiệt giòn mát và lớp sốt bột bắp óng ả thơm mùi tỏi phi.', 'Xếp tôm và bông cải xanh ra đĩa rộng khi còn nóng, rắc tiêu đen xay lên trên; dùng ngay với cơm trắng nóng hổi.', 'Món hải sản xào ngon nhất khi ăn nóng trong bữa; nếu bảo quản tủ mát tối đa 24 giờ, hãy đảo nhanh lại trên chảo nóng khoảng 1 phút để tôm không bị khô cứng.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Rau xanh","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["crustaceans","fish","sesame","shrimp"]', 207, 207.1, 866, 19.2, 10, 1.5, 12.3, 2.8, 2.8, 1127, 2.82, '["USDA FDC 169230","USDA FDC 169698","USDA FDC 170000","USDA FDC 170379","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '28ec40c79a59d454b15dcd6ba27af587d645b9bdbfd9884b703c2c1d822f7077', '887a69516490cf41a247b31b2d0950a397a9a35cf29d4846213bfd402c879b0f', 4),
('imp-b87b71d57128cc07', 'ca-loc-chien-sa-ot-vang-gion', 74, 'Cá lóc chiên sả ớt vàng giòn', 'Khúc cá lóc ướp sả nghệ chiên vàng giòn rụm phủ sả phi thơm lừng, thịt cá ngọt săn chấm mắm ớt', 'Cá lóc chiên sả ớt vàng giòn là món ăn đậm chất miền Tây Nam Bộ, hấp dẫn bởi lớp vỏ ngoài vàng óng màu nghệ và giòn tan quyện sả tỏi phi thơm nức, trong khi thớ thịt cá lóc bên trong vẫn trắng ngọt, săn chắc.', 'Xếp các khúc cá ra đĩa, phủ đều phần sả tỏi phi vàng giòn lên trên cùng vài lát ớt sừng trang trí, ăn nóng với cơm trắng và chén nước mắm chanh ớt.', 'Nên dùng hết trong ngày để giữ độ giòn của lớp vỏ và sả phi; nếu bảo quản tủ mát tối đa 24 giờ, nên làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút.', 'vietnamese', 'mon_chien', 'nam', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Cá lóc","Nam Bộ","Sả ớt","Đưa cơm"]', '["lunch","dinner"]', '["deep_fry","pan_fry"]', '["fish","wheat"]', 292, 291.6, 1220, 29.1, 10.6, 2, 19.6, 0.9, 3.1, 1297, 3.24, '["Panko / Batter Mix Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '04355739d8bb1e4fe581c7028028d40de1b1103497f0f349e5ac29e858e37183', '2dde0993324ae9b03754e24509761127888f47067fa853fb659d86e88c567f8a', 4),
('imp-511a92d180408e0a', 'trung-hap-thit-bam-nam-huong-mem-min', 75, 'Trứng hấp thịt bằm nấm hương mềm mịn', 'Trứng gà đánh tan lọc mịn hấp cách thủy cùng thịt heo xay và nấm hương thơm dịu, mềm mượt như tàu hũ non', 'Món trứng hấp thịt bằm nấm hương béo bùi nhưng thanh nhẹ, bề mặt mịn mượt không bị rỗ nhờ lọc rây kỹ và hấp lửa nhỏ, kết hợp vị ngọt đậm của thịt heo xay cùng hương nấm đông cô đặc trưng.', 'Dọn nóng nguyên tô trứng hấp ra bàn, rắc thêm hành lá xanh và tiêu xay, ăn kèm cơm trắng nóng rất hợp cho cả trẻ nhỏ và người lớn tuổi.', 'Món ngon nhất khi dùng nóng ngay sau khi hấp. Nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và hấp cách thủy lại 5 phút ở lửa nhỏ.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 20, 22, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Trẻ em thích","Thanh đạm","Cơm nhà","Dễ nấu"]', '["lunch","dinner"]', '["steam"]', '["egg","fish","pork","sesame"]', 309, 308.8, 1291, 20, 21.4, 7.3, 8.9, 1.2, 2.3, 1128, 2.82, '["USDA FDC 167902","USDA FDC 168436","USDA FDC 169655","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd91ad3e96b3d5fe9b53589eef07b7461230ac22c3d3722b2e571b3c1957cb739', '14a6a69bf67a386f1edf0b02f4dd265e9fed98ad082555288d2e3e415c23af6f', 4),
('imp-d02c9b83214f81be', 'goi-dua-leo-tom-thit-gion-mat', 76, 'Gỏi dưa leo tôm thịt giòn mát', 'Dưa leo bỏ ruột thái lát ngâm đá giòn rụm trộn cùng tôm rim ngọt thịt, ba chỉ luộc mỏng, cà rốt và húng lủi thấm đẫm nước mắm chanh tỏi ớt', 'Gỏi dưa leo tôm thịt là món khai vị thanh mát đặc trưng Nam Bộ với từng lát dưa leo xanh giòn không chảy nước, kết hợp thịt ba chỉ luộc mềm, tôm rim đỏ cam săn ngọt và nước trộn mắm chanh tương ớt chua cay mặn ngọt hài hòa.', 'Bày gỏi ra đĩa lớn, rắc đậu phộng rang giã dập và hành phi giòn lên trên, dọn ăn ngay kèm bánh phồng tôm giòn rụm.', 'Gỏi dưa leo ngon nhất ngay sau khi trộn để giữ độ giòn của rau củ; nếu chuẩn bị trước, giữ riêng phần dưa leo cà rốt đã vắt ráo, tôm thịt và nước mắm trộn trong hộp kín ngăn mát tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi dưa leo","Khai vị","Giải ngán","Nam Bộ","Tôm thịt"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["crustaceans","fish","peanut","pork","shrimp"]', 656, 656.3, 2746, 28.1, 42.6, 13.9, 43.4, 4.3, 16.9, 1458, 3.65, '["USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 175179","USDA FDC Sriracha Ref","VN Banh Da Ref"]', '7b732d74488a13acf783528365b074d26386e514c85dd4e10e01bcc1960a8f60', '2d65ffb6ee5906c1577b7275839087dc53b37f1dec36c3256d31261249e263f7', 4),
('imp-9ae951bec7fbf21b', 'hu-tieu-xao-tom-gia-he-kieu-sai-gon', 77, 'Hủ tiếu xào tôm giá hẹ kiểu Sài Gòn', 'Sợi hủ tiếu dai mềm thấm đẫm xì dầu và dầu hào thơm lừng, xào nhanh trên lửa lớn cùng tôm tươi giòn ngọt, giá đỗ và lá hẹ xanh mướt', 'Món hủ tiếu xào tôm giá hẹ mang đậm phong vị quán ăn Sài Gòn với sợi hủ tiếu tơi mềm không bết dính, áo màu nâu cánh gián bóng bẩy từ nước tương và dầu hào, kết hợp tôm sú giòn ngọt cùng giá hẹ tươi mát.', 'Bày hủ tiếu xào ra đĩa nóng, điểm ngò rí và ớt tươi thái lát lên trên; dọn ăn ngay kèm nước tương ớt xắt hoặc tương ớt.', 'Món xào ngon nhất khi ăn nóng ngay sau khi nấu để giữ độ giòn của giá hẹ; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo chống dính với chút nước lọc.', 'vietnamese', 'mon_bun_pho', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu xào","Sài Gòn","Món nhanh","Hải sản"]', '["breakfast","lunch","dinner"]', '["stir_fry","boil","assemble"]', '["crustaceans","molluscs","shrimp","soybean","wheat"]', 515, 515.4, 2157, 21.7, 12.8, 2, 77.5, 3.5, 5.9, 1273, 3.18, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169745","USDA FDC 169963","USDA FDC 169994","USDA FDC 169997","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '822622d83aef402c57ad1616c1f04130d359be90f90d81c3090e6954eeddfba3', '3d6ab2c517d1d5df65ae2617e3ea1411c40abf798672f6eb5f19fe44a8c66bc3', 4),
('imp-5ab5c1053b7371f0', 'dau-phu-chien-sa-ot-chay-dam-da', 78, 'Đậu phụ chiên sả ớt chay đậm đà', 'Miếng đậu phụ chiên vàng giòn rụm áo kín sả ớt băm phi thơm lừng, thấm xì dầu mặn ngọt đưa cơm', 'Đậu phụ trắng chiên vàng giòn bên ngoài nhưng vẫn mềm béo bên trong, xóc đều cùng sả băm, tỏi và ớt tươi phi thơm với nước tương đậm đà, tạo nên món mặn chay dân dã dậy hương sả ớt vô cùng đưa cơm.', 'Bày đậu phụ chiên sả ớt ra đĩa, rắc thêm chút tiêu xay và dọn nóng cùng cơm trắng, dưa leo thái lát hoặc rau luộc.', 'Ngon nhất khi ăn nóng ngay để cảm nhận lớp vỏ giòn thơm; nếu bảo quản ngăn mát tối đa 2 ngày, hãy áp chảo nhanh trên lửa vừa 3 phút cho đậu nóng giòn trở lại.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Đậu phụ","Chiên sả ớt","Đậm vị","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["soybean","wheat"]', 214, 214.2, 896, 13.9, 14.2, 2.1, 11.9, 1.5, 3.6, 1251, 3.13, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '875cd9c905c1d8c12ddc98caa50f74e59877981f56644e259aa1a370dc8a1748', '5ecf33351bded411ef149f66f577b94d9483a0b1cb3127d5be5588227396904b', 4),
('imp-67054d03e5a5b011', 'chao-trung-ga-hanh-la-gung-am-bung', 79, 'Cháo trứng gà hành lá gừng ấm bụng', 'Cháo trắng ninh nhừ sánh mịn quyện vân trứng gà béo mượt, thêm gừng thái chỉ và hành lá thơm ấm', 'Bát cháo trứng gà nóng hổi với hạt gạo tẻ nấu nhừ sánh quyện, vân trứng gà mềm mịn không tanh, nổi bật hương cay ấm dịu của gừng tươi thái chỉ, hành lá xanh mát và chút dầu mè.', 'Múc cháo nóng sôi trực tiếp lên bát đã lót hành lá và gừng thái chỉ, nhỏ vài giọt dầu mè thơm và rắc tiêu đen xay rồi dùng ngay.', 'Cháo trứng ngon nhất khi nấu tới đâu ăn nóng tới đó. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đun nóng lại trên lửa nhỏ cùng chút nước sôi.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 5, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Cháo trứng","Ăn sáng","Dưới 20 phút","Dễ tiêu","Ấm bụng"]', '["breakfast","dinner"]', '["boil","simmer"]', '["egg","fish","sesame"]', 276, 275.6, 1153, 9.6, 6.9, 1.8, 42.6, 1.2, 0.9, 1353, 3.38, '["USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647"]', '82bdf026928964ed652d9f9571899a34b05b413a19bcdaa3e6f245406a6378ca', '4264d139701e4ca8ea91902a80971094b56c5a4026b263ad314e70912330e76e', 4),
('imp-e375595daced53af', 'lau-bo-nhung-dua-chua-thanh', 80, 'Lẩu bò nhúng dứa chua thanh', 'Nước lẩu ngọt thanh từ nước dừa tươi và dứa chín, thơm sả hành phi, nhúng thịt thăn bò thái mỏng chín tới cuốn bánh tráng chấm mắm nêm', 'Lẩu bò nhúng dứa chua thanh mang phong vị phóng khoáng của ẩm thực Nam Bộ. Nước dùng kết hợp nước dừa tươi ngọt dịu, dứa chín, cà chua và chút giấm gạo tạo vị chua thanh rất dễ chịu, dùng nhúng thịt thăn bò thái mỏng cuốn cùng bánh tráng, rau sống và chấm mắm nêm đậm đà.', 'Bày đĩa thịt thăn bò thái mỏng, bánh tráng, bún tươi, rau muống, xà lách và chén mắm nêm dứa băm tỏi ớt quanh nồi lẩu sôi; nhúng bò chín tái 15–20 giây rồi cuốn ăn nóng.', 'Thịt bò tươi chưa nhúng giữ trong ngăn mát tối đa 24 giờ; phần nước lẩu còn dư đun sôi lại 3 phút trước khi dùng tiếp, không để thịt bò chín ngâm qua đêm trong nồi.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Bò nhúng","Dứa chín","Nam Bộ","Cuốn bánh tráng"]', '["lunch","dinner"]', '["simmer","boil","assemble"]', '["beef","fish"]', 796, 796.2, 3331, 41.4, 21.6, 7.3, 109.9, 7.7, 19.9, 1680, 4.2, '["NIN VN Fresh Bun Ref","USDA FDC 168573","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169247","USDA FDC 169378","USDA FDC 170000","USDA FDC 170106","USDA FDC 170174","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC Rice Paper Ref","USDA FDC Sucrose Ref","VN Mam Nem Ref"]', '97f842e02cd37690116aade03a0feb390a824ccb8bb0adc06e747b12d983743c', '6ca07cd11d4bbe29abf089c5fd460da4893a0731cbaf4a8d84fe85b5dbd6bd61', 4),
('imp-9b4ea97916a44e67', 'canh-rau-muong-nau-tom-thanh-mat', 81, 'Canh rau muống nấu tôm thanh mát', 'Rau muống xanh mướt giòn ngon hòa cùng vị ngọt đậm của tôm tươi giã dập, món canh thanh nhiệt nhanh gọn kiểu miền Bắc', 'Món canh mùa hè thanh mát đậm chất cơm nhà Bắc Bộ với từng cọng rau muống xanh giòn, nước dùng trong ngọt thanh vị tôm tươi giã nhuyễn và mùi thơm dịu nhẹ của hành tím phi.', 'Dọn canh nóng vào tô lớn, có thể vắt thêm vài giọt chanh tươi khi dùng hoặc ăn kèm cà pháo muối, cơm trắng và món mặn kho tiêu.', 'Canh rau muống nên dùng hết ngay trong bữa để giữ màu xanh và độ giòn của rau; không khuyến khích đun lại nhiều lần vì rau dễ chuyển màu thẫm.', 'vietnamese', 'mon_canh', 'bac', 'easy', 12, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Dưới 20 phút","Thanh mát","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 103, 103.1, 431, 12.9, 3.8, 0.6, 6.1, 2.4, 2.3, 1238, 3.1, '["USDA FDC 169378","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '50f66046d1e252ea6781d0e0f2faecd69622c94c5c606939b51b600bc49e3776', '487b988233f9fcfbb50fed836f354f6d80e660dc599db6dfbe3efd3520a1de61', 4),
('imp-6d7fc503ade5df6e', 'thit-ba-chi-xao-sa-ot-kieu-mien-trung', 82, 'Thịt ba chỉ xào sả ớt kiểu miền Trung', 'Thịt ba chỉ thái mỏng áp chảo xém cạnh vàng ươm, quyện sả ớt băm thơm nồng và nước mắm mặn ngọt cực đưa cơm', 'Thịt ba chỉ xào sả ớt kiểu miền Trung hấp dẫn với phần thịt ba chỉ săn giòn xém cạnh không hề ngấy mỡ, thấm đẫm hương thơm nồng nàn của sả băm, vị cay bùng nổ từ ớt tươi và mặn ngọt hài hòa của nước mắm ngon.', 'Gắp thịt ba chỉ xào sả ớt ra đĩa, rắc hành lá và tiêu đen xay lên trên; ăn nóng kèm cơm trắng dẻo và rau luộc hoặc dưa leo thái lát.', 'Món mặn này bảo quản được trong hộp kín ngăn mát tủ lạnh 2–3 ngày; khi ăn chỉ cần đảo nóng lại trên chảo khô ở lửa vừa khoảng 2 phút.', 'vietnamese', 'mon_xao', 'trung', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt heo","Miền Trung","Cay nồng","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["fish","pork"]', 635, 634.7, 2655, 11.7, 59.7, 21.4, 13.1, 0.5, 3.6, 785, 1.96, '["USDA FDC 167820","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","VN/Asian Seasoning Powder Avg"]', '63340daf71353016cc681651a99ae080431bdcc8c15274757c2ddd812413b2fa', 'fff27227d4391a9de0a7f603f0d348d91009b02daf5f4a6efed946657862092d', 4),
('imp-364497296cfcf033', 'muc-nhoi-thit-hap-gung-hanh', 83, 'Mực nhồi thịt hấp gừng hành', 'Mực ống tươi nhồi đầy thịt heo xay trộn nấm hương thơm bùi, hấp chín mềm cùng gừng sợi và hành lá chấm muối tiêu chanh', 'Những khoanh mực ống trắng giòn ôm trọn phần nhân thịt heo xay dẻo ngọt quyện hương nấm hương, hành tím và gừng thơm nồng; món hấp thanh nhẹ nhưng đậm đà, đẹp mắt cho mâm cơm gia đình lẫn tiệc đãi khách.', 'Cắt mực nhồi thịt thành khoanh dày khoảng 1,5 cm xếp xen lớp ra đĩa, trang trí hành lá và gừng sợi; ăn nóng chấm cùng muối tiêu chanh hoặc nước mắm ớt.', 'Mực nhồi thịt đã hấp bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi ăn hấp lại 5–6 phút cho nhân thịt nóng đều mà vỏ mực không bị dai.', 'vietnamese', 'mon_hap_luoc', 'trung', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Hải sản","Đãi khách","Thanh đạm","Miền Trung"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","pork","squid"]', 297, 297.1, 1243, 28.4, 14.9, 5.3, 11.5, 1.2, 2, 1112, 2.78, '["USDA FDC 167902","USDA FDC 168155","USDA FDC 168436","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '22ba22fae19d88be2589b4bf28bff3bd07cbb502fbc17ecf507ea5e8c6c28783', 'a4d5fcb658c1edf506484e10c9679dc6d5bde4e3549da2fcfe4e72435a2c6e55', 4),
('imp-806780abda4b5205', 'com-chien-dua-tom-hai-san', 84, 'Cơm chiên dứa tôm hải sản', 'Cơm chiên vàng ươm mùi cà ri nhẹ quyện tôm mực giòn ngọt, dứa chín chua dịu và hạt điều rang bùi', 'Món cơm chiên dứa hải sản Nam Bộ rực rỡ sắc màu với từng hạt cơm tơi vàng ươm hương bột cà ri dịu, tôm tươi và mực giòn ngọt, dứa chín mọng nước cân bằng vị cùng hạt điều rang bùi béo.', 'Có thể múc cơm chiên vào lòng nửa trái dứa khoét rỗng để tăng hương thơm và vẻ bắt mắt; rắc hành lá, tiêu xay và hạt điều rang rồi ăn nóng kèm xì dầu ớt.', 'Ngon nhất khi ăn nóng ngay sau khi chiên để hạt điều giòn và hải sản không bị dai. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng nhanh trên chảo lửa vừa.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Hải sản","Nam Bộ","Ăn sáng","Dứa thơm"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["cashew","crustaceans","egg","fish","molluscs","shrimp","squid","tree_nuts"]', 544, 543.8, 2275, 28.3, 15.7, 3.1, 73.1, 4.2, 11.7, 986, 2.47, '["USDA FDC 168878","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170162","USDA FDC 170393","USDA FDC 170499","USDA FDC 170924","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 174223","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '9d66ac84afccb043c6748e238ef4147f94fd4d229ab1ea0cd321aa182402b368', '97bb44c0f21c43c290dd68d7ac3b50def40357e028027d0813373a09bd8eaa93', 4),
('imp-a48b19224e397cea', 'com-bo-hanh-tay-gyudon-kieu-nhat', 85, 'Cơm bò hành tây Gyudon kiểu Nhật', 'Thịt bò thái mỏng mềm ngọt quyện hành tây om trong nước dùng dashi, sake và xì dầu đậm đà, phủ trên tô cơm Nhật dẻo nóng', 'Gyudon là món cơm bò quốc dân của Nhật Bản với những lát thịt bò có vân mỡ mỏng tang được om nhanh cùng hành tây thái múi trong sốt xì dầu, rượu sake, mirin và dashi thanh ngọt.', 'Xới cơm trắng nóng ra tô sâu lòng, gắp thịt bò và hành tây phủ kín mặt cơm, rưới thêm vài muỗng nước sốt om rồi rắc hành lá thái khoanh; có thể ăn kèm trứng lòng đào hoặc gừng hồng muối.', 'Phần thịt bò và nước sốt nguội có thể cho vào hộp kín bảo quản tủ mát tối đa 2 ngày; khi dùng hâm nóng trên bếp lửa nhỏ 2–3 phút rồi mới chan lên cơm nóng.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cơm donburi","Thịt bò","Nhanh gọn","Bữa trưa"]', '["lunch","dinner"]', '["simmer"]', '["beef","egg","fish","soybean","wheat"]', 638, 637.6, 2668, 39.3, 18.2, 6.7, 70.3, 2.3, 12.8, 1467, 3.67, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168878","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 171287","USDA FDC 174277"]', 'a84f0f142a805de472824bc5f9732bb465e6d53af8cb4441df8c4d10b0c83c6c', '73737099a5b243548474a25d21553695e4b6dfc47f0f7e99b38b8bd043a4b123', 4),
('imp-79819e1b0c75f4da', 'mi-udon-xao-thit-heo-bap-cai-yaki-udon', 86, 'Mì Udon xào thịt ba chỉ bắp cải Yaki Udon', 'Sợi mì Udon trắng tròn dai mềm xào lửa lớn cùng thịt ba chỉ xém cạnh, bắp cải giòn ngọt, cà rốt và nấm hương đậm vị xì dầu Nhật', 'Yaki Udon là món mì xào trứ danh của ẩm thực đường phố Nhật Bản với sợi mì udon dày mềm dai quyện vị béo thơm của thịt ba chỉ, rau củ tươi giòn và nước sốt xì dầu pha rượu mirin, sake cùng cá bào katsuobushi.', 'Bày mì Udon xào nóng hổi ra đĩa sâu lòng, rắc ngay cá bào khô Katsuobushi để từng lát cá múa nhẹ theo hơi nóng và thưởng thức liền tay.', 'Mì ngon nhất khi ăn nóng ngay sau khi xào; phần dư có thể cất hộp kín tủ lạnh tối đa 2 ngày, khi ăn xào lại trên chảo lửa vừa với 1 muỗng canh nước lọc để sợi mì mềm tơi trở lại.', 'japanese', 'mon_xao', NULL, 'easy', 12, 18, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Mì xào","Yaki Udon","Thịt ba chỉ","Bữa tối"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["fish","pork","soybean","wheat"]', 779, 778.5, 3257, 18.6, 50.2, 16.7, 59.7, 6.6, 8.8, 1474, 3.69, '["MEXT Boiled/Fresh Udon","MEXT Hon-Mirin 16031","MEXT Katsuobushi 10099","MEXT Sake 16021","USDA FDC 167820","USDA FDC 169251","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '0171afac52ea4477abebed5a7679929fe4dee43327ee2ffbc64c100965c37574', '13fd627ec21a15b26423d315c7ff1e7308790596b211c5e12beecf8402785dc6', 4),
('imp-ac255bcc36d1324e', 'ca-hoi-ap-chao-sot-teriyaki-bong-dep', 87, 'Cá hồi áp chảo sốt Teriyaki kiểu Nhật', 'Phi lê cá hồi còn da áp chảo giòn rụm, thịt cá mềm mọng ẩm quyện lớp sốt Teriyaki sánh bóng đậm đà hương bơ, gừng tỏi', 'Cá hồi phi lê còn da được phủ nhẹ lớp bột mì giữ trọn nước ngọt bên trong, áp chảo mặt da giòn vàng với bơ lạt rồi rim nhanh trong sốt Teriyaki tự pha từ nước tương Nhật, rượu mirin, sake và đường.', 'Xếp từng miếng cá hồi ra đĩa với mặt da giòn quay lên trên, rưới phần sốt Teriyaki sánh bóng còn lại trong chảo, rắc hành lá thái nhỏ và dọn kèm cơm trắng nóng cùng bông cải xanh luộc.', 'Phần cá thừa bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi ăn làm nóng nhanh trong chảo lửa nhỏ có thêm 1 muỗng canh nước hoặc quay lò vi sóng 1 phút.', 'japanese', 'mon_chien', NULL, 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cá hồi","Teriyaki","Áp chảo","Bổ dưỡng"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["fish","milk","salmon","soybean","wheat"]', 468, 468, 1958, 32.9, 27.8, 7.9, 15.9, 0.5, 9.7, 1258, 3.15, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169761","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175167"]', 'c5bcbee07e09ace8f3444007688b69f58b40baee2e0231eacf872eb27cb9bca5', '045a8c482be0a614ac650c3c134a74b9934c17b2c6367ff84e1be41275a4a459', 4),
('imp-bb07db73fb381724', 'dau-phu-lanh-hiyayakko-gung-hanh', 88, 'Đậu phụ non lạnh Hiyayakko gừng hành', 'Đậu phụ non ướp lạnh mềm tan trong miệng, phủ gừng tươi mài nhuyễn, hành lá và cá bào, rưới xì dầu Nhật quyện dầu mè thanh mát', 'Hiyayakko là món đậu phụ lạnh truyền thống ngày hè của Nhật Bản, giữ trọn vị béo mát nguyên bản của đậu phụ non kết hợp cùng gừng mài cay ấm, hành lá giòn thơm và nước tương pha dầu mè thanh dịu.', 'Dọn lạnh ngay sau khi rưới nước tương lên đậu phụ; dùng làm món khai vị giải nhiệt hoặc ăn kèm cơm trắng và cá nướng.', 'Món ăn dùng lạnh ngay trong ngày để giữ độ tươi mịn của đậu phụ non; không hâm nóng hay cấp đông vì sẽ làm đậu bị rỗ xốp.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 1, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Khai vị","Không cần nấu","Đậu phụ","Thanh mát"]', '["lunch","dinner"]', '["assemble"]', '["fish","sesame","soybean","wheat"]', 155, 154.8, 648, 12.1, 8.5, 1.2, 8.2, 1.1, 1.8, 718, 1.79, '["MEXT Katsuobushi 10099","USDA FDC 168456","USDA FDC 169231","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 172476","USDA FDC 174277"]', 'ef1b6ae09d334a06363aa0a518c6383d16eb9318e2965d3568455f6d3bd50dc5', '5be84c00e33fa803659f68ba420bb3b5520deabb9fb2cd30189802e030248523', 4),
('imp-a9398d96945ba6f7', 'canh-kim-chi-dau-phu-thit-ba-chi-kimchi-jjigae', 89, 'Canh kim chi đậu phụ thịt ba chỉ (Kimchi Jjigae)', 'Nồi canh Kimchi Jjigae sôi sục đậm đà từ kim chi cải thảo ủ chua, thịt ba chỉ béo mềm, nấm đùi gà và đậu phụ trắng thanh mát', 'Canh kim chi đậu phụ thịt ba chỉ (Kimchi Jjigae) là món canh hầm quốc dân xứ Hàn với nước dùng đỏ rực sóng sánh vị chua thanh từ kim chi ủ kỹ, béo ngọt từ thịt ba chỉ xào săn và mềm mịn tan nhẹ của từng miếng đậu phụ.', 'Dọn canh trong nồi đất giữ nhiệt khi còn sôi lăn tăn, rắc thêm hành lá xanh và ăn kèm cơm trắng nóng hổi cùng rong biển khô.', 'Canh kim chi để qua ngày càng thấm đậm vị; bảo quản hộp kín trong ngăn mát tối đa 3 ngày và đun sôi kỹ trên lửa vừa 5 phút trước khi dùng.', 'korean', 'mon_canh', NULL, 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Kim chi","Ấm bụng","Cay đậm"]', '["lunch","dinner"]', '["simmer","stir_fry"]', '["fish","pork","sesame","soybean","wheat"]', 445, 444.8, 1861, 14.8, 36.3, 11.9, 16.6, 4.1, 7.8, 1566, 3.91, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","MEXT Hon-Mirin 16031","USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277"]', '0a8dc85e316cfc8b5ea740cecc5c37a0c80b26f7c009715e776dc9b73fd09721', '07897b85ecdf2f8d832f733a27eef616ac6a62509788cc877a2f11a0d6cdc69d', 4),
('imp-af8a9cdb17d5e9fd', 'bo-xao-bulgogi-hanh-tay-ca-rot', 90, 'Bò xào Bulgogi hành tây cà rốt', 'Thịt bò thăn thái mỏng ướp xì dầu, tỏi gừng và đường nâu mềm mọng, xào lửa lớn thơm lừng cùng hành tây giòn ngọt và cà rốt', 'Bò xào Bulgogi hành tây cà rốt là món mặn trứ danh của ẩm thực Hàn Quốc với từng lát thịt bò thăn mềm mọng thấm gia vị mặn ngọt hài hòa từ nước tương, đường nâu, rượu ngọt Mirin và dầu mè rang, xào cùng hành tây cà rốt giòn thanh.', 'Dọn bò Bulgogi nóng ra đĩa, rắc thêm hạt mè trắng rang và hành lá xanh; ăn kèm cơm trắng nóng hoặc cuốn lá xà lách chấm tương đậu Hàn.', 'Bảo quản thịt bò đã xào trong hộp kín ngăn mát tối đa 2 ngày; hâm nhanh trên chảo nóng với lửa vừa 2–3 phút, tránh đun quá lâu khiến thịt bò bị khô dai.', 'korean', 'mon_xao', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món xào","Thịt bò","Bulgogi","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","sesame","soybean","wheat"]', 428, 427.6, 1790, 31.5, 25.1, 7.2, 17.9, 1.9, 11.8, 874, 2.19, '["MEXT Hon-Mirin 16031","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174277"]', 'dc3c3114bc763283bb36858331bcccdcfde5fcea55d124619f59b58e9a4d27aa', 'f78f0306f368694d76535fd7279fd60a19526cb534e96ad99b35820c391b5378', 4),
('imp-d3d0c59e0cfa845d', 'banh-kim-chi-chien-kimchi-jeon-gion-rum', 91, 'Bánh kim chi chiên giòn (Kimchi Jeon)', 'Bánh xèo kim chi cải thảo chiên áp chảo vàng rụm hai mặt, viền giòn tan kết hợp nước chấm xì dầu giấm gạo chua ngọt thanh dịu', 'Bánh kim chi chiên giòn (Kimchi Jeon) là món bánh dân dã nhưng cực kỳ bắt miệng của Hàn Quốc với lớp bột pha nước lạnh giòn rụm bên ngoài, bên trong đậm vị chua cay của kim chi cải thảo chín, hành tây và hành lá thơm nồng.', 'Cắt bánh thành từng miếng tam giác vừa ăn khi còn nóng giòn, chấm kèm chén nước tương pha giấm gạo và hạt mè trắng rang.', 'Nên thưởng thức ngay khi vừa chiên xong để giữ độ giòn. Nếu còn dư, bọc kín cất ngăn mát tối đa 24 giờ và áp chảo lại trên chảo không dầu ở lửa vừa 3–4 phút cho giòn lại.', 'korean', 'mon_chien', NULL, 'easy', 10, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món chiên","Kim chi","Ăn vặt","Giòn rụm"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["egg","sesame","soybean","wheat"]', 512, 512.2, 2143, 12.8, 19.8, 3.3, 70.6, 4.7, 3.9, 1134, 2.84, '["Korean Chili Flake Ref","USDA FDC 169655","USDA FDC 169698","USDA FDC 169761","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 171287","USDA FDC 171413","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', 'ba1dd3f2abbc5a1436721aefd4fc1807c0c596d67cc4dbefeb27841548f535be', '40073301c2b41c95bf8952a73bd33ff5bc68950a3cb369d99dac7fb8a44af743', 4),
('imp-262caf09e6f38c59', 'bong-cai-xanh-xao-toi-kieu-quang-dong', 92, 'Bông cải xanh xào tỏi kiểu Quảng Đông', 'Bông cải xanh chần nhanh giữ màu xanh ngọc giòn ngọt, xào lửa lớn cùng tỏi gừng thơm lừng và sốt xì dầu sánh bóng', 'Bông cải xanh xào tỏi kiểu Quảng Đông giữ trọn độ giòn ngọt tự nhiên và màu xanh mướt nhờ kỹ thuật chần nước sôi trước khi xào nhanh trên lửa lớn cùng tỏi băm, gừng thơm và lớp sốt xì dầu sánh nhẹ.', 'Bày ngay ra đĩa khi vừa tắt bếp, dùng nóng làm món rau ăn kèm các món kho, món chiên trong bữa cơm gia đình.', 'Món rau xào nên ăn hết trong bữa để giữ độ giòn xanh; nếu bảo quản tủ mát tối đa 24 giờ, làm nóng nhanh trên chảo nóng trong 1–2 phút.', 'chinese', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Rau xanh","Xào tỏi","Thanh nhẹ"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["sesame","soybean","wheat"]', 142, 141.7, 593, 4.8, 8.6, 1.2, 14.2, 3.5, 3.7, 731, 1.83, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170379","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '554becbc09c4e21bdb4394fea115bdc8b96e50683bd92f8583a1a05b9b27bd87', '34535a9e60e495fb8e1cfc1efd2e6b854111b536c059879e587ee76d3e0e6c92', 4),
('imp-352999f711c710d9', 'ga-xao-gung-hanh-kieu-quang-dong', 93, 'Gà xào gừng hành kiểu Quảng Đông', 'Thịt đùi gà tẩm bột bắp áp chảo vàng xém, xào nhanh với gừng lát thơm nồng, hành tím, rượu Thiệu Hưng và sốt dầu hào sánh đậm', 'Gà xào gừng hành kiểu Quảng Đông sử dụng thịt đùi gà lọc xương ướp kỹ thuật giữ ẩm, áp chảo xém thơm rồi quyện cùng hương gừng già cay ấm, hành lá giòn ngọt và nước sốt xì dầu dầu hào sánh óng.', 'Dọn nóng ra đĩa cùng cơm trắng dẻo thơm và một đĩa rau cải thìa chần hoặc xào tỏi thanh nhẹ.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa vừa với 1–2 muỗng canh nước lọc hoặc nước dùng gà trong 3 phút.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Thịt gà","Gừng hành","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["chicken","molluscs","sesame","soybean","wheat"]', 448, 448.1, 1876, 35, 25.2, 6, 16.3, 1.4, 4, 1326, 3.32, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 172883","USDA FDC 173468","USDA FDC 174277"]', '2a46ce996a47f75e90f4a61faa02b5278ee886521465f0e5d2083b824a704869', '24217c294b834356e1472d5afbcf02b5df32060e803f2379326d83be5b218794', 4),
('imp-b3f99919ea9f17f8', 'canh-bi-dao-thit-bam-kieu-hoa', 94, 'Canh bí đao thịt bằm viên kiểu Hoa', 'Nước dùng gà thanh ngọt ninh cùng bí đao trong mướt và những viên thịt heo quết tay dai giòn thơm mùi gừng hành', 'Canh bí đao thịt bằm viên kiểu Hoa mang vị thanh tao, nước dùng trong ngọt từ nước dùng gà hòa quyện bí đao mềm mọng và viên thịt heo quết một chiều dai ngọt tự nhiên.', 'Múc canh ra tô lớn khi còn nóng hổi, rắc thêm lá hành xanh, ngò rí và chút tiêu trắng xay; dùng kèm cơm trắng và các món mặn.', 'Ngon nhất khi dùng trong ngày để bí đao không bị bở. Nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhẹ lại trên lửa vừa trong 3–5 phút trước khi dùng.', 'chinese', 'mon_canh', NULL, 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thanh mát","Trung Hoa","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","pork","sesame","soybean","wheat"]', 296, 295.7, 1237, 17.3, 21.3, 6.9, 7.5, 3.9, 3, 1481, 3.7, '["Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169214","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '86156f50b6791659643318468b57950c2eabb8586584821eadee63a4fabfa2ca', 'fb64d6cadd97a28f86ff9ab80ac32c21425ead3655ecd384baf2462c6b598ed9', 4),
('imp-b6dae711698259d6', 'canh-tom-chua-cay-tom-yum-kieu-thai', 95, 'Canh tôm chua cay Tom Yum kiểu Thái', 'Nước dùng tôm ngọt thanh nấu cùng sả, riềng, lá chanh Thái và nấm tươi, hòa quyện vị chua thanh của chanh và cay ấm của sốt Tom Yum', 'Tom Yum Goong là món canh quốc hồn quốc túy của Thái Lan với nước dùng chiết xuất từ vỏ đầu tôm phi thơm cùng bộ ba thảo mộc sả, riềng, lá chanh Kaffir và vị chua cay bừng vị.', 'Múc canh Tom Yum nóng hổi ra tô lớn, rắc ngò rí thái nhỏ lên trên, ăn kèm cơm trắng gạo lài hoặc dùng làm món canh khai vị ấm bụng.', 'Canh hải sản ngon nhất khi ăn ngay; nếu cần bảo quản, để nguội và cất ngăn mát trong 24 giờ, khi hâm lại chỉ đun nóng vừa tới để tôm không bị dai.', 'thai', 'mon_canh', NULL, 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Tom Yum","Chua cay","Hải sản"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 171, 171.4, 717, 20.7, 5.4, 0.8, 11.8, 2.4, 6.4, 1462, 3.65, '["Citrus Leaf Culinary Ref","Thai Tom Yum Paste Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169251","USDA FDC 169655","USDA FDC 169997","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179"]', 'c8144fb55f1a9758164d6c7abd8f882e39ce9c663e87b112b22300eeab82a659', '449eaf4ba0ba8808cf8fb74f42dfd9d45dc936de49ec71c9994591c79d713c9f', 4),
('imp-f729957329cd75f5', 'mi-xao-pad-thai-tom-gia-do', 96, 'Mì xào Pad Thai tôm giá đỗ', 'Bánh phở gạo mềm dai áo đẫm sốt me thốt nốt chua ngọt mặn mà, xào lửa lớn cùng tôm tươi, đậu phụ, trứng tơi và đậu phộng giòn bùi', 'Pad Thai chuẩn vị với sự hòa quyện tinh tế giữa sợi bánh phở gạo dai mềm, sốt me chua ngọt nấu từ đường thốt nốt, tôm áp chảo săn ngọt, đậu phụ chiên vàng, trứng gà đánh tơi cùng giá đỗ và hẹ tươi.', 'Gắp Pad Thai nóng ra đĩa, xếp tôm áp chảo lên trên, rắc đậu phộng rang giã dập và ớt vảy khô; dọn kèm giá sống, hẹ tươi và múi chanh để vắt trực tiếp khi ăn.', 'Pad Thai ngon nhất khi thưởng thức ngay lúc vừa xào xong; nếu dư có thể cất ngăn mát tối đa 24 giờ và xào nóng lại trên chảo với 1 muỗng canh nước lọc để sợi mì tơi mềm.', 'thai', 'mon_xao', NULL, 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Thai","Mì xào","Hải sản","Chua ngọt"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","peanut","shrimp","soybean"]', 691, 691.3, 2893, 38.1, 24.5, 4.1, 83.1, 5.8, 24.4, 1425, 3.56, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169745","USDA FDC 169918","USDA FDC 169963","USDA FDC 169994","USDA FDC 170499","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 172475","USDA FDC 173647","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', '3552f74b93350768169de073d22ec4f964a3bec47fa2da6e7fb70790f1d3b453', '53c8c3cac646056883acf6c09e3a58d1df92608f2b9991a1260afaed5a13bb81', 4),
('imp-04d0b94d17ce080c', 'ga-xao-gung-nam-kieu-thai-gai-pad-khing', 97, 'Gà xào gừng nấm kiểu Thái (Gai Pad Khing)', 'Ức gà thái lát mềm ngọt xào lửa lớn cùng gừng non thái sợi chỉ, nấm hương tươi và hành tây, thấm đẫm sốt dầu hào xì dầu thơm nồng', 'Gai Pad Khing là món xào gia đình thanh đạm nhưng rất bắt cơm của Thái Lan, kết hợp thịt ức gà mềm mọng với hương cay ấm của gừng tươi thái sợi chỉ, vị ngọt tự nhiên từ nấm hương và hành tây giòn nhẹ.', 'Múc gà xào gừng nấm nóng hổi ra đĩa sâu lòng, rắc chút tiêu nếu thích và dọn ăn ngay với cơm trắng dẻo thơm.', 'Nên dùng nóng ngay để hành tây và gừng giữ độ giòn; nếu bảo quản ngăn mát tối đa 2 ngày, hâm nóng nhanh trên chảo lửa vừa với chút nước lọc để sốt bóng trở lại.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món xào","Ức gà","Gừng nấm","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish","molluscs","soybean","wheat"]', 272, 272.2, 1139, 32, 9.3, 1.6, 14.7, 2.3, 5.5, 987, 2.47, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 171477","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277"]', '71b2d6e0501083f7d3704b14a2647077f67cd93a274cb437e1adfb2a04bf2a4e', '900b8a16362866947ee6225801f193c98449f98d36e751b8641fa426ad67e531', 4),
('imp-b01569fd0df22f66', 'mi-y-aglio-e-olio-toi-ot-dau-olive', 98, 'Mì Ý Aglio e Olio tỏi ớt dầu ô liu', 'Món mì Ý tối giản trứ danh với sợi Spaghetti bóng mượt nhũ tương dầu ô liu nguyên chất, tỏi thái lát vàng thơm và ớt sừng cay dịu', 'Mì Ý Aglio e Olio là món mì đêm khuya kinh điển của người Ý chỉ dùng những nguyên liệu mộc mạc nhất: tỏi lát phi vàng dịu trong dầu ô liu nguyên chất, chút ớt sừng cay nhẹ và nước luộc mì giàu tinh bột tạo lớp sốt óng mượt.', 'Chia mì ra đĩa sâu lòng đã làm ấm, rưới phần dầu tỏi ớt còn lại trong chảo và rắc thêm ngò tây tươi băm nhuyễn nếu thích, dùng nóng ngay.', 'Món mì trộn dầu nhũ tương ngon nhất khi thưởng thức ngay lúc vừa chế biến; nếu còn dư nên bảo quản ngăn mát tối đa 1 ngày và đảo nhanh trên chảo cùng chút nước ấm.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Aglio e Olio","Dưới 30 phút","Tối giản"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["wheat"]', 483, 483.3, 2022, 12.1, 17.4, 2.5, 69, 3.1, 2.6, 473, 1.18, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'ebfe0610823914364f6694fa21c115b70b5be262243085bd4c2e55e5db471287', '3b3b6eb8994c62d2d40174e3ba14683f8dc8636f49d2570457baf66806538964', 4),
('imp-d463228be1e6e7c0', 'com-risotto-nam-bo-pho-mai-beo-ngay', 99, 'Cơm Risotto nấm bơ phô mai béo ngậy', 'Gạo Ý Arborio rang thơm rồi om chậm cùng nước dùng rau củ nóng, nấm xào vàng xém và đánh bóng cuối bằng bơ lạt lạnh cùng phô mai Parmesan', 'Cơm Risotto nấm bơ phô mai là món cơm kem đặc trưng của miền Bắc nước Ý. Hạt gạo Arborio hạt tròn giàu tinh bột được rang nhẹ rồi om từng vá nước dùng rau củ nóng, hòa quyện vị ngọt umami từ nấm áp chảo và độ béo mịn của bơ lạnh, phô mai Parmesan.', 'Múc cơm Risotto ra đĩa sâu lòng để giữ độ sóng sánh, xếp phần nấm xào để riêng lên mặt, rắc thêm ngò tây băm, tiêu đen xay và chút phô mai Parmesan.', 'Cơm Risotto ngon nhất khi ăn nóng ngay sau khi hoàn thiện; phần dư bảo quản ngăn mát tối đa 2 ngày, khi hâm lại thêm ít nước dùng rau củ khuấy trên lửa nhỏ.', 'italian', 'mon_kho', NULL, 'medium', 15, 30, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cơm Risotto","Nấm tươi","Bơ phô mai","Ấm bụng"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["milk","sulphites"]', 595, 594.9, 2488, 15.1, 23.2, 11, 78.8, 4.3, 5.1, 1434, 3.58, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171595","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC Arborio Rice Ref"]', '30688cfa2bfdb73a26e165321e2aa818cb26723e7e8729a877ab337e4ef4ae3b', 'c3de2c7a2cc424d1170c0b3280f1e77fef5ca16f1fbdb0611f392a26500e5305', 4),
('imp-9d575ec5c01896f0', 'mi-y-sot-kem-ca-hoi-rau-bina', 100, 'Mì Ý sốt kem cá hồi rau bina', 'Spaghetti dai mềm quyện sốt kem tươi béo ngậy cùng phi lê cá hồi áp chảo vàng thơm, rau bina xanh non và hương chanh vàng thanh mát', 'Mì Ý sốt kem cá hồi rau bina mang đến sự cân bằng tinh tế giữa phi lê cá hồi áp chảo béo ngọt, sốt kem tươi sánh mịn thơm mùi phô mai Parmesan và rau bina tươi mát cùng chút vỏ và nước cốt chanh vàng dịu nhẹ.', 'Gắp mì ra 3 đĩa sâu lòng khi còn nóng, xếp đều các miếng cá hồi lên trên, rắc thêm ngò tây tươi thái nhỏ, tiêu đen xay và chút phô mai Parmesan bào.', 'Món mì sốt kem hải sản ngon nhất khi ăn nóng ngay; nếu còn dư bảo quản hộp kín ngăn mát tối đa 24 giờ và hâm nhẹ trên chảo lửa nhỏ với chút kem tươi hoặc nước lọc.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Cá hồi","Rau bina","Sốt kem"]', '["lunch","dinner"]', '["boil","pan_fry","simmer","toss_mix"]', '["fish","milk","salmon","wheat"]', 881, 881.2, 3686, 41.5, 45.9, 20.6, 75.5, 5, 5.4, 818, 2.05, '["USDA FDC 167746","USDA FDC 168462","USDA FDC 168927","USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175167"]', '2015c780b485afef6808301caea8896920d7b82d737ecf8e84849b221c02dab2', '1eddfa104b39f9159a0a8bbab15919f5a4d2a518a7dae5ae920c994bea009c5c', 4),
('imp-810c132a4d2cd4e0', 'canh-chua-tom-dua-nam-bo', 101, 'Canh chua tôm dứa Nam Bộ', 'Nước canh chua thanh dịu từ me chín, dứa và cà chua hòa quyện tôm tươi giòn ngọt, đậu bắp, bạc hà và giá đỗ chuẩn vị miền Tây', 'Tô canh chua tôm Nam Bộ bắt mắt với sắc đỏ cà chua, vàng dứa, xanh mướt của đậu bắp, dọc mùng và vị chua thanh ngọt dịu từ nước cốt me quyện tôm tươi săn giòn.', 'Múc canh nóng ra tô lớn, rắc rau ngổ, ngò gai, hành lá và ớt thái lát lên trên; ăn kèm cơm trắng hoặc bún tươi cùng chén nước mắm ớt nguyên chất để chấm tôm.', 'Nên dùng hết trong bữa để giá đỗ và bạc hà giữ được độ giòn tươi; nếu cần bảo quản tủ mát tối đa 24 giờ, nên vớt riêng phần rau giòn và đun sôi lại phần nước canh cùng tôm.', 'vietnamese', 'mon_canh', 'nam', 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Chua ngọt","Thanh nhiệt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 213, 212.8, 891, 19.8, 5.2, 0.8, 24.6, 3.5, 16.8, 1379, 3.45, '["NIN VN Doc Mung Ref","USDA FDC 169124","USDA FDC 169230","USDA FDC 169260","USDA FDC 169655","USDA FDC 169918","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN Culinary Herb Ref","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', '50b2a618ac17be01e252b58ec7d3bba64fb8c24898a6ed92d2becf13bf3c1d45', '702862dfe6d5d4bda12efb0a0454cc459781dd55a3ee5abe2196658a466ab8a2', 4),
('imp-59015074541ba061', 'canh-kho-qua-nhoi-tom', 102, 'Canh khổ qua nhồi tôm thịt', 'Từng khoanh khổ qua xanh mềm dịu vị đắng ôm trọn nhân tôm tươi và thịt heo băm dai ngọt quyện nấm hương thơm lừng', 'Phiên bản nâng tầm của canh khổ qua nhồi truyền thống với phần nhân kết hợp thịt heo xay béo mềm và tôm tươi băm dai ngọt, điểm xuyết nấm hương thơm bùi trong nước canh thanh trong.', 'Múc các khoanh khổ qua nhồi tôm thịt vào tô lớn, chan ngập nước dùng nóng trong, rắc hành lá và chút tiêu xay; ăn kèm cơm trắng hoặc chấm cùng nước mắm ớt.', 'Mở hé vung cho canh nguội tự nhiên trước khi cất tủ mát để tránh đọng hơi nước làm canh chua; bảo quản tối đa 24 giờ và đun sôi lại kỹ trước khi dùng.', 'vietnamese', 'mon_canh', 'nam', 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Thanh nhiệt","Hải sản","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["crustaceans","fish","pork","shrimp"]', 235, 234.7, 982, 21.7, 11.3, 4.1, 13, 4.9, 4.3, 1254, 3.14, '["USDA FDC 167902","USDA FDC 168393","USDA FDC 168436","USDA FDC 169655","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'cd6a707d509ba6b034868a87d41e07d9fcb9b3445da0c291d6b82fd534736e8d', '9ca216dce2b47a369237747ce4f653b832212a6d5a81e0f4a0ba7af9265342b3', 4),
('imp-9c678f92a5cb0812', 'canh-bi-dao-tom-tuoi', 103, 'Canh bí đao nấu tôm tươi', 'Bí đao xanh non thanh mát nấu cùng tôm tươi băm ngọt dịu, nước canh trong veo nhẹ bụng cho bữa cơm ngày nóng', 'Món canh giải nhiệt nhẹ nhàng với miếng bí đao vừa chín tới giữ nguyên độ thanh ngọt, hòa quyện thịt tôm tươi băm săn mềm và hương hành tím phi dịu nhẹ.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay; dọn kèm cơm trắng và các món mặn đậm đà như thịt kho tàu hoặc cá chiên sả.', 'Dùng hết trong ngày để cảm nhận trọn vẹn độ giòn ngọt của bí đao; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại nhanh trên lửa vừa tránh làm bí nhũn.', 'vietnamese', 'mon_canh', 'nam', 'easy', 12, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Thanh mát","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 96, 95.5, 399, 10.9, 3.8, 0.6, 5.4, 3.3, 2.1, 1434, 3.59, '["USDA FDC 169214","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '2d4b6f2b25e8abe6caef7d0fd326bd951507e9b2f8a4bfd689952efa5bfbaa5b', '8008c0461ec02e4fa1449d6724e1c6a1fd2c87524a7e0ce5c92f137e3040adaa', 4),
('imp-80ce5736becc08da', 'canh-ca-chua-trung-nha-la', 104, 'Canh cà chua trứng (Canh mây)', 'Trứng gà đánh tơi tạo vân mây vàng óng bồng bềnh trong nước dùng cà chua đỏ dịu thanh mát, nấu gọn chỉ trong 15 phút', 'Món canh dân dã nhanh gọn với nước dùng chua thanh tự nhiên từ cà chua chín xào mềm, nổi bật những dải vân trứng gà mềm mịn vàng ươm và mùi thơm tươi của hành lá, ngò rí.', 'Múc canh nóng ra tô ngay khi vừa tắt bếp, rắc hành lá, ngò rí và chút tiêu xay; ăn kèm cơm trắng nóng hoặc bún đều rất ngon miệng.', 'Canh cà chua trứng ngon nhất khi dùng hết trong bữa vì trứng hâm lại dễ bị bở và tanh; nếu còn dư, đậy kín trong tủ mát tối đa 12 giờ và đun sôi lại nhanh.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 8, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Dưới 20 phút","Dễ nấu","Cơm nhà","Thanh đạm"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish"]', 145, 145, 606, 7.5, 8.9, 2.1, 9.7, 1.9, 5.9, 1389, 3.47, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '501f3757d45eeeab73b835d54059a9fa1cc5f877219322cd2c32723fa730a102', '156cddd8ff4f8343ad01a6f6b1df2f0020244c382a91427d68753f69a94a3b0d', 4),
('imp-9473faeacd64d970', 'canh-nam-ga-xe-soi', 105, 'Canh nấm đùi gà ức gà xé sợi', 'Thịt ức gà luộc mềm xé sợi ngọt thanh kết hợp nấm đùi gà giòn sần sật và cà rốt trong nước dùng gà trong veo không cần xương', 'Tô canh thanh đạm giàu đạm nhưng nhẹ bụng với nước dùng nấu trực tiếp từ thịt ức gà xào săn, nấm đùi gà xé sợi giòn ngọt tự nhiên và sắc cam tươi của cà rốt.', 'Dọn canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay; rất thích hợp ăn kèm cơm trắng hoặc dùng như món canh khai vị nhẹ nhàng.', 'Để canh nguội rồi bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 24 giờ; hâm nóng lại ở lửa vừa đến khi sôi đều trước khi dùng.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Không xương","Giàu đạm","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["chicken","fish"]', 191, 191.2, 800, 25.6, 5.2, 1, 10.7, 2.7, 4.1, 1312, 3.28, '["USDA FDC 168580","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'bd1302d5fd53c3bad546a4f837d60363fd3be8d41385db44dc256beb4aa3918f', '399c295ef3582cb1e4cedb101c701e7459e0d6eaf61c5c446bb6bcb9af103854', 4),
('imp-9ab5767266722397', 'canh-muc-ca-chua-chua-nhe', 106, 'Canh mực cà chua chua nhẹ', 'Mực ống thái khoanh giòn ngọt nấu cùng cà chua chín chua dịu và gừng thơm ấm bụng, món canh hải sản nhanh gọn cho bữa tối', 'Món canh biển thanh nhẹ dễ nấu với từng khoanh mực ống giòn sần sật, nước canh ánh đỏ cam từ cà chua xào mềm, dậy hương gừng thái sợi ấm áp và chút chanh tươi chua dịu.', 'Dọn canh nóng vào tô ngay khi mực vừa chín tới, vắt nhẹ nước cốt chanh tùy thích, rắc hành lá và tiêu xay; ăn kèm cơm trắng và chén nước mắm ớt chấm mực.', 'Canh mực ngon nhất khi dùng hết ngay trong bữa; không nên đun lại nhiều lần vì mực sẽ bị dai và tiết nước tanh.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Hải sản","Dưới 20 phút","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["fish","molluscs","squid"]', 177, 177.3, 742, 17.5, 6.1, 1.1, 13.4, 2.1, 5.8, 1431, 3.58, '["USDA FDC 168155","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '78ceb42b4a9a7fb2c5fd50eba41946dd16f7a1c0f7ac1e39a62c22d379855b70', '306798046fb51a21de059fe3037de3d6f23d9a26697e2bf70999b602de85ccb1', 4),
('imp-61eac17e8f3042a9', 'canh-su-su-bam-thit', 107, 'Canh su su nấu thịt bằm', 'Su su non giòn ngọt tự nhiên nấu cùng thịt heo băm xào tơi đậm đà, món canh mộc mạc thanh mát cho mâm cơm gia đình', 'Tô canh su su băm thịt dân dã có nước dùng ngọt trong, thịt heo băm tơi thơm mùi hành phi hòa quyện cùng từng miếng su su non chín tới giữ nguyên độ giòn ngọt mát lành.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và tiêu xay; dùng kèm cơm trắng cùng các món cá kho nghệ hoặc thịt rang sả ớt.', 'Canh su su nên ăn hết trong ngày; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại nhanh trên lửa vừa để su su không bị mềm nhũn.', 'vietnamese', 'mon_canh', 'trung', 'easy', 15, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Trung","Dễ nấu","Thanh mát","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["fish","pork"]', 204, 204.2, 854, 10.8, 15.1, 4.9, 6.8, 2.1, 2.5, 1203, 3.01, '["USDA FDC 167902","USDA FDC 169990","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'f614fbeb3f31e559cca501cf2c64e9cec0fe8401fb993d192ae6a5186608b49d', '20370ef46f6858601c425e141b855d94d0bee2d4be451dee473b5320b3fedd14', 4),
('imp-ad2b55ed85f0d109', 'canh-bap-cai-trung-cuon', 108, 'Canh bắp cải trứng cuộn', 'Bắp cải thái sợi giòn ngọt nấu cùng cà rốt và những dải trứng gà đánh tơi cuộn vàng mềm mịn trong nước dùng thanh đạm', 'Món canh gia đình thanh đạm dễ ăn với những sợi bắp cải xanh mướt giòn ngọt tự nhiên, điểm xuyết lát cà rốt cam tươi và những vân trứng gà vàng óng mềm mượt.', 'Dọn canh nóng vào tô lớn, rắc hành lá, ngò rí, vài lát ớt đỏ (nếu ăn cay) và tiêu xay; ăn kèm cơm trắng cùng thịt rim hoặc đậu phụ rán tẩm hành.', 'Món canh bắp cải trứng nên ăn hết ngay khi vừa nấu để rau còn giòn và trứng mềm thơm; tránh đun lại lâu khiến bắp cải nồng mùi.', 'vietnamese', 'mon_canh', 'bac', 'easy', 10, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Thanh đạm","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish"]', 151, 150.8, 632, 8.1, 7.7, 1.9, 13.7, 4, 7.9, 1562, 3.9, '["USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '79118e20cc1752ddbd78f1ec899ec6df774b32599c6ea4c170bcfc803b579d1d', 'cad7b6316ee97b7b61f6cccecf451356cdc533f0e8e13e54ee6aaff11fd67be0', 4),
('imp-7cfc6a2e9d8bf8a3', 'canh-rau-muong-tom-dong', 109, 'Canh rau muống nấu tôm đồng cà chua', 'Ngọn rau muống non xanh giòn nấu cùng tôm đồng giã thô ngọt nước và cà chua chín chua dịu đậm chất đồng quê Nam Bộ', 'Món canh dân dã mang hương vị đồng quê với phần nước dùng ánh đỏ cam dịu nhẹ từ cà chua xào mềm, ngọt thanh đậm vị tôm đồng giã thô cùng từng cọng rau muống xanh mướt giòn ngon.', 'Múc canh nóng ra tô lớn, dùng kèm cơm trắng nóng hổi cùng cá rô kho tộ hoặc thịt ba rọi cháy cạnh rất đưa cơm.', 'Nên dùng hết ngay trong ngày để rau muống giữ màu xanh tươi và độ giòn; tránh hâm đi hâm lại nhiều lần khiến rau ngả thẫm.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Đồng quê","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 115, 115.2, 482, 11.4, 4.9, 0.8, 8.4, 3, 3.8, 1220, 3.05, '["USDA FDC 169378","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'c8f70f5490649a04508361a38834a7190ff0db37b7909d4e6de956879fa6780e', '02d58ceea1258175631a28ec11c3b7376f6a2bea4166c60cae8792e6d9f0a889', 4),
('imp-24cdd0b61f9ed162', 'canh-cua-dong-dau-phu', 110, 'Canh riêu cua đồng đậu phụ cà chua', 'Riêu cua đồng kết mảng béo ngọt nấu cùng đậu phụ rán vàng giòn, cà chua chua thanh từ me chín và rau răm thơm lừng chuẩn vị Bắc', 'Món canh riêu cua đậu phụ đậm hương vị đồng bằng Bắc Bộ với phần nước canh chua thanh nhẹ của me và cà chua, từng miếng đậu phụ rán vàng thấm vị quyện mảng riêu cua ngọt béo và rau răm dậy mùi.', 'Múc canh nóng ra bát tô, xếp nhẹ mảng riêu cua và rắc hành phi giòn lên trên; ăn kèm cơm trắng, cà muối hoặc chan bún tươi kèm rau sống chẻ nhỏ đều rất ngon.', 'Để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 24 giờ; khi hâm lại nên đun sôi lăn tăn nhẹ nhàng tránh làm nát đậu phụ và vỡ mảng riêu cua.', 'vietnamese', 'mon_canh', 'bac', 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Cua đồng","Truyền thống","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["crab","crustaceans","fish","soybean"]', 183, 183.2, 766, 17.5, 9.2, 1.4, 9.5, 2.1, 5.3, 1521, 3.8, '["USDA FDC 169918","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', 'ba3ec0b694c9b6f3519c4010478412f99efbe8c27eb39fff22e9d98f1fe957b3', 'd3c47f99736bc95673e0e94ffac5322b30b4b30ae6adaa4b5530e1e8cf6d514a', 4),
('imp-15155ec6cc7b7713', 'ba-chi-nuong-sa-mat-ong', 111, 'Ba chỉ nướng sả mật ong', 'Thịt ba chỉ thái dải ướp sả băm, tỏi gừng và mật ong nướng vàng xém cạnh thơm lừng, ăn kèm nước mắm chua ngọt đậm vị', 'Những dải thịt ba chỉ nạc mỡ hài hòa thấm đẫm hương thơm sả băm, hành tỏi gừng và vị ngọt dịu của mật ong, nướng chín vàng ruộm xém cạnh bên ngoài mà vẫn mềm mọng bên trong.', 'Thái lát vừa ăn, vắt nhẹ chanh tươi nếu thích và dọn nóng cùng chén nước mắm chua ngọt tỏi ớt, bún tươi, rau sống hoặc bánh tráng cuốn.', 'Thịt đã nướng bọc kín bảo quản ngăn mát tối đa 2 ngày; khi ăn nướng lại bằng nồi chiên không dầu ở 180°C khoảng 4–5 phút cho nóng giòn.', 'vietnamese', 'mon_kho', 'toan_quoc', 'medium', 25, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Ba chỉ nướng","Mật ong","Sả ớt","Cuối tuần","Cuốn bánh tráng"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","pork"]', 660, 660.3, 2762, 11.4, 59.6, 21, 20.5, 0.7, 13.8, 1301, 3.25, '["USDA FDC 167820","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647"]', '5d4fa93e9ad4ad601567f3e450b6db19d04d5e3df8ba87dfa6beba1089086a56', 'ea679e4e8013caa8b81e35017469ddbf35ea3785225c41562b8223aeda4e24bc', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-363ca9ee2c5f7738', 'bo-kho-banh-mi-dam-vi', 112, 'Bò kho bánh mì đậm vị', 'Thịt nạm bò hầm mềm tan trong nước dùng dừa tươi thơm hương sả, hồi quế và màu điều đỏ cam, chấm bánh mì nóng giòn chuẩn vị Sài Gòn', 'Thịt nạm bò có gân mỡ đan xen được hầm nhừ cùng nước dừa tươi, cà rốt, sả, hoa hồi, quế thanh và màu điều đỏ cam sóng sánh, tỏa mùi thơm quyến rũ khó cưỡng.', 'Múc bò kho nóng vào tô sâu lòng, rắc húng quế, ngò gai và ớt thái lát lên trên, ăn kèm ổ bánh mì nướng giòn rụm và muối tiêu chanh.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng trên lửa nhỏ và thêm ít nước lọc nếu nước sốt quá đặc.', 'vietnamese', 'mon_kho', 'nam', 'medium', 25, 75, 5, '/frigo/illustrations/delicious-meal.png', '["Bò kho","Bánh mì","Nam Bộ","Món hầm","Ăn sáng"]', '["breakfast","lunch","dinner"]', '["braise","stir_fry","simmer"]', '["beef","fish","wheat"]', 687, 686.5, 2872, 36.4, 24.7, 9.2, 79.2, 7.6, 18.4, 1751, 4.38, '["Annatto Infused Oil Ref","Five Spice USDA Ref","MEXT Sake 16021","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169717","USDA FDC 170000","USDA FDC 170174","USDA FDC 170198","USDA FDC 170393","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171316","USDA FDC 171320","USDA FDC 172185","USDA FDC 172232","USDA FDC 172686","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', 'aaa0abd69cb130b33ff2f5592d144f3022e705db7a8a2ea94afdb2b8a4b99c2d', '3819e0fff916f637c30211acff2d794d832e715f7d6b826201e07c9bf36fd383', 4),
('imp-3ec27a2b8f5e4345', 'ga-kho-gung-ot-hiem', 113, 'Gà kho gừng ớt hiểm', 'Thịt đùi gà kho săn cùng gừng tươi thái sợi và ớt hiểm cay nồng, nước kho sánh màu cánh gián đậm đà cực kỳ đưa cơm', 'Những miếng đùi gà giữ nguyên da săn chắc thấm đẫm vị mặn ngọt hài hòa, quyện cùng hương thơm cay ấm của gừng tươi thái sợi và vị cay nồng đặc trưng từ ớt hiểm.', 'Múc gà kho ra đĩa sâu lòng, rắc hành lá cắt khúc và tiêu xay lên trên, ăn nóng với cơm trắng và dưa leo thái lát.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại trên lửa nhỏ với 1–2 muỗng canh nước ấm.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Gừng ớt","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["chicken","fish"]', 347, 346.9, 1452, 29.2, 20.4, 4.9, 10.7, 0.9, 6.6, 1474, 3.68, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647"]', '49690959195da2adcfd4f554f4c773e3e39c0e2c17eaf6ac271f46ee1b821861', '6d8d8ffc933c54550e87c00ba0ef16ecbeff49f6f3333a42dfdd06ca37ffd894', 4),
('imp-323aae415415eb28', 'tom-kho-tieu-xanh', 114, 'Tôm kho tiêu xanh', 'Tôm tươi thịt chắc kho sánh keo với tiêu xanh tươi đập dập cay tê thơm nồng, món mặn nhanh gọn cực bắt cơm', 'Tôm tươi rang săn rồi kho mở nắp với nước mắm đường và những chùm tiêu xanh tươi đập dập, mang lại vị cay tê dịu nhẹ và hương thơm tinh dầu tiêu đặc trưng miền Nam.', 'Xếp tôm cùng chùm tiêu xanh ra đĩa, rưới phần nước kho sánh bóng và rắc hành lá cắt khúc; ăn nóng với cơm trắng và rau luộc.', 'Dùng hết trong ngày để giữ độ ngọt giòn của tôm và hương thơm tươi của tiêu xanh; nếu bảo quản ngăn mát tối đa 24 giờ, hâm nhanh trên chảo lửa nhỏ.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Hải sản","Tiêu xanh","Nhanh gọn","Nam Bộ"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","shrimp"]', 203, 203.3, 851, 22.6, 7.6, 1.2, 12.5, 1.4, 7.5, 1290, 3.23, '["Green Peppercorn Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '8df46b54fc7e31187a4822b4ac23c2d80fa58ba91fac3f61f84b9d321920e19d', '819180201a427845ba7563469c1fad3e09381efa3087f98664c55e2e4806e0d8', 4),
('imp-3f1ad35e1f1ec87f', 'muc-rim-dua-mien-trung', 115, 'Mực rim dứa miền Trung', 'Mực khô nướng thơm đập mềm xé sợi rim cùng nước cốt dứa chín, tương ớt, dầu hào và mè rang đậm vị cay ngọt miền Trung', 'Đặc sản miền Trung với từng thớ mực khô nướng thơm đập mềm thấm đẫm sốt dứa chín chua ngọt quyện tương ớt cay nồng, dầu hào đậm đà và mè rang bùi béo.', 'Xếp mực rim dứa ra đĩa, rắc thêm chút tiêu xay, ăn nóng với cơm trắng kèm dưa leo thái lát hoặc nhâm nhi cùng bánh tráng nướng.', 'Để nguội hoàn toàn rồi cho vào hũ thủy tinh đậy kín, bảo quản ngăn mát tối đa 7 ngày; có thể ăn nguội trực tiếp hoặc đảo nhanh trên chảo ấm.', 'vietnamese', 'mon_kho', 'trung', 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món rim","Miền Trung","Hải sản","Mực khô","Đưa cơm"]', '["lunch","dinner"]', '["braise","grill_roast"]', '["fish","molluscs","sesame","soybean","squid","wheat"]', 372, 372.1, 1557, 50.5, 10.3, 1.7, 18.6, 1.7, 13, 1552, 3.88, '["MEXT Surume Ref","USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC Sriracha Ref"]', '122078d83d8a839c7cd8216001bdbec1a01821c8b9d387b345ad32e5767ad63c', '0524b625beac80e3f6c253accc98c11f89e79231eb080adbe39996f5c8f85acd', 4),
('imp-64e505d497388f4a', 'ca-hoi-ap-chao-toi-chanh', 116, 'Cá hồi áp chảo sốt tỏi chanh', 'Cá hồi phi lê áp chảo da giòn thịt hồng mọng nước, rưới sốt bơ tỏi chanh nước mắm chua thanh đậm đà', 'Cá hồi áp chảo sốt tỏi chanh là sự kết hợp tinh tế giữa kỹ thuật áp chảo da giòn kiểu Âu và hương vị sốt bơ tỏi chanh pha nước mắm hài hòa theo khẩu vị Việt. Miếng cá giữ được độ béo mọng đặc trưng bên trong, hòa quyện lớp sốt chua thanh thơm lừng giúp ăn không bị ngấy.', 'Dọn nóng từng miếng cá hồi ra đĩa, rưới đều sốt bơ tỏi chanh lên mặt, rắc hành lá và tiêu xay, ăn kèm cơm trắng nóng hoặc salad cà chua tươi.', 'Cá hồi ngon nhất khi ăn nóng ngay để thịt mềm mọng và da giòn; nếu bảo quản tủ mát tối đa 24 giờ, nên hâm nhẹ bằng chảo nắp kín ở lửa nhỏ 2–3 phút tránh làm khô thịt cá.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Áp chảo","Cá hồi","Nhanh gọn","Hiện đại"]', '["lunch","dinner"]', '["pan_fry"]', '["fish","milk","salmon"]', 541, 541.3, 2264, 42.6, 36.3, 9.5, 10.3, 1.6, 4.9, 1010, 2.53, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173430","USDA FDC 173468","USDA FDC 175167"]', '8a0cbe2830df3ec718a7e935fbdae9ebcb037d5c6f02c16e8eef1342df55c7ed', '4efacea3a138c24e530d8c7bc5100040028c0f5e63bbde4d9b519caf0a2b97c3', 4),
('imp-6e4c264764981b8b', 'ga-xao-sa-ot-non', 117, 'Gà xào sả ớt Nam Bộ', 'Thịt đùi gà săn mềm thấm vị mặn ngọt đậm đà cùng sả băm vàng ruộm, ớt cay nồng và hành tây giòn thơm', 'Gà xào sả ớt kiểu Nam Bộ quyến rũ với màu nâu cánh gián óng ả từ đường nâu thắng nhẹ, từng miếng thịt đùi gà mềm ngọt thấm sâu hương sả thơm nồng, vị cay kích thích của ớt hiểm và chút giòn ngọt của hành tây.', 'Múc gà xào sả ớt ra đĩa sâu lòng cùng phần nước sốt sền sệt, dùng nóng với cơm trắng và dưa leo xắt lát.', 'Có thể bảo quản trong hộp kín ngăn mát tối đa 2 ngày; hâm nóng lại trên chảo với 1–2 muỗng canh nước lọc ở lửa vừa đến khi nóng đều.', 'vietnamese', 'mon_xao', 'nam', 'easy', 20, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Nam Bộ","Cay nồng","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish"]', 396, 396, 1657, 30.6, 24.2, 5.6, 13.3, 0.7, 4.7, 1426, 3.57, '["USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 170000","USDA FDC 170106","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '95bebba763d2dc8f7ab8df85ca43e61a5a29557f4c4a250121f49edf334286d4', '7f9abe593a19b8d2e73165b38ae20c99c42ca8708ff90adc258ee364858c0a30', 4),
('imp-53760c13ec1e452b', 'tom-xao-gia-do', 118, 'Tôm xào giá đỗ thanh ngọt', 'Giá đỗ trắng mập giòn mọng xào nhanh trên lửa lớn cùng tôm tươi săn ngọt và hương hành lá thơm dịu', 'Tôm xào giá đỗ là món ăn thanh nhẹ giải ngấy cực nhanh gọn cho bữa cơm hằng ngày. Từng con tôm đỏ cam săn chắc quyện cùng cọng giá đỗ chín tới giòn tan, mọng nước ngọt tự nhiên mà không hề bị nát hay chảy nước.', 'Gắp tôm xào giá đỗ ra đĩa khi vừa tắt bếp, rắc thêm tiêu đen xay; dùng nóng ngay cùng cơm trắng và chén nước mắm ớt.', 'Món giá đỗ xào nên ăn hết ngay trong bữa để giữ độ giòn tươi và tránh giá bị chảy nước thâm sẫm.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Thanh đạm","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","fish","shrimp"]', 154, 154.4, 647, 18.1, 6.1, 0.9, 8.9, 2.1, 4.5, 1200, 3, '["USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '8907853cfd0dbee39d952ef18167bc660d1cd3c82ce605930268727753b3ccaf', '39fa681738390b5cd63a4fa030cdf3dafd52efd127f2f291325594f4938dacbf', 4),
('imp-a47ef9289f5d0136', 'ca-rot-xao-trung', 119, 'Cà rốt xào trứng gà', 'Cà rốt thái sợi mềm ngọt tự nhiên quyện cùng trứng gà đánh bông tơi vàng ươm và hương thơm dịu của ngò rí', 'Cà rốt xào trứng gà là món ăn bình dị, giàu dinh dưỡng với sợi cà rốt mềm ngọt tự nhiên ôm quyện lấy từng mảng trứng gà vàng óng béo nhẹ, thơm mùi nước mắm, tiêu xay và rau ngò rí.', 'Dọn cà rốt xào trứng ra đĩa khi còn nóng hổi, rắc thêm ngò rí và tiêu xay; ăn kèm cơm trắng hoặc kẹp bánh mì đều rất hợp.', 'Nên dùng hết ngay trong bữa để trứng giữ độ bông mềm và thơm ngon; không nên để qua đêm hoặc hâm lại nhiều lần.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Trứng","Dưới 20 phút","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","fish"]', 147, 146.6, 613, 6.6, 9.9, 2.2, 8.2, 2.2, 3.7, 624, 1.56, '["USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC Monosodium Glutamate","VN/Asian Seasoning Powder Avg"]', '5986303c355f339928d247962ef21ab22cdd836df68149766994bb2aea0546ac', '7103aa4dc5dd34c5841a1ccd7ef09ef5c08074ae771ba3d5464562ab0e0d982c', 4),
('imp-abdcd797955a6d6a', 'dau-phu-xao-ca-chua', 120, 'Đậu phụ xào cà chua', 'Đậu phụ chiên vàng giòn cạnh xào cùng sốt cà chua chín nhừ đậm đà vị mặn ngọt, món cơm nhà thanh đạm cực bắt cơm', 'Đậu phụ xào cà chua hấp dẫn với từng miếng đậu phụ ngoài vàng nhẹ, bên trong béo mềm thấm đẫm phần sốt cà chua đỏ au sóng sánh vị chua ngọt hài hòa, thơm mùi hành lá và ngò rí.', 'Trút đậu phụ xào cà chua ra đĩa sâu lòng, rưới đều nước sốt cà chua lên mặt cùng hành lá, ngò rí và tiêu xay; ăn nóng với cơm trắng rất hao cơm.', 'Bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa nhỏ cùng 1–2 muỗng canh nước lọc khoảng 3 phút cho sốt mềm sánh trở lại.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Đậu phụ","Cà chua","Tiết kiệm","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["fish","soybean"]', 245, 244.6, 1023, 14.1, 17.7, 2.6, 11.8, 3.2, 6.5, 1098, 2.75, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '6cbb8fbab240e3147be14bf4644b3f6d83e9d33c1183c28905b42fc333508385', '502958b5caf5a97d5297ed72cfecc18d660268e90247ba983c4bc0dc2fe042d1', 4),
('imp-97f26ff4abe44f9b', 'nem-ran-nhan-cua-thit', 121, 'Nem rán nhân cua thịt', 'Nem cua bể gói vuông giòn rụm hai lần lửa, nhân thịt nạc vai quyện thịt cua ngọt thanh và rau củ', 'Nem rán nhân cua thịt (nem cua bể) là đặc sản trứ danh miền duyên hải Bắc Bộ. Từng chiếc nem gói vuông vức, lớp vỏ bánh đa nem giòn tan ôm trọn phần nhân đầy đặn gồm thịt cua biển tươi, thịt nạc vai xay, nấm hương, mộc nhĩ, miến dong và các loại củ bào sợi ngọt mát.', 'Cắt nem làm đôi hoặc làm tư ngay khi còn nóng để lộ phần nhân cua thịt hấp dẫn, dọn kèm rau sống, bún tươi và chén nước mắm chanh tỏi ớt chua ngọt.', 'Nem rán sơ lần một để nguội có thể xếp hộp lót giấy nến bảo quản ngăn đá tới 3 tuần; trước khi ăn đem rán lại ở lửa vừa 4–5 phút đến khi vỏ vàng giòn rụm.', 'vietnamese', 'mon_chien', 'bac', 'hard', 40, 25, 6, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Nem cua bể","Bắc Bộ","Hải sản","Tiệc tùng"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["crab","crustaceans","egg","fish","pork"]', 549, 548.6, 2295, 25.1, 24.6, 6.8, 56.9, 5.3, 5.5, 1147, 2.87, '["USDA FDC 167902","USDA FDC 168155","USDA FDC 168436","USDA FDC 168437","USDA FDC 168482","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170072","USDA FDC 170106","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173647","USDA FDC 174208","USDA FDC Rice Paper Ref","VN/Asian Seasoning Powder Avg"]', '7c9f1e5ba65664929e959922d2542b536a7c8c1d34abbe4c28c82bef3a7a16d0', 'e0bde82b6807cc18f4c4aacc0226319e1a0da672521281f7470b947010c6352e', 4),
('imp-03cb4c492e643034', 'tom-chien-trung-mong', 122, 'Tôm chiên trứng mỏng', 'Tôm tươi xào săn xếp trên lớp trứng gà đánh bột bắp chiên mỏng vàng ươm, mềm mịn thơm hành', 'Tôm chiên trứng mỏng là món ăn đơn giản nhưng rất được lòng trẻ nhỏ và gia đình bận rộn. Tôm tươi bóc vỏ được xào nhanh cho chín đỏ rồi trải đều trên lớp trứng gà đánh cùng chút bột bắp hòa nước, chiên lửa nhỏ đậy vung để mặt trứng mềm mịn, không bị khô xác.', 'Trượt nguyên miếng trứng chiên tôm ra đĩa phẳng, cắt miếng vừa ăn và dùng nóng ngay với cơm trắng, có thể chấm thêm tương ớt hoặc nước mắm chua ngọt.', 'Món ăn ngon nhất khi vừa chiên xong còn nóng mềm; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hâm lại trên chảo chống dính lửa nhỏ có nắp đậy trong 2 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Tôm tươi","Trứng chiên","Trẻ em thích","Dưới 30 phút"]', '["lunch","dinner"]', '["pan_fry"]', '["crustaceans","egg","fish","shrimp"]', 227, 227.3, 951, 20.9, 13.8, 3, 4.8, 0.4, 0.7, 735, 1.84, '["USDA FDC 169698","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '15d45f3ab29439fe685076a6a795e1203f373111a2f2af0db38fedf5f2eae265', '5ea0e12f93d1e042278eee320903344dd19299704a62dbc01f79c1542df74e15', 4),
('imp-c4a65718d5cd4b3c', 'cha-gio-chay-nam-dau', 123, 'Chả giò chay nấm đậu', 'Vỏ bánh tráng giòn rụm chiên hai lửa, nhân đậu phụ vắt ráo quyện nấm đùi gà, đậu xanh bùi và củ sợi', 'Chả giò chay nấm đậu có lớp vỏ giòn tan không thua kém chả giò mặn nhờ bí quyết vắt ráo đậu phụ, hấp khô đậu xanh và chiên hai lần lửa. Nhân nấm đùi gà dai ngọt hòa quyện với đậu xanh bùi béo, khoai lang và củ đậu thanh mát, chấm nước mắm chay chua ngọt cực kỳ bắt vị.', 'Bày chả giò chay ra đĩa cùng rau xà lách, rau thơm các loại và bún tươi, chấm đẫm chén nước mắm chay chanh ớt có cà rốt băm giòn.', 'Chả giò chiên sơ lần một để nguội hoàn toàn có thể cấp đông trong hộp kín tới 3 tuần; khi ăn chỉ cần chiên lại ở lửa vừa 3–4 phút hoặc quay nồi chiên không dầu 180°C trong 6 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'medium', 35, 20, 5, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Món chay","Chả giò","Giòn rụm","Thanh đạm"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["soybean","wheat"]', 462, 462.1, 1934, 15.2, 15.4, 2.3, 69.5, 9, 10.2, 1037, 2.59, '["USDA FDC 168155","USDA FDC 168437","USDA FDC 168482","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170005","USDA FDC 170072","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174256","USDA FDC Rice Paper Ref","Vegetarian Fish Sauce Ref","Vegetarian Seasoning Powder Ref"]', '10dd0e29862c1e71e8a4846ce564a6f6a12d862f64f836f5da5fe5ff47898e7c', 'a1e6d87801799347ed60e0ef0b5bc404906d65760c60c307a907c9a5a2650a12', 4),
('imp-f3c2431be267b74d', 'ca-hap-dua-gung', 124, 'Cá điêu hồng hấp dứa gừng thanh mát', 'Cá điêu hồng tươi nguyên con ướp sốt mắm tương đậm đà hấp cùng dứa chín chua ngọt và gừng sợi thơm ấm', 'Cá điêu hồng tươi hấp cách thủy cùng những lát dứa chín vàng óng và gừng sợi cay nhẹ tạo nên nước hấp chua ngọt thanh tao, giúp thịt cá trắng mềm thơm ngọt mà hoàn toàn không có vị tanh.', 'Dọn nguyên đĩa cá hấp dứa gừng nóng hổi lên bàn, có thể ăn kèm cơm trắng hoặc cuốn bánh tráng cùng bún tươi, rau sống chấm nước mắm gừng.', 'Món cá hấp ngon nhất khi ăn nóng ngay trong bữa. Nếu còn dư, gỡ bỏ xương cá bảo quản ngăn mát tối đa 24 giờ và hấp lại 5 phút trước khi dùng.', 'vietnamese', 'mon_hap_luoc', 'nam', 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Cá tươi","Thanh mát","Món Nam","Đãi khách"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","sesame","soybean","wheat"]', 265, 265, 1108, 36.5, 5.7, 1.4, 16.2, 2, 9.5, 1436, 3.59, '["USDA FDC 169124","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '5cecf42e18bc24e1cd503ced7e9a0df903da078935fb429f91ce1c6e22deedd3', '7d589d8d7c3f371eb548c1aba2a3b20881758fe04fc53c555334dd512dfe839f', 4),
('imp-6118e8aa010584af', 'trung-hap-tom-chung', 125, 'Trứng hấp tôm chưng mềm mượt', 'Trứng gà lọc mịn hấp cách thủy cùng tôm tươi băm ngọt thanh, mặt trứng láng mịn như gương nhẹ bụng dễ tiêu', 'Món trứng hấp tôm chưng mềm mịn như đậu hũ non, mặt trứng bóng mượt không một vết rỗ hòa quyện vị ngọt tự nhiên của tôm tươi bóc vỏ và hương thơm dịu từ hành lá, dầu mè.', 'Dùng muỗng múc từng phần trứng hấp tôm nóng hổi ăn kèm cơm trắng, rất phù hợp cho bữa tối thanh nhẹ hoặc thực đơn trẻ nhỏ.', 'Món ăn ngon nhất khi dùng nóng ngay sau khi hấp; không nên để qua ngày vì trứng và tôm hấp lại dễ bị tách nước.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Trứng","Thanh đạm","Dễ nấu","Nhẹ bụng"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","egg","fish","sesame","shrimp"]', 146, 146, 611, 17.3, 7.4, 2.1, 2.2, 0.4, 0.7, 675, 1.69, '["USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '8b0dfbd74796209e49da7453aeae34c49d919569c130be2adadb3fe4db32522c', '651c1b527562ea400c13980e0f0fda9be64d7b2a67c73993e86b0c321242c67d', 4),
('imp-4ced29ad30507f2c', 'goi-cuon-tom-thit-rau-song', 126, 'Gỏi cuốn tôm thịt rau sống chấm mắm tỏi ớt', 'Gỏi cuốn truyền thống bánh tráng mỏng dẻo bọc tôm sú luộc, ba chỉ thái mỏng, bún tươi, giá đỗ và rau thơm chấm nước mắm chanh tỏi ớt thanh nhẹ', 'Gỏi cuốn tôm thịt rau sống mang hương vị thanh nhẹ chuẩn Nam Bộ với bánh tráng mềm dẻo ôm trọn tôm luộc đỏ tươi, thịt ba chỉ béo mềm, bún sợi nhỏ, dưa leo giòn mát, hẹ lá và ngò gai thơm dịu, chấm cùng chén nước mắm chanh tỏi ớt đậm đà.', 'Xếp gỏi cuốn ra đĩa, dọn ăn ngay kèm chén nước mắm chanh tỏi ớt pha vừa vị chua cay mặn ngọt.', 'Thưởng thức ngay sau khi cuốn để bánh tráng không bị khô cứng; nếu chưa ăn ngay, bọc từng cuốn bằng màng bọc thực phẩm giữ trong ngăn mát tối đa 4 giờ.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi cuốn","Rau sống","Nam Bộ","Nước mắm tỏi ớt","Khai vị"]', '["lunch","dinner"]', '["boil","assemble"]', '["crustaceans","fish","pork","shrimp"]', 584, 583.8, 2443, 22.8, 33.5, 12.1, 48.6, 2.4, 6.1, 1107, 2.77, '["NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169994","USDA FDC 170106","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref","VN Culinary Herb Ref"]', '551a8df5d104294b244ed2fa43129559314e5da7e63f85c73b54cb5e5bb2ae2e', '027b0156a3993310a786833d84fa008f798d5fd834e34ce9e19d2992acf58b71', 4),
('imp-3a06ac78b572f3ae', 'nom-dua-leo-tom-chua-cay', 127, 'Nộm dưa leo tôm chua cay', 'Dưa leo bỏ ruột thái lát ngâm đá giòn sần sật quyện tôm rim săn ngọt, cà rốt, rau thơm và nước trộn chanh ớt hiểm cay nồng sảng khoái', 'Nộm dưa leo tôm chua cay là món khai vị bùng vị với dưa leo và cà rốt ngâm đá giữ trọn độ giòn mát, kết hợp tôm tươi rim muối ngọt thịt và nước mắm chanh tương ớt giã tỏi ớt hiểm cay nồng, rắc lạc rang thơm bùi.', 'Gắp nộm ra đĩa, rắc đậu phộng rang giã dập lên mặt và dọn ăn ngay kèm bánh phồng tôm giòn tan.', 'Dùng ngon nhất trong vòng 30 phút sau khi trộn; nếu chưa ăn ngay, để riêng dưa leo cà rốt đã vắt ráo, tôm rim và nước trộn trong tủ lạnh.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 20, 10, 4, '/frigo/illustrations/delicious-meal.png', '["Nộm dưa leo","Tôm tươi","Chua cay","Khai vị","Mát lành"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 350, 349.9, 1465, 24.8, 7.4, 1.1, 50.2, 4.5, 19.3, 1612, 4.03, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 175179","USDA FDC Sriracha Ref","VN Banh Da Ref"]', 'ff21aa25c5a6765c36bc5d9eeaf0a246983d7f0f385ec6d6a6fd299b71c81947', '378c335561ebcd27ae665ce3c61f642cebe2748d9d327b8c9ba9912c0873b50a', 4),
('imp-21f32dccd464c605', 'pho-ga-pho-co', 128, 'Phở gà phố cổ Hà Nội', 'Nước dùng phở gà trong veo ngọt thanh từ gà ta luộc và hạt mùi rang thơm, quyện sợi bánh phở mềm dai, thịt gà xé thơm lá chanh thái chỉ', 'Phở gà phố cổ Hà Nội tinh tế với nước dùng trong vắt thơm hương hạt mùi rang, hành gừng nướng, thịt gà ta chín tới da vàng giòn ngọt mềm, điểm lá chanh thái chỉ thanh mát.', 'Xếp bánh phở và thịt gà xé vào tô, thêm đầu hành chẻ, hành tây thái mỏng, hành lá, ngò rí, lá chanh thái chỉ rồi chan nước dùng sôi nóng; ăn kèm giá đỗ, chanh tươi và ớt tươi.', 'Nước dùng và thịt gà lọc xương bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi nước dùng, trụng bánh phở mới và xếp thịt gà vào chan ngập nước sôi cho nóng.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 25, 80, 4, '/frigo/illustrations/delicious-meal.png', '["Phở gà","Phố cổ Hà Nội","Nước dùng trong","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["boil","simmer","assemble"]', '["chicken","fish"]', 728, 728, 3047, 42, 28.8, 8.2, 72.2, 3.8, 7.1, 1891, 4.73, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 169231","USDA FDC 169745","USDA FDC 169963","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170922","USDA FDC 171077","USDA FDC 171316","USDA FDC 171320","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', 'b675c4937599393368ccbf57ce5ff719712f303ffd585d8b184ea1a8ea6ed272', '9ac538c925a47779e8a23d2ff10528ada9b4b41e742ae0c25ddb966b59cd44eb', 4),
('imp-ba737c5583985a50', 'bun-bo-hue-sa-ot', 129, 'Bún bò Huế sả ớt', 'Nước dùng xương bò nạm bò ninh sả đậm đà hương mắm ruốc Huế và sa tế sả ớt đỏ gạch cay nồng, ăn kèm viên giò sống dai ngọt và rau sống', 'Bún bò Huế sả ớt phiên bản cay nồng thơm sả nổi bật với nạm bò ướp sả ớt xào săn trước khi hầm mềm, viên giò sống dai giòn, nước dùng đậm đà mắm ruốc Huế cùng chén sa tế sả ớt tự làm đỏ rực bắt mắt.', 'Xếp bún sợi to, thịt nạm bò thái lát và viên giò sống vào tô, chan ngập nước dùng nóng rực sắc điều, rắc hành lá, hành tây, rau răm rồi dọn kèm giá đỗ, chanh tươi và chén sa tế sả ớt.', 'Nước dùng, thịt nạm và sa tế sả ớt có thể bảo quản ngăn mát 2 ngày; khi ăn hâm sôi nước dùng, thả nạm bò làm nóng lại rồi chan lên bún vừa trụng.', 'vietnamese', 'mon_bun_pho', 'trung', 'hard', 35, 120, 4, '/frigo/illustrations/delicious-meal.png', '["Bún bò Huế","Sả ớt","Cay nồng","Ẩm thực miền Trung"]', '["breakfast","lunch","dinner"]', '["simmer","stir_fry","boil","assemble"]', '["beef","crustaceans","fish","pork","shrimp"]', 839, 839.3, 3512, 41.1, 41.9, 14.1, 76.3, 5.3, 10.7, 1612, 4.03, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","USDA Beef Rib / Bone Ref","USDA FDC 167902","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169963","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170198","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC Sucrose Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', 'd7f940303fbf34edb34928df8c5775f65c932997463d17788cb1f618438d4848', '33a90caed19048909422c315158a7661a138486cbdc3fd3a63473c0a94d6b938', 4),
('imp-37a39eaa1edcd2e4', 'hu-tieu-tom-thit-nam-vang', 130, 'Hủ tiếu tôm thịt Nam Vang', 'Nước lèo trong vắt ngọt thanh từ xương ống heo, tôm khô và khô mực nướng, quyện sợi hủ tiếu dai cùng tôm tươi, thịt ba chỉ, thịt băm và trứng cút', 'Tô hủ tiếu Nam Vang trứ danh đất Sài Gòn gây thương nhớ bởi nồi nước lèo trong veo ngọt dịu từ xương heo hầm củ cải trắng, tôm khô và khô mực nướng, điểm xuyết tỏi phi vàng thơm cùng thịt ba chỉ, tôm tươi, thịt băm và trứng cút.', 'Trụng hủ tiếu trộn chút dầu tỏi phi vào tô, xếp thịt ba chỉ thái lát, thịt băm xào, tôm luộc và trứng cút bổ đôi; chan nước lèo sôi nóng, rắc hẹ lá, cần tây, hành lá, tỏi phi và dọn kèm giá đỗ, rau tần ô, chanh tươi.', 'Nước lèo và các phần nhân chín bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi nước lèo, trụng lại hủ tiếu mới và làm nóng thịt tôm bằng cách nhúng nhanh qua nước dùng sôi.', 'vietnamese', 'mon_bun_pho', 'nam', 'medium', 30, 90, 4, '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu Nam Vang","Tôm thịt","Ẩm thực Nam Bộ","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["simmer","boil","stir_fry","assemble"]', '["celery","crustaceans","egg","fish","molluscs","pork","shrimp","squid"]', 833, 833.2, 3486, 37.4, 39.6, 12.3, 80.3, 4.5, 9.6, 1841, 4.6, '["MEXT Surume Ref","Pork Bone Stock Extraction Ref","USDA / Asian Dried Shrimp Ref","USDA FDC 167820","USDA FDC 167902","USDA FDC 168155","USDA FDC 168452","USDA FDC 169230","USDA FDC 169249","USDA FDC 169745","USDA FDC 169963","USDA FDC 169988","USDA FDC 169994","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172191","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', 'fe6fb9628d4dafd0f6f583d53482ed754e16daaec82aaa8e59df84e7f94ad17a', '11efacb29d63ad8cff74fb5f8576b327051a3c5470afc52974f5dd8f8ef8d397', 4),
('imp-0efa407066cdc8dd', 'bun-ca-tom-ca-chua', 131, 'Bún cá nấu dứa cà chua', 'Cá lóc ướp nghệ chiên săn nấu cùng dứa chín và cà chua tạo nước dùng chua ngọt thanh dịu, ăn kèm bún tươi và rau thơm', 'Tô bún cá nấu dứa cà chua ấm bụng với từng khúc cá lóc ướp nghệ chiên áp chảo vàng nhẹ không tanh, thấm nước dùng chua thanh tự nhiên từ cà chua chín và dứa thơm.', 'Xếp bún tươi đã trụng vào tô, đặt khúc cá lóc lên trên, chan nước dùng cà chua dứa nóng hổi rồi rắc hành lá, thì là, ngò rí và ớt tươi thái lát.', 'Nước dùng và cá chín nên tách riêng bảo quản ngăn mát tối đa 24 giờ; khi ăn đun sôi nước dùng, thả cá vào hâm nóng nhẹ 2 phút rồi chan lên bún mới trụng.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Bún cá","Cà chua","Chua thanh","Món nước"]', '["breakfast","lunch","dinner"]', '["pan_fry","simmer","boil","assemble"]', '["fish"]', 416, 416.4, 1742, 26.2, 10.5, 1.9, 54.7, 4, 9, 1300, 3.25, '["NIN VN Fresh Bun Ref","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '907811221a2637bcccd8ace0310ee14e92d5f0a810977402782eba053bbf0568', 'fb1eea93fe31c3d6c262bcd9304d3d95f11362430fd5d5411ec24839cc9cc4d5', 4),
('imp-b6aeb931b882e8a3', 'com-chay-dau-kho-nam', 132, 'Cơm chay đậu phụ kho nấm đùi gà', 'Cơm trắng dẻo thơm ăn kèm đậu phụ rán vàng kho sánh cùng nấm đùi gà giòn ngọt đậm đà nước tương', 'Mâm cơm chay giản dị mà tròn vị với phần cơm trắng nấu chín dẻo thơm ăn kèm nồi đậu phụ chiên vàng kho cùng nấm đùi gà thái lát dày, ngấm đượm nước tương sánh đậm, thoảng vị cay ấm của tiêu xay và hành lá.', 'Xới cơm trắng nóng ra chén, gắp đậu phụ kho nấm ra đĩa sâu lòng, rưới thêm nước kho sánh lên mặt và dùng ngay khi còn nóng hổi.', 'Phần cơm và phần đậu kho nấm nên bảo quản riêng trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; hâm nóng lại nồi kho trên lửa nhỏ với 1–2 muỗng nước lọc trước khi ăn.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món chay","Cơm nhà","Món kho","Đậu phụ","Nấm đùi gà"]', '["lunch","dinner"]', '["boil","pan_fry","braise"]', '["soybean","wheat"]', 608, 608.4, 2545, 23, 14.3, 2.2, 99, 4.5, 3.8, 1348, 3.37, '["USDA FDC 168580","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '3325e845f0207c0c08ff5cf14b613819d413ea516c6b24dae68f99cd4bc57d9a', '0d5832b367586890a31c25a11b8ba07052bacaa1190876f00bd4606b3d69b326', 4),
('imp-f0039d3d3f6299b3', 'nam-kho-dau-phu-tuong', 133, 'Nấm đùi gà kho đậu phụ tương đậm vị', 'Nấm đùi gà giòn ngọt kho cùng đậu phụ rán và cà chua trong nước sốt tương sánh màu cánh gián đậm đà', 'Đĩa nấm đùi gà kho đậu phụ thơm nồng quyến rũ với màu nâu cánh gián óng ả từ xì dầu đặc kết hợp nước tương và vị chua ngọt tự nhiên của cà chua chín, giúp từng lát nấm dai giòn và miếng đậu phụ mềm béo thấm trọn gia vị.', 'Múc nấm và đậu phụ kho tương ra đĩa sâu lòng, rưới đều nước sốt sánh bóng lên trên rồi rắc hành lá, tiêu đen và ớt lát; ăn nóng cùng cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ 4–5 phút và thêm chút nước lọc nếu sốt quá đặc.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món kho","Nấm đùi gà","Đậu phụ","Ngày rằm"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["soybean","wheat"]', 236, 236.1, 987, 17.2, 13.1, 1.9, 18.1, 4.2, 9.7, 1932, 4.83, '["Dark Soy Sauce Label Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Monosodium Glutamate"]', 'f7d59a6e64ef3eed23730c619a716ca9d40e860ffb46ee9b0bb1626bc862d7cb', 'dbadf94ce37f14a350656598eb1ae2ac5b05071faf23dabe72168168c2b43f60', 4),
('imp-e771ef1a49b2aeed', 'bong-cai-xao-nam-chay', 134, 'Bông cải xanh xào nấm đùi gà chay', 'Bông cải xanh và cà rốt giữ độ giòn tươi, xào nhanh trên lửa lớn cùng nấm đùi gà trong lớp sốt nước tương sánh nhẹ', 'Đĩa rau xào chay đầy màu sắc với từng nhánh bông cải xanh mướt giòn sần sật, cà rốt ngọt thanh và nấm đùi gà thái lát dai giòn, được bao bọc bởi lớp nước sốt nước tương và bột bắp sánh mịn thơm mùi tỏi phi.', 'Dọn nóng ra đĩa ngay sau khi tắt bếp, rắc thêm tiêu xay và ớt thái lát; dùng kèm cơm trắng nóng hoặc chén nước tương ớt.', 'Món xào ngon nhất khi ăn ngay lúc vừa nấu xong để giữ độ giòn của bông cải; nếu bảo quản tủ mát tối đa 1 ngày, đảo nhanh lại trên chảo nóng 2 phút.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Bông cải xanh","Nấm đùi gà","Thanh đạm"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["soybean","wheat"]', 192, 191.6, 802, 6.7, 11, 1.6, 20.6, 5.2, 6.9, 1506, 3.77, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170106","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'da00eaa13c9f2816a0e0cd3777d97e2d1ba3b33d907c3fb8dd4e2f73657a3112', '9b91ca40e94c3b1b28386cf59ce4dec0174dd969b946421709f53d2cfded6329', 4),
('imp-43e806b28c7b8bb5', 'com-chien-tom-trung', 135, 'Cơm chiên tôm trứng', 'Cơm nguội rang tơi săn hạt cùng tôm tươi ngọt thịt, trứng gà béo thơm, cà rốt và giá đỗ giòn mát', 'Đĩa cơm chiên tôm trứng dân dã mà tròn vị với hạt cơm tơi rời bóng nhẹ, thịt tôm tươi săn ngọt đậm xì dầu nước mắm, trứng gà xốp vàng, cà rốt thái hạt lựu và giá đỗ giòn thanh giải ngấy.', 'Múc cơm chiên ra đĩa nóng, rắc tiêu đen xay và hành lá, ăn kèm dưa leo cắt lát cùng chén nước tương ớt xắt.', 'Thưởng thức ngay lúc nóng để giá đỗ giữ độ giòn và hạt cơm săn ngon. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và rang lại trên chảo nóng không dầu 3 phút.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Tôm trứng","Ăn nhanh","Dưới 20 phút","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["crustaceans","egg","fish","shrimp","soybean","wheat"]', 434, 433.5, 1814, 21.7, 12.1, 2.4, 59, 2.5, 3.5, 1401, 3.5, '["USDA FDC 168878","USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '598f52aed342553ae6e459009e090bc7b590186ad88c41a160219b37408e2a3b', '54c9b902af1377cd062601800800567c16be7c190296670935dba93fa2cbedcd', 4),
('imp-f92a1c569c245541', 'mi-xao-bo-rau-cu', 136, 'Mì xào bò rau củ', 'Sợi mì tươi dai mượt áp chảo lửa lớn cùng thịt bò thăn mềm ngọt, bắp cải, cà rốt và hành tây đậm sốt xì dầu', 'Đĩa mì xào bò rau củ hài hòa dinh dưỡng với sợi mì vàng dai mềm không bết, thịt bò thăn xào tái mềm mọng nước quyện hương tỏi gừng và sốt xì dầu, dầu hào đậm đà, bắp cải, cà rốt cùng hành tây giòn ngọt.', 'Bày mì xào bò rau củ ra đĩa sâu lòng khi còn bốc khói, rắc tiêu đen xay và thưởng thức nóng kèm chén tương ớt hoặc nước tương ớt thái lát.', 'Ngon nhất khi ăn nóng ngay sau khi xào để rau củ còn giòn và thịt bò không bị dai. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ rồi làm nóng nhanh trên chảo lửa vừa.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 12, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Thịt bò","Rau củ","Ăn nhanh","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["beef","molluscs","soybean","wheat"]', 436, 436.1, 1825, 22.9, 17.8, 4.8, 46.5, 3.9, 6.1, 1125, 2.81, '["NIN VN Fresh Rice Noodle Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '8a13555392379fdb6d145855c7d9319a17961090fcaa137dcda4fdd7ec2a8675', 'd449bb965f083ca1aacfff5261ae0c98dc8740ba37ed56ec8e245e4847e81c3c', 4),
('imp-f4665d594d941e4a', 'chao-ga-gung-nong', 137, 'Cháo gà gừng nóng', 'Cháo gạo rang nấu nước luộc đùi gà ngọt thanh, thịt gà xé mềm quyện gừng sợi và hành lá ấm áp', 'Nồi cháo gà gừng nóng hổi với nước dùng ngọt tự nhiên từ đùi gà ta luộc cùng gừng hành tím, hạt gạo tẻ kết hợp gạo nếp nở bung sánh mịn, thịt đùi gà xé phay mềm ngọt và gừng tươi thái chỉ ấm bụng.', 'Múc cháo nóng ra tô, xếp thịt gà xé sợi lên trên cùng hành lá thái nhỏ, gừng thái chỉ, tiêu đen xay và vài giọt dầu mè; ăn kèm quẩy giòn hoặc chén nước mắm gừng.', 'Có thể bảo quản phần cháo và thịt gà xé riêng trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn chỉ cần đun sôi lại phần cháo với chút nước lọc rồi cho gà xé và gừng hành vào.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo gà","Gừng ấm","Ăn sáng","Bồi bổ","Cơm nhà"]', '["breakfast","dinner"]', '["boil","simmer"]', '["chicken","fish","sesame"]', 420, 419.9, 1757, 24.5, 12.4, 3.3, 50.2, 1.6, 1.3, 1311, 3.28, '["USDA FDC 168881","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd49ffb0085ed3db122a255613feaef3d072e6cbfddff7840e8d424519f6f58be', '6cf35f9128c35c80ccf4997a9fa925505d03fa4d5db58241e7b8628c0bcae3a9', 4),
('imp-35164fb31de89c5f', 'goi-ga-bap-cai-chanh', 138, 'Gỏi gà bắp cải chanh', 'Ức gà luộc xé phay mềm ngọt trộn bắp cải, cà rốt bào giòn cùng nước mắm chanh tỏi ớt chua ngọt', 'Đĩa gỏi gà bắp cải thanh mát với thịt ức gà ta luộc chín mềm không khô, sợi bắp cải trắng và cà rốt giòn sần sật, hành tây bớt hăng quyện cùng rau răm thơm nồng và nước mắm chanh tỏi ớt chua cay mặn ngọt.', 'Xếp gỏi gà bắp cải ra đĩa, rắc đậu phộng rang giã dập và ít tiêu xay lên mặt; ăn kèm bánh phồng tôm hoặc cơm nóng, cháo gà đều rất hợp.', 'Nên trộn gỏi ngay trước khi ăn để bắp cải giữ độ giòn rụm không bị chảy nước. Có thể sơ chế sẵn gà xé, rau củ cắt sợi và pha riêng nước mắm trộn bảo quản ngăn mát tối đa 24 giờ.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi gà","Thanh mát","Ít dầu mỡ","Khai vị","Nhanh gọn"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["chicken","fish","peanut"]', 233, 232.6, 973, 26.6, 6.5, 1.1, 17.9, 3.8, 11.1, 978, 2.45, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170931","USDA FDC 171477","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","VN Rau Ram Ref"]', 'ef34c129df5b08e456e7404d5164803cfa29d3626747248ae87d9654f76f8abf', 'cb52d2be92ec4d3ca11fb48904cab272e9ac1ecdaeee881476bd4ff03c77ec6d', 4),
('imp-368d91563cb1879b', 'lau-thai-tom-ca-mien-tay', 139, 'Lẩu Thái tôm cá miền Tây', 'Nước lẩu hầm xương đậm đà hòa quyện hương thơm sả, riềng, lá chanh và vị chua cay đặc trưng, nhúng tôm sú, cá diêu hồng và nấm tươi', 'Lẩu Thái tôm cá miền Tây là sự kết hợp hài hòa giữa vị chua cay nồng nàn kiểu Thái với nguyên liệu tươi ngon vùng sông nước Nam Bộ. Nước dùng ninh xương ống ngọt sâu, thơm dậy mùi sả, riềng, lá chanh và sa tế tôm, làm nổi bật vị ngọt của tôm sú, cá diêu hồng và nấm tươi.', 'Dọn nồi lẩu sôi lăn tăn giữa bàn, bày đĩa cá diêu hồng, tôm sú, nấm đùi gà, nấm rơm và rau muống xung quanh; nhúng chín tới và thưởng thức nóng kèm bún tươi cùng chén nước mắm ớt.', 'Nếu còn dư phần nước lẩu chưa nhúng cá tôm, để nguội rồi bảo quản ngăn mát tối đa 24 giờ; khi ăn đun sôi lại 3–5 phút và nhúng hải sản mới.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Lẩu Thái","Tôm cá","Miền Tây","Chua cay"]', '["lunch","dinner"]', '["simmer","boil"]', '["crustaceans","fish","pork","shrimp"]', 456, 456, 1907, 37.3, 12.2, 2.7, 51.7, 5.4, 9.4, 1507, 3.77, '["Chili Oil / Satay Ref","Citrus Leaf Culinary Ref","NIN VN Fresh Rice Noodle Ref","Pork Bone Stock Extraction Ref","Thai Tom Yum Paste Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169251","USDA FDC 169378","USDA FDC 169655","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'cca2d14219d2f4b561906d3731c656a01e5b930a8fdda714581875cdb7b86b10', 'f823e50b3914655037dce8e38510aec00914bed30a9cded8d67619af8751b40c', 4),
('imp-c52c790faf9281da', 'lau-nam-chay-dau-phu', 140, 'Lẩu nấm chay đậu phụ', 'Nước dùng chay thanh ngọt tự nhiên từ bắp ngọt, cà rốt và nhiều loại nấm tươi, nhúng đậu phụ chiên giòn, váng đậu và rau xanh', 'Lẩu nấm chay đậu phụ mang hương vị thanh tịnh và ngọt lành hoàn toàn từ rau củ và các loại nấm tươi. Nước lẩu thơm mùi hành boa-rô phi, ngọt dịu tự nhiên từ bắp ngọt và cà rốt, kết hợp đậu phụ trắng mềm, váng đậu giòn dai, bắp cải và nhiều loại nấm bổ dưỡng.', 'Dọn nồi lẩu nấm chay sôi nhẹ giữa bàn, nhúng nấm tươi, đậu phụ, váng đậu và bắp cải; ăn kèm bún khô chần mềm cùng chén nước tương ớt thái lát.', 'Nếu còn dư nước dùng chay chưa nhúng rau, để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi ăn đun sôi lại 3 phút với nấm mới.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'easy', 20, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Món chay","Lẩu nấm","Đậu phụ","Thanh đạm"]', '["lunch","dinner"]', '["simmer","boil"]', '["soybean","wheat"]', 497, 497.4, 2082, 22.4, 15.1, 2.3, 74.6, 8.7, 12.8, 1651, 4.13, '["USDA FDC 168580","USDA FDC 169246","USDA FDC 169251","USDA FDC 169253","USDA FDC 169745","USDA FDC 169975","USDA FDC 169998","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172472","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref","Vegetarian Seasoning Powder Ref"]', '22174aefb94d0e6d21a73f43dd9a3853f0e0fdd3f3032b96841f1fa252c7fb8a', '82ce520031970260d4a08361aac1a589ad9fb0bae0d908ed059db78194b631e0', 4),
('imp-e9678cfa1bc90074', 'tom-xao-trung-ca-chua', 141, 'Tôm xào trứng cà chua', 'Tôm tươi giòn ngọt kết hợp trứng gà chiên mềm xốp quyện trong sốt cà chua chua ngọt đậm vị cho bữa cơm nhanh gọn', 'Tôm xào trứng cà chua nâng tầm món trứng cà chua quen thuộc nhờ thịt tôm tươi săn giòn, kết hợp trứng gà đánh mềm xốp và phần sốt cà chua sóng sánh hài hòa vị chua ngọt mặn dịu.', 'Dọn nóng trên đĩa sâu lòng, rắc hành lá xanh thái nhỏ và thưởng thức ngay cùng cơm trắng nóng.', 'Món ăn ngon nhất khi dùng ngay trong bữa; nếu bảo quản tủ mát tối đa 24 giờ, làm nóng nhanh trên chảo lửa vừa trong 2 phút và tránh nấu quá lâu khiến tôm bị dai.', 'chinese', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Trung Hoa","Tôm trứng","Xào nhanh","Đưa cơm"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","egg","sesame","shrimp","soybean","wheat"]', 332, 331.7, 1388, 30, 17.5, 3.8, 14.5, 2.3, 8.8, 1130, 2.83, '["Shaoxing Wine Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170457","USDA FDC 170460","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'd757521b5d830c1c43962f9438321c52c903095a4801624b4cf5e3a4a9592b14', 'cc1a4de4864b1b5f69dd87b134402a1ca2dcedff277f47253287442a458de352', 4),
('imp-387c41fb3a0c2297', 'ga-kung-pao-tu-xuyen', 142, 'Gà Kung Pao Tứ Xuyên', 'Thịt đùi gà tẩm bột áo mềm mọng xào lửa lớn với ớt khô, hoa tiêu cay tê, đậu phộng giòn rụm và sốt giấm đen chua ngọt đậm vị', 'Gà Kung Pao Tứ Xuyên chinh phục vị giác nhờ sự cân bằng tinh tế giữa vị cay tê của ớt khô và hoa tiêu, vị chua ngọt dịu đặc trưng từ giấm đen Trấn Giang cùng miếng thịt đùi gà mềm mọng và đậu phộng rang giòn bùi.', 'Bày ngay ra đĩa khi sốt vừa áo bóng và đậu phộng còn giòn tan; ăn nóng kèm cơm trắng dẻo thơm.', 'Nếu cần bảo quản, cất hộp kín trong ngăn mát tối đa 2 ngày và để riêng phần đậu phộng rang nếu có thể; hâm lại nhanh trên chảo lửa vừa trong 2–3 phút rồi rắc đậu phộng.', 'chinese', 'mon_xao', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Kung Pao","Đậu phộng","Cay tê"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","peanut","soybean","wheat"]', 501, 501.1, 2097, 30.8, 33.3, 6.4, 19.9, 3.1, 9.1, 912, 2.28, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","Dark Soy Sauce Label Ref","Shaoxing Wine Ref","Spice Reference","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170933","USDA FDC 171413","USDA FDC 172385","USDA FDC 172430","USDA FDC 172883","USDA FDC 173468","USDA FDC 174277"]', 'f9837d1349409a7155308e250675fd65bdedc58ec472caf68024b19448b5a4be', 'a9f2190257dc75e26e3c73eec340235a0dfe18bc87d1e65a0aad20ce91986a8d', 4),
('imp-f5abd36e99d48d94', 'dau-phu-mapo-tu-xuyen', 143, 'Đậu phụ Mapo Tứ Xuyên', 'Đậu phụ non om trong lớp dầu ớt tự phi thơm nồng từ ớt tươi và ớt khô cùng thịt heo xay, tương đậu cay và hoa tiêu tê đầu lưỡi', 'Đậu phụ Mapo Tứ Xuyên phiên bản tự phi dầu ớt tươi và ớt khô trực tiếp tại bếp mang đến hương cay thơm bùng nổ, kết hợp thịt heo xay tơi đậm vị tương ớt đậu bản và đậu phụ non mềm tan.', 'Múc ra đĩa sâu lòng khi sốt đang sôi liu riu, rắc thêm bột hoa tiêu và hành lá xanh; món ăn sinh ra để ăn nóng với cơm trắng.', 'Dùng ngon nhất ngay sau khi nấu. Nếu bảo quản tủ mát tối đa 2 ngày, hâm lại nhẹ tay trên chảo lửa nhỏ cùng 1–2 muỗng canh nước dùng hoặc nước lọc.', 'chinese', 'mon_kho', NULL, 'medium', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Cay tê","Đậu phụ","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry","braise"]', '["pork","sesame","soybean","wheat"]', 420, 420.4, 1759, 17, 34.3, 7.7, 11.5, 1.4, 2.7, 715, 1.79, '["Pixian Doubanjiang Ref","Spice Reference","USDA FDC 167902","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 172476","USDA FDC 172883","USDA FDC 173647"]', '0b6289ca7e53e45e179a8730a203545a43599bf926bb13e3e6a2f52fd6ad4e14', 'aec18eb9aceaab44ffef33245d8cfff033ea709f4de886b0c788b770671f27dd', 4),
('imp-242fd73cebd63651', 'suon-chua-ngot-quang-dong', 144, 'Sườn om chua ngọt Quảng Đông', 'Sườn non heo áp xém vàng om mềm trong sốt tương cà, giấm gạo, đường phèn và dứa cà chua sánh bóng đậm đà', 'Sườn om chua ngọt Quảng Đông là món mặn trứ danh với từng khúc sườn non mềm róc xương, quyện lớp sốt đỏ bóng chua thanh của giấm gạo và tương cà, hòa cùng vị ngọt tươi từ dứa chín và cà chua.', 'Bày sườn và dứa cà chua ra đĩa lớn, rưới nước sốt sánh keo lên trên; ăn nóng kèm cơm trắng dẻo thơm.', 'Bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng trên chảo lửa nhỏ đến vừa với 2 muỗng canh nước lọc trong 5 phút.', 'chinese', 'mon_kho', NULL, 'medium', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Chua ngọt","Sườn heo","Tiệc nhà"]', '["lunch","dinner"]', '["boil","pan_fry","braise"]', '["pork","soybean","wheat"]', 376, 376.1, 1574, 16.8, 26.2, 8.9, 17.5, 1.4, 13.1, 801, 2, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 167861","USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170457","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '8df6f265ce1c06e3b2e795cccbec62f961f6b3262a336faa16d08668b52db728', 'ff61b09a51b656b02cc77adcfff057eab33da2779d132862563bfebafb6d753e', 4),
('imp-34f3eb2438125614', 'bap-cai-xao-toi-quang-dong', 145, 'Bắp cải xào tỏi kiểu Quảng Đông', 'Bắp cải xanh xé miếng kết hợp cà rốt thái lát xào lửa lớn giữ trọn độ giòn ngọt, dậy mùi tỏi phi, rượu Thiệu Hưng và giấm đen', 'Bắp cải xào tỏi kiểu Quảng Đông nổi bật với từng lá bắp cải xé tay giòn sần sật, mép lá hơi xém cạnh thơm mùi chảo nóng, quyện vị mặn ngọt thanh nhẹ của xì dầu, rượu Thiệu Hưng và giấm đen Trấn Giang.', 'Trút ra đĩa và dùng nóng ngay với cơm trắng để cảm nhận trọn vẹn độ giòn ngọt tự nhiên của rau củ.', 'Món rau xào nên dùng hết trong bữa để giữ độ giòn tươi; nếu bảo quản tủ mát tối đa 24 giờ, đảo nóng nhanh trên chảo lửa lớn trong 1–2 phút.', 'chinese', 'mon_xao', NULL, 'easy', 10, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Bắp cải","Xào tỏi","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["pork","soybean","wheat"]', 268, 268.4, 1123, 5.8, 20.9, 6.2, 15.9, 4.8, 7.2, 782, 1.96, '["Chinkiang Black Vinegar Ref","Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '52efb7776902ccc550e2e7ddddf172a3dcc69a16412ccd93bd2ca230754c7447', 'a4d0192d3e34c28ffcf8f3aaf95a3b3ccd52ee02c382679dd7dd7311b5e6ac3d', 4),
('imp-2d508cd359edb61c', 'dau-phu-hap-tom-gung', 146, 'Đậu phụ trứng hấp tôm gừng', 'Những khoanh đậu phụ trứng mềm tan phủ chả tôm tươi băm nhuyễn quyện gừng hành hấp chín tới, rưới sốt dầu hào xì dầu sánh bóng', 'Đậu phụ trứng hấp tôm gừng mang phong vị dim sum tinh tế với phần đậu phụ trứng béo mịn nâng đỡ viên chả tôm giòn ngọt tự nhiên, hoàn thiện bằng lớp sốt xì dầu dầu hào trong mượt và hương thơm ấm nồng của gừng hành.', 'Dọn nóng nguyên đĩa ngay sau khi rưới sốt và rắc lá hành xanh; dùng làm món chính nhẹ bụng cùng cơm trắng hoặc món khai vị tiệc gia đình.', 'Ngon nhất khi ăn nóng ngay sau khi hấp; nếu bảo quản tủ mát tối đa 24 giờ, đậy kín màng bọc thực phẩm và hấp nóng lại khoảng 4–5 phút trước khi dùng.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Dim sum","Đậu phụ","Tôm tươi"]', '["lunch","dinner"]', '["steam","simmer"]', '["crustaceans","egg","molluscs","sesame","shrimp","soybean","wheat"]', 211, 211, 883, 21.7, 9.3, 2.1, 9.3, 0.8, 1.9, 816, 2.04, '["Asian Egg Tofu Ref","Shaoxing Wine Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '1cf7eaeed48e1dd0452678f47a45bc1f2f9edfbb31237148f3f73f9b1a151e6e', '0e08d58f6cee8917495c9cd92e6f1e47a0b9d6b8b98e21f55a7d78497de0b86f', 4),
('imp-6eaf6ed6d417c52c', 'muc-chien-muoi-ot', 147, 'Mực chiên giòn muối ớt kiểu Hồng Kông', 'Mực tươi áo hai lớp bột ướt và bột khô chiên vàng giòn rụm, xóc nhanh cùng tỏi gừng, ớt hiểm phi thơm và muối tiêu rang', 'Mực chiên giòn muối ớt kiểu Hồng Kông hấp dẫn với lớp vỏ ngoài xốp giòn vàng ruộm ôm trọn miếng mực tươi giòn ngọt bên trong, dậy mùi thơm bùng nổ của tỏi phi, gừng băm, ớt hiểm và hành lá.', 'Dọn nóng ngay khi vừa xóc gia vị để giữ độ giòn rụm; thưởng thức kèm tương ớt hoặc chanh tươi như món khai vị hoặc ăn cùng cơm trắng.', 'Món chiên ngon nhất khi dùng ngay lúc nóng giòn; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 3–4 phút.', 'chinese', 'mon_chien', NULL, 'medium', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Hồng Kông","Hải sản","Muối ớt"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["molluscs","squid","wheat"]', 423, 422.7, 1768, 23.7, 17.5, 2.8, 40.7, 1.6, 0.7, 586, 1.46, '["Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 169761","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 175039"]', '40d30ab8bfc0264f87b8f4c3814251e31ca02c8f2a0c43f7bf57b06a17f05950', '77cba96b653b12470e4f775a9223c0787c4b8c6b1974689393091a2fa50c8daf', 4),
('imp-d90dc5bbe2891a12', 'chao-thit-bam-gung', 148, 'Cháo thịt bằm gừng trứng kiểu Quảng Đông', 'Cháo gạo rang ninh sánh mịn kết hợp thịt heo bằm ướp đậm vị, vân trứng gà béo mượt, gừng sợi cay ấm và hành lá thơm nồng', 'Cháo thịt bằm gừng trứng kiểu Quảng Đông là món ăn bổ dưỡng, ấm bụng với hạt gạo rang trước giúp cháo nhanh nhừ sánh mịn, hòa quyện thịt heo bằm tơi mềm, vân trứng gà óng ả và gừng tươi thái sợi giải cảm.', 'Xếp gừng thái sợi vào đáy tô trước rồi chan cháo nóng hổi lên trên, rắc hành lá, tiêu đen xay và vài giọt dầu mè thơm; dùng nóng ngay.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi hâm lại trên bếp lửa nhỏ, thêm 50–100 ml nước lọc và khuấy đều tay để cháo không bị bén đáy nồi.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 15, 40, 3, '/frigo/illustrations/delicious-meal.png', '["Món cháo","Quảng Đông","Bữa sáng","Ấm bụng"]', '["breakfast","dinner"]', '["simmer"]', '["egg","pork","sesame","soybean","wheat"]', 529, 529, 2213, 21.1, 20.6, 6.8, 62.4, 1.7, 1.2, 1340, 3.35, '["USDA FDC 167902","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'd55b69accb07fd52218bb7131fbecbab0905a0260cf3faf9ff108cbf0bf1b528', 'ce40c62dada905484e449db2948047ecf9b84105e5c5f027ec40f63e5225b6be', 4),
('imp-b23ab24915e52866', 'com-chien-duong-chau', 149, 'Cơm chiên Dương Châu', 'Hạt cơm tơi vàng óng ánh áo lòng đỏ trứng, quyện tôm tươi, thịt bằm, lạp xưởng, trứng chiên cắt hạt lựu cùng cà rốt và đậu giòn ngọt', 'Cơm chiên Dương Châu chuẩn vị quán Quảng Đông nổi bật với hạt cơm săn tơi vàng ươm nhờ kỹ thuật trộn lòng đỏ trứng trước khi rang, kết hợp đầy đặn tôm tươi, thịt heo xay, lạp xưởng thơm béo và rau củ giòn ngọt.', 'Dọn nóng ra đĩa hoặc nén chén úp ngược đẹp mắt, rắc thêm tiêu xay và hành lá; ăn kèm dưa leo, cà chua lát và chút nước tương ớt.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; hâm nóng bằng cách đảo nhanh trên chảo chống dính lửa vừa trong 3–4 phút cho hạt cơm tơi nóng lại.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Dương Châu","Cơm chiên","Quảng Đông","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","egg","pork","shrimp","soybean","wheat"]', 676, 675.6, 2827, 31.2, 31.1, 8.5, 65.9, 2.1, 5.2, 1330, 3.33, '["USDA / Chinese Sausage Ref","USDA FDC 167902","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'c35d990700c82d41cb844659ec45096548eaa4adb202c8c8431e6cbb1b6ac49b', '2af45fce514d2c653dd40575895c456ecbc826c7553370b829e721fa44469ac4', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-e83f58ebb9b02fbd', 'mi-dan-dan-tu-xuyen', 150, 'Mì Đan Đan Tứ Xuyên', 'Mì sợi dai trộn sốt tương mè béo bùi, dầu ớt cay nồng, giấm đen và hoa tiêu Tứ Xuyên, phủ thịt heo băm xào giòn, cải thìa và đậu phộng', 'Mì Đan Đan Tứ Xuyên là món mì trộn đường phố trứ danh, quy tụ hài hòa vị béo bùi của tương mè, vị cay tê bùng nổ từ dầu ớt và hoa tiêu, hòa quyện cùng sợi mì dai mượt, cải thìa chần giòn và thịt heo băm xào khô thơm lừng.', 'Trình bày gọn đẹp trong tô vừa với lớp sốt dưới đáy, mì ở giữa, thịt xào, cải thìa, đậu phộng giã và hành lá trên cùng; trộn thật đều tay trước khi ăn nóng.', 'Món mì trộn ngon nhất khi ăn ngay lúc vừa chế biến. Nếu cần chuẩn bị trước, có thể bảo quản riêng phần thịt xào và nước sốt trong tủ mát tối đa 3 ngày, khi ăn chỉ cần luộc mì nóng rồi trộn.', 'chinese', 'mon_bun_pho', NULL, 'medium', 15, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Tứ Xuyên","Cay tê","Mì Đan Đan"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["egg","peanut","pork","sesame","soybean","wheat"]', 792, 792.1, 3314, 29.5, 39, 8.7, 80.9, 5.9, 5.6, 1682, 4.21, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","Dark Soy Sauce Label Ref","Five Spice USDA Ref","Shaoxing Wine Ref","Spice Reference","USDA / MEXT Wheat Noodle Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170189","USDA FDC 170390","USDA FDC 171028","USDA FDC 171413","USDA FDC 172430","USDA FDC 173647","USDA FDC 174277"]', 'fdb7a50c1e90707e1eb47c1ea5eb5237c6944f62b52e6e681e4d9e562325566d', 'dd70c6cbb8fd9fe98dbd0b5526f0b6db908b0eaf5473683161a6e3cfd705c57a', 4),
('imp-04d477399e49fe8e', 'mi-xao-bo-quang-dong', 151, 'Mì xào bò Quảng Đông', 'Thịt bò thái lát ướp mềm kiểu Quảng Đông xào lửa lớn với mì trứng áp vàng, giá đỗ, đậu Hà Lan giòn ngọt và sốt xì dầu đậm vị', 'Mì xào bò Quảng Đông mang hương vị đặc trưng của món xào chảo nóng với sợi mì trứng tơi dai, thịt bò mềm mọng nhờ kỹ thuật ướp baking soda và bột bắp, hòa cùng giá đỗ, đậu giòn ngọt và nước sốt xì dầu bóng thơm.', 'Dọn nóng ngay ra đĩa lớn, dùng kèm tương ớt sa tế hoặc giấm ớt ngâm nếu thích vị cay kích thích.', 'Mì xào ngon nhất khi dùng ngay lúc nóng; nếu bảo quản tủ mát tối đa 24 giờ, làm nóng nhanh trên chảo lửa vừa với 1–2 muỗng canh nước lọc trong 2–3 phút.', 'chinese', 'mon_xao', NULL, 'easy', 20, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Mì xào","Thịt bò","Lửa lớn"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["beef","egg","molluscs","sesame","soybean","wheat"]', 706, 705.6, 2953, 35.9, 25.4, 6.5, 81.9, 4.5, 6.9, 1660, 4.15, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169961","USDA FDC 169963","USDA FDC 170005","USDA FDC 170187","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175039"]', 'd2cfc0333aa54019c4e49709e6a4716516624ecdbfcad37331519845767a658a', '9a2aa582646a85e94b8d23bd358c5a8829bd062e1c7112f4f4bf3186779f94a3', 4),
('imp-a22f9257b0fd7a46', 'ba-chi-kho-dong-pha', 152, 'Ba chỉ kho Đông Pha', 'Từng khối ba chỉ heo buộc dây lạt kho liu riu hàng giờ trong rượu Thiệu Hưng, xì dầu, đường phèn và lớp hành gừng thơm nồng đến mềm tan', 'Ba chỉ kho Đông Pha là tuyệt phẩm ẩm thực Giang Nam với từng khối thịt ba chỉ vuông vắn có lớp bì màu nâu hổ phách óng ả, phần mỡ trong mềm tan không ngấy nhờ được om chậm hàng giờ với rượu Thiệu Hưng, xì dầu và đường phèn.', 'Gắp từng khối thịt ra đĩa sâu lòng, cắt bỏ dây buộc, rưới phần nước kho sánh bóng lên mặt; dọn nóng cùng cơm trắng dẻo và cải thìa luộc xanh mướt.', 'Có thể bảo quản hộp kín trong ngăn mát tối đa 4 ngày (thịt kho càng hâm lại càng đậm đà). Khi ăn, hấp cách thủy hoặc đun liu riu lại với nước kho trên lửa nhỏ trong 10–15 phút.', 'chinese', 'mon_kho', NULL, 'hard', 20, 180, 5, '/frigo/illustrations/delicious-meal.png', '["Đông Pha nhục","Trung Hoa","Món kho","Tiệc nhà"]', '["lunch","dinner"]', '["boil","braise"]', '["pork","soybean","wheat"]', 665, 665.1, 2782, 12.8, 61.2, 22.3, 11.6, 0.8, 8.5, 1139, 2.85, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169231","USDA FDC 170005","USDA FDC 170917","USDA FDC 171316","USDA FDC 171320","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', '8bd61b0014aa4ba0a9f99bfe0f99a42a05be746490f0e6d9dbccbe9cae1e9439', '1b8eee68225532eff6a66aa6510eae1527c32b3b963629da1f9985b8949445be', 4),
('imp-5f8d0890bd6d0a76', 'vien-su-tu-dau-kho-cai', 153, 'Viên Sư Tử Đầu kho cải thảo', 'Những viên thịt heo lớn quết tay mềm xốp trộn củ năng giòn sần sật, chiên vàng định hình rồi kho mềm thấm trên nền cải thảo ngọt thanh', 'Viên Sư Tử Đầu kho cải thảo là món ăn truyền thống vùng Hoài Dương nổi bật với những viên thịt heo cỡ lớn mềm tơi mọng nước xen lẫn củ năng giòn sần sật, được kho liu riu trên lớp cải thảo ngọt thanh cùng sốt xì dầu dầu hào sánh bóng.', 'Xếp cải thảo kho mềm xuống đáy đĩa sâu lòng, đặt 4 viên thịt Sư Tử Đầu lên trên, rưới nước sốt sánh bóng và rắc hành lá xanh; ăn nóng với cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại cả thịt viên và nước kho trong nồi đậy nắp trên lửa nhỏ khoảng 8–10 phút.', 'chinese', 'mon_kho', NULL, 'hard', 25, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Sư tử đầu","Hoài Dương","Món kho","Tiệc nhà"]', '["lunch","dinner"]', '["deep_fry","braise"]', '["egg","molluscs","pork","sesame","soybean","wheat"]', 513, 513.2, 2147, 25.1, 35.8, 10.9, 21.3, 2.8, 6.9, 1334, 3.33, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","Panko / Batter Mix Ref","Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169231","USDA FDC 169294","USDA FDC 169698","USDA FDC 169977","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', 'd55b7318855e6227cb3ea22ed5a1ee1ecf5d932c059ecbc8cff8bc1f27d1bc19', 'b2f02830ddfbd574ee5d293e430060a7e421004c02c6e2e4c3253f663a3641e3', 4),
('imp-ece7da4660b63e9d', 'bo-xao-ca-chua-kieu-trung', 154, 'Bò xào cà chua kiểu Trung', 'Thịt bò thái lát mềm mọng xào cùng cà chua chín đỏ sốt chua ngọt sánh mịn, đậm vị cơm nhà Trung Hoa', 'Món bò xào cà chua kiểu Trung nổi bật với từng lát thịt bò được xử lý mềm mượt hòa quyện trong phần sốt cà chua chín đỏ sánh bóng, chua ngọt hài hòa.', 'Dọn nóng ngay ra đĩa sâu lòng, rắc hành lá thái khúc lên trên và thưởng thức cùng cơm trắng dẻo thơm hoặc rau cải chần.', 'Ngon nhất khi dùng ngay sau khi xào; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đảo nhanh trên chảo lửa lớn cùng 1 muỗng canh nước lọc khi hâm lại.', 'chinese', 'mon_xao', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Cà chua","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","sesame","soybean","wheat"]', 420, 420.3, 1759, 30.6, 25, 7, 18.2, 2.8, 9.3, 1074, 2.69, '["Shaoxing Wine Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170460","USDA FDC 170499","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175039"]', '99dc2aa12ae7c712b7de6903506314f6dbb28b48d0341ef34b222365db4f84a6', 'a2652bc891d63a1ac2e8a263c1dac134bce24e71514be862f41c599e8cf2f796', 4),
('imp-b9d222a8c523b8e4', 'dua-leo-dap-toi-tu-xuyen', 155, 'Dưa leo đập tỏi Tứ Xuyên', 'Dưa leo đập dập giòn sần thấm đẫm sốt giấm đen Trấn Giang, tỏi băm, dầu mè và dầu ớt tê cay đặc trưng', 'Món khai vị lạnh trứ danh của ẩm thực Tứ Xuyên với từng miếng dưa leo đập dập giòn rụm, thấm sâu hỗn hợp giấm đen Trấn Giang, tỏi tươi, dầu mè thơm lừng và sa tế dầu ớt.', 'Bày dưa leo ra đĩa sâu lòng, rưới phần sốt còn lại trong tô lên mặt, rắc mè trắng rang và ngò rí; ăn lạnh ngay để khai vị hoặc giải ngấy cùng các món thịt kho, đồ chiên.', 'Món trộn ăn liền ngon nhất trong vòng 30 phút sau khi trộn; nếu chuẩn bị trước, nên bảo quản riêng dưa đã vắt ráo và phần sốt trong ngăn mát tối đa 12 giờ rồi mới trộn trước khi ăn.', 'chinese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn","Tứ Xuyên","Khai vị","Dưa leo","Giải ngấy"]', '["lunch","dinner"]', '["toss_mix"]', '["sesame","soybean","wheat"]', 145, 144.9, 607, 2.7, 10, 1.5, 12.9, 1.5, 6.9, 751, 1.88, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","Spice Reference","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170106","USDA FDC 170150","USDA FDC 171028","USDA FDC 173468","USDA FDC 174277"]', '0108fd9b397054c86308bd2c11f5fd78780877ccdd9fc48a5affaf2bd694cfa9', '7706d3de617cd05bd4aa738524599b2b9ee5562dcbc81ee49574f5226731bf2c', 4),
('imp-51f6c12eefee914d', 'dau-phu-kho-bap-cai', 156, 'Đậu phụ kho bắp cải', 'Đậu phụ chiên vàng óng kho mềm cùng bắp cải ngọt và nấm kim châm trong nước tương đậm đà thanh đạm', 'Món kho bình dân kiểu gia đình Trung Hoa kết hợp đậu phụ chiên vàng giòn vỏ ngoài, bắp cải giòn ngọt và nấm kim châm dai mềm thấm đẫm sốt nước tương sánh nhẹ.', 'Dọn nóng ngay trong nồi đất hoặc đĩa sâu lòng, rắc hành lá và tiêu đen xay lên mặt; dùng kèm cơm trắng nóng rất bắt vị.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn, hâm nóng trên chảo lửa nhỏ 3–4 phút cho đậu phụ và bắp cải nóng đều.', 'chinese', 'mon_kho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Đậu phụ","Bắp cải","Thanh đạm","Trung Hoa"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 254, 253.8, 1062, 15.8, 16.1, 2.3, 16.7, 5.4, 7.3, 1428, 3.57, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169253","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', 'ca80a96598d41662040e7bcdec81dfc698b6711e5ce9436210446d7676b9e18e', '77cde94fa04560d42870a3a4793a02c21a17bc355a5fcd92d851effacc0dc87e', 4),
('imp-6d3fa354c64cf8b1', 'ca-kho-tuong-dam', 157, 'Cá kho tương đậm kiểu Trung', 'Cá nguyên con áp chảo vàng giòn da rồi kho sánh cùng rượu Thiệu Hưng, giấm đen Trấn Giang và xì dầu đậm đà', 'Món cá kho tàu trứ danh kiểu Trung Hoa không thêm nước mà om cá trực tiếp trong hỗn hợp rượu Thiệu Hưng, giấm đen Trấn Giang và xì dầu sánh bóng, giữ nguyên lớp da vàng giòn và thớ thịt trắng ngọt.', 'Đặt nguyên con cá lên đĩa bầu dục lớn, rưới đều phần sốt nâu đỏ sánh mịn lên mình cá và dùng nóng cùng cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn, cho cá cùng nước sốt vào chảo đậy nắp hâm trên lửa nhỏ 5–6 phút đến khi nóng kỹ.', 'chinese', 'mon_kho', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Cá nguyên con","Trung Hoa","Đậm đà","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["fish","soybean","wheat"]', 341, 340.8, 1425, 39.3, 12.5, 2.4, 12.6, 0.6, 7.7, 745, 1.86, '["Chinkiang Black Vinegar Ref","Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","USDA FDC 175176"]', 'a510891d8a2135a5405fd24108770af9fa9c1265ed38266e63d4eaa1dc03bbfa', 'd7f2b2197eee328041dc277d93bb25ea703fa8eb508391e6c53c54e1a23b194a', 4),
('imp-03577e7fa7667ab8', 'canh-chua-cay-trung-hoa', 158, 'Canh chua cay kiểu Trung Hoa', 'Nước súp sánh mượt nóng hổi hòa quyện vị chua thanh giấm đen, cay nồng tiêu trắng cùng đậu phụ, nấm và vân trứng gà', 'Món súp chua cay trứ danh của ẩm thực Trung Hoa với nước dùng gà sánh nhẹ, vân trứng gà tơ mềm, nấm đùi gà giòn ngọt, đậu phụ mềm mịn cùng vị chua thơm từ giấm đen và cay ấm của tiêu trắng.', 'Múc canh nóng hổi ra tô sứ sâu lòng, rắc hành lá thái nhỏ và ớt hiểm đỏ lên mặt; dùng làm món khai vị nóng trước bữa chính.', 'Ngon nhất khi ăn nóng ngay lúc vừa nấu; nếu còn dư, bảo quản ngăn mát tối đa 24 giờ và đun nóng lại trên lửa vừa, thêm chút giấm đen trước khi tắt bếp để giữ trọn hương thơm.', 'chinese', 'mon_canh', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Chua cay","Trung Hoa","Khai vị","Ấm bụng"]', '["lunch","dinner"]', '["simmer"]', '["egg","sesame","soybean","wheat"]', 212, 211.7, 886, 16.9, 9.2, 1.9, 17.4, 3, 5.1, 1401, 3.5, '["Chinkiang Black Vinegar Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 172475","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '7eec388f0e729514d24716c53fbb29e2da0840df00c282b811207f1d98ec0286', '6ef7535dd433bc5a23a67cfbdaead5b0bf6c9a0f2874da02e7a71fc1827f5933', 4),
('imp-62ebe8dd18b15b5e', 'muc-xao-gung-hanh', 159, 'Mực xào gừng hành', 'Mực ống khía hoa giòn ngọt chần nhanh rồi xào lửa lớn với gừng sợi, hành lá và sốt dầu hào thơm lừng', 'Món mực xào gừng hành kiểu Quảng Đông giữ được độ giòn sần sật tự nhiên của từng miếng mực khía hoa nhờ kỹ thuật chần nhanh với gừng và xào đảo tốc độ trên lửa lớn.', 'Trút ngay ra đĩa khi vừa tắt bếp để mực giữ độ giòn ngọt, rắc thêm chút tiêu xay và ăn nóng kèm cơm trắng.', 'Mực xào ngon nhất khi ăn ngay lúc nóng; nếu cần bảo quản ngăn mát tối đa 24 giờ, khi hâm lại chỉ đảo thật nhanh trên chảo nóng trong 30 giây để tránh mực bị dai.', 'chinese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Mực tươi","Quảng Đông","Nhanh gọn","Hải sản"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["molluscs","soybean","squid","wheat"]', 264, 263.9, 1104, 24.1, 10.5, 1.8, 16.6, 1.5, 4.9, 1335, 3.34, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '2708bd3ceb39a2a7ae6429c87b9b6ee7c18ca458e149ceb9b2ebc16985196a1e', 'a5e45bca6d64ea7a6fc3f6d715c78d94e1b88074792c2270188c09308d231278', 4),
('imp-d283a9225d6ece09', 'com-ca-hoi-donburi', 160, 'Cơm cá hồi ướp tương Donburi kiểu Nhật', 'Những lát cá hồi tươi béo mềm ướp sốt tương mirin dầu mè đậm đà, xếp trên lớp hành tây giòn ngọt và cơm gạo Nhật ấm nóng', 'Cơm cá hồi Zuke Donburi là món cơm tô nổi tiếng của Nhật với phi lê cá hồi tươi chuẩn sashimi thái lát mỏng, ướp thấm đẫm nước sốt xì dầu mirin thơm dầu mè, đặt lên lớp đệm hành tây thái mỏng trên nền cơm ấm.', 'Xới cơm Nhật vừa ấm ra hai tô lớn, phủ kín hành tây và cá hồi ướp sốt lên trên, rắc hành lá, rong biển nori vụn, hạt mè rang và ăn kèm wasabi.', 'Món cá hồi sống ướp sốt ngon nhất khi ăn ngay sau khi hoàn thành; không nên hâm nóng hoặc để qua ngày để đảm bảo độ tươi ngon và an toàn thực phẩm.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 15, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Donburi","Cá hồi","Bữa trưa","Thanh mát"]', '["lunch","dinner"]', '["toss_mix","assemble"]', '["fish","salmon","sesame","soybean","wheat"]', 654, 654.1, 2736, 36.7, 25.4, 5.3, 64.2, 2.1, 8.4, 1549, 3.88, '["MEXT Hon-Mirin 16031","USDA FDC 168456","USDA FDC 168878","USDA FDC 169231","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 174277","USDA FDC 175167"]', '0ab09124e614508d233b9b83cd56783f8159e6fb58030d782ab4ca910bf281b5', '3519921a36a5a08f7c729abb40fa1c7d5735419d8265be5589118216b2f17f41', 4),
('imp-7ed24282981e96f6', 'thit-ba-chi-shogayaki-gung', 161, 'Thịt ba chỉ áp chảo sốt gừng Shogayaki', 'Thịt ba chỉ heo thái mỏng áp chảo xém cạnh quyện sốt gừng tươi xì dầu mirin thơm nồng, ăn kèm bắp cải thái sợi thanh mát', 'Shogayaki là món thịt heo xào gừng quốc dân trong thực đơn teishoku Nhật Bản, nổi bật với từng lát thịt ba chỉ mềm thơm phủ sốt gừng tươi mài nhuyễn hòa quyện vị mặn ngọt từ nước tương, rượu sake và mirin.', 'Bày thịt ba chỉ sốt gừng nóng hổi cạnh ụ bắp cải thái sợi mịn trên đĩa lớn, rưới phần sốt sánh còn lại trong chảo lên mặt thịt và ăn cùng cơm trắng nóng.', 'Phần thịt thừa bảo quản hộp kín ngăn mát tối đa 2 ngày; hâm nóng lại trên chảo lửa nhỏ hoặc lò vi sóng 1–2 phút, phần bắp cải nên ăn tươi trong ngày.', 'japanese', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Shogayaki","Thịt ba chỉ","Cơm trưa","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["pork","soybean","wheat"]', 681, 680.6, 2848, 13.1, 58.2, 20.6, 21.2, 3.4, 14.2, 1032, 2.58, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 167820","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 171413","USDA FDC 174277"]', '81ea24d173972ec1b47292157e8ca404e0ecacc115f0ea7f7a00f92e15759c48', '1c477a09e1b43625b53f46a3bdeb09a770134ace41fe341f28f587bc2c590f66', 4),
('imp-c6e706b483805e44', 'ba-chi-ham-kakuni', 162, 'Thịt ba chỉ hầm Kakuni kiểu Nhật', 'Thịt ba chỉ heo hầm hai giai đoạn mềm tan như tan trong miệng, quyện nước sốt dashi xì dầu đường ngọt dịu và trứng lòng đào ngấm vị', 'Buta no Kakuni là món thịt ba chỉ hầm trứ danh vùng Nagasaki Nhật Bản. Thịt được áp chảo rút mỡ, ninh mềm trong nước gừng hành rồi mới om chậm cùng nước dùng dashi, rượu sake, mirin, đường và xì dầu cho đến khi từng thớ thịt mềm rục bóng mượt.', 'Xếp từng khối thịt ba chỉ hầm bóng mượt ra bát sâu lòng cùng nửa quả trứng ngâm sốt và rau đậu hoặc cải thìa chần, rưới nước kho sánh ngọt và đặt hành trắng thái sợi lên trên.', 'Món Kakuni càng để qua đêm trong tủ lạnh càng thấm đậm; hớt bỏ lớp mỡ đông trên mặt nước kho, bảo quản tối đa 3–4 ngày và hâm lại lửa nhỏ khoảng 5–7 phút trước khi ăn.', 'japanese', 'mon_kho', NULL, 'hard', 25, 150, 5, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Kakuni","Thịt kho","Bữa tiệc","Hầm mềm"]', '["lunch","dinner"]', '["braise","pan_fry","boil"]', '["egg","fish","pork","soybean","wheat"]', 802, 802.2, 3356, 19.6, 65, 23.3, 25.5, 1.1, 19.1, 1559, 3.9, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 167820","USDA FDC 169231","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', 'e991055e26963a5baf30bbe9ed07b36c104c49177b9a7fd3835be13e94afd5cd', '84e4c6a5e09e67c60a009f77ecc4cc4c5dbfd0d4d7bd4f2cc53ea887daddf232', 4),
('imp-324e0ea2e2f068bf', 'canh-miso-dau-phu-nam', 163, 'Canh Miso đậu phụ non và nấm', 'Bát canh Miso ấm nóng nấu từ nước dùng dashi tảo bẹ thanh ngọt, đậu phụ non mềm mịn, nấm tươi giòn và rong biển wakame', 'Canh Miso là món canh truyền thống không thể thiếu trong bữa cơm Nhật Bản. Nước dùng thanh ngọt từ tảo bẹ kombu hòa cùng tương miso thơm dịu, đậu phụ non cắt khối và nấm tươi tạo nên vị umami nhẹ nhàng ấm bụng.', 'Múc canh nóng ra từng chén sứ nhỏ có nắp, rắc hành lá thái khoanh lên trên và dùng nóng ngay trước hoặc trong bữa cơm cùng cá nướng và cơm trắng.', 'Canh miso ngon nhất khi dùng ngay lúc mới nấu; nếu bảo quản tủ mát tối đa 1 ngày, chỉ hâm nóng tới khoảng 75–80°C trên lửa nhỏ, tuyệt đối không đun sôi bùng để tránh mất mùi thơm của tương miso.', 'japanese', 'mon_canh', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Món canh","Canh Miso","Thanh đạm","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["soybean"]', 90, 90.2, 377, 6.7, 3.2, 0.5, 9.7, 2.1, 2.6, 789, 1.97, '["USDA FDC 168457","USDA FDC 169251","USDA FDC 170005","USDA FDC 170496","USDA FDC 172446","USDA FDC 172476","USDA FDC 173647"]', '80f1b740c56e069805b0b9f9831f9b03ed4993cd2f80e7f7dfc92af1bb9f5815', 'e8d7e15b85a402aa4f336e48838f63e4108f9459b879680f4582b5597069a2c2', 4),
('imp-5507103398040565', 'mi-xao-yakisoba-rau-cu', 164, 'Mì xào Yakisoba thịt ba chỉ rau củ', 'Sợi mì lúa mì Yakisoba xào lửa lớn giòn thơm cùng thịt ba chỉ, bắp cải, cà rốt, giá đỗ và nước sốt chua ngọt đậm đà kiểu đường phố Nhật', 'Yakisoba là món mì xào lễ hội nổi tiếng của Nhật Bản, kết hợp sợi mì lúa mì dai giòn, thịt ba chỉ áp chảo thơm béo cùng các loại rau củ tươi giòn và sốt yakisoba tự pha từ sốt Worcestershire, dầu hào, tương cà và xì dầu.', 'Bày mì Yakisoba nóng hổi ra đĩa lớn, rắc rong biển vụn hoặc cá bào Katsuobushi lên trên và dùng kèm gừng hồng muối nếu thích.', 'Mì xào ngon nhất khi ăn nóng ngay; phần thừa cất hộp kín bảo quản tủ lạnh tối đa 2 ngày, khi ăn xào lại trên chảo lửa vừa với 1 muỗng canh nước cho sợi mì tơi mềm.', 'japanese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Yakisoba","Mì xào","Rau củ","Bữa trưa"]', '["lunch","dinner"]', '["stir_fry"]', '["egg","molluscs","pork","soybean","wheat"]', 696, 696.2, 2913, 18.3, 35.2, 11.3, 78, 6.7, 14.9, 1083, 2.71, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 167820","USDA FDC 168456","USDA FDC 169076","USDA FDC 169251","USDA FDC 169655","USDA FDC 169963","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172227","USDA FDC 174277"]', '1f7ac3d8a09a40ed8e13a6dcaf75402e8a8921de7f0c94891a80a18f628fabc1', '41e538533fe5ae45355bc83c858005d7670edb76368d904a958bebd5497ec8be', 4),
('imp-710fd476f2dddd56', 'com-trung-boc-omurice', 165, 'Cơm gà sốt cà chua bọc trứng Omurice', 'Cơm chiên thịt gà sốt cà chua đậm đà thơm mùi bơ lạt và hành tây, được bọc khéo léo trong lớp trứng chiên vàng mịn mượt chuẩn vị Yoshoku Nhật Bản', 'Omurice là món cơm bọc trứng nổi tiếng thuộc phong cách ẩm thực Yoshoku Nhật Bản. Hạt cơm tơi ráo xào thấm đều sốt cà chua ketchup, thịt đùi gà mềm ngọt và đậu xanh, bọc ngoài bằng lớp trứng rây mịn mềm ẩm tan chảy.', 'Úp ngược từng phần Omurice ra đĩa bầu dục cho phần mép gấp nằm gọn bên dưới, rưới hình zíc zắc chút tương cà lên mặt trứng vàng mịn và dọn ăn nóng.', 'Phần cơm gà chiên có thể bảo quản tủ lạnh 2 ngày hoặc đông lạnh 1 tháng; khi dùng chiên nóng lại cơm rồi mới tráng lớp trứng tươi bọc ngoài để giữ độ mềm ngon nhất.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 15, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Omurice","Trẻ em","Cơm chiên","Trứng gà"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry","assemble"]', '["chicken","egg","milk"]', 615, 614.8, 2572, 28.2, 28.7, 13.2, 59.5, 1.8, 11.7, 986, 2.47, '["USDA FDC 168878","USDA FDC 169076","USDA FDC 169961","USDA FDC 170000","USDA FDC 170931","USDA FDC 171287","USDA FDC 172227","USDA FDC 172385","USDA FDC 173430","USDA FDC 173468"]', '4cc3a30db55b7b54af699b819dc0011a47a8ef05b028178f583db8a142cb6233', 'cff17e56b24663e5169818f0ab2d357033e3922934e6799de6b0499f59eac1fd', 4),
('imp-14c8ef999fe47b8f', 'trung-cuon-tamagoyaki', 166, 'Trứng cuộn Nhật Bản Tamagoyaki', 'Khối trứng cuộn nhiều lớp vàng ươm vuông vức, ruột mềm ẩm béo nhẹ vị sữa tươi và hành lá, món trứng chuẩn hộp cơm bento Nhật', 'Tamagoyaki là món trứng cuộn nhiều lớp kinh điển của bữa sáng và hộp cơm bento Nhật Bản. Hỗn hợp trứng gà, chút sữa tươi, xì dầu, rượu mirin và hành lá được tráng thành từng lớp mỏng rồi cuộn chồng khéo léo tạo nên khối trứng mềm ẩm thơm dịu.', 'Thái khối trứng Tamagoyaki thành 6–8 khoanh dày khoảng 2 cm, xếp gọn ra đĩa dùng nóng với cơm trắng hoặc cho vào hộp cơm bento.', 'Có thể bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi ăn dùng ở nhiệt độ phòng kiểu bento hoặc quay lò vi sóng nhẹ 20 giây cho ấm mềm.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Tamagoyaki","Trứng cuộn","Bữa sáng","Hộp cơm"]', '["breakfast","lunch"]', '["pan_fry"]', '["egg","milk","soybean","wheat"]', 192, 192.1, 804, 12, 12, 3.4, 7.6, 0.3, 6.3, 650, 1.62, '["MEXT Hon-Mirin 16031","USDA FDC 169655","USDA FDC 170005","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '65a83094ac9b0049e0086dfa0581f2f4acdbb862349b136f8dbe992818678c59', '6538b3c7c9f54057148be93d16a3aa4f6d2a30e5f179532d0b333c3e381eed73', 4),
('imp-0841a517e823e3b6', 'ga-nuong-teriyaki-bong', 167, 'Đùi gà áp chảo sốt Teriyaki kiểu Nhật', 'Đùi gà lọc xương áp chảo da vàng giòn, thịt mềm mọng thấm đẫm nước sốt Teriyaki nâu bóng hương gừng tỏi đậm đà đưa cơm', 'Gà Teriyaki là món mặn trứ danh của ẩm thực Nhật Bản. Thịt đùi gà có da được khía nhẹ dàn đều độ dày rồi áp chảo giòn da, sau đó rưới sốt Teriyaki tự pha từ nước tương Nhật, rượu mirin, sake, đường cùng gừng tỏi cô sánh bóng đẹp.', 'Thái miếng đùi gà vừa ăn theo thớ ngang, xếp lên đĩa hoặc tô cơm nóng, rưới thêm vài muỗng sốt Teriyaki sóng sánh và dùng kèm bắp cải bào sợi hoặc bông cải xanh luộc.', 'Bảo quản thịt gà đã nguội cùng nước sốt trong hộp kín tủ mát tối đa 3 ngày; khi dùng hâm nóng lại trên chảo lửa nhỏ có thêm 1 muỗng canh nước để giữ độ mềm mọng.', 'japanese', 'mon_chien', NULL, 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Teriyaki","Thịt gà","Áp chảo","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["chicken","soybean","wheat"]', 488, 487.9, 2042, 40.5, 25.1, 6.4, 17.3, 0.4, 12.9, 1334, 3.34, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170931","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277"]', '9d58135b5ab116d5a1773801bb98e470fd5e6cf41d3c41e826398333dec7f385', '2845103596af3fb745831797a2e9e8aea88a0ba411b785ae46d2013f9c341c05', 4),
('imp-6ae7feae7ec0d517', 'ga-xien-yakitori-hanh', 168, 'Gà xiên nướng hành lá Yakitori', 'Xiên đùi gà xen kẽ hành lá nướng xém cạnh thơm lừng, quét nhiều lớp nước sốt tare đậm đà sánh bóng kiểu quán nướng Nhật Bản', 'Negima Yakitori là món gà xiên nướng trứ danh trong các quán izakaya Nhật Bản, kết hợp thịt đùi gà mềm mọng xen kẽ khúc hành lá ngọt thơm, được quét liên tục nước sốt tare cô đặc từ xì dầu, mirin, sake và đường nâu.', 'Dọn nóng từng xiên gà Yakitori vừa nướng xong ra đĩa dài, rắc thêm chút bột ớt 7 vị Shichimi Togarashi và dùng kèm nước chấm sốt tare chừa riêng.', 'Phần xiên thừa bảo quản hộp kín tủ mát tối đa 3 ngày; khi dùng làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C khoảng 6–7 phút và quét thêm chút sốt tare.', 'japanese', 'mon_lau_tiec', NULL, 'medium', 20, 35, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Yakitori","Đồ nướng","Thịt gà","Món nhậu"]', '["dinner"]', '["grill_roast","simmer"]', '["chicken","sesame","soybean","wheat"]', 367, 367.1, 1537, 31.3, 17.5, 4.6, 14.5, 0.9, 10.6, 1298, 3.24, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 168833","USDA FDC 170005","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', 'a47a22106838b7010d8fd321c0a962196f23352a4dc3bac3a1eefab823cd41d5', '7ea1502a4332f34d647777f6c3a31cedbc91837e644e103626946b38996e58b3', 4),
('imp-7facaaeafc40dac2', 'ca-hoi-nuong-muoi-chanh', 169, 'Cá hồi nướng muối chanh Shioyaki', 'Phi lê cá hồi ướp rượu sake và muối hạt kiểu Shioyaki truyền thống, nướng da giòn thịt mềm béo, dùng kèm củ cải trắng mài và chanh tươi', 'Shioyaki là phương pháp nướng cá với muối mộc mạc nhưng tinh tế của Nhật Bản. Cá hồi được xoa rượu sake và ướp muối hạt trong tủ lạnh để khử tanh, rút bớt nước thừa giúp thịt cá săn ngọt và phần da nướng giòn thơm.', 'Xếp cá hồi nướng nóng ra đĩa cùng ụ củ cải trắng mài nhuyễn vắt nhẹ nước, múi chanh tươi và hành lá thái nhỏ; dọn kèm cơm trắng nóng và canh miso.', 'Bảo quản cá nướng thừa trong hộp kín ngăn mát tối đa 2 ngày; khi ăn làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C trong 3–4 phút cho da giòn trở lại.', 'japanese', 'mon_chien', NULL, 'easy', 15, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Shioyaki","Cá hồi","Đồ nướng","Nhẹ bụng"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","salmon"]', 391, 391, 1635, 35.2, 25.2, 5.5, 3.5, 1.1, 1.3, 458, 1.15, '["MEXT Sake 16021","USDA FDC 168155","USDA FDC 168452","USDA FDC 170005","USDA FDC 171413","USDA FDC 173468","USDA FDC 175167"]', '5d758ce57af3d9bdf4d303bd2ab7a45be485b119e055089ee72588aa5d7a5d75', 'a2b8ae89724ede5f472c575ba75ff00e2ae22dc5a10bb8fda25f82cebf27951e', 4),
('imp-70379b3f30b48438', 'goi-dua-leo-tom-nhat', 170, 'Gỏi dưa leo tôm giấm Nhật Sunomono', 'Dưa leo thái lát mỏng bóp muối giòn sần sật trộn cùng tôm luộc ngọt thịt, rưới nước giấm gạo chua ngọt dịu và mè rang thơm bùi', 'Ebi Sunomono là món gỏi trộn giấm khai vị truyền thống thanh nhẹ của Nhật Bản. Dưa leo được ướp muối vắt ráo để giữ độ giòn lâu, kết hợp cùng tôm tươi luộc chín ngọt thịt và nước sốt giấm gạo pha xì dầu, đường và dầu mè thơm dịu.', 'Múc gỏi dưa leo tôm ra các chén thủy tinh nhỏ, rắc hạt mè trắng rang và hành lá lên trên, dùng lạnh làm món khai vị hoặc ăn kèm cá nướng, cơm chiên để chống ngấy.', 'Món ăn dùng lạnh, bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 1–2 ngày; không để lâu hơn vì dưa leo sẽ tiết nước làm nhạt vị sốt giấm.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Sunomono","Món gỏi","Khai vị","Thanh mát"]', '["lunch","dinner"]', '["toss_mix","boil"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 115, 115.3, 483, 13.2, 3.3, 0.5, 9, 1.1, 5.8, 563, 1.41, '["USDA FDC 168409","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171319","USDA FDC 172238","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', 'e97b0fcaee04dac6112648d5c65a030c6c6aa1e8fb72739cef679dbb9f0a1291', '94c9a1ef627b6711f2ca9183a51996dca248ff1d933ae8792fa7a451b3fa7013', 4),
('imp-49262ac40836045a', 'trung-hap-chawanmushi-ga', 171, 'Trứng hấp Chawanmushi thịt gà và nấm', 'Trứng hấp Chawanmushi trong chén sứ mềm mịn mượt mà như pudding mặn, nhân ức gà ướp sake, nấm đùi gà giòn ngọt và chả cá Nhật', 'Khác với phiên bản hải sản, Chawanmushi thịt gà và nấm tập trung vào vị ngọt thanh của nước dùng dashi kết hợp cùng ức gà mềm thơm ướp rượu sake, nấm đùi gà thái mỏng và lớp trứng đánh rây mịn màng không bọt khí.', 'Dọn nóng từng chén sứ Chawanmushi có nắp lên bàn ăn, rắc thêm hành lá thái nhỏ lên trên mặt trứng vàng mịn và thưởng thức bằng thìa nhỏ.', 'Nên ăn nóng ngay sau khi hấp; phần dư đậy kín nắp chén cất tủ mát tối đa 2 ngày và hấp cách thủy lửa nhỏ 3–4 phút cho nóng lại.', 'japanese', 'mon_hap_luoc', NULL, 'medium', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Chawanmushi","Món hấp","Thịt gà","Thanh đạm"]', '["breakfast","lunch","dinner"]', '["steam"]', '["chicken","egg","fish","soybean","wheat"]', 148, 148, 619, 16.6, 5.5, 1.6, 5.6, 0.6, 2.5, 1030, 2.57, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA / MEXT Fish Cake Ref","USDA FDC 169251","USDA FDC 170005","USDA FDC 171287","USDA FDC 171477","USDA FDC 173468","USDA FDC 174277"]', 'd2327976ce200739134df084c8009ca06909879a1aaca10bc7c98bb270109cb0', '5bb4a59497b9af8b027bd3b268454bfaa168ca3d7a19a571095c6e635b6cd6f7', 4),
('imp-e26d04bf95bcede8', 'mi-ramen-heo-trung', 172, 'Mì Ramen thịt xá xíu Chashu và trứng lòng đào', 'Tô mì Shoyu Ramen chuẩn vị Nhật với nước dùng hầm xương heo đậm ngọt, sợi mì dai ngon, thịt ba chỉ cuộn Chashu mềm tan và trứng ngâm tương Ajitama', 'Shoyu Ramen là món mì nước biểu tượng của Nhật Bản với nước dùng trong ngọt từ xương ống heo và rau củ thơm, kết hợp cùng nước sốt shoyu tare cô từ nước om thịt ba chỉ cuộn Chashu mềm béo và trứng lòng đào ngâm tương Ajitama.', 'Chan nước dùng nóng hổi vào tô đã lót sẵn shoyu tare, xếp gọn mì ramen trụng dai vừa, vài lát thịt Chashu béo mềm, nửa quả trứng lòng đào, hành lá thái nhỏ và lá rong biển Nori.', 'Nước dùng, thịt Chashu cuộn và nước sốt tare nguội có thể trữ hộp kín ngăn mát 3–4 ngày; khi ăn thái lát Chashu lạnh rồi thả vào tô nước dùng đang sôi nóng và luộc mì ramen mới ngay trước lúc dọn.', 'japanese', 'mon_bun_pho', NULL, 'hard', 30, 180, 4, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Mì Ramen","Chashu","Trứng lòng đào","Bữa tối"]', '["lunch","dinner"]', '["simmer","braise","boil"]', '["egg","pork","soybean","wheat"]', 837, 836.7, 3501, 27.6, 51.6, 18.5, 61.5, 2.6, 5, 1478, 3.69, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","Pork Bone Stock Extraction Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 167820","USDA FDC 168456","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 171287","USDA FDC 171401","USDA FDC 173647","USDA FDC 174277"]', 'dab2229616c9f004379a9b49cbf3d06d482bbe38f477853a55ac8cf704d31896', '4029f97b221fa950e52521203eab8bd16e75ef1fbf2100cd07da885f8a2fe42c', 4),
('imp-b808fb03d1e8ede6', 'com-ca-ri-ga-nhat', 173, 'Cơm cà ri gà Nhật', 'Sốt cà ri Nhật sánh mịn, ngọt dịu từ hành tây xào vàng ôm lấy thịt gà mềm, khoai tây và cà rốt ăn kèm cơm nóng', 'Cơm cà ri gà kiểu Nhật (Kare Raisu) có phần sốt sánh mịn, thơm nồng gia vị cà ri hòa quyện vị ngọt tự nhiên từ hành tây xào chín vàng, đùi gà mềm mọng cùng khoai tây và cà rốt bùi bở, chan cạnh cơm trắng dẻo nóng.', 'Xới cơm trắng dẻo ra một bên đĩa sâu lòng, múc cà ri gà nóng hổi sang nửa đĩa còn lại, rắc hành lá thái xéo và dọn kèm củ cải muối Fukujinzuke giòn chua ngọt.', 'Để cà ri nguội hoàn toàn rồi bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; khi ăn đun nóng lại trên lửa nhỏ, thêm chút nước dùng nếu sốt quá đặc.', 'japanese', 'mon_kho', NULL, 'easy', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Cà ri Nhật","Ẩm thực Nhật","Đùi gà","Cơm nhà","Bữa tối"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["chicken","soybean","wheat"]', 757, 757.2, 3169, 32.6, 25.6, 8.4, 96.8, 6.2, 8.8, 1818, 4.54, '["MEXT Curry Roux Ref","MEXT Takuan Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169756","USDA FDC 170000","USDA FDC 170005","USDA FDC 170026","USDA FDC 170393","USDA FDC 171413","USDA FDC 172227","USDA FDC 172385","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'ba7a5dc007cc688d4063a0d09dc13cd77241bf36ad658129f23649d3f3ce74b2', 'e2814039ae0669ad52efa307d6a76eead5bdbb5670e218aebd29392ed0563e9c', 4),
('imp-46c2a1c4cc7a8bb5', 'mi-udon-bo-hanh', 174, 'Mì Udon bò hành', 'Sợi mì Udon trắng dày dai mướt trong nước dùng Dashi thanh ngọt, phủ thịt bò xào hành tây đậm vị kiểu Nhật', 'Mì Udon bò hành (Niku Udon) kết hợp sợi Udon mềm dai cùng nước dùng Dashi trong thanh, ngọt dịu từ xì dầu và Mirin, điểm xuyết thịt bò thái lát mỏng xào nhanh với hành tây và gừng thơm nồng ấm bụng.', 'Chia mì Udon ra tô sâu lòng, chan ngập nước dùng Dashi nóng hổi, xếp thịt bò xào hành tây lên trên và rắc hành lá thái xéo cùng chút bột ớt 7 vị Shichimi.', 'Bảo quản riêng phần nước dùng, thịt bò xào và mì Udon chưa trụng trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nước dùng và thịt bò trước rồi mới trụng mì.', 'japanese', 'mon_bun_pho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Ẩm thực Nhật","Thịt bò","Mì nước","Bữa trưa"]', '["lunch","dinner"]', '["boil","pan_fry","assemble"]', '["beef","fish","sesame","soybean","wheat"]', 540, 539.7, 2258, 29.6, 14.5, 4.7, 64.6, 3.6, 15.1, 1858, 4.65, '["MEXT Boiled/Fresh Udon","MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', '90965f2cfa23deb65a626b4225d438607927280eb0bb57fe58ff888bdcb30471', 'ba027095e1e55e6f7352dcf61d557bfe4e5db9828f0684152d22818166c1586d', 4),
('imp-38fb8569664d1f3b', 'ca-hoi-ap-chao-bo-chanh', 175, 'Cá hồi áp chảo bơ chanh', 'Phi lê cá hồi da giòn rụm, thịt mềm mọng quyện sốt bơ lạt sủi bọt thơm tỏi, chanh tươi và xì dầu Nhật', 'Cá hồi áp chảo bơ chanh kiểu Meunière Nhật kết hợp lớp áo bột gạo thật mỏng giúp da cá giòn rụm, bên trong vẫn mềm hồng béo ngậy, rưới sốt bơ tan chảy hòa quyện nước cốt chanh tươi, tỏi phi và xì dầu thanh nhẹ.', 'Đặt miếng cá hồi mặt da hướng lên trên đĩa ấm, rưới đều phần sốt bơ chanh tỏi phi, rắc hành lá thái nhỏ và dùng nóng cùng cơm trắng hoặc măng tây áp chảo.', 'Món cá hồi áp chảo ngon nhất khi ăn ngay lúc da còn giòn; nếu dư, bọc kín bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 160°C trong 3 phút.', 'japanese', 'mon_chien', NULL, 'easy', 15, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Cá hồi","Áp chảo","Sốt bơ chanh","Ẩm thực Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["fish","milk","salmon","soybean","wheat"]', 425, 424.7, 1777, 29.4, 31.1, 10, 5.3, 0.5, 1.4, 635, 1.59, '["MEXT Hon-Mirin 16031","USDA FDC 168155","USDA FDC 169230","USDA FDC 169714","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175167"]', '750644319c464acf8e22200f3200bfdb3d4bf049abd9cffbddcdaa1b24af8616', 'da34e39aa1b07a4b6451f83e255f0b56b96f3f9e3d47623d7a9f45745d5223e2', 4),
('imp-eae128801c2c7f96', 'rau-bina-tron-me-nhat', 176, 'Rau bina trộn mè Nhật', 'Rau bina chần xanh mướt, vắt ráo nước trộn cùng mè trắng rang giã thơm với xì dầu, Mirin và dầu mè thanh dịu', 'Rau bina trộn mè Nhật (Horenso Goma-ae) là món rau phụ thanh mát quen thuộc trong mâm cơm Nhật, giữ trọn màu xanh ngọc mướt của cải bó xôi hòa quyện vị béo bùi của hạt mè trắng rang giã dập và sốt xì dầu ngọt dịu.', 'Bày rau bina trộn mè thành từng ụ nhỏ gọn đẹp mắt ra đĩa sứ nhỏ, rắc thêm chút hạt mè rang nguyên hạt lên trên và dùng mát hoặc ở nhiệt độ phòng kèm cơm nóng.', 'Cho rau bina trộn mè vào hộp đậy kín, bảo quản trong ngăn mát tủ lạnh tối đa 2 ngày; món ăn ngon khi dùng nguội mát, không nên hâm nóng lại.', 'japanese', 'mon_chay', NULL, 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Rau bina","Mè rang","Món chay","Ẩm thực Nhật","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["sesame","soybean","wheat"]', 135, 134.9, 564, 5.4, 8.7, 1.2, 11.5, 3.6, 5.2, 566, 1.42, '["MEXT Hon-Mirin 16031","USDA FDC 168462","USDA FDC 169655","USDA FDC 170150","USDA FDC 171028","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'bd3bdefa0cb87a9047432ba2b3ef597cff34c78233181890dc22fbcaa9e10ff6', 'ecdbc6a772a0fe966b6333837ad69614c6deb6b27724807d651a08e967472fac', 4),
('imp-56ec9eae817af509', 'bap-cai-tron-me-lanh', 177, 'Bắp cải trộn mè lạnh', 'Bắp cải và cà rốt thái sợi hấp nhanh giữ độ giòn ngọt, làm lạnh trộn cùng sốt mè rang giã thơm thanh mát', 'Bắp cải trộn mè lạnh kiểu Nhật kết hợp bắp cải xanh và cà rốt thái sợi hấp nhẹ chỉ với một ít nước nên giữ trọn vị ngọt giòn tự nhiên, trộn đều cùng sốt mè trắng rang giã dập, xì dầu, giấm gạo và dầu mè thơm bùi.', 'Múc bắp cải trộn mè đã làm lạnh ra đĩa sâu lòng hoặc bát nhỏ, rắc thêm hành lá thái nhỏ và một nhúm hạt mè rang nguyên hạt lên trên để dùng kèm các món mặn.', 'Đậy kín trong hộp bảo quản ở ngăn mát tủ lạnh dùng ngon trong 2–3 ngày; không hâm nóng để giữ độ giòn mát của rau.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Bắp cải","Mè rang","Món trộn","Ẩm thực Nhật","Thanh mát"]', '["lunch","dinner"]', '["steam","toss_mix"]', '["sesame","soybean","wheat"]', 158, 157.8, 661, 4.7, 9.1, 1.3, 17.3, 5.5, 9.5, 429, 1.07, '["USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 171028","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', 'af73b90f3bc99882c6bbb5f999734a75086d60ed66f61ad7a0f0514c746ad228', '0b80f38998999b896cbfc4a227174fc0fced6ce32cd6827e1f3a894ac05aa796', 4),
('imp-44b1338a7a49098d', 'canh-kimchi-dau-phu-han', 178, 'Canh kim chi đậu phụ kiểu Hàn', 'Nước canh hầm nóng hổi đậm vị kim chi ủ chua, thịt ba chỉ mềm thơm và đậu phụ trắng thanh mát trong nền nước dùng cá cơm tảo bẹ', 'Canh kim chi đậu phụ kiểu Hàn mang hương vị truyền thống với phần kim chi được xào kỹ cùng thịt ba chỉ cho dậy mùi thơm, hầm liu riu trong nước dùng cá cơm tảo bẹ ngọt thanh cùng hành tây, ớt bột Gochugaru và đậu phụ mềm mịn.', 'Múc canh nóng ra tô sâu lòng hoặc nồi đất, rắc hành lá thái vát lên mặt và dùng kèm cơm trắng dẻo nóng.', 'Canh nguội hẳn cho vào hộp kín bảo quản ngăn mát tối đa 3 ngày; khi ăn lại đun sôi trên lửa vừa 4–5 phút để hương vị hài hòa trở lại.', 'korean', 'mon_canh', NULL, 'easy', 15, 30, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Kim chi","Đậu phụ","Cơm nhà"]', '["lunch","dinner"]', '["simmer","stir_fry"]', '["fish","pork","sesame","soybean","wheat"]', 567, 567.2, 2373, 17.4, 48.9, 15.6, 16.9, 4.5, 7.9, 1781, 4.45, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468"]', '8e5d265493068fb0942e1f08c0a76df0fcec3af548fb2d5ac4b1f57be46c9eed', 'f30ff93b8748843604a1a2b1fd7a0224e7ff4b4eb62c2d48c5b2156052d9a288', 4),
('imp-a24a701c584d3ef3', 'com-tron-bibimbap-han', 179, 'Cơm trộn Bibimbap Hàn Quốc', 'Tô cơm trộn đủ sắc vị với thịt bò ướp xào mềm, giá đỗ, rau chân vịt, cà rốt, bí ngòi, nấm đùi gà, dưa leo, trứng ốp la và sốt Gochujang', 'Cơm trộn Bibimbap Hàn Quốc là bức tranh ẩm thực hài hòa năm sắc màu với cơm trắng dẻo nóng làm nền, xếp bên trên các loại rau củ sơ chế riêng giữ trọn độ giòn tươi, thịt bò thăn xào đậm vị, trứng gà ốp la và sốt tương ớt Gochujang cay ngọt.', 'Dọn mỗi tô cơm trộn nóng hổi kèm một phần sốt Gochujang riêng và chén canh rong biển hoặc kim chi; khi ăn trộn đều tất cả nguyên liệu với lòng đỏ trứng.', 'Có thể chuẩn bị sẵn các phần rau xào và thịt bò đựng hộp riêng trong ngăn mát tối đa 2 ngày; khi ăn chỉ cần làm nóng cơm và thịt bò rồi xếp lên tô, chiên trứng mới.', 'korean', 'mon_cuon_nom', NULL, 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Cơm trộn","Bibimbap","Đầy đủ dinh dưỡng","Thịt bò"]', '["lunch","dinner"]', '["boil","stir_fry","pan_fry","toss_mix"]', '["beef","egg","sesame","soybean","wheat"]', 672, 671.6, 2810, 30.6, 26, 6.2, 79.7, 6.2, 15.2, 1928, 4.82, '["MEXT Hon-Mirin 16031","USDA / Korean Gochujang Ref","USDA FDC 168409","USDA FDC 168462","USDA FDC 168580","USDA FDC 168878","USDA FDC 169230","USDA FDC 169291","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'eb15297647f4c6c2f6e9ed58514e1955ac5f3538a7439cd62b429aac045b0a63', '93cd09a34d76d75a293dc7fdb772956ac39ac7fd8fe1f1d8ab6850821876ffff', 4),
('imp-52b5963c6cecfb96', 'bo-nuong-bulgogi-ngot', 180, 'Bò nướng Bulgogi kiểu Hàn', 'Thịt bò thăn ngoại thái lát mỏng ướp xì dầu, mật ong, đường nâu và tỏi gừng nướng áp chảo xém cạnh thơm lừng', 'Bò nướng Bulgogi kiểu Hàn nổi bật với từng lát thịt bò thăn ngoại mềm ngọt, thấm sâu nước sốt ướp mặn ngọt dịu từ nước tương, mật ong, đường nâu và rượu ngọt Mirin, khi nướng áp chảo lửa lớn tạo lớp cạnh xém thơm quyến rũ.', 'Bày thịt bò nướng Bulgogi nóng ra đĩa, rắc hạt mè trắng rang và hành lá thái nhỏ; ăn kèm cơm trắng hoặc cuốn xà lách cùng kim chi.', 'Thịt bò ướp sống có thể để ngăn mát tối đa 24 giờ; thịt đã nướng chín bảo quản hộp kín trong tủ lạnh tối đa 2 ngày và hâm nhanh trên chảo nóng 2 phút.', 'korean', 'mon_lau_tiec', NULL, 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món nướng","Bulgogi","Thịt bò","Tiệc nướng"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["beef","sesame","soybean","wheat"]', 367, 366.7, 1535, 27, 20.1, 6, 18.9, 1.5, 14, 891, 2.23, '["MEXT Hon-Mirin 16031","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174277"]', '8730c296336bdc47bb20a3c9094b2aa57894fce500c49d9aa00c54371399dd98', 'df3ab1eaf3d9a4c50a69d686194fa741ea582782e441361304bf90a86b0ebbbf', 4),
('imp-51b6559bf09bc980', 'canh-tom-nau-bi-do', 181, 'Canh tôm nấu bí đỏ dẻo ngọt', 'Bí đỏ hầm bở dẻo hòa quyện vị tôm sú xào thơm tỏi và gừng sợi ấm bụng, tạo nên tô canh vàng sánh ngọt lành cho bữa cơm nhà', 'Khác với kiểu nấu nhanh giữ miếng, bí đỏ được ninh bở dẻo trên lửa nhỏ cùng nước dùng ngọt thanh từ tôm tươi xào tỏi gừng thơm nức, mang đến tô canh ấm áp sánh vàng dịu nhẹ.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và tiêu xay; dùng kèm cơm trắng nóng rất thích hợp cho bữa tối gia đình quây quần.', 'Để nguội rồi bảo quản hộp kín trong tủ mát tối đa 24 giờ; khi hâm lại nên khuấy đều nhẹ tay trên lửa nhỏ để phần bí bở dẻo không bén đáy nồi.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 22, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Bí đỏ","Bổ dưỡng","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 123, 123, 515, 13.4, 3.8, 0.6, 10.5, 0.9, 4.5, 1220, 3.05, '["USDA FDC 168448","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '2041006f1a05862ce58acbf14f87b75f3b06353f4187bbbd5d357b4580f57bda', '99fa6a307e0f3fa51bc9b4106c556b0468be4884cfb3828783be0704facdd8e9', 4),
('imp-81a203668e5e4c1a', 'canh-trung-nam-kim-cham', 182, 'Canh trứng nấm kim châm cà chua', 'Nấm kim châm giòn ngọt nấu cùng cà chua chua dịu và vân trứng gà đánh tơi vàng óng, món canh thanh nhẹ nấu nhanh 15 phút', 'Tô canh thanh nhẹ giàu chất xơ với nấm kim châm giòn sần sật ngọt nước, hòa quyện sắc đỏ dịu của cà chua chín và những sợi vân trứng gà mềm béo đẹp mắt.', 'Dọn canh nóng vào tô lớn ngay sau khi tắt bếp, rắc hành lá và tiêu xay lên trên; dùng kèm cơm trắng hoặc ăn nhẹ buổi tối đều rất ngon.', 'Món canh nấm trứng nên dùng hết ngay trong bữa để giữ độ giòn của nấm kim châm và vị béo mịn của trứng; hạn chế đun lại nhiều lần.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nấm","Dưới 20 phút","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish"]', 155, 155.4, 650, 8.7, 9, 2.1, 11.6, 3, 3.4, 1291, 3.23, '["USDA FDC 169230","USDA FDC 169253","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'a05dcd7ea953254e47a300d35e8f568a5e5bfaaad13abf2799055d5e50fd6ec3', 'aba3ea8c57d8b2d1a8cdc037a980773e1b3be5f2e36e6d0165c9af80a9ec2b9d', 4),
('imp-6c20dba60d77bdfd', 'canh-suon-su-su-non', 183, 'Canh sườn hầm su su non', 'Sườn non heo ninh mềm róc xương cho nước dùng trong ngọt đậm đà, kết hợp su su non giòn mát và cà rốt cho bữa cơm ấm áp cả nhà', 'Nồi canh ấm nóng quen thuộc với phần nước hầm sườn non trong veo, thịt sườn mềm ngọt róc xương quyện cùng su su non giòn mát và sắc cam dịu của cà rốt.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay lên mặt; dọn kèm cơm trắng và đĩa rau xào hoặc thịt kho đều rất tròn vị.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 24 giờ sau khi canh nguội hẳn; đun sôi lại ở lửa vừa vừa đủ nóng để su su không bị nhũn.', 'vietnamese', 'mon_canh', 'bac', 'easy', 15, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Sườn","Bổ dưỡng","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["fish","pork"]', 217, 217.4, 909, 11.8, 15.4, 5.7, 8.4, 2.7, 3.2, 955, 2.39, '["USDA FDC 167861","USDA FDC 169990","USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '63937bff019916ca3a26ac40fca38f3dc842e06ddab00ceab14eb4d6c1214fd5', '487849306d18ba65862c23c5e539cf677983581b7255c2482f662c51a992a8ec', 4),
('imp-734cc9acf8620c69', 'canh-dau-phu-ca-chua-trung', 184, 'Canh đậu phụ cà chua trứng', 'Món canh thanh nhẹ với đậu phụ non mềm mịn, cà chua chín đỏ au và vân trứng gà tơ vàng ươm đẹp mắt', 'Canh đậu phụ cà chua trứng có nước dùng đỏ cam tự nhiên, vị chua dịu hài hòa từ cà chua chín, miếng đậu phụ non béo mềm tan nhẹ cùng những sợi vân trứng gà vàng mịn thơm lừng.', 'Múc canh ra tô lớn khi còn nóng hổi, rắc thêm hành lá, ngò rí và chút tiêu xay; dùng kèm cơm trắng và các món mặn như cá kho hay thịt rang cháy cạnh.', 'Canh ngon nhất khi ăn nóng ngay sau khi nấu; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và hâm lại trên lửa vừa, tránh khuấy mạnh làm nát đậu phụ.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Đậu phụ","Thanh đạm","Nấu nhanh","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish","soybean"]', 126, 125.7, 526, 7.5, 7.6, 1.5, 7.5, 1.3, 3.8, 914, 2.28, '["USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172476","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '404ca5dfff64e388c6f15c91ed6b3a6f6000a30026a85fe2ec53de241654398b', '5b8312c83eef8c43ec0141f56e70e627883821f908fc5ab6dbd22f99c8b0c21f', 4),
('imp-095cff5e61d32fd9', 'canh-bo-ca-chua-ngot', 185, 'Canh bò cà chua ngọt', 'Nước canh đỏ cam ngọt thanh chua dịu hòa quyện cùng thịt bò thăn thái mỏng mềm ngọt và hương rau răm đặc trưng Nam Bộ', 'Canh bò cà chua ngọt là món canh cơm nhà giản dị nhưng đậm đà hương vị miền Nam. Thịt bò thăn thái mỏng ướp gia vị thấm mềm, nấu nhanh trong nước dùng cà chua đỏ au chua ngọt nhẹ, dậy mùi rau răm và hành lá.', 'Dọn canh nóng ngay khi thịt bò vừa chín tới, ăn kèm cơm trắng nóng dẻo hoặc chan cùng bún tươi và chén nước mắm ớt cắt lát.', 'Nên ăn hết trong bữa để thịt bò giữ được độ mềm ngọt; nếu bảo quản tủ mát tối đa 24 giờ, nên vớt riêng phần thịt bò, đun sôi nước canh trước rồi mới thả bò vào làm nóng nhanh 30 giây.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Cà chua","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["beef","molluscs","soybean","wheat"]', 228, 227.7, 953, 19.8, 12.9, 4.1, 8.4, 2.1, 5.1, 872, 2.18, '["USDA FDC 169655","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN Culinary Herb Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', '452c7247d0b39e6d665b86c44d791244f6e1dc1934d1369f65c9e066338343bd', '07b8bd99f7781a6698e96a5e935439890315ed53448241539a561e613643415e', 4),
('imp-a4822c0a1187e4d7', 'suon-nuong-muoi-ot', 186, 'Sườn nướng muối ớt', 'Sườn non ướp muối hạt, ớt hiểm, tỏi và nước mắm ngon nướng vàng xém cạnh, chấm muối ớt chanh chua cay thơm lừng', 'Những khúc sườn non nhiều thịt mềm ngọt được ướp đậm đà vị mặn mà của muối hạt, cay nồng từ ớt hiểm tươi và tỏi băm, nướng chín vàng xém cạnh ăn kèm nước chấm chanh ớt.', 'Bày sườn nướng ra đĩa lớn, dọn nóng cùng cơm trắng, dưa leo, rau sống và chén nước mắm chanh ớt tiêu cay thơm.', 'Bảo quản sườn đã nướng trong hộp kín ở ngăn mát tối đa 2 ngày; khi dùng làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C khoảng 5 phút.', 'vietnamese', 'mon_kho', 'toan_quoc', 'medium', 20, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Sườn nướng","Muối ớt","Cuối tuần","Món mặn","Đưa cơm"]', '["lunch","dinner"]', '["grill_roast","boil"]', '["fish","pork"]', 456, 456.2, 1909, 21.2, 35.5, 11.9, 12.4, 0.6, 9.9, 1185, 2.96, '["USDA FDC 167861","USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647"]', 'b97eed0b515685b9f9d19cbda6470dde8cadc3c88f46f4d3aa97ba7c2f512690', 'c3ce6641b40e010029458ae894dcd6e3917fcb51f630cef85dc2ab93667ead2d', 4),
('imp-04514fa34052d242', 'ga-kho-nam-dam', 187, 'Gà kho nấm đùi gà đậm vị', 'Đùi gà áp chảo vàng thơm kho cùng nấm đùi gà dai giòn và nấm hương khô trong nước sốt xì dầu, dầu mè đen và đường phèn sóng sánh', 'Thịt đùi gà áp chảo săn chắc kho quyện hương thơm đặc trưng của dầu mè, nấm hương khô ngâm nở và nấm đùi gà dai ngọt tự nhiên, nước kho sánh nâu đậm vị.', 'Múc gà kho nấm ra đĩa sâu lòng, rắc hành lá và cần tây lên trên, dùng nóng cùng cơm trắng dẻo và rau luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ, thêm 1 muỗng nước lọc để sốt sánh mượt trở lại.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Nấm đùi gà","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["celery","chicken","fish","molluscs","sesame","soybean","wheat"]', 393, 392.9, 1644, 31.7, 22.8, 5.3, 16.1, 2.5, 5.3, 1250, 3.13, '["Dark Soy Sauce Label Ref","USDA FDC 168436","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169988","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', '91f0a4b48bd00a6551b8369fb231d9040def327f4d9a149bde98ae0ae89e3056', '793dba71a342f0cdade36aaf3f3b37167f65606157a9492993c3a95920e89d74', 4),
('imp-695f59248dbf4895', 'ca-kho-gung-sa', 188, 'Cá kho gừng sả miền Trung', 'Cá lóc cắt khoanh chiên sơ kho liu riu cùng sả băm, gừng giã nhuyễn và ớt cay nồng, thấm vị mặn ngọt đậm đà chuẩn cơm nhà miền Trung', 'Khúc cá lóc chiên săn chắc thịt kho thấm vị nước mắm ngon, thơm nồng mùi sả băm, gừng giã dập phi vàng và vị cay ấm đặc trưng từ ớt bột cùng ớt tươi miền Trung.', 'Gắp cá ra đĩa sâu lòng, rưới phần nước kho sánh thơm sả gừng và rắc hành lá thái nhỏ; dùng nóng với cơm trắng dẻo.', 'Bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại trên lửa nhỏ cùng 1–2 muỗng canh nước sôi.', 'vietnamese', 'mon_kho', 'trung', 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Cá kho","Miền Trung","Gừng sả","Món kho","Đưa cơm"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["fish"]', 273, 272.6, 1140, 30, 10.7, 2, 13.6, 0.8, 7.8, 1440, 3.6, '["USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '9d3d29042fcbf059eb01e3d54b56bc787082b58290a45f50ab157e52927abbb0', '4a455f9e48c34219624378b5c79b8f202077af5185a0e556a504cb4826e43ea5', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-208386f834b8da43', 'trung-kho-tuong-keo', 189, 'Trứng gà kho nước tương sánh keo', 'Trứng gà luộc lòng chín tới chiên xém nhẹ rồi kho liu riu trong sốt nước tương, hắc xì dầu và ngũ vị hương sánh bóng đậm đà', 'Những quả trứng gà thấm đẫm nước sốt nước tương và xì dầu đặc sánh kẹo màu nâu bóng đẹp mắt, phảng phất mùi thơm dịu của ngũ vị hương, hành tỏi phi và tương ớt cay nhẹ.', 'Cắt đôi hoặc để nguyên quả trứng bày ra đĩa sâu lòng, rưới phần sốt keo bóng cùng hành lá, ngò rí và tiêu xay; ăn nóng với cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi ăn hâm lại trên lửa nhỏ cùng 1 muỗng nước ấm để sốt sánh nóng đều.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Trứng kho","Nước tương","Nhanh gọn","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","boil","pan_fry"]', '["egg","soybean","wheat"]', 278, 278.4, 1165, 17.7, 18, 4.7, 11.4, 1.2, 6.8, 1739, 4.35, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC Sriracha Ref"]', '633ef7c2e0d459d46761a5256c050b97805bf74c3dd453a4fbc0b31c5fad6d81', '6f6e5e3801a551e2dc7fcbc2024acde4f7559596b1eb0acd6cb28fb0860dbecf', 4),
('imp-d1f8ab89051a6336', 'bong-cai-xao-tom-tuoi', 190, 'Bông cải xào tôm tươi', 'Bông cải xanh và cà rốt giòn ngọt xào lửa lớn cùng tôm tươi cong hồng, áo sốt sánh nhẹ thơm mè trắng rang', 'Đĩa bông cải xào tôm tươi hài hòa giữa sắc xanh mướt của súp lơ, cam tươi của cà rốt và vị ngọt săn chắc từ tôm tươi, được bao bọc bởi lớp sốt bột bắp sánh bóng thơm dịu dầu mè và mè trắng rang.', 'Trình bày bông cải xào tôm tươi ra đĩa rộng, rắc mè trắng rang và tiêu đen xay; dùng nóng cùng cơm trắng và nước tương ớt.', 'Món xào ngon nhất khi ăn ngay lúc vừa hoàn thành; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, đảo nóng nhanh trên chảo lửa lớn trong 1 phút trước khi dùng.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Rau xanh","Giàu chất xơ","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["crustaceans","fish","sesame","shrimp"]', 196, 195.7, 819, 16.7, 9.3, 1.4, 13.7, 3.4, 3.5, 1077, 2.69, '["USDA FDC 169230","USDA FDC 169698","USDA FDC 170000","USDA FDC 170150","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'e79164017f41fe11823c366609946912a3c75c4a2deee68d71e1527d08570143', '444f7401efc8c125f35e4aa74cdbc538e2e4d61ff064a1b84660aa6ae28b597f', 4),
('imp-03c5e6e31e01088d', 'dau-phu-xao-sa-ot', 191, 'Đậu phụ xào sả ớt', 'Đậu phụ chiên vàng giòn cạnh xào thấm sốt sả ớt cay thơm đậm vị nước tương và tương ớt, món chay mặn đều ngon', 'Đậu phụ xào sả ớt kiểu Nam Bộ hấp dẫn với lớp vỏ đậu vàng giòn bên ngoài nhưng bên trong vẫn béo mềm, quyện đẫm phần sốt sả băm thơm lừng, vị cay nồng của ớt và mặn ngọt sánh nhẹ từ nước tương, dầu hào chay và tương ớt.', 'Xếp đậu phụ xào sả ớt ra đĩa, rắc thêm chút tiêu đen xay và vài lát ớt sừng; ăn nóng với cơm trắng hoặc bún tươi đều rất bắt vị.', 'Bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi dùng làm nóng lại trên chảo chống dính ở lửa vừa khoảng 2–3 phút để đậu nóng đều.', 'vietnamese', 'mon_xao', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Món chay","Đậu phụ","Sả ớt","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["soybean","wheat"]', 264, 264.4, 1106, 17.4, 18.3, 2.7, 12.7, 1.8, 4, 601, 1.5, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277","USDA FDC Sriracha Ref","Vegan Mushroom Sauce Ref"]', '84cb2d06f15fbe550b3b52420cbedba20dfc94ac2e3c040504ec1af553e45f1c', '8f8ec8d7b59df4044a4c252afae195f6ceed7eec0e8ad986ed57ba648fced937', 4),
('imp-2862e7aa0ae0d8fe', 'bo-xao-dua-chua-ngot', 192, 'Bò xào dứa chua ngọt', 'Thịt thăn bò mềm mọng quyện vị chua ngọt thanh dịu từ dứa chín tươi và hành tây giòn thơm kiểu Nam Bộ', 'Bò xào dứa chua ngọt là món ăn cực kỳ bắt cơm với thịt thăn bò mềm tan nhờ enzyme tự nhiên từ dứa tươi, kết hợp cùng hành tây giòn ngọt và nước sốt dầu hào nước mắm đậm đà hương vị Nam Bộ.', 'Múc bò xào dứa ra đĩa rộng khi còn bốc khói, rắc tiêu đen xay lên mặt; ăn nóng kèm cơm trắng và nước tương ớt.', 'Món xào ngon nhất khi ăn ngay lúc vừa nấu xong vì dứa tiết nước theo thời gian; nếu bảo quản tủ mát trong ngày, hâm nóng nhanh trên chảo lửa lớn khoảng 1 phút.', 'vietnamese', 'mon_xao', 'nam', 'easy', 18, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Chua ngọt","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","fish","molluscs","soybean","wheat"]', 347, 347, 1452, 22.6, 19.1, 5.4, 22, 2.3, 14.2, 1518, 3.8, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'ab41d359bac6f6e05c8e07d2099c9d1aa66b4b06bfb1953127882b4f28c08c23', '95f88171ea5f667701fd53ddee30d00456b478dcb1ccf1883a8f71305b99335e', 4),
('imp-aa94e2f8bdf3985f', 'tom-hap-sa-chanh', 193, 'Tôm hấp sả lá chanh thơm nồng', 'Tôm sú tươi hấp nhanh cùng sả cây, lá chanh, gừng và rượu trắng rồi rưới tỏi phi vàng thơm lừng chấm muối chanh ớt', 'Tôm sú tươi giữ nguyên vị ngọt giòn tự nhiên khi hấp nhanh cùng sả đập dập, lá chanh thơm mát, gừng lát và chút rượu trắng khử tanh, phủ thêm lớp tỏi phi vàng giòn dậy mùi hấp dẫn.', 'Xếp tôm đỏ au ra đĩa lớn, rưới đều tỏi phi thơm lừng lên thân tôm và dọn nóng chấm kèm muối tiêu chanh ớt.', 'Món tôm hấp ngon nhất khi thưởng thức nóng ngay. Nếu còn dư, bóc vỏ bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh 2 phút trong chảo hoặc xửng hấp.', 'vietnamese', 'mon_hap_luoc', 'nam', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Tôm","Sả","Mát lành","Dưới 20 phút"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","shrimp","sulphites"]', 173, 172.6, 723, 26.9, 4.9, 0.8, 5.5, 0.7, 0.5, 1042, 2.61, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '531bbb31623f716fc61b5a5866635514f54845c55df2d304ff262879ced5133b', '0acf80870c6058c1cbc2a425942ea08b8fa410da196a410d299fceff90973d88', 4),
('imp-b55451e6e46a4c13', 'bap-cai-cuon-hap-thit', 194, 'Bắp cải cuộn thịt hấp thanh ngọt', 'Lá bắp cải chần mềm cuộn nhân thịt heo xay, mộc nhĩ và cà rốt hấp chín tới ngọt thanh đẹp mắt chuẩn vị Bắc Bộ', 'Những cuộn bắp cải xanh mướt căng tròn ôm lấy phần nhân thịt heo xay quyện mộc nhĩ giòn sần sật và cà rốt ngọt dịu, buộc cố định bằng cọng hành lá chần mềm; hấp cách thủy giữ trọn vị ngọt tự nhiên.', 'Xếp các cuộn bắp cải hấp nóng hổi ra đĩa sâu lòng, rưới ít nước ngọt tiết ra khi hấp cùng tiêu xay; ăn kèm cơm nóng và chấm nước tương ớt hoặc nước mắm tỏi ớt.', 'Có thể bảo quản cuộn bắp cải đã hấp chín trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hấp lại 6–8 phút đến khi phần nhân thịt nóng đều.', 'vietnamese', 'mon_hap_luoc', 'bac', 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Bắp cải","Khéo tay","Món Bắc","Thanh đạm"]', '["lunch","dinner"]', '["steam","boil"]', '["fish","pork"]', 246, 246.1, 1030, 14.9, 16.1, 6, 11.3, 5.5, 3.8, 665, 1.66, '["USDA FDC 167902","USDA FDC 168437","USDA FDC 169230","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '59821506f7edc893591174184c94561c8664ef657df563707620d80a1cdb5ea2', 'b5cc87c231c52e0bb60b2639514978ee14bd932f3c0c419bffeca00442d344de', 4),
('imp-500644420438efd3', 'dau-phu-hap-sa', 195, 'Đậu phụ hấp sả xì dầu thanh đạm', 'Đậu phụ trắng mềm mịn hấp cùng sả băm xào thơm và xì dầu đậm đà, điểm hành lá dầu mè nhẹ bụng cho bữa tối', 'Đậu phụ non mịn hấp cách thủy cùng nước sốt xì dầu đậm dịu và sả xào vàng thơm lừng, giữ trọn vị béo bùi tự nhiên của đậu nành, ít dầu mỡ và rất dễ tiêu hóa.', 'Dọn nóng nguyên đĩa đậu phụ hấp sả ra bàn, rưới thêm chút xì dầu pha ớt nếu thích đậm vị, ăn kèm cơm trắng nóng.', 'Món đậu phụ hấp ngon nhất khi dùng nóng ngay trong bữa để đậu mềm mọng không bị xốp rỗ; nếu còn dư, bảo quản ngăn mát tối đa 24 giờ rồi hấp lại 4 phút.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Đậu phụ","Thanh đạm","Dễ nấu","Món chay"]', '["lunch","dinner"]', '["steam"]', '["sesame","soybean","wheat"]', 179, 178.8, 748, 13.3, 12.4, 1.8, 7.2, 1.5, 2.1, 856, 2.14, '["USDA FDC 168573","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'c65c15a06decc2ab7f448d9daca352fcf5f5dfa58a23741b7709fe2e9e645941', 'b791bcdf2b9a34e5a54b2300d4e171e02d11665f245d578d5234ad7acc1b4a69', 4),
('imp-47cbfe72125b811d', 'goi-bo-dua-leo-chanh', 196, 'Gỏi bò dưa leo chanh', 'Thịt bò thăn xào lửa lớn mềm mọng quyện dưa leo bỏ ruột giòn mát, cà rốt, hành tây trong nước trộn mắm chanh tỏi ớt chua cay cuốn hút', 'Gỏi bò dưa leo chanh kết hợp tinh tế giữa thịt bò thăn xào tỏi thơm mềm mọng, từng sợi dưa leo và cà rốt giòn ngọt, hành tây thanh dịu và nước trộn mắm chanh ớt hiểm đậm đà, điểm xuyết đậu phộng rang bùi béo và rau thơm.', 'Bày gỏi bò ra đĩa, rắc phần đậu phộng rang giã dập còn lại và ớt thái lát lên mặt; dọn ăn ngay kèm bánh phồng tôm.', 'Thịt bò xào nên trộn và dùng ngay khi còn tươi giòn; nếu chuẩn bị trước, để riêng phần rau củ vắt ráo và nước trộn trong ngăn mát tủ lạnh, chỉ xào bò và trộn gỏi ngay trước bữa ăn.', 'vietnamese', 'mon_cuon_nom', 'nam', 'medium', 25, 10, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi bò","Dưa leo","Chua cay","Khai vị","Đãi tiệc"]', '["lunch","dinner"]', '["stir_fry","toss_mix"]', '["beef","fish","peanut"]', 396, 396.4, 1659, 26.9, 23.5, 5.9, 21.9, 4, 12.6, 1308, 3.27, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","VN/Asian Seasoning Powder Avg"]', '4f86934f4a69d3c316cab17b266fd72d3de2647e88c25e4bf063057535a7bf9c', '98b349cae6bf53d394c293a4c0b50eed9d340dd60fb3cf12bcf6cfed58ec40f2', 4),
('imp-403a1693ea9b3cf8', 'bun-tom-rau-muong-chua-cay', 197, 'Bún tôm rau muống chua cay', 'Nước dùng xương heo nấu me, dứa, cà chua và sa tế chua cay bắt vị, ăn kèm tôm tươi giòn ngọt, bún tươi và rau muống chẻ thanh mát', 'Bún tôm rau muống chua cay mang đậm hương vị Nam Bộ dễ ăn với nước dùng ngọt xương hòa vị chua dịu từ me vắt, thơm dịu từ dứa và cà chua, thêm chút sa tế cay nồng ăn cùng tôm tươi và rau muống chẻ giòn.', 'Trụng bún và xếp tôm chín lên tô cùng rau muống chẻ, chan nước dùng chua cay nóng hổi, rắc hành phi, hành lá, ngò rí, tiêu xay rồi vắt thêm chanh và ớt tươi tùy thích.', 'Bảo quản nước dùng riêng trong ngăn mát tối đa 24 giờ; khi ăn đun sôi nước dùng, thả tôm và rau muống chẻ vào trụng nóng rồi chan lên bún mới.', 'vietnamese', 'mon_bun_pho', 'nam', 'easy', 25, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Bún tôm","Chua cay","Rau muống","Nam Bộ"]', '["breakfast","lunch","dinner"]', '["simmer","stir_fry","boil","assemble"]', '["crustaceans","fish","pork","shrimp"]', 593, 592.5, 2478, 28, 16, 3, 89, 7, 24.5, 2309, 5.77, '["Annatto Infused Oil Ref","Chili Oil / Satay Ref","NIN VN Fresh Bun Ref","Pork Bone Stock Extraction Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169124","USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 169918","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'e9de5b0409df62333527716d2d92fb447f86979c841d3a3abd446cb34a4dd146', '16430058b635bd4a35dd83d399987897a4f649f4a2b3cd4a0e902df45f6fb939', 4),
('imp-c039dac37b31acdb', 'mi-quang-ga-ta', 198, 'Mì Quảng gà ta', 'Sợi mì Quảng dẻo thơm quyện nước nhân gà ta kho nghệ sánh vàng óng, ăn kèm đậu phộng rang giòn, bánh đa nướng và đĩa rau sống miền Trung', 'Mì Quảng gà ta chuẩn vị Quảng Nam với phần nước nhân nấu vừa xâm xấp đậm đà hương nghệ, hành tím và sả phi dầu, thịt gà ta săn mềm thấm vị, ăn cùng rau sống chín tầng, đậu phộng rang và bánh đa bẻ giòn.', 'Lót xà lách, giá đỗ, húng lủi và bắp chuối bào dưới đáy tô, xếp mì Quảng và thịt gà lên trên, chan nước nhân vừa xâm xấp mặt mì, rắc đậu phộng rang, hành lá và ăn kèm bánh đa nướng cùng nước mắm tỏi ớt.', 'Phần thịt gà và nước nhân bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nồi nước nhân và trụng mới mì Quảng để sợi mì không bị bở.', 'vietnamese', 'mon_bun_pho', 'trung', 'medium', 30, 55, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Quảng","Gà ta","Ẩm thực miền Trung","Đặc sản"]', '["breakfast","lunch","dinner"]', '["braise","simmer","assemble"]', '["chicken","fish","peanut"]', 817, 817.1, 3420, 40.5, 38.7, 8.9, 78.5, 7.4, 9.3, 2019, 5.05, '["Annatto Infused Oil Ref","NIN VN Fresh Pho Noodle Ref","SE Asian Banana Blossom Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","VN Banh Da Ref","VN/Asian Seasoning Powder Avg"]', '9f17cf267d185684b3c494bdf44f7fdbaa9442a870a9d084fcee1fdf19b74f49', '9eb26db39154ec9eee7fc2616aac82b571b0401950ff3d36bf1d30bfd1261eac', 4),
('imp-875e99916a13d031', 'pho-chay-nam-dau', 199, 'Phở chay nấm đậu', 'Nước dùng rau củ hầm củ cải trắng, cà rốt và hành gừng nướng thơm thoang thoảng quế hồi thảo quả, ăn cùng đậu phụ chiên vàng và nấm đùi gà xào đậm đà', 'Phở chay nấm đậu thanh tịnh nhưng vẫn đậm đà tròn vị nhờ nước dùng hầm củ cải trắng, cà rốt, hành tây nướng và gia vị phở truyền thống, kết hợp đậu phụ chiên vàng giòn và nấm đùi gà xào ngũ vị hương thơm lừng.', 'Xếp bánh phở, giá đỗ trụng và nấm đậu xào lên tô, chan ngập nước dùng chay sôi nóng, rắc hành lá, ngò gai và thưởng thức cùng húng quế, chanh tươi và tương đen.', 'Nước dùng rau củ bảo quản ngăn mát 2–3 ngày; đậu phụ và nấm nên xào nóng lại trên chảo trước khi chan nước dùng sôi lên bánh phở mới.', 'vietnamese', 'mon_bun_pho', 'toan_quoc', 'medium', 25, 50, 4, '/frigo/illustrations/delicious-meal.png', '["Phở chay","Thanh đạm","Nấm đậu","Món nước"]', '["breakfast","lunch","dinner"]', '["simmer","pan_fry","stir_fry","assemble"]', '["sesame","soybean","wheat"]', 448, 447.9, 1875, 18.2, 12, 1.8, 71.9, 6.8, 12.4, 1930, 4.83, '["Five Spice USDA Ref","NIN VN Fresh Pho Noodle Ref","USDA FDC 168155","USDA FDC 168452","USDA FDC 168580","USDA FDC 169231","USDA FDC 169963","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170919","USDA FDC 170931","USDA FDC 171316","USDA FDC 171320","USDA FDC 171370","USDA FDC 171413","USDA FDC 172232","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref","VN Culinary Herb Ref","Vegetarian Seasoning Powder Ref"]', '467f53dad9f593c5b95b73083cd57d71bb42c3aef34d62b4ae192d87cf4e82c4', '74a2d85da074e50d87e28c13276b779ccaf37313d9c08196b97a4ec534b1d0e2', 4),
('imp-389f525ea854b373', 'canh-chua-chay-dua-dau', 200, 'Canh chua chay dứa đậu phụ Nam Bộ', 'Nồi canh chua thanh mát chuẩn vị Nam Bộ với nước cốt me, dứa chín, cà chua, đậu bắp, bạc hà và đậu phụ mềm béo', 'Bát canh chua chay Nam Bộ thanh tao đậm đà với sự hòa quyện cân bằng giữa vị chua dịu từ me chín, ngọt thơm của dứa chín, sắc đỏ của cà chua cùng đậu phụ béo mềm, đậu bắp, dọc mùng và giá đỗ giòn tươi.', 'Múc canh nóng ra tô lớn, rắc rau ngổ, ngò gai thái nhỏ lên trên; dùng kèm cơm trắng nóng hoặc bún tươi đều rất hợp vị.', 'Canh ngon nhất khi dùng hết trong ngày để giữ độ giòn của đậu bắp, dọc mùng và giá đỗ; nếu để sang ngày hôm sau nên vớt riêng rau và đun sôi lại phần nước canh trước khi ăn.', 'vietnamese', 'mon_chay', 'nam', 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món chay","Canh chua","Nam Bộ","Thanh nhiệt","Đậu phụ"]', '["lunch","dinner"]', '["simmer"]', '["soybean"]', 204, 204, 853, 12, 8.4, 1.2, 25.1, 4.8, 15.4, 717, 1.79, '["NIN VN Doc Mung Ref","USDA FDC 169124","USDA FDC 169246","USDA FDC 169260","USDA FDC 169655","USDA FDC 169918","USDA FDC 169963","USDA FDC 170457","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN Herb Ref","Vegetarian Seasoning Powder Ref"]', '12b4dcea26bcfa995936dce6b4f2fbef435d9466ddc044ca2a54229108eb576a', 'f0092dac3c2e4aec79902132e4cd0f6c53955fd92379e6d0d014aa6ca115c91f', 4),
('imp-8301ed8c884fb619', 'cai-bap-xao-nam-chay', 201, 'Bắp cải xào nấm đùi gà chay', 'Bắp cải giòn ngọt xào nhanh lửa lớn cùng nấm đùi gà thái lát, lá hẹ xanh thơm và xì dầu đậm vị', 'Món xào chay thanh đạm mà đưa cơm với lá bắp cải trắng giòn ngọt tự nhiên kết hợp nấm đùi gà dai sần sật, thấm nhẹ nước tương, hương tỏi phi và mùi thơm đặc trưng của lá hẹ xanh tươi.', 'Trút bắp cải xào nấm ra đĩa rộng khi còn nóng hổi, rắc tiêu xay lên mặt và dùng kèm cơm trắng nóng hoặc chấm thêm chén nước tương ớt.', 'Món rau xào nên dùng hết trong bữa để giữ trọn độ giòn của bắp cải; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo nóng.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Bắp cải","Nấm đùi gà","Nhanh gọn"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["soybean","wheat"]', 145, 144.6, 606, 5.2, 7.9, 1.2, 15.8, 5.1, 6.7, 1106, 2.77, '["MEXT Sake 16021","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 169994","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'baac2cf3d31ec51e23e709b1cf7561f5278a1d47a5cdb261e3b395aec9dfc949', '7d8b42b23f606da4fe5747f357c9954b23c2f4374b27165a659bb64fc95e3d1f', 4),
('imp-327ffa644fbe1a7d', 'chao-tom-nam-nong', 202, 'Cháo tôm nấm đùi gà nóng', 'Cháo gạo rang sánh mịn ngọt tự nhiên từ tôm tươi và nấm đùi gà xào thơm, điểm gừng sợi và hành lá ấm bụng', 'Tô cháo tôm nấm nóng hổi sánh mượt với gạo tẻ kết hợp chút gạo nếp rang thơm, thịt tôm tươi săn ngọt đậm đà cùng nấm đùi gà giòn sần sật, gừng tươi thái chỉ và hành lá thơm dịu.', 'Múc cháo nóng ra tô, xếp phần tôm và nấm đùi gà xào lên mặt cùng hành lá, ngò rí, gừng thái sợi và tiêu đen xay rồi dùng ngay.', 'Nên thưởng thức ngay khi còn nóng. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi hâm lại trên lửa nhỏ cần thêm chút nước sôi và khuấy đều tránh cháy đáy.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 28, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo tôm","Nấm đùi gà","Ăn sáng","Thanh ngọt","Ấm bụng"]', '["breakfast","dinner"]', '["boil","simmer","stir_fry"]', '["crustaceans","fish","shrimp"]', 245, 245.2, 1026, 13.1, 3.8, 0.6, 39.3, 1.8, 1.7, 908, 2.27, '["USDA FDC 168881","USDA FDC 169231","USDA FDC 169251","USDA FDC 169756","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '488d7220d7809772762d5ca6740c06e91451c4229bfdd573b4c31ce5c0dc034d', 'd4d55596ad7651e07cef5a3ea0cb1d93f74be009008ece862ed455e110c1edc4', 4),
('imp-9aed26098f07c061', 'trung-duc-thit-bam', 203, 'Trứng đúc thịt bằm', 'Trứng gà đánh bông chiên lửa nhỏ cùng thịt heo xay, hành tím và hành lá chín vàng xốp mềm đậm đà', 'Món trứng đúc thịt bằm dân dã quen thuộc trong mọi mâm cơm Việt với lớp vỏ ngoài vàng ươm thơm phức, phần nhân bên trong bông mềm ẩm mượt quyện thịt heo nạc vai xay, hành tím phi và hành lá xanh tươi.', 'Cắt trứng đúc thịt thành từng miếng tam giác hoặc miếng vuông vừa ăn, bày lên đĩa nóng cùng rau sống dưa leo và thưởng thức với cơm trắng nóng chấm tương ớt.', 'Ngon nhất khi ăn nóng ngay sau khi chiên. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 2 ngày và hâm nóng lại bằng chảo đậy nắp 3 phút trên lửa nhỏ hoặc lò vi sóng.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Trứng đúc thịt","Cơm nhà","Nhanh gọn","Giàu đạm","Bé thích"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","fish","pork"]', 280, 280.1, 1172, 17.4, 21.8, 6.7, 2.8, 0.5, 1.1, 836, 2.09, '["USDA FDC 167902","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'a10da70bc157094694b8aca694528fb66ef3fd150c707af96c73160dd6f4e095', '3af9544b49dfab4c3f221abbc0f1d8dddc52d02a7f87baa8c09a1d3a837aa652', 4),
('imp-24e75cbb2ba569f4', 'banh-trang-tron-rau-cu', 204, 'Bánh tráng trộn rau củ', 'Bánh tráng gạo cắt sợi dai mềm trộn bắp cải, cà rốt bào giòn cùng sốt nước tương chanh ớt chua cay mặn ngọt', 'Món bánh tráng trộn rau củ chuẩn vị Sài Gòn phiên bản thanh mát với sợi bánh tráng dẻo dai vừa độ, bắp cải và cà rốt bào giòn, rau răm thơm nồng quyện mỡ hành béo nhẹ, đậu phộng rang giòn bùi và sốt nước tương chanh ớt.', 'Cho bánh tráng trộn rau củ ra đĩa ngay khi vừa trộn xong, rắc thêm đậu phộng rang và rau răm lên trên rồi thưởng thức liền để bánh không bị nhũn.', 'Chỉ trộn ngay trước lúc ăn để bánh tráng giữ độ dẻo dai và rau củ còn giòn. Có thể chuẩn bị riêng bánh tráng cắt sợi, rau củ bào và hũ nước sốt trong ngăn mát tối đa 1 ngày.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Bánh tráng trộn","Nam Bộ","Ăn vặt","Thanh nhẹ","Dưới 20 phút"]', '["breakfast","lunch"]', '["toss_mix"]', '["peanut","soybean","wheat"]', 262, 262.3, 1098, 5.8, 10.2, 1.4, 39.7, 4.1, 7.6, 604, 1.51, '["USDA FDC 168155","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Rice Paper Ref","VN Rau Ram Ref"]', '60944fc7510ffc897fa0a30283a1334471528201dadfc50600711adf3bd39afb', '89b46d22c25a5ea4c1a1322638b2960a3d7908a631f1bd8d08f522e10553b3aa', 4),
('imp-0bd4954058454e92', 'lau-ga-nam-am', 205, 'Lẩu gà nấm ấm bụng', 'Thịt đùi gà ta hầm thơm gừng sả và nấm hương tươi, nước dùng vàng óng thanh ngọt nhúng cùng nấm đùi gà, bắp cải và rau muống', 'Lẩu gà nấm ấm bụng mang hương vị dịu nhẹ chuẩn cơm tiệc gia đình miền Bắc. Đùi gà ta xào săn cùng gừng tươi và sả cây rồi hầm mềm ngọt nước, kết hợp nấm hương tươi thơm nức, nấm đùi gà giòn ngọt cùng bắp cải và rau muống xanh mát.', 'Dọn nồi lẩu sôi lăn tăn trên bàn tiệc ngày se lạnh, nhúng nấm đùi gà, bắp cải và rau muống; ăn nóng cùng bún tươi và chén muối tiêu chanh ớt chấm thịt gà.', 'Nếu còn dư nước dùng và thịt gà, để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 24 giờ; khi dùng lại đun sôi 5 phút trước khi nhúng thêm rau.', 'vietnamese', 'mon_lau_tiec', 'bac', 'medium', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Gà nấm","Bắc Bộ","Ấm bụng","Gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","fish"]', 554, 554.4, 2320, 40.5, 21.5, 5.4, 51.5, 6.9, 8, 1460, 3.65, '["NIN VN Fresh Bun Ref","USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 169378","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd2559e40cca13fbbe6e732c5dd28ff7ab68482294487078ef2c9ae773f222b3c', 'edbca77cb531dbec35df9365460b15ab109da66afb836af0bce1be156affe0f1', 4),
('imp-7fa36d5f0187a86e', 'com-chien-ba-chi-hanh', 206, 'Cơm chiên ba chỉ hành', 'Thịt ba chỉ cắt hạt lựu rang cháy cạnh béo thơm cùng tỏi phi, cơm nguội săn tơi đậm xì dầu và nhiều hành lá', 'Món cơm chiên ba chỉ hành thơm nức mũi với những miếng thịt ba chỉ cắt hạt lự chiên giòn cạnh tiết mỡ béo ngậy, hạt cơm rang săn rời áo hương tỏi phi, xì dầu dậy mùi khói chảo cùng thật nhiều hành lá tươi xanh.', 'Múc cơm chiên ba chỉ hành ra đĩa nóng, rắc tiêu đen xay và hành lá, thưởng thức cùng dưa leo thái lát và chén nước tương ớt xắt.', 'Ngon nhất khi ăn nóng để phần ba chỉ cháy cạnh giữ độ giòn. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và rang lại trên chảo nóng không dầu 3 phút.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Ba chỉ","Béo thơm","Nhanh gọn","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry"]', '["pork","soybean","wheat"]', 595, 594.7, 2488, 11.9, 35.1, 12.2, 56.2, 1.4, 1.6, 935, 2.34, '["USDA FDC 167820","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'f7ca9be077b285f8d58a29ffd23ad81d3647c25e570f860d45c5c994cb5141b6', 'b236b420adf65df735ee7c013aa837d0a1e2e0e92d4ddc392193e6318a367e10', 4),
('imp-fcf23c737f51ef13', 'com-chien-ca-chua-trung', 207, 'Cơm chiên cà chua trứng', 'Hạt cơm tơi săn áo sốt cà chua tương cà đỏ óng hòa cùng trứng bác bông mềm và hương dầu mè thơm nức', 'Món cơm chiên cà chua trứng kiểu Trung Hoa giản dị nhưng cuốn hút với từng hạt cơm nguội tơi ráo quyện đều nước sốt cà chua chua ngọt, dầu hào đậm đà và những mảng trứng gà chiên mềm thơm.', 'Múc cơm chiên ra tô hoặc đĩa sâu lòng, rắc hành lá thái nhỏ lên trên; dùng nóng ngay cùng dưa leo thái lát hoặc canh rong biển thanh mát.', 'Ngon nhất khi ăn ngay lúc vừa chiên xong; nếu bảo quản ngăn mát trong hộp kín tối đa 2 ngày, khi hâm lại đảo trên chảo chống dính lửa vừa 3–4 phút cho hạt cơm nóng tơi trở lại.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Cà chua","Trứng gà","Trung Hoa","Món nhanh"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","molluscs","sesame","soybean","wheat"]', 625, 624.7, 2613, 19.4, 24.7, 5.2, 79.7, 2.3, 9.1, 1361, 3.4, '["Dark Soy Sauce Label Ref","USDA FDC 168878","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468"]', '425b0f70cad55799855b64e58d584c55c6646dda18fe540f2e72b9002176ab26', '7e985363a21ae73ce4001ba679331fb581d2f53cd63cadb6e4b5a69df4835778', 4),
('imp-a5148e527a9ce9cf', 'ga-xao-gung-hanh-trung', 208, 'Gà xào gừng hành kiểu Trung', 'Thịt đùi gà mềm mọng xào lửa lớn thấm sốt gừng non nạo, hành tây ngọt và hành lá thơm nồng đưa cơm', 'Món gà xào gừng hành kiểu Trung Hoa chế biến nhanh gọn nhưng đậm đà nhờ phần nước sốt pha gừng non nạo nhuyễn kết hợp xì dầu, dầu hào và hành lá cắt khúc thơm nồng.', 'Dọn nóng ra đĩa sâu lòng cùng phần nước sốt sánh bóng chan cơm trắng; ăn kèm rau cải luộc hoặc dưa leo tươi.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi dùng, đun nóng trên chảo lửa vừa 3–4 phút cùng 1–2 muỗng canh nước lọc để sốt sánh mượt trở lại.', 'chinese', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Gừng hành","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","molluscs","soybean","wheat"]', 300, 299.8, 1255, 24.7, 16.8, 4.1, 11, 1.3, 4.1, 1090, 2.73, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170933","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', 'a5647acfc4e226d23b478b897eb26d422d2725ff1d1b6125bc7f47f45dc385a1', '00af15f5958ceeb63b7bb893fd9774f82b8c9bff3743f68d0870d46f8716863e', 4),
('imp-b3d9ecb751b0a043', 'bo-xao-hanh-tay-ot', 209, 'Bò xào hành tây ớt kiểu Trung', 'Thịt bò thăn thái mỏng thấm xì dầu, dầu hào xào lửa lớn cùng hành tây giòn ngọt và ớt hiểm cay nồng', 'Món bò xào hành tây ớt kiểu Trung Hoa hấp dẫn bởi từng lát thịt bò thăn mềm ngọt quyện sốt xì dầu dầu hào bóng mịn, kết hợp cùng hành tây giòn ngọt và chút cay nồng của ớt hiểm.', 'Dọn nóng ngay ra đĩa, rắc thêm chút tiêu đen xay lên trên; thưởng thức cùng cơm trắng nóng hoặc bánh mì.', 'Ngon nhất khi ăn ngay lúc vừa xào xong để bò mềm và hành tây còn độ giòn; nếu còn dư, bảo quản ngăn mát tối đa 24 giờ và đảo nhanh trên chảo nóng 1 phút khi hâm lại.', 'chinese', 'mon_xao', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Hành tây","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","soybean","wheat"]', 295, 295.1, 1235, 22.1, 19.1, 5.4, 8.4, 1, 3.4, 925, 2.31, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170106","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'c617e98bd2da57ce1532d8e2040441041b97c323163ed9e0142534106a2f05d9', '73adbeacc0d9ce3b67062660871d81d1a0d23f91e2bfa3175a835dc3869cae1c', 4),
('imp-835a527c81a79e9c', 'sup-bap-cai-thit-bam', 210, 'Súp cải thảo thịt bằm kiểu Trung', 'Nước dùng gà trong ngọt nấu cùng cải thảo mềm thanh, thịt heo bằm xào thơm và gừng ấm bụng', 'Món canh súp cải thảo thịt bằm kiểu Trung Hoa có nước dùng trong veo ngọt dịu từ gà và rau củ, thịt heo bằm ướp mềm đậm vị kết hợp cùng cọng cải thảo chín tới ấm lòng cho bữa cơm tối.', 'Múc canh ra tô sứ lớn, nhỏ vài giọt dầu mè thơm và rắc hành lá thái nhỏ lên mặt; ăn nóng cùng cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi lại trên lửa vừa 3–4 phút.', 'chinese', 'mon_canh', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Cải thảo","Thịt bằm","Trung Hoa","Thanh đạm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["pork","sesame","soybean","wheat"]', 254, 254.1, 1063, 14.3, 18.7, 5.8, 7, 2, 2.9, 1260, 3.15, '["Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169231","USDA FDC 169698","USDA FDC 169977","USDA FDC 170005","USDA FDC 170393","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '48b2cc76fc304e9b77943b86b25cafb865295aacd4f57738ddcbe0b64dedb821', 'aed14aa421063f7fc2323b437e1234ea8a99b7f5ac13b5fcffa92b91443ef66f', 4),
('imp-1dc0835c31b06d5e', 'tom-xao-bong-cai-trung', 211, 'Tôm xào bông cải xanh kiểu Trung', 'Tôm tươi săn giòn đỏ hồng xào cùng bông cải xanh mướt thấm sốt dầu hào Hoisin bóng nhẹ chuẩn Quảng Đông', 'Món tôm xào bông cải xanh kiểu Trung Hoa cân bằng dinh dưỡng với từng con tôm tươi săn ngọt kết hợp bông cải xanh chín tới giòn mướt nhờ kỹ thuật ủ hơi nước, phủ lớp sốt dầu hào bóng nhẹ.', 'Trút ra đĩa lớn, dọn nóng ngay để giữ độ giòn của bông cải xanh và vị ngọt săn của tôm; dùng kèm cơm trắng rất hợp.', 'Ngon nhất khi thưởng thức ngay lúc nóng; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đảo nhanh trên chảo lửa vừa 1–2 phút khi hâm lại.', 'chinese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Tôm tươi","Bông cải xanh","Quảng Đông","Thanh ngọt"]', '["lunch","dinner"]', '["stir_fry","steam"]', '["crustaceans","molluscs","sesame","shrimp","soybean","wheat"]', 346, 345.8, 1447, 35.6, 15.5, 2.3, 19.5, 4.2, 6, 1453, 3.63, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170106","USDA FDC 170379","USDA FDC 170931","USDA FDC 171319","USDA FDC 171369","USDA FDC 171370","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'ea85c6268421c353b95f49e83c76f1ed5f3061d560a12e7a865cd9f40827b4ff', 'e884ec0cdc5fc16fbd6da9697d4821191fa073bdad5e4daad458e0d368aa88aa', 4),
('imp-57b4406be05661c7', 'ba-chi-xao-tuong-dau', 212, 'Thịt ba chỉ xào tương đậu', 'Lát ba chỉ áp chảo cháy cạnh giòn béo xào quyện tương ớt đậu bản Doubanjiang, đậu đen muối và ớt chuông giòn ngọt', 'Món thịt ba chỉ xào tương đậu đậm chất cơm nhà Trung Hoa với từng miếng ba chỉ áp chảo xém cạnh thơm béo, quyện trong mùi thơm nồng đặc trưng của tương ớt đậu bản Doubanjiang và đậu tương đen lên men Douchi.', 'Dọn nóng ngay ra đĩa, dùng kèm cơm trắng nóng để cân bằng vị mặn béo đậm đà; có thể ăn kèm rau cải luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đảo nhanh trên chảo lửa vừa 2–3 phút cho thịt nóng giòn trở lại.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt ba chỉ","Tương đậu","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["pork","soybean","wheat"]', 737, 736.7, 3082, 15.1, 67.5, 23.8, 16.6, 3.4, 7.5, 1276, 3.19, '["Dark Soy Sauce Label Ref","Douchi Reference","Pixian Doubanjiang Ref","Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170933","USDA FDC 171413","USDA FDC 174277"]', 'b61931828870200eb549ca9b31feded8a3791d07f5111f4c563159cc91215d0a', 'c587cad384601ce68d34943e2118cc0c54c5cf9e13970cb24e57a9b45814b4ef', 4),
('imp-3774a1f0fda5cce1', 'ga-sot-chua-ngot-trung', 213, 'Gà chiên sốt chua ngọt kiểu Trung', 'Miếng ức gà tẩm bột chiên giòn rụm hai lần phủ sốt chua ngọt dứa chín, tương cà và ớt chuông bóng đẹp', 'Món gà chiên sốt chua ngọt kiểu Trung Hoa hấp dẫn với lớp vỏ bột mỏng nhẹ giòn rụm nhờ kỹ thuật chiên hai lần, quyện trong nước sốt chua ngọt sóng sánh cùng dứa chín, ớt chuông và hành tây tím.', 'Dọn nóng ngay ra đĩa khi lớp vỏ gà vẫn còn giòn tan, ăn kèm cơm trắng hoặc mì xào rau củ.', 'Ngon nhất khi ăn ngay sau khi trộn sốt; nếu cần chuẩn bị trước, nên giữ riêng phần gà đã chiên lần một và chỉ chiên giòn lần hai rồi áo sốt ngay trước bữa ăn.', 'chinese', 'mon_chien', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chua ngọt","Thịt gà","Trung Hoa","Món tiệc"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["chicken","sesame","wheat"]', 503, 502.5, 2102, 32, 19.3, 3, 49.1, 2.6, 18, 747, 1.87, '["USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169761","USDA FDC 170000","USDA FDC 170108","USDA FDC 170933","USDA FDC 171028","USDA FDC 171325","USDA FDC 171413","USDA FDC 171477","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 175039"]', '5618cb6677557a414aa2316b467b263b355ce7154ca23270a115a5b8c83f0082', '1cf96e7d06f10449ba7a544fbbe707e8f992e83bc742f633a3fcb569792629e0', 4),
('imp-49ca1819d60ffec8', 'mi-hanh-dau', 214, 'Mì trộn dầu hành kiểu Quảng Đông', 'Sợi mì dai mượt trộn quyện dầu hành phi vàng thơm nức và sốt xì dầu hai vị mặn ngọt bóng bẩy', 'Món mì trộn dầu hành nổi tiếng với hương thơm quyến rũ từ hành lá phi chậm trong dầu nguội hòa quyện cùng xì dầu nhạt, xì dầu đặc và đường cát tạo nên lớp sốt nâu bóng áo đều từng sợi mì dai ngon.', 'Chia mì ra tô sâu lòng, rắc hành lá phi giòn và hạt mè rang lên mặt; có thể ăn kèm trứng ốp la hoặc cải thìa chần.', 'Mì ngon nhất khi trộn và ăn ngay lúc nóng; riêng phần sốt dầu hành có thể làm sẵn để hũ thủy tinh kín trong ngăn mát dùng dần trong 2 tuần.', 'chinese', 'mon_bun_pho', NULL, 'easy', 5, 12, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Dầu hành","Quảng Đông","Món nhanh","Giản dị"]', '["breakfast","lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["egg","sesame","soybean","wheat"]', 520, 520.4, 2178, 14.6, 18, 2.9, 75.6, 3.9, 5.1, 1498, 3.74, '["Dark Soy Sauce Label Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '16283652a9c8fca1ecee7dc8010224e2120bd491035e7de7c9bb3b1a9f3cf5d8', '61378ba5b3d5cc4ba73423db15bbf86a834014778fee75789684dcfde5d16007', 4),
('imp-2b5b79ba1b622db1', 'canh-cai-thao-tom', 215, 'Canh cải thảo nấu tôm', 'Canh cải thảo mềm ngọt nấu cùng tôm khô đậm đà, nước dùng gà thanh trong và gừng hành ấm áp', 'Món canh cải thảo nấu tôm mang vị ngọt thanh tự nhiên từ tôm khô ninh kỹ hòa quyện cùng nước dùng gà trong veo, lá cải thảo mềm mọng và hương thơm ấm áp của gừng tươi.', 'Múc canh nóng hổi ra tô lớn, nhỏ vài giọt dầu mè thơm và rắc hành lá thái nhỏ; dùng kèm cơm trắng trong bữa ăn hằng ngày.', 'Ngon nhất khi dùng hết trong ngày; nếu bảo quản ngăn mát tối đa 24 giờ, đun sôi nhẹ lại 2–3 phút trên lửa vừa trước khi ăn.', 'chinese', 'mon_canh', NULL, 'easy', 10, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Cải thảo","Tôm khô","Trung Hoa","Thanh ngọt"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","sesame","shrimp"]', 101, 100.8, 422, 10.3, 4.7, 0.8, 5.2, 1.9, 2.5, 941, 2.35, '["USDA / Asian Dried Shrimp Ref","USDA FDC 169231","USDA FDC 169977","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647"]', 'e795e4571c666ebca4c9e249a54173f37f36d90fb1913467061421c26c663e21', '08e0a3d965682e68c00c2b527fca229cfed88451a62427450f7f71a289c77f3e', 4),
('imp-ee5bc076d722f397', 'ga-hap-nam-dong', 216, 'Gà hấp nấm đông cô', 'Thịt đùi gà ướp mềm đậm vị hấp cách thủy cùng nấm hương khô và gừng sợi giữ trọn nước ngọt thanh', 'Món gà hấp nấm đông cô kiểu gia đình Trung Hoa giữ nguyên độ mọng nước ngọt tự nhiên của thịt đùi gà ướp bột bắp kết hợp hương thơm umami đậm đà từ nấm hương khô ngâm nở.', 'Đặt nguyên đĩa gà hấp nóng hổi lên bàn ăn, rắc hành lá thái nhỏ; dùng kèm cơm trắng và chan phần nước thịt ngọt tiết ra trong đĩa.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hấp lại trong xửng khoảng 5–7 phút cho thịt và nấm nóng đều.', 'chinese', 'mon_hap_luoc', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Thịt gà","Nấm hương","Trung Hoa","Gia đình"]', '["lunch","dinner"]', '["steam"]', '["chicken","molluscs","sesame","soybean","wheat"]', 266, 265.6, 1112, 25.3, 13.8, 3.7, 9.5, 1.2, 1.5, 302, 0.76, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 168436","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 172385","USDA FDC 174277","USDA FDC Jujube Ref"]', 'e2e6c4755b62d64c1308b7abee87ae137f34875a6bd737a662715a9b3713acde', '5d2518c217726f864fafd8608d670f4ede43186f18517bdf773a48ffa741129b', 4),
('imp-aac2c265c3845ec4', 'tom-hap-gung-hanh', 217, 'Tôm hấp gừng hành kiểu Quảng Đông', 'Tôm sú tươi còn vỏ hấp chín hồng mọng nước cùng gừng sợi, rưới sốt xì dầu pha thơm nhẹ tinh tế', 'Món tôm hấp gừng hành kiểu Quảng Đông tôn vinh trọn vẹn độ ngọt giòn tự nhiên của tôm sú tươi hấp chín vừa tới trong vòng 5–6 phút, phủ lớp gừng sợi, hành lá xanh mướt và nước sốt xì dầu dịu nhẹ.', 'Dọn nóng nguyên đĩa tôm hấp ngay khi vừa rưới sốt, dùng kèm cơm trắng và chấm thêm nước sốt xì dầu đọng dưới đáy đĩa.', 'Tôm hấp ngon nhất khi thưởng thức ngay lúc nóng để thịt giòn ngọt; nếu còn dư, bóc vỏ bảo quản ngăn mát tối đa 24 giờ và hấp nhanh 2 phút khi dùng lại.', 'chinese', 'mon_hap_luoc', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Tôm sú","Gừng hành","Quảng Đông","Thanh đạm"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 158, 157.9, 661, 24.7, 4.4, 0.7, 4.6, 0.6, 1.9, 703, 1.76, '["Shaoxing Wine Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '75f53e45e000423781fed7ad80e35ca630e10b7794c5c5ccdbde25259e127d3a', 'a67b088b6d267853ff5fbadb7f73ca584408ad977930a83397c006538c8e7e57', 4),
('imp-55201e4225342ca3', 'ca-sot-chua-ngot-trung', 218, 'Cá phi lê sốt chua ngọt kiểu Trung', 'Phi lê cá thịt trắng chiên vàng giòn rụm áo sốt chua ngọt cà chua, dứa chín và ớt chuông bóng loáng', 'Món cá phi lê sốt chua ngọt kiểu Quảng Đông nổi bật với từng miếng phi lê cá lọc xương áo lòng trắng trứng và bột bắp chiên vàng giòn rụm, hòa quyện trong phần sốt tương cà, giấm gạo, dứa chín và rau củ giòn tươi.', 'Dọn nóng ngay ra đĩa bầu dục khi cá vừa phủ sốt, dùng kèm cơm trắng nóng để cảm nhận trọn vẹn độ giòn bên ngoài và thịt cá mềm ngọt bên trong.', 'Ngon nhất khi ăn ngay lúc vừa chế biến; nếu cần chuẩn bị trước, giữ riêng cá chiên và sốt trong hộp kín ngăn mát tối đa 24 giờ, khi ăn chiên giòn lại cá rồi mới đảo nhanh với sốt nóng.', 'chinese', 'mon_chien', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chua ngọt","Phi lê cá","Quảng Đông","Món tiệc"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["egg","fish","soybean","wheat"]', 443, 442.6, 1853, 38.7, 17.7, 3.2, 31.5, 1.9, 16.2, 1037, 2.59, '["USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170457","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175148"]', 'e427c5ec180552c80fa0e8c8f5a8dbe3e80389e6dd61d38b8486aa64c81dfd78', 'bac9d9750e554e4257532f2134a826eaadf18b83ee34422e719bd2baf311b4e5', 4),
('imp-6771c725aa163703', 'dau-phu-lanh-hanh', 219, 'Đậu phụ non sốt hành xì dầu lạnh', 'Đậu phụ non mát lạnh mịn mướt chan sốt xì dầu hành lá thơm nồng, pha chút chua nhẹ giấm gạo và vị cay tê của ớt hiểm', 'Món khai vị lạnh chuẩn vị Trung Hoa với từng khối đậu phụ non mềm tan như kem, quyện cùng nước sốt xì dầu nhạt đun thơm hành tỏi, điểm chút giấm gạo thanh dịu, dầu mè béo thơm và ớt hiểm tươi cay nhẹ.', 'Rắc thêm hành lá xanh và mè rang lên mặt đậu, dọn lạnh ngay cùng cơm trắng nóng hoặc dùng làm món khai vị giải nhiệt đầu bữa.', 'Nên thưởng thức ngay sau khi làm mát 15–20 phút để đậu giữ độ tươi mượt; sốt dư bảo quản lọ kín trong ngăn mát tối đa 5 ngày.', 'chinese', 'mon_chay', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món lạnh","Khai vị","Đậu phụ","Thanh mát","Chay"]', '["lunch","dinner"]', '["simmer","assemble"]', '["sesame","soybean","wheat"]', 148, 148.2, 620, 9.4, 7.9, 1.1, 10.5, 1, 4.4, 1067, 2.67, '["USDA FDC 168833","USDA FDC 169230","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171028","USDA FDC 172238","USDA FDC 172476","USDA FDC 174277"]', '7d6bf6fddf250300263aff0e80e5d368019642bffd8dbee86b018f56b3c04f6b', 'a6407dc35899329e9d90ce65ca337134be547fb824eb8d2430a037eac50e9296', 4),
('imp-5eb2769876646aae', 'mi-tron-dau-phu-cay', 220, 'Mì trộn đậu phụ chiên giòn sốt cay', 'Sợi mì dai mượt áo sốt xì dầu đậm vị cùng dầu ớt cay nồng, kết hợp đậu phụ chiên giòn rụm bên ngoài, mềm béo bên trong', 'Bữa trưa nhanh gọn mà đầy đủ năng lượng với sợi mì lúa mì dai ngon trộn đều trong nước sốt xì dầu nhạt, xì dầu đặc, giấm gạo và dầu ớt thơm lừng tỏi phi, ăn kèm những khối đậu phụ áo bột bắp ngũ vị chiên giòn rụm.', 'Chia mì đã trộn sốt ra tô, xếp đậu phụ chiên giòn lên trên cùng (không trộn trước) và rắc hành lá thái nhỏ, dùng ngay để giữ lớp vỏ đậu giòn lâu.', 'Món ngon nhất khi dùng ngay lúc mới trộn; nếu chuẩn bị trước, nên tách riêng mì trộn sốt và đậu phụ chiên, khi ăn chỉ cần làm nóng lại đậu bằng nồi chiên không dầu 3 phút ở 180°C.', 'chinese', 'mon_bun_pho', NULL, 'easy', 25, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Đậu phụ","Cay nồng","Nhanh gọn","Bữa trưa"]', '["breakfast","lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["sesame","soybean","wheat"]', 416, 415.6, 1738, 17.5, 19.6, 2.9, 45.6, 3.2, 5.1, 1634, 4.09, '["Chili Oil / Satay Ref","Dark Soy Sauce Label Ref","Five Spice USDA Ref","NIN VN Fresh Rice Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '164b5d3140407eb2554b4b03b7b1b674be2857686c134d7cb71fa55d1a6094c9', '2af83bc4c416bc7a85cc18f4f29b782cd33a72015933c0e8556886281218067f', 4),
('imp-87adca15ad4c1369', 'ga-ham-nikujaga-ca-rot', 221, 'Gà hầm Nikujaga cà rốt', 'Đùi gà, khoai tây, cà rốt và hành tây hầm mềm thấm đẫm nước dùng Dashi xì dầu Mirin ngọt mặn đậm cơm nhà Nhật', 'Gà hầm Nikujaga biến tấu thanh nhẹ từ món hầm truyền thống Nhật Bản với thịt đùi gà mềm ngọt thay cho thịt bò, hầm cùng khoai tây bở bùi, cà rốt và hành tây trong nước dùng Dashi hòa quyện xì dầu, rượu Sake và Mirin.', 'Múc gà hầm Nikujaga cùng khoai tây, cà rốt và ít nước hầm nóng ra bát sâu lòng, rắc hành lá thái nhỏ lên trên rồi dùng nóng với cơm trắng.', 'Để nguội hoàn toàn rồi cất trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; hôm sau hâm nóng lại trên lửa nhỏ món hầm càng ngấm vị đậm đà (không nên cấp đông vì khoai tây dễ bị bở).', 'japanese', 'mon_kho', NULL, 'easy', 20, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Nikujaga","Thịt gà hầm","Ẩm thực Nhật","Cơm nhà","Mùa lạnh"]', '["lunch","dinner"]', '["simmer","braise"]', '["chicken","fish","soybean","wheat"]', 319, 319, 1335, 21.8, 11.6, 2.9, 29.1, 3.6, 10.6, 1474, 3.68, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170026","USDA FDC 170393","USDA FDC 171413","USDA FDC 172385","USDA FDC 174277"]', 'c68561034947f0834ba0ad946c3bd8f06fdca4bf640916219b4733f43e66ff72', '328703ae0476424335d86cb1355de6f7db7826ea7bb93fc531f81957cdda264b', 4),
('imp-62d95da722597187', 'mi-soba-tron-nam-me', 222, 'Mì Soba trộn nấm mè', 'Mì Soba kiều mạch dai bùi trộn nấm đùi gà áp chảo xém cạnh quyện sốt xì dầu giấm gạo, dầu mè và hạt mè rang thơm', 'Mì Soba trộn nấm mè mang hương vị thanh nhã của mì kiều mạch Nhật Bản dai mềm, hòa quyện cùng nấm đùi gà xào vàng giòn sần sật, gừng bào, hành lá và phần sốt mè rang thơm bùi đậm vị xì dầu giấm gạo.', 'Chia mì Soba trộn nấm ra đĩa hoặc bát nông, rắc phần hành lá và hạt mè rang chừa lại lên trên; có thể thưởng thức lúc còn ấm nóng hoặc để mát đều ngon.', 'Ngon nhất khi dùng trong ngày; nếu bảo quản ngăn mát tối đa 24 giờ trong hộp kín, nên để riêng phần sốt trộn và nấm xào để sợi mì Soba không bị trương mềm.', 'japanese', 'mon_bun_pho', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Soba","Nấm đùi gà","Mè rang","Ẩm thực Nhật","Bữa trưa"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["buckwheat","sesame","soybean","wheat"]', 446, 445.7, 1865, 17, 15.9, 2.3, 63.7, 7.2, 5.9, 1811, 4.53, '["MEXT Dry Soba 01097","USDA FDC 168580","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', '2b9a7226031f3e72c7f68cfe3eb9129356a21a8476b40c33a478044090f6fcc3', 'd0eedf7f7e5d7b7ef51801aa71ece3a181a9600c37b3fed924a3996f396883b1', 4),
('imp-d2ab8a9e07388289', 'muc-nuong-teriyaki', 223, 'Mực nướng Teriyaki', 'Mực ống tươi chần săn khứa vằn nướng lửa lớn phết sốt Teriyaki sánh bóng, ngọt mặn đậm đà hương gừng tỏi', 'Mực nướng Teriyaki kiểu Nhật (Ika Maruyaki) giữ trọn độ giòn ngọt tự nhiên của mực ống tươi nhờ chần nhanh rồi nướng xém cạnh, phủ lớp sốt Teriyaki nấu từ xì dầu, rượu Sake, Mirin và đường nâu sánh bóng thơm lừng.', 'Cắt thân mực nướng thành từng khoanh tròn dày 1,5 cm, xếp ra đĩa cùng phần râu mực giòn, rưới thêm nước sốt Teriyaki còn lại và rắc hành lá thái nhỏ rồi dùng nóng.', 'Nên dùng hết trong bữa để mực giữ độ giòn ngọt; nếu còn dư, bọc kín bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo cùng phần sốt dư trong 1–2 phút.', 'japanese', 'mon_lau_tiec', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mực nướng","Teriyaki","Hải sản","Ẩm thực Nhật","Món nướng"]', '["lunch","dinner"]', '["boil","grill_roast"]', '["molluscs","soybean","squid","wheat"]', 301, 300.7, 1258, 30.8, 6.8, 1.3, 21.8, 0.5, 11, 1318, 3.3, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277"]', 'f890c9afb1298e60e6c9aaf7c5dd119aecb22cd4e73fed863e9444594bb89e01', '355660a2e522ec5fcc9867baa41424bcf99bb7a96dbf66a0c9a283b751056aec', 4),
('imp-81ff926a5557c059', 'ca-hoi-nuong-miso', 224, 'Cá hồi nướng Miso', 'Phi lê cá hồi ướp tương Miso trắng hòa quyện Sake, Mirin và xì dầu nướng vàng xém cạnh, mềm béo đậm đà kiểu Saikyo Yaki', 'Cá hồi nướng Miso (Saikyo Yaki) là món cá nướng tinh tế nổi tiếng của Nhật Bản, dùng tương Miso trắng ngọt dịu kết hợp rượu Sake, Mirin và chút dầu mè ướp thấm nhẹ vào từng thớ cá hồi béo ngậy rồi nướng lửa trên vàng xém thơm lừng.', 'Bày từng miếng cá hồi nướng Miso mặt da úp xuống hoặc ngửa tùy thích ra đĩa, rắc thêm hạt mè rang và hành lá thái xéo lên trên, ăn nóng kèm cơm trắng và củ cải bào.', 'Bảo quản cá hồi nướng Miso trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; khi dùng làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 160°C trong 3–4 phút.', 'japanese', 'mon_chien', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cá hồi","Tương Miso","Món nướng","Ẩm thực Nhật","Cơm tối"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","salmon","sesame","soybean","wheat"]', 440, 440.1, 1841, 37.3, 26.4, 5.7, 8.7, 1.1, 4.2, 998, 2.5, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172446","USDA FDC 174277","USDA FDC 175167"]', '8a22be9422c20b4556546a10e625a2722251e8d911642f0128bde4a81e44e01d', 'ed329b8e33f4240fd9256b22c0e484b03e0cf25b4ab0ad79efe5d9c9f0032e47', 4),
('imp-8c6abf9194ba8c45', 'ga-xao-gia-itame', 225, 'Gà xào giá Itame', 'Đùi gà áp chảo da vàng giòn trộn thấm sốt xì dầu tỏi, xào nhanh lửa lớn cùng giá đỗ giòn sần sật thanh đạm', 'Gà xào giá Itame (Tori Moyashi Itame) là món xào nhà Nhật nhanh gọn chỉ trong 20 phút, kết hợp thịt đùi gà áp chảo vàng thơm thấm sốt xì dầu tỏi và giá đỗ xào nhanh trên lửa lớn nên vẫn giữ được độ giòn ngọt tươi mát.', 'Múc gà xào giá nóng hổi ra đĩa rộng, rắc hành lá băm nhỏ cùng chút tiêu đen xay lên trên và dùng ngay khi còn nóng kèm cơm trắng.', 'Nên ăn hết ngay sau khi xào để giá đỗ giữ được độ giòn tươi; nếu dư, bảo quản ngăn mát tối đa 24 giờ và đảo nóng nhanh trên lửa lớn 1 phút.', 'japanese', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gà xào","Giá đỗ","Itame","Ẩm thực Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["chicken","sesame","soybean","wheat"]', 339, 338.5, 1417, 33.5, 19, 4.8, 8.8, 2.2, 4.5, 1236, 3.09, '["USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '52206e2eebae61603d3d999c0e548181f77d437566b26e13bfe5644c909200c4', '70c0441dcd4cfb4c45340c65a3de0a18ec647b92f96fc8c55c9b42ea102bd2ae', 4),
('imp-b33750551f6ea7fe', 'nam-nuong-bo-shoyu', 226, 'Nấm nướng bơ Shoyu', 'Nấm đùi gà thái khoanh dày khía caro áp chảo vàng nâu quyện bơ tan chảy và xì dầu cháy cạnh thơm nức kiểu Izakaya', 'Nấm nướng bơ Shoyu là món nhậu Izakaya kinh điển của Nhật Bản, dùng nấm đùi gà cắt khoanh dày khía caro áp chảo vàng ruộm rồi áo đẫm bơ béo thơm và xì dầu Nhật rưới cháy cạnh, cắn vào giòn sần sật đậm vị umami.', 'Xếp từng khoanh nấm nướng bơ Shoyu lên đĩa ấm, rưới phần bơ xì dầu còn lại trong chảo, rắc hành lá thái nhỏ lên trên rồi thưởng thức ngay khi còn nóng.', 'Ngon nhất khi ăn nóng ngay sau khi áp chảo; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 2 ngày và làm nóng lại trên chảo khô khoảng 1–2 phút.', 'japanese', 'mon_chien', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nấm đùi gà","Bơ Shoyu","Izakaya","Ẩm thực Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["milk","soybean","wheat"]', 116, 115.6, 484, 3.7, 9.4, 4.7, 6.6, 2.5, 1.2, 429, 1.07, '["USDA FDC 168580","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277"]', '663a4b9b85bb5d46e8b09b3fa8976f81cd57a14ac13015440d62dc93ea969976', 'd6d937eb5a0d127ba6b3c340aba53e34f1b471320c9aad7c50f688ae8d07868d', 4),
('imp-e9562581c7d79169', 'com-cua-kanimeshi', 227, 'Cơm cua Kanimeshi', 'Gạo Nhật nấu thấm vị xì dầu Sake hạt nêm gà, trộn thịt cua tươi ngọt thơm, hành lá, dầu mè và trứng gà hấp chín mềm tơi', 'Cơm cua Kanimeshi nấu bằng nồi cơm điện tiện lợi nhưng vẫn đậm đà hương vị biển kiểu Hokkaido, kết hợp cơm gạo Nhật dẻo thơm vị xì dầu và rượu Sake, hòa quyện thịt cua tươi ngọt chắc, dầu mè thơm và lớp trứng đánh hấp tơi béo.', 'Xới cơm cua Kanimeshi ra bát sứ nóng, rắc thêm chút hành lá thái nhỏ và tiêu đen xay lên trên, ăn nóng trực tiếp hoặc kèm súp Miso thanh nhẹ.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi ăn rưới thêm một thìa nhỏ nước lọc và hâm nóng lại trong lò vi sóng 1–2 phút cho cơm mềm ẩm.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 15, 45, 3, '/frigo/illustrations/delicious-meal.png', '["Kanimeshi","Cơm cua","Nồi cơm điện","Ẩm thực Nhật","Hải sản"]', '["lunch","dinner"]', '["boil","steam"]', '["crab","crustaceans","egg","sesame","soybean","wheat"]', 523, 523.2, 2189, 23.1, 9.9, 2.1, 81.2, 1.6, 0.7, 1178, 2.94, '["MEXT Sake 16021","USDA FDC 169756","USDA FDC 170005","USDA FDC 170931","USDA FDC 171009","USDA FDC 171028","USDA FDC 171287","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '9ff61d83a5cea5f490e73dfb955a3848156502d5751a13b1b1a680b492f2f5e3', '3acc6e3cf352eeb5d612addb95a1989535317f9b23b7787cc5afb2eaef7b1928', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-ee7ca138c67f4f24', 'bo-xao-gung-itame', 228, 'Bò xào gừng Itame', 'Thịt bò thái lát áo bột khoai tây mềm mọng, xào nhanh cùng hành tây ngọt giòn và sốt gừng Sake Mirin xì dầu sánh bóng', 'Bò xào gừng Itame kiểu Nhật có miếng thịt bò mềm mọng nhờ bí quyết áo lớp tinh bột khoai tây mỏng, xào nhanh cùng hành tây hấp chín ngọt thanh và gừng tươi hai kiểu vừa thái sợi vừa mài nhuyễn trong nước sốt xì dầu Mirin sánh đậm.', 'Múc bò xào gừng hành tây ra đĩa nông lòng, rắc hành lá thái nhỏ lên trên và dùng nóng ngay cùng cơm trắng dẻo.', 'Nên dùng nóng ngay sau khi xào để thịt bò giữ độ mềm mọng; nếu còn dư, bảo quản hộp kín ngăn mát tối đa 2 ngày và đảo nóng nhanh trên lửa vừa trong 1 phút.', 'japanese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Thịt bò xào","Gừng tươi","Itame","Ẩm thực Nhật","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","sesame","soybean","wheat"]', 272, 272.3, 1139, 19.2, 12, 3.9, 16.9, 1.6, 8.9, 831, 2.08, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468","USDA FDC 174277","USDA FDC Potato Starch"]', 'f0e7d2bc14d03303ab2cb3aec5a82f70f351668d0a931448b2080414ca050ead', '72770dd432f54301313b169f6c342ea320198ae4038e9eaf44762e1059df9f2c', 4),
('imp-57a8ece15d731efb', 'sup-miso-bap-cai', 229, 'Súp Miso bắp cải', 'Nước dùng Dashi thanh ngọt nấu mềm bắp cải xanh, nấm đùi gà giòn ngọt và rong biển Wakame, hòa tương Miso thơm dịu', 'Súp Miso bắp cải là món canh hằng ngày thanh đạm của người Nhật, kết hợp vị ngọt tự nhiên từ bắp cải xanh và nấm đùi gà nấu vừa chín tới trong nước dùng Dashi, hòa tan tương Miso sau khi tắt bếp để giữ trọn hương thơm lên men dịu nhẹ.', 'Múc súp Miso bắp cải nấm nóng ra 3 bát gỗ hoặc bát sứ sâu lòng, rắc hành lá thái xéo mỏng lên trên và thưởng thức nóng đầu bữa cơm.', 'Súp Miso ngon nhất khi dùng nóng ngay sau khi nấu; nếu còn dư, bảo quản ngăn mát tối đa 2 ngày và chỉ hâm nóng lại trên lửa nhỏ đến khi vừa bốc hơi, tuyệt đối không đun sôi bùng.', 'japanese', 'mon_canh', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Súp Miso","Bắp cải","Nấm đùi gà","Ẩm thực Nhật","Món canh"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["fish","sesame","soybean","wheat"]', 95, 94.6, 396, 6.4, 2.9, 0.4, 12.8, 3.8, 3.9, 1528, 3.82, '["MEXT Ichiban Dashi Ref","USDA FDC 168580","USDA FDC 169975","USDA FDC 170005","USDA FDC 170496","USDA FDC 171028","USDA FDC 172446","USDA FDC 174277"]', '40be28752f0d9685725f27634af4b19ac64235e05c3152f64401896d97e998cb', 'c9e0fe0d0dd73be09341851647e5d11815fd19bbc21a3f7b3b2666ba2a5b76ff', 4),
('imp-23a82881883d70fb', 'mi-udon-nam-dau', 230, 'Mì Udon nấm đậu', 'Nước dùng Dashi chay ninh từ tảo bẹ Kombu và nấm hương khô ngọt thanh, ăn cùng mì Udon dai, nấm đùi gà và đậu phụ chiên', 'Mì Udon nấm đậu là tô mì chay thanh tịnh chuẩn vị Nhật Bản, lấy vị ngọt tự nhiên từ tảo bẹ Kombu và nấm hương khô nấu Dashi, kết hợp sợi mì Udon dày dai, đậu phụ chiên vàng mềm béo và nấm đùi gà giòn ngọt.', 'Chia mì Udon ra 3 tô lớn, xếp nấm đùi gà, nấm hương thái lát và đậu phụ chiên lên trên, chan ngập nước dùng Dashi nấm nóng hổi rồi rắc hành lá thái khoanh.', 'Bảo quản riêng phần nước dùng nấm đậu và mì Udon chưa trụng trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nước dùng rồi trụng nóng mì sau cùng.', 'japanese', 'mon_bun_pho', NULL, 'easy', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Đậu phụ","Nấm đùi gà","Món chay","Ẩm thực Nhật"]', '["lunch","dinner"]', '["boil","simmer"]', '["soybean","wheat"]', 412, 411.7, 1722, 16.6, 10, 1.6, 65.3, 6.2, 7.2, 999, 2.5, '["MEXT Boiled/Fresh Udon","MEXT Hon-Mirin 16031","USDA FDC 168436","USDA FDC 168457","USDA FDC 168580","USDA FDC 169655","USDA FDC 170005","USDA FDC 172472","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'f7fa032e5a288b2e3fb25898e2556eefdd50eb94d7b92c6f11dcbfcc4d9c2287', 'f2bac8ed52eeccbd94abf5a0a3bed4d5782a7c7c5631fcef09ea29a90acdb2cd', 4),
('imp-85a3d8b84fc0bc05', 'mi-ramen-pho-mai-kim-chi', 231, 'Mì ramen phô mai kim chi', 'Sợi mì ramen dai ngon thấm nước dùng kim chi cay ấm, quyện lớp phô mai Cheddar tan chảy béo ngậy và trứng gà lòng đào', 'Mì ramen phô mai kim chi kết hợp vị chua cay nồng ấm của kim chi cải thảo xào thơm với nước dùng đậm đà, sợi mì ramen dai giòn, trứng gà lòng đào và lớp phô mai Cheddar tan chảy béo thơm hài hòa.', 'Bưng nguyên nồi nhỏ ra bàn hoặc múc ra tô sâu lòng, rắc hành lá thái nhỏ và thưởng thức ngay khi phô mai còn kéo sợi nóng hổi.', 'Món mì nước ngon nhất khi ăn ngay lúc vừa nấu xong; không nên bảo quản qua đêm vì sợi mì sẽ trương nở và mất độ dai.', 'korean', 'mon_bun_pho', NULL, 'easy', 10, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Mì cay","Phô mai","Kim chi","Món nhanh"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["egg","milk","sesame","wheat"]', 661, 661, 2766, 25.5, 27.1, 8.5, 79.3, 5.1, 5.6, 1545, 3.86, '["Korean Chili Flake Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170497","USDA FDC 170499","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173414","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '2990f477bfc519843cda7f1eb855f95c0117a6023604c139083db60775aee081', '0f2048029bcf0732af4698378ea5894081942771be9c760522bd0b75ce57298a', 4),
('imp-9d28abab0b8e5619', 'ga-ham-kim-chi', 232, 'Gà hầm kim chi (Dak Kimchi Jjim)', 'Đùi gà hầm mềm thấm đẫm vị kim chi cải thảo ủ chua cay nồng, sóng sánh nước sốt đỏ đậm đà kiểu Dak Kimchi Jjim cực đưa cơm', 'Gà hầm kim chi (Dak Kimchi Jjim) kết hợp những miếng đùi gà chặt vừa ăn được om chậm cùng kim chi cải thảo chua lâu năm và sốt Gochujang cay thơm, cho phần thịt gà mềm rục thấm vị và nước sốt sánh đỏ cực kỳ bắt cơm.', 'Bày gà hầm kim chi nóng hổi ra đĩa sâu lòng hoặc nồi đất, rắc hành lá xanh lên mặt và ăn kèm cơm trắng dẻo nóng.', 'Để nguội hoàn toàn rồi bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng trên lửa vừa 6–8 phút, có thể thêm chút nước nếu sốt quá sánh.', 'korean', 'mon_kho', NULL, 'easy', 15, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món hầm","Thịt gà","Kim chi","Đưa cơm"]', '["lunch","dinner"]', '["braise","simmer"]', '["chicken","fish","sesame","soybean","wheat"]', 370, 369.5, 1547, 33.1, 19.5, 5, 14.6, 3.5, 7.6, 1808, 4.52, '["Korean Chili Flake Ref","MEXT Sake 16021","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 172185","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', 'bc3cb19bce5a478f8d221f3a31892d681d5a6c969ab726d808bd2eed7d00a6f6', '48f079129023a33b9da3c5f08c87975695ba2cd80afa945f9764b45863939f20', 4),
('imp-2842fe1b767de23d', 'trung-cuon-gyeran-mari', 233, 'Trứng cuộn Hàn Quốc (Gyeran Mari)', 'Cuộn trứng gà vàng ươm mềm ẩm điểm xuyết sắc đỏ cà rốt và xanh hành lá, cắt khoanh gọn đẹp cho bữa sáng hoặc hộp cơm Bento', 'Trứng cuộn Hàn Quốc (Gyeran Mari) có kết cấu mềm mịn, nhiều lớp cuộn chặt tay với nhân cà rốt và hành lá băm nhuyễn đẹp mắt, vị béo nhẹ thanh tao thích hợp dùng kèm cơm nóng hoặc xếp hộp cơm trưa.', 'Để trứng cuộn nguội bớt 3 phút cho định hình rồi cắt lát dày 2 cm, bày ra đĩa chấm kèm nước tương hoặc tương cà tùy thích.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; món ăn ngon ở cả nhiệt độ phòng hoặc làm ấm nhẹ bằng lò vi sóng 30 giây.', 'korean', 'mon_nhanh_sang', NULL, 'medium', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món trứng","Bữa sáng","Hộp cơm","Món nhanh"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","milk","soybean","wheat"]', 180, 180.4, 755, 12.3, 12.9, 3.5, 3.4, 0.7, 1.5, 1012, 2.53, '["USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', 'b0ff00dd10d8209d3f98f78a5ab7186d3ee45b560ce1396dc25af04e5c6cec6b', 'd968fd759d83778a616a2e0393bbc1e8d7c0ecd3ea3a88aeff03f5cc9047820d', 4),
('imp-412960b58d00d211', 'sundubu-tom-cay', 234, 'Canh đậu phụ non hải sản cay (Sundubu Jjigae)', 'Nồi canh Sundubu Jjigae sôi sùng sục với đậu phụ non mềm tan, tôm tươi ngọt thịt, nấm đùi gà, trứng gà và nước dùng ớt bột Gochugaru cay ấm', 'Canh đậu phụ non hải sản cay (Sundubu Jjigae) là món canh nóng nổi tiếng của Hàn Quốc nhờ dầu ớt Gochugaru tự xào thơm lừng hòa trong nước dùng cá cơm tảo bẹ, ôm trọn từng miếng đậu phụ non béo mịn, tôm tươi săn ngọt và trứng gà lòng đào.', 'Dọn canh trực tiếp trong nồi đất khi nước còn sôi lăn tăn, rắc hành lá và ớt hiểm đỏ thái lát, thưởng thức cùng cơm trắng nóng.', 'Món canh có đậu phụ non và trứng ngon nhất khi ăn ngay trong ngày; nếu cần bảo quản, cất ngăn mát tối đa 24 giờ và hâm sôi nhẹ không khuấy mạnh để tránh vỡ đậu.', 'korean', 'mon_canh', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Hải sản","Đậu phụ non","Cay ấm"]', '["lunch","dinner"]', '["simmer","stir_fry"]', '["crustaceans","egg","fish","sesame","shrimp","soybean"]', 408, 408.4, 1709, 39.4, 20.2, 3.7, 19.1, 4.3, 4.7, 1748, 4.37, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172476","USDA FDC 175179"]', '2607daaeacd23f7d74473513968a6883a0a757c228ba9aa03c7382b925a6c13f', 'be5c92bbb65b39c1a1ef82c5db225ae5c6cd61bca849c4077fa75cacbd6b4b09', 4),
('imp-80976e834de46c34', 'japchae-mi-soi-tron', 235, 'Miến trộn Hàn Quốc (Japchae)', 'Sợi miến khoai lang dai bóng thơm dầu mè trộn cùng thịt bò xào mềm, nấm hương, nấm đùi gà, rau chân vịt, cà rốt, ớt chuông và trứng thái sợi', 'Miến trộn Hàn Quốc (Japchae) là món ăn truyền thống không thể thiếu trong các dịp lễ tiệc nhờ sợi miến khoai lang trong suốt dai ngon áo xì dầu và dầu mè rang, hòa quyện cùng thịt bò thăn, hai loại nấm thơm ngọt và rau củ xào riêng rực rỡ.', 'Bày miến trộn ra đĩa lớn, rắc thêm hạt mè trắng rang và sợi trứng tráng vàng lên trên; ngon cả khi ăn ấm lẫn ở nhiệt độ phòng.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn chỉ cần làm ấm lại nhanh trên chảo hoặc lò vi sóng 1–2 phút với chút nước lọc để sợi miến mềm lại.', 'korean', 'mon_xao', NULL, 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Miến trộn","Japchae","Lễ tiệc","Thịt bò"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["beef","egg","sesame","soybean","wheat"]', 438, 437.5, 1831, 14.5, 19, 4, 54.3, 4.3, 9, 1116, 2.79, '["USDA FDC 168436","USDA FDC 168462","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '737662300c51bfa9ba939a0a37f2520d94e5221de28caa5e7636ac214ca3bc8c', 'feaa49914f7c267ece5c8f5e65dc6af4e851d17ec49f444009189c5deaec186d', 4),
('imp-8608afb7fee8ebc3', 'ba-chi-nuong-samgyeopsal', 236, 'Ba chỉ nướng Hàn Quốc (Samgyeopsal)', 'Thịt ba chỉ heo cắt dày áp chảo vàng ruộm giòn bì, nướng kèm kim chi và tỏi lát, cuốn lá xà lách tía tô chấm sốt Ssamjang chuẩn tiệc nướng Hàn', 'Ba chỉ nướng Hàn Quốc (Samgyeopsal) hấp dẫn nhờ miếng ba chỉ dày thịt xen mỡ được nướng trên chảo gang đến khi vàng giòn hai mặt, ăn kèm kim chi áp chảo và tỏi nướng thơm lừng, cuốn trong xà lách và lá tía tô cùng tương Ssamjang.', 'Cắt thịt ba chỉ thành miếng vừa ăn trực tiếp trên chảo, cuốn cùng lá xà lách, lá tía tô, kim chi, tỏi nướng, hành lá trộn và chấm sốt Ssamjang hoặc dầu mè muối tiêu.', 'Thịt ba chỉ đã nướng chín bảo quản hộp kín trong ngăn mát tối đa 2 ngày; hâm nóng lại bằng chảo gang không dầu trên lửa vừa 3–4 phút cho bề mặt giòn trở lại.', 'korean', 'mon_lau_tiec', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Tiệc nướng","Thịt ba chỉ","Samgyeopsal","Cuốn rau"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["pork","sesame","soybean","wheat"]', 811, 810.6, 3391, 16.2, 76.6, 26.2, 14.1, 3.2, 5.6, 1293, 3.23, '["Korean Doenjang Ref","MEXT Hon-Mirin 16031","MEXT Shiso Ref","USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468"]', '16fb0b61f83f33f980294554d8aea92a5dde9dbbbe7f8a6cb4f53a303fc84c54', 'a0657c46d6f84bdee8004bd5994c93e402dc532e1ec5a9a1289c22c45c330d9f', 4),
('imp-97ba5787e2d4113b', 'canh-tuong-dau-han', 237, 'Canh tương đậu Hàn Quốc (Doenjang Jjigae)', 'Canh tương đậu lên men Doenjang thơm nồng hòa quyện nước dùng cá cơm tảo bẹ cùng đậu phụ trắng mềm, nấm đùi gà và rau chân vịt thanh ngọt', 'Canh tương đậu Hàn Quốc (Doenjang Jjigae) là món canh quen thuộc trên mâm cơm gia đình xứ Hàn với vị mặn bùi đặc trưng của tương đậu lên men Doenjang hòa cùng nước dùng cá cơm tảo bẹ ngọt thanh, nấm đùi gà giòn ngọt, rau chân vịt xanh mướt và đậu phụ mềm.', 'Dọn canh nóng hổi trong nồi đất hoặc tô lớn, ăn kèm cơm trắng nóng, kim chi và các món panchan.', 'Canh nguội hẳn cho vào hộp kín bảo quản ngăn mát tối đa 2 ngày; khi hâm nóng đun sôi nhẹ trên lửa vừa 3–4 phút rồi mới thêm rau nếu cần.', 'korean', 'mon_canh', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Tương đậu","Đậu phụ","Thanh đạm"]', '["lunch","dinner"]', '["simmer"]', '["fish","soybean","wheat"]', 135, 134.9, 564, 13.8, 4.4, 0.6, 12.8, 4.1, 2.6, 1206, 3.01, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","Korean Doenjang Ref","USDA FDC 168462","USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 172475"]', 'da8b10144a39c55aa21cb1d61e22a88deb304811fbc7cf4db69df97f355840dd', 'adce81ad663fd62ad6050036f897d5ce43c198bd739706610880da16ed5b244d', 4),
('imp-96d226a7f4d12156', 'ga-chien-gangjeong-cay', 238, 'Gà chiên giòn sốt cay ngọt (Dakgangjeong)', 'Miếng ức gà áo bột bắp chiên giòn hai lần phủ lớp sốt mật ong Gochujang cay ngọt keo bóng, rắc đậu phộng giã dập và hạt mè rang', 'Gà chiên giòn sốt cay ngọt (Dakgangjeong) nổi bật với kỹ thuật chiên hai lần giúp lớp vỏ bột bắp giòn rụm lâu dài dù đã áo đẫm nước sốt mật ong, đường nâu, giấm gạo và tương ớt Gochujang keo bóng đậm đà.', 'Bày gà chiên phủ sốt ra đĩa lớn, rắc đậu phộng rang giã dập, hạt mè trắng rang và hành lá thái nhỏ; dùng kèm củ cải muối hoặc cơm trắng.', 'Món ngon nhất khi dùng ngay lúc mới xóc sốt để giữ vỏ giòn; nếu còn dư, bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút.', 'korean', 'mon_chien', NULL, 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Gà chiên","Cay ngọt","Giòn rụm","Dakgangjeong"]', '["lunch","dinner"]', '["deep_fry","simmer","toss_mix"]', '["chicken","peanut","sesame","soybean","wheat"]', 460, 459.5, 1923, 30.8, 18, 2.8, 42, 1.3, 26, 702, 1.76, '["MEXT Hon-Mirin 16031","USDA / Korean Gochujang Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 169698","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 171477","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 174277"]', '995ef0fc5c85d127c7f32d240328967e103feb5a07ceca458b7e72f6a81fc510', 'aa213359a43f6e618f6bb7918be360e2741554c4e7a41c3f0a89ed3b7d141861', 4),
('imp-ba1871f088d9a522', 'lau-bulgogi-nam', 239, 'Lẩu Bulgogi nấm kiểu Hàn (Bulgogi Jeongol)', 'Nồi lẩu nóng hổi thanh ngọt với thịt bò ướp Bulgogi mềm thơm, nấm đùi gà giòn ngọt, cải thảo, củ cải trắng và miến khoai lang dai mượt', 'Lẩu Bulgogi nấm kiểu Hàn (Bulgogi Jeongol) mang đến trải nghiệm ấm cúng với thịt bò thăn ướp sốt mật ong xì dầu xếp gọn cùng nấm đùi gà, cải thảo, cà rốt và miến khoai lang trong nồi nước dùng cá cơm tảo bẹ ninh củ cải ngọt thanh.', 'Đặt nồi lẩu trên bếp từ hoặc bếp gas mini tại bàn cho sôi lăn tăn, chan dùng nóng kèm cơm trắng hoặc thưởng thức trực tiếp cùng kim chi.', 'Nếu còn dư nước lẩu và thịt bò, vớt riêng phần miến và rau; bảo quản nước lẩu cùng thịt trong ngăn mát tối đa 2 ngày và đun sôi lại 5 phút trước khi dùng.', 'korean', 'mon_lau_tiec', NULL, 'easy', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món lẩu","Thịt bò","Nấm đùi gà","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["beef","fish","sesame","soybean","wheat"]', 425, 425.2, 1779, 29.7, 16.1, 5.2, 40.1, 3.3, 12.9, 1597, 3.99, '["Korean Anchovy Kelp Stock Ref","MEXT Hon-Mirin 16031","USDA FDC 168452","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 169977","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277"]', 'ac88b0f0c1610f685da5bdef4a1416cca230f33a1fc991129d3a1e54ba8b4804', '3f2fc75109abf5a1abd8fc32d1730a218a2c06c89cf9b440116eeb27ec2d17ea', 4),
('imp-24fc3ac5cd3ff445', 'com-chien-kim-chi-han', 240, 'Cơm chiên kim chi truyền thống (Kimchi Bokkeumbap)', 'Cơm nguội chiên săn tơi thấm đẫm vị kim chi ủ chua kỹ, nước kim chi và tương ớt Gochujang cay đậm, ăn kèm trứng ốp la và rong biển khô', 'Cơm chiên kim chi truyền thống (Kimchi Bokkeumbap) giữ đúng tinh thần tối giản chuẩn vị Hàn với kim chi cải thảo ủ chua kỹ xào săn, hạt cơm nguội rang tơi áo đều nước kim chi và Gochujang cay nồng, phủ trứng ốp la béo thơm.', 'Xới cơm chiên nóng ra 3 đĩa hoặc tô, đặt trứng ốp la lên trên, rắc hạt mè trắng rang, hành lá và rong biển khô xé nhỏ để trộn ăn ngay.', 'Phần cơm còn dư bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi ăn đảo nóng lại trên chảo lửa vừa 3–4 phút cho hạt cơm tơi ráo.', 'korean', 'mon_chien', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Cơm chiên","Kim chi","Món nhanh","Cay đậm"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["egg","sesame","soybean","wheat"]', 401, 401.2, 1679, 12.4, 13.9, 2.8, 55.8, 2.8, 3.8, 1002, 2.51, '["USDA / Korean Gochujang Ref","USDA FDC 168456","USDA FDC 168878","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 174277"]', '1643183b5aa7f5ab46b47d3e5a54206cf37bcc80bfa11f86b06fcef9fc9c99f6', '208e259f02662ca8c689f0495aacddd26b6fe662e3af55c28da0981bb8bdb1f4', 4),
('imp-46962ad0d6f6e63b', 'ga-xao-hung-que-pad-krapao', 241, 'Gà bằm xào húng quế kiểu Thái (Pad Krapow Gai)', 'Thịt ức gà băm xào lửa lớn với tỏi ớt hiểm dậy hương húng quế Thái nồng nàn, sốt dầu hào xì dầu đậm vị ăn kèm cơm trắng và trứng ốp la', 'Phiên bản Pad Krapow thịt gà băm thanh nhẹ hơn thịt heo nhưng vẫn giữ trọn hương vị đường phố Thái Lan: thịt gà tơi ngọt quyện sốt dầu hào, hai loại xì dầu, vị cay tê của ớt hiểm và mùi thơm bừng tỉnh của lá húng quế.', 'Xới cơm trắng nóng ra 3 đĩa, múc gà xào húng quế lên bên cạnh, đặt trứng ốp la lòng đào giòn viền lên trên và dọn kèm vài lát dưa leo tươi.', 'Thịt gà xào giữ được 2 ngày trong hộp kín ngăn mát; hâm nóng lại trên chảo lửa lớn với 1 muỗng cà phê nước và chiên trứng ốp la mới khi dùng.', 'thai', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Krapow","Thịt gà","Cay nồng","Cơm đĩa"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["chicken","egg","fish","molluscs","soybean","wheat"]', 571, 570.7, 2388, 45.5, 19.1, 3.9, 51.1, 1.6, 5.2, 1287, 3.22, '["Dark Soy Sauce Label Ref","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 171477","USDA FDC 172185","USDA FDC 172232","USDA FDC 174277"]', 'f38fa81ba0ab2005090625ee9cac5982e9d20f26c26ac37a8597987654ea3678', '75098db7cea55ed73438ecca9f5740c7fd66107c40208aaae544a444e367af93', 4),
('imp-f8fc539b7aa359ac', 'com-chien-dua-thai', 242, 'Cơm chiên dứa hải sản kiểu Thái (Khao Pad Sapparot)', 'Cơm hạt tơi vàng óng hương bột cà ri xào cùng dứa chín mọng, tôm tươi áp chảo, trứng gà và hạt điều rang giòn bùi', 'Khao Pad Sapparot là món cơm chiên nhiệt đới nổi tiếng của Thái Lan với hạt cơm tơi vàng ươm hương cà ri dịu nhẹ, vị chua ngọt thanh mát từ dứa tươi hòa cùng tôm săn ngọt và hạt điều bùi béo.', 'Múc cơm chiên dứa vào lòng quả dứa khoét rỗng hoặc đĩa rộng, xếp tôm lên trên và rắc thêm hành lá; dọn ăn nóng kèm dưa leo thái lát.', 'Ngon nhất khi ăn nóng ngay để hạt điều giòn và cơm không bị ẩm; phần dư bảo quản ngăn mát tối đa 24 giờ và rang lại trên chảo lửa vừa.', 'thai', 'mon_xao', NULL, 'medium', 20, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Cơm chiên","Hải sản","Dứa chín","Chua ngọt"]', '["lunch","dinner"]', '["stir_fry"]', '["cashew","crustaceans","egg","fish","shrimp","soybean","tree_nuts","wheat"]', 672, 671.9, 2811, 32.3, 27.6, 5.2, 76.7, 5.4, 16.2, 1218, 3.05, '["USDA FDC 168878","USDA FDC 169124","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170162","USDA FDC 170457","USDA FDC 170924","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '5b1a6e080803aff0baff57cec8a57021788a5673f96d3553e80ee2881702e16f', '9e0cb238e62098d0eeed6f6c57334df06c615a8ff87300027b47e56448f9e0c9', 4),
('imp-e28e249efceacac7', 'larb-heo-chua-cay', 243, 'Gỏi thịt heo bằm chua cay kiểu Thái (Larb Moo)', 'Thịt heo bằm xào chín tơi trộn nước cốt chanh chua sáng, nước mắm, ớt khô cay nồng, thính gạo rang thơm lừng và rau thơm mát', 'Larb Moo là món gỏi thịt bằm đặc sản vùng Isan Thái Lan với vị chua thanh từ chanh tươi, mặn ngọt hài hòa, cay tê của ớt bột và hương thơm bùi đặc trưng từ thính gạo rang cùng húng lủi.', 'Bày gỏi thịt heo bằm ra đĩa sâu lòng, xếp bắp cải tách lá và dưa leo thái lát bên cạnh để cuốn hoặc ăn kèm xôi nếp nóng hay cơm trắng.', 'Nên trộn và ăn ngay trong ngày khi thính gạo còn thơm và rau sống giòn tươi; tránh để qua đêm vì nước chanh làm thịt sẫm màu và rau bị héo.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Chua cay","Thịt heo bằm","Ít dầu mỡ"]', '["lunch","dinner"]', '["stir_fry","toss_mix"]', '["fish","pork"]', 355, 355.1, 1485, 21, 23, 8.5, 16.9, 3.5, 5.5, 1036, 2.59, '["Citrus Leaf Culinary Ref","Toasted Rice Powder Ref","USDA FDC 167902","USDA FDC 168155","USDA FDC 168409","USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 171319","USDA FDC 172185","USDA FDC 173474","USDA FDC 173647"]', '883d9e49ee240c89cf71167a026e8d0ff00f484520b0c408233c02451062b1b0', 'd11819602e1065c4f805f180333092f5e77f1bd61013fa2f111081da3d13b809', 4),
('imp-90fc2e140739a7d7', 'tom-yum-ca-nam', 244, 'Canh chua cay cá nấm Tom Yum kiểu Thái (Tom Yum Pla)', 'Nước canh Tom Yum trong thanh dậy hương sả, riềng, lá chanh Thái nấu cùng cá phi lê trắng ngọt, nấm đùi gà giòn và cà chua bi', 'Tom Yum Pla là biến thể Tom Yum nước trong thanh mát không dùng cốt dừa hay tương ớt béo, nổi bật với vị ngọt tự nhiên của phi lê cá thịt trắng, nấm đùi gà giòn sần sật và hương thảo mộc tươi nồng nàn.', 'Múc canh Tom Yum cá nấm nóng hổi ra tô lớn, rắc ngò rí lên trên và thưởng thức cùng cơm trắng dẻo.', 'Thịt cá dễ nát khi hâm đi hâm lại nên ngon nhất khi ăn hết trong bữa; nếu còn dư có thể bảo quản ngăn mát 24 giờ và hâm nhẹ trên lửa nhỏ không khuấy mạnh.', 'thai', 'mon_canh', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Tom Yum","Cá tươi","Chua cay"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 193, 192.9, 807, 28.7, 3.9, 0.9, 11.4, 2.3, 5.6, 1148, 2.87, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 172185","USDA FDC 173647","USDA FDC 175148","USDA FDC Palm Sugar Ref"]', 'b119bd404383a3ee96781bd335b052feafb18b391ca8a6d2fff1d27f9368b7b1', '9360d9d93e7f31e90169e37f5cd7cac7ce77c258214275b8f2de1ae611613ef5', 4),
('imp-8ebb3021c30c48f8', 'pad-see-ew-ga', 245, 'Hủ tiếu xào xì dầu thịt gà kiểu Thái (Pad See Ew)', 'Bánh phở tươi bản lớn xào lửa lớn cháy cạnh thơm khói chảo, áo đều sốt hắc xì dầu dầu hào cùng ức gà mềm, trứng tơi và cải thìa giòn xanh', 'Pad See Ew là món mì xào xì dầu trứ danh tại các khu chợ đêm Thái Lan, nổi bật với sợi bánh phở tươi bản to dẻo dai áp chảo hơi xém cạnh, vị mặn ngọt hài hòa từ hắc xì dầu, dầu hào và cải xanh giòn ngọt.', 'Trút Pad See Ew nóng hổi ra đĩa, rắc thêm chút tiêu trắng xay và dọn kèm ớt tươi thái lát ngâm giấm hoặc chanh tươi tùy thích.', 'Nên ăn nóng ngay để sợi bánh phở tơi mềm và thơm mùi chảo; nếu còn dư bảo quản ngăn mát trong 24 giờ, xào nóng lại với 1 muỗng canh nước lọc trên lửa lớn.', 'thai', 'mon_xao', NULL, 'medium', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad See Ew","Mì xào","Ức gà","Xì dầu"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["chicken","egg","molluscs","soybean","wheat"]', 621, 620.7, 2597, 37.8, 23.2, 4.4, 64.1, 2.7, 10.2, 1327, 3.32, '["Dark Soy Sauce Label Ref","NIN VN Fresh Pho Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170390","USDA FDC 170933","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 171477","USDA FDC 173647","USDA FDC 174277"]', 'd56f2264d6c428eb1627cff414db56cb4e2a75abc971409e5cbd662adb1797e2', '159f24857839a9905520c0343720c30f217abf8d93cf4b05f0aafd30fb8cc680', 4),
('imp-8e2f2113f406a7d8', 'ga-xien-sate-sa', 246, 'Thịt gà xiên sả nướng kiểu Thái (Satay Sả)', 'Đùi gà rút xương cắt dải ướp hỗn hợp sả tươi, tỏi, rễ ngò xay cùng nước cốt dừa béo thơm, nướng áp chảo xém vàng mọng nước', 'Gà xiên sả kiểu Thái thơm nức hương sả tươi, tỏi và ngò rí quyện cùng nước cốt dừa giúp thịt đùi gà mềm mọng lạ miệng, nướng xém cạnh vàng ươm mà không hề bị khô.', 'Xếp các xiên gà nướng nóng hổi ra đĩa, dọn kèm chanh tươi cắt múi cau để vắt trực tiếp khi ăn cùng xôi nếp, cơm trắng hoặc đồ chua rau củ.', 'Thịt gà ướp có thể bọc kín bảo quản ngăn mát qua đêm để nướng ngon hơn; xiên đã nướng giữ trong tủ mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu 180°C trong 4 phút.', 'thai', 'mon_chien', NULL, 'medium', 35, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Xiên nướng","Thịt gà","Sả thơm","Tiệc cuối tuần"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["chicken","egg","molluscs","soybean","wheat"]', 401, 401.1, 1679, 31.7, 24.2, 8.4, 14.1, 0.9, 3.2, 948, 2.37, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169997","USDA FDC 170172","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277"]', 'a3076131cdf47f7867e36b0f4f9d5dbcb5719a35285cf2773b1a45f943208a8d', 'e0b82588383bf76f7eafea87ef6a847613d25f67e748dceb5870bfc43e7b6554', 4),
('imp-574963de4a60d466', 'ca-hap-chanh-ot-thai', 247, 'Cá chẽm hấp chanh ớt kiểu Thái (Pla Neung Manao)', 'Cá tươi nguyên con hấp sả chín mọng ngọt thịt, chan đẫm sốt nước dùng gà pha chanh tươi, nước mắm, tỏi băm và ớt hiểm cay nồng', 'Pla Neung Manao là món cá hấp kinh điển trong các bữa tiệc Thái Lan, giữ trọn độ ngọt thanh mềm mọng của thịt cá tươi hòa quyện cùng nước sốt chanh tỏi ớt chua tê bùng vị và hương cần tàu tươi mát.', 'Chuyển cá hấp sang đĩa bầu dục sâu lòng, xếp lá cần tàu xung quanh rồi rưới đều nước sốt chanh tỏi ớt nóng ấm lên mình cá; dọn ăn ngay với cơm trắng.', 'Món cá hấp ngon nhất khi thưởng thức nóng ngay lúc vừa rưới sốt; nếu bảo quản ngăn mát trong 24 giờ, nên giữ riêng phần sốt và hấp nóng lại cá 5 phút trước khi chan sốt.', 'thai', 'mon_hap_luoc', NULL, 'medium', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món hấp","Cá tươi","Chua cay","Thanh mát"]', '["lunch","dinner"]', '["steam"]', '["celery","fish"]', 227, 226.7, 948, 35.1, 4.4, 1.2, 10.6, 1.1, 5.2, 1281, 3.2, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169988","USDA FDC 169997","USDA FDC 170106","USDA FDC 172185","USDA FDC 172883","USDA FDC 175176","USDA FDC Palm Sugar Ref"]', '9eaf09b92f49adaf1c7afc9b9b36ebd2ced88e2d58fc9e5f84daffb521f55933', 'e3bde15fc4c32e1b0e0d8f211ae2f59b37e590d9f1395a9954c1ae0c5b6fcd61', 4),
('imp-295e7045e644d2ca', 'goi-muc-mi-soi-thai', 248, 'Gỏi miến mực chua cay kiểu Thái (Yam Wun Sen)', 'Miến dong dai trong trộn cùng mực tươi chần giòn, sả hành thơm nồng, tôm khô giã tỏi ớt và nước sốt chanh đường thốt nốt chua cay', 'Yam Wun Sen là món gỏi miến khai vị thanh mát trứ danh của Thái Lan với sợi miến trong dai không bết dính, mực tươi giòn ngọt quyện sốt nước mắm chanh đường thốt nốt chua cay đậm vị.', 'Bày gỏi miến mực ra đĩa sâu lòng, rắc mè rang vàng và vài lát ớt đỏ lên trên; thưởng thức ngay khi còn mát tươi như món khai vị hoặc ăn nhẹ.', 'Miến dễ hút nước và nở mềm nên ngon nhất khi trộn và dùng hết ngay trong vòng 1–2 giờ sau khi chế biến.', 'thai', 'mon_cuon_nom', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Miến trộn","Hải sản","Chua cay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","molluscs","sesame","shrimp","squid"]', 328, 327.7, 1371, 16.5, 2.2, 0.4, 60.6, 1.8, 7.9, 1415, 3.54, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168952","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170499","USDA FDC 172185","USDA FDC 173474","USDA FDC 173647","USDA FDC 174223","USDA FDC Palm Sugar Ref"]', '65db5d6e999ac7f5e2c46bbd68c888feafd9d8e89bd2bdf4fb2581e6636fde20', 'e50f897449e3b30c1483ab8144540f374b33f0bedfda29e0bc0eaee5e91f7dd0', 4),
('imp-5e0a488541baee5e', 'trung-chien-kai-jeow', 249, 'Trứng chiên giòn phồng kiểu Thái (Kai Jeow)', 'Trứng gà đánh sủi bọt cùng nước mắm và hành lá chiên ngập dầu nóng già tạo lớp viền xốp giòn vàng rụm, bên trong mềm béo đậm đà', 'Kai Jeow là món trứng chiên đường phố nổi tiếng của Thái Lan với kỹ thuật rót trứng từ trên cao vào chảo dầu thật nóng, tạo lớp vỏ ngoài phồng xốp giòn tan mà ruột trứng vẫn giữ độ ẩm mềm.', 'Đặt miếng trứng chiên Kai Jeow phồng giòn lên đĩa cơm trắng nóng, rắc lá ngò rí và dọn kèm chén tương ớt chua ngọt hoặc nước mắm ớt chanh.', 'Món trứng chiên phồng ngon nhất khi dùng nóng ngay vừa vớt ra; nếu để nguội trứng sẽ xẹp bớt nhưng vẫn bảo quản tủ mát trong ngày và áp chảo nóng lại không dầu 2 phút.', 'thai', 'mon_chien', NULL, 'easy', 5, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Trứng chiên","Món chiên","Nhanh gọn","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["deep_fry"]', '["egg","fish"]', 205, 205.1, 858, 9.3, 16.6, 3.6, 4.9, 0.8, 2.9, 805, 2.01, '["USDA FDC 168155","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC Sriracha Ref"]', '87fc527a1de83deba08fca26f9555cfb20f207212220e36ad164efdcdc4f81cb', 'bfceef1163d35155a92027c58c182fddf201296e076147b0678dd45fc74d1f80', 4),
('imp-bcc430e4b54c1e65', 'canh-tom-chuet-tom', 250, 'Canh bắp cải tôm tươi thanh ngọt kiểu Thái (Tom Chuet)', 'Nước canh trong dịu ngọt vị tôm tươi và bắp cải non hầm mềm, hòa quyện cà chua chín, hương tỏi phi và hành ngò nhẹ nhàng không cay', 'Tom Chuet là món canh thanh mát không cay quen thuộc trên mâm cơm gia đình Thái Lan, kết hợp vị ngọt tự nhiên từ tôm tươi áp chảo sơ cùng bắp cải mềm ngọt, cà chua chín và nước dùng thơm mùi tỏi phi.', 'Múc canh Tom Chuet nóng ra tô lớn, rắc tiêu đen xay và ngò rí lên trên; rất hợp dùng kèm các món mặn hoặc món xào cay kiểu Thái.', 'Canh rau bắp cải nên dùng hết trong ngày để giữ độ ngọt tươi; nếu bảo quản ngăn mát tối đa 24 giờ, đun sôi nhanh lại trên lửa vừa rồi dùng ngay.', 'thai', 'mon_canh', NULL, 'easy', 12, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Không cay","Thanh đạm","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","shrimp","soybean","wheat"]', 135, 134.5, 563, 16.4, 3.8, 0.6, 10.7, 3.4, 5.6, 976, 2.44, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '6b7a523d16da748c9cbd39d203bec562f27ee3a160eb653ceaae101224a6cf40', '62b7b43cc399bd95b4d7420fd7a036f578ab719135d5c55bf9aff18ebbaf2fef', 4),
('imp-103ea67cd56c9c96', 'mi-y-carbonara-ba-chi', 251, 'Mì Ý Carbonara ba chỉ giòn', 'Sợi Spaghetti áo lớp sốt kem trứng và phô mai Pecorino Romano sánh mượt không dùng kem tươi, kết hợp thịt ba chỉ muối áp chảo giòn thơm và tiêu đen', 'Mì Ý Carbonara chuẩn truyền thống thành Rome không hề dùng kem tươi mà tạo độ sánh mượt nhờ kỹ thuật nhũ tương hóa hỗn hợp trứng gà, phô mai Pecorino Romano bào mịn cùng mỡ ba chỉ muối giòn và nước luộc mì giàu tinh bột.', 'Chia mì ra 4 đĩa sâu lòng đã làm ấm, rắc đều thịt ba chỉ giòn, thêm phô mai Pecorino Romano bào và tiêu đen mới xay lên trên rồi thưởng thức ngay.', 'Mì Carbonara cần ăn ngay khi còn nóng để sốt trứng giữ được độ kem bóng mịn; món này không thích hợp để qua đêm hay hâm lại vì trứng dễ tách nước và vón cục.', 'italian', 'mon_bun_pho', NULL, 'medium', 10, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Carbonara","Ba chỉ","Béo mịn"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["egg","milk","pork","wheat"]', 544, 543.5, 2274, 24.6, 21.1, 8.2, 62, 2.8, 2.5, 963, 2.41, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169230","USDA FDC 170931","USDA FDC 171287","USDA FDC 173468","USDA FDC 173647","USDA FDC Pecorino Ref"]', '08d0130579c2fc016838b595f70e369306b3145344070a0a484d26f095185165', 'b13104e7bb071423d8c42207677951f5706747cbb19f8e9bb6ea1d513f39bf84', 4),
('imp-34505f9722b38fc1', 'mi-y-bo-bam-bologna', 252, 'Mì Ý bò bằm sốt Ragù Bologna', 'Thịt bò heo xay và ba chỉ xông khói hầm chậm cùng rau củ soffritto, rượu vang đỏ và sốt cà chua đậm đà phủ sợi mì Spaghetti', 'Sốt Ragù Bologna là tinh hoa ẩm thực miền Emilia-Romagna với thịt bò xay kết hợp thịt heo xay và ba chỉ muối xào xém, hầm liu riu hàng giờ cùng cà rốt, cần tây, hành tây, rượu vang đỏ và cà chua Passata tạo nên độ sánh đậm quyện vị.', 'Trộn mì Ý Spaghetti trực tiếp vào nồi sốt Ragù nóng hổi cùng chút nước luộc mì, chia ra 4 đĩa sâu lòng và rắc phô mai Parmesan bào mịn lên trên.', 'Sốt Ragù Bologna bảo quản hộp kín trong ngăn mát đến 3–4 ngày hoặc cấp đông đến 2 tháng; khi dùng hâm nóng sốt trên lửa nhỏ, thêm chút nước dùng bò nếu đặc.', 'italian', 'mon_bun_pho', NULL, 'medium', 20, 90, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Ragù Bologna","Thịt bò bằm","Cuối tuần"]', '["lunch","dinner"]', '["boil","braise","simmer"]', '["beef","celery","milk","pork","sulphites","wheat"]', 853, 853.1, 3569, 41, 42.1, 15.7, 72.2, 5.2, 8.4, 1327, 3.32, '["USDA FDC 167902","USDA FDC 167923","USDA FDC 168927","USDA FDC 169072","USDA FDC 169230","USDA FDC 169988","USDA FDC 170000","USDA FDC 170393","USDA FDC 170460","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171593","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174036"]', 'b66ae0364b7a4f5ba2ab7aa5097a64a79e09241db73599f86f6f5a24e6cc6150', '11a5a25322ca2af9292581cc1e113b93ce71a989a0b3245dcf0834f730f12ad8', 4),
('imp-266d7af134d7286a', 'mi-y-nam-kem', 253, 'Mì Ý nấm đùi gà sốt kem', 'Nấm đùi gà áp chảo vàng thơm cùng bơ tỏi quyện sốt kem sữa sánh mịn và phô mai Parmesan ôm trọn sợi mì Spaghetti nóng hổi', 'Mì Ý nấm đùi gà sốt kem là món pasta ấm áp, dễ nấu chỉ trong 30 phút. Nấm đùi gà giòn ngọt được xào vàng với bơ lạt và dầu ô liu rồi hòa quyện cùng kem tươi, sữa tươi và phô mai Parmesan béo ngậy.', 'Múc mì ra 3 đĩa sâu lòng khi còn nóng, rắc thêm ngò tây tươi thái nhỏ, chút phô mai Parmesan bào và tiêu đen xay lên trên.', 'Thưởng thức ngay khi còn nóng để sốt kem giữ độ mượt; nếu bảo quản ngăn mát tối đa 2 ngày, hâm nóng trên chảo lửa nhỏ cùng vài muỗng sữa tươi.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Nấm đùi gà","Sốt kem","Nhanh gọn"]', '["lunch","dinner"]', '["boil","stir_fry","simmer","toss_mix"]', '["milk","wheat"]', 673, 672.6, 2814, 20.8, 33.9, 18.4, 72.7, 4.7, 6.4, 770, 1.93, '["USDA FDC 168580","USDA FDC 168927","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', 'e2d9731003d9de4f9a2079be84bab973ce43e7e8d8de42402aaf4af3968120c8', '43009c07cd4fd7de4245814281f387cddce09405bd485a56b8490be3947e5370', 4),
('imp-8b2c852ba59f2143', 'risotto-rau-bina-nam', 254, 'Cơm Risotto rau bina và nấm', 'Gạo Arborio om chậm với nước dùng rau củ nóng, nấm đùi gà áp chảo vàng thơm, rau bina xanh mướt và đánh bóng cuối bằng bơ phô mai', 'Cơm Risotto rau bina và nấm là sự kết hợp hài hòa giữa vị ngọt giòn của nấm đùi gà áp chảo, sắc xanh tươi mát từ cải bó xôi cùng hạt gạo Arborio mềm dẻo sóng sánh trong nước dùng rau củ, bơ lạt và phô mai Parmesan.', 'Múc cơm Risotto nóng ra 3 đĩa sâu lòng, rắc thêm tiêu đen mới xay và chút phô mai Parmesan bào mịn lên trên rồi dùng ngay khi cơm còn sóng sánh.', 'Risotto ngon nhất khi ăn nóng ngay lúc vừa tắt bếp; phần dư bảo quản ngăn mát tối đa 2 ngày, hâm lại bằng chảo nhỏ với ít nước dùng rau củ nóng.', 'italian', 'mon_kho', NULL, 'medium', 15, 30, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cơm Risotto","Rau bina","Nấm đùi gà","Thanh đạm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["milk","sulphites"]', 577, 576.8, 2412, 15, 18.4, 7.9, 84.1, 5, 6.1, 1418, 3.54, '["USDA FDC 168462","USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171595","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC Arborio Rice Ref"]', '4dc2dc902cfda0f26defb1ba00a0791720c4e7a244126b8fede0ff7885953196', '7c10fe09541c9202f605ad23d76ec87fb33312646b15218af25248fde13a9dea', 4),
('imp-de5ce12092f4f0aa', 'frittata-rau-bina-pho-mai', 255, 'Trứng chiên kiểu Ý Frittata rau bina phô mai', 'Khối trứng chiên dày xốp kết hợp rau bina xào thơm, hành tây ngọt dịu cùng hai lớp phô mai Parmesan và Mozzarella tan chảy béo ngậy', 'Frittata rau bina phô mai là món trứng chiên dày kiểu Ý giàu đạm và chất xơ, dễ làm ngay trên bếp chảo chống dính mà không cần lò nướng. Rau bina được làm xẹp và vắt thật ráo nước để khối trứng chiên lên xốp mềm, thơm ngậy phô mai.', 'Trượt khối Frittata ra thớt hoặc đĩa lớn, để nguội bớt 2 phút rồi cắt thành 6 múi tam giác đều nhau, ăn kèm salad rau trộn dầu giấm hoặc bánh mì nướng.', 'Frittata ăn ngon cả khi nóng lẫn nguội; có thể bọc kín bảo quản ngăn mát 2–3 ngày và hâm nóng nhẹ bằng chảo khô lửa nhỏ hoặc thưởng thức ở nhiệt độ phòng.', 'italian', 'mon_chien', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Frittata","Trứng chiên","Rau bina","Phô mai"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","milk"]', 345, 345.4, 1445, 24.8, 23.9, 8.6, 8.5, 2.4, 2.6, 1043, 2.61, '["USDA FDC 168462","USDA FDC 169230","USDA FDC 170000","USDA FDC 170845","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468"]', '846524a24b5a932b4878721d1feb219e79686d05a40d4afa02c555304b6fc511', '5ff16d7d8e38658f595624c3549c27ecbb484392825d8633541817c8231c65d0', 4),
('imp-b8d2cb0b37dbdb81', 'ga-sot-chanh-bo-y', 256, 'Ức gà áp chảo sốt chanh bơ kiểu Ý', 'Miếng ức gà áo bột mỏng áp chảo vàng giòn hai mặt rồi om thấm sốt chanh vàng thơm lừng hương thảo, đánh bóng béo mượt bằng bơ lạt lạnh', 'Pollo al limone là món gà sốt chanh bơ thanh lịch đặc trưng của ẩm thực Ý. Ức gà cắt miếng đều được phủ lớp bột mì mỏng rồi áp chảo vàng ươm, sau đó rim nhẹ trong nước cốt và vỏ chanh vàng cùng hương thảo, hoàn thiện với bơ lạt lạnh tạo sốt bóng mượt.', 'Xếp gà ra đĩa ấm, rưới đều phần sốt chanh bơ sánh bóng lên trên và rắc chút ngò tây tươi thái nhỏ; ăn kèm cơm trắng, mì Ý bơ tỏi hoặc bánh mì giòn chấm sốt.', 'Thịt gà sốt chanh bơ bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa nhỏ cùng 1–2 muỗng canh nước lọc để sốt không bị tách dầu.', 'italian', 'mon_chien', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Ức gà","Sốt chanh bơ","Áp chảo","Thanh nhẹ"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["chicken","milk","wheat"]', 369, 369.3, 1545, 35.1, 21.2, 7.9, 9.1, 1.5, 0.8, 717, 1.79, '["USDA FDC 167746","USDA FDC 169230","USDA FDC 169761","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '3381b926a82817c310adceb950e9ca381f87d198f8f1c0c01fd41adf150e66ec', '30ed9cdca30621c608616283c422c08b6a1844e5d4db67b25be4ef026e433889', 4),
('imp-a4d02f2246e0e115', 'ga-cacciatore-nam', 257, 'Gà om nấm sốt cà chua Cacciatore', 'Đùi gà áp chảo vàng da om mềm thấm đẫm sốt cà chua tươi, nấm đùi gà giòn ngọt, rượu vang trắng và hương thảo kiểu thợ săn Ý', 'Gà om nấm Cacciatore là món ăn đồng quê ấm áp của nước Ý. Đùi gà áo bột mỏng áp chảo xém da rồi được om chậm trong nền rau củ hành tây, cần tây, nấm đùi gà, rượu vang trắng và cà chua chín mọng thơm mùi hương thảo, lá nguyệt quế.', 'Múc gà om nấm cùng nước sốt đỏ sánh ra đĩa sâu lòng, rắc ngò tây tươi băm nhuyễn; dùng nóng kèm bánh mì giòn chấm sốt, cơm trắng hoặc mì Ý luộc.', 'Món gà om Cacciatore để qua đêm càng thấm vị; bảo quản hộp kín trong ngăn mát tối đa 3 ngày và hâm nóng lại trên chảo lửa nhỏ đến khi sôi đều.', 'italian', 'mon_kho', NULL, 'medium', 15, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cacciatore","Đùi gà om","Nấm đùi gà","Cà chua"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["celery","chicken","sulphites","wheat"]', 434, 434.3, 1817, 33.9, 23.8, 5.6, 16.5, 4, 5.6, 809, 2.02, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169761","USDA FDC 169988","USDA FDC 170000","USDA FDC 170416","USDA FDC 170457","USDA FDC 170917","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 172385","USDA FDC 172883","USDA FDC 173190","USDA FDC 173468","USDA FDC 173475"]', 'd54870ed48f7eca95054bd9541d96e3452b127e039448df06d95949b43c4e9f5', 'f84aef6a626a26c03fd36b7f47babb29fa237c499816312627e7a238527b2484', 4),
('imp-a60814a4aca4143b', 'vien-thit-polpette-ca-chua', 258, 'Thịt viên bò sốt cà chua Polpette', 'Thịt bò xay trộn ruột bánh mì tươi, trứng gà và hai loại phô mai Ý vo viên nhỏ om mềm trong sốt cà chua Passata thơm lá húng quế', 'Polpette là món thịt viên om sốt cà chua truyền thống trong bữa cơm gia đình Ý. Thịt bò xay được nhào cùng ruột bánh mì gối tươi, trứng gà, nhục đậu khấu và phô mai Parmesan, Pecorino giúp viên thịt mềm ẩm mà không bị khô, sau đó thả trực tiếp vào sốt cà chua ninh sánh.', 'Múc các viên thịt Polpette ra đĩa sâu lòng cùng nhiều sốt cà chua nóng hổi, điểm thêm vài lá húng quế tươi; dùng kèm bánh mì giòn chấm sốt hoặc trộn với mì Ý.', 'Thịt viên om sốt bảo quản hộp kín trong ngăn mát tối đa 2–3 ngày; khi dùng hâm nóng trên chảo lửa nhỏ cùng chút nước lọc đến khi sốt sôi nhẹ.', 'italian', 'mon_kho', NULL, 'medium', 25, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Polpette","Thịt bò viên","Sốt cà chua","Gia đình"]', '["lunch","dinner"]', '["braise","simmer"]', '["beef","egg","milk","wheat"]', 644, 644.2, 2696, 41.2, 39.9, 14.4, 31.5, 5.2, 12.3, 1512, 3.78, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171326","USDA FDC 171413","USDA FDC 172232","USDA FDC 172687","USDA FDC 173468","USDA FDC 174036","USDA FDC Pecorino Ref"]', 'e78fa2063c5b1ff16bc643117f05fc486f568fd0d421273b2698d7beaf4968da', 'abf00a5ed6ad194afdb22f7b08337394b2871ff1e9f1c7968134c4c016c61228', 4),
('imp-5504378372dc989b', 'sup-minestrone-rau-cu', 259, 'Súp rau củ Ý Minestrone', 'Nồi súp rau củ đa sắc màu ninh chậm từ cà rốt, bí đỏ, khoai tây, đậu trắng, bắp cải và nui Ý ngắn thơm dịu mùi hương thảo và dầu ô liu', 'Súp Minestrone là món canh rau củ truyền thống giàu chất xơ của nước Ý. Hàng chục loại rau củ tươi được cắt hạt lựu đều nhau rồi cho vào nồi theo từng đợt chín dần, hòa quyện cùng đậu trắng bùi béo và bó thơm hương thảo, nguyệt quế.', 'Múc súp Minestrone nóng ra bát sâu lòng, rưới nhẹ một vòng dầu ô liu nguyên chất và rắc thêm tiêu đen xay; có thể dùng kèm bánh mì nướng giòn hoặc phô mai Parmesan bào.', 'Súp Minestrone để qua đêm hương vị càng hòa quyện; bảo quản hộp kín trong ngăn mát tối đa 3 ngày và đun sôi lại trên lửa vừa trước khi ăn (nên luộc riêng nui nếu để lâu).', 'italian', 'mon_canh', NULL, 'easy', 20, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Súp Minestrone","Rau củ","Thanh nhẹ","Mùa lạnh"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["celery","wheat"]', 322, 322.3, 1349, 10.7, 10.3, 1.5, 50.7, 9.1, 9.8, 749, 1.87, '["USDA FDC 168448","USDA FDC 168927","USDA FDC 169230","USDA FDC 169246","USDA FDC 169291","USDA FDC 169961","USDA FDC 169975","USDA FDC 169986","USDA FDC 169988","USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170457","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647","USDA FDC 175200"]', '2740cce4459f436dc6b8d1dcf3c0f3a7ed3bd8395469e14ec05f0d4c57c0cca2', '00ea92644faff9a08bc0d28f15716588474189d05e025fe49096fa48a419be13', 4),
('imp-b6496331f7aa0ee9', 'mi-y-tom-kem-chanh', 260, 'Mì Ý tôm tươi sốt kem chanh', 'Tôm tươi giòn ngọt nấu cùng sốt kem béo mượt thơm nồng tỏi bơ, rượu vang trắng, phô mai Parmesan và hương chanh vàng thanh mát', 'Mì Ý tôm tươi sốt kem chanh là món pasta hải sản sang trọng nhưng chế biến gọn nhẹ. Vị ngọt tự nhiên của tôm tươi hòa cùng sốt kem tươi sánh mịn, phô mai Parmesan và vị chua dịu từ vỏ, nước cốt chanh vàng giúp món ăn béo mà không hề ngán.', 'Gắp mì và tôm ra 3 đĩa sâu lòng khi còn nóng, rưới đều sốt kem chanh lên trên, rắc ngò tây tươi thái nhỏ và chút phô mai Parmesan bào mịn.', 'Món mì hải sản sốt kem ngon nhất khi dùng ngay lúc nóng; nếu còn dư bảo quản ngăn mát tối đa 2 ngày và hâm nóng nhẹ trên chảo lửa nhỏ với chút kem tươi.', 'italian', 'mon_bun_pho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Tôm tươi","Sốt kem chanh","Hải sản"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["crustaceans","milk","shrimp","sulphites","wheat"]', 738, 737.6, 3086, 39.7, 36.9, 22.6, 57.4, 2.9, 4.5, 919, 2.3, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 169230","USDA FDC 169761","USDA FDC 170416","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '908df6c3d9f0a408f77cba18541171b7c9e3fc95f12181404a15c1a2456f9286', '8f8a6613387bbb561438f4dbc4cb19bae311b751917c0c04adb2f0c436f03485', 4),
('imp-d6f7b2ef8f347338', 'canh-dua-suon-non', 261, 'Canh dứa sườn non', 'Sườn non heo hầm mềm ngọt xương hòa quyện cùng vị chua ngọt tự nhiên của dứa chín và cà chua đặc trưng ẩm thực Nam Bộ', 'Canh dứa sườn non là món canh khai vị quen thuộc trong bữa cơm Nam Bộ. Sườn non được chần sạch rồi hầm liu riu ra nước ngọt thanh, nấu cùng dứa chín và cà chua tạo vị chua ngọt tự nhiên rất bắt cơm.', 'Dọn canh nóng vào tô lớn, rắc hành lá và ngò gai thái nhỏ; dùng kèm cơm trắng và chén nước mắm ớt mặn để chấm từng miếng sườn non mềm ngọt.', 'Có thể bảo quản ngăn mát tủ lạnh trong hộp kín tối đa 2 ngày; khi ăn đun sôi lại trên lửa vừa 5 phút để sườn nóng đều và thấm vị nước canh.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Sườn non","Dứa chín","Nam Bộ","Chua ngọt"]', '["lunch","dinner"]', '["simmer"]', '["fish","pork"]', 327, 327, 1368, 14.5, 23.6, 7.7, 15, 2, 10.3, 1493, 3.73, '["USDA FDC 167861","USDA FDC 169124","USDA FDC 169655","USDA FDC 169918","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', 'b2964be88a73bd77f88807efcb925e53a0fe6edadb0b047c77156bd29f0524e0', '50283ebdc7b6c09b55126ad7b39adbecb011c08985f532f78772a85bf77a5746', 4),
('imp-5e0564249085d9c1', 'canh-tom-bong-cai', 262, 'Canh tôm bông cải xanh', 'Nước canh trong veo ngọt thanh tự nhiên từ tôm tươi quyện cùng những bông cải xanh giòn ngọt đầy dinh dưỡng', 'Canh tôm bông cải xanh là món canh nấu nhanh giàu đạm và chất xơ. Tôm tươi bóc vỏ giã dập nhẹ hoặc giữ nguyên con nấu cùng bông cải xanh giòn ngọt, tạo nên bát canh trong thanh, nhẹ bụng cho cả gia đình.', 'Dọn canh nóng ra tô, rắc hành lá, ngò rí và chút tiêu xay; ăn kèm cơm trắng và một món mặn như thịt kho tiêu hoặc trứng chiên.', 'Món canh rau xanh ngon nhất khi dùng ngay lúc mới nấu để bông cải giữ màu xanh tươi và độ giòn; nếu bảo quản tủ mát tối đa 24 giờ, chỉ hâm sôi nhanh 1–2 phút trước khi ăn.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Bông cải xanh","Thanh mát","Nấu nhanh"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 138, 137.7, 576, 16.4, 5.1, 0.8, 8.6, 2.6, 2.1, 1336, 3.34, '["USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170379","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'a5377f7dcb2f463d99683d78e8829e3869a71f9d004b05efcf12e598166590e6', 'd599b2117f91735348416ebb790d7d97520fe921d987fef3fae78490f4be4d42', 4),
('imp-9daae727e7894587', 'canh-ga-bap-cai-ngot', 263, 'Canh gà nấu bắp cải ngọt', 'Thịt đùi gà ta hầm thơm gừng tươi cùng bắp cải giòn ngọt và cà rốt đỏ cam, nước canh trong veo ấm bụng cho bữa cơm gia đình', 'Canh gà nấu bắp cải ngọt mang đến hương vị thanh dịu dễ ăn. Thịt đùi gà chặt miếng ướp nhẹ gừng hành rồi ninh mềm, kết hợp cùng bắp cải và cà rốt tiết ra vị ngọt tự nhiên giúp nước canh trong lành và đậm đà.', 'Dùng canh nóng trong bữa cơm chiều mát hoặc ngày mưa, rắc thêm hành lá và tiêu xay; chấm thịt gà với muối tiêu chanh hoặc nước mắm ớt.', 'Nếu dùng không hết, để nguội hoàn toàn rồi đậy kín cất ngăn mát tối đa 24 giờ; khi hâm lại đun sôi nhẹ 3–4 phút trên lửa vừa để bắp cải không bị nát.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Đùi gà","Bắp cải","Cà rốt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["chicken","fish"]', 279, 278.5, 1166, 23.8, 15.4, 3.8, 11.3, 3.3, 5.9, 1252, 3.13, '["USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd59920258983adce2292b97cad4f10595b84d8935d2393fded5c9848d29d5ff9', 'd3797087cc02a3ba321f0e54f6f66d4bc75be8d1e5bce5a2d9e69d262244a5be', 4),
('imp-20123919cd3164a8', 'canh-ca-hoi-ca-chua', 264, 'Canh chua cá hồi cà chua dứa', 'Cá hồi béo mềm không tanh hòa quyện nước canh chua thanh từ cà chua, dứa chín, măng chua và chanh tươi thơm mùi rau ngổ', 'Canh chua cá hồi cà chua dứa kết hợp miếng cá hồi giàu béo mềm ngọt với hương vị canh chua truyền thống gồm dứa thơm, cà chua, măng chua, dọc mùng và rau ngổ. Nước canh đậm đà chua thanh dịu nhẹ, rất hợp cơm ngày nóng.', 'Dọn canh nóng ra tô, rắc hành lá, rau ngổ và vài lát ớt tươi; chấm thịt cá hồi với nước mắm ớt để cảm nhận trọn vị béo ngọt.', 'Canh cá hồi nên ăn hết trong bữa để tránh cá bị bở và dậy mùi tanh; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhẹ nước dùng rồi hâm cá ở lửa nhỏ 2 phút.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Cá hồi","Canh chua","Hải sản","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer"]', '["fish","salmon"]', 384, 384.3, 1607, 28.3, 20.6, 4.3, 23.4, 4.5, 15, 1403, 3.51, '["NIN VN Doc Mung Ref","USDA FDC 168155","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169958","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175167","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', 'ad6478a303e338eed8299f3ff4e0639300c8930f652802408d35a6469fe9b31b', '5fe30bc37fe646fa8e0042c0a80710186548ca011a076d068587186861faf681', 4),
('imp-d500b08871587628', 'tom-kho-dua-keo', 265, 'Tôm kho dứa sánh keo', 'Tôm tươi bóc vỏ chừa đuôi rim cùng dứa chín cắt lát và nước mắm đường sánh keo, hòa quyện vị chua thanh ngọt mặn chuẩn cơm nhà Nam Bộ', 'Tôm tươi thịt chắc ngọt quyện trong lớp nước sốt dứa chín chua dịu sánh keo bám bóng màu đỏ cam, thơm mùi hành tỏi phi và tiêu xay cay ấm.', 'Trút tôm kho dứa ra đĩa, rưới sốt keo và rắc hành lá cùng tiêu xay; ăn nóng với cơm trắng dẻo và canh rau tập tàng.', 'Ngon nhất khi thưởng thức nóng trong ngày; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa nhỏ.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Tôm tươi","Dứa chín","Nam Bộ","Đưa cơm"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","shrimp"]', 198, 197.6, 827, 20, 6.2, 0.9, 17.3, 1.5, 12.4, 1274, 3.19, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '9dfd65a718a70b14640cebedce6147684664665850916dfd2c1220e78a12f1e2', '3a141299485836379c70c0698da6f7a5fa755b50e4ac744b1f945b7ed0cfa4b9', 4),
('imp-c7e40140f9ee9591', 'ga-kho-sa-ot-do', 266, 'Gà kho sả ớt đỏ', 'Thịt đùi gà kho sả băm và ớt hiểm đỏ lên màu cánh gián bắt mắt, vị mặn ngọt đậm đà quyện hương thơm cay nồng chuẩn vị Nam Bộ', 'Đùi gà chặt miếng săn chắc thấm đẫm hương thơm nồng của sả băm và ớt hiểm đỏ cay dịu, nước sốt thắng caramel nâu đỏ sánh bóng cực kỳ bắt cơm.', 'Múc gà kho sả ớt ra đĩa sâu lòng, rắc hành lá cắt khúc và tiêu xay; ăn nóng với cơm trắng cùng đĩa rau luộc hoặc dưa leo.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng đun nóng lại trên lửa nhỏ với 1–2 muỗng nước ấm để sốt bóng mượt.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Gà kho sả ớt","Nam Bộ","Món kho","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["chicken","fish"]', 359, 358.6, 1501, 29.3, 19.4, 4.8, 16.3, 0.7, 8.5, 1326, 3.32, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'eabfdd51857dab2b3c7f650d6a014159dbe1a2d9b7fcb802037152682e7711fa', '97198b0e316540be70733d94c939920b9c1d8f14d2b5d5a269b301c2b9791bd2', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-ebbd704089d9c62a', 'ga-xao-hanh-tay', 267, 'Gà xào hành tây sốt dầu hào', 'Thịt đùi gà săn mềm om thấm sốt dầu hào nước tương đậm vị, kết hợp hành tây giòn ngọt và hương sả tỏi thơm lừng', 'Gà xào hành tây sốt dầu hào có lớp thịt đùi gà mềm mọng không bị khô, thấm đẫm hương sả, hành tím và tỏi phi quyện trong nước sốt mặn ngọt hài hòa cùng những múi hành tây chín tới giòn ngọt thanh.', 'Múc gà xào hành tây ra đĩa sâu lòng cùng phần nước sốt nâu óng, rắc thêm chút tiêu đen xay; dùng nóng kèm cơm trắng hoặc bánh mì đều rất ngon.', 'Cất hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi dùng hâm nóng trên chảo lửa vừa với 1 muỗng canh nước lọc khoảng 3 phút cho gà và sốt nóng đều.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 20, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Hành tây","Đậm đà","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish","molluscs","soybean","wheat"]', 399, 398.9, 1669, 31.2, 22.9, 5.4, 16.6, 1.7, 7.7, 1543, 3.86, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '58242de04412affdc6fe7a3a3d56fa77c0cbf081e22c2ead18e3f27ff92afb4f', '218863f835479482e8712b3da375608d1c980348acc90ca9272c6458b5724562', 4),
('imp-b7ae5824ff7e6a74', 'su-su-xao-toi', 268, 'Su su xào tỏi', 'Su su non thái lát mỏng giòn sần sật xào lửa lớn cùng tỏi ta đập dập thơm nồng và hành lá xanh mướt', 'Su su xào tỏi là món rau xào thanh mát, mộc mạc mà đưa cơm với những lát su su non giòn ngọt không hề bị nhựa hay nhũn, quyện hương thơm nồng nàn của tỏi đập dập phi vàng và chút vị đậm đà từ nước mắm ngon.', 'Gắp su su xào tỏi ra đĩa khi còn nóng, rắc thêm chút tiêu đen xay; dùng kèm cơm trắng và các món kho mặn.', 'Món rau xào nên ăn ngay trong bữa khi còn nóng để cảm nhận trọn vẹn độ giòn ngọt tự nhiên.', 'vietnamese', 'mon_xao', 'trung', 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Thanh đạm","Dưới 20 phút","Miền Trung"]', '["lunch","dinner"]', '["stir_fry"]', '["fish"]', 117, 117, 489, 2.5, 7.3, 1.1, 12.8, 3.8, 3.8, 894, 2.24, '["USDA FDC 169230","USDA FDC 169990","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'd0eaf2f55f7a75f6db36fd46dc144e184959e027614892eb64c71b96b3cdbd1f', 'f00fefbae95ff59358f94768a9b9619056906ff5f528fec27a7c0a4ff6b1e7a3', 4),
('imp-30c2038c8737538c', 'bo-xao-nam-dui', 269, 'Bò xào nấm đùi gà', 'Thịt thăn bò mềm mọng xào lửa lớn cùng nấm đùi gà giòn sần sật thấm đẫm nước thịt và sốt dầu hào đậm đà', 'Bò xào nấm đùi gà là sự kết hợp tuyệt vời giữa từng lát thịt bò thăn mềm ngọt và những miếng nấm đùi gà giòn dai sần sật, hút trọn vị ngọt của thịt bò cùng hương thơm dầu hào, tỏi phi và tiêu đen.', 'Gắp bò xào nấm đùi gà ra đĩa nóng, rắc ngò rí và tiêu xay lên trên; dùng ngay với cơm trắng và chấm kèm nước tương ớt lát.', 'Món xào ngon nhất khi dùng nóng; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy đảo nóng nhanh trên chảo lửa lớn khoảng 1 phút trước khi ăn.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Nấm","Đậm đà","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","soybean","wheat"]', 304, 303.9, 1272, 22.8, 20, 5.3, 9.5, 2.4, 1.8, 981, 2.45, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC Monosodium Glutamate","VN/Asian Seasoning Powder Avg"]', '5530cbf228a59a7c54bf38970eb9cefa4d17960c91a2d723447b2e97bc410a28', 'a6cc72fa42c21de964498c549da3d7c88b7d1bedae4fb75835f335f64d247fa1', 4),
('imp-019bbf517408a529', 'ca-chien-sot-ca-chua', 270, 'Cá chiên sốt cà chua', 'Cá thu phi lê chiên vàng săn chắc om trong sốt cà chua chín nhuyễn đậm đà mặn ngọt đưa cơm', 'Cá chiên sốt cà chua là món ăn gia đình quen thuộc với khúc cá thịt trắng béo ngọt được chiên vàng đều hai mặt giữ độ săn chắc, sau đó rim nhỏ lửa trong phần sốt cà chua chín đỏ sánh mịn quyện hương thơm hành tím, tỏi và dầu hào.', 'Bày từng khúc cá ra đĩa sâu lòng, rưới phần sốt cà chua óng mượt cùng hành lá và tiêu xay lên trên, ăn nóng kèm cơm trắng dẻo và dưa leo thái lát.', 'Có thể bảo quản hộp kín trong ngăn mát tủ lạnh tới 2 ngày; khi ăn chỉ cần hâm lại trên chảo lửa nhỏ khoảng 5 phút có thêm 1–2 muỗng canh nước lọc để sốt mềm sánh trở lại.', 'vietnamese', 'mon_chien', 'nam', 'medium', 15, 22, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Cá thu","Sốt cà chua","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["fish","molluscs","soybean","wheat"]', 263, 263.1, 1101, 27.4, 12.7, 2.2, 9.8, 1.6, 6.6, 1144, 2.86, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148"]', 'a5612ada9305bbc10be9301e59143c24ffcfb4f5ac9c2133e41091f43a5a0aed', 'f45b338d98afb78e1d8b1fbc90983188b11cd15e265ed125194be25e26ed78a7', 4),
('imp-d7836b7d1a4d90b3', 'nam-chien-gion', 271, 'Nấm đùi gà chiên giòn', 'Nấm đùi gà xé dải chần ráo tẩm trứng và bột năng chiên hai lần giòn rụm, thơm lá húng quế chiên', 'Nấm đùi gà chiên giòn là món ăn vặt lẫn món mặn đưa cơm rất bắt miệng. Thân nấm đùi gà được chần sơ vắt ráo để giữ độ dai ngọt tự nhiên, nhúng qua trứng gà rồi áo bột năng khô chiên hai lửa cùng lá húng quế, tạo lớp vỏ giòn tan mà bên trong vẫn mềm mọng.', 'Xếp nấm chiên giòn và lá húng quế chiên ra đĩa, rắc thêm chút hành lá thái nhỏ nếu thích, dùng nóng ngay và chấm kèm tương ớt cay ngọt.', 'Món này ngon nhất khi ăn nóng ngay sau khi chiên lần hai; tránh để qua đêm trong tủ lạnh vì lớp bột năng sẽ hút ẩm và mất độ giòn.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Nấm đùi gà","Giòn rụm","Ăn vặt","Trẻ em thích"]', '["lunch","dinner"]', '["deep_fry","boil"]', '["egg"]', 313, 313.3, 1311, 5.5, 18.5, 2.9, 33.7, 2.9, 3.7, 756, 1.89, '["USDA FDC 168580","USDA FDC 169717","USDA FDC 170005","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC Sriracha Ref"]', 'd9c60c3abd47b2413b458bc805c0d44033f28f98e29b59b8106b2753209803a6', '392567b19f37770001c4123b0d6338f7210add82bd02805b2ef6ed719ed210fe', 4),
('imp-9d527dacd46efc67', 'dau-phu-chien-sa', 272, 'Đậu phụ chiên sả ớt chay', 'Đậu phụ chiên vàng giòn rụm xóc đều sả băm tỏi ớt phi thơm lừng, đậm vị nước tương ăn kèm dưa leo', 'Đậu phụ chiên sả ớt chay là món ăn dân dã nhưng cực kỳ gây nghiện nhờ sự kết hợp giữa miếng đậu phụ chiên vỏ giòn ruột béo và lớp sả ớt phi thơm giòn đậm vị nước tương, hạt nêm chay. Món thực hiện nhanh gọn, phù hợp cả bữa cơm chay lẫn mặn.', 'Xếp đậu phụ chiên sả ớt vào lòng đĩa có viền dưa leo thái lát mỏng, rắc ngò rí lên trên và dọn nóng cùng cơm trắng, chấm kèm nước tương ớt thái lát.', 'Ngon nhất khi dùng nóng ngay lúc lớp sả phi và vỏ đậu còn giòn; nếu còn dư có thể cất ngăn mát 24 giờ và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4 phút.', 'vietnamese', 'mon_chien', 'nam', 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Món chay","Đậu phụ","Sả ớt","Nam Bộ"]', '["lunch","dinner"]', '["deep_fry","pan_fry"]', '["soybean","wheat"]', 311, 310.7, 1300, 19.2, 20.4, 3, 19.1, 2.6, 3.6, 1062, 2.65, '["USDA FDC 168409","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'c44b20a07f18b2eff2012e54930d7c60c3170464e5b8047555538a2857e19cbc', 'c7c9d348dbad1219be862c1936cd1b931ebcc74c8d8f4be58a1ecf189c2ff876', 4),
('imp-236e3b84d403909e', 'ga-luoc-hanh-la', 273, 'Đùi gà luộc hành lá da vàng giòn', 'Đùi gà tơ luộc chín mềm mọng nước bằng cách ủ nhiệt, da căng bóng vàng ươm ăn kèm muối tiêu chanh lá chanh', 'Đùi gà góc tư luộc vừa sôi rồi ủ chín từ từ giúp thịt mềm ngọt giữ trọn nước, không bị nứt rách da hay đỏ xương; sốc lạnh nhanh cho lớp da giòn sần sật ánh vàng hấp dẫn.', 'Chặt đùi gà thành miếng vừa ăn xếp ra đĩa, rắc hành lá thái nhỏ và lá chanh thái chỉ; dọn kèm chén muối tiêu chanh ớt và tận dụng nước luộc nấu canh hoặc cháo.', 'Gà luộc bọc kín bảo quản ngăn mát tối đa 2 ngày; khi ăn có thể dùng nguội chặt lát hoặc hấp lại 5 phút cho ấm nóng.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món luộc","Gà ta","Giản dị","Cơm nhà","Thanh đạm"]', '["lunch","dinner"]', '["boil"]', '["chicken"]', 381, 380.8, 1594, 40.3, 21.7, 6, 4.5, 1.2, 1, 1214, 3.04, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 169231","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 172231","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'b415115cee7f8e2a289b40da34cfa3686886fd43b03a650a1c4a390855ac7c0f', '8cb5f24779f43fdc212667a83a14f891d2dcb8e5709cd7f785d2d8c7ec53bcf0', 4),
('imp-df7571988423623f', 'muc-hap-sa-ot', 274, 'Mực tươi hấp sả ớt kiểu miền Trung', 'Mực tươi ướp nước mắm tiêu đường hấp nhanh cùng sả đập dập và ớt hiểm, chấm nước mắm chanh cay thơm đậm vị', 'Mực tươi làm sạch nguyên con hoặc cắt khoanh, ướp nhẹ nước mắm đường tiêu rồi hấp lửa lớn cùng sả đập dập, gừng, ớt hiểm và hành lá; thịt mực trắng giòn ngọt lịm chấm nước mắm chanh ớt đúng điệu miền Trung.', 'Gắp mực hấp sả ớt ra đĩa, chan nhẹ phần nước ngọt tiết ra khi hấp; dùng nóng chấm nước mắm chanh tiêu ớt kèm cơm trắng hoặc bánh tráng cuốn rau sống.', 'Mực hấp ngon nhất khi dùng nóng ngay sau khi chín để giữ độ giòn. Nếu còn dư, bảo quản ngăn mát tối đa 24 giờ và hấp lại nhanh 2 phút.', 'vietnamese', 'mon_hap_luoc', 'trung', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Mực","Sả","Miền Trung","Dưới 20 phút"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","squid"]', 161, 161, 674, 23.2, 2.1, 0.5, 11.6, 0.8, 3.7, 1008, 2.52, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 172185","USDA FDC 173647","USDA FDC 174223"]', '56f89c617271ff422afd716b7ae28f920c6a84307c3da81dba72399a46d2108a', 'bcfd87168444f192ec189d624a8f668d833bdb623861d3f44b8a72481809de10', 4),
('imp-2b88b3e83b941e80', 'goi-su-su-tom', 275, 'Gỏi su su tôm giòn mát', 'Su su bào sợi giòn sần sật trộn tôm luộc ngọt thịt, cà rốt, rau răm và ngò rí trong nước mắm chanh tỏi ớt chua ngọt thanh sạch', 'Gỏi su su tôm giòn mát mang vị thanh sạch lạ miệng với từng sợi su su và cà rốt ướp muối vắt ráo giòn sần sật, kết hợp tôm tươi luộc chín đỏ au chẻ đôi, rau răm thơm nồng, hành tím phi giòn và lạc rang bùi béo.', 'Bày gỏi ra đĩa, rắc đậu phộng rang giã dập, hành phi giòn và ngò rí lên trên; dọn ăn ngay kèm bánh phồng tôm.', 'Nên vắt thật ráo su su trước khi trộn và ăn ngay trong bữa; nếu chuẩn bị trước, bảo quản su su cà rốt vắt ráo, tôm luộc và nước trộn riêng trong ngăn mát tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'trung', 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi su su","Tôm tươi","Thanh mát","Khai vị","Miền Trung"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 347, 347, 1451, 19.5, 12.3, 1.7, 43.7, 5.7, 16.4, 1530, 3.82, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169990","USDA FDC 169997","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN Banh Da Ref","VN Rau Ram Ref"]', 'fad96a7a670b68958e530dddf5fc3e761549a98c23274d1f9b058bc2ca615228', '1a5264f3e5b9709011baec7adcc0f49a6df72946b253065073ae38e534fdcbc4', 4),
('imp-0b34a73de8ccab71', 'goi-dau-phu-dua-leo', 276, 'Gỏi đậu phụ dưa leo chay thanh mát', 'Đậu phụ chiên vàng giòn thái sợi trộn dưa leo bỏ ruột giòn mát, cà rốt, rau răm, húng quế và đậu phộng rang trong nước mắm chay chanh tỏi ớt', 'Gỏi đậu phụ dưa leo là món khai vị chay thanh đạm mà đậm vị với từng miếng đậu phụ chiên vàng giòn bên ngoài mềm béo bên trong, quyện cùng dưa leo và cà rốt bóp muối vắt khô giòn sần sật, rau thơm và đậu phộng rang bùi thơm.', 'Bày gỏi ra đĩa, rắc hành lá cắt nhỏ và phần đậu phộng rang giã dập còn lại lên mặt; ăn kèm bánh đa nướng hoặc bánh phồng chay giòn rụm.', 'Đậu phụ chiên nên trộn ngay trước bữa ăn để giữ lớp vỏ giòn; bảo quản riêng dưa leo cà rốt đã vắt ráo và nước mắm chay trong ngăn mát tủ lạnh tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi chay","Đậu phụ","Dưa leo","Thanh đạm","Mát lành"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["peanut","soybean"]', 312, 312.3, 1307, 18.3, 20.3, 2.8, 21, 4.3, 12, 923, 2.31, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172232","USDA FDC 172430","USDA FDC 172475","USDA FDC 173468","VN Rau Ram Ref","Vegetarian Fish Sauce Ref"]', '27be4748d81d03c872673d58e7fd65ac82255ea1daad0f4cfaa7418b1b2e7f91', '066f6f2866b780544e0dff65718ff85a2806c0a0d6394b4e5c6a83e707605173', 4),
('imp-0ea0e53318af9de9', 'bun-bo-nam-bo-tron', 277, 'Bún bò Nam Bộ trộn', 'Thịt bò thăn ướp sả tỏi xì dầu xào nhanh trên lửa lớn, trộn cùng bún tươi, rau sống mát lành, hành phi giòn, đậu phộng rang và nước mắm chua ngọt', 'Tô bún bò Nam Bộ trộn hài hòa giữa vị thịt bò xào sả tỏi mềm mọng nóng hổi, bún tươi thanh mát, rau thơm, giá đỗ giòn sần sật cùng hành phi thơm lừng, đậu phộng rang bùi béo và nước mắm chua ngọt.', 'Xếp xà lách, rau thơm, giá đỗ, dưa leo, cà rốt bào và bún tươi vào tô, đặt thịt bò xào hành tây nóng lên trên, rắc đậu phộng rang, hành phi, hành lá rồi chan nước mắm chua ngọt trộn đều.', 'Có thể chuẩn bị sẵn hành phi, đậu phộng rang và nước mắm pha trước 1–2 ngày; thịt bò nên ướp trước khi ăn và xào nhanh tay ngay trước lúc dọn để giữ độ mềm ngọt.', 'vietnamese', 'mon_bun_pho', 'nam', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Bún bò Nam Bộ","Món trộn","Thịt bò xào","Thanh mát"]', '["lunch","dinner"]', '["stir_fry","toss_mix","assemble"]', '["beef","fish","molluscs","peanut","soybean","wheat"]', 622, 622.3, 2604, 32.6, 24.6, 6.1, 71.5, 6.8, 13.6, 1753, 4.38, '["NIN VN Fresh Bun Ref","USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 172430","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'cf9d8d7be436332194bc029fee56f61dd9d02dfc28cd50046fc866a53f7ff532', '9e93926e735e7ba7654f8f4b275275bfb46bbf3d80f25a40f01a1c32fa50cfcd', 4),
('imp-1fa2a5a65ec5a26d', 'bun-rieu-cua-dau', 278, 'Bún riêu cua đậu', 'Riêu cua đồng kết tảng béo ngậy hòa nước dùng cà chua giấm bỗng chua thanh, ăn kèm đậu phụ chiên vàng và đĩa rau sống chẻ sợi giòn mát', 'Tô bún riêu cua đậu thanh thuần vị quê nhà nổi bật với tảng riêu cua đồng xốp béo, phần nước gạch cua phi hành đỏ óng cùng cà chua, đậu phụ chiên giòn và hương thơm dịu của giấm bỗng.', 'Chia bún tươi ra tô, gắp tảng riêu cua, đậu phụ chiên và cà chua lên trên, chan nước dùng nóng hổi, rắc hành lá rồi dọn kèm rau muống chẻ, hoa chuối bào, kinh giới, chanh, ớt và mắm tôm.', 'Nước riêu và đậu phụ chiên bảo quản ngăn mát tối đa 24 giờ; khi hâm lại giữ lửa vừa tránh khuấy mạnh để không vỡ tảng riêu, sau đó chan lên bún mới trụng.', 'vietnamese', 'mon_bun_pho', 'bac', 'hard', 30, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Bún riêu","Cua đồng","Đậu phụ rán","Ẩm thực miền Bắc"]', '["breakfast","lunch","dinner"]', '["simmer","pan_fry","boil","assemble"]', '["crab","crustaceans","fish","shrimp","soybean"]', 525, 525.3, 2197, 29.8, 17, 2.6, 66.5, 8.2, 7, 2218, 5.55, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","SE Asian Banana Blossom Ref","USDA FDC 168155","USDA FDC 169247","USDA FDC 169378","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '0ed5aa6fcf26c963d9985af4ebc519381b0523962aa5a61d157a272e30b12468', 'afbc8f9420c7573f05ed755bfb3bdcb4e1e9b801b7144805a5abc50597605231', 4),
('imp-ff6d8fe6659e4976', 'bun-cha-ha-noi', 279, 'Bún chả Hà Nội', 'Thịt ba chỉ thái miếng và chả băm viên ướp nước cốt sả hành nướng vàng ươm trong lò, ăn kèm bún tươi, dưa góp giòn và bát nước mắm ấm', 'Bún chả Hà Nội chế biến gọn gàng tại nhà với chả miếng ba chỉ và chả viên nạc vai ướp nước hàng, mắm tôm, cốt sả hành, nướng lò vàng bóng không khô, hòa quyện cùng nước chấm ấm và dưa góp đu đủ cà rốt.', 'Thả chả miếng và chả viên nướng nóng vào bát nước mắm ấm cùng dưa góp đu đủ cà rốt, ăn kèm bún tươi sợi nhỏ và đĩa rau sống kinh giới, tía tô, xà lách.', 'Chả đã nướng có thể bảo quản ngăn mát tối đa 2 ngày; khi ăn nướng lại ở 180°C trong 4 phút rồi thả vào bát nước chấm đun ấm.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 35, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Bún chả","Hà Nội","Món nướng lò","Bữa trưa"]', '["lunch","dinner"]', '["grill_roast","toss_mix","assemble"]', '["crustaceans","fish","pork","shrimp"]', 801, 800.7, 3350, 22.7, 48.3, 16.9, 69.9, 5.2, 17.7, 2016, 5.04, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 167902","USDA FDC 168155","USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref","VN/Asian Seasoning Powder Avg"]', '7e3421425f8c6bc68e4ce3d7c4c66819cbcade652a4c1c2a3a48b6d34ba7320c', '3c7bc5288635673745ee143d9d17ff1701f89ff67b523fdc710699a63d6d4e9f', 4),
('imp-675a6c1cea0b604e', 'com-rang-chay-nam-dau', 280, 'Cơm rang chay nấm đậu phụ rau củ', 'Hạt cơm rang tơi ráo quyện đều nấm đùi gà, đậu phụ chiên hạt lựu, cà rốt giòn ngọt và nước tương thơm lừng', 'Đĩa cơm rang chay đầy đủ dưỡng chất và màu sắc bắt mắt với từng hạt cơm nguội rang tơi ráo bóng nhẹ, hòa quyện cùng nấm đùi gà dai ngọt, đậu phụ cắt hạt lựu béo mềm, cà rốt giòn tươi và mùi thơm quyến rũ của tỏi phi, hành lá.', 'Múc cơm rang nóng ra đĩa, rắc thêm hành lá và tiêu đen xay; ăn kèm dưa leo thái lát và chén nước tương ớt cắt khoanh.', 'Món ăn ngon nhất khi thưởng thức nóng ngay; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy rang nóng lại trên chảo khô lửa vừa 3–4 phút cho hạt cơm tơi lại.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Cơm rang","Đậu phụ","Nấm đùi gà","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["soybean","wheat"]', 438, 437.9, 1832, 16.6, 13.9, 2.1, 63.9, 4.3, 4.3, 1174, 2.94, '["USDA FDC 168580","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '5cd1edeb2d0fd54275023965b3d144843d7d01eadbfca7ae389ea06cb83b8afb', '6562f9f2f3939ab489e19ad55a212bd1dad7f524e96d9710c8b5ce23ea675015', 4),
('imp-4dbcf05ec1f88763', 'nam-xao-sa-ot-chay', 281, 'Nấm đùi gà xào sả ớt chay', 'Nấm đùi gà thái lát dày xào săn vàng cạnh cùng sả băm, ớt hiểm cay nồng, nước tương đậm đà và mè rang thơm bùi', 'Món xào chay đậm đà đưa cơm với từng lát nấm đùi gà giòn dai thấm đẫm nước tương mặn ngọt, phủ đầy sả phi thơm lừng, ớt hiểm cay ấm cùng chút mè trắng rang bùi béo và hành lá xanh tươi.', 'Gắp nấm đùi gà xào sả ớt ra đĩa, rắc mè trắng rang và ngò rí lên trên; dùng nóng cùng cơm trắng dẻo thơm.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2–3 ngày vì nấm xào khô sả ớt càng để càng thấm vị; hâm nóng lại trên chảo 2–3 phút trước khi ăn.', 'vietnamese', 'mon_chay', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Nam Bộ","Nấm đùi gà","Xào sả ớt","Đậm vị"]', '["lunch","dinner"]', '["stir_fry"]', '["sesame","soybean","wheat"]', 148, 147.8, 618, 5.9, 7.5, 1.1, 18.1, 3.3, 5.7, 1124, 2.81, '["USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","USDA FDC Monosodium Glutamate","Vegetarian Seasoning Powder Ref"]', '48d9bd7223c1d2c2db1e74a5440af04903061f99e9ef47a55266a5c19b5d6438', '6a413b7030fe5b27b5e46fd405e83e67ba4c1af488febcea9ef38491908121e7', 4),
('imp-b88c09328fa3f33a', 'goi-cuon-chay-nam-dau', 282, 'Gỏi cuốn chay nấm đậu phụ', 'Bánh tráng cuốn chặt tay nhân bún tươi, đậu phụ chiên tẩm nước tương, nấm đùi gà xào, rau sống giòn mát và nước chấm chua ngọt', 'Những cuốn gỏi chay tròn đầy thanh mát với lớp bánh tráng dẻo mỏng ôm trọn nhân đậu phụ chiên tẩm nước tương đậm vị, nấm đùi gà xào dai ngọt, bún gạo tươi, cà rốt, dưa leo, giá đỗ và rau thơm giòn tươi, chấm cùng nước tương chanh ớt mè rang.', 'Xếp gỏi cuốn ra đĩa, có thể cắt đôi chéo để lộ phần nhân nhiều màu sắc hấp dẫn; dọn ăn ngay kèm chén nước chấm nước tương chua cay rắc mè trắng rang.', 'Gỏi cuốn ngon nhất khi dùng ngay sau khi cuốn; nếu chưa ăn ngay cần bọc màng bọc thực phẩm từng cuốn để bánh tráng không bị khô cứng và dùng trong vòng 4 giờ.', 'vietnamese', 'mon_chay', 'nam', 'easy', 25, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chay","Gỏi cuốn","Nam Bộ","Mát lành","Bánh tráng"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry","boil","assemble"]', '["sesame","soybean","wheat"]', 391, 391.4, 1638, 16.7, 11.7, 1.7, 60, 5.6, 9.5, 1254, 3.14, '["NIN VN Fresh Bun Ref","USDA FDC 168155","USDA FDC 168409","USDA FDC 168580","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169994","USDA FDC 170150","USDA FDC 170393","USDA FDC 171319","USDA FDC 171413","USDA FDC 172232","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","USDA FDC Rice Paper Ref","Vegetarian Seasoning Powder Ref"]', '9d5c1f888ba2c790ca92db94015eb8766aaff98f7795f4a08eac9bdbce67cf49', 'a379b7a19540c9204b4d4bcf0eb05f45a759b2c3418b5043d3d4febd97a81f45', 4),
('imp-66711b78b6c12643', 'com-tam-suon-nuong', 283, 'Cơm tấm sườn nướng', 'Sườn cốt lết ướp mật ong sữa tươi nướng xém thơm bên cơm tấm dẻo, trứng ốp la, mỡ hành và đồ chua nước mắm kẹo', 'Đĩa cơm tấm sườn nướng chuẩn vị Sài Gòn với miếng sườn cốt lết ướp sữa tươi mật ong nướng vàng ươm mềm mọng, hạt cơm tấm tơi dẻo phủ mỡ hành béo xanh, trứng gà ốp la lòng đào, đồ chua củ cải cà rốt giòn thanh và chén nước mắm chua ngọt kẹo.', 'Xếp cơm tấm ra đĩa lớn, đặt sườn nướng, trứng ốp la và đồ chua bên cạnh, rưới mỡ hành béo thơm lên cơm và sườn rồi ăn nóng kèm chén nước mắm tỏi ớt chua ngọt.', 'Sườn ướp có thể bảo quản ngăn mát qua đêm để nướng sáng hôm sau càng thấm vị; cơm tấm và sườn chín giữ ngăn mát tối đa 2 ngày, hâm nóng sườn bằng nồi chiên không dầu 170°C trong 4 phút.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'medium', 25, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Cơm tấm","Sườn nướng","Nam Bộ","Quốc dân","Mỡ hành"]', '["breakfast","lunch","dinner"]', '["grill_roast","pan_fry","boil"]', '["egg","fish","milk","molluscs","pork","soybean","wheat"]', 725, 724.8, 3032, 41.5, 20.7, 5.7, 90.1, 2.8, 21.9, 1979, 4.95, '["USDA FDC 167827","USDA FDC 168452","USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647"]', '60cc8450baebff5124d0d21e275acc44364270700cd0a4b6d71305b05a505090', '1a33ffcfd7217cd652016f46c7cd1e2f288e0bdb66b3640110ad4129cbd9869d', 4),
('imp-6a3a83f38e6d3f9c', 'chao-bo-gung', 284, 'Cháo bò gừng', 'Cháo gạo rang nấu sánh mịn cùng thịt bò thăn thái mỏng chín tới, gừng sợi ấm nồng và hành lá tía tô', 'Tô cháo bò gừng nóng hổi thơm lừng với hạt gạo tẻ kết hợp gạo nếp rang thơm nở bung sánh mịn, lát thịt bò thăn mềm ngọt chín tái tới ngay trong cháo sôi cùng gừng tươi thái chỉ, hành lá và lá tía tô giải cảm ấm người.', 'Chan cháo đang sôi sục lên bát thịt bò ướp gừng tỏi đã lót sẵn tía tô và hành lá, rắc tiêu đen xay rồi dùng nóng ngay.', 'Nên ăn nóng ngay sau khi chan cháo để thịt bò mềm ngọt không bị dai. Phần cháo trắng nấu sẵn có thể bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại cháo rồi mới thả thịt bò ướp vào.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo bò","Gừng ấm","Ăn sáng","Bổ dưỡng","Ấm bụng"]', '["breakfast","dinner"]', '["boil","simmer"]', '["beef","fish"]', 379, 379.4, 1588, 20.2, 11.5, 3.7, 47.1, 1.8, 1.3, 1250, 3.13, '["MEXT Shiso Ref","USDA FDC 168881","USDA FDC 169230","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170187","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '958040d9cdab014541f274242c7b737fe2145bf545c1fe7a2918ae239964d027', '40d5175650b3d9fdee9e671597138882ebb8afd1bd01b6e03a37dc672488c8b4', 4),
('imp-b1dcb812f8671a49', 'banh-trang-nuong-pho-mai', 285, 'Bánh tráng nướng phô mai', 'Bánh tráng gạo nướng chảo giòn rụm phủ trứng gà, phô mai mozzarella kéo sợi, xúc xích và hành phi thơm lừng', 'Món bánh tráng nướng phô mai kiểu Đà Lạt hấp dẫn ngay trên chảo chống dính với đế bánh tráng gạo giòn tan, lớp trứng gà hành lá béo thơm phủ đầy phô mai mozzarella tan chảy kéo sợi, xúc xích thái lát, hành tím phi và tương ớt mayonnaise.', 'Gấp đôi chiếc bánh tráng nướng giòn rụm hoặc cắt thành miếng tam giác bằng kéo, thưởng thức ngay khi phô mai còn kéo sợi nóng hổi.', 'Bánh tráng nướng ngon nhất khi ăn ngay sau khi nướng để đế giữ độ giòn rụm. Không nên bảo quản bánh đã nướng quá lâu vì trứng và sốt sẽ làm mềm đế bánh.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'easy', 8, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Bánh tráng nướng","Phô mai","Nam Bộ","Ăn vặt","Dưới 20 phút"]', '["breakfast","lunch"]', '["pan_fry","grill_roast"]', '["egg","milk","pork"]', 362, 361.6, 1513, 16, 23.2, 7.5, 21.9, 0.8, 4, 847, 2.12, '["USDA / Chinese Sausage Ref","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170845","USDA FDC 171009","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC Rice Paper Ref","USDA FDC Sriracha Ref"]', '67a3a8bb4c245ac92bdf1aeb030129af27a767dffa5b30e606675249a507777b', '2fcdc1bb673ca9bd537b22f4f8857f8f58d7b187c7337d54e83cf798694e644d', 4),
('imp-8f24a253602fc9be', 'lau-ca-chua-dua', 286, 'Lẩu cá chua dứa miền Tây', 'Cá diêu hồng tươi săn ngọt nấu trong nước lẩu chua thanh từ dứa chín, cà chua và nước cốt chanh, thơm nồng sả gừng và rau ngổ', 'Lẩu cá chua dứa miền Tây mang hương vị thanh mát đặc trưng vùng sông nước. Cá diêu hồng tươi cắt khúc nấu chín vừa tới giữ thịt trắng ngọt săn chắc, hòa quyện nước lẩu chua dịu từ dứa chín, cà chua và chanh tươi, thơm lừng mùi sả, gừng, ngò gai và rau ngổ.', 'Bày đĩa cá diêu hồng, nấm đùi gà, rau muống, dọc mùng và bún tươi quanh nồi lẩu sôi; nhúng cá và rau ăn nóng, chấm thịt cá với chén nước mắm gừng ớt mặn.', 'Món lẩu cá nên dùng hết trong bữa để thịt cá không bị tanh hay bở; phần nước lẩu chưa nhúng cá có thể bảo quản ngăn mát tối đa 24 giờ và đun sôi lại 3 phút.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 20, 40, 5, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Cá diêu hồng","Dứa chín","Miền Tây","Chua ngọt"]', '["lunch","dinner"]', '["simmer","boil"]', '["fish"]', 453, 453, 1894, 38.2, 10.4, 2, 53.3, 5.6, 11.9, 1789, 4.47, '["Chili Oil / Satay Ref","NIN VN Doc Mung Ref","NIN VN Fresh Rice Noodle Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169378","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","VN Culinary Herb Ref","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', '22a53d21e7539c4707152b453f5b656b0fcf21ea4be56413425dd97023bfa3c5', '401f027f0997c41a335be332df973a1809e67e39e2b475a5c98d620e9d121c0d', 4),
('imp-cd86ce166f002f60', 'suon-ham-tuong-dau', 287, 'Sườn non hầm tương đậu đen', 'Sườn non áp chảo vàng cạnh hầm liu riu cùng đậu tương đen lên men tàu xì, xì dầu và gừng tỏi cho đến khi mềm rục tách xương', 'Món hầm truyền thống Trung Hoa nổi bật với hương vị bùi mặn đặc trưng của đậu tương đen lên men (tàu xì) quyện cùng xì dầu, rượu Thiệu Hưng và gừng tỏi thơm nồng, thấm sâu vào từng miếng sườn non mềm rục.', 'Múc sườn hầm cùng nước sốt đen bóng sánh đặc ra đĩa sâu lòng, rắc hành lá xanh thái nhỏ và ăn nóng với cơm trắng dẻo.', 'Để nguội hoàn toàn và bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi ăn hâm lại trên lửa nhỏ với 2 muỗng canh nước lọc để sốt không bị khét.', 'chinese', 'mon_kho', NULL, 'medium', 15, 65, 4, '/frigo/illustrations/delicious-meal.png', '["Món hầm","Sườn non","Tàu xì","Đậm đà","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["pork","soybean","wheat"]', 450, 450.3, 1884, 22.6, 35.7, 12, 6.9, 0.8, 2.9, 1242, 3.11, '["Dark Soy Sauce Label Ref","Douchi Reference","Shaoxing Wine Ref","USDA FDC 167861","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '2ad9f16afa492acfbdf199db9e6ccabeb271bc27a7a5351ea2bce2d023c6ae38', '578407ad83eb01054e0969f099e3a8ef8a4187c26b27934546fd944520418774', 4),
('imp-3e8e08fb584de7f3', 'bo-ham-gung-dam', 288, 'Thịt bò hầm gừng cà rốt đậm vị', 'Nạm bò mềm rục thấm đẫm hương gừng ấm, hồi quế, tương đậu cay và xì dầu đặc, quyện cùng cà rốt ngọt thanh sánh mịn', 'Món bò hầm chuẩn vị gia đình Trung Hoa ấm nồng mùi gừng tươi thái lát, hoa hồi và lá nguyệt quế, hòa quyện vị cay nhẹ từ tương đậu bản Tứ Xuyên cùng nước dùng bò sánh đậm ôm trọn từng miếng thịt bò mềm tan và cà rốt ngọt bùi.', 'Múc thịt bò hầm và cà rốt ra tô sâu lòng, chan nước sốt nâu đỏ sánh mịn, rắc hành lá thái nhỏ và ăn nóng cùng cơm trắng hoặc bánh mì.', 'Món hầm để qua đêm trong ngăn mát tủ lạnh sẽ càng thấm gia vị, bảo quản kín tối đa 3 ngày; hâm sôi kỹ lại trên lửa nhỏ trước khi dùng.', 'chinese', 'mon_kho', NULL, 'medium', 20, 135, 4, '/frigo/illustrations/delicious-meal.png', '["Thịt bò","Món hầm","Gừng ấm","Mùa lạnh","Đậm đà"]', '["lunch","dinner"]', '["boil","pan_fry","braise","simmer"]', '["beef","soybean","wheat"]', 618, 618.4, 2588, 46.7, 38.3, 14.8, 19.2, 2.6, 8.8, 1563, 3.91, '["Dark Soy Sauce Label Ref","Pixian Doubanjiang Ref","Shaoxing Wine Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170198","USDA FDC 170393","USDA FDC 170917","USDA FDC 171316","USDA FDC 171413","USDA FDC 171593","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', '3e3d2ec42347c2113274bcb2968f1c484f4f2b50edb4342f109b2359747cd77b', '51aed921a28a41a1f840bea2596fbbb64701d152d2efe0ce537275aeb15a50f8', 4),
('imp-abcc9b72400680cf', 'trung-cuon-hanh-la-trung', 289, 'Trứng cuộn hành lá áp chảo kiểu Trung', 'Những cuộn trứng mỏng mềm xốp mịn thơm lừng hành lá và tiêu trắng, rưới nhẹ xì dầu nhạt đậm đà cho bữa sáng hoặc món khai vị', 'Món trứng cuộn hành lá đơn giản nhưng tinh tế của bếp Hoa, tráng từng lớp mỏng trên chảo chống dính với chút bột bắp và rượu Thiệu Hưng giúp trứng xốp mềm ẩm mượt, cuộn tròn cắt khúc gọn đẹp rồi rưới xì dầu nhạt thơm dịu.', 'Xếp các khúc trứng cuộn ra đĩa, rưới đều xì dầu nhạt lên mặt hoặc chấm riêng, ăn nóng với cơm trắng hoặc cháo trắng rất bắt vị.', 'Món ngon nhất khi thưởng thức nóng ngay sau khi cuộn; nếu dư, bọc kín để ngăn mát tối đa 24 giờ và áp chảo lại 1 phút trên lửa nhỏ.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Trứng cuộn","Nhanh gọn","Khai vị","Bữa sáng","Trung Hoa"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","soybean","wheat"]', 271, 270.6, 1132, 14.9, 20.3, 4.9, 5.5, 0.7, 1.9, 1439, 3.6, '["Shaoxing Wine Ref","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '943b96147f67772de3ee35f57398dfc50e1879b102de1d654bbc464785b91fd9', '0ae67a8d69b3b9edd1741d99006f9d949343067d3d683cfc07468b58d9f482f5', 4),
('imp-26359a897d4be366', 'sup-tom-nam-trung', 290, 'Súp tôm nấm đùi gà gừng ấm', 'Tôm tươi giòn ngọt nấu cùng nấm đùi gà trong nước dùng gà trong veo, thơm nồng vị gừng, tỏi phi và dầu mè dịu nhẹ', 'Món súp khai vị nhẹ bụng mà giàu dinh dưỡng kiểu nhà hàng Trung Hoa: nước dùng gà thanh ngọt quyện hương gừng tươi ấm áp, những lát nấm đùi gà dai ngọt tự nhiên và thịt tôm ướp rượu Thiệu Hưng chín tới hồng hào giòn sần sật.', 'Múc súp nóng ra tô, rưới thêm vài giọt dầu mè thơm và rắc lá hành xanh thái nhỏ, dùng nóng ngay làm món khai vị hoặc ăn cùng bữa cơm gia đình.', 'Nên dùng hết trong ngày để tôm giữ độ giòn ngọt; nếu bảo quản tủ mát tối đa 24 giờ, chỉ đun sôi lại phần nước súp nấm rồi thả tôm vào đảo nóng nhanh 1 phút.', 'chinese', 'mon_canh', NULL, 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Súp","Tôm tươi","Nấm đùi gà","Thanh ngọt","Khai vị"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 157, 156.7, 656, 16.2, 6.9, 1.2, 7.4, 1.5, 2, 1525, 3.81, '["Shaoxing Wine Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '5655514a1e723966a27e0c13b5b93b8054589314d103108005cdfb889a92c671', '60df14591a8c48871c4350b6e73f4fac3ba0657118ec7a4889f818b1655db3d4', 4),
('imp-00e0b1417e11b291', 'dau-phu-xao-hanh-tay', 291, 'Đậu phụ chiên giòn xào hành tây', 'Đậu phụ cứng áo bột bắp chiên vàng giòn, xào cùng hành tây thái mỏng và gừng tỏi trong nước sốt xì dầu rượu Thiệu Hưng sánh bóng', 'Những miếng đậu phụ cứng thấm khô áo lớp bột bắp mỏng chiên vàng giòn rụm hai mặt, sau đó đảo nhanh trên chảo nóng cùng hành tây ngọt thanh, gừng tỏi phi thơm và nước sốt xì dầu đậm – nhạt quyện vị dịu của rượu Thiệu Hưng và đường nâu.', 'Trút đậu phụ xào hành tây lên đĩa hoặc phủ trực tiếp lên bát cơm trắng nóng, rắc thêm hành lá xanh và hạt mè trắng rang cho dậy hương thơm.', 'Món ngon nhất khi dùng nóng để cảm nhận vỏ đậu giòn ráo; nếu còn dư, bảo quản hộp kín ngăn mát tối đa 2 ngày và áp chảo lại 3 phút trên lửa vừa.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Đậu phụ","Xào","Hành tây","Chay","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["sesame","soybean","wheat"]', 349, 348.7, 1458, 16.4, 20.2, 2.9, 28.3, 2.7, 8.3, 891, 2.23, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', '5f18d5d029a71946a591caa14d7d088b4b6b6636bf1e26ce342864ef214e2fea', '4b8e5e93523695d72fe13d5945c92aa368f924e21290d90f0af9cedaca79a4dc', 4),
('imp-45274582db71eb9f', 'mi-xao-tom-quang-dong', 292, 'Mì xào tôm cải bắp kiểu Quảng Đông', 'Sợi mì trứng mềm dai xào lửa lớn cùng tôm tươi giòn ngọt, bắp cải, giá đỗ và nước sốt dầu hào xì dầu óng ánh', 'Đĩa mì xào kiểu Quảng Đông đậm đà hương chảo nóng với từng sợi mì trứng mềm dai không bết dính, hòa quyện vị ngọt mặn dịu của dầu hào, xì dầu và dầu mè, kết hợp tôm tươi săn giòn cùng bắp cải thái sợi và giá đỗ giòn mát.', 'Gắp mì xào tôm nóng hổi ra đĩa rộng, dùng ngay khi bắp cải và giá đỗ còn giữ độ giòn tươi, có thể kèm chén tương ớt nếu thích vị cay.', 'Món ngon nhất khi ăn nóng ngay sau khi xào; nếu còn dư, bảo quản kín trong ngăn mát tối đa 24 giờ và đảo nóng nhanh 2–3 phút trên chảo không dính.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Quảng Đông","Tôm tươi","Bắp cải","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","egg","molluscs","sesame","shrimp","soybean","wheat"]', 579, 578.7, 2422, 28.4, 15.9, 2.6, 81.7, 4.7, 10.4, 1487, 3.72, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169963","USDA FDC 169975","USDA FDC 170005","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'b3118fcb707e84eb574de9cf142e871a6e09eccdca45e30947a49a5ead8615ed', '071992d0dcb5b0c1493f78916b79aa500abe6c31d01ff0c9ef7f0fc31d2a5df7', 4),
('imp-3d2e5735cbfe9654', 'tom-rang-muoi-tieu', 293, 'Tôm rang muối tiêu ớt kiểu Hồng Kông', 'Tôm tươi nguyên vỏ áo bột bắp chiên giòn rụm ăn được cả vỏ, xóc đều tỏi phi vàng, ớt hiểm và bột muối tiêu Tứ Xuyên thơm nồng', 'Món tôm rang muối tiêu trứ danh của ẩm thực Hồng Kông với từng con tôm nguyên vỏ áo bột bắp mỏng chiên giòn tan đến mức ăn được cả vỏ, xóc nhanh cùng bột tiêu Tứ Xuyên rang muối biển thơm lừng, tỏi phi vàng giòn và ớt hiểm cay nồng.', 'Bày tôm ra đĩa khi vừa tắt bếp, rắc thêm phần bột muối tiêu còn lại lên trên và dùng nóng ngay để tận hưởng trọn vẹn độ giòn của vỏ tôm.', 'Tôm rang muối tiêu ngon nhất khi thưởng thức ngay lúc nóng giòn; hạn chế để qua đêm vì vỏ tôm sẽ hút ẩm và mất độ giòn.', 'chinese', 'mon_chien', NULL, 'medium', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm rang","Muối tiêu","Hồng Kông","Giòn rụm","Khai vị"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["crustaceans","shrimp"]', 176, 175.7, 735, 19.1, 6.1, 0.9, 11.6, 0.9, 0.6, 926, 2.32, '["Spice Reference","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 171413","USDA FDC 173468","USDA FDC 175179"]', '979adc7095fc9c35e64dda9ead19cdd5b8bea9b3758293e1529e1c8ed3a5e8aa', '2993bcd05bee6109542a76e4f859e203c023e35878132470bfcfeeb8288b3ace', 4),
('imp-73568e9a99d0ccdf', 'trung-xao-hanh-tay', 294, 'Trứng xào hành tây mềm thơm kiểu Trung', 'Những mảng trứng bông xốp ẩm mượt kết hợp hành tây xào chín mềm ngọt thanh, nêm hạt nêm gà và tiêu đen dậy vị đưa cơm', 'Món xào gia đình quen thuộc của bếp Trung Hoa hoàn thành chỉ trong 15 phút: trứng gà đánh cùng chút sữa tươi và mayonnaise nên cực kỳ mềm xốp, quyện cùng hành tây xào ẩm với nước lọc giữ trọn vị ngọt tự nhiên.', 'Trút trứng xào hành tây nóng hổi ra đĩa nông, ăn ngay cùng cơm trắng nóng hoặc cháo trắng vào bữa sáng đều rất hợp vị.', 'Món ngon nhất khi dùng nóng ngay sau khi xào; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng nhẹ trên chảo chống dính.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 5, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Trứng xào","Hành tây","Nhanh gọn","Cơm nhà","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","milk"]', 302, 302.4, 1265, 12, 25.8, 5.4, 5.5, 0.9, 2.5, 982, 2.46, '["USDA FDC 170000","USDA FDC 170005","USDA FDC 170931","USDA FDC 171009","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '37741dd046f1fb28cbbc9bcf93cdfc50562c65cdef83519a56b4a261c84707bd', '63e1081999ca586931e30afeef95dce771add397458ce0f173f69bcf504b4dcd', 4),
('imp-a17f5a86a1bc891c', 'ba-chi-luoc-cham-tuong', 295, 'Thịt ba chỉ luộc thái mỏng rưới sốt tỏi ớt Tứ Xuyên', 'Ba chỉ luộc chín mềm da dẻo thơm hương hồi quế, thái lát mỏng xếp trên dưa leo giòn mát, rưới sốt dầu ớt tỏi thơm nồng cay tê', 'Món ba chỉ luộc sốt tỏi (Toán Nê Bạch Nhục) trứ danh vùng Tứ Xuyên: thịt ba chỉ nguyên tảng luộc liu riu cùng gừng, hành, hoa hồi và tiêu Tứ Xuyên cho mềm mọng, thái lát mỏng mượt rồi chan sốt xì dầu giấm đen, tỏi băm và dầu ớt thơm lừng.', 'Xếp dưa leo thái sợi lót đáy đĩa, bày các lát ba chỉ luộc mỏng đều lên trên, chan đều sốt tỏi ớt mè rang và rắc lá hành xanh rồi dùng nguội hoặc ấm nhẹ với cơm trắng.', 'Thịt luộc thái lát và sốt pha sẵn nên bảo quản riêng trong hộp kín ngăn mát tối đa 3 ngày; khi ăn chỉ cần chan sốt và dùng mát lạnh.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Thịt ba chỉ","Luộc","Tứ Xuyên","Khai vị","Mùa hè"]', '["lunch","dinner"]', '["boil","assemble"]', '["pork","sesame","soybean","wheat"]', 654, 654, 2736, 12.3, 62.8, 20.2, 11.2, 2.2, 4.1, 927, 2.32, '["Chinkiang Black Vinegar Ref","Shaoxing Wine Ref","Spice Reference","USDA FDC 167820","USDA FDC 168409","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170189","USDA FDC 171028","USDA FDC 171316","USDA FDC 171319","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', '4d861e98d879db04fe0e2a752ef71e0d3d22b22ad45e1703031da5d4476a55ec', '0be1e4c5a7c5dd5bd67cd125b4d0253e966fecb0e67b679807b5660577d416ae', 4),
('imp-fbbe89a1039604fc', 'nam-xao-toi-trung', 296, 'Nấm đùi gà xào tỏi nước tương', 'Từng khoanh nấm đùi gà khía caro áp chảo xém vàng dai giòn như bào ngư, đảo nhanh trong sốt tỏi băm xì dầu nhạt thơm lừng', 'Món nấm xào 10 phút đậm hương vị nhà hàng Trung Hoa: nấm đùi gà thái khoanh dày khía caro áp chảo xém cạnh săn giòn, rồi quyện cùng hỗn hợp tỏi phi thơm lẫn tỏi sống băm nhuyễn, xì dầu nhạt và chút dầu hào dậy vị ngọt tự nhiên.', 'Trút nấm đùi gà xào tỏi ra đĩa nóng, rắc hành lá xanh và ớt khoanh, thưởng thức ngay cùng cơm trắng nóng.', 'Nên dùng hết trong bữa ăn để cảm nhận trọn vẹn độ giòn sần sật của nấm; bảo quản ngăn mát tối đa 24 giờ và áp chảo lại 2 phút trên lửa lớn.', 'chinese', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nấm đùi gà","Xào tỏi","Nhanh gọn","Chay","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["molluscs","soybean","wheat"]', 137, 136.7, 572, 5.4, 8.9, 1.3, 12.2, 3.4, 2.7, 710, 1.77, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '6e51ed29ffbcb1ca4a6629c232c704f71be1acbce88bc0b0711d10a1a5ffc902', 'a10da6a01d0856dcb4b2dba22d4c884e9f76cee6febce8670ebbf3a97970c740', 4),
('imp-3ee45f761eb0b78d', 'mi-lanh-ga-trung', 297, 'Mì lạnh gà xé dưa leo sốt mè Tứ Xuyên', 'Sợi mì dai mát trộn cùng thịt ức gà xé tơi mềm mọng, dưa leo giòn ngọt và nước sốt tương mè giấm đen dầu ớt béo cay thanh mát', 'Tô mì lạnh gà xé Tứ Xuyên giải ngấy lý tưởng cho ngày nắng nóng: ức gà ủ chín mềm mọng nước rồi xé sợi tơi, kết hợp sợi mì luộc xả lạnh dai giòn, dưa leo bào sợi mát lành và nước sốt tương mè béo bùi quyện giấm đen, xì dầu, dầu ớt và tiêu Tứ Xuyên tê dịu.', 'Xếp dưa leo, thịt gà xé lên mặt tô mì lạnh, chan đẫm nước sốt tương mè, rắc đậu phộng rang giã dập, mè rang và hành lá rồi trộn đều ngay trước khi ăn.', 'Bảo quản riêng gà xé, mì trộn dầu và hũ nước sốt trong ngăn mát tối đa 2 ngày; chỉ trộn tất cả nguyên liệu cùng dưa leo ngay trước khi thưởng thức.', 'chinese', 'mon_bun_pho', NULL, 'easy', 20, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Mì lạnh","Ức gà","Sốt mè","Tứ Xuyên","Giải nhiệt"]', '["lunch","dinner"]', '["boil","toss_mix","assemble"]', '["chicken","peanut","sesame","soybean","wheat"]', 657, 657.3, 2750, 44.3, 32.8, 4.9, 47.8, 4.4, 10.6, 1633, 4.08, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","NIN VN Fresh Rice Noodle Ref","Spice Reference","USDA FDC 168409","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170189","USDA FDC 171028","USDA FDC 171413","USDA FDC 171477","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'e4aee95732debdec907ebecf8b2fc85880293009ffcaf8045cb04f2ce2b1a302', '7746db7c9e1ab211da781b07783ce02dc1e36f5b4f9f29f5e58ba7ba4598601f', 4),
('imp-cbb5635bfe848a49', 'ga-om-gung-tuong', 298, 'Đùi gà om gừng xì dầu kiểu Hoa', 'Đùi gà nguyên xương áp chảo vàng da, om liu riu cùng thật nhiều gừng tươi, hoa hồi, rượu Thiệu Hưng và xì dầu đặc sánh bóng', 'Món đùi gà om xì dầu đậm vị cơm nhà Trung Hoa: thịt đùi gà có xương giữ trọn độ mọng ngọt sau khi áp chảo vàng da, om thấm đẫm hương gừng tươi thái lát ấm nồng, hồi quế, đường nâu và hai loại xì dầu tạo nước sốt nâu bóng sánh đẹp.', 'Gắp đùi gà om gừng ra đĩa sâu lòng, rưới nước sốt sánh bóng và rắc hành lá xanh thái nhỏ lên trên, ăn nóng kèm cơm trắng dẻo và rau luộc.', 'Để nguội bảo quản hộp kín ngăn mát tối đa 3 ngày; khi ăn hâm lại trên lửa nhỏ với 2–3 muỗng canh nước lọc đến khi thịt gà nóng đều.', 'chinese', 'mon_kho', NULL, 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Đùi gà","Món om","Gừng tươi","Xì dầu","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["chicken","sesame","soybean","wheat"]', 606, 606.1, 2537, 57.3, 35, 9, 11.1, 0.6, 6.6, 1191, 2.98, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 170005","USDA FDC 170917","USDA FDC 170933","USDA FDC 171028","USDA FDC 171316","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', '7248cc48f78e158b92d2ab0db61498e677ea91b5e3e53aadda2165b2d6508602', '37e4468fb9940bc7d142858cfc6a42d4b93b0b9d390adaaccceb7c620fdc0770', 4),
('imp-7bf9327b2c48f2d4', 'suon-nuong-tuong', 299, 'Sườn non nướng tương mật ong kiểu Hoa', 'Sườn non ướp đậm xì dầu, tương đen Hoisin, tỏi và ngũ vị hương nướng lò chín mềm, phết mật ong bóng nâu thơm lừng cạnh cháy xém', 'Những dẻ sườn non nướng kiểu xá xíu Trung Hoa hấp dẫn với vị mặn ngọt hài hòa từ xì dầu nhạt, tương đen Hoisin, rượu Thiệu Hưng và ngũ vị hương, nướng chín mềm ẩm trong lò rồi phết mật ong lửa lớn tạo lớp vỏ caramel óng ả xém cạnh.', 'Chặt sườn thành từng khúc vừa ăn, xếp ra đĩa rắc hành lá thái nhỏ và dọn nóng cùng cơm trắng, dưa leo hoặc cải thìa xào tỏi cho bữa tiệc cuối tuần.', 'Bảo quản sườn đã nướng trong hộp kín ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại bằng lò nướng hoặc nồi chiên không dầu 5 phút ở 180°C.', 'chinese', 'mon_lau_tiec', NULL, 'medium', 20, 55, 4, '/frigo/illustrations/delicious-meal.png', '["Sườn nướng","Mật ong","Ngũ vị hương","Cuối tuần","Tiệc nhà"]', '["lunch","dinner"]', '["grill_roast"]', '["pork","sesame","soybean","wheat"]', 623, 622.5, 2605, 32.1, 46.9, 17, 15.9, 0.7, 12.4, 1564, 3.91, '["Five Spice USDA Ref","Shaoxing Wine Ref","USDA FDC 167861","USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171370","USDA FDC 173468","USDA FDC 174277"]', '6d971caffe940d40fd7f04d076fb47a7b21c262c89801b7713251ff07837e785', 'dacda88453a567dd3974968e96bdb14561ac94f1dc44e8f667d010635c73a6a3', 4),
('imp-bbfdcf2e3b277fed', 'soba-nong-ga', 300, 'Mì Soba nóng thịt gà', 'Sợi mì Soba kiều mạch nóng trong nước dùng Dashi Kombu cá bào đậm vị, phủ đùi gà áp chảo da giòn và hành boa-rô thơm ngọt', 'Mì Soba nóng thịt gà (Torinanban Soba) là món mì nước ấm áp kinh điển của Nhật Bản, kết hợp nước dùng Dashi truyền thống từ tảo bẹ Kombu và cá bào Katsuobushi, đùi gà áp chảo da vàng giòn, hành boa-rô xém ngọt cùng chút gừng mài thơm nồng.', 'Xếp mì Soba nóng vào 3 tô, chan ngập nước dùng Dashi cùng thịt gà và hành boa-rô áp xém, thêm chút gừng tươi mài nhuyễn và bột ớt 7 vị Shichimi rồi thưởng thức ngay.', 'Nếu chưa ăn hết ngay, bảo quản riêng phần mì Soba đã luộc ráo và phần nước dùng thịt gà trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi nước dùng rồi trụng nóng lại mì.', 'japanese', 'mon_bun_pho', NULL, 'easy', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Soba","Thịt gà","Nước dùng Dashi","Ẩm thực Nhật","Mì nước"]', '["lunch","dinner"]', '["boil","pan_fry","simmer"]', '["buckwheat","chicken","fish","sesame","soybean","wheat"]', 597, 597, 2498, 34.8, 15.1, 3.6, 77.2, 4.6, 9.4, 1694, 4.24, '["MEXT Dry Soba 01097","MEXT Hon-Mirin 16031","MEXT Katsuobushi 10099","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 168457","USDA FDC 169231","USDA FDC 169246","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'cf125bd130ac99f2617a502f1c53f2ed1ff31c3ebb784b7c51b312640aae8cac', '522a686fb73f3caa5d4eeb5a446a0a65708214f1958cad43d1129712d060a736', 4),
('imp-f2334219f33e48d0', 'tom-nuong-muoi-nhat', 301, 'Tôm nướng muối kiểu Nhật', 'Tôm sú nguyên vỏ ướp sơ rượu Sake, xiên thẳng rắc muối hạt biển nướng xém cạnh giữ trọn thịt ngọt chắc, chấm chanh tiêu', 'Tôm nướng muối kiểu Nhật (Ebi Shioyaki) tôn vinh trọn vẹn vị ngọt tự nhiên của tôm sú nguyên vỏ, chỉ cần ướp nhanh với rượu Sake khử tanh, xiên que giữ thân thẳng đẹp và phủ lớp muối hạt nướng xém vỏ giòn thơm.', 'Xếp tôm nướng muối đỏ au ra đĩa cùng múi chanh tươi, rắc chút hành lá thái nhỏ và dọn kèm chén muối tiêu đen xay để chấm thịt tôm sau khi bóc vỏ.', 'Tôm nướng muối ngon nhất khi dùng nóng ngay sau khi nướng để vỏ giòn và thịt ngọt mọng; nếu dư, bóc vỏ bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo.', 'japanese', 'mon_lau_tiec', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Shioyaki","Hải sản","Ẩm thực Nhật","Món nướng"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","shrimp"]', 104, 103.9, 435, 21.1, 1.3, 0.2, 1.8, 0.5, 0.3, 448, 1.12, '["MEXT Sake 16021","USDA FDC 168155","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 175179"]', 'f48c5e1f33bbc6725d60adfa682fd174bf88cceacff0de86dac6ed6d6f9b8000', 'd642d9cf84c90257a7fb5d81f887a2dc504c6158898587200e6c48ad933674dc', 4),
('imp-8f6eeb8b34b7cd65', 'com-muc-nuong', 302, 'Cơm mực nướng sốt Teriyaki', 'Cơm gạo Nhật dẻo thơm ăn cùng mực ống nguyên con áp chảo cháy cạnh áo đẫm sốt xì dầu Sake Mirin gừng mài sánh bóng', 'Cơm mực nướng sốt Teriyaki (Ikayaki Don) mang hương vị quán ăn lễ hội Nhật Bản, kết hợp cơm trắng gạo hạt ngắn dẻo ngọt cùng mực ống nguyên con áp chảo xém cạnh thơm lừng, áo lớp sốt xì dầu Sake Mirin gừng tươi sánh bóng đậm đà.', 'Xới cơm nóng ra 3 bát, xếp các khoanh mực và phần râu mực áp chảo lên trên, rưới đẫm phần sốt Teriyaki gừng còn lại trong chảo và rắc hành lá thái nhỏ.', 'Ngon nhất khi ăn nóng ngay lúc mực vừa nướng xong; nếu còn dư, bảo quản riêng cơm và mực trong hộp kín ở ngăn mát tối đa 24 giờ và làm nóng nhanh trong 1–2 phút.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 15, 40, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm mực","Mực nướng","Teriyaki","Ẩm thực Nhật","Hải sản"]', '["lunch","dinner"]', '["pan_fry","boil"]', '["molluscs","soybean","squid","wheat"]', 565, 565.3, 2365, 27.5, 5.2, 1, 95.6, 1.6, 10.6, 708, 1.77, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 171413","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277"]', '38a712c2179e886f41a32b3000c00a6bdcb55aa04a314d94d2180c6652d9ba34', '85602b430c7d8ede0fb26481b237125881d8fceac182ecda69d48ab3c6ddcdaa', 4),
('imp-9e4ad3e4074d2a1c', 'salad-bap-cai-tom-nhat', 303, 'Salad bắp cải tôm Nhật', 'Bắp cải, cà rốt và hành tây thái sợi giòn mát trộn tôm sú luộc ngọt thịt, quyện sốt Mayonnaise mật ong giấm chanh dịu nhẹ', 'Salad bắp cải tôm kiểu Nhật kết hợp bắp cải thái sợi mỏng, cà rốt giòn ngọt và hành tây ngâm lạnh hết hăng cùng tôm sú luộc đỏ au săn chắc, áo đều lớp sốt Mayonnaise pha mật ong, giấm gạo, chanh tươi và chút xì dầu thanh dịu.', 'Bày salad bắp cải tôm đã làm mát ra đĩa sâu lòng, rắc hành lá thái nhỏ lên trên để tạo màu sắc tươi tắn và dùng lạnh như món khai vị hoặc ăn kèm đồ chiên nướng.', 'Nên trộn sốt ngay trước khi ăn hoặc bảo quản trong ngăn mát tối đa 24 giờ; nếu chuẩn bị trước, để riêng phần sốt và rau tôm để giữ độ giòn tươi.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Salad Nhật","Bắp cải","Tôm tươi","Món trộn","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","egg","shrimp","soybean","wheat"]', 208, 208.2, 872, 14.5, 11.7, 1.9, 12.6, 2.3, 9.1, 431, 1.08, '["USDA FDC 168155","USDA FDC 169640","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 171009","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '82be1318d6db17c16ed33d24e68463949dfb0cda5d0fcbb617f48d35a8065cfa', 'c971312346e978f1ef35dd12e8c724906a24d0f92568bc751b51751f0873a8a5', 4),
('imp-4023e971948407f6', 'ca-hoi-om-ca-chua', 304, 'Cá hồi om cà chua kiểu Nhật', 'Cá hồi áp chảo áo bột mỏng om cùng cà chua tươi, hành tây và nấm đùi gà trong nước sốt xì dầu Mirin thanh ngọt đậm đà', 'Món cá hồi om cà chua phong cách gia đình Nhật kết hợp vị béo ngậy của phi lê cá hồi áp chảo với nước sốt cà chua tươi chua dịu, ngọt thanh hành tây và hương thơm umami từ nấm cùng xì dầu Nhật Bản.', 'Dọn cá hồi om cà chua ra đĩa sâu lòng khi còn nóng hổi, rưới đều nước sốt sánh mịn lên mặt cá, rắc thêm hành lá xanh và ăn kèm cơm trắng hạt dẻo.', 'Món ăn ngon nhất khi dùng nóng trong ngày; nếu còn dư, bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày và hâm nóng nhẹ trên lửa nhỏ với 1–2 muỗng canh nước lọc để sốt không bị cạn.', 'japanese', 'mon_kho', NULL, 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Cá hồi","Cà chua","Cơm nhà","Bữa tối ấm"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["fish","salmon","soybean","wheat"]', 329, 329.3, 1377, 24, 18, 3.7, 17.4, 2.9, 8.6, 1001, 2.5, '["MEXT Hon-Mirin 16031","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175167"]', 'e4d0ac5f33c5848b2f14efbf86ccbf3a192f08317f6e0bcfffb8547f503985e7', 'f44aa223e896a540d72869b4ac32bbdcdfc45e72bd137e4d9c47819f748fd6fe', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-76ddca35768468fe', 'bo-nuong-yakiniku-muoi', 305, 'Bò nướng Yakiniku muối chanh', 'Thịt bò thái lát mỏng nướng xém cạnh trên vỉ nóng, thưởng thức cùng muối tiêu, chanh tươi và sốt hành lá Negi-shio thơm lừng dầu mè', 'Phiên bản Yakiniku vị thanh kiểu Nhật không ướp sốt ngọt dày, giữ trọn vị ngọt thịt của lát bò thăn nướng cháy cạnh, kết hợp muối tiêu, vị chua thơm của chanh tươi và chén sốt hành lá dầu mè Negi-shio béo thơm.', 'Nướng từng mẻ thịt bò nóng hổi tại bàn, vắt trực tiếp vài giọt chanh tươi lên miếng thịt vừa chín, chấm hoặc cuộn kèm sốt hành lá Negi-shio và ăn cùng cơm trắng nóng.', 'Thịt bò nên nướng đến đâu ăn đến đó để giữ độ mềm mọng. Phần sốt hành lá Negi-shio chưa dùng hết có thể đậy kín trong hũ thủy tinh, bảo quản ngăn mát tủ lạnh từ 5–7 ngày.', 'japanese', 'mon_lau_tiec', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Yakiniku","Thịt bò nướng","Sốt Negi-shio","Cuối tuần","Nhật Bản"]', '["lunch","dinner"]', '["grill_roast","toss_mix"]', '["beef","sesame"]', 294, 293.8, 1230, 25.9, 18.4, 5.7, 5.2, 1.6, 1.1, 770, 1.92, '["MEXT Sake 16021","USDA FDC 167746","USDA FDC 169230","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468"]', '23767f393aced35d01513a53af99bc9727fa92fdef0322bce18c4a05293a6e60', '3e704595a0aa42d42847225a27bf983a74e0d3a431fbadd2650d77eceddd8d10', 4),
('imp-1bbb2341036dd966', 'bong-cai-tron-me-nhat', 306, 'Bông cải xanh trộn mè Nhật (Goma-ae)', 'Bông cải xanh chần giòn giữ màu xanh mướt trộn sốt hạt mè trắng rang giã dập, xì dầu và mật ong thanh dịu chuẩn vị món phụ Nhật Bản', 'Món rau phụ Goma-ae truyền thống của Nhật Bản với bông cải xanh chần vừa chín tới giòn ngọt tự nhiên, quyện lớp sốt bùi béo từ mè trắng rang giã dập hòa cùng xì dầu Nhật, Sake, Dashi và mật ong.', 'Bày bông cải trộn mè ra đĩa sâu lòng nhỏ, rắc thêm phần mè nguyên hạt và hành lá thái nhỏ lên mặt; dùng nguội mát hoặc ở nhiệt độ phòng như món rau phụ cân bằng bữa cơm Nhật.', 'Món Goma-ae ngon nhất khi dùng trong ngày để giữ độ giòn và mùi mè rang; có thể bảo quản ngăn mát tủ lạnh trong hộp kín tối đa 2 ngày và ăn nguội trực tiếp, không hâm nóng lại.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 10, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Goma-ae","Bông cải xanh","Món phụ Nhật","Thanh đạm","Mè rang"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["fish","sesame","soybean","wheat"]', 104, 103.6, 433, 4.9, 4.8, 0.7, 11.9, 3.4, 4.8, 676, 1.69, '["MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 169640","USDA FDC 170005","USDA FDC 170150","USDA FDC 170379","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '057a11cd7573ac6086cc5152aaff443689bea95ecab16ba70bfc159a78f4705c', 'fc1bec01a6f290f407856d926baddf2f83d8842c2f279cb025fef5628ebe8057', 4),
('imp-5ed977305ac677b6', 'com-bo-hanh-nhat', 307, 'Cơm bơ xì dầu hành lá Nhật Bản', 'Cơm trắng hạt ngắn nóng hổi trộn bơ lạt tan chảy, xì dầu Nhật thơm dịu, hành lá xanh tươi cùng cá bào và rong biển Nori béo ngậy khó cưỡng', 'Món cơm trộn Butter Shoyu Gohan kinh điển của Nhật Bản: hơi nóng từ cơm mới nấu làm viên bơ lạt tan chảy, hòa quyện vị mặn thanh của xì dầu Nhật, hành lá tươi, cá bào Katsuobushi và rong biển Nori giòn thơm.', 'Dùng ngay khi cơm còn nóng bốc hơi, trộn đều tay để bơ và xì dầu phủ bóng từng hạt cơm; có thể ăn kèm một quả trứng ốp la lòng đào hoặc súp Miso nóng.', 'Nên chế biến và ăn ngay từng phần vì cơm bơ để nguội sẽ đông bơ và mất độ thơm béo; không khuyến khích bảo quản lại món đã trộn.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 5, 5, 2, '/frigo/illustrations/delicious-meal.png', '["Cơm bơ Nhật","Bữa sáng nhanh","Nhật Bản","Đơn giản","Tiện lợi"]', '["breakfast","lunch","dinner"]', '["assemble","toss_mix"]', '["fish","milk","sesame","soybean","wheat"]', 372, 371.5, 1555, 8.8, 13.5, 7.6, 52.9, 1.5, 0.4, 496, 1.24, '["MEXT Katsuobushi 10099","USDA FDC 168456","USDA FDC 168878","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 173430","USDA FDC 174277"]', 'db7b6bb9c0e1bc9f1be0082caa3063063e1efdca7d0b78c1213057eeeed06d1f', '6ec168fb522896395cd4b379763a4378efd79e6d5cd3cfc00b40ebab02a2fa86', 4),
('imp-57294c4da3e61e24', 'sup-miso-tom-nam', 308, 'Súp Miso tôm nấm đùi gà', 'Nước dùng Dashi thanh ngọt nấu cùng tôm tươi nguyên con, nấm đùi gà giòn ngọt, rong biển Wakame và tương Miso Nhật thơm ấm bụng', 'Bát súp Miso hải sản chuẩn vị Nhật Bản kết hợp vị ngọt tự nhiên từ tôm tươi nấu cùng rượu Sake khử tanh, nấm đùi gà cắt lát sần sật, rong biển Wakame mềm mượt và tương Miso hòa tan sau khi tắt bếp giữ trọn hương thơm.', 'Múc súp Miso nóng ra 3 bát nhỏ, chia đều tôm, nấm và rong biển, rắc thêm hành lá thái khoanh; dùng nóng làm món canh khai vị hoặc ăn kèm cơm trắng và cá nướng.', 'Súp Miso ngon nhất khi thưởng thức ngay sau khi nấu; nếu bảo quản tủ mát tối đa 1 ngày, chỉ hâm nóng lại trên lửa nhỏ cho đến khi vừa bốc hơi, tuyệt đối không đun sôi bùng để tránh mất mùi thơm của Miso.', 'japanese', 'mon_canh', NULL, 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Súp Miso","Tôm tươi","Nấm đùi gà","Canh Nhật","Ấm bụng"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp","soybean","wheat"]', 101, 101.1, 423, 14.3, 1.5, 0.2, 8, 2, 1.8, 964, 2.41, '["MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168580","USDA FDC 170005","USDA FDC 170496","USDA FDC 172446","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'f1137148cb5755b0b45bb8bbcc3a65e9c169bb0083df129695f38218c320360b', '192ba2451aa6187b9167ef3447b9dc84ef426ad02966e76e0d7cc1adf25c5fc9', 4),
('imp-ea9ba867b7d2c6ad', 'ga-hap-gung-bap-cai', 309, 'Ức gà hấp gừng bắp cải kiểu Nhật', 'Ức gà hấp mềm ẩm trên lớp bắp cải ngọt thanh, rưới sốt nước tương Ponzu chua dịu quyện dầu mè, gừng tươi và mè trắng rang', 'Món ức gà hấp kiểu Nhật nhẹ nhàng, giàu đạm và ít dầu mỡ: thịt ức gà hấp chín tới trên nền bắp cải ngọt giúp giữ độ ẩm mềm, sau đó xé sợi trộn sốt nước tương Ponzu, gừng bào và dầu mè thơm bùi.', 'Bày thịt gà xé cùng bắp cải hấp ra đĩa lớn, rưới đều nước sốt Ponzu gừng và phần nước ngọt tiết ra khi hấp, rắc thêm hạt mè trắng rang và hành lá thái nhỏ; dùng nóng hoặc nguội mát đều ngon.', 'Bảo quản phần gà hấp và sốt riêng trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn có thể dùng nguội như salad gà hoặc hấp lại 3–4 phút cho ấm nóng.', 'japanese', 'mon_hap_luoc', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Ức gà","Bắp cải","Thanh đạm","Nhật Bản"]', '["lunch","dinner"]', '["steam","toss_mix"]', '["chicken","sesame","soybean","wheat"]', 225, 225.3, 943, 27.1, 7.7, 1.3, 10.6, 3.5, 4.9, 952, 2.38, '["MEXT Ponzu Ref","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647"]', 'b6394ae05e8f409ed7d5a714eb6b814380fbd1662860744e56f07d994f2e3200', 'd90c8f2b754d248625a2d4ae3f9c219ae624fb673070f29cb76eed38d84f61da', 4),
('imp-7d764feba948bce3', 'canh-kimchi-ca', 310, 'Canh kim chi cá hồi đậu phụ', 'Nồi canh kim chi jjigae cay ấm với cá hồi tươi béo ngậy, đậu phụ mềm mịn và nước dùng chua thanh chuẩn vị Hàn', 'Canh kim chi cá hồi đậu phụ là biến tấu đậm đà của món kimchi jjigae truyền thống Hàn Quốc. Vị chua cay tự nhiên của kim chi cải thảo lên men kỹ hòa cùng thịt cá hồi béo ngọt và đậu phụ thanh mát, rất đưa cơm trong những ngày se lạnh.', 'Dọn canh nóng hổi ngay trong nồi đất hoặc tô sâu lòng, rắc hành lá thái vát lên mặt và ăn kèm cơm trắng nóng dẻo.', 'Nên thưởng thức ngay khi còn nóng để cá và đậu phụ giữ nguyên thớ đẹp; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm sôi nhẹ trên lửa nhỏ.', 'korean', 'mon_canh', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Canh kim chi","Hàn Quốc","Cá hồi","Đậu phụ","Cay ấm"]', '["lunch","dinner"]', '["simmer"]', '["fish","salmon","sesame","soybean","wheat"]', 357, 357.2, 1494, 28.8, 22.9, 4.4, 10.9, 3.5, 5, 1100, 2.75, '["Korean Chili Flake Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175167"]', 'b5e33aff19d45425d3c90c525e97d3e193ff249b411d6f6849d87823a29595c7', '1712fa2a5a869cc7c495c8384c6169ddf210a52c77a620d46fbe26492d86cad4', 4),
('imp-a24e0f07380bfdc2', 'suon-ham-galbi-han', 311, 'Sườn bò hầm kiểu Hàn (Galbi Jjim)', 'Sườn bò hầm mềm róc xương quyện sốt tương ngọt bóng, thấm vị củ cải, cà rốt, nấm hương và táo đỏ sang trọng', 'Sườn bò hầm Galbi Jjim là món ăn truyền thống trong các dịp lễ tiệc của Hàn Quốc. Từng dẻ sườn bò được ngâm chần kỹ để sạch tạp chất rồi hầm liu riu với nước ngâm nấm hương, nước tương và rượu mirin đến khi thịt mềm róc xương, phủ lớp sốt nâu bóng óng ánh.', 'Bày sườn và rau củ ra đĩa sâu lòng hoặc thố giữ nhiệt, rắc hành lá cắt khúc lên trên, ăn nóng kèm cơm trắng và kim chi cải thảo.', 'Có thể bảo quản ngăn mát tủ lạnh tới 3 ngày trong hộp kín (vớt bỏ lớp mỡ đông trên mặt trước khi hâm). Hâm nóng trên bếp lửa nhỏ với 2–3 muỗng canh nước trong 8–10 phút.', 'korean', 'mon_lau_tiec', NULL, 'hard', 45, 110, 5, '/frigo/illustrations/delicious-meal.png', '["Galbi jjim","Sườn bò","Món tiệc","Hàn Quốc","Hầm mềm"]', '["lunch","dinner"]', '["boil","braise"]', '["beef","sesame","soybean","wheat"]', 488, 488.2, 2042, 21.6, 21.6, 8.2, 50.1, 4.1, 34.3, 1279, 3.2, '["MEXT Hon-Mirin 16031","USDA Beef Rib / Bone Ref","USDA FDC 168436","USDA FDC 168452","USDA FDC 168836","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 173647","USDA FDC 174277","USDA FDC Jujube Ref"]', 'aa467d2cc877f2a3ddf087b28e2690154db2d38f95a39da67f4dc408d17cd3b5', 'a83ddd95ace30fcbfa0926b79e0653fbba6864ebb53c859f729160446d1adfe0', 4),
('imp-706c3678abea88b4', 'trung-chien-tron-han', 312, 'Trứng chiên hành lá kiểu Hàn (Gyeran Jeon)', 'Trứng chiên tròn vàng ruộm viền giòn, thơm hành lá xanh mướt chấm nước tương pha chua ngọt kiểu hộp cơm Hàn', 'Gyeran Jeon là món trứng chiên tròn dẹt giản dị nhưng rất được ưa chuộng trong bữa cơm gia đình và hộp cơm trưa Hàn Quốc. Trứng đánh kỹ chiên trên chảo chống dính với lượng dầu vừa đủ cho mặt ngoài vàng đều, viền giòn nhẹ và bên trong mềm ẩm thơm hành lá.', 'Cắt miếng tam giác hoặc miếng vuông vừa ăn, bày ra đĩa cùng chén nước tương giấm mè; dùng nóng với cơm trắng hoặc xếp vào hộp cơm.', 'Ngon nhất khi ăn ngay lúc vừa chiên xong; có thể bảo quản nguội trong hộp kín ở ngăn mát tối đa 24 giờ và áp chảo lại 1 phút không dầu trước khi ăn.', 'korean', 'mon_chien', NULL, 'easy', 8, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Gyeran jeon","Trứng chiên","Hàn Quốc","Món nhanh","Hộp cơm"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","sesame","soybean","wheat"]', 208, 208, 870, 12.9, 15.5, 3.8, 4.2, 0.8, 1.8, 1326, 3.32, '["USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 174277"]', '0a6f2f08188a37b52da64283582e2a59cfbe82f07b81c020d7db05555e7c6e78', '9ef3dced68ed443fd525136b6957b2df20deac416089a8cff16ecb1b84cab24c', 4),
('imp-d88e008b28a31151', 'muc-xao-kimchi', 313, 'Mực xào kim chi cay đậm kiểu Hàn', 'Mực tươi khứa caro giòn sần sật xào lửa lớn cùng kim chi chua, hành tây và sốt tương ớt Gochujang đỏ bóng', 'Món mực xào kim chi (Ojingeo Kimchi Bokkeum) kết hợp độ giòn ngọt tự nhiên của mực tươi khứa caro với vị chua cay đậm đà từ kim chi cải thảo chín kỹ và tương ớt Gochujang. Kỹ thuật xào nhanh lửa lớn giữ cho mực không ra nước và sốt áo bóng đều từng miếng.', 'Dọn nóng ra đĩa sâu lòng, rắc mè trắng rang lên trên; ăn ngay cùng cơm trắng nóng dẻo hoặc xúc trực tiếp lên cơm như món cơm trộn.', 'Mực xào ngon nhất khi ăn ngay lúc vừa tắt bếp để giữ độ giòn; nếu bảo quản tủ mát tối đa 24 giờ, nên đảo nhanh lại trên chảo nóng lửa vừa 1–2 phút, tránh hâm quá lâu làm mực dai.', 'korean', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Mực xào","Kim chi","Hàn Quốc","Cay đậm","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["molluscs","sesame","soybean","squid","wheat"]', 372, 371.9, 1556, 27.2, 16.4, 2.6, 30.7, 5.4, 12.2, 1532, 3.83, '["Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174223","USDA FDC 174277"]', '914ac0652c1c90430c8b66cb9a41f56b254b99410ddd64e6cc36f0f3f8ae07d9', '4b31e0118588497dda4c46ac857dc5179ba269975428cc6aa14dcf1437341edc', 4),
('imp-3ec4d8a534fc8861', 'ga-nuong-bulgogi', 314, 'Gà nướng Bulgogi kiểu Hàn (Dak Bulgogi)', 'Đùi gà rút xương ướp nước tương, đường nâu, mật ong và gừng tỏi nướng áp chảo xém cạnh thơm lừng', 'Gà nướng Bulgogi (Dak Bulgogi) sử dụng phần đùi gà mềm mọng ướp đậm đà trong hỗn hợp nước tương, đường nâu, mật ong, rượu mirin, dầu mè và gừng tỏi. Khi nướng hoặc áp chảo trên lửa vừa-cao, lớp gia vị caramel hóa tạo bề mặt vàng xém thơm lừng mà thịt bên trong vẫn mọng nước.', 'Thái gà thành miếng vừa ăn, rưới nước sốt ướp đã đun sánh và rắc hành lá, mè rang lên trên; ăn nóng với cơm trắng hoặc cuốn lá xà lách kèm kim chi.', 'Có thể ướp gà trước trong ngăn mát qua đêm để tiện nấu nhanh; gà đã nướng bảo quản hộp kín ngăn mát tối đa 2 ngày và hâm nóng bằng lò nướng 180°C trong 5 phút.', 'korean', 'mon_lau_tiec', NULL, 'easy', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Dak bulgogi","Gà nướng","Hàn Quốc","Mặn ngọt","Cuốn rau"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["chicken","sesame","soybean","wheat"]', 338, 338.2, 1416, 26.5, 18.4, 4.4, 15.6, 0.9, 11.9, 839, 2.1, '["MEXT Hon-Mirin 16031","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172385","USDA FDC 174277"]', 'c5957f3b217229ee5baee0671cb331a26dfe07332d7b7f6a252aec97fcc4699b', '4d0e2c7e73fce62d8c6f2467e12ac21c8f0cd4c76a9c48ae015080597937201e', 4),
('imp-750cef719bf5f2f6', 'chao-kimchi-han', 315, 'Cháo kim chi trứng kiểu Hàn (Kimchi Juk)', 'Tô cháo kim chi sánh mịn đậm vị chua cay ấm bụng với trứng gà đánh ủ mềm, dầu mè thơm và rong biển vụn', 'Cháo kim chi Hàn Quốc (Kimchi Juk) là món cháo nóng hổi thanh nhẹ nhưng giàu hương vị nhờ bước xào kim chi chua cùng dầu mè và ép nhẹ cơm cho thơm béo trước khi ninh. Trứng gà được ủ chín mềm trong cháo nóng, kết hợp cùng rong biển vụn và hành lá tạo nên tô cháo ấm bụng cho bữa sáng hoặc ngày se lạnh.', 'Múc cháo nóng ra tô sâu lòng, rắc hành lá, rong biển khô cắt vụn, chút ớt bột Hàn và mè trắng rang lên trên; thưởng thức ngay khi còn nóng.', 'Cháo ngon nhất khi ăn ngay lúc vừa nấu xong; nếu để nguội sẽ đặc lại, khi hâm nóng chỉ cần thêm 50–100 ml nước lọc và khuấy đều trên lửa nhỏ.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 10, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Kimchi juk","Cháo Hàn","Bữa sáng","Cay ấm","Trứng gà"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","fish","sesame","soybean","wheat"]', 348, 348.3, 1457, 11.3, 12, 2.5, 48.7, 2.8, 5, 1071, 2.68, '["Korean Chili Flake Ref","USDA FDC 168456","USDA FDC 169230","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277"]', '11a9c6dd0fc07d67694f982adf43440118425cc408550deb1590185444ac8f34', '491c49589409ae0be299c27cd02c5e7ebc1d99c71cf2b8be4045114692d2a303', 4),
('imp-28d20ebe44b82a22', 'nam-xao-tuong-han', 316, 'Nấm đùi gà xào tương kiểu Hàn', 'Nấm đùi gà thái miếng dày xào săn bóng với nước tương, dầu hào, tỏi phi và ớt sừng giòn dai thanh ngọt', 'Nấm đùi gà xào tương là món banchan (món phụ) quen thuộc trên mâm cơm Hàn Quốc nhờ cách làm nhanh gọn chỉ trong 20 phút. Nấm đùi gà xào lửa vừa giữ được độ dai giòn sần sật, thấm đều hỗn hợp nước tương đặc, dầu hào và mè rang thơm bùi.', 'Bày nấm ra đĩa nhỏ rắc hành lá và mè trắng rang; dùng nóng với cơm trắng hoặc để nguội làm món ăn kèm trong hộp cơm văn phòng vẫn giữ độ giòn dai.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tới 3 ngày; có thể ăn nguội kiểu banchan hoặc đảo lại nhanh trên chảo nóng 1 phút.', 'korean', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Banchan","Nấm đùi gà","Hàn Quốc","Xào tương","Món nhanh"]', '["lunch","dinner"]', '["stir_fry"]', '["molluscs","sesame","soybean","wheat"]', 165, 165.3, 691, 5.4, 11.4, 1.6, 13.8, 3.4, 5.1, 786, 1.96, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277"]', '1aa38449437ecdc8e1cabe7818b03852208b74bb5809257ec181a3e364c52f46', '0c17b36d2426611b912ea9d330b112e384c4db5194681408c1f9f221181295d4', 4),
('imp-922028bd2fb07eb8', 'dau-phu-chien-tuong-han', 317, 'Đậu phụ chiên sốt tương hành kiểu Hàn (Dubu Buchim)', 'Đậu phụ chiên áp chảo vàng giòn hai mặt, rim nhanh cùng sốt tương tỏi hành siro ngô sánh bóng đậm đà', 'Đậu phụ chiên sốt tương hành (Dubu Jorim / Dubu Buchim) là món banchan truyền thống có mặt trong hầu hết bữa cơm Hàn Quốc. Miếng đậu phụ chắc được thấm khô và áp chảo vàng đều hai mặt rồi rim nhẹ trong nước tương, siro ngô, tỏi băm và ớt bột tạo nên lớp áo bóng mặn ngọt hài hòa.', 'Xếp đậu phụ ra đĩa, chan phần sốt tương hành sánh bóng lên trên và rắc mè trắng rang; dùng nóng hay nguội cùng cơm trắng đều rất ngon.', 'Có thể bảo quản ngăn mát tủ lạnh tới 3 ngày trong hộp kín; món này ăn nguội kiểu banchan vẫn đậm đà hoặc hâm nóng nhẹ bằng chảo 2 phút.', 'korean', 'mon_chien', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Dubu buchim","Đậu phụ","Banchan","Hàn Quốc","Chiên sốt"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 271, 271.1, 1134, 18, 19.5, 2.8, 11.2, 2.5, 6.5, 778, 1.94, '["Korean Chili Flake Ref","USDA FDC 168836","USDA FDC 169230","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', 'a839b902adbcad5a246ed11c992832f14ef29813cca345f524911f5704f15940', 'c8ea81420518f570a85813b6274d46ea9ba593d18afbd9bc8d4578377720bd29', 4),
('imp-b575db6fcd68a387', 'canh-trung-han', 318, 'Canh trứng kiểu Hàn (Gyeran Guk)', 'Tô canh trứng thanh nhẹ nấu nước dùng tảo bẹ ngọt tự nhiên, vân trứng tơ mềm mịn thơm hành lá và dầu mè', 'Canh trứng Gyeran Guk là món canh nhà quốc dân của Hàn Quốc vì chỉ mất 15 phút chế biến nhưng vô cùng ấm bụng và dễ tiêu hóa. Nước dùng đun cùng tảo bẹ kombu ngọt thanh tự nhiên, nêm nhẹ nước tương và nước mắm rồi rưới trứng gà đánh tan tạo thành những vân trứng mềm mịn như mây.', 'Múc canh ra tô nóng, rắc chút tiêu đen và nhỏ vài giọt dầu mè thơm; ăn kèm cơm trắng nóng hoặc chan trực tiếp cơm vào canh cho bữa sáng nhẹ nhàng.', 'Canh trứng nên dùng hết trong bữa để giữ vân trứng mềm mượt và không bị tanh; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 12 giờ và đun sôi nhẹ lại.', 'korean', 'mon_canh', NULL, 'easy', 5, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gyeran guk","Canh trứng","Hàn Quốc","Thanh đạm","Món nhanh"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","fish","sesame","soybean","wheat"]', 112, 111.6, 467, 8.4, 7.2, 2.1, 3.1, 0.5, 0.6, 891, 2.23, '["USDA FDC 168457","USDA FDC 169230","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '21e84ec0f5d392b884efedfc34da3b92822d4ccb519b2915d1a591a136535a5a', '963259b5d459c3161fe24cef3cabe6afc4652909bbac5714da33b5fe4626de5b', 4),
('imp-53933600fa3853f3', 'bo-xao-nam-han', 319, 'Thịt bò xào nấm kiểu Hàn', 'Thịt bò thái lát mỏng ướp sốt tương mè tỏi đường xào lửa lớn cùng nấm đùi gà giòn ngọt và hành tây', 'Thịt bò xào nấm kiểu Hàn kết hợp hương vị bulgogi mặn ngọt thơm dầu mè với nấm đùi gà thái lát dọc dai giòn và hành tây ngọt thanh. Thịt bò được thái mỏng ngang thớ và ướp thấm gia vị trước khi xào nhanh trên chảo nóng, giúp thịt mềm mọng mà không bị ra nước.', 'Dọn thịt bò và nấm nóng hổi ra đĩa, rắc hạt mè trắng rang lên trên; ăn kèm cơm trắng nóng hoặc cuốn cùng rau xà lách và kim chi.', 'Có thể ướp thịt bò trước trong ngăn mát tới 12 giờ; món xào ngon nhất khi ăn nóng ngay, nếu bảo quản tủ mát tối đa 24 giờ và đảo lại nhanh trên chảo nóng 1–2 phút.', 'korean', 'mon_xao', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Bulgogi xào","Thịt bò","Nấm đùi gà","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","sesame","soybean","wheat"]', 435, 435.1, 1821, 31.9, 26.9, 7.3, 17.6, 2.9, 9.1, 847, 2.12, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174277"]', '543b94203f7714453264c4fdac486ab87dd50e0e4dc328db7aa0ba94e807f99b', '3c782f0eb8065c8f21b8a6c806663185133698f5fd32fa24e94f203279ef04c7', 4),
('imp-81fc284c0bafa826', 'tom-xao-sa-ot-thai', 320, 'Tôm tươi xào sả ớt lá chanh kiểu Thái', 'Tôm tươi săn ngọt xào lửa lớn cùng sả băm, tỏi, ớt hiểm và lá chanh Thái thơm nồng, áo đều sốt dầu hào xì dầu đường thốt nốt óng mượt', 'Món tôm xào sả ớt kiểu Thái nổi bật nhờ sự kết hợp giữa sả băm, tỏi, ớt hiểm và lá chanh Kaffir thơm nồng đặc trưng, quyện cùng nước sốt xào sánh bóng từ dầu hào, xì dầu và đường thốt nốt.', 'Bày tôm xào sả ớt nóng hổi ra đĩa, rưới phần sốt sánh thơm trong chảo lên trên và dọn ăn ngay với cơm trắng dẻo.', 'Tôm xào ngon nhất khi ăn nóng ngay lúc thịt còn giòn ngọt; nếu còn dư bảo quản ngăn mát 24 giờ và làm nóng nhanh trên chảo lửa vừa khoảng 1–2 phút.', 'thai', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món xào","Tôm tươi","Sả ớt","Đậm đà"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 216, 216.3, 905, 26, 7.7, 1.2, 11.9, 0.5, 4.7, 1162, 2.91, '["Citrus Leaf Culinary Ref","Dark Soy Sauce Label Ref","USDA FDC 168573","USDA FDC 169230","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', '3406ef52ca5a61b090f2ccf657369cae798eec75309e291f53d60fd6256c7f18', 'a95fef2099fccbbc1c12a966d1bf90f86f85f18f64d2c32ec32b17ea9badd496', 4),
('imp-15e4185437e9198c', 'mi-xao-pad-thai-tom', 321, 'Mì xào Pad Thai tôm truyền thống', 'Bánh phở khô ngâm mềm xào nhanh lửa lớn với sốt me đường thốt nốt thắng caramen, tôm áp chảo, đậu phụ ép, trứng gà, giá đỗ và hẹ tươi', 'Công thức Pad Thai tôm truyền thống cân chỉnh chuẩn cho 3 phần ăn, giữ nguyên kỹ thuật thắng caramen đường thốt nốt cùng nước cốt me chua dịu, đậu phụ ép chiên cạnh vàng và sợi trứng tơi quyện quanh từng sợi bánh phở.', 'Gắp Pad Thai ra 3 đĩa, đặt tôm áp chảo lên trên, rắc đậu phộng rang giã dập và ớt khô xay; dọn kèm múi chanh, giá đỗ và hẹ sống.', 'Thưởng thức ngon nhất ngay lúc vừa xào xong; phần dư bảo quản ngăn mát tối đa 24 giờ và làm nóng trên chảo với 1 muỗng canh nước lọc.', 'thai', 'mon_xao', NULL, 'medium', 25, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Thai","Mì xào","Truyền thống","Tôm tươi"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","peanut","shrimp","soybean"]', 772, 772.3, 3232, 44.5, 28.5, 4.9, 88.7, 6.6, 27.9, 1721, 4.3, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169745","USDA FDC 169918","USDA FDC 169963","USDA FDC 169994","USDA FDC 170499","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 172475","USDA FDC 173647","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', 'e9688803f56e52ce29df722f271dde523c5b23f16535e34a65f4b3566a1a71e2', '43174c886f2e91af5f7707bf7841412f95c30b9e68a0918ca2b1bb9c9fb86c70', 4),
('imp-cc62ea4de6a7436b', 'goi-dua-tom-thai', 322, 'Gỏi dứa tôm tươi chua cay kiểu Thái', 'Dứa chín vàng mọng trộn cùng tôm luộc giòn ngọt, hành tím thái mỏng, ớt hiểm và nước mắm chanh chua cay thanh mát, rắc đậu phộng rang bùi', 'Gỏi dứa tôm tươi kiểu Thái là món khai vị giải ngấy tuyệt vời với vị ngọt mọng tự nhiên của dứa chín hòa quyện tôm luộc giòn săn, vị chua cay mặn ngọt cân bằng và hương bạc hà the mát.', 'Bày gỏi dứa tôm ra đĩa rộng, rắc đậu phộng rang giã dập cùng lá bạc hà xắt rối lên trên; dùng ngay làm món khai vị hoặc ăn kèm cơm trắng.', 'Dứa chín dễ tiết nước sau khi trộn muối mắm nên món gỏi ngon nhất khi dùng ngay trong vòng 1 giờ sau khi trộn.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Dứa chín","Tôm tươi","Khai vị"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 263, 262.7, 1099, 24, 8.1, 1.1, 28, 4.2, 19.3, 1057, 2.64, '["USDA FDC 168155","USDA FDC 169124","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 172185","USDA FDC 172430","USDA FDC 173474","USDA FDC 173647","USDA FDC 175179"]', '490144712173babacf18df90449d8c404ab7202f9c750ce6e2a4807b5952af60', '6760c2a4d072f36a5df5f0cab6ba0b2f178b1ad690d97cb2daf0e7cbb82b4b99', 4),
('imp-3d7573766352454e', 'canh-ga-sa-thai', 323, 'Canh gà nấu sả nấm chua thanh kiểu Thái (Tom Yum Gai)', 'Thịt đùi gà hầm mềm trong nước dùng gà trong thanh dậy hương hành tím nướng, sả, riềng, lá chanh Thái cùng nấm đùi gà giòn và vị chua me chanh', 'Món canh gà sả nấm kiểu Thái mang hương vị chua cay thanh tao từ nước cốt me kết hợp chanh tươi, hành tím áp chảo thơm lừng cùng sả, riềng, lá chanh Thái, thịt đùi gà mềm ngọt và nấm đùi gà giòn sần sật.', 'Múc canh gà sả nấm nóng hổi ra tô lớn, rắc hành lá thái nhỏ lên trên và ăn kèm cơm trắng nóng.', 'Có thể bảo quản trong hộp kín ngăn mát tối đa 2 ngày (nên vớt bỏ xác sả riềng trước khi cất); khi ăn hâm nóng lại trên lửa vừa tới sôi lăn tăn.', 'thai', 'mon_canh', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Thịt gà","Nấm đùi gà","Chua cay"]', '["lunch","dinner"]', '["simmer"]', '["chicken","fish"]', 270, 270.3, 1132, 25.1, 11.8, 3.2, 16.7, 2.6, 7.7, 1729, 4.32, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169918","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 172185","USDA FDC 172385","USDA FDC 172883"]', 'a82b1a0fc2bf14448dd30e2020525e7939be6909f339965f3b1bfa08bf983dd1', 'cf4ff082166e43e0a2ad6f661c79c6f8fe71c01f5533874132681ba4e60ef573', 4),
('imp-88fc351665d5e9fc', 'bo-xao-ot-thai', 324, 'Bò xào ớt kiểu Thái', 'Thịt bò thăn xào nhanh trên lửa lớn cùng ớt chuông, ớt hiểm, hành tây và sốt dầu hào sánh đậm vị Thái', 'Bò xào ớt kiểu Thái là món xào lửa lớn nổi tiếng với từng lát thịt bò mềm mọng áo đều lớp sốt dầu hào, xì dầu đậm đà, hòa cùng vị cay thơm của ớt hiểm, tỏi phi và độ giòn ngọt tự nhiên của ớt chuông, hành tây.', 'Dọn nóng ngay ra đĩa, rắc thêm hành lá; dùng kèm cơm trắng nóng hổi và có thể thêm một quả trứng ốp la lòng đào kiểu Thái.', 'Ngon nhất khi ăn ngay sau khi xào; nếu còn dư, để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo nóng 1–2 phút.', 'thai', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Ẩm thực Thái","Cay nồng","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","fish","molluscs","soybean","wheat"]', 333, 333.1, 1394, 23.4, 19.3, 5.4, 17.1, 5.3, 6.3, 1037, 2.59, '["Dark Soy Sauce Label Ref","USDA FDC 168437","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170187","USDA FDC 170933","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172883","USDA FDC 173647","USDA FDC 174277"]', 'b9124173535dfc3f7c7ec602f64492404e4d9ebf72ef5c5a1d66c3cc5f98b1c0', 'f925fc6eadbab9d2f980b752a1c9fdf433e6f4b54815c73817ee8057ac1b568c', 4),
('imp-4ec49419e966f676', 'ca-nuong-muoi-sa', 325, 'Cá diêu hồng nướng muối sả kiểu Thái', 'Cá nguyên con giữ vảy nhồi sả và lá chanh Kaffir bọc muối hạt nướng thơm, thịt trắng mọng chấm sốt hải sản xanh cay nồng', 'Cá diêu hồng nướng muối sả kiểu Thái (Pla Pao) giữ nguyên lớp vảy cá bọc muối hạt mịn giúp khóa trọn độ ẩm và vị ngọt tự nhiên của thớ thịt cá trắng bên trong, thơm dịu mùi sả và lá chanh Kaffir, chấm cùng sốt chanh tỏi ớt chua cay đặc trưng.', 'Lột bỏ lớp da bọc muối khi ăn, dọn phần thịt cá trắng nóng hổi kèm bún tươi, rau xà lách và chén sốt chấm chanh tỏi ớt hải sản.', 'Nên ăn hết khi cá còn ấm nóng; phần thịt cá gỡ sẵn có thể bọc kín bảo quản ngăn mát tối đa 24 giờ, làm nóng lại bằng nồi chiên không dầu hoặc áp chảo 3 phút.', 'thai', 'mon_lau_tiec', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Cá diêu hồng","Ẩm thực Thái","Nướng muối","Tiệc gia đình"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","wheat"]', 245, 245.4, 1026, 39.4, 4.8, 1.3, 9.7, 0.7, 4.2, 1301, 3.25, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170106","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', 'd62c1eb63358727dc5dab4f8ddaedc748d1dae72a89c48b21cd6d4731e3518ec', '71a03252d0e0dbc64f25c251b6471e679362bbbe35f4c2b0436618d878f73058', 4),
('imp-e47b2f01ee81031a', 'mi-xao-dua-tom-thai', 326, 'Mì xào dứa tôm kiểu Thái', 'Sợi hủ tiếu gạo xào dai mềm với tôm tươi, dứa chín chua ngọt, trứng gà, giá đỗ và sốt me đậm vị Pad Thai', 'Mì xào dứa tôm kiểu Thái kết hợp sợi hủ tiếu gạo dai mềm áo sốt me chua ngọt cùng tôm tươi săn giòn, dứa chín mọng nước, trứng gà tơi béo và đậu phộng rang bùi thơm, mang hương vị đường phố Bangkok tươi mới.', 'Bày mì ra đĩa lớn, rắc hành lá tươi và đậu phộng rang giã dập lên trên; dọn nóng kèm múi chanh tươi và ít ớt bột khô tùy khẩu vị.', 'Nên thưởng thức ngay khi sợi mì còn nóng dẻo; phần dư có thể bảo quản ngăn mát tối đa 24 giờ và làm nóng bằng chảo chống dính với 1 muỗng canh nước.', 'thai', 'mon_xao', NULL, 'easy', 25, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Pad Thai","Tôm tươi","Dứa thơm","Ẩm thực Thái"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","peanut","shrimp","soybean","wheat"]', 619, 618.6, 2589, 30.4, 22.3, 3.7, 77, 5.2, 19.1, 1713, 4.28, '["USDA FDC 168155","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169745","USDA FDC 169918","USDA FDC 169963","USDA FDC 170005","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '37fc230fce50a0143635905fef8371defe76b656707fc3e53c2675b96159eb11', '26779337a3ba10e1083221bb37b461634638ed134c6e87f6cb84913092c0b624', 4),
('imp-192973f6e1b702b5', 'dau-phu-chien-sot-cay-thai', 327, 'Đậu phụ chiên sốt cay kiểu Thái', 'Đậu phụ chiên vỏ giòn ruộm rưới sốt tương ớt tỏi, đường thốt nốt và nước cốt chanh chua cay ngọt hài hòa', 'Đậu phụ chiên sốt cay kiểu Thái hấp dẫn với lớp vỏ ngoài chiên vàng giòn rụm, bên trong vẫn mềm béo, quyện cùng nước sốt chua cay mặn ngọt từ đường thốt nốt, nước cốt chanh, tương ớt và tỏi phi thơm lừng.', 'Xếp đậu phụ chiên nóng ra đĩa, rưới đều sốt cay hoặc dọn chén sốt chấm riêng bên cạnh; rắc ngò rí, hành lá và vài lát ớt hiểm, dùng làm món khai vị hoặc ăn kèm cơm trắng.', 'Đậu chiên giòn nên ăn ngay lúc nóng; nếu dư, tách riêng đậu và sốt để tủ mát 24 giờ, chiên lại đậu trong nồi chiên không dầu 4 phút ở 180°C trước khi rưới sốt.', 'thai', 'mon_chien', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Đậu phụ chiên","Món chay","Khai vị","Ẩm thực Thái","Chua cay"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["soybean","wheat"]', 404, 404.3, 1691, 20.4, 22.1, 3.2, 36.3, 3.4, 14.9, 1023, 2.56, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169698","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172475","USDA FDC 174277","USDA FDC Palm Sugar Ref","USDA FDC Sriracha Ref"]', 'a6777df67ee49288a65f8ce9fa97899c7a1f5650f253d44d9ce9746b8b26f19b', 'e0df246cf9b1c255028596d2ff500a98037e7230f87f2debf0c3968c7c637480', 4),
('imp-2a705e2ff35573b1', 'canh-chua-me-tom-thai', 328, 'Canh chua me tôm kiểu Thái', 'Canh chua me Gaeng Som dịu thanh với tôm tươi, cà chua, nấm đùi gà và thịt cá nghiền sánh nhẹ chuẩn vị Thái', 'Canh chua me tôm kiểu Thái (Gaeng Som) mang vị chua thanh dịu từ me chín kết hợp hậu ngọt của đường thốt nốt, nước dùng sánh nhẹ nhờ thịt cá phi lê nghiền mịn, ăn kèm tôm tươi ngọt thịt, cà chua và nấm đùi gà giòn ngon.', 'Múc canh chua me nóng ra tô lớn, rắc hành lá và vài lát ớt hiểm tươi lên trên; dọn ăn nóng kèm cơm trắng hoặc trứng chiên kiểu Thái.', 'Canh ngon nhất trong ngày; bảo quản phần dư trong hộp kín ở ngăn mát tối đa 24 giờ, đun sôi nhẹ lại trước khi ăn (tránh đun lâu làm tôm bị dai).', 'thai', 'mon_canh', NULL, 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Canh chua","Tôm tươi","Gaeng Som","Ẩm thực Thái","Thanh mát"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 211, 211.3, 885, 25.5, 2.6, 0.6, 24.1, 3.6, 14.4, 1316, 3.29, '["Asian Shrimp Paste Ref","USDA FDC 168155","USDA FDC 168580","USDA FDC 169230","USDA FDC 169918","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171319","USDA FDC 172185","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', '9ba186380118971ee20883248094ad55193eb264cad2e8a0456d899a98224c14', 'be72bb899d807fa79d123731256a2a70d383ae9c0dbdd38e9a276b4caf23d1e9', 4),
('imp-f050984a2c4deb91', 'goi-nam-chua-cay-thai', 329, 'Gỏi nấm chua cay kiểu Thái', 'Nấm đùi gà, nấm kim châm và nấm mỡ chần giòn trộn hành tây tím, cà chua bi cùng nước sốt chanh tỏi ớt chay thanh mát', 'Gỏi nấm chua cay kiểu Thái kết hợp ba loại nấm chần giòn ngọt là nấm đùi gà, nấm mỡ và nấm kim châm, trộn đều với hành tây tím, cà chua bi, cần tây và nước sốt chanh tỏi ớt chua cay mặn ngọt bùng vị, rắc đậu phộng rang bùi béo.', 'Bày gỏi nấm ra đĩa sâu lòng, rắc đậu phộng rang giã dập lên mặt; dùng ngay làm món khai vị thanh mát hoặc ăn kèm cơm trắng, xôi nếp đều hợp.', 'Gỏi nên trộn và ăn hết trong vòng 2 giờ để nấm giữ độ giòn và không ra nước; nếu chuẩn bị trước, bảo quản riêng nấm đã chần ráo và chén nước trộn trong ngăn mát tối đa 12 giờ.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi nấm","Món chay","Khai vị","Ẩm thực Thái","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["celery","peanut","soybean","wheat"]', 217, 217.4, 909, 11.7, 9.8, 1.3, 26.8, 7, 10.9, 1037, 2.59, '["USDA FDC 168155","USDA FDC 168580","USDA FDC 169230","USDA FDC 169251","USDA FDC 169253","USDA FDC 169655","USDA FDC 169988","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 172430","USDA FDC 173468","USDA FDC 174277"]', '639dd78768e775b3901c292be6a0245c45f27bd6097d67fc7b72bd4e41e293c2', '0faa57b2cac9ee2a8a31fc64a3c2fb958b4f2f0a154846be403bc391b7dda3d1', 4),
('imp-8b874d97e90e00f0', 'ga-chien-sa-thai', 330, 'Gà chiên sả kiểu Thái', 'Đùi gà lọc xương ướp sả giã tơi sợi, rễ ngò, tỏi tiêu rồi chiên ngập dầu vàng giòn rụm, xóc cùng lá chanh Kaffir thơm nức', 'Gà chiên sả kiểu Thái hấp dẫn với từng miếng thịt đùi gà mềm mọng bên trong, lớp vỏ ngoài giòn rụm áo phủ những sợi sả giã tơi chiên vàng ruộm, dậy hương nồng nàn của rễ ngò rí, tiêu đen và lá chanh Kaffir.', 'Bày gà chiên sả cùng sợi sả chiên giòn ra đĩa lớn, dùng nóng với cơm trắng hoặc xôi nếp dẻo kèm tương ớt chua ngọt Thái và dưa leo.', 'Gà chiên ngon nhất ngay sau khi vớt ráo dầu; phần dư bọc kín bảo quản ngăn mát tối đa 48 giờ, làm nóng lại bằng nồi chiên không dầu ở 180°C trong 6–8 phút để lấy lại độ giòn.', 'thai', 'mon_chien', NULL, 'medium', 40, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Đùi gà","Sả ớt","Ẩm thực Thái","Giòn rụm"]', '["lunch","dinner"]', '["deep_fry"]', '["chicken","fish","molluscs","soybean","wheat"]', 427, 426.5, 1785, 30.4, 26.4, 5.9, 16.1, 0.8, 4.3, 1092, 2.73, '["Citrus Leaf Culinary Ref","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169997","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC Sriracha Ref"]', 'a575cd3644687bf4ffe4ce7ee40ae71e30a24d529ca0335291ccb0aff6b74836', '087e9c86937ff6f8b04afee1f88ce65277f460e939a40079c82d5c3a33d1d9e4', 4),
('imp-b95544e75512c4e8', 'mi-y-toi-dau-ot', 331, 'Mì Ý tỏi dầu ớt kiểu truyền thống', 'Sợi Spaghetti al dente xóc cùng tỏi lát phi vàng trong dầu ô liu nguyên chất, ớt sừng đỏ cay nồng và nước luộc mì sánh mịn', 'Mì Ý tỏi dầu ớt truyền thống chinh phục vị giác bằng sự thuần khiết: dầu ô liu nguyên chất thơm nức mùi tỏi lát phi dịu và vị cay ấm của ớt sừng đỏ, hoàn thiện bằng kỹ thuật xóc chảo với nước luộc mì tạo lớp sốt bóng mượt tự nhiên.', 'Chia mì ra 3 đĩa sâu lòng khi còn nóng hổi, rưới đều phần dầu tỏi ớt còn lại trong chảo và rắc thêm ngò tây tươi thái nhỏ nếu thích.', 'Mì tỏi dầu ớt ngon nhất khi dùng nóng ngay sau khi nấu; nếu cần hâm lại, đảo nhanh trên chảo cùng 1–2 muỗng canh nước ấm để tránh mì bị khô.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Aglio e Olio","Cay nhẹ","Nhanh gọn"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["wheat"]', 423, 422.9, 1769, 10.7, 14.9, 2.1, 60.9, 2.7, 2.3, 395, 0.99, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'f410cc3375ee28ff769eb5e0956acf4482cc88a3b7cb2dcd641406f30d1333c8', '943ba15ee0d5e8fad6847477e21d1a9ce45e4feb1e358ba07a2cfdd2236a1f54', 4),
('imp-5ae4665cc17ff036', 'mi-y-sot-cay-ca-chua', 332, 'Mì Ý Penne sốt cà chua cay Arrabbiata', 'Mì ống Penne có rãnh thấm đẫm sốt cà chua lột vỏ ninh sánh quyện vị cay nồng của ớt tươi, hương tỏi phi dầu ô liu và ngò tây thơm mát', 'Penne all''Arrabbiata là món mì cay nổi tiếng vùng Lazio với cái tên mang nghĩa ''giận dữ'' bởi sắc đỏ rực của cà chua và vị cay bùng nổ từ ớt tươi. Mì ống Penne có rãnh nhỏ giúp ôm trọn phần sốt cà chua sánh đặc cùng hương ngò tây tươi mát.', 'Múc mì ra 3 đĩa sâu lòng khi còn nóng hổi, rắc thêm ngò tây tươi băm và phô mai Pecorino Romano bào mịn nếu thích.', 'Sốt Arrabbiata ngon nhất khi dùng ngay; phần dư bảo quản hộp kín trong ngăn mát tối đa 1–2 ngày và hâm nóng trên chảo cùng chút nước lọc.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Arrabbiata","Sốt cay","Cà chua"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["milk","wheat"]', 449, 448.7, 1877, 15.1, 13.3, 3.3, 68, 4.6, 6.9, 716, 1.79, '["USDA FDC 168927","USDA FDC 169072","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC Pecorino Ref"]', '16a242100a73ec1803f750fdb13a912fc9570cd02561a535783ba386d04f3846', 'c00408e31d736fedc58545898f2f8991529d0ff39bbea9e7083c6dcc06965cf0', 4),
('imp-9c48616208fff232', 'mi-y-bong-cai-xanh', 333, 'Mì Ý sốt kem bông cải xanh hạnh nhân', 'Sợi mì Spaghetti quyện sốt bông cải xanh xay mịn cùng phô mai Parmesan, bông cải om mềm và hạnh nhân rang giòn bùi thơm', 'Mì Ý bông cải xanh hạnh nhân là món pasta rau củ thanh mát, giàu dinh dưỡng với phần sốt xanh mướt được tạo nên từ một nửa bông cải xanh xay nhuyễn cùng hạnh nhân rang và phô mai Parmesan, kết hợp phần bông cải om mềm giữ nguyên nhánh tạo kết cấu thú vị.', 'Múc mì ra 3 đĩa sâu lòng khi còn nóng, rắc phần hạnh nhân rang giòn còn lại, ít phô mai Parmesan bào và ớt tươi thái lát lên trên.', 'Món mì sốt rau củ ngon nhất khi ăn nóng ngay; nếu còn dư bảo quản ngăn mát tối đa 2 ngày và hâm nóng trên chảo cùng vài muỗng nước lọc cho sốt mượt lại.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Bông cải xanh","Hạnh nhân","Thanh đạm"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["almond","milk","tree_nuts","wheat"]', 584, 583.7, 2442, 21.3, 24.8, 6.6, 71.6, 7.5, 5, 677, 1.69, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170379","USDA FDC 170567","USDA FDC 170848","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', 'd6ddf99b03905d628dd03b18374d5a68aecae9a75fb0206b1429e01b83140a16', '5d96d7d2893eb93e5cc9d4a8b40f10c07614c6210048e1cc7b41bb238cf7f2d9', 4),
('imp-b5571547ad5d2cec', 'mi-y-ca-hoi-bo-chanh', 334, 'Mì Ý cá hồi sốt bơ chanh', 'Mì ống hoặc Spaghetti trộn cá hồi áp săn thấm rượu vang trắng, nước cốt chanh vàng thanh mát và sốt bơ lạt đánh bóng thơm ngò tây', 'Mì Ý cá hồi sốt bơ chanh là lựa chọn hoàn hảo cho bữa tối nhanh gọn mà vẫn tinh tế. Cá hồi áp chảo vừa chín mềm được hòa quyện cùng hành tím phi thơm, rượu vang trắng, nước cốt chanh vàng và bơ lạt đánh bóng ngoài bếp lửa.', 'Chia mì và cá hồi ra 3 đĩa sâu lòng khi còn nóng, rắc vỏ chanh vàng bào sợi mảnh, phần ngò tây tươi còn lại và tiêu đen xay lên trên.', 'Món mì cá hồi sốt bơ chanh nên thưởng thức ngay lúc nóng để sốt bơ giữ độ bóng mượt; phần dư bảo quản ngăn mát tối đa 24 giờ và hâm nhẹ trên chảo lửa nhỏ.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Cá hồi","Bơ chanh","Nấu nhanh"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["fish","milk","salmon","sulphites","wheat"]', 655, 654.9, 2740, 27.8, 29.7, 9.2, 64.3, 3.6, 3.8, 448, 1.12, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 170416","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175167"]', 'd3f1f616f764d857d3e4aa6df85c730517100f64ce47d3d5dcbf397c272ba719', '67e8950d77f39848430cfbeb7921b41aa1372a72d2b5fb74844ad67f3d51ec6a', 4),
('imp-7b5f0d33681ea7d2', 'ga-parmigiana-nuong', 335, 'Gà Parmigiana nướng phô mai', 'Ức gà tẩm bột chiên xù giòn rụm phủ sốt cà chua húng quế và phô mai Mozzarella nướng tan béo ngậy chuẩn vị Ý', 'Món gà Parmigiana kinh điển với từng lát ức gà dần mỏng tẩm bột chiên xù trộn phô mai Pecorino vàng giòn, phủ sốt cà chua húng quế nấu sánh và phô mai Mozzarella nướng chảy thơm lừng.', 'Dọn nóng trực tiếp từ khay nướng, rắc ngò tây băm; dùng kèm mì Ý luộc hoặc salad rau xanh trộn dầu giấm để cân bằng vị béo.', 'Nên thưởng thức ngay khi lớp vỏ còn giòn; nếu còn dư, đậy kín trong ngăn mát tối đa 2 ngày và hâm nóng lại bằng lò nướng 180°C trong 10 phút.', 'italian', 'mon_lau_tiec', NULL, 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Gà Parmigiana","Ẩm thực Ý","Nướng lò","Phô mai","Món chính"]', '["lunch","dinner"]', '["pan_fry","simmer","grill_roast"]', '["chicken","egg","milk","wheat"]', 692, 691.9, 2895, 62.1, 32.4, 11.9, 37.7, 4.1, 8, 1501, 3.75, '["Panko / Batter Mix Ref","USDA FDC 167746","USDA FDC 169072","USDA FDC 169230","USDA FDC 169761","USDA FDC 170416","USDA FDC 170845","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 171477","USDA FDC 172232","USDA FDC 173468","USDA FDC Pecorino Ref"]', 'efc4d47f0499fad55f611e3d4170ae58885fd1ff5116b3a07931e190e81dd2f0', '98ffaa2517b022e2f5a83077bcdcaa1982ad4cec3a3dc9910bcf1dabe001034f', 4),
('imp-e3df53f1154592bc', 'ca-nuong-ca-chua-y', 336, 'Cá nướng cà chua chanh vàng kiểu Ý', 'Phi lê cá biển thịt trắng ướp chanh tỏi nướng lò cùng cà chua chín mọng và lớp vụn bánh mì giòn thơm thảo mộc', 'Phi lê cá thịt trắng chắc ngọt được ướp thấm vị nước cốt chanh vàng, tỏi và dầu ô liu, phủ lớp vụn bánh mì ngò tây giòn rụm rồi nướng lò cùng cà chua chín mọng tiết sốt chua ngọt tự nhiên.', 'Dọn cá nóng ra đĩa, rưới phần nước sốt cà chua đọng dưới khay lên trên và ăn kèm bánh mì giòn hoặc khoai tây nướng.', 'Món ngon nhất khi ăn nóng ngay sau khi nướng; nếu còn thừa có thể bảo quản ngăn mát tối đa 24 giờ và hâm lại ở 170°C trong 6–8 phút.', 'italian', 'mon_lau_tiec', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Cá nướng","Ẩm thực Ý","Cà chua","Chanh vàng","Ít béo"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","wheat"]', 332, 332.2, 1390, 33, 16.6, 2.8, 13.1, 2.3, 3.7, 724, 1.81, '["Panko / Batter Mix Ref","USDA FDC 167746","USDA FDC 169230","USDA FDC 170416","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 175148"]', '8d5061d70b4d0b4ab7f459fbb2aac2cb66f8e6741401406a8e8126f73123848d', '261071898f9ef91fe2dc1a424494bb530b0deb9df1ab49b3a1e5ea3a058e5fc3', 4),
('imp-a0ed6c762f7dceba', 'bo-pizzaiola', 337, 'Bò om sốt cà chua lá Oregano (Pizzaiola)', 'Lát thịt bò dần mỏng nấu nhanh trong sốt cà chua sánh quyện mùi tỏi thơm và lá Oregano chuẩn phong vị Napoli', 'Món bò Pizzaiola dân dã vùng Napoli với từng lát thịt bò dần mỏng mềm ngọt, thấm đẫm sốt cà chua nấu sánh thơm lừng mùi tỏi và thảo mộc Oregano đặc trưng.', 'Dọn nóng ngay ra đĩa, múc nhiều sốt cà chua rưới lên mặt thịt và rắc vài lá húng quế tươi; ăn kèm bánh mì giòn chấm sốt hoặc mì Ý luộc.', 'Nếu nấu trước, nên nấu riêng phần sốt cà chua và bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại sốt rồi mới cho thịt bò vào nấu chín để thịt không bị dai.', 'italian', 'mon_kho', NULL, 'easy', 10, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Bò Pizzaiola","Ẩm thực Ý","Thịt bò","Cà chua","Món mặn"]', '["lunch","dinner"]', '["simmer","braise"]', '["beef"]', 319, 318.8, 1335, 27.4, 20, 6.1, 7.5, 2, 3.9, 667, 1.67, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170187","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '59bba854661b3adbc13fcad87cb54d65bc60564bc22fba2d2622e72fc6ebc23f', '48e4ab40adcd4ebb53f819d712534a998f0a94559e184915327a9eccd1919f68', 4),
('imp-2865ee57783628d7', 'salad-mi-y-nguoi', 338, 'Salad mì Ý trộn nguội phô mai Feta', 'Mì xoắn Fusilli dai nhẹ hòa quyện cà chua bi, dưa leo giòn mát, phô mai Feta mặn béo và sốt chanh dầu ô liu', 'Đĩa salad mì Ý thanh mát mang phong vị Địa Trung Hải với những xoắn mì Fusilli chín vừa al dente quyện sốt dầu ô liu chanh vàng, cà chua mọng nước, dưa leo giòn ngọt và phô mai Feta béo mặn.', 'Dọn lạnh trực tiếp sau khi ủ mát 30 phút, rắc thêm lá húng quế tươi; rất hợp làm món chính nhẹ nhàng cho bữa trưa hoặc món khai vị cho tiệc nướng.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; trước khi ăn đảo nhẹ lại một lượt cho sốt hòa đều mà không cần hâm nóng.', 'italian', 'mon_cuon_nom', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Salad mì Ý","Ẩm thực Ý","Món mát","Bữa trưa","Feta"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["milk","wheat"]', 420, 420.3, 1758, 14.9, 15.3, 5.4, 56.3, 3.5, 4.2, 534, 1.34, '["USDA FDC 167746","USDA FDC 168409","USDA FDC 168927","USDA FDC 170000","USDA FDC 170457","USDA FDC 170853","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '4e6b611f9dcacb098e16d2f5ee35f835f2d6ea8b5610a77b9e3063647c4ac217', '18f78b8144f2cb92bddda87b7bb5a09e6ce254cf4de5557b5584a959d5d7221e', 4),
('imp-f9481ae10c0cc62a', 'sup-ca-chua-kem-y', 339, 'Súp cà chua kem tươi kiểu Ý', 'Súp cà chua chín xay mịn lọc rây mượt mà kết hợp sữa tươi, kem béo và bánh mì áp chảo giòn rụm ấm áp', 'Bát súp cà chua kem kiểu Ý mịn mượt như nhung với vị chua thanh tự nhiên từ cà chua chín hòa quyện độ béo dịu của sữa tươi, kem tươi và hương húng quế Tây thanh tao.', 'Múc súp nóng ra tô sâu lòng, rưới thêm vòng kem tươi, rắc phô mai Parmesan bào và dùng kèm các viên bánh mì áp chảo giòn rụm để giữ độ giòn.', 'Bảo quản phần súp trong hộp kín ở ngăn mát tối đa 2 ngày, tách riêng bánh mì giòn; khi ăn hâm nóng lại trên lửa thật nhỏ và khuấy đều, không đun sôi bùng.', 'italian', 'mon_canh', NULL, 'easy', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Súp kem cà chua","Ẩm thực Ý","Khai vị","Món nóng","Crouton"]', '["lunch","dinner"]', '["simmer","pan_fry"]', '["milk","wheat"]', 409, 409.3, 1712, 10.6, 28, 14.2, 30.9, 3.5, 15.5, 1062, 2.66, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170000","USDA FDC 170457","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 171595","USDA FDC 172232","USDA FDC 172687","USDA FDC 173430","USDA FDC 173468"]', '777a673e4e0c2d07a03b31964642c6669c8d2d661f565f124da91bfc42d31bdb', '549799400d5b6266539a3bd44ffd6523b4b2533c7748068f4ce85672b6316596', 4),
('imp-e39ba043b6d1f19d', 'rau-cu-nuong-y', 340, 'Rau củ nướng dầu ô liu kiểu Ý', 'Bông cải xanh, cà rốt và hành tây nướng chín tới xém cạnh caramel ngọt bùi quyện sốt dầu ô liu tỏi thơm', 'Khay rau củ nướng vàng xém cạnh với bông cải xanh giòn ngọt, cà rốt bùi bở và hành tây thơm lừng mùi tỏi nướng caramel hóa, quyện dầu ô liu nguyên chất, giấm Balsamic Ý chua ngọt dịu và thảo mộc Oregano Địa Trung Hải.', 'Dọn nóng hoặc ở nhiệt độ phòng như món ăn kèm lý tưởng cho gà nướng, bít tết bò hay cá áp chảo, hoặc dùng kèm cơm trắng đều ngon.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại bằng nồi chiên không dầu hoặc lò nướng 180°C khoảng 5–6 phút để rau giòn cạnh trở lại.', 'italian', 'mon_chay', NULL, 'easy', 12, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Rau củ nướng","Món chay","Ẩm thực Ý","Món phụ","Thanh nhẹ"]', '["lunch","dinner"]', '["grill_roast"]', '["sulphites"]', 166, 166.2, 695, 3.8, 10.3, 1.4, 17.4, 5.1, 6.6, 512, 1.28, '["USDA FDC 169230","USDA FDC 170000","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173470","USDA FDC 173475"]', '33be6358a761e86705eed5ac4e47452fe48e0161ef4392c680b766665e402862', '9b6625345de0bb5b2ab0801f3a2431177ff79a7c1ab1c80d5bf95e54f216d753', 4),
('imp-f50c115d909f97f2', 'canh-nam-ca-chua-chua-nhe', 341, 'Canh nấm cà chua chua nhẹ', 'Món canh thanh đạm kết hợp nấm đùi gà giòn ngọt và cà chua chín đỏ au, nấu nhanh gọn chỉ trong 20 phút', 'Canh nấm cà chua chua nhẹ không dùng thịt nhưng vẫn ngọt thanh nhờ sự kết hợp giữa nấm đùi gà, nấm rơm hoặc nấm hương tươi cùng vị chua dịu từ cà chua chín và hương thơm ấm nhẹ của gừng, hành tỏi.', 'Múc canh ra tô lớn khi còn nóng, rắc hành lá và chút tiêu đen xay; dùng kèm cơm trắng và đậu phụ chiên sả ớt hoặc cá kho.', 'Canh nấm ngon nhất khi dùng hết trong bữa; nếu bảo quản ngăn mát tủ lạnh tối đa 24 giờ, chỉ đun sôi lại 2 phút trên lửa vừa để nấm giữ độ giòn ngọt.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nấm đùi gà","Cà chua","Thanh đạm","Nấu nhanh"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 111, 111.2, 465, 4.1, 6, 0.9, 12.7, 3.2, 6.3, 898, 2.24, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647"]', 'b818d9b40063743456f446c8fd1625c5bdfa0c0cd991ffa750e434b229ebf551', 'ec3c7de7874a6f46f8328839e88092ea9c733ff5c1298d77262cbaa98534695e', 4),
('imp-ae5b053b8361f807', 'canh-tom-nau-sa-chua', 342, 'Canh tôm nấu sả chua', 'Nước canh miền Trung thơm lừng sả tươi và ớt hiểm, vị chua thanh của chanh hòa quyện cùng tôm tươi ngọt giòn kích thích vị giác', 'Canh tôm nấu sả chua mang đậm phong vị miền Trung với nước dùng trong vắt, thơm nồng hương sả đập dập và cay nhẹ từ ớt hiểm, kết hợp thịt tôm tươi săn ngọt cùng vị chua thanh mát của cà chua và nước cốt chanh.', 'Dọn canh nóng vào tô lớn, rắc hành lá và thêm vài lát ớt tươi; ăn nóng cùng cơm trắng và các món cá kho hoặc thịt ram mặn.', 'Canh ngon nhất khi dùng nóng ngay sau khi vắt chanh; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại phần nước canh và tôm 1–2 phút rồi mới nêm lại chút nước cốt chanh nếu cần.', 'vietnamese', 'mon_canh', 'trung', 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Miền Trung","Chua cay","Sả chanh"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 133, 133.1, 557, 15.5, 3.9, 0.6, 10.7, 1.5, 5.6, 1397, 3.49, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '60c43859f8dae007e40cd5367b7dec9604b2f2c3f6da0935de68059ea1afc715', 'e16d3c98654f3d3780e790bd6a44a26417c31ae780bf5c00472b7007bcf12d3d', 4),
('imp-ac77ed3af015efd7', 'canh-bo-bap-cai', 343, 'Canh thịt bò nấu bắp cải', 'Thịt bò thăn thái mỏng mềm ngọt quyện cùng lá bắp cải giòn ngọt và nước canh trong veo, món canh ấm áp cho bữa tối gia đình', 'Canh thịt bò nấu bắp cải kết hợp vị ngọt đậm của thịt bò thăn thái lát với độ ngọt mát tự nhiên của bắp cải và cà chua. Nước canh trong trẻo, thơm dịu mùi tỏi phi và ngò rí, cực kỳ dễ ăn.', 'Dọn canh nóng vào tô lớn, rắc hành lá, ngò rí và tiêu đen xay; thưởng thức cùng cơm trắng nóng dẻo và chén nước mắm ớt cắt lát.', 'Canh ngon nhất khi ăn nóng ngay lúc mới nấu để bắp cải giòn và thịt bò mềm ngọt; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhanh 1–2 phút trước khi dùng.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Bắp cải","Thanh ngọt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["beef","fish"]', 205, 205.4, 860, 17.6, 11.5, 3.6, 8.6, 2.9, 4.1, 1274, 3.18, '["USDA FDC 169230","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '1b30dea248be1d603857e8f36a7423549ab7af876f1f6ca762e2221df60173c8', '5b0f16ff1bea49b7e36b6649b17029e7c940a3eca6bcb3d9865d9b08d95ac04b', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-4ec35a6c12daa33d', 'muc-kho-tieu', 344, 'Mực kho tiêu', 'Mực tươi cắt khoanh khứa vảy rồng giòn ngọt kho tiêu đen cay nồng, nước sốt nâu cánh gián sánh đậm cực bắt cơm', 'Những khoanh mực tươi trụng sơ giữ nguyên độ giòn sần sật, thấm đẫm nước kho mặn ngọt màu cánh gián quyện mùi hành tỏi phi thơm và tiêu đen xay cay nồng.', 'Múc mực kho tiêu ra đĩa sâu lòng, rắc thêm tiêu đen xay và hành lá cắt khúc; ăn nóng với cơm trắng và dưa leo thái lát.', 'Ngon nhất khi dùng hết trong ngày để giữ độ giòn của mực; nếu bảo quản ngăn mát tối đa 24 giờ, làm nóng nhanh trên chảo lửa nhỏ khoảng 2 phút.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Mực tươi","Tiêu đen","Nam Bộ","Đưa cơm"]', '["lunch","dinner"]', '["braise","boil","stir_fry"]', '["fish","molluscs","squid"]', 226, 225.9, 945, 21, 10.2, 1.7, 11.9, 0.7, 5.2, 1064, 2.66, '["MEXT Sake 16021","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '000d2fdcd3a68e9d187c99b3c3027b2f5993f9ded508ceb88f47557d6272b6c7', 'ef4f133991164537581e78d5684e547d87bbaa727a2865ec4d7403401d638d9f', 4),
('imp-01121ea953ffed76', 'suon-kho-trung', 345, 'Sườn non kho trứng cút', 'Sườn non heo kho mềm róc xương cùng trứng cút luộc và nước dừa tươi thanh ngọt, thấm đẫm màu cánh gián đậm đà chuẩn cơm nhà', 'Những miếng sườn non kho liu riu trong nước dừa tươi đến khi mềm rệu, kết hợp cùng trứng cút bùi béo thấm màu nâu hổ phách sóng sánh và hương thơm cay ấm của tiêu ớt.', 'Múc sườn và trứng cút ra đĩa sâu lòng, chan nước kho sánh bóng và rắc hành lá cùng tiêu xay; ăn nóng với cơm trắng dẻo.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm lại trên lửa nhỏ cho nước sốt nóng sánh đều.', 'vietnamese', 'mon_kho', 'bac', 'medium', 20, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món kho","Sườn non","Trứng cút","Bắc Bộ","Cơm nhà"]', '["lunch","dinner"]', '["braise","boil","stir_fry"]', '["egg","fish","pork"]', 353, 352.7, 1475, 17.1, 26.2, 8.5, 11.7, 1.6, 8.7, 1098, 2.75, '["USDA FDC 167861","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170174","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172191","USDA FDC 173468","USDA FDC 173647"]', '5abf4b4fe39ba32c692c79c18bfeb4ba341d0125e9ca9e18098fb28076bed604', 'c8f74ef980631bbc4c17599e4ca6903fdc3ffac36ecb49cac6fbb7320459b619', 4),
('imp-296b724137581830', 'dau-phu-kho-tieu', 346, 'Đậu phụ kho tiêu', 'Đậu phụ trắng chiên vàng giòn hai mặt kho liu riu trong sốt nước tương sánh keo thơm nồng tiêu đen, món chay mặn đều dùng được cực đưa cơm', 'Những miếng đậu phụ vàng ruộm bên ngoài, mềm béo bên trong thấm đẫm sốt nước tương ngọt mặn hài hòa quyện vị cay ấm của tiêu đen xay và hương tỏi phi.', 'Xếp đậu phụ kho tiêu ra đĩa sâu lòng, rưới sốt sánh bóng và rắc hành lá, ớt lát cùng tiêu xay; ăn nóng với cơm trắng và rau luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa nhỏ với 1 muỗng canh nước lọc.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Đậu phụ","Món chay","Nhanh gọn","Đưa cơm"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["soybean","wheat"]', 241, 241.2, 1009, 17.6, 16.9, 2.5, 9.2, 2, 5.1, 973, 2.43, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '4a5d3eb680c7cae2a8092da8be8828d5949b1de5113b795c165642c141221231', 'fa7e8cb7fea67d891c6c15749cc75cdf9a018e82818e6f087ca831258c3d3552', 4),
('imp-54c8037962551d6b', 'gia-do-xao-toi', 347, 'Giá đỗ xào tỏi', 'Giá đỗ trắng mập giòn ngọt xào chớp nhoáng trên lửa lớn cùng tỏi phi vàng thơm và hành lá xanh tươi', 'Giá đỗ xào tỏi là món rau cấp tốc giữ nguyên độ giòn mọng ngọt thanh tự nhiên của giá đỗ tươi, quyện mùi tỏi phi vàng thơm lừng và vị mặn dịu vừa vặn, cực kỳ hợp để giải ngấy trong bữa cơm gia đình.', 'Gắp giá đỗ xào tỏi ra đĩa phẳng ngay sau khi tắt bếp, dùng nóng với cơm trắng cùng các món thịt kho hoặc cá chiên.', 'Giá đỗ xào rất nhanh ra nước khi nguội nên cần ăn hết ngay trong bữa; không khuyến khích bảo quản qua đêm.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Thanh đạm","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["fish"]', 116, 115.6, 484, 4.5, 7.2, 1.1, 11.1, 2.6, 5.4, 924, 2.31, '["USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'b3981b1e4dbccfd3c2f031d3bc5e66983b93422ac7f68ec890e53284b4429d8a', '165a01ade8a0619fcfb9dff6ab23ad7299ae0886c184aaaeb26bb0ca0a16edb2', 4),
('imp-e75e90d847daa628', 'mi-xao-hai-san', 348, 'Mì xào hải sản', 'Sợi mì trứng dai ngon xào lửa lớn cùng tôm mực giòn ngọt, cải thìa, cà rốt và ớt chuông quyện sốt dầu hào đậm đà', 'Mì xào hải sản là món ăn đủ chất và rực rỡ sắc màu với những vắt mì trứng dai mềm không bết dính, ôm trọn tôm sú, mực ống tươi giòn cùng cải thìa, cà rốt, ớt chuông thấm đẫm sốt dầu hào và nước tương thơm lừng.', 'Bày mì xào hải sản ra đĩa lớn, rắc thêm ngò rí và tiêu đen xay; dùng nóng kèm chén nước tương dầm ớt xắt lát.', 'Món mì xào ngon nhất khi ăn nóng ngay; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo với 1 muỗng canh nước lọc ở lửa vừa.', 'vietnamese', 'mon_xao', 'nam', 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Mì xào","Nam Bộ","Đủ chất"]', '["breakfast","lunch","dinner"]', '["stir_fry","boil"]', '["crustaceans","egg","molluscs","shrimp","soybean","squid","wheat"]', 492, 492, 2059, 31.9, 14.5, 2.4, 59.5, 5, 9, 1483, 3.71, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170390","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'c824e433bee5ac6dd2f5abc3bacebd44d36cba133a321218f8f65e4f549c02e7', '054a40628e78675329a0a573139ab1fc62f24a07929d56602dedca6b8b15a0a2', 4),
('imp-1e6d5d1750d3aa51', 'ga-xao-ca-chua', 349, 'Gà xào cà chua', 'Thịt đùi gà áp chảo vàng mềm om thấm sốt cà chua đỏ sánh đậm vị xì dầu, ăn kèm hành tây giòn ngọt cực hao cơm', 'Gà xào cà chua mang hương vị cơm nhà ấm cúng với từng miếng thịt đùi gà săn mềm mọng nước, thấm đẫm phần sốt cà chua chín nhừ đỏ au quyện xì dầu mặn ngọt dịu nhẹ và hành tây giòn thơm.', 'Trút gà xào cà chua ra đĩa sâu lòng, rưới đều nước sốt sánh lên trên cùng hành lá và tiêu đen xay; dùng nóng với cơm trắng hoặc bún tươi.', 'Bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa vừa khoảng 3–4 phút cho sốt sôi đều trở lại.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Cà chua","Đậm đà","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish","soybean","wheat"]', 408, 407.5, 1705, 33.7, 24.1, 5.7, 13.8, 2.7, 7.3, 1118, 2.8, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'aaa534a0854a57f9b3e281f066dfbb5a1ab909ccf8c045fe3bd9e7e1ad8448ee', '6ebf6906a5c23a7c5d4b27bba43a68fdc70d645e17c7648a8d763a1f3ed833ce', 4),
('imp-ce3c9df133ba1cd4', 'banh-trang-chien-trung', 350, 'Bánh tráng chiên trứng', 'Bánh tráng nướng chiên phồng giòn rụm phủ trứng gà béo mềm, hành lá, ruốc sấy và rau răm thơm nức', 'Bánh tráng chiên trứng là món ăn vặt đường phố Sài Gòn nổi tiếng nhờ sự kết hợp giữa miếng bánh tráng mỏng chiên phồng giòn rụm bên dưới và lớp trứng gà béo mềm bên trên, điểm thêm vị mặn thơm của ruốc sấy, hành phi, ớt hiểm và rau răm tươi.', 'Cắt bánh thành từng miếng tam giác vừa ăn khi còn nóng giòn, chấm kèm tương ớt cay ngọt và thưởng thức ngay lúc mới ra chảo.', 'Món ăn ngon nhất ngay khi vừa chiên xong để giữ độ giòn của bánh tráng; không nên cất tủ lạnh qua ngày vì hơi ẩm từ trứng sẽ làm bánh tráng bị dai cứng.', 'vietnamese', 'mon_chien', 'nam', 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Ăn vặt","Bánh tráng","Sài Gòn","Dưới 30 phút"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["crustaceans","egg","shrimp"]', 367, 367.3, 1537, 11.1, 16.4, 3.2, 44, 1.4, 2.6, 1002, 2.51, '["USDA / Asian Dried Shrimp Ref","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC Rice Paper Ref","USDA FDC Sriracha Ref","VN Rau Ram Ref"]', 'f8fa03bb80198ad18167b83ce5ce1fc270e8d63d5c1cf0a9c826696324c8b0c2', '8888d4ade4d1f7585109efdc6b6c62de6600e2295b7dd602b10a3f8652677ce0', 4),
('imp-1d4d9422e7f81e97', 'cua-hap-chanh-ot', 351, 'Cua thịt hấp chanh sả ớt', 'Cua biển thịt chắc hấp chín đỏ au cùng sả, gừng, hành tây thơm nồng, gỡ thịt ngọt mọng chấm muối tiêu chanh ớt', 'Cua thịt tươi sống được chà rửa sạch và hấp cách thủy cùng sả cây đập dập, hành tây, gừng và ớt hiểm giúp khử mùi bùn biển, giữ nguyên từng thớ thịt trắng muốt ngọt đậm quyện chén muối tiêu chanh ớt.', 'Bày cua hấp đỏ au ra mâm lớn cùng vài lát chanh tươi và rau răm thơm nồng; bóc mai gỡ thịt chấm muối tiêu chanh ớt ngay khi còn nóng.', 'Chỉ hấp và dùng cua tươi sống trong ngày. Nếu còn dư, gỡ sẵn thịt cua bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hấp nóng lại trước khi ăn.', 'vietnamese', 'mon_hap_luoc', 'nam', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Hải sản","Cua biển","Món Nam","Đãi tiệc"]', '["lunch","dinner"]', '["steam"]', '["crab","crustaceans"]', 202, 202.2, 846, 37.3, 2.3, 0.5, 6.7, 1.1, 2.5, 1411, 3.53, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN Rau Ram Ref"]', 'a070f49b50e179907a2466fd4e11284e009b5762ef46bdcdaa70bce0302cd71d', 'c2e739d6cd0a7fd914d1c709221e640c4ce105bb8226b048f6deeffbcf8a1aa0', 4),
('imp-d3972d88e860aba9', 'goi-muc-chanh', 352, 'Gỏi mực chanh ớt giòn ngọt', 'Mực ống tươi luộc gừng chín tới cắt khoanh giòn ngọt trộn cùng hành lá chần, rau răm và nước mắm chanh tỏi ớt chua cay mát lành', 'Gỏi mực chanh ớt là món khai vị hải sản thanh mát, nhanh gọn với từng khoanh mực ống trắng giòn ngọt tự nhiên không tanh, quyện hành lá chần dịu hăng, rau răm thơm nồng và nước trộn chanh tỏi ớt đậm vị chua cay hài hòa.', 'Bày gỏi mực ra đĩa, rắc vài lát ớt hiểm và rau răm lên trên; dọn ăn ngay kèm bánh phồng tôm hoặc bánh đa nướng giòn rụm.', 'Gỏi mực ngon nhất khi dùng ngay trong vòng 30 phút sau khi trộn để khoanh mực giữ độ giòn và không tiết nước; nếu chưa trộn, bọc kín mực luộc ráo và nước chấm riêng trong ngăn mát tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'trung', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi mực","Hải sản","Chanh ớt","Khai vị","Miền Trung"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["fish","molluscs","squid"]', 287, 287.4, 1203, 24.8, 2.4, 0.6, 41, 1.3, 10.2, 1645, 4.11, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN Banh Da Ref","VN Rau Ram Ref"]', '0b3db5508772ed50415456859cc22de71e35c13bb120724d112a498dc78be134', '44992233b8bf22c46a46c34e0ae2a6b0b29d161cdfa3963a2e337fa29ffd8eae', 4),
('imp-68184b07a3c61cff', 'cuon-nem-nuong-banh-trang', 353, 'Cuốn nem nướng bánh tráng chấm sốt nếp gan tôm', 'Nem thịt heo giò sống mỡ hạt lựu nướng thơm xiên sả, cuốn bánh tráng cùng rau sống, giá đỗ, dưa leo, đồ chua và chấm sốt nếp tôm thịt gan sánh bùi', 'Cuốn nem nướng bánh tráng đậm chất miền Trung với những xiên nem thịt heo giò sống lẫn mỡ hạt lựu nướng vàng ruộm thơm sả, cuốn gọn trong bánh tráng cùng rau sống, giá đỗ, dưa leo, đồ chua và chén sốt gạo nếp tôm thịt gan heo béo bùi khó cưỡng.', 'Bày nem nướng nóng ra đĩa cùng bánh tráng, rau sống, dưa leo, giá đỗ và đồ chua; múc sốt chấm ra chén rắc đậu phộng rang giã dập lên trên để cuốn và chấm nóng.', 'Nem đã nướng chín và sốt chấm bảo quản riêng trong hộp kín ngăn mát tối đa 2 ngày; khi ăn làm nóng nem trong nồi chiên không dầu 160°C trong 4 phút và hâm nóng lại chén sốt với chút nước lọc.', 'vietnamese', 'mon_cuon_nom', 'trung', 'medium', 45, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Nem nướng","Bánh tráng cuốn","Miền Trung","Nước chấm đặc biệt","Đãi tiệc"]', '["lunch","dinner"]', '["grill_roast","simmer","assemble"]', '["crustaceans","fish","molluscs","peanut","pork","shrimp","soybean","wheat"]', 653, 652.7, 2731, 30.6, 35.9, 11.3, 52.9, 3.3, 9.8, 1319, 3.3, '["Annatto Infused Oil Ref","NIN VN Gio Lua Ref","USDA FDC 167820","USDA FDC 167871","USDA FDC 167902","USDA FDC 168409","USDA FDC 168573","USDA FDC 168881","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169717","USDA FDC 169963","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 174277","USDA FDC 175179","USDA FDC Rice Paper Ref"]', '4e6c30b65cad8e34ef8d2dd92b15bbb1a3f70d2898b00c007683aaf170f18395', '7bc7dbebc5b029bb3ec79300ce16a0d70d933fbeb99a22cbaed7c485a4e635d3', 4),
('imp-ed9f34ecd475d031', 'bun-dau-mam-tom', 354, 'Bún đậu mắm tôm', 'Mẹt bún lá ép cắt miếng, đậu phụ chiên giòn nóng hổi, thịt ba chỉ luộc mềm, chả cốm thơm bùi chấm cùng bát mắm tôm đánh sủi bọt béo ngậy', 'Mẹt bún đậu mắm tôm đậm chất Hà thành quy tụ đủ hương vị từ đậu phụ mơ chiên vỏ giòn ruột béo, thịt ba chỉ luộc thái mỏng, chả cốm chiên thơm dẻo cùng bát mắm tôm pha quất, đường và dầu nóng đánh bông hấp dẫn.', 'Xếp bún lá cắt miếng, đậu phụ chiên vàng, chả cốm, thịt ba chỉ thái lát, dưa leo và rau tía tô, kinh giới, xà lách lên mẹt tre lót lá chuối, đặt bát mắm tôm đánh sủi bọt ở giữa để chấm ngập.', 'Món ngon nhất khi dùng ngay lúc đậu phụ và chả cốm còn nóng giòn; nếu dư thịt luộc hoặc đậu chiên, bảo quản ngăn mát tối đa 24 giờ và làm nóng đậu bằng nồi chiên không dầu ở 180°C trong 4 phút.', 'vietnamese', 'mon_bun_pho', 'bac', 'easy', 25, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Bún đậu mắm tôm","Hà Nội","Món mẹt","Ăn trưa"]', '["lunch","dinner"]', '["boil","deep_fry","assemble"]', '["crustaceans","pork","shrimp","soybean","sulphites"]', 938, 937.7, 3923, 36, 63.9, 19.9, 58.4, 5.4, 5.2, 1293, 3.23, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","NIN VN Gio Lua Ref","USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169231","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 171413","USDA FDC 172475","USDA FDC 173190","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647"]', '96be49bface0667d9580104d2d302cadd9e14c2c52ef03cfb4bbe49700750dea', '5cd9cba5d22ff33b4270ba59bb43856ec249157e79c7e689b27179be2effecbb', 4),
('imp-a744a977e7e4b165', 'hu-tieu-muc', 355, 'Hủ tiếu mực', 'Nước dùng ninh xương heo cùng tôm khô, khô mực nướng và củ cải trắng ngọt thanh trong veo, ăn kèm mực ống chần giòn sần sật và thịt heo băm xào thơm', 'Tô hủ tiếu mực Nam Bộ thanh nhẹ đầy đủ dinh dưỡng với nồi nước lèo trong vắt ngọt tự nhiên từ xương ống heo, củ cải trắng, tôm khô và khô mực nướng, kết hợp mực ống tươi giòn ngọt cùng thịt heo băm xào đậm đà.', 'Trụng hủ tiếu và giá đỗ cho vào tô, xếp mực ống khoanh, thịt băm xào, hẹ lá và cần tây lên trên, chan nước lèo sôi nóng và rắc hành tỏi phi vàng cùng tiêu xay và ớt thái lát.', 'Nước lèo và thịt băm bảo quản ngăn mát tối đa 2 ngày; mực ống tươi nên chần ngay trước khi ăn trong nước sôi để giữ độ giòn ngọt, không bị dai.', 'vietnamese', 'mon_bun_pho', 'nam', 'easy', 25, 60, 4, '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu mực","Hải sản","Nước dùng trong","Nam Bộ"]', '["breakfast","lunch","dinner"]', '["simmer","boil","stir_fry","assemble"]', '["celery","crustaceans","fish","molluscs","pork","shrimp","squid"]', 617, 616.6, 2581, 39, 21.7, 6.4, 65.4, 3.9, 8.1, 2081, 5.2, '["MEXT Surume Ref","NIN VN Fresh Pho Noodle Ref","Pork Bone Stock Extraction Ref","USDA / Asian Dried Shrimp Ref","USDA FDC 167902","USDA FDC 168452","USDA FDC 169230","USDA FDC 169963","USDA FDC 169988","USDA FDC 169994","USDA FDC 170000","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC Sucrose Ref"]', '10a365540f3d8c375d969159ed8b615b5084bf8186395b7ff8d3a614184e4830', '4999282a1292828f4a1b2931488b137646088fae26e90e9f0ddb3cf57fcac9f1', 4),
('imp-c67f536bef1c38d6', 'bap-cai-kho-nam-chay', 356, 'Bắp cải kho nấm đùi gà chay', 'Bắp cải kho mềm ngọt cùng nấm đùi gà, cà rốt và đậu phụ chiên thấm đượm nước tương sánh đậm bữa cơm ngày rằm', 'Món kho chay ấm áp đưa cơm với từng miếng bắp cải mềm ngọt mà vẫn giữ được thớ lá, hòa quyện nấm đùi gà giòn sần sật, cà rốt và đậu phụ chiên ngấm đẫm nước sốt tương sánh nhẹ thơm mùi hành boa-rô và tiêu xay.', 'Múc bắp cải kho nấm ra đĩa sâu lòng khi còn nóng, rưới phần nước kho sánh lên mặt rồi rắc hành lá và tiêu đen xay; dùng kèm cơm trắng nóng.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ 4–5 phút và thêm chút nước nếu cạn.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món kho","Bắp cải","Nấm đùi gà","Ngày rằm"]', '["lunch","dinner"]', '["braise"]', '["soybean","wheat"]', 239, 239.4, 1002, 12, 13, 2, 24, 6.4, 10.6, 1494, 3.73, '["USDA FDC 168580","USDA FDC 169246","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172472","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '43fab93218dc01021504e654d0141e3abeaebb34a7a6274fc61507f140afc2f1', '52a4bc8a9060a3b75028490dd3b3feb0c263c179611919f7a5ba0a29c6936ae6', 4),
('imp-35deaaa123c7470d', 'nom-gia-chua-cay', 357, 'Nộm giá đỗ chua cay chay', 'Giá đỗ chần sơ giòn sần sật trộn cùng cà rốt bào sợi, nước mắm chay chanh tỏi ớt chua cay và đậu phộng rang bùi béo', 'Đĩa nộm giá đỗ chua cay chay thanh mát chống ngán với từng cọng giá đỗ trắng mập giòn sần sật, cà rốt cam tươi bào sợi, quyện đều nước trộn nước mắm chay chanh tỏi ớt hài hòa, thơm dịu rau húng quế và bùi béo đậu phộng rang.', 'Bày nộm giá ra đĩa, rắc thêm đậu phộng rang giã dập và húng quế thái nhỏ lên trên; dùng ngay như món khai vị hoặc ăn kèm các món kho chay.', 'Món nộm ngon nhất ngay sau khi trộn để giữ độ giòn ráo; nếu chuẩn bị trước, nên tách riêng phần rau củ ráo nước và phần nước trộn, chỉ trộn đều ngay trước khi dọn bữa.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món nộm","Giá đỗ","Khai vị","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["peanut","soybean"]', 147, 147, 616, 6.9, 5.3, 0.7, 21.9, 4.2, 14.9, 816, 2.04, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 172232","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","Vegetarian Fish Sauce Ref"]', 'd1291fff8d6d03ec4023a82dea5f818a81a7af5be73cbefbdc457eb16bf5a7c2', 'ea10fad4f536d7827f22c2241b6eb39a061021f7980197c8f5408f05016df7c8', 4),
('imp-94b6bce7403fedc6', 'chao-nam-dau-phu', 358, 'Cháo nấm đậu phụ', 'Cháo gạo rang nấu mềm mịn quyện nấm đùi gà giòn ngọt, đậu phụ non béo thanh cùng gừng sợi và xì dầu dịu nhẹ', 'Tô cháo nấm đậu phụ thanh đạm dễ tiêu với hạt gạo tẻ kết hợp gạo nếp rang thơm sánh mịn, nấm đùi gà xào thơm giòn ngọt cùng đậu phụ trắng mềm béo, gừng tươi ấm bụng và hương xì dầu dịu nhẹ.', 'Múc cháo nóng ra tô, rắc hành lá, ngò rí, gừng thái sợi và tiêu đen xay; có thể chấm đậu phụ hoặc nêm thêm vài giọt xì dầu tùy khẩu vị.', 'Ngon nhất khi ăn nóng trong ngày. Nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, khi hâm nóng lại cần thêm chút nước sôi khuấy đều trên lửa nhỏ để cháo sánh mượt như mới.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 12, 28, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo chay","Nấm đùi gà","Đậu phụ","Thanh đạm","Dễ tiêu"]', '["breakfast","dinner"]', '["boil","simmer","stir_fry"]', '["soybean","wheat"]', 299, 299, 1251, 13.1, 7.6, 1.1, 46, 2.9, 2, 1035, 2.59, '["USDA FDC 168881","USDA FDC 169231","USDA FDC 169251","USDA FDC 169756","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'b4b4b61d4c4efe3c0476fde2667271a4b90586128bd78db878e5fbd8bebdadc1', 'e100e250074ded180108a3d871b7c1f7fb7dc44f62fd9dfda5f8d72df237e7ab', 4),
('imp-4f7a2cd919912ac9', 'mi-tron-trung-hanh', 359, 'Mì trộn trứng hành', 'Sợi mì dai săn trộn sốt xì dầu, dầu mè hành phi thơm nức, ăn kèm trứng chiên béo mềm và nhiều hành lá', 'Món mì trộn trứng hành siêu tốc chỉ trong 10 phút nhưng đậm đà khó cưỡng với từng sợi mì dai bóng không nát áo đều sốt xì dầu nước mắm, hương dầu hành phi thơm lừng, dầu mè béo nhẹ và trứng gà chiên vàng mềm.', 'Trộn đều mì nóng với nước sốt và dầu hành, xếp trứng chiên lên trên, rắc mè rang và tiêu xay rồi ăn nóng kèm tương ớt hoặc dưa leo thái lát.', 'Ngon nhất khi trộn và ăn ngay lúc mì còn nóng để sợi mì giữ độ dai săn, không bị trương nở.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 5, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Ăn nhanh","Dưới 20 phút","Sinh viên","Tiết kiệm"]', '["breakfast","lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["egg","fish","sesame","soybean","wheat"]', 485, 485.1, 2030, 17.2, 20.3, 3.9, 58.4, 3.2, 4.5, 1663, 4.16, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', '99c4f5d161f42b2fb0ff593a9672d6c7e423e2a01b226f0bf311476120c8fb53', 'c09e4b82495a82fb98f42e26a6a98a11c88784216cf3ed1cb281e0f93e2a1c7d', 4),
('imp-edac077a60dfa8b5', 'trung-kho-tra-trung-hoa', 360, 'Trứng gà kho trà vân đá ngũ vị', 'Trứng gà luộc lòng đào rạn vỏ ngâm ủ trong nước kho hoa hồi, quế thanh, nguyệt quế, tiêu Tứ Xuyên và xì dầu tạo hoa văn vân đá đẹp mắt', 'Món trứng kho vân đá truyền thống của ẩm thực đường phố Trung Hoa: những quả trứng gà luộc vừa chín tới được gõ rạn nhẹ lớp vỏ ngoài, rồi ngâm ủ trong nồi nước gia vị đậm hương hoa hồi, quế thanh, lá nguyệt quế, tiêu Tứ Xuyên và xì dầu cho ra đường vân đá nâu sẫm thơm bùi.', 'Bóc vỏ trứng kho vân đá, cắt đôi bày ăn kèm tô mì nước, cháo trắng hoặc dùng như món ăn vặt mặn thơm giàu đạm.', 'Giữ nguyên trứng chưa bóc vỏ ngâm trong nước kho ở ngăn mát tủ lạnh tối đa 4 ngày; dùng lạnh, ở nhiệt độ phòng hoặc hâm ấm nhẹ đều ngon.', 'chinese', 'mon_kho', NULL, 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Trứng kho trà","Vân đá","Ngũ vị","Ăn vặt","Trung Hoa"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["egg","soybean","wheat"]', 137, 136.7, 572, 11.6, 8.4, 2.8, 2.3, 0.2, 1.2, 878, 2.19, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","Spice Reference","USDA FDC 169231","USDA FDC 169655","USDA FDC 170917","USDA FDC 171287","USDA FDC 171316","USDA FDC 171320","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '12ba84fc176a5f79a5839ba435e28c719a0dbb9885f577397e749c9d7621a8bd', 'cd8ba3722cad50501036615d9a6cee44c3920c64e11a5923e092a413faab52b0', 4),
('imp-0efe9204d9dbdb3e', 'ga-chien-ot-kho', 361, 'Gà chiên giòn xóc ớt khô hoa tiêu Tứ Xuyên', 'Thịt đùi gà cắt miếng vừa ăn chiên giòn vàng rụm, đảo lửa nhỏ cùng ớt khô, hoa tiêu Tứ Xuyên, gừng tỏi và mè rang cay tê bùng nổ', 'Món Lạp Tử Kê trứ danh vùng Trùng Khánh – Tứ Xuyên: những miếng thịt đùi gà rút xương ướp gia vị chiên giòn rụm bên ngoài, mềm mọng bên trong, xóc thơm cùng ớt khô ngâm mềm, hoa tiêu Tứ Xuyên tê đầu lưỡi, gừng tỏi và mè trắng rang.', 'Trút gà chiên ớt khô ra đĩa rộng cùng toàn bộ gia vị thơm và dùng nóng ngay; thực khách gắp từng miếng gà giòn thơm trong đĩa ớt hấp dẫn.', 'Món ngon nhất khi dùng ngay lúc nóng giòn; nếu còn dư, bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu 4 phút ở 180°C.', 'chinese', 'mon_chien', NULL, 'medium', 25, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Gà chiên","Tứ Xuyên","Cay tê","Món nhậu","Giòn rụm"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["chicken","sesame","soybean","wheat"]', 316, 316.3, 1324, 23.2, 21.4, 4.7, 6.8, 1.7, 1.5, 573, 1.43, '["Shaoxing Wine Ref","Spice Reference","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170150","USDA FDC 170933","USDA FDC 171319","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277"]', '384d037ed1e66bae64db993d43f041234bbbaca8bd2e44be9e130e4c46414816', 'd477e3e4e5c8170dd82aa574cfb1ca72fb18becf0a46d600e1167d9eef128ef7', 4),
('imp-0a1f8e0bd042cbfd', 'ba-chi-xao-bap-cai', 362, 'Thịt ba chỉ xào bắp cải giòn kiểu Trung', 'Những lát ba chỉ mỏng áp chảo xém cạnh tươm mỡ, xào lửa lớn cùng bắp cải ngọt giòn, tỏi gừng, rượu Thiệu Hưng và dầu mè thơm lừng', 'Món xào dân dã cực kỳ đưa cơm của ẩm thực Trung Hoa: thịt ba chỉ thái lát mỏng áp chảo xém cạnh cho tiết bớt mỡ béo ngậy, dùng chính phần mỡ thơm đó xào lửa lớn với bắp cải trắng xé miếng giòn ngọt, rưới xì dầu nhạt quanh thành chảo dậy hương chảo nóng.', 'Trút thịt ba chỉ xào bắp cải ra đĩa lớn, dùng nóng ngay với cơm trắng dẻo khi bắp cải còn giữ độ giòn ngọt mọng nước.', 'Món ngon nhất khi ăn nóng ngay lúc vừa xào để bắp cải không bị mềm nhũn; bảo quản ngăn mát tối đa 24 giờ và đảo nóng nhanh 2 phút trên lửa lớn.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thịt ba chỉ","Bắp cải","Món xào","Đưa cơm","Trung Hoa"]', '["lunch","dinner"]', '["stir_fry"]', '["pork","sesame","soybean","wheat"]', 662, 661.8, 2769, 12.9, 62, 20.6, 13.2, 3.4, 6.3, 1582, 3.95, '["Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', 'edc888af37391d3a606f5bb96fb5f3f3c8b89fba7ec3d834351541aaa0850145', '2a3433af64513a48c4873dbaa5e85dc3b7adf9d204576aea214cc26933004ccc', 4),
('imp-ae6d3af49ade8384', 'cua-xao-gung-hanh', 363, 'Cua biển xào gừng hành kiểu Quảng Đông', 'Cua biển tươi chặt miếng chiên sơ khóa vị ngọt, xào nhanh cùng gừng lát, hành lá và sốt dầu hào sánh đậm chuẩn vị Quảng Đông', 'Món cua xào gừng hành kiểu Quảng Đông nổi bật với thịt cua săn ngọt, lớp vỏ thấm đẫm nước sốt dầu hào sánh nhẹ thơm nức mùi gừng phi, tỏi và hành lá tươi.', 'Dọn cua nóng ra đĩa sâu lòng, rưới hết phần sốt gừng hành lên mặt; thưởng thức ngay cùng cơm trắng nóng, chuẩn bị kẹp càng cua và khăn ướt.', 'Món hải sản ngon nhất khi dùng ngay trong bữa; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo lửa vừa với chút nước lọc.', 'chinese', 'mon_xao', NULL, 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món xào","Cua biển","Quảng Đông","Hải sản","Tiệc gia đình"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["crab","crustaceans","molluscs","sesame","soybean","wheat"]', 257, 256.6, 1074, 24.4, 11.9, 1.8, 11.3, 0.7, 1.9, 679, 1.7, '["Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277"]', '787b213b0bba2c4d41efb57a99d25f04049a966577f0911857d7c1fbe56358f7', '6e067df5cb5b30d7794d05ac0d87b94ff6635c26e94fb84cc91475da858b5d2e', 4),
('imp-122b920eba3f2e50', 'mi-xao-dau-phu', 364, 'Mì xào đậu phụ cải thảo kiểu Hoa', 'Sợi mì Udon dai mềm xào cùng đậu phụ áp chảo vàng giòn, cải thảo, cà rốt và sốt tương đen Hoisin đậm đà kiểu Trung Hoa', 'Đĩa mì xào đậu phụ kiểu Hoa hài hòa giữa sợi mì Udon mềm dai thấm đẫm sốt tương Hoisin sánh bóng, đậu phụ vàng ruộm bên ngoài béo mềm bên trong cùng cải thảo và cà rốt giòn ngọt.', 'Chia mì nóng ra đĩa, rắc thêm chút tiêu xay hoặc hành lá, có thể dọn kèm ít tương ớt nếu thích vị cay nhẹ.', 'Mì xào ngon nhất khi ăn nóng ngay sau khi nấu; nếu dư có thể bảo quản hộp kín trong ngăn mát 1 ngày và xào lại nhanh với 1 muỗng canh nước lọc.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Đậu phụ","Món chay","Nhanh gọn","Cải thảo"]', '["lunch","dinner"]', '["boil","pan_fry","stir_fry"]', '["sesame","soybean","wheat"]', 411, 410.6, 1717, 18.1, 17.8, 2.6, 46.3, 5, 8.3, 877, 2.19, '["MEXT Boiled/Fresh Udon","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 169977","USDA FDC 170005","USDA FDC 170393","USDA FDC 171028","USDA FDC 171370","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', '970936443e0d5419c3c731500b93aec739e6a176a3e1552121e75fc4590046d4', '25add1b9996b287d2a6e851fc2b491fa24b450cabf170e21428d33c72e062663', 4),
('imp-01ae566db4a7feab', 'sup-bo-nam-trung', 365, 'Súp thịt bò nấm đùi gà kiểu Hoa', 'Súp bò nấm thanh ngọt từ nước hầm bò cùng thịt thăn bò mềm mọng, nấm đùi gà giòn sần sật, gừng ấm và tiêu trắng dậy hương', 'Tô súp thịt bò nấm đùi gà kiểu Hoa ấm nóng với nước dùng trong ngọt thanh vị nấm và gừng, những lát thịt bò chín tới mềm ngọt quyện chút sánh mịn nhẹ dịu và hương dầu mè tiêu trắng.', 'Múc súp nóng ra tô sâu lòng, rắc hành lá tươi và thêm chút tiêu trắng xay; dùng làm món khai vị hoặc ăn kèm cơm trắng nóng.', 'Ngon nhất khi thưởng thức ngay lúc nóng để thịt bò không bị dai; phần súp dư bảo quản ngăn mát tối đa 24 giờ và đun sôi lăn tăn lại trên lửa nhỏ.', 'chinese', 'mon_canh', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món súp","Thịt bò","Nấm đùi gà","Thanh ngọt","Ấm bụng"]', '["lunch","dinner"]', '["simmer"]', '["beef","sesame","soybean","wheat"]', 281, 281.2, 1176, 28, 13.5, 4.9, 11.9, 2.2, 1.8, 1539, 3.85, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 170187","USDA FDC 170933","USDA FDC 171028","USDA FDC 171593","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'd73e1f4d5f99fb0007ce1d7705ed4224e17d386fd09cbc7807df50f79604dc1e', '6ccfad13d727887f71c5089388a6ce13c710f6d182ef9b787fe571e89a04523c', 4),
('imp-296dbce4d9098a2e', 'ca-nuong-tuong', 366, 'Cá chẽm nướng xì dầu hành gừng', 'Phi lê cá thịt trắng nướng giấy bạc mềm mọng thấm sốt xì dầu ngọt dịu, rưới dầu mè phi hành gừng tỏi thơm nức kiểu Trung Hoa', 'Những miếng phi lê cá chẽm trắng muốt, mềm mọng tự nhiên sau khi nướng kín giấy bạc cùng gừng hành và xì dầu nhạt, nổi bật với lớp dầu mè phi tỏi hành nóng hổi rưới lên mặt khi dọn.', 'Gắp cá nướng ra đĩa sâu lòng, chan phần nước sốt xì dầu trong khay cùng hành gừng phi dầu mè lên trên; ăn nóng kèm cơm trắng và rau cải luộc.', 'Bảo quản cá nướng trong hộp kín ở ngăn mát tủ lạnh tối đa 24 giờ; khi dùng hâm lại ở lò 160°C trong 6–8 phút hoặc hấp cách thủy 5 phút để thịt cá không bị khô.', 'chinese', 'mon_lau_tiec', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Phi lê cá","Xì dầu","Hành gừng","Bữa tối"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","sesame","soybean","wheat"]', 275, 274.7, 1150, 37.6, 10.8, 2.1, 5.5, 0.7, 2, 1236, 3.09, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175148"]', '73173933b7130ec909e6655046baa65d903b7d0cb0ecfd8703816f3ec0c8130a', 'd5fe46e9381fd47055e8af79b5feb3c996717910f04bbe528962909461c85ccf', 4),
('imp-0a43bfa1d02fa497', 'rau-bina-tron-toi', 367, 'Cải bó xôi trộn tỏi dầu mè', 'Cải bó xôi chần nhanh ngâm nước đá giữ màu xanh mướt, trộn tỏi băm, xì dầu nhạt, giấm đen Trấn Giang và mè trắng rang thanh mát', 'Món khai vị lạnh kiểu Trung Hoa thanh mát với từng cọng cải bó xôi xanh mướt giòn ngọt, quyện đều nước sốt chua mặn dịu từ giấm đen Trấn Giang, xì dầu, tỏi băm và dầu mè thơm lừng.', 'Bày rau trộn ra đĩa nông lòng, rắc hạt mè trắng rang lên trên; dùng mát như món khai vị hoặc ăn kèm các món kho, món chiên để giải ngấy.', 'Món trộn lạnh dùng ngon nhất trong ngày; nếu chưa ăn ngay, đậy kín bảo quản ngăn mát tối đa 12 giờ và trộn đều lại trước khi dọn.', 'chinese', 'mon_cuon_nom', NULL, 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn","Cải bó xôi","Khai vị","Thanh mát","Món chay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["sesame","soybean","wheat"]', 97, 97.2, 406, 4.7, 5.8, 0.8, 8.9, 3.2, 2.4, 793, 1.98, '["Chinkiang Black Vinegar Ref","USDA FDC 168462","USDA FDC 169230","USDA FDC 169655","USDA FDC 170150","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '0bc7e3cd6443b1da341a25e97d7699e93824fe163e0c2f1104cd6d2be9588a5b', '7e98c61d165844b4b863e5d900939aa37ad637c5b7771867e0d6bc35fe857839', 4),
('imp-329f0579ddc26919', 'ca-chua-tron-toi', 368, 'Cà chua trộn tỏi dầu mè kiểu Hoa', 'Cà chua chín đỏ chần lột vỏ thái múi cau, ướp lạnh thấm đẫm sốt tỏi băm, xì dầu nhạt, giấm gạo và dầu mè thanh mát giải ngấy', 'Món cà chua trộn lạnh thanh ngọt giải ngấy với từng múi cà chua bóc vỏ mềm mọng, thấm đượm vị chua ngọt dịu của giấm gạo đường cát, hòa quyện hương tỏi phi nhẹ, xì dầu và dầu mè thơm nồng.', 'Xếp cà chua ướp lạnh ra đĩa sâu lòng, rưới phần nước sốt dưới đáy tô lên mặt, rắc hành lá xanh và ngò rí; ăn lạnh làm món khai vị hoặc kèm các món chiên nướng.', 'Món ăn lạnh không cần hâm nóng; nên thưởng thức trong vòng 4–6 giờ sau khi ướp để cà chua giữ được độ tươi giòn, tránh để quá lâu ở nhiệt độ phòng.', 'chinese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn","Cà chua","Khai vị","Thanh mát","Món chay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["sesame","soybean","wheat"]', 123, 123.1, 515, 2.6, 7.9, 1.1, 12, 2.2, 7.5, 830, 2.08, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 171028","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'fdd73a1346c6970cc303a87d476fefc238bf4666324ef92c534b7dd1be21e22c', 'a0df65f866d26ff18f44aca79ae35869be8e4b8420d723107ad150539182f39e', 4),
('imp-59f5760d6349d284', 'nam-nhoi-thit-hap', 369, 'Nấm đùi gà nhồi thịt hấp xì dầu', 'Nấm đùi gà thớ chắc nhồi nhân thịt heo xay quết dẻo cùng trứng gà, hấp chín mọng ngọt rồi rưới sốt dầu hào xì dầu sánh bóng', 'Những miếng nấm đùi gà giòn ngọt tự nhiên ôm lấy phần nhân thịt heo xay mềm dẻo đậm hương gừng hành và dầu hào, hấp chín tới giữ trọn nước ngọt rồi phủ lớp sốt sánh bóng thơm mùi dầu mè.', 'Xếp nấm nhồi thịt ra đĩa nóng, rưới sốt dầu hào sánh mịn và rắc hành lá xanh thái nhỏ; dùng ngay cùng cơm trắng nóng.', 'Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn hấp cách thủy 5–7 phút cho nóng đều và giữ nguyên độ ẩm của nhân thịt.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Nấm đùi gà","Thịt băm","Khéo tay","Cơm nhà"]', '["lunch","dinner"]', '["steam","simmer"]', '["egg","molluscs","pork","sesame","soybean","wheat"]', 362, 361.9, 1514, 22.8, 23.9, 8.5, 14.2, 2.9, 4.3, 1054, 2.64, '["Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 168580","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'a894daa684785b91de51c6a01b4de176a4c4dadd24c12ea80e110825f03edbb1', '2a6ced45abecb9459f3d941c6f8809601f34f96a9daa8ad54faa914ee5fbd4b1', 4),
('imp-d8001a64eeaa9150', 'com-tron-trung-tan-nhat', 370, 'Cơm trộn trứng Nhật (Tamago Kake Gohan)', 'Cơm trắng hạt ngắn nóng bốc hơi trộn trứng gà tươi đánh quyện cùng xì dầu Nhật, cá bào Katsuobushi và rong biển Nori béo mịn chuẩn bữa sáng Nhật', 'Món cơm trộn trứng Tamago Kake Gohan trứ danh của Nhật Bản: hơi nóng từ cơm mới nấu làm trứng gà tươi tiệt trùng chín nhẹ thành lớp sốt kem vàng óng mịn màng, hòa quyện vị umami của xì dầu Nhật, cá bào Katsuobushi và rong biển Nori.', 'Trộn đều mạnh tay ngay khi cơm còn thật nóng cho đến khi trứng nổi bọt mịn bao quanh từng hạt cơm, rắc thêm hành lá và mè rang rồi ăn kèm dưa muối Nhật hoặc súp Miso.', 'Món ăn sử dụng trứng tươi đánh với cơm nóng nên phải thưởng thức ngay lập tức sau khi trộn; tuyệt đối không bảo quản lại hay để qua bữa.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 5, 5, 2, '/frigo/illustrations/delicious-meal.png', '["Tamago Kake Gohan","Cơm trộn trứng","Bữa sáng nhanh","Nhật Bản","Tối giản"]', '["breakfast","lunch"]', '["assemble","toss_mix"]', '["egg","fish","sesame","soybean","wheat"]', 342, 342, 1431, 15.1, 6.1, 1.7, 54.2, 1.4, 1.6, 721, 1.8, '["MEXT Hon-Mirin 16031","MEXT Katsuobushi 10099","USDA FDC 168456","USDA FDC 168878","USDA FDC 170005","USDA FDC 170150","USDA FDC 171287","USDA FDC 174277"]', '19afc6f619d217d355aeaf9aba798610f71ddc08ac43465453dbb12babde01e3', '2c9333f162aedf66e0cc8fbce6dc9c30375a9077ba1c4093fc0e3b6de110d151', 4),
('imp-e420d7a0eed8a0d6', 'tom-sot-cay-nhat', 371, 'Tôm sốt cay Nhật Bản (Ebi Chili)', 'Tôm tươi áp chảo giòn ngọt quyện sốt cà cay thơm nồng ấm từ tương ớt đậu bản Doubanjiang, tương cà, gừng tỏi và rượu Sake kiểu Yoshoku Nhật Bản', 'Món Ebi Chili trứ danh trong ẩm thực Nhật Bản: tôm tươi sơ chế sạch giòn sần sật được áp chảo nhanh tay giữ trọn độ ngọt, sau đó áo đều lớp sốt đỏ óng sánh mịn hòa quyện vị cay thơm lên men của Doubanjiang và vị chua ngọt dịu từ tương cà.', 'Múc tôm sốt cay ra đĩa nóng, rắc thêm phần lá xanh hành lá thái nhỏ; dùng kèm cơm trắng nóng hoặc mì xào rau củ đều rất bắt vị.', 'Món tôm ngon nhất khi ăn nóng ngay vừa nấu xong; nếu còn thừa, đậy kín bảo quản ngăn mát tối đa 2 ngày và hâm nhanh trên chảo lửa vừa với 1 muỗng canh nước lọc để tôm không bị dai.', 'japanese', 'mon_xao', NULL, 'medium', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Ebi Chili","Tôm sốt cay","Yoshoku","Nhật Bản","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 273, 273.1, 1143, 25.8, 10.3, 1.6, 18.4, 0.9, 7.4, 1343, 3.36, '["MEXT Sake 16021","Pixian Doubanjiang Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '8febca6b675e777d608a428b9181c75823b72952ffec8ffd3c7f1f56c70bf979', '55a79d3eb495badd92a4859e611604ab1e2d7abee9587df42e95766cd5d8109a', 4),
('imp-2138056075abd874', 'salad-dau-phu-dua-leo', 372, 'Salad đậu phụ dưa leo kiểu Nhật', 'Đậu phụ trắng ép ráo cắt khối mềm mịn trộn cùng dưa leo giòn mát, hành lá và sốt tương Miso trắng giấm gạo dầu ô liu mè rang thanh nhẹ', 'Món salad lạnh kiểu Nhật hài hòa kết cấu giữa đậu phụ trắng mềm béo đã ép ráo nước, dưa leo tươi giòn mát và lớp sốt trộn sánh thơm từ tương Miso trắng, giấm gạo, xì dầu Nhật, dầu ô liu và mè trắng rang.', 'Dọn salad đậu phụ dưa leo lạnh mát ra tô hoặc đĩa sâu lòng, rắc thêm hạt mè rang lên mặt; rất thích hợp dùng làm món khai vị hoặc món ăn kèm chống ngán cho các món chiên nướng.', 'Salad đậu phụ ngon nhất khi ăn trong ngày ngay sau khi làm lạnh 10 phút; nếu bảo quản qua đêm trong tủ lạnh, dưa leo có thể tiết nước làm loãng sốt.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 3, 3, '/frigo/illustrations/delicious-meal.png', '["Salad Nhật","Đậu phụ","Dưa leo","Thanh mát","Món chay nhẹ"]', '["lunch","dinner"]', '["toss_mix","assemble"]', '["sesame","soybean","wheat"]', 253, 252.6, 1057, 14.1, 18.5, 2.6, 11.5, 3, 4.2, 1034, 2.58, '["USDA FDC 168409","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 171413","USDA FDC 172238","USDA FDC 172446","USDA FDC 172475","USDA FDC 174277"]', '5d84a2afde3240c01848d79165385e4be1c53d792ac17a3a4d8b9752c69e47be', '6653ebb1cd0a86b1bb8865456cf75160a3835eb9daaa6e781241d95fa7170142', 4),
('imp-ff9fd0fdcdd85b79', 'bap-cai-nuong-bo', 373, 'Bắp cải áp chảo bơ xì dầu kiểu Nhật', 'Bắp cải tươi cắt miếng dày áp chảo xém cạnh ngọt thơm quyện bơ lạt tan chảy, tỏi lát, xì dầu Nhật và cá bào Katsuobushi chuẩn món nhắm Izakaya', 'Món bắp cải áp chảo bơ xì dầu đơn giản mà cuốn hút theo phong cách quán Izakaya Nhật Bản: từng miếng bắp cải được nướng xém vàng tự nhiên giữ trọn vị ngọt giòn, thấm đẫm hương béo thơm của bơ lạt quyện xì dầu Nhật và tỏi phi.', 'Dọn bắp cải áp chảo nóng hổi ra đĩa, rắc thêm hành lá xanh và ít cá bào khô Katsuobushi lên mặt; ăn kèm cơm nóng hoặc dùng làm món rau phụ cân bằng bữa tiệc nướng.', 'Món ăn ngon nhất khi thưởng thức nóng ngay sau khi chế biến lúc bơ còn thơm béo; nếu còn dư, bảo quản ngăn mát tối đa 1 ngày và áp chảo lại nhanh trên lửa vừa 2 phút trước khi ăn.', 'japanese', 'mon_xao', NULL, 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Izakaya","Bắp cải áp chảo","Bơ xì dầu","Món phụ Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["fish","milk","soybean","wheat"]', 128, 127.6, 534, 3.6, 9.7, 4.7, 8.3, 3.2, 3.8, 607, 1.52, '["MEXT Katsuobushi 10099","USDA FDC 169230","USDA FDC 169975","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277"]', '1ac81c8acee98823cc4ade2e7c9ef1361ece2d78a71a0041b494ce841442cfdf', '3c539a042caf9e7d85217bf31a2ef8a0677d150f04031e1d6d7e8837a94ab30c', 4),
('imp-d6e35b3fa19080de', 'trung-om-nam-nhat', 374, 'Trứng om nấm đùi gà kiểu Nhật', 'Nấm đùi gà om mềm trong nước dùng Dashi xì dầu Mirin thanh ngọt rồi phủ trứng gà đánh tan om chín mượt mà, ấm bụng cho bữa cơm nhẹ', 'Món trứng om nấm Tamago-toji kiểu gia đình Nhật với nấm đùi gà thái lát sần sật thấm đẫm nước dùng Dashi pha xì dầu nhạt, rượu Mirin và Sake, ôm trọn bởi lớp trứng gà đánh mịn chín mềm vừa tới.', 'Múc trứng om nấm ra tô cùng ít nước dùng thanh ngọt, rắc hành lá xanh và tiêu đen xay nếu thích; dùng nóng trực tiếp chan lên cơm trắng hoặc ăn kèm mì Udon.', 'Món trứng om ngon nhất khi thưởng thức nóng ngay sau khi nấu để giữ độ mềm mượt của trứng; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 1 ngày và hâm ấm nhẹ trên lửa nhỏ, tránh đun sôi làm trứng bị khô xác.', 'japanese', 'mon_kho', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Trứng gà","Nấm đùi gà","Nhanh gọn","Ấm bụng"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","fish","soybean","wheat"]', 165, 165.2, 691, 12.9, 7.3, 2.3, 11.3, 1.8, 6.1, 1019, 2.55, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168580","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171287","USDA FDC 173468","USDA FDC 174277"]', 'f14fae2f30afb6f5d41d546b6f26e25e48134445d4de727d13e337a0a8c12ea3', '568f6e647ed88e6e92ae8dbf2d4b7816900e5cdea02859b4f9a2bd82692230b6', 4),
('imp-cc88c6bd94df496e', 'canh-cua-nam-nhat', 375, 'Canh trong cua thịt nấm đùi gà kiểu Nhật', 'Nước dùng Dashi thanh trong nấu cùng thịt cua hấp gỡ sợi ngọt biển, nấm đùi gà lát mỏng, rượu Sake và hành lá kiểu Osuimono trang nhã', 'Món canh trong Osuimono trang nhã của Nhật Bản: nền nước dùng Dashi kết hợp vị ngọt thanh của nấm đùi gà và từng thớ thịt cua biển tươi ngọt, nêm nhẹ với xì dầu nhạt để giữ nước canh trong vắt mà đậm đà hương vị umami.', 'Múc canh nóng ra 3 bát có nắp hoặc tô sứ nhỏ, chia đều thịt cua và nấm đùi gà, rắc hành lá thái khoanh lên mặt; dùng làm món canh khai vị hoặc dùng kèm bữa cơm gia đình thanh nhẹ.', 'Canh ngon nhất khi thưởng thức nóng ngay sau khi nấu để giữ trọn mùi thơm và độ ngọt của thịt cua; nếu còn dư, đậy kín để ngăn mát tối đa 1 ngày và hâm nóng nhẹ lửa vừa đến khi vừa sôi lăn tăn.', 'japanese', 'mon_canh', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Canh trong Nhật","Thịt cua","Nấm đùi gà","Umami","Thanh đạm"]', '["lunch","dinner"]', '["simmer"]', '["crab","crustaceans","fish","soybean","wheat"]', 84, 84.4, 353, 14.4, 0.9, 0.2, 4, 1.3, 0.7, 904, 2.26, '["MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168580","USDA FDC 170005","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277"]', '75edfbb84128d835a1b87c525b1809e692445d8fb38890973bc502a69acafab1', '37d1e49dbeadf2dc35e07bd90b3ec945cfb7c70534e1e96b62e740bdb96870c9', 4),
('imp-df7a6429150724b1', 'tom-om-ca-chua-nhat', 376, 'Tôm om cà chua kiểu Nhật (Yoshoku)', 'Tôm tươi áp chảo săn ngọt om cùng cà chua chín nhừ, hành tây, tỏi thơm trong nước sốt xì dầu tương cà Sake đậm đà phong cách Yoshoku chan cơm', 'Món tôm om cà chua phong cách Yoshoku hiện đại của Nhật Bản: tôm tươi áp chảo nhanh tay giữ độ giòn ngọt, hòa quyện trong nước sốt cà chua tươi nấu nhừ cùng hành tây, tương cà, xì dầu Nhật và rượu Sake thơm lừng.', 'Múc tôm om cà chua ra đĩa sâu lòng khi còn nóng hổi, rắc hành lá xanh thái khoanh lên mặt; dùng chan trực tiếp lên cơm trắng nóng hổi.', 'Nên dùng hết trong ngày để tôm giữ được độ giòn ngọt; nếu bảo quản ngăn mát tối đa 2 ngày, tách riêng phần tôm hoặc hâm nhanh lửa vừa trong 2 phút cho vừa nóng tới.', 'japanese', 'mon_kho', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Yoshoku","Tôm tươi","Cà chua","Chan cơm"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["crustaceans","shrimp","soybean","wheat"]', 182, 181.7, 760, 22.2, 5.1, 0.8, 11.8, 2, 7, 825, 2.06, '["MEXT Sake 16021","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '0c92ea97488a5fe7a33d6652b34846c3c5f1af0057dbba40cfff235b9d027342', 'de17a798b71ef30441393d7f5f7dba4c48a1462a4a4a33ef703e520bf1203147', 4),
('imp-9157234945e6ff01', 'ga-ham-dak-jjim', 377, 'Gà hầm tương kiểu Andong (Andong Jjimdak)', 'Đùi gà hầm mềm quyện sốt tương đen Chunjang, dầu hào và siro ngô cùng miến khoai lang dai trong, khoai tây, cà rốt', 'Andong Jjimdak là món gà hầm nổi tiếng xuất xứ từ vùng Andong, Hàn Quốc. Thịt đùi gà được áp chảo săn rồi hầm cùng khoai tây, cà rốt, nấm đùi gà và miến khoai lang trong hỗn hợp sốt tương, dầu hào, siro ngô và chút tương đen Chunjang tạo màu nâu óng đậm vị mặn ngọt hài hòa.', 'Bày nguyên chảo hoặc múc gà, miến và rau củ ra đĩa sâu lòng, đặt dưa leo thái lát và hành lá thái sợi lên trên, rắc mè rang rồi ăn nóng kèm cơm trắng.', 'Gà và rau củ có thể bảo quản ngăn mát tủ lạnh tới 2 ngày (lưu ý miến để lâu sẽ hút hết sốt và nở mềm, nên thêm chút nước khi hâm trên lửa nhỏ).', 'korean', 'mon_kho', NULL, 'medium', 35, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Andong jjimdak","Gà hầm","Hàn Quốc","Miến Hàn","Đậm đà"]', '["lunch","dinner"]', '["braise"]', '["chicken","molluscs","sesame","soybean","wheat"]', 628, 628.3, 2630, 37.5, 27.1, 6.2, 59.9, 4.7, 19.1, 1721, 4.3, '["Korean Chunjang Ref","USDA FDC 168409","USDA FDC 168580","USDA FDC 168836","USDA FDC 168952","USDA FDC 169230","USDA FDC 169231","USDA FDC 170000","USDA FDC 170005","USDA FDC 170026","USDA FDC 170106","USDA FDC 170150","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '1582f187a40f70bebd7650e6bbe0622be01dcdb04d856937df72a18e0ca76a4f', '22e60653d287953d49c3bd3dd2a6d240a3ff6cc62fd9598eddba2075cbd66fd7', 4),
('imp-aedcf1c5c1d05d04', 'tom-xao-tuong-han', 378, 'Tôm xào sốt tương bơ tỏi kiểu Hàn', 'Tôm tươi săn giòn xào lửa lớn với bơ tỏi thơm ngậy, nước tương, rượu ngọt Mirin và hành lá xanh mướt', 'Tôm xào sốt tương bơ tỏi kiểu Hàn là món ăn đưa cơm nhanh gọn chỉ mất 20 phút. Tôm tươi bóc vỏ ướp nhẹ muối tiêu được xào nhanh trên chảo bơ tỏi thơm lừng rồi áo đều lớp sốt nước tương, rượu mirin và chút đường tạo độ bóng mặn ngọt hài hòa.', 'Trút tôm nóng ra đĩa, rắc thêm hạt mè trắng rang và hành lá; dùng ngay với cơm trắng nóng dẻo.', 'Tôm xào ngon nhất khi ăn ngay lúc vừa chế biến; nếu bảo quản ngăn mát tối đa 24 giờ, chỉ nên đảo ấm lại trên chảo trong 1 phút để tôm không bị khô dai.', 'korean', 'mon_xao', NULL, 'easy', 12, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm xào","Bơ tỏi","Hàn Quốc","Banchan","Món nhanh"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","milk","sesame","shrimp","soybean","wheat"]', 212, 212, 887, 20.2, 10.2, 3.1, 10.2, 1.1, 5.5, 783, 1.96, '["MEXT Hon-Mirin 16031","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '5fca005daf1c2f00542c62bb1e170aecb0c2013885b97cc1dba0d9e977e6dfa6', '76e11cec84031e27fbd2b8caf15b59d1b324d14ae34af731005a7957821a1bae', 4),
('imp-e39a1be406f9e1ea', 'trung-hap-han', 379, 'Trứng hấp xốp kiểu Hàn (Gyeran Jjim)', 'Trứng hấp bông xốp phồng cao mềm tan trong miệng, đậm vị nước mắm, nước tương và thơm lừng dầu mè hành lá', 'Gyeran Jjim là món trứng hấp nổi tiếng thường được phục vụ nóng hổi trong thố đất tại các quán thịt nướng Hàn Quốc. Bằng kỹ thuật khuấy nhẹ giữa chừng khi nấu trong nồi đáy dày hoặc nồi đất đậy nắp kín, trứng nở phồng bông xốp như bánh souffle nhưng vẫn giữ độ ẩm mềm mịn tan ngay đầu lưỡi.', 'Dọn nguyên thố hoặc nồi đất còn đang bốc hơi nghi ngút, rắc thêm hành lá, ớt bột Hàn và hạt mè rang; ăn nóng ngay kèm cơm trắng và thịt nướng.', 'Trứng hấp Gyeran Jjim ngon nhất khi thưởng thức ngay lúc vừa tắt bếp vì sẽ xẹp nhẹ khi nguội; nếu còn dư bảo quản ngăn mát tối đa 24 giờ.', 'korean', 'mon_hap_luoc', NULL, 'easy', 5, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Gyeran jjim","Trứng hấp","Hàn Quốc","Bông xốp","Món nhanh"]', '["breakfast","lunch","dinner"]', '["steam"]', '["egg","fish","sesame","soybean","wheat"]', 146, 145.6, 609, 10.1, 10.1, 2.7, 3.5, 0.7, 1.8, 529, 1.32, '["Korean Chili Flake Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277"]', '62f750f3590596be60da0d6a48da6ca9d233379acf240b0e0c65a77f8e393bef', 'c7b1bff8333d19ec81340ebaff34a379fb43bba4dcee12ac14decccdfc7e5c6a', 4),
('imp-da5a134e2654eeb5', 'dau-phu-tron-kimchi', 380, 'Đậu phụ luộc trộn kim chi xào kiểu Hàn (Dubu Kimchi)', 'Đậu phụ luộc mềm ấm xếp cạnh kim chi cải thảo xào sốt Gochujang cay đậm thơm mùi gừng tỏi và dầu mè', 'Đậu phụ trộn kim chi xào (Dubu Kimchi) là sự đối lập đầy tinh tế giữa những lát đậu phụ trắng luộc mềm mát, thanh vị với phần kim chi cải thảo xào nóng hổi đậm đà vị chua cay của tương ớt Gochujang, tỏi gừng và dầu mè rang. Đây vừa là món khai vị thanh nhẹ vừa là món nhậu truyền thống rất được yêu thích ở Hàn Quốc.', 'Xếp các lát đậu phụ quanh viền đĩa lớn, múc phần kim chi xào nóng vào giữa, rắc hành lá và mè rang lên trên; gắp một lát đậu phụ kẹp cùng kim chi thưởng thức.', 'Nên dùng ngay khi đậu phụ còn ấm mềm và kim chi còn nóng; nếu còn dư, tách riêng đậu phụ và kim chi xào bảo quản ngăn mát tối đa 24 giờ.', 'korean', 'mon_chay', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Dubu kimchi","Đậu phụ","Kim chi","Hàn Quốc","Khai vị"]', '["lunch","dinner"]', '["boil","stir_fry","assemble"]', '["sesame","soybean","wheat"]', 281, 281.1, 1176, 19, 17.3, 2.5, 17.9, 4.4, 9.1, 1046, 2.61, '["USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', 'b744f56a9f63bebf9ff60675a249fe5d01a3911b77666e1b93bd92d8ec67974b', '8e1d9227130e1e6e63932153b3fbd444d83c23915015c032f1f7e721ef320f75', 4),
('imp-8cd9bb1abdd63a9e', 'mi-lanh-naengmyeon', 381, 'Mì lạnh nước kiểu Hàn (Mul Naengmyeon)', 'Sợi mì kiều mạch dai giòn ngập trong nước dùng bò dăm đá chua ngọt thanh mát, ăn kèm thịt bò luộc, củ cải muối và trứng luộc', 'Mì lạnh Mul Naengmyeon là đặc sản giải nhiệt mùa hè trứ danh của ẩm thực Hàn Quốc. Sợi mì kiều mạch được luộc chín vừa rồi xả kỹ qua nước đá lạnh để đạt độ dai giòn sần sật, chan nước hầm thịt bò lọc sạch mỡ pha giấm đường và mù tạt vàng cay dịu lạnh buốt.', 'Xếp mì cuộn gọn vào tô lạnh, chan nước dùng dăm đá men theo thành tô, bày thịt bò thái lát, củ cải trộn, dưa leo và trứng luộc bổ đôi lên trên; ăn ngay khi còn lạnh.', 'Nước dùng bò đã nêm có thể giữ lạnh trong ngăn mát 2–3 ngày hoặc cấp đông trước để tạo lớp dăm đá; chỉ luộc mì ngay trước khi ăn để sợi mì không bị bở.', 'korean', 'mon_bun_pho', NULL, 'medium', 30, 60, 3, '/frigo/illustrations/delicious-meal.png', '["Naengmyeon","Mì lạnh","Hàn Quốc","Mùa hè","Thịt bò"]', '["lunch","dinner"]', '["boil","simmer","assemble"]', '["beef","buckwheat","egg","mustard","sesame","soybean","wheat"]', 617, 617.3, 2583, 33, 17.3, 6.1, 83.4, 5.3, 12.8, 1993, 4.98, '["Korean Chili Flake Ref","MEXT Dry Soba 01097","USDA FDC 168409","USDA FDC 168452","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170198","USDA FDC 171287","USDA FDC 172234","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'bc12a59c8c9e58159c685edb54512e3ef946b3fa492a8c5f438b1833ccffcf5f', 'e106f4760c65ae8d6a0ae7432790880dbec594cfb5e2d896f8fe47e2f09b8e53', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-a631650d667191b4', 'muc-nuong-cay-han', 382, 'Mực nướng sốt cay kiểu Hàn (Ojingeo Gui)', 'Mực tươi khứa caro ướp sốt Gochujang siro ngô cay ngọt, nướng xém cạnh thơm lừng cuốn lá tía tô và chanh tươi', 'Mực nướng cay Ojingeo Gui là món nhậu (anju) khoái khẩu tại các quán nướng Hàn Quốc. Thân mực tươi được chà muối sạch nhớt, khứa caro nông và ướp thấm sốt tương ớt Gochujang, ớt bột Hàn, siro ngô và chút mù tạt vàng, khi nướng trên lửa lớn chỉ 4–5 phút là mực săn giòn, áo lớp sốt đỏ bóng thơm nức.', 'Bày mực nướng lên đĩa lót lá tía tô thái sợi, rắc hành lá, mè trắng rang, rưới dầu mè và vắt chút nước cốt chanh vàng; cắt khoanh bằng kéo ngay trước khi ăn nóng.', 'Nên thưởng thức ngay lúc vừa nướng xong để giữ độ giòn ngọt của mực; mực đã ướp sốt có thể giữ lạnh tối đa 12 giờ trước khi nướng.', 'korean', 'mon_lau_tiec', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Ojingeo gui","Mực nướng","Hàn Quốc","Món nhậu","Cay ngọt"]', '["lunch","dinner"]', '["grill_roast"]', '["molluscs","mustard","sesame","soybean","squid","wheat"]', 300, 300.3, 1257, 24.6, 7.7, 1.4, 32.8, 2.6, 19.7, 879, 2.2, '["Korean Chili Flake Ref","MEXT Hon-Mirin 16031","MEXT Shiso Ref","USDA / Korean Gochujang Ref","USDA FDC 167746","USDA FDC 168836","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172234","USDA FDC 173468","USDA FDC 174223","USDA FDC 174277"]', 'bb16ee2f752c5a172fd3fb3ff5ec3e04e8327951152c347dd298c4c960606b62', '88cf0c248858ad1e1053f5e74cd5b89b4ced97f4e43fc3aaaa7586395665e9b4', 4),
('imp-2a958e709ba9cb7c', 'dau-phu-xao-kimchi', 383, 'Đậu phụ áp chảo kim chi xào cay (Dubu Kimchi)', 'Đậu phụ áp chảo vàng ruộm hai mặt ăn kèm kim chi xào cay đậm Gochujang thơm mùi tỏi phi và hành tây ngọt', 'Phiên bản đậu phụ áp chảo kim chi xào cay (Dubu Kimchi) mang đến kết cấu giòn nhẹ bên ngoài của từng miếng đậu phụ vàng ruộm, hòa quyện cùng đĩa kim chi cải thảo xào sốt Gochujang đỏ óng cay nồng, rất thích hợp ăn cùng cơm trắng nóng hoặc làm món nhắm cuối tuần.', 'Xếp đậu phụ áp chảo nóng cạnh phần kim chi xào, rắc hành lá và hạt mè trắng rang lên trên; dùng nóng cùng cơm trắng hoặc đồ uống lạnh.', 'Ngon nhất khi ăn nóng ngay để cảm nhận vỏ đậu phụ còn giòn; nếu còn dư bảo quản hộp kín ngăn mát tối đa 24 giờ và áp chảo ấm lại trước khi dùng.', 'korean', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Dubu kimchi","Đậu phụ","Kim chi xào","Hàn Quốc","Món nhậu"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["sesame","soybean","wheat"]', 251, 251, 1050, 15.1, 15.6, 2.3, 17.6, 4.5, 8.8, 1004, 2.51, '["Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', 'b4f5cf3281dd4724f8f8c334581ba727d8944427ac4e5060f06e712fb7c51818', '43259ad3705221db35076429a6d5790f7f8394722ef53e20852e16b717eb565a', 4),
('imp-1f3a7df71f4cbc77', 'suon-nuong-galbi', 384, 'Sườn bò nướng LA Galbi kiểu Hàn', 'Sườn bò cắt ngang ướp sốt tương hành tây, tỏi gừng, mật ong và dầu mè nướng than xém cạnh thơm lừng, ăn kèm ssamjang và rau cuốn', 'LA Galbi là món sườn bò cắt ngang xương nổi tiếng của Hàn Quốc, được ướp ngập trong hỗn hợp nước tương, mật ong, đường, rượu mirin, dầu mè và hành tây gừng tỏi xay mịn giúp từng thớ thịt mềm mọng và thấm vị đậm đà. Khi nướng trên vỉ than hoặc chảo gang nóng, dẻ sườn chín nhanh, viền thịt xém cạnh caramel thơm nức.', 'Dùng kéo cắt phần thịt sườn thành miếng vừa ăn ngay trên đĩa, cuốn cùng lá xà lách, lá tía tô, chấm sốt ssamjang pha sẵn hoặc ăn kèm cơm trắng và kim chi.', 'Sườn sống đã ướp có thể bảo quản ngăn mát tới 24 giờ hoặc cấp đông tới 1 tháng; sườn đã nướng bảo quản ngăn mát tối đa 2 ngày và hâm nhanh trên chảo nóng 2 phút.', 'korean', 'mon_lau_tiec', NULL, 'medium', 35, 15, 4, '/frigo/illustrations/delicious-meal.png', '["LA Galbi","Sườn bò nướng","Hàn Quốc","Tiệc nướng","Cuốn rau"]', '["lunch","dinner"]', '["grill_roast"]', '["beef","sesame","soybean","wheat"]', 465, 464.9, 1945, 27.4, 29.7, 11.2, 21.5, 2.3, 13.6, 1183, 2.96, '["Korean Doenjang Ref","MEXT Hon-Mirin 16031","MEXT Shiso Ref","USDA / Korean Gochujang Ref","USDA Beef Rib / Bone Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169247","USDA FDC 169640","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 173647","USDA FDC 174277"]', 'b3b86178009a0357f734f5d234c7ece272a7907836bf9e13c4d7aeb9cd6e3670', 'a5473f81b8e5a4ea7ee4e3e8c4dd1c82506e901e7b5e27ad0710f9aac0e796d5', 4),
('imp-328b6c9769e256eb', 'tom-nuong-muoi-ot-han', 385, 'Tôm nướng muối hạt kiểu Hàn (Saeu Sogeum Gui)', 'Tôm tươi nguyên vỏ nướng chín trên lớp muối biển hạt to thơm lừng, bóc vỏ chấm sốt Gochujang chanh mật ong cay chua hài hòa', 'Tôm nướng muối hạt (Saeu Sogeum Gui) là món ăn mùa thu rất được yêu thích tại Hàn Quốc nhờ cách chế biến mộc mạc giúp giữ trọn độ ngọt tự nhiên của tôm tươi. Tôm nguyên vỏ được nướng áp nhiệt gián tiếp trên lớp muối biển hạt to nóng già nên chín đều, vỏ giòn thơm mà thịt bên trong vẫn mọng nước, chấm kèm sốt tương ớt Gochujang pha chanh mật ong.', 'Gắp tôm nóng ra đĩa, gạt nhẹ hạt muối bám ngoài vỏ, rắc hành lá thái nhỏ và hạt mè trắng rang; bóc vỏ tại bàn và chấm ngập bát sốt Gochujang tỏi ớt chanh.', 'Món tôm nướng muối ngon nhất khi ăn nóng ngay tại bàn vì tôm để nguội sẽ bớt độ ngọt và dai; không khuyến khích bảo quản qua ngày.', 'korean', 'mon_lau_tiec', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng muối","Hàn Quốc","Món nhậu","Hải sản","Chấm Gochujang"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 207, 206.9, 866, 27.6, 4.6, 0.7, 14.9, 1.3, 8.3, 1073, 2.68, '["USDA / Korean Gochujang Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169640","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171028","USDA FDC 173468","USDA FDC 175179"]', '99d26f6363d9e612d6b2c157a4e52ae399972c62106d9c9320fcc3b91b8472b2', '5df66d2a83118752d3aaf7c6e92c9e53c239509c848fa3a94c33daf503818d0b', 4),
('imp-5dbb6aa38dae701d', 'mi-xao-kimchi-han', 386, 'Mì xào kim chi Hàn Quốc', 'Sợi mì ramen dai mềm xào cùng kim chi cải thảo chua cay đậm vị, quyện bơ tỏi thơm béo và trứng ốp la lòng đào hấp dẫn', 'Đĩa mì xào kim chi Hàn Quốc nóng hổi với sợi mì ramen săn bóng áo đều sốt tương ớt Gochujang cay nhẹ, vị chua thanh của kim chi lên men, chút béo ngậy từ bơ lạt và trứng ốp la đặt trên mặt.', 'Chia mì ra đĩa sâu lòng, đặt trứng ốp la lòng đào lên trên, rắc thêm hành lá và rong biển lá khô cắt sợi; dùng nóng ngay để sợi mì giữ độ dai ngon.', 'Món mì xào ngon nhất khi ăn ngay lúc vừa ra chảo; nếu còn dư có thể cất hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo với 1 muỗng canh nước lọc.', 'korean', 'mon_xao', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Kim chi","Hàn Quốc","Bữa tối nhanh","Trứng ốp la"]', '["lunch","dinner"]', '["boil","stir_fry","pan_fry"]', '["egg","milk","sesame","soybean","wheat"]', 514, 513.7, 2149, 18.3, 19.1, 5.8, 67.9, 4.8, 7.3, 1479, 3.7, '["USDA / Korean Gochujang Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 168456","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173430","USDA FDC 173647","USDA FDC 174277"]', '61f3ae98eed7914e232eac99aa2453a93368b3cd0eb7ca2d1fdd0486a1897419', '4fdc9845fdab8adeff8116f6150a1aec1195d9707e2e8136441cd37657a72db5', 4),
('imp-b7f8a716b25a7072', 'canh-bo-bap-cai-han', 387, 'Canh bò cải thảo Hàn Quốc', 'Nước canh thịt bò xào tỏi dầu mè trong veo ngọt thanh, nấu mềm cùng cải thảo tươi mát kiểu cơm nhà Hàn Quốc', 'Tô canh bò cải thảo Hàn Quốc ấm áp với nước dùng trong thanh ngọt tự nhiên từ thịt bò xào săn và rau cải thảo hầm mềm, điểm xuyết hương dầu mè và tỏi thơm dịu rất dễ ăn.', 'Múc canh nóng vào tô lớn, rắc chút hạt mè trắng rang lên trên; dọn ăn kèm cơm trắng nóng dẻo và một đĩa kim chi cải thảo.', 'Canh ngon nhất khi ăn nóng trong ngày; phần dư bảo quản ngăn mát tủ lạnh tối đa 2 ngày trong hộp kín và đun sôi lại trên lửa vừa trước khi dùng.', 'korean', 'mon_canh', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Cải thảo","Hàn Quốc","Thanh đạm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["beef","sesame","soybean","wheat"]', 166, 165.5, 693, 15.3, 9.7, 3, 4.8, 1.8, 1.7, 940, 2.35, '["USDA FDC 169230","USDA FDC 169977","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '684a1086ebcd521160c088c83a5ea97deb01ee3b2cd6d5dfa78ff2221af859e8', 'b60c1fb5e2f4003183ecdd70106e4716ca92bd28430506dd6972711b7b362598', 4),
('imp-7d38862afc164a8d', 'muc-hap-tuong-han', 388, 'Mực xào xì dầu Hàn Quốc', 'Khoanh mực tươi giòn ngọt xào lửa lớn cùng hành tây, ớt chuông và sốt xì dầu dầu hào mặn ngọt không cay', 'Món mực xào xì dầu Hàn Quốc (Ojingeo Ganjang-bokkeum) nổi bật với từng khoanh mực trắng giòn sần sật, thấm đẫm sốt xì dầu đặc và dầu hào ngọt mặn hài hòa cùng hành tây, ớt chuông giòn tươi.', 'Trút mực xào ra đĩa rộng, rắc thêm hạt mè trắng rang lên trên; dọn nóng ngay ăn kèm cơm trắng rất bắt vị, phù hợp cho cả trẻ nhỏ vì không cay.', 'Mực xào ngon nhất khi thưởng thức ngay sau khi nấu để giữ độ giòn ngọt; nếu bảo quản ngăn mát tối đa 24 giờ, chỉ đảo nóng nhanh trên chảo 1–2 phút tránh làm mực dai.', 'korean', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Mực tươi","Xì dầu","Hàn Quốc","Không cay"]', '["lunch","dinner"]', '["stir_fry"]', '["molluscs","sesame","soybean","squid","wheat"]', 348, 347.7, 1455, 29.2, 16.5, 2.7, 20.5, 2.1, 8.9, 1005, 2.51, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170150","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 174223"]', 'a9337c6bcc5cff3c7620e0f9a526eaae65b2fb04d245e6804e1203bc53cbfec5', 'e15a457bb5d30de285cb541a5f5505b3ff37efaeefffa06dbf08f3886cb3aacb', 4),
('imp-c78c4d4ca35484d3', 'com-nam-han', 389, 'Cơm nấu nấm Hàn Quốc', 'Gạo tẻ hạt ngắn dẻo thơm nấu cùng nấm đùi gà, bào ngư và kim châm trong nước dùng tảo bẹ, chan sốt xì dầu hành lá', 'Nồi cơm nấm Hàn Quốc (Beoseot-bap) tỏa hương thơm dịu tự nhiên nhờ gạo được rang sơ rồi nấu trực tiếp với nước dùng tảo bẹ Kombu cùng ba loại nấm ngọt giòn, ăn kèm chén sốt xì dầu hành lá thanh tao.', 'Xới nhẹ cho cơm tơi đều cùng các loại nấm, múc ra chén rồi rưới từng muỗng sốt xì dầu hành lá theo khẩu vị; ăn kèm kim chi hoặc rong biển cuộn.', 'Cơm nấm bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi hâm nóng hãy vẩy thêm 1 muỗng canh nước lọc rồi đậy nắp hấp hoặc quay lò vi sóng để hạt cơm mềm dẻo lại.', 'korean', 'mon_chay', NULL, 'easy', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Cơm nấm","Món chay","Hàn Quốc","Nấm tươi","Thanh đạm"]', '["lunch","dinner"]', '["boil","simmer"]', '["sesame","soybean","wheat"]', 458, 458.1, 1917, 10.9, 7.3, 1.1, 87.3, 4.3, 1.3, 505, 1.26, '["USDA FDC 168457","USDA FDC 168580","USDA FDC 169253","USDA FDC 169756","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', 'd80452e133c80da2d221a0a05e8933952f4faa10769fbbfdb587eb6dac07b852', '9ddb98ee95bf89970ec85c85da5a2cd682cb99074f3dfb226a78c37c40aca126', 4),
('imp-97c4b38c79bf9f39', 'canh-kimchi-tom', 390, 'Canh kim chi tôm đậu phụ Hàn Quốc', 'Nước canh kim chi chua cay nồng nàn hòa quyện vị ngọt tươi của tôm sú và đậu phụ non mềm mịn chuẩn vị Jjigae', 'Nồi canh kim chi tôm (Haemul Kimchi Jjigae) bốc khói nghi ngút với nước dùng cá cơm tảo bẹ đậm đà, vị chua dịu từ kim chi chín kỹ kết hợp cùng thịt tôm giòn ngọt và từng miếng đậu phụ non tan mềm.', 'Dọn nguyên nồi canh đang sôi lăn tăn hoặc múc ra tô đất giữ nhiệt, rắc hành lá xanh lên trên; thưởng thức nóng cùng cơm trắng dẻo.', 'Nếu còn dư, nên vớt riêng phần tôm để không bị dai, bảo quản phần nước canh và kim chi trong ngăn mát tối đa 2 ngày rồi đun sôi lại và thả tôm vào làm nóng nhanh.', 'korean', 'mon_canh', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Canh kim chi","Hải sản","Tôm tươi","Hàn Quốc","Cay ấm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["crustaceans","fish","sesame","shrimp","soybean","wheat"]', 223, 223.3, 935, 21.3, 8.3, 1.2, 17.4, 4, 6.5, 1723, 4.31, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 171028","USDA FDC 171413","USDA FDC 172476","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '8d6c0f32e46d0e9b040b90668d561535e94a237cb46a654ab2618e122e30bf47', 'ec7e4c25ed7c21185e182fd8572de393629385999776cac1ae10e08e40e6f812', 4),
('imp-b855b6ba4a9a3be8', 'tom-yum-tom-nam', 391, 'Canh Tom Yum tôm nấm kiểu Thái', 'Nước dùng đầu tôm ninh ngọt tự nhiên dậy hương sả, riềng, lá chanh Kaffir hòa quyện vị chua cay đậm đà cùng tôm tươi và nấm', 'Canh Tom Yum tôm nấm kiểu Thái trứ danh với nước dùng nấu trực tiếp từ gạch đầu tôm và vỏ tôm xào thơm, kết hợp bộ ba thảo mộc sả, riềng, lá chanh Kaffir cùng nấm đùi gà giòn ngọt và tôm tươi chín tới mọng thịt.', 'Múc canh Tom Yum nóng hổi ra tô sâu lòng, rắc hành lá và ngò gai; dùng nóng ăn kèm cơm trắng gạo thơm hoặc chan bún tươi.', 'Canh ngon nhất khi thưởng thức ngay lúc nóng để giữ hương thơm của chanh tươi; nếu dư, vớt bớt sả riềng rồi bảo quản ngăn mát tối đa 24 giờ, hâm nóng lại không đun sôi bùng quá lâu.', 'thai', 'mon_canh', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Tom Yum","Canh chua cay","Tôm tươi","Ẩm thực Thái","Hải sản"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 167, 166.7, 698, 20.6, 5.6, 0.9, 10.4, 2.1, 4.5, 1508, 3.77, '["Citrus Leaf Culinary Ref","Thai Tom Yum Paste Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN Culinary Herb Ref"]', '36626d90fdd3ee673a304dc4a8f36d59755a54c4e18fab175d6e5017b1d9ee93', 'b20c9f10defb46a67f1dd02c0e8528905f90ffed1754c03476f2b7b88988e4b2', 4),
('imp-2b514b564c702ff1', 'tom-nuong-chanh-ot', 392, 'Tôm nướng chanh ớt kiểu Thái', 'Xiên tôm sú tươi nướng lửa lớn chín mọng xém cạnh, áo sốt chanh tươi, nước mắm và ớt tỏi chua cay mặn ngọt đậm đà', 'Tôm nướng chanh ớt kiểu Thái mang hương vị biển tươi mát với từng con tôm sú chắc thịt nướng cháy cạnh thơm lừng, được phết đẫm lớp sốt chanh tươi, nước mắm, đường và ớt tỏi băm đậm vị ngay khi còn nóng.', 'Dọn xiên tôm nướng nóng hổi ra đĩa, rắc thêm hành lá; dùng làm món khai vị tiệc gia đình hoặc ăn kèm rau sống, dưa leo và cơm trắng.', 'Tôm nướng ngon nhất ngay khi vừa nhấc khỏi vỉ; nếu còn dư, gỡ xiên bảo quản hộp kín ngăn mát tối đa 24 giờ và làm nóng nhanh 2 phút bằng nồi chiên không dầu ở 170°C.', 'thai', 'mon_lau_tiec', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Chanh ớt","Ẩm thực Thái","Hải sản","Món tiệc"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","fish","shrimp"]', 207, 207.1, 867, 29.7, 6.3, 1, 9.1, 0.7, 6.2, 1528, 3.82, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 175179"]', '830ba8f43b79773724e783fdf219432c6834b434d61c84adc62894ac0ba7b7f1', '59d167a189cd8962b2c2157b4dd5c86b5d41381aea57c0b1cfc04a0b6b419fb8', 4),
('imp-119da2ec6738c17e', 'ga-hap-chanh-sa', 393, 'Gà hấp chanh sả kiểu Thái', 'Đùi gà ta ướp sả, riềng, lá chanh Kaffir và húng quế hấp mềm mọng nước, chấm nước mắm chanh tỏi ớt pha nước ngọt tiết từ đĩa hấp', 'Gà hấp chanh sả kiểu Thái thơm dịu và mọng ngọt với từng miếng thịt đùi gà ướp kỹ cùng sả, riềng, lá chanh Kaffir và rễ ngò xay nhuyễn, hấp chín mềm cùng lá húng quế Thái, chấm kèm nước mắm chanh tỏi ớt hòa chút nước ngọt gà hấp đậm đà.', 'Bày gà hấp nóng ra đĩa, rưới nhẹ ít nước hấp và rắc hành lá thái nhỏ lên mặt; chấm kèm chén nước chấm chanh tỏi ớt và dùng với cơm trắng nóng.', 'Gà hấp ngon nhất khi ăn nóng; nếu còn dư, bảo quản kín cùng phần nước hấp trong ngăn mát tối đa 48 giờ, hấp lại 6–8 phút cho nóng mềm.', 'thai', 'mon_hap_luoc', NULL, 'easy', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Gà hấp","Sả chanh","Ẩm thực Thái","Thanh đạm","Cơm gia đình"]', '["lunch","dinner"]', '["steam"]', '["chicken","fish","molluscs","soybean","wheat"]', 358, 357.7, 1497, 32.1, 16.5, 4.5, 20.5, 1.4, 9.3, 1263, 3.16, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 172185","USDA FDC 172232","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '98d09035df2de0005658be94bceeeae55a27b6794baaf18369857914b267ac7d', 'f9b77a983ab0069c8e1820a36f47d29884fbcebee432a045577ae71154a313bf', 4),
('imp-2fb85e79ab43b8bc', 'goi-bo-nuong-thai', 394, 'Gỏi bò nướng Nam Tok kiểu Thái', 'Thịt bò nướng chín tới thái lát mỏng trộn thính gạo rang thơm lừng, sả, hành tím, bạc hà và sốt mắm chanh ớt cay nồng', 'Gỏi bò nướng Nam Tok kiểu Thái đặc trưng với thịt thăn bò ướp vừa vị nướng xém cạnh, giữ trọn nước thịt ngọt mềm, trộn ngay cùng thính gạo rang (Khao Khua), sả thái mỏng, hành tím, lá bạc hà và nước trộn chanh ớt mắm đậm đà.', 'Trình bày gỏi bò Nam Tok ra đĩa, ăn ngay khi thịt còn ấm nhẹ kèm rau xà lách, dưa leo thái lát, xôi nếp hoặc cơm trắng.', 'Món gỏi thính gạo ngon nhất ngay sau khi trộn để thính thơm và rau không bị ỉu; phần thịt bò nướng có thể bọc kín giữ mát 24 giờ và chỉ trộn sốt trước khi ăn.', 'thai', 'mon_cuon_nom', NULL, 'medium', 35, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Nam Tok","Gỏi bò","Thính gạo","Ẩm thực Thái","Khai vị"]', '["lunch","dinner"]', '["grill_roast","toss_mix"]', '["beef","fish","molluscs","soybean","wheat"]', 338, 337.6, 1413, 26.8, 17, 5.5, 19.6, 2.1, 4.9, 1051, 2.63, '["Toasted Rice Powder Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172883","USDA FDC 173474","USDA FDC 174277"]', 'dd34f1439f6adefe716cf5480bf3ce6474d5d002b9f3b558753bbe2212530e1d', '5058b8764ac170e4fce7934ae90e7bb8826fd09ded3c0d3f06591b1f11db681e', 4),
('imp-3f14cf8e63967712', 'muc-xao-toi-ot-thai', 395, 'Mực xào tỏi ớt kiểu Thái', 'Khoanh mực tươi khía vảy rồng xào lửa lớn giòn sần sật, thấm đẫm sốt dầu hào tỏi ớt giã cối thơm nồng đậm vị biển', 'Mực xào tỏi ớt kiểu Thái ghi điểm với từng miếng mực tươi khía vảy rồng giòn sần sật, không ra nước, thấm đẫm hương thơm nồng nàn của tỏi ớt giã cối phi vàng và sốt dầu hào, nước mắm, xì dầu đặc đậm đà đưa cơm.', 'Trút mực xào nóng hổi ra đĩa, dùng ngay với cơm trắng nóng kèm vài lát dưa leo tươi và chanh cắt múi nếu thích.', 'Hải sản xào ngon nhất khi ăn ngay lúc vừa tắt bếp; phần dư bảo quản ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo nóng 1 phút.', 'thai', 'mon_xao', NULL, 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Mực xào","Tỏi ớt","Hải sản","Ẩm thực Thái","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["fish","molluscs","soybean","squid","wheat"]', 237, 236.6, 990, 21.8, 10.2, 1.7, 13.9, 0.7, 3.9, 1129, 2.82, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '25808177a85ff1b1f60db3c4e88fce852126c5e87513a5fdf2c65ca1aa16cbf7', 'ca2754ec720062086b8cebdd94858bebea81868ea9e8a117e95f32e4ab0edafc', 4),
('imp-244640181aff1fb6', 'nam-nuong-sa', 396, 'Nấm đùi gà nướng sả kiểu Thái', 'Khoanh nấm đùi gà khứa vằn ướp sả băm nhuyễn, hành tím, tương ớt và dầu hào chay nướng xém vàng đậm hương', 'Nấm đùi gà nướng sả kiểu Thái là món chay thơm nức với từng khoanh nấm giòn ngọt tự nhiên được luộc sơ khử hăng, khứa vảy rồng thấm đẫm sốt xì dầu, dầu hào chay, dầu mè và sả băm nhuyễn, nướng xém cạnh hấp dẫn.', 'Xếp nấm nướng sả nóng hổi ra đĩa, rắc mè rang và hành lá thái nhỏ lên mặt; ăn kèm cơm trắng nóng và rưới thêm nước sốt nướng trong khay.', 'Nên ăn ngay sau khi nướng để nấm giòn ngọt; phần dư bảo quản ngăn mát tối đa 24 giờ và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 3–4 phút.', 'thai', 'mon_chay', NULL, 'easy', 25, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Nấm đùi gà","Nấm nướng","Sả ớt","Ẩm thực Thái"]', '["lunch","dinner"]', '["grill_roast"]', '["sesame","soybean","wheat"]', 192, 191.6, 801, 6.2, 10.9, 1.6, 21.4, 4, 7.1, 825, 2.06, '["USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC Sriracha Ref","Vegan Mushroom Sauce Ref"]', '3ae24e8a87463313884e882dc6a4f8bbd276f2f776ee4c5f8669c68c85e12ea3', '2db91a6246cbb59298bc37a6942f11248a8518ed154f61b7bce859320d89f5f7', 4),
('imp-f494a9f384ce66a4', 'cua-xao-cay-thai', 397, 'Cua xào cay kiểu Thái', 'Thịt cua biển ngọt mềm xào nhanh cùng ớt hiểm, tỏi phi thơm, ớt chuông xanh và sốt dầu hào đậm đà vị biển', 'Cua xào cay kiểu Thái (Poo Pad Prik) nổi bật với thớ thịt cua tươi trắng ngọt tự nhiên quyện trong nước sốt dầu hào, xì dầu nhạt sánh nhẹ, dậy mùi tỏi phi, ớt hiểm cay nồng cùng vị giòn mát của ớt chuông xanh và hành lá.', 'Dọn nóng thịt cua xào cay ra đĩa, dùng ngay với cơm trắng nóng hổi hoặc bánh mì giòn chấm nước sốt đậm đà.', 'Thịt cua ngon nhất khi ăn ngay lúc vừa xào xong; phần dư bảo quản ngăn mát tối đa 24 giờ và làm nóng nhẹ trên chảo trong 1–2 phút.', 'thai', 'mon_xao', NULL, 'medium', 15, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Cua xào","Poo Pad Prik","Hải sản","Ẩm thực Thái","Cay nồng"]', '["lunch","dinner"]', '["stir_fry"]', '["crab","crustaceans","molluscs","soybean","wheat"]', 209, 209, 875, 19.8, 10.8, 1.7, 8.3, 1.2, 4.4, 901, 2.25, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172883","USDA FDC 174208","USDA FDC 174277"]', 'd734e0f4c6a668bd462eada9da044ca6ac32f655039d7a66aa89d0f96b1d90f7', '388e1a390f90f04b9e42fbaf6e0359b82b90a94f83124da3274c1dbf44db5fc5', 4),
('imp-0ec0d1db60dbdc1e', 'com-ga-khao-man-gai', 398, 'Cơm gà Khao Man Gai kiểu Thái', 'Gà ta luộc liu riu thịt ngọt mọng, cơm Jasmine xào mỡ gà nấu nước luộc thơm tỏi gừng ăn kèm sốt tương đậu lên men Taojiew', 'Cơm gà Khao Man Gai kiểu Thái chinh phục thực khách với từng hạt cơm gạo thơm dẻo bóng nhẹ mùi tỏi gừng và mỡ gà, thịt gà ta luộc chín tới da giòn thịt mọng ngọt, ăn kèm chén sốt tương đậu nành lên men gừng ớt đậm vị và bát nước dùng thanh ngọt.', 'Xới cơm nóng ra đĩa, xếp thịt gà chặt miếng vừa ăn và dưa leo thái lát bên cạnh; dọn kèm chén nước chấm tương đậu gừng ớt và bát nước dùng gà rắc ngò rí.', 'Nên bảo quản riêng cơm, thịt gà và nước chấm trong ngăn mát tối đa 48 giờ; hấp nóng lại cơm gà 5 phút trước khi ăn.', 'thai', 'mon_hap_luoc', NULL, 'medium', 25, 60, 4, '/frigo/illustrations/delicious-meal.png', '["Khao Man Gai","Cơm gà","Ẩm thực Thái","Nước chấm gừng","Bữa trưa"]', '["lunch","dinner"]', '["boil","simmer"]', '["chicken","soybean","wheat"]', 836, 836.2, 3499, 44.1, 32.7, 8.8, 88.5, 3.5, 8.8, 1348, 3.37, '["Dark Soy Sauce Label Ref","Korean Doenjang Ref","USDA FDC 168155","USDA FDC 168409","USDA FDC 168452","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169756","USDA FDC 169997","USDA FDC 170000","USDA FDC 170106","USDA FDC 170933","USDA FDC 171077","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'b0d5e99604694433b4de3a5b6daf6c3964a8dfe85f172691b88c85d92b4c667c', 'ff913a34184d4bfd9172a977d6f9473e4a6ffbcc024cc2977b782280f701a59d', 4),
('imp-4316659025be0f91', 'mi-xao-bo-cay-thai', 399, 'Mì xào bò cay kiểu Thái', 'Sợi hủ tiếu bản rộng áp chảo xém cạnh kiểu Pad Kee Mao cùng thịt bò mềm, cải rổ, cà rốt, ớt tỏi và lá húng quế Thái dậy mùi', 'Mì xào bò cay kiểu Thái (Pad Kee Mao) nổi bật với sợi hủ tiếu bản rộng dai mềm xém cạnh thơm mùi chảo lửa, thịt bò thăn mềm mọng đậm vị, hòa quyện vị cay nồng của tỏi ớt giã cùng mùi thơm đặc trưng không thể thiếu của lá húng quế Thái.', 'Gắp mì xào bò cay nóng hổi ra đĩa lớn, rắc thêm hành lá và thưởng thức ngay khi lá húng quế còn thơm nồng.', 'Mì xào lửa lớn ngon nhất khi dùng ngay; phần dư bảo quản ngăn mát tối đa 24 giờ và áp chảo nhanh lại trên lửa vừa với 1 muỗng canh nước.', 'thai', 'mon_xao', NULL, 'easy', 25, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Kee Mao","Mì xào","Thịt bò","Ẩm thực Thái","Cay nồng"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","fish","molluscs","soybean","wheat"]', 671, 671.3, 2809, 31.4, 24, 6.4, 80.3, 3.7, 10.3, 1328, 3.32, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169745","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170187","USDA FDC 170390","USDA FDC 170393","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277"]', 'b198a296dc013f32bf176af46cec1d81ebc4dcbc0aaeab28d808a12c7c0bb2d6', '87cdbf68b7a9073d868c0a0f1397505b764a555a709cf98cf0aa93bec659c852', 4),
('imp-0e30c82a4c77802e', 'goi-dau-phu-cay-thai', 400, 'Gỏi đậu phụ cay kiểu Thái', 'Đậu phụ non ướp lạnh mát mịn kết hợp sả, hành tím, dưa leo, rau thơm và nước sốt chanh đường thốt nốt cay nồng thanh mát', 'Gỏi đậu phụ cay kiểu Thái mang đến sự tương phản thú vị giữa từng khối đậu phụ non mềm mịn mát lạnh và lớp rau thơm băm nhuyễn giòn tươi gồm sả non, hành tím, dưa leo, bạc hà, ngò rí thấm đẫm nước sốt chanh ớt đường thốt nốt chua cay hài hòa.', 'Rắc mè đen rang thơm lên trên mặt đĩa gỏi đậu phụ, dọn dùng ngay khi đậu còn mát lạnh như món khai vị thanh nhẹ hoặc ăn kèm cơm trắng nóng.', 'Món gỏi đậu phụ non nên dùng hết ngay sau khi rưới sốt; nếu chuẩn bị trước, ướp lạnh riêng đậu phụ và chén rau củ trộn trong ngăn mát tối đa 6 giờ.', 'thai', 'mon_cuon_nom', NULL, 'easy', 20, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi đậu phụ","Món chay","Khai vị","Ẩm thực Thái","Thanh mát"]', '["lunch","dinner"]', '["toss_mix","assemble"]', '["sesame","soybean","wheat"]', 162, 162, 678, 10, 6, 0.9, 19, 2.2, 9.3, 849, 2.12, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170150","USDA FDC 170499","USDA FDC 172476","USDA FDC 173474","USDA FDC 174277","USDA FDC Palm Sugar Ref"]', '60e3247733175ec419adfcd2fc2d0b16836e00b9c99a14b44971cc835e604d72', 'cde071cc679e1033b1844bd5982b7681d96abb0271b4d2d22d34a56de24d53e0', 4),
('imp-d005aca18d138bfe', 'tom-xao-hung-que-thai', 401, 'Tôm xào húng quế kiểu Thái', 'Tôm tươi xào nhanh lửa lớn cùng tỏi ớt giã thơm nồng, sốt dầu hào đậm đà và lá húng quế Thái dậy vị Pad Krapao trứ danh', 'Tôm xào húng quế kiểu Thái (Pad Krapao Tôm) là món ăn đường phố cực kỳ bắt cơm với từng con tôm tươi săn giòn áo lớp sốt dầu hào, nước mắm sánh đậm, hòa cùng vị cay thơm nồng nàn của tỏi ớt giã và lá húng quế Thái đảo nhanh khi tắt bếp.', 'Trút tôm xào húng quế ra đĩa, rắc thêm hành lá và thưởng thức ngay với cơm trắng nóng hổi cùng một quả trứng ốp la lòng đào kiểu Thái.', 'Món xào tôm ngon nhất khi ăn nóng ngay; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh 1 phút trên chảo nóng.', 'thai', 'mon_xao', NULL, 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Tôm xào","Húng quế","Ẩm thực Thái","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 209, 208.7, 873, 20.4, 10.3, 1.5, 9.7, 1, 5.5, 1253, 3.13, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'ff28164d20178425241cf86b8e879a0fd6802c3694faa1104c29ac619e999b51', '93b0fa97f3ef47cccc2d4228f39d30378db9d4ef04bc84cbe6274e4e058a0066', 4),
('imp-a9710414682c8521', 'mi-xao-xi-dau-bo-thai', 402, 'Mì xào xì dầu bò kiểu Thái', 'Sợi mì trứng dai ngon xào xém cạnh kiểu Pad See Ew cùng thịt bò ướp mềm, trứng gà tơi, bắp cải giòn ngọt và sốt xì dầu đậm đà', 'Mì xào xì dầu bò kiểu Thái (Pad See Ew biến tấu với mì sợi trứng) hấp dẫn với từng sợi mì vàng nâu bóng mượt, hơi xém cạnh thơm mùi khói chảo, hòa quyện thịt bò thăn mềm ngọt, trứng gà tơi béo và bắp cải giòn giòn đậm vị xì dầu.', 'Gắp mì xào xì dầu bò nóng hổi ra đĩa, rắc thêm chút tiêu xay và hành lá; có thể ăn kèm vài lát ớt tươi hoặc giấm ớt ngâm kiểu Thái.', 'Món mì ngon nhất khi ăn nóng ngay sau khi xào; phần dư bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo chống dính khoảng 2 phút.', 'thai', 'mon_xao', NULL, 'easy', 25, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Pad See Ew","Mì xào","Thịt bò","Xì dầu","Ẩm thực Thái"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","egg","molluscs","soybean","wheat"]', 692, 692, 2896, 38, 25.8, 7.1, 76.4, 4.9, 10.2, 1455, 3.64, '["Dark Soy Sauce Label Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', '0e3052bb90f0b98e1fc693da7bd39bb5e9be6dd885a0d6ca5cb0605afdf0d472', '68e69f4714727d3f6cb8c8d6e348ace939981a534be2eda050545a3813e731c5', 4),
('imp-c64c83ef34771b5a', 'canh-nam-sa-thai', 403, 'Canh nấm sả Thái chay thanh vị', 'Canh nấm đùi gà và đậu phụ non nấu sả riềng lá chanh kiểu Thái, nước dùng trong thanh ngọt dịu và dậy mùi thảo mộc', 'Bát canh nấm sả Thái chay thanh mát lấy cảm hứng từ món Tom Yum nước trong, kết hợp nấm đùi gà giòn ngọt, đậu phụ non mềm mịn cùng hương thơm nồng nàn của sả, riềng tươi, lá chanh Thái và vị chua dịu tự nhiên từ cà chua, nước cốt chanh.', 'Múc canh nóng ra tô lớn, vớt bỏ phần sả riềng già cho dễ ăn, rắc thêm hành lá và ngò rí; dùng ngay làm món khai vị hoặc ăn kèm cơm trắng nóng.', 'Nên thưởng thức ngay khi vừa nấu xong để giữ trọn hương chanh tươi; nếu bảo quản tủ mát trong 24 giờ, đun sôi nhẹ lại phần nước canh và nấm rồi mới vắt thêm chanh.', 'thai', 'mon_canh', NULL, 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Canh chay","Nấm đùi gà","Thảo mộc Thái","Thanh nhẹ","Khai vị"]', '["lunch","dinner"]', '["simmer"]', '["soybean"]', 128, 127.6, 533, 7.3, 4.9, 0.7, 17.1, 3.8, 6.9, 1116, 2.79, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172476","USDA FDC 173647","Vegetarian Fish Sauce Ref","Vegetarian Seasoning Powder Ref"]', '66dfc88efc1d155757ef0fc3f2835cc070ef33373f7408bdac02f6edbad0c6dd', '5e89a0bc0e81e5495427b7aa13dd966e58c49bdcfea3c1cbfb64cded5d811ae9', 4),
('imp-a71f6ef791b463ea', 'goi-tom-sa-chanh', 404, 'Gỏi tôm sả chanh kiểu Thái', 'Tôm sú chần chín giòn ngọt trộn cùng sả non, hành tím, bạc hà và nước mắm chanh ớt cay nồng đặc trưng món gỏi Plaa Goong', 'Đĩa gỏi tôm sả chanh kiểu Thái mang hương vị tươi mát bùng nổ với thịt tôm sú chần vừa chín tới giòn sần sật, quyện cùng sả thái khoanh mỏng, ngò gai, lá bạc hà và sốt trộn chua cay mặn ngọt hài hòa.', 'Bày gỏi tôm ra đĩa sâu lòng, rắc thêm ngò gai và lá bạc hà tươi lên mặt; dùng ngay làm món khai vị hoặc ăn kèm xà lách và bánh phồng tôm giòn.', 'Gỏi tôm ngon nhất khi trộn và dùng hết trong vòng 30 phút để tôm giữ độ giòn và rau không ra nước; nếu chuẩn bị trước, nên bảo quản riêng tôm chần và nước sốt trong tủ mát tối đa 12 giờ.', 'thai', 'mon_cuon_nom', NULL, 'easy', 20, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi Thái","Tôm sú","Sả chanh","Khai vị","Chua cay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","shrimp"]', 191, 191.4, 801, 28.4, 1, 0.2, 19.3, 1.7, 9.7, 1263, 3.16, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 172185","USDA FDC 173474","USDA FDC 175179","USDA FDC Sriracha Ref","VN Culinary Herb Ref"]', '696a79bd6f35ce2fee46fc0f307b86b6714fc0b676fcc3eaee6a5b3b76971e04', '6da0457ffafe2201986fe697431d5586d126a62910db5ecf50151926224b2a61', 4),
('imp-9236740e2b55e8a1', 'com-chien-ga-thai', 405, 'Cơm chiên gà kiểu Thái (Khao Pad Gai)', 'Cơm rang tơi hạt cùng thịt đùi gà mềm ngọt, trứng gà, xì dầu Thái và nước mắm ớt Prik Nam Pla đậm vị đường phố Bangkok', 'Cơm chiên gà Thái (Khao Pad Gai) chinh phục vị giác nhờ từng hạt cơm dẻo tơi săn cạnh, thịt đùi gà áp chảo mềm ngọt quyện trứng gà béo bùi, dậy mùi thơm đặc trưng của xì dầu nhạt, tiêu trắng và chén nước mắm ớt chanh ăn kèm.', 'Ép cơm chiên vào chén rồi úp ra đĩa, rắc thêm ngò rí và tiêu trắng xay; dọn nóng kèm dưa leo thái lát, múi chanh tươi và chén nước mắm ớt Prik Nam Pla.', 'Ngon nhất khi ăn nóng ngay lúc vừa rang xong; nếu còn dư, đậy kín bảo quản tủ mát tối đa 24 giờ và đảo nhanh trên chảo nóng với 1 muỗng cà phê nước lọc cho hạt cơm mềm tơi trở lại.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Khao Pad","Cơm chiên","Thịt gà","Đường phố Thái","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","egg","fish","soybean","wheat"]', 506, 506.3, 2119, 26.6, 19.5, 4.6, 55, 2.5, 6, 1677, 4.19, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 174277"]', '0d937e3c06be24885a8d4ad425fffafdd9db337e31bb915a035c32462b80b102', 'bd0c13c0212369d00b87afd2d74c788772867d5fa27934cc58db91e015e2c524', 4),
('imp-a1904f60d9f4f10e', 'mi-y-bo-toi', 406, 'Mì Ý sốt bơ tỏi (Burro e Aglio)', 'Sợi mì Spaghetti dai vừa quyện sốt nhũ hóa từ bơ lạt béo thơm, tỏi phi lát mỏng và phô mai Parmesan bào mịn', 'Món mì Ý bơ tỏi tối giản mà tinh tế với từng sợi Spaghetti dai mượt bao phủ bởi lớp sốt nhũ hóa óng ả từ bơ lạt, nước luộc mì giàu tinh bột, tỏi phi lát vàng dịu và phô mai Parmesan.', 'Chia mì ra đĩa sâu lòng ngay khi vừa tắt bếp, rắc thêm phô mai Parmesan bào và ngò tây tươi thái nhỏ; ăn nóng để cảm nhận trọn vị béo mịn.', 'Món này ngon nhất khi thưởng thức ngay lúc còn nóng; nếu còn dư có thể cất ngăn mát tối đa 24 giờ và áp chảo lại cùng chút nước ấm hoặc bơ lạt.', 'italian', 'mon_bun_pho', NULL, 'easy', 8, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý bơ tỏi","Ẩm thực Ý","Nhanh gọn","Spaghetti","Món chính"]', '["lunch","dinner"]', '["boil","pan_fry"]', '["milk","wheat"]', 603, 602.5, 2520, 18.4, 23.9, 14.3, 78.2, 3.7, 2.9, 777, 1.94, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171319","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', '9a44f796e208519a3d8b62f70881c7ee366e8e7681f29a65f8a83e9f75871dd8', '645c84f12179a5302b97c69dc602cbb972c31991b36bf905e692fa3d05d5e70a', 4),
('imp-cc5f58548e934d9e', 'mi-y-tom-toi-ot', 407, 'Mì Ý tôm tỏi ớt (Aglio Olio)', 'Sợi mì Ý thấm đẫm sốt dầu ô liu bơ tỏi ớt cay nhẹ quyện thịt tôm tươi ngọt giòn và hương vỏ chanh vàng thanh mát', 'Món mì Ý hải sản tinh tế với tôm tươi xào săn ngọt thịt, sợi mì dai mềm quyện sốt dầu ô liu bơ thơm nức mùi tỏi phi, chút cay nồng của ớt tươi và vị tươi mát từ vỏ chanh vàng bào.', 'Dọn nóng ngay ra đĩa sâu lòng, rắc thêm ngò tây băm nhỏ và chút phô mai Parmesan bào nếu thích.', 'Món mì sốt dầu hải sản ngon nhất khi ăn nóng ngay; nếu cần bảo quản, cất hộp kín ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo với chút nước ấm.', 'italian', 'mon_bun_pho', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý tôm","Aglio Olio","Ẩm thực Ý","Hải sản","Cay nhẹ"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","milk","shrimp","wheat"]', 633, 633.2, 2650, 34.3, 26.4, 9.1, 64.7, 3.1, 2.5, 624, 1.56, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '3f2f377cd7fea7646eae08c84647dcd7c7c7a08b554d463408ea4b311d73ced4', '4893eaeeecfa2dbbc68228ff9ca9bb810f97241ff8b9a1b3c5c32fc0230e2392', 4),
('imp-8fdcddab058d5f65', 'mi-y-sot-ca-chua-tuoi', 408, 'Mì Ý sốt cà chua tươi (Pomodoro)', 'Sợi mì Spaghetti al dente quyện sốt cà chua tươi nấu nhanh giữ trọn vị ngọt thanh cùng húng quế Tây thơm mát', 'Đĩa mì Ý sốt cà chua tươi Pomodoro thanh vị với cà chua chín mọng nấu nhanh cùng tỏi phi dầu ô liu, thêm chút cà chua cô đặc tạo màu đỏ au đẹp mắt và hương thơm dịu của lá húng quế Tây.', 'Dọn mì nóng ra đĩa sâu lòng, rắc lá húng quế Tây xé nhỏ và thêm ít phô mai Parmesan bào mịn tùy khẩu vị.', 'Món mì sốt cà chua tươi ngon nhất khi dùng ngay lúc nóng; phần sốt nấu dư có thể bảo quản ngăn mát 2 ngày và hâm nóng lại với ít nước trước khi trộn mì.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý Pomodoro","Cà chua tươi","Ẩm thực Ý","Nhanh gọn","Món chính"]', '["lunch","dinner"]', '["boil","simmer"]', '["milk","wheat"]', 486, 486.2, 2034, 16.2, 14.7, 3.2, 72.6, 4.8, 6.5, 956, 2.39, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170457","USDA FDC 170460","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647"]', 'bce6a9b293974e2c8a080c44320e973a2adbc952970502ef95fc89cfb058aca3', '31e287d274df6ccc5f3558a3ead27a7b702c23078f04f03dcbce3c9e7f017ec6', 4),
('imp-d4d1de72f13e8f30', 'lasagna-bo-bam', 409, 'Lasagna bò bằm nướng sốt Béchamel', 'Từng lớp lá mì Lasagna xen kẽ sốt bò bằm Ragù ninh chậm đậm đà, sốt sữa trắng Béchamel béo mịn và phô mai Parmesan nướng vàng', 'Món Lasagna truyền thống vùng Bologna với 5 tầng lá mì mềm dẻo ôm trọn phần sốt thịt bò bằm và thịt xông khói ninh chậm cùng cà chua, cân bằng bởi sốt sữa trắng Béchamel thơm mùi nhục đậu khấu và lớp phô mai Parmesan nướng vàng giòn.', 'Để khay Lasagna nghỉ 10 phút sau khi ra lò rồi cắt thành từng phần vuông vức; dùng nóng kèm salad rau xanh trộn giấm thanh mát.', 'Có thể bảo quản ngăn mát tối đa 3 ngày hoặc cấp đông từng phần tối đa 1 tháng; khi ăn phủ giấy bạc hâm nóng ở 180°C khoảng 15–20 phút.', 'italian', 'mon_lau_tiec', NULL, 'hard', 30, 120, 6, '/frigo/illustrations/delicious-meal.png', '["Lasagna","Bò bằm","Ẩm thực Ý","Nướng lò","Tiệc cuối tuần"]', '["lunch","dinner"]', '["simmer","assemble","grill_roast"]', '["beef","celery","milk","pork","sulphites","wheat"]', 713, 712.9, 2983, 35.8, 42.6, 17.8, 45.1, 3.5, 11.3, 1442, 3.61, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169072","USDA FDC 169761","USDA FDC 169988","USDA FDC 170000","USDA FDC 170393","USDA FDC 170460","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171326","USDA FDC 171413","USDA FDC 171595","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174036"]', '7890e4ac36ba2c6fcfe12f9d67f9c2b44cd69f5a813517dcb64a279f24655341', '6191d81864915d41da97b8b632b91b96fd14f14a40bb0d598055ff302259acbb', 4),
('imp-3fd9eb5a7c40c3c0', 'risotto-ga-hanh', 410, 'Risotto gà hành kiểu Ý', 'Hạt gạo Arborio dẻo béo nấu chậm cùng nước dùng gà nóng, ức gà áp chảo vàng mềm, bơ lạt và phô mai Parmesan sánh mượt', 'Đĩa cơm Ý Risotto béo mịn chuẩn vị với từng hạt gạo Arborio mềm dẻo bên ngoài nhưng vẫn giữ lõi sần nhẹ bên trong, quyện thịt ức gà ngọt mềm, hành tây thơm dịu, bơ lạt và phô mai Parmesan.', 'Múc cơm Risotto nóng ra đĩa sâu lòng, rắc ngò tây băm nhỏ và thêm ít phô mai Parmesan bào lên trên; thưởng thức ngay khi cơm còn sánh chảy nhẹ.', 'Món Risotto ngon nhất khi ăn nóng ngay sau khi hoàn thiện; nếu còn dư có thể bảo quản ngăn mát tối đa 2 ngày và hâm nóng trên chảo với chút nước dùng gà hoặc nước ấm.', 'italian', 'mon_lau_tiec', NULL, 'medium', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Risotto","Ẩm thực Ý","Ức gà","Gạo Ý","Món chính"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["chicken","milk","sulphites"]', 638, 637.5, 2667, 31.5, 23.6, 10.4, 70.2, 1.7, 2.9, 1400, 3.5, '["USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 172883","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC Arborio Rice Ref"]', '02ec2d8872cdad073a144ed0313ef0c85bd3638246be0818538a1241f12ea6d8', '200c94fce3a5995aa69f8a44440463b20249aca1aea073f3551633b0111cc9e4', 4),
('imp-4c5955ef4919d61a', 'mi-y-cua-ot', 411, 'Mì Ý thịt cua tỏi ớt chanh vàng', 'Sợi mì Spaghetti quyện thịt cua biển ngọt thanh, dầu ô liu phi tỏi ớt thơm nồng và hương vỏ chanh vàng tươi mát', 'Món mì Ý hải sản tinh tế với từng thớ thịt cua biển ngọt tự nhiên hòa quyện sốt nhũ hóa trắng sánh từ dầu ô liu phi thơm tỏi ớt và nước luộc mì, điểm nhấn bởi hương thơm tươi mát của vỏ chanh vàng và ngò tây.', 'Chia mì ra 4 đĩa sâu lòng khi còn nóng hổi, rắc thêm ngò tây băm và một vòng nhỏ dầu ô liu nguyên chất; tránh dùng phô mai để giữ trọn vị ngọt thanh của thịt cua.', 'Mì hải sản ngon nhất khi ăn ngay lúc nóng; nếu còn thừa bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo với ít nước ấm.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Ý cua","Hải sản","Ẩm thực Ý","Cay nhẹ","Bữa tối"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["crab","crustaceans","wheat"]', 486, 485.6, 2032, 23.3, 12.3, 1.8, 68.9, 3.3, 2.8, 627, 1.57, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208"]', '9931a9d5aede0d95dd9a459bdf38c48ea289e099129c04014a41215856a9df15', 'a5cfa01b1d72407c37dade79ab327252725d6d62f29c5bd49aa42c239516770b', 4),
('imp-c398c169dc196c4e', 'tom-nuong-toi-chanh-y', 412, 'Tôm nướng tỏi chanh vàng kiểu Ý', 'Tôm tươi nguyên vỏ ướp dầu ô liu, tỏi băm, chanh vàng và ngò tây nướng chín tới giữ trọn độ giòn ngọt mọng nước', 'Món khai vị hải sản kiểu Ý đầy cuốn hút với những con tôm tươi nguyên vỏ nướng nhanh trên lửa lớn, thịt tôm chắc ngọt thơm lừng hương dầu ô liu, tỏi băm, vỏ chanh vàng và ngò tây tươi.', 'Dọn nóng ngay ra đĩa, rưới thêm phần nước sốt dầu tỏi chanh sạch lên trên, rắc ngò tây băm và bày kèm vài múi chanh vàng để vắt thêm.', 'Món tôm nướng ngon nhất khi thưởng thức nóng ngay sau khi nướng; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và làm ấm lại nhanh trong lò 170°C khoảng 3–4 phút.', 'italian', 'mon_lau_tiec', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Ẩm thực Ý","Chanh vàng","Khai vị","Hải sản"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","shrimp"]', 278, 277.8, 1163, 32.1, 15.5, 2.2, 4.4, 1.1, 0.8, 771, 1.93, '["USDA FDC 167746","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 175179"]', '8cbc45ccac28adaf3dee1907555bd81e9da69d1c10f41ceca52b8c1d3abbfcd5', '4b08b02f32633da516f00f24591e5c1d7782d8ecaf69245fe0548456e33fef30', 4),
('imp-8fcc592ab7250a38', 'bap-cai-om-ca-chua-y', 413, 'Bắp cải om cà chua kiểu Ý', 'Bắp cải thái sợi om chậm trong sốt cà chua sánh dịu quyện vị ngọt của hành tây, tỏi thơm và dầu ô liu béo nhẹ', 'Món rau om dân dã vùng Bắc Ý với từng sợi bắp cải chín mềm ngọt lịm, thấm đều nước sốt cà chua đỏ au quyện hương dầu ô liu, hành tây và tỏi phi dịu nhẹ.', 'Múc nóng ra đĩa sâu lòng để dùng làm món ăn kèm cho các món thịt nướng, xúc xích hoặc chấm trực tiếp với bánh mì giòn.', 'Món bắp cải om để qua đêm trong ngăn mát tối đa 2 ngày càng thấm đẫm gia vị; khi ăn hâm nóng lại trên chảo với lửa vừa khoảng 5 phút.', 'italian', 'mon_chay', NULL, 'easy', 12, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Bắp cải om","Món chay","Ẩm thực Ý","Món phụ","Thanh đạm"]', '["lunch","dinner"]', '["braise","simmer"]', '[]', 170, 169.9, 712, 4, 10.2, 1.4, 19.1, 6.3, 10.2, 770, 1.92, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 169975","USDA FDC 170000","USDA FDC 170931","USDA FDC 171413","USDA FDC 171595","USDA FDC 173468"]', '9179b1db2d1a94f1aee49d808e6df9afe9748352498601cbe8961ec22db0cea9', '71df3d86ef60f3f59aa0a2139c1e24a0fca3756c880f643b4f8d6940d9da5e19', 4),
('imp-da0c2dea539000e5', 'frittata-nam-pho-mai', 414, 'Frittata nấm phô mai kiểu Ý', 'Trứng chiên dày kiểu Ý vàng ươm thơm lừng nhân nấm đùi gà xào cháy cạnh, hành tỏi và phô mai Parmesan béo mặn', 'Ổ trứng chiên dày Frittata kiểu Ý mềm ẩm bên trong, xém vàng bên ngoài với nấm đùi gà xào thơm ngọt, ngò tây tươi, tỏi phi và phô mai Parmesan tan quyện đậm đà.', 'Cắt ổ Frittata thành từng miếng tam giác đều nhau, rắc thêm ngò tây tươi và dùng nóng hoặc ở nhiệt độ phòng cùng bánh mì nướng và salad trộn.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn làm nóng lại nhẹ bằng chảo khô lửa nhỏ hoặc thưởng thức nguội đều rất ngon.', 'italian', 'mon_nhanh_sang', NULL, 'easy', 12, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Frittata","Bữa sáng","Ẩm thực Ý","Trứng nấm","Phô mai"]', '["breakfast","lunch"]', '["pan_fry"]', '["egg","milk"]', 299, 299.4, 1252, 19.7, 21.3, 6.3, 8.7, 2.6, 1.6, 740, 1.85, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 173468"]', '8777c4420e2b58c01c3fa22917f94bb0a7613f3beb2c6690ff3d0920d49397ae', 'da84d2b469a79b598b3478d4e3325c34c231875bb012086cf607b4369e731573', 4),
('imp-e427b91ce9f574c3', 'sup-nam-kem-y', 415, 'Súp nấm kem tươi kiểu Ý', 'Súp nấm đùi gà xay nhuyễn sánh mượt cùng sữa tươi, kem béo, nước dùng rau củ và bánh mì nướng giòn Crostini', 'Bát súp nấm kem kiểu Ý thơm nức mùi nấm đùi gà xào vàng quyện sốt bơ bột mì béo dịu từ sữa tươi và kem tươi, kết cấu mịn mượt ăn kèm lát nấm áp chảo và bánh mì nướng giòn.', 'Múc súp nóng ra 4 bát sâu lòng, xếp vài lát nấm đùi gà áp chảo vàng lên mặt và rắc ngò tây tươi thái nhỏ; dùng kèm bánh mì nướng giòn Crostini.', 'Bảo quản phần súp trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng trên lửa nhỏ và khuấy đều, tránh đun sôi bùng làm tách lớp kem sữa.', 'italian', 'mon_canh', NULL, 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Súp nấm kem","Ẩm thực Ý","Khai vị","Món nóng","Crostini"]', '["lunch","dinner"]', '["simmer","pan_fry"]', '["milk","wheat"]', 413, 412.5, 1725, 10.4, 26.3, 12.1, 36.3, 4.2, 9.2, 1046, 2.62, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169761","USDA FDC 170000","USDA FDC 170416","USDA FDC 170859","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 171595","USDA FDC 172687","USDA FDC 173430","USDA FDC 173468"]', '7c8bbba944354c10730e3435804c39bdd1a45fe7adbec5a08794092784536a5d', 'dd55a31ed8167edb5db29303f845a55f2efab3d3481de44474a6800803405271', 4),
('imp-f3eb85959cb62d3e', 'sup-ga-rau-cu-y', 416, 'Súp gà rau củ thanh nhẹ kiểu Ý', 'Nước dùng gà trong ngọt tự nhiên hầm cùng cà rốt, khoai tây, cần tây thái hạt lựu và thịt ức gà xé mềm ấm bụng', 'Tô súp gà rau củ kiểu Ý nhẹ nhàng, thanh vị với nước dùng gà luộc trong vắt ngọt tự nhiên, kết hợp cà rốt, khoai tây bùi mềm, cần tây thơm dịu và thịt ức gà xé thớ mềm ngon.', 'Múc súp nóng ra tô sâu lòng, rắc thêm ngò tây tươi thái nhỏ và chút tiêu đen xay mới; rất thích hợp dùng kèm bánh mì nướng giòn cho bữa tối nhẹ nhàng.', 'Bảo quản súp trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng đun sôi nhẹ lại trên lửa vừa cho khoai tây và thịt gà nóng đều.', 'italian', 'mon_canh', NULL, 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Súp gà","Rau củ","Ẩm thực Ý","Thanh nhẹ","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer","boil"]', '["celery","chicken"]', 327, 327.2, 1369, 30.9, 12.7, 2, 22.1, 4.4, 5.6, 866, 2.17, '["USDA FDC 169230","USDA FDC 169988","USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170416","USDA FDC 170460","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647"]', '242c11f9175823bd4a10d6e99b46a4a6cc8fc319995c8aba53e9107f6c449b00', '0c1b34b177b31edce0a6125ea0bfddc2201888708354f160ceabbc559e3346ec', 4),
('imp-f4c5afa7ccc2a9ed', 'ca-chua-nhoi-thit-nuong', 417, 'Cà chua nhồi thịt nướng lò kiểu Ý', 'Trái cà chua chín mọng ôm trọn nhân thịt heo xay trộn vụn bánh mì, trứng gà và phô mai Parmesan nướng thơm lừng', 'Món Pomodori Ripieni truyền thống đẹp mắt với từng trái cà chua chín chắc tay nhồi đầy nhân thịt heo xay mềm ẩm quyện ruột cà chua băm, trứng gà, bột chiên xù, tỏi thơm và phô mai Parmesan nướng vàng.', 'Dọn ra đĩa trang trí vài lá húng quế Tây tươi; ăn nóng cùng bánh mì giòn chấm nước sốt cà chua tươm ra trong khay hoặc dùng ở nhiệt độ phòng đều ngon.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn làm ấm lại bằng lò nướng 170°C khoảng 10 phút.', 'italian', 'mon_lau_tiec', NULL, 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Cà chua nhồi thịt","Ẩm thực Ý","Nướng lò","Chiêu đãi","Món chính"]', '["lunch","dinner"]', '["assemble","grill_roast"]', '["egg","milk","pork","wheat"]', 413, 412.9, 1727, 20.8, 29, 9.3, 17.7, 2.5, 4.7, 735, 1.84, '["Panko / Batter Mix Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 170416","USDA FDC 170457","USDA FDC 170848","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468"]', '3443de2cc2f1809db8908c0f4822c70468b07db86f1cd227dda9f041fff43f38', '65302bfa776f10d23f53949baaf6d963a34bbfedfbe42c75e3c6004ab766a561', 4),
('imp-0d54a1288223d8ac', 'ga-nuong-bo-toi-y', 418, 'Gà nướng bơ tỏi kiểu Ý', 'Đùi gà nướng lò da vàng giòn rụm, thịt mềm mọng đẫm vị bơ tỏi thơm lừng thảo mộc Ý', 'Đùi gà có xương nướng lò ở nhiệt độ cao giúp lớp da ngoài vàng giòn bắt mắt trong khi thớ thịt bên trong vẫn giữ trọn độ ngọt mọng, hòa quyện hương bơ lạt, tỏi phi dịu và thảo mộc Ý.', 'Xếp gà nướng ra đĩa lớn, rưới nước bơ tỏi từ khay và rắc ngò tây tươi thái nhỏ; ăn nóng cùng khoai tây nghiền, bánh mì giòn hoặc salad trộn dầu giấm.', 'Bảo quản thịt gà nguội trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày. Khi dùng, làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C khoảng 8–10 phút để da giòn trở lại.', 'italian', 'mon_lau_tiec', NULL, 'easy', 15, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Nướng lò","Đùi gà","Bơ tỏi","Ẩm thực Ý","Món chính"]', '["lunch","dinner"]', '["grill_roast"]', '["chicken","milk"]', 424, 424, 1775, 36.5, 28.7, 11.2, 3.7, 0.9, 0.2, 692, 1.73, '["USDA FDC 169230","USDA FDC 170416","USDA FDC 170931","USDA FDC 171319","USDA FDC 171325","USDA FDC 172385","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475"]', '9d32c22e15ac7c286d851f36e1140eedcf041e4a4a80bc081be5e71c5f5a336c', '212e260c9a7ec1399b97869c21565fce040c2afe6e2f8191de94392eeb19db60', 4),
('imp-70e5e19dd4073b76', 'bo-ham-ca-chua-y', 419, 'Bò hầm cà chua kiểu Ý (Stracotto)', 'Thịt bò áp chảo vàng cạnh hầm liu riu nhiều giờ cùng rượu vang đỏ, passata cà chua và rau củ ngọt thanh', 'Món bò hầm truyền thống miền Bắc nước Ý được nấu chậm cùng nền rau củ xào thơm, rượu vang đỏ và sốt cà chua passata, cho thớ thịt bò mềm tơi đậm đà cùng nước sốt sánh quyện tuyệt hảo.', 'Múc thịt bò hầm nóng hổi ra đĩa sâu lòng cùng nước sốt sánh đặc, ăn kèm bánh mì giòn chấm sốt, khoai tây nghiền hoặc polenta nóng.', 'Món hầm để qua đêm trong ngăn mát tủ lạnh sẽ càng thấm vị ngon hơn, bảo quản được tối đa 3 ngày. Hâm lại trên lửa nhỏ, thêm 2–3 muỗng canh nước hoặc nước dùng nếu sốt quá đặc.', 'italian', 'mon_kho', NULL, 'hard', 25, 110, 5, '/frigo/illustrations/delicious-meal.png', '["Stracotto","Bò hầm","Rượu vang đỏ","Ẩm thực Ý","Mùa lạnh"]', '["lunch","dinner"]', '["braise","simmer"]', '["beef","celery","milk","sulphites","wheat"]', 638, 638, 2670, 51.1, 37.4, 14.1, 19.7, 3.8, 7.1, 1231, 3.08, '["USDA FDC 169072","USDA FDC 169761","USDA FDC 169988","USDA FDC 170000","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 171593","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475"]', 'ae45ed65324a3f5b2bc88be379cd85784ac172b90aacda793b92e8489d3ace9a', '7142bd127adbda02adeb961894284703e4892dbe56741a693ffd7520169dade0', 4),
('imp-500ffbf4fd05f9da', 'mi-y-muc-ot', 420, 'Mì Ý mực sốt cà chua cay', 'Sợi mì spaghetti al dente áo đẫm sốt cà chua bi chua ngọt quyện mực ống săn giòn và vị ớt cay nhẹ', 'Sự kết hợp chuẩn vị biển Địa Trung Hải giữa mực ống tươi áp chảo xém cạnh, om mềm trong sốt cà chua bi nấu cùng rượu vang trắng, tỏi và ớt tươi cay nhẹ, bám quyện hoàn hảo quanh từng sợi mì Ý.', 'Chia mì mực ra 4 đĩa sâu lòng khi còn nóng hổi, rắc thêm ít ngò tây tươi, lá hẹ thái nhỏ và tiêu đen xay; món mì hải sản Ý truyền thống không dùng kèm phô mai để giữ trọn vị ngọt thanh của mực.', 'Mì Ý trộn sốt ngon nhất khi dùng ngay sau khi nấu. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm lại trên chảo với 2 muỗng canh nước ở lửa nhỏ.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Hải sản","Mực tươi","Sốt cà chua","Cay nhẹ"]', '["lunch","dinner"]', '["boil","simmer","stir_fry"]', '["molluscs","squid","sulphites","wheat"]', 502, 501.6, 2098, 26.5, 12.5, 2, 67.7, 3.9, 4.5, 393, 0.98, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 169994","USDA FDC 170106","USDA FDC 170416","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223"]', 'f553e7e7396fdd8e4d9de921f8d0efb1a15fb3f1b14a50a75b938d04037e4080', 'a035f9cf8eb30af313f1af857cee33d8567ee0dc9e0159e907a1f3cc513294f6', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-ebc8bf739393ac91', 'canh-tom-dau-phu', 421, 'Canh tôm nấu đậu phụ cà chua', 'Tôm tươi bóc vỏ ngọt săn nấu cùng đậu phụ non mềm mịn và cà chua đỏ au, món canh nhanh 20 phút thanh mát cho bữa cơm tối', 'Canh tôm nấu đậu phụ cà chua là món canh dễ nấu, giàu đạm và nhẹ bụng. Nước canh có màu đỏ cam dịu nhẹ từ cà chua xào, hòa quyện vị ngọt tươi của tôm bóc vỏ cùng đậu phụ mềm mịn và hương thơm thoang thoảng của gừng, hành ngò.', 'Dọn canh nóng ra tô, rắc hành lá, ngò rí và chút tiêu xay; ăn kèm cơm trắng và đĩa rau xào hoặc thịt kho tiêu.', 'Món canh ngon nhất khi dùng nóng trong bữa; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đun sôi nhẹ 2 phút trước khi ăn.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Đậu phụ","Cà chua","Nấu nhanh"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp","soybean"]', 146, 146.3, 612, 17.2, 6.9, 1, 6.1, 2, 3.2, 1135, 2.84, '["USDA FDC 169231","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '70409cd0634d8a0768eed59b18e9b5ce7a35d8c2503bfee79e59e5e9456a92b4', '69055b03602a378687878976197f61553e3cd710bc5903ab983523a7ee765c90', 4),
('imp-3446b3924b05eb7b', 'canh-bo-bap-cai-ca-rot', 422, 'Canh thịt bò bắp cải cà rốt', 'Nước canh trong veo ngọt lịm từ bắp cải và cà rốt, kết hợp thịt bò thái mỏng mềm thơm cho bữa cơm ấm bụng', 'Canh thịt bò bắp cải cà rốt là biến tấu đầy đủ sắc màu và dinh dưỡng của món canh bò truyền thống. Vị ngọt bùi của cà rốt hòa cùng bắp cải mềm ngọt và lát thịt bò thăn thơm mùi tỏi phi tạo nên tô canh ấm nóng dễ chịu.', 'Dọn canh nóng vào tô lớn, rắc hành lá và tiêu đen xay; ăn kèm cơm trắng nóng và chén nước mắm ớt cắt lát.', 'Nếu còn dư, để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi hâm lại đun sôi nhẹ 2 phút trên lửa vừa để tránh thịt bò bị dai.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Bắp cải","Cà rốt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["beef","fish"]', 211, 211.4, 885, 17.4, 11.4, 3.6, 10.2, 3.1, 5.1, 1287, 3.22, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '899283b9448a9e996d011af9cf278098f656c9866bb62f7ed5eeb241f2a5c166', '721b7d290ef3724cf371fde08a3997b84fc2b17478189e9f98a14df173c3d6f7', 4),
('imp-6e3eb737c7d88a2c', 'ga-kho-trung', 423, 'Gà kho trứng', 'Đùi gà chặt miếng kho mềm cùng trứng gà luộc trong nước màu cánh gián sánh keo, món mặn đậm đà chuẩn vị cơm nhà Nam Bộ', 'Thịt đùi gà săn ngọt quyện cùng những quả trứng gà thấm đều nước kho màu nâu cánh gián sánh mượt, dậy mùi thơm của hành tím, tỏi, ớt giã nhuyễn và nước mắm ngon.', 'Múc gà kho trứng ra tô sâu lòng, rắc hành lá thái nhỏ và tiêu đen xay lên trên; dùng nóng với cơm trắng và dưa cải chua.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm lại trên lửa nhỏ cho gà và trứng nóng đều, nước kho đậm vị.', 'vietnamese', 'mon_kho', 'nam', 'easy', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Trứng gà","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["braise","boil","stir_fry"]', '["chicken","egg","fish"]', 470, 469.5, 1965, 41.9, 27.7, 7.7, 10.9, 0.6, 7.9, 1243, 3.11, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '47add4ab015821f929e8da48c099e3b503448f700c4884509d10ded1e1fec35e', '7f9821f6467df6d1c0df944ce196f65e9e4a867725c10d9071f1ba9a38801426', 4),
('imp-6251f57b97918111', 'tom-kho-tuong-dam', 424, 'Tôm kho nước tương đậm vị', 'Tôm tươi thịt chắc kho sánh cùng nước tương, dầu hào, rượu nấu ăn và dầu điều đỏ đẹp, món mặn nhanh gọn 15 phút cho bữa cơm tối', 'Tôm tươi rút chỉ lưng thấm đẫm nước sốt nước tương và dầu hào sánh bóng, lên màu đỏ cam bắt mắt từ dầu điều, thơm lừng mùi hành tỏi phi và tiêu đen cay nhẹ.', 'Gắp tôm kho ra đĩa sâu lòng, rưới phần sốt sánh đậm và rắc hành lá cùng tiêu đen xay; ăn nóng với cơm trắng và rau luộc.', 'Ngon nhất khi ăn nóng trong bữa; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa nhỏ.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Tôm tươi","Nước tương","Nhanh gọn","Đưa cơm"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 230, 229.6, 961, 28, 9.1, 1.4, 8.9, 0.7, 5, 1391, 3.48, '["Annatto Infused Oil Ref","MEXT Sake 16021","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '0cccab87392e7c1d147e58186be395ac696e303685bacb16cc5528eb44254ee4', '8942ad36bd6f05b4bd02d44c54c4067c7813a7fd3bc70506fb809e56ecce90b8', 4),
('imp-977a3409383d743f', 'muc-xao-bong-cai', 425, 'Mực xào bông cải xanh', 'Khoanh mực tươi giòn sần sật xào lửa lớn cùng bông cải xanh mướt thấm sốt nước tương và hành tím phi thơm', 'Mực xào bông cải xanh kết hợp giữa những khoanh mực giòn ngọt không hề tanh với bông cải xanh chần sơ xanh mướt, thấm đều gia vị nước tương, hành tím phi thơm và vị cay nhẹ kích thích vị giác.', 'Gắp mực xào bông cải xanh ra đĩa nóng, rắc tiêu đen xay và chút ớt bột nếu thích cay; dùng ngay cùng cơm trắng.', 'Mực xào ngon nhất khi thưởng thức nóng ngay; nếu bảo quản tủ mát trong ngày, hãy đảo nhanh trên chảo lửa lớn khoảng 1 phút để mực không bị dai.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Bông cải","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["molluscs","soybean","squid","wheat"]', 250, 249.6, 1044, 24.2, 9.3, 1.5, 18.7, 3.6, 5.6, 1114, 2.78, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170379","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 174223","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '91482137d85714c73db7543b6d2aefa1b39ab9b330888a3f9f4b4b0842b4f7cc', '3142f42895531c91c833aa31c174f9db96e3960b97d6879e13e8ad853612974b', 4),
('imp-a4ff266c02427746', 'bong-cai-xao-toi', 426, 'Bông cải xanh xào tỏi', 'Bông cải xanh chần sốc lạnh giòn ngọt sần sật xào nhanh trên lửa lớn cùng tỏi phi vàng và chút nước tương thơm dịu', 'Bông cải xanh xào tỏi là món rau xanh thanh mát, giữ nguyên sắc xanh ngọc bích và độ giòn ngọt tự nhiên của từng bông súp lơ nhờ kỹ thuật chần sốc nhiệt, quyện hương tỏi phi vàng thơm lừng và vị mặn dịu của nước tương.', 'Gắp bông cải xanh xào tỏi ra đĩa phẳng khi vừa tắt bếp để giữ độ giòn xanh; dùng nóng kèm cơm trắng và các món mặn.', 'Món rau xào nên ăn hết trong bữa để giữ trọn màu xanh và độ giòn tự nhiên.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 12, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau xanh","Tỏi","Thanh đạm","Dưới 20 phút"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["soybean","wheat"]', 128, 128.3, 537, 4, 8.8, 1.3, 10.8, 3, 2.3, 1042, 2.61, '["USDA FDC 169230","USDA FDC 170379","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Monosodium Glutamate","VN/Asian Seasoning Powder Avg"]', '4322ba7a2ea89c286d85e6455c994f831c0c0423eed749a6db1142e23ba89a53', '829e68521a10ad294a2589ff9a571a0c3f3f37d5e32e6838e28a25bc3ab4cdae', 4),
('imp-f9f08651bc712e93', 'cha-ca-ha-noi-nghe', 427, 'Chả cá Hà Nội tẩm nghệ (Chả cá Lã Vọng)', 'Cá lăng phi lê ướp riềng mẻ nghệ mắm tôm áp chảo thơm vàng, đảo nóng cùng thì là hành lá và lạc rang', 'Chả cá Hà Nội tẩm nghệ là tinh hoa ẩm thực Tràng An nổi tiếng. Cá lăng phi lê ít xương được ướp đậm đà với riềng giã, nước mẻ lọc mịn, bột nghệ và chút mắm tôm rồi áp chảo vàng ươm, sau đó đảo nóng tại bàn cùng thật nhiều hành lá và thì là xanh mướt.', 'Múc chả cá cùng hành lá, thì là ra đĩa hoặc chảo gang nóng, rắc đậu phộng rang giã dập lên trên; ăn kèm bún tươi, rau húng láng, ớt thái lát và mắm tôm đánh bông sủi bọt.', 'Cá sau khi ướp và áp chảo sơ có thể bảo quản ngăn mát 24 giờ; khi ăn chỉ cần đảo nóng lại trên chảo dầu 3–4 phút rồi mới thả hành lá và thì là vào sau cùng để giữ màu xanh giòn.', 'vietnamese', 'mon_chien', 'bac', 'medium', 35, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chả cá","Hà Nội","Bắc Bộ","Đặc sản"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["crustaceans","fish","peanut","shrimp"]', 483, 483, 2020, 36.3, 19.1, 3.2, 42.7, 4.5, 6.5, 1121, 2.8, '["Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 172233","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 175176","USDA FDC Monosodium Glutamate","VN Com Me Ref"]', 'ffee401f7697af5523a53bb69e581aec59b450990dfdf295d289017350adf105', '4b512f3c182ad64598b040ae5ff7e51f79f3172cd4d41c263a74071f8bc18785', 4),
('imp-0d6c454ae1073ef6', 'su-su-hap-toi', 428, 'Su su hấp tỏi rưới mắm thơm', 'Su su non hấp chín tới giữ nguyên độ giòn ngọt, rưới dầu tỏi phi thơm hòa nước mắm đậm đà cho bữa cơm nhẹ bụng', 'Những miếng su su non xanh mướt hấp cách thủy vừa chín tới giữ được vị ngọt thanh tự nhiên và độ giòn nhẹ, rưới đều hỗn hợp nước mắm dầu tỏi phi vàng thơm nức cùng hành lá xanh tươi.', 'Bày su su hấp ra đĩa sâu lòng, rưới đẫm phần nước mắm dầu tỏi thơm lừng lên trên, ăn nóng kèm cơm trắng hoặc chấm thêm xì dầu ớt.', 'Su su hấp ngon nhất khi ăn nóng ngay trong bữa để giữ độ giòn ngọt; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và hấp lại nhanh 3 phút.', 'vietnamese', 'mon_hap_luoc', 'trung', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Su su","Thanh đạm","Dễ nấu","Dưới 20 phút"]', '["lunch","dinner"]', '["steam"]', '["fish","soybean","wheat"]', 115, 114.7, 479, 3.1, 6.2, 0.9, 14.2, 3.8, 5.5, 1061, 2.65, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169990","USDA FDC 170005","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '2d39aa22711258adcb8db306d281321578e2b48d3c0839cd2a660f3e1f114af5', 'bb7a09fd308a1f564a4b0465526d64003b8ebd192a3ac008dd287655fdde13c2', 4),
('imp-4d81607829384874', 'ga-hap-gung-hanh', 429, 'Đùi gà hấp gừng hành thơm mềm', 'Đùi gà ướp đậm vị hấp chín mềm mọng cùng gừng sợi, hành tím và hành lá tươi, rưới dầu mè thơm chấm muối tiêu chanh', 'Đùi gà tơ khứa nhẹ ướp thấm gia vị rồi hấp cách thủy cùng gừng non thái sợi, hành tím và hành lá giúp giữ trọn độ ẩm ngọt trong từng thớ thịt, dậy hương thơm ấm bụng rất hợp bữa cơm gia đình.', 'Chặt hoặc để nguyên đùi gà xếp ra đĩa, rưới thêm nước hấp thơm gừng hành và dầu mè; dọn nóng chấm muối tiêu chanh hoặc xì dầu ớt.', 'Gà hấp bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn hấp lại 6–8 phút ở lửa vừa để thịt nóng mềm mà không bị khô.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 20, 28, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Gà","Gừng","Gia đình","Cơm nhà"]', '["lunch","dinner"]', '["steam"]', '["chicken","sesame","soybean","wheat"]', 364, 364.2, 1525, 36.8, 20.7, 5.6, 6.1, 1.2, 1.5, 1361, 3.4, '["USDA FDC 168155","USDA FDC 169231","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'a9b8458243995913cf6ff16969d41411619ca54ae2f5e1204f8c96f8a5c06071', '503f82046707782b3106372ca923f8e3b3c9feb76253f70315ee87bfee011f7a', 4),
('imp-1b518ba2f068f3ab', 'nom-dua-chua-cay', 430, 'Nộm dứa chua cay giòn mát', 'Dứa chín vàng thái lát quyện cà rốt ngâm đá giòn sần sật, hành lá xanh tươi và đậu phộng rang trong nước trộn chanh ớt hiểm chua cay thanh mát', 'Nộm dứa chua cay mang hương vị nhiệt đới tươi mới với từng lát dứa chín vàng mọng nước, cà rốt bào sợi ngâm đá giòn sần sật, hành lá xanh mát và nước mắm giấm chanh tỏi ớt hài hòa, điểm đậu phộng rang thơm bùi.', 'Bày nộm ra đĩa sâu lòng, rắc đậu phộng rang giã dập và vài lát ớt hiểm lên trên; dùng ngay làm món khai vị giải ngấy.', 'Nộm dứa nên trộn trước khi ăn khoảng 10 phút và dùng hết trong ngày; nếu chuẩn bị trước, giữ riêng dứa thái lát, cà rốt ráo nước và bát nước trộn trong ngăn mát tủ lạnh.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nộm dứa","Chua cay","Khai vị","Thanh mát","Nhiệt đới"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["fish","peanut"]', 227, 227.1, 950, 6.7, 8.5, 1.1, 35.7, 5.2, 24.4, 1398, 3.5, '["USDA FDC 168155","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647"]', '18f406ea5773b5641570768b74aac904c26d0ca7d62c97924316dcb9c78fee8c', 'a3146e5270cb2448072a6830dc66c1881a0fdce213b2f071c4eb2045f82bdcb5', 4),
('imp-0f336e8735d9ce75', 'goi-muc-dua-leo', 431, 'Gỏi mực dưa leo sả ớt giòn mát', 'Khoanh mực ống trụng giòn ngọt trộn dưa leo bỏ ruột và cà rốt vắt ráo, thơm nức hương sả khoanh, rau răm, húng quế và tỏi phi vàng giòn', 'Gỏi mực dưa leo sả ớt là món gỏi biển giòn mát với từng khoanh mực ống trụng vừa chín tới trắng giòn, hòa quyện cùng dưa leo bỏ ruột và cà rốt vắt ráo, sả thái khoanh thơm nồng, rau răm húng quế và chút tỏi phi vàng rụm.', 'Bày gỏi mực dưa leo ra đĩa, rắc tỏi phi vàng giòn và vài lát ớt lên trên; dọn ăn ngay kèm bánh phồng tôm giòn tan.', 'Nên thưởng thức gỏi trong vòng 30 phút sau khi trộn để dưa leo và mực giữ độ giòn sần sật; nếu chuẩn bị trước, để riêng phần mực trụng, rau củ vắt ráo và nước trộn trong tủ lạnh.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi mực","Dưa leo","Sả ớt","Khai vị","Mát lành"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["celery","fish","molluscs","squid"]', 264, 264.1, 1105, 18.6, 4.6, 0.9, 38.1, 2.6, 10.5, 1164, 2.91, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169988","USDA FDC 170106","USDA FDC 170393","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN Banh Da Ref","VN Rau Ram Ref"]', '6016d336c0d189b58fdc04b93a98bfd4cd4110fe0bb4a655a06a5addcfe7c627', '46ae58a1a823b3b9805300b780915a87de9e5dec634cdcba77d2e6ac6cd8482e', 4),
('imp-f93013fb234d39d0', 'bun-xao-chay-nam', 432, 'Bún xào chay nấm đùi gà rau củ', 'Sợi bún gạo tươi tơi mềm không bết dính, xào thơm cùng nấm đùi gà, bắp cải, cà rốt và nước tương đậm đà', 'Đĩa bún xào chay mộc mạc mà tròn vị với từng sợi bún gạo tơi mềm thấm đều nước tương thơm lừng, kết hợp nấm đùi gà giòn ngọt, bắp cải và cà rốt thái sợi giòn tươi, dậy hương tỏi phi và hành lá.', 'Gắp bún xào nóng ra đĩa lớn, rắc thêm chút tiêu xay và ớt thái lát nếu thích cay; dùng nóng kèm chén nước tương ớt hoặc dưa leo rau sống.', 'Bún xào ngon nhất khi thưởng thức nóng ngay sau khi nấu; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo lửa vừa 2–3 phút với 1 muỗng nước lọc.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Bún xào","Nấm đùi gà","Rau củ","Ngày rằm"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["soybean","wheat"]', 301, 300.5, 1258, 7.3, 9.5, 1.4, 49.3, 5.5, 7.2, 1516, 3.79, '["NIN VN Fresh Bun Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'f665cba686e6da185c386aba9e09295ad1bb319e876887abd10c1ed43bf85f66', '94a9646b0255d986cdf03e45ba83019cdd9f608535c9b9c2da207bc3d5608b80', 4),
('imp-6af3e18fdac79061', 'mien-tron-ga', 433, 'Miến trộn gà', 'Sợi miến dong dai giòn trộn đều nước tương chua ngọt đậm đà cùng thịt đùi gà luộc giòn mềm, giá đỗ chần, rau răm thơm và lạc rang bùi béo', 'Món miến trộn gà thanh mát nhẹ bụng rất hợp cho bữa trưa mùa hè với sợi miến dong không bị dính bết, thịt đùi gà luộc gừng ngâm lạnh giòn da mềm thịt, quyện sốt nước tương nước mắm chua ngọt cùng rau thơm và lạc rang giã dập.', 'Trộn đều miến dong, giá đỗ, thịt gà thái lát và rau thơm với nước trộn chua ngọt ngay trước khi ăn, rắc lạc rang giã dập và hành lá thái nhỏ lên trên để giữ độ giòn thơm.', 'Gà luộc và nước trộn pha sẵn có thể bảo quản ngăn mát 1–2 ngày; chỉ nên trụng miến dong và trộn cùng rau thơm, lạc rang ngay trước bữa ăn để sợi miến không bị trương nở.', 'vietnamese', 'mon_bun_pho', 'bac', 'easy', 20, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Miến trộn","Thịt gà","Món trộn thanh mát","Bữa trưa"]', '["lunch","dinner"]', '["boil","toss_mix","assemble"]', '["chicken","fish","peanut","soybean","wheat"]', 456, 456.2, 1909, 24.7, 16.1, 3.6, 53.6, 2.9, 5.3, 2051, 5.13, '["USDA FDC 168155","USDA FDC 168952","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 172185","USDA FDC 172238","USDA FDC 172385","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 174277","VN Culinary Herb Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', '4bdf6baefc2f17e185e40dc3d54e34c5650470569802cd2276ad56e48c644712', 'be80a7cc22818303997be42329af17aea11c8f1665a647f4b6553343960494d0', 4),
('imp-2e39be75d8f72249', 'ca-chua-xao-nam-chay', 434, 'Cà chua xào nấm đùi gà chay', 'Nấm đùi gà xào săn giòn ngọt hòa quyện sốt cà chua chín đỏ mọng sánh mịn, thanh đạm đưa cơm', 'Món xào chay thanh nhẹ nhanh gọn với từng lát nấm đùi gà xém cạnh giòn dai thấm hương tỏi phi, quyện trong phần sốt cà chua chín đỏ mọng chua ngọt dịu, thêm chút dầu hào chay và bột năng giúp nước sốt sánh bóng quyến rũ.', 'Múc cà chua xào nấm ra đĩa sâu lòng khi còn nóng hổi, rắc thêm phần lá hành xanh thái nhỏ lên trên; dùng kèm cơm trắng nóng rất bắt cơm.', 'Món xào ngon nhất khi ăn nóng ngay trong bữa; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy đun nóng lại trên chảo lửa vừa 2–3 phút.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Cà chua","Nấm đùi gà","Dưới 20 phút"]', '["lunch","dinner"]', '["stir_fry"]', '["soybean","wheat"]', 146, 146.2, 611, 5.6, 8, 1.2, 16.6, 4.3, 6.6, 816, 2.04, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170457","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '54f494c0506d043fdb1c35af6ae2d92177950bb78c5c4905fe58802b2e488415', 'd025df7fec30106ae191e708cbc862ba2bd6ec0a5b72701e8a0693228b5dff15', 4),
('imp-11b65c6b18266849', 'dau-phu-kho-dua-chay', 435, 'Đậu phụ kho dứa chay chua ngọt', 'Đậu phụ rán vàng giòn kho liu riu cùng dứa chín thơm ngọt trong nước sốt nước tương dầu hào sánh đậm bắt cơm', 'Món kho chay mới lạ kích thích vị giác với đậu phụ trắng chiên vàng giòn bên ngoài, mềm béo bên trong, rim thấm cùng những miếng dứa chín chua ngọt thanh dịu, quyện sốt nước tương dầu hào chay sánh bóng thơm lừng hành tỏi.', 'Múc đậu phụ kho dứa ra đĩa sâu lòng, rưới nước sốt sánh vàng lên trên rồi rắc hành lá, ớt lát và tiêu xay; thưởng thức nóng cùng cơm trắng.', 'Để nguội rồi bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; hâm nóng lại trên lửa nhỏ 4–5 phút cùng 1–2 muỗng nước lọc trước khi ăn.', 'vietnamese', 'mon_chay', 'nam', 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Nam Bộ","Món kho","Đậu phụ","Dứa"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["soybean","wheat"]', 279, 279.1, 1167, 18.5, 16.3, 2.4, 20.4, 3.1, 11.2, 1520, 3.8, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', 'b2ad2056e8eed27f13f09aed3ec1e10506917787bc4599041d0b1c64db4e17c1', 'b86772bb5d375635120425236b68dd2785a8153b377358756e17d76b9a420019', 4),
('imp-2ae4c4cdd97c5d02', 'com-bo-hanh-tay', 436, 'Cơm bò hành tây', 'Thịt bò thăn xào lửa lớn mềm ngọt cùng hành tây giòn thơm sốt xì dầu, dầu hào, chan lên đĩa cơm trắng nóng dẻo', 'Bữa cơm bò hành tây nhanh gọn chỉ trong 20 phút với thịt bò thăn xào tái chín mềm mọng đậm vị xì dầu, dầu hào, từng múi hành tây chín tới giòn ngọt tự nhiên và phần nước sốt sánh thơm rưới đẫm cơm trắng nóng hổi.', 'Xới cơm trắng nóng ra đĩa sâu lòng, múc phần bò xào hành tây và nước sốt rưới lên trên, rắc hành lá cùng tiêu đen xay và ăn kèm dưa leo hoặc cà chua.', 'Thịt bò xào hành tây ngon nhất khi ăn nóng ngay. Nếu còn dư, bảo quản riêng phần bò xào trong ngăn mát tối đa 24 giờ và đảo nóng lại thật nhanh trên chảo lửa vừa để thịt không bị dai.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm bò","Xào nhanh","Dưới 20 phút","Cơm văn phòng","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","soybean","wheat"]', 535, 535, 2239, 27.8, 18.3, 5.3, 63.1, 2.4, 4.7, 990, 2.48, '["USDA FDC 168878","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '906220caa1a39c810ca2add2cd6437cec447586af26c6ff77b2d2e30315ee415', '477bdb303d022c54561f8cf03a73009eff5f958a26961609b21196c65c713294', 4),
('imp-9a2994a529126adb', 'mi-xao-trung-rau', 437, 'Mì xào trứng rau', 'Sợi mì dai săn xào lửa lớn cùng trứng gà chiên tơi xốp, bắp cải và cà rốt giòn ngọt đậm sốt xì dầu, dầu hào', 'Món mì xào trứng rau đơn giản nhưng đủ sắc hương vị với sợi mì dai săn bóng bẩy quyện sốt xì dầu, dầu hào, trứng gà đánh tơi vàng ươm mềm xốp cùng bắp cải trắng và cà rốt giòn ngọt.', 'Bày mì xào trứng rau ra đĩa nóng, rắc hành lá và tiêu đen xay; dùng kèm tương ớt hoặc ớt tươi thái lát rất tròn vị.', 'Nên ăn nóng ngay sau khi xào để sợi mì tơi dai và rau củ giữ được độ giòn. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ rồi đảo nóng nhanh trên chảo lửa vừa.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Trứng rau","Ăn nhanh","Dưới 20 phút","Tiết kiệm"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["egg","fish","molluscs","soybean","wheat"]', 462, 462.4, 1935, 17.5, 14.9, 3.2, 65.3, 5.2, 7.6, 1861, 4.65, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '959d7530bc4a6892152a88e6121c7b1a7f03029916bc5526077e8ea1971c70a7', '39e061c73f6035f9a77370d946b212c29df6aa8a92cae1d5462c36b994adc90c', 4),
('imp-990934aa20b70964', 'lau-bo-rau-thom', 438, 'Lẩu bò rau thơm cà chua', 'Nước lẩu hầm xương bò ngọt sâu hòa quyện vị chua thanh cà chua và chanh tươi, nhúng thịt bò thăn tái mềm cùng rau húng quế, ngò rí', 'Lẩu bò rau thơm cà chua là món lẩu dễ ăn và tròn vị cho những buổi sum họp cuối tuần. Nước lẩu được ninh kỹ từ xương ống bò cho vị ngọt đậm tự nhiên, kết hợp cà chua xào đỏ đẹp và nước cốt chanh thanh mát, nhúng thịt bò thái mỏng chín tới cùng hương thơm nồng nàn của húng quế, ngò rí và rau muống.', 'Bày đĩa thịt bò thái mỏng, nấm đùi gà, rau muống, húng quế, ngò rí và bún tươi quanh nồi lẩu sôi; nhúng thịt bò trong 20 giây cho tái mềm ngọt nước rồi thưởng thức nóng.', 'Thịt bò sống chưa nhúng bảo quản ngăn mát tối đa 24 giờ; phần nước dùng còn dư đun sôi lại 5 phút trước khi dùng tiếp với rau và thịt mới.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'medium', 25, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Lẩu bò","Rau thơm","Cà chua","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["beef","fish"]', 587, 587.2, 2456, 42.7, 26.6, 9.5, 45.4, 5.3, 6.5, 1740, 4.35, '["NIN VN Fresh Rice Noodle Ref","USDA Beef Rib / Bone Ref","USDA FDC 168155","USDA FDC 168580","USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd8874f901e38fef4f204a5487eea57c9e7e3608d410d5c5879018734129189a6', '703eb09d0a231801af7c80e50de9bae5496c0960833b0351fda47c3655605f94', 4),
('imp-d0569e8ec34b2bfc', 'bo-xao-gia-do', 439, 'Thịt bò xào giá đỗ lửa lớn', 'Thịt bò thái lát mỏng xào nhanh lửa lớn giữ độ mềm ngọt, kết hợp giá đỗ giòn sần sật thấm vị xì dầu và dầu hào thơm tỏi', 'Đĩa thịt bò xào giá đỗ đậm đà hương vị cơm nhà kiểu Hoa với từng lát thịt bò mềm mọng thấm gia vị và cọng giá đỗ trắng mập vẫn giữ nguyên độ giòn thanh không ra nước.', 'Trút bò xào giá đỗ ra đĩa khi còn bốc khói, rắc chút tiêu đen xay lên trên và ăn ngay cùng cơm trắng nóng, chấm thêm xì dầu ớt lát nếu thích.', 'Món xào giá đỗ nên dùng hết ngay trong bữa để giữ độ giòn tươi; nếu bảo quản tủ mát chỉ nên giữ tối đa 12 giờ và đảo nóng lại rất nhanh trên lửa lớn.', 'chinese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Giá đỗ","Bữa nhanh","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","sesame","soybean","wheat"]', 277, 276.8, 1159, 20.6, 17.9, 4.8, 8.7, 1.7, 4.6, 1183, 2.96, '["Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '824af3ec1fb57e3672b677be98e41b588ffcdeb9bf0651f2e9cc4732edecce39', 'e696b366cad65bdf7bbc5a8dae3d42d073ac3f554a30dfd92369c3d159590501', 4),
('imp-531f59c246a56bcb', 'vien-thit-chien-trung', 440, 'Thịt viên chiên giòn kiểu Hoa', 'Thịt heo xay quết dẻo cùng trứng gà, gừng hành và ngũ vị hương, vo viên chiên ngập dầu vàng giòn bên ngoài, mềm mọng bên trong', 'Những viên thịt heo chiên vàng rộm, vỏ ngoài hơi xém giòn thơm nức mùi ngũ vị hương, gừng và xì dầu đặc, cắn vào bên trong vẫn giữ được độ dẻo dai và nước thịt ngọt mềm.', 'Bày thịt viên nóng ra đĩa, rắc thêm chút hành lá hoặc ăn kèm dưa leo thái lát; chấm muối tiêu chanh hoặc tương ớt cay.', 'Thịt viên chiên dư có thể để nguội hoàn toàn, bảo quản ngăn mát tối đa 2 ngày (hoặc cấp đông 2 tuần); khi ăn chiên lại bằng nồi chiên không dầu ở 180°C trong 5 phút cho giòn vỏ.', 'chinese', 'mon_chien', NULL, 'medium', 25, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Thịt viên","Món nhậu","Trung Hoa","Giòn rụm"]', '["lunch","dinner"]', '["deep_fry"]', '["egg","pork","soybean","wheat"]', 466, 465.5, 1947, 23.5, 36.8, 11.5, 8.4, 0.5, 2.7, 887, 2.22, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '49dbde7cd7208204b2c3551bfe67cd37ed830cc34e64dec743a61e547ba34bd4', '380b9d75ca148b9e218955d40a30f222a170c7cdf8e7c745a89ec9621378fab2', 4),
('imp-3767b2e36f535b7b', 'ga-nuong-tuong-trung', 441, 'Gà nướng xì dầu mật ong kiểu Hoa', 'Ức gà ướp xì dầu đặc, ngũ vị hương, tỏi gừng rồi nướng lửa vừa kết hợp phết mật ong cho mặt ngoài bóng đẹp cánh gián thơm lừng', 'Những miếng ức gà nướng óng ả màu cánh gián từ xì dầu đặc và mật ong, thấm sâu hương thơm ấm áp của ngũ vị hương, tỏi gừng và dầu mè, thịt bên trong vẫn mềm mọng khi thưởng thức.', 'Để gà nghỉ 5 phút rồi thái lát xéo dày 1,5 cm xếp ra đĩa, rưới nước sốt nướng còn lại và rắc hành lá; dùng nóng với cơm trắng hoặc rau cải chần.', 'Bảo quản thịt gà nướng trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại trong lò 160°C khoảng 6–8 phút hoặc áp chảo lửa nhỏ có đậy nắp để thịt giữ độ ẩm.', 'chinese', 'mon_lau_tiec', NULL, 'easy', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Ức gà","Xì dầu","Mật ong","Cơm nhà"]', '["lunch","dinner"]', '["grill_roast"]', '["chicken","sesame","soybean","wheat"]', 308, 308.3, 1290, 41.1, 10.3, 1.8, 11.1, 0.7, 7.4, 943, 2.36, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 171477","USDA FDC 174277"]', '27e7f7c0c67e933ed17858c3f846ad8c5a915c2010732b3d216eaae722293325', 'd887b64d8ec6b53821389dbbf48eeef7210482e2b7388a34d5196fe1ef9fc821', 4),
('imp-08b08cad387c7c9f', 'dau-phu-chien-toi', 442, 'Đậu phụ chiên giòn sốt tỏi', 'Đậu phụ trắng áo bột bắp chiên vàng giòn rụm, rưới sốt tỏi phi dầu nóng cùng xì dầu nhạt và dầu hào chay đậm đà đưa cơm', 'Đậu phụ cứng chiên áp chảo giòn rụm lớp vỏ ngoài nhờ phủ bột bắp, bên trong vẫn béo mềm, quyện cùng bát sốt tỏi hành lá xèo thơm trong dầu nóng pha xì dầu và dầu hào chay.', 'Xếp đậu phụ chiên còn nóng giòn ra đĩa, rưới đều sốt tỏi lên mặt rồi rắc hạt mè trắng rang và ớt sừng đỏ thái lát; dùng ngay cùng cơm trắng nóng.', 'Món chiên rưới sốt ngon nhất khi ăn ngay lúc vừa làm xong; nếu cần để riêng phần đậu chiên và sốt trong ngăn mát tối đa 2 ngày, khi ăn áp chảo lại đậu cho giòn rồi mới rưới sốt.', 'chinese', 'mon_chien', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Đậu phụ","Món chay","Sốt tỏi","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry"]', '["sesame","soybean","wheat"]', 376, 375.9, 1572, 15.8, 28.4, 4.1, 18.8, 2.1, 7.1, 880, 2.2, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '7b2fa3d5c6ad975fad0a6cbed39a4c20257bc5479c5d31fe47233dd41ca31e4f', '4bb1262db0bfbf4d8e10b4be78968c89e77a47fc8352d7ceae9b52d90d8f823d', 4),
('imp-cbbfa59518b7d47d', 'mi-tron-toi', 443, 'Mì trộn dầu hành tỏi phi xì dầu', 'Sợi mì trứng dai ngon trộn đều trong sốt xì dầu nhạt, xì dầu đặc sánh dịu cùng dầu phi hành lá và tỏi vàng thơm nức', 'Món mì trộn kiểu Thượng Hải nhanh gọn chỉ trong 15 phút với từng sợi mì bóng bẩy áo đều dầu hành phi giòn thơm, tỏi phi vàng nhạt cùng hỗn hợp xì dầu nhạt và xì dầu đặc đậm đà.', 'Gắp mì trộn nóng ra đĩa sâu lòng, rắc hành lá phi giòn lên trên, trộn thêm một lần nữa trước khi thưởng thức; có thể ăn kèm trứng ốp la hoặc cải thìa luộc.', 'Mì trộn ngon nhất khi ăn nóng ngay sau khi trộn; nếu dư bảo quản ngăn mát tối đa 1 ngày và xào đảo nóng lại cùng 1–2 muỗng canh nước lọc.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Bữa nhanh","Tỏi phi","Hành phi","Bữa trưa"]', '["breakfast","lunch","dinner"]', '["boil","toss_mix"]', '["egg","sesame","soybean","wheat"]', 538, 538.4, 2253, 13.7, 22.5, 3.5, 71.1, 3.2, 5.1, 1739, 4.35, '["Dark Soy Sauce Label Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '3f2e2ad68221e100fb1e9330cd81025f83e72e69bf52c95eec13aa909ad3857d', '9a87b6f48885a60b471a8e992bb3737b9b1a2e02bdc689f802ac3225310b2813', 4),
('imp-266587069d92cb79', 'cua-hap-gung', 444, 'Cua biển hấp gừng chấm giấm đen', 'Cua biển tươi hấp chín giữ trọn vị ngọt thịt trên lớp gừng thơm, dùng kèm nước chấm giấm đen Trấn Giang gừng băm hài hòa', 'Món cua hấp gừng thanh tao kiểu Trung Hoa tôn vinh trọn vẹn độ ngọt tự nhiên và thớ thịt săn chắc của cua biển tươi, kết hợp cùng bát nước chấm giấm đen Trấn Giang pha gừng băm dịu vị ấm bụng.', 'Bày cua hấp đỏ au ra đĩa lớn, dọn nóng ngay cùng bát nước chấm giấm đen gừng hành và kẹp càng cua để tách vỏ dễ dàng.', 'Cua hấp ngon nhất khi thưởng thức nóng ngay sau khi lấy khỏi xửng; nếu còn dư có thể gỡ lấy thịt cua bảo quản ngăn mát tối đa 24 giờ và hấp lại 3–4 phút trước khi ăn.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 15, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Cua biển","Hải sản","Gừng tươi","Thanh tao"]', '["lunch","dinner"]', '["steam"]', '["crab","crustaceans","soybean","wheat"]', 169, 169.4, 709, 30.3, 1.8, 0.4, 5.2, 0.3, 3, 1006, 2.52, '["Chinkiang Black Vinegar Ref","Shaoxing Wine Ref","USDA FDC 168833","USDA FDC 169231","USDA FDC 170005","USDA FDC 172238","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277"]', 'd57fa7aeb0a56ff85083e9fdb538ded0d83876700c38c52de73f1bc4a5c7bd39', 'ea1b6ad3a7b78205e785d7b1ef610a762fac3a3abd2daf3bd88d5a415ce0abff', 4),
('imp-b02fdf7cecfae119', 'muc-kho-tuong', 445, 'Mực ống kho xì dầu gừng', 'Khoanh mực ống tươi săn giòn ướp rượu Thiệu Hưng và xì dầu, kho nhanh cùng gừng sợi tạo nước sốt sánh nâu cánh gián thơm hương dầu mè', 'Món mực ống kho xì dầu gừng kiểu Hoa với những khoanh mực trắng dày thịt săn giòn, thơm hương rượu Thiệu Hưng và gừng sợi ấm nồng, thấm đẫm nước sốt hai loại xì dầu sánh nâu bóng mượt điểm dầu mè thơm lừng.', 'Múc mực kho cùng nước sốt sệt ra đĩa sâu lòng, rắc hành lá cắt khúc và tiêu đen xay; dùng nóng kèm cơm trắng dẻo rất bắt vị.', 'Bảo quản mực kho trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại nhanh trên chảo lửa nhỏ khoảng 2–3 phút, tránh đun lâu làm mực bị dai.', 'chinese', 'mon_kho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Mực ống","Xì dầu","Cơm nhà","Đậm đà"]', '["lunch","dinner"]', '["braise"]', '["molluscs","sesame","soybean","squid","wheat"]', 319, 319.1, 1335, 30.7, 13, 2.2, 17.9, 0.7, 9.3, 1359, 3.4, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277"]', 'f6f1b70b0517adb77f41f869313d03f5968c5b45c5c9d4ebb037e44ea56f7f2d', '7bfa2e178cb64310786a5285564c758771542799b9dcf357eea423252d2f1cd1', 4),
('imp-4693d6520fbd9d49', 'bo-nuong-toi', 446, 'Thịt bò nướng tỏi lát kiểu Hoa', 'Thịt bò thái lát mỏng ngang thớ ướp xì dầu nướng lửa lớn xém cạnh, phủ tỏi lát phi vàng giòn và hành lá chấm muối tiêu đậm đà', 'Món thịt bò nướng tỏi thơm lừng với từng lát bò thăn mềm mọng cháy cạnh nhẹ, hòa quyện hương xì dầu dầu hào đậm đà, điểm xuyết những lát tỏi phi vàng giòn rụm và muối tiêu chấm kèm.', 'Xếp thịt bò nướng nóng ra đĩa, rắc tỏi lát phi vàng cùng hành lá xanh lên mặt; thưởng thức ngay cùng muối tiêu và cơm trắng hoặc cuốn rau sống.', 'Thịt bò nướng ngon nhất khi dùng ngay lúc nóng; phần dư bảo quản ngăn mát tối đa 24 giờ và áp chảo nóng lại trên chảo gang khoảng 1 phút cho vừa ấm.', 'chinese', 'mon_lau_tiec', NULL, 'easy', 20, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Thịt bò","Tỏi phi","Cháy cạnh","Món nhậu"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["beef","molluscs","soybean","wheat"]', 367, 366.5, 1534, 32.9, 23, 7.2, 6.2, 0.9, 0.8, 1493, 3.73, '["USDA FDC 169230","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '63825ac212546f1837503016f8c9bc1eb3582f9d7028058f89211e888b7f63ca', 'b3497dbf333c4794f197090361532b9451188ee3a8b1dbf3d33d3ef4ef8f8881', 4),
('imp-dd48c08a9b9ed207', 'suon-chien-gion', 447, 'Sườn non chiên giòn ngũ vị', 'Sườn non ướp thấm xì dầu, dầu hào và ngũ vị hương, nhúng hỗn hợp trứng gà bột chiên giòn rồi chiên ngập dầu vàng rụm mềm ngọt', 'Từng khúc sườn non thơm lừng ngũ vị hương và tỏi, được bao bọc bởi lớp bột trứng vàng ruộm giòn tan bên ngoài trong khi thớ thịt sát xương bên trong vẫn mềm ngọt mọng nước.', 'Xếp sườn chiên nóng ra đĩa, dọn kèm chén muối tiêu hoặc tương ớt cay; ăn cùng cơm trắng nóng và dưa leo thái lát giúp cân bằng vị béo.', 'Bảo quản sườn chiên trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn làm nóng giòn lại bằng nồi chiên không dầu ở 180°C trong 6–8 phút.', 'chinese', 'mon_chien', NULL, 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Sườn non","Giòn rụm","Ngũ vị hương","Cơm nhà"]', '["lunch","dinner"]', '["deep_fry"]', '["egg","molluscs","pork","soybean","wheat"]', 522, 522.1, 2185, 23.2, 35.3, 11.1, 26.9, 1.2, 2.4, 1179, 2.95, '["Five Spice USDA Ref","Panko / Batter Mix Ref","USDA FDC 167861","USDA FDC 169230","USDA FDC 169655","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '6b6b65f49d20c5877f58b95c115bd4c6ed66c6050a13642e1399c839ec181a14', 'ffdc230151157ecaee29db8d31d2faf6dcb64141d34a42b4a58b975f8c715de6', 4),
('imp-b4924a7d33d5acff', 'chao-trung-trung', 448, 'Cháo trứng vân mây kiểu Hoa', 'Cháo trắng ninh nhừ sánh mịn rưới dòng trứng gà đánh tan tạo vân hoa mềm mượt, điểm hành lá, gừng sợi và tiêu trắng ấm bụng', 'Nồi cháo trắng sánh nhừ bông mịn kiểu Hoa với những sợi vân trứng gà vàng óng mềm mượt hòa quyện, thoang thoảng mùi tiêu trắng ấm nồng, hành lá tươi và chút xì dầu nhạt dịu vị.', 'Múc cháo nóng ra tô, rắc gừng tươi thái sợi và hành lá xanh; dọn kèm chén xì dầu nhạt để mỗi người tự nêm thêm theo khẩu vị.', 'Cháo để nguội sẽ đặc lại; bảo quản hộp kín trong ngăn mát tối đa 2 ngày và khi hâm nóng hãy thêm chút nước sôi khuấy đều trên lửa nhỏ.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 15, 45, 3, '/frigo/illustrations/delicious-meal.png', '["Cháo nóng","Trứng gà","Bữa sáng","Dễ tiêu","Thanh nhẹ"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","soybean","wheat"]', 268, 268, 1121, 9.6, 6.1, 1.7, 42.2, 1.2, 0.6, 1083, 2.71, '["USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '72871a2fc746552ac6e78133bc0ed9bcd2492780c7b69628ed27fb2f12f7a63c', '71bfca88335e031c523fcfc1ee4d25cf3fef4a58432f94a506be3462ddcc2bb1', 4),
('imp-4a712c9f5f9913be', 'mi-tom-nong', 449, 'Mì nước tôm tươi gừng hành', 'Tô mì trứng dai ngon chan nước dùng gà trong ngọt thanh, thơm gừng tỏi phi với tôm tươi săn ngọt, cải thìa và nấm giòn tươi', 'Tô mì nước nóng hổi kiểu Hoa với nước dùng gà thanh ngọt quyện hương gừng tỏi phi dịu nhẹ, sợi mì trứng dai mềm ăn kèm tôm tươi săn giòn, cải thìa xanh mướt và nấm thái lát.', 'Múc mì, tôm và rau ra tô sâu lòng, chan ngập nước dùng nóng hổi, rưới chút dầu mè thơm và rắc hành lá tươi; dùng ngay khi còn nóng.', 'Nên nấu và dùng ngay để mì không bị trương nở và tôm giữ độ giòn ngọt; nếu bảo quản tủ mát tối đa 24 giờ, nên để riêng mì với nước dùng rồi đun sôi lại phần nước dùng trước khi chan.', 'chinese', 'mon_bun_pho', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì nước","Tôm tươi","Bữa sáng","Thanh ngọt","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["crustaceans","egg","sesame","shrimp","soybean","wheat"]', 393, 393.3, 1646, 32, 8.3, 1.5, 47.8, 2.9, 2.8, 1826, 4.57, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 170005","USDA FDC 170390","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '77dfdf08c281b1e059a2f0efb33b0e5de7af05b5b06ee6880b516b5947da74aa', '9112bf61989ba5f5c8413a0bfd440dad5c25784e59b73e9429b94a93a86098f0', 4),
('imp-a27445c786a3fd67', 'com-bo-donburi', 450, 'Cơm bò Gyudon Nhật Bản', 'Thịt bò thái lát mỏng om mềm cùng hành tây ngọt dịu trong nước dùng Dashi xì dầu Mirin Sake, phủ lên cơm trắng nóng và hành lá trứ danh Nhật Bản', 'Tô cơm bò Gyudon trứ danh của Nhật Bản với từng lát thịt bò mềm mọng thấm đẫm nước sốt ngọt mặn cân bằng từ Dashi, xì dầu Nhật, rượu Sake và Mirin, hòa cùng hành tây thái lát chín mềm đặt trên cơm trắng hạt ngắn nóng hổi.', 'Xới cơm trắng nóng ra 3 tô lớn, chan một ít nước sốt om xuống cơm trước rồi gắp thịt bò và hành tây phủ đều lên mặt, rắc hành lá và ăn kèm gừng tươi thái sợi mỏng.', 'Nếu còn dư, bảo quản riêng phần thịt bò nước sốt và cơm trong hộp kín ở ngăn mát tối đa 2–3 ngày; khi ăn chỉ cần đun nóng lại phần bò trên lửa nhỏ 2–3 phút rồi chan lên cơm vừa hâm nóng.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Gyudon","Cơm bò Nhật","Donburi","Bữa trưa nhanh","Nhật Bản"]', '["lunch","dinner"]', '["simmer","assemble"]', '["beef","fish","soybean","wheat"]', 578, 577.5, 2417, 31.6, 12.8, 4.8, 75.9, 1.8, 14.4, 1420, 3.55, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168878","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 174277"]', '17301b1ed091904c487ee0f6e50f09c9ff061f1e11d5505189ed26287c6a592d', '9e61ebe8f64df677ec53eba0498922451bec17b3c3c6ae04c9b8da5627eb1bd0', 4),
('imp-aba623dc468a9569', 'canh-ca-nam-nhat', 451, 'Canh cá hồi nấu nấm kiểu Nhật', 'Canh trong nước dùng tảo bẹ Kombu nấu cùng phi lê cá hồi chần khử tanh kiểu Shimofuri, nấm đùi gà, gừng lát, rượu Sake và xì dầu Nhật thanh ngọt', 'Tô canh cá hồi nấu nấm kiểu Nhật trong vắt và thanh nhẹ với nước dùng ngâm tảo bẹ Kombu ngọt umami tự nhiên, thịt cá hồi phi lê xử lý chần sơ kiểu Shimofuri hoàn toàn không tanh, kết hợp nấm đùi gà và hương gừng rượu Sake ấm áp.', 'Múc canh nóng ra 4 bát, chia đều các miếng cá hồi và nấm đùi gà, thả hành lá lên trên để dậy mùi thơm; dùng nóng kèm cơm trắng hoặc các món kho mặn.', 'Canh ngon nhất khi ăn nóng trong ngày; nếu bảo quản tủ mát tối đa 1–2 ngày, hâm nóng nhẹ trên lửa nhỏ đến khi vừa sôi lăn tăn, tránh khuấy mạnh làm vỡ miếng cá hồi.', 'japanese', 'mon_canh', NULL, 'easy', 20, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Canh cá Nhật","Cá hồi","Nấm đùi gà","Tảo bẹ Kombu","Thanh ngọt"]', '["lunch","dinner"]', '["simmer"]', '["fish","salmon","soybean","wheat"]', 238, 238.1, 996, 22.9, 13.7, 3.1, 4.4, 1.4, 0.8, 871, 2.18, '["MEXT Sake 16021","USDA FDC 168457","USDA FDC 168580","USDA FDC 169231","USDA FDC 170005","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175167"]', '7c3c4687425844448aeff9f8d62f16bcdde03c954e0ed7fecbe1a8e11b931541', '8b12d93532906aedb8027ff4142ac10debcad55aab1a165c5f810e14f9e8b916', 4),
('imp-4f398ac575200416', 'mi-udon-ca-ri', 452, 'Mì Udon cà ri gà Nhật Bản', 'Sợi mì Udon dai mượt chan nước sốt cà ri Nhật sánh đậm từ viên cà ri, nước dùng Dashi, đùi gà mềm ngọt, cà rốt và hành tây ấm nồng', 'Tô mì Udon cà ri gà chuẩn vị Nhật Bản kết hợp sợi mì lúa mì bản to dai mềm với phần nước dùng cà ri sánh mượt đậm đà từ nước dùng Dashi, viên cà ri Nhật, xì dầu, rượu Sake cùng thịt đùi gà và rau củ ngọt thanh.', 'Xếp mì Udon vừa trụng nóng vào 3 tô sâu lòng, chan ngập nước cà ri gà nóng hổi lên trên, rắc hành lá xanh thái khoanh; có thể ăn kèm một ít ớt bột 7 vị nếu thích vị cay ấm.', 'Mì Udon nên luộc và dùng ngay để sợi giữ độ dai; phần nước cà ri gà thừa có thể bảo quản hộp kín ngăn mát tối đa 3 ngày, khi ăn hâm nóng lại với ít nước lọc và trụng mì mới.', 'japanese', 'mon_bun_pho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Cà ri Nhật","Đùi gà","Món nước ấm","Nhật Bản"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","fish","soybean","wheat"]', 654, 653.5, 2734, 31.9, 27.7, 8.5, 64.6, 5.1, 6.6, 1827, 4.57, '["MEXT Boiled/Fresh Udon","MEXT Curry Roux Ref","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', '029fd3635ce1534f94d1d3cbb7de905d4cd98c429ae0a9d02e68f2fae2076b7d', '77a607c294bce2aff865c1ed6488ac5264ed289ddd06d63cd2c0dbe4802aa0a1', 4),
('imp-b8731e057182331b', 'bap-cai-tron-me-nhat', 453, 'Bắp cải trộn mè rang kiểu Nhật', 'Bắp cải thái sợi bóp muối vắt ráo giòn mát trộn cùng hạt mè trắng rang giã dập, xì dầu Nhật, dầu mè, giấm gạo và hành lá thanh vị', 'Món rau phụ bắp cải trộn mè kiểu Nhật thanh mát và giòn sần sật: bắp cải thái sợi được ủ nhẹ với muối cho mềm giòn tự nhiên rồi trộn đều trong hỗn hợp mè trắng rang giã dập quyện xì dầu Nhật, đường, dầu mè thơm và giấm gạo.', 'Bày bắp cải trộn mè ra đĩa nhỏ, rắc thêm chút mè nguyên hạt lên mặt; dùng mát làm món rau phụ giải ngấy rất hợp bên cạnh thịt nướng, cá chiên hoặc cơm cà ri.', 'Món trộn ngon nhất khi dùng trong ngày để giữ độ giòn tươi của bắp cải; có thể bảo quản ngăn mát tối đa 1–2 ngày trong hộp kín và chắt bớt nước tiết ra nếu có trước khi ăn.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn Nhật","Bắp cải","Mè rang","Rau phụ","Giòn mát"]', '["lunch","dinner"]', '["toss_mix"]', '["sesame","soybean","wheat"]', 109, 108.8, 456, 3.4, 5.6, 0.8, 13.4, 4.3, 7.9, 428, 1.07, '["USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 172238","USDA FDC 173468","USDA FDC 174277"]', '2224bcbe84f1f5d3b9be274976e4a2b31b7f312643beafadfb4e833491a08a32', 'a27cf0b9a5c4235a5918ce66936cce8739d838d7442dfa01dd6209b498e25ec8', 4),
('imp-f04b28987d7cd34a', 'cua-nuong-muoi-nhat', 454, 'Cua nướng muối biển kiểu Nhật', 'Chân cua biển cắt hở nửa vỏ ướp rượu Sake, muối hạt và quết nhẹ bơ lạt nướng than hồng cháy cạnh thơm lừng vị biển Hokkaido, chấm xì dầu chanh tươi', 'Món cua nướng muối kiểu Nhật (Yaki-kani) trứ danh vùng Hokkaido: từng thớ thịt cua biển tươi ngọt mọng nước được bảo vệ bởi lớp vỏ nướng xém cùng muối biển, rượu Sake và chút bơ lạt thơm béo, ăn kèm chanh vàng tươi và xì dầu.', 'Dọn cua nướng muối còn nóng hổi ra đĩa lớn, rắc thêm hành lá xanh và xếp các múi chanh vàng bên cạnh; khi ăn vắt chanh tươi lên thịt cua và chấm thêm xì dầu Nhật nếu thích.', 'Cua nướng ngon nhất khi thưởng thức nóng ngay tại bàn; nếu còn thừa, tách lấy phần thịt cua bảo quản hộp kín trong ngăn mát tối đa 1 ngày và áp chảo làm nóng nhanh với chút bơ trước khi dùng.', 'japanese', 'mon_lau_tiec', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Cua nướng muối","Hải sản Nhật","Tiệc nướng","Hokkaido","Cao cấp"]', '["lunch","dinner"]', '["grill_roast"]', '["crab","crustaceans","milk","soybean","wheat"]', 142, 141.5, 592, 20.6, 4.9, 2.6, 2.1, 0.5, 0.5, 939, 2.35, '["MEXT Sake 16021","USDA FDC 167746","USDA FDC 170005","USDA FDC 173430","USDA FDC 173468","USDA FDC 174208","USDA FDC 174277"]', '1dff837557626b9103ea8365e94224e7fdacb9f319f1f89a53b44c8ec3d79627', '00a37d510676eb95f279699e8e9c5315bc82cb21205f26cead47876f4b72f533', 4),
('imp-bf6c9c4d92b2e04c', 'tom-om-gung-nhat', 455, 'Tôm om gừng nước tương kiểu Nhật', 'Tôm tươi nguyên con om mềm đậm vị trong nước dùng Sake Mirin xì dầu Nhật và gừng thái lát thơm ấm nồng, dùng nóng chan cơm cực kỳ đưa miệng', 'Món tôm om gừng Shogani kiểu Nhật Bản với những con tôm tươi săn giòn, đỏ au đẹp mắt thấm đẫm nước sốt om ngọt mặn hài hòa từ xì dầu Nhật, rượu Sake, Mirin, đường và hương gừng tươi cay ấm.', 'Gắp tôm om ra đĩa sâu lòng, rưới 2–3 muỗng canh nước om ấm lên trên, phủ gừng thái sợi mảnh cùng hành lá xanh; dùng nóng kèm cơm trắng dẻo.', 'Có thể bảo quản phần tôm và nước om trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn chỉ cần hâm nóng nhẹ trên lửa nhỏ khoảng 2 phút hoặc thưởng thức nguội theo kiểu món nguội Nhật cũng rất ngon.', 'japanese', 'mon_kho', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Tôm tươi","Gừng tươi","Nhanh gọn","Đưa cơm"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","shrimp","soybean","wheat"]', 162, 162, 678, 17.2, 0.6, 0.1, 17.1, 0.5, 13.1, 973, 2.43, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '1494c153a97c61068bd81c0f6a34af390048665377a77ee56a46a0f3d9279865', '11afc0db5d6c391c184f4a77aa5b8af750777e4ce386e0eb88c08db55dadde91', 4),
('imp-92aabff659e3c551', 'ga-xao-toi-han', 456, 'Gà xào sốt tỏi Hàn Quốc', 'Thịt đùi gà rút xương áo bột áp chảo vàng giòn, phủ đều lớp sốt tỏi băm mật ong xì dầu óng ả đậm đà cực kỳ đưa cơm', 'Món gà xào sốt tỏi kiểu Hàn hấp dẫn với từng miếng thịt đùi gà rút xương ngoài giòn rụm, bên trong mọng nước, quyện đều lớp sốt tỏi băm mật ong, giấm gạo và xì dầu đặc sánh bóng thơm lừng.', 'Bày gà xào sốt tỏi ra đĩa lớn, rưới phần sốt sánh còn lại trong chảo lên trên, rắc hành lá thái nhỏ và mè trắng rang; dùng nóng cùng cơm trắng và củ cải muối.', 'Món ngon nhất khi dùng nóng ngay để cảm nhận lớp vỏ giòn; phần thừa bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu 170°C trong 4 phút hoặc đảo nhanh trên chảo.', 'korean', 'mon_xao', NULL, 'easy', 15, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Thịt gà","Món xào","Sốt tỏi","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["chicken","sesame","soybean","wheat"]', 444, 444.4, 1860, 29.3, 20.5, 4.9, 34.9, 1.1, 17, 1071, 2.68, '["Dark Soy Sauce Label Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169640","USDA FDC 169698","USDA FDC 169761","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171319","USDA FDC 171325","USDA FDC 171413","USDA FDC 172238","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647"]', 'f2d3a38f7f9578cbe8c6248e0a1a514c23f23f8ad1fc6fc3d9e959e1e4d89e20', '0fc2b61f8edd3d9ad573942afa7b3473dfec799c267590e4509bd76d9e7893a9', 4),
('imp-4b592ae31a81a527', 'bo-kho-tuong-han', 457, 'Thịt bò kho tương Hàn Quốc', 'Thịt bò hầm mềm tơi xé dọc thớ thấm đẫm nước tương mặn ngọt cùng tỏi nguyên tép và ớt sừng thơm lừng chuẩn món Jangjorim', 'Món thịt bò kho tương Hàn Quốc (Jangjorim) mang hương vị mặn ngọt đậm đà đặc trưng: thịt thăn bò được hầm mềm rồi xé dọc thớ thấm vị xì dầu, ăn kèm tỏi kho bùi béo và ớt sừng cay dịu rất bắt cơm.', 'Xếp các thớ thịt bò xé ra đĩa sâu lòng cùng tỏi kho và ớt sừng, rưới nước kho sánh đậm lên trên; ăn nóng hoặc nguội cùng cơm trắng dẻo.', 'Món kho mặn giúp bảo quản rất tốt trong hộp kín ở ngăn mát tủ lạnh đến 5–7 ngày; khi ăn chỉ cần gắp lượng vừa đủ hâm nóng lại cho tan mỡ.', 'korean', 'mon_kho', NULL, 'medium', 15, 75, 5, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt bò","Nước tương","Hàn Quốc","Cơm nhà"]', '["lunch","dinner"]', '["boil","braise"]', '["beef","soybean","wheat"]', 248, 248.3, 1039, 25.3, 11.9, 4.5, 9.5, 0.5, 6, 1489, 3.72, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170931","USDA FDC 173647","USDA FDC 174277"]', '0716880b968e8f3486ee16ac356efc7294374b8f322929723e2a32459b3ed90f', '1def3af2778313e504838c2fd330838750b0dd3ac3838098d5416eeb9da2b2a4', 4),
('imp-72e70eb4e8fba4db', 'tom-xao-kim-chi', 458, 'Tôm xào kim chi Hàn Quốc', 'Tôm tươi áp chảo bơ tỏi gừng săn ngọt, xào nhanh cùng kim chi chua cay, cải thảo giòn và ớt chuông đỏ đậm vị đưa cơm', 'Đĩa tôm xào kim chi Hàn Quốc bắt mắt với thịt tôm hồng tươi giòn ngọt thấm hương bơ tỏi gừng, quyện cùng kim chi cải thảo chua cay nhẹ, cải thảo giòn sần sật và ớt chuông đỏ rực.', 'Trút tôm xào kim chi ra đĩa, rắc thêm hành lá và hạt mè trắng rang; thưởng thức nóng ngay cùng cơm trắng dẻo.', 'Tôm xào ngon nhất khi ăn ngay lúc vừa nấu xong; nếu bảo quản ngăn mát tối đa 24 giờ, chỉ đảo nóng nhanh 1–2 phút trên chảo lửa vừa để tôm không bị dai.', 'korean', 'mon_xao', NULL, 'easy', 20, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Tôm tươi","Kim chi","Hàn Quốc","Bữa tối nhanh"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["crustaceans","milk","sesame","shrimp","soybean","wheat"]', 266, 265.9, 1113, 29.3, 14.2, 5.4, 7.6, 2.7, 2.8, 1255, 3.14, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169977","USDA FDC 170005","USDA FDC 170108","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', 'adde2cf414ee9f879fa041bdd8ba5fe561a7ff99789a15f1afccdc543336f515', 'b231514a60a11ef1276e537e2c5129538e168ebe74049ff174250f04375de99e', 4),
('imp-88b58c0233dec53e', 'trung-xao-kim-chi', 459, 'Trứng xào kim chi Hàn Quốc', 'Trứng gà đánh bông chiên mềm mịn quyện cùng kim chi cải thảo xào thơm cay dịu và hành lá tươi mát cho bữa cơm 10 phút', 'Đĩa trứng xào kim chi mềm mịn tan trong miệng với từng mảng trứng vàng ươm béo nhẹ xen lẫn kim chi cải thảo chua cay giòn sần sật, cực kỳ gọn nhẹ cho bữa sáng hoặc bữa tối bận rộn.', 'Gạt trứng xào kim chi ra đĩa ấm ngay khi vừa chín tới, rắc hành lá thái nhỏ và hạt mè trắng rang; dùng nóng kèm cơm trắng hoặc bánh mì nướng.', 'Món trứng xào ngon nhất khi thưởng thức ngay sau khi nấu để giữ độ mềm mướt; không nên hâm đi hâm lại nhiều lần vì trứng sẽ bị khô xác.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 5, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món nhanh","Trứng gà","Kim chi","Hàn Quốc","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","sesame","soybean","wheat"]', 204, 203.6, 852, 12.1, 15.9, 3.8, 3.1, 1.3, 1.1, 677, 1.69, '["USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '0eb7170993398c3f7bad14095422a4414e07733eb7aee9543591d2998064a70c', '3d2afb61c7731f4dc6263b88d24dda2637ee36530691568a9fb2feaa432177db', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-e5d49dd8dc1449d1', 'ba-chi-kho-kim-chi', 460, 'Thịt ba chỉ kho kim chi Hàn Quốc', 'Thịt ba chỉ heo kho mềm béo ngậy cùng kim chi lên men chua sâu, tương Doenjang và bột ớt Hàn trong nước kho sánh đậm', 'Nồi thịt ba chỉ kho kim chi Hàn Quốc (Kimchi Jjim) đậm đà quyến rũ với từng miếng ba chỉ ninh mềm tan béo ngậy, thấm trọn vị chua cay nồng nàn của kim chi lên men kỹ và hương tương đậu Doenjang trầm ấm.', 'Dùng kéo cắt kim chi thành khúc vừa ăn ngay trong nồi, rắc hành lá và ớt sừng thái lát lên trên; dọn nóng cùng cơm trắng và trứng cuộn hoặc đậu phụ trắng.', 'Thịt ba chỉ kho kim chi bảo quản hộp kín trong ngăn mát tủ lạnh đến 4 ngày hoặc cấp đông 1 tháng; khi hâm nóng lại trên lửa nhỏ hương vị càng ngấm sâu và ngon hơn.', 'korean', 'mon_kho', NULL, 'easy', 15, 65, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Ba chỉ heo","Kim chi","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["braise"]', '["pork","soybean","wheat"]', 704, 704, 2945, 14.8, 65, 23.4, 14.9, 4.3, 8.1, 1331, 3.33, '["Korean Chili Flake Ref","Korean Doenjang Ref","MEXT Hon-Mirin 16031","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170497","USDA FDC 170931","USDA FDC 173647","USDA FDC 174277"]', '0909709f7910e43ddb2e20804ed638cb82433aff0a70b52132f0840e8cc012d7', 'd4cdb1144995af63ed21fb08ff35ac41e6806d2581134cdfbd12c688fa08e0d9', 4),
('imp-daec3b038c4f43af', 'ca-nuong-tuong-han', 461, 'Cá thu nướng chấm tương Hàn Quốc', 'Cá thu nướng vỉ da vàng giòn thơm thịt trắng ngọt béo, rưới nước tương xì dầu tỏi ớt chanh tươi kiểu Hàn', 'Món cá thu nướng kiểu Hàn hấp dẫn với lớp da cá giòn rụm vàng ươm, phần thịt bên trong trắng mềm béo ngậy giữ trọn vị ngọt tự nhiên, kết hợp nước chấm xì dầu tỏi ớt chanh tươi cân bằng vị béo rất bắt cơm.', 'Bày cá thu nướng ra đĩa dài, rưới một nửa chén nước tương chấm lên thân cá và rắc ngò rí thái nhỏ; phần nước chấm còn lại để riêng chấm kèm cơm trắng nóng.', 'Cá nướng ngon nhất khi dùng nóng ngay vừa ra lò; phần dư bảo quản ngăn mát tối đa 2 ngày và làm nóng lại trong nồi chiên không dầu hoặc lò nướng 180°C khoảng 5 phút để da giòn lại.', 'korean', 'mon_chien', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Cá nướng","Cá thu","Hàn Quốc","Nước chấm tương","Bữa cơm gia đình"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","mackerel","sesame","soybean","wheat"]', 360, 360, 1507, 26.2, 26, 5.4, 3.7, 0.9, 0.5, 1394, 3.49, '["Korean Chili Flake Ref","MEXT Sake 16021","USDA FDC 168155","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175119"]', 'a3a1750e81f4fb71526aeacba7648a34e22a04792bfdc4527e051721f73a2d71', 'c74715e81e8ed5e412fca257bf5e51af8241f53cd4292bbef2ebce790200bdf7', 4),
('imp-4ca7d6f55d5b7937', 'mi-xao-bo-han', 462, 'Miến xào thịt bò Hàn Quốc (Japchae)', 'Miến khoai lang Hàn dai bóng trộn đều cùng thịt bò thăn xào mềm, nấm hương, rau chân vịt và cà rốt thấm sốt xì dầu mè thơm', 'Đĩa miến trộn Japchae Hàn Quốc óng ả sắc màu với sợi miến khoai lang dai mềm quyện hương dầu mè rang và đường nâu ngọt dịu, kết hợp thịt thăn bò mềm thơm cùng nấm hương, rau chân vịt, cà rốt và hành tây giòn ngọt.', 'Bày miến xào thịt bò ra đĩa lớn, rắc thêm chút hạt mè trắng rang; thưởng thức nóng hoặc ở nhiệt độ phòng đều giữ nguyên độ dai ngon.', 'Japchae bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi hâm nóng bằng lò vi sóng hoặc đảo nhanh trên chảo với 1 muỗng canh nước lọc, sợi miến sẽ mềm bóng trở lại.', 'korean', 'mon_xao', NULL, 'medium', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Miến xào","Thịt bò","Japchae","Hàn Quốc","Tiệc gia đình"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["beef","sesame","soybean","wheat"]', 459, 459.1, 1921, 12.7, 18.8, 3.7, 61.4, 3.4, 11.2, 1140, 2.85, '["USDA FDC 168462","USDA FDC 168833","USDA FDC 168952","USDA FDC 169230","USDA FDC 169251","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '25e57b7467398768c010fd75a6a6fd6abbb6417c125a6bb14564cbe5080ddc08', '7eea0f32b7f575337889e28bf644d6213b3da063a0f2e4565f217274538013d4', 4),
('imp-09e07baa201acf28', 'chao-tom-han', 463, 'Cháo tôm Hàn Quốc (Saewoo-juk)', 'Cháo gạo tẻ rang dầu mè ninh sánh mịn cùng tôm tươi giòn ngọt, cà rốt, hành tây, vân trứng gà béo nhẹ và rong biển nướng vụn', 'Tô cháo tôm Saewoo-juk kiểu Hàn sánh mịn mượt mà với hạt gạo rang dầu mè thơm bùi, thịt tôm tươi thái nhỏ ngọt tự nhiên cùng cà rốt, hành tây, vân trứng gà mềm mịn và rong biển nướng giòn rắc mặt.', 'Múc cháo nóng ra tô, rắc rong biển lá khô bóp vụn cùng hạt mè trắng rang giã dập lên trên; thưởng thức ngay khi còn nóng, ăn kèm kim chi củ cải nếu thích.', 'Cháo thừa bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi hâm nóng hãy thêm khoảng 50–100 ml nước lọc khuấy đều trên lửa nhỏ đến khi sôi sánh trở lại.', 'korean', 'mon_canh', NULL, 'easy', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món cháo","Tôm tươi","Hàn Quốc","Ấm bụng","Dễ tiêu"]', '["breakfast","lunch","dinner"]', '["stir_fry","simmer"]', '["crustaceans","egg","fish","sesame","shrimp"]', 328, 327.6, 1371, 18.6, 7.7, 1.5, 45.4, 2.1, 2.3, 895, 2.24, '["USDA FDC 168456","USDA FDC 169230","USDA FDC 169756","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '16eeb2e459bbaebf306011de98dd4c25b25ce5e7e6793b916e8a534c8c08e783', 'e660f7b1b27b31cf59f2ba5206101ae146d0b2de29928bf4156827e8174fb158', 4),
('imp-9c2f22829fd3d3f1', 'bo-xao-kim-chi', 464, 'Thịt bò xào kim chi Hàn Quốc', 'Thịt thăn bò thái lát mỏng xào lửa lớn mềm ngọt cùng kim chi cải thảo chua cay, hành tây giòn thơm và sốt mật ong dầu hào', 'Đĩa thịt bò xào kim chi Hàn Quốc hấp dẫn với từng lát thịt thăn bò mềm ẩm thấm gia vị, kết hợp hoàn hảo cùng kim chi cải thảo chua cay đậm đà và hành tây giòn ngọt quyện sốt mật ong dầu hào bóng đẹp.', 'Trút thịt bò xào kim chi ra đĩa, rắc thêm hành lá và hạt mè trắng rang lên trên; thưởng thức ngay khi còn nóng hổi với cơm trắng dẻo.', 'Món xào ngon nhất khi ăn nóng ngay; nếu bảo quản hộp kín trong ngăn mát tối đa 2 ngày, chỉ đảo nóng nhanh trên chảo lửa lớn 1–2 phút để thịt bò giữ được độ mềm.', 'korean', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Kim chi","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","sesame","soybean","wheat"]', 278, 278.4, 1165, 20.2, 17.3, 4.7, 11.1, 2, 6.5, 982, 2.46, '["USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '0000f56f952196fb4951018982dc644e3fc8487db7b07e6d4ccebfd4b08e4415', '17b9200720f3d0e7ff6450b400d256a007d4160638732643d7d6c4e4fd14f673', 4),
('imp-d7b9a40e678c0e29', 'ga-nuong-muoi-han', 465, 'Gà nướng muối kiểu Hàn', 'Đùi gà rút xương còn da áp chảo không dầu vàng giòn rụm với muối tiêu, ăn kèm hành lá nướng xém, tỏi nguyên tép và chanh tươi', 'Món gà nướng muối kiểu Hàn (Dak-sogeum-gui) giản dị mà cực kỳ cuốn hút: thịt đùi gà rút xương được áp chảo tự tiết mỡ giúp lớp da mỏng giòn tan, thịt bên trong ngọt mọng quyện hành lá tỏi nướng xém thơm nức.', 'Thái gà thành miếng vừa ăn xếp ra đĩa cùng hành lá và tỏi nướng xém vàng, vắt thêm múi chanh tươi và chấm muối tiêu dầu mè rang.', 'Gà nướng da giòn ngon nhất khi dùng nóng ngay sau khi chế biến; nếu còn dư có thể cất ngăn mát tối đa 2 ngày và quay nóng bằng nồi chiên không dầu 180°C trong 4–5 phút.', 'korean', 'mon_chien', NULL, 'easy', 15, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Gà nướng","Đùi gà","Hàn Quốc","Da giòn","Bữa cơm gia đình"]', '["lunch","dinner"]', '["pan_fry","grill_roast"]', '["chicken","sesame"]', 384, 384.2, 1608, 37.1, 23.7, 6, 4.1, 0.9, 0.5, 855, 2.14, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 172385","USDA FDC 173468"]', '102b728313bb05c99ee4f9fac01a232cef02e254917eca0a0bce1b8779d73d12', '31d066809a882c198f2ce5dd04ea1fd1a299db92d0288bcf551a5a26f6bfead1', 4),
('imp-2b289d9040d46110', 'dau-phu-kho-gung-han', 466, 'Đậu phụ kho gừng kiểu Hàn', 'Từng miếng đậu phụ chiên vàng hai mặt kho thấm sốt xì dầu gừng băm sánh đậm, thơm dịu dầu mè cho bữa cơm chay thanh đạm', 'Đĩa đậu phụ kho gừng Hàn Quốc (Dubu Jorim) thơm nức mùi gừng tỏi xào quyện nước tương xì dầu mặn ngọt hài hòa, miếng đậu bên ngoài săn vàng thấm vị mà bên trong vẫn giữ được độ mềm béo thanh tao.', 'Xếp các miếng đậu phụ kho ra đĩa, rưới phần sốt sệt còn lại trong chảo lên trên rồi rắc hạt mè trắng rang và hành lá; dùng nóng hoặc nguội với cơm trắng đều rất bắt vị.', 'Món đậu kho bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 3 ngày như một món ăn kèm (banchan); có thể ăn nguội trực tiếp hoặc hâm nóng lại với 1 muỗng canh nước lọc trên chảo.', 'korean', 'mon_chay', NULL, 'easy', 12, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Đậu phụ","Món kho","Gừng tươi","Hàn Quốc"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 259, 258.7, 1082, 16.1, 18.5, 2.7, 11.6, 2.5, 5.9, 772, 1.93, '["Korean Chili Flake Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', '2bd3f02b85403aa9e7f3f1dbd88b814865d14733a55541bf598acf7ca184fc80', '5a134208b11c73dcf60cc4847b9a0739b23e05c9405bc9e057fd13eaa4ea3314', 4),
('imp-7cb7368109956ad5', 'canh-kim-chi-gia', 467, 'Canh kim chi giá đỗ Hàn Quốc', 'Nước canh kim chi chua cay trong thanh kết hợp cùng giá đỗ giòn ngọt và nước dùng cá cơm tảo bẹ giúp giải nhiệt ấm bụng', 'Tô canh kim chi giá đỗ (Kimchi Kongnamul-guk) nóng hổi thanh nhẹ mà đậm đà: giá đỗ giữ nguyên độ giòn ngọt tự nhiên hòa quyện nước dùng cá cơm tảo bẹ cùng vị chua cay dịu của kim chi chín kỹ.', 'Để canh nghỉ 2–3 phút sau khi tắt bếp cho vị ngọt sâu rồi múc ra tô, rắc hành lá xanh lên trên; ăn nóng kèm cơm trắng hoặc chan trực tiếp thành canh cơm.', 'Nên dùng hết trong ngày để giá đỗ giữ độ giòn tươi; phần thừa bảo quản ngăn mát tối đa 24 giờ và đun sôi nhanh trên lửa vừa trước khi dùng.', 'korean', 'mon_canh', NULL, 'easy', 10, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Kim chi","Giá đỗ","Hàn Quốc","Thanh mát"]', '["breakfast","lunch","dinner"]', '["stir_fry","simmer"]', '["fish","sesame","soybean","wheat"]', 124, 123.8, 519, 8, 5.7, 0.8, 12.6, 3.6, 5.4, 1569, 3.92, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170497","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277"]', 'db9df6ee08293cb66776f5dbe9956c8946bc23229f6f9b0db8256405a7b636f2', 'aeda83fb5c044d099f78f38967f596cc3490b9811ad2ce21c219629ecabfa0a2', 4),
('imp-a3e676be13c4c51c', 'bo-ham-nam-han', 468, 'Thịt bò hầm nấm Hàn Quốc', 'Thịt bò thái mỏng ướp sốt Bulgogi mềm ngọt nấu cùng nấm đùi gà, nấm hương, cải thảo và miến khoai lang trong nước dùng thanh ngọt', 'Nồi thịt bò hầm nấm Hàn Quốc (Beoseot Bulgogi Jeongol) ấm áp sang trọng với nước dùng tảo bẹ củ cải trong ngọt, kết hợp thịt thăn bò ướp sốt đậm đà cùng nấm đùi gà, nấm hương, rau củ tươi và miến khoai lang dai mềm.', 'Đặt nồi hầm nóng ngay giữa bàn ăn, rắc hành lá lên trên để mọi người vừa gắp thịt bò và nấm vừa chan nước dùng thanh ngọt ăn cùng cơm trắng.', 'Nếu còn dư, vớt riêng phần miến khoai lang để không bị nở nát; bảo quản thịt, nấm và nước dùng trong ngăn mát tối đa 2 ngày và đun sôi lại khi ăn.', 'korean', 'mon_lau_tiec', NULL, 'medium', 25, 30, 5, '/frigo/illustrations/delicious-meal.png', '["Món hầm","Thịt bò","Nấm tươi","Hàn Quốc","Lẩu gia đình"]', '["lunch","dinner"]', '["simmer"]', '["beef","sesame","soybean","wheat"]', 354, 353.6, 1480, 25, 13.9, 4.6, 32.7, 3.2, 10.6, 1164, 2.91, '["MEXT Hon-Mirin 16031","USDA FDC 168452","USDA FDC 168457","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169251","USDA FDC 169640","USDA FDC 169655","USDA FDC 169977","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'ce065df0b1e804d11dbf0b4a0cdb5af0de80a141a9d49beede8d10a24ccfb081', '99c900d7ef4f7503c5edafc77f98cbe87145a5f36a9c1af85c83a4f54401c262', 4),
('imp-1b54108818405e6a', 'com-chien-ba-chi-kim-chi', 469, 'Cơm chiên ba chỉ kim chi Hàn Quốc', 'Cơm trắng rang săn hạt cùng thịt ba chỉ xém cạnh béo giòn, kim chi chua cay, sốt Gochujang và trứng ốp la lòng đào', 'Món cơm chiên ba chỉ kim chi Hàn Quốc (Kimchi Bokkeumbap) đậm đà khó cưỡng với từng hạt cơm săn tơi phủ màu đỏ cam bắt mắt của tương ớt Gochujang, quyện thịt ba chỉ chiên xém béo giòn, kim chi chua cay và trứng ốp la lòng đào.', 'Nén nhẹ cơm chiên ra chén rồi úp ra đĩa, đặt trứng ốp la lên trên, rắc thêm hành lá xanh, hạt mè trắng rang và rong biển cắt sợi để thưởng thức nóng.', 'Cơm chiên ngon nhất khi dùng nóng ngay vừa ra chảo; phần thừa bảo quản hộp kín trong ngăn mát tối đa 2 ngày và đảo nóng lại trên chảo chống dính với lửa vừa.', 'korean', 'mon_xao', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Ba chỉ heo","Kim chi","Hàn Quốc","Bữa tối nhanh"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","pork","sesame","soybean","wheat"]', 740, 740.2, 3097, 18.8, 45.1, 14.4, 63.3, 2.9, 3.7, 1276, 3.19, '["USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 168456","USDA FDC 168878","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', 'f4b8185c520b79aee5819e91f65ff314451a9500354614bf83cbca076d13a949', 'dcf5a4f70d4941352e968c9c7e10795b151dad4d64efb096369f71b194954208', 4),
('imp-9328a098d7bd1f6f', 'ga-nuong-chanh-ot', 470, 'Gà nướng chanh ớt kiểu Thái (Gai Yang)', 'Đùi gà góc tư ướp nước mắm, tỏi, ớt hiểm và nước cốt chanh nướng vàng giòn lớp da, thịt bên trong mọng nước đậm đà', 'Món gà nướng chanh ớt kiểu Thái hấp dẫn với từng chiếc đùi gà góc tư da vàng óng giòn rụm, thịt thớ mềm mọng thấm đẫm hương vị chua thanh của nước cốt chanh, mặn thơm nước mắm cùng vị cay nồng ấm của tỏi và ớt hiểm.', 'Chặt đùi gà nướng thành miếng vừa ăn hoặc để nguyên chiếc, rắc hành lá thái nhỏ; dọn nóng cùng xôi nếp hoặc cơm trắng, xà lách, dưa leo và chén tương ớt chấm kèm.', 'Thưởng thức nóng ngay sau khi nướng để lớp da giữ độ giòn; nếu dư, bọc kín bảo quản tủ mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 6–8 phút.', 'thai', 'mon_lau_tiec', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Gai Yang","Gà nướng","Thái Lan","Chanh ớt","Món tiệc"]', '["lunch","dinner"]', '["grill_roast"]', '["chicken","fish"]', 386, 385.7, 1615, 32.9, 22.9, 5.6, 11.2, 0.9, 7.3, 1311, 3.28, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC Sriracha Ref"]', 'c3d65c06a86046bab08531b7ea4931e6e96505185986a50453f69f619098e9f5', 'daaf9da1e9869fd01e2f8b6e6e21d35c37285cf45ad8b9bd87a4a4a7ec34dbf2', 4),
('imp-cc203adb1d5aa11b', 'canh-ca-sa-ca-chua', 471, 'Canh cá nấu sả cà chua kiểu Thái', 'Canh cá nước trong ngọt thanh nấu cùng sả đập dập và cà chua chín mọng, hậu chua dịu từ nước cốt chanh tươi rất dễ ăn', 'Tô canh cá sả cà chua kiểu Thái có phần nước dùng trong veo, thơm dịu tinh dầu sả tươi, hòa quyện cùng thịt cá trắng ngọt chắc, vị chua nhẹ từ cà chua chín và chanh tươi giúp bữa cơm thêm nhẹ bụng, ấm áp.', 'Múc canh cá ra tô lớn khi còn nóng hổi, rắc hành lá và ngò rí lên trên; dùng cùng cơm trắng và chén nước mắm ớt để chấm thịt cá.', 'Nên dùng hết trong ngày để thịt cá giữ nguyên độ ngọt chắc; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhẹ lại trên lửa nhỏ mà không khuấy mạnh để tránh làm nát cá.', 'thai', 'mon_canh', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Canh cá","Sả cà chua","Nước trong","Thái Lan","Thanh mát"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 180, 180, 752, 24.5, 5.3, 1.1, 8.6, 1.8, 5.3, 1281, 3.2, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '08d84085f6302a125cb88a34241535158f0ff1f489fd7efcd120233f38569282', 'f7b0b89ead643070fa29ea5146ff56c8a248e47d30b8b332a575dbdcd7e8278b', 4),
('imp-7bd81a7e8fb33958', 'muc-om-sa-thai', 472, 'Mực hấp om sả chanh kiểu Thái', 'Mực ống tươi khứa vảy rồng hấp om cùng sả thơm nồng, rưới nước sốt mắm chanh tỏi ớt chua cay mặn ngọt đậm vị biển', 'Món mực om sả kiểu Thái kết hợp kỹ thuật hấp nhanh giữ trọn độ giòn ngọt tự nhiên của mực ống tươi cùng hương tinh dầu sả nồng nàn, hòa quyện với nước sốt hải sản Nam Jim chua cay mặn ngọt bùng vị.', 'Dọn đĩa mực hấp nóng hổi ngay khi vừa rưới sốt, rắc thêm ngò rí và hành lá; ăn kèm cơm trắng nóng hoặc rau sống dưa leo giải ngấy.', 'Mực hấp ngon nhất khi ăn nóng ngay lúc vừa chế biến; nếu dư, bảo quản tủ mát tối đa 24 giờ và hấp cách thủy lại 2–3 phút trên lửa lớn để mực nóng mà không bị dai.', 'thai', 'mon_hap_luoc', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Mực hấp","Sả chanh","Hải sản Thái","Chua cay","Ít dầu mỡ"]', '["lunch","dinner"]', '["steam","simmer"]', '["fish","molluscs","squid"]', 198, 197.7, 827, 23.9, 2.2, 0.5, 20.8, 1.1, 8.7, 1168, 2.92, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 172185","USDA FDC 173647","USDA FDC 174223"]', 'd26f0c3659d61c5f0569245da29c2dd0afc20b9d99cb87ac0e7d6b51c0bc8b09', '1754c7e2d23dd9a7fe88b2900a6a790dcd5437e81e3c82f25ebf4cf1457bcbab', 4),
('imp-0abadc2e606770a7', 'cua-hap-sa', 473, 'Cua biển hấp sả gừng kiểu Thái', 'Cua thịt chắc hấp cách thủy cùng sả cây đập dập, gừng lát và rượu vang trắng khử tanh, chấm muối tiêu chanh ớt cay thơm đậm đà', 'Cua biển hấp sả gừng kiểu Thái giữ trọn vị ngọt chắc nguyên bản của thịt cua tươi, quyện cùng hương thơm nồng ấm của sả cây, gừng tươi và rượu vang trắng bốc hơi trong xửng hấp, ăn kèm muối tiêu chanh ớt cay thanh rất bắt vị.', 'Gỡ nhẹ dây buộc, tách đôi mai cua hoặc chặt miếng lớn bày lên đĩa cùng vài khúc sả hấp thơm; dọn nóng kèm muối tiêu chanh ớt và rau răm.', 'Nên dùng hết ngay khi cua vừa hấp nóng để thịt ngọt và không bị tanh; nếu còn dư, gỡ sẵn thịt cua bọc kín bảo quản tủ mát tối đa 24 giờ và hấp nóng lại 3 phút trước khi ăn.', 'thai', 'mon_hap_luoc', NULL, 'medium', 20, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Cua hấp","Sả gừng","Hải sản","Thái Lan","Món tiệc"]', '["lunch","dinner"]', '["steam"]', '["crab","crustaceans","sulphites"]', 226, 225.5, 943, 37, 5.2, 0.9, 5.2, 0.5, 1.3, 1134, 2.84, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '8bf42fe69f20f981eb5d6c8071c63ea75866cf122668893e68e14014a6213faa', 'd4c9fdfb52c9417ce3502305aed166180edeb1a094a83d5daafcd37ec4413346', 4),
('imp-cc6a0ca585b502d4', 'larb-ga', 474, 'Larb gà bằm trộn thính gạo kiểu Isaan', 'Thịt gà bằm xào tơi vừa chín tới trộn cùng thính gạo rang thơm bùi, hành tím, lá bạc hà và sốt chanh mắm ớt chuẩn vị Đông Bắc Thái', 'Larb gà kiểu Isaan là món gỏi thịt ấm nổi tiếng của vùng Đông Bắc Thái Lan, gây ấn tượng với thịt gà bằm mềm ẩm không khô, quyện thính gạo rang giòn bùi, vị chua thanh của chanh, mặn thơm nước mắm và hương lá bạc hà tươi mát.', 'Bày larb gà ra đĩa, rắc thêm lá bạc hà tươi lên trên; dùng ấm kèm xôi nếp hoặc cơm trắng cùng dưa leo, bắp cải giòn và đậu que sống.', 'Nên trộn thính gạo và rau thơm ngay trước khi ăn để thính không bị ỉu hút hết nước sốt; nếu bảo quản tủ mát tối đa 24 giờ, chỉ giữ riêng phần thịt xào sốt và trộn thính, rau thơm lúc ăn.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Larb gà","Isaan","Thính gạo","Chua cay","Thái Lan"]', '["lunch","dinner"]', '["stir_fry","toss_mix"]', '["chicken","fish"]', 276, 276.1, 1155, 34.6, 8.1, 2, 15.2, 1.8, 3.7, 1193, 2.98, '["Citrus Leaf Culinary Ref","Toasted Rice Powder Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 171477","USDA FDC 172185","USDA FDC 172385","USDA FDC 173474","USDA FDC 173647"]', '91fd1e262bcc12a9764cec8398a90d8abb0a3f4e380e0864b29ab3278487b16c', '2381082acdaf96c70202747c16cc26fd431b9d86f608c078f381e9cfdfed1ac6', 4),
('imp-6e4967b3145dee09', 'nam-xao-hung-que-thai', 475, 'Nấm đùi gà xào húng quế kiểu Thái chay', 'Nấm đùi gà áp chảo cháy cạnh xào tỏi ớt cay nồng cùng dầu hào chay, xì dầu và lá húng quế thơm nức chuẩn vị Pad Krapao Hed', 'Phiên bản chay thanh đạm nhưng cực kỳ bắt cơm của món xào đường phố Thái Pad Krapao: nấm đùi gà xém cạnh giòn ngọt sần sật thấm sốt xì dầu đậm đà, quyện hương cay nồng của tỏi ớt và lá húng quế tươi bùng vị.', 'Xúc nấm xào nóng hổi ra đĩa, rắc thêm hành lá thái khúc; dùng ngay với cơm trắng nóng dẻo hoặc kèm dưa leo thái lát thanh mát.', 'Nên ăn nóng ngay sau khi xào để nấm giòn ngon và lá húng quế còn xanh thơm; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và đảo nhanh trên chảo nóng không đậy nắp.', 'thai', 'mon_xao', NULL, 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Món chay","Nấm đùi gà","Húng quế","Thái Lan"]', '["lunch","dinner"]', '["stir_fry"]', '["soybean","wheat"]', 182, 181.7, 760, 7.6, 8.2, 1.2, 24.1, 5.1, 10.7, 930, 2.32, '["Dark Soy Sauce Label Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 171413","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '0682d6e6f48ccba026e97c67ffa3086aa4c810c0e2dccc4c759b2e2af1242bd2', '34d4219554a013b8bd22ef3297f8f3cccfa32969879a129cc21127037167dca1', 4),
('imp-4d9fae75b597d2c5', 'bo-nuong-sa-thai', 476, 'Thịt bò ướp sả nướng kiểu Thái', 'Thịt thăn bò thái lát mỏng ướp sả non, tỏi, tiêu đen, nước mắm và đường nâu nướng xém cạnh thơm lừng, ăn kèm chanh ớt tươi', 'Từng lát thịt thăn bò mềm mọng thấm đẫm hương thơm nồng nàn của sả non băm nhuyễn, tỏi, tiêu đen, xì dầu và nước mắm ngon, nướng nhanh trên lửa lớn cho mặt thịt xém cạnh thơm phức, cực kỳ hợp cho bữa tiệc hay cơm gia đình.', 'Xếp thịt bò nướng sả ra đĩa khi còn nóng, bày kèm chanh cắt múi cau và ớt hiểm thái lát; dùng với xôi nếp, cơm trắng, bún tươi hoặc cuốn rau sống.', 'Bò nướng ngon nhất khi dùng nóng ngay sau khi nướng và để nghỉ vài phút; nếu dư, bọc kín bảo quản tủ mát tối đa 2 ngày và áp chảo nóng nhanh 1 phút mỗi mặt cho thịt mềm ẩm trở lại.', 'thai', 'mon_lau_tiec', NULL, 'medium', 20, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Bò nướng","Sả thơm","Thái Lan","Món nhậu","Nướng vỉ"]', '["lunch","dinner"]', '["grill_roast"]', '["beef","fish","sesame","soybean","wheat"]', 316, 315.8, 1322, 27.2, 17.8, 5.8, 11.3, 0.5, 5.4, 881, 2.2, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 170106","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 174277"]', '3d276aefdbc22f127cb71d3e55a0df851bbc9fa11ada3cc1ca058bd034121cbc', 'a42178363f3afa985b4af7e1c9db05f8d0fadd0ce2e88b4d3b902848b6c11d98', 4),
('imp-a97820d3080e47eb', 'tom-xien-sa-nuong', 477, 'Tôm sú xiên cây sả nướng thơm nồng', 'Tôm sú ướp dầu hào, nước mắm và hành tỏi sả băm rồi xiên dọc thân vào cây sả tươi nướng vàng thơm, chấm muối ớt chanh cay thanh', 'Tôm sú xiên sả nướng mang hương thơm nhiệt đới quyến rũ: dùng chính thân cây sả vót nhọn xiên dọc mình tôm giúp thịt tôm chín giữ dáng thẳng đẹp, thấm đẫm tinh dầu sả hòa quyện vị đậm đà của dầu hào, nước mắm và muối ớt chanh.', 'Bày các xiên tôm nướng còn nóng hổi ra đĩa cùng xà lách, dưa leo tươi; vắt nhẹ chút nước cốt chanh lên tôm và chấm kèm chén muối ớt chanh giã nhuyễn.', 'Tôm nướng ngon nhất khi ăn nóng ngay lúc vừa chín; nếu còn dư, gỡ vỏ bảo quản tủ mát tối đa 24 giờ và làm nóng nhanh trong nồi chiên không dầu ở 180°C khoảng 2–3 phút.', 'thai', 'mon_lau_tiec', NULL, 'easy', 25, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Xiên sả","Hải sản Thái","Món tiệc","Chanh ớt"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 191, 191.1, 800, 27.4, 5.2, 0.8, 10, 0.7, 3.3, 1403, 3.51, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '12839d0a0031963b051e8d36bd0c67f72d7df8c127d520f77c55402e9e07303f', '871619709c94c357a0c0eec53b58706dbb4b4d91b8cfa9ca4036ff9766e66540', 4),
('imp-a9d8b4d783b986d1', 'com-tom-sa-thai', 478, 'Cơm chiên tôm sả kiểu Thái', 'Cơm nguội rang tơi hạt cùng tôm tươi giòn ngọt, sả non thái lát mỏng, cà rốt, trứng gà và bộ ba sốt xì dầu, dầu hào, nước mắm đậm vị', 'Đĩa cơm chiên tôm sả kiểu Thái thơm nức mùi sả non phi vàng và hương khói chảo wok, hòa quyện thịt tôm săn ngọt, cà rốt giòn thanh, trứng chiên tơi xốp cùng vị đậm đà hài hòa của xì dầu, dầu hào và nước mắm.', 'Xới cơm chiên tôm sả ra đĩa khi còn nóng hổi, rắc thêm hành lá và tiêu trắng; dọn kèm vài lát dưa leo, chanh tươi cắt múi để vắt nhẹ khi ăn.', 'Món cơm chiên ngon nhất khi ăn nóng ngay lúc vừa tắt bếp; nếu bảo quản tủ mát tối đa 24 giờ, nên đảo lại trên chảo nóng không dầu khoảng 3 phút cho hạt cơm săn tơi.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Tôm sả","Thái Lan","Nhanh gọn","Bữa chính"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","molluscs","shrimp","soybean","wheat"]', 427, 427, 1787, 25.3, 12.6, 2.4, 53, 1.8, 4.1, 1136, 2.84, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170933","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '5a1805dae89fc01503b09388d5a72fd3d7d88c20d538ba07e1d3937cc969de4c', 'e221d28ecfff2a12102c3e0f161489678c3ec02f0287bd7aff0aeac81f6a6d06', 4),
('imp-4095c816782acd82', 'salad-ca-chua-cay-thai', 479, 'Salad cà chua trộn cay kiểu Thái', 'Cà chua chín mọng bổ múi cau trộn nước mắm chanh tỏi ớt chua cay mặn ngọt, rắc tôm khô và đậu phộng rang giòn bùi mát lành', 'Món salad cà chua cay kiểu Thái (Yum Makhuea Thet) thanh mát đầy sức sống với từng múi cà chua chín đỏ mọng nước thấm sốt mắm chanh đường thốt nốt, điểm xuyết vị giòn bùi của đậu phộng rang và tôm khô đậm đà.', 'Múc salad cà chua ra đĩa sâu lòng cùng phần nước sốt chua cay tự nhiên, rắc hành lá, ngò rí và đậu phộng rang giã dập lên trên; dùng mát làm món khai vị hoặc ăn kèm đồ nướng.', 'Salad cà chua ngon nhất khi trộn và dùng trong vòng 1–2 giờ; nếu ướp lạnh trong tủ mát, chỉ rắc đậu phộng rang và rau thơm ngay trước khi dọn để giữ độ giòn.', 'thai', 'mon_cuon_nom', NULL, 'easy', 12, 3, 3, '/frigo/illustrations/delicious-meal.png', '["Salad Thái","Cà chua","Chua cay","Khai vị","Mát lành"]', '["lunch","dinner"]', '["toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 148, 148, 618, 8.8, 6.3, 0.8, 17.2, 3.8, 10.5, 1071, 2.68, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 172185","USDA FDC 172430","USDA FDC Palm Sugar Ref"]', '209f986debc39e6a6190cb1cd1a80eb02f8f7d9d2fa9f8a36bd7b9493bad3fc7', 'e540fabf7847365d2b1cfb91e8b03cecbab6d93a810507c363b1337f918bbeb6', 4),
('imp-0e9c9740a6232263', 'heo-xao-hung-que', 480, 'Thịt heo bằm xào húng quế kiểu Thái (Pad Krapao)', 'Thịt heo xay xào săn trên lửa lớn với tỏi ớt giã nồng, dầu hào, nước mắm và lá húng quế Thái thơm lừng, chan cơm trắng cùng trứng ốp la', 'Món ăn quốc dân của đường phố Thái Lan: thịt nạc vai heo xay xào tơi đậm đà cùng đậu đũa giòn ngọt, quyện mùi thơm cay nồng của tỏi ớt phi và lá húng quế, ăn kèm cơm trắng nóng và trứng gà ốp la viền giòn lòng đào béo ngậy.', 'Xới cơm trắng nóng ra đĩa, xúc thịt heo xào húng quế đặt cạnh cùng 1 quả trứng gà ốp la lòng đào, rắc thêm hành lá và thưởng thức ngay.', 'Ngon nhất khi ăn nóng ngay sau khi xào; nếu còn dư, bảo quản hộp kín trong tủ mát tối đa 2 ngày và đảo nóng lại trên chảo 2 phút với 1 muỗng canh nước lọc.', 'thai', 'mon_xao', NULL, 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Thịt heo bằm","Húng quế","Đường phố Thái","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["egg","fish","molluscs","pork","soybean","wheat"]', 585, 585.3, 2448, 33.3, 45, 14.5, 11, 1.3, 6.3, 1336, 3.34, '["Dark Soy Sauce Label Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277"]', '9a46dbf1d53171e08859b8b5047c28ac4adddeac8519fd7c662e70ea820f022c', '0a29d98d010923ad6234aefd785c916f180fe395a8cbe5b69ea05f2f635dca91', 4),
('imp-b6d6788784da6342', 'ca-chien-sot-cay-thai', 481, 'Cá chiên giòn rưới sốt ớt tỏi kiểu Thái (Pla Rad Prik)', 'Cá điêu hồng nguyên con áo mỏng bột chiên vàng giòn rụm, phủ sốt tỏi ớt đường thốt nốt, nước mắm và chanh tươi sánh bóng đậm vị', 'Cá chiên sốt cay kiểu Thái (Pla Rad Prik) gây thương nhớ bởi lớp da cá chiên giòn tan vàng ruộm ôm lấy thớ thịt cá trắng ngọt mềm ẩm, quyện cùng nước sốt tỏi ớt đường thốt nốt sánh dẻo chua cay mặn ngọt bùng vị.', 'Bày cá chiên giòn ra đĩa lớn, chỉ rưới phần sốt tỏi ớt nóng hổi lên mình cá ngay trước khi ăn, rắc thêm hành lá thái lát và dùng kèm cơm trắng nóng.', 'Nên ăn nóng ngay sau khi rưới sốt để giữ độ giòn rụm của da cá; nếu chưa ăn hết, tách riêng phần cá chiên và nước sốt trong tủ mát tối đa 24 giờ, làm nóng giòn cá bằng nồi chiên không dầu ở 180°C trong 6 phút rồi mới hâm sốt rưới lên.', 'thai', 'mon_chien', NULL, 'medium', 20, 22, 4, '/frigo/illustrations/delicious-meal.png', '["Cá chiên giòn","Pla Rad Prik","Sốt cay","Thái Lan","Đưa cơm"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["fish","wheat"]', 359, 359.2, 1502, 32.1, 19.4, 3.3, 13.1, 0.8, 6.6, 1440, 3.6, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169761","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","USDA FDC Palm Sugar Ref"]', '6b48a622b5cd76927552168417f985b4a52c6ae74260b638567444dcd7b1180b', '9ba6dfa5147cbabdc52ae114d27e5074f2bc4bc6d5a2728523d6153d5c89a57a', 4),
('imp-71cac2085659d819', 'ga-xao-dua-thai', 482, 'Thịt đùi gà xào dứa chua ngọt kiểu Thái', 'Đùi gà áp chảo vàng mềm xào cùng dứa chín ngọt, ớt chuông, hành tây và đậu Hà Lan áo sốt giấm gạo tương ớt ngọt sánh bóng', 'Đĩa gà xào dứa kiểu Thái rực rỡ sắc màu với thịt đùi gà áp chảo mềm ngọt săn cạnh, quyện cùng dứa chín thơm mọng, ớt chuông đỏ và đậu Hà Lan giòn tươi trong lớp sốt chua ngọt cay nhẹ bóng mượt từ giấm gạo, đường nâu và nước mắm.', 'Xúc gà xào dứa nóng hổi ra đĩa lớn, rắc thêm hành lá và ớt hiểm thái lát; ăn kèm cơm trắng nóng hoặc cơm gạo lứt đều rất đưa cơm.', 'Ngon nhất khi ăn nóng để rau củ giữ độ giòn tươi; nếu bảo quản tủ mát tối đa 2 ngày, đảo nhanh trên chảo nóng trong 3 phút để gà nóng đều mà rau không bị nhũn.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Gà xào dứa","Chua ngọt","Thái Lan","Màu sắc","Cơm gia đình"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish"]', 470, 470, 1967, 35, 23.8, 5.8, 29.3, 4.1, 19, 995, 2.49, '["USDA FDC 168833","USDA FDC 169124","USDA FDC 169230","USDA FDC 169698","USDA FDC 169961","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC Sriracha Ref"]', '712c57cbde15e3a00da27e3cbdc722c1f582d53628a9f23e3328bcb142997b9b', '3464df55053f46d473a5b62dd7e6373d1190fab945683a26001f404b86cdb784', 4),
('imp-b398545ca76325f1', 'canh-bap-cai-sa-thai', 483, 'Canh bắp cải nấu sả chanh Thái chay', 'Canh bắp cải giòn ngọt nấu cùng đậu phụ non, cà rốt và sả tươi đập dập, nước dùng chay trong thanh hậu chua dịu của chanh tươi', 'Tô canh bắp cải sả Thái chay thanh nhẹ trong veo, kết hợp vị ngọt mát tự nhiên của bắp cải xanh và cà rốt, đậu phụ non mềm mịn cùng hương thơm nồng dịu của sả đập dập và nước cốt chanh tươi rất dễ ăn.', 'Múc canh nóng ra tô lớn, gắp bỏ bớt khúc sả già, rắc hành lá và ngò rí lên trên; dùng khai vị hoặc ăn kèm cơm trắng trong bữa cơm thanh đạm.', 'Nên dùng hết trong ngày để bắp cải giữ màu xanh giòn ngọt và giữ trọn mùi thơm chanh tươi; nếu bảo quản tủ mát trong 24 giờ, chỉ đun sôi lại phần nước canh và rau rồi vắt thêm chút chanh tươi trước khi ăn.', 'thai', 'mon_canh', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Canh chay","Bắp cải","Sả chanh","Thanh mát","Thái Lan"]', '["lunch","dinner"]', '["simmer"]', '["soybean"]', 137, 136.9, 573, 8.4, 6.3, 0.9, 15.2, 4.5, 7.9, 1001, 2.5, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","Vegetarian Fish Sauce Ref","Vegetarian Seasoning Powder Ref"]', '23c6175ba486eee480a01b83e8a082d2c33951699b9f8174682e59310b921c36', '8d073ab3731c90ebf1b65ec8b717314dc6721ef42e80062f16ce6218c0cf31fd', 4),
('imp-9f9a3f24b4141acb', 'cua-chien-toi-ot-thai', 484, 'Cua lột chiên giòn xóc tỏi ớt kiểu Thái', 'Cua lột áo bột chiên ngập dầu giòn rụm, xóc nhanh trên chảo nóng cùng tỏi phi vàng, rễ ngò rí và ớt hiểm đỏ thơm nức đậm vị', 'Cua lột chiên tỏi ớt kiểu Thái hấp dẫn với lớp vỏ ngoài giòn rụm vàng ươm bọc lấy phần thịt cua ngọt béo mềm tan, xóc đều cùng bộ ba hương liệu Thái gồm rễ ngò rí, tỏi chiên giòn và ớt hiểm cay nồng thơm lừng.', 'Xếp cua chiên nóng hổi ra đĩa, rắc ngập tỏi phi giòn, hành lá và ngò rí lên trên; ăn nguyên con khi còn nóng giòn cùng cơm trắng hoặc chấm tương ớt.', 'Món cua lột chiên giòn ngon nhất khi thưởng thức ngay sau khi nấu để giữ trọn độ giòn tan; không nên để qua đêm vì vỏ bột sẽ ỉu mềm.', 'thai', 'mon_chien', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Cua chiên giòn","Cua lột","Tỏi ớt","Hải sản Thái","Món nhậu"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["crab","crustaceans","soybean","wheat"]', 404, 404.1, 1691, 36.7, 16.3, 2.5, 26.8, 1.6, 2.4, 1419, 3.55, '["Panko / Batter Mix Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171413","USDA FDC 173468","USDA FDC 174208","USDA FDC 174277"]', '7315becc8f984c50260a41c95473e989105afa4ae6273a7a7f287a6745043b7b', '02f63ea26f3754e265c320d123779d763c90535d0b47c2f75ecbbbc9a7674707', 4),
('imp-8fecebfe6dc0f0a2', 'mi-y-rau-bina', 485, 'Mì Ý sốt kem rau bina và hạnh nhân', 'Sợi spaghetti trộn sốt pesto rau bina xanh mướt xay mịn cùng phô mai ricotta, parmesan và hạnh nhân rang bùi', 'Món mì Ý chay nhẹ nhàng nhưng đầy đặn dinh dưỡng với lớp sốt xanh ngọc mượt mà từ rau bina chần xay nhuyễn cùng phô mai ricotta béo thanh, parmesan đậm vị và hạnh nhân rang thơm bùi.', 'Dọn mì ngay ra đĩa nông khi còn ấm nóng, rắc thêm chút phô mai parmesan bào sợi và hạnh nhân rang giã dập lên mặt để tăng độ giòn thơm.', 'Món sốt xanh rau bina ngon nhất khi ăn ngay sau khi trộn để giữ màu xanh tươi. Nếu bảo quản tủ lạnh tối đa 1 ngày, hâm nhẹ trên chảo lửa thật nhỏ cùng 1–2 muỗng nước ấm.', 'italian', 'mon_bun_pho', NULL, 'easy', 12, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Rau bina","Sốt kem","Nhanh gọn","Thanh đạm"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["almond","milk","tree_nuts","wheat"]', 604, 604.4, 2529, 22.6, 24.7, 6, 74.1, 5.7, 3.3, 562, 1.4, '["USDA FDC 168462","USDA FDC 168927","USDA FDC 169230","USDA FDC 170567","USDA FDC 170848","USDA FDC 170853","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', '1dc7105639ae114b0a176a81e5ca5aaad822acd2444074d3cd9260be65142373', '31b88d7e364bec9ae16906a541f8d564b7a4c8a5bfac39802bc1cb2c7d2926a2', 4),
('imp-20d3992a65cb17fd', 'mi-y-ga-nam', 486, 'Mì Ý gà nấm sốt cà chua', 'Ức gà áp chảo vàng cạnh cùng nấm đùi gà giòn ngọt và cà chua chín mọng ôm trọn từng sợi mì spaghetti', 'Đĩa mì Ý đầy đặn dinh dưỡng cho bữa tối gia đình với ức gà mềm mọng thấm gia vị, nấm đùi gà xào lửa lớn giữ trọn độ giòn ngọt và vị chua thanh nhẹ tự nhiên từ cà chua chín tươi.', 'Múc mì ra đĩa sâu lòng khi còn nóng, rắc phô mai Parmesan bào mịn cùng chút tiêu đen xay mới và thưởng thức ngay.', 'Nếu chưa dùng hết, cất hộp kín trong ngăn mát tối đa 2 ngày. Hâm nóng trên chảo với 2 muỗng canh nước lọc trên lửa vừa trong 3–4 phút cho mì mềm tơi trở lại.', 'italian', 'mon_bun_pho', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Ức gà","Nấm đùi gà","Cà chua","Bữa tối"]', '["lunch","dinner"]', '["boil","pan_fry","stir_fry"]', '["chicken","milk","wheat"]', 553, 553.1, 2314, 38.6, 14, 3.2, 67.5, 4.9, 4.5, 568, 1.42, '["USDA FDC 168580","USDA FDC 168927","USDA FDC 169230","USDA FDC 170416","USDA FDC 170457","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647"]', 'a3a79f3d9fea651a5f605b1c6e3583acd9bc06c861d78b547384b2bc7be4b85e', '119f7667d3e2058ed0f50eb80457a71b0316772ff4de2c1904a407d035865648', 4),
('imp-38137393c32d70d7', 'risotto-tom', 487, 'Risotto tôm tươi nấu nước dùng vỏ tôm', 'Cơm Ý Arborio sánh kem mượt mà thấm đẫm vị ngọt tự nhiên từ nước dùng ninh vỏ đầu tôm, rượu vang trắng và bơ lạt', 'Đĩa risotto chuẩn phong cách Ý với hạt gạo Arborio dẻo mềm nhưng vẫn giữ độ sần nhẹ ở lõi, tỏa hương ngọt biển sâu lắng nhờ nước dùng ninh từ vỏ và đầu tôm rang kỹ, kết thúc bằng bước đánh bơ tạo độ bóng kem mượt mà.', 'Múc risotto ra đĩa sâu lòng khi vừa nhấc khỏi bếp, xếp các con tôm áp chảo lên trên mặt và rắc ngò tây tươi băm nhỏ; theo truyền thống Ý, risotto hải sản không dùng kèm phô mai.', 'Risotto ngon nhất khi dùng ngay lúc vừa nấu xong để giữ độ sánh kem đặc trưng. Phần còn dư có thể bảo quản ngăn mát tối đa 2 ngày và hâm nóng trên chảo cùng 2–3 muỗng canh nước dùng hoặc nước lọc.', 'italian', 'mon_kho', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Risotto","Tôm tươi","Cơm Ý","Hải sản","Sánh kem"]', '["lunch","dinner"]', '["simmer","pan_fry"]', '["celery","crustaceans","milk","shrimp","sulphites"]', 508, 507.5, 2124, 23.6, 13.6, 5, 67.9, 1.9, 1.8, 612, 1.53, '["USDA FDC 169230","USDA FDC 169988","USDA FDC 170393","USDA FDC 170416","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Arborio Rice Ref"]', 'b08efae4eeca45921b80b7d4bdbe4450bcd0604212d44becff22105f34ff8a5a', 'd24203fcf893aaebbd07109ecffe013bb9e94c97fa9e782f74321c84c3a3cc8d', 4),
('imp-e61010e240534690', 'muc-om-ca-chua-y', 488, 'Mực om cà chua kiểu Ý', 'Mực ống tươi om mềm trong sốt cà chua pelati sánh đỏ cùng rượu vang trắng, tỏi thơm và ngò tây', 'Món mực om cà chua mang đậm hương vị vùng biển nước Ý với từng khoanh mực mềm mọng không hề bị dai, thấm đẫm nước sốt cà chua pelati chua thanh hòa quyện mùi tỏi, rượu vang trắng và ngò tây tươi.', 'Múc mực om nóng hổi ra đĩa sâu lòng cùng nước sốt đỏ sánh, rắc ngò tây băm nhỏ và ăn kèm bánh mì nướng giòn để chấm sốt.', 'Bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày. Khi ăn, hâm lại trên chảo với lửa nhỏ trong 4–5 phút để mực mềm ấm mà không bị dai.', 'italian', 'mon_kho', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Mực om","Cà chua","Hải sản","Ẩm thực Ý","Món chính"]', '["lunch","dinner"]', '["braise","simmer"]', '["molluscs","squid","sulphites"]', 227, 226.9, 950, 21.8, 8.6, 1.4, 13, 2.2, 4.7, 672, 1.68, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 174223"]', '9617df795256461fe09ea114bae57d48f82f7b54e9196e83e4bbc371f4c62e4f', 'ada91f4fd6a3961a21cc41c3ce5a9e586904edbc79969a4727db1755aa20cea0', 4),
('imp-452ef6d0f8ec0de9', 'tom-om-ca-chua-y', 489, 'Tôm om sốt cà chua kiểu Ý', 'Tôm tươi săn ngọt chín tới trong nước sốt cà chua passata sóng sánh, thơm hương tỏi phi và lá húng quế Tây', 'Món tôm om sốt cà chua thanh nhẹ kiểu Ý hoàn thành chỉ trong 25 phút với nguyên liệu tinh gọn: tôm tươi bóc vỏ săn ngọt quyện trong sốt cà chua passata sánh mịn, điểm vị cay nhẹ từ ớt và hương thơm tươi mát của húng quế Tây.', 'Múc tôm cùng nước sốt cà chua ra đĩa sâu lòng, rưới thêm vài giọt dầu ô liu nguyên chất và dọn nóng ngay kèm bánh mì nướng giòn hoặc cơm trắng.', 'Món tôm ngon nhất khi dùng ngay lúc mới nấu để tôm giữ độ giòn ngọt. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm nhanh ở lửa nhỏ trong 2 phút.', 'italian', 'mon_kho', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm om","Sốt cà chua","Nhanh gọn","Hải sản","Ẩm thực Ý"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","shrimp"]', 202, 201.7, 844, 25.4, 8.1, 1.2, 8.7, 2.1, 4.5, 655, 1.64, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '5329af471b43c2718e68644fccd38a4bff4425aeab078525ef6f7e21577a3c77', '55efd411512ec44b3b3026e755a3a2050aa7d946b03bf9bafdff1162d3f71f2c', 4),
('imp-f44be7e8c88c20d3', 'sup-ca-hoi-kem-y', 490, 'Súp cá hồi kem tươi kiểu Ý', 'Nồi súp kem ấm áp sánh mịn từ khoai tây, cà rốt và cá hồi phi lê chín mềm béo thanh không tanh', 'Bát súp cá hồi nấu kem kiểu Ý sánh mịn tự nhiên nhờ khoai tây bở hòa cùng kem tươi béo dịu, tôn lên vị ngọt thơm đặc trưng của từng khối phi lê cá hồi tươi chín vừa tới.', 'Múc súp cá hồi ra tô sâu lòng khi còn nóng ấm, rắc ngò tây tươi thái nhỏ, chút thì là tươi và tiêu đen xay mới; ăn kèm bánh mì nướng giòn.', 'Bảo quản súp nguội trong hộp kín ở ngăn mát tối đa 2 ngày. Khi hâm, đun lửa thật nhỏ và khuấy nhẹ để kem không tách dầu và miếng cá hồi không bị nát.', 'italian', 'mon_canh', NULL, 'medium', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Súp kem","Cá hồi","Khoai tây","Ẩm thực Ý","Mùa lạnh"]', '["lunch","dinner"]', '["simmer"]', '["fish","milk","salmon"]', 554, 554.1, 2318, 25.3, 38.6, 18.9, 27, 4.2, 7.8, 1100, 2.75, '["USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170416","USDA FDC 170859","USDA FDC 170931","USDA FDC 171595","USDA FDC 172233","USDA FDC 173430","USDA FDC 173468","USDA FDC 175167"]', '58857cabe58684ca25f324437fc644f2ff9f896ac4c64d09513eb19f7f5a7881', 'c9b165fa61aa6ca0616f630827ac7392da3e42006513ce245f712ae5b89c60e7', 4),
('imp-e748a717f7250188', 'salad-ca-hoi-dua-leo', 491, 'Salad cá hồi áp chảo dưa leo sốt chanh', 'Cá hồi áp chảo xém cạnh mềm ngọt kết hợp dưa leo giòn mát, xà lách tươi và sốt dầu ô liu chanh vàng thanh nhẹ', 'Đĩa salad cá hồi thanh mát cân bằng dinh dưỡng với miếng phi lê cá hồi áp chảo vừa chín tới mềm ngọt, ăn cùng dưa leo ướp muối giữ độ giòn sần sật, rau xà lách tươi và nước sốt nhũ tương dầu ô liu chanh vàng dịu mát.', 'Bày salad cá hồi ra đĩa rộng hoặc tô nông lòng khi cá còn hơi ấm hoặc đã để mát, dùng kèm bánh mì nướng giòn để bữa ăn thêm tròn vị.', 'Salad trộn sốt ngon nhất khi dùng ngay trong vòng 1–2 giờ sau khi chế biến. Nếu chuẩn bị trước, nên bảo quản riêng phần cá hồi, rau củ và nước sốt chanh trong ngăn mát tối đa 24 giờ và chỉ trộn đều ngay trước khi ăn.', 'italian', 'mon_cuon_nom', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Salad","Cá hồi","Dưa leo","Thanh mát","Ít tinh bột"]', '["breakfast","lunch","dinner"]', '["pan_fry","toss_mix"]', '["fish","salmon"]', 394, 393.7, 1647, 26.1, 29.4, 5.5, 7.1, 2, 2.4, 475, 1.19, '["USDA FDC 167746","USDA FDC 168409","USDA FDC 169247","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173474","USDA FDC 175167"]', 'ffe972a9cd476d10b3596d20dc545bc59a30ae80013da34e07845f1508ee9351', '9d1d3ff34d0e9345ea631f5e5ca3adcb61fbb07c791469d72bbab4c83eb9c5fd', 4),
('imp-957396bc647d3798', 'bong-cai-om-ca-chua-y', 492, 'Bông cải xanh om cà chua kiểu Ý', 'Bông cải xanh chần giữ màu xanh mướt rồi om thấm vị cùng cà chua bi, tỏi phi dầu ô liu và chút ớt cay nhẹ', 'Món rau ăn kèm giản dị chuẩn bếp nhà Ý với từng nhánh bông cải xanh mềm ngọt nhưng vẫn giữ độ chắc, quyện trong nước sốt cà chua bi chua thanh sánh nhẹ, dậy mùi tỏi phi thơm trong dầu ô liu nguyên chất.', 'Dọn bông cải om cà chua ra đĩa nông lòng, rắc ngò tây tươi thái nhỏ lên trên; thích hợp ăn kèm thịt nướng, cá áp chảo hoặc bánh mì giòn.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày. Khi dùng, làm nóng trên chảo lửa vừa cùng 1–2 muỗng canh nước trong 3 phút.', 'italian', 'mon_chay', NULL, 'easy', 10, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Bông cải xanh","Cà chua","Món phụ","Món chay","Ẩm thực Ý"]', '["lunch","dinner"]', '["boil","braise"]', '[]', 149, 148.9, 622, 4.3, 10.9, 1.5, 11.7, 4.2, 3.8, 278, 0.7, '["USDA FDC 169230","USDA FDC 170106","USDA FDC 170379","USDA FDC 170416","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'f21b49a116388f4fc809468df9105ee8a8f932d44a0768efc622acab6e662791', 'ca002c567928b3784aa667400854bb69c814de9194e4e0a16debfabc12ba6e85', 4),
('imp-c98aa0f1ffe2f469', 'suon-om-ca-chua-y', 493, 'Sườn heo om sốt cà chua kiểu Ý', 'Sườn non áp chảo xém vàng om mềm róc xương cùng sốt cà chua đậm đà, rượu vang trắng, ô liu đen và hương thảo', 'Món sườn heo om cà chua đậm đà kiểu Ý với dẻ sườn áp chảo xém cạnh thơm phức, hầm liu riu cùng hành tây, rượu vang trắng, cà chua đóng hộp và ô liu đen cho đến khi thịt mềm tơi dễ dàng tách khỏi xương.', 'Múc sườn om nóng hổi cùng phần sốt sánh ra đĩa lớn, dùng kèm bánh mì giòn chấm sốt, khoai tây nghiền hoặc trộn cùng mì Ý luộc chín.', 'Món sườn om bảo quản hộp kín trong ngăn mát tối đa 3 ngày và hương vị thường đậm ngon hơn vào ngày hôm sau. Hâm nóng lại trên lửa nhỏ, thêm 2–3 muỗng nước nếu sốt đặc.', 'italian', 'mon_kho', NULL, 'hard', 20, 80, 5, '/frigo/illustrations/delicious-meal.png', '["Sườn heo","Ragu Ý","Om cà chua","Ô liu đen","Cuối tuần"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["pork","sulphites"]', 589, 588.9, 2464, 26.2, 45.9, 14.5, 15.9, 3.9, 7.1, 994, 2.48, '["USDA FDC 167861","USDA FDC 169072","USDA FDC 169094","USDA FDC 169230","USDA FDC 170000","USDA FDC 170393","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '6730c036020532afd7b11ee318883502274aa99b57d16aed626842a7fd93046b', '012219587ed4d63cfbd5f2040b330ff3c153da37953afe545851c53e75571da2', 4),
('imp-a286f8724d79a504', 'ca-chua-tron-pho-mai', 494, 'Cà chua trộn phô mai Mozzarella tươi kiểu Ý', 'Cà chua chín mọng xếp xen kẽ phô mai Mozzarella tươi mềm béo, rưới dầu ô liu nguyên chất và giấm Balsamic thanh dịu', 'Món khai vị lạnh thanh mát chuẩn phong cách Ý tôn vinh nguyên liệu tươi ngon nhất: cà chua chín mọng cắt lát dày quyện phô mai Mozzarella tươi mềm béo, dầu ô liu nguyên chất thơm nồng và lá húng quế Tây tươi mát.', 'Bày đĩa cà chua trộn phô mai ngay sau khi hoàn thiện để dùng làm món khai vị hoặc ăn kèm bánh mì nướng giòn chấm phần nước dầu ô liu cà chua tiết ra.', 'Món khai vị tươi sống ngon nhất khi ăn ngay lúc vừa trộn; không nên cất tủ lạnh vì nhiệt độ thấp làm cà chua bở và mất hương thơm.', 'italian', 'mon_cuon_nom', NULL, 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Khai vị","Cà chua","Mozzarella","Salad Ý","Mát lành"]', '["breakfast","lunch","dinner"]', '["toss_mix","assemble"]', '["milk","sulphites"]', 304, 303.9, 1271, 17.3, 22.2, 7.9, 9.8, 2.1, 5.6, 753, 1.88, '["USDA FDC 169230","USDA FDC 170457","USDA FDC 170845","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173470"]', '7cc66d35f236cfcf6afeb064405591c96bf2efaa20b4412f6b0b2e1fea79ab73', '19680b1799d0cdc621bef1dfe169c386b719ccfe2a2854302b7714b9c33131e8', 4),
('imp-83ed31fc537569a6', 'bo-cuon-rau-bina-y', 495, 'Bò cuộn rau bina phô mai kiểu Ý', 'Thịt bò lát mỏng dần mềm cuộn nhân rau bina xào bơ và phô mai béo ngậy, áp chảo vàng rồi om sốt rượu vang trắng', 'Những cuộn thịt bò involtini khéo léo ôm trọn phần nhân rau bina xanh mướt xào bơ tỏi, phô mai Mozzarella tan chảy và cà rốt ngọt thanh, áp chảo xém cạnh rồi om mềm cùng cà chua và rượu vang trắng.', 'Rút bỏ dây buộc hoặc tăm cố định, cắt đôi cuộn thịt bò theo lát chéo để lộ lớp nhân xanh vàng đẹp mắt, rưới sốt om nóng lên trên và dùng kèm khoai tây nghiền hoặc mì Ý.', 'Bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày. Khi dùng, hâm lại cùng nước sốt trên chảo lửa nhỏ đậy nắp khoảng 5–6 phút.', 'italian', 'mon_kho', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Involtini","Bò cuộn","Rau bina","Phô mai","Ẩm thực Ý"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["beef","milk","sulphites"]', 600, 599.6, 2509, 46.3, 39.2, 16.6, 13.7, 4.2, 5.2, 896, 2.24, '["USDA FDC 168462","USDA FDC 169230","USDA FDC 170187","USDA FDC 170393","USDA FDC 170457","USDA FDC 170499","USDA FDC 170845","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', '4713e8616370e5cf8671c51937c12ff5182fef4cfb89909d18557b96cd4cc316', '47cc012efdf360aea669448a002b166bc6887d580d48f3fb865de6e9eab290ca', 4),
('imp-a92103c19952bcf0', 'ga-chien-chanh-y', 496, 'Gà chiên giòn ướp chanh vàng kiểu Ý', 'Ức gà ướp nước cốt chanh vàng và thảo mộc đậm đà, áo lớp bột chiên xù trộn Parmesan rồi chiên vàng và nướng giòn', 'Món gà chiên thơm mát hương chanh vàng vùng Địa Trung Hải: ức gà ướp rượu vang trắng, chanh tươi và tỏi thảo mộc giúp thịt mềm ẩm, bọc lớp bột chiên xù giòn rụm trộn phô mai Parmesan và vỏ chanh bào.', 'Xếp gà nóng ra đĩa, rắc thêm ngò tây tươi băm nhỏ và vỏ chanh vàng bào sợi; ăn kèm salad rau xanh dầu giấm hoặc khoai tây chiên.', 'Bảo quản thịt gà nguội trong hộp kín ở ngăn mát tối đa 2 ngày. Khi dùng, làm nóng bằng nồi chiên không dầu hoặc lò nướng ở 180°C khoảng 6–8 phút để lớp vỏ giòn trở lại.', 'italian', 'mon_chien', NULL, 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Gà chiên","Chanh vàng","Parmesan","Giòn rụm","Ẩm thực Ý"]', '["lunch","dinner"]', '["pan_fry","grill_roast"]', '["chicken","milk","sulphites","wheat"]', 426, 425.5, 1780, 45, 13.4, 3.9, 28.9, 2.5, 1.9, 1112, 2.78, '["Panko / Batter Mix Ref","USDA FDC 167746","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173190","USDA FDC 173468","USDA FDC 173475"]', 'bbefd24f7c898d7b37dbac53bff10d06dd9fa2713e3fd857339386f98251dc28', '4e0a8ae6b51b98cf31b2a88b41f746d343613accaae7e4e564903bdee360309f', 4),
('imp-afdcd866c1f92192', 'ca-om-ca-chua-y', 497, 'Cá phi lê om cà chua bi kiểu Ý', 'Phi lê cá thịt trắng om dịu trong nước dùng cà chua bi, hành tây, rượu vang trắng và ô liu đen đậm vị biển', 'Món cá om thanh tao kiểu ngư dân vùng biển Naples nước Ý với từng miếng phi lê cá thịt trắng mềm ngọt giữ nguyên thớ, nấu trong nước dùng cà chua bi tươi mát quyện hương tỏi, rượu vang trắng và quả ô liu đen.', 'Gắp cá ra 4 đĩa sâu lòng, chan đều nước dùng cà chua và ô liu nóng hổi lên mặt cá, rắc ngò tây tươi băm nhỏ và ăn kèm bánh mì giòn chấm nước sốt.', 'Món cá om ngon nhất khi dùng ngay lúc mới nấu. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm lại trên lửa thật nhỏ để thịt cá không bị nát.', 'italian', 'mon_kho', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Cá om","Cà chua bi","Hải sản","Thanh nhẹ","Ẩm thực Ý"]', '["lunch","dinner"]', '["braise","simmer"]', '["fish","sulphites"]', 290, 289.8, 1213, 32.2, 13.4, 2.3, 8.1, 2, 3.6, 624, 1.56, '["USDA FDC 169094","USDA FDC 169230","USDA FDC 170000","USDA FDC 170106","USDA FDC 170416","USDA FDC 170457","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148"]', '96368b117e8cd5928cdf72cb448cd75c2e3024cf743ed9dca99a2c1957fcc098', '6a00f89aa89b3fb8744b2e00469f65843991cb83f8208492b22afbd5a8af892d', 4),
('imp-6d26ce6b0af4fb79', 'rau-bina-om-kem-y', 498, 'Rau bina om sốt kem Béchamel kiểu Ý', 'Rau bina hấp xào mềm mượt quyện trong sốt kem Béchamel béo thanh, phô mai Parmesan và thoảng hương nhục đậu khấu', 'Món rau ăn kèm sang trọng chuẩn cổ điển Ý với rau bina nấu chín bằng chính độ ẩm tự nhiên rồi vắt ráo, xào thơm cùng hành tây và hòa quyện trong lớp sốt kem trắng Béchamel sánh mịn, thơm vị bơ sữa, Parmesan và nhục đậu khấu.', 'Múc rau bina om sốt kem nóng ra đĩa sâu lòng và thưởng thức ngay cùng thịt gà nướng, bò áp chảo hoặc phi lê cá nướng lò.', 'Món ăn ngon nhất khi dùng ngay lúc mới nấu xong. Nếu bảo quản ngăn mát tối đa 24 giờ, hâm nóng nhẹ trên chảo với 1–2 muỗng canh sữa tươi và khuấy đều tay.', 'italian', 'mon_chay', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Rau bina","Béchamel","Sốt kem","Món phụ","Món chay"]', '["lunch","dinner"]', '["steam","simmer","toss_mix"]', '["milk","wheat"]', 273, 273.2, 1143, 12.8, 17.8, 8.4, 18.7, 4.5, 5.7, 850, 2.13, '["USDA FDC 168462","USDA FDC 169761","USDA FDC 170000","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171326","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468"]', 'bcd39cc4f63da275678b9a14e0eed055e31ab9ca81ac39853424489be4324059', '52adc251baac5e19a044a0cfb1eaa0313c91300c85fccae387c8e5708fcadf02', 4);
INSERT INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-bd34e8ea2eaa1cd4', 'sup-bap-cai-y', 499, 'Súp bắp cải đậu trắng thịt xông khói kiểu Ý', 'Súp hầm ấm bụng với bắp cải ngọt mềm, đậu trắng bở béo, thịt xông khói thơm lừng cùng nui Ý và Parmesan', 'Nồi súp bắp cải kiểu nông thôn Ý đầy đặn dinh dưỡng với nền rau củ xào thơm quyện thịt xông khói, ninh mềm cùng đậu trắng cannellini, bắp cải ngọt thanh và nui Ý hạt nhỏ, hoàn thiện bằng lớp phô mai Parmesan béo dịu.', 'Múc nui Ý luộc sẵn ra 4 tô sâu lòng, chan súp bắp cải đậu trắng nóng hổi lên trên và rắc phô mai Parmesan bào mịn; ăn kèm bánh mì nướng giòn.', 'Nếu chuẩn bị ăn nhiều bữa, nên bảo quản riêng phần nui đã luộc và nồi súp trong ngăn mát tối đa 3 ngày; khi dùng đun sôi lại phần súp rồi chan lên nui để nui không bị bở nát.', 'italian', 'mon_canh', NULL, 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Súp Ý","Bắp cải","Đậu trắng","Thịt xông khói","Mùa lạnh"]', '["lunch","dinner"]', '["simmer","boil"]', '["celery","milk","pork","wheat"]', 503, 502.7, 2104, 18.5, 26.4, 9.7, 49.8, 7.8, 7.4, 1231, 3.08, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169230","USDA FDC 169975","USDA FDC 169988","USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 172883","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647","USDA FDC 175200"]', 'c033996f841f549b17724f1beeaf3c519cff13093942674c33341b45b4d011ed', 'd03297a6273f63b2e84a6ec276b8df7d20e587f28465cbd3605edddcf18c1a1e', 4);
