('imp-bd34e8ea2eaa1cd4_v4_ing_16', 'imp-bd34e8ea2eaa1cd4', 15, 'SALT', 'Muối ăn', '5 g (~1 muỗng cà phê)', 'dùng 3 g cho vào nước luộc nui (bỏ nước), 2 g nêm nồi súp', 'broth', 5, 'g', 5, 0.5, 2.5, 0, 1),
('imp-bd34e8ea2eaa1cd4_v4_ing_17', 'imp-bd34e8ea2eaa1cd4', 16, 'BLACK_PEPPER', 'Tiêu đen xay', '1,5 g (~1/2 muỗng cà phê)', 'nêm vào nồi súp khi ninh', 'broth', 1.5, 'g', 1.5, 1, 1.5, 0, 1),
('imp-bd34e8ea2eaa1cd4_v4_ing_18', 'imp-bd34e8ea2eaa1cd4', 17, 'COOKING_WATER', 'Nước lọc (luộc riêng nui Ý)', '1000 ml (1 lít)', 'đun sôi với muối để luộc nui chín al dente rồi chắt bỏ nước', 'broth', 1000, 'ml', 1000, 0.05, 50, 0, 0);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-canh-01_v4_step_1', 'vn-canh-01', 1, 'prep', 'Làm sạch nhớt và ướp cá lóc', 'Đánh sạch vảy, bỏ mang, moi ruột và cạo sạch màng đen trong bụng cá lóc. Chà xát mình cá với 3 g muối hạt trong 2 phút để hết nhớt, rửa lại nước lạnh rồi để ráo, cắt khúc dày 2,5 cm. Ướp cá với 10 ml nước mắm, 2 g muối và 2 g tiêu đen xay trong 10 phút cho thịt cá săn và đậm vị.', 'Không rửa cá bằng nước nóng vì sẽ làm nhớt đông lại khó làm sạch; muối hạt hoặc nước cốt chanh giúp khử tanh hiệu quả nhất.', 10),
('vn-canh-01_v4_step_2', 'vn-canh-01', 2, 'prep', 'Lọc nước cốt me và sơ chế rau củ', 'Ngâm 50 g cơm me chín vào 100 ml nước ấm trong 5 phút, dùng thìa dằm nát rồi lọc qua rây lấy phần nước cốt sánh, bỏ hạt và xơ. Đeo găng tay để tước bỏ lớp vỏ xơ xanh bên ngoài dọc mùng, thái lát xéo dày 0,5 cm, bóp nhẹ với 3 g muối rồi rửa sạch nhiều lần với nước và vắt nhẹ cho hết ngứa. Thái múi cau cà chua, cắt lát dứa, thái vát đậu bắp, nhặt giá đỗ và cắt khúc 2 cm hành lá, ngò gai, rau ngổ.', 'Bóp dọc mùng với muối rồi xả sạch và vắt ráo trước khi nấu sẽ giúp bạc hà giòn ngon mà không gây ngứa họng.', 5),
('vn-canh-01_v4_step_3', 'vn-canh-01', 3, 'cook', 'Phi thơm tỏi làm tỏi phi vàng giòn', 'Làm nóng nồi đáy dày trên lửa vừa với 25 ml dầu ăn, cho 2/3 lượng tỏi băm vào phi đều tay đến khi dậy mùi thơm và vừa chuyển màu vàng nhạt thì lập tức vớt phần tỏi phi ra chén giấy thấm dầu, giữ lại toàn bộ phần dầu thơm trong nồi.', 'Vớt tỏi phi ngay khi hơi ngả vàng nhạt vì lượng nhiệt dư sẽ tiếp tục làm tỏi vàng giòn hoàn hảo mà không bị đắng khét.', NULL),
('vn-canh-01_v4_step_4', 'vn-canh-01', 4, 'cook', 'Xào sơ nền cà chua và dứa tạo màu', 'Cho 1/3 phần tỏi băm còn lại cùng đầu hành lá vào nồi dầu nóng phi thơm 30 giây trên lửa vừa, tiếp tục thả một nửa lượng cà chua bổ múi cau và dứa vào xào nhanh 2 phút cho cà chua tiết màu đỏ cam tự nhiên, rồi đổ 1,4 lít nước lọc vào đun lửa lớn đến khi sôi bùng.', NULL, 2),
('vn-canh-01_v4_step_5', 'vn-canh-01', 5, 'cook', 'Nêm nước dùng chua ngọt và nấu chín cá', 'Khi nước sôi mạnh, hạ lửa vừa và từ từ rót nước cốt me đã lọc vào, nêm 25 ml nước mắm, 25 g đường cát trắng và 3 g muối sao cho đạt vị chua thanh ngọt dịu cân bằng. Thả nhẹ từng khúc cá lóc đã ướp vào nồi nước sôi, nấu sôi liu riu khoảng 6 phút đồng thời hớt sạch bọt nổi để nước canh thật trong. Khi mắt cá đục trắng và thịt cá chín chắc hoàn toàn, dùng vá lỗ nhẹ nhàng vớt cá ra tô riêng.', 'Hạ lửa vừa để nước chỉ sôi lăn tăn khi thả cá và vớt cá ra trước khi cho rau sẽ giữ được từng khúc cá nguyên vẹn, không bị nát vụn.', 6),
('vn-canh-01_v4_step_6', 'vn-canh-01', 6, 'finish', 'Chần chín rau củ và hoàn thiện tô canh', 'Thả đậu bắp và phần cà chua còn lại vào nồi canh nấu 2 phút trên lửa vừa, sau đó thêm dọc mùng nấu thêm 1 phút cho vừa chín tới vẫn giữ màu xanh mướt. Cuối cùng thả giá đỗ vào rồi tắt bếp ngay, xếp các khúc cá lên mặt tô canh, chan nước dùng nóng hổi cùng rau củ và rắc rau ngổ, ngò gai, hành lá, ớt sừng thái lát cùng tỏi phi vàng lên trên.', NULL, NULL),
('vn-canh-02_v4_step_1', 'vn-canh-02', 1, 'prep', 'Làm sạch cua đồng và khêu gạch cua', 'Ngâm 500 g cua đồng trong chậu nước sạch khoảng 15–20 phút cho nhả hết bùn đất, xóc rửa nhiều lần đến khi nước trong. Tách bỏ mai cua, lột bỏ phần yếm và chất bẩn ở miệng cua; dùng tăm nhọn khêu lấy toàn bộ phần gạch cua màu vàng cam trong mai ra chén riêng.', 'Tự sơ chế cua sống giúp nước canh ngọt đậm và sạch cát; nếu dùng cua xay sẵn, hãy chọn hàng tươi mới xay trong ngày.', 15),
('vn-canh-02_v4_step_2', 'vn-canh-02', 2, 'prep', 'Giã thịt cua và lọc lấy nước cốt cua', 'Cho phần thân cua đã làm sạch vào cối cùng 3 g muối ăn, giã thật nhuyễn mịn. Đổ 600 ml nước lọc vào bóp nhẹ cho thịt cua tan đều rồi gạn qua rây lưới mịn vào nồi nấu canh; tiếp tục đổ 600 ml nước lọc còn lại vào phần bã vỏ, bóp và lọc lần hai để thu trọn phần thịt cua, bỏ sạch xác vỏ.', 'Cho chút muối khi giã giúp đạm cua kết dính dẻo hơn, khi đun sẽ đóng thành tảng riêu dày và không bị bở vụn.', 8),
('vn-canh-02_v4_step_3', 'vn-canh-02', 3, 'prep', 'Sơ chế rau đay, mồng tơi, mướp hương và hành tím', 'Nhặt bỏ cọng già của 400 g rau đay và rau mồng tơi, giữ phần lá và đọt non, rửa sạch rồi thái khúc nhỏ khoảng 1 cm để canh có độ sánh mịn. Mướp hương gọt vỏ, rửa sạch, bổ đôi dọc thân và thái lát chéo dày 0,7 cm. Hành tím bóc vỏ, băm nhuyễn 15 g và chia làm hai phần bằng nhau.', NULL, NULL),
('vn-canh-02_v4_step_4', 'vn-canh-02', 4, 'cook', 'Đun nước cua cho đóng tảng riêu nổi mặt', 'Hòa một nửa lượng hành tím băm vào nồi nước lọc cua, đặt lên bếp đun ở lửa vừa và khuấy nhẹ một chiều trong 2 phút đầu để thịt cua không lắng bén đáy nồi. Khi nước bắt đầu nóng già và thịt cua tách lớp, ngừng khuấy hoàn toàn, hạ lửa nhỏ vừa để riêu cua từ từ kết thành mảng dày nổi lên mặt nồi mà không bị trào.', 'Tuyệt đối không khuấy khi nước cua gần sôi và không đun lửa lớn quá mức vì bọt cua dễ trào ra ngoài và làm vỡ tảng riêu.', 8),
('vn-canh-02_v4_step_5', 'vn-canh-02', 5, 'cook', 'Phi hành tím chưng gạch cua vàng thơm', 'Trong lúc đợi nồi canh sôi, bắc chảo nhỏ với 15 ml dầu ăn trên lửa vừa, cho nửa lượng hành tím băm còn lại vào phi thơm. Khi hành dậy mùi, trút chén gạch cua vào chưng nhanh tay khoảng 1–2 phút cho gạch chuyển màu vàng cam óng ả và chín thơm.', NULL, 2),
('vn-canh-02_v4_step_6', 'vn-canh-02', 6, 'cook', 'Thả mướp hương, rau đay và mồng tơi vào canh', 'Dùng vá gạt nhẹ tảng riêu cua sang một bên mép nồi. Thả mướp hương vào khoảng trống trước, đợi nước sôi lăn tăn lại rồi cho rau đay và mồng tơi vào theo mép nồi, ấn nhẹ cho rau ngập nước. Nêm 3 g muối còn lại, 6 g hạt nêm, 10 ml nước mắm ngon và 5 g mắm tôm (nếu dùng).', 'Thả rau vào mép nồi thay vì đổ thẳng lên giữa mặt nước sẽ giữ nguyên vẹn tảng riêu cua đẹp mắt.', 3),
('vn-canh-02_v4_step_7', 'vn-canh-02', 7, 'finish', 'Trút gạch cua chưng và hoàn thiện tô canh', 'Nấu thêm 2 phút ở lửa vừa đến khi rau mồng tơi, rau đay chín mềm xanh mướt và mướp hương vừa chuyển trong, thịt cua chín kỹ hoàn toàn. Rưới phần gạch cua đã chưng lên mặt nồi, khuấy nhẹ mép nồi rồi tắt bếp ngay để giữ trọn vị ngọt và sắc xanh của rau.', NULL, NULL),
('vn-canh-03_v4_step_1', 'vn-canh-03', 1, 'prep', 'Nạo sạch ruột và chần khổ qua giảm đắng', 'Rửa sạch 4 trái khổ qua, cắt bỏ hai đầu, dùng mũi dao rạch một đường dọc thân rồi dùng cán muỗng nạo sạch toàn bộ hạt và phần màng trắng gây đắng bên trong. Đun sôi một nồi nước nhỏ pha 4 g muối, chần nhanh khổ qua trong 30–45 giây rồi vớt ngay vào thau nước lạnh cho nguội hẳn, để ráo nước. Tận dụng nước nóng trụng mềm vài cọng lá hành lá để làm dây buộc.', 'Nạo thật sạch lớp màng trắng sát ruột và chần nhanh rồi ngâm nước lạnh giúp khổ qua hết đắng gắt mà vẫn giữ màu xanh tươi.', 5),
('vn-canh-03_v4_step_2', 'vn-canh-03', 2, 'prep', 'Ngâm mộc nhĩ và băm nhỏ rau thơm', 'Ngâm 20 g mộc nhĩ khô vào nước ấm khoảng 15 phút cho nở mềm hoàn toàn, rửa lại nhiều lần cho sạch sạn, cắt bỏ chân nấm cứng và băm nhỏ. Băm nhuyễn hành tím, tỏi và phần đầu trắng của hành lá; phần lá hành còn lại và ngò rí rửa sạch, thái nhỏ.', NULL, 15),
('vn-canh-03_v4_step_3', 'vn-canh-03', 3, 'marinate', 'Trộn và ướp nhân thịt heo xay mộc nhĩ', 'Cho 250 g thịt heo xay vào tô lớn cùng mộc nhĩ băm, hành tím, tỏi, đầu hành lá băm, 1 quả trứng gà đánh tan, 6 g hạt nêm, 3 g đường và 2 g tiêu đen xay. Trộn và quết đều theo một chiều khoảng 2 phút cho khối nhân dẻo quánh, ướp nghỉ 10 phút cho thấm vị.', 'Quết nhân kỹ theo một chiều kết hợp trứng gà giúp nhân thịt kết dính chặt, không bị rời rạc hay trào ra khi hầm.', 10),
('vn-canh-03_v4_step_4', 'vn-canh-03', 4, 'prep', 'Nhồi thịt vào khổ qua và buộc cố định', 'Múc từng thìa nhân thịt nhồi chặt tay vào lòng mỗi trái khổ qua, dùng ngón tay nén nhẹ hai đầu cho nhân đầy khít không còn khe rỗng. Dùng cọng hành lá đã trụng mềm quấn nhẹ một vòng ngang thân mỗi trái khổ qua và thắt nút cố định để giữ miệng khổ qua khép kín khi nấu.', NULL, NULL),
('vn-canh-03_v4_step_5', 'vn-canh-03', 5, 'cook', 'Hầm khổ qua trong nước sôi mở vung', 'Đun sôi 1,5 lít nước lọc trong nồi sâu lòng trên lửa lớn. Khi nước sôi bùng, nhẹ nhàng thả từng trái khổ qua nhồi thịt vào, hạ xuống lửa vừa và để mở nắp hoàn toàn, hầm trong 22–25 phút. Thường xuyên dùng vá hớt sạch bọt nổi để nước canh trong vắt.', 'Chỉ thả khổ qua khi nước đã sôi già và tuyệt đối không đậy nắp trong lúc hầm để vỏ khổ qua không bị ngả vàng xỉn màu.', 24),
('vn-canh-03_v4_step_6', 'vn-canh-03', 6, 'cook', 'Kiểm tra độ chín và nêm gia vị nước dùng', 'Dùng đầu đũa xiên thử phần thân khổ qua thấy mềm mượt và nhân thịt bên trong chín chắc hoàn toàn (không còn nước hồng tiết ra). Nêm 6 g hạt nêm còn lại, 4 g muối và 3 g đường vào nước canh, khuấy nhẹ cho tan đều rồi nếm lại vị thanh ngọt hài hòa và tắt bếp.', 'Không nên nêm nước mắm vào canh khổ qua vì dễ làm nước canh ngả vị chua nhẹ nếu để qua bữa.', NULL),
('vn-canh-03_v4_step_7', 'vn-canh-03', 7, 'finish', 'Cắt khoanh và hoàn thiện tô canh khổ qua', 'Nhẹ nhàng vớt các trái khổ qua ra đĩa, cắt khoanh tròn dày khoảng 2,5–3 cm vừa ăn rồi xếp ngay ngắn vào tô lớn. Chan ngập nước canh nóng hổi, rắc hành lá cắt nhỏ, ngò rí và 1 g tiêu đen xay lên trên mặt rồi thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('vn-canh-04_v4_step_1', 'vn-canh-04', 1, 'prep', 'Chần sạch sườn non khử mùi hôi', 'Rửa sạch 450 g sườn non đã chặt khúc 3–4 cm. Đun sôi một nồi nước riêng với 3 g muối ăn, thả sườn vào chần nhanh 2–3 phút trên lửa lớn để đẩy hết máu thừa và tạp chất. Vớt sườn ra rổ, xả sạch lại dưới vòi nước lạnh rồi để thật ráo.', 'Chần sơ sườn với chút muối và xả sạch lại giúp nước canh sau khi ninh trong veo, không bị đục hay có mùi hôi.', 3),
('vn-canh-04_v4_step_2', 'vn-canh-04', 2, 'marinate', 'Ướp sườn non và sơ chế bí đao', 'Ướp sườn đã ráo với 10 ml nước mắm ngon, 5 g hạt nêm và 1 g tiêu đen xay trong 10–15 phút. Trong lúc chờ, gọt bỏ vỏ xanh của 1 quả bí đao, bổ dọc bỏ hết phần ruột xốp và hạt, rửa sạch rồi cắt khúc dày khoảng 2 cm để khi nấu không bị nát. Băm nhỏ 20 g hành tím, đập dập 10 g gừng, thái nhỏ hành lá và ngò gai.', NULL, 12),
('vn-canh-04_v4_step_3', 'vn-canh-04', 3, 'cook', 'Phi thơm hành tím và xào săn sườn non', 'Làm nóng nồi đáy dày với 15 ml dầu ăn trên lửa vừa, cho đầu hành đập dập và hành tím băm vào phi thơm 30 giây. Trút sườn non đã ướp vào đảo đều khoảng 3–4 phút cho miếng sườn săn chắc các mặt và dậy mùi thơm.', NULL, 4),
('vn-canh-04_v4_step_4', 'vn-canh-04', 4, 'cook', 'Hầm sườn non lấy nước dùng ngọt trong', 'Đổ 1,5 lít nước lọc vào nồi sườn, bật lửa lớn đun sôi bùng rồi hớt sạch lớp bọt nổi trên mặt. Thả lát gừng đập dập vào nồi, hạ xuống lửa nhỏ liu riu và hầm khoảng 25 phút cho đến khi thịt sườn chín mềm, dễ dàng xiên đũa qua.', 'Hầm sườn ở lửa nhỏ liu riu và mở hé nắp giúp chất ngọt tiết ra từ từ mà nước dùng vẫn giữ được độ trong suốt.', 25),
('vn-canh-04_v4_step_5', 'vn-canh-04', 5, 'cook', 'Nấu bí đao chín tới giữ độ ngọt mát', 'Khi sườn đã mềm, thả toàn bộ bí đao cắt miếng vào nồi, tăng nhẹ lên lửa vừa để nước sôi trở lại rồi nấu khoảng 5–6 phút cho đến khi thịt bí chuyển màu trắng trong mờ, xiên nhẹ thấy mềm nhưng vẫn giữ nguyên góc cạnh.', 'Bí đao chín rất nhanh, không nên nấu quá 7 phút kẻo bí nhũn nát và mất đi hương vị thanh mát.', 6),
('vn-canh-04_v4_step_6', 'vn-canh-04', 6, 'finish', 'Nêm gia vị và rắc rau thơm hoàn thiện', 'Nêm thêm 15 ml nước mắm ngon, 5 g hạt nêm và 3 g muối còn lại, khuấy nhẹ tránh làm nát bí rồi nếm lại vừa miệng. Tắt bếp, thả hành lá và ngò gai thái nhỏ cùng 1 g tiêu đen xay lên mặt nồi rồi múc ra tô dùng nóng.', NULL, NULL),
('vn-canh-05_v4_step_1', 'vn-canh-05', 1, 'prep', 'Sơ chế hạt sen và cắt miếng bí đỏ', 'Rửa sạch 100 g hạt sen tươi, tách nhẹ đầu hạt để rút bỏ hoàn toàn phần tâm sen xanh nếu còn sót vì tâm sen gây vị đắng. Bí đỏ gọt vỏ, bỏ sạch phần ruột xơ và hạt, rửa qua nước lạnh rồi cắt miếng vuông cỡ 2,5 cm để bí chín nhanh mà không dễ vỡ vụn.', 'Nếu dùng hạt sen khô thay cho sen tươi, hãy ngâm nước ấm trước 30 phút rồi ninh hạt sen trước 10 phút cho bở đều cùng bí đỏ.', NULL),
('vn-canh-05_v4_step_2', 'vn-canh-05', 2, 'marinate', 'Ướp thịt heo nạc xay cho đậm đà', 'Cho 200 g thịt heo nạc xay vào tô, ướp với một nửa chỗ hành tím băm, 7 ml nước mắm ngon, 4 g hạt nêm và 1 g tiêu đen xay. Trộn đều rồi ướp 10 phút cho thịt ngấm gia vị; trong lúc chờ, thái nhỏ hành lá và ngò gai, băm nhỏ tỏi và phần hành tím còn lại.', NULL, 10),
('vn-canh-05_v4_step_3', 'vn-canh-05', 3, 'cook', 'Phi thơm hành tỏi và xào săn thịt băm', 'Đặt nồi lên bếp với 15 ml dầu ăn ở lửa vừa, cho tỏi băm và phần hành tím băm còn lại vào phi thơm vàng nhẹ. Trút thịt heo xay đã ướp vào đảo nhanh tay cho thịt tơi rời và săn lại hoàn toàn, thêm 8 g đường và 8 ml nước mắm còn lại, xào thêm 1 phút cho dậy mùi.', 'Dùng đũa đảo tơi liên tục khi thịt mới vào nồi nóng giúp thịt băm không bị vón cục lớn.', 3),
('vn-canh-05_v4_step_4', 'vn-canh-05', 4, 'cook', 'Xào sơ bí đỏ thấm gia vị trước khi đổ nước', 'Cho toàn bộ bí đỏ cắt miếng vào nồi thịt, nêm 5 g muối ăn rồi đảo đều trên lửa vừa khoảng 2 phút cho miếng bí săn bề mặt và áo đều hương thơm của thịt xào.', NULL, 2),
('vn-canh-05_v4_step_5', 'vn-canh-05', 5, 'cook', 'Ninh bí đỏ và hạt sen chín bở mềm', 'Đổ 1,2 lít nước lọc vào nồi, đun lửa lớn đến khi nước sôi bùng thì hớt sạch bọt nổi. Thả 100 g hạt sen tươi vào, hạ xuống lửa vừa đậy hé vung và nấu khoảng 15 phút cho đến khi hạt sen chín bở và dùng đũa xiên qua miếng bí đỏ dễ dàng.', 'Hớt bọt kỹ ngay khi nước vừa sôi và không khuấy mạnh khi bí đã mềm sẽ giúp nước canh trong và vàng đẹp.', 15),
('vn-canh-05_v4_step_6', 'vn-canh-05', 6, 'finish', 'Tạo độ sánh nhẹ và hoàn thiện tô canh', 'Nêm 6 g hạt nêm còn lại vào nồi, nếm thử lại cho vừa vị ngọt thanh tự nhiên rồi dùng lưng muôi dầm nhẹ 2–3 miếng bí đỏ chín cho nước canh hơi sánh vàng. Tắt bếp, rắc hành lá, ngò gai thái nhỏ cùng 1 g tiêu đen xay rồi múc ra tô thưởng thức nóng.', NULL, NULL),
('vn-canh-06_v4_step_1', 'vn-canh-06', 1, 'prep', 'Ngâm sạch cát và sơ chế rau thơm', 'Ngâm 1 kg ngao tươi trong thau nước pha 3 g muối ăn và vài lát ớt tươi khoảng 30 phút để ngao nhả hết bùn cát, sau đó chà rửa sạch lớp vỏ ngoài và xả kỹ qua 2–3 lần nước. Trong lúc ngâm ngao, bổ múi cau 2,5 quả cà chua, gọt vỏ bỏ mắt thái lát 0,5 quả dứa, băm nhỏ 20 g hành tím, cắt khúc 2 cm thì là và hành lá, phần ớt còn lại thái lát.', 'Ngâm ngao với nước muối loãng thêm vài lát ớt cay là cách đơn giản nhất giúp ngao mở vỏ nhả sạch cát mà không bị chết.', 30),
('vn-canh-06_v4_step_2', 'vn-canh-06', 2, 'cook', 'Luộc ngao mở miệng và gạn lấy nước dùng trong', 'Cho ngao sạch vào nồi cùng 1,4 lít nước lọc, đun ở lửa lớn đến khi nước sôi và toàn bộ vỏ ngao vừa há mở miệng hoàn toàn thì tắt bếp ngay để thịt ngao không bị teo dai. Vớt ngao ra rổ, loại bỏ những con không há miệng, tách bỏ vỏ lấy phần thịt ngao rồi rửa nhanh qua nước lọc cho sạch hẳn cát; phần nước luộc ngao đổ ra tô lớn để yên 5 phút cho lắng hết cặn dưới đáy.', 'Không luộc ngao quá lâu sau khi vỏ đã mở miệng kẻo thịt ngao bị quắt nhỏ và dai mất độ ngọt.', 7),
('vn-canh-06_v4_step_3', 'vn-canh-06', 3, 'marinate', 'Ướp thịt ngao và xào cùng cà chua tạo màu', 'Ướp phần thịt ngao với 1/3 chỗ hành tím băm và 7 ml nước mắm cốt khoảng 5 phút. Làm nóng nồi khô với 15 ml dầu ăn trên lửa vừa, phi thơm phần hành tím băm còn lại rồi cho thịt ngao vào đảo nhanh tay 1 phút, trút ra đĩa riêng. Dùng tiếp nồi đó xào cà chua bổ múi cau với 1 g muối còn lại khoảng 2 phút cho cà chua mềm tơi và tiết màu đỏ cam.', NULL, 5),
('vn-canh-06_v4_step_4', 'vn-canh-06', 4, 'cook', 'Chắt nước luộc ngao và nấu chín dứa chua ngọt', 'Từ từ rót phần nước luộc ngao đã lắng vào nồi cà chua xào, khéo léo chừa lại phần cặn cát đọng dưới đáy tô. Bật lửa lớn đun sôi, sau đó thả các lát dứa vào nấu trên lửa vừa khoảng 5 phút cho dứa chín mềm và tiết vị chua ngọt thanh dịu hòa quyện cùng nước ngao.', 'Chắt nước luộc ngao thật nhẹ tay để giữ phần nước trong vắt và loại bỏ hoàn toàn cặn sạn dưới đáy tô.', 5),
('vn-canh-06_v4_step_5', 'vn-canh-06', 5, 'cook', 'Nêm gia vị và trút thịt ngao vào nồi canh', 'Nêm vào nồi 6 g hạt nêm, 5 g đường cát trắng và 8 ml nước mắm cốt còn lại, khuấy nhẹ và nếm thử lại cho đạt vị chua thanh, ngọt hậu, mặn vừa. Trút đĩa thịt ngao đã xào vào nồi, đun sôi lăn tăn lại 1 phút cho thịt ngao ngấm đều nước canh.', NULL, NULL),
('vn-canh-06_v4_step_6', 'vn-canh-06', 6, 'finish', 'Thả thì là, hành lá và hoàn thiện món canh', 'Tắt bếp ngay rồi cho toàn bộ thì là tươi, hành lá cắt khúc và ớt thái lát vào đảo nhẹ một lượt để rau vừa chín tới bằng hơi nóng, giữ được màu xanh tươi và hương thơm nồng đặc trưng của thì là. Múc canh ra tô lớn dùng nóng với cơm trắng.', NULL, NULL),
('vn-kho-01_v4_step_1', 'vn-kho-01', 1, 'prep', 'Làm sạch, chần sơ và cắt khối thịt ba chỉ', 'Cạo sạch phần bì của 500 g thịt ba chỉ, chà xát đều với 5 g muối hạt rồi rửa sạch dưới vòi nước lạnh. Đun sôi nồi nước, thả thịt vào chần sơ 3 phút để loại bỏ tạp chất và mùi hôi, vớt ra rửa lại nước mát, để ráo và cắt thành các miếng vuông đều nhau cỡ 4x4 cm.', 'Chọn miếng ba chỉ dưới có lớp nạc mỡ đan xen đều và phần da mỏng để khi kho xong thịt mềm béo mà không bị bở nát.', 5),
('vn-kho-01_v4_step_2', 'vn-kho-01', 2, 'prep', 'Luộc chín và bóc vỏ trứng gà', 'Cho 5 quả trứng gà vào nồi nước ngập mặt, đun lửa vừa từ lúc nước nguội đến khi sôi thì hạ lửa nhỏ luộc thêm 8 phút cho lòng đỏ vừa chín tới. Vớt trứng ngâm ngay vào tô nước lạnh 5 phút rồi bóc sạch vỏ.', 'Dùng tăm nhọn xăm nhẹ vài lỗ nhỏ quanh lòng trắng sau khi bóc vỏ sẽ giúp trứng dễ thấm nước kho hơn.', 8),
('vn-kho-01_v4_step_3', 'vn-kho-01', 3, 'marinate', 'Ướp thịt ba chỉ thấm gia vị', 'Trộn thịt ba chỉ trong tô lớn với một nửa lượng hành tím và tỏi băm nhuyễn, 15 ml nước mắm ngon, 15 g đường cát trắng, 5 g hạt nêm và 1 g tiêu đen xay. Xoa đều gia vị lên từng mặt thịt, bọc kín và ướp ít nhất 30 phút cho ngấm sâu.', NULL, 30),
('vn-kho-01_v4_step_4', 'vn-kho-01', 4, 'sauce', 'Thắng nước màu cánh gián', 'Làm nóng nồi đáy dày trên lửa nhỏ với 5 ml dầu ăn và 15 g đường cát trắng còn lại. Đun nhẹ cho đường tan chảy và nổi bọt chuyển màu nâu cánh gián thì lập tức đổ từ từ 100 ml nước lọc ấm vào khuấy tan đều để hãm nhiệt, tránh cháy đắng.', 'Không khuấy đường khi mới bắc lên bếp ở giai đoạn đầu; chỉ lắc nhẹ nồi để đường tan đều và lên màu hổ phách trong đẹp.', 5),
('vn-kho-01_v4_step_5', 'vn-kho-01', 5, 'cook', 'Xào săn thịt và đổ nước dừa xiêm', 'Cho 10 ml dầu ăn vào nồi, phi thơm phần hành tím và tỏi băm còn lại trên lửa vừa trong 1 phút. Trút toàn bộ thịt ba chỉ đã ướp vào đảo săn các mặt khoảng 5 phút rồi rưới nước màu cánh gián vào đảo đều cho thịt áo màu đẹp. Đổ 400 ml nước dừa tươi cùng 20 ml nước mắm còn lại vào ngập mặt thịt, đun lửa lớn cho sôi bùng và hớt sạch bọt nổi.', NULL, 6),
('vn-kho-01_v4_step_6', 'vn-kho-01', 6, 'cook', 'Kho liu riu không đậy nắp cho thịt mềm rệu', 'Hạ lửa nhỏ nhất, không đậy nắp và kho liu riu trong 40 phút cho thịt chín mềm từ từ và phần mỡ trở nên trong veo. Nếu nước cạn nhanh mà thịt chưa đủ mềm, châm thêm 200 ml nước lọc nóng sao cho vừa xâm xấp mặt thịt.', 'Kho mở nắp giúp hơi nước thoát đều, nước kho trong và thịt lên màu đỏ nâu tự nhiên không bị đục.', 40),
('vn-kho-01_v4_step_7', 'vn-kho-01', 7, 'finish', 'Kho cùng trứng gà và hoàn thiện món', 'Thả nhẹ 5 quả trứng gà đã bóc vỏ và 1 quả ớt sừng đỏ nguyên trái vào nồi, kho thêm 15 phút trên lửa nhỏ cho trứng ngấm vị và nước kho sánh nhẹ, không khuấy mạnh tránh làm vỡ trứng. Tắt bếp, múc thịt và trứng ra đĩa sâu lòng, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng.', NULL, 15),
('vn-kho-02_v4_step_1', 'vn-kho-02', 1, 'prep', 'Làm sạch nhớt và ướp khứa cá lóc', 'Chà xát đều 5 g muối hạt lên các khứa cá lóc để khử sạch nhớt và mùi tanh, rửa lại nước lạnh rồi thấm thật khô. Ướp cá với 35 ml nước mắm, 8 g đường cát trắng, 4 g hạt nêm, 2 g tiêu đen xay, phần đầu hành lá băm cùng một nửa tỏi và hành tím băm trong 25 phút cho thịt cá săn chắc.', 'Ướp cá đủ thời gian với nước mắm ngon giúp thịt cá săn cứng tự nhiên, khi kho không bị bở nát.', 25),
('vn-kho-02_v4_step_2', 'vn-kho-02', 2, 'cook', 'Thắng tóp mỡ giòn và phi thơm gia vị', 'Bắc tộ đất hoặc chảo lên bếp, cho 120 g thịt ba chỉ thái mỏng vào đảo trên lửa vừa khoảng 6 phút cho đến khi thịt tiết mỡ và chuyển vàng giòn thành tóp mỡ. Vớt phần tóp mỡ ra chén riêng, giữ lại phần mỡ heo nóng trong nồi cùng 5 ml dầu ăn để phi thơm phần hành tím và tỏi băm còn lại.', NULL, 6),
('vn-kho-02_v4_step_3', 'vn-kho-02', 3, 'sauce', 'Áp chảo sơ cá và thắng nước màu', 'Cho 5 ml dầu ăn còn lại vào chảo khác, chiên áp chảo nhẹ từng khứa cá đã ướp khoảng 1 phút mỗi mặt cho săn se bề mặt rồi gắp riêng. Dùng chảo đó cho 12 g đường vào đun lửa nhỏ đến khi chuyển màu nâu cánh gián đậm, thêm 20 ml nước ấm khuấy đều để làm nước màu.', NULL, NULL),
('vn-kho-02_v4_step_4', 'vn-kho-02', 4, 'cook', 'Xếp cá vào tộ và kho thấm lửa nhỏ', 'Xếp các khứa cá vào tộ đất có sẵn hành tỏi phi và mỡ heo, rưới toàn bộ phần nước ướp cá, nước màu vừa thắng cùng 100 ml nước ấm vào xâm xấp mặt cá. Đun lửa lớn cho sôi bùng 1 phút rồi hạ lửa nhỏ liu riu, thả 2 quả ớt hiểm vào kho mở hé vung trong 20 phút.', 'Không dùng đũa đảo cá trong tộ; chỉ cầm quai tộ lắc nhẹ hoặc dùng muỗng múc nước kho rưới lên mặt cá để khứa cá nguyên vẹn.', 20),
('vn-kho-02_v4_step_5', 'vn-kho-02', 5, 'cook', 'Sánh kẹo nước kho trên lửa vừa', 'Mở hẳn nắp tộ, tăng lên lửa vừa kho thêm 5 phút cho nước kho rút cạn bớt và sánh sệt óng ả bám đều quanh khứa cá. Nếm thử nước kho xem độ mặn ngọt đã hài hòa chưa.', NULL, 5),
('vn-kho-02_v4_step_6', 'vn-kho-02', 6, 'finish', 'Rắc tóp mỡ, tiêu đen và hành lá', 'Khi nước sốt vừa sệt kẹo và khứa cá chín chắc hoàn toàn, rắc phần tóp mỡ vàng giòn, 1 g tiêu đen xay còn lại và phần lá hành cắt khúc lên mặt tộ cá rồi tắt bếp. Dọn nóng ngay khi còn sôi lăn tăn trong tộ đất.', 'Cho tóp mỡ vào sau cùng ngay trước khi tắt bếp để tóp mỡ giữ được độ giòn rụm hòa quyện với nước sốt béo thơm.', NULL),
('vn-kho-03_v4_step_1', 'vn-kho-03', 1, 'prep', 'Khử mùi, chặt miếng gà và sơ chế gừng sả', 'Chà xát 600 g đùi gà với 5 g muối hạt và vài lát gừng đập dập để khử mùi hôi, rửa sạch lại với nước rồi để ráo, chặt thành từng miếng vừa ăn cỡ 3–4 cm. Gừng tươi thái sợi nhỏ; sả tươi, hành tím và tỏi băm nhuyễn; ớt hiểm thái lát mỏng.', 'Không chặt miếng gà quá nhỏ vì thịt gà sẽ co lại khi kho, dễ bị khô và nát xương.', NULL),
('vn-kho-03_v4_step_2', 'vn-kho-03', 2, 'marinate', 'Ướp thịt gà với nước mắm và sả gừng', 'Cho gà vào tô lớn, ướp cùng một nửa lượng gừng thái sợi, một nửa lượng sả băm, một nửa tỏi băm, 15 ml nước mắm, 5 g đường cát trắng, 5 g hạt nêm, 3 g muối và 1 g tiêu đen xay. Trộn đều và để 25 phút cho gia vị thấm vào từng thớ thịt.', NULL, 25),
('vn-kho-03_v4_step_3', 'vn-kho-03', 3, 'sauce', 'Thắng nước màu và phi thơm sả gừng', 'Làm nóng chảo sâu lòng trên lửa vừa với 25 ml dầu ăn và 15 g đường cát trắng còn lại, khuấy nhẹ đến khi đường tan và chuyển màu nâu cánh gián. Hạ lửa nhỏ rồi trút nhanh phần hành tím, tỏi, sả băm và gừng sợi còn lại vào đảo thơm 30 giây.', 'Cho sả và gừng vào ngay khi đường vừa chuyển màu cánh gián để hãm nhiệt, vừa tạo mùi thơm nức vừa giúp nước màu không bị cháy khét.', NULL),
('vn-kho-03_v4_step_4', 'vn-kho-03', 4, 'cook', 'Xào săn thịt gà trên lửa lớn', 'Vặn lửa lớn, cho toàn bộ thịt gà đã ướp vào chảo đảo liên tục trong 5 phút đến khi da gà săn lại, bề mặt miếng thịt đổi màu vàng nâu đẹp mắt và thấm đều dầu thơm.', NULL, 5),
('vn-kho-03_v4_step_5', 'vn-kho-03', 5, 'cook', 'Kho nhỏ lửa cho gà chín mềm sánh sốt', 'Rót 120 ml nước lọc ấm vào chảo cho xâm xấp mặt thịt gà, thêm 15 ml nước mắm còn lại và ớt thái lát. Đợi nước sôi lại thì hạ lửa nhỏ, đậy nắp kho liu riu 18 phút, thỉnh thoảng đảo nhẹ để thịt gà chín thấu vào tận xương không còn đỏ hồng.', NULL, 18),
('vn-kho-03_v4_step_6', 'vn-kho-03', 6, 'finish', 'Cô cạn nhẹ nước sốt và trình bày', 'Mở nắp, tăng lên lửa vừa đảo thêm 2–3 phút đến khi nước kho cạn sệt và bám bóng quanh từng miếng thịt gà. Nêm nếm lại vừa miệng, tắt bếp rồi rắc 1 g tiêu đen xay còn lại lên trên và dọn ăn nóng.', 'Giữ lại một ít nước kho sánh sệt dưới đáy chảo để chan cơm hoặc chấm rau luộc sẽ rất đậm vị.', NULL),
('vn-kho-04_v4_step_1', 'vn-kho-04', 1, 'prep', 'Chần sơ sườn non và sơ chế rau củ', 'Chặt 550 g sườn non thành miếng dài 3–4 cm. Đun sôi nồi nước với 4 g muối ăn, thả sườn vào chần nhanh 3 phút để sạch bọt bẩn rồi vớt ra rửa lại nước mát, thấm thật khô ráo. Cà chua bỏ cuống thái hạt lựu, hành tây thái múi cau mỏng, tỏi và hành tím băm nhuyễn, hành lá thái nhỏ.', 'Không luộc sườn quá lâu ở bước chần để tránh làm thịt mất chất ngọt và bị khô xác khi chiên.', 3),
('vn-kho-04_v4_step_2', 'vn-kho-04', 2, 'marinate', 'Ướp sườn non và pha chén sốt chua ngọt', 'Ướp sườn với 15 ml nước mắm, 10 g đường cát trắng, 3 g hạt nêm, 2 g muối, 1 g tiêu đen xay và một nửa hành tím băm trong 20 phút. Trong chén riêng, khuấy tan 15 ml nước mắm còn lại, 30 ml giấm gạo, 20 ml tương cà, 25 g đường, 3 g hạt nêm và 100 ml nước lọc.', NULL, 20),
('vn-kho-04_v4_step_3', 'vn-kho-04', 3, 'cook', 'Chiên sườn vàng xém hai mặt', 'Làm nóng chảo với 35 ml dầu ăn trên lửa vừa, gạt bớt hành băm bám trên miếng sườn rồi xếp từng dẻ sườn vào chiên khoảng 8 phút đến khi bề mặt sườn vàng ruộm và xém cạnh đều hai mặt. Gắp sườn ra đĩa có lót giấy thấm dầu, chắt bớt dầu thừa trong chảo.', 'Thấm thật khô sườn trước khi chiên và giữ lửa vừa giúp sườn không bị bắn dầu và không cháy xém phần đường ướp.', 8),
('vn-kho-04_v4_step_4', 'vn-kho-04', 4, 'cook', 'Xào nhuyễn sốt cà chua và đun sôi gia vị', 'Dùng lại chảo với 10 ml dầu ăn còn lại, phi thơm phần hành tím và tỏi băm trên lửa vừa trong 1 phút. Cho cà chua thái hạt lựu vào đảo đều 4 phút đến khi cà chua chín nhuyễn ra sốt đỏ đẹp, rồi đổ chén nước sốt chua ngọt đã pha vào đun sôi lăn tăn.', NULL, 5),
('vn-kho-04_v4_step_5', 'vn-kho-04', 5, 'cook', 'Rim sườn thấm đẫm sốt chua ngọt', 'Trút toàn bộ sườn đã chiên vàng vào chảo sốt, đảo đều rồi hạ lửa nhỏ, đậy nắp rim trong 10 phút cho thịt sườn mềm róc xương và thấm sâu vị chua ngọt. Mở nắp, thả hành tây vào đảo thêm 2 phút trên lửa vừa đến khi sốt sánh bóng áo đều quanh từng miếng sườn.', 'Cho hành tây vào giai đoạn cuối để hành vừa chín tới, giữ được độ giòn ngọt mà không bị nhũn nát.', 12),
('vn-kho-04_v4_step_6', 'vn-kho-04', 6, 'finish', 'Nêm lại sốt và trình bày ra đĩa', 'Nếm thử phần sốt xem độ chua ngọt đã cân bằng vừa ý chưa rồi tắt bếp. Xếp sườn ra đĩa, rưới phần sốt sánh còn lại lên trên, rắc hành lá thái nhỏ và 1 g tiêu đen xay còn lại để dậy mùi thơm rồi dùng nóng.', NULL, NULL),
('vn-kho-05_v4_step_1', 'vn-kho-05', 1, 'prep', 'Làm sạch tôm và khử mùi nước muối loãng', 'Cắt bỏ râu, chân và phần ngạnh đầu nhọn của 450 g tôm tươi, khều sạch chỉ đen trên lưng. Rửa nhanh tôm qua nước pha 5 g muối rồi xả lại nước sạch, trút ra rổ để thật ráo nước trước khi chế biến.', 'Để tôm thật ráo nước và giữ nguyên vỏ khi rim sẽ giúp vỏ tôm giòn ngon, thịt bên trong ngọt chắc không bị ra nước.', NULL),
('vn-kho-05_v4_step_2', 'vn-kho-05', 2, 'prep', 'Sơ chế hành tím, tỏi, hành lá và ớt', 'Bóc vỏ hành tím và tỏi khô rồi băm thật nhỏ, chia làm 2 phần bằng nhau để phi thơm và cho vào lúc rim. Hành lá rửa sạch thái nhỏ; ớt tươi bỏ cuống rồi thái lát mỏng để ráo.', NULL, NULL),
('vn-kho-05_v4_step_3', 'vn-kho-05', 3, 'cook', 'Phi thơm hành tỏi và rang săn tôm trên lửa lớn', 'Làm nóng chảo rộng với 20 ml dầu ăn trên lửa vừa, phi thơm 1/2 lượng hành tím và tỏi băm trong 1 phút. Tăng lên lửa lớn rồi trút tôm vào đảo nhanh tay trong 3–4 phút cho đến khi vỏ tôm chuyển màu đỏ cam rực, thịt tôm cong săn khoảng 70% và hơi sém thơm.', NULL, 4),
('vn-kho-05_v4_step_4', 'vn-kho-05', 4, 'sauce', 'Nêm nước mắm đường và hành tỏi còn lại', 'Hạ nhỏ bếp hoặc nhấc tạm chảo ra khỏi lửa để tránh đường cháy khét. Rưới 35 ml nước mắm ngon, 22 g đường cát trắng, 40 ml nước lọc và 1/2 phần hành tím tỏi băm còn lại vào chảo, xóc đều tay cho gia vị hòa quyện bám quanh thân tôm.', 'Nhấc chảo khỏi bếp trong vài giây khi cho đường và nước mắm sẽ giúp đường tan từ từ mà không bị cháy đen đắng.', NULL),
('vn-kho-05_v4_step_5', 'vn-kho-05', 5, 'cook', 'Rim mở nắp cho tôm chín kỹ và keo sốt', 'Đặt chảo lại lên bếp ở lửa vừa nhỏ, tuyệt đối không đậy nắp, rim trong 5 phút và đảo nhẹ thường xuyên đến khi tôm chín hồng hoàn toàn, phần nước mắm đường cô đặc sánh bóng áo đẹp quanh vỏ tôm.', 'Không đậy vung khi rim tôm để hơi nước bay đi nhanh, nước sốt sánh kẹo và không gây mùi nồng của vỏ tôm.', 5),
('vn-kho-05_v4_step_6', 'vn-kho-05', 6, 'finish', 'Trộn hành lá, ớt tiêu và dọn dùng nóng', 'Khi nước sốt đã keo bóng, cho hành lá cắt nhỏ, ớt thái lát và 1,5 g tiêu đen xay vào đảo nhanh 15 giây rồi tắt bếp ngay. Gắp tôm ra đĩa, rưới phần sốt keo lên trên và ăn nóng cùng cơm trắng.', NULL, NULL),
('vn-kho-06_v4_step_1', 'vn-kho-06', 1, 'prep', 'Sơ chế thịt ba chỉ và khử hăng củ cải trắng', 'Cạo sạch bì 500 g thịt ba chỉ, xát với 3 g muối hạt rồi rửa sạch, thấm khô và thái miếng vuông dày 2,5–3 cm. Củ cải trắng gọt vỏ, cắt khúc hình con chì to khoảng 3 cm, xóc nhẹ với 2 g muối hạt trong 5 phút rồi rửa lại bằng nước sạch để giảm mùi hăng.', 'Cắt củ cải miếng hơi dày vì trong quá trình kho củ cải sẽ ngót bớt nước và dễ bị nát nếu thái quá mỏng.', 5),
('vn-kho-06_v4_step_2', 'vn-kho-06', 2, 'marinate', 'Ướp thịt ba chỉ thấm gia vị', 'Cho thịt ba chỉ vào tô lớn, ướp với một nửa hành tím băm, 20 ml nước mắm ngon, 8 g hạt nêm, 5 g đường cát trắng, 3 g muối, 1 g tiêu đen xay và đầu hành lá đập dập. Trộn đều và ướp trong 30 phút cho thịt ngấm gia vị.', NULL, 30),
('vn-kho-06_v4_step_3', 'vn-kho-06', 3, 'sauce', 'Thắng nước màu và xào săn thịt', 'Làm nóng nồi đáy dày với 20 ml dầu ăn và 12 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan chảy chuyển màu nâu cánh gián. Nhanh tay rót 50 ml nước lọc nóng vào khuấy tan rồi cho phần hành tím băm còn lại vào phi thơm. Trút thịt ba chỉ đã ướp vào đảo săn trên lửa vừa trong 5 phút.', NULL, 5),
('vn-kho-06_v4_step_4', 'vn-kho-06', 4, 'cook', 'Kho thịt lửa một cho mềm thớ thịt', 'Chế 300 ml nước lọc nóng vào xâm xấp mặt thịt, đun sôi rồi hớt sạch bọt để nước kho thật trong. Hạ lửa nhỏ, đậy hé nắp kho liu riu 20 phút cho thịt bắt đầu mềm và tiết ra vị ngọt béo.', 'Luôn dùng nước nóng để chế vào nồi thịt đang xào giúp thịt không bị co cứng và giữ được độ trong của nước kho.', 20),
('vn-kho-06_v4_step_5', 'vn-kho-06', 5, 'cook', 'Cho củ cải trắng vào kho lửa hai', 'Thả củ cải trắng vào nồi thịt, tắt bếp để nghỉ 10 phút cho thịt và củ cải hồi nhiệt ngấm màu rồi bật bếp lại kho thêm 15 phút trên lửa nhỏ. Khi củ cải chuyển trong mềm, nêm tiếp 15 ml nước mắm và 3 g đường cát trắng còn lại, đun thêm 2 phút cho nước kho sánh hổ phách.', 'Kỹ thuật kho hai lửa giúp miếng thịt lên màu nâu bóng tự nhiên, củ cải thấm đều vị ngọt béo từ thịt mà không bị nát vụn.', 15),
('vn-kho-06_v4_step_6', 'vn-kho-06', 6, 'finish', 'Rắc hành lá, tiêu xay và hoàn thiện món ăn', 'Nêm nếm lại độ mặn ngọt vừa miệng, cho hành lá cắt khúc, ớt tươi thái lát và 1 g tiêu đen xay còn lại vào nồi, đảo nhẹ rồi tắt bếp. Múc thịt kho củ cải ra đĩa sâu lòng và dùng nóng với cơm trắng.', NULL, NULL),
('vn-xao-01_v4_step_1', 'vn-xao-01', 1, 'prep', 'Nhặt rửa rau muống và chuẩn bị tỏi ớt', 'Nhặt bỏ lá úa, lá già và phần gốc xơ cứng của rau muống, ngắt thành từng đoạn dài 6–8 cm. Rửa sạch nhiều lần rồi ngâm nước muối loãng 5 phút, vớt ra rổ để thật ráo nước. Bóc vỏ tỏi ta, đập dập rồi băm nhỏ, chia thành hai phần (2/3 để phi thơm đầu và 1/3 để cho vào cuối). Ớt sừng đỏ rửa sạch, thái lát xéo mỏng.', 'Chọn mớ rau muống ngọn nhỏ, thân non mềm thì khi xào sẽ giòn ngọt và ít bị dai xơ.', NULL),
('vn-xao-01_v4_step_2', 'vn-xao-01', 2, 'prep', 'Chần rau muống và sốc nhiệt nước đá', 'Đun sôi một nồi nước lớn (đủ ngập rau) trên lửa lớn, thả 6 g muối ăn và 5 ml giấm gạo vào khuấy tan. Khi nước sôi bùng, thả rau muống vào đảo nhanh trong 30–45 giây cho rau vừa chuyển màu xanh ngọc tươi rồi vớt ra ngay, thả vào thau nước đá lạnh ngâm 2 phút cho nguội hẳn trước khi vớt ra vắt nhẹ để thật ráo.', 'Không đậy vung khi chần và sốc nhiệt ngay bằng nước đá là bí quyết giúp rau muống giữ màu xanh lục bảo và độ giòn sần sật.', 3),
('vn-xao-01_v4_step_3', 'vn-xao-01', 3, 'cook', 'Phi thơm phần tỏi băm ban đầu', 'Đặt chảo sâu lòng lên bếp ở lửa vừa, làm nóng 30 ml dầu ăn rồi cho 2/3 lượng tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi vừa chuyển màu vàng nhạt và tỏa mùi thơm lừng.', 'Canh lửa vừa và tắt bớt nhiệt nếu chảo quá nóng để tỏi không bị cháy sẫm gây vị đắng.', NULL),
('vn-xao-01_v4_step_4', 'vn-xao-01', 4, 'cook', 'Xào rau muống lửa lớn và nêm gia vị', 'Bật bếp lên lửa lớn nhất, trút toàn bộ phần rau muống đã để ráo vào chảo dầu tỏi và đảo nhanh tay liên tục. Rưới đều 10 ml nước mắm ngon, rắc 5 g hạt nêm, 3 g đường cát trắng và 2 g muối ăn còn lại, đảo đều trong khoảng 1–2 phút cho rau bóng dầu và thấm gia vị.', 'Xào nhanh trên lửa lớn giúp rau không bị tiết nước và giữ nguyên độ giòn thanh.', 2),
('vn-xao-01_v4_step_5', 'vn-xao-01', 5, 'cook', 'Thêm phần tỏi tươi cuối cùng dậy mùi', 'Khi rau đã ngấm đều gia vị và nóng hổi, rắc nốt 1/3 lượng tỏi băm tươi còn lại vào chảo, đảo nhanh tay thêm 20–30 giây cho hương tỏi tươi hòa quyện nồng nàn mà không bị cháy.', NULL, NULL),
('vn-xao-01_v4_step_6', 'vn-xao-01', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Tắt bếp ngay, gắp rau muống xào tỏi ra đĩa lớn, rưới chút nước xào còn trong chảo lên mặt rau và xếp vài lát ớt sừng đỏ lên trên. Dọn dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('vn-xao-02_v4_step_1', 'vn-xao-02', 1, 'prep', 'Thái mỏng và thấm khô thịt thăn bò', 'Rửa nhanh thịt thăn bò qua nước sạch rồi dùng khăn giấy thấm thật khô bề mặt. Đặt miếng thịt lên thớt, thái lát mỏng ngang thớ dày khoảng 0,3 cm để khi xào thịt nhanh chín và giữ độ mềm ngọt.', 'Thấm khô thịt trước khi ướp giúp thịt ngấm gia vị tốt hơn và không bị ra nước lênh láng lúc xào.', NULL),
('vn-xao-02_v4_step_2', 'vn-xao-02', 2, 'marinate', 'Ướp thịt bò mềm đậm đà', 'Cho thịt bò vào tô, ướp cùng 1/3 lượng tỏi băm, 10 ml nước tương (xì dầu), 5 ml dầu hào, 2,5 g hạt nêm, 1,5 g đường cát trắng, 1 g tiêu đen xay và 5 ml dầu ăn. Trộn đều nhẹ tay và ướp trong 15 phút để thịt thấm vị và giữ độ ẩm mượt.', 'Thêm một chút dầu ăn vào bước ướp giúp các thớ thịt tách rời khi gặp chảo nóng và không bị khô cứng.', 15),
('vn-xao-02_v4_step_3', 'vn-xao-02', 3, 'prep', 'Sơ chế cần tây, tỏi tây, hành tây và cà chua', 'Cần tây nhặt bỏ bớt lá già, rửa sạch từng nhánh rồi cắt khúc xéo 3–4 cm. Tỏi tây tách kỹ từng bẹ để rửa sạch cát, vẩy ráo rồi thái vát tương tự. Hành tây bóc vỏ, bổ múi cau; cà chua bỏ cuống, bổ 6 múi cau. Phần tỏi khô còn lại băm nhỏ.', NULL, NULL),
('vn-xao-02_v4_step_4', 'vn-xao-02', 4, 'cook', 'Áp chảo thịt bò nhanh trên lửa lớn', 'Đặt chảo rộng lên bếp lửa lớn, đun nóng già 15 ml dầu ăn rồi cho một nửa lượng tỏi băm còn lại vào phi thơm. Trút toàn bộ thịt bò đã ướp vào dàn đều mặt chảo, đảo nhanh tay liên tục khoảng 1–2 phút đến khi thịt bò vừa chuyển màu chín tái 80% thì lập tức trút ra đĩa riêng.', 'Chỉ xào bò vừa chín tái rồi vớt ra ngay để thịt giữ được độ mọng nước, không bị dai khi đảo lại cùng rau.', 2),
('vn-xao-02_v4_step_5', 'vn-xao-02', 5, 'cook', 'Xào chín tới hành tây, cần tây, tỏi tây và cà chua', 'Dùng lại chảo vừa xào bò, thêm 15 ml dầu ăn vào đun nóng trên lửa lớn, phi thơm nốt phần tỏi băm. Cho hành tây vào đảo 1 phút cho hơi trong, tiếp tục cho cà chua, cần tây và tỏi tây vào xào chung. Nêm 10 ml dầu hào, 2,5 g hạt nêm, 3 g muối ăn và 1,5 g đường cát trắng, đảo đều 2 phút đến khi rau củ chín tới, vẫn giữ màu xanh giòn.', NULL, 2),
('vn-xao-02_v4_step_6', 'vn-xao-02', 6, 'finish', 'Đảo quyện thịt bò và hoàn thiện đĩa xào', 'Trút đĩa thịt bò cùng phần nước tiết ra trở lại chảo rau củ, bật lửa lớn nhất và đảo nhanh tay trong 30–45 giây cho thịt bò chín hoàn toàn và quyện đều vị sốt. Tắt bếp, bày ra đĩa rộng và rắc 1 g tiêu đen xay còn lại lên trên, dùng nóng với cơm trắng.', NULL, NULL),
('vn-xao-03_v4_step_1', 'vn-xao-03', 1, 'prep', 'Làm sạch mực ống và khứa vảy rồng', 'Lột bỏ lớp màng tím ngoài thân mực ống, rút nhẹ đầu mực để lấy hết túi mực, nội tạng và thanh nang trắng bên trong, bỏ mắt và răng mực. Rửa thật sạch dưới vòi nước lạnh, xẻ đôi thân mực, khứa đường chéo vảy rồng rồi cắt miếng vuông khoảng 3 x 4 cm, để ráo.', 'Chọn mực ống thân dày, da sáng ánh nhũ, mắt trong và đầu dính chặt vào thân để món xào được giòn ngọt tự nhiên.', NULL),
('vn-xao-03_v4_step_2', 'vn-xao-03', 2, 'prep', 'Chần gừng và sốc nhiệt nước đá giúp mực giòn', 'Đun sôi một nồi nước với 25 g gừng tươi đập dập trên lửa lớn. Cho mực vào vợt, nhúng nhanh vào nước sôi trong 15–20 giây đến khi miếng mực vừa cuộn nhẹ và chuyển màu trắng đục thì lập tức vớt ra ngâm ngay vào thau nước đá lạnh 2 phút rồi để thật ráo nước.', 'Chần nhanh qua nước gừng rồi sốc nhiệt nước đá vừa khử sạch mùi tanh, vừa giúp mực ráo nước và giòn sần sật khi xào.', 2),
('vn-xao-03_v4_step_3', 'vn-xao-03', 3, 'prep', 'Sơ chế rau củ, dứa và gia vị', 'Dứa gọt sạch mắt, bỏ lõi cứng rồi thái lát mỏng vừa ăn. Cà chua và hành tây bổ múi cau. Cần tây và tỏi tây tách bẹ rửa thật sạch, cắt khúc dài 4 cm. Tỏi khô bóc vỏ băm nhỏ; ớt sừng đỏ thái lát xéo.', NULL, NULL),
('vn-xao-03_v4_step_4', 'vn-xao-03', 4, 'cook', 'Xào săn mực ống trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, đun nóng 15 ml dầu ăn rồi phi thơm một nửa phần tỏi băm. Trút mực ống đã ráo nước vào đảo nhanh tay liên tục, nêm 15 ml nước mắm ngon và 5 g hạt nêm, xào khoảng 1–2 phút cho mực săn giòn, nở hoa đều thì trút ra đĩa riêng.', 'Xào mực riêng trên lửa thật lớn giúp mực chín đều, săn giòn mà không bị tiết nước làm loãng rau củ.', 2),
('vn-xao-03_v4_step_5', 'vn-xao-03', 5, 'cook', 'Xào cà chua, hành tây, dứa và cần tỏi', 'Dùng lại chảo, thêm 15 ml dầu ăn đun nóng rồi phi thơm nốt phần tỏi băm còn lại. Cho cà chua vào xào 1–2 phút trên lửa vừa-lớn cho hơi mềm tạo màu, sau đó tăng lửa lớn cho hành tây và dứa vào đảo 1 phút. Tiếp tục thả cần tây và tỏi tây vào, nêm 3 g hạt nêm và 5 g đường cát trắng, đảo đều 2 phút cho rau củ chín tới.', NULL, 3),
('vn-xao-03_v4_step_6', 'vn-xao-03', 6, 'finish', 'Trộn mực với rau củ và trình bày', 'Trút đĩa mực đã xào trở lại chảo rau củ, đảo nhanh tay trên lửa lớn khoảng 30–45 giây cho mực nóng hổi, chín kỹ và hòa quyện cùng sốt dứa cà chua. Thêm ớt sừng đỏ thái lát đảo sơ rồi tắt bếp, gắp ra đĩa và rắc 2 g tiêu đen xay lên trên.', NULL, NULL),
('vn-xao-04_v4_step_1', 'vn-xao-04', 1, 'marinate', 'Thái mỏng và ướp thịt thăn bò', 'Thấm thật khô thịt thăn bò rồi thái lát mỏng ngang thớ. Cho thịt vào tô, ướp với 10 ml nước tương (xì dầu), 5 ml dầu hào, 2 g hạt nêm, 3 g đường cát trắng, 1 g tiêu đen xay và 5 ml dầu ăn, trộn đều rồi để nghỉ 15 phút cho thịt ngấm gia vị.', 'Thái thịt bò ngang thớ và thêm chút dầu ăn khi ướp giúp thịt giữ độ mềm ẩm và không bị dai khi xào lửa lớn.', 15),
('vn-xao-04_v4_step_2', 'vn-xao-04', 2, 'prep', 'Sơ chế và chần sơ bông cải xanh, cà rốt', 'Tách bông cải xanh thành từng nhánh nhỏ vừa ăn, gọt bỏ phần vỏ xơ quanh cuống rồi rửa sạch. Cà rốt gọt vỏ, thái lát mỏng hoặc tỉa hoa dày 0,3 cm. Đun sôi nồi nước với 4 g muối ăn, thả cà rốt vào chần trước 30 giây rồi cho bông cải xanh vào chần chung thêm 45 giây, vớt ngay ra thau nước lạnh ngâm 1 phút rồi để ráo.', 'Chần sơ bông cải xanh giúp loại bỏ mùi hăng nhẹ, giữ màu xanh mướt và rút ngắn thời gian xào trên chảo.', 2),
('vn-xao-04_v4_step_3', 'vn-xao-04', 3, 'prep', 'Chuẩn bị tỏi băm và hành lá', 'Tỏi khô bóc vỏ, băm nhuyễn và chia làm hai phần bằng nhau. Hành lá rửa sạch, thái nhỏ phần đầu hành trắng để phi thơm, phần lá xanh cắt khúc 3 cm.', NULL, NULL),
('vn-xao-04_v4_step_4', 'vn-xao-04', 4, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, đun nóng 10 ml dầu ăn rồi cho một nửa lượng tỏi băm vào phi thơm. Đổ thịt bò đã ướp vào dàn đều, đảo nhanh tay khoảng 1–2 phút đến khi thịt vừa săn lại và chín tái thì trút ra đĩa riêng.', NULL, 2),
('vn-xao-04_v4_step_5', 'vn-xao-04', 5, 'cook', 'Xào cà rốt và bông cải xanh thấm vị dầu hào', 'Dùng lại chảo vừa xào bò, thêm 15 ml dầu ăn vào đun nóng, phi thơm nốt phần tỏi băm và đầu hành lá trắng. Cho cà rốt và bông cải xanh đã ráo nước vào đảo đều trên lửa lớn, nêm 10 ml dầu hào, 3 g hạt nêm và 2 g muối ăn còn lại, xào khoảng 2 phút cho rau củ chín tới nhưng vẫn giòn ngọt.', 'Không xào bông cải quá lâu sau khi đã chần sơ để giữ độ giòn sần sật và hàm lượng vitamin tự nhiên.', 2),
('vn-xao-04_v4_step_6', 'vn-xao-04', 6, 'finish', 'Đảo quyện bò với rau củ và hoàn thiện', 'Trút đĩa thịt bò đã xào tái trở lại chảo bông cải cà rốt, đảo nhanh tay trên lửa lớn 45 giây cho thịt bò chín hoàn toàn và thấm sốt. Rưới 5 ml nước mắm ngon, thả hành lá cắt khúc vào đảo đều rồi tắt bếp, bày ra đĩa và rắc 1 g tiêu đen xay lên trên.', NULL, NULL),
('vn-xao-05_v4_step_1', 'vn-xao-05', 1, 'prep', 'Gọt vỏ và thái sợi su su không dính nhựa', 'Ngâm 3 quả su su trong chậu nước khoảng 2 phút hoặc gọt vỏ trực tiếp dưới vòi nước chảy để nhựa su su không làm rít tay. Bổ đôi quả, khoét bỏ phần hạt non ở giữa rồi thái thành sợi dày khoảng 0,3 cm đều nhau, rửa lại nước sạch và để thật ráo.', 'Chọn su su quả non có vỏ xanh sáng, bấm nhẹ thấy mọng nước để món xào được ngọt và không bị xơ.', NULL),
('vn-xao-05_v4_step_2', 'vn-xao-05', 2, 'prep', 'Chuẩn bị hành tím, rau thơm và đánh trứng gà', 'Hành tím khô bóc vỏ, băm nhỏ. Hành lá và ngò rí rửa sạch, thái nhỏ. Đập 3 quả trứng gà ta vào tô, thêm 3 ml nước mắm ngon (giúp trứng thơm và không tanh), dùng đũa đánh tan đều lòng đỏ với lòng trắng.', NULL, NULL),
('vn-xao-05_v4_step_3', 'vn-xao-05', 3, 'cook', 'Phi thơm hành tím và xào su su lửa lớn', 'Bắc chảo lên bếp lửa vừa, làm nóng 30 ml dầu ăn rồi cho hành tím băm vào phi thơm khoảng 30 giây. Tăng lên lửa lớn, trút toàn bộ sợi su su vào đảo nhanh tay liên tục, nêm 5 g hạt nêm, 4 g muối ăn và 7 ml nước mắm ngon còn lại, xào khoảng 3 phút đến khi sợi su su hơi trong và chín tới 80%.', 'Xào su su trên lửa lớn giúp su su nhanh chín mà không bị ra nhiều nước làm nhão trứng.', 3),
('vn-xao-05_v4_step_4', 'vn-xao-05', 4, 'cook', 'Đổ trứng gà và đảo quyện đều cùng su su', 'Hạ xuống lửa vừa, dàn đều su su ra khắp mặt chảo rồi rưới từ từ tô trứng gà đã đánh tan lên trên. Đợi 15–20 giây cho phần trứng tiếp xúc mặt chảo hơi se lại rồi dùng đũa đảo đều nhẹ tay khoảng 1–2 phút đến khi trứng chín hoàn toàn, bám đều quanh từng sợi su su thành mảng tơi mềm.', 'Không đảo quá mạnh ngay khi vừa đổ trứng để tránh trứng bị nát vụn và bết dính.', 2),
('vn-xao-05_v4_step_5', 'vn-xao-05', 5, 'cook', 'Thêm hành lá và nêm nếm lại', 'Khi trứng đã chín ráo mặt và thơm ngậy, cho toàn bộ hành lá thái nhỏ vào chảo đảo nhanh tay thêm 20 giây cho hành chín xanh, nếm lại gia vị cho vừa khẩu vị rồi tắt bếp.', NULL, NULL),
('vn-xao-05_v4_step_6', 'vn-xao-05', 6, 'finish', 'Trình bày và thưởng thức', 'Múc su su xào trứng gà ra đĩa, rắc ngò rí và 1,5 g tiêu đen xay lên trên cho thơm. Dọn dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('vn-xao-06_v4_step_1', 'vn-xao-06', 1, 'marinate', 'Thái mỏng và ướp thịt bò thấm gia vị', 'Rửa sạch thịt thăn bò, thấm thật khô rồi thái lát mỏng ngang thớ. Ướp thịt với 1/3 lượng tỏi băm, 5 g hạt nêm, 2 g muối ăn, 3 g đường cát trắng, 1 g tiêu đen xay và 5 ml dầu ăn; trộn đều và để thấm 15 phút.', 'Thái thịt ngang thớ giúp từng lát bò mềm mượt, không bị dai sau khi xào.', 15),
('vn-xao-06_v4_step_2', 'vn-xao-06', 2, 'prep', 'Tước xơ và chần sơ đậu cô ve', 'Nhặt bỏ hai đầu và tước sạch đường xơ dọc hai bên thân đậu cô ve, rửa sạch rồi thái vát chéo hoặc cắt khúc dài 4 cm. Đun sôi nồi nước với 2 g muối ăn, chần nhanh đậu cô ve trong 45–60 giây rồi vớt ra ngâm nước lạnh 1 phút và để thật ráo.', 'Chần sơ đậu cô ve giúp khử vị ngai ngái, giữ sắc xanh mướt và giúp đậu chín đồng đều khi xào.', 1),
('vn-xao-06_v4_step_3', 'vn-xao-06', 3, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Làm nóng 15 ml dầu ăn trên chảo lửa lớn, phi thơm 1/3 lượng tỏi băm rồi cho thịt bò đã ướp vào dàn đều. Đảo nhanh tay liên tục khoảng 1,5–2 phút đến khi thịt vừa chín tái 80% thì trút ngay ra đĩa riêng.', NULL, 2),
('vn-xao-06_v4_step_4', 'vn-xao-06', 4, 'cook', 'Xào đậu cô ve giòn xanh', 'Dùng lại chảo vừa xào bò, thêm 15 ml dầu ăn đun nóng rồi phi thơm 1/3 lượng tỏi băm còn lại. Cho đậu cô ve vào đảo nhanh trên lửa lớn 1 phút, thêm 2 g muối ăn và 60 ml nước lọc, đậy nắp om nhanh khoảng 2 phút cho đậu chín tới mà vẫn giữ độ giòn.', 'Chỉ thêm một lượng nước nhỏ và đậy nắp nhanh để hơi nóng làm đậu chín đều từ trong ra ngoài mà không bị nát.', 2),
('vn-xao-06_v4_step_5', 'vn-xao-06', 5, 'cook', 'Đảo chung thịt bò với sốt dầu hào', 'Mở nắp, bật lửa lớn và trút toàn bộ đĩa thịt bò đã xào tái trở lại chảo. Nêm 15 ml dầu hào và 10 ml nước mắm ngon, đảo nhanh tay 1 phút cho thịt bò chín hoàn toàn và sốt sánh quyện đều lên đậu cô ve.', NULL, NULL),
('vn-xao-06_v4_step_6', 'vn-xao-06', 6, 'finish', 'Thêm hành lá và dọn nóng', 'Thả hành lá cắt khúc vào đảo nhanh một lượt rồi tắt bếp ngay. Bày đậu cô ve xào thịt bò ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('vn-chien-01_v4_step_1', 'vn-chien-01', 1, 'prep', 'Thấm khô đậu phụ và cắt miếng vừa ăn', 'Rửa nhẹ đậu phụ trắng dưới vòi nước lạnh cho sạch, đặt lên khăn giấy sạch thấm thật khô hai mặt rồi cắt thành miếng vuông dày khoảng 2 cm. Nếu thích lớp vỏ xốp giòn, lăn nhẹ các miếng đậu qua 12 g bột năng rồi giũ bỏ bột thừa; còn để giữ đúng độ mềm mướt kiểu lướt ván thì chiên trực tiếp.', 'Thấm khô bề mặt đậu phụ là bí quyết quan trọng nhất để khi thả vào chảo dầu không bị bắn và miếng đậu lên màu vàng đều.', NULL),
('vn-chien-01_v4_step_2', 'vn-chien-01', 2, 'prep', 'Sơ chế cà chua và các loại hành thơm', 'Cà chua chín đỏ rửa sạch, bỏ cuống, thái hạt lựu nhỏ để khi xào nhanh nhừ thành sốt mịn. Hành tím bóc vỏ, thái lát mỏng hoặc băm nhỏ. Hành lá rửa sạch, tách riêng phần đầu hành trắng băm nhỏ và phần lá xanh cắt khúc dài 2 cm.', NULL, NULL),
('vn-chien-01_v4_step_3', 'vn-chien-01', 3, 'cook', 'Chiên lướt ván đậu phụ vàng đều hai mặt', 'Đặt chảo chống dính lên bếp, cho 125 ml dầu ăn vào đun trên lửa vừa đến khi đầu đũa chạm đáy chảo sủi tăm nhẹ. Thả từng miếng đậu phụ vào chiên khoảng 3 phút mỗi mặt đến khi lớp vỏ bên ngoài vừa se vàng nhạt nhưng bên trong vẫn mềm núng nính thì vớt ra đĩa có giấy thấm dầu.', 'Không chiên quá lâu ở lửa lớn khiến vỏ đậu bị cứng và ruột bị rỗ khô; đậu vừa vàng xém nhẹ hai mặt là đạt.', 6),
('vn-chien-01_v4_step_4', 'vn-chien-01', 4, 'sauce', 'Phi thơm hành tím và xào nhừ cà chua', 'Chắt bớt dầu thừa trong chảo, giữ lại khoảng 10–12 ml dầu ăn, đun nóng trên lửa vừa rồi cho hành tím và đầu hành lá vào phi thơm 1 phút. Trút toàn bộ cà chua vào xào cùng 2 g hạt nêm, đậy nắp chảo nấu 3 phút cho cà chua mềm nát và tiết màu đỏ cam.', NULL, 3),
('vn-chien-01_v4_step_5', 'vn-chien-01', 5, 'sauce', 'Nêm gia vị và nấu sánh sốt cà chua', 'Mở nắp, dùng muôi dằm nhẹ phần cà chua cho nhuyễn mịn rồi đổ 80 ml nước lọc vào khuấy đều. Nêm 25 ml nước mắm ngon, 15 ml dầu hào (nếu dùng), 6 g đường cát trắng và 4 g hạt nêm còn lại, nấu sôi nhẹ 2 phút. Hòa 4 g bột năng với 20 ml nước lọc rồi rót từ từ vào chảo khuấy đều cho sốt sánh bóng.', 'Dầu hào và đường giúp làm dịu vị chua gắt của cà chua, tạo độ sánh mượt tự nhiên cho phần sốt rưới cơm.', 2),
('vn-chien-01_v4_step_6', 'vn-chien-01', 6, 'finish', 'Om đậu thấm sốt và hoàn thiện món ăn', 'Hạ lửa nhỏ, nhẹ nhàng xếp từng miếng đậu phụ đã chiên vào chảo sốt cà chua, dùng thìa rưới đều sốt lên mặt đậu và rim khoảng 3 phút cho sốt thấm quanh miếng đậu mà không bị vỡ. Rắc hành lá cắt khúc vào đảo nhẹ rồi tắt bếp, gắp ra đĩa và rắc thêm tiêu đen xay lên trên.', NULL, 3),
('vn-chien-02_v4_step_1', 'vn-chien-02', 1, 'marinate', 'Ướp thịt bằm và sơ chế trụng nấm rơm', 'Cho thịt heo xay vào tô, ướp cùng 3 g hạt nêm, 1 g muối ăn và 1 g tiêu đen xay trong 10 phút cho thấm vị. Nấm rơm gọt bỏ gốc bẩn, rửa qua nước muối pha 1 g muối còn lại, sau đó thả vào 500 ml nước lọc đang sôi trụng nhanh 1 phút, vớt ra xả ngay nước lạnh, vắt ráo nhẹ rồi thái lát mỏng hoặc băm nhỏ.', 'Trụng nhanh nấm rơm rồi xả lạnh giúp nấm giữ được độ giòn ngọt, không bị thâm đen và ra ít nước khi xào.', 10),
('vn-chien-02_v4_step_2', 'vn-chien-02', 2, 'prep', 'Sơ chế hành lá, hành tím và tỏi băm', 'Hành lá rửa sạch, để ráo rồi thái nhỏ. Hành tím bóc vỏ thái lát mỏng (nếu tự phi), tỏi bóc vỏ băm nhuyễn. Chuẩn bị sẵn tô lớn để đánh trứng.', NULL, NULL),
('vn-chien-02_v4_step_3', 'vn-chien-02', 3, 'cook', 'Xào ráo nhân nấm rơm và thịt bằm', 'Làm nóng chảo với 10 ml dầu ăn trên lửa vừa, phi thơm hành tím và tỏi băm rồi cho nấm rơm vào đảo nhanh 2 phút cùng 2 g hạt nêm cho ráo nước, trút ra đĩa. Giữ nguyên chảo, tăng lửa lớn và cho thịt heo xay đã ướp vào đảo tơi đến khi thịt chuyển màu trắng đục chín hoàn toàn, trút nấm vào đảo chung 1 phút cho ráo hẳn nước rồi tắt bếp để nguội bớt.', 'Phải xào thịt và nấm thật ráo nước trên lửa lớn trước khi trộn vào trứng, nếu nhân còn ướt miếng trứng sẽ bị bở và vỡ khi lật.', 4),
('vn-chien-02_v4_step_4', 'vn-chien-02', 4, 'prep', 'Đánh tan trứng cùng sữa tươi và trộn nhân', 'Đập 5 quả trứng gà vào tô lớn, thêm 25 ml sữa tươi không đường, 15 ml nước mắm ngon, 5 ml dầu mè thơm (nếu dùng) và 1 g tiêu đen xay. Dùng đũa khuấy đều nhẹ tay cho lòng trắng và lòng đỏ hòa quyện mà không tạo quá nhiều bọt khí, rồi cho hành lá thái nhỏ cùng toàn bộ nhân thịt nấm đã nguội vào trộn đều.', NULL, NULL),
('vn-chien-02_v4_step_5', 'vn-chien-02', 5, 'cook', 'Chiên phồng mặt đáy trứng trên lửa nhỏ', 'Đặt chảo chống dính đường kính 22–24 cm lên bếp, đun nóng 20 ml dầu ăn còn lại trên lửa vừa rồi hạ xuống lửa nhỏ. Đổ hỗn hợp trứng thịt nấm vào chảo, dàn đều nhân khắp mặt, đậy nắp chảo chiên khoảng 5 phút cho mặt dưới chín vàng và mặt trên se đặc lại.', 'Đậy nắp và giữ lửa nhỏ giúp hơi nóng làm chín phần thịt trứng ở giữa mà không làm cháy sém mặt đáy.', 5),
('vn-chien-02_v4_step_6', 'vn-chien-02', 6, 'finish', 'Lật mặt chiên vàng đều và cắt miếng dọn nóng', 'Khi mặt trên trứng đã se lại không còn lỏng, úp một chiếc đĩa lớn lên miệng chảo rồi lật ngược chảo để lấy trứng ra đĩa, sau đó trượt nhẹ mặt chưa chín trở lại chảo. Chiên tiếp không đậy nắp thêm 2 phút trên lửa nhỏ cho đến khi hai mặt vàng ruộm và phần nhân chín kỹ hoàn toàn, gắp ra đĩa cắt thành 6 miếng tam giác và dùng nóng.', NULL, 2);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-chien-03_v4_step_1', 'vn-chien-03', 1, 'prep', 'Làm sạch và trụng sơ khử mùi cánh gà', 'Chà xát kỹ cánh gà với 5 g muối hạt và 1/2 quả chanh tươi trong 2 phút, rửa sạch lại nhiều lần rồi khía nhẹ 2 đường mặt trong để thịt nhanh chín. Đun sôi 950 ml nước lọc cùng 5 g muối hạt, 10 ml giấm gạo, gừng tươi đập dập và 10 g hành tím đập dập, thả cánh gà vào trụng 4 phút rồi vớt ra để thật ráo nước.', 'Trụng sơ giúp loại bỏ tạp chất, làm da gà săn lại nên khi chiên sẽ ít bắn dầu và thịt bên trong giữ được độ ẩm ngọt.', 4),
('vn-chien-03_v4_step_2', 'vn-chien-03', 2, 'prep', 'Thấm khô, áo bột và băm nhuyễn tỏi ớt', 'Dùng khăn giấy sạch thấm khô hoàn toàn từng chiếc cánh gà. Nếu dùng bột chiên giòn, cho cánh gà vào tô xóc đều với 60 g bột chiên giòn khô rồi giũ bỏ bột thừa để chỉ còn một lớp áo mỏng. Băm nhuyễn tỏi ta, ớt sừng đỏ và 15 g hành tím còn lại để riêng.', NULL, NULL),
('vn-chien-03_v4_step_3', 'vn-chien-03', 3, 'cook', 'Chiên cánh gà ngập dầu đến khi vàng giòn', 'Đổ 385 ml dầu ăn vào chảo sâu lòng, đun nóng già ở lửa vừa đến khi đầu đũa sủi bọt mạnh. Thả cánh gà vào chiên ngập mặt dầu khoảng 10–12 phút, trở đều các mặt cho đến khi lớp da vàng ruộm, giòn rụm và thịt sát xương chín hoàn toàn không còn nước hồng. Vớt gà ra rây hoặc giấy thấm dầu cho ráo.', 'Không xếp quá nhiều cánh gà trong một mẻ để giữ nhiệt độ dầu ổn định, giúp da gà giòn lâu và không bị ngấm dầu.', 12),
('vn-chien-03_v4_step_4', 'vn-chien-03', 4, 'sauce', 'Pha hỗn hợp sốt nước mắm chua ngọt', 'Trong chén nhỏ, hòa tan hoàn toàn 35 ml nước mắm truyền thống, 20 g đường cát trắng, 20 ml tương ớt, 5 ml giấm gạo, 50 ml nước lọc và 1 g tiêu đen xay cho đến khi đường tan hết.', NULL, NULL),
('vn-chien-03_v4_step_5', 'vn-chien-03', 5, 'sauce', 'Phi thơm tỏi ớt và nấu sánh keo sốt mắm', 'Đặt một chảo sạch lên bếp, cho 15 ml dầu ăn vào đun nóng ở lửa vừa rồi phi thơm hành tím băm, tỏi băm và ớt băm trong 1 phút. Đổ chén sốt nước mắm đã pha vào chảo, hạ lửa nhỏ và khuấy đều khoảng 3 phút đến khi sốt sôi sủi bọt và sánh kẹo lại.', 'Phải nấu cho sốt thật sánh kẹo trước khi cho gà vào; nếu sốt còn loãng sẽ làm lớp da gà bị ỉu mềm ngay lập tức.', 3),
('vn-chien-03_v4_step_6', 'vn-chien-03', 6, 'finish', 'Đảo cánh gà áo sốt và dọn nóng', 'Trút toàn bộ cánh gà đã chiên giòn vào chảo sốt, bật lửa vừa và xóc đảo nhanh tay khoảng 1–2 phút cho sốt mắm tỏi ớt bóng đẹp bám đều quanh từng chiếc cánh gà. Tắt bếp, rắc 1 g tiêu đen xay còn lại, xếp ra đĩa và thưởng thức ngay khi còn nóng giòn.', NULL, 2),
('vn-chien-04_v4_step_1', 'vn-chien-04', 1, 'prep', 'Luộc mỡ heo hạt lựu và sơ chế rau thơm', 'Đun sôi 400 ml nước lọc, cho 80 g phần thịt mỡ heo vào luộc chín tới khoảng 5 phút, vớt ra để nguội ráo rồi thái hạt lựu nhỏ 0,5 cm, trộn ướp với 3 g đường cát trắng trong 10 phút cho mỡ trong giòn. Thì là tươi, đầu hành hoa rửa sạch để thật ráo nước rồi thái nhỏ; hành tím băm nhuyễn.', NULL, 5),
('vn-chien-04_v4_step_2', 'vn-chien-04', 2, 'marinate', 'Ướp lạnh thịt cá trước khi quết dai', 'Cho 450 g thịt cá thác lác nạo vào tô lớn, ướp cùng 20 ml nước mắm ngon, 8 g hạt nêm, 3 g muối ăn và 3 g tiêu đen xay. Trộn sơ rồi bọc kín đặt trong ngăn mát tủ lạnh 15 phút để thịt cá giữ độ lạnh sâu, giúp liên kết protein bền chặt khi quết.', 'Giữ cá thật lạnh trước và trong khi quết là bí quyết giúp chả cá dai giòn sần sật tự nhiên mà không bị bở.', 15),
('vn-chien-04_v4_step_3', 'vn-chien-04', 3, 'prep', 'Quết dẻo thịt cá với nạc vai và bột năng', 'Lấy tô cá lạnh ra, dùng muôi gỗ bản to hoặc tay đeo găng quết mạnh, miết sát vào thành tô liên tục trong 10 phút đến khi thịt cá dẻo quánh và nặng tay. Tiếp tục cho 100 g thịt nạc vai heo xay vào quết thêm 4 phút cho hai loại thịt quyện mịn vào nhau.', NULL, 14),
('vn-chien-04_v4_step_4', 'vn-chien-04', 4, 'prep', 'Trộn mỡ hạt lựu, thì là và hạt tiêu', 'Thêm phần mỡ heo hạt lựu đã ướp đường, lòng trắng 1 quả trứng gà, 20 g bột năng, thì là thái nhỏ, đầu hành hoa, hành tím băm và 3 g tiêu đen xay còn lại vào tô. Trộn đều và quết thêm 3 phút cho nguyên liệu phân bố đều khắp khối chả.', 'Cho thì là và phần tiêu còn lại vào sau cùng để giữ trọn hương thơm tươi mát, không bị nồng hăng khi quết lâu.', NULL),
('vn-chien-04_v4_step_5', 'vn-chien-04', 5, 'cook', 'Nặn miếng tròn dẹt và chiên chả vàng phồng', 'Thoa 10 ml dầu ăn lên lòng bàn tay để chống dính, múc từng phần chả nặn thành miếng tròn dẹt dày khoảng 1,5 cm. Làm nóng 340 ml dầu ăn trong chảo trên lửa vừa đến khi dầu nóng già, thả chả vào chiên khoảng 6–7 phút, trở đều hai mặt cho đến khi miếng chả phồng căng, vỏ vàng ươm và chín kỹ tận lõi.', 'Chiên ở lửa vừa ổn định; lửa quá lớn khiến vỏ ngoài cháy nhanh mà bên trong chưa kịp chín phồng, còn lửa quá nhỏ làm chả ngấm dầu.', 7),
('vn-chien-04_v4_step_6', 'vn-chien-04', 6, 'finish', 'Thấm ráo dầu và thưởng thức nóng', 'Vớt chả cá ra đĩa có lót giấy thấm dầu để ráo bớt dầu thừa trong 2 phút. Xếp ra đĩa, dùng nóng kèm cơm trắng hoặc bún tươi, chấm cùng tương ớt cay ngọt.', NULL, 2),
('vn-chien-05_v4_step_1', 'vn-chien-05', 1, 'prep', 'Ngâm nở nấm hương, mộc nhĩ và miến dong', 'Ngâm riêng 8 g mộc nhĩ khô, 8 g nấm hương khô và 50 g miến dong khô vào 350 ml nước lọc ấm trong khoảng 12 phút cho nở mềm vừa. Rửa sạch nấm và mộc nhĩ, cắt bỏ chân nấm, vắt thật kiệt nước rồi băm nhỏ; miến vớt ra để thật ráo rồi cắt khúc ngắn 2–3 cm.', 'Phải vắt khô kiệt nấm, mộc nhĩ và để ráo miến dong để nhân nem khô ráo, tránh tiết nước làm bục vỏ khi chiên.', 12),
('vn-chien-05_v4_step_2', 'vn-chien-05', 2, 'prep', 'Sơ chế rau củ, tôm và ướp thịt xay', 'Gọt vỏ củ đậu, cà rốt rồi bào sợi ngắn; hành tây thái hạt lựu nhỏ; hành hoa, rau mùi ta rửa sạch để ráo thái nhỏ; hành tím băm nhuyễn. Tôm tươi bóc vỏ, rút chỉ đen, thái hạt lựu. Ướp 450 g thịt nạc vai xay với 15 ml dầu ăn, 5 ml nước mắm, 5 g hạt nêm, 4 g muối ăn và 4 g tiêu đen xay trong 10 phút.', NULL, 10),
('vn-chien-05_v4_step_3', 'vn-chien-05', 3, 'prep', 'Trộn hoàn chỉnh nhân nem trước khi gói', 'Cho toàn bộ tôm, mộc nhĩ, nấm hương, miến, củ đậu, hành tây, cà rốt, hành hoa, rau mùi ta và hành tím vào âu thịt đã ướp, trộn đều nhẹ tay. Ngay trước lúc bắt đầu cuốn mới đập 2 quả trứng gà vào đảo đều lần cuối để nhân kết dính vừa phải mà không chảy nước.', 'Cho trứng gà vào sau cùng ngay lúc chuẩn bị gói là mẹo giúp củ đậu và hành tây không ra nước trong thời gian chờ.', NULL),
('vn-chien-05_v4_step_4', 'vn-chien-05', 4, 'prep', 'Thoa giấm loãng và cuốn nem đều tay', 'Pha 5 ml giấm gạo với 50 ml nước lọc, dùng khăn sạch thấm nhẹ thoa đều mặt bánh đa nem cho mềm dẻo (có thể lót thêm 1/2 lá vào giữa cho chắc). Múc 2 muỗng canh nhân đặt vào đầu lá, gấp hai mép bên rồi cuộn tròn vừa tay thành khoảng 20 chiếc nem kích thước đều nhau.', 'Không cuốn nem quá chặt tay vì khi gặp nhiệt nhân thịt trứng nở ra sẽ dễ làm rách vỏ bánh đa nem.', NULL),
('vn-chien-05_v4_step_5', 'vn-chien-05', 5, 'cook', 'Rán nem hai lần lửa để vỏ giòn tan', 'Đun nóng 485 ml dầu ăn trong chảo sâu lòng trên lửa vừa, thả nem vào rán lần 1 trong 7 phút cho nem se mặt và chín khoảng 80% thì vớt ra giá để nguội hẳn. Trước khi ăn, đun dầu nóng lại ở lửa vừa-lớn rồi thả nem vào rán lần 2 thêm 3–4 phút cho đến khi vỏ nem vàng ruộm giòn rụm và nhân thịt tôm chín kỹ hoàn toàn, vớt ra giấy thấm dầu.', NULL, 11),
('vn-chien-05_v4_step_6', 'vn-chien-05', 6, 'finish', 'Pha nước chấm chua ngọt và bày đĩa', 'Khuấy tan 35 g đường cát trắng với 200 ml nước lọc ấm, sau đó thêm 45 ml nước mắm ngon và 40 ml giấm gạo nếm vừa vị chua ngọt hài hòa, cuối cùng thả tỏi băm và ớt băm vào để nổi đều đẹp mắt. Cắt nem làm đôi hoặc làm ba, dùng nóng kèm rau sống và nước chấm.', 'Hòa tan đường với nước ấm trước rồi mới cho nước mắm, tỏi ớt băm thả vào sau cùng sẽ giúp tỏi ớt nổi đều trên mặt chén.', NULL),
('vn-chien-06_v4_step_1', 'vn-chien-06', 1, 'prep', 'Làm sạch khử tanh và khía thân cá rô phi', 'Đánh sạch vảy, cắt bỏ mang và mổ bỏ ruột cá rô phi, chú ý cạo sạch lớp màng đen bên trong bụng cá để hết mùi tanh. Dùng 6 g muối ăn chà xát khắp mình và bụng cá trong 2 phút rồi rửa sạch lại bằng nước lạnh, dùng khăn sạch thấm thật khô cá và khía 3–4 đường chéo trên mỗi mặt thân cá.', 'Cạo thật sạch lớp màng đen trong bụng cá và chà xát muối kỹ giúp khử hoàn toàn mùi tanh bùn của cá rô phi đồng.', NULL),
('vn-chien-06_v4_step_2', 'vn-chien-06', 2, 'marinate', 'Ướp cá và pha hỗn hợp bột mì nhúng', 'Rắc đều 2 g muối ăn và 1 g tiêu đen xay vào các đường khía trên thân cá, ướp 10 phút cho thịt cá săn đậm vị. Trong tô lớn, khuấy đều 35 g bột mì đa dụng với 60 ml nước lọc, 2 g muối ăn và 1 g tiêu đen xay còn lại thành hỗn hợp sền sệt mịn không vón cục.', NULL, 10),
('vn-chien-06_v4_step_3', 'vn-chien-06', 3, 'cook', 'Chiên cá ngập dầu lửa vừa đến khi vàng giòn', 'Đổ 300 ml dầu ăn vào chảo lớn sâu lòng, đun lửa vừa đến khi dầu nóng già và thử đầu đũa thấy sủi tăm mạnh. Nhúng từng con cá qua tô bột mì cho phủ một lớp áo thật mỏng rồi nhẹ nhàng thả vào chảo, chiên mỗi mặt 7–8 phút không trở quá sớm đến khi da cá vàng giòn rụm và thịt cá chín trắng đục tận xương.', 'Giữ lửa vừa ổn định và đợi mặt dưới chín vàng cứng cáp mới lật để da cá không bị dính sát chảo hay vỡ nát.', 16),
('vn-chien-06_v4_step_4', 'vn-chien-06', 4, 'finish', 'Vớt cá lên rây cho ráo dầu', 'Khi hai mặt cá đã vàng giòn đều từ đầu đến đuôi, nhẹ nhàng gắp cá ra rây thưa hoặc đĩa có lót giấy thấm dầu, để nghỉ 2 phút cho thoát bớt dầu thừa giúp vỏ cá giòn lâu hơn.', 'Gác cá lên rây thưa hoặc giấy thấm dầu giúp hơi ẩm thoát đều, giữ lớp vỏ ngoài giòn rụm lâu hơn.', NULL),
('vn-chien-06_v4_step_5', 'vn-chien-06', 5, 'sauce', 'Giã nhuyễn gừng tỏi ớt và pha nước mắm', 'Giã nhuyễn 40 g gừng tươi, 1 củ tỏi khô và 2 quả ớt tươi (hoặc băm thật mịn). Hòa tan hoàn toàn 25 g đường cát trắng với 60 ml nước lọc ấm trong chén, sau đó thêm 60 ml nước mắm nguyên chất và nước cốt của 1,5 quả chanh tươi khuấy đều, cuối cùng cho gừng tỏi ớt vào.', 'Khuấy tan đường trước với nước ấm rồi mới thêm nước mắm, chanh và gừng tỏi ớt sau cùng để nước chấm sánh thơm và tỏi ớt nổi đẹp.', NULL),
('vn-chien-06_v4_step_6', 'vn-chien-06', 6, 'finish', 'Bày cá chiên ra đĩa và thưởng thức nóng', 'Đặt cá rô phi chiên giòn lên đĩa lớn, dọn ngay khi còn nóng hổi giòn tan cùng chén nước mắm gừng, ăn kèm cơm trắng nóng và rau luộc hoặc cuốn rau sống.', NULL, NULL),
('vn-hap-01_v4_step_1', 'vn-hap-01', 1, 'prep', 'Làm sạch và khử mùi hôi gà ta', 'Rửa sạch nửa con gà ta dưới vòi nước lạnh, cắt bỏ tuyến dầu ở phần đuôi. Dùng 6 g muối hạt và 10 g gừng đập dập chà xát kỹ cả bên ngoài da lẫn khoang bụng trong 2 phút để loại bỏ mùi hôi và chất nhờn, sau đó xả lại nhiều lần với nước sạch rồi thấm thật khô bằng khăn giấy.', 'Thấm thật ráo bề mặt da trước khi ướp sẽ giúp gia vị bám đều và da gà khi hấp xong căng bóng, không bị bở nhão.', NULL),
('vn-hap-01_v4_step_2', 'vn-hap-01', 2, 'prep', 'Sơ chế sả, gừng, hành tím và lá chanh', 'Cạo vỏ phần gừng còn lại, cắt 20 g thành lát mỏng và băm nhỏ 10 g. Bóc lớp bẹ già của 3 cây sả, đập dập cắt khúc 2 cây và thái lát mỏng 1 cây. Lá chanh rửa sạch lau khô, giữ 5 g lá nguyên để lót hấp, phần 5 g còn lại cuộn tròn thái sợi chỉ thật mảnh. Bóc vỏ 30 g hành tím đập dập, thái lát 1 quả ớt và băm nhỏ 1 quả ớt còn lại.', NULL, NULL),
('vn-hap-01_v4_step_3', 'vn-hap-01', 3, 'marinate', 'Ướp đậm đà phần thịt và da gà', 'Trộn đều 6 g muối hạt, 5 g hạt nêm, 1,5 g tiêu đen xay, 10 g gừng băm, 1 cây sả thái lát, 1 quả ớt thái lát và một ít lá chanh thái chỉ. Xoa đều hỗn hợp lên khắp mình gà, nhét phần gia vị vào mặt trong khoang bụng rồi bọc kín để ướp 15 phút cho thịt ngấm sâu hương thơm.', NULL, 15),
('vn-hap-01_v4_step_4', 'vn-hap-01', 4, 'cook', 'Chuẩn bị xửng hấp và hấp gà chín tới', 'Đổ 700 ml nước lọc vào đáy nồi hấp, đun sôi bùng trên lửa lớn. Lót 2 cây sả đập dập, 20 g gừng thái lát, 30 g hành tím đập dập và 5 g lá chanh nguyên lên mặt vỉ hấp. Đặt nửa con gà ta ngửa phần thịt lên trên, đậy kín nắp và hấp cách thủy ở lửa vừa trong 25 phút.', 'Không mở nắp vung liên tục trong 20 phút đầu để giữ ổn định nhiệt độ hơi nước và tránh thất thoát tinh dầu sả lá chanh.', 25),
('vn-hap-01_v4_step_5', 'vn-hap-01', 5, 'cook', 'Kiểm tra độ chín và làm giòn da gà', 'Dùng đầu đũa nhọn xiên vào phần thịt dày nhất ở má đùi, nếu thấy nước tiết ra trong suốt và không còn màu hồng là gà đã chín hoàn toàn. Tắt bếp, đậy vung ủ thêm 3 phút cho thịt mọng nước rồi vớt gà ra ngâm nhanh vào âu nước đá sạch khoảng 2 phút giúp da se giòn vàng đẹp.', 'Ủ thêm vài phút sau khi tắt bếp rồi mới sốc nhiệt nhanh giúp thớ thịt gà không bị khô xác mà lớp da vẫn săn giòn sần sật.', 5),
('vn-hap-01_v4_step_6', 'vn-hap-01', 6, 'sauce', 'Pha muối tiêu chanh ớt chấm gà', 'Trong lúc chờ gà nguội ráo, cho 6 g muối hạt, 1,5 g tiêu đen xay, 3 g đường cát trắng và 1 quả ớt băm nhỏ vào chén sạch. Vắt nước cốt 1 quả chanh tươi vào chén, khuấy nhẹ cho muối tan bớt tạo thành hỗn hợp chấm sánh nhẹ, thơm dịu vị chanh.', NULL, NULL),
('vn-hap-01_v4_step_7', 'vn-hap-01', 7, 'finish', 'Chặt gà và trình bày cùng lá chanh thái chỉ', 'Khi gà nguội bớt và da se khô, đặt lên thớt dùng dao sắc chặt thành từng miếng vuông vừa ăn, xếp ngay ngắn ra đĩa lớn. Rắc toàn bộ phần lá chanh thái chỉ còn lại phủ đều lên mặt da gà cho dậy mùi thơm, dọn ăn nóng kèm chén muối tiêu chanh ớt.', NULL, NULL),
('vn-hap-02_v4_step_1', 'vn-hap-02', 1, 'prep', 'Sơ chế và chần khử mùi thịt ba chỉ', 'Cạo sạch lông trên bì miếng thịt ba chỉ rút sườn, xát nhẹ 3 g muối hạt khắp miếng thịt rồi rửa sạch. Đun sôi 600 ml nước lọc với 3 g muối còn lại, thả thịt vào chần nhanh 2 phút để loại bỏ bọt bẩn, sau đó vớt ra xả sạch dưới vòi nước mát và thấm ráo.', 'Chần sơ thịt rồi rửa lại giúp nước luộc thứ hai trong veo và miếng thịt luộc trắng sạch, không có mùi hôi.', 3),
('vn-hap-02_v4_step_2', 'vn-hap-02', 2, 'cook', 'Luộc thịt ba chỉ trắng thơm chín tới', 'Đặt thịt vào nồi sạch, đổ 900 ml nước lọc lạnh ngập mặt thịt cùng 30 g hành tím đập dập, 20 g gừng thái lát và 15 ml giấm gạo trắng. Đun lửa lớn đến khi nước sôi bùng thì hớt sạch bọt, hạ xuống lửa vừa để sôi lăn tăn và luộc tiếp 20 phút cho thịt chín mềm.', 'Cho thịt vào từ nước lạnh giúp thịt chín đều từ ngoài vào trong và giữ phần nạc mềm ngọt, không bị co rút.', 20),
('vn-hap-02_v4_step_3', 'vn-hap-02', 3, 'cook', 'Ủ thịt và ngâm nước lạnh giúp giòn bì', 'Dùng đũa xiên qua phần thịt dày nhất, thấy nước ứa ra trong suốt không còn đỏ hồng là thịt đã chín. Tắt bếp và đậy nắp ngâm thịt thêm 5 phút trong nồi, sau đó vớt ngay ra thau nước lạnh sạch ngâm 5 phút cho thịt săn lại, bì giòn và không bị thâm mặt.', NULL, 10),
('vn-hap-02_v4_step_4', 'vn-hap-02', 4, 'sauce', 'Pha mắm tôm đánh bông với dầu nóng', 'Cho 45 g mắm tôm, 12 g đường cát trắng và 5 ml rượu trắng nấu ăn vào chén, vắt nước cốt 1 quả chanh tươi rồi dùng đũa đánh mạnh tay đến khi nổi bọt trắng mịn. Đun thật nóng 15 ml dầu ăn trên chảo nhỏ rồi rưới trực tiếp vào chén mắm tôm, khuấy đều và thêm tỏi băm nhuyễn cùng ớt hiểm thái lát.', 'Rưới dầu ăn đang sôi vào mắm tôm vừa giúp tiệt trùng an toàn, vừa khử bớt mùi nồng và làm bọt mắm bông xốp hấp dẫn.', NULL),
('vn-hap-02_v4_step_5', 'vn-hap-02', 5, 'prep', 'Chuẩn bị cà pháo muối, dưa leo và rau sống', 'Vớt 150 g cà pháo muối giòn ra để ráo nước rồi xếp ra đĩa nhỏ. Dưa leo rửa sạch thái lát chéo vừa ăn; các loại rau sống nhặt rửa sạch để thật ráo nước rồi bày ra đĩa riêng.', NULL, NULL),
('vn-hap-02_v4_step_6', 'vn-hap-02', 6, 'finish', 'Thái lát thịt mỏng và hoàn thiện mâm cơm', 'Thấm thật khô miếng thịt ba chỉ đã nguội, dùng dao bản rộng thật sắc thái ngang thớ thành từng lát mỏng đều từ 2–3 mm để thịt không bị dai. Xếp thịt xen lớp đẹp mắt ra đĩa, đặt cạnh đĩa cà pháo muối, rau sống, dưa leo và chén mắm tôm sủi bọt để thưởng thức ngay với cơm nóng.', NULL, NULL),
('vn-hap-03_v4_step_1', 'vn-hap-03', 1, 'prep', 'Làm sạch khử tanh và khứa thân cá điêu hồng', 'Cá điêu hồng đánh sạch vảy, bỏ mang, moi ruột và cạo sạch lớp màng đen dọc sống lưng để không bị tanh đắng. Chà xát 5 g muối hạt lên khắp thân cá rồi xả lại dưới vòi nước lạnh, thấm thật khô bằng khăn giấy. Dùng dao sắc khứa 3 đường chéo nông ở mỗi mặt thân cá.', 'Cạo sạch màng đen trong bụng cá và phần máu tụ gần xương sống là bí quyết giúp cá hấp ngọt thanh hoàn toàn không tanh.', NULL),
('vn-hap-03_v4_step_2', 'vn-hap-03', 2, 'prep', 'Sơ chế nấm hương, gừng, hành lá, thì là và ớt', 'Ngâm 15 g nấm hương khô trong nước ấm khoảng 20 phút cho nở mềm rồi cắt gốc, thái lát mỏng. Cạo vỏ gừng: 20 g thái lát mỏng, 25 g thái sợi chỉ. Hành lá cắt riêng phần đầu hành đập dập, lá xanh chẻ sợi dài 4 cm. Rửa sạch thì là cắt khúc 4 cm, ớt sừng bỏ hạt thái sợi chỉ.', NULL, 20),
('vn-hap-03_v4_step_3', 'vn-hap-03', 3, 'marinate', 'Ướp cá điêu hồng và chuẩn bị sốt xì dầu', 'Xoa đều lên cả trong lẫn ngoài thân cá 15 ml xì dầu, 15 ml rượu nấu ăn, 4 g hạt nêm và 1 g tiêu đen xay, để cá thấm gia vị trong 15 phút. Trong lúc đó, khuấy tan hỗn hợp sốt gồm 30 ml xì dầu còn lại, 15 ml dầu hào, 8 g đường cát trắng và 50 ml nước lọc.', NULL, 15),
('vn-hap-03_v4_step_4', 'vn-hap-03', 4, 'cook', 'Xếp cá vào đĩa sâu lòng và hấp lửa lớn', 'Rải 20 g gừng thái lát cùng phần đầu hành lá xuống đáy đĩa sâu lòng chịu nhiệt, đặt cá điêu hồng lên trên rồi nhét ít gừng sợi và hành chẻ vào bụng cá, rải nấm hương thái lát xung quanh. Đun sôi 800 ml nước lọc trong nồi hấp ở lửa lớn, đặt đĩa cá vào xửng và đậy kín nắp hấp 15 phút.', 'Nước phải thật sôi trước khi cho cá vào và duy trì lửa lớn để cá chín nhanh, thịt săn ngọt không bị nát bở.', 15),
('vn-hap-03_v4_step_5', 'vn-hap-03', 5, 'cook', 'Rưới sốt xì dầu và hấp thêm cho thấm vị', 'Mở nắp xửng, rưới đều toàn bộ chén sốt xì dầu dầu hào đã pha lên khắp mình cá, rải thêm thì là cắt khúc lên trên. Đậy kín vung và hấp tiếp trên lửa vừa thêm 5 phút cho đến khi mắt cá đục trắng, phần thịt dày ở lưng tách nhẹ khỏi xương là chín hoàn toàn.', NULL, 5),
('vn-hap-03_v4_step_6', 'vn-hap-03', 6, 'finish', 'Xối dầu sôi lên hành gừng và thưởng thức', 'Nhấc đĩa cá ra khỏi xửng, xếp phần hành lá chẻ sợi, 25 g gừng thái sợi chỉ và ớt sừng thái chỉ phủ đều lên thân cá, rắc thêm 1 g tiêu đen xay. Đun sôi 25 ml dầu ăn trên chảo nhỏ rồi dội trực tiếp lên lớp hành gừng để dậy mùi thơm và làm chín tái rau thơm, rưới tiếp 5 ml dầu mè và dọn ăn nóng ngay.', 'Dầu ăn phải đun thật nóng già mới dội lên hành lá và gừng sợi để tạo tiếng xèo nhẹ, làm hành gừng chín thơm mà không bị hăng.', NULL),
('vn-hap-04_v4_step_1', 'vn-hap-04', 1, 'prep', 'Ngâm tôm khô và sơ chế rau củ luộc', 'Rửa sạch 25 g tôm khô rồi ngâm trong 50 ml nước ấm khoảng 20 phút cho mềm, vớt ra để ráo. Tách súp lơ xanh thành miếng vừa ăn, gọt vỏ cà rốt cắt khúc vừa và gọt vỏ su su cắt miếng con chì đều nhau, rửa sạch toàn bộ rồi để ráo nước.', NULL, 20),
('vn-hap-04_v4_step_2', 'vn-hap-04', 2, 'cook', 'Thắng tóp mỡ giòn rụm trong nồi đất', 'Thái 200 g thịt ba chỉ thành hạt lựu vuông 1 cm. Cho thịt vào nồi đất hoặc chảo đáy dày, thắng trên lửa vừa và đảo đều tay khoảng 12 phút đến khi mỡ tiết ra hết và phần tóp mỡ vàng giòn rụm. Vớt tóp mỡ ra đĩa riêng, chắt bớt mỡ nước chỉ giữ lại khoảng 20 ml trong nồi.', 'Thắng tóp mỡ ở lửa vừa không quá gắt sẽ giúp mỡ ra kiệt, tóp vàng giòn đều mà không bị cháy khét hay bắn dầu.', 12),
('vn-hap-04_v4_step_3', 'vn-hap-04', 3, 'cook', 'Luộc rau củ giòn ngọt và giữ màu xanh tươi', 'Đun sôi 1,2 lít nước lọc với 10 g muối ăn trên lửa lớn. Thả cà rốt và su su vào luộc trước 3 phút, sau đó mới cho súp lơ xanh vào luộc chung thêm 2 phút đến khi rau củ vừa chín tới còn độ giòn. Vớt ngay rau củ ra rổ cho ráo hơi nước rồi xếp đẹp mắt ra đĩa.', 'Cho cà rốt và su su vào trước rồi mới thả súp lơ giúp các loại rau chín đồng đều mà súp lơ không bị nhũn hay ngả vàng.', 5),
('vn-hap-04_v4_step_4', 'vn-hap-04', 4, 'sauce', 'Pha hỗn hợp nước mắm đường kho quẹt', 'Bóc vỏ hành tím thái lát mỏng, tỏi băm nhỏ, hành lá thái khoanh nhỏ, rửa sạch tiêu xanh và ớt hiểm. Trong chén sạch, khuấy tan 55 ml nước mắm ngon với 35 g đường cát trắng, 4 g hạt nêm và 50 ml nước lọc để sẵn sàng kho.', NULL, NULL),
('vn-hap-04_v4_step_5', 'vn-hap-04', 5, 'cook', 'Xào tôm khô và rim kho quẹt sánh kẹo', 'Đun nóng lại phần mỡ nước trong nồi đất ở lửa vừa, cho hành tím và tỏi băm vào phi thơm vàng. Đổ tôm khô đã ngâm mềm vào đảo đều 2 phút cho săn thơm rồi rót hỗn hợp nước mắm đường vào, hạ lửa nhỏ liu riu và kho khoảng 8 phút đến khi nước sốt sánh sệt lại.', 'Kho bằng nồi đất trên lửa nhỏ liu riu giúp nước mắm đường keo sánh từ từ, giữ được độ bóng đẹp và hương thơm đậm đà đặc trưng.', 8),
('vn-hap-04_v4_step_6', 'vn-hap-04', 6, 'finish', 'Trộn tóp mỡ tiêu xanh và dọn thưởng thức', 'Thả phần tóp mỡ vàng giòn, 15 g tiêu xanh tươi và 2 quả ớt hiểm vào nồi kho quẹt, đảo đều thêm 1 phút để tóp mỡ áo đều lớp sốt mặn ngọt nhưng vẫn giữ độ giòn nhẹ. Rắc hành lá thái khoanh lên mặt niêu kho quẹt, dọn nóng ngay cạnh đĩa rau củ luộc giòn ngọt.', NULL, NULL),
('vn-hap-05_v4_step_1', 'vn-hap-05', 1, 'prep', 'Làm sạch mực ống và khử mùi tanh', 'Kéo nhẹ đầu mực tách khỏi thân, rút bỏ túi mực, nang sống lưng và toàn bộ nội tạng, cắt bỏ mắt và răng mực rồi lột bỏ lớp màng da sẫm bên ngoài. Bóp nhẹ mực với 30 ml rượu trắng nấu ăn và 15 g gừng đập dập trong 2 phút, xả sạch dưới vòi nước lạnh và thấm thật ráo.', 'Không làm vỡ túi mực khi rút ruột và chỉ dùng rượu gừng chà nhanh với nước mát để thịt mực giữ được độ giòn ngọt tự nhiên.', NULL),
('vn-hap-05_v4_step_2', 'vn-hap-05', 2, 'marinate', 'Khứa thân mực và ướp nhẹ gia vị', 'Dùng dao sắc khứa nhẹ các đường vảy rồng nông trên thân mực (hoặc cắt khoanh dày 2 cm nếu thích), phần râu mực cắt làm đôi. Ướp đều mực với 4 g muối ăn trong 10 phút cho thịt săn nhẹ và đậm đà hơn khi hấp.', NULL, 10),
('vn-hap-05_v4_step_3', 'vn-hap-05', 3, 'prep', 'Sơ chế gừng non, sả, hành tím, lá chanh và ớt', 'Thái 30 g gừng non thành sợi chỉ mảnh. Bóc bẹ già của 3 cây sả, đập dập rồi cắt khúc dài 5 cm. Bóc vỏ 30 g hành tím thái lát mỏng; thái vát 2 quả ớt sừng; lá chanh rửa sạch để một nửa nguyên lá và thái chỉ phần còn lại.', NULL, NULL),
('vn-hap-05_v4_step_4', 'vn-hap-05', 4, 'cook', 'Xếp đĩa và hấp mực nhanh trên lửa lớn', 'Lót một lớp sả đập dập, lá chanh nguyên và một nửa lượng gừng sợi dưới đáy đĩa sâu lòng chịu nhiệt, xếp mực ống lên trên rồi rải nốt gừng sợi, hành tím thái lát và ớt sừng phủ đều. Đun sôi bùng 600 ml nước lọc trong nồi hấp, đặt đĩa mực vào xửng đậy kín vung và hấp lửa lớn trong 8 phút.', 'Hấp mực nhanh ở lửa lớn chỉ 7–9 phút tùy độ dày thân mực; khi thịt mực chuyển trắng đục và các đường khứa nở bung đều là vừa chín tới, tránh hấp quá lâu làm mực ra nước và bị dai.', 8),
('vn-hap-05_v4_step_5', 'vn-hap-05', 5, 'sauce', 'Pha muối tiêu chanh chấm hải sản', 'Trong lúc chờ mực chín, trộn đều 5 g muối ăn còn lại với 2 g tiêu đen xay trong chén nhỏ, vắt nước cốt 1 quả chanh tươi vào khuấy tan tạo thành chén muối tiêu chanh chua cay hài hòa.', NULL, NULL),
('vn-hap-05_v4_step_6', 'vn-hap-05', 6, 'finish', 'Ủ ấm ngắn và trình bày đĩa mực hấp nóng', 'Tắt bếp và giữ đĩa mực trong nồi đậy nắp thêm 1 phút cho hương sả gừng thấm sâu rồi nhấc ra, gạn bỏ bớt phần nước hấp thừa nếu quá nhiều. Rắc phần lá chanh thái chỉ lên trên đĩa mực và thưởng thức nóng ngay cùng muối tiêu chanh.', 'Gạn bớt phần nước hấp tiết ra trước khi dọn giúp miếng mực ráo mặt, giữ trọn độ giòn sần sật và không làm loãng muối chấm.', NULL),
('vn-hap-06_v4_step_1', 'vn-hap-06', 1, 'prep', 'Làm sạch tôm sú và rút chỉ đen dọc lưng', 'Dùng kéo cắt gọn râu tôm, chân và phần gai nhọn ở đầu tôm, dùng tăm nhọn khều nhẹ ở đốt lưng thứ hai để rút sạch đường chỉ đen. Rửa nhanh tôm qua nước muối loãng rồi xả sạch lại với nước mát, để vào rổ cho thật ráo.', 'Rút chỉ đen bằng tăm ngay tại khe đốt vỏ giúp giữ nguyên con tôm đẹp mắt mà không bị rách lưng khi hấp.', NULL),
('vn-hap-06_v4_step_2', 'vn-hap-06', 2, 'marinate', 'Sơ chế gia vị và ướp tôm sú', 'Bóc bẹ già 3 cây sả: thái lát mỏng 1 cây để ướp tôm, 2 cây còn lại đập dập cắt khúc 5 cm. Thái lát mỏng 20 g gừng và 25 g hành tím; bỏ hạt thái sợi chỉ 1 quả ớt sừng. Trộn đều tôm với sả thái lát, 5 g muối hạt, 4 g đường cát trắng và một nhúm nhỏ tiêu đen xay, để ướp 10 phút cho ngấm.', NULL, 10),
('vn-hap-06_v4_step_3', 'vn-hap-06', 3, 'cook', 'Xếp tôm vào nồi cùng nước dừa xiêm', 'Trải lớp sả đập dập, gừng thái lát và hành tím thái lát xuống đáy chảo sâu lòng hoặc nồi đáy rộng. Xếp đều tôm sú đã ướp lên trên mặt lớp sả gừng rồi rót từ từ 350 ml nước dừa xiêm tươi vào nồi sao cho nước dừa xâm xấp khoảng một nửa thân tôm.', 'Nên chọn nước dừa xiêm tươi vừa chín tới có vị ngọt thanh tự nhiên để làm bật vị ngọt của tôm mà không bị chua gắt.', NULL),
('vn-hap-06_v4_step_4', 'vn-hap-06', 4, 'cook', 'Hấp tôm chín đỏ au trong nước dừa', 'Đậy kín nắp nồi và đun trên lửa lớn để nước dừa nhanh chóng sôi bùng, sau đó giữ lửa vừa hấp tiếp khoảng 7 phút cho đến khi toàn bộ vỏ tôm chuyển màu đỏ au, thịt tôm săn chắc và thân uốn cong hình chữ C là chín hoàn toàn.', 'Không hấp tôm quá 10 phút vì thịt tôm sẽ bị teo cứng, mất độ giòn ngọt và nước dừa bay hơi cạn.', 7),
('vn-hap-06_v4_step_5', 'vn-hap-06', 5, 'sauce', 'Pha muối tiêu chanh chấm tôm sú', 'Trong lúc chờ tôm chín, cho 5 g muối hạt còn lại và 2 g tiêu đen xay vào chén nhỏ, vắt nước cốt 1 quả chanh tươi vào khuấy đều cho tan nhẹ thành muối tiêu chanh sánh thơm.', NULL, NULL),
('vn-hap-06_v4_step_6', 'vn-hap-06', 6, 'finish', 'Trình bày đĩa tôm hấp nước dừa nóng hổi', 'Tắt bếp, gắp tôm xếp vòng tròn đẹp mắt quanh đĩa lớn (hoặc quanh miệng vỏ trái dừa tươi), rưới vài muỗng nước hấp dừa sả nóng hổi lên mình tôm cho bóng mượt, điểm thêm ớt sừng thái chỉ và dọn dùng nóng ngay cùng chén muối tiêu chanh.', NULL, NULL),
('vn-cuon-01_v4_step_1', 'vn-cuon-01', 1, 'prep', 'Sơ chế rau sống và làm đồ chua', 'Nhặt sạch xà lách, rau húng quế, hẹ lá và giá đỗ, ngâm nước muối loãng với 2 g muối trong 5 phút rồi xả sạch, vẩy thật ráo nước. Dưa leo bỏ ruột, thái thanh dài mỏng. Cà rốt và củ cải trắng bào sợi, trộn với 100 ml nước lọc, 75 ml giấm gạo, 30 g đường cát trắng và 2 g muối, ngâm ít nhất 15 phút cho thấm vị chua ngọt.', 'Rau sống và giá đỗ phải thật ráo nước thì khi cuốn bánh tráng không bị ướt nhũn hay rách.', 15),
('vn-cuon-01_v4_step_2', 'vn-cuon-01', 2, 'cook', 'Luộc chín thịt ba chỉ và thái lát mỏng', 'Đun sôi 1050 ml nước lọc với 1 củ hành tím đập dập và 2 g muối trên lửa lớn. Thả thịt ba chỉ vào luộc ở lửa vừa khoảng 15 phút đến khi dùng đũa xiên qua không còn nước hồng tiết ra là thịt chín kỹ. Vớt thịt ra ngâm ngay vào nước nguội sạch 10 phút cho thịt săn trắng, để ráo rồi thái lát mỏng.', 'Ngâm thịt ba chỉ qua nước mát ngay sau khi vớt giúp phần bì giòn ngon và lát thịt không bị thâm xỉn.', 15),
('vn-cuon-01_v4_step_3', 'vn-cuon-01', 3, 'cook', 'Luộc chín tôm sú và chẻ đôi', 'Dùng nồi nước luộc thịt đang sôi, thả tôm sú đã rửa sạch vào luộc trên lửa vừa khoảng 4 phút cho đến khi vỏ tôm chuyển đỏ au và thân cong săn chắc là chín hoàn toàn. Vớt tôm ra để nguội bớt, bóc sạch vỏ, rút bỏ chỉ đen trên sống lưng rồi chẻ đôi theo chiều dọc.', NULL, 4),
('vn-cuon-01_v4_step_4', 'vn-cuon-01', 4, 'sauce', 'Nấu tương đen bơ đậu phộng sánh mịn', 'Bắc chảo nhỏ lên bếp với 15 ml dầu ăn ở lửa vừa, cho tỏi băm vào phi thơm vàng nhạt. Hạ lửa nhỏ, trút 100 ml tương đen, 35 g bơ đậu phộng, 15 g đường cát trắng và 50 ml nước lọc vào khuấy đều tay khoảng 3 phút cho sốt hòa quyện sánh mịn, thêm 5 ml giấm gạo cho vị hài hòa rồi tắt bếp.', 'Đun sốt tương trên lửa nhỏ và khuấy liên tục để bơ đậu phộng tan mượt, không bị cháy xém đáy chảo.', NULL),
('vn-cuon-01_v4_step_5', 'vn-cuon-01', 5, 'prep', 'Rang giã đậu phộng và chuẩn bị nguyên liệu cuốn', 'Rang chín vàng đậu phộng trên lửa nhỏ, để nguội rồi xát sạch vỏ lụa, cho vào cối giã dập vừa giữ độ bùi. Ớt sừng bỏ hạt, băm nhỏ. Tách bún tươi thành từng lọn nhỏ vừa tay, xếp tất cả nhân tôm, thịt, dưa leo và rau thơm ra khay gọn gàng.', NULL, NULL),
('vn-cuon-01_v4_step_6', 'vn-cuon-01', 6, 'finish', 'Làm mềm bánh tráng và cuốn gỏi tròn chặt tay', 'Nhúng nhanh từng tờ bánh tráng qua nước sạch hoặc dùng khăn ẩm thoa đều hai mặt cho bánh vừa dẻo. Xếp lá xà lách, rau húng quế, giá đỗ, dưa leo, bún tươi và 2 lát thịt ba chỉ vào phần đầu bánh, gập hai mép bên rồi cuộn chặt 1 vòng. Đặt 3 nửa con tôm mặt đỏ úp xuống cùng 2 cọng hẹ thò đầu ra ngoài, cuộn tròn tiếp đến hết mép bánh. Múc tương ra chén, rắc đậu phộng rang giã dập và ớt sừng băm lên trên để chấm.', 'Đặt tôm sau vòng cuốn đầu tiên sẽ giúp phần lưng tôm đỏ au nổi rõ qua lớp bánh tráng trong veo cực kỳ đẹp mắt.', NULL),
('vn-cuon-02_v4_step_1', 'vn-cuon-02', 1, 'prep', 'Sơ chế rau thơm và cắt lá bánh phở', 'Rửa sạch xà lách xoăn, rau húng Láng và ngò rí, ngâm nước muối loãng 5 phút rồi vớt ra rổ vẩy thật ráo nước để lá bánh phở không bị nhão khi cuốn. Bóc từng lá bánh phở tươi vuông, dùng dao sắc cắt thành miếng chữ nhật kích thước khoảng 25×12 cm vừa chiều dài lá xà lách.', 'Dùng khăn sạch thấm khô lá rau hoàn toàn trước khi cuốn giúp cuốn phở chắc tay và giữ được dáng tròn đẹp.', NULL),
('vn-cuon-02_v4_step_2', 'vn-cuon-02', 2, 'marinate', 'Thái lát và ướp thịt bò thăn', 'Dùng dao sắc thái thịt bò thăn thành lát mỏng ngang thớ. Giã nhuyễn tỏi rồi vắt lấy nước cốt, giữ lại phần xác tỏi để riêng. Cho thịt bò vào tô, ướp cùng nước cốt tỏi, 15 ml nước mắm, 5 g hạt nêm, 2 g tiêu đen xay và 15 ml dầu ăn; trộn đều và để thấm trong 20 phút.', 'Ướp thịt bò với nước cốt tỏi và chút dầu ăn thay vì tỏi băm sẽ giúp xác tỏi không bị cháy khét khi xào lửa lớn mà thịt vẫn mềm bóng.', 20),
('vn-cuon-02_v4_step_3', 'vn-cuon-02', 3, 'prep', 'Làm dưa góp đu đủ xanh và cà rốt', 'Gọt vỏ đu đủ xanh và cà rốt, thái lát mỏng vừa ăn. Xóc đều với 4 g muối ăn, để yên 5 phút cho ra bớt nhựa hăng rồi xả sạch nhiều lần với nước lạnh, vắt nhẹ cho ráo giòn.', NULL, 5),
('vn-cuon-02_v4_step_4', 'vn-cuon-02', 4, 'sauce', 'Pha nước mắm chấm chua ngọt chuẩn Hà Nội', 'Hòa tan 33 g đường cát trắng với 165 ml nước lọc ấm, khuấy đều đến khi tan hết đường rồi để nguội. Rót tiếp 33 ml nước mắm ngon, 33 ml giấm gạo và 5 ml tương ớt vào khuấy đều, thả dưa góp đu đủ cà rốt vào bát nước chấm.', 'Nước chấm phở cuốn Hà Nội chuẩn vị pha theo tỉ lệ 1 mắm : 1 đường : 1 giấm : 5 nước để giữ vị thanh nhẹ, không lấn át hương rau thơm.', NULL),
('vn-cuon-02_v4_step_5', 'vn-cuon-02', 5, 'cook', 'Xào nhanh thịt bò trên lửa lớn', 'Làm nóng chảo đáy dày trên lửa lớn với 25 ml dầu ăn, cho phần xác tỏi vào phi thơm vàng trong 20 giây. Trút toàn bộ thịt bò đã ướp vào đảo thật nhanh tay trên lửa lớn khoảng 2 phút đến khi thịt vừa chuyển màu nâu chín đều, mềm mọng và không ra nước thì trút ngay ra đĩa.', 'Chảo phải thật nóng và xào nhanh tay ở lửa lớn để khóa nước ngọt bên trong từng lát bò, tránh xào lâu làm thịt bị dai.', 2),
('vn-cuon-02_v4_step_6', 'vn-cuon-02', 6, 'finish', 'Cuốn phở gọn đẹp và trình bày', 'Trải phẳng từng miếng bánh phở tươi lên đĩa sạch, đặt 1 lá xà lách, vài cọng húng Láng, ngò rí rồi gắp thịt bò xào dàn đều theo chiều ngang. Gập nhẹ đầu bánh và cuộn tròn chắc tay cho đến hết mép, bày phở cuốn ra đĩa ăn ngay kèm bát nước mắm dưa góp.', NULL, NULL),
('vn-cuon-03_v4_step_1', 'vn-cuon-03', 1, 'prep', 'Làm sạch và khử mùi tai heo', 'Dùng dao cạo sạch lông và chất bẩn ở các kẽ tai heo. Hòa 4 g muối ăn với ít nước cốt chanh chà xát kỹ khắp hai mặt tai trong 3 phút, sau đó ngâm tai heo với 30 ml giấm gạo trong 10 phút rồi rửa sạch lại bằng nước lạnh.', 'Ngâm tai heo qua giấm và muối giúp khử hoàn toàn mùi hôi mà vẫn giữ bề mặt tai trắng sạch.', 10),
('vn-cuon-03_v4_step_2', 'vn-cuon-03', 2, 'cook', 'Luộc chín giòn tai heo và ngâm nước đá', 'Cho tai heo vào nồi với 1200 ml nước lọc ngập mặt, thêm 4 g muối ăn và 15 g gừng tươi đập dập. Đun sôi trên lửa lớn rồi hạ lửa vừa luộc khoảng 15 phút cho tai vừa chín tới, giòn sần sật. Vớt ra ngâm ngay vào thau nước đá lạnh 15 phút cho tai trắng giòn, vớt ráo rồi thái sợi mỏng.', 'Không luộc tai quá mềm sẽ mất độ giòn sần sật đặc trưng; ngâm nước đá ngay khi vớt ra giúp tai giòn và không bị thâm.', 15),
('vn-cuon-03_v4_step_3', 'vn-cuon-03', 3, 'prep', 'Bào mỏng hoa chuối ngâm chanh muối', 'Bóc bỏ các bẹ già bên ngoài bắp hoa chuối tây, dùng dao sắc bào từng lát thật mỏng và thả ngay vào thau nước lạnh đã pha 4 g muối ăn cùng nước cốt 1 quả chanh tươi. Ngâm 15 phút cho ra hết nhựa chát, vớt ra rửa lại hai lần nước sạch rồi vắt nhẹ để thật ráo.', 'Chọn hoa chuối tây thay vì chuối tiêu và ngâm ngập nước chanh muối ngay khi bào giúp sợi hoa chuối trắng tinh, không bị thâm đen.', 15),
('vn-cuon-03_v4_step_4', 'vn-cuon-03', 4, 'prep', 'Sơ chế rau củ, phi hành và giã lạc rang', 'Bào sợi cà rốt, thái lát mỏng hành tây rồi ngâm nước đá 5 phút cho giòn bớt hăng, vớt ráo. Nhặt rửa sạch giá đỗ, rau răm, rau kinh giới và húng bạc hà, để ráo và thái nhỏ rau thơm. Phi thơm vàng giòn hành tím thái lát với 20 ml dầu ăn trên lửa nhỏ rồi vớt ra giấy thấm dầu. Rang vàng lạc, xát vỏ và giã dập vừa.', NULL, NULL),
('vn-cuon-03_v4_step_5', 'vn-cuon-03', 5, 'sauce', 'Pha nước trộn nộm chua ngọt đậm đà', 'Cho 35 ml nước mắm ngon, 35 g đường cát trắng và nước cốt 1 quả chanh tươi còn lại vào bát, khuấy kỹ cho đường tan hoàn toàn rồi thêm tỏi băm và 1 quả ớt tươi băm nhuyễn vào đảo đều.', NULL, NULL),
('vn-cuon-03_v4_step_6', 'vn-cuon-03', 6, 'finish', 'Trộn nộm thấm vị và trình bày ra đĩa', 'Cho hoa chuối, tai heo thái sợi, cà rốt, hành tây và giá đỗ vào âu lớn. Rưới từ từ nước trộn nộm vào, đảo nhẹ tay và để 10 phút cho nguyên liệu thấm đều. Chắt bớt nước tiết ra nếu có, thêm rau răm, rau kinh giới, húng bạc hà và 2/3 lượng lạc rang vào trộn đều lần cuối. Bày nộm ra đĩa, rắc phần lạc rang còn lại, hành phi giòn và ớt thái lát lên trên.', NULL, 10),
('vn-cuon-04_v4_step_1', 'vn-cuon-04', 1, 'cook', 'Làm sạch và luộc chín thịt gà ta', 'Chà xát đùi gà với 2 g muối ăn và vài lát gừng tươi để khử mùi hôi rồi rửa sạch. Cho gà vào nồi với 1200 ml nước lọc ngập mặt, thêm 4 g muối ăn, phần gừng còn lại và 10 g hành tím đập dập. Đun sôi trên lửa lớn rồi hạ lửa nhỏ luộc liu riu khoảng 20 phút, tắt bếp đậy vung ngâm gà thêm 10 phút cho thịt chín đều từ trong ra ngoài, không còn đỏ sát xương.', 'Luộc lửa nhỏ và ngâm thêm trong nồi sau khi tắt bếp giúp thịt gà mềm mọng, giữ trọn vị ngọt mà da gà không bị nứt rách.', 20),
('vn-cuon-04_v4_step_2', 'vn-cuon-04', 2, 'prep', 'Ngâm giấm đá hành tây và sơ chế rau củ', 'Bào sợi thật mỏng bắp cải trắng và cà rốt, rửa sạch rồi để rổ cho thật ráo nước. Hành tây thái lát mỏng, trộn cùng 30 ml giấm gạo, 12 g đường cát trắng, 2 g muối ăn và vài viên đá lạnh, để ngăn mát tủ lạnh 15 phút cho hành giòn và dịu hẳn vị hăng rồi vớt ra vắt ráo.', 'Ngâm hành tây trong giấm đường lạnh là bí quyết giúp sợi hành trong giòn và ngọt dịu tự nhiên.', 15),
('vn-cuon-04_v4_step_3', 'vn-cuon-04', 3, 'prep', 'Chuẩn bị rau thơm, hành phi và lạc rang', 'Nhặt rửa sạch rau răm rồi cắt khúc ngắn; lá chanh thái chỉ thật mảnh. Băm nhỏ tỏi và 2 quả ớt; quả ớt còn lại bỏ hạt thái sợi. Phi thơm vàng 20 g hành tím thái lát với 15 ml dầu ăn trên lửa nhỏ rồi vớt ráo dầu. Rang chín vàng đậu phộng, xát vỏ và giã dập.', NULL, NULL),
('vn-cuon-04_v4_step_4', 'vn-cuon-04', 4, 'sauce', 'Pha nước trộn gỏi chua ngọt', 'Khuấy tan 45 ml nước mắm ngon với 30 g đường cát trắng và nước cốt 2 quả chanh tươi trong chén đến khi đường tan hết. Thêm tỏi và ớt băm vào khuấy đều, nêm lại để đạt vị chua mặn ngọt hài hòa.', 'Khuấy tan hoàn toàn đường trong nước mắm và nước cốt chanh trước khi thả tỏi ớt sẽ giúp nước trộn dậy mùi thơm dịu hơn.', NULL),
('vn-cuon-04_v4_step_5', 'vn-cuon-04', 5, 'prep', 'Xé sợi thịt gà và ướp thấm trước', 'Vớt gà ra để nguội bớt rồi lọc bỏ xương, xé thịt theo thớ thành miếng dài vừa ăn. Cho thịt gà vào âu, rưới khoảng 1/3 lượng nước trộn gỏi vào đảo đều và ướp 5 phút cho từng thớ thịt đậm đà.', NULL, 5),
('vn-cuon-04_v4_step_6', 'vn-cuon-04', 6, 'finish', 'Trộn gỏi đều tay và hoàn thiện đĩa gỏi', 'Cho bắp cải bào, cà rốt và hành tây đã vắt ráo vào âu thịt gà, rưới phần nước trộn còn lại và dùng tay đeo găng bóp trộn nhẹ nhàng cho hòa quyện. Thêm rau răm và lá chanh thái chỉ vào đảo đều lần cuối, bày ra đĩa rồi rắc hành phi, đậu phộng rang giã dập và ớt thái sợi lên trên.', NULL, NULL),
('vn-cuon-05_v4_step_1', 'vn-cuon-05', 1, 'prep', 'Bào sợi và ngâm khử nhựa đu đủ, cà rốt', 'Khía nhẹ vài đường quanh vỏ đu đủ xanh cho chảy bớt nhựa rồi rửa sạch, gọt vỏ, bỏ hạt và bào sợi mỏng dài. Cà rốt gọt vỏ, bào sợi tương tự. Hòa 600 ml nước lọc với 20 ml giấm gạo và 5 g muối ăn, thả đu đủ và cà rốt vào ngâm 20 phút cho ra sạch nhựa.', 'Ngâm nước giấm muối giúp sợi đu đủ xanh giòn trắng, hết hẳn vị hăng chát tự nhiên.', 20),
('vn-cuon-05_v4_step_2', 'vn-cuon-05', 2, 'prep', 'Bóp muối, ướp đường giúp sợi nộm giòn tan', 'Vớt đu đủ và cà rốt ra, bóp nhẹ với 5 g muối ăn trong 2 phút rồi xả sạch lại bằng nước lạnh và vắt ráo. Trộn đều sợi rau củ với 20 g đường cát trắng, để yên 15 phút cho sợi đu đủ cứng giòn rồi vắt thật ráo phần nước tiết ra.', 'Ướp đường rồi vắt ráo trước khi trộn là bí quyết giúp sợi nộm giòn sần sật mà không bị chảy nước khi bày đĩa.', 15),
('vn-cuon-05_v4_step_3', 'vn-cuon-05', 3, 'cook', 'Rang lạc, phi hành tím và xé bò khô', 'Rang lạc trên lửa nhỏ khoảng 8 phút đến khi chín thơm vàng đều, để nguội bóc vỏ lụa và giã dập. Phi thơm vàng hành tím thái lát với 10 ml dầu ăn trên lửa nhỏ rồi vớt ra giấy thấm dầu. Xé thịt bò khô thành sợi mảnh vừa ăn, nhặt rửa sạch rau kinh giới và húng bạc hà rồi cắt nhỏ.', NULL, 8),
('vn-cuon-05_v4_step_4', 'vn-cuon-05', 4, 'sauce', 'Pha nước trộn nộm chua ngọt cay nhẹ', 'Khuấy tan 45 ml nước mắm ngon với 25 g đường cát trắng và nước cốt 1,5 quả chanh tươi đến khi tan hết đường. Thêm tỏi băm nhuyễn và 1 quả ớt tươi băm nhỏ vào đảo đều, nếm lại cho vừa vị chua ngọt mặn hài hòa.', NULL, NULL),
('vn-cuon-05_v4_step_5', 'vn-cuon-05', 5, 'prep', 'Áo sơ nộm với rau thơm và bò khô', 'Cho đu đủ xanh, cà rốt đã vắt ráo, thịt bò khô xé sợi cùng rau kinh giới và húng bạc hà vào âu trộn lớn, đảo tơi đều để các nguyên liệu phân bổ hài hòa.', NULL, NULL),
('vn-cuon-05_v4_step_6', 'vn-cuon-05', 6, 'finish', 'Rưới nước trộn và trình bày thưởng thức', 'Rưới đều bát nước trộn nộm vào âu, dùng đũa trộn nhẹ tay cho từng sợi đu đủ và bò khô thấm đẫm gia vị. Gắp nộm ra đĩa sâu lòng, rắc lạc rang giã dập, hành phi giòn và vài lát ớt tươi lên trên rồi thưởng thức ngay.', 'Chỉ rắc lạc rang và hành phi lên đĩa nộm ngay trước khi ăn để giữ độ giòn bùi và mùi thơm hấp dẫn.', NULL),
('vn-cuon-06_v4_step_1', 'vn-cuon-06', 1, 'prep', 'Sơ chế cây sả và băm tôm thịt', 'Rửa sạch 12 cây sả, bóc bớt bẹ già. Lấy 10 cây cắt khúc dài 14 cm, đập dập nhẹ phần đầu củ để làm xiên nướng giúp tinh dầu sả thấm vào thịt; 2 cây sả còn lại băm thật nhuyễn. Tôm tươi bóc vỏ, rút chỉ đen và băm nhuyễn.', NULL, NULL),
('vn-cuon-06_v4_step_2', 'vn-cuon-06', 2, 'marinate', 'Quết dẻo nhân nem lụi và ướp lạnh', 'Trộn đều 200 g thịt nạc vai heo xay, 300 g giò sống và tôm băm cùng sả băm, hành tím băm, 1/2 lượng tỏi băm, 16 g bột năng, 15 ml dầu hào, 20 ml dầu màu điều, 22 g đường cát trắng, 4 g hạt nêm, 5 ml nước mắm và 2 g tiêu đen xay. Quết mạnh tay 5 phút cho khối thịt dẻo mịn, bọc kín và cất ngăn mát tủ lạnh ít nhất 60 phút cho thấm và se chắc.', 'Giò sống đã có sẵn độ mặn nên chỉ nêm thêm rất ít nước mắm; ướp lạnh giúp thịt dẻo và dễ nặn bám chặt quanh thân sả.', 60),
('vn-cuon-06_v4_step_3', 'vn-cuon-06', 3, 'prep', 'Bọc nhân thịt quanh cây sả', 'Thoa nhẹ 10 ml dầu ăn lên găng tay, lấy một nắm thịt vừa tay dàn mỏng rồi bọc kín quanh phần đầu đập dập của từng cây sả, miết nhẹ hai đầu cho thịt ôm chặt không bị rơi tuột khi nướng, chừa phần cuống sả để cầm.', 'Nặn khối thịt thuôn dài vừa phải và miết kỹ hai đầu mép giúp nem chín đều từ trong ra ngoài mà không bị nứt.', NULL),
('vn-cuon-06_v4_step_4', 'vn-cuon-06', 4, 'cook', 'Nướng nem lụi và quét sốt mật ong bóng đẹp', 'Làm nóng nồi chiên không dầu hoặc lò nướng ở 180°C trước 5 phút. Xếp nem lụi lên vỉ và nướng 15 phút cho thịt săn chín bên trong. Pha 15 ml mật ong, 10 ml dầu hào và 10 ml dầu màu điều, lấy nem ra quét đều lên khắp bề mặt rồi nướng tiếp 10 phút ở 180°C đến khi nem chín kỹ hoàn toàn, vàng ruộm hơi xém cạnh và dậy mùi thơm lừng.', 'Quét hỗn hợp mật ong dầu điều ở lượt nướng sau giúp nem có màu nâu cánh gián bóng mượt mà không bị cháy khét đường.', 25),
('vn-cuon-06_v4_step_5', 'vn-cuon-06', 5, 'sauce', 'Chuẩn bị rau cuốn và pha nước chấm chua ngọt', 'Rửa sạch xà lách rau thơm để ráo; thái lát mỏng dài dưa leo, dứa chín và chuối xanh (ngâm nước muối loãng chống thâm rồi vớt ráo). Tách bún tươi vừa ăn và bày bánh tráng ra đĩa. Khuấy tan 45 ml nước mắm, 20 g đường cát trắng và 60 ml nước lọc, thêm nước cốt 1 quả chanh, phần tỏi băm còn lại và ớt băm nhuyễn.', NULL, NULL),
('vn-cuon-06_v4_step_6', 'vn-cuon-06', 6, 'finish', 'Trình bày nem lụi và cuốn bánh tráng thưởng thức', 'Bày nem lụi nóng ra đĩa lớn bên cạnh bún tươi, bánh tráng và rổ rau sống. Khi ăn, trải bánh tráng, xếp xà lách, rau thơm, dưa leo, chuối xanh, dứa thơm, bún tươi và tuốt 1 cây nem lụi đặt vào giữa rồi cuốn chặt tay, chấm cùng nước mắm tỏi ớt.', NULL, NULL),
('vn-bun-01_v4_step_1', 'vn-bun-01', 1, 'prep', 'Chần sạch xương ống bò', 'Rửa sơ xương ống bò rồi cho vào nồi với 1 lít nước lọc và 5 g muối ăn, đun lửa lớn đến khi sôi bùng và chần trong 5 phút cho tiết hết bọt bẩn. Đổ bỏ toàn bộ nước chần, rửa từng khúc xương dưới vòi nước lạnh cho thật sạch cặn.', 'Chần bỏ nước đầu và rửa sạch xương dưới vòi nước giúp nước dùng trong, không bị mùi hôi gây.', 5),
('vn-bun-01_v4_step_2', 'vn-bun-01', 2, 'prep', 'Nướng gia vị tươi và rang thảo mộc khô', 'Nướng 50 g gừng tươi, 1 củ hành tây và 45 g hành tím khô trên bếp cho đến khi sém vàng mặt ngoài và dậy mùi thơm, cạo sạch lớp cháy đen rồi rửa qua và đập dập nhẹ. Cho hoa hồi khô, quế thanh khô, thảo quả khô, hạt mùi khô và đinh hương khô lên chảo khô rang ở lửa nhỏ khoảng 2 phút đến khi thơm nồng thì cho vào túi vải sạch buộc chặt.', 'Rang thảo mộc ở lửa nhỏ vừa đủ dậy tinh dầu thơm; tránh rang cháy vì sẽ làm nước phở bị đắng và sậm màu.', 10),
('vn-bun-01_v4_step_3', 'vn-bun-01', 3, 'cook', 'Ninh nước dùng xương bò thanh ngọt', 'Cho xương ống bò đã chần sạch vào nồi lớn cùng 2,5 lít nước lọc lạnh, đun sôi trên lửa lớn rồi hớt thật kỹ lớp bọt nổi. Hạ xuống lửa nhỏ liu riu, thả gừng nướng, hành tây nướng và hành tím nướng vào ninh khoảng 2,5 giờ, sau đó mới cho túi thảo mộc khô vào ninh tiếp 30 phút để hương gia vị không bị bay hơi quá sớm.', 'Chỉ giữ lửa liu riu và không đậy kín nắp hoàn toàn để nước dùng sôi êm, trong và không bị đục.', 180),
('vn-bun-01_v4_step_4', 'vn-bun-01', 4, 'marinate', 'Thái mỏng và ướp thịt thăn bò', 'Thịt thăn bò thấm thật khô bằng khăn giấy, thái lát mỏng 1–2 mm ngang thớ để thịt mềm không dai. Trộn đều thịt bò với 1/2 lượng tỏi khô băm, 5 g gừng tươi băm nhuyễn và 2 g tiêu đen xay, ướp khoảng 15 phút cho thịt ngấm hương thơm.', NULL, 15),
('vn-bun-01_v4_step_5', 'vn-bun-01', 5, 'cook', 'Lọc và nêm nếm nước dùng phở', 'Vớt bỏ xương ống bò, hành gừng nướng và túi gia vị khô ra khỏi nồi nước dùng. Nêm vào nồi 15 g muối ăn, 30 g đường phèn và 20 ml nước mắm ngon, khuấy tan rồi nếm lại sao cho nước dùng đạt vị ngọt xương thanh tao, mặn dịu hài hòa và giữ sôi nóng trên lửa nhỏ.', NULL, NULL),
('vn-bun-01_v4_step_6', 'vn-bun-01', 6, 'prep', 'Chuẩn bị rau thơm và trụng bánh phở', 'Củ hành tây còn lại thái lát thật mỏng ngâm nước đá lạnh cho giòn và bớt hăng. Hành lá tươi tách đầu hành chẻ mỏng và phần lá xanh thái nhỏ; ngò gai thái khúc ngắn. Rửa sạch húng quế, giá đỗ, cắt múi chanh tươi và thái lát ớt tươi. Đun sôi nồi nước khác, trụng bánh phở tươi khoảng 10–15 giây cho nóng mềm rồi vẩy ráo, chia đều vào 4 tô.', NULL, NULL),
('vn-bun-01_v4_step_7', 'vn-bun-01', 7, 'cook', 'Xào tái lăn thịt bò trên lửa lớn', 'Bắc chảo sâu lòng lên bếp, cho 30 ml dầu ăn vào đun đến khi dầu thật nóng bốc khói nhẹ thì cho 1/2 lượng tỏi băm còn lại vào phi thơm. Trút toàn bộ thịt thăn bò đã ướp vào đảo thật nhanh tay trên lửa lớn trong khoảng 45 giây, rưới 10 ml nước mắm ngon lên thành chảo cho dậy mùi xém thơm rồi tắt bếp ngay khi thịt vừa chuyển tái hồng.', 'Chảo phải thật nóng và xào không quá 1 phút để thịt bò giữ được độ mềm ngọt bên trong và thơm cạnh ngoài.', 1),
('vn-bun-01_v4_step_8', 'vn-bun-01', 8, 'finish', 'Chan nước dùng và hoàn thiện tô phở', 'Xếp thịt thăn bò xào tái lăn lên trên bánh phở, thêm đầu hành chẻ, hành tây thái lát, hành lá và ngò gai. Chan nước dùng đang sôi sùng sục ngập mặt bánh phở để sức nóng giúp thịt bò chín hoàn toàn và quyện hương, dọn nóng ngay cùng húng quế, giá đỗ, chanh tươi và ớt tươi.', NULL, NULL),
('vn-bun-02_v4_step_1', 'vn-bun-02', 1, 'prep', 'Sơ chế thịt ba chỉ và thịt nạc vai', 'Xát nhẹ thịt ba chỉ heo với 3 g muối ăn rồi rửa sạch dưới vòi nước lạnh, thấm thật ráo và thái lát mỏng khoảng 0,5 cm bản vừa ăn. Để riêng thịt nạc vai heo xay vào tô sạch.', NULL, 5),
('vn-bun-02_v4_step_2', 'vn-bun-02', 2, 'prep', 'Vắt nước cốt sả hành và thắng nước hàng', 'Xay thật nhuyễn sả tươi và hành tím khô với 20 ml nước lọc rồi dùng rây vắt lấy phần nước cốt thơm, bỏ bã để thịt nướng không bị cháy sém xác hành sả. Thắng chảy 8 g đường vàng trên chảo nhỏ với 1 muỗng canh nước lọc đến khi chuyển màu nâu cánh gián thì tắt bếp.', 'Chỉ dùng nước cốt sả hành thay vì xác băm giúp miếng chả lên màu vàng ruộm mà không bị lốm đốm cháy đắng.', NULL),
('vn-bun-02_v4_step_3', 'vn-bun-02', 3, 'marinate', 'Ướp chả miếng và chả viên đậm đà', 'Pha hỗn hợp ướp gồm nước cốt sả hành, nước hàng vừa thắng, 10 ml nước mắm ngon, 4 g mắm tôm, 10 g đường cát trắng, 6 g hạt nêm, 4 g muối ăn và 3 g tiêu đen xay. Chia đôi hỗn hợp trộn kỹ vào thịt ba chỉ và thịt nạc vai xay, bọc kín để ngăn mát tủ lạnh ít nhất 1 giờ cho thấm vị. Trước khi nướng 15 phút, trộn thêm 1/2 muỗng cà phê nước cốt chanh tươi vào cả hai tô thịt để chả mềm mọng.', NULL, 60),
('vn-bun-02_v4_step_4', 'vn-bun-02', 4, 'prep', 'Làm dưa góp đu đủ cà rốt giòn ngon', 'Đu đủ xanh và cà rốt thái lát mỏng, bóp nhẹ với 3 g muối ăn để 5 phút cho ra nước hăng rồi xả sạch, vắt thật ráo. Trộn đều đu đủ cà rốt với 10 g đường cát trắng, 15 ml giấm gạo, 2 g muối ăn và 1 quả ớt hiểm đỏ băm, ướp trong ngăn mát 20 phút cho thấm giòn.', 'Bóp muối xả sạch và vắt ráo nước giúp đu đủ xanh hết nhựa mà vẫn giữ được độ giòn sần sật.', 20),
('vn-bun-02_v4_step_5', 'vn-bun-02', 5, 'cook', 'Vê chả viên và nướng thịt trên than hoa', 'Nặn thịt nạc vai xay thành từng viên tròn rồi ấn dẹt vừa ăn. Xếp chả miếng ba chỉ và chả viên lên vỉ, nướng trên bếp than hoa hồng lửa vừa (hoặc nồi chiên không dầu 190°C), lật đều tay mỗi 1–2 phút và phết nhẹ 15 ml dầu ăn lên bề mặt để chả không bị khô. Nướng khoảng 15–18 phút đến khi thịt chín kỹ hoàn toàn, mỡ tươm xèo xèo và hai mặt vàng xém thơm nức.', 'Không để than quá bốc lửa; lật vỉ đều tay và phết dầu ăn mỏng giúp chả chín sâu bên trong mà lớp ngoài bóng đẹp.', 16),
('vn-bun-02_v4_step_6', 'vn-bun-02', 6, 'sauce', 'Pha nước mắm chấm bún chả ấm nóng', 'Cho 230 ml nước lọc còn lại vào nồi nhỏ cùng 80 ml nước mắm ngon, 55 g đường cát trắng, 15 ml giấm gạo và phần nước cốt chanh tươi còn lại. Đun ở lửa nhỏ cho đường tan hoàn toàn và nước chấm vừa ấm nóng (không đun sôi mạnh để giữ hương thơm của mắm và chanh), tắt bếp rồi thả tỏi khô băm và 1 quả ớt hiểm đỏ băm vào.', NULL, NULL),
('vn-bun-02_v4_step_7', 'vn-bun-02', 7, 'finish', 'Rửa rau sống và bày biện thưởng thức', 'Rửa sạch xà lách tươi, lá tía tô cùng rau kinh giới và húng lủi, vẩy thật ráo nước. Chia bún gạo tươi ra đĩa, múc nước chấm ấm ra 4 bát, thả chả miếng, chả viên nướng nóng hổi cùng dưa góp đu đủ cà rốt vào bát và thưởng thức ngay cùng rau sống.', NULL, NULL),
('vn-bun-03_v4_step_1', 'vn-bun-03', 1, 'prep', 'Chần sạch chân giò heo và xương ống bò', 'Chà rửa chân giò heo và xương ống bò với 8 g muối ăn, sau đó cho vào nồi nước sôi chần 5 phút cho ra hết bọt bẩn rồi vớt ra rửa thật sạch dưới vòi nước lạnh.', NULL, 5),
('vn-bun-03_v4_step_2', 'vn-bun-03', 2, 'cook', 'Ninh nước dùng xương bò và chân giò', 'Cho xương ống bò, chân giò heo vào nồi cùng 2,5 lít nước lọc lạnh, thả 3 cây sả cây đập dập bó gọn và 20 g gừng tươi đập dập. Đun sôi trên lửa lớn, hớt sạch bọt rồi hạ lửa nhỏ ninh khoảng 75–90 phút; khi chân giò vừa chín mềm dẻo thì vớt ra ngâm nhanh vào nước nguội để da giòn, không bị thâm.', 'Vớt chân giò ngay khi vừa mềm sần sật và giữ lửa nhỏ khi ninh xương giúp nước dùng trong veo, không bị đục.', 80),
('vn-bun-03_v4_step_3', 'vn-bun-03', 3, 'cook', 'Luộc chín bắp bò hoa thơm mùi sả gừng', 'Cho bắp bò hoa vào nồi riêng với 500 ml nước lọc, 1 cây sả cây đập dập, 10 g gừng tươi và 1 củ hành tím đập dập, luộc lửa vừa khoảng 35–40 phút đến khi xiên đũa qua thấy thịt chín mềm. Vớt bắp bò ra để nguội hoàn toàn trong ngăn mát 20 phút rồi thái lát mỏng.', 'Để bắp bò nguội hẳn rồi ủ mát trước khi cắt giúp lát thịt săn chắc, mỏng đều và không bị nát.', 35),
('vn-bun-03_v4_step_4', 'vn-bun-03', 4, 'sauce', 'Phi sa tế sả ớt và lọc nước mắm ruốc', 'Hòa tan 25 g mắm ruốc Huế với 200 ml nước lọc, khuấy đều rồi để yên 15 phút cho lắng hết sạn cặn. Trong chảo nhỏ, đun nóng 25 ml dầu ăn và 20 ml dầu màu điều trên lửa vừa, phi thơm hành tím băm, tỏi khô băm và 2 cây sả băm nhuyễn; tắt bớt lửa rồi cho ớt bột Huế, 10 ml nước mắm và 5 g đường phèn vào đảo nhanh 2 phút thành hỗn hợp sa tế sánh đỏ.', 'Cho ớt bột khi dầu không quá sôi giúp sa tế lên màu đỏ tươi đẹp mà không bị cháy đen khét.', NULL),
('vn-bun-03_v4_step_5', 'vn-bun-03', 5, 'cook', 'Nêm mắm ruốc, luộc chả cua và hoàn thiện nước dùng', 'Vớt bỏ xương bò và sả gừng cũ khỏi nồi nước dùng, từ từ gạn lấy phần nước trong của mắm ruốc Huế đổ vào nồi (bỏ phần cặn đáy). Khi nước dùng sôi nhẹ, dùng muỗng múc từng viên chả cua Huế thả vào luộc khoảng 4–5 phút đến khi viên chả nổi lên chín căng thì vớt ra. Cho 2/3 phần sa tế vào nồi, nêm 20 ml nước mắm ngon, 15 g đường phèn, 10 g muối ăn và 12 g hạt nêm cho vị đậm đà hài hòa.', NULL, 10),
('vn-bun-03_v4_step_6', 'vn-bun-03', 6, 'finish', 'Sơ chế rau, trụng bún và lên tô bún bò Huế', 'Thái lát mỏng hành tây, cắt nhỏ hành lá và ngò rí; chuẩn bị hoa chuối bào, giá đỗ và chanh tươi. Trụng bún sợi to qua nước sôi cho mềm tơi rồi chia vào 4 tô, xếp khoanh chân giò heo, bắp bò thái lát và chả cua lên trên, chan ngập nước dùng nóng hổi, rắc hành tây, hành lá, ngò rí và dọn kèm sa tế còn lại cùng đĩa rau sống.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-bun-04_v4_step_1', 'vn-bun-04', 1, 'prep', 'Làm sạch cua đồng, khều gạch và lọc nước cua', 'Ngâm cua đồng tươi 30 phút cho nhả bùn rồi rửa nhiều lần thật sạch. Tách mai, bỏ yếm và dùng đầu đũa khều phần gạch vàng trong mai ra chén riêng. Giã nhuyễn phần thân cua cùng 3 g muối ăn, sau đó hòa với 2,4 lít nước lọc chia làm 3 lượt, bóp nhẹ và lọc qua rây mịn bỏ xác để thu nồi nước thịt cua sánh.', 'Cho chút muối khi giã cua và khuấy đều trước khi đun giúp protein cua kết dính thành tảng riêu chắc mịn.', NULL),
('vn-bun-04_v4_step_2', 'vn-bun-04', 2, 'cook', 'Rán vàng giòn đậu phụ trắng', 'Làm nóng chảo với 85 ml dầu ăn trên lửa vừa, thả từng miếng đậu phụ trắng đã thấm khô vào rán vàng đều các mặt trong khoảng 6–8 phút rồi vớt ra đĩa có giấy thấm dầu cho ráo bớt dầu thừa.', NULL, 7),
('vn-bun-04_v4_step_3', 'vn-bun-04', 3, 'cook', 'Phi hành xào gạch cua và cà chua', 'Dùng chảo khác đun nóng 15 ml dầu ăn, cho hành tím khô thái lát vào phi vàng thơm rồi vớt bớt nửa phần hành phi để riêng. Cho gạch cua vào đảo nhanh 1 phút trên lửa vừa đến khi dậy mùi thơm béo thì trút ra chén. Tiếp tục cho cà chua bổ múi cau vào chảo xào 3 phút cùng 10 ml nước mắm ngon và 5 g đường cát trắng cho cà chua mềm tiết màu đỏ cam.', 'Phi thơm hành tím rồi xào gạch cua riêng trước khi xào cà chua giúp nước dùng lên màu đỏ cam óng và thơm béo hơn.', 4),
('vn-bun-04_v4_step_4', 'vn-bun-04', 4, 'cook', 'Nấu riêu cua đồng đóng tảng xốp đẹp', 'Đặt nồi nước cua đã lọc lên bếp, nêm 10 g mắm tôm Bắc và 10 ml nước mắm ngon. Đun ở lửa vừa, dùng muôi khuấy nhẹ nhàng sát đáy nồi theo một chiều trong 3 phút đầu cho thịt cua không bén đáy; khi nước bắt đầu ấm nóng và riêu nổi lấm tấm thì ngưng khuấy, hạ lửa nhỏ. Đợi riêu kết thành tảng dày nổi lên mặt nước thì vớt nhẹ tảng riêu ra tô riêng để không bị vỡ.', 'Ngưng khuấy ngay khi nước bắt đầu nóng già và tuyệt đối không để sôi bùng mạnh để tảng riêu không bị tan nát.', 8),
('vn-bun-04_v4_step_5', 'vn-bun-04', 5, 'cook', 'Hoàn thiện nước dùng bún riêu chua thanh', 'Lọc 30 g cơm mẻ qua rây với 100 ml nước lọc cho vào nồi nước dùng cùng cà chua xào, gạch cua xào, đậu phụ rán vàng và 45 ml giấm bỗng. Nêm thêm 4 g muối ăn và 10 g hạt nêm cho vị chua thanh ngọt dịu hài hòa, đun sôi lăn tăn thêm 5 phút để đậu phụ ngấm vị nước riêu.', NULL, 5),
('vn-bun-04_v4_step_6', 'vn-bun-04', 6, 'finish', 'Thái bắp bò, chuẩn bị rau và chan bún nóng', 'Thái thật mỏng thịt bắp bò tươi; rửa sạch xà lách, rau kinh giới, lá tía tô với 3 g muối pha loãng rồi thái rối, cắt nhỏ hành lá và thái lát ớt tươi. Trụng bún tươi qua nước sôi chia vào 4 tô, xếp tảng riêu cua, đậu rán và cà chua lên trên; nhúng nhanh thịt bắp bò vào nồi nước dùng đang sôi 15–20 giây cho vừa chín tái mềm rồi xếp lên tô, chan ngập nước riêu nóng, rắc hành lá và dọn kèm rau sống, mắm tôm.', NULL, NULL),
('vn-bun-05_v4_step_1', 'vn-bun-05', 1, 'marinate', 'Sơ chế và ướp thịt nạc dăm nướng', 'Rửa thịt nạc dăm heo với 2 g muối ăn rồi xả sạch, thấm khô và thái lát mỏng 0,5 cm. Xay nhuyễn sả tươi, 20 g hành tím khô và 2/3 lượng tỏi khô, vắt lấy nước cốt thơm (bỏ xác) rồi trộn với 20 ml dầu hào, 15 ml mật ong nguyên chất, 15 ml nước mắm ngon, 10 g đường cát trắng, 2 g muối ăn và 10 ml dầu ăn. Trộn đều với thịt, bọc kín ướp ngăn mát ít nhất 1 giờ.', 'Vắt bỏ xác sả tỏi khi ướp giúp thịt thấm sâu hương thơm mà không bị cháy đen khi nướng trên lửa cao.', 60),
('vn-bun-05_v4_step_2', 'vn-bun-05', 2, 'prep', 'Làm đồ chua củ cải trắng và cà rốt', 'Củ cải trắng và 2/3 củ cà rốt bào sợi mảnh, bóp nhẹ với 2 g muối ăn để 10 phút cho mềm bớt hăng rồi xả sạch, vắt thật ráo. Trộn đều sợi củ với 20 g đường cát trắng và 35 ml giấm gạo, ủ trong ngăn mát tủ lạnh ít nhất 20 phút cho thấm giòn.', NULL, 20),
('vn-bun-05_v4_step_3', 'vn-bun-05', 3, 'cook', 'Cuốn chả giò và chiên vàng giòn', 'Trộn 150 g thịt heo xay với 1/3 củ cà rốt băm nhỏ, 10 g hành tím băm, 5 ml nước mắm ngon và 1 g muối ăn. Trải bánh tráng cuốn chả giò, múc lượng nhân vừa đủ cuộn tròn chặt tay thành 10–12 cuốn. Đun nóng 175 ml dầu ăn trên lửa vừa trong chảo sâu lòng, thả chả giò vào chiên khoảng 8–10 phút đến khi vỏ ngoài vàng rộm, giòn đều và nhân thịt heo chín kỹ thì vớt ra giấy thấm dầu.', 'Chiên chả giò ở lửa vừa giúp phần nhân thịt chín thấu bên trong mà lớp vỏ bánh tráng ngoài vẫn vàng giòn lâu.', 10),
('vn-bun-05_v4_step_4', 'vn-bun-05', 4, 'cook', 'Nướng thịt xém cạnh và thắng mỡ hành', 'Xiên thịt nạc dăm đã ướp lên vỉ nướng than hoa (hoặc xếp vào nồi chiên không dầu ở 200°C), nướng khoảng 14–16 phút và trở mặt giữa chừng đến khi thịt chín hẳn, vàng óng xém cạnh thơm lừng. Trong chén chịu nhiệt, trộn hành lá tươi thái nhỏ với 1 g muối ăn; đun sôi 15 ml dầu ăn trên chảo nhỏ rồi rưới nhanh vào chén hành, đảo đều cho hành chín tái xanh mướt.', NULL, 15),
('vn-bun-05_v4_step_5', 'vn-bun-05', 5, 'sauce', 'Pha nước mắm chua ngọt Nam Bộ', 'Hòa tan 35 g đường cát trắng với 80 ml nước lọc, 40 ml nước mắm ngon và 25 ml giấm gạo cho đến khi đường tan hết không còn lắng đáy, sau đó mới thả 1/3 lượng tỏi khô băm nhuyễn và ớt tươi băm vào để tỏi ớt nổi đẹp trên mặt chén.', 'Khuấy tan hoàn toàn đường trong hỗn hợp mắm giấm nước trước khi cho tỏi ớt băm sẽ giúp tỏi ớt nổi đều đẹp mắt.', NULL),
('vn-bun-05_v4_step_6', 'vn-bun-05', 6, 'finish', 'Chuẩn bị rau, cắt chả giò và hoàn thiện tô bún', 'Rửa sạch xà lách, rau thơm rồi thái sợi vừa ăn; dưa leo thái sợi mảnh; giá đỗ chần sơ nước sôi để ráo; giã dập đậu phộng rang. Chia xà lách, rau thơm lót đáy 4 tô, xếp bún tươi sợi nhỏ lên trên cùng dưa leo, giá đỗ, thịt nướng nóng, chả giò cắt khúc và đồ chua; rưới mỡ hành, rắc đậu phộng giã dập rồi chan nước mắm chua ngọt thưởng thức.', NULL, NULL),
('vn-bun-06_v4_step_1', 'vn-bun-06', 1, 'prep', 'Sơ chế gà ta và ngâm nấm, miến dong', 'Chà xát toàn bộ thân gà ta với 5 g muối ăn để khử mùi, cắt bỏ tuyến dầu ở phao câu rồi rửa sạch với nước lạnh. Nướng sơ gừng tươi, hành tây và 15 g hành tím khô cho dậy thơm, cạo sạch vỏ cháy. Ngâm nấm hương khô và mộc nhĩ khô vào nước ấm 15 phút cho nở mềm rồi rửa sạch, cắt bỏ chân cứng và thái sợi. Ngâm miến dong khô trong nước lạnh 7 phút cho mềm rồi vớt ra cắt khúc vừa ăn.', NULL, 15),
('vn-bun-06_v4_step_2', 'vn-bun-06', 2, 'cook', 'Luộc gà ta lửa nhỏ lấy nước dùng trong', 'Cho gà ta vào nồi lớn cùng 2,5 lít nước lọc lạnh, thêm gừng nướng, hành tây nướng và hành tím nướng. Đun ở lửa vừa đến khi nước vừa sôi tim thì hạ nhỏ lửa liu riu, luộc khoảng 30 phút và hớt bọt mỗi 5 phút để nước thật trong. Xiên đũa vào phần đùi gà thấy không còn nước hồng chảy ra là gà đã chín kỹ.', 'Luộc gà từ nước lạnh và giữ sôi lăn tăn ở lửa nhỏ giúp thịt gà chín đều, da không bị nứt rách và nước dùng trong vắt.', 30),
('vn-bun-06_v4_step_3', 'vn-bun-06', 3, 'prep', 'Xé thịt gà và nêm nước dùng ngọt thanh', 'Vớt gà ra ngâm nhanh vào tô nước nguội 5 phút để da giòn, vớt ráo rồi lọc bỏ xương và xé thịt gà thành miếng vừa ăn. Trả phần xương gà vào nồi ninh tiếp 10 phút cho ngọt nước rồi vớt bỏ xương và hành gừng. Nêm vào nồi nước dùng 10 g muối ăn, 15 ml nước mắm ngon và 10 g hạt nêm cho vừa miệng, giữ nóng trên lửa nhỏ.', 'Ngâm gà chín vào nước nguội vài phút giúp da gà săn bóng đẹp mắt và thịt giữ được độ ẩm ngọt.', NULL),
('vn-bun-06_v4_step_4', 'vn-bun-06', 4, 'marinate', 'Ướp thịt gà xé thấm vị đậm đà', 'Trộn đều phần thịt gà xé với 5 ml nước mắm ngon, 4 g đường cát trắng và 1 g tiêu đen xay, để nghỉ khoảng 10 phút cho thịt gà thấm gia vị trước khi xào.', NULL, 10),
('vn-bun-06_v4_step_5', 'vn-bun-06', 5, 'cook', 'Xào nấm hương mộc nhĩ cùng thịt gà', 'Đun nóng 25 ml dầu ăn trên chảo lửa vừa, cho 15 g hành tím khô băm nhỏ vào phi thơm. Trút nấm hương và mộc nhĩ thái sợi vào xào săn khoảng 4 phút cùng 5 ml nước mắm ngon, sau đó cho thịt gà đã ướp vào đảo đều tay thêm 3 phút đến khi thịt săn thơm thì tắt bếp.', 'Xào riêng nấm và thịt gà giúp phần topping thơm lừng mùi nấm hương mà không làm đục nồi nước dùng trong.', 7),
('vn-bun-06_v4_step_6', 'vn-bun-06', 6, 'finish', 'Chần miến dong và chan nước dùng nóng', 'Khi nước dùng đang sôi nhẹ, trụng miến dong vào nồi nước sôi khoảng 30–45 giây cho sợi miến vừa chín mềm dai (không trụng quá lâu tránh nát) rồi chia ra 4 tô. Xếp thịt gà xào nấm hương mộc nhĩ lên trên, chan nước dùng gà thật nóng ngập mặt miến, rắc hành lá, rau răm, ngò gai và 1 g tiêu đen xay còn lại rồi thưởng thức ngay.', NULL, NULL),
('vn-chay-01_v4_step_1', 'vn-chay-01', 1, 'prep', 'Sơ chế đậu phụ, nấm đông cô và gia vị tươi', 'Rửa nhẹ đậu phụ trắng qua nước sạch, dùng khăn giấy thấm thật khô rồi cắt miếng vuông cạnh 3,5–4 cm. Nấm đông cô tươi cắt bỏ phần chân cứng, rửa sạch nhẹ tay rồi để ráo, khía chữ thập nhẹ trên mũ nấm lớn để nhanh thấm vị. Hành boa-rô rửa sạch, thái nhỏ riêng phần thân trắng và phần lá xanh; ớt sừng thái lát mỏng.', 'Thấm thật ráo nước trên bề mặt đậu phụ giúp khi chiên không bị bắn dầu và lớp vỏ vàng giòn nhanh hơn.', NULL),
('vn-chay-01_v4_step_2', 'vn-chay-01', 2, 'sauce', 'Pha hỗn hợp nước sốt kho nấm tiêu', 'Cho vào chén 30 ml nước tương, 15 ml dầu hào chay, 12 g đường cát trắng, 4 g hạt nêm chay, 2 g muối ăn, 1,5 g tiêu đen xay thô (một nửa lượng tiêu) và 80 ml nước lọc. Khuấy đều tay đến khi đường và hạt nêm tan hoàn toàn thành hỗn hợp sốt đồng nhất.', 'Pha sẵn sốt trong chén giúp gia vị thấm đều khắp nồi đậu và nấm, tránh chỗ mặn chỗ nhạt khi kho.', NULL),
('vn-chay-01_v4_step_3', 'vn-chay-01', 3, 'cook', 'Chiên vàng đều các mặt đậu phụ', 'Làm nóng chảo chống dính trên lửa vừa với 20 ml dầu ăn thực vật. Nhẹ nhàng xếp từng miếng đậu phụ vào chiên khoảng 6 phút, lật trở đều tay đến khi các mặt se vàng giòn thì gắp ra đĩa có lót giấy thấm dầu.', 'Chiên tạo lớp vỏ se vàng giúp miếng đậu giữ nguyên hình dáng, không bị vỡ nát khi kho chung với nấm.', 6),
('vn-chay-01_v4_step_4', 'vn-chay-01', 4, 'cook', 'Phi thơm hành boa-rô và xào săn nấm', 'Dùng nồi đất hoặc chảo sâu lòng, cho 10 ml dầu ăn còn lại vào làm nóng trên lửa vừa, thả phần thân trắng hành boa-rô vào phi 30 giây cho dậy mùi thơm. Trút nấm đông cô vào đảo nhanh tay trong 3 phút đến khi mũ nấm săn lại và hơi xém cạnh.', NULL, 3),
('vn-chay-01_v4_step_5', 'vn-chay-01', 5, 'cook', 'Kho liu riu đậu phụ và nấm thấm sốt', 'Rót chén nước sốt kho đã pha vào nồi nấm, xếp nhẹ các miếng đậu phụ chiên vào và lắc nhẹ nồi cho sốt phủ đều. Đun sôi bùng trên lửa vừa rồi hạ xuống lửa nhỏ, kho liu riu không đậy nắp trong 9 phút đến khi nước sốt keo sánh óng ả và bám quanh từng miếng đậu, nấm.', 'Kho lửa nhỏ và tránh dùng đũa đảo mạnh mà chỉ rưới sốt lên mặt đậu sẽ giúp đậu thấm đượm gia vị mà vẫn nguyên miếng.', 9),
('vn-chay-01_v4_step_6', 'vn-chay-01', 6, 'finish', 'Hoàn thiện với dầu mè, tiêu đen và hành lá boa-rô', 'Nêm nếm lại sốt kho cho vừa khẩu vị, rắc phần lá xanh hành boa-rô, ớt sừng thái lát và rưới 5 ml dầu mè thơm vào, đảo thật nhẹ rồi tắt bếp. Rắc nốt 1,5 g tiêu đen xay còn lại lên mặt nồi kho và dọn nóng ăn kèm cơm trắng.', NULL, NULL),
('vn-chay-02_v4_step_1', 'vn-chay-02', 1, 'prep', 'Ngâm mềm hạt sen, táo đỏ và kỷ tử', 'Ngâm 150 g hạt sen khô trong nước ấm khoảng 30 phút cho mềm, kiểm tra và tách bỏ hết phần tim sen nếu còn để nước canh không bị đắng. Táo đỏ và kỷ tử khô rửa sạch bụi, ngâm nước ấm riêng trong 10 phút cho nở mềm rồi vớt ra để ráo.', 'Ngâm hạt sen trước giúp khi hầm nhanh bở tơi mà không bị sượng lõi bên trong.', 10),
('vn-chay-02_v4_step_2', 'vn-chay-02', 2, 'prep', 'Sơ chế củ sen, cà rốt, bắp ngọt và hai loại nấm', 'Củ sen gọt vỏ, thái khoanh dày 0,6 cm và ngâm ngay vào thau nước pha 3 g muối hột trong 5 phút cho khỏi thâm, sau đó rửa lại để ráo. Cà rốt gọt vỏ, tỉa hoa cắt khoanh 0,8 cm; bắp ngọt rửa sạch. Nấm đùi gà cắt bỏ gốc, thái lát 0,5 cm; nấm kim châm cắt gốc, tách chùm vừa ăn. Hành boa-rô thái riêng đầu trắng và lá xanh; mùi tàu thái nhỏ.', 'Ngâm củ sen trong nước muối loãng ngay sau khi thái giữ cho lát sen trắng giòn và đẹp mắt.', NULL),
('vn-chay-02_v4_step_3', 'vn-chay-02', 3, 'cook', 'Phi thơm hành boa-rô và xào sơ củ quả lấy ngọt', 'Đun nóng 15 ml dầu ăn trong nồi sâu lòng trên lửa vừa, phi thơm phần đầu trắng hành boa-rô trong 30 giây. Cho nấm đùi gà, củ sen, cà rốt, bắp ngọt và hạt sen vào đảo đều 2 phút cùng 4 g muối hột và 5 g hạt nêm chay cho nguyên liệu ngấm vị.', 'Xào sơ củ quả và nấm với chút gia vị trước khi đổ nước giúp nước canh ngọt đậm và thơm hơn.', 2),
('vn-chay-02_v4_step_4', 'vn-chay-02', 4, 'cook', 'Hầm mềm hạt sen, củ sen và táo đỏ', 'Đổ 1500 ml nước lọc vào nồi, bật lửa lớn đun sôi rồi hạ về lửa nhỏ, mở hé vung hầm 15 phút và hớt sạch bọt nổi để nước canh trong veo. Tiếp theo cho táo đỏ vào hầm thêm 10 phút cho hạt sen chín bở, củ sen mềm giòn và táo tiết vị ngọt dịu.', NULL, 25),
('vn-chay-02_v4_step_5', 'vn-chay-02', 5, 'cook', 'Nấu chín nấm kim châm và kỷ tử', 'Thả nấm kim châm và kỷ tử vào nồi canh, nêm thêm 3 g muối hột cùng 5 g hạt nêm chay còn lại. Đun sôi lăn tăn trên lửa vừa trong 3 phút cho nấm kim châm vừa chín tới, giữ được độ giòn ngọt tự nhiên.', 'Nấm kim châm chín rất nhanh, chỉ nên nấu 3 phút để không bị dai và mất vị ngọt thanh.', 3),
('vn-chay-02_v4_step_6', 'vn-chay-02', 6, 'finish', 'Hoàn thiện tô canh chay thanh mát', 'Nêm nếm lại độ mặn ngọt hài hòa của nước canh rồi tắt bếp, thả phần lá xanh hành boa-rô và mùi tàu thái nhỏ vào khuấy nhẹ. Múc canh nấm hạt sen táo đỏ ra tô lớn và thưởng thức ngay khi còn nóng ấm.', NULL, NULL),
('vn-chay-03_v4_step_1', 'vn-chay-03', 1, 'prep', 'Chần tơi sợi mì và sơ chế rau củ, nấm', 'Tách tơi 450 g mì sợi vàng tươi chay, chần thật nhanh qua nước ấm 1 phút cho sợi vừa mềm tơi rồi vớt ra rổ, rũ tơi và để ráo hoàn toàn nước. Nấm đùi gà thái lát mỏng; cà rốt gọt vỏ thái lát mỏng; cải ngọt cắt khúc 4 cm; hành boa-rô thái nhỏ; ngò rí cắt khúc. Hòa tan 10 g bột năng với 45 ml nước lọc để riêng.', 'Chỉ ngâm hoặc chần mì vừa mềm nhẹ để khi chiên sợi mì phồng giòn rụm mà không bị cứng hay ngấm dầu.', 2),
('vn-chay-03_v4_step_2', 'vn-chay-03', 2, 'cook', 'Chiên phồng giòn từng mẻ mì sợi vàng', 'Đun nóng khoảng 235 ml dầu ăn thực vật trong chảo sâu lòng trên lửa vừa đến khi dầu sôi sủi tăm quanh đầu đũa. Chia mì thành 3 phần, thả nhẹ từng phần vào chiên ngập dầu trong 3–4 phút, trở đều 2 mặt đến khi sợi mì phồng vàng giòn rụm thì vớt ra giấy thấm dầu.', 'Đảm bảo dầu đủ nóng trước khi thả mì để mì phồng nhanh, giòn lâu và không bị hút dầu.', 4),
('vn-chay-03_v4_step_3', 'vn-chay-03', 3, 'cook', 'Phi thơm hành boa-rô và xào săn nấm đùi gà, cà rốt', 'Đặt chảo khác lên bếp với 15 ml dầu ăn, làm nóng trên lửa lớn rồi phi thơm phần đầu trắng hành boa-rô trong 20 giây. Cho nấm đùi gà và cà rốt vào đảo nhanh tay 2 phút đến khi nấm săn lại, sau đó nêm 15 ml nước tương, 4 g hạt nêm chay, 3 g đường và 15 ml dầu hào chay.', NULL, 2),
('vn-chay-03_v4_step_4', 'vn-chay-03', 4, 'cook', 'Xào chín giòn cải ngọt và nêm sốt', 'Thêm phần cọng cải ngọt vào đảo 1 phút, sau đó cho phần lá cải ngọt cùng 75 ml nước lọc vào xào nhanh trên lửa lớn khoảng 2 phút cho rau vừa chín tới, vẫn giữ màu xanh mướt. Nêm tiếp 15 ml nước tương và 4 g hạt nêm chay còn lại rồi đảo đều.', 'Xào nhanh trên lửa lớn và cho cọng cải vào trước phần lá giúp cải chín đều mà giữ được độ giòn ngọt.', 2),
('vn-chay-03_v4_step_5', 'vn-chay-03', 5, 'sauce', 'Tạo độ sánh cho nước sốt với bột năng', 'Khuấy đều lại chén nước bột năng rồi rót từ từ vào chảo rau nấm đang sôi, vừa rót vừa đảo đều tay khoảng 1 phút đến khi nước sốt trở nên sánh bóng bám đều vào rau củ. Rưới 5 ml dầu mè thơm và rắc 1 g tiêu đen xay vào đảo nhẹ rồi tắt bếp.', NULL, NULL),
('vn-chay-03_v4_step_6', 'vn-chay-03', 6, 'finish', 'Trình bày và thưởng thức mì xào giòn nóng', 'Xếp các vắt mì đã chiên giòn ra đĩa lớn, múc phần nhân nấm đùi gà, cải ngọt, cà rốt cùng nước sốt sánh nóng hổi rưới đều lên trên. Rắc lá xanh hành boa-rô, ngò rí và 0,5 g tiêu đen xay còn lại rồi thưởng thức ngay khi mì còn giòn rụm.', NULL, NULL),
('vn-chay-04_v4_step_1', 'vn-chay-04', 1, 'prep', 'Sơ chế cà tím và các nguyên liệu ăn kèm', 'Chọn cà tím dài quả thẳng, vỏ căng bóng, rửa sạch rồi bổ đôi theo chiều dọc, dùng mũi dao khứa vài đường chéo trên bề mặt thịt cà để gia vị dễ thấm. Hành lá rửa sạch, vẩy thật ráo rồi thái nhỏ; tỏi khô và ớt sừng băm thật nhuyễn; đậu phộng rang giã dập.', 'Khứa đường chéo nhẹ trên mặt cắt cà tím giúp cà chín nhanh đều và giữ được sốt khi nướng lần hai.', NULL),
('vn-chay-04_v4_step_2', 'vn-chay-04', 2, 'cook', 'Nướng sơ cà tím cho thịt cà mềm ngọt', 'Làm nóng lò nướng hoặc nồi chiên không dầu ở 190°C trong 5 phút. Xếp cà tím lên khay có lót giấy bạc với mặt cắt hướng lên trên, nướng lần 1 trong 15 phút đến khi vỏ hơi xém và thịt cà mềm nhũn khi ấn nhẹ.', 'Nếu nướng trên bếp than hoa, có thể nướng nguyên quả và trở đều mỗi 4–5 phút để vỏ cháy xém thơm đặc trưng rồi mới tách vỏ.', 15),
('vn-chay-04_v4_step_3', 'vn-chay-04', 3, 'sauce', 'Pha sốt nước tương tỏi ớt chua ngọt dịu', 'Trong lúc chờ nướng cà, cho vào chén 30 ml nước tương, 60 ml nước lọc và 5 g đường cát trắng, khuấy đều tay đến khi đường tan hết. Tiếp tục thêm toàn bộ phần tỏi băm và ớt băm vào trộn đều để tạo vị mặn ngọt cay dịu hài hòa.', NULL, NULL),
('vn-chay-04_v4_step_4', 'vn-chay-04', 4, 'sauce', 'Chế biến mỡ hành xanh mướt thơm béo', 'Cho hành lá thái nhỏ cùng 2,5 g muối ăn vào chén chịu nhiệt. Đun nóng 30 ml dầu ăn thực vật trong chảo nhỏ trên lửa vừa khoảng 1 phút đến khi dầu sôi sủi tăm thì tắt bếp, đổ trực tiếp dầu nóng vào chén hành và đảo đều tay.', 'Trộn chút muối vào hành và đổ dầu sôi già khi đã tắt bếp giúp hành giữ màu xanh tươi mà không bị cháy đắng.', 1),
('vn-chay-04_v4_step_5', 'vn-chay-04', 5, 'cook', 'Tước thớ thịt cà tím và nướng thấm sốt lần hai', 'Lấy khay cà tím ra khỏi lò, dùng nĩa xăm nhẹ và tước dọc nhẹ nhàng cho phần thịt cà tơi ra thành thớ dài. Dùng muỗng rưới đều một nửa phần sốt nước tương tỏi ớt và một nửa mỡ hành lên khắp bề mặt cà tím, đưa lại vào lò nướng thêm 8 phút ở 180°C cho sốt thấm sâu vào từng thớ cà.', NULL, 8),
('vn-chay-04_v4_step_6', 'vn-chay-04', 6, 'finish', 'Phết mỡ hành, rắc đậu phộng và thưởng thức nóng', 'Xếp cà tím nướng ra đĩa dài, chan nốt phần sốt nước tương tỏi ớt và mỡ hành còn lại lên mặt cà. Rắc đều đậu phộng rang giã dập cùng 1 g tiêu đen xay và thưởng thức ngay khi còn nóng hổi với cơm trắng.', NULL, NULL),
('vn-chay-05_v4_step_1', 'vn-chay-05', 1, 'prep', 'Sơ chế nấm rơm, đậu hũ non và rau thơm', 'Nấm rơm gọt sạch phần gốc dính đất, rửa nhẹ dưới vòi nước rồi ngâm nước muối loãng 5 phút, xả lại nước sạch và để thật ráo; nấm to bổ làm đôi. Đậu hũ non cắt khoanh tròn dày 1,5–2 cm, xếp ngay ngắn vào đĩa sâu lòng. Tỏi và hành tím băm nhuyễn; hành lá, ngò rí thái nhỏ; ớt sừng thái lát.', 'Chọn nấm rơm búp còn tròn chắc chưa nở bung sẽ giữ được độ giòn ngọt đặc trưng khi xào.', NULL),
('vn-chay-05_v4_step_2', 'vn-chay-05', 2, 'cook', 'Hấp cách thủy đậu hũ non nóng đều', 'Đun sôi nước trong xửng hấp rồi đặt đĩa đậu hũ non vào, hấp cách thủy trên lửa vừa khoảng 10 phút đến khi từng khoanh đậu nóng ấm và hơi săn mặt lại. Nhấc đĩa đậu ra, chắt nhẹ phần nước thừa tiết ra trên đĩa để sốt không bị loãng.', 'Hấp riêng đậu hũ non trước rồi mới rưới sốt giúp từng khoanh đậu giữ nguyên hình tròn đẹp mắt, không bị vỡ nát.', 10),
('vn-chay-05_v4_step_3', 'vn-chay-05', 3, 'sauce', 'Pha chén nước sốt dầu hào chay', 'Trong lúc hấp đậu, cho vào chén 18 ml dầu hào chay, 22 ml nước tương, 6 g đường cát trắng, 4 g hạt nêm chay, 4 g bột bắp và 80 ml nước lọc. Khuấy kỹ cho đường và bột bắp tan hoàn toàn không bị lắng cặn dưới đáy chén.', NULL, NULL),
('vn-chay-05_v4_step_4', 'vn-chay-05', 4, 'cook', 'Phi thơm hành tỏi và xào săn nấm rơm', 'Làm nóng chảo với 20 ml dầu ăn trên lửa vừa, cho hành tím và tỏi băm vào phi khoảng 45 giây đến khi dậy mùi thơm và ngả vàng nhẹ. Vặn lửa lớn, thả nấm rơm vào đảo nhanh tay 3–4 phút cho nấm săn lại và thấm hương dầu thơm.', 'Xào nấm nhanh trên lửa lớn giúp nấm rơm chín giòn và không bị chảy nhiều nước.', 4),
('vn-chay-05_v4_step_5', 'vn-chay-05', 5, 'cook', 'Nấu sánh phần nước sốt nấm rơm', 'Khuấy đều lại chén sốt dầu hào chay rồi đổ vào chảo nấm, hạ xuống lửa vừa và đảo đều liên tục khoảng 2–3 phút đến khi nước sốt sôi lăn tăn, sánh bóng mượt và quyện quanh từng miếng nấm thì tắt bếp.', NULL, 3),
('vn-chay-05_v4_step_6', 'vn-chay-05', 6, 'finish', 'Rưới sốt lên đậu hũ non và hoàn thiện', 'Múc phần sốt nấm rơm đang nóng hổi rưới đều phủ lên từng khoanh đậu hũ non đã hấp. Rắc hành lá, ngò rí thái nhỏ, 1 g tiêu đen xay và xếp vài lát ớt sừng lên trên, dọn dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('vn-chay-06_v4_step_1', 'vn-chay-06', 1, 'prep', 'Sơ chế rau cải bẹ xanh, đậu phụ và gừng', 'Rau cải bẹ xanh nhặt bỏ lá úa và phần gốc già, tách bẹ rửa sạch nhiều lần rồi cắt khúc 3–4 cm, để ráo. Đậu phụ trắng cắt miếng vuông cạnh 2 cm. Gừng già cạo vỏ, đập dập một nửa (12,5 g), phần còn lại thái sợi mỏng; hành tím băm nhỏ; hành lá và ngò rí thái nhỏ.', 'Chọn bó cải bẹ xanh non, cọng mảnh vừa phải sẽ ít đắng và giòn ngọt hơn cải già.', NULL),
('vn-chay-06_v4_step_2', 'vn-chay-06', 2, 'cook', 'Phi thơm hành tím và gừng già đập dập', 'Đặt nồi lên bếp với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và phần gừng đập dập vào phi khoảng 45 giây đến khi dậy mùi thơm cay ấm đặc trưng.', 'Phi thơm gừng đập dập trước giúp tinh dầu gừng tiết ra hòa vào nước dùng, làm ấm bụng và khử mùi tanh nhẹ của đậu.', NULL),
('vn-chay-06_v4_step_3', 'vn-chay-06', 3, 'cook', 'Nấu nước canh sôi và thả đậu phụ', 'Đổ 1000 ml nước lọc vào nồi, đậy nắp đun lửa lớn cho sôi bùng rồi hạ lửa vừa. Nhẹ nhàng thả từng miếng đậu phụ trắng vào, nấu sôi lăn tăn trong 4 phút cho đậu nóng đều và nước canh ngấm hương gừng.', NULL, 4),
('vn-chay-06_v4_step_4', 'vn-chay-06', 4, 'cook', 'Nêm gia vị cân bằng vị cải bẹ xanh', 'Nêm vào nồi canh 6 g hạt nêm chay, 3 g muối ăn, 2 g đường cát trắng và 15 ml nước tương, khuấy thật nhẹ tay tránh làm vỡ đậu và nếm lại cho vừa khẩu vị thanh dịu.', 'Thêm một chút đường cát trắng giúp dịu hẳn vị đắng nhẹ đặc trưng của rau cải bẹ xanh.', NULL),
('vn-chay-06_v4_step_5', 'vn-chay-06', 5, 'cook', 'Nấu cải bẹ xanh giữ màu xanh giòn', 'Tăng lên lửa lớn cho nước canh sôi mạnh trở lại rồi thả rau cải bẹ xanh cùng phần gừng thái sợi vào, dùng vá ấn nhẹ cho rau ngập nước. Nấu mở vung trong 2 phút đến khi cọng cải vừa chín tới, giữ nguyên màu xanh mướt.', 'Không đậy vung và không nấu cải quá 3 phút để rau không bị úa vàng và mất độ giòn.', 2),
('vn-chay-06_v4_step_6', 'vn-chay-06', 6, 'finish', 'Hoàn thiện và dọn canh nóng', 'Tắt bếp ngay khi cải vừa chín tới, thả hành lá và ngò rí thái nhỏ vào. Múc canh ra tô lớn, rắc 1 g tiêu đen xay lên trên và dùng nóng ngay trong bữa cơm.', NULL, NULL),
('vn-sang-01_v4_step_1', 'vn-sang-01', 1, 'prep', 'Làm tơi cơm nguội và ướp gia vị', 'Cho 360 g cơm nguội ra tô lớn, dùng tay sạch bóp nhẹ cho từng hạt cơm tách rời hoàn toàn. Trộn cơm với 5 ml nước mắm ngon, 3 g hạt nêm, 2 g đường cát trắng, 1,5 g muối ăn, 1/2 lượng tiêu đen xay và 10 ml dầu ăn để hạt cơm bóng mượt, thấm đều gia vị trước khi chiên.', 'Dùng cơm nấu ráo nước đã để nguội trong ngăn mát vài giờ sẽ giúp hạt cơm săn chắc, khi rang rất tơi mà không bị bết dính.', NULL),
('vn-sang-01_v4_step_2', 'vn-sang-01', 2, 'prep', 'Sơ chế tỏi, hành lá và cà chua', 'Bóc vỏ 1 củ tỏi khô, chia một nửa băm nhuyễn và một nửa thái lát mỏng đều nhau. Rửa sạch hành lá, tách riêng đầu hành trắng băm nhỏ, phần lá xanh thái nhuyễn. Rửa sạch cà chua chín, cắt lát mỏng để trang trí đĩa cơm.', NULL, NULL),
('vn-sang-01_v4_step_3', 'vn-sang-01', 3, 'cook', 'Phi thơm vàng giòn tỏi băm và tỏi lát', 'Đun nóng 20 ml dầu ăn trong chảo sâu lòng trên lửa vừa, thử đầu đũa thấy sủi tăm nhẹ thì hạ lửa nhỏ. Cho tỏi băm vào đảo đều tay khoảng 2 phút đến khi vừa ngả màu vàng nhạt thì vớt nhanh ra đĩa lót giấy thấm dầu. Tiếp tục thả tỏi thái lát vào phi thêm 1 phút đến khi nổi vàng giòn thì vớt ra ngay, giữ lại phần dầu tỏi trong chảo.', 'Vớt tỏi phi ngay khi chuyển màu vàng nhạt vì lượng nhiệt dư sẽ tiếp tục làm tỏi vàng giòn hoàn hảo mà không bị cháy đắng.', 3),
('vn-sang-01_v4_step_4', 'vn-sang-01', 4, 'cook', 'Đánh tan và chiên tơi trứng gà', 'Làm nóng lại chảo dầu tỏi trên lửa vừa, cho phần đầu hành lá băm vào đảo thơm 15 giây. Đập 2 quả trứng gà trực tiếp vào chảo, chờ 10 giây cho lớp đáy hơi se lại rồi dùng đũa khuấy đều theo vòng tròn tạo thành những mảng trứng vàng xốp mềm.', NULL, 1),
('vn-sang-01_v4_step_5', 'vn-sang-01', 5, 'cook', 'Rang cơm lửa lớn cho hạt săn tơi', 'Trút toàn bộ tô cơm đã ướp vào chảo trứng, tăng lên lửa lớn và đảo liên tục trong 5 phút. Dùng xẻng gỗ hoặc đũa tản đều để hạt cơm và trứng hòa quyện, rang đến khi thấy hạt cơm khô ráo, săn bóng và bắt đầu nhảy lách tách nhẹ trên mặt chảo.', 'Giữ lửa lớn và đảo đều tay giúp hơi ẩm thoát nhanh, hạt cơm săn giòn bên ngoài nhưng vẫn dẻo mềm bên trong.', 5),
('vn-sang-01_v4_step_6', 'vn-sang-01', 6, 'finish', 'Rưới nước mắm tạo hương và trình bày', 'Rưới 5 ml nước mắm ngon còn lại dọc quanh thành chảo đang nóng để dậy hương thơm đặc trưng, đảo thêm 30 giây rồi tắt bếp. Trút hành lá thái nhỏ và phần tiêu đen xay còn lại vào đảo đều. Múc cơm ra đĩa, xếp cà chua thái lát bên cạnh, rắc toàn bộ tỏi phi vàng giòn lên mặt và thưởng thức nóng.', 'Chỉ rắc tỏi phi lên mặt khi tắt bếp hoặc lúc bày đĩa để giữ nguyên độ giòn rụm đến miếng cuối cùng.', NULL),
('vn-sang-02_v4_step_1', 'vn-sang-02', 1, 'prep', 'Sơ chế dưa leo, ngò rí và ớt tươi', 'Rửa sạch dưa leo, cắt bỏ hai đầu rồi thái lát vát xéo mỏng khoảng 0,3 cm để khi kẹp dễ ăn và giữ độ giòn mát. Nhặt sạch rễ ngò rí, rửa kỹ rồi vẩy thật ráo nước để bánh không bị ướt mềm. Thái lát mỏng ớt sừng đỏ nếu dùng cay.', 'Vẩy thật ráo nước rau thơm và dưa leo trước khi kẹp giúp vỏ bánh mì giữ độ giòn lâu hơn.', NULL),
('vn-sang-02_v4_step_2', 'vn-sang-02', 2, 'cook', 'Làm nóng giòn vỏ bánh mì và phết pate', 'Làm nóng nồi chiên không dầu hoặc lò nướng ở 180°C, cho 2 ổ bánh mì vào nướng lại 3 phút cho vỏ ngoài nóng giòn rụm (hoặc áp chảo khô trên lửa vừa 2 phút mỗi mặt). Dùng dao răng cưa rạch dọc một bên thân bánh tạo khoang mở, phết đều 40 g pate gan heo vào hai mặt ruột của mỗi ổ bánh.', 'Phết pate lên cả hai mặt ruột khi bánh vừa nướng nóng sẽ giúp pate hơi chảy mềm, lan tỏa hương béo ngậy khắp ổ bánh.', 3),
('vn-sang-02_v4_step_3', 'vn-sang-02', 3, 'cook', 'Đun chảy bơ và chiên trứng ốp la lòng đào', 'Đặt chảo chống dính lên bếp với lửa vừa, cho 15 g bơ vào đun chảy đến khi sủi bọt lăn tăn nhưng không để cháy nâu. Hạ lửa nhỏ vừa, đập nhẹ 2 quả trứng gà vào chảo, giữ nguyên khoảng 2 phút cho lòng trắng đông trắng hoàn toàn và viền hơi vàng giòn trong khi lòng đỏ vẫn tròn mềm sóng sánh.', 'Chiên bơ ở lửa nhỏ vừa giúp trứng không bị cháy cạnh và giữ được hương thơm béo thanh đặc trưng.', 2),
('vn-sang-02_v4_step_4', 'vn-sang-02', 4, 'cook', 'Nêm gia vị lên mặt trứng ốp la', 'Khi trứng chín đạt khoảng 7 phần (lòng trắng đông chắc, lòng đỏ hơi se màng mỏng bên ngoài), rắc đều 1,5 g muối ăn và 1 g tiêu đen xay lên bề mặt trứng, nấu thêm 30 giây rồi tắt bếp ngay để giữ độ lòng đào chuẩn.', NULL, NULL),
('vn-sang-02_v4_step_5', 'vn-sang-02', 5, 'finish', 'Xếp nhân vào ổ bánh mì', 'Dùng xẻng mỏng nhẹ nhàng xúc từng quả trứng ốp la đặt gọn vào giữa lòng mỗi ổ bánh mì đã phết pate. Xếp tiếp các lát dưa leo giòn mát, vài nhánh ngò rí tươi và vài lát ớt sừng đỏ lên trên mặt trứng.', NULL, NULL),
('vn-sang-02_v4_step_6', 'vn-sang-02', 6, 'finish', 'Rưới xì dầu, tương ớt và thưởng thức nóng', 'Rưới đều 5 ml xì dầu và 7–8 ml tương ớt vào bên trong mỗi ổ bánh mì, khép nhẹ hai mép bánh lại để phần pate, lòng đào trứng và rau hòa quyện với nhau. Dọn ăn ngay khi bánh còn nóng giòn.', 'Tránh ấn quá mạnh tay khi vừa kẹp xong để lòng đỏ trứng không bị vỡ tràn ra ngoài trước khi cắn miếng đầu tiên.', NULL),
('vn-sang-03_v4_step_1', 'vn-sang-03', 1, 'prep', 'Vo sạch và rang thơm hỗn hợp gạo tẻ, gạo nếp', 'Trộn 100 g gạo tẻ với 20 g gạo nếp, vo nhanh qua 2 lần nước sạch rồi chắt thật ráo. Làm nóng nồi đáy dày không dầu trên lửa nhỏ, cho gạo vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy hương thơm dịu.', 'Rang gạo không dầu trước khi nấu giúp hạt gạo săn lại, khi ninh chín sẽ nở bung sánh mịn mà không bị vữa nát.', 6),
('vn-sang-03_v4_step_2', 'vn-sang-03', 2, 'cook', 'Ninh cháo gạo rang trên lửa nhỏ vừa', 'Đổ 1,2 lít nước lọc đun sôi vào nồi gạo vừa rang, khuấy nhẹ đáy nồi một lượt rồi đậy hé nắp. Đun sôi bùng trên lửa vừa sau đó hạ lửa nhỏ ninh khoảng 18 phút, thỉnh thoảng khuấy đều sát đáy nồi để hạt gạo nở bung mềm nhừ và nước cháo sánh mịn.', 'Nên dùng nước nóng đổ vào gạo rang và khuấy sát đáy nồi 5 phút một lần để tránh tình trạng cháo bị bén khét.', 18),
('vn-sang-03_v4_step_3', 'vn-sang-03', 3, 'marinate', 'Ướp thịt heo xay và sơ chế gừng, tía tô, hành lá', 'Trong lúc ninh cháo, cho 180 g thịt heo nạc xay vào tô, ướp với 20 g hành tím băm, 5 ml nước mắm ngon, 2,5 g hạt nêm, 1,5 g muối ăn và 1 g tiêu đen xay, trộn đều để 10 phút cho thấm vị. Gừng già cạo vỏ thái chỉ mảnh; lá tía tô và hành lá rửa sạch rồi thái sợi nhỏ.', NULL, NULL),
('vn-sang-03_v4_step_4', 'vn-sang-03', 4, 'cook', 'Khuấy tơi thịt bằm vào nồi cháo đang sôi', 'Khi hạt gạo đã nở nhừ sánh mịn, múc một vá nước cháo nóng rưới vào tô thịt heo xay rồi dằm tơi ra trước khi trút từ từ vào nồi. Khuấy đều tay trên lửa vừa trong 4 phút để thịt chín hoàn toàn, tơi mịn mà không đóng cục và tiết vị ngọt tự nhiên.', 'Hòa chút nước cháo vào thịt xay trước khi thả vào nồi là bí quyết giúp thịt bằm tơi đều như ngoài hàng mà không cần xào nhiều dầu mỡ.', 4),
('vn-sang-03_v4_step_5', 'vn-sang-03', 5, 'cook', 'Nêm gia vị và thêm gừng tươi ấm bụng', 'Nêm thêm 10 ml nước mắm ngon, 2,5 g hạt nêm và 2,5 g muối ăn vào nồi cháo, khuấy nhẹ rồi nếm lại cho vừa khẩu vị thanh nhẹ. Thả 2/3 lượng gừng già thái chỉ vào nấu sôi lăn tăn thêm 1 phút để tinh dầu gừng hòa vào cháo.', NULL, NULL),
('vn-sang-03_v4_step_6', 'vn-sang-03', 6, 'finish', 'Lót rau thơm và múc cháo nóng giải cảm', 'Xếp một nửa lượng lá tía tô thái sợi, hành lá thái nhỏ và phần gừng thái chỉ còn lại xuống đáy 3 tô sứ sâu lòng. Múc cháo thịt bằm đang sôi sục lên trên để hơi nóng làm chín tái lá tía tô dậy mùi thơm, rắc thêm phần tía tô còn lại cùng 1 g tiêu đen xay lên mặt và thưởng thức nóng ngay.', 'Không đun lá tía tô quá lâu trong nồi vì tinh dầu dễ bay hơi và lá sẽ chuyển màu thâm đen kém đẹp mắt.', NULL),
('vn-sang-04_v4_step_1', 'vn-sang-04', 1, 'marinate', 'Thái mỏng và ướp mềm thịt bò thăn', 'Thấm khô 200 g thịt bò thăn rồi thái lát mỏng ngang thớ để thịt không bị dai. Cho bò vào tô, ướp cùng 5 ml xì dầu, 5 ml dầu hào, 3 g hạt nêm, 1 g tiêu đen xay, 1/2 lượng tỏi băm và hành tím băm cùng 5 ml dầu ăn trong 12 phút cho ngấm vị và giữ ẩm.', 'Thêm một chút dầu ăn vào ướp thịt bò giúp khóa ẩm khi xào lửa lớn và giúp các lát thịt tơi rời không dính chùm.', 12),
('vn-sang-04_v4_step_2', 'vn-sang-04', 2, 'prep', 'Sơ chế rau cải ngọt và trụng mì vừa dai', 'Cắt khúc 200 g rau cải ngọt dài 4 cm, để riêng phần cọng và lá. Đun sôi 800 ml nước lọc, thả 2 vắt mì vào trụng nhanh đúng 1 phút cho sợi mì vừa tơi rời, vớt ngay ra rổ xả qua nước lạnh cho săn sợi, để thật ráo rồi trộn với 5 ml dầu ăn chống dính.', 'Chỉ trụng mì vừa bung sợi khoảng 1 phút và xả ngay nước nguội để sợi mì giữ độ dai giòn khi đem xào lại trên chảo.', 1),
('vn-sang-04_v4_step_3', 'vn-sang-04', 3, 'cook', 'Xào nhanh rau cải ngọt giữ màu xanh giòn', 'Làm nóng 5 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một phần nhỏ tỏi băm. Cho phần cọng cải ngọt vào đảo trước 45 giây rồi trút phần lá vào xào thêm 1 phút, nêm 2 g hạt nêm, thấy rau vừa xanh mướt chín tới thì trút ngay ra đĩa riêng.', NULL, NULL),
('vn-sang-04_v4_step_4', 'vn-sang-04', 4, 'cook', 'Áp chảo thịt bò trên lửa lớn', 'Thêm 5 ml dầu ăn vào chảo nóng, phi thơm phần tỏi và hành tím băm còn lại rồi trút toàn bộ thịt bò đã ướp vào đảo nhanh tay trên lửa lớn khoảng 90 giây đến khi thịt bò vừa săn đổi màu nâu hồng, chín tới mềm ngọt thì múc riêng ra đĩa.', 'Không xào thịt bò quá lâu trên bếp vì nhiệt dư sẽ làm thịt bị khô cứng và ra nhiều nước.', 2),
('vn-sang-04_v4_step_5', 'vn-sang-04', 5, 'cook', 'Xào mì thấm sốt cùng bò và rau cải', 'Trút mì đã trụng vào chảo nóng, rưới 10 ml xì dầu, 10 ml dầu hào và 1 g hạt nêm còn lại vào đảo đều trên lửa lớn 2 phút cho sợi mì săn bóng và ngấm đều màu nâu đẹp. Đổ đĩa thịt bò và rau cải ngọt trở lại chảo cùng hành lá cắt khúc, đảo nhanh 30 giây rồi tắt bếp.', NULL, NULL),
('vn-sang-04_v4_step_6', 'vn-sang-04', 6, 'finish', 'Chiên trứng ốp la lòng đào và hoàn thiện', 'Bắc một chảo chống dính nhỏ với 10 ml dầu ăn trên lửa vừa, đập 2 quả trứng gà vào ốp la khoảng 2 phút đến khi lòng trắng đông chắc mà lòng đỏ vẫn sánh mềm. Chia mì xào bò ra 2 đĩa, đặt mỗi đĩa một quả trứng ốp la lên trên, rắc ngò rí và 1 g tiêu đen xay còn lại rồi dùng nóng.', NULL, NULL),
('vn-sang-05_v4_step_1', 'vn-sang-05', 1, 'prep', 'Băm hạt lựu thật nhỏ rau củ', 'Gọt vỏ cà rốt, rửa sạch rồi băm hạt lựu thật nhỏ li ti khoảng 2 mm. Hành tây bóc vỏ, băm hạt lựu nhỏ tương tự cà rốt. Rửa sạch hành lá và thái nhuyễn đều để khi tráng không làm cộm hay rách lớp trứng mỏng.', 'Cắt rau củ càng nhỏ mịn thì trứng càng dễ cuộn chặt tay và rau củ kịp chín mềm ngọt ngay trong lúc tráng.', NULL),
('vn-sang-05_v4_step_2', 'vn-sang-05', 2, 'prep', 'Đánh tan trứng với sữa tươi và lọc qua rây', 'Đập 4 quả trứng gà vào tô lớn, đổ vào 30 ml sữa tươi không đường, 5 ml nước mắm ngon, 2 g hạt nêm và 2 g muối ăn. Dùng đũa khuấy tan nhẹ nhàng một chiều đến khi lòng trắng và lòng đỏ quyện đều hoàn toàn, sau đó lọc hỗn hợp qua rây mịn vào tô sạch để loại bỏ lợn cợn.', 'Bước lọc qua rây giúp loại bỏ phần lòng trắng còn dai và bọt khí, tạo bề mặt trứng cuộn mịn mượt không rỗ.', NULL),
('vn-sang-05_v4_step_3', 'vn-sang-05', 3, 'prep', 'Trộn rau củ vào hỗn hợp trứng lọc', 'Trút toàn bộ cà rốt, hành tây băm hạt lựu, hành lá thái nhỏ và 1 g tiêu đen xay vào tô trứng đã lọc, khuấy nhẹ cho rau củ phân bố đều khắp hỗn hợp.', NULL, NULL),
('vn-sang-05_v4_step_4', 'vn-sang-05', 4, 'cook', 'Tráng lớp trứng mỏng đầu tiên và cuộn tròn', 'Làm nóng chảo chống dính trên lửa vừa rồi hạ xuống lửa nhỏ, dùng giấy thấm phết một lớp dầu ăn thật mỏng đều đáy chảo. Khuấy nhẹ tô trứng để lấy cả rau củ, múc 1 vá canh đổ vào lắc nhẹ cho tráng đều đáy. Khi mặt trứng vừa se ẩm khoảng 70% trong 1 phút, dùng xẻng nhẹ nhàng cuộn tròn từ mép xa về một phía thành chảo.', 'Cuộn ngay khi mặt trên trứng còn hơi ướt ẩm sẽ giúp các vòng cuộn kết dính chặt với nhau mà không bị gãy nứt.', 2),
('vn-sang-05_v4_step_5', 'vn-sang-05', 5, 'cook', 'Nối tiếp các lớp trứng đến khi hết hỗn hợp', 'Phết thêm chút dầu ăn vào phần đáy chảo trống, múc tiếp 1 vá hỗn hợp trứng đổ vào và nâng nhẹ mép cuộn trứng lên cho trứng mới chảy lót xuống bên dưới. Chờ khoảng 1 phút cho lớp mới se mặt rồi cuộn nối tiếp vòng, lặp lại đều đặn 3–4 lượt trong khoảng 5 phút đến khi hết phần trứng.', NULL, 5),
('vn-sang-05_v4_step_6', 'vn-sang-05', 6, 'finish', 'Áp vàng nhẹ hai mặt và cắt khoanh tròn', 'Khi cuộn hết trứng, giữ cuốn trứng trên chảo thêm 30 giây mỗi mặt trên lửa nhỏ để chín hoàn toàn từ trong ra ngoài và tạo màu vàng đẹp. Gắp cuộn trứng ra thớt nghỉ 2 phút cho định hình chắc tay rồi dùng dao bén cắt thành từng khoanh dày 2 cm xếp ra đĩa, ăn nóng.', 'Chờ trứng nguội bớt 2 phút trước khi cắt giúp lát cắt sắc nét, rau củ bên trong không bị xô lệch.', NULL),
('vn-sang-06_v4_step_1', 'vn-sang-06', 1, 'prep', 'Ngâm nấm hương khô và luộc chín ức gà', 'Ngâm 20 g nấm hương khô trong nước ấm khoảng 20 phút cho nở mềm, cắt bỏ chân nấm, rửa sạch rồi thái sợi chỉ mỏng. Cho 300 g ức gà vào nồi cùng 1,44 lít nước lọc và 2 g muối ăn, đun sôi rồi hạ lửa vừa luộc 12 phút, thường xuyên hớt bọt cho nước dùng thật trong. Vớt ức gà ra để nguội bớt rồi xé sợi nhỏ vừa ăn, giữ lại toàn bộ nước luộc gà.', 'Hớt bọt kỹ ngay khi nước vừa sôi giúp nước dùng súp gà trong veo và không bị mùi hôi.', 12),
('vn-sang-06_v4_step_2', 'vn-sang-06', 2, 'prep', 'Chuẩn bị ngô ngọt, bột năng và trứng đánh tan', 'Rửa sạch 200 g hạt ngô ngọt tươi để ráo. Hòa tan hoàn toàn 25 g bột năng với 60 ml nước lọc nguội trong chén nhỏ cho không còn vón cục. Đập 2 quả trứng gà vào chén, đánh tan nhẹ bằng đũa; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('vn-sang-06_v4_step_3', 'vn-sang-06', 3, 'cook', 'Phi thơm hành tím, xào sơ gà xé và nấm hương', 'Làm nóng 10 ml dầu ăn trong nồi sạch trên lửa vừa, cho 20 g hành tím băm nhỏ vào phi thơm. Trút thịt ức gà xé sợi và nấm hương thái sợi vào đảo đều khoảng 3 phút cho thơm săn rồi đổ toàn bộ nước luộc gà và hạt ngô ngọt vào nồi, đun sôi trở lại trong 4 phút để hạt ngô chín mềm ngọt.', 'Xào nhanh thịt gà xé cùng nấm hương và hành tím trước khi chan nước dùng giúp tô súp thơm đậm đà hơn nhiều.', 4),
('vn-sang-06_v4_step_4', 'vn-sang-06', 4, 'cook', 'Nêm gia vị và tạo độ sánh mượt cho súp', 'Nêm 4 g muối ăn còn lại và 6 g hạt nêm vào nồi nước dùng đang sôi nhẹ, nếm lại cho vừa vị ngọt thanh. Khuấy lại chén nước bột năng cho đều rồi rót từ từ từng dòng nhỏ vào nồi, vừa rót vừa khuấy đều tay một chiều trên lửa nhỏ khoảng 2 phút đến khi súp sánh mượt trong veo.', 'Rót bột năng thật chậm và khuấy đều tay liên tục giúp súp sánh mịn đồng nhất, không bị vón cục.', 2),
('vn-sang-06_v4_step_5', 'vn-sang-06', 5, 'cook', 'Rót trứng tạo vân hoa mềm mượt', 'Giữ nồi súp sôi lăn tăn trên lửa nhỏ, rót từ từ chén trứng gà đã đánh tan qua rây (hoặc rưới dòng nhỏ cao tay) đồng thời dùng đũa khuấy nhẹ nhàng theo chiều kim đồng hồ để tạo thành các vân hoa trứng mỏng tơi đẹp mắt. Nấu thêm 1 phút cho trứng chín hẳn rồi tắt bếp.', NULL, NULL),
('vn-sang-06_v4_step_6', 'vn-sang-06', 6, 'finish', 'Múc súp ra bát, thêm dầu mè và rau thơm', 'Múc súp gà nóng hổi ra 4 bát, nhỏ đều 5 ml dầu mè thơm lên bề mặt, rắc hành lá thái nhỏ, ngò rí và 2 g tiêu trắng xay. Thưởng thức ngay khi súp còn nóng sánh.', NULL, NULL),
('vn-lau-01_v4_step_1', 'vn-lau-01', 1, 'prep', 'Chần sườn sụn và ninh nước dùng ngọt trong', 'Chặt 400 g sườn sụn heo thành miếng 3 cm, chà nhẹ với 2 g muối ăn rồi chần nước sôi 3 phút, vớt ra xả sạch. Cho sườn sụn vào nồi cùng 1300 ml nước lọc và 3 g muối ăn, đun sôi rồi hạ lửa nhỏ ninh 25 phút và hớt sạch bọt để sườn mềm sần sật, nước dùng trong ngọt.', 'Ninh sườn sụn ở lửa nhỏ vừa phải sẽ giữ được phần sụn giòn sần sật mà không bị mềm bở quá mức.', 25),
('vn-lau-01_v4_step_2', 'vn-lau-01', 2, 'prep', 'Lọc cua đồng lấy nước cốt và khêu gạch cua', 'Rửa sạch 500 g cua đồng tươi, tách mai khêu riêng phần gạch cua vàng vào chén nhỏ. Giã hoặc xay nhuyễn phần thân cua với 1 g muối ăn rồi hòa cùng 1500 ml nước lọc, bóp kỹ và lọc qua rây 2–3 lần bỏ bã xác cua để thu phần nước thịt cua mịn.', NULL, 10),
('vn-lau-01_v4_step_3', 'vn-lau-01', 3, 'prep', 'Rán vàng đậu phụ và sơ chế rau nhúng lẩu', 'Cắt 4 bìa đậu phụ thành miếng vuông 2,5 cm, làm nóng chảo với 30 ml dầu ăn trên lửa vừa và chiên vàng giòn đều các mặt rồi vớt ra đĩa có giấy thấm dầu. Bổ múi cau 4 quả cà chua; băm nhỏ hành tím; rửa sạch rau muống chẻ, hoa chuối bào, tía tô, kinh giới, hành lá và bày bắp bò, váng đậu, chả cá, bún tươi ra khay.', NULL, 8),
('vn-lau-01_v4_step_4', 'vn-lau-01', 4, 'cook', 'Nấu đóng tảng riêu cua vàng xốp', 'Đặt nồi nước lọc cua đồng lên bếp ở lửa vừa, khuấy nhẹ đều tay theo một chiều trong 2 phút đầu để thịt cua không dính đáy nồi, sau đó dừng khuấy. Khi mảng riêu cua kết tủa nổi dày lên mặt, hạ lửa nhỏ đun liu riu thêm 2–3 phút cho riêu chín định hình rồi dùng vá lỗ nhẹ nhàng vớt riêng tảng riêu cua ra tô.', 'Tuyệt đối không khuấy khi nước cua bắt đầu nóng và không để sôi trào mạnh để mảng riêu cua đóng thành tảng lớn, xốp mịn không bị vỡ nát.', 8),
('vn-lau-01_v4_step_5', 'vn-lau-01', 5, 'cook', 'Chưng gạch cua với dầu điều và xào cà chua', 'Làm nóng chảo với 20 ml dầu màu điều trên lửa vừa, phi thơm hành tím băm rồi cho gạch cua vào đảo nhanh 1 phút cho dậy mùi thơm béo (múc bớt phần hành phi vàng để riêng rắc mặt). Trút cà chua bổ múi cau vào xào 3 phút đến khi cà chua hơi mềm và tiết sắc đỏ cam đẹp mắt.', NULL, 3),
('vn-lau-01_v4_step_6', 'vn-lau-01', 6, 'cook', 'Pha nước lẩu riêu chua thanh với giấm bỗng', 'Trút phần nước sườn sụn đã ninh (cả sườn) vào nồi nước lọc cua, thêm hỗn hợp cà chua gạch cua vừa xào. Hòa tan 10 g mắm tôm Bắc với ít nước dùng rồi lọc bỏ cặn đổ vào nồi, nêm 100 ml giấm bỗng, 25 ml nước mắm ngon, 10 g hạt nêm, 2 g muối ăn còn lại và 10 ml sa tế ớt cho dậy vị chua thanh nồng nàn.', 'Cho giấm bỗng vào sau cùng khi nước lẩu sắp dọn để giữ trọn hương thơm nồng dịu đặc trưng mà không bị bay hơi hết.', NULL),
('vn-lau-01_v4_step_7', 'vn-lau-01', 7, 'finish', 'Bày nồi lẩu lên bếp từ và thưởng thức nóng', 'Chuyển nồi nước dùng sang nồi lẩu điện hoặc bếp từ đặt giữa bàn, xếp đậu phụ rán vàng, tảng riêu cua đồng, hành lá cắt khúc và hành phi lên trên rồi đun sôi đều 3–5 phút để riêu cua chín kỹ hoàn toàn. Khi nước sôi lăn tăn, thực khách nhúng bắp bò hoa thái mỏng khoảng 15–20 giây cho vừa chín mềm, nhúng kèm váng đậu, chả cá, rau muống chẻ, hoa chuối và thưởng thức cùng bún tươi, tía tô, kinh giới.', NULL, NULL),
('vn-lau-02_v4_step_1', 'vn-lau-02', 1, 'prep', 'Làm sạch và ướp thịt gà ta đậm vị', 'Chà xát 1200 g thịt gà ta với 4 g muối ăn trong 2 phút để hết mùi hôi, rửa sạch để ráo rồi chặt miếng vừa ăn 3,5–4 cm. Ướp gà với 15 ml nước mắm, 5 g hạt nêm, 2 g tiêu đen xay, một nửa lượng tỏi băm, một nửa sả băm và 1 quả ớt hiểm băm trong 20 phút cho thịt săn thấm vị.', 'Ướp gà đủ 20 phút trước khi xào giúp phần thịt bám chặt gia vị, khi hầm không bị nhạt lõi bên trong.', 20),
('vn-lau-02_v4_step_2', 'vn-lau-02', 2, 'prep', 'Sơ chế lá giang, sả và các loại rau nhúng lẩu', 'Nhặt lấy phần lá non của 200 g lá giang tươi, rửa sạch để ráo rồi dùng tay vò nhẹ cho lá hơi dập để dễ tiết vị chua. Đập dập 2 cây sả cắt khúc 5 cm, bổ múi cau 2 quả cà chua; rửa sạch rau muống chẻ, hoa chuối bào, ngò gai, rau ngổ cắt khúc 2 cm và bày bún gạo tươi ra đĩa.', 'Chỉ nên vò lá giang vừa dập trước khi thả vào nồi; vò quá nát và nấu quá lâu trong nồi inox/nhôm dễ làm nước có vị chát nhẹ.', NULL),
('vn-lau-02_v4_step_3', 'vn-lau-02', 3, 'cook', 'Phi hành thơm và xào săn thịt gà ta', 'Làm nóng nồi đáy dày trên lửa vừa với 20 ml dầu ăn, cho hành tím thái lát vào phi vàng giòn rồi vớt một nửa ra chén để rắc mặt sau cùng. Cho tỏi băm, sả băm còn lại và sả cây đập dập vào phi thơm 30 giây, trút thịt gà đã ướp vào đảo săn 5 phút đến khi da gà căng bóng và thịt hơi chuyển vàng.', NULL, 5),
('vn-lau-02_v4_step_4', 'vn-lau-02', 4, 'cook', 'Hầm gà lấy nước dùng ngọt thanh', 'Đổ 2000 ml nước lọc vào nồi gà, bật lửa lớn đun sôi bùng rồi hớt sạch bọt nổi. Hạ xuống lửa vừa nhỏ, thả cà chua bổ múi cau và 1 quả ớt hiểm đập dập vào hầm thêm 18 phút đến khi thịt gà chín mềm hoàn toàn, không còn sắc đỏ bên trong xương và nước dùng ngọt thanh.', NULL, 18),
('vn-lau-02_v4_step_5', 'vn-lau-02', 5, 'cook', 'Thả lá giang tạo vị chua thanh và nêm gia vị', 'Nâng lửa vừa, thả toàn bộ lá giang đã vò dập vào nồi nấu khoảng 3 phút cho lá tiết vị chua thanh tự nhiên vào nước dùng. Nêm tiếp 25 ml nước mắm ngon, 7 g hạt nêm, 4 g muối ăn, 10 g đường cát trắng và 10 ml sa tế ớt sao cho cân bằng hài hòa vị chua cay mặn ngọt.', 'Nêm đường sau khi lá giang đã tiết hết vị chua sẽ giúp bạn dễ căn chỉnh độ chua ngọt tròn vị chuẩn Nam Bộ nhất.', 3),
('vn-lau-02_v4_step_6', 'vn-lau-02', 6, 'finish', 'Dọn nồi lẩu lên bếp bàn và nhúng rau tươi', 'Chuyển nồi lẩu sang bếp từ hoặc bếp ga mini đặt giữa bàn, rắc ngò gai, rau ngổ, hành phi vàng và 1 quả ớt hiểm thái lát lên mặt. Khi nước sôi lăn tăn, thực khách nhúng rau muống chẻ và hoa chuối bào ăn kèm bún gạo tươi nóng hổi.', NULL, NULL),
('vn-lau-03_v4_step_1', 'vn-lau-03', 1, 'prep', 'Sơ chế sạch tôm sú, mực ống và cá phi lê', 'Cắt râu và rút chỉ đen lưng 450 g tôm sú tươi rồi rửa sạch. Làm sạch 400 g mực ống tươi, lột bỏ túi mực và da ngoài nếu thích, khía vảy rồng nhẹ bên trong rồi thái khoanh hoặc miếng vừa ăn. Thái lát xéo dày 1 cm 300 g phi lê cá tươi, xếp tất cả hải sản lên đĩa lớn bọc màng thực phẩm giữ mát.', 'Giữ hải sản trong ngăn mát hoặc đặt trên lớp đá lạnh trước khi dọn bàn giúp thịt tôm, mực luôn tươi giòn và không bị tanh.', NULL),
('vn-lau-03_v4_step_2', 'vn-lau-03', 2, 'prep', 'Lọc me chín và sơ chế nấm, rau nhúng lẩu', 'Ngâm 60 g cơm me chín với 120 ml nước nóng, dằm nhuyễn rồi lọc qua rây bỏ hạt. Cắt gốc và rửa sạch nấm kim châm, nấm đùi gà thái lát xéo; rửa sạch rau muống và cải thảo cắt khúc 5 cm; băm nhỏ hành tím, tỏi khô, 1 cây sả; đập dập 3 cây sả còn lại, thái lát riềng, vò nhẹ lá chanh, bổ múi cau cà chua và thái lát dứa.', NULL, NULL),
('vn-lau-03_v4_step_3', 'vn-lau-03', 3, 'cook', 'Phi thơm sả riềng và xào sốt nền cà chua dứa', 'Làm nóng nồi trên lửa vừa với 25 ml dầu ăn, cho hành tím, tỏi, sả băm, sả cây đập dập và riềng thái lát vào phi thơm khoảng 2 phút. Thêm phần cà chua băm và dứa thái lát vào xào đều 3 phút đến khi cà chua mềm nhuyễn ra màu, tiếp tục đảo cùng 20 ml tương ớt và 20 ml tương cà cho dậy hương.', 'Xào tương ớt và tương cà trực tiếp trong dầu nóng cùng cà chua giúp màu nước lẩu đỏ cam óng đẹp mà không bị tách dầu.', 5),
('vn-lau-03_v4_step_4', 'vn-lau-03', 4, 'cook', 'Nấu sôi nước dùng chua cay thơm lá chanh', 'Đổ 1680 ml nước lọc vào nồi, bật lửa lớn đun sôi bùng rồi hớt bọt. Hạ lửa vừa nấu 6 phút cho sả, riềng và dứa tiết hết vị ngọt thơm, sau đó rót nước cốt me đã lọc vào cùng cà chua bổ múi cau, 1 quả ớt đập dập, 25 ml nước mắm ngon, 20 g đường cát trắng và 6 g muối ăn cho đạt vị chua cay mặn ngọt hài hòa.', NULL, 6),
('vn-lau-03_v4_step_5', 'vn-lau-03', 5, 'cook', 'Thả lá chanh và chuyển nước lẩu ra bàn tiệc', 'Thả lá chanh đã vò nhẹ vào nồi lẩu đun thêm 1 phút cho tinh dầu lan tỏa rồi tắt bếp chuyển sang nồi lẩu điện đặt giữa bàn, giữ sôi lăn tăn ở mức lửa vừa.', 'Chỉ thả lá chanh vào cuối bước nấu nước dùng để hương thơm thanh mát không bị đắng do đun lâu.', NULL),
('vn-lau-03_v4_step_6', 'vn-lau-03', 6, 'finish', 'Nhúng chín hải sản, nấm và rau xanh ăn kèm bún', 'Khi nước lẩu sôi sùng sục, cho nấm đùi gà vào trước 2 phút rồi lần lượt nhúng phi lê cá, tôm sú (khoảng 3 phút đến khi chuyển màu đỏ cam chín đều), mực ống (1–2 phút cho giòn sần sật), nấm kim châm, rau muống và cải thảo. Gắp ăn nóng kèm bún tươi và 2 quả ớt thái lát chấm nước mắm.', NULL, NULL),
('vn-lau-04_v4_step_1', 'vn-lau-04', 1, 'prep', 'Chần xương ống và sơ chế, ướp thịt gà ta', 'Rửa sạch 400 g xương ống heo rồi chần nước sôi 3 phút, xả sạch bọt bẩn. Chà xát 1200 g thịt gà ta với 4 g muối hạt, rửa sạch chặt miếng vừa ăn rồi ướp với 10 ml nước mắm, 5 g hạt nêm, 1,5 g tiêu đen xay và một nửa lượng tỏi băm trong 15 phút.', NULL, 15),
('vn-lau-04_v4_step_2', 'vn-lau-04', 2, 'prep', 'Sơ chế các loại nấm tươi, rau củ và thảo mộc', 'Cắt bỏ phần gốc bám đất của nấm đùi gà, nấm bào ngư, nấm kim châm, nấm hương tươi và nấm rơm; rửa nhẹ tay qua nước sạch rồi để ráo, thái lát nấm đùi gà và xếp thập cẩm nấm ra khay lớn. Cắt khoanh bắp ngọt, củ cải trắng, cà rốt; rửa sạch táo đỏ, kỷ tử, cải thảo, rau cải cúc và cắt khối 2,5 cm đậu phụ non.', 'Không bóp hay ngâm nấm quá lâu trong nước để các loại nấm giữ được độ giòn ngọt và hương thơm tự nhiên khi nhúng lẩu.', NULL),
('vn-lau-04_v4_step_3', 'vn-lau-04', 3, 'cook', 'Ninh xương ống cùng bắp ngọt và củ cải trắng', 'Cho xương ống heo đã chần vào nồi lớn cùng 3000 ml nước lọc, bắp ngọt cắt khoanh, củ cải trắng và 3 g muối hạt. Đun sôi bùng rồi hạ lửa nhỏ liu riu, đậy hé vung ninh khoảng 25 phút và thường xuyên hớt bọt để thu nước dùng trong vắt, ngọt thanh.', 'Ninh xương cùng củ cải trắng và bắp ngọt giúp nước lẩu ngọt tự nhiên sâu vị mà không cần dùng nhiều đường hay bột ngọt.', 25),
('vn-lau-04_v4_step_4', 'vn-lau-04', 4, 'cook', 'Phi thơm hành tỏi và xào săn thịt gà', 'Trong chảo hoặc nồi khác, làm nóng 15 ml dầu ăn trên lửa vừa, phi thơm 25 g hành tím băm và tỏi băm còn lại khoảng 30 giây. Cho gà ta đã ướp vào đảo săn 4 phút đến khi thịt săn chắc và lớp da hơi vàng thơm.', NULL, 4),
('vn-lau-04_v4_step_5', 'vn-lau-04', 5, 'cook', 'Nấu gà với nấm hương, cà rốt, táo đỏ và kỷ tử', 'Vớt bỏ xương ống từ nồi nước ninh hoặc giữ lại tùy thích, trút thịt gà đã xào săn vào nồi nước dùng cùng cà rốt, nấm hương tươi và táo đỏ kỷ tử. Ninh lửa vừa 15 phút cho gà chín mềm hoàn toàn và thấm vị thảo mộc, sau đó nêm 10 ml nước mắm ngon, 7 g hạt nêm và 3 g muối hạt còn lại sao cho vừa thanh dịu.', 'Cho một phần nấm hương tươi vào hầm cùng nước dùng sẽ giúp hương thơm nấm quyện sâu vào nước lẩu ngay từ đầu.', 15),
('vn-lau-04_v4_step_6', 'vn-lau-04', 6, 'finish', 'Bày nồi lẩu nấm và nhúng ăn nóng với mì trứng', 'Chuyển nồi lẩu ra bếp giữa bàn, nhẹ nhàng thả đậu phụ non vào đun sôi lăn tăn. Lần lượt nhúng nấm đùi gà, nấm bào ngư, nấm rơm, nấm kim châm khoảng 2–3 phút cho chín giòn ngọt, nhúng thêm cải thảo, rau cải cúc và ăn kèm mì trứng vắt đã trụng chín ráo.', NULL, NULL),
('vn-lau-05_v4_step_1', 'vn-lau-05', 1, 'prep', 'Ninh xương ống heo với hành tây và cà rốt', 'Chặt nhỏ 500 g xương ống heo, chà nhẹ với 2 g muối hạt rồi chần nước sôi 3 phút, rửa sạch bọt bẩn. Cho xương vào nồi cùng 2200 ml nước lọc, 1 củ hành tây bổ tư, 1 củ cà rốt thái khoanh và 5 g muối hạt, đun sôi rồi hạ lửa nhỏ liu riu ninh 25 phút và thường xuyên hớt bọt để nước dùng thật trong ngọt.', NULL, 25),
('vn-lau-05_v4_step_2', 'vn-lau-05', 2, 'prep', 'Quết dẻo dai chả cá thác lác với đầu hành thì là', 'Cho 450 g thịt cá thác lác nạo lạnh vào tô lớn cùng 15 ml nước mắm ngon, 4 g hạt nêm, 2 g tiêu trắng xay, đầu hành lá băm nhuyễn, một nửa hành tím băm, một nửa thì là thái nhỏ và 5 ml dầu ăn. Dùng muỗng chắc tay miết và quết liên tục theo một chiều khoảng 10 phút đến khi khối cá dẻo quánh, bám dính chặt vào tô.', 'Giữ thịt cá thác lác thật lạnh trong lúc quết và thoa chút dầu ăn vào muỗng sẽ giúp chả cá dai giòn tự nhiên, không bị bở hay dính tay.', 10),
('vn-lau-05_v4_step_3', 'vn-lau-05', 3, 'prep', 'Bào mỏng khổ qua và ngâm đá lạnh cho giòn mát', 'Bổ đôi 3 quả khổ qua tươi, dùng muỗng nạo thật sạch phần ruột và màng trắng bên trong để giảm vị đắng. Thái hoặc bào khổ qua thành lát thật mỏng, ngâm ngập vào thau nước đá lạnh pha 1 g muối hạt trong 10 phút cho khổ qua giòn rụm, sau đó vớt ráo xếp lên đĩa đá. Rửa sạch nấm kim châm, nấm rơm, rau cải cúc, rau muống và bày bún gạo tươi ra đĩa.', 'Nạo sạch phần màng trắng trong ruột khổ qua và ngâm nước đá lạnh giúp khổ qua giữ màu xanh ngọc, giòn sần sật và bớt đắng rõ rệt.', 10);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-lau-05_v4_step_4', 'vn-lau-05', 4, 'cook', 'Phi thơm hành tím và nêm nước lẩu thanh dịu', 'Làm nóng chảo nhỏ với 10 ml dầu ăn còn lại, phi thơm phần hành tím thái lát còn lại rồi trút vào nồi nước dùng xương đã ninh (có thể vớt bỏ xác hành tây và xương ống cho gọn nồi lẩu). Nêm 15 ml nước mắm ngon, 4 g hạt nêm và 12 g đường phèn khuấy tan, nếm lại vị ngọt thanh dịu.', NULL, NULL),
('vn-lau-05_v4_step_5', 'vn-lau-05', 5, 'cook', 'Múc viên chả cá thác lác thả chín trong nồi lẩu', 'Đặt nồi nước dùng lên bếp lẩu giữa bàn ở lửa vừa cho sôi lăn tăn. Thoa chút dầu lên 2 chiếc muỗng, khéo léo vo thành từng viên chả cá thác lác tròn dẹt rồi thả trực tiếp vào nồi nước dùng đang sôi cùng nấm rơm, nấu khoảng 4 phút đến khi từng viên cá nổi lên mặt nước, căng phồng và chín chắc hoàn toàn.', 'Duy trì nước lẩu sôi lăn tăn vừa phải khi thả viên cá thác lác để chả chín từ từ, nở phồng đẹp mắt và không bị rã bở.', 4),
('vn-lau-05_v4_step_6', 'vn-lau-05', 6, 'finish', 'Nhúng khổ qua, rau thơm và dùng nóng với bún', 'Rắc hành lá, ngò rí và phần thì là còn lại vào nồi lẩu. Khi ăn, gắp khổ qua bào mỏng nhúng nhanh vào nước lẩu sôi khoảng 15–20 giây cho vừa chín tái giòn ngọt, nhúng thêm nấm kim châm, rau cải cúc, rau muống rồi thưởng thức ngay cùng chả cá thác lác dai ngọt, bún gạo tươi và nước mắm ớt thái lát.', NULL, NULL),
('gl-01_v4_step_1', 'gl-01', 1, 'prep', 'Sơ chế tỏi, cà chua và húng quế', 'Bóc vỏ 2 tép tỏi tươi, chẻ đôi lấy bỏ phần lõi xanh ở giữa cho đỡ hăng rồi thái lát mỏng. Trút 400 g cà chua lột vỏ nghiền hộp Ý ra tô, dùng nĩa dằm sơ cho nát vừa còn chút thịt quả. Rửa sạch 8 g lá húng quế Tây tươi, thấm khô nước.', 'Tách bỏ lõi xanh giữa tép tỏi giúp dầu tỏi thơm ngọt mà không bị hăng gắt khi phi.', NULL),
('gl-01_v4_step_2', 'gl-01', 2, 'sauce', 'Phi tỏi với dầu ô liu trên lửa nhỏ', 'Bắc chảo sâu lòng lên bếp ở lửa nhỏ, cho 30 ml dầu ô liu nguyên chất vào làm ấm nhẹ. Thả tỏi lát vào phi đều tay khoảng 2 phút đến khi tỏi dậy mùi thơm và vừa ngả màu vàng nhạt thì hạ lửa thật nhỏ.', 'Không để dầu quá nóng hay tỏi chuyển nâu vì tỏi cháy sẽ làm sốt cà chua bị đắng.', 2),
('gl-01_v4_step_3', 'gl-01', 3, 'sauce', 'Ninh sốt cà chua Pomodoro sánh mịn', 'Trút toàn bộ cà chua nghiền vào chảo dầu tỏi, đảo đều và nêm 2 g muối hạt cùng 1 g tiêu đen xay. Đun sôi nhẹ rồi hạ lửa nhỏ, ninh liu riu khoảng 15 phút cho sốt sánh đặc lại và bay bớt vị chua gắt. Thả 4 lá húng quế Tây vào đảo nhẹ rồi ninh thêm 3 phút.', NULL, 18),
('gl-01_v4_step_4', 'gl-01', 4, 'cook', 'Luộc mì Ý đạt độ dai al dente', 'Đun sôi mạnh nồi lớn với 2 lít nước lọc, cho 10 g muối hạt vào khuấy tan rồi thả 200 g mì Ý Spaghetti khô vào. Luộc ở lửa lớn trong khoảng 8 phút (ít hơn 1 phút so với hướng dẫn trên bao bì) để sợi mì chín dẻo bên ngoài, còn hơi chắc lõi ở giữa.', 'Nước luộc mì cần đủ nhiều và có vị mặn nhẹ để sợi mì ngấm vị từ bên trong và không bị dính.', 8),
('gl-01_v4_step_5', 'gl-01', 5, 'cook', 'Nhũ tương hóa sốt với nước luộc mì', 'Trước khi vớt mì, múc giữ lại khoảng 120 ml nước luộc mì đục tinh bột. Gắp mì Ý cho thẳng vào chảo sốt cà chua, rưới thêm 2–3 muỗng canh nước luộc mì rồi bật lửa vừa, đảo và xóc đều tay 2 phút đến khi lớp sốt đỏ óng bám đều quanh từng sợi mì.', NULL, 2),
('gl-01_v4_step_6', 'gl-01', 6, 'finish', 'Hoàn thiện và rắc phô mai Parmesan', 'Tắt bếp, nếm lại độ mặn ngọt vừa miệng rồi chia mì ra 2 đĩa sâu lòng. Rắc 20 g phô mai Parmesan bào mịn nếu thích cùng phần lá húng quế Tây tươi còn lại lên trên và thưởng thức ngay khi còn nóng.', NULL, NULL),
('gl-02_v4_step_1', 'gl-02', 1, 'prep', 'Rang giã hoa tiêu và sơ chế hương liệu', 'Làm nóng chảo khô trên lửa nhỏ, cho 3 g hoa tiêu Tứ Xuyên vào rang khoảng 2 phút đến khi dậy mùi thơm đặc trưng rồi giã mịn thành bột, giữ lại 1/4 lượng bột hoa tiêu để rắc mặt sau cùng. Tỏi khô và gừng tươi băm thật nhuyễn; hành lá tách đầu hành trắng băm nhỏ và lá xanh thái khúc; băm nhuyễn tương ớt đậu bản Doubanjiang và đậu tương đen lên men Douchi; hòa tan 8 g bột bắp với 45 ml nước lọc.', 'Chỉ rang hoa tiêu trên lửa nhỏ và nhặt bỏ hạt đen bên trong trước khi giã sẽ tránh được vị đắng khét.', 2),
('gl-02_v4_step_2', 'gl-02', 2, 'prep', 'Cắt đậu phụ non và chần nước muối ấm', 'Nhẹ tay cắt 450 g đậu phụ non thành từng khối vuông cạnh 2 cm. Đun nóng 800 ml nước lọc cùng 2 g muối ăn đến khi vừa sôi lăn tăn, thả nhẹ đậu phụ vào chần 2 phút rồi dùng vợt lỗ vớt ra rổ thưa cho ráo nước, tránh làm vỡ nát miếng đậu.', 'Chần đậu phụ với nước muối loãng giúp khử mùi đậu sống và làm bề mặt miếng đậu săn chắc, ít vỡ khi om sốt.', 2),
('gl-02_v4_step_3', 'gl-02', 3, 'cook', 'Xào săn thịt heo xay', 'Ướp nhẹ 150 g thịt heo xay với 1 g muối ăn. Đặt chảo sâu lòng lên lửa vừa lớn, làm nóng 25 ml dầu ăn thực vật rồi cho thịt heo xay vào đảo tơi liên tục khoảng 3 phút đến khi thịt săn chắc, ráo nước và hơi xém vàng cạnh. Trút thịt ra chén riêng, giữ lại dầu thơm trong chảo.', NULL, 3),
('gl-02_v4_step_4', 'gl-02', 4, 'cook', 'Phi tương ớt đậu bản tạo dầu đỏ', 'Hạ lửa nhỏ, thêm 15 ml dầu ăn thực vật còn lại vào chảo, cho tương ớt đậu bản Doubanjiang đã băm nhuyễn vào đảo đều tay khoảng 1 phút cho đến khi dầu chuyển màu đỏ cam óng đẹp. Tiếp tục cho đậu tương đen lên men Douchi, 4 g ớt bột khô Tứ Xuyên, tỏi băm, gừng băm và đầu hành trắng vào xào thơm thêm 30 giây.', 'Xào tương ớt đậu bản ở lửa nhỏ giúp dầu tiết màu đỏ tự nhiên và dậy mùi thơm đậm mà không làm cháy tỏi gừng.', 2),
('gl-02_v4_step_5', 'gl-02', 5, 'cook', 'Nấu nước sốt và om thấm đậu phụ', 'Cho 3/4 phần bột hoa tiêu Tứ Xuyên vào đảo nhanh 15 giây, lập tức đổ 200 ml nước dùng gà, 15 ml xì dầu nhạt, 3 g đường cát trắng cùng một nửa lượng thịt heo xay vào nồi. Đun sôi nhẹ rồi hạ lửa nhỏ om 2 phút, sau đó thả nhẹ nhàng toàn bộ đậu phụ non vào, nghiêng lắc chảo hoặc dùng lưng muôi đẩy nhẹ, om liu riu 6 phút để đậu ngấm sâu gia vị.', 'Tuyệt đối không dùng đũa đảo mạnh tay; chỉ cần đẩy nhẹ bằng lưng muôi từ mép chảo vào trong để giữ nguyên khối đậu vuông đẹp.', 8),
('gl-02_v4_step_6', 'gl-02', 6, 'finish', 'Sánh sốt, rưới dầu mè và hoàn thiện', 'Khuấy đều chén nước bột bắp cho không bị lắng đáy, rót một nửa vào chảo sốt đang sôi nhẹ rồi đẩy nhẹ đậu phụ 30 giây cho sốt bắt đầu sánh, tiếp tục rót phần nước bột bắp còn lại đến khi sốt sánh bóng bám đều từng miếng đậu. Rắc nốt nửa phần thịt heo xay giòn lên trên, rưới 5 ml dầu mè thơm, tắt bếp dọn ra đĩa sâu lòng và rắc phần lá hành xanh cùng bột hoa tiêu giữ riêng lên mặt.', NULL, NULL),
('gl-03_v4_step_1', 'gl-03', 1, 'prep', 'Sơ chế cà chua và hành lá', 'Rửa sạch 4 quả cà chua chín đỏ, khoét bỏ phần cuống cứng rồi bổ thành những múi cau nhỏ đều nhau để cà chua nhanh mềm và tiết nước khi xào. Hành lá tươi rửa sạch, thái nhỏ toàn bộ để riêng.', 'Chọn cà chua chín đỏ mọng nhưng còn chắc tay sẽ cho nước sốt đậm màu đẹp và vị ngọt tự nhiên hơn.', NULL),
('gl-03_v4_step_2', 'gl-03', 2, 'prep', 'Đánh tan trứng gà với gia vị', 'Đập 4 quả trứng gà tươi vào tô, thêm 1,5 g muối ăn, 1 g tiêu trắng xay, 3 ml dầu mè thơm và 5 ml rượu Thiệu Hưng. Dùng đũa đánh đều tay khoảng 1 phút cho lòng trắng và lòng đỏ hòa quyện hơi nổi bọt nhẹ.', 'Nêm rượu Thiệu Hưng và dầu mè ngay vào tô trứng giúp trứng dậy mùi thơm, khử tanh và chiên lên xốp mềm hơn.', 1),
('gl-03_v4_step_3', 'gl-03', 3, 'cook', 'Chiên xốp trứng gà trên chảo nóng', 'Làm nóng chảo sâu lòng trên lửa vừa lớn đến khi bề mặt hơi bốc khói nhẹ, rót 25 ml dầu ăn thực vật tráng đều lòng chảo. Đổ hỗn hợp trứng gà vào, dùng sạn gỗ đẩy nhẹ từ ngoài vào trong tạo thành từng mảng trứng mềm xốp. Khi trứng vừa đông khoảng 85–90% nhưng bề mặt vẫn còn hơi ẩm bóng thì lập tức xúc ra đĩa riêng.', 'Không chiên trứng quá khô vì trứng sẽ còn được đảo tiếp trong sốt cà chua ở bước sau.', 2),
('gl-03_v4_step_4', 'gl-03', 4, 'cook', 'Xào cà chua với hành lá', 'Thêm 10 ml dầu ăn thực vật còn lại vào chảo, bật lửa lớn, cho toàn bộ cà chua múi cau và một nửa lượng hành lá thái nhỏ vào đảo nhanh tay trong 1 phút cho cà chua bắt đầu xém cạnh và thơm nhẹ.', NULL, 1),
('gl-03_v4_step_5', 'gl-03', 5, 'cook', 'Om mềm cà chua tạo sốt chua ngọt', 'Thêm 8 g đường cát trắng, 2,5 g muối ăn còn lại cùng 60 ml nước lọc vào chảo cà chua, đảo nhẹ rồi cho phần trứng gà đã chiên trở lại chảo. Đậy nắp vung, hạ lửa vừa và om khoảng 2 phút cho cà chua mềm nhừ, tiết nước sốt đỏ sánh quyện vào trứng.', 'Đậy nắp giúp cà chua chín mềm ra nước nhanh mà không cần dùng nhiều dầu ăn.', 2),
('gl-03_v4_step_6', 'gl-03', 6, 'finish', 'Hoàn thiện và trình bày nóng', 'Mở nắp, dùng sạn đảo nhẹ 20–30 giây cho sốt cà chua áo đều từng miếng trứng vàng mềm, nêm lại muối và đường nếu cần rồi rắc nốt phần hành lá thái nhỏ còn lại lên trên. Tắt bếp, trút ra đĩa sâu lòng và dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('gl-04_v4_step_1', 'gl-04', 1, 'prep', 'Sơ chế và ướp thịt đùi gà với rượu Sake', 'Làm sạch 280 g thịt đùi gà lọc xương, thấm khô bằng khăn giấy rồi cắt miếng vuông cạnh 2 cm theo góc dao nghiêng để miếng thịt dày đều. Cho thịt gà vào bát, rưới 15 ml rượu Sake nấu ăn lên trộn đều và ướp trong 5 phút cho thịt mềm và hết mùi tanh.', 'Cắt thịt gà theo góc dao nghiêng giúp tăng diện tích tiếp xúc với nước sốt, thịt chín nhanh và thấm đều hơn mà không bị khô.', 5),
('gl-04_v4_step_2', 'gl-04', 2, 'sauce', 'Thái rau củ và pha hỗn hợp nước sốt om', 'Thái dọc 1/2 củ hành tây thành múi mỏng 5 mm và cắt nhỏ 1/2 bó hành lá. Trong bát nhỏ, khuấy tan 120 ml nước dùng Dashi, 30 ml nước tương Nhật, 30 ml rượu ngọt Mirin và 8 g đường cát trắng đến khi đường hòa quyện hoàn toàn.', 'Hòa tan đường trước trong nước sốt nguội sẽ giúp nước om trong chảo đậm đều ngay từ đầu, tránh bị cháy đường ở đáy chảo.', NULL),
('gl-04_v4_step_3', 'gl-04', 3, 'cook', 'Nấu mềm hành tây trong nước sốt', 'Đổ hỗn hợp nước sốt Dashi đã pha vào chảo nông đường kính 20 cm, đặt lên bếp lửa vừa và không đậy nắp. Khi nước sốt vừa sôi lăn tăn, thả hành tây thái mỏng vào dàn đều, nấu mở nắp khoảng 3 phút cho đến khi hành tây chuyển trong và tiết vị ngọt tự nhiên.', NULL, 3),
('gl-04_v4_step_4', 'gl-04', 4, 'cook', 'Om chín hoàn toàn thịt đùi gà', 'Xếp đều từng miếng thịt đùi gà đã ướp vào chảo nước sốt đang sôi nhẹ trên lửa vừa. Nấu khoảng 4–5 phút và trở mặt gà giữa chừng cho đến khi thịt gà chuyển màu trắng đục hoàn toàn, không còn sắc hồng ở lõi và nước sốt hơi rút sánh lại.', NULL, 5),
('gl-04_v4_step_5', 'gl-04', 5, 'cook', 'Đánh nhẹ và rưới trứng thành hai lần', 'Đập 3 quả trứng gà vào bát, dùng đũa gạt cắt lòng trắng 5–6 nhịp cho tơi nhẹ, giữ lại vân trắng vàng. Rưới 2/3 phần trứng (ưu tiên lòng trắng) vào giữa chảo trên lửa vừa nhỏ, chờ 30 giây cho trứng hơi se mặt rồi rưới nốt 1/3 trứng còn lại đều khắp, đậy vung nấu thêm 1–2 phút đến khi trứng chín tới mềm mịn.', 'Không đánh trứng tan bông hoàn toàn vì sẽ làm món trứng mất đi vân cẩm thạch trắng vàng đẹp mắt và độ béo bùi đặc trưng.', 2),
('gl-04_v4_step_6', 'gl-04', 6, 'finish', 'Trình bày tô cơm Oyakodon và thưởng thức nóng', 'Xới 360 g cơm gạo Nhật nóng vào hai tô donburi, lắc nhẹ chảo rồi trượt nguyên mảng gà trứng cùng nước sốt phủ kín mặt cơm. Rắc hành lá thái nhỏ và chút bột ớt 7 vị Nhật Shichimi lên trên rồi dọn ăn ngay khi còn nóng.', NULL, NULL),
('gl-05_v4_step_1', 'gl-05', 1, 'prep', 'Sơ chế kim chi, rau củ và dằm tơi cơm nguội', 'Vắt nhẹ 160 g kim chi cải thảo ủ chua để chắt riêng khoảng 40 ml nước kim chi vào chén, phần cái thái nhỏ cỡ 1 cm. Thái hạt lựu nhỏ hành tây và cà rốt, thái nhỏ hành lá. Dùng tay hoặc thìa dằm nhẹ cho 450 g cơm trắng nguội hạt ngắn tơi đều, không vón cục.', 'Dùng cơm nguội để qua đêm trong tủ lạnh giúp hạt cơm se mặt, khi chiên sẽ săn tơi và không bị bết dính.', NULL),
('gl-05_v4_step_2', 'gl-05', 2, 'sauce', 'Pha hỗn hợp sốt Gochujang chua cay', 'Cho 20 g tương ớt Hàn Quốc (Gochujang), 15 ml nước tương và phần nước kim chi đã vắt vào chén nhỏ, khuấy đều tay cho đến khi hỗn hợp sốt hòa quyện sánh mịn.', 'Pha sẵn sốt trước giúp gia vị bám đều lên từng hạt cơm khi đảo nhanh trên chảo nóng.', NULL),
('gl-05_v4_step_3', 'gl-05', 3, 'cook', 'Xào thơm hành tây, cà rốt và kim chi', 'Làm nóng chảo sâu lòng trên lửa vừa với 5 ml dầu thực vật, cho đầu hành lá, hành tây và cà rốt vào đảo đều 2 phút đến khi hành tây hơi trong. Tiếp tục cho phần kim chi cải thảo thái nhỏ vào xào thêm 2 phút cho kim chi săn ráo và dậy mùi thơm đặc trưng.', NULL, 4),
('gl-05_v4_step_4', 'gl-05', 4, 'cook', 'Rang cơm và áo đều sốt Gochujang', 'Tăng lên lửa lớn, trút toàn bộ 450 g cơm trắng nguội vào chảo, đảo đều và ép nhẹ mặt cơm xuống đáy chảo khoảng 3 phút cho hạt cơm nóng ráo, săn chắc. Rưới đều chén sốt Gochujang vào, đảo nhanh tay thêm 2 phút để từng hạt cơm nhuộm màu đỏ cam bóng đẹp và thấm gia vị.', 'Dàn cơm mỏng trên mặt chảo vài giây trước khi đảo sẽ tạo lớp cháy xém nhẹ rất thơm.', 5),
('gl-05_v4_step_5', 'gl-05', 5, 'cook', 'Chiên trứng ốp la lòng đào', 'Trong một chảo chống dính nhỏ, đun nóng 5 ml dầu thực vật còn lại trên lửa vừa, đập nhẹ 2 quả trứng gà tươi vào chiên khoảng 3 phút đến khi lòng trắng đông chín hoàn toàn, viền hơi giòn còn lòng đỏ vẫn giữ độ sánh lòng đào.', NULL, 3),
('gl-05_v4_step_6', 'gl-05', 6, 'finish', 'Trộn dầu mè và trình bày đĩa cơm', 'Tắt bếp chảo cơm chiên, rưới 10 ml dầu mè rang, rắc phần hành lá xanh và một nửa lượng hạt mè trắng rang vào đảo đều một lượt cho thơm. Xới cơm ra 2 đĩa, đặt trứng ốp la lên trên, rắc nốt phần hạt mè trắng rang và rong biển lá khô xé nhỏ rồi thưởng thức ngay khi nóng.', NULL, NULL),
('gl-06_v4_step_1', 'gl-06', 1, 'prep', 'Giã tỏi ớt và sơ chế rau củ', 'Cho 1/2 củ tỏi khô bóc vỏ cùng 3 quả ớt hiểm vào cối, giã dập thành hỗn hợp sần sùi để tinh dầu tiết ra mạnh hơn so với băm. Thái lát xéo 1 quả ớt sừng đỏ. Tước xơ 100 g đậu que và cắt khúc ngắn 1 cm. Nhặt 25 g lá húng quế Thái, rửa nhẹ rồi vẩy thật ráo.', 'Không nên giã tỏi ớt quá nhuyễn thành bột vì khi gặp dầu nóng rất dễ cháy khét và tạo vị đắng.', NULL),
('gl-06_v4_step_2', 'gl-06', 2, 'sauce', 'Pha sẵn nước sốt xào đậm đà', 'Trộn đều trong một chén nhỏ gồm 15 ml xì dầu đen đặc Thái, 15 ml xì dầu nhạt, 10 ml nước mắm ngon, 5 g đường cát trắng và 30 ml nước lọc. Khuấy kỹ đến khi đường tan hoàn toàn để sẵn ngay cạnh bếp.', 'Các bước xào Pad Krapow diễn ra rất nhanh trên lửa lớn nên việc pha sẵn sốt giúp thịt không bị quá lửa trong lúc nêm.', NULL),
('gl-06_v4_step_3', 'gl-06', 3, 'cook', 'Phi thơm tỏi ớt và xào săn thịt heo băm', 'Đun nóng chảo sâu lòng trên lửa lớn với 20 ml dầu ăn đến khi dầu lăn tăn hơi nóng, cho hỗn hợp tỏi và ớt hiểm giã dập vào đảo nhanh khoảng 20 giây cho dậy mùi thơm nồng. Lập tức trút 300 g thịt heo xay vào chảo, dùng xẻng dằm tơi đều tay và xào liên tục khoảng 4 phút đến khi thịt săn rời, ráo nước và chín hoàn toàn không còn màu hồng.', 'Giữ lửa lớn và dằm thịt thật tơi ngay từ đầu để thịt ra hết nước thừa nhanh, áp chảo hơi xém cạnh sẽ thơm mùi khói chảo.', 4),
('gl-06_v4_step_4', 'gl-06', 4, 'cook', 'Xào đậu que và áo đều nước sốt', 'Cho 100 g đậu que cắt khúc cùng ớt sừng đỏ thái lát vào chảo thịt, đảo đều 1 phút trên lửa lớn. Khuấy lại chén nước sốt rồi rưới hết vào chảo, tiếp tục đảo nhanh tay thêm 2 phút cho nước sốt sôi bùng, keo nhẹ lại và bám bóng đều quanh từng hạt thịt heo.', NULL, 3),
('gl-06_v4_step_5', 'gl-06', 5, 'finish', 'Tắt bếp và đảo nhanh lá húng quế Thái', 'Tắt bếp ngay khi nước sốt vừa sệt, cho toàn bộ 25 g lá húng quế Thái vào chảo và đảo nhanh 10–15 giây cho lá vừa xẹp xuống, tỏa hương thơm nồng nàn nhờ nhiệt dư rồi trút ngay ra đĩa.', 'Cho lá húng quế vào sau khi đã tắt bếp giúp giữ trọn màu xanh tươi và tinh dầu thơm đặc trưng của lá quế.', NULL),
('gl-06_v4_step_6', 'gl-06', 6, 'cook', 'Chiên trứng gà ốp la viền giòn kiểu Thái', 'Dùng một chảo nhỏ làm nóng 15 ml dầu ăn còn lại trên lửa vừa lớn đến khi dầu thật nóng già, nhẹ nhàng trượt từng quả trứng gà (2 quả) vào chiên khoảng 2 phút. Nghiêng nhẹ chảo và múc dầu nóng rưới lên mặt lòng trắng để viền trứng phồng giòn vàng rụm trong khi lòng đỏ vẫn béo sánh lòng đào rồi vớt ra.', NULL, 2),
('gl-06_v4_step_7', 'gl-06', 7, 'finish', 'Trình bày cơm đĩa Pad Krapow nóng hổi', 'Ép nhẹ 300 g cơm trắng nóng vào chén rồi úp ra 2 đĩa, múc phần thịt heo băm xào lá quế sang bên cạnh và đặt mỗi đĩa 1 quả trứng ốp la giòn viền lên trên, dọn dùng ngay khi còn nóng.', NULL, NULL),
('gl-07_v4_step_1', 'gl-07', 1, 'prep', 'Trộn cơm dầu mè và ướp thịt bò', 'Xới 650 g cơm trắng dẻo hạt ngắn còn âm ấm ra tô lớn, trộn đều với 2,5 g muối ăn, 15 ml dầu mè rang và 9 g hạt mè trắng rang rồi để nguội bớt. Ở tô khác, ướp 200 g thịt bò thăn thái sợi với 30 ml nước tương, 5 g đường cát trắng, một nửa lượng tỏi khô băm nhuyễn, 5 ml dầu mè rang và 1 g tiêu đen xay trong 15 phút.', 'Nêm gia vị khi cơm còn ấm giúp muối tan đều và hạt cơm bóng thơm mà không bị nát.', 15),
('gl-07_v4_step_2', 'gl-07', 2, 'prep', 'Chần rau chân vịt và vắt thật ráo', 'Đun sôi 1 lít nước lọc trên lửa lớn, thả 200 g rau chân vịt vào chần nhanh trong 45 giây cho vừa chín xanh mướt. Vớt ngay ra thau nước lạnh cho giữ màu, sau đó vắt thật kiệt nước bằng hai tay và trộn đều với 10 ml dầu mè rang, 1 g muối ăn cùng phần tỏi khô băm nhuyễn còn lại.', 'Vắt rau thật ráo là bí quyết giúp cuộn Kimbap không bị ướt nhão và giữ được độ giòn của rong biển.', 1),
('gl-07_v4_step_3', 'gl-07', 3, 'cook', 'Tráng trứng mỏng và xào cà rốt', 'Đánh tan 3 quả trứng gà tươi với 1 g muối ăn, làm nóng chảo chống dính với 7 ml dầu thực vật trên lửa nhỏ rồi đổ trứng vào tráng thành 2–3 lớp mỏng vàng đều, để nguội và thái sợi dài. Tiếp tục dùng 6 ml dầu thực vật xào nhanh cà rốt thái sợi với 0,5 g muối ăn trên lửa vừa khoảng 2 phút đến khi vừa chín tới nhưng vẫn giữ độ giòn.', NULL, 5),
('gl-07_v4_step_4', 'gl-07', 4, 'cook', 'Xào chín thịt bò trên lửa lớn', 'Làm nóng chảo với 7 ml dầu thực vật còn lại trên lửa lớn, trút toàn bộ thịt bò thăn đã ướp vào đảo nhanh tay trong 3 phút đến khi thịt săn chín hoàn toàn và hơi xém cạnh thơm lừng, sau đó trút ra đĩa để ráo bớt nước.', NULL, 3),
('gl-07_v4_step_5', 'gl-07', 5, 'finish', 'Trải cơm, xếp nhân và cuộn chặt Kimbap', 'Đặt 1 tấm mành tre lên mặt phẳng sạch, trải 1 lá rong biển lá khô cuộn Kimbap (mặt nhám hướng lên trên). Dàn đều khoảng 130 g cơm trộn thành lớp mỏng phủ 3/4 diện tích lá, chừa mép trên khoảng 2 cm. Xếp lần lượt thịt bò xào, trứng tráng thái sợi, cà rốt, rau chân vịt và 1 thanh củ cải muối vàng thành hàng ngang gọn gàng.', 'Thấm một chút nước lên đầu ngón tay khi dàn cơm để cơm không dính tay và giữ lớp cơm mỏng đều.', NULL),
('gl-07_v4_step_6', 'gl-07', 6, 'finish', 'Cuộn tròn, phết dầu mè và cắt khoanh', 'Cuộn chặt tay từ mép dưới qua mành tre, vừa cuộn vừa nén nhẹ để nhân cố định ở giữa, thấm chút nước lên mép rong biển trống để dán kín cuộn. Lặp lại cho đủ 5 cuộn, phết 5 ml dầu mè rang còn lại lên mặt ngoài vỏ rong biển cho bóng thơm rồi dùng dao sắc lau ẩm cắt thành từng khoanh tròn dày 1,5–2 cm.', NULL, NULL),
('gl-08_v4_step_1', 'gl-08', 1, 'prep', 'Luộc trứng gà lòng đào và sơ chế nguyên liệu', 'Đun sôi nước trong nồi nhỏ, thả nhẹ 2 quả trứng gà vào luộc đúng 7 phút trên lửa vừa để đạt độ lòng đào dẻo, sau đó vớt ra ngâm ngay vào nước lạnh rồi bóc vỏ. Rửa sạch 300 g bánh gạo Hàn Quốc dạng thỏi, cắt miếng chả cá Hàn Quốc, cắt vuông bắp cải trắng và cắt khúc 4 cm hành lá tươi.', 'Nếu dùng bánh gạo bảo quản lạnh bị cứng, ngâm nước ấm 10–15 phút trước khi nấu giúp bánh chín đều mà không nát bề mặt.', 7),
('gl-08_v4_step_2', 'gl-08', 2, 'sauce', 'Pha nước sốt cay ngọt Gochujang', 'Đổ 480 ml nước dùng cá cơm tảo bẹ vào chảo sâu lòng, cho 38 g tương ớt Hàn Quốc (Gochujang), 3 g ớt bột Hàn Quốc (Gochugaru), 10 ml nước tương, 16 g đường cát trắng, 15 ml siro ngô và tỏi khô băm nhuyễn vào khuấy tan hoàn toàn trên lửa vừa.', 'Khuấy tan hoàn toàn tương ớt Gochujang trước khi thả bánh gạo để sốt mịn đều, không bị vón cục.', NULL),
('gl-08_v4_step_3', 'gl-08', 3, 'cook', 'Nấu mềm bánh gạo trong nước sốt', 'Khi nước sốt sôi lăn tăn, thả toàn bộ bánh gạo Hàn Quốc dạng thỏi vào chảo, hạ lửa vừa-nhỏ và nấu khoảng 6 phút. Khuấy nhẹ tay thường xuyên để tinh bột từ bánh gạo tiết ra làm nước sốt sánh dần và bánh không bị dính đáy chảo.', NULL, 6),
('gl-08_v4_step_4', 'gl-08', 4, 'cook', 'Thêm bắp cải và chả cá Hàn Quốc', 'Cho bắp cải trắng và chả cá Hàn Quốc thái miếng vào chảo, đảo đều nhẹ nhàng và tiếp tục đun liu riu thêm 4 phút cho bắp cải chín mềm tiết vị ngọt tự nhiên, chả cá nở phồng thấm sốt cay ngọt đỏ au.', 'Không đun quá cạn vì nước sốt Tokbokki sẽ đặc thêm nhẹ khi nguội bớt.', 4),
('gl-08_v4_step_5', 'gl-08', 5, 'cook', 'Áo sốt cho trứng gà luộc và hành lá', 'Thả trứng gà luộc đã bóc vỏ cùng hành lá tươi cắt khúc vào chảo, dùng muỗng rưới đều phần sốt sánh lên mặt trứng và nấu thêm 1–2 phút cho hành vừa chín tái dậy mùi thơm.', NULL, NULL),
('gl-08_v4_step_6', 'gl-08', 6, 'finish', 'Rưới dầu mè và dọn nóng', 'Tắt bếp, rưới 5 ml dầu mè rang lên khắp mặt chảo và đảo nhẹ một lượt. Múc Tokbokki cùng chả cá, bắp cải ra đĩa sâu lòng, cắt đôi trứng gà đặt lên trên và rắc hạt mè trắng rang trang trí rồi thưởng thức ngay.', NULL, NULL),
('gl-09_v4_step_1', 'gl-09', 1, 'prep', 'Ngâm nấm hương khô và sơ chế nấm tươi', 'Ngâm 8 g nấm hương khô trong 50 ml nước lọc ấm khoảng 15 phút cho nở mềm hoàn toàn, vắt nhẹ ráo nước rồi cắt bỏ chân nấm, thái lát mỏng. Phần 50 g nấm tươi cắt bỏ gốc, tách thành từng nhánh nhỏ vừa miệng và 30 g chả cá Nhật thái 4 lát mỏng.', NULL, 15),
('gl-09_v4_step_2', 'gl-09', 2, 'marinate', 'Sơ chế và ướp tôm cùng thịt gà với rượu Sake', 'Lột vỏ 80 g tôm tươi, rút bỏ chỉ đen sống lưng; cắt 70 g thịt đùi gà thành miếng nhỏ 1,5 cm. Cho tôm và gà vào hai bát riêng, rưới mỗi bát 10 ml rượu Sake nấu ăn (tổng 20 ml) và ướp 10 phút giúp thịt thơm và sạch mùi.', NULL, 10),
('gl-09_v4_step_3', 'gl-09', 3, 'sauce', 'Pha hỗn hợp trứng dashi và lọc qua rây mịn', 'Đập 2 quả trứng gà vào bát, dùng đũa đánh tan nhẹ nhàng sát đáy bát theo đường zíc zắc để tránh nổi bọt. Rót từ từ 220 ml nước dùng Dashi đã nguội hoàn toàn cùng 5 ml nước tương Nhật, 5 ml rượu ngọt Mirin và 1 g muối ăn vào khuấy đều, sau đó lọc hỗn hợp qua rây mịn 2 lần vào ca rót.', 'Nước dùng Dashi bắt buộc phải nguội trước khi trộn với trứng để tránh làm trứng chín vón cục ngay trong bát.', NULL),
('gl-09_v4_step_4', 'gl-09', 4, 'prep', 'Xếp nhân và rót trứng vào hai chén sứ', 'Chia đều thịt đùi gà, nấm hương thái lát và nấm tươi xuống đáy hai chén sứ có nắp. Đặt tôm tươi và lát chả cá Nhật lên lớp trên để tạo điểm nhấn màu sắc, từ từ rót hỗn hợp trứng qua thành chén đến khoảng 80% dung tích, hớt sạch bọt khí li ti trên bề mặt rồi đậy kín nắp chén hoặc bọc màng giấy bạc.', 'Hớt sạch toàn bộ bọt khí trên mặt chén trước khi hấp giúp bề mặt trứng chín bóng láng như gương.', NULL),
('gl-09_v4_step_5', 'gl-09', 5, 'cook', 'Hấp cách thủy trứng ở lửa nhỏ nhất', 'Đun sôi nồi nước cao đến khoảng nửa thân chén hấp, sau đó hạ ngay xuống mức lửa nhỏ nhất để nước chỉ lăn tăn hơi nóng ở 85–90°C. Nhẹ nhàng đặt hai chén trứng vào nồi, đậy nắp nồi hơi hé một khe nhỏ bằng chiếc đũa và hấp liu riu 22–25 phút cho đến khi trứng đông mịn hoàn toàn và tôm gà chín kỹ.', 'Tuyệt đối không để nước trong nồi sôi bùng vì nhiệt quá cao sẽ khiến trứng tách nước và bị rỗ mặt như tổ ong.', 24),
('gl-09_v4_step_6', 'gl-09', 6, 'finish', 'Kiểm tra độ chín và dọn thưởng thức nóng', 'Mở nắp chén, dùng đầu xiên tre châm nhẹ vào giữa phần trứng: nếu nước tiết ra trong veo (không đục) là trứng đã chín đều và gà tôm đạt chuẩn an toàn. Rắc hành lá thái mỏng lên mặt chén, đậy nắp lại 1 phút cho dậy hương rồi dọn dùng nóng với thìa nhỏ.', NULL, NULL),
('gl-10_v4_step_1', 'gl-10', 1, 'prep', 'Tăng hương sốt cà ri xanh và sơ chế nguyên liệu', 'Cho 45 g sốt cà ri xanh Thái, 4 g mắm tôm và 10 g lá húng quế Thái vào cối giã hoặc máy xay nhỏ, nghiền quyện thành hỗn hợp xanh mượt dậy mùi tươi mới. Cắt 400 g thịt đùi gà thành miếng vuông 3–4 cm. Cắt 170 g cà tím thành múi cau vừa ăn, thái sợi 1/2 quả ớt chuông đỏ và thái lát 2 quả ớt sừng đỏ.', 'Giã thêm lá húng quế tươi cùng mắm tôm giúp sốt cà ri đóng gói có màu xanh đẹp và hương thơm đậm như giã tay tại nhà.', NULL),
('gl-10_v4_step_2', 'gl-10', 2, 'cook', 'Đun tách dầu cốt dừa và xào thơm sốt cà ri', 'Múc 120 ml phần kem đặc phía trên của nước cốt dừa cho vào nồi đáy dày, đun trên lửa vừa và khuấy nhẹ khoảng 4 phút đến khi nước bay hơi bớt và thấy lớp dầu dừa trong óng ánh tách nổi lên mặt. Cho toàn bộ hỗn hợp sốt cà ri xanh vào đảo đều tay thêm 3–4 phút cho đến khi sốt thơm nồng và sánh bóng.', 'Kỹ thuật tách dầu trực tiếp từ nước cốt dừa giúp món cà ri Thái có độ béo ngậy tự nhiên mà không cần dùng thêm dầu ăn.', 4),
('gl-10_v4_step_3', 'gl-10', 3, 'cook', 'Xào săn đùi gà và om mềm với nước dùng', 'Cho 400 g thịt đùi gà vào nồi sốt cà ri, đảo đều khoảng 3 phút trên lửa vừa để từng miếng thịt săn lại và áo kín lớp sốt thơm. Rót 180 ml nước dùng gà vào nồi, thả 4 g lá chanh Thái xé nhỏ bỏ gân vào rồi hạ lửa nhỏ, đậy hé nắp om liu riu 12 phút đến khi thịt gà chín mềm hoàn toàn và thấm vị.', NULL, 12),
('gl-10_v4_step_4', 'gl-10', 4, 'cook', 'Nấu cà tím, ớt chuông và nêm gia vị', 'Vớt bỏ bớt lá chanh cứng nếu thích, cho 170 g cà tím và 1/2 quả ớt chuông đỏ thái sợi vào nồi nấu tiếp khoảng 5 phút đến khi cà tím vừa chín mềm mà vẫn giữ nguyên khối không nát. Nêm 20 g đường thốt nốt băm nhỏ cùng 20 ml nước mắm ngon, khuấy tan rồi nếm điều chỉnh cho vị mặn ngọt cay béo hài hòa.', NULL, 5),
('gl-10_v4_step_5', 'gl-10', 5, 'cook', 'Hòa phần nước cốt dừa còn lại', 'Rót 180 ml nước cốt dừa còn lại vào nồi, khuấy nhẹ tay và đun sôi lăn tăn trên lửa nhỏ thêm 2 phút để nước cà ri sánh mịn, hòa quyện đều màu xanh ngọc dịu mắt.', 'Không đun sôi mạnh sau khi đã cho phần cốt dừa cuối vào vì nhiệt cao sẽ làm cốt dừa bị tách béo và lợn cợn.', 2),
('gl-10_v4_step_6', 'gl-10', 6, 'finish', 'Tắt bếp thả húng quế và dọn nóng', 'Tắt bếp ngay rồi cho 15 g lá húng quế Thái còn lại vào đảo nhẹ cho lá vừa héo dậy mùi thơm. Múc cà ri xanh thịt gà ra tô sâu lòng, xếp vài lát ớt sừng đỏ lên trên và dọn nóng ngay.', NULL, NULL),
('gl-11_v4_step_1', 'gl-11', 1, 'prep', 'Thái hạt lựu thịt xông khói và rau củ nền', 'Thái hạt lựu nhỏ 75 g thịt ba chỉ xông khói Pancetta. Gọt vỏ cà rốt, nhặt rửa cần tây và bóc vỏ hành tây rồi băm thật nhỏ cả ba loại rau củ để làm nền soffritto giúp sốt ngọt tự nhiên.', NULL, NULL),
('gl-11_v4_step_2', 'gl-11', 2, 'cook', 'Xào thịt xông khói và rau củ soffritto', 'Bắc nồi đáy dày lên bếp ở lửa vừa, cho 15 ml dầu ô liu và thịt ba chỉ xông khói vào đảo 4 phút đến khi ra mỡ và hơi xém cạnh. Trút cà rốt, cần tây và hành tây vào xào chậm khoảng 8 phút đến khi rau mềm trong và thơm ngọt, không để cháy xém.', 'Xào chậm rau củ trên lửa vừa giúp giải phóng đường tự nhiên tạo độ ngọt sâu cho sốt Bolognese.', 8),
('gl-11_v4_step_3', 'gl-11', 3, 'cook', 'Xào săn thịt bò xay và khử rượu vang', 'Tăng lên lửa vừa-lớn, cho 250 g thịt bò xay vào nồi, dùng muỗng gỗ dằm tơi và đảo đều khoảng 6 phút đến khi thịt săn chắc, chín hoàn toàn hết màu hồng. Đổ 100 ml rượu vang trắng khô nấu ăn vào, đảo đều 3 phút đến khi cồn bay hơi hết.', NULL, 9),
('gl-11_v4_step_4', 'gl-11', 4, 'sauce', 'Hầm sốt cà chua cùng nước dùng bò và sữa tươi', 'Đổ 300 g sốt cà chua xay nhuyễn Passata vào nồi, nêm 4 g muối ăn và 2 g tiêu đen xay. Hạ lửa thật nhỏ, đậy vung hờ và hầm liu riu khoảng 40 phút, thỉnh thoảng khuấy đều và châm dần 250 ml nước dùng bò nếu sốt đặc. Khi còn 10 phút cuối, rót 100 ml sữa tươi nguyên kem vào khuấy đều cho sốt béo mịn.', 'Sữa tươi giúp trung hòa vị chua gắt của cà chua và làm thịt bò xay mềm mượt hơn.', 40),
('gl-11_v4_step_5', 'gl-11', 5, 'cook', 'Luộc mì Ý Spaghetti chín độ al dente', 'Khi sốt gần hầm xong, đun sôi mạnh nồi với 2,5 lít nước lọc cùng 8 g muối ăn. Thả 250 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút cho đến khi sợi mì chín dai vừa tới, giữ lại 100 ml nước luộc mì trước khi vớt.', NULL, 9),
('gl-11_v4_step_6', 'gl-11', 6, 'finish', 'Trộn mì với sốt và rắc phô mai', 'Cho mì đã vớt vào nồi sốt Bolognese cùng 2–3 muỗng canh nước luộc mì, đảo đều trên lửa vừa 1 phút cho sốt bám đều từng sợi mì. Tắt bếp, chia ra 3 đĩa sâu lòng, rắc 30 g phô mai Parmesan bào lên trên nếu thích rồi thưởng thức nóng.', 'Mì và sốt trộn nóng trực tiếp giúp tinh bột từ nước luộc kết dính sốt thịt vào sợi mì đồng đều.', NULL),
('gl-12_v4_step_1', 'gl-12', 1, 'prep', 'Sơ chế cà chua hai kiểu cắt và gia vị', 'Rửa sạch 3,5 quả cà chua chín đỏ: 2,5 quả bổ múi cau để giữ kết cấu miếng khi ăn, 1 quả thái hạt lựu nhỏ để nhanh tiết nước làm sốt sánh. Gọt vỏ 6 g gừng tươi, thái lát mỏng; hành lá tươi rửa sạch, thái nhỏ.', 'Kết hợp cà chua thái hạt lựu và cà chua bổ múi cau giúp phần sốt sánh nhanh mà vẫn giữ được miếng cà chua đẹp mắt.', NULL),
('gl-12_v4_step_2', 'gl-12', 2, 'prep', 'Đánh trứng gà với sữa tươi', 'Đập 3 quả trứng gà tươi vào tô, rót vào 20 ml sữa tươi không đường rồi dùng đũa đánh đều nhẹ tay đến khi hỗn hợp đồng nhất, mịn mượt.', 'Thêm một ít sữa tươi vào trứng là bí quyết giúp trứng sau khi xào có độ bồng mềm, béo mượt như trứng chần kiểu Hồng Kông.', NULL),
('gl-12_v4_step_3', 'gl-12', 3, 'cook', 'Chiên mềm trứng gà trên lửa vừa lớn', 'Làm nóng chảo chống dính hoặc chảo lòng sâu với 20 ml dầu ăn trung tính trên lửa vừa lớn. Đổ tô trứng đánh sữa vào, đợi mép trứng vừa se lại thì đẩy nhẹ từ rìa vào giữa tạo các lớp gợn sóng mềm. Khi trứng vừa đông khoảng 80% và vẫn còn ẩm bóng, lập tức trút ra đĩa riêng.', NULL, 2),
('gl-12_v4_step_4', 'gl-12', 4, 'cook', 'Phi gừng thơm và xào nhừ cà chua', 'Thêm 10 ml dầu ăn trung tính còn lại vào chảo, hạ lửa vừa rồi cho các lát gừng tươi vào phi thơm khoảng 1 phút. Tiếp theo, thả cà chua thái hạt lựu vào đảo 2 phút cho mềm nhuyễn ra nước, rồi cho tiếp phần cà chua bổ múi cau vào xào thêm 3 phút đến khi cà chua mềm mọng.', NULL, 5),
('gl-12_v4_step_5', 'gl-12', 5, 'sauce', 'Nêm sốt tương cà, xì dầu và dầu hào', 'Hạ lửa vừa nhỏ, nêm vào chảo cà chua 30 ml tương cà chua, 15 ml xì dầu nhạt, 8 ml dầu hào, 5 g đường cát trắng và 1 g tiêu trắng xay. Đảo đều nhẹ tay khoảng 1 phút để các gia vị tan hoàn toàn, tạo thành phần sốt đỏ cam sánh mịn.', 'Nếm thử độ đậm của sốt trước khi cho trứng vào để dễ điều chỉnh cân bằng giữa vị chua ngọt của tương cà và vị mặn dịu của xì dầu.', NULL),
('gl-12_v4_step_6', 'gl-12', 6, 'finish', 'Đảo quyện trứng với sốt và hoàn thiện', 'Trút toàn bộ trứng gà chiên mềm trở lại chảo sốt cà chua, đảo nhẹ tay 30 giây theo chuyển động hất nhẹ từ dưới lên để sốt áo đều quanh từng mảng trứng mà không làm nát trứng. Tắt bếp, rắc hành lá tươi thái nhỏ lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-199ff78d3d8c8ab3_v4_step_1', 'imp-199ff78d3d8c8ab3', 1, 'prep', 'Sơ chế tôm, giữ đầu vỏ và ướp thịt tôm', 'Rửa sạch 250 g tôm tươi, lột bỏ vỏ và tách riêng phần đầu tôm vào chén sạch để nấu nước dùng. Rạch nhẹ sống lưng rút sạch chỉ đen, rửa lại thịt tôm với nước lạnh rồi để ráo. Ướp phần thịt tôm với một nửa chỗ hành tím băm, 5 ml nước mắm, 2 g muối ăn và 1 g tiêu đen xay trong 10 phút cho thấm vị.', 'Tận dụng phần đầu và vỏ tôm rửa sạch để đun lấy nước dùng giúp nồi canh ngọt đậm tự nhiên mà không cần nhiều gia vị.', 10),
('imp-199ff78d3d8c8ab3_v4_step_2', 'imp-199ff78d3d8c8ab3', 2, 'prep', 'Cắt miếng bí đỏ và băm rau thơm gia vị', 'Gọt vỏ bí đỏ, bỏ hết ruột và hạt, rửa sạch rồi thái miếng vuông cạnh 2,5–3 cm để bí chín đều mà vẫn giữ nguyên khối. Băm nhuyễn phần hành tím còn lại và 10 g tỏi khô; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('imp-199ff78d3d8c8ab3_v4_step_3', 'imp-199ff78d3d8c8ab3', 3, 'cook', 'Nấu và lọc nước dùng ngọt từ đầu vỏ tôm', 'Cho phần đầu và vỏ tôm vào nồi cùng 1,1 lít nước lọc, đun sôi trên lửa lớn rồi hạ lửa vừa nấu thêm 5 phút cho tiết hết chất ngọt. Dùng rây lọc bỏ toàn bộ xác đầu vỏ tôm, giữ lại phần nước dùng tôm trong veo.', NULL, 5),
('imp-199ff78d3d8c8ab3_v4_step_4', 'imp-199ff78d3d8c8ab3', 4, 'cook', 'Phi thơm hành tỏi và xào săn thịt tôm', 'Làm nóng nồi nấu canh trên lửa vừa với 15 ml dầu ăn, cho phần hành tím băm còn lại và tỏi băm vào phi thơm vàng nhẹ. Trút phần thịt tôm đã ướp vào đảo nhanh tay 1–2 phút đến khi tôm vừa săn lại và chuyển màu đỏ cam thì trút tôm ra chén riêng.', 'Xào tôm vừa săn tới rồi vớt ra trước khi hầm bí giúp thịt tôm không bị nấu quá lâu dẫn đến khô bã.', 2),
('imp-199ff78d3d8c8ab3_v4_step_5', 'imp-199ff78d3d8c8ab3', 5, 'cook', 'Nấu bí đỏ chín mềm trong nước dùng tôm', 'Đổ phần nước dùng tôm đã lọc vào nồi vừa xào tôm, đun sôi trên lửa lớn rồi thả toàn bộ bí đỏ cắt miếng vào. Hạ xuống lửa vừa và nấu khoảng 8 phút đến khi dùng đầu đũa xiên qua miếng bí thấy mềm bùi mà không bị nát.', 'Không đậy nắp quá kín và giữ lửa vừa giúp bí chín bùi đều mà miếng bí vẫn giữ nguyên cạnh đẹp mắt.', 8),
('imp-199ff78d3d8c8ab3_v4_step_6', 'imp-199ff78d3d8c8ab3', 6, 'finish', 'Trút tôm vào nồi, nêm nếm và hoàn thiện', 'Nêm 8 g hạt nêm, 3 g muối còn lại và 10 ml nước mắm vào nồi canh, khuấy nhẹ cho tan đều. Thả chén thịt tôm đã xào vào đun sôi lăn tăn thêm 1 phút để tôm chín kỹ hoàn toàn và hòa vị với bí. Tắt bếp, rắc hành lá, ngò rí thái nhỏ và 1 g tiêu đen xay lên mặt rồi múc ra tô dùng nóng.', NULL, NULL),
('imp-ab36e38b07f3a57b_v4_step_1', 'imp-ab36e38b07f3a57b', 1, 'prep', 'Chần sơ sườn non và vắt nước cốt dứa', 'Rửa sạch 600 g sườn non với 2 g muối, chặt miếng 3–4 cm rồi chần trong nồi nước sôi có 2 g muối khoảng 3 phút cho ra bọt bẩn, vớt ra rửa lại nước sạch và để ráo. Gọt vỏ bỏ mắt dứa; một nửa thái miếng tam giác vừa ăn, nửa còn lại giã hoặc băm nhuyễn vắt lấy nước cốt.', 'Ướp sườn với nước cốt dứa tươi không chỉ tạo vị chua ngọt thanh mà enzyme tự nhiên trong dứa còn giúp thớ thịt mềm nhanh hơn.', 4),
('imp-ab36e38b07f3a57b_v4_step_2', 'imp-ab36e38b07f3a57b', 2, 'marinate', 'Ướp sườn non thấm gia vị và nước cốt dứa', 'Cho sườn vào tô lớn, ướp với toàn bộ nước cốt dứa, 35 ml nước mắm ngon, 10 g đường cát trắng, 2 g muối và 1 g tiêu đen xay. Trộn đều rồi ướp trong 25 phút cho sườn ngấm gia vị.', 'Không nên ướp sườn với nước cốt dứa quá 45 phút vì enzyme bromelain có thể làm bề mặt thịt bị bở quá mức.', 25),
('imp-ab36e38b07f3a57b_v4_step_3', 'imp-ab36e38b07f3a57b', 3, 'cook', 'Xào sơ dứa cho dịu vị chua', 'Làm nóng chảo với 10 ml dầu ăn trên lửa vừa, phi thơm một nửa lượng hành tím và tỏi băm. Cho phần dứa cắt miếng cùng 5 g đường cát trắng vào đảo nhanh 4 phút cho dứa bóng mượt và dịu bớt độ chua gắt, trút ra đĩa riêng.', 'Xào trước và chỉ thả dứa vào nồi ở giai đoạn cuối giúp miếng dứa giữ được độ giòn ngọt, không bị nát vụn khi kho.', 4),
('imp-ab36e38b07f3a57b_v4_step_4', 'imp-ab36e38b07f3a57b', 4, 'sauce', 'Thắng nước màu và xào săn sườn non', 'Dùng nồi đáy dày làm nóng 15 ml dầu ăn và 10 g đường cát trắng còn lại trên lửa nhỏ đến khi đường chuyển màu nâu cánh gián, rót nhanh 30 ml nước nóng khuấy đều rồi cho phần hành tím và tỏi băm còn lại vào phi thơm. Trút sườn đã ướp vào đảo săn trên lửa vừa 6 phút cho từng miếng sườn lên màu đẹp.', NULL, 6),
('imp-ab36e38b07f3a57b_v4_step_5', 'imp-ab36e38b07f3a57b', 5, 'cook', 'Kho nhỏ lửa cho sườn non chín mềm', 'Đổ 220 ml nước lọc nóng vào xâm xấp mặt sườn, đun sôi rồi hạ lửa nhỏ, đậy hé vung kho liu riu 25 phút cho thịt sườn chín mềm và nước kho bắt đầu sánh nhẹ.', NULL, 25),
('imp-ab36e38b07f3a57b_v4_step_6', 'imp-ab36e38b07f3a57b', 6, 'finish', 'Kho cùng dứa, nêm lại và trình bày', 'Cho phần dứa đã xào, 10 ml nước mắm còn lại và ớt sừng thái lát vào nồi, đảo nhẹ và kho mở nắp thêm 5 phút trên lửa vừa đến khi nước sốt sánh kẹo bám đều quanh sườn và dứa. Tắt bếp, múc ra đĩa, rắc hành lá cắt nhỏ và 1 g tiêu đen xay còn lại lên trên.', NULL, 5),
('imp-26a36c69306143bc_v4_step_1', 'imp-26a36c69306143bc', 1, 'marinate', 'Làm sạch tôm tươi và ướp gia vị', 'Tôm tươi bóc sạch vỏ, bỏ đầu, rạch nhẹ sống lưng để rút hết chỉ đen, rửa sạch rồi thấm thật ráo nước. Cho tôm vào tô ướp cùng một nửa lượng tỏi băm, 2,5 g hạt nêm và 1 g tiêu đen xay, trộn đều và để thấm khoảng 10 phút.', 'Thấm khô tôm trước khi ướp và xào giúp tôm lên màu đẹp và không bị bắn dầu.', 10),
('imp-26a36c69306143bc_v4_step_2', 'imp-26a36c69306143bc', 2, 'prep', 'Chần sơ và sốc lạnh bông cải xanh', 'Tách bông cải xanh thành từng miếng vừa ăn, rửa sạch và để ráo. Đun sôi nồi nước với 6 g muối ăn trên lửa lớn, thả bông cải vào chần khoảng 1 phút cho vừa chuyển xanh mướt thì vớt ngay ra ngâm vào tô nước đá lạnh 2 phút, sau đó vớt ra rổ để ráo hoàn toàn. Hòa tan 4 g bột bắp với 30 ml nước lọc trong chén nhỏ.', 'Chần nhanh và ngâm nước đá giúp bông cải giữ độ giòn sần sật và màu xanh tươi mắt sau khi xào.', 2),
('imp-26a36c69306143bc_v4_step_3', 'imp-26a36c69306143bc', 3, 'cook', 'Xào săn tôm trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, làm nóng 15 ml dầu ăn rồi cho một phần tỏi băm còn lại vào phi thơm. Trút tôm đã ướp vào đảo nhanh tay khoảng 1,5–2 phút đến khi tôm chuyển màu đỏ cam đều, thân cong tròn săn chắc và chín hoàn toàn thì trút ra đĩa riêng.', 'Không xào tôm quá lâu để thịt tôm giữ được độ giòn ngọt, không bị khô bở.', 2),
('imp-26a36c69306143bc_v4_step_4', 'imp-26a36c69306143bc', 4, 'cook', 'Xào bông cải xanh và hành tây', 'Thêm 15 ml dầu ăn còn lại vào chảo, phi thơm nốt phần tỏi băm cùng hành tây thái múi cau trong 45 giây. Cho bông cải xanh đã ráo nước vào đảo đều trên lửa lớn khoảng 2 phút cho rau nóng đều và thấm dầu tỏi.', NULL, 2),
('imp-26a36c69306143bc_v4_step_5', 'imp-26a36c69306143bc', 5, 'cook', 'Rưới sốt bột bắp và đảo quyện cùng tôm', 'Trút đĩa tôm đã xào trở lại chảo bông cải xanh, nêm 15 ml nước mắm ngon, 2,5 g hạt nêm và 2 g muối ăn. Khuấy lại chén nước bột bắp cho khỏi lắng rồi rưới đều vào chảo, đảo nhanh tay khoảng 1 phút cho lớp sốt sánh nhẹ áo bóng quanh tôm và bông cải.', NULL, NULL),
('imp-26a36c69306143bc_v4_step_6', 'imp-26a36c69306143bc', 6, 'finish', 'Hoàn thiện hương dầu mè và dọn nóng', 'Rưới 3 ml dầu mè thơm vào chảo, đảo đều một lượt rồi tắt bếp ngay. Bày tôm xào bông cải xanh ra đĩa và rắc 1 g tiêu đen xay còn lại lên trên, thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-b87b71d57128cc07_v4_step_1', 'imp-b87b71d57128cc07', 1, 'prep', 'Làm sạch nhớt, cắt khúc và ướp cá lóc', 'Chà xát cá lóc với 4 g muối ăn và vài lát chanh tươi để hết nhớt, rửa sạch nhiều lần rồi thấm thật khô và cắt khúc dày khoảng 2 cm, khía nhẹ trên da. Băm nhuyễn sả tươi, tỏi, hành tím và 2 quả ớt. Ướp cá với 1/2 lượng sả băm, 1/2 tỏi băm, hành tím, 1 quả ớt băm, 2 g muối, 4 g hạt nêm, 4 g đường, 2 g tiêu đen xay và 3 g bột nghệ trong 20 phút cho thấm.', 'Khứa nhẹ trên da và thấm khô mặt cá trước khi ướp giúp gia vị bám sâu và khi chiên không bị bắn dầu.', 20),
('imp-b87b71d57128cc07_v4_step_2', 'imp-b87b71d57128cc07', 2, 'prep', 'Pha bột áo chiên giòn cho cá', 'Cho 50 g bột chiên giòn, 2 g muối ăn còn lại và 60 ml nước lọc vào tô, khuấy đều đến khi thu được hỗn hợp bột sền sệt mịn màng đủ bám một lớp áo mỏng quanh khúc cá.', NULL, NULL),
('imp-b87b71d57128cc07_v4_step_3', 'imp-b87b71d57128cc07', 3, 'cook', 'Chiên vàng giòn sả băm và tỏi băm trước', 'Đun nóng 250 ml dầu ăn trong chảo sâu lòng ở lửa vừa, thả 1/2 phần sả băm còn lại vào chiên trước khoảng 3 phút cho vàng thơm rồi mới cho 1/2 phần tỏi băm còn lại vào đảo thêm 1 phút đến khi vàng giòn đều thì vớt ngay ra rây để ráo dầu.', 'Sả chứa nhiều nước và lâu chín hơn tỏi nên phải chiên sả trước rồi mới thả tỏi vào, tránh để tỏi cháy đắng.', 4),
('imp-b87b71d57128cc07_v4_step_4', 'imp-b87b71d57128cc07', 4, 'cook', 'Chiên ngập dầu cá lóc tẩm bột đến khi giòn rụm', 'Giữ chảo dầu thơm đang nóng ở lửa vừa, nhúng từng khúc cá lóc đã ướp (gạt bớt sả băm để không cháy) qua lớp bột chiên giòn sệt rồi thả vào chiên mỗi mặt 4 phút cho vàng ươm. Cuối cùng tăng lửa lớn trong 1 phút để thoát bớt dầu và vỏ giòn lâu, kiểm tra thịt cá trắng đục chín hoàn toàn rồi vớt ra giấy thấm dầu.', 'Tăng lửa lớn 1 phút cuối trước khi vớt là mẹo giúp đẩy dầu thừa ra ngoài, giúp cá lóc giòn lâu mà không bị ngấy.', 9),
('imp-b87b71d57128cc07_v4_step_5', 'imp-b87b71d57128cc07', 5, 'finish', 'Xóc cá cùng sả tỏi phi và pha nước chấm', 'Chắt hết dầu trong chảo, cho cá chiên vào xóc nhanh tay cùng sả tỏi chiên vàng và 1 quả ớt băm còn lại trong 30 giây cho bám đều hương thơm. Trong chén nhỏ, khuấy tan 30 ml nước mắm ngon với 4 g đường, vài giọt nước cốt chanh và ớt thái lát để làm nước chấm.', NULL, NULL),
('imp-b87b71d57128cc07_v4_step_6', 'imp-b87b71d57128cc07', 6, 'finish', 'Bày cá chiên sả ớt ra đĩa và thưởng thức', 'Xếp các khúc cá lóc chiên vàng giòn ra đĩa, rắc hết phần sả tỏi phi giòn lên mặt cùng lát ớt tươi trang trí và dọn ăn ngay với cơm trắng nóng.', NULL, NULL),
('imp-511a92d180408e0a_v4_step_1', 'imp-511a92d180408e0a', 1, 'prep', 'Ngâm nấm hương và sơ chế hành tím, hành lá', 'Ngâm 20 g nấm hương khô trong nước ấm khoảng 20 phút cho nở mềm hoàn toàn, vớt ra vắt nhẹ nước, cắt bỏ chân nấm cứng rồi băm nhỏ. Bóc vỏ 15 g hành tím băm nhuyễn; rửa sạch hành lá thái nhỏ và để riêng 1/3 phần lá xanh dùng rắc mặt.', NULL, 20),
('imp-511a92d180408e0a_v4_step_2', 'imp-511a92d180408e0a', 2, 'marinate', 'Ướp thịt heo xay cùng nấm hương và gia vị', 'Cho 200 g thịt heo xay vào tô cùng nấm hương băm nhỏ, hành tím băm, 5 ml nước mắm, 2,5 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay. Trộn thật đều tay rồi để nghỉ 10 phút cho thịt ngấm vị và không bị vón cục khi hòa cùng trứng.', 'Ướp thịt heo xay trước khi trộn vào trứng giúp thịt tơi mềm, đậm đà và không bị nhạt vị so với phần trứng xung quanh.', 10),
('imp-511a92d180408e0a_v4_step_3', 'imp-511a92d180408e0a', 3, 'prep', 'Đánh tan trứng gà và lọc qua rây mịn', 'Đập 4 quả trứng gà vào tô lớn, thêm 120 ml nước lọc nguội, 10 ml nước mắm còn lại, 2,5 g hạt nêm và 3 g đường cát trắng. Dùng đũa khuấy nhẹ đều theo một chiều cho tan gia vị mà không tạo nhiều bọt khí, sau đó lọc hỗn hợp qua rây mịn vào tô sứ chịu nhiệt.', 'Khuấy nhẹ tay theo một chiều và lọc qua rây giúp loại bỏ lợn cợn lòng trắng và bọt khí, mặt trứng sau khi hấp sẽ láng mịn như gương.', NULL),
('imp-511a92d180408e0a_v4_step_4', 'imp-511a92d180408e0a', 4, 'prep', 'Trộn đều nhân thịt nấm và bọc kín miệng tô', 'Cho phần thịt heo xay đã ướp cùng 2/3 lượng hành lá thái nhỏ vào tô trứng đã lọc, khuấy nhẹ cho thịt tơi đều không lắng đọng cục ở đáy. Dùng màng bọc thực phẩm chịu nhiệt bọc kín miệng tô (hoặc đậy đĩa sứ vừa khít) để hơi nước không nhỏ giọt làm rỗ mặt trứng.', NULL, NULL),
('imp-511a92d180408e0a_v4_step_5', 'imp-511a92d180408e0a', 5, 'cook', 'Hấp cách thủy lửa nhỏ cho trứng đông mịn', 'Đun sôi 600 ml nước lọc trong nồi hấp, đặt tô trứng lên xửng rồi hạ xuống lửa nhỏ liu riu, đậy nắp và hấp cách thủy trong 20 phút. Nếu dùng nắp vung thường không bọc màng thực phẩm, nên lót thêm chiếc khăn sạch dưới nắp nồi để thấm hơi nước.', 'Luôn giữ lửa nhỏ liu riu trong suốt quá trình hấp; nhiệt quá mạnh sẽ làm nước sôi trào khiến trứng bị rỗ tổ ong và tách nước.', 20),
('imp-511a92d180408e0a_v4_step_6', 'imp-511a92d180408e0a', 6, 'finish', 'Kiểm tra độ chín và hoàn thiện tô trứng hấp', 'Mở màng bọc, dùng tăm xiên nhẹ vào chính giữa tô trứng, rút ra thấy tăm sạch không dính dịch trứng ướt và phần thịt bên trong đã chín trắng hoàn toàn là đạt. Rắc phần hành lá thái nhỏ và 1 g tiêu đen xay còn lại lên mặt, rưới thêm 5 ml dầu mè thơm và dùng nóng ngay với cơm.', NULL, NULL),
('imp-d02c9b83214f81be_v4_step_1', 'imp-d02c9b83214f81be', 1, 'cook', 'Luộc chín thịt ba chỉ và thái lát mỏng', 'Chà sạch thịt ba chỉ với chút muối rồi rửa lại, cho vào nồi với 500 ml nước lọc, 10 g hành tím đập dập và 3 g muối ăn. Đun sôi trên lửa lớn rồi hạ lửa vừa luộc khoảng 18 phút đến khi đũa xiên qua thịt không còn nước hồng. Vớt ra ngâm nước nguội cho thịt trắng săn, để ráo rồi thái lát mỏng vừa ăn.', NULL, 18),
('imp-d02c9b83214f81be_v4_step_2', 'imp-d02c9b83214f81be', 2, 'prep', 'Sơ chế dưa leo giòn mát không đắng', 'Rửa sạch dưa leo, cắt bỏ hai đầu và chà xát vòng tròn hai đầu quả đến khi ra bọt trắng để loại bỏ vị đắng, sau đó xả sạch. Bổ đôi dưa leo theo chiều dọc, nạo bỏ hết phần ruột hạt rồi thái lát vát mỏng, ngâm cùng cà rốt bào sợi vào thau nước đá lạnh pha 300 ml nước lọc và 3 g muối ăn trong 10 phút cho rau củ giòn cứng rồi vớt vắt ráo.', 'Loại bỏ hết phần ruột dưa leo và ngâm nước đá giúp gỏi giữ độ giòn lâu mà không bị chảy nhiều nước khi trộn.', 10),
('imp-d02c9b83214f81be_v4_step_3', 'imp-d02c9b83214f81be', 3, 'cook', 'Rim chín tôm giữ trọn vị ngọt', 'Rửa sạch tôm tươi, cắt bỏ râu chân và rút chỉ đen trên lưng. Làm nóng chảo trên lửa vừa, cho tôm cùng 2 g muối ăn vào rim đảo đều khoảng 4 phút đến khi tôm chuyển màu đỏ cam rực, thịt săn chín hoàn toàn và cạn ráo nước thì tắt bếp, để nguội rồi bóc vỏ và chẻ đôi.', 'Rim tôm trên chảo khô thay vì luộc ngập nước giúp thịt tôm săn giòn và giữ nguyên vị ngọt tự nhiên.', 4),
('imp-d02c9b83214f81be_v4_step_4', 'imp-d02c9b83214f81be', 4, 'sauce', 'Giã tỏi ớt pha nước mắm trộn gỏi', 'Cho 48 g đường cát trắng, tỏi khô và ớt sừng vào cối giã nhuyễn quyện đều. Trút ra bát, thêm 45 ml nước mắm ngon, 15 ml tương ớt và nước cốt 2 quả chanh tươi, khuấy kỹ cho đường tan hết thành hỗn hợp nước trộn sánh thơm.', NULL, NULL),
('imp-d02c9b83214f81be_v4_step_5', 'imp-d02c9b83214f81be', 5, 'prep', 'Phi hành tím và chuẩn bị đồ ăn kèm', 'Phi thơm vàng 10 g hành tím thái lát với 10 ml dầu ăn trên lửa nhỏ rồi vớt ráo dầu. Rang chín lạc trên lửa nhỏ, xát sạch vỏ và giã dập. Chuẩn bị sẵn đĩa bánh phồng tôm giòn và rửa sạch, cắt nhỏ rau húng lủi.', NULL, NULL),
('imp-d02c9b83214f81be_v4_step_6', 'imp-d02c9b83214f81be', 6, 'finish', 'Trộn gỏi theo hai lượt thấm đều vị', 'Cho dưa leo và cà rốt đã vắt ráo vào âu lớn, rưới một nửa nước mắm trộn vào đảo đều và để 3 phút cho rau củ thấm trước. Tiếp theo cho tôm rim và thịt ba chỉ vào, rưới nốt phần nước trộn còn lại đảo nhẹ tay, thêm rau húng lủi cắt nhỏ vào trộn đều lần cuối. Bày gỏi ra đĩa, rắc đậu phộng rang giã dập, hành phi và dọn ăn kèm bánh phồng tôm.', 'Trộn rau củ trước với một nửa nước trộn giúp dưa leo cà rốt đậm đà mà không làm tôm thịt bị mặn gắt.', NULL),
('imp-9ae951bec7fbf21b_v4_step_1', 'imp-9ae951bec7fbf21b', 1, 'prep', 'Ngâm và trụng hủ tiếu khô tơi sợi', 'Ngâm hủ tiếu khô trong nước lọc mát khoảng 8 phút cho sợi hơi mềm, sau đó đun nóng 1 lít nước lọc khoảng 80°C rồi trụng hủ tiếu nhanh 2 phút. Vớt ra rổ xóc ráo hoàn toàn, trộn ngay với 10 ml dầu ăn để sợi hủ tiếu tơi rời, không dính bết khi xào.', 'Không luộc hủ tiếu bằng nước sôi quá lâu vì sợi sẽ mềm nhão và dễ nát vụn khi đảo trên chảo.', 10),
('imp-9ae951bec7fbf21b_v4_step_2', 'imp-9ae951bec7fbf21b', 2, 'marinate', 'Sơ chế và ướp tôm tươi thấm vị', 'Tôm tươi bóc vỏ chừa đuôi, rút bỏ chỉ đen, rửa sạch thấm khô. Ướp tôm với 10 ml dầu hào, 2,5 g hạt nêm, 2,5 g đường cát trắng, 1 g tiêu đen xay cùng một nửa phần tỏi khô và hành tím khô băm nhuyễn, để ngấm 10 phút.', NULL, 10),
('imp-9ae951bec7fbf21b_v4_step_3', 'imp-9ae951bec7fbf21b', 3, 'prep', 'Chuẩn bị giá đỗ, hẹ lá và rau trang trí', 'Rửa sạch giá đỗ, để thật ráo nước để khi xào không ra nước; hẹ lá cắt khúc 3–4 cm; ngò rí rửa sạch và ớt tươi thái lát mỏng.', NULL, NULL),
('imp-9ae951bec7fbf21b_v4_step_4', 'imp-9ae951bec7fbf21b', 4, 'cook', 'Xào chín săn tôm tươi trên lửa lớn', 'Bắc chảo rộng lên bếp lửa lớn với 15 ml dầu ăn, phi thơm phần tỏi và hành tím băm còn lại rồi trút tôm đã ướp vào đảo nhanh tay khoảng 2–3 phút đến khi tôm chuyển màu hồng cam đậm, thịt săn chín hoàn toàn thì trút ra đĩa riêng.', 'Xào tôm riêng ở lửa lớn giúp tôm giữ độ giòn ngọt và không ra nước làm ướt sợi hủ tiếu.', 3),
('imp-9ae951bec7fbf21b_v4_step_5', 'imp-9ae951bec7fbf21b', 5, 'cook', 'Xào hủ tiếu thấm xì dầu với giá hẹ', 'Làm nóng chảo vừa dùng với 15 ml dầu ăn còn lại, thả giá đỗ và hẹ lá vào đảo nhanh 45 giây trên lửa lớn cho vừa chín tới. Trút sợi hủ tiếu đã trộn dầu vào, rưới đều 25 ml xì dầu, 10 ml dầu hào còn lại, 2,5 g hạt nêm và 2,5 g đường cát trắng, xóc đảo liên tục 2 phút cho sợi hủ tiếu ráo bóng, lên màu vàng nâu hấp dẫn.', 'Đảo nhanh tay trên lửa lớn giúp sợi hủ tiếu dậy mùi thơm áp chảo mà giá hẹ vẫn giòn xanh.', 3),
('imp-9ae951bec7fbf21b_v4_step_6', 'imp-9ae951bec7fbf21b', 6, 'finish', 'Trộn đều tôm và bày đĩa thưởng thức', 'Trút phần tôm đã xào vào chảo hủ tiếu, đảo đều thêm 30 giây cho quyện vị rồi tắt bếp. Bày ra 3 đĩa, rắc thêm 1 g tiêu đen xay còn lại, điểm ngò rí và ớt tươi thái lát để thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-5ab5c1053b7371f0_v4_step_1', 'imp-5ab5c1053b7371f0', 1, 'prep', 'Thấm ráo đậu phụ và băm nhuyễn sả, tỏi, ớt', 'Đậu phụ trắng rửa nhẹ, dùng khăn giấy thấm thật khô rồi cắt mỗi bìa thành 6–8 miếng vuông dày khoảng 2 cm. Sả tươi bóc bỏ lớp bẹ già bên ngoài, cắt bỏ gốc và băm thật nhuyễn; tỏi khô và ớt sừng bỏ hạt, băm nhuyễn để riêng.', 'Băm sả càng nhuyễn thì khi xào sả càng dễ dậy hương và bám kín đều lên bề mặt từng miếng đậu phụ.', NULL),
('imp-5ab5c1053b7371f0_v4_step_2', 'imp-5ab5c1053b7371f0', 2, 'cook', 'Chiên vàng giòn đều các mặt đậu phụ', 'Làm nóng chảo với 85 ml dầu ăn thực vật trên lửa vừa đến khi dầu nóng già, lần lượt thả từng miếng đậu phụ vào chiên khoảng 8 phút. Lật nhẹ các mặt đến khi vỏ đậu phồng vàng giòn đều thì gắp ra đĩa lót giấy thấm dầu.', 'Chờ dầu nóng già trước khi thả đậu và giữ khoảng cách giữa các miếng giúp đậu không bị dính sát và không vỡ khi trở mặt.', 8),
('imp-5ab5c1053b7371f0_v4_step_3', 'imp-5ab5c1053b7371f0', 3, 'cook', 'Phi thơm tỏi, sả băm và ớt trên lửa nhỏ', 'Chắt bớt dầu trong chảo ra, chỉ giữ lại khoảng 15 ml dầu ăn. Cho tỏi băm vào phi 30 giây trên lửa nhỏ cho vừa dậy hương, tiếp tục đổ toàn bộ sả băm và ớt băm vào đảo đều tay thêm 2 phút đến khi sả ngả vàng thơm nồng.', 'Giữ lửa nhỏ khi phi sả và tỏi để hỗn hợp chín vàng đều từ từ, tránh bị cháy đắng.', 2),
('imp-5ab5c1053b7371f0_v4_step_4', 'imp-5ab5c1053b7371f0', 4, 'cook', 'Nêm gia vị vào hỗn hợp sả ớt', 'Nêm trực tiếp vào chảo sả ớt 30 ml nước tương, 8 g đường cát trắng, 3 g muối ăn và 4 g hạt nêm chay. Đảo đều trên lửa nhỏ khoảng 1 phút cho đường tan hết và gia vị quyện sánh với sả ớt.', NULL, NULL),
('imp-5ab5c1053b7371f0_v4_step_5', 'imp-5ab5c1053b7371f0', 5, 'cook', 'Xóc đều đậu phụ chiên với sả ớt đậm đà', 'Trút toàn bộ phần đậu phụ đã chiên giòn trở lại chảo, dùng đũa hoặc xẻng gỗ đảo nhẹ và đều tay trong 3 phút trên lửa nhỏ để lớp sả ớt mặn ngọt bám kín quanh từng miếng đậu.', NULL, 3),
('imp-5ab5c1053b7371f0_v4_step_6', 'imp-5ab5c1053b7371f0', 6, 'finish', 'Rắc tiêu đen và trình bày ra đĩa nóng', 'Rắc 1 g tiêu đen xay vào chảo, đảo nhanh thêm 10 giây rồi tắt bếp. Gắp đậu phụ chiên sả ớt ra đĩa, gạt đều phần sả ớt phi vàng lên mặt và dùng nóng ngay với cơm trắng.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-67054d03e5a5b011_v4_step_1', 'imp-67054d03e5a5b011', 1, 'prep', 'Vo gạo và sơ chế gừng, hành lá, đánh trứng', 'Vo sạch 100 g gạo tẻ qua 2 lần nước nhẹ tay rồi để ráo. Cạo vỏ 15 g gừng tươi, rửa sạch và thái sợi chỉ thật mảnh. Rửa sạch hành lá, thái nhuyễn. Đập 2 quả trứng gà vào chén, dùng đũa đánh tan nhẹ đến khi lòng trắng và lòng đỏ hòa đều.', 'Thái gừng thành sợi thật mảnh sẽ giúp gừng tiết tinh dầu ấm nhanh khi gặp cháo nóng mà không bị cay gắt lúc nhai.', NULL),
('imp-67054d03e5a5b011_v4_step_2', 'imp-67054d03e5a5b011', 2, 'cook', 'Nấu gạo nở mềm trên lửa nhỏ vừa', 'Cho gạo vào nồi cùng 1,2 lít nước lọc, đặt lên bếp đun sôi bùng trên lửa lớn rồi hạ ngay xuống lửa nhỏ. Đậy hé nắp và ninh khoảng 15 phút, thỉnh thoảng dùng vá khuấy sát đáy nồi để hạt gạo nở bung đều, nước cháo sánh mịn mà không bị bén đáy.', 'Đậy hé nắp khi ninh cháo giúp giữ nhiệt ổn định cho gạo nhanh nhừ mà không bị trào bọt ra bếp.', 15),
('imp-67054d03e5a5b011_v4_step_3', 'imp-67054d03e5a5b011', 3, 'cook', 'Nêm gia vị cho nồi cháo trắng', 'Khi hạt gạo đã nở nhừ sánh mịn, nêm 3 g muối ăn và 15 ml nước mắm ngon vào nồi, khuấy đều rồi nếm thử để điều chỉnh độ mặn thanh vừa miệng.', NULL, NULL),
('imp-67054d03e5a5b011_v4_step_4', 'imp-67054d03e5a5b011', 4, 'cook', 'Rót trứng gà tạo vân tơi mịn', 'Giữ nồi cháo sôi lăn tăn nhẹ trên lửa nhỏ, từ từ rót chén trứng gà đã đánh tan vào nồi theo dòng mảnh, đồng thời dùng đũa khuấy đều một chiều khoảng 1 phút để trứng kết thành những vân vàng mịn quyện đều trong cháo và chín hoàn toàn.', 'Rót trứng từ từ khi cháo đang sôi nhẹ giúp trứng chín ngay thành vân mượt mà không bị tanh hay vón cục lớn.', 1),
('imp-67054d03e5a5b011_v4_step_5', 'imp-67054d03e5a5b011', 5, 'cook', 'Hòa một phần gừng vào nồi cháo', 'Thả một nửa lượng gừng tươi thái sợi vào nồi cháo, khuấy nhẹ thêm 30 giây cho hương gừng lan tỏa đều trong nước cháo rồi tắt bếp.', NULL, NULL),
('imp-67054d03e5a5b011_v4_step_6', 'imp-67054d03e5a5b011', 6, 'finish', 'Chan cháo nóng lên hành lá và thưởng thức', 'Lót hành lá thái nhỏ và phần gừng tươi thái sợi còn lại dưới đáy 2 bát sứ. Múc cháo trứng nóng hổi chan lên trên để hành lá chín tái dậy mùi thơm, nhỏ đều 5 ml dầu mè và rắc 1,5 g tiêu đen xay rồi thưởng thức ngay.', NULL, NULL),
('imp-e375595daced53af_v4_step_1', 'imp-e375595daced53af', 1, 'prep', 'Thái mỏng và ướp nhẹ thịt thăn bò', 'Thấm thật khô 600 g thịt thăn bò, thái lát mỏng ngang thớ. Xếp thịt bò ra đĩa lớn, ướp nhẹ với 15 g gừng thái sợi, một nửa lượng tỏi băm, 1,5 g tiêu đen xay và 5 ml dầu ăn rồi trộn đều cho thịt thơm mềm và không bị thâm.', 'Chỉ ướp thịt bò với dầu ăn, gừng, tỏi và tiêu, không ướp muối hay nước mắm quá sớm để thịt không bị chảy nước đỏ.', NULL),
('imp-e375595daced53af_v4_step_2', 'imp-e375595daced53af', 2, 'prep', 'Sơ chế dứa, rau củ và chuẩn bị đồ cuốn', 'Thái lát mỏng 1/2 quả dứa chín để nấu lẩu, băm nhuyễn 1/4 quả còn lại để pha mắm nêm. Bổ múi cau 2 quả cà chua; 1/2 củ hành tây bổ múi cau, 1/2 củ thái lát mỏng xếp lên đĩa thịt bò. Đập dập 3 cây sả cắt khúc 5 cm; rửa sạch rau muống, xà lách, rau sống và bày bánh tráng cuốn, bún tươi ra bàn.', NULL, NULL),
('imp-e375595daced53af_v4_step_3', 'imp-e375595daced53af', 3, 'sauce', 'Pha mắm nêm dứa tỏi ớt đậm đà', 'Cho 45 ml mắm nêm vào chén cùng 8 g đường phèn giã nhỏ, phần dứa băm nhuyễn, phần tỏi băm còn lại và 1 quả ớt hiểm băm. Khuấy đều cho đường tan hoàn toàn và các gia vị hòa quyện sánh thơm.', 'Băm nhuyễn dứa chín trộn vào mắm nêm giúp làm dịu độ mặn gắt tự nhiên của mắm cá cơm và tạo vị chua ngọt thanh rất bắt miệng.', NULL),
('imp-e375595daced53af_v4_step_4', 'imp-e375595daced53af', 4, 'cook', 'Phi thơm hành tím và xào sơ dứa, cà chua', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn còn lại, phi thơm 20 g hành tím băm và 3 cây sả đập dập trong 1 phút. Cho phần dứa thái lát và cà chua bổ múi cau vào đảo nhẹ 3 phút cho cà chua mềm và dứa tiết nước ngọt.', NULL, 4),
('imp-e375595daced53af_v4_step_5', 'imp-e375595daced53af', 5, 'cook', 'Nấu nước lẩu dừa dứa chua thanh', 'Đổ 500 ml nước dừa tươi và 1200 ml nước lọc vào nồi, thêm 1/2 củ hành tây bổ múi cau rồi đun sôi bùng và hớt sạch bọt. Hạ lửa vừa nấu 10 phút cho nước ngọt thanh, sau đó cho 80 ml giấm gạo, 15 ml nước mắm ngon, 12 g đường phèn, 3 g muối ăn và 1 quả ớt thái lát vào nếm lại vị chua ngọt dịu nhẹ.', 'Cho giấm gạo vào ở giai đoạn cuối trước khi dọn bàn để giữ độ chua thanh dịu mà không bị bay hơi mất mùi thơm.', 10),
('imp-e375595daced53af_v4_step_6', 'imp-e375595daced53af', 6, 'finish', 'Nhúng bò chín tới và cuốn bánh tráng chấm mắm nêm', 'Chuyển nồi lẩu ra bếp giữa bàn giữ sôi lăn tăn. Khi ăn, gắp từng lát thịt bò cùng hành tây thái lát nhúng vào nước lẩu khoảng 15–20 giây cho thịt vừa chín tái hồng mềm ngọt, nhúng thêm rau muống. Trải bánh tráng, xếp rau sống, bún tươi và thịt bò nóng hổi vào cuốn tròn rồi chấm cùng mắm nêm dứa ớt.', NULL, NULL),
('imp-9b4ea97916a44e67_v4_step_1', 'imp-9b4ea97916a44e67', 1, 'prep', 'Nhặt và rửa sạch rau muống non', 'Nhặt bỏ phần cọng già và lá úa của 1,5 bó rau muống, cắt khúc dài khoảng 5 cm. Ngâm rau vào chậu nước sạch pha 3 g muối ăn trong 7 phút cho sạch bụi bẩn, sau đó rửa lại 2–3 lần nước lạnh rồi vớt ra rổ để thật ráo.', NULL, 7),
('imp-9b4ea97916a44e67_v4_step_2', 'imp-9b4ea97916a44e67', 2, 'prep', 'Sơ chế tôm giã nhuyễn và đập dập', 'Lột vỏ 250 g tôm tươi, bỏ đầu, rút sạch chỉ đen dọc lưng, rửa qua nước lạnh rồi thấm ráo. Chia 1/3 lượng tôm cho vào cối giã thật nhuyễn để tạo độ ngọt tự nhiên cho nước canh; 2/3 phần tôm còn lại dùng sống dao đập dập nhẹ cho thịt tôm giữ độ sần sật. Băm nhỏ 20 g hành tím, cắt khúc hành lá và ngò rí.', 'Kết hợp giã nhuyễn 1/3 tôm và đập dập 2/3 tôm giúp nước dùng vừa ngọt đậm đà vừa còn miếng thịt tôm ăn rất đã miệng.', NULL),
('imp-9b4ea97916a44e67_v4_step_3', 'imp-9b4ea97916a44e67', 3, 'cook', 'Phi thơm hành tím và xào chín thơm tôm', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm vào phi đến khi dậy mùi thơm vàng nhẹ. Trút cả phần tôm giã nhuyễn và tôm đập dập vào đảo đều 2–3 phút đến khi tôm săn lại, chuyển màu cam hồng hấp dẫn và chín đều.', NULL, 3),
('imp-9b4ea97916a44e67_v4_step_4', 'imp-9b4ea97916a44e67', 4, 'cook', 'Nấu nước dùng tôm ngọt trong', 'Đổ 900 ml nước lọc vào nồi tôm, bật lửa lớn đun sôi bùng, dùng vá hớt sạch phần bọt nổi trên mặt rồi hạ xuống lửa vừa nấu tiếp 5 phút để thịt tôm tiết hết vị ngọt vào nước canh.', 'Hớt sạch bọt ngay khi nước vừa sôi giúp nồi canh rau muống giữ được độ trong thanh và không bị đục.', 5),
('imp-9b4ea97916a44e67_v4_step_5', 'imp-9b4ea97916a44e67', 5, 'cook', 'Nêm gia vị và thả rau muống nấu mở vung', 'Nêm 8 g hạt nêm, 5 g muối ăn còn lại, 10 ml nước mắm và 4 g đường vào nồi, khuấy tan rồi nếm lại vị thanh ngọt hài hòa. Khi nước sôi bùng trở lại trên lửa lớn, thả rau muống vào và dùng vá nhấn nhẹ cho rau ngập nước, nấu mở vung đúng 3 phút đến khi cọng rau vừa chín tới, xanh mướt và vẫn giữ độ giòn.', 'Nấu rau muống ở lửa lớn và tuyệt đối không đậy nắp giúp giữ màu xanh tươi tự nhiên mà không bị thâm sẫm.', 3),
('imp-9b4ea97916a44e67_v4_step_6', 'imp-9b4ea97916a44e67', 6, 'finish', 'Hoàn thiện với hành lá và ngò rí', 'Tắt bếp ngay sau khi rau chín tới, thả hành lá và ngò rí cắt khúc vào đảo nhẹ một lượt cho dậy hương thơm rồi múc canh ra tô dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-6d7fc503ade5df6e_v4_step_1', 'imp-6d7fc503ade5df6e', 1, 'prep', 'Sơ chế thịt ba chỉ và băm nhuyễn sả ớt', 'Rửa sạch thịt ba chỉ heo, dùng khăn giấy thấm thật khô rồi thái thành từng lát mỏng vừa ăn dày khoảng 0,4 cm. Sả tươi bóc bỏ bẹ già, đập dập và băm thật nhuyễn; tỏi khô và ớt hiểm đỏ tươi băm nhỏ; hành lá rửa sạch thái nhỏ.', 'Thấm khô thịt ba chỉ trước khi cho lên chảo giúp thịt nhanh săn xém cạnh mà không bị bắn dầu.', NULL),
('imp-6d7fc503ade5df6e_v4_step_2', 'imp-6d7fc503ade5df6e', 2, 'cook', 'Áp chảo thịt ba chỉ ra bớt mỡ và săn xém', 'Đặt chảo khô lên bếp lửa vừa (thêm tối đa 10 ml dầu ăn nếu thịt ít mỡ). Cho toàn bộ thịt ba chỉ vào dàn đều, đảo khoảng 3–4 phút cho thịt tiết bớt mỡ thừa, săn chắc và chín kỹ đều hai mặt không còn sắc hồng thì gắp riêng ra đĩa.', 'Áp chảo trước giúp phần mỡ ba chỉ tan bớt, miếng thịt khi xào xong ăn giòn ngậy mà không bị ngán.', 4),
('imp-6d7fc503ade5df6e_v4_step_3', 'imp-6d7fc503ade5df6e', 3, 'cook', 'Phi thơm vàng tỏi, sả và ớt băm', 'Chắt bớt phần mỡ heo dư nếu quá nhiều, chỉ giữ lại khoảng 1,5 muỗng canh mỡ nóng trong chảo. Cho tỏi băm, sả băm và ớt hiểm đỏ băm vào phi đều tay trên lửa vừa khoảng 2 phút cho đến khi sả ngả vàng nhẹ và dậy mùi thơm nồng.', 'Giữ lửa vừa khi phi sả để tinh dầu sả tỏa thơm mà không bị cháy khét gây đắng.', 2),
('imp-6d7fc503ade5df6e_v4_step_4', 'imp-6d7fc503ade5df6e', 4, 'cook', 'Xào thấm gia vị đậm đà kiểu miền Trung', 'Trút toàn bộ thịt ba chỉ vào lại chảo sả ớt, nêm 15 ml nước mắm ngon, 8 g đường cát trắng và 5 g hạt nêm. Hạ lửa vừa-nhỏ và đảo liên tục khoảng 3–4 phút để gia vị keo nhẹ bám đều quanh miếng thịt, bề mặt thịt vàng xém cạnh và chín kỹ hoàn toàn.', NULL, 4),
('imp-6d7fc503ade5df6e_v4_step_5', 'imp-6d7fc503ade5df6e', 5, 'cook', 'Thêm hành lá và tiêu đen xay', 'Nêm nếm lại cho vừa khẩu vị mặn cay đậm đà. Cho hành lá thái nhỏ và 2 g tiêu đen xay vào đảo nhanh tay thêm 20 giây cho hành chín xanh rồi tắt bếp.', NULL, NULL),
('imp-6d7fc503ade5df6e_v4_step_6', 'imp-6d7fc503ade5df6e', 6, 'finish', 'Trình bày và dùng nóng với cơm', 'Múc thịt ba chỉ xào sả ớt cùng phần sả phi vàng thơm ra đĩa, thưởng thức nóng ngay với cơm trắng.', NULL, NULL),
('imp-364497296cfcf033_v4_step_1', 'imp-364497296cfcf033', 1, 'prep', 'Làm sạch ống mực và ngâm mềm nấm hương', 'Nắm phần đầu mực kéo nhẹ tách khỏi thân, rút bỏ túi mực, nang cứng và nội tạng, cắt bỏ mắt cùng răng mực rồi lột bỏ lớp da tím bên ngoài. Rửa mực với 2 g muối ăn rồi xả sạch lại nước mát, giữ nguyên ống thân không bị thủng rách và để thật ráo. Ngâm 15 g nấm hương khô trong nước ấm 20 phút cho nở mềm rồi băm nhuyễn.', NULL, 20),
('imp-364497296cfcf033_v4_step_2', 'imp-364497296cfcf033', 2, 'marinate', 'Quết dẻo nhân thịt heo xay với nấm và gia vị', 'Cho 250 g thịt heo xay vào tô lớn cùng nấm hương băm nhuyễn, 10 g gừng băm, 15 g hành tím băm, tỏi băm nhuyễn và một nửa lượng hành lá thái nhỏ. Nêm 15 ml nước mắm, 4 g hạt nêm, 4 g đường cát trắng, 2 g muối ăn và 2 g tiêu đen xay, dùng thìa quết mạnh tay 2 phút cho nhân dẻo mịn rồi để nghỉ 10 phút.', 'Quết nhân kỹ cho dẻo kết dính giúp phần thịt bên trong không bị rời rạc hay rỗng ruột khi cắt khoanh.', 10),
('imp-364497296cfcf033_v4_step_3', 'imp-364497296cfcf033', 3, 'prep', 'Nhồi nhân vào thân mực và cố định bằng tăm', 'Dùng thìa nhỏ múc từng phần nhân thịt nhồi vào ống thân mực, ấn nhẹ cho nhân chặt đều nhưng chỉ nhồi khoảng 80% độ dài thân mực để trừ hao độ co khi chín. Đặt đầu mực trở lại miệng ống và dùng tăm tre ghim chéo cố định chắc chắn, có thể chích vài lỗ tăm nhỏ dọc thân mực để thoát khí.', 'Chỉ nhồi đầy khoảng 80% thân mực và chích 2–3 lỗ tăm nhỏ giúp vỏ mực không bị nứt vỡ khi hấp nóng.', NULL),
('imp-364497296cfcf033_v4_step_4', 'imp-364497296cfcf033', 4, 'cook', 'Hấp cách thủy mực nhồi thịt chín đều', 'Đun sôi 600 ml nước lọc trong nồi hấp. Xếp mực đã nhồi vào đĩa sâu lòng chịu nhiệt, rải đều 15 g gừng thái sợi và phần hành lá cắt khúc còn lại lên trên. Đặt đĩa vào xửng, đậy kín nắp và hấp trên lửa vừa khoảng 18 phút đến khi thân mực chuyển trắng đục và xiên tăm vào giữa thấy nhân thịt chín săn, nước tiết ra trong suốt.', 'Duy trì lửa vừa ổn định khi hấp giúp nhân thịt bên trong chín đều tới tâm mà lớp mực bên ngoài không bị co rút hay nứt vỡ.', 18),
('imp-364497296cfcf033_v4_step_5', 'imp-364497296cfcf033', 5, 'sauce', 'Pha muối tiêu chanh ớt chấm mực hấp', 'Trộn đều 3 g muối ăn còn lại với 1 g tiêu đen xay trong chén nhỏ, vắt nước cốt 1/2 quả chanh tươi vào khuấy nhẹ rồi thả vài lát ớt tươi lên trên.', NULL, NULL),
('imp-364497296cfcf033_v4_step_6', 'imp-364497296cfcf033', 6, 'finish', 'Cắt khoanh mực nhồi thịt và trình bày nóng', 'Nhấc đĩa mực ra khỏi xửng, chờ nguội bớt khoảng 3 phút cho nhân săn chắc rồi rút bỏ tăm tre. Dùng dao bản mỏng thật sắc thái mực thành từng khoanh tròn dày 1,5 cm, xếp ngay ngắn ra đĩa cùng phần gừng hành hấp và rưới nhẹ ít nước ngọt tiết ra, dọn nóng chấm muối tiêu chanh.', NULL, NULL),
('imp-806780abda4b5205_v4_step_1', 'imp-806780abda4b5205', 1, 'marinate', 'Sơ chế và ướp tôm tươi cùng mực ống', 'Lột vỏ tôm tươi, rút sạch chỉ lưng rồi cắt miếng vừa ăn; làm sạch mực ống, thái miếng vuông 1 cm. Cho tôm mực vào tô ướp với 5 ml nước mắm ngon, 2 g hạt nêm, một nửa lượng tiêu đen xay và một phần nhỏ hành tím băm trong 10 phút cho thấm vị.', NULL, 10),
('imp-806780abda4b5205_v4_step_2', 'imp-806780abda4b5205', 2, 'prep', 'Sơ chế dứa chín, rau củ và đánh tơi cơm nguội', 'Khoét lấy phần thịt dứa từ 1/2 quả dứa chín (giữ lại vỏ làm bát đựng nếu thích), bỏ lõi cứng, cắt hạt lựu nhỏ rồi ép nhẹ cho ráo bớt nước. Thái hạt lựu nhỏ cà rốt và đậu cô ve; băm nhỏ tỏi, phần hành tím còn lại và thái nhỏ hành lá. Đánh tơi 540 g cơm nguội với 3 g bột cà ri để cơm lên màu vàng đều.', 'Vắt nhẹ phần dứa cắt hạt lựu cho ráo nước giúp cơm khi rang luôn tơi khô mà không bị nhão.', NULL),
('imp-806780abda4b5205_v4_step_3', 'imp-806780abda4b5205', 3, 'cook', 'Xào nhanh tôm mực chín săn và rau củ giòn ngọt', 'Làm nóng 10 ml dầu ăn trên lửa lớn, phi thơm một nửa lượng tỏi và hành tím băm. Cho tôm và mực vào đảo nhanh khoảng 2 phút đến khi tôm chuyển màu đỏ hồng, thịt mực săn trắng chín hoàn toàn thì trút riêng ra đĩa. Tận dụng chảo nóng đảo nhanh cà rốt và đậu cô ve thêm 2 phút cho chín tới rồi cho ra đĩa cùng hải sản.', 'Xào hải sản trên lửa lớn và vớt ra sớm giúp tôm mực giữ độ giòn ngọt tự nhiên, không bị ra nước và dai.', 4),
('imp-806780abda4b5205_v4_step_4', 'imp-806780abda4b5205', 4, 'cook', 'Chiên trứng và rang tơi cơm nguội với bột cà ri', 'Cho 15 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi và hành tím băm còn lại. Đập 2 quả trứng gà vào khuấy tơi trên lửa vừa, ngay khi trứng vừa sệt lại thì trút toàn bộ cơm nguội đã trộn bột cà ri vào. Vặn lửa lớn, đảo đều liên tục khoảng 4 phút cho từng hạt cơm săn tơi và quyện đều trứng.', NULL, 4),
('imp-806780abda4b5205_v4_step_5', 'imp-806780abda4b5205', 5, 'cook', 'Trộn dứa chín, hải sản và nêm vị đậm đà', 'Cho phần thịt dứa cắt hạt lựu vào chảo cơm đảo đều 1 phút, nêm 15 ml nước mắm ngon, 4 g đường cát trắng và 2 g hạt nêm còn lại. Tiếp tục trút đĩa tôm mực cùng cà rốt, đậu cô ve vào đảo nhanh trên lửa lớn 2 phút cho mọi nguyên liệu quyện đều và nóng hổi.', 'Cho dứa vào gần cuối giúp miếng dứa giữ được độ mọng giòn và vị chua ngọt tươi mát.', 2),
('imp-806780abda4b5205_v4_step_6', 'imp-806780abda4b5205', 6, 'finish', 'Rắc hành lá, hạt điều rang và trình bày', 'Tắt bếp, rắc hành lá thái nhỏ và phần tiêu đen xay còn lại vào đảo đều một lượt. Múc cơm chiên dứa hải sản vào lòng quả dứa hoặc ra đĩa lớn, rắc hạt điều rang chín giã dập lên trên và thưởng thức nóng.', NULL, NULL),
('imp-a48b19224e397cea_v4_step_1', 'imp-a48b19224e397cea', 1, 'prep', 'Sơ chế thịt bò thái mỏng, hành tây và gừng', 'Thái 250 g thịt bò thành lát thật mỏng dày khoảng 1,5 mm rồi cắt đoạn dài 4–5 cm; thái múi mỏng 1 củ hành tây theo chiều dọc; mài nhuyễn 8 g gừng tươi và thái khoanh mỏng 1/2 bó hành lá. Giữ ấm sẵn 360 g cơm gạo Nhật nấu chín.', 'Nếu tự thái thịt bò tại nhà, đặt khối thịt vào ngăn đá 30 phút cho hơi se cứng lại sẽ giúp cắt được những lát thịt mỏng đều dễ dàng.', NULL),
('imp-a48b19224e397cea_v4_step_2', 'imp-a48b19224e397cea', 2, 'cook', 'Luộc nhanh trứng lòng đào ăn kèm (tùy chọn)', 'Nếu dùng trứng ăn kèm, đun sôi nhẹ nồi nước nhỏ, nhẹ nhàng thả 2 quả trứng gà lạnh vào luộc đúng 6 phút trên lửa vừa, sau đó vớt ngay sang bát nước đá ngâm 5 phút cho nguội hẳn rồi bóc sạch vỏ.', NULL, 6),
('imp-a48b19224e397cea_v4_step_3', 'imp-a48b19224e397cea', 3, 'sauce', 'Đun sôi nước sốt và nấu mềm ngọt hành tây', 'Cho 120 ml nước dùng Dashi, 45 ml rượu Sake nấu ăn, 35 ml nước tương Nhật, 15 ml rượu ngọt Mirin và 12 g đường cát trắng vào chảo sâu lòng trên lửa vừa, khuấy tan đường. Khi nước sốt sôi nhẹ, thả toàn bộ hành tây vào nấu khoảng 5 phút cho đến khi hành mềm trong và ngấm vị.', 'Nấu mềm hành tây trước giúp hành tiết trọn vị ngọt vào nước dùng mà không cần đun thịt bò quá lâu.', 5),
('imp-a48b19224e397cea_v4_step_4', 'imp-a48b19224e397cea', 4, 'cook', 'Om nhanh thịt bò thái mỏng đến vừa chín tới', 'Dàn đều các lát thịt bò vào chảo nước sốt đang sôi lăn tăn trên lửa vừa, dùng đũa tách tơi các lát thịt để chín đều. Nấu khoảng 3–4 phút, thường xuyên hớt sạch bọt nổi lên mặt nước để nước sốt trong đẹp và thịt vừa chín tới không còn màu đỏ tái.', 'Thịt bò thái mỏng rất nhanh chín; tránh đun quá 5 phút khiến thịt bị co cứng, dai và mất nước ngọt.', 4),
('imp-a48b19224e397cea_v4_step_5', 'imp-a48b19224e397cea', 5, 'cook', 'Thêm gừng mài nhuyễn dậy hương thơm', 'Cho 8 g gừng tươi mài nhuyễn vào chảo thịt bò, đảo nhẹ cho hòa quyện vào nước sốt và nấu thêm 1 phút trên lửa nhỏ để gừng tỏa hương thơm dịu mà không bị nồng gắt rồi tắt bếp.', NULL, 1),
('imp-a48b19224e397cea_v4_step_6', 'imp-a48b19224e397cea', 6, 'finish', 'Bày tô cơm Gyudon nóng và thưởng thức', 'Xới 360 g cơm gạo Nhật vào hai tô sâu lòng, gắp thịt bò cùng hành tây xếp phủ đều lên cơm, chan thêm vài muỗng nước sốt om cho thấm vị. Rắc hành lá thái khoanh lên trên và đặt thêm nửa quả trứng lòng đào nếu thích, dọn ăn ngay khi còn nóng.', NULL, NULL),
('imp-79819e1b0c75f4da_v4_step_1', 'imp-79819e1b0c75f4da', 1, 'prep', 'Sơ chế rau củ, thịt ba chỉ và pha hỗn hợp sốt', 'Thái lát mỏng 160 g thịt ba chỉ heo cắt đoạn 3 cm; cắt 1/4 bắp cải xanh thành miếng vuông 2,5 cm; thái múi 1/2 củ hành tây; thái sợi 1/2 củ cà rốt; thái lát 40 g nấm hương tươi và cắt khúc 1 bó hành lá. Khuấy đều 30 ml nước tương Nhật, 15 ml rượu Sake nấu ăn và 10 ml rượu ngọt Mirin trong bát nhỏ.', NULL, NULL),
('imp-79819e1b0c75f4da_v4_step_2', 'imp-79819e1b0c75f4da', 2, 'prep', 'Chần nhanh sợi mì Udon cho tơi mềm', 'Đun sôi nồi nước trên lửa lớn, thả 2 gói mì Udon tươi vào chần nhanh khoảng 40 giây đến 1 phút vừa đủ để các sợi mì tách tơi ra, lập tức vớt ra rổ để thật ráo nước.', 'Mì udon tươi đã chín sẵn nên chỉ cần chần thoáng dưới 1 phút; chần quá lâu sợi mì sẽ bị bở và đứt gãy khi xào.', 1),
('imp-79819e1b0c75f4da_v4_step_3', 'imp-79819e1b0c75f4da', 3, 'cook', 'Xào thịt ba chỉ vàng xém cạnh', 'Làm nóng chảo sâu lòng trên lửa vừa với 15 ml dầu ăn thực vật. Cho thịt ba chỉ vào xào, rắc 1 g muối ăn và 1 g tiêu đen xay, đảo đều khoảng 4 phút đến khi thịt ra bớt mỡ, xém vàng nhẹ các mép và chín kỹ hoàn toàn.', 'Xào cho thịt ba chỉ hơi xém vàng giúp mỡ thừa tiết ra làm nền xào rau củ thơm béo đậm đà.', 4),
('imp-79819e1b0c75f4da_v4_step_4', 'imp-79819e1b0c75f4da', 4, 'cook', 'Xào và om chín mềm bắp cải cùng rau củ', 'Cho hành tây vào chảo đảo 1 phút cho dậy mùi, tiếp tục thả bắp cải xanh, cà rốt, nấm hương tươi và phần đầu hành lá vào đảo đều tay cho thấm mỡ thịt. Đậy nắp chảo và hạ lửa vừa nhỏ hấp nhẹ trong 3 phút để rau củ chín mềm mà vẫn giữ được độ giòn ngọt.', NULL, 3),
('imp-79819e1b0c75f4da_v4_step_5', 'imp-79819e1b0c75f4da', 5, 'cook', 'Xào mì Udon trên lửa lớn và rưới sốt áp thành chảo', 'Mở nắp, tăng lên lửa vừa lớn, trút mì Udon đã chần vào chảo và dùng kẹp gắp nâng đảo đều tay trong 2 phút. Rưới hỗn hợp nước sốt nước tương Nhật men theo thành chảo nóng, đảo thêm 2 phút cùng phần lá hành xanh đến khi sốt rút quyện bóng đều từng sợi mì rồi tắt bếp.', 'Dùng kẹp gắp thay vì đũa và rót nước tương dọc thành chảo nóng giúp sợi udon không bị đứt vụn mà lại dậy mùi thơm khói nhẹ đặc trưng.', 4),
('imp-79819e1b0c75f4da_v4_step_6', 'imp-79819e1b0c75f4da', 6, 'finish', 'Bày đĩa mì và rắc cá bào Katsuobushi', 'Gắp mì Yaki Udon nóng hổi chia đều ra hai đĩa, rắc thêm cá bào khô Katsuobushi lên trên để tăng độ đậm đà và dùng nóng ngay.', NULL, NULL),
('imp-ac255bcc36d1324e_v4_step_1', 'imp-ac255bcc36d1324e', 1, 'sauce', 'Pha hỗn hợp sốt Teriyaki hương gừng tỏi', 'Trong bát chịu nhiệt, cho 60 ml nước tương Nhật, 30 ml rượu Sake nấu ăn (một nửa lượng chuẩn bị), 30 ml rượu ngọt Mirin, 24 g đường cát trắng cùng 10 g gừng tươi băm và 1/2 củ tỏi băm nhuyễn. Khuấy đều cho đường tan hoàn toàn hoặc làm ấm nhẹ 30 giây để gia vị hòa quyện.', NULL, NULL),
('imp-ac255bcc36d1324e_v4_step_2', 'imp-ac255bcc36d1324e', 2, 'prep', 'Thấm khô, ướp muối tiêu và áo bột mì cho cá hồi', 'Dùng khăn giấy thấm thật khô bề mặt 600 g phi lê cá hồi còn da, rắc đều 2 g muối ăn và 1 g tiêu đen xay lên cả hai mặt. Tiếp theo rắc đều 16 g bột mì đa dụng phủ mỏng hai mặt cá, vỗ nhẹ cho bột bám sát rồi giũ bỏ phần bột thừa.', 'Lớp bột mì mỏng đóng vai trò khóa nước ngọt trong thịt cá hồi, đồng thời giúp sốt Teriyaki tự sánh quyện mà không cần pha thêm bột năng.', NULL),
('imp-ac255bcc36d1324e_v4_step_3', 'imp-ac255bcc36d1324e', 3, 'cook', 'Áp chảo mặt da cá hồi vàng giòn với dầu và bơ', 'Làm nóng chảo chống dính lớn trên lửa vừa với 15 ml dầu ăn trung tính và 25 g bơ lạt. Khi bơ vừa tan sủi bọt, đặt từng miếng cá hồi mặt da úp xuống chảo, dùng xẻng ép nhẹ 15 giây cho mặt da áp sát đáy chảo rồi chiên khoảng 3 phút đến khi da cá vàng giòn và phần thịt chín dần lên quá nửa thân cá thì lật mặt.', NULL, 3),
('imp-ac255bcc36d1324e_v4_step_4', 'imp-ac255bcc36d1324e', 4, 'cook', 'Rưới rượu Sake hấp chín mềm lõi cá hồi', 'Rưới 30 ml rượu Sake nấu ăn còn lại vào chảo, đậy kín vung và hạ xuống lửa nhỏ hấp thêm 3–4 phút cho đến khi thịt cá hồi chuyển màu hồng nhạt đục đều và chín tới mềm ẩm. Nhẹ nhàng gắp cá ra đĩa riêng và lau sạch phần mỡ cháy thừa trong chảo.', 'Không đậy vung hấp quá lâu khiến cá hồi bị khô xác; thịt cá vừa chuyển đục và tách thớ nhẹ khi ấn là đạt.', 4),
('imp-ac255bcc36d1324e_v4_step_5', 'imp-ac255bcc36d1324e', 5, 'cook', 'Cô sánh sốt Teriyaki và áo bóng lên cá hồi', 'Đổ toàn bộ bát sốt Teriyaki vào chảo nóng trên lửa vừa, khi sốt bắt đầu sôi sủi bọt đều thì đặt cá hồi trở lại chảo. Nghiêng chảo và liên tục múc sốt rưới lên từng miếng cá khoảng 2 phút cho đến khi sốt cô sánh lại thành lớp men nâu bóng bám đẹp quanh miếng cá rồi tắt bếp.', 'Tắt bếp ngay khi sốt vừa sánh nhẹ vì khi nguội bớt sốt Teriyaki sẽ tiếp tục cô đặc và bám bóng đẹp hơn.', 2),
('imp-ac255bcc36d1324e_v4_step_6', 'imp-ac255bcc36d1324e', 6, 'finish', 'Trình bày cá hồi sốt Teriyaki và dùng nóng', 'Xếp các miếng cá hồi ra đĩa lớn với mặt da giòn quay lên trên, rưới nốt phần sốt Teriyaki sánh bóng trong chảo lên mặt cá, rắc hành lá thái nhỏ và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-bb07db73fb381724_v4_step_1', 'imp-bb07db73fb381724', 1, 'prep', 'Làm lạnh sâu và thấm nhẹ nước cho đậu phụ non', 'Giữ 350 g đậu phụ non trong ngăn mát tủ lạnh đến sát giờ chế biến. Nhẹ nhàng lấy khối đậu ra khỏi hộp, gói lỏng trong hai lớp khăn giấy sạch đặt lên đĩa khoảng 5 phút để thấm bớt phần nước đọng bề mặt mà không làm nát đậu.', 'Tuyệt đối không dùng vật nặng ép đậu phụ non vì sẽ làm vỡ cấu trúc mềm mịn đặc trưng của món Hiyayakko.', 5),
('imp-bb07db73fb381724_v4_step_2', 'imp-bb07db73fb381724', 2, 'prep', 'Mài nhuyễn gừng tươi và chuẩn bị rau gia vị', 'Gọt sạch vỏ 15 g gừng tươi, dùng bàn mài nhuyễn mịn và giữ lại cả phần nước gừng tiết ra. Rửa sạch 1/2 bó hành lá tươi, vẩy ráo nước rồi thái khoanh thật mỏng; nếu dùng rong biển khô Nori thì cắt thành sợi nhỏ.', NULL, NULL),
('imp-bb07db73fb381724_v4_step_3', 'imp-bb07db73fb381724', 3, 'sauce', 'Pha hỗn hợp nước tương dầu mè', 'Trong chén nhỏ, khuấy đều 20 ml nước tương Nhật cùng 5 ml dầu mè rang đến khi hòa quyện hoàn toàn, giữ sẵn để rưới trực tiếp trước lúc ăn.', NULL, NULL),
('imp-bb07db73fb381724_v4_step_4', 'imp-bb07db73fb381724', 4, 'prep', 'Cắt khối đậu phụ và xếp ra đĩa sâu lòng', 'Gỡ bỏ khăn giấy, nhúng lưỡi dao mỏng qua nước lọc cho trơn rồi cắt khối đậu phụ non thành 6 hoặc 8 miếng vuông vừa ăn. Dùng xẻng rộng bản nhẹ tay nhấc từng khối đậu xếp vào hai đĩa sâu lòng hoặc bát nhỏ.', 'Nhúng ướt dao trước khi cắt giúp lát cắt đậu phụ sắc nét, bóng mịn và không dính mặt dao.', NULL),
('imp-bb07db73fb381724_v4_step_5', 'imp-bb07db73fb381724', 5, 'finish', 'Phủ gia vị lên mặt đậu và ướp lạnh nhẹ', 'Nghiêng nhẹ đĩa đổ bỏ phần nước vừa tiết thêm từ đậu phụ trong 2 phút chờ. Lần lượt đặt gừng tươi mài nhuyễn, hành lá thái mỏng lên chính giữa từng miếng đậu, rắc cá bào khô Katsuobushi, hạt mè trắng rang và rong biển khô Nori lên trên.', NULL, 2),
('imp-bb07db73fb381724_v4_step_6', 'imp-bb07db73fb381724', 6, 'finish', 'Rưới sốt nước tương ngay tại bàn và thưởng thức', 'Rưới đều hỗn hợp nước tương Nhật và dầu mè rang quanh các miếng đậu phụ ngay trước khi ăn để giữ đậu luôn mát lạnh, không bị ngấm mặn quá sớm.', 'Nghiêng nhẹ đĩa chắt bỏ nước đậu thừa một lần nữa ngay trước lúc rưới sốt giúp hương vị đậm đà không bị loãng.', NULL),
('imp-a9398d96945ba6f7_v4_step_1', 'imp-a9398d96945ba6f7', 1, 'prep', 'Sơ chế kim chi, thịt ba chỉ và rau nấm', 'Cắt 450 g kim chi cải thảo ủ chua thành khúc dài 3–4 cm, giữ lại phần nước kim chi. Thái thịt ba chỉ heo thành miếng dày 0,5 cm rồi ướp nhẹ với 15 ml rượu ngọt Mirin và 1 g tiêu đen xay trong 10 phút. Thái lát hành tây, nấm đùi gà tươi, đậu phụ trắng mềm và cắt khúc hành lá tươi.', NULL, 10),
('imp-a9398d96945ba6f7_v4_step_2', 'imp-a9398d96945ba6f7', 2, 'cook', 'Xào thịt ba chỉ và kim chi cho săn thơm', 'Làm nóng nồi đáy dày hoặc nồi đất trên lửa vừa với 5 ml dầu mè rang, cho thịt ba chỉ heo vào đảo 3 phút đến khi thịt săn chín mặt và tươm mỡ nhẹ. Thêm tỏi khô băm nhỏ, hành tây và kim chi cải thảo vào xào chung 4 phút cho kim chi mềm dịu và thấm mỡ thịt.', 'Xào kỹ kim chi trước khi đổ nước dùng giúp vị chua gắt dịu xuống và nước canh thơm sâu hơn.', NULL),
('imp-a9398d96945ba6f7_v4_step_3', 'imp-a9398d96945ba6f7', 3, 'cook', 'Nấu nước dùng và hòa gia vị cay đậm', 'Cho 6 g ớt bột Hàn Quốc (Gochugaru), 15 g tương ớt Hàn Quốc (Gochujang), 15 ml nước tương, 8 g đường cát trắng và phần nước kim chi vào nồi đảo nhanh 30 giây, sau đó rót 600 ml nước dùng cá cơm tảo bẹ vào đun sôi trên lửa lớn.', NULL, 5),
('imp-a9398d96945ba6f7_v4_step_4', 'imp-a9398d96945ba6f7', 4, 'cook', 'Hầm liu riu cho thịt mềm và thấm vị', 'Khi nồi canh sôi bùng, hớt bớt bọt nổi rồi hạ xuống lửa vừa-nhỏ, đậy hé nắp hầm khoảng 12 phút để thịt ba chỉ chín mềm hoàn toàn và vị ngọt của kim chi hòa quyện vào nước canh. Nêm thêm 3 g muối ăn và điều chỉnh lại theo khẩu vị.', NULL, 12),
('imp-a9398d96945ba6f7_v4_step_5', 'imp-a9398d96945ba6f7', 5, 'cook', 'Thả nấm đùi gà và đậu phụ trắng', 'Cho nấm đùi gà tươi và xếp nhẹ từng lát đậu phụ trắng mềm lên mặt nồi canh, nấu thêm 4 phút trên lửa vừa để nấm chín ngọt và đậu phụ nóng ấm mà không bị nát vụn.', 'Không khuấy mạnh tay sau khi đã thả đậu phụ để giữ nguyên dáng miếng đậu vuông đẹp mắt.', 4),
('imp-a9398d96945ba6f7_v4_step_6', 'imp-a9398d96945ba6f7', 6, 'finish', 'Rắc hành lá, rưới dầu mè và dọn nóng', 'Thả hành lá tươi cắt khúc vào nồi nấu thêm 30 giây, tắt bếp rồi rưới 5 ml dầu mè rang còn lại lên trên và dọn nóng ngay cùng cơm trắng.', 'Chỉ rưới phần dầu mè rang còn lại sau khi tắt bếp để giữ nguyên hương thơm nồng nàn đặc trưng.', NULL),
('imp-af8a9cdb17d5e9fd_v4_step_1', 'imp-af8a9cdb17d5e9fd', 1, 'prep', 'Sơ chế rau củ và thái mỏng thịt bò', 'Thái 420 g thịt bò thăn thành lát thật mỏng khoảng 2–3 mm theo chiều ngang thớ. Bóc vỏ hành tây thái múi cau mỏng, gọt vỏ cà rốt thái lát vát mỏng 0,3 cm, rửa sạch hành lá tươi và cắt khúc 4 cm.', 'Để miếng thịt bò vào ngăn đá khoảng 20 phút cho hơi cứng mặt sẽ giúp bạn thái lát cực mỏng và đều tay.', NULL),
('imp-af8a9cdb17d5e9fd_v4_step_2', 'imp-af8a9cdb17d5e9fd', 2, 'marinate', 'Ướp thịt bò với sốt Bulgogi', 'Trong tô lớn, trộn tan 36 ml nước tương, 22 g đường nâu, 15 ml rượu ngọt Mirin, 10 ml dầu mè rang, tỏi khô băm nhuyễn, gừng tươi băm nhuyễn và 1 g tiêu đen xay. Cho thịt bò thái lát cùng một nửa lượng hành tây vào bóp nhẹ cho thấm đều gia vị, bọc kín ướp tối thiểu 20 phút.', 'Ướp cùng một phần hành tây và gừng giúp enzyme tự nhiên làm thịt bò mềm ngọt hơn khi xào.', 20),
('imp-af8a9cdb17d5e9fd_v4_step_3', 'imp-af8a9cdb17d5e9fd', 3, 'cook', 'Xào sơ cà rốt và hành tây giữ độ giòn', 'Làm nóng chảo rộng trên lửa lớn với 7 ml dầu thực vật, cho cà rốt và phần hành tây còn lại vào đảo nhanh tay 2 phút đến khi cà rốt vừa chín tới và hành tây thơm ngọt rồi trút tạm ra đĩa.', NULL, 2),
('imp-af8a9cdb17d5e9fd_v4_step_4', 'imp-af8a9cdb17d5e9fd', 4, 'cook', 'Áp chảo thịt bò Bulgogi trên lửa lớn', 'Thêm 8 ml dầu thực vật còn lại vào chảo đang nóng già, trải đều thịt bò đã ướp lên mặt chảo trên lửa lớn để thịt xém cạnh nhanh mà không bị tiết nhiều nước. Đảo đều tay khoảng 3–4 phút cho đến khi thịt chín đều chuyển màu nâu bóng hấp dẫn.', 'Không cho quá nhiều thịt cùng lúc nếu chảo nhỏ; có thể chia làm 2 mẻ xào để thịt giữ được độ săn và mùi thơm áp chảo.', 4),
('imp-af8a9cdb17d5e9fd_v4_step_5', 'imp-af8a9cdb17d5e9fd', 5, 'cook', 'Đảo chung rau củ và hành lá', 'Trút đĩa cà rốt, hành tây đã xào sơ cùng hành lá tươi cắt khúc vào chảo thịt bò, đảo nhanh tay thêm 1 phút trên lửa lớn cho toàn bộ nguyên liệu quyện đều phần nước sốt Bulgogi sánh nhẹ dưới đáy chảo.', NULL, NULL),
('imp-af8a9cdb17d5e9fd_v4_step_6', 'imp-af8a9cdb17d5e9fd', 6, 'finish', 'Hoàn thiện với dầu mè và hạt mè rang', 'Tắt bếp, rưới 5 ml dầu mè rang còn lại và rắc 8 g hạt mè trắng rang lên khắp mặt chảo, đảo nhẹ một lượt rồi trút ra đĩa thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-d3d0c59e0cfa845d_v4_step_1', 'imp-d3d0c59e0cfa845d', 1, 'prep', 'Thái kim chi và pha nước chấm xì dầu giấm', 'Vắt nhẹ 180 g kim chi cải thảo chín lấy khoảng 45 ml nước kim chi để riêng, phần cái thái nhỏ cỡ 1 cm. Thái mỏng hành tây và cắt khúc 3 cm hành lá tươi. Trong chén nhỏ, khuấy tan 20 ml nước tương, 10 ml giấm gạo, 3 g đường cát trắng và 3 g hạt mè trắng rang làm nước chấm.', 'Dùng kim chi đã ủ chua kỹ sẽ cho hương vị đậm đà và độ giòn sần sật hấp dẫn nhất khi chiên.', NULL),
('imp-d3d0c59e0cfa845d_v4_step_2', 'imp-d3d0c59e0cfa845d', 2, 'sauce', 'Trộn bột bánh với nước lạnh và kim chi', 'Trộn đều 140 g bột mì đa dụng, 20 g bột bắp và 3 g ớt bột Hàn Quốc (Gochugaru) trong tô lớn. Rót từ từ 220 ml nước lọc lạnh cùng 45 ml nước kim chi vào, đánh nhẹ vừa đủ tan hết bột khô rồi cho 1 quả trứng gà tươi, kim chi thái nhỏ, hành tây và hành lá vào trộn đều thành hỗn hợp bột hơi sánh.', 'Dùng nước lọc thật lạnh và không khuấy bột quá kỹ giúp bánh chiên lên giòn xốp, không bị dai.', NULL),
('imp-d3d0c59e0cfa845d_v4_step_3', 'imp-d3d0c59e0cfa845d', 3, 'cook', 'Chiên bánh mẻ thứ nhất đến khi giòn cạnh', 'Làm nóng chảo chống dính đường kính 22–24 cm trên lửa vừa-lớn với 22 ml dầu thực vật, múc một nửa lượng bột dàn thành lớp mỏng đều khắp mặt chảo. Chiên khoảng 4 phút đến khi phần viền vàng giòn rụm và mặt bột bên trên se lại.', NULL, 4),
('imp-d3d0c59e0cfa845d_v4_step_4', 'imp-d3d0c59e0cfa845d', 4, 'cook', 'Lật mặt và chiên vàng giòn hoàn toàn', 'Lật khéo chiếc bánh lại, ấn nhẹ bằng xẻng chiên cho bánh áp sát mặt chảo và chiên tiếp 3 phút trên lửa vừa đến khi cả hai mặt vàng ruộm, dậy mùi thơm lừng rồi gắp ra đĩa lót giấy thấm dầu.', 'Ấn nhẹ mặt bánh sau khi lật giúp hơi nước thoát nhanh, mặt bánh phẳng và giòn đều từ tâm ra viền.', 3),
('imp-d3d0c59e0cfa845d_v4_step_5', 'imp-d3d0c59e0cfa845d', 5, 'cook', 'Chiên nốt mẻ bánh kim chi thứ hai', 'Cho 23 ml dầu thực vật còn lại vào chảo, trút hết phần bột kim chi còn lại dàn mỏng đều và lặp lại quy trình chiên mỗi mặt 3–4 phút cho đến khi bánh chín vàng giòn đều hai mặt.', NULL, 7),
('imp-d3d0c59e0cfa845d_v4_step_6', 'imp-d3d0c59e0cfa845d', 6, 'finish', 'Cắt miếng tam giác và thưởng thức nóng', 'Đặt bánh kim chi chiên giòn lên thớt sạch, cắt thành từng miếng tam giác hoặc ô vuông vừa ăn, xếp ra đĩa và dọn nóng kèm chén nước chấm xì dầu giấm gạo mè rang.', NULL, NULL),
('imp-262caf09e6f38c59_v4_step_1', 'imp-262caf09e6f38c59', 1, 'prep', 'Sơ chế bông cải xanh và hương liệu', 'Tách 1,5 bông cải xanh thành các nhánh hoa cỡ vừa đồng đều để khi nấu chín cùng lúc; gọt bỏ lớp xơ cứng ở phần thân cọng rồi rửa sạch và để ráo. Tỏi khô băm nhỏ, gừng tươi băm thật nhuyễn.', 'Cắt các nhánh bông cải có kích thước tương đương nhau giúp rau chín đều, không bị chỗ sượng chỗ mềm nhũn.', NULL),
('imp-262caf09e6f38c59_v4_step_2', 'imp-262caf09e6f38c59', 2, 'sauce', 'Pha chén sốt xì dầu bột bắp', 'Cho vào chén nhỏ 30 ml nước lọc, 22 ml xì dầu nhạt, 3 ml xì dầu đặc, 4 g đường cát trắng, 4 g bột bắp và 1 g muối ăn (tùy khẩu vị). Khuấy đều tay đến khi đường và bột bắp tan hoàn toàn, để sẵn cạnh bếp.', 'Luôn khuấy lại chén sốt ngay trước khi rót vào chảo vì bột bắp rất nhanh lắng xuống đáy.', NULL),
('imp-262caf09e6f38c59_v4_step_3', 'imp-262caf09e6f38c59', 3, 'cook', 'Chần bông cải xanh giữ màu giòn mướt', 'Đun sôi mạnh 1000 ml nước lọc với 2 g muối ăn và 5 ml dầu ăn thực vật trong nồi lớn. Thả toàn bộ bông cải xanh vào chần đúng 1 phút trên lửa lớn cho rau vừa chuyển màu xanh ngọc rực rỡ, lập tức vớt ra rổ thưa xóc thật ráo nước.', 'Một chút dầu ăn và muối trong nước sôi giúp khóa màu xanh mướt cho bông cải và rút ngắn tối đa thời gian xào trên chảo.', 1),
('imp-262caf09e6f38c59_v4_step_4', 'imp-262caf09e6f38c59', 4, 'cook', 'Phi thơm tỏi gừng trên chảo nóng', 'Đặt chảo sâu lòng lên lửa vừa lớn, làm nóng 20 ml dầu ăn thực vật còn lại. Cho gừng băm và tỏi băm vào đảo nhanh khoảng 30 giây đến khi dậy mùi thơm dịu và tỏi vừa chuyển vàng nhẹ, tuyệt đối không để tỏi cháy sậm.', NULL, NULL),
('imp-262caf09e6f38c59_v4_step_5', 'imp-262caf09e6f38c59', 5, 'cook', 'Xào bông cải với sốt lửa lớn', 'Trút bông cải xanh đã ráo nước vào chảo, tăng lửa lớn và đảo nhanh tay trong 1 phút. Khuấy đều chén sốt đã pha rồi rót vòng quanh chảo, tiếp tục xóc đảo liên tục thêm 1 phút cho đến khi sốt sôi sệt, trong bóng và bám đều quanh từng nhánh bông cải.', NULL, 2),
('imp-262caf09e6f38c59_v4_step_6', 'imp-262caf09e6f38c59', 6, 'finish', 'Rưới dầu mè và hoàn thiện', 'Tắt bếp ngay khi sốt vừa áo bóng, rưới 5 ml dầu mè thơm lên trên rồi đảo đều một lượt cuối cùng. Gắp bông cải ra đĩa và dùng nóng ngay để cảm nhận trọn vẹn độ giòn ngọt.', NULL, NULL),
('imp-352999f711c710d9_v4_step_1', 'imp-352999f711c710d9', 1, 'prep', 'Sơ chế hương liệu và thái thịt đùi gà', 'Thấm khô 500 g thịt đùi gà lọc xương rồi thái miếng vuông đều 2,5 cm. Gọt vỏ 45 g gừng tươi già: bào nhuyễn 5 g để ướp thịt, 40 g còn lại thái lát mỏng. Hành lá tươi cắt khúc 5 cm tách riêng đầu hành trắng đập dập và phần lá xanh; đập dập 4 tép tỏi khô và 2 củ hành tím khô; thái lát vát 1 quả ớt sừng đỏ (nếu dùng).', NULL, NULL),
('imp-352999f711c710d9_v4_step_2', 'imp-352999f711c710d9', 2, 'marinate', 'Ướp thịt gà giữ ẩm với bột bắp', 'Cho thịt đùi gà vào tô cùng 15 ml rượu Thiệu Hưng, 10 ml xì dầu nhạt, 1,5 g muối ăn và 5 g gừng bào nhuyễn, bóp trộn đều đến khi thịt thấm hết phần nước gia vị rồi mới cho 12 g bột bắp vào trộn áo đều từng miếng. Ướp thịt trong 15 phút.', 'Trộn cho thịt ngậm hết nước gia vị trước rồi mới áo bột bắp giúp miếng gà khi áp chảo mềm mọng bên trong mà bề mặt vẫn xém đẹp.', 15),
('imp-352999f711c710d9_v4_step_3', 'imp-352999f711c710d9', 3, 'sauce', 'Pha chén sốt xì dầu dầu hào', 'Khuấy đều trong chén nhỏ 60 ml nước dùng gà, 20 ml xì dầu nhạt còn lại, 5 ml xì dầu đặc, 15 ml dầu hào, 4 g đường cát trắng, 4 g bột bắp còn lại và 1 g tiêu trắng xay đến khi tan mịn hoàn toàn.', 'Khuấy lại chén sốt ngay trước khi đổ vào chảo để bột bắp không bị lắng xuống đáy chén.', NULL),
('imp-352999f711c710d9_v4_step_4', 'imp-352999f711c710d9', 4, 'cook', 'Phi thơm gừng, tỏi và hành tím', 'Đun nóng chảo sâu lòng trên lửa vừa lớn đến khi hơi bốc khói, rót 20 ml dầu ăn thực vật tráng đều. Cho gừng thái lát vào đảo khoảng 1 phút đến khi cạnh gừng hơi xém vàng thơm nồng, tiếp tục cho tỏi khô, hành tím khô và đầu hành trắng đập dập vào đảo nhanh 20 giây.', NULL, 1),
('imp-352999f711c710d9_v4_step_5', 'imp-352999f711c710d9', 5, 'cook', 'Áp chảo gà chín xém hai mặt', 'Dàn đều thịt gà đã ướp thành một lớp mỏng trong chảo, giữ nguyên không đảo trong 2 phút để mặt dưới vàng xém đẹp rồi lật mặt áp tiếp 1–2 phút nữa đến khi thịt gà săn chắc hoàn toàn và không còn màu hồng bên trong. Rưới 25 ml rượu Thiệu Hưng còn lại quanh mép chảo, đảo nhanh tay cho hơi rượu bốc lên làm bong lớp cháy thơm đáy chảo.', 'Không xếp chồng miếng gà lên nhau khi áp chảo vì hơi nước sẽ làm thịt bị hấp mềm thay vì xém vàng thơm.', 4),
('imp-352999f711c710d9_v4_step_6', 'imp-352999f711c710d9', 6, 'finish', 'Quyện sốt sánh, thêm hành lá và hoàn thiện', 'Thả phần lá hành xanh và ớt sừng thái lát vào đảo 30 giây cho hành vừa mềm vẫn giữ sắc xanh. Khuấy lại chén sốt rồi rót đều vào chảo, đảo liên tục 30–45 giây trên lửa lớn đến khi sốt sánh bóng bám đều từng miếng gà. Tắt bếp, rưới 5 ml dầu mè thơm, đảo một lượt cuối và dọn nóng ăn kèm cơm trắng.', NULL, NULL),
('imp-b3f99919ea9f17f8_v4_step_1', 'imp-b3f99919ea9f17f8', 1, 'prep', 'Sơ chế bí đao và rau thơm', 'Gọt sạch vỏ xanh của bí đao tươi, nạo bỏ phần ruột xốp và hạt, rửa sạch rồi cắt thành từng miếng con chì dày khoảng 0,6 cm đều nhau để bí chín tới cùng lúc. Gừng tươi băm nhuyễn; hành lá tươi tách phần băm trộn thịt, phần đầu hành trắng để phi và lá xanh thái nhỏ; ngò rí tươi cắt khúc ngắn.', NULL, NULL),
('imp-b3f99919ea9f17f8_v4_step_2', 'imp-b3f99919ea9f17f8', 2, 'marinate', 'Ướp và quết thịt heo viên dai giòn', 'Cho 300 g thịt heo xay vào tô lớn cùng 25 ml xì dầu nhạt, 20 ml rượu Thiệu Hưng, 3 ml dầu mè thơm, 2/3 lượng tiêu trắng xay, 2 g đường cát trắng, 1,5 g muối ăn, lòng trắng của 1 quả trứng gà, 10 g gừng băm, 1/2 phần hành lá băm và 20 ml nước lọc. Dùng đũa quết mạnh tay theo đúng một chiều trong 8–10 phút đến khi thịt dẻo quánh, bám dính thành khối.', 'Quết thịt theo một chiều và thêm chút nước lọc giúp sợi thịt ngậm nước và liên kết đàn hồi, cho viên thịt mềm mọng mà vẫn giòn dai.', 8),
('imp-b3f99919ea9f17f8_v4_step_3', 'imp-b3f99919ea9f17f8', 3, 'prep', 'Vo viên thịt gọn đẹp', 'Thoa một lớp dầu mỏng vào lòng bàn tay hoặc dùng muỗng nhúng dầu, chia hỗn hợp thịt thành 12–16 viên tròn đường kính khoảng 2,5–3 cm rồi xếp lên đĩa phẳng, giữ mát trong khi nấu nước dùng để viên thịt giữ dáng chắc đẹp.', NULL, NULL),
('imp-b3f99919ea9f17f8_v4_step_4', 'imp-b3f99919ea9f17f8', 4, 'cook', 'Phi thơm đầu hành và nấu mềm bí đao', 'Làm nóng 10 ml dầu ăn thực vật trong nồi canh trên lửa vừa, thả phần đầu hành trắng vào xào thơm 1 phút cho dậy mùi. Đổ 650 ml nước dùng gà và 350 ml nước lọc vào nồi, thả bí đao vào đun sôi rồi hạ lửa vừa, nấu liu riu 8–10 phút đến khi miếng bí đao bắt đầu chuyển trong.', NULL, 9),
('imp-b3f99919ea9f17f8_v4_step_5', 'imp-b3f99919ea9f17f8', 5, 'cook', 'Thả thịt viên và nấu chín tới', 'Khi nước canh đang sôi nhẹ, nhẹ nhàng thả từng viên thịt vào nồi để viên thịt se mặt ngay và không bị vỡ nát. Hớt sạch bọt nổi trên mặt nước, đun liu riu thêm 4 phút đến khi toàn bộ thịt viên nổi hẳn lên mặt nước và chín chắc hoàn toàn bên trong, bí đao vừa trong mướt mà không bị nát bở.', 'Giữ lửa ở mức sôi lăn tăn sau khi thả viên giúp nước canh trong veo và viên thịt chín đều từ ngoài vào trong.', 4),
('imp-b3f99919ea9f17f8_v4_step_6', 'imp-b3f99919ea9f17f8', 6, 'finish', 'Nêm gia vị và hoàn thiện tô canh', 'Nêm vào nồi canh 3,5 g muối ăn còn lại (điều chỉnh theo độ mặn nước dùng), 1/3 lượng tiêu trắng xay còn lại và 2 ml dầu mè thơm, khuấy nhẹ rồi tắt bếp. Múc canh ra tô lớn, rắc lá hành xanh và ngò rí tươi lên mặt, dùng nóng ngay.', 'Rưới dầu mè thơm và tiêu trắng sau khi tắt bếp giúp giữ trọn hương thơm dịu mà không bị đắng.', NULL),
('imp-b6dae711698259d6_v4_step_1', 'imp-b6dae711698259d6', 1, 'prep', 'Sơ chế tôm sú và nhóm thảo mộc Thái', 'Rửa sạch 450 g tôm sú, tách riêng phần đầu và vỏ tôm để nấu nước dùng; phần thịt tôm chẻ dọc sống lưng rút sạch chỉ đen rồi để ráo trong ngăn mát. Đập dập 3 cây sả cắt khúc 4–5 cm, thái lát mỏng 35 g củ riềng tươi, xé bỏ gân 6 g lá chanh Thái, đập dập 3 quả ớt hiểm, bổ đôi 200 g nấm và cắt múi cau 2 quả cà chua.', 'Giữ lại đầu và vỏ tôm để xào gạch sẽ giúp nước dùng Tom Yum ngọt tự nhiên và có sắc cam óng mà không cần bột nêm.', NULL),
('imp-b6dae711698259d6_v4_step_2', 'imp-b6dae711698259d6', 2, 'cook', 'Phi vỏ đầu tôm và ninh nước dùng ngọt thanh', 'Làm nóng nồi trên lửa vừa lớn với 15 ml dầu ăn, trút toàn bộ đầu và vỏ tôm vào xào khoảng 3 phút, dùng muôi ấn nhẹ đầu tôm cho gạch tiết ra và vỏ chuyển đỏ au thơm lừng. Đổ 1200 ml nước lọc vào đun sôi rồi hạ lửa vừa, nấu liu riu 8 phút và hớt sạch bọt, sau đó vớt bỏ toàn bộ xác vỏ đầu tôm.', NULL, 8),
('imp-b6dae711698259d6_v4_step_3', 'imp-b6dae711698259d6', 3, 'cook', 'Hầm thảo mộc dậy hương thơm đặc trưng', 'Cho sả, riềng, lá chanh Thái và ớt hiểm đập dập vào nồi nước dùng tôm, đun sôi lăn tăn trên lửa nhỏ 5 phút để các loại thảo mộc tiết hết tinh dầu thơm nồng vào nước dùng.', 'Đun sôi nhẹ thay vì lửa quá lớn để giữ nước dùng trong thơm và thảo mộc không bị nồng gắt.', 5),
('imp-b6dae711698259d6_v4_step_4', 'imp-b6dae711698259d6', 4, 'cook', 'Nấu nấm, cà chua và hòa sốt Tom Yum', 'Múc một vá nước dùng nóng ra chén hòa tan 45 g sốt Tom Yum rồi đổ ngược lại vào nồi, nêm thêm 40 ml nước mắm ngon và 6 g đường cát trắng. Thả 200 g nấm cùng 2 quả cà chua bổ múi cau vào nấu thêm 3 phút trên lửa vừa đến khi nấm chín mềm và cà chua vừa tiết vị chua dịu.', NULL, 3),
('imp-b6dae711698259d6_v4_step_5', 'imp-b6dae711698259d6', 5, 'cook', 'Nấu tôm chín hồng vừa tới giữ độ giòn ngọt', 'Tăng lửa cho nồi canh sôi đều trở lại, thả phần thịt tôm đã sơ chế vào nấu nhanh khoảng 2 phút đến khi tôm cuộn cong, vỏ đuôi đỏ au và thịt tôm chuyển đục săn chắc chín hoàn toàn thì tắt bếp ngay.', 'Nấu tôm vừa chín tới rồi tắt bếp ngay để thịt tôm giữ được độ giòn mọng tự nhiên, không bị khô xác.', 2),
('imp-b6dae711698259d6_v4_step_6', 'imp-b6dae711698259d6', 6, 'finish', 'Vắt chanh tươi, rắc ngò rí và hoàn thiện tô canh', 'Chờ nồi canh hết sôi hẳn mới rót nước cốt từ 2 quả chanh tươi vào khuấy nhẹ để giữ trọn hương thơm và không bị đắng. Nếm lại cho đạt vị chua thanh dẫn đầu, mặn cay hài hòa rồi múc ra tô, rắc 20 g ngò rí thái khúc lên trên và dọn nóng.', NULL, NULL),
('imp-f729957329cd75f5_v4_step_1', 'imp-f729957329cd75f5', 1, 'prep', 'Ngâm bánh phở và chuẩn bị nguyên liệu', 'Ngâm 240 g bánh phở khô trong nước nguội 45 phút đến khi sợi mềm dẻo nhưng vẫn còn độ dai nhẹ khi bẻ cong, vớt ra để thật ráo nước rồi cắt đôi cho dễ đảo. Ngâm 70 g me chín với 100 ml nước ấm rồi dằm lọc bỏ hạt lấy nước cốt. Băm nhỏ 15 g tôm khô, 50 g hành tím, 1/2 củ tỏi; cắt hạt lựu 1,5 miếng đậu phụ; cắt khúc 4 cm phần 80 g hẹ lá; giã thô 60 g đậu phộng rang và bổ múi cau 2 quả chanh tươi.', 'Ngâm bánh phở bằng nước nguội thay vì luộc nước sôi giúp sợi mì giữ độ dai bóng và không bị bết nát khi xào.', 45),
('imp-f729957329cd75f5_v4_step_2', 'imp-f729957329cd75f5', 2, 'sauce', 'Nấu sốt me đường thốt nốt chua ngọt', 'Cho 60 g đường thốt nốt băm nhỏ vào nồi nhỏ đun lửa vừa, khuấy liên tục đến khi đường tan chảy và hơi chuyển màu nâu caramen thơm dịu. Tắt bếp rồi rót nước cốt me đã lọc cùng 45 ml nước mắm ngon vào khuấy tan đều thành hỗn hợp sốt sánh mượt màu hổ phách.', 'Thắng nhẹ đường thốt nốt trước khi cho nước cốt me giúp sốt Pad Thai có mùi thơm sâu và màu hổ phách bóng đẹp.', 4),
('imp-f729957329cd75f5_v4_step_3', 'imp-f729957329cd75f5', 3, 'cook', 'Áp chảo tôm chín săn và giữ riêng', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, xếp 350 g tôm tươi vào áp chảo mỗi mặt khoảng 1 phút đến khi tôm chuyển màu hồng cam, cong săn và chín hoàn toàn bên trong thì gắp ra đĩa riêng, giữ lại dầu thơm trong chảo.', NULL, 2),
('imp-f729957329cd75f5_v4_step_4', 'imp-f729957329cd75f5', 4, 'cook', 'Xào vàng đậu phụ và hương liệu', 'Vẫn chiếc chảo đó trên lửa vừa, thêm 25 ml dầu ăn rồi cho đậu phụ cắt hạt lựu, hành tím băm, tỏi băm, tôm khô băm và 2 g ớt khô vảy vào đảo đều 3 phút đến khi đậu phụ vàng cạnh và dậy mùi thơm.', NULL, 3),
('imp-f729957329cd75f5_v4_step_5', 'imp-f729957329cd75f5', 5, 'cook', 'Xào bánh phở ngấm sốt và đánh tơi trứng', 'Tăng lửa lớn, trút bánh phở đã ráo và toàn bộ nước sốt me vào chảo, đảo liên tục 3 phút cho sợi mì hút trọn nước sốt và tơi bóng (nếu mì còn hơi cứng có thể rưới thêm 1–2 muỗng canh nước lọc). Gạt mì sang một bên chảo, thêm 10 ml dầu ăn còn lại vào khoảng trống, đập 3 quả trứng gà vào đánh vỡ lòng đỏ rồi phủ mì lên chờ 20 giây cho trứng se chín, sau đó đảo tơi quyện đều.', 'Pad Thai chuẩn phải ráo bóng, từng sợi mì áo đều sốt mà không đọng nước ở đáy chảo.', 3),
('imp-f729957329cd75f5_v4_step_6', 'imp-f729957329cd75f5', 6, 'finish', 'Trộn giá đỗ, hẹ và dọn Pad Thai nóng', 'Tắt bếp, trút tôm áp chảo trở lại chảo cùng 2/3 lượng giá đỗ (khoảng 130 g), phần lớn hẹ cắt khúc và một nửa lượng đậu phộng rang giã dập, đảo nhanh tay 20 giây để giá hẹ vừa chín tái giữ độ giòn tươi. Gắp mì ra đĩa, rắc phần đậu phộng còn lại lên trên và dọn kèm giá sống, hẹ tươi cùng múi chanh.', NULL, NULL),
('imp-04d0b94d17ce080c_v4_step_1', 'imp-04d0b94d17ce080c', 1, 'marinate', 'Thái lát và ướp mềm ức gà', 'Thái 380 g ức gà phi lê thành từng lát mỏng dày 0,5 cm để thịt chín nhanh mà không bị khô. Trộn đều thịt gà với 12 ml xì dầu trong tô sạch, ướp nghỉ 10 phút trong lúc sơ chế rau củ.', NULL, 10),
('imp-04d0b94d17ce080c_v4_step_2', 'imp-04d0b94d17ce080c', 2, 'prep', 'Sơ chế gừng sợi, nấm, hành tây và pha sốt', 'Cạo vỏ 80 g gừng tươi và thái sợi chỉ thật mảnh, thái lát 150 g nấm hương tươi, bổ múi cau mỏng 3/4 củ hành tây, băm nhỏ 1/2 củ tỏi, thái lát xéo 2 quả ớt sừng đỏ và cắt khúc 3–4 cm hành lá (để riêng đầu hành trắng và lá xanh). Pha sẵn chén sốt gồm 20 ml dầu hào, 13 ml xì dầu còn lại, 5 ml nước mắm, 5 g đường và 45 ml nước lọc.', 'Thái gừng thành sợi chỉ mỏng đều giúp gừng chín mềm thơm dịu và dễ ăn hòa quyện cùng thịt gà.', NULL),
('imp-04d0b94d17ce080c_v4_step_3', 'imp-04d0b94d17ce080c', 3, 'cook', 'Áp chảo xào săn thịt ức gà', 'Đun nóng chảo sâu lòng trên lửa lớn với 10 ml dầu ăn, cho toàn bộ ức gà đã ướp vào trải đều và xào nhanh tay khoảng 2 phút đến khi bề mặt gà săn trắng và chín khoảng 80% thì trút ngay ra đĩa riêng.', 'Xào gà riêng trước rồi lấy ra giúp thịt ức gà giữ độ mọng nước và không bị dai trong lúc xào rau.', 2),
('imp-04d0b94d17ce080c_v4_step_4', 'imp-04d0b94d17ce080c', 4, 'cook', 'Xào thơm gừng sợi, hành tây và nấm tươi', 'Dùng lại chảo đó trên lửa vừa lớn với 10 ml dầu ăn còn lại, cho tỏi băm, gừng thái sợi, hành tây và phần đầu hành trắng vào đảo đều 3 phút đến khi gừng dậy hương thơm nồng và hành tây hơi trong. Tiếp tục cho nấm hương thái lát vào xào thêm 2 phút đến khi nấm mềm săn.', NULL, 5),
('imp-04d0b94d17ce080c_v4_step_5', 'imp-04d0b94d17ce080c', 5, 'cook', 'Đảo gà với sốt dầu hào cho sánh quyện', 'Trút phần ức gà cùng nước tiết ra vào chảo, khuấy lại chén sốt đã pha rồi rưới đều vào. Đảo nhanh tay trên lửa lớn khoảng 2 phút đến khi thịt gà chín trắng hoàn toàn bên trong, nước sốt sôi sệt lại và bám bóng đều quanh từng lát gà, gừng và nấm.', 'Đảo nhanh trên lửa lớn ở bước cuối để nước sốt cô sánh bám vào gà mà nấm và hành tây không bị ra nước loãng.', 2),
('imp-04d0b94d17ce080c_v4_step_6', 'imp-04d0b94d17ce080c', 6, 'finish', 'Thêm hành lá, ớt sừng và hoàn thiện đĩa gà xào', 'Tắt bếp ngay rồi cho phần lá xanh của hành lá cùng ớt sừng đỏ thái lát vào đảo đều 10 giây cho hành vừa héo xanh mướt, nếm lại vừa miệng rồi trút ra đĩa thưởng thức nóng.', NULL, NULL),
('imp-b01569fd0df22f66_v4_step_1', 'imp-b01569fd0df22f66', 1, 'prep', 'Sơ chế tỏi lát, ớt tươi và ngò tây', 'Bóc vỏ 3 tép tỏi tươi, bổ dọc lấy bỏ phần lõi xanh ở giữa rồi thái thành những lát mỏng đều nhau để chín cùng lúc. Rửa sạch 1 quả ớt sừng đỏ tươi, bỏ hạt nếu ăn cay nhẹ rồi thái khoanh mỏng. Nhặt lá 6 g ngò tây tươi, rửa sạch, thấm khô và băm nhỏ.', 'Thái tỏi lát đều tay giúp tỏi vàng đồng loạt trong dầu mà không bị miếng cháy miếng sống.', NULL),
('imp-b01569fd0df22f66_v4_step_2', 'imp-b01569fd0df22f66', 2, 'cook', 'Đun nước muối và luộc mì Ý al dente', 'Đun sôi mạnh nồi với 2 lít nước lọc, cho 10 g muối hạt vào khuấy tan rồi thả 180 g mì Ý Spaghetti khô vào luộc khoảng 7–8 phút (bớt 2 phút so với hướng dẫn bao bì) để mì chín tiếp trong chảo sốt. Trước khi vớt, múc giữ lại 120 ml nước luộc mì.', NULL, 8),
('imp-b01569fd0df22f66_v4_step_3', 'imp-b01569fd0df22f66', 3, 'sauce', 'Phi thơm tỏi ớt trên lửa nhỏ với dầu ô liu', 'Đổ 35 ml dầu ô liu nguyên chất vào chảo lớn, đặt lên bếp lửa thật nhỏ. Khi dầu vừa ấm, cho tỏi thái lát và ớt sừng vào phi nhẹ nhàng 2–3 phút đến khi tỏi dậy mùi thơm và vừa chuyển màu vàng nhạt thì lập tức nhấc chảo khỏi bếp để giữ màu đẹp.', 'Chỉ cần tỏi hơi ngả vàng nhạt là đạt, tuyệt đối không để tỏi chuyển nâu vì sẽ gây vị đắng gắt.', 3),
('imp-b01569fd0df22f66_v4_step_4', 'imp-b01569fd0df22f66', 4, 'cook', 'Nhũ tương hóa dầu tỏi với nước luộc mì', 'Đặt chảo dầu tỏi ớt lại lên bếp ở lửa vừa, múc khoảng 60 ml nước luộc mì giàu tinh bột vào chảo và khuấy nhẹ cho hỗn hợp sủi lăn tăn, tạo thành lớp nền hơi sệt.', NULL, NULL),
('imp-b01569fd0df22f66_v4_step_5', 'imp-b01569fd0df22f66', 5, 'cook', 'Xóc mì Ý quyện sốt óng mượt', 'Gắp mì Ý Spaghetti từ nồi thả thẳng vào chảo, đảo và xóc đều tay liên tục khoảng 2 phút trên lửa vừa. Thêm từng chút nước luộc mì còn lại nếu cần cho đến khi tinh bột hòa với dầu ô liu thành lớp sốt bóng mượt ôm trọn sợi mì.', 'Xóc chảo liên tục giúp dầu ô liu và nước tinh bột tạo nhũ tương mượt thay vì tách dầu đọng ở đáy chảo.', 2),
('imp-b01569fd0df22f66_v4_step_6', 'imp-b01569fd0df22f66', 6, 'finish', 'Chỉnh muối, rắc ngò tây và dọn nóng', 'Nếm thử và rắc thêm chút muối hạt (khoảng 2 g nếu nhạt), tắt bếp rồi rắc ngò tây tươi băm nhỏ vào đảo nhẹ lần cuối. Chia mì ra 2 đĩa sâu lòng, rưới phần dầu tỏi ớt còn lại lên trên và thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-d463228be1e6e7c0_v4_step_1', 'imp-d463228be1e6e7c0', 1, 'prep', 'Giữ nóng nước dùng và sơ chế nấm rau củ', 'Đun 800 ml nước dùng rau củ trong nồi riêng ở lửa nhỏ cho luôn sôi lăn tăn. Lau sạch 300 g nấm đùi gà và nấm bào ngư bằng khăn ẩm (không ngâm nước), thái lát dày 0,5 cm. Băm nhỏ hành tây, tỏi tươi và ngò tây để riêng; cắt 23 g bơ lạt vào ngăn mát giữ lạnh.', 'Nước dùng phải luôn nóng để không làm hạt gạo bị sốc nhiệt và sượng lõi khi om.', NULL),
('imp-d463228be1e6e7c0_v4_step_2', 'imp-d463228be1e6e7c0', 2, 'cook', 'Áp chảo nấm vàng thơm với bơ và tỏi', 'Làm nóng chảo lớn trên lửa vừa-cao với 12 ml dầu ô liu nguyên chất và 22 g bơ lạt. Phi thơm tỏi băm 30 giây rồi trút nấm vào dàn đều một lớp, xào 5 phút đến khi nấm cạn nước và vàng xém nhẹ. Nêm 2 g muối ăn và 1 g tiêu đen xay, trút ra đĩa giữ ấm.', 'Dàn nấm thành một lớp mỏng và hạn chế đảo sớm giúp nấm xém vàng thơm thay vì ra nhiều nước.', 5),
('imp-d463228be1e6e7c0_v4_step_3', 'imp-d463228be1e6e7c0', 3, 'cook', 'Xào hành tây và rang hạt gạo Arborio', 'Bắc nồi đáy dày lên bếp ở lửa vừa, thêm 8 ml dầu ô liu còn lại vào xào hành tây băm khoảng 4 phút đến khi hành mềm trong suốt (không để vàng cháy). Đổ 240 g gạo Ý Arborio vào đảo đều 3 phút cho đến khi viền hạt gạo trở nên trong mờ.', NULL, 7);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-d463228be1e6e7c0_v4_step_4', 'imp-d463228be1e6e7c0', 4, 'cook', 'Om gạo từng vá nước dùng nóng với nấm', 'Rót 60 ml rượu vang trắng khô vào nồi gạo (nếu dùng), đảo 2 phút cho bay hơi hết mùi cồn. Múc từng vá nước dùng rau củ nóng (~120 ml) vào ngập mặt gạo, khuấy đều tay; khi nước rút gần cạn mới thêm vá tiếp theo. Sau 8 phút, trút 2/3 lượng nấm xào vào om cùng đến phút thứ 18 khi hạt gạo mềm béo bên ngoài và hơi sật nhẹ ở lõi.', 'Thêm nước dùng nóng từng vá một và khuấy đều giúp tinh bột gạo tiết ra tự nhiên tạo độ sánh như kem.', 18),
('imp-d463228be1e6e7c0_v4_step_5', 'imp-d463228be1e6e7c0', 5, 'finish', 'Đánh bóng Risotto với bơ lạnh và phô mai', 'Khi cơm đạt độ sánh sóng sánh nhẹ, tắt bếp ngay. Cho 23 g bơ lạt lạnh cắt nhỏ cùng 40 g phô mai Parmesan bào mịn vào nồi, đánh nhanh và đều tay khoảng 2 phút đến khi cơm bóng mượt và quyện kem mịn.', 'Tắt bếp rồi mới cho bơ lạnh và phô mai vào đánh giúp tạo nhũ tương béo mượt mà không bị tách dầu.', 2),
('imp-d463228be1e6e7c0_v4_step_6', 'imp-d463228be1e6e7c0', 6, 'finish', 'Nêm lại gia vị và trình bày đĩa nóng', 'Trộn 8 g ngò tây tươi băm, nêm nếm lại phần muối ăn (khoảng 3 g) và 0,5 g tiêu đen xay còn lại cho vừa miệng, để nghỉ 1 phút. Múc cơm Risotto ra 3 đĩa sâu lòng, xếp 1/3 lượng nấm còn lại lên trên và dùng nóng ngay.', NULL, NULL),
('imp-9d575ec5c01896f0_v4_step_1', 'imp-9d575ec5c01896f0', 1, 'prep', 'Sơ chế cá hồi và rau củ gia vị', 'Thấm thật khô 300 g phi lê cá hồi tươi bằng giấy bếp rồi cắt miếng vuông 3–4 cm, ướp đều với 1 g muối ăn, 1 g tiêu đen xay và vài giọt nước cốt chanh vàng. Thái hạt lựu hành tây, băm nhuyễn tỏi tươi, rửa sạch để ráo rau bina, bào vỏ vàng chanh và thái nhỏ ngò tây.', 'Thấm thật khô bề mặt cá hồi trước khi áp chảo giúp miếng cá vàng giòn mà không bị bắn dầu hay nát thịt.', NULL),
('imp-9d575ec5c01896f0_v4_step_2', 'imp-9d575ec5c01896f0', 2, 'cook', 'Luộc mì Ý Spaghetti giữ nước tinh bột', 'Đun sôi nồi lớn với 2,5 lít nước lọc cùng 9 g muối ăn, cho 270 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút đến khi vừa chín tới (al dente). Trước khi vớt mì ra rổ, múc giữ lại 100 ml nước luộc mì.', NULL, 9),
('imp-9d575ec5c01896f0_v4_step_3', 'imp-9d575ec5c01896f0', 3, 'cook', 'Áp chảo cá hồi chín vàng đều các mặt', 'Đun nóng chảo lớn trên lửa vừa-cao với 15 ml dầu ô liu. Xếp các miếng cá hồi vào chảo không chồng lên nhau, áp chảo khoảng 3–4 phút mỗi mặt đến khi vàng đều và thịt cá chín chắc hoàn toàn bên trong rồi gắp ra đĩa riêng.', 'Không áp chảo cá hồi quá lâu để tránh thịt cá bị khô; cá sẽ được đảo nhẹ lại cùng sốt ở bước cuối.', 7),
('imp-9d575ec5c01896f0_v4_step_4', 'imp-9d575ec5c01896f0', 4, 'sauce', 'Xào thơm hành tỏi và làm xẹp rau bina', 'Hạ chảo vừa áp chảo cá xuống lửa vừa, cho 15 g bơ lạt vào đun tan. Cho hành tây vào xào 3 phút cho mềm trong rồi thêm tỏi băm phi thơm 30 giây. Thả toàn bộ 150 g rau bina tươi vào đảo nhanh 1–2 phút đến khi lá vừa héo mềm.', NULL, 4),
('imp-9d575ec5c01896f0_v4_step_5', 'imp-9d575ec5c01896f0', 5, 'sauce', 'Nấu sốt kem tươi và phô mai Parmesan', 'Rót 150 ml kem tươi vào chảo, khuấy đều và đun liu riu 3 phút trên lửa nhỏ cho sốt hơi sánh lại (không để sôi bùng). Hạ lửa thật nhỏ, cho 45 g phô mai Parmesan bào vào khuấy tan hoàn toàn cùng vỏ chanh bào, phần nước cốt chanh vàng còn lại, ớt vảy khô (nếu dùng), 2 g muối ăn và 1 g tiêu đen xay.', 'Vỏ và nước cốt chanh vàng giúp cân bằng độ béo ngậy của kem tươi và cá hồi rất hiệu quả.', 3),
('imp-9d575ec5c01896f0_v4_step_6', 'imp-9d575ec5c01896f0', 6, 'finish', 'Trộn mì Ý với cá hồi và trình bày nóng', 'Cho mì Ý Spaghetti vào chảo sốt đảo đều tay 1 phút, thêm từng chút nước luộc mì nếu sốt đặc. Thả cá hồi áp chảo vào đảo thật nhẹ để miếng cá không nát, tắt bếp, dọn ra 3 đĩa sâu lòng và rắc ngò tây tươi lên trên.', NULL, NULL),
('imp-810c132a4d2cd4e0_v4_step_1', 'imp-810c132a4d2cd4e0', 1, 'prep', 'Sơ chế và ướp tôm sú tươi', 'Lột vỏ 350 g tôm sú (có thể giữ phần chóp đuôi cho đẹp), rút sạch chỉ đen dọc sống lưng, rửa sạch và để thật ráo nước. Ướp tôm với 6 ml nước mắm và 2 g muối ăn trong 10 phút để thịt tôm săn chắc và đậm vị.', NULL, 10),
('imp-810c132a4d2cd4e0_v4_step_2', 'imp-810c132a4d2cd4e0', 2, 'prep', 'Dằm lọc nước cốt me và sơ chế rau củ', 'Ngâm 25 g cơm me chín với 80 ml nước lọc nóng, dằm nhuyễn rồi lọc qua rây bỏ hạt lấy nước cốt. Đeo găng tay tước bỏ vỏ xơ dọc mùng, thái lát xéo dày 0,5 cm, bóp nhẹ với 3 g muối ăn rồi rửa sạch nhiều lần và vắt ráo. Bổ múi cau cà chua, cắt lát dứa, rửa sạch giá đỗ, băm tỏi, cắt khúc hành lá, ngò gai, rau ngổ và thái lát ớt sừng; sát lúc nấu mới thái vát đậu bắp.', 'Chỉ thái đậu bắp ngay trước khi thả vào nồi để đậu bắp giữ màu xanh mướt và hạn chế tiết nhớt ra nước canh.', NULL),
('imp-810c132a4d2cd4e0_v4_step_3', 'imp-810c132a4d2cd4e0', 3, 'cook', 'Phi thơm tỏi và xào sơ tôm trước', 'Làm nóng nồi với 20 ml dầu ăn trên lửa vừa, cho tỏi băm vào phi thơm vàng nhạt rồi trút tôm đã ướp vào đảo nhanh 2 phút đến khi tôm vừa chuyển màu đỏ au thì vớt riêng ra chén.', 'Xào sơ tôm rồi vớt ra và thả lại vào cuối bước nấu giúp thịt tôm giữ nguyên độ giòn ngọt, không bị teo dai.', 2),
('imp-810c132a4d2cd4e0_v4_step_4', 'imp-810c132a4d2cd4e0', 4, 'cook', 'Xào nền cà chua dứa và nấu nước dùng me', 'Dùng lại nồi có dầu thơm, cho một nửa cà chua bổ múi cau và toàn bộ dứa vào xào 3 phút trên lửa vừa cùng 3 g muối ăn còn lại cho cà chua mềm tiết màu đỏ cam. Đổ 1,42 lít nước lọc còn lại vào đun lửa lớn đến khi sôi bùng, sau đó cho nước cốt me, 25 g đường, 8 g hạt nêm và 14 ml nước mắm còn lại vào khuấy tan, nấu 4 phút cho nước dùng dậy vị chua ngọt hài hòa.', 'Cho nước cốt me vào từ từ và nếm chỉnh với đường để đạt vị chua thanh ngọt dịu đặc trưng miền Nam.', 7),
('imp-810c132a4d2cd4e0_v4_step_5', 'imp-810c132a4d2cd4e0', 5, 'cook', 'Chần chín rau củ và nấu chín kỹ tôm', 'Thả đậu bắp thái vát và phần cà chua còn lại vào nồi nấu 2 phút trên lửa vừa, tiếp theo cho dọc mùng vào nấu thêm 1 phút. Trút lại phần tôm đã xào vào nồi, đun sôi lăn tăn thêm 2 phút cho tôm chín kỹ hoàn toàn từ trong ra ngoài.', NULL, 5),
('imp-810c132a4d2cd4e0_v4_step_6', 'imp-810c132a4d2cd4e0', 6, 'finish', 'Thả giá đỗ và rau thơm hoàn thiện tô canh', 'Cuối cùng thả giá đỗ vào nồi, đợi nước vừa sôi trở lại khoảng 15 giây thì tắt bếp ngay để giá vẫn giữ được độ giòn mát. Múc canh ra tô lớn, rắc hành lá, ngò gai, rau ngổ và ớt sừng thái lát lên mặt rồi dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-59015074541ba061_v4_step_1', 'imp-59015074541ba061', 1, 'prep', 'Ngâm nấm hương và chần khổ qua giảm đắng', 'Ngâm 15 g nấm hương khô trong nước ấm 20 phút cho nở mềm hoàn toàn, rửa sạch, bỏ chân cứng rồi băm nhỏ. Rửa sạch 4 trái khổ qua, cắt khoanh tròn dày khoảng 3 cm, dùng cán muỗng nạo thật sạch ruột và lớp màng trắng. Đun sôi nồi nước pha 4 g muối ăn, chần sơ các khoanh khổ qua 2 phút rồi vớt ngay vào nước lạnh, để ráo.', 'Nạo sạch màng trắng và chần sơ qua nước muối rồi ngâm lạnh giúp khoanh khổ qua bớt hẳn vị đắng gắt mà vẫn xanh giòn.', 20),
('imp-59015074541ba061_v4_step_2', 'imp-59015074541ba061', 2, 'prep', 'Băm tôm, cà rốt và chuẩn bị hành lá', 'Lột vỏ 250 g tôm sú và rút sạch chỉ đen. Giữ lại 8 con chừa phần chóp đuôi để cắm trang trí; 180 g tôm còn lại băm hoặc quết nhuyễn. Cà rốt gọt vỏ, băm nhỏ một nửa để trộn nhân và thái lát hoa một nửa. Băm nhuyễn 25 g hành tím cùng đầu trắng của hành lá; phần lá hành xanh cắt khúc 2 cm.', NULL, NULL),
('imp-59015074541ba061_v4_step_3', 'imp-59015074541ba061', 3, 'marinate', 'Quết dẻo và ướp nhân tôm thịt', 'Trộn đều tôm băm nhuyễn, 200 g thịt heo xay, nấm hương băm, cà rốt băm, hành tím và đầu hành lá băm trong tô lớn cùng 6 ml nước mắm, 5 g hạt nêm, 5 g đường và 1 g tiêu đen xay. Quết liên tục theo một chiều 2 phút cho khối nhân dẻo dai rồi ướp 15 phút cho thấm gia vị.', 'Quết nhân kỹ giúp thịt heo và tôm kết dính chặt chẽ, không bị rời rạc hay rã nhân trong nước canh.', 15),
('imp-59015074541ba061_v4_step_4', 'imp-59015074541ba061', 4, 'prep', 'Nhồi nhân vào khoanh khổ qua và gắn đuôi tôm', 'Múc từng lượng nhân tôm thịt nhồi vừa khít vào lòng từng khoanh khổ qua, ấn nhẹ cho mặt nhân phẳng mịn nhưng không nén quá chặt để chừa chỗ nhân nở khi chín. Cắm nhẹ một con tôm nguyên chừa đuôi lên giữa mặt mỗi khoanh khổ qua cho đẹp mắt.', NULL, NULL),
('imp-59015074541ba061_v4_step_5', 'imp-59015074541ba061', 5, 'cook', 'Hầm khổ qua nhồi tôm thịt mở nắp cho nước trong', 'Đun sôi 1,5 lít nước lọc trong nồi rộng đáy, nêm 14 ml nước mắm còn lại, 5 g hạt nêm và 2 g muối ăn. Khi nước sôi đều, nhẹ nhàng xếp từng khoanh khổ qua nhồi và cà rốt thái hoa vào nồi, hạ xuống lửa vừa và nấu mở nắp hoàn toàn trong 20 phút, thỉnh thoảng hớt bọt nổi cho đến khi khổ qua chín mềm và nhân tôm thịt chín chắc hoàn toàn.', 'Không đậy nắp nồi trong suốt lúc hầm để giữ màu xanh tươi cho vỏ khổ qua và giúp nước canh trong vắt.', 20),
('imp-59015074541ba061_v4_step_6', 'imp-59015074541ba061', 6, 'finish', 'Hoàn thiện tô canh khổ qua nhồi tôm', 'Nếm lại nước canh cho vừa miệng rồi tắt bếp, thả hành lá cắt khúc vào. Nhẹ nhàng gắp các khoanh khổ qua nhồi tôm và cà rốt xếp vào tô, chan nước dùng nóng hổi lên trên, rắc 1 g tiêu đen xay còn lại và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-9c678f92a5cb0812_v4_step_1', 'imp-9c678f92a5cb0812', 1, 'prep', 'Sơ chế bí đao sạch nhựa và cắt miếng', 'Gọt sạch lớp vỏ xanh bên ngoài 1 quả bí đao, bổ dọc thân rồi nạo bỏ toàn bộ phần ruột xốp và hạt. Rửa lại bí thật kỹ qua 2 lượt nước cho hết nhựa nhớt, sau đó cắt miếng vừa ăn dày khoảng 1 cm.', 'Rửa sạch lớp nhựa trên miếng bí sau khi gọt sẽ giúp nước canh thành phẩm trong veo và không có vị chát nhẹ.', NULL),
('imp-9c678f92a5cb0812_v4_step_2', 'imp-9c678f92a5cb0812', 2, 'marinate', 'Làm sạch, băm nhỏ và ướp tôm tươi', 'Lột vỏ 250 g tôm tươi, bỏ đầu, rút sạch chỉ đen dọc sống lưng, rửa qua nước muối loãng rồi để ráo. Giữ lại khoảng 4–5 con nguyên để cho đẹp mắt, phần còn lại băm nhỏ vừa phải. Ướp tôm với 5 ml nước mắm, 4 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay trong 15 phút. Băm nhỏ 20 g hành tím, thái nhỏ hành lá và ngò rí.', NULL, 15),
('imp-9c678f92a5cb0812_v4_step_3', 'imp-9c678f92a5cb0812', 3, 'cook', 'Phi thơm hành tím và xào săn tôm', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm vào phi thơm vàng nhẹ rồi thả toàn bộ tôm đã ướp vào đảo nhanh khoảng 2 phút đến khi tôm săn lại và chuyển màu đỏ cam đều.', NULL, 2),
('imp-9c678f92a5cb0812_v4_step_4', 'imp-9c678f92a5cb0812', 4, 'cook', 'Đun sôi nước dùng tôm và hớt sạch bọt', 'Đổ 1,1 lít nước lọc vào nồi tôm, bật lửa lớn đun sôi bùng rồi dùng vá hớt bỏ sạch phần bọt nổi trên mặt để nước canh trong vắt.', 'Hớt bọt ngay khi nước vừa sôi mạnh giúp nước dùng tôm giữ được độ trong sáng và thơm thanh.', 4),
('imp-9c678f92a5cb0812_v4_step_5', 'imp-9c678f92a5cb0812', 5, 'cook', 'Nấu bí đao chín tới và nêm nếm hài hòa', 'Nêm 4 g muối còn lại và 4 g hạt nêm vào nồi, thả toàn bộ bí đao cắt miếng vào và dùng vá ấn nhẹ cho bí ngập nước. Nấu trên lửa vừa khoảng 4–5 phút đến khi miếng bí chuyển màu trong nhẹ, xiên đũa thấy vừa mềm nhưng vẫn giữ độ giòn ngọt và tôm chín kỹ hoàn toàn. Nêm thêm 10 ml nước mắm còn lại rồi tắt bếp.', 'Không nên cho nước mắm quá sớm hoặc nấu bí quá lâu kẻo bí bị nhũn nát và mất đi mùi thơm thanh mát.', 5),
('imp-9c678f92a5cb0812_v4_step_6', 'imp-9c678f92a5cb0812', 6, 'finish', 'Rắc hành ngò và tiêu xay hoàn thiện', 'Thả hành lá và ngò rí thái nhỏ vào nồi canh đang nóng, rắc 1 g tiêu đen xay còn lại rồi múc ra tô lớn thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-80ce5736becc08da_v4_step_1', 'imp-80ce5736becc08da', 1, 'prep', 'Sơ chế cà chua, hành tỏi và đánh tan trứng gà', 'Rửa sạch 3 quả cà chua chín, bỏ cuống và bổ múi cau vừa ăn. Băm nhỏ 15 g hành tím khô và 7,5 g tỏi khô; rửa sạch hành lá và ngò rí rồi thái nhỏ, để riêng phần đầu hành. Đập 3 quả trứng gà vào chén cùng 1 g muối ăn, dùng đũa đánh tan thật đều lòng đỏ và lòng trắng.', 'Đánh tan trứng với một nhúm nhỏ muối trước giúp vân trứng đậm đà và khi rót vào nồi không bị tanh.', NULL),
('imp-80ce5736becc08da_v4_step_2', 'imp-80ce5736becc08da', 2, 'cook', 'Phi thơm hành tỏi và xào mềm cà chua tạo màu', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm, tỏi băm và đầu hành lá vào phi thơm 30 giây. Trút cà chua bổ múi cau vào cùng 15 ml nước mắm ngon, xào đảo đều khoảng 2–3 phút cho cà chua mềm nhũn nhẹ và tiết màu đỏ cam bắt mắt.', 'Xào cà chua trực tiếp với chút nước mắm giúp cà chua nhanh mềm và nước canh lên màu đỏ tự nhiên rất đẹp.', 3),
('imp-80ce5736becc08da_v4_step_3', 'imp-80ce5736becc08da', 3, 'cook', 'Nấu sôi nước dùng chua dịu hài hòa', 'Đổ 1,1 lít nước lọc vào nồi cà chua, tăng lên lửa lớn đun sôi bùng rồi nêm 3 g muối ăn còn lại, 6 g hạt nêm và 5 g đường cát trắng. Khuấy tan và nấu thêm 2 phút cho nước canh ngấm vị chua ngọt dịu nhẹ, hớt bọt nếu có.', NULL, 4),
('imp-80ce5736becc08da_v4_step_4', 'imp-80ce5736becc08da', 4, 'cook', 'Rưới trứng tạo vân mây vàng óng bồng bềnh', 'Hạ xuống lửa nhỏ để nước canh chỉ sôi lăn tăn nhẹ. Cầm chén trứng đã đánh tan rưới thật chậm theo dòng mảnh vòng quanh nồi, chờ khoảng 5 giây cho lớp trứng hơi se mặt rồi dùng đũa khuấy nhẹ nhàng theo một chiều để tạo thành những dải vân trứng mịn màng.', 'Không đổ trứng khi nước đang sôi sùng sục và không khuấy mạnh tay để tránh vân trứng bị nát vụn làm đục nước.', 2),
('imp-80ce5736becc08da_v4_step_5', 'imp-80ce5736becc08da', 5, 'cook', 'Nấu chín kỹ trứng gà vừa tới', 'Giữ lửa nhỏ đun thêm đúng 1 phút cho các dải trứng nổi đều và chín hoàn toàn bên trong, nếm lại gia vị lần cuối cho vừa miệng rồi tắt bếp ngay để trứng không bị dai cứng.', NULL, 1),
('imp-80ce5736becc08da_v4_step_6', 'imp-80ce5736becc08da', 6, 'finish', 'Rắc rau thơm và tiêu xay hoàn thiện', 'Thả hành lá và ngò rí thái nhỏ vào nồi canh nóng, rắc thêm 1 g tiêu đen xay rồi múc ra tô lớn thưởng thức ngay cùng cơm trắng.', NULL, NULL),
('imp-9473faeacd64d970_v4_step_1', 'imp-9473faeacd64d970', 1, 'marinate', 'Sơ chế và ướp ức gà thấm gia vị', 'Rửa sạch 400 g ức gà phi lê, thấm ráo nước và giữ nguyên miếng để luộc không bị khô. Ướp ức gà với 1/3 chỗ hành tím băm, 5 ml nước mắm, 4 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay trong 15 phút cho thịt gà đậm đà từ bên trong.', NULL, 15),
('imp-9473faeacd64d970_v4_step_2', 'imp-9473faeacd64d970', 2, 'prep', 'Thái sợi nấm đùi gà, cà rốt và rau thơm', 'Cắt bỏ phần gốc cứng của 250 g nấm đùi gà, rửa nhanh dưới vòi nước lạnh cho sạch rồi để ráo, sau đó xé hoặc thái sợi dọc dày 0,5 cm. Gọt vỏ 1 củ cà rốt, thái lát mỏng hoặc thái sợi. Thái lát gừng, băm nhỏ phần hành tím còn lại, cắt khúc đầu hành lá và thái nhỏ lá hành cùng ngò rí.', 'Không ngâm nấm đùi gà quá lâu trong nước vì nấm hút nước sẽ bị nhạt vị và mất độ giòn ngọt đặc trưng.', NULL),
('imp-9473faeacd64d970_v4_step_3', 'imp-9473faeacd64d970', 3, 'cook', 'Áp săn ức gà và luộc chín lấy nước dùng trong', 'Làm nóng nồi với 10 ml dầu ăn trên lửa vừa, phi thơm phần hành tím băm còn lại rồi cho miếng ức gà đã ướp vào áp chảo săn hai mặt khoảng 3 phút. Đổ 1,1 lít nước lọc và gừng lát vào nồi, đun sôi bùng rồi hạ lửa vừa luộc thêm 12 phút đến khi thịt gà chín hoàn toàn bên trong (không còn lõi hồng), đồng thời hớt sạch bọt nổi.', 'Áp săn ức gà trước khi đổ nước giúp bề mặt thịt se thơm và nước dùng luộc gà trong veo không bị đục.', 15),
('imp-9473faeacd64d970_v4_step_4', 'imp-9473faeacd64d970', 4, 'prep', 'Vớt ức gà ra để nguội bớt và xé sợi', 'Vớt miếng ức gà ra đĩa cho nguội bớt khoảng 3–4 phút rồi dùng tay xé dọc theo thớ thịt thành từng sợi vừa ăn; giữ lại toàn bộ nồi nước luộc gà trên bếp.', 'Xé thịt khi ức gà còn hơi ấm theo đúng thớ dọc giúp sợi gà mềm tơi và không bị bở nát.', NULL),
('imp-9473faeacd64d970_v4_step_5', 'imp-9473faeacd64d970', 5, 'cook', 'Nấu cà rốt, nấm đùi gà và thả gà xé vào nồi', 'Đun sôi lại nồi nước luộc gà, thả cà rốt vào nấu 2 phút trước, sau đó cho nấm đùi gà thái sợi vào nấu thêm 3 phút trên lửa vừa cho nấm vừa chín tới vẫn còn độ giòn ngọt. Trút toàn bộ thịt ức gà xé sợi trở lại nồi, nêm 8 g hạt nêm còn lại, 10 ml nước mắm, 2 g muối và 4 g đường cát trắng, đun sôi nhẹ thêm 1–2 phút cho hòa quyện.', NULL, 7),
('imp-9473faeacd64d970_v4_step_6', 'imp-9473faeacd64d970', 6, 'finish', 'Thêm đầu hành, rau thơm và tiêu xay hoàn thiện', 'Thả đầu hành lá cắt khúc và lá hành thái nhỏ vào nồi, khuấy đều rồi tắt bếp. Múc canh ra tô lớn, rắc ngò rí và 1 g tiêu đen xay lên mặt, dùng nóng với cơm trắng.', NULL, NULL),
('imp-9ab5767266722397_v4_step_1', 'imp-9ab5767266722397', 1, 'prep', 'Làm sạch mực ống và khử mùi tanh', 'Rút bỏ đầu, ruột, túi mực và sống lưng cứng của 350 g mực ống tươi; lột bỏ lớp màng da bên ngoài nếu thích nước canh thật trong. Chà xát nhanh mực với 2 g muối ăn rồi rửa sạch nhiều lần bằng nước lạnh, để thật ráo và cắt khoanh tròn dày 1,5–2 cm.', 'Bóp rửa nhanh mực với chút muối rồi để thật ráo nước giúp mực hết nhớt và giữ độ giòn sần sật khi nấu.', NULL),
('imp-9ab5767266722397_v4_step_2', 'imp-9ab5767266722397', 2, 'marinate', 'Ướp mực và sơ chế cà chua, gừng, hành', 'Ướp mực cắt khoanh với 6 ml nước mắm, 3 g hạt nêm và 1 g tiêu đen xay trong 10 phút cho thấm vị. Trong lúc chờ, bổ múi cau 2,5 quả cà chua, băm nhỏ 25 g hành tím, thái lát một nửa lượng gừng và thái sợi phần gừng còn lại; cắt khúc hành lá và ngò rí.', NULL, 10),
('imp-9ab5767266722397_v4_step_3', 'imp-9ab5767266722397', 3, 'cook', 'Phi thơm hành gừng và xào cà chua lên màu', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và gừng thái lát vào phi thơm khoảng 1 phút cho dậy mùi ấm nồng. Trút cà chua bổ múi cau vào cùng 2 g muối ăn còn lại, xào đảo khoảng 2–3 phút đến khi cà chua mềm nhẹ và ra màu đỏ cam đẹp mắt.', 'Phi thơm hành tím cùng gừng lát trước khi xào cà chua là bước khử mùi tanh đặc trưng giúp canh mực thơm dịu hơn.', 3),
('imp-9ab5767266722397_v4_step_4', 'imp-9ab5767266722397', 4, 'cook', 'Nấu sôi nước dùng chua ngọt thanh nhẹ', 'Đổ 1,1 lít nước lọc vào nồi cà chua, bật lửa lớn đun sôi bùng rồi nêm 14 ml nước mắm còn lại, 5 g hạt nêm và 5 g đường cát trắng, nấu sôi 3 phút cho gia vị tan đều và cà chua tiết vị chua dịu.', NULL, 3),
('imp-9ab5767266722397_v4_step_5', 'imp-9ab5767266722397', 5, 'cook', 'Thả mực vào nấu chín tới giữ độ giòn ngọt', 'Khi nước đang sôi đều trên lửa lớn vừa, thả toàn bộ mực đã ướp và gừng thái sợi vào nồi. Nấu đúng 2–3 phút cho nước sôi lại, khoanh mực cong tròn, chuyển màu trắng đục săn chắc và chín hoàn toàn bên trong rồi nêm nếm lại cho vừa miệng.', 'Chỉ thả mực khi nước đang sôi mạnh và nấu khoảng 2–3 phút để mực vừa chín tới, giữ trọn độ giòn ngọt mà không bị dai.', 3),
('imp-9ab5767266722397_v4_step_6', 'imp-9ab5767266722397', 6, 'finish', 'Hoàn thiện với chanh tươi và hành ngò', 'Tắt bếp ngay, thả hành lá và ngò rí cắt nhỏ vào đảo nhẹ. Múc canh ra tô, vắt thêm nước cốt của 0,5 quả chanh tươi tùy khẩu vị và rắc 1 g tiêu đen xay lên trên, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-61eac17e8f3042a9_v4_step_1', 'imp-61eac17e8f3042a9', 1, 'prep', 'Gọt su su sạch mủ và cắt miếng vừa ăn', 'Cắt bỏ hai đầu của 2 quả su su non, ngâm hoặc gọt vỏ trực tiếp dưới vòi nước lạnh chảy nhẹ để mủ su su trôi sạch không làm dính và rít da tay. Bổ đôi su su, khoét bỏ phần hạt non rồi thái lát vát dày khoảng 0,5 cm, rửa lại nước sạch và để ráo.', 'Gọt vỏ su su dưới nước hoặc ngâm qua nước muối loãng giúp loại bỏ hoàn toàn nhựa mủ và giữ miếng su su trắng xanh đẹp mắt.', NULL),
('imp-61eac17e8f3042a9_v4_step_2', 'imp-61eac17e8f3042a9', 2, 'marinate', 'Ướp thịt heo xay và băm hành tím, rau thơm', 'Băm nhuyễn 20 g hành tím khô, thái nhỏ hành lá và ngò rí. Cho 220 g thịt heo xay vào tô, ướp cùng một nửa lượng hành tím băm, 5 ml nước mắm, 4 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay, trộn đều để thấm gia vị trong 10 phút.', NULL, 10),
('imp-61eac17e8f3042a9_v4_step_3', 'imp-61eac17e8f3042a9', 3, 'cook', 'Phi thơm hành tím và xào tơi thịt heo băm', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho nửa phần hành tím băm còn lại vào phi thơm vàng nhạt. Trút thịt heo xay đã ướp vào đảo nhanh và dằm nhẹ cho thịt tơi rời, xào khoảng 3 phút cho thịt săn lại và chín đều.', 'Dùng đũa đảo tơi liên tục khi thịt mới vào nồi nóng giúp thịt băm rời đều và không bị vón thành từng cục lớn.', 3),
('imp-61eac17e8f3042a9_v4_step_4', 'imp-61eac17e8f3042a9', 4, 'cook', 'Đun sôi nước dùng và hớt sạch bọt', 'Đổ 1,2 lít nước lọc vào nồi thịt xào, tăng lên lửa lớn đun sôi bùng rồi dùng vá hớt sạch phần bọt nổi trên mặt để nước canh trong vắt.', NULL, 5),
('imp-61eac17e8f3042a9_v4_step_5', 'imp-61eac17e8f3042a9', 5, 'cook', 'Nấu su su chín tới và nêm nếm vị thanh ngọt', 'Thả toàn bộ su su thái lát vào nồi nước đang sôi, nấu trên lửa vừa khoảng 4–5 phút đến khi su su chuyển màu xanh trong nhẹ và vẫn còn độ giòn ngọt (tránh nấu nhũn). Nêm 3 g muối còn lại, 4 g hạt nêm và 10 ml nước mắm vào khuấy nhẹ rồi nếm lại vừa miệng.', 'Su su thái lát mỏng chín rất nhanh; tắt bếp ngay khi su su vừa chuyển trong sẽ giữ được độ giòn ngọt và màu xanh tươi.', 5),
('imp-61eac17e8f3042a9_v4_step_6', 'imp-61eac17e8f3042a9', 6, 'finish', 'Hoàn thiện với hành lá, ngò rí và tiêu xay', 'Tắt bếp, thả hành lá và ngò rí thái nhỏ vào nồi canh, rắc 1 g tiêu đen xay còn lại rồi múc ra tô dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-ad2b55ed85f0d109_v4_step_1', 'imp-ad2b55ed85f0d109', 1, 'prep', 'Thái sợi bắp cải, cà rốt và đánh tan trứng', 'Tách bỏ lá úa và phần cùi cứng của 0,75 bắp cải, thái sợi hoặc miếng vuông vừa ăn rồi rửa sạch qua 2–3 lần nước, để thật ráo. Gọt vỏ 0,5 củ cà rốt, thái lát mỏng. Băm nhỏ 20 g hành tím, thái nhỏ ngò rí và hành lá (để riêng phần đầu hành đập dập), thái lát ớt sừng. Đập 4 quả trứng gà vào tô, đánh tan đều tay.', 'Đánh đều tay cho lòng đỏ và lòng trắng hòa quyện hoàn toàn sẽ giúp vân trứng cuộn thành dải mảnh mịn đẹp mắt.', NULL),
('imp-ad2b55ed85f0d109_v4_step_2', 'imp-ad2b55ed85f0d109', 2, 'cook', 'Phi thơm hành và đun sôi nước dùng cà rốt', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và đầu hành lá vào phi thơm vàng nhẹ. Đổ 1,2 lít nước lọc vào nồi cùng cà rốt thái lát, nêm 6 g muối ăn, 10 g hạt nêm và 8 g đường cát trắng, đun sôi khoảng 4 phút cho cà rốt hơi mềm và gia vị tan đều.', NULL, 4),
('imp-ad2b55ed85f0d109_v4_step_3', 'imp-ad2b55ed85f0d109', 3, 'cook', 'Rưới trứng tạo vân cuộn vàng mềm mịn', 'Khi nước dùng đang sôi đều ở lửa vừa, từ từ rót phần trứng gà đã đánh tan vào nồi qua dòng chảy nhỏ, đồng thời dùng đũa khuấy nhẹ nhàng theo một vòng tròn để trứng kết thành những sợi cuộn mỏng bồng bềnh và không bị vón cục.', 'Giữ nước sôi vừa phải và khuấy thật nhẹ một chiều trong lúc rưới trứng để tạo vân cuộn tơi đẹp mà không làm đục nước.', 2),
('imp-ad2b55ed85f0d109_v4_step_4', 'imp-ad2b55ed85f0d109', 4, 'cook', 'Nấu bắp cải vừa chín tới giữ độ giòn ngọt', 'Thả toàn bộ bắp cải thái sợi vào nồi, đảo nhẹ cho ngập nước và nấu mở vung trên lửa vừa thêm 2 phút đến khi bắp cải vừa chín tới vẫn giữ màu xanh nhạt tươi tắn, độ giòn ngọt và trứng chín hoàn toàn bên trong.', 'Chỉ nấu bắp cải khoảng 2 phút mở vung để rau giữ được độ giòn ngọt tự nhiên và không bị nồng mùi.', 2),
('imp-ad2b55ed85f0d109_v4_step_5', 'imp-ad2b55ed85f0d109', 5, 'cook', 'Nêm nước mắm sau cùng giữ trọn hương thơm', 'Rưới 20 ml nước mắm ngon vào nồi canh, khuấy nhẹ đều một lượt rồi nếm lại vị thanh ngọt vừa miệng trước khi tắt bếp.', NULL, NULL),
('imp-ad2b55ed85f0d109_v4_step_6', 'imp-ad2b55ed85f0d109', 6, 'finish', 'Hoàn thiện với hành ngò, ớt lát và tiêu xay', 'Tắt bếp, rắc hành lá và ngò rí thái nhỏ cùng vài lát ớt sừng đỏ và 1 g tiêu đen xay lên mặt nồi. Múc canh ra tô lớn dùng nóng với cơm trắng.', NULL, NULL),
('imp-7cfc6a2e9d8bf8a3_v4_step_1', 'imp-7cfc6a2e9d8bf8a3', 1, 'prep', 'Nhặt rau muống và sơ chế cà chua, hành lá', 'Nhặt bỏ phần gốc già của 1,5 bó rau muống, ngắt lấy phần cọng non và lá xanh thành khúc dài khoảng 5 cm. Ngâm rau với nước pha 2 g muối ăn trong 5 phút rồi xả sạch nhiều lần, để thật ráo. Bổ múi cau 2 quả cà chua chín, băm nhỏ 20 g hành tím và cắt nhỏ hành lá.', NULL, 5),
('imp-7cfc6a2e9d8bf8a3_v4_step_2', 'imp-7cfc6a2e9d8bf8a3', 2, 'marinate', 'Giã thô và ướp tôm đồng cho ngọt nước', 'Lột vỏ 200 g tôm đồng, bỏ đầu, rút sạch chỉ đen dọc lưng và giữ lại phần gạch tôm nếu có. Cho tôm vào cối giã thô vừa phải để thịt tôm vẫn còn độ sần sật, sau đó ướp với 1 g muối ăn, 3 g hạt nêm, 4 g đường cát trắng và 1 g tiêu đen xay trong 10 phút cho ngấm vị.', 'Giã thô tôm đồng cùng chút gạch giúp thịt tôm tiết ra hết độ ngọt vào nước dùng và tạo màu cam hấp dẫn.', 10),
('imp-7cfc6a2e9d8bf8a3_v4_step_3', 'imp-7cfc6a2e9d8bf8a3', 3, 'cook', 'Phi thơm hành tím và xào chín tôm, cà chua', 'Làm nóng nồi với 20 ml dầu ăn trên lửa vừa, cho hành tím băm vào phi thơm vàng nhẹ rồi trút tôm đồng đã ướp vào đảo đều khoảng 2 phút đến khi tôm săn lại và chuyển màu hồng cam. Tiếp tục cho cà chua bổ múi cau vào xào chung thêm 3 phút cho cà chua mềm nhẹ và ra màu đỏ cam tự nhiên.', 'Xào chín tôm cùng cà chua trước khi đổ nước giúp nước canh có màu đỏ cam đẹp mắt và dậy mùi thơm đậm đà.', 5),
('imp-7cfc6a2e9d8bf8a3_v4_step_4', 'imp-7cfc6a2e9d8bf8a3', 4, 'cook', 'Đun sôi nước dùng và nêm gia vị hài hòa', 'Đổ 1,3 lít nước lọc vào nồi, bật lửa lớn đun sôi bùng và hớt sạch bọt nổi trên mặt. Nêm 3 g muối ăn còn lại, 5 g hạt nêm và 15 ml nước mắm ngon vào nồi, khuấy tan đều và nấu thêm 2 phút cho nước canh đậm vị chua thanh ngọt dịu.', NULL, 4),
('imp-7cfc6a2e9d8bf8a3_v4_step_5', 'imp-7cfc6a2e9d8bf8a3', 5, 'cook', 'Thả rau muống vào nấu mở vung giữ màu xanh', 'Khi nước đang sôi mạnh trên lửa lớn, thả toàn bộ rau muống vào nồi và dùng vá ấn nhẹ cho rau ngập đều trong nước dùng. Nấu mở nắp khoảng 2–3 phút đến khi cọng rau vừa chín tới, xanh mướt và vẫn giữ độ giòn.', 'Không đậy nắp nồi và nấu nhanh trên lửa lớn giúp rau muống giữ màu xanh tươi mướt mà không bị úa vàng.', 3),
('imp-7cfc6a2e9d8bf8a3_v4_step_6', 'imp-7cfc6a2e9d8bf8a3', 6, 'finish', 'Hoàn thiện với hành lá và dọn nóng', 'Nếm lại vị canh lần cuối cho vừa miệng, thả hành lá cắt nhỏ vào đảo nhẹ rồi tắt bếp ngay. Múc canh ra tô lớn dùng nóng với cơm trắng.', NULL, NULL),
('imp-24cdd0b61f9ed162_v4_step_1', 'imp-24cdd0b61f9ed162', 1, 'prep', 'Làm sạch cua đồng, khêu gạch và lọc nước cua', 'Ngâm rửa sạch 400 g cua đồng cho hết bùn đất, tách mai, bỏ yếm và khêu riêng phần gạch cua ra chén. Giã nhuyễn thân cua với 2 g muối ăn (hoặc dùng cua xay nhuyễn), hòa với 1,14 lít nước lọc, bóp kỹ rồi lọc gạn 2–3 lần qua rây mịn vào nồi nấu canh để loại bỏ hoàn toàn vỏ sạn. Ngâm dằm 25 g me chín với 60 ml nước nóng rồi lọc lấy nước cốt.', 'Lọc nước cua qua rây mịn 2 lần giúp thu hết thịt cua mà nước canh vẫn sạch hoàn toàn không bị lợn cợn vỏ cứng.', 10),
('imp-24cdd0b61f9ed162_v4_step_2', 'imp-24cdd0b61f9ed162', 2, 'prep', 'Rán vàng đậu phụ và phi giòn hành tím', 'Thấm khô 2 bìa đậu phụ, cắt miếng vuông vừa ăn khoảng 2,5 cm. Làm nóng chảo với 20 ml dầu ăn trên lửa vừa, thả đậu phụ vào rán vàng giòn các mặt rồi gắp ra đĩa giấy thấm dầu. Bổ múi cau 2,5 quả cà chua; thái nhỏ hành lá và rau răm; chia 25 g hành tím làm hai phần (một nửa thái lát mỏng, một nửa băm nhỏ) rồi dùng chảo nhỏ với 15 ml dầu ăn phi vàng giòn phần hành thái lát, vớt riêng ra chén.', NULL, 8),
('imp-24cdd0b61f9ed162_v4_step_3', 'imp-24cdd0b61f9ed162', 3, 'cook', 'Nấu nổi riêu cua đồng và vớt tảng riêu riêng', 'Hòa 10 g hạt nêm và 2 g muối ăn vào nồi nước lọc cua, khuấy nhẹ một chiều rồi bắc lên bếp đun ở lửa vừa. Khi nước nóng dần và thịt cua bắt đầu tách lớp nổi lên mặt, ngừng khuấy hoàn toàn và hạ nhỏ lửa để riêu kết lại thành từng mảng dày. Khi nước sôi nhẹ, dùng vá lỗ nhẹ nhàng vớt phần riêu cua ra bát riêng để không bị nát.', 'Ngừng khuấy ngay khi thịt cua bắt đầu kết mảng và vớt riêu ra trước khi cho cà chua giúp giữ trọn tảng riêu nguyên vẹn đẹp mắt.', 8),
('imp-24cdd0b61f9ed162_v4_step_4', 'imp-24cdd0b61f9ed162', 4, 'cook', 'Chưng gạch cua cùng cà chua tạo màu đỏ óng', 'Tận dụng chảo dầu vừa phi hành, cho phần hành tím băm vào phi thơm, thả cà chua bổ múi cau và 2 g muối ăn còn lại vào xào mềm khoảng 2 phút cho ra màu đỏ đẹp rồi trút chén gạch cua vào đảo nhanh tay 1 phút đến khi gạch chín thơm vàng óng.', 'Chưng gạch cua trên lửa vừa cùng hành phi và cà chua giúp gạch lên màu vàng cam óng ả và khử hoàn toàn mùi tanh.', 3),
('imp-24cdd0b61f9ed162_v4_step_5', 'imp-24cdd0b61f9ed162', 5, 'cook', 'Nấu nước riêu chua dịu và thả đậu phụ rán', 'Trút chảo cà chua chưng gạch vào nồi nước cua, đun sôi lại rồi từ từ rót nước cốt me vào cùng 15 ml nước mắm ngon, điều chỉnh độ chua thanh mặn ngọt hài hòa. Thả toàn bộ đậu phụ rán vàng vào nồi đun sôi liu riu thêm 3 phút cho đậu thấm vị canh.', NULL, 4),
('imp-24cdd0b61f9ed162_v4_step_6', 'imp-24cdd0b61f9ed162', 6, 'finish', 'Thả lại riêu cua, hành răm và rắc hành phi', 'Nhẹ nhàng đặt phần riêu cua trở lại mặt nồi canh, rắc hành lá và rau răm thái nhỏ rồi tắt bếp ngay. Múc canh ra bát tô, rắc phần hành tím phi vàng giòn lên trên và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-15155ec6cc7b7713_v4_step_1', 'imp-15155ec6cc7b7713', 1, 'prep', 'Làm sạch và thái dải thịt ba chỉ', 'Rửa sạch 500 g thịt ba chỉ với nước pha 4 g muối để khử mùi, rửa lại nước sạch và thấm thật khô. Thái thịt thành các dải dày 1–1,5 cm, dài khoảng 5–6 cm để khi nướng thịt chín đều mà vẫn giữ được độ mọng nước.', 'Thấm thật khô thịt trước khi ướp giúp gia vị bám chắc vào bề mặt và không bị chảy nước loãng.', NULL),
('imp-15155ec6cc7b7713_v4_step_2', 'imp-15155ec6cc7b7713', 2, 'prep', 'Băm nhuyễn sả, hành tím, tỏi, gừng và ớt', 'Đập dập rồi băm thật nhuyễn 4 cây sả tươi, 30 g hành tím, 15 g gừng, tỏi và ớt hiểm. Giữ lại 1/4 lượng tỏi và 1 quả ớt hiểm băm riêng để pha nước chấm, phần còn lại dùng để ướp thịt.', NULL, NULL),
('imp-15155ec6cc7b7713_v4_step_3', 'imp-15155ec6cc7b7713', 3, 'marinate', 'Trộn sốt ướp sả mật ong và ướp thịt', 'Trộn đều sả, hành tím, gừng, 3/4 tỏi và 1 quả ớt băm với 30 ml nước mắm, 30 ml mật ong, 15 ml dầu ăn, 5 g đường cát trắng, 2 g muối và 2 g tiêu đen xay. Xoa đều hỗn hợp lên từng dải thịt ba chỉ, bọc kín và ướp ít nhất 45 phút trong ngăn mát tủ lạnh.', 'Gạt bớt phần xác sả tỏi quá dày trên bề mặt thịt trước khi đặt lên vỉ để tránh bị cháy khét trong lúc nướng mật ong.', 45),
('imp-15155ec6cc7b7713_v4_step_4', 'imp-15155ec6cc7b7713', 4, 'sauce', 'Pha nước mắm chua ngọt tỏi ớt ăn kèm', 'Trong lúc chờ thịt ngấm, hòa tan 10 g đường cát trắng với 45 ml nước lọc ấm và 15 ml giấm gạo, sau đó cho 15 ml nước mắm ngon vào khuấy đều. Cuối cùng thả phần tỏi và ớt hiểm băm còn lại vào để tỏi ớt nổi đẹp trên mặt chén nước chấm.', NULL, NULL),
('imp-15155ec6cc7b7713_v4_step_5', 'imp-15155ec6cc7b7713', 5, 'cook', 'Làm nóng lò và nướng vàng mặt thứ nhất', 'Lấy thịt ra khỏi tủ lạnh trước 10 phút cho bớt lạnh. Làm nóng lò nướng (hoặc nồi chiên không dầu) ở 190°C trong 10 phút, xếp dải thịt lên vỉ có khay hứng mỡ bên dưới và nướng mặt đầu tiên trong 15 phút.', NULL, 15),
('imp-15155ec6cc7b7713_v4_step_6', 'imp-15155ec6cc7b7713', 6, 'cook', 'Lật mặt, phết nước ướp và nướng cháy cạnh', 'Lật mặt miếng thịt, phết thêm một lớp mỏng phần nước ướp còn dư rồi tiếp tục nướng thêm 12–15 phút ở 190°C đến khi hai mặt thịt vàng ruộm, xém cạnh thơm lừng và nước thịt chảy ra trong hoàn toàn không còn màu hồng.', 'Mật ong rất nhanh lên màu nên cần canh lửa vừa khoảng 180–190°C và quan sát ở 5 phút cuối để thịt vàng bóng mà không bị đắng.', 15),
('imp-15155ec6cc7b7713_v4_step_7', 'imp-15155ec6cc7b7713', 7, 'finish', 'Thái miếng, vắt chanh tươi và dọn thưởng thức', 'Gắp thịt ba chỉ nướng ra thớt để nghỉ 5 phút cho nước thịt ổn định, sau đó thái lát mỏng vừa ăn. Xếp ra đĩa, vắt vài giọt nước cốt chanh tươi lên trên để cân bằng vị béo và dùng nóng kèm nước mắm chua ngọt.', NULL, NULL),
('imp-363ca9ee2c5f7738_v4_step_1', 'imp-363ca9ee2c5f7738', 1, 'prep', 'Khử mùi thịt nạm bò và sơ chế rau thơm', 'Bóp đều 650 g thịt nạm bò với 6 g muối hạt và 15 ml rượu trắng trong 5 phút để khử mùi gây, rửa lại nhiều lần nước lạnh rồi thấm khô và thái khối vuông 3,5–4 cm. Cà rốt cắt khúc 2,5 cm; cà chua bỏ hạt băm nhỏ; sả đập dập 2 cây và băm nhỏ 1 cây; gừng, hành tím, tỏi băm nhỏ; hoa hồi và quế thanh rang khô thơm; húng quế, ngò gai rửa sạch.', NULL, 5),
('imp-363ca9ee2c5f7738_v4_step_2', 'imp-363ca9ee2c5f7738', 2, 'marinate', 'Ướp thịt bò với ngũ vị hương và gia vị', 'Cho thịt bò vào tô lớn, trộn đều cùng một nửa lượng sả băm, gừng, hành tím, tỏi băm, 5 g bột ngũ vị hương, 15 ml nước mắm, 15 g đường cát trắng và 2 g tiêu đen xay. Bọc kín và ướp ít nhất 45 phút trong ngăn mát để thịt thấm sâu hương vị.', 'Nếu có thời gian, ướp thịt qua đêm trong ngăn mát tủ lạnh sẽ giúp thớ thịt bò mềm hơn và đậm mùi ngũ vị hương hơn.', 45),
('imp-363ca9ee2c5f7738_v4_step_3', 'imp-363ca9ee2c5f7738', 3, 'cook', 'Phi thơm dầu điều, xào cà chua và thịt bò', 'Làm nóng nồi đáy dày với 15 ml dầu màu điều trên lửa vừa, phi thơm phần hành tím, tỏi, gừng và sả băm còn lại trong 1 phút. Cho cà chua băm vào xào nhuyễn 3 phút tạo nền màu đỏ sánh, rồi trút toàn bộ thịt bò đã ướp vào đảo săn trên lửa lớn trong 5 phút.', NULL, 8),
('imp-363ca9ee2c5f7738_v4_step_4', 'imp-363ca9ee2c5f7738', 4, 'cook', 'Hầm mềm thịt bò với nước dừa tươi và thảo mộc', 'Đổ 1 lít nước dừa tươi và 100 ml nước lọc vào nồi, thả 2 cây sả đập dập, hoa hồi, quế thanh và nguyên củ hành tây vào cùng. Đun sôi bùng, hớt sạch bọt rồi hạ lửa nhỏ đậy hé nắp hầm liu riu 40 phút cho thịt nạm bò chín mềm.', 'Thả nguyên củ hành tây vào hầm giúp nước bò kho có độ ngọt thanh tự nhiên mà không bị đục nước.', 40),
('imp-363ca9ee2c5f7738_v4_step_5', 'imp-363ca9ee2c5f7738', 5, 'cook', 'Hầm cà rốt chín mềm và nêm nước dùng', 'Vớt bỏ củ hành tây, hoa hồi, quế thanh và cọng sả ra khỏi nồi. Cho cà rốt cắt khúc vào nồi cùng 15 ml nước mắm còn lại, 10 g đường cát trắng, 6 g hạt nêm và 2 g muối, tiếp tục hầm lửa vừa nhỏ thêm 15 phút đến khi cà rốt chín mềm mà không bị bở nát.', NULL, 15),
('imp-363ca9ee2c5f7738_v4_step_6', 'imp-363ca9ee2c5f7738', 6, 'finish', 'Tạo độ sánh bằng bột năng và dọn kèm bánh mì', 'Khuấy tan 18 g bột năng với 150 ml nước lọc, vừa rót từ từ vào nồi bò kho đang sôi nhẹ vừa khuấy đều đến khi nước dùng sánh mịn mượt, đun thêm 2 phút cho chín bột rồi tắt bếp. Múc bò kho ra tô, rắc ngò gai thái nhỏ và húng quế lên trên, dọn nóng kèm 5 ổ bánh mì giòn.', 'Rót nước bột năng từ từ từng chút một để kiểm soát độ sánh vừa đủ chấm bánh mì mà không bị đặc vón cục.', NULL),
('imp-3ec27a2b8f5e4345_v4_step_1', 'imp-3ec27a2b8f5e4345', 1, 'prep', 'Làm sạch gà và sơ chế gừng, ớt hiểm', 'Chà xát 700 g đùi gà với 4 g muối hạt cho sạch nhớt và khử mùi tanh, rửa lại nước lạnh rồi để ráo, chặt miếng vừa ăn cỡ 3,5–4 cm. Gừng cạo vỏ, chia đôi một nửa thái sợi mỏng và một nửa thái lát; ớt hiểm bỏ cuống đập dập nhẹ; hành tím và tỏi băm nhỏ; hành lá cắt khúc 3 cm.', 'Đập dập nhẹ ớt hiểm giúp tinh dầu cay tỏa đều vào nước kho mà không làm vỡ nát quá nhiều hạt ớt.', NULL),
('imp-3ec27a2b8f5e4345_v4_step_2', 'imp-3ec27a2b8f5e4345', 2, 'marinate', 'Ướp đùi gà với gừng sợi và nước mắm', 'Ướp thịt gà trong tô lớn cùng phần gừng thái sợi, 25 ml nước mắm ngon, 8 g đường cát trắng, 3 g muối và 1 g tiêu đen xay. Trộn đều rồi ướp ít nhất 25 phút cho thịt ngấm đậm gia vị.', 'Dùng gừng già thái sợi mỏng ướp cùng thịt gà giúp hương thơm cay ấm thấm sâu vào từng thớ thịt.', 25),
('imp-3ec27a2b8f5e4345_v4_step_3', 'imp-3ec27a2b8f5e4345', 3, 'sauce', 'Thắng nước màu và phi thơm hành tỏi gừng', 'Làm nóng nồi đáy dày hoặc nồi đất với 25 ml dầu ăn và 12 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan và chuyển màu nâu cánh gián. Cho nhanh hành tím, tỏi băm và phần gừng thái lát vào phi thơm khoảng 1 phút.', 'Kho bằng nồi đất hoặc nồi gang giữ nhiệt ổn định giúp thịt gà mềm thấm và nước kho sánh bóng nhanh hơn.', NULL),
('imp-3ec27a2b8f5e4345_v4_step_4', 'imp-3ec27a2b8f5e4345', 4, 'cook', 'Xào săn thịt gà trên lửa lớn', 'Vặn lửa lớn, trút toàn bộ thịt gà đã ướp vào nồi đảo liên tục trong 5 phút cho đến khi da gà săn lại, bề mặt miếng thịt đổi màu vàng nâu óng ả và thấm đều hương gừng tỏi.', NULL, 5),
('imp-3ec27a2b8f5e4345_v4_step_5', 'imp-3ec27a2b8f5e4345', 5, 'cook', 'Kho nhỏ lửa với ớt hiểm cho thấm vị', 'Thêm 20 ml nước mắm còn lại, 4 quả ớt hiểm và 80 ml nước lọc ấm vào nồi, đảo đều rồi đợi nước sôi lại. Hạ lửa nhỏ, đậy nắp kho liu riu trong 20 phút và thỉnh thoảng trở mặt để thịt gà chín kỹ tận xương.', NULL, 20),
('imp-3ec27a2b8f5e4345_v4_step_6', 'imp-3ec27a2b8f5e4345', 6, 'finish', 'Sánh sốt và rắc hành lá hoàn thiện', 'Mở nắp, tăng lửa vừa kho thêm 3 phút cho nước sốt cạn sánh sệt bám quanh từng miếng thịt gà. Nêm lại vừa miệng, tắt bếp rồi rắc hành lá cắt khúc và 1 g tiêu đen xay còn lại lên trên, dọn dùng nóng.', NULL, NULL),
('imp-323aae415415eb28_v4_step_1', 'imp-323aae415415eb28', 1, 'prep', 'Làm sạch tôm với nước muối chanh loãng', 'Pha 4 g muối hạt và phần lớn nước cốt của 1/2 quả chanh tươi vào tô nước lạnh (chừa lại vài giọt chanh). Ngâm rửa nhanh 400 g tôm trong 1 phút cho hết mùi tanh, xả lại nước sạch rồi cắt bớt râu, rút chỉ đen trên lưng và để thật ráo nước.', NULL, NULL),
('imp-323aae415415eb28_v4_step_2', 'imp-323aae415415eb28', 2, 'prep', 'Sơ chế tiêu xanh và hành tỏi thơm', 'Rửa sạch 30 g tiêu xanh tươi, lấy một nửa số hạt đập dập nhẹ cho tiết tinh dầu, phần còn lại giữ nguyên nhánh. Băm nhỏ hành tím, tỏi khô và đầu hành lá; lá hành cắt khúc 2,5 cm; ớt hiểm thái lát mỏng.', 'Đập dập nhẹ một phần tiêu xanh khi ướp giúp vị cay thơm thấm vào thịt tôm, trong khi giữ nguyên chùm cho vào sau giúp món ăn bắt mắt.', NULL),
('imp-323aae415415eb28_v4_step_3', 'imp-323aae415415eb28', 3, 'marinate', 'Ướp tôm cùng tiêu xanh đập dập', 'Trộn đều tôm với một nửa hành tím và tỏi băm, đầu hành băm, phần tiêu xanh đập dập, 30 ml nước mắm, 8 g đường cát trắng và 4 g hạt nêm. Ướp trong 15 phút cho thịt tôm săn và đậm đà.', 'Tôm tươi chỉ cần ướp khoảng 15 phút là đủ ngấm vị, ướp quá lâu với muối mắm dễ làm thịt tôm bị bở.', 15),
('imp-323aae415415eb28_v4_step_4', 'imp-323aae415415eb28', 4, 'sauce', 'Thắng nước màu và xào săn tôm', 'Đun nóng nồi đất hoặc chảo với 25 ml dầu ăn và 10 g đường cát trắng còn lại trên lửa nhỏ đến khi đường chuyển màu nâu cánh gián. Trút phần hành tím, tỏi băm còn lại vào phi thơm 30 giây, rồi vặn lửa lớn cho tôm vào đảo nhanh 3 phút đến khi tôm cong đỏ đều.', NULL, 3),
('imp-323aae415415eb28_v4_step_5', 'imp-323aae415415eb28', 5, 'cook', 'Kho mở nắp với tiêu xanh nguyên chùm', 'Rót 100 ml nước lọc nóng vào nồi, thả các nhánh tiêu xanh nguyên chùm còn lại vào cùng. Hạ lửa vừa nhỏ, kho không đậy nắp trong 8 phút, đảo nhẹ vài lần cho tôm chín hồng hoàn toàn và nước sốt rút sánh bóng bám quanh vỏ tôm.', 'Không đậy nắp và không kho quá lâu để tôm giữ được độ giòn ngọt tự nhiên mà không bị bở thịt.', 8),
('imp-323aae415415eb28_v4_step_6', 'imp-323aae415415eb28', 6, 'finish', 'Hoàn thiện hương vị và bày đĩa', 'Thả hành lá cắt khúc và ớt hiểm thái lát vào đảo nhẹ, tắt bếp rồi rắc 1,5 g tiêu đen xay và vắt thêm vài giọt nước cốt chanh tươi còn lại cho dậy hương thanh nhẹ. Dọn nóng ngay với cơm trắng.', NULL, NULL),
('imp-3f1ad35e1f1ec87f_v4_step_1', 'imp-3f1ad35e1f1ec87f', 1, 'prep', 'Nướng thơm, đập mềm và xé sợi mực khô', 'Kẹp 280 g mực khô vào vỉ, nướng trên bếp lửa nhỏ hoặc nồi chiên không dầu ở 180°C khoảng 3–4 phút cho mực vừa cong thơm đều hai mặt, tránh nướng quá lâu làm mực khô cứng. Bọc mực nóng trong giấy sạch dùng chày đập nhẹ cho mềm tơi, rũ sạch vụn cháy rồi xé sợi bản rộng cỡ 1 cm.', 'Đập mềm mực ngay khi còn nóng giúp các thớ thịt tơi mềm và dễ thấm đều nước sốt dứa khi rim.', 4),
('imp-3f1ad35e1f1ec87f_v4_step_2', 'imp-3f1ad35e1f1ec87f', 2, 'prep', 'Vắt nước cốt dứa và rang vàng mè trắng', 'Gọt vỏ bỏ mắt 1/2 quả dứa chín, băm nhuyễn hoặc giã nát rồi vắt qua rây thu lấy phần nước cốt dứa thơm ngọt, bỏ bã. Rang khô 15 g hạt mè trắng trên chảo lửa nhỏ khoảng 2 phút đến khi vàng thơm rồi trút ra chén riêng.', NULL, 2),
('imp-3f1ad35e1f1ec87f_v4_step_3', 'imp-3f1ad35e1f1ec87f', 3, 'sauce', 'Pha hỗn hợp nước sốt dứa chua cay mặn ngọt', 'Cho toàn bộ nước cốt dứa vào tô lớn, thêm 25 ml nước mắm ngon, 20 ml dầu hào, 20 ml tương cà, 20 ml tương ớt, 20 g đường cát trắng, 40 ml nước lọc và 3 quả ớt hiểm băm nhỏ. Khuấy đều đến khi đường tan hoàn toàn.', NULL, NULL),
('imp-3f1ad35e1f1ec87f_v4_step_4', 'imp-3f1ad35e1f1ec87f', 4, 'cook', 'Phi thơm hành tỏi và đun sôi hỗn hợp sốt', 'Làm nóng chảo rộng với 25 ml dầu ăn trên lửa vừa, phi thơm hành tím và tỏi băm khoảng 1 phút đến khi vừa ngả vàng. Đổ chén nước sốt dứa vào chảo đun sôi nhẹ trong 2 phút cho sốt hòa quyện và nếm chỉnh độ chua cay ngọt vừa miệng.', 'Nêm nếm độ chua ngọt ngay khi sốt đang sôi nhẹ trước khi thả mực vào sẽ giúp điều chỉnh hương vị chuẩn xác hơn.', 2),
('imp-3f1ad35e1f1ec87f_v4_step_5', 'imp-3f1ad35e1f1ec87f', 5, 'cook', 'Rim nhỏ lửa cho mực thấm kẹo nước sốt', 'Trút toàn bộ mực khô xé sợi vào chảo sốt, đảo đều rồi hạ lửa nhỏ nhất, rim liu riu trong 10 phút và đảo liên tục để từng sợi mực hút cạn nước sốt, chuyển màu đỏ nâu sánh bóng dẻo ngon.', 'Luôn giữ lửa nhỏ khi rim để đường và tương ớt không bị cháy khét đáy chảo trước khi mực kịp ngấm đều.', 10),
('imp-3f1ad35e1f1ec87f_v4_step_6', 'imp-3f1ad35e1f1ec87f', 6, 'finish', 'Trộn ớt bột, mè rang và hoàn thiện', 'Khi nước sốt đã keo đặc bám trọn quanh miếng mực, rắc 2 g ớt bột khô và 15 g mè trắng rang vàng vào đảo đều 30 giây rồi tắt bếp. Để mực nguội bớt trước khi gắp ra đĩa và rắc thêm 1,5 g tiêu đen xay lên trên.', NULL, NULL),
('imp-64e505d497388f4a_v4_step_1', 'imp-64e505d497388f4a', 1, 'marinate', 'Thấm khô và ướp cá hồi với muối tiêu chanh', 'Thấm thật khô 3 miếng cá hồi phi lê bằng khăn giấy sạch, xoa đều 2 g muối ăn, 2 g tiêu đen xay và 20 ml nước cốt chanh tươi lên các mặt miếng cá rồi để ướp 10 phút cho thịt cá săn và thơm.', 'Lau thật khô bề mặt da cá trước khi áp chảo giúp lớp da áp nhiệt trực tiếp nhanh chóng vàng giòn mà không bị dính chảo.', 10),
('imp-64e505d497388f4a_v4_step_2', 'imp-64e505d497388f4a', 2, 'prep', 'Chuẩn bị tỏi, hành tím, ớt và hành lá', 'Tỏi khô và hành tím bóc vỏ, băm nhỏ; ớt tươi băm nhỏ; hành lá thái nhuyễn. Cắt thêm vài lát chanh mỏng và thái lát quả cà chua tươi (nếu dùng) để ăn kèm.', NULL, NULL),
('imp-64e505d497388f4a_v4_step_3', 'imp-64e505d497388f4a', 3, 'cook', 'Áp chảo cá hồi da giòn trên lửa vừa', 'Đặt chảo chống dính lên bếp, đun nóng 20 ml dầu ăn trên lửa vừa, đặt mặt da cá hồi xuống trước và ấn nhẹ 15 giây cho da phẳng sát đáy chảo. Áp chảo yên mặt da trong 3 phút cho vàng giòn, rồi nhẹ nhàng trở mặt nấu thêm 2 phút cho hai bên chín vừa tới và thịt cá chuyển hồng nhạt mọng nước, gắp cá ra đĩa nghỉ.', 'Không di chuyển miếng cá liên tục trong lúc áp chảo và tránh nấu quá lâu khiến cá hồi bị khô xác.', 5),
('imp-64e505d497388f4a_v4_step_4', 'imp-64e505d497388f4a', 4, 'sauce', 'Nấu sốt bơ tỏi chanh nước mắm sánh thơm', 'Dùng chảo sạch trên lửa nhỏ, cho 15 g bơ lạt vào đun chảy rồi thêm tỏi băm, hành tím băm và ớt băm (nếu ăn cay) phi thơm khoảng 1 phút cho vừa dậy mùi. Rót 20 ml nước mắm ngon, 20 ml nước cốt chanh còn lại và 8 g đường cát trắng vào khuấy tan sôi lăn tăn trong 1 phút cho sốt hơi sánh.', 'Giữ lửa nhỏ khi đun chảy bơ lạt để bơ không bị cháy khét, đồng thời giúp tỏi hành dậy mùi thơm dịu.', 2),
('imp-64e505d497388f4a_v4_step_5', 'imp-64e505d497388f4a', 5, 'cook', 'Áo nhanh sốt tỏi chanh lên cá hồi', 'Đặt các miếng cá hồi vừa áp chảo trở lại chảo sốt, dùng thìa rưới liên tục phần sốt bơ tỏi chanh nóng lên mặt thịt cá khoảng 1 phút trên lửa nhỏ để hương vị ngấm đều mà vẫn giữ nguyên độ giòn của lớp da.', 'Rưới liên tục sốt bơ tỏi chanh lên mặt thịt cá thay vì nấu lâu trên bếp giúp cá hồi giữ trọn độ mọng mềm bên trong.', 1),
('imp-64e505d497388f4a_v4_step_6', 'imp-64e505d497388f4a', 6, 'finish', 'Bày đĩa cùng cà chua và dùng nóng', 'Gắp cá hồi ra đĩa, rưới toàn bộ phần sốt còn lại trong chảo lên trên, rắc hành lá thái nhỏ và 1 g tiêu đen xay còn lại, trang trí vài lát chanh và cà chua tươi bên cạnh rồi thưởng thức ngay khi nóng.', NULL, NULL),
('imp-6e4c264764981b8b_v4_step_1', 'imp-6e4c264764981b8b', 1, 'prep', 'Sơ chế thịt đùi gà và rau gia vị', 'Rửa sạch thịt đùi gà lọc xương, thấm khô rồi cắt miếng vuông vừa ăn khoảng 2,5–3 cm. Sả tươi đập dập băm nhuyễn; hành tím khô và tỏi khô băm nhỏ; ớt hiểm đỏ tươi thái lát mỏng; hành tây bóc vỏ bổ múi cau.', NULL, NULL),
('imp-6e4c264764981b8b_v4_step_2', 'imp-6e4c264764981b8b', 2, 'marinate', 'Ướp thịt đùi gà thấm vị nước mắm', 'Cho thịt đùi gà vào tô, trộn đều cùng 15 ml nước mắm ngon, 4 g hạt nêm và 1/3 lượng tỏi băm. Bọc kín và ướp trong 20 phút cho miếng gà ngấm đậm gia vị.', 'Ướp thịt gà trước với nước mắm giúp thớ thịt săn chắc, thơm nồng từ bên trong khi gặp lửa.', 20),
('imp-6e4c264764981b8b_v4_step_3', 'imp-6e4c264764981b8b', 3, 'cook', 'Phi thơm hành tím, tỏi, sả và ớt', 'Đặt chảo lên bếp lửa vừa, làm nóng 30 ml dầu ăn rồi cho hành tím băm và 2/3 phần tỏi băm còn lại vào phi thơm 30 giây. Tiếp tục thả sả băm và ớt hiểm thái lát vào đảo đều khoảng 1,5 phút đến khi sả ngả vàng nhẹ và dậy mùi thơm nồng.', 'Phi hành tỏi trước rồi mới cho sả vào giúp tất cả nguyên liệu thơm chín đều mà tỏi không bị cháy.', NULL),
('imp-6e4c264764981b8b_v4_step_4', 'imp-6e4c264764981b8b', 4, 'cook', 'Xào săn thịt gà trên lửa lớn', 'Tăng lên lửa lớn, trút toàn bộ thịt gà đã ướp vào chảo sả ớt và đảo đều tay khoảng 3 phút cho bề mặt thịt gà săn lại và áo đều sả băm thơm lừng.', NULL, 3),
('imp-6e4c264764981b8b_v4_step_5', 'imp-6e4c264764981b8b', 5, 'cook', 'Om thấm gia vị cho thịt gà chín hoàn toàn', 'Hạ xuống lửa vừa, thêm 8 g đường vàng, 4 g hạt nêm còn lại, 3 g muối ăn và 45 ml nước lọc vào chảo. Đảo đều rồi đậy nắp hờ, rim nhỏ lửa khoảng 8–10 phút cho thịt gà chín kỹ hoàn toàn từ trong ra ngoài (không còn màu hồng ở lõi) và phần nước sốt sánh sệt lại.', 'Rim gà với chút nước lọc giúp thịt đùi gà chín mềm mọng nước mà đường không bị cháy sậm.', 9),
('imp-6e4c264764981b8b_v4_step_6', 'imp-6e4c264764981b8b', 6, 'finish', 'Đảo hành tây giòn ngọt và dọn đĩa', 'Mở nắp, tăng lên lửa lớn và cho hành tây bổ múi cau vào đảo nhanh tay thêm 1,5 phút cho hành vừa chín tới vẫn giữ độ giòn ngọt. Nêm nếm lại cho vừa khẩu vị rồi tắt bếp, múc ra đĩa dùng nóng với cơm trắng.', NULL, NULL),
('imp-53760c13ec1e452b_v4_step_1', 'imp-53760c13ec1e452b', 1, 'marinate', 'Làm sạch và ướp tôm tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch lưng rút bỏ chỉ đen rồi rửa sạch, thấm ráo nước. Cho tôm vào tô ướp với 2,5 g hạt nêm, 2 g muối ăn và một nửa lượng tiêu đen xay, trộn đều để thấm trong 10 phút.', NULL, 10),
('imp-53760c13ec1e452b_v4_step_2', 'imp-53760c13ec1e452b', 2, 'prep', 'Nhặt giá đỗ và chuẩn bị hành tỏi', 'Giá đỗ nhặt bỏ rễ và vỏ đậu nếu có, rửa nhẹ nhàng 2 lần nước rồi vẩy thật ráo để khi xào không ra nước. Hành tím khô và tỏi khô bóc vỏ băm nhỏ; hành lá rửa sạch cắt khúc dài 4 cm.', 'Để giá đỗ thật ráo nước trước khi cho vào chảo là yếu tố quyết định giúp món xào giòn khô, không bị sũng nước.', NULL),
('imp-53760c13ec1e452b_v4_step_3', 'imp-53760c13ec1e452b', 3, 'cook', 'Phi thơm hành tỏi và xào chín tôm', 'Làm nóng 20 ml dầu ăn trong chảo rộng trên lửa vừa-lớn, cho hành tím và tỏi băm vào phi thơm 30 giây. Tăng lên lửa lớn, trút tôm đã ướp vào đảo nhanh tay khoảng 2 phút đến khi tôm chuyển màu đỏ cam đều, thân cong săn chắc và chín hoàn toàn.', NULL, 2),
('imp-53760c13ec1e452b_v4_step_4', 'imp-53760c13ec1e452b', 4, 'cook', 'Xào nhanh giá đỗ lửa lớn giữ độ giòn', 'Giữ nguyên lửa lớn nhất, trút toàn bộ giá đỗ vào chảo tôm và đảo đều tay liên tục. Rưới 10 ml nước mắm ngon, thêm 2,5 g hạt nêm và 2 g muối ăn còn lại, xào nhanh trong khoảng 1,5 phút cho giá vừa chín tới mà vẫn giòn mọng.', 'Chỉ xào giá đỗ trong 1,5–2 phút trên lửa lớn để giá không bị nhũn mềm và mất nước.', NULL),
('imp-53760c13ec1e452b_v4_step_5', 'imp-53760c13ec1e452b', 5, 'cook', 'Thêm hành lá và tắt bếp ngay', 'Thả hành lá cắt khúc vào chảo, đảo nhanh tay thêm 15–20 giây cho hành vừa chín xanh và nêm nếm lại cho vừa khẩu vị rồi tắt bếp ngay.', 'Tắt bếp ngay sau khi cho hành lá vì nhiệt dư trong chảo vẫn tiếp tục làm giá chín thêm.', NULL),
('imp-53760c13ec1e452b_v4_step_6', 'imp-53760c13ec1e452b', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Gắp tôm xào giá đỗ ra đĩa, rắc phần tiêu đen xay còn lại lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-a47ef9289f5d0136_v4_step_1', 'imp-a47ef9289f5d0136', 1, 'prep', 'Thái sợi cà rốt và chuẩn bị ngò rí, hành lá', 'Cà rốt gọt vỏ, rửa sạch rồi cắt khúc dài 5 cm và thái sợi nhỏ đều nhau dày khoảng 0,3 cm. Ngò rí và hành lá rửa sạch, thái nhỏ; tách riêng phần đầu hành trắng băm nhỏ, còn ngò rí chia làm hai phần.', 'Thái sợi cà rốt đều tay giúp cà rốt chín đồng đều và dễ quyện bám lấy từng mảng trứng.', NULL),
('imp-a47ef9289f5d0136_v4_step_2', 'imp-a47ef9289f5d0136', 2, 'prep', 'Đánh tan trứng gà với gia vị', 'Đập 3 quả trứng gà ta vào tô lớn, thêm 5 ml nước mắm ngon, 3 g hạt nêm, 2 g bột ngọt, một nửa lượng tiêu đen xay và 1/2 phần ngò rí thái nhỏ. Dùng đũa đánh bông đều cho lòng đỏ và lòng trắng hòa quyện hoàn toàn.', NULL, NULL),
('imp-a47ef9289f5d0136_v4_step_3', 'imp-a47ef9289f5d0136', 3, 'cook', 'Xào chín mềm sợi cà rốt', 'Làm nóng 10 ml dầu ăn trên chảo lửa vừa, cho đầu hành lá băm vào phi thơm 20 giây. Trút cà rốt thái sợi vào đảo đều, thêm 2 g hạt nêm còn lại và 30 ml nước lọc rồi xào khoảng 4–5 phút đến khi nước cạn ráo và sợi cà rốt chín mềm ngọt thì múc ra tô riêng.', 'Xào riêng cà rốt với một chút nước giúp cà rốt chín mềm hoàn toàn và giải phóng vị ngọt tự nhiên.', 4),
('imp-a47ef9289f5d0136_v4_step_4', 'imp-a47ef9289f5d0136', 4, 'cook', 'Chiên đảo tơi trứng gà trên lửa vừa', 'Lau sạch chảo rồi đun nóng 10 ml dầu ăn còn lại ở lửa vừa-nhỏ. Rót tô trứng gà đã đánh vào chảo, chờ 20 giây cho mặt dưới hơi se lại rồi dùng đũa khuấy nhẹ tạo thành từng mảng trứng chín mềm ẩm khoảng 1,5–2 phút.', 'Giữ lửa vừa-nhỏ khi chiên trứng để trứng chín bông mềm, không bị khô xác.', 2),
('imp-a47ef9289f5d0136_v4_step_5', 'imp-a47ef9289f5d0136', 5, 'cook', 'Trộn đều cà rốt với trứng và hành lá', 'Trút toàn bộ cà rốt đã xào chín trở lại chảo trứng, đảo đều nhẹ tay khoảng 1 phút cho cà rốt và trứng quyện vào nhau đều màu. Cho phần hành lá thái nhỏ vào đảo thêm 15 giây rồi tắt bếp.', NULL, NULL),
('imp-a47ef9289f5d0136_v4_step_6', 'imp-a47ef9289f5d0136', 6, 'finish', 'Hoàn thiện hương ngò rí và dọn nóng', 'Bày cà rốt xào trứng gà ra đĩa, rắc phần ngò rí thái nhỏ và tiêu đen xay còn lại lên trên. Dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-abdcd797955a6d6a_v4_step_1', 'imp-abdcd797955a6d6a', 1, 'prep', 'Thấm khô đậu phụ và sơ chế cà chua bỏ vỏ', 'Đậu phụ rửa nhẹ dưới vòi nước, dùng khăn giấy thấm thật khô rồi cắt miếng vuông dày 1,5–2 cm. Cà chua chín khía nhẹ hình chữ thập ở đáy, chần nước sôi 1 phút rồi nhúng nước lạnh để bóc sạch vỏ, bỏ hạt và băm nhuyễn. Hành tím khô, tỏi khô và đầu hành trắng băm nhỏ; lá hành xanh và ngò rí thái nhỏ.', 'Thấm khô mặt đậu trước khi chiên giúp đậu không bị bắn dầu và dễ tạo lớp vỏ vàng giòn không nát.', NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-abdcd797955a6d6a_v4_step_2', 'imp-abdcd797955a6d6a', 2, 'cook', 'Áp chảo chiên vàng đều các mặt đậu phụ', 'Đun nóng 80 ml dầu ăn trong chảo chống dính trên lửa vừa. Nhẹ nhàng xếp từng miếng đậu phụ vào chiên khoảng 4–5 phút mỗi mặt cho đến khi các mặt chuyển màu vàng giòn nhẹ thì gắp ra đĩa lót giấy thấm dầu.', NULL, 5),
('imp-abdcd797955a6d6a_v4_step_3', 'imp-abdcd797955a6d6a', 3, 'sauce', 'Phi thơm hành tỏi và xào nhừ sốt cà chua', 'Chắt bớt dầu thừa ra chén, chỉ chừa lại khoảng 20 ml dầu ăn trong chảo. Cho hành tím, tỏi băm và đầu hành trắng vào phi thơm vàng nhẹ rồi trút toàn bộ cà chua băm nhuyễn vào đảo đều trên lửa vừa khoảng 4 phút đến khi cà chua nhừ ra sốt đỏ sánh.', 'Xào cà chua với chút muối ngay từ đầu giúp cà chua nhanh nhuyễn và tiết màu đỏ đẹp mắt.', 4),
('imp-abdcd797955a6d6a_v4_step_4', 'imp-abdcd797955a6d6a', 4, 'sauce', 'Nêm gia vị cân bằng sốt cà chua', 'Rót 60 ml nước lọc vào chảo cà chua, nêm 15 ml nước mắm ngon, 5 g đường cát trắng, 3 g muối ăn và 4 g hạt nêm. Khuấy đều và đun sôi liu riu khoảng 2 phút cho sốt hòa quyện đậm đà.', NULL, NULL),
('imp-abdcd797955a6d6a_v4_step_5', 'imp-abdcd797955a6d6a', 5, 'cook', 'Đảo đậu phụ thấm đều sốt cà chua', 'Nhẹ nhàng cho toàn bộ đậu phụ đã chiên vào chảo sốt cà chua, hạ lửa nhỏ và dùng đũa lật nhẹ tay để đậu áo đều sốt mà không bị vỡ nát. Đun liu riu thêm khoảng 4–5 phút cho đậu ngấm vị sốt chua ngọt.', 'Đảo nhẹ tay và đun lửa nhỏ giúp đậu phụ giữ nguyên hình khối đẹp mắt mà vẫn thấm sâu gia vị.', 5),
('imp-abdcd797955a6d6a_v4_step_6', 'imp-abdcd797955a6d6a', 6, 'finish', 'Thêm hành lá, ngò rí và dọn nóng', 'Cho hành lá thái khúc vào đảo nhẹ thêm 20 giây rồi tắt bếp. Múc đậu phụ xào cà chua ra đĩa sâu lòng, rắc ngò rí và 1,5 g tiêu đen xay lên trên, ăn nóng cùng cơm trắng.', NULL, NULL),
('imp-97f26ff4abe44f9b_v4_step_1', 'imp-97f26ff4abe44f9b', 1, 'prep', 'Ngâm nở nấm hương, mộc nhĩ và miến dong', 'Ngâm riêng 20 g nấm hương khô, 15 g mộc nhĩ khô và 70 g miến dong khô vào 350 ml nước lọc ấm trong khoảng 15 phút cho nở mềm vừa. Rửa sạch nấm hương và mộc nhĩ, cắt chân nấm, vắt thật kiệt nước rồi băm nhỏ; miến vớt ra để thật ráo rồi cắt khúc ngắn.', 'Ngâm riêng từng loại để hương nấm không lấn át nhau và bắt buộc phải vắt thật khô trước khi trộn nhân.', 15),
('imp-97f26ff4abe44f9b_v4_step_2', 'imp-97f26ff4abe44f9b', 2, 'prep', 'Bào sợi rau củ và chuẩn bị thịt cua', 'Cà rốt, củ đậu và khoai lang (nếu dùng) gọt vỏ, bào sợi thật mảnh và ngắn (giữ lại 20 g cà rốt thái lát mỏng cho nước chấm). Hành tây băm nhỏ; hành lá, rau mùi ta (nếu dùng) thái nhỏ. Kiểm tra kỹ 300 g thịt cua biển để loại bỏ hoàn toàn mảnh vỏ vụn.', 'Bào sợi mảnh giúp rau củ nhanh chín đều cùng thời gian chiên thịt cua mà vẫn giữ độ ngọt thanh.', NULL),
('imp-97f26ff4abe44f9b_v4_step_3', 'imp-97f26ff4abe44f9b', 3, 'prep', 'Trộn nhân thịt cua và lòng đỏ trứng gà', 'Trong âu lớn, trộn đều 350 g thịt nạc vai heo xay với nấm hương, mộc nhĩ, miến, cà rốt, củ đậu, khoai lang, hành tây, hành lá và rau mùi ta. Nêm 15 ml dầu ăn, 5 ml nước mắm ngon, 5 g hạt nêm và 3 g tiêu đen xay; ngay lúc chuẩn bị gói mới cho 2–3 lòng đỏ trứng gà vào trộn đều (giữ phần lòng trắng để dán mép), còn thịt cua để riêng.', NULL, NULL),
('imp-97f26ff4abe44f9b_v4_step_4', 'imp-97f26ff4abe44f9b', 4, 'prep', 'Thoa giấm loãng và gói nem cua bể hình vuông', 'Hòa 15 ml giấm gạo với 60 ml nước lọc, thoa nhẹ một lớp mỏng lên mặt bánh đa nem cho mềm dẻo rồi đặt thêm 1/4 lá vào giữa để chống vỡ. Múc 1,5 muỗng canh nhân thịt rau củ dàn thành hình vuông, đặt một phần thịt cua biển lên trên mặt nhân, gấp 4 góc bánh lại vuông vức và phết lòng trắng trứng dán kín mép.', 'Gói hơi lỏng tay một chút vì khi chiên nhân thịt và trứng sẽ nở phồng; đặt thịt cua lên trên giúp miếng nem cắt ra thấy rõ thớ cua ngon mắt.', NULL),
('imp-97f26ff4abe44f9b_v4_step_5', 'imp-97f26ff4abe44f9b', 5, 'cook', 'Rán nem ngập dầu hai lần lửa cho giòn lâu', 'Đun nóng 485 ml dầu ăn trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm. Thả nem vào rán lần 1 khoảng 7 phút cho vỏ se vàng nhạt và nhân chín khoảng 80% thì vớt ra để ráo nguội. Khi sắp dùng bữa, thả nem vào rán lại lần 2 ở lửa vừa-lớn thêm 3 phút đến khi vỏ vàng rộm giòn tan và nhân chín kỹ hoàn toàn, vớt ra giấy thấm dầu.', NULL, 10),
('imp-97f26ff4abe44f9b_v4_step_6', 'imp-97f26ff4abe44f9b', 6, 'finish', 'Pha nước chấm chua ngọt và dọn nem nóng', 'Khuấy tan 15 g đường cát trắng với 90 ml nước lọc ấm, thêm 45 ml nước mắm ngon và nước cốt của 1 quả chanh tươi cho vừa vị chua ngọt dịu, thả thêm tỏi băm, ớt băm và vài lát cà rốt mỏng vào. Cắt mỗi chiếc nem làm đôi hoặc làm tư, dọn nóng kèm rau sống và bún tươi.', NULL, NULL),
('imp-03cb4c492e643034_v4_step_1', 'imp-03cb4c492e643034', 1, 'marinate', 'Làm sạch tôm và ướp muối tiêu', 'Tôm tươi bỏ đầu, bóc vỏ, khía nhẹ dọc sống lưng để rút sạch chỉ đen rồi thấm thật ráo nước bằng khăn giấy. Ướp tôm với 1 g muối ăn và 0,5 g tiêu đen xay trong 5 phút cho thịt tôm săn và đậm đà.', NULL, 5),
('imp-03cb4c492e643034_v4_step_2', 'imp-03cb4c492e643034', 2, 'prep', 'Hòa bột bắp và đánh tan hỗn hợp trứng', 'Khuấy tan hoàn toàn 10 g bột bắp với 30 ml nước lọc trong chén nhỏ. Đập 4 quả trứng gà vào tô lớn, đổ nước bột bắp vào cùng 10 ml nước mắm ngon, 1 g muối ăn, 0,5 g tiêu đen xay, hành tím băm và hành lá thái nhỏ rồi đánh tan đều nhẹ tay.', 'Cho nước bột bắp vào trứng giúp cấu trúc trứng mềm mịn, bóng đẹp và không bị khô rách khi chiên lớp mỏng.', NULL),
('imp-03cb4c492e643034_v4_step_3', 'imp-03cb4c492e643034', 3, 'cook', 'Xào nhanh tôm tươi chín tới trên lửa lớn', 'Đun nóng 10 ml dầu ăn trong chảo chống dính trên lửa lớn, thả tôm đã ướp vào đảo nhanh tay khoảng 2 phút đến khi tôm chuyển màu đỏ hồng cong nhẹ và chín tới hoàn toàn, trút ngay ra đĩa để riêng.', 'Xào tôm nhanh ở lửa lớn giúp tôm chín săn, giữ trọn vị ngọt mà không ra nước vào trứng ở bước sau.', 2),
('imp-03cb4c492e643034_v4_step_4', 'imp-03cb4c492e643034', 4, 'cook', 'Tráng lớp trứng mỏng và xếp tôm lên mặt', 'Lau sạch chảo, đun nóng 20 ml dầu ăn còn lại trên lửa vừa rồi hạ lửa nhỏ. Đổ toàn bộ tô trứng vào, nghiêng chảo dàn đều thành lớp mỏng phủ khắp đáy chảo. Ngay khi viền và mặt trứng bắt đầu se lại nhưng mặt trên còn hơi ướt, xếp đều toàn bộ tôm đã xào lên trên mặt trứng.', NULL, NULL),
('imp-03cb4c492e643034_v4_step_5', 'imp-03cb4c492e643034', 5, 'cook', 'Đậy nắp chiên lửa nhỏ cho trứng chín đều', 'Đậy nắp chảo và chiên tiếp ở lửa nhỏ khoảng 3–4 phút cho đến khi mặt dưới vàng ươm và lớp trứng mặt trên chín đông hoàn toàn quanh từng con tôm mà không cần lật mặt.', 'Đậy nắp ở lửa nhỏ giúp hơi nhiệt tuần hoàn làm chín mặt trên của lớp trứng mỏng, tránh làm vỡ trứng khi lật.', 4),
('imp-03cb4c492e643034_v4_step_6', 'imp-03cb4c492e643034', 6, 'finish', 'Trượt trứng ra đĩa và cắt miếng thưởng thức', 'Tắt bếp, nhẹ nhàng trượt miếng trứng chiên tôm ra đĩa phẳng, cắt thành từng miếng vuông hoặc tam giác vừa ăn và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-c4a65718d5cd4b3c_v4_step_1', 'imp-c4a65718d5cd4b3c', 1, 'prep', 'Hấp chín đậu xanh, ngâm nấm và vắt ráo đậu phụ', 'Hấp chín 80 g đậu xanh cà vỏ đã ngâm mềm sao cho hạt chín bở tơi mà không nhão ướt, để nguội tán nhẹ. Ngâm 15 g mộc nhĩ khô và 40 g miến dong vào 220 ml nước ấm 12 phút cho nở mềm rồi vớt ráo, băm nhỏ mộc nhĩ và cắt ngắn miến. Chần nhanh 3 miếng đậu phụ trắng qua nước sôi, bọc khăn xô vắt thật kiệt nước rồi bóp vụn.', 'Vắt thật ráo đậu phụ và nấu đậu xanh khô tơi là bí quyết giúp nhân chả giò chay không bị chảy nước làm rách vỏ bánh.', 12),
('imp-c4a65718d5cd4b3c_v4_step_2', 'imp-c4a65718d5cd4b3c', 2, 'prep', 'Sơ chế nấm đùi gà, rau củ và xào khô nhân', 'Nấm đùi gà, khoai lang bào sợi mảnh ngắn; cà rốt bào sợi 70 g (chừa 12 g băm nhỏ cho nước chấm); củ đậu bào sợi bóp với 1 g muối ăn rồi vắt ráo; hành lá thái nhỏ. Làm nóng 20 ml dầu ăn trên lửa vừa, phi vàng hành tím (nếu dùng) vớt riêng, rồi cho đậu phụ và nấm đùi gà vào xào ráo 3 phút cùng 5 ml nước mắm chay và 2 g hạt nêm chay nấm hương.', NULL, 3),
('imp-c4a65718d5cd4b3c_v4_step_3', 'imp-c4a65718d5cd4b3c', 3, 'prep', 'Trộn hoàn chỉnh nhân và pha hồ dán mép', 'Trong âu lớn, trộn nhẹ tay đậu phụ nấm vừa xào nguội bớt cùng đậu xanh, mộc nhĩ, miến, khoai lang, củ đậu, cà rốt sợi, hành lá, hành phi, 3 g hạt nêm chay còn lại, 1 g muối ăn, 4 g đường và 2 g tiêu đen xay. Hòa 16 g bột mì đa dụng với 30 ml nước lọc thành hồ sệt để dán mép bánh.', NULL, NULL),
('imp-c4a65718d5cd4b3c_v4_step_4', 'imp-c4a65718d5cd4b3c', 4, 'prep', 'Cuốn chả giò chay chặt vừa tay', 'Trải từng lá bánh tráng lên mặt phẳng sạch (có thể lót thêm 1/2 lá vào giữa nếu vỏ mỏng), múc khoảng 1,5 muỗng canh nhân đặt vào đầu bánh, gấp hai mép bên rồi cuộn tròn đều tay thành khoảng 20 cuốn vừa ăn, phết hồ bột mì dán kín mép ngoài.', 'Cuốn chả giò có độ chặt vừa phải, kích thước đồng đều để khi thả vào chảo dầu chín vàng cùng lúc.', NULL),
('imp-c4a65718d5cd4b3c_v4_step_5', 'imp-c4a65718d5cd4b3c', 5, 'cook', 'Chiên chả giò ngập dầu hai lần lửa', 'Đun nóng 480 ml dầu ăn trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm. Thả chả giò vào chiên lần 1 khoảng 5 phút đến khi vỏ se vàng nhạt thì vớt ra giá để nguội. Trước khi ăn, chiên lại lần 2 ở lửa vừa-lớn thêm 3 phút cho đến khi vỏ vàng ruộm giòn rụm đều các mặt, vớt ra giấy thấm dầu.', 'Chiên ngập dầu hai lần lửa giúp vỏ bánh tráng giòn xốp lâu hơn hẳn và không bị ỉu khi chấm nước mắm chay.', 8),
('imp-c4a65718d5cd4b3c_v4_step_6', 'imp-c4a65718d5cd4b3c', 6, 'finish', 'Nấu nước mắm chay chua ngọt và dọn ăn nóng', 'Đun sôi nhẹ 50 ml nước mắm chay với 26 g đường cát trắng còn lại và 50 ml nước lọc cho tan sánh rồi tắt bếp để nguội hẳn. Khi nguội, khuấy vào nước cốt của 1 quả chanh tươi cùng cà rốt băm nhuyễn, tỏi băm và ớt băm (nếu dùng). Dọn chả giò chay nóng giòn ăn kèm rau sống và bún.', 'Luôn đợi nước mắm chay nguội hẳn mới khuấy nước cốt chanh vào để giữ vị chua thanh và không bị đắng.', NULL),
('imp-f3c2431be267b74d_v4_step_1', 'imp-f3c2431be267b74d', 1, 'prep', 'Làm sạch cá điêu hồng và khứa thân', 'Đánh sạch vảy, bỏ mang, moi ruột và cạo sạch màng đen dọc khoang bụng cá điêu hồng. Chà xát 10 g muối hạt đều khắp trong ngoài thân cá trong 2 phút để khử sạch nhớt tanh, xả lại dưới vòi nước lạnh rồi thấm thật khô, khứa 3 đường chéo nông trên mỗi mặt cá.', 'Thấm thật ráo nước trên thân cá sau khi rửa muối giúp sốt ướp bám chặt vào từng thớ thịt và cá giữ được độ săn ngọt.', NULL),
('imp-f3c2431be267b74d_v4_step_2', 'imp-f3c2431be267b74d', 2, 'prep', 'Sơ chế dứa chín, gừng, hành tây và rau thơm', 'Gọt vỏ nửa quả dứa chín, bỏ mắt và lõi cứng rồi thái lát mỏng dày 0,5 cm. Cạo vỏ gừng: 15 g thái lát mỏng, 25 g thái sợi chỉ. Hành tây bóc vỏ cắt múi cau mỏng; hành tím thái lát mỏng; ớt sừng bỏ hạt thái sợi; hành lá và thì là rửa sạch cắt khúc 4 cm.', NULL, NULL),
('imp-f3c2431be267b74d_v4_step_3', 'imp-f3c2431be267b74d', 3, 'marinate', 'Pha sốt và ướp cá điêu hồng thấm gia vị', 'Khuấy tan hỗn hợp gồm 30 ml nước mắm ngon, 15 ml xì dầu, 15 ml dầu hào, 8 g đường cát trắng, 4 g hạt nêm và 2 g tiêu đen xay. Thoa đều sốt lên khắp hai mặt thân cá và cả bên trong bụng cá, nhét phần gừng thái lát và hành tím thái lát vào bụng rồi ướp 20 phút cho ngấm.', 'Ướp cá đủ 20 phút và thoa sốt vào cả các đường khứa giúp thịt cá phía sát xương cũng đậm đà hương vị.', 20),
('imp-f3c2431be267b74d_v4_step_4', 'imp-f3c2431be267b74d', 4, 'cook', 'Xếp dứa lót đáy và hấp cá lửa lớn', 'Xếp một nửa số lát dứa chín và hành tây cắt múi xuống đáy đĩa sâu lòng chịu nhiệt, đặt cá đã ướp lên trên, rưới nốt phần sốt ướp còn thừa cùng phần dứa, hành tây, gừng sợi và ớt thái sợi phủ mặt cá. Đun sôi 700 ml nước lọc trong nồi hấp ở lửa lớn, đặt đĩa cá vào xửng đậy kín nắp và hấp 18 phút.', 'Lót dứa và hành tây dưới bụng cá vừa ngăn da cá bị dính đĩa, vừa giúp hơi nóng lưu thông đều và tiết nước ngọt tự nhiên.', 18),
('imp-f3c2431be267b74d_v4_step_5', 'imp-f3c2431be267b74d', 5, 'cook', 'Thêm hành lá, thì là hấp chín tới', 'Mở nắp xửng, xếp hành lá và thì là cắt khúc lên mặt cá, đậy nắp hấp tiếp thêm 3 phút trên lửa vừa đến khi mắt cá đục trắng, dùng đũa tách nhẹ thấy thịt cá trắng đục chín mềm và rau thơm vừa chín tới vẫn giữ màu xanh mướt.', NULL, 3),
('imp-f3c2431be267b74d_v4_step_6', 'imp-f3c2431be267b74d', 6, 'finish', 'Rưới dầu mè thơm và dọn thưởng thức nóng', 'Nhấc đĩa cá ra khỏi nồi hấp cẩn thận, rưới 5 ml dầu mè thơm đều lên thân cá cho dậy mùi hấp dẫn, chan nhẹ nước hấp dứa chua ngọt xung quanh và dùng nóng ngay với cơm trắng hoặc cuốn bánh tráng rau sống.', NULL, NULL),
('imp-6118e8aa010584af_v4_step_1', 'imp-6118e8aa010584af', 1, 'marinate', 'Làm sạch và ướp tôm tươi thái hạt lựu', 'Tôm tươi bóc sạch vỏ, bỏ đầu và rút chỉ đen dọc lưng, rửa qua nước muối loãng rồi thấm thật ráo. Thái tôm thành hạt lựu nhỏ (hoặc băm thô) để giữ độ giòn ngọt, ướp tôm với 4 ml nước mắm và 1 g tiêu đen xay trong 10 phút cho thấm vị.', NULL, 10),
('imp-6118e8aa010584af_v4_step_2', 'imp-6118e8aa010584af', 2, 'prep', 'Đánh nhẹ trứng gà với nước lọc theo tỉ lệ chuẩn', 'Đập 4 quả trứng gà vào tô sạch, thêm 240 ml nước lọc nguội, 6 ml nước mắm còn lại và 4 g hạt nêm. Dùng đũa khuấy thật nhẹ nhàng theo một chiều cho gia vị tan đều mà không đánh nổi bọt khí quá nhiều.', 'Tỉ lệ khoảng 1,5 phần nước nguội so với 1 phần ruột trứng là bí quyết giúp món trứng hấp mềm rung rinh như tàu hũ non.', NULL),
('imp-6118e8aa010584af_v4_step_3', 'imp-6118e8aa010584af', 3, 'prep', 'Lọc rây trứng và dàn tôm lên mặt tô', 'Rót hỗn hợp trứng qua rây lưới mịn vào đĩa sâu lòng hoặc tô sứ chịu nhiệt để loại bỏ lợn cợn và bọt khí, dùng thìa hớt sạch phần bọt nhỏ nếu còn sót trên bề mặt. Nhẹ nhàng rải đều phần tôm đã ướp lên mặt trứng rồi bọc kín miệng tô bằng màng bọc thực phẩm chịu nhiệt (hoặc đậy đĩa vừa khít).', 'Bọc kín miệng tô bằng màng bọc chịu nhiệt giúp hơi nước ngưng tụ từ nắp nồi không nhỏ giọt làm rỗ bề mặt trứng hấp.', NULL),
('imp-6118e8aa010584af_v4_step_4', 'imp-6118e8aa010584af', 4, 'cook', 'Hấp cách thủy lửa nhỏ cho trứng mịn mượt', 'Đun sôi 600 ml nước lọc trong nồi hấp rồi hạ ngay xuống lửa nhỏ liu riu, đặt tô trứng vào xửng và đậy nắp hấp khoảng 16 phút. Hơi nóng dịu nhẹ sẽ làm trứng đông mịn dần và thịt tôm chín đỏ au nổi đẹp trên bề mặt.', 'Không để nước sôi quá mạnh hoặc đậy nắp kín hoàn toàn không thoát hơi khi không dùng màng bọc, vì hơi nước mạnh sẽ làm mặt trứng bị rỗ.', 16),
('imp-6118e8aa010584af_v4_step_5', 'imp-6118e8aa010584af', 5, 'prep', 'Chẻ hành lá trang trí tạo độ tươi xanh', 'Trong lúc chờ trứng chín, rửa sạch hành lá tươi, thái nhỏ một nửa và chẻ sợi phần còn lại ngâm nhanh vào chén nước mát cho xoăn nhẹ rồi vớt ra để ráo.', NULL, NULL),
('imp-6118e8aa010584af_v4_step_6', 'imp-6118e8aa010584af', 6, 'finish', 'Kiểm tra độ chín và hoàn thiện món ăn', 'Thử xiên tăm vào giữa tô trứng thấy tăm khô sạch không dính dịch lỏng và tôm đã chuyển đỏ hoàn toàn là đạt. Nhấc tô trứng ra, rắc hành lá tươi, 1 g tiêu đen xay còn lại và rưới 5 ml dầu mè thơm lên trên rồi thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-4ced29ad30507f2c_v4_step_1', 'imp-4ced29ad30507f2c', 1, 'cook', 'Luộc chín thịt ba chỉ và ngâm mát giữ độ trắng giòn', 'Chà xát thịt ba chỉ với 2 g muối ăn rồi rửa sạch. Đun sôi 1080 ml nước lọc với 1 g muối ăn trên lửa lớn, thả thịt ba chỉ vào luộc ở lửa vừa khoảng 18 phút đến khi xiên đũa qua thịt không còn nước hồng. Vớt thịt ra ngâm ngay vào nước nguội sạch 10 phút cho thịt trắng săn rồi thái lát thật mỏng.', 'Ngâm thịt ba chỉ trong nước mát ngay sau khi luộc giúp thớ thịt săn chắc, phần mỡ trong giòn và dễ thái lát mỏng đẹp.', 18),
('imp-4ced29ad30507f2c_v4_step_2', 'imp-4ced29ad30507f2c', 2, 'cook', 'Luộc chín tôm tươi và chẻ đôi dọc lưng', 'Cho tôm tươi đã rửa sạch vào nồi nước luộc thịt đang sôi ở lửa vừa, đậy vung luộc khoảng 4 phút đến khi tôm chuyển màu đỏ cam đều và chín kỹ hoàn toàn. Vớt tôm ra để nguội, bóc bỏ vỏ, rút chỉ đen trên lưng rồi chẻ đôi theo chiều dọc.', NULL, 4),
('imp-4ced29ad30507f2c_v4_step_3', 'imp-4ced29ad30507f2c', 3, 'prep', 'Sơ chế rau sống, giá đỗ và dưa leo', 'Ngâm xà lách, rau húng quế, ngò gai, hẹ lá và giá đỗ với nước pha 3 g muối ăn trong 5 phút rồi xả sạch nhiều lần, vẩy thật ráo nước. Dưa leo rửa sạch, bỏ phần ruột mềm rồi thái thanh dài mỏng. Tách bún tươi thành từng lọn nhỏ vừa cuốn.', 'Rau sống phải được vẩy thật ráo nước trước khi cuốn để tránh làm ướt mềm quá mức khiến bánh tráng dễ bị rách.', NULL),
('imp-4ced29ad30507f2c_v4_step_4', 'imp-4ced29ad30507f2c', 4, 'sauce', 'Pha nước mắm chanh tỏi ớt nổi đẹp', 'Hòa tan 50 ml nước mắm ngon với 25 g đường cát trắng và 120 ml nước lọc đến khi đường tan hết. Thêm nước cốt 1 quả chanh tươi, tỏi băm nhuyễn và ớt hiểm băm nhỏ vào sau cùng để tỏi ớt nổi đều trên mặt chén nước chấm.', NULL, NULL),
('imp-4ced29ad30507f2c_v4_step_5', 'imp-4ced29ad30507f2c', 5, 'prep', 'Làm mềm bánh tráng và xếp lớp nhân', 'Nhúng nhanh từng lá bánh tráng mỏng qua nước ấm sạch cho vừa dẻo rồi trải phẳng lên thớt sạch. Xếp 1 lá xà lách, vài cọng rau húng quế, ngò gai, giá đỗ, dưa leo, một ít bún tươi và 2–3 lát thịt ba chỉ vào mép dưới bánh.', NULL, NULL),
('imp-4ced29ad30507f2c_v4_step_6', 'imp-4ced29ad30507f2c', 6, 'finish', 'Cuộn tròn chặt tay và trình bày ra đĩa', 'Gập hai mép bên bánh tráng vào trong, cuộn tròn từ dưới lên 1 vòng cho gọn chắc, tiếp tục đặt 2 nửa con tôm úp mặt đỏ xuống dưới cùng 2 cọng hẹ lá thò đầu ra ngoài rồi cuộn chặt đến hết lá bánh. Lặp lại cho đến hết nguyên liệu, xếp gỏi cuốn ra đĩa dùng ngay với nước mắm tỏi ớt.', 'Làm mềm từng lá bánh tráng ngay trước khi cuốn và xếp lượng nhân vừa phải để cuốn gỏi tròn đều, không bị phồng rách.', NULL),
('imp-3a06ac78b572f3ae_v4_step_1', 'imp-3a06ac78b572f3ae', 1, 'prep', 'Sơ chế dưa leo và cà rốt ngâm đá giòn', 'Rửa sạch dưa leo, cắt hai đầu và chà xát vòng tròn đến khi ra bọt trắng để khử vị đắng rồi rửa sạch. Bổ đôi dưa leo, nạo bỏ ruột, thái lát mỏng; cà rốt gọt vỏ bào sợi mảnh. Ngâm cả hai vào thau nước đá với 400 ml nước lọc và 4 g muối ăn trong 10 phút rồi vớt ra vắt ráo nước.', 'Ngâm dưa leo và cà rốt trong nước đá muối giúp sợi rau củ giòn lâu, giữ màu tươi sáng và hạn chế ra nước sau khi trộn.', 10),
('imp-3a06ac78b572f3ae_v4_step_2', 'imp-3a06ac78b572f3ae', 2, 'cook', 'Rim chín tôm tươi giữ độ ngọt giòn', 'Làm sạch tôm, rút bỏ chỉ đen trên sống lưng rồi để ráo. Làm nóng chảo trên lửa vừa, cho tôm và 2 g muối ăn vào rim đảo đều khoảng 5 phút đến khi tôm chuyển màu đỏ cam đều, chín săn hoàn toàn thì tắt bếp, để nguội bóc vỏ và chẻ đôi.', 'Rim tôm vừa chín tới trên lửa vừa giúp tôm không bị teo khô mà giữ trọn vị ngọt đậm tự nhiên.', 5),
('imp-3a06ac78b572f3ae_v4_step_3', 'imp-3a06ac78b572f3ae', 3, 'sauce', 'Giã tỏi ớt hiểm pha nước mắm chua cay', 'Cho 48 g đường cát trắng, tỏi khô và 3 quả ớt hiểm vào cối giã thật nhuyễn. Trút ra bát, hòa thêm 45 ml nước mắm ngon, 15 ml tương ớt và nước cốt 2 quả chanh tươi, khuấy tan hoàn toàn để tạo bát nước trộn sánh thơm.', NULL, NULL),
('imp-3a06ac78b572f3ae_v4_step_4', 'imp-3a06ac78b572f3ae', 4, 'prep', 'Rang đậu phộng và cắt nhỏ rau thơm', 'Rang chín vàng đậu phộng trên lửa nhỏ, để nguội xát sạch vỏ lụa rồi giã dập vừa. Nhặt rửa sạch rau húng lủi và húng quế, vẩy ráo nước rồi cắt nhỏ. Chuẩn bị sẵn bánh phồng tôm giòn ăn kèm.', NULL, NULL),
('imp-3a06ac78b572f3ae_v4_step_5', 'imp-3a06ac78b572f3ae', 5, 'prep', 'Trộn thấm dưa leo, cà rốt và tôm rim', 'Cho dưa leo, cà rốt đã vắt ráo và tôm rim vào tô lớn, rưới đều bát nước trộn mắm chanh ớt vào, đeo găng tay trộn nhẹ nhàng rồi để yên 8 phút cho các nguyên liệu ngấm vị chua cay mặn ngọt.', NULL, 8),
('imp-3a06ac78b572f3ae_v4_step_6', 'imp-3a06ac78b572f3ae', 6, 'finish', 'Trộn rau thơm, rắc đậu phộng và thưởng thức', 'Thêm rau húng lủi và húng quế cắt nhỏ vào tô nộm, đảo đều nhẹ tay lần cuối để rau giữ màu xanh tươi. Gắp nộm ra đĩa, rắc đậu phộng rang giã dập lên trên và dọn ăn ngay kèm bánh phồng tôm.', 'Chỉ cho rau thơm vào trộn ở bước cuối để lá rau không bị dập nát hay thâm màu.', NULL),
('imp-21f32dccd464c605_v4_step_1', 'imp-21f32dccd464c605', 1, 'prep', 'Làm sạch gà và nướng rang hương liệu', 'Xát 10 g muối ăn cùng 20 g gừng tươi đập dập lên khắp mình và trong bụng gà ta, để 5 phút rồi rửa thật sạch dưới vòi nước lạnh và để ráo. Nướng 1/2 củ hành tây, 40 g gừng tươi và hành tím khô đến khi sém vàng thơm, cạo sạch cháy. Rang hạt mùi khô (cùng quế thanh và hoa hồi nếu thích) trên chảo khô lửa nhỏ 2 phút đến khi thơm rồi bọc vào túi vải sạch.', NULL, 10),
('imp-21f32dccd464c605_v4_step_2', 'imp-21f32dccd464c605', 2, 'cook', 'Luộc gà ta chín tới giữ da vàng giòn', 'Cho gà ta và 3 lít nước lọc lạnh vào nồi lớn cùng 5 g muối ăn, đun lửa vừa cho nước nóng lên từ từ; khi nước sôi lăn tăn thì hớt sạch bọt, mở hé vung và hạ lửa nhỏ liu riu luộc khoảng 30–35 phút. Xiên đũa vào phần thịt dày nhất ở đùi thấy không chảy nước hồng là gà chín hoàn toàn.', 'Luộc gà ở nhiệt độ sôi lăn tăn và mở hé nắp giúp nước dùng trong veo, thịt gà mềm mọng không bị bã.', 35),
('imp-21f32dccd464c605_v4_step_3', 'imp-21f32dccd464c605', 3, 'cook', 'Ngâm nguội gà, lọc xương và ninh nước dùng', 'Vớt gà ra ngâm nhanh vào thau nước lọc nguội 5 phút cho da gà giòn săn rồi vớt ráo, lọc lấy toàn bộ phần thịt và giữ lại phần xương. Cho xương gà cùng túi thảo mộc, hành tây nướng, gừng nướng và hành tím nướng vào nồi nước luộc, tiếp tục ninh lửa nhỏ thêm 35 phút cho nước dùng ngọt sâu rồi vớt bỏ hết xương và túi gia vị, lọc qua rây cho thật trong.', 'Trả phần xương gà sau khi lọc vào ninh thêm giúp nước dùng phở gà đậm vị ngọt tự nhiên mà thịt gà vẫn mềm.', 35),
('imp-21f32dccd464c605_v4_step_4', 'imp-21f32dccd464c605', 4, 'cook', 'Nêm hoàn thiện nồi nước dùng phở gà', 'Nêm vào nồi nước dùng đã lọc 5 g muối ăn còn lại, 15 g đường phèn, 10 g hạt nêm và 30 ml nước mắm ngon, khuấy đều cho tan hết rồi đun sôi nhẹ lại, nếm vị thanh ngọt vừa miệng và giữ nóng trên bếp.', 'Cho nước mắm ngon vào bước cuối giúp giữ được mùi thơm đặc trưng và không làm chua nước dùng.', NULL),
('imp-21f32dccd464c605_v4_step_5', 'imp-21f32dccd464c605', 5, 'prep', 'Chuẩn bị bánh phở, xé gà và rau thơm', 'Ngâm bánh phở khô rồi chần qua nước sôi cho mềm tơi, xả nhanh nước nguội rồi tráng lại nước nóng cho ráo. Thái miếng hoặc xé sợi phần thịt gà đã nguội. Thái lát thật mỏng 1/2 củ hành tây còn lại ngâm nước đá cho giòn; chẻ đầu hành lá, thái nhỏ lá hành, ngò rí; thái chỉ lá chanh tươi; trụng sơ giá đỗ và cắt múi chanh tươi, thái lát ớt tươi.', NULL, NULL),
('imp-21f32dccd464c605_v4_step_6', 'imp-21f32dccd464c605', 6, 'finish', 'Xếp tô phở gà phố cổ và thưởng thức', 'Chia bánh phở vào 4 tô lớn, xếp thịt gà ta lên trên, điểm đầu hành chẻ, hành tây thái mỏng, hành lá, ngò rí và lá chanh thái chỉ. Chan ngập nước dùng đang sôi sùng sục vào từng tô và dọn nóng ngay kèm giá đỗ, chanh tươi và ớt tươi.', NULL, NULL),
('imp-ba737c5583985a50_v4_step_1', 'imp-ba737c5583985a50', 1, 'prep', 'Chần xương bò, rang hương liệu và sơ chế sả', 'Chần xương ống bò với 500 ml nước sôi và 3 g muối ăn trong 5 phút rồi xả sạch dưới vòi nước lạnh. Đập dập 5 cây sả tươi, băm nhuyễn 3 cây sả còn lại cùng ớt hiểm tươi và tỏi khô. Rang thơm 1/2 củ hành tây, gừng tươi đập dập và 25 g hành tím khô trên chảo khô.', NULL, 8),
('imp-ba737c5583985a50_v4_step_2', 'imp-ba737c5583985a50', 2, 'marinate', 'Ướp và xào săn thịt nạm bò', 'Ướp nguyên miếng thịt nạm bò với 1/3 lượng sả tỏi ớt băm, 3 g hạt nêm, 5 ml dầu màu điều và 1 g tiêu đen xay trong 20 phút. Làm nóng chảo với 10 ml dầu ăn trên lửa lớn, cho thịt nạm vào áp chảo xào săn đều các mặt cho dậy mùi thơm rồi gắp ra.', NULL, 20),
('imp-ba737c5583985a50_v4_step_3', 'imp-ba737c5583985a50', 3, 'cook', 'Hầm xương bò và nạm bò mềm ngọt', 'Cho xương ống bò, hành tây gừng hành tím đã rang cùng 5 cây sả đập dập vào nồi với 2,25 lít nước lọc, đun sôi rồi hạ lửa nhỏ hầm 60 phút và hớt bọt thường xuyên. Tiếp theo thả miếng nạm bò đã xào săn vào hầm chung thêm 50 phút đến khi nạm bò chín mềm vừa ăn thì vớt ra để nguội, thái lát mỏng.', 'Xào săn nạm bò trước khi hầm giúp thịt giữ vị ngọt đậm và bề mặt thơm mùi sả ớt hơn.', 110),
('imp-ba737c5583985a50_v4_step_4', 'imp-ba737c5583985a50', 4, 'sauce', 'Lọc mắm ruốc Huế và nấu sa tế sả ớt', 'Hòa 18 g mắm ruốc Huế với 250 ml nước lọc, để lắng 10 phút rồi gạn lấy phần nước trong cho vào nồi nước dùng, bỏ cặn. Đun nóng 30 ml dầu ăn và 10 ml dầu màu điều trên lửa vừa, phi thơm 25 g hành tím băm, phần tỏi băm và sả băm còn lại đến vàng thơm rồi hạ lửa nhỏ cho 10 g ớt bột khô vào đảo nhanh. Cho một nửa sa tế vào nồi nước dùng; nửa còn lại trộn thêm phần ớt hiểm tươi băm còn lại, 2 g muối ăn và 5 g đường phèn thành sa tế ăn kèm.', 'Lắng kỹ mắm ruốc chỉ lấy phần nước trong để nồi bún bò thơm đặc trưng mà không bị sạn đục.', NULL),
('imp-ba737c5583985a50_v4_step_5', 'imp-ba737c5583985a50', 5, 'cook', 'Nêm nước dùng và luộc viên thịt heo xay', 'Vớt bỏ xương ống bò và sả gừng khỏi nồi nước dùng, nêm 25 g đường phèn còn lại, 5 g hạt nêm, 3 g muối ăn và 25 ml nước mắm ngon cho vị đậm đà cay thơm hài hòa. Quết kỹ 200 g thịt heo xay với 5 ml nước mắm ngon và 1 g tiêu đen xay đến khi dẻo quánh, vo thành từng viên nhỏ thả vào nồi nước dùng đang sôi nhẹ khoảng 5 phút đến khi viên thịt nổi lên chín kỹ hoàn toàn.', 'Quết đều thịt heo xay giúp viên mọc dai giòn tự nhiên khi nấu chín trong nước dùng.', 6),
('imp-ba737c5583985a50_v4_step_6', 'imp-ba737c5583985a50', 6, 'finish', 'Trụng bún, sắp tô và dọn nóng', 'Trụng bún sợi to qua nước sôi cho nóng tơi rồi chia vào 4 tô. Xếp thịt nạm bò thái lát và viên giò sống lên trên, chan nước dùng nóng hổi ngập mặt bún, rắc hành lá, rau răm và 1/2 củ hành tây thái thật mỏng. Dọn kèm giá đỗ, chanh tươi và chén sa tế sả ớt.', NULL, NULL),
('imp-37a39eaa1edcd2e4_v4_step_1', 'imp-37a39eaa1edcd2e4', 1, 'prep', 'Chần xương heo và nướng khô mực', 'Rửa sạch xương ống heo rồi chần qua 500 ml nước sôi với 2 g muối ăn trong 4 phút để loại bỏ bọt bẩn, vớt ra rửa lại dưới vòi nước lạnh. Nướng khô mực trên lửa nhỏ khoảng 2 phút đến khi dậy mùi thơm và hơi xém cạnh thì xé làm bốn; rửa sạch tôm khô.', NULL, 6),
('imp-37a39eaa1edcd2e4_v4_step_2', 'imp-37a39eaa1edcd2e4', 2, 'cook', 'Ninh nước lèo xương heo cùng củ cải và mực khô', 'Cho xương ống heo vào nồi với 2,1 lít nước lọc lạnh, thêm tôm khô, khô mực nướng, củ cải trắng cắt khúc, cà rốt cắt khúc và đầu hành lá đập dập. Đun sôi nhẹ rồi hạ lửa vừa hầm khoảng 75 phút, thường xuyên hớt bọt để nước lèo thật trong. Vớt bỏ xương, củ cải, cà rốt và xác mực tôm khô rồi nêm 25 g đường phèn, 8 g muối ăn, 10 g hạt nêm và 25 ml nước mắm ngon.', 'Giữ nồi nước lèo sôi lăn tăn nhẹ thay vì sôi bùng mạnh để củ cải và xương tiết vị ngọt mà nước vẫn trong vắt.', 75),
('imp-37a39eaa1edcd2e4_v4_step_3', 'imp-37a39eaa1edcd2e4', 3, 'cook', 'Luộc thịt ba chỉ, tôm tươi và trứng cút', 'Luộc chín thịt ba chỉ heo với chút nước và 2 g muối ăn khoảng 20 phút đến khi thịt chín kỹ, vớt ra ngâm nước đá lạnh cho săn trắng rồi thái lát mỏng. Trong nồi nước sôi khác, luộc trứng cút 8 phút rồi bóc vỏ bổ đôi; tiếp tục trụng luộc tôm tươi khoảng 3 phút đến khi chuyển màu hồng cam chín đều thì vớt ra bóc vỏ chừa đuôi, bỏ chỉ lưng.', NULL, 20),
('imp-37a39eaa1edcd2e4_v4_step_4', 'imp-37a39eaa1edcd2e4', 4, 'cook', 'Phi tỏi vàng giòn và xào thịt heo xay', 'Đun nóng 40 ml dầu ăn trong chảo nhỏ ở lửa vừa, cho tỏi khô băm vào đảo đều tay đến khi vừa chuyển màu vàng nhạt thì tắt bếp và vớt ngay phần tỏi phi ra chén (giữ lại dầu tỏi). Chắt 1 muỗng canh dầu tỏi ra riêng, phần còn lại trên chảo phi thơm hành tím khô băm rồi cho thịt heo xay vào xào săn tơi khoảng 4 phút với 5 ml nước mắm ngon.', 'Vớt tỏi phi ngay khi vừa ngả vàng rơm để nhiệt dư làm tỏi giòn đều mà không bị cháy đắng.', NULL),
('imp-37a39eaa1edcd2e4_v4_step_5', 'imp-37a39eaa1edcd2e4', 5, 'prep', 'Trụng hủ tiếu khô và chuẩn bị rau ăn kèm', 'Trụng hủ tiếu khô qua nồi nước sôi khoảng 2–3 phút cho vừa mềm dai, vớt ra xả nhanh nước lạnh cho ráo rồi trộn ngay với 1 muỗng canh dầu tỏi phi để sợi tơi bóng. Rửa sạch giá đỗ, rau tần ô, cắt khúc hẹ lá, cần tây, hành lá và cắt múi chanh tươi.', 'Xả nhanh hủ tiếu qua nước lạnh rồi trộn dầu tỏi phi giúp sợi dai bóng và không bị vón cục khi chia tô.', NULL),
('imp-37a39eaa1edcd2e4_v4_step_6', 'imp-37a39eaa1edcd2e4', 6, 'finish', 'Xếp tô hủ tiếu Nam Vang và chan nước lèo', 'Chia hủ tiếu vào 4 tô, xếp thịt ba chỉ thái lát, thịt heo xay xào, tôm luộc và trứng cút bổ đôi lên trên. Chan nước lèo đang sôi sùng sục ngập mặt hủ tiếu, thêm chút tỏi phi thơm vào tô và rắc hành lá, hẹ lá, cần tây; dọn nóng ngay kèm giá đỗ, rau tần ô và chanh tươi.', NULL, NULL),
('imp-0efa407066cdc8dd_v4_step_1', 'imp-0efa407066cdc8dd', 1, 'marinate', 'Làm sạch nhớt và ướp cá lóc với nghệ', 'Đánh sạch vảy, bỏ mang và cạo sạch màng đen trong bụng cá lóc tươi. Chà xát mình cá với 4 g muối ăn trong 2 phút cho hết nhớt rồi rửa sạch dưới vòi nước lạnh, thấm ráo và cắt khúc dày 3 cm. Ướp cá nhẹ tay với 3 g bột nghệ, 15 ml nước mắm ngon và 2 g muối ăn trong 15 phút.', 'Thấm thật ráo khúc cá trước khi ướp và chiên giúp cá không bị bắn dầu và giữ được lớp da nguyên vẹn.', 15),
('imp-0efa407066cdc8dd_v4_step_2', 'imp-0efa407066cdc8dd', 2, 'prep', 'Sơ chế cà chua, dứa và rau thơm', 'Cà chua chín bổ múi cau; dứa cắt lát xéo vừa ăn; băm nhỏ hành tím khô và tỏi khô. Rửa sạch hành lá, thì là tươi và ngò rí rồi thái khúc 2 cm; thái lát mỏng ớt tươi.', NULL, NULL),
('imp-0efa407066cdc8dd_v4_step_3', 'imp-0efa407066cdc8dd', 3, 'cook', 'Chiên áp chảo sơ từng khúc cá lóc', 'Đun nóng 30 ml dầu ăn trên chảo chống dính ở lửa vừa, xếp các khúc cá lóc đã ướp vào áp chảo mỗi mặt khoảng 2 phút đến khi bề mặt cá se vàng nhẹ thì nhẹ nhàng gắp ra đĩa riêng.', 'Chiên áp chảo sơ qua giúp thịt cá săn chắc, không bị vỡ nát khi thả vào nồi nước dùng sôi.', 4),
('imp-0efa407066cdc8dd_v4_step_4', 'imp-0efa407066cdc8dd', 4, 'cook', 'Xào cà chua, dứa và nấu nước dùng', 'Trong nồi lớn, làm nóng 15 ml dầu ăn còn lại, phi thơm hành tím và tỏi băm trên lửa vừa rồi cho cà chua và dứa vào xào 4 phút đến khi cà chua mềm tiết màu đỏ cam đẹp mắt. Đổ 1,6 lít nước lọc vào đun lửa lớn đến khi sôi bùng.', NULL, 4),
('imp-0efa407066cdc8dd_v4_step_5', 'imp-0efa407066cdc8dd', 5, 'cook', 'Nấu chín cá và nêm nước dùng chua ngọt', 'Hạ lửa vừa, nhẹ nhàng thả các khúc cá đã chiên sơ vào nồi nước sôi, nấu liu riu khoảng 8–10 phút đến khi thịt cá chín trắng hoàn toàn và hớt sạch bọt. Vớt nhẹ cá ra đĩa để tránh nát, nêm nồi nước dùng với 20 ml nước mắm ngon, 2 g muối ăn còn lại và 6 g đường cát trắng cho vị chua thanh hài hòa.', 'Không khuấy đảo mạnh tay sau khi cho cá vào nồi để từng khúc cá giữ trọn hình dáng đẹp mắt.', 10),
('imp-0efa407066cdc8dd_v4_step_6', 'imp-0efa407066cdc8dd', 6, 'finish', 'Trụng bún tươi và chan nước dùng nóng', 'Trụng nhanh bún gạo tươi qua nồi nước sôi khác trong 1 phút cho mềm tơi rồi chia đều vào 4 tô. Xếp các khúc cá lóc lên mặt bún, chan ngập nước dùng cà chua dứa đang sôi, rắc hành lá, thì là tươi, ngò rí và ớt tươi thái lát rồi thưởng thức ngay khi nóng.', NULL, NULL),
('imp-b6aeb931b882e8a3_v4_step_1', 'imp-b6aeb931b882e8a3', 1, 'cook', 'Vo gạo và nấu chín cơm trắng dẻo', 'Vo nhẹ 450 g gạo tẻ thơm qua 2 lần nước sạch để giữ lớp cám dinh dưỡng, cho vào nồi cơm điện cùng 600 ml nước lọc rồi bật chế độ nấu khoảng 25 phút. Khi cơm chín, để chế độ giữ ấm thêm 5 phút rồi xới tơi.', 'Trong lúc chờ nồi cơm chín, tận dụng thời gian sơ chế và kho đậu nấm để món mặn vừa xong kịp bữa.', 25),
('imp-b6aeb931b882e8a3_v4_step_2', 'imp-b6aeb931b882e8a3', 2, 'prep', 'Sơ chế nấm đùi gà, đậu phụ và pha nước kho', 'Nấm đùi gà cắt bỏ gốc, rửa nhanh dưới vòi nước lạnh rồi để ráo, thái lát dày 0,8–1 cm. Đậu phụ trắng thấm khô, cắt miếng vuông cạnh 3 cm. Hành lá tách đầu trắng băm nhỏ, lá xanh thái khúc; ớt sừng thái lát. Khuấy tan trong chén 45 ml nước tương, 8 g đường, 8 g hạt nêm chay, 3 g muối và 150 ml nước lọc.', 'Nấm đùi gà chỉ nên rửa nhanh chứ không ngâm lâu để giữ nguyên độ giòn ngọt tự nhiên.', NULL),
('imp-b6aeb931b882e8a3_v4_step_3', 'imp-b6aeb931b882e8a3', 3, 'cook', 'Chiên vàng sơ các mặt đậu phụ', 'Đun nóng 20 ml dầu ăn thực vật trong chảo trên lửa vừa, thả các miếng đậu phụ vào chiên khoảng 6 phút, lật nhẹ cho đến khi hai mặt vàng đều thì gắp ra đĩa lót giấy thấm dầu.', NULL, 6),
('imp-b6aeb931b882e8a3_v4_step_4', 'imp-b6aeb931b882e8a3', 4, 'cook', 'Phi thơm đầu hành và xào săn nấm đùi gà', 'Cho 20 ml dầu ăn còn lại vào nồi kho, đun nóng trên lửa vừa rồi phi thơm phần đầu hành lá băm trong 30 giây. Trút nấm đùi gà vào đảo nhanh tay 2 phút trên lửa vừa đến khi nấm săn lại và dậy mùi thơm.', NULL, 2),
('imp-b6aeb931b882e8a3_v4_step_5', 'imp-b6aeb931b882e8a3', 5, 'cook', 'Kho liu riu đậu phụ cùng nấm thấm vị', 'Đổ chén nước kho đã pha vào nồi nấm, xếp nhẹ các miếng đậu phụ chiên vào. Đun sôi bùng trên lửa vừa rồi hạ xuống lửa nhỏ, kho liu riu trong 9 phút cho nước kho sánh sệt lại, thấm đượm vào từng miếng đậu và nấm.', 'Hạn chế dùng đũa đảo mạnh trong lúc kho mà thỉnh thoảng nghiêng nhẹ nồi cho nước kho phủ đều, giúp đậu không bị nát.', 9),
('imp-b6aeb931b882e8a3_v4_step_6', 'imp-b6aeb931b882e8a3', 6, 'finish', 'Hoàn thiện và dọn cơm chay đậu kho nấm', 'Nêm nếm lại nước kho cho vừa miệng ăn kèm cơm, rắc phần lá xanh hành lá, ớt sừng thái lát và 1,5 g tiêu đen xay vào rồi tắt bếp. Xới cơm trắng nóng ra chén, múc đậu phụ kho nấm ra đĩa rưới nước kho sánh lên trên và thưởng thức nóng.', NULL, NULL),
('imp-f0039d3d3f6299b3_v4_step_1', 'imp-f0039d3d3f6299b3', 1, 'prep', 'Sơ chế đậu phụ, nấm đùi gà và cà chua', 'Đậu phụ trắng rửa nhẹ, để thật ráo rồi cắt miếng vuông dày vừa ăn. Nấm đùi gà cắt bỏ gốc, rửa sạch, thái lát dọc dày 0,5 cm. Cà chua bỏ cuống bổ múi cau; tỏi khô băm nhuyễn; hành lá cắt khúc 2–3 cm; ớt sừng thái lát mỏng.', 'Cắt đậu phụ miếng hơi dày một chút để khi kho lâu đậu vẫn chắc miếng và không bị vỡ nát.', NULL),
('imp-f0039d3d3f6299b3_v4_step_2', 'imp-f0039d3d3f6299b3', 2, 'cook', 'Chiên vàng sơ các mặt đậu phụ', 'Làm nóng chảo với 15 ml dầu ăn trên lửa vừa, thả từng miếng đậu phụ vào chiên khoảng 6 phút đến khi hai mặt ngả vàng nhẹ thì gắp ra đĩa để ráo dầu.', NULL, 6),
('imp-f0039d3d3f6299b3_v4_step_3', 'imp-f0039d3d3f6299b3', 3, 'cook', 'Phi tỏi và xào săn nấm đùi gà', 'Cho 10 ml dầu ăn còn lại vào chảo, phi thơm tỏi băm trên lửa vừa trong 30 giây. Đổ nấm đùi gà vào xào nhanh tay 3 phút với 10 ml nước tương và 1 g tiêu đen xay cho đến khi nấm săn cạnh và ngấm hương thơm.', NULL, 3),
('imp-f0039d3d3f6299b3_v4_step_4', 'imp-f0039d3d3f6299b3', 4, 'sauce', 'Xếp tầng nguyên liệu và pha sốt tương kho', 'Xếp cà chua bổ múi cau lót dưới đáy nồi kho, phủ phần nấm đùi gà đã xào lên trên và xếp đậu phụ chiên lên lớp trên cùng. Khuấy đều trong tô 30 ml nước tương còn lại, 20 ml hắc xì dầu, 15 g đường cát trắng, 4 g muối ăn, 3 g bột ngọt và 300 ml nước lọc đến khi tan hết.', 'Lót cà chua dưới đáy nồi giúp cà chua tiết nước ngọt làm nền sốt, đồng thời giữ đậu phụ phía trên nguyên vẹn không bị nát.', NULL),
('imp-f0039d3d3f6299b3_v4_step_5', 'imp-f0039d3d3f6299b3', 5, 'cook', 'Kho liu riu đến khi nước tương sánh đậm', 'Rót tô nước sốt tương vào nồi sao cho xâm xấp mặt nguyên liệu, bật lửa lớn đun sôi rồi hạ xuống lửa nhỏ, đậy hé vung kho liu riu trong 15 phút. Thỉnh thoảng lắc nhẹ quai nồi cho gia vị ngấm đều đến khi nước kho cạn sánh lại.', 'Kho ở lửa nhỏ liu riu và mở hé vung giúp nước sốt rút sánh dần mà không bị trào hay cháy khét đáy nồi.', 15),
('imp-f0039d3d3f6299b3_v4_step_6', 'imp-f0039d3d3f6299b3', 6, 'finish', 'Hoàn thiện món nấm kho đậu phụ tương', 'Nêm nếm lại sốt kho cho vừa vị đậm đà, tắt bếp rồi rắc hành lá cắt khúc, ớt sừng thái lát và 0,5 g tiêu đen xay còn lại lên trên. Múc ra đĩa sâu lòng và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-e771ef1a49b2aeed_v4_step_1', 'imp-e771ef1a49b2aeed', 1, 'prep', 'Sơ chế bông cải xanh, nấm đùi gà và cà rốt', 'Tách bông cải xanh thành từng nhánh vừa ăn, rửa sạch rồi để ráo. Nấm đùi gà cắt bỏ gốc, rửa nhanh sạch đất rồi thái lát dày 0,5 cm. Cà rốt gọt vỏ, thái lát mỏng; tỏi khô băm nhỏ; ớt sừng thái lát mỏng. Hòa tan 4 g bột bắp với 50 ml nước lọc trong chén riêng.', 'Không ngâm nấm đùi gà quá lâu trong nước để tránh nấm hút nước làm nhũn và mất vị ngọt khi xào.', NULL),
('imp-e771ef1a49b2aeed_v4_step_2', 'imp-e771ef1a49b2aeed', 2, 'cook', 'Chần sơ bông cải xanh và cà rốt giữ độ giòn', 'Đun sôi nồi nước nhỏ trên bếp, thả bông cải xanh và cà rốt vào chần nhanh trong 1–2 phút rồi vớt ra ngâm ngay vào thau nước lạnh khoảng 1 phút, sau đó vớt ra rổ để thật ráo nước.', 'Chần sơ rồi ngâm nước lạnh giúp bông cải xanh chín đều, giữ màu xanh mướt và giòn ngọt khi xào nhanh trên lửa lớn.', 2),
('imp-e771ef1a49b2aeed_v4_step_3', 'imp-e771ef1a49b2aeed', 3, 'cook', 'Xào săn nấm đùi gà riêng trên lửa lớn', 'Làm nóng chảo với 15 ml dầu ăn trên lửa lớn, trút nấm đùi gà vào xào nhanh tay 3 phút cho đến khi nấm săn lại và hơi xém cạnh. Nêm 1 g muối ăn và 0,5 g tiêu đen xay, đảo đều rồi trút nấm ra đĩa riêng.', 'Xào riêng nấm trước giúp nấm rút bớt nước, giữ độ dai giòn thơm và không làm nhũn rau khi xào chung.', 3),
('imp-e771ef1a49b2aeed_v4_step_4', 'imp-e771ef1a49b2aeed', 4, 'cook', 'Phi thơm tỏi và xào nhanh bông cải, cà rốt', 'Dùng lại chảo, thêm 20 ml dầu ăn đun nóng rồi cho tỏi băm vào phi khoảng 30 giây đến khi thơm vàng nhẹ. Bật lửa lớn, cho bông cải xanh và cà rốt đã ráo nước vào đảo đều tay 2 phút; nêm 30 ml nước tương, 8 g đường cát trắng, 8 g hạt nêm chay và 2 g muối ăn còn lại.', NULL, 2),
('imp-e771ef1a49b2aeed_v4_step_5', 'imp-e771ef1a49b2aeed', 5, 'sauce', 'Trộn nấm và làm sánh nước sốt bột bắp', 'Trút phần nấm đùi gà đã xào vào lại chảo rau củ, đảo đều tay cho hòa quyện. Khuấy đều chén nước bột bắp rồi chế từ từ vào chảo, đảo nhanh khoảng 1 phút đến khi lớp sốt sánh nhẹ bao quanh đều các nguyên liệu thì tắt bếp.', NULL, NULL),
('imp-e771ef1a49b2aeed_v4_step_6', 'imp-e771ef1a49b2aeed', 6, 'finish', 'Trình bày đĩa rau nấm xào chay nóng hổi', 'Gắp bông cải xanh xào nấm đùi gà ra đĩa lớn, rắc 1 g tiêu đen xay còn lại cùng vài lát ớt sừng đỏ lên trên để tăng màu sắc và hương thơm. Dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-43e806b28c7b8bb5_v4_step_1', 'imp-43e806b28c7b8bb5', 1, 'marinate', 'Làm sạch và ướp tôm tươi đậm vị', 'Bóc vỏ 200 g tôm tươi, bỏ đầu, rút sạch chỉ đen rồi rửa nước muối loãng và thấm thật khô. Thái tôm thành miếng nhỏ vừa ăn, ướp với 1/2 lượng hành tím băm, 5 ml nước mắm ngon, 2 g hạt nêm và 1 g tiêu đen xay trong 10 phút cho săn ngọt.', NULL, 10),
('imp-43e806b28c7b8bb5_v4_step_2', 'imp-43e806b28c7b8bb5', 2, 'prep', 'Sơ chế cà rốt, giá đỗ và đánh tơi cơm nguội', 'Thái hạt lựu nhỏ 1/2 củ cà rốt; rửa sạch 100 g giá đỗ rồi để thật ráo nước. Băm nhỏ tỏi và phần hành tím còn lại; thái nhỏ hành lá. Bóp tơi 540 g cơm nguội với 2 g muối ăn; đánh tan 2 quả trứng gà trong chén.', 'Cà rốt thái hạt lựu thật đều và giá đỗ để thật ráo sẽ giúp chảo cơm không bị ra nước lúc xào nhanh.', NULL),
('imp-43e806b28c7b8bb5_v4_step_3', 'imp-43e806b28c7b8bb5', 3, 'cook', 'Xào chín tôm tươi và cà rốt hạt lựu', 'Đun nóng 10 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa lượng tỏi băm và hành tím băm. Cho tôm đã ướp cùng cà rốt hạt lựu vào xào nhanh khoảng 3 phút đến khi tôm chuyển màu cam hồng, chín săn hoàn toàn và cà rốt vừa mềm thì xúc riêng ra đĩa.', NULL, 3),
('imp-43e806b28c7b8bb5_v4_step_4', 'imp-43e806b28c7b8bb5', 4, 'cook', 'Chiên tơi trứng gà và rang cơm lửa lớn', 'Cho 20 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi và hành tím băm còn lại. Đổ chén trứng gà vào đảo đều 30 giây thành mảng xốp mềm rồi trút toàn bộ cơm nguội vào. Tăng lửa lớn, rang đảo liên tục trong 4 phút để hạt cơm tơi đều, săn bóng và bám đều trứng vàng.', 'Đảo cơm đều tay trên lửa lớn cho đến khi nghe tiếng hạt cơm nhảy tanh tách nhẹ là cơm đã đạt độ săn ngon.', 4),
('imp-43e806b28c7b8bb5_v4_step_5', 'imp-43e806b28c7b8bb5', 5, 'cook', 'Nêm xì dầu, nước mắm và trộn tôm, giá đỗ', 'Rưới 20 ml xì dầu và 5 ml nước mắm ngon còn lại dọc quanh thành chảo nóng, thêm 3 g hạt nêm còn lại rồi đảo đều 1 phút cho dậy mùi thơm. Trút đĩa tôm cà rốt và 100 g giá đỗ vào đảo nhanh tay trên lửa lớn khoảng 1 phút để giá đỗ vừa chín tới vẫn còn độ giòn ngọt.', 'Rưới xì dầu quanh thành chảo đang nóng sẽ tạo mùi thơm cháy cạnh đặc trưng và giúp hạt cơm không bị ướt sũng.', NULL),
('imp-43e806b28c7b8bb5_v4_step_6', 'imp-43e806b28c7b8bb5', 6, 'finish', 'Rắc hành lá, tiêu xay và dọn nóng', 'Tắt bếp, rắc hành lá thái nhỏ và 1 g tiêu đen xay còn lại vào đảo đều lần cuối. Múc cơm chiên tôm trứng ra đĩa và dùng nóng ngay.', NULL, NULL),
('imp-f92a1c569c245541_v4_step_1', 'imp-f92a1c569c245541', 1, 'marinate', 'Thái mỏng và ướp mềm thịt bò với tỏi gừng', 'Thấm khô 250 g thịt bò thăn, thái lát mỏng ngang thớ. Ướp bò với 10 ml xì dầu, 5 ml dầu hào, 2 g hạt nêm, 1/2 lượng tỏi băm, 10 g gừng băm, 1/2 lượng tiêu đen xay và 5 ml dầu ăn trong 15 phút để thịt thấm vị và giữ độ mềm mọng khi xào.', 'Ướp bò với chút gừng băm và dầu ăn giúp khử mùi nhẹ và tạo lớp màng giữ nước cho thịt bò luôn mềm ngọt.', 15),
('imp-f92a1c569c245541_v4_step_2', 'imp-f92a1c569c245541', 2, 'prep', 'Sơ chế rau củ và trụng tơi mì tươi', 'Thái sợi bản vừa 1/4 bắp cải, thái sợi mỏng cà rốt, thái múi cau mỏng hành tây và cắt khúc 4 cm hành lá. Đun sôi 1 lít nước lọc, thả 400 g mì tươi vào trụng nhanh khoảng 1 phút cho sợi mì vừa rời tơi, vớt ra xả ngay nước lạnh cho săn sợi, để thật ráo rồi trộn với 5 ml dầu ăn chống dính.', NULL, 1),
('imp-f92a1c569c245541_v4_step_3', 'imp-f92a1c569c245541', 3, 'cook', 'Xào nhanh thịt bò tái mềm trên lửa lớn', 'Làm nóng 10 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa phần tỏi băm còn lại. Trút thịt bò đã ướp vào đảo nhanh tay trong 2 phút đến khi miếng thịt vừa săn chuyển màu nâu hồng mềm ngọt thì xúc ngay ra đĩa riêng.', 'Xào riêng thịt bò trên lửa lớn giúp thịt chín tái mềm mà không bị ra nhiều nước làm nhũn sợi mì.', 2),
('imp-f92a1c569c245541_v4_step_4', 'imp-f92a1c569c245541', 4, 'cook', 'Xào rau củ giòn ngọt và nêm sốt xì dầu', 'Thêm 10 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi băm còn lại rồi cho cà rốt và hành tây vào đảo trước 1 phút trên lửa lớn. Tiếp tục cho bắp cải vào xào chung thêm 2 phút, nêm 3 g hạt nêm còn lại và 4 g đường cát trắng cho rau chín tới giòn ngọt.', NULL, 3),
('imp-f92a1c569c245541_v4_step_5', 'imp-f92a1c569c245541', 5, 'cook', 'Áp chảo sợi mì thấm đều gia vị', 'Gạt rau củ sang một bên hoặc trút trực tiếp 400 g mì đã trụng vào chảo, rưới đều 15 ml xì dầu và 15 ml dầu hào còn lại lên sợi mì. Đảo đều tay trên lửa lớn khoảng 2 phút cho sợi mì săn bóng, ngấm đều gia vị và hơi xém thơm.', 'Xào mì trên lửa lớn và đảo liên tục giúp sợi mì thấm sốt đậm đà mà vẫn khô ráo, không bị nhão bết.', NULL),
('imp-f92a1c569c245541_v4_step_6', 'imp-f92a1c569c245541', 6, 'finish', 'Trộn thịt bò, hành lá và hoàn thiện món mì', 'Đổ đĩa thịt bò xào cùng hành lá cắt khúc vào chảo mì rau củ, đảo nhanh tay thêm 30 giây trên lửa lớn cho hòa quyện đều rồi tắt bếp. Bày mì xào ra đĩa, rắc phần tiêu đen xay còn lại lên trên và thưởng thức nóng.', NULL, NULL),
('imp-f4665d594d941e4a_v4_step_1', 'imp-f4665d594d941e4a', 1, 'prep', 'Làm sạch đùi gà, vo gạo và sơ chế gừng hành', 'Chà xát 500 g đùi gà với 3 g muối ăn trong 2 phút cho sạch mùi rồi rửa kỹ nước lạnh, để ráo. Trộn 200 g gạo tẻ với 30 g gạo nếp, vo qua 2 nước rồi chắt ráo. Đập dập 25 g gừng tươi và 25 g hành tím khô; phần 20 g gừng còn lại cạo vỏ thái sợi chỉ; hành lá rửa sạch thái nhỏ.', NULL, NULL),
('imp-f4665d594d941e4a_v4_step_2', 'imp-f4665d594d941e4a', 2, 'cook', 'Luộc chín đùi gà lấy nước dùng ngọt thanh', 'Cho đùi gà vào nồi cùng 2 lít nước lọc, gừng đập dập, hành tím và 3 g muối ăn. Đun sôi trên lửa lớn rồi hạ lửa vừa hớt sạch bọt, luộc liu riu khoảng 20 phút đến khi xiên đũa vào phần thịt dày nhất không thấy nước hồng chảy ra. Vớt đùi gà ra đĩa để nguội bớt, lọc giữ lại toàn bộ nước dùng gà.', 'Không luộc gà sôi sục quá mạnh để thịt đùi gà chín mềm mọng, giữ được độ ngọt và nước dùng trong veo.', 20),
('imp-f4665d594d941e4a_v4_step_3', 'imp-f4665d594d941e4a', 3, 'cook', 'Rang thơm gạo tẻ và gạo nếp', 'Trong lúc luộc gà, làm nóng chảo khô không dầu trên lửa nhỏ, cho gạo tẻ và gạo nếp đã ráo nước vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy hương thơm dịu thì tắt bếp.', 'Rang gạo đến khi hạt gạo trắng đục và thơm nhẹ là vừa đạt; tránh rang cháy vàng đậm sẽ làm cháo bị sẫm màu.', 6),
('imp-f4665d594d941e4a_v4_step_4', 'imp-f4665d594d941e4a', 4, 'cook', 'Ninh cháo với nước luộc gà cho sánh nhừ', 'Trút toàn bộ gạo rang vào nồi nước luộc gà nóng, khuấy đều một lượt rồi đun sôi trở lại. Hạ lửa nhỏ ninh khoảng 20 phút, thỉnh thoảng khuấy nhẹ sát đáy nồi để hạt gạo nở bung sánh mịn và ngấm trọn vị ngọt thanh của nước gà.', 'Dùng nước luộc gà nóng để ninh gạo rang giúp hạt gạo nhanh nở mềm và bát cháo đậm vị ngọt tự nhiên.', 20),
('imp-f4665d594d941e4a_v4_step_5', 'imp-f4665d594d941e4a', 5, 'prep', 'Xé sợi đùi gà luộc và trộn gia vị nhẹ', 'Khi đùi gà đã nguội bớt, tách bỏ xương rồi xé thịt gà thành từng miếng sợi vừa ăn. Trộn nhẹ thịt gà xé với 2 g hạt nêm và 1 g tiêu đen xay cho đậm đà hơn.', NULL, NULL),
('imp-f4665d594d941e4a_v4_step_6', 'imp-f4665d594d941e4a', 6, 'finish', 'Nêm nồi cháo và hoàn thiện tô cháo gà gừng', 'Nêm 20 ml nước mắm ngon, 4 g hạt nêm còn lại và 2 g muối ăn vào nồi cháo nhừ, khuấy đều rồi nấu thêm 2 phút trên lửa nhỏ. Múc cháo nóng ra 4 tô, xếp thịt gà xé sợi lên trên, rắc hành lá thái nhỏ, gừng tươi thái chỉ, 1 g tiêu đen xay còn lại và nhỏ đều 5 ml dầu mè trước khi thưởng thức.', NULL, NULL),
('imp-35164fb31de89c5f_v4_step_1', 'imp-35164fb31de89c5f', 1, 'cook', 'Luộc chín mềm ức gà ta và xé sợi', 'Cho 400 g ức gà vào nồi với 1 lít nước lọc, phần đầu hành lá đập dập và 2 g muối ăn. Đun sôi trên lửa vừa rồi hạ lửa nhỏ luộc khoảng 12 phút đến khi thịt gà chín trắng hoàn toàn, tắt bếp đậy nắp ủ thêm 5 phút cho ngọt thịt. Vớt gà ngâm nước nguội 2 phút cho săn trắng rồi xé sợi dọc thớ, trộn nhẹ với 1,5 g tiêu đen xay.', 'Ủ thêm 5 phút sau khi tắt bếp giúp miếng ức gà chín đều tận lõi mà thớ thịt vẫn ẩm mềm, không bị khô bã.', 12),
('imp-35164fb31de89c5f_v4_step_2', 'imp-35164fb31de89c5f', 2, 'prep', 'Sơ chế bắp cải, cà rốt và hành tây giòn mát', 'Bào sợi thật mỏng 280 g bắp cải trắng và 110 g cà rốt, xóc nhẹ với 2 g muối ăn để 5 phút rồi rửa nhanh qua nước lọc lạnh và vắt thật ráo nước. Thái lát mỏng 70 g hành tây, ngâm vào tô nước đá lạnh pha 5 g đường cát trắng trong 10 phút cho hết hăng rồi vớt ra để thật ráo cùng hành lá chẻ sợi và rau răm thái rối.', 'Vắt thật ráo rau củ sau khi ngâm nước đá giúp đĩa gỏi khô ráo giòn ngon, nước sốt bám đều mà không bị loãng vị.', 10),
('imp-35164fb31de89c5f_v4_step_3', 'imp-35164fb31de89c5f', 3, 'sauce', 'Pha nước mắm chanh tỏi ớt chua ngọt', 'Vắt 1,5 quả chanh tươi lấy nước cốt bỏ hạt. Cho 30 ml nước mắm ngon, 20 g đường cát trắng còn lại và nước cốt chanh vào chén, khuấy tan hoàn toàn đường rồi mới cho tỏi băm nhuyễn và 1 quả ớt hiểm băm nhỏ vào để tỏi ớt nổi đẹp trên mặt sốt.', 'Khuấy tan hoàn toàn đường với nước mắm và chanh trước khi thả tỏi ớt băm giúp phần tỏi ớt nổi đẹp mà không chìm đáy.', NULL),
('imp-35164fb31de89c5f_v4_step_4', 'imp-35164fb31de89c5f', 4, 'cook', 'Trộn sơ gà xé với một phần nước sốt', 'Cho thịt ức gà xé sợi vào thau lớn, rưới 1/3 lượng nước mắm chanh tỏi ớt đã pha vào trộn nhẹ cho thịt gà ngấm trước vị chua ngọt đậm đà.', NULL, NULL),
('imp-35164fb31de89c5f_v4_step_5', 'imp-35164fb31de89c5f', 5, 'cook', 'Trộn đều bắp cải, cà rốt, hành tây và rau răm', 'Cho bắp cải, cà rốt bào sợi, hành tây ngâm ráo, rau răm và hành lá chẻ sợi vào thau thịt gà. Rưới phần nước mắm chanh còn lại lên trên rồi dùng tay sạch (đeo găng) trộn nhẹ nhàng từ dưới lên để các sợi rau không bị dập nát mà vẫn thấm đều gia vị.', NULL, NULL),
('imp-35164fb31de89c5f_v4_step_6', 'imp-35164fb31de89c5f', 6, 'finish', 'Bày đĩa gỏi gà và rắc đậu phộng rang', 'Gắp gỏi gà bắp cải xếp gọn gàng lên đĩa, trang trí thêm vài lát ớt hiểm đỏ và rắc toàn bộ 30 g đậu phộng rang giã dập lên trên cùng. Thưởng thức ngay khi rau còn giòn mát.', NULL, NULL),
('imp-368d91563cb1879b_v4_step_1', 'imp-368d91563cb1879b', 1, 'prep', 'Chần xương ống và ninh nước dùng ngọt thanh', 'Chặt nhỏ 600 g xương ống heo, chần nước sôi 3 phút với 1 g muối ăn rồi vớt ra rửa sạch bọt bẩn. Cho xương vào nồi cùng 2400 ml nước lọc và 2 g muối ăn, đun sôi bùng rồi hạ lửa nhỏ liu riu ninh 25 phút, hớt bọt thường xuyên để nước dùng thật trong ngọt.', NULL, 25),
('imp-368d91563cb1879b_v4_step_2', 'imp-368d91563cb1879b', 2, 'prep', 'Làm sạch cá diêu hồng, tôm tươi và rau nấm', 'Chà xát 400 g cá diêu hồng với 2 g muối ăn cho hết nhớt, rửa sạch để ráo rồi cắt khúc dày 2 cm. Rửa sạch 400 g tôm tươi, cắt râu và rút chỉ đen lưng. Cắt gốc và rửa sạch nấm đùi gà thái lát, nấm rơm bổ đôi, rau muống cắt khúc; băm nhỏ hành tím, tỏi khô, 1 cây sả; đập dập 3 cây sả còn lại, thái lát riềng, vò nhẹ lá chanh, bổ múi cau cà chua và vắt nước cốt 2 quả chanh tươi.', 'Chà muối khử nhớt cá diêu hồng rồi rửa lại thật sạch và thấm khô giúp cá săn chắc, không bị tanh khi nhúng lẩu.', NULL),
('imp-368d91563cb1879b_v4_step_3', 'imp-368d91563cb1879b', 3, 'cook', 'Phi thơm sả riềng và xào nền sốt lẩu Thái', 'Làm nóng chảo sâu lòng với 20 ml dầu ăn trên lửa vừa, phi thơm hành tím, tỏi băm, sả băm, sả cây đập dập và riềng thái lát khoảng 2 phút cho dậy mùi. Cho phần cà chua băm nhỏ, 15 ml sa tế tôm và 25 g sốt gia vị lẩu Thái vào đảo đều 3 phút đến khi cà chua mềm nhuyễn lên màu đỏ cam đẹp mắt.', NULL, 5),
('imp-368d91563cb1879b_v4_step_4', 'imp-368d91563cb1879b', 4, 'cook', 'Hòa nước hầm xương và nấu sôi nước dùng chua cay', 'Vớt bỏ xương ống từ nồi nước ninh (hoặc giữ lại tùy thích), trút hỗn hợp sốt sả riềng vừa xào vào nồi nước dùng cùng 2 quả cà chua bổ múi cau và 1 quả ớt hiểm đập dập. Đun sôi 5 phút trên lửa vừa rồi nêm 30 ml nước mắm ngon, 8 g hạt nêm, 20 g đường cát trắng và 1 g muối ăn còn lại.', 'Nêm gia vị trước khi thả lá chanh và nước cốt chanh sẽ giúp bạn kiểm soát vị mặn ngọt chuẩn xác mà không bị vị chua làm nhiễu.', 5),
('imp-368d91563cb1879b_v4_step_5', 'imp-368d91563cb1879b', 5, 'cook', 'Thả lá chanh và rưới nước cốt chanh tạo vị chua tươi', 'Tắt bếp hoặc hạ về mức lửa nhỏ nhất để nước không sôi sùng sục, thả lá chanh đã vò nhẹ vào nồi và từ từ rưới nước cốt chanh tươi vào khuấy đều, nếm lại sao cho nước dùng dậy vị chua cay ngọt hài hòa đúng điệu miền Tây.', 'Tắt bếp rồi mới vắt chanh và thả lá chanh giúp giữ trọn tinh dầu thơm mát và tránh làm nước lẩu bị đắng gắt.', NULL),
('imp-368d91563cb1879b_v4_step_6', 'imp-368d91563cb1879b', 6, 'finish', 'Bày nồi lẩu lên bàn và nhúng cá, tôm, nấm nóng hổi', 'Chuyển nồi lẩu sang bếp bàn đun sôi lăn tăn, thả nấm đùi gà, nấm rơm và cá diêu hồng vào nấu trước 5 phút cho cá chín chắc hoàn toàn. Tiếp tục nhúng tôm tươi khoảng 3 phút đến khi tôm chuyển màu đỏ cam săn giòn, nhúng rau muống ăn kèm bún tươi và 2 quả ớt thái lát chấm nước mắm.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-c52c790faf9281da_v4_step_1', 'imp-c52c790faf9281da', 1, 'prep', 'Sơ chế các loại nấm tươi, đậu phụ và rau củ', 'Cắt bỏ phần gốc bám đất của nấm đùi gà, nấm bào ngư, nấm kim châm, nấm rơm và nấm đông cô tươi; ngâm nhanh qua nước pha 2 g muối ăn rồi rửa sạch, để thật ráo và thái lát vừa ăn. Cắt khoanh 250 g bắp ngọt và 1 củ cà rốt; cắt khối vuông 2,5 cm 2,5 bìa đậu phụ trắng; cắt khúc bắp cải trắng và thái lát phần củ trắng hành boa-rô.', 'Vắt nhẹ hoặc để các loại nấm thật ráo nước trước khi bày đĩa giúp nấm giữ độ giòn ngọt và không làm loãng nước lẩu khi nhúng.', NULL),
('imp-c52c790faf9281da_v4_step_2', 'imp-c52c790faf9281da', 2, 'prep', 'Luộc chín mềm bún khô hoặc mì chay', 'Ngâm 200 g bún khô hoặc mì chay khô trong nước lạnh 5 phút cho mềm bớt rồi luộc trong nồi nước sôi 4 phút đến khi sợi chín dẻo vừa tới. Vớt ra xả lại nước đun sôi để nguội cho tơi sợi rồi xếp ra đĩa ăn kèm.', NULL, 4),
('imp-c52c790faf9281da_v4_step_3', 'imp-c52c790faf9281da', 3, 'cook', 'Phi thơm hành boa-rô và xào nấm tạo hương', 'Làm nóng nồi trên lửa vừa với 20 ml dầu ăn thực vật, cho phần củ trắng hành boa-rô thái lát vào phi thơm khoảng 1 phút đến khi hơi vàng. Trút một nửa lượng nấm đông cô tươi vào đảo nhanh 2 phút cho dậy hương thơm đặc trưng.', 'Xào sơ nấm đông cô cùng hành boa-rô phi sẽ giúp nước lẩu chay dậy mùi thơm ấm hấp dẫn không thua kém nước hầm xương.', 3),
('imp-c52c790faf9281da_v4_step_4', 'imp-c52c790faf9281da', 4, 'cook', 'Ninh bắp ngọt và cà rốt lấy nước lẩu thanh ngọt', 'Đổ 2200 ml nước lọc vào nồi, thả toàn bộ bắp ngọt cắt khoanh và cà rốt vào đun sôi bùng. Hạ lửa vừa ninh khoảng 15 phút để bắp ngọt và cà rốt tiết hết vị ngọt thanh tự nhiên vào nước dùng, hớt sạch bọt nếu có.', NULL, 15),
('imp-c52c790faf9281da_v4_step_5', 'imp-c52c790faf9281da', 5, 'cook', 'Nêm gia vị thuần chay hài hòa', 'Nêm 25 ml nước tương, 12 g hạt nêm chay nấm hương, 12 g đường phèn và 5 g muối ăn vào nồi nước dùng, khuấy tan đều và nấu thêm 2 phút cho nước lẩu thấm vị thanh ngọt dịu nhẹ.', 'Sử dụng đường phèn thay đường cát giúp nước lẩu chay có độ ngọt thanh mát tự nhiên, không bị ngọt gắt cổ.', NULL),
('imp-c52c790faf9281da_v4_step_6', 'imp-c52c790faf9281da', 6, 'finish', 'Chuyển nồi lẩu ra bàn và nhúng nấm, đậu phụ nóng hổi', 'Chuyển nồi lẩu lên bếp giữa bàn giữ sôi lăn tăn, thả phần lá xanh hành boa-rô cắt khúc, đậu phụ trắng và váng đậu vào nấu 3 phút. Lần lượt nhúng nấm đùi gà, nấm bào ngư, nấm rơm, nấm kim châm và bắp cải vừa chín tới rồi thưởng thức nóng cùng bún khô luộc và 10 ml nước tương pha ớt tươi thái lát.', NULL, NULL),
('imp-e9678cfa1bc90074_v4_step_1', 'imp-e9678cfa1bc90074', 1, 'marinate', 'Làm sạch tôm và ướp gia vị', 'Tôm tươi bóc vỏ, khứa dọc sống lưng lấy sạch chỉ đen rồi rửa lại và thấm thật khô. Ướp tôm với 5 ml xì dầu nhạt, 0,5 g muối ăn và một nửa lượng tiêu trắng xay trong 10 phút. Cà chua chín bổ múi cau; tỏi khô băm nhỏ; hành lá tươi tách riêng đầu trắng và lá xanh thái nhỏ.', NULL, 10),
('imp-e9678cfa1bc90074_v4_step_2', 'imp-e9678cfa1bc90074', 2, 'prep', 'Đánh trứng gà mềm mượt', 'Hòa tan 3 g bột năng với 15 ml nước lọc (nếu dùng). Đập 5 quả trứng gà vào tô cùng hỗn hợp bột năng, 1,5 g muối ăn, phần tiêu trắng xay còn lại, 2,5 ml dầu mè thơm và 5 ml rượu Thiệu Hưng; đánh đều tay trong 1 phút cho trứng hòa quyện.', 'Bột năng pha loãng giúp trứng giữ nước khi xào, tạo kết cấu mềm mượt mà không bị tách nước.', NULL),
('imp-e9678cfa1bc90074_v4_step_3', 'imp-e9678cfa1bc90074', 3, 'cook', 'Chần nhanh tôm và chiên xốp trứng', 'Đun sôi một nồi nước nhỏ, thả tôm đã ướp vào chần nhanh 30–40 giây đến khi thịt tôm vừa chuyển màu hồng cam thì vớt ra để ráo, giữ độ giòn ngọt. Sau đó, làm nóng 14 ml dầu ăn thực vật trong chảo trên lửa vừa, đổ trứng gà vào đảo nhẹ đến khi trứng chín khoảng 70% còn mềm ẩm thì trút ra đĩa.', 'Chần sơ tôm trước giúp tôm không tiết nước làm loãng sốt và giữ độ giòn sần sật khi đảo lại cùng cà chua.', 3),
('imp-e9678cfa1bc90074_v4_step_4', 'imp-e9678cfa1bc90074', 4, 'cook', 'Phi thơm tỏi hành và nấu sốt cà chua', 'Cho 14 ml dầu ăn thực vật còn lại vào chảo, phi thơm tỏi băm và đầu hành trắng khoảng 30 giây, thả cà chua vào xào lửa lớn 1 phút. Tiếp tục cho 15 ml tương cà chua, 15 g cà chua cô đặc, 10 ml xì dầu nhạt còn lại, 8 g đường cát trắng, 2 g muối ăn và 60 ml nước lọc vào, đậy nắp nấu lửa vừa 4 phút cho cà chua mềm nhừ thành sốt sệt.', NULL, 5),
('imp-e9678cfa1bc90074_v4_step_5', 'imp-e9678cfa1bc90074', 5, 'cook', 'Đảo quyện tôm và trứng vào sốt', 'Mở nắp, thả tôm đã chần vào đảo 1 phút cho tôm chín chắc hoàn toàn và ngấm sốt, rồi nhẹ tay trút phần trứng chiên mềm vào đảo quyện 30 giây để sốt cà chua bám đều từng miếng trứng và tôm.', 'Không đảo mạnh tay khi cho trứng vào để giữ các mảng trứng xốp mềm ngấm sốt mà không bị nát vụn.', 1),
('imp-e9678cfa1bc90074_v4_step_6', 'imp-e9678cfa1bc90074', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Rưới 2,5 ml dầu mè thơm còn lại, rắc phần lá hành xanh thái nhỏ lên trên, đảo nhẹ một lượt rồi tắt bếp ngay. Trút ra đĩa sâu lòng và thưởng thức khi còn nóng cùng cơm trắng.', NULL, NULL),
('imp-387c41fb3a0c2297_v4_step_1', 'imp-387c41fb3a0c2297', 1, 'marinate', 'Thái hạt lựu và ướp thịt đùi gà', 'Thái 500 g thịt đùi gà không xương thành khối hạt lựu đều cạnh 1,5 cm. Trộn đều gà với 15 ml xì dầu nhạt, 10 ml rượu Thiệu Hưng, 8 g bột bắp, 1 g muối ăn, 1 g tiêu trắng xay và 10 ml dầu ăn thực vật. Để ướp trong 15 phút cho thịt ngấm gia vị và mềm mượt.', 'Lớp bột bắp cùng một chút dầu ăn giúp khóa ẩm miếng gà và ngăn thịt dính vào nhau khi cho lên chảo nóng.', 15),
('imp-387c41fb3a0c2297_v4_step_2', 'imp-387c41fb3a0c2297', 2, 'sauce', 'Pha chén sốt Kung Pao chua ngọt', 'Trong chén nhỏ, khuấy đều 30 ml nước dùng gà, 30 ml giấm đen Trấn Giang, 15 ml rượu Thiệu Hưng còn lại, 10 ml xì dầu nhạt còn lại, 8 ml xì dầu đặc, 22 g đường cát trắng, 6 g bột bắp còn lại và 1 g muối ăn đến khi đường và bột bắp tan hoàn toàn. Chuẩn bị sẵn tỏi khô thái lát, gừng tươi thái sợi, ớt khô cắt khúc, hành lá cắt khúc và ớt chuông đỏ thái hạt lựu (nếu dùng).', NULL, NULL),
('imp-387c41fb3a0c2297_v4_step_3', 'imp-387c41fb3a0c2297', 3, 'cook', 'Xào săn thịt gà rồi trút ra đĩa', 'Làm nóng chảo sâu lòng trên lửa vừa lớn với 15 ml dầu ăn thực vật. Trút thịt gà đã ướp vào dàn đều một lớp, giữ yên 30 giây cho mặt dưới se vàng rồi đảo nhanh tay khoảng 2–3 phút đến khi mặt ngoài gà vừa chuyển trắng đục và chín khoảng 80%. Lập tức vớt gà ra đĩa riêng.', NULL, 3),
('imp-387c41fb3a0c2297_v4_step_4', 'imp-387c41fb3a0c2297', 4, 'cook', 'Phi thơm hoa tiêu, ớt khô và hương liệu', 'Hạ lửa nhỏ, cho 20 ml dầu ăn thực vật còn lại vào chảo rồi thả 2 g hoa tiêu Tứ Xuyên và 6 quả ớt khô đỏ Tứ Xuyên cắt khúc vào đảo đều khoảng 1 phút cho dậy hương cay tê mà không bị cháy đen. Tăng lửa vừa, thêm tỏi khô, gừng tươi, một nửa hành lá tươi và ớt chuông đỏ vào đảo thơm 1 phút.', 'Luôn giữ lửa nhỏ khi phi hoa tiêu và ớt khô để tránh bị cháy sém gây vị đắng cho món xào.', 2),
('imp-387c41fb3a0c2297_v4_step_5', 'imp-387c41fb3a0c2297', 5, 'cook', 'Đảo gà với sốt đến khi sánh bóng', 'Khuấy đều lại chén sốt rồi rót nhanh vào chảo, đảo đều tay 15 giây cho sốt bắt đầu sôi lăn tăn và sánh lại. Trút toàn bộ thịt gà trở lại chảo, bật lửa lớn đảo nhanh 1–2 phút đến khi thịt gà chín kỹ hoàn toàn, không còn màu hồng và nước sốt sánh bóng bám đều từng miếng.', NULL, 2),
('imp-387c41fb3a0c2297_v4_step_6', 'imp-387c41fb3a0c2297', 6, 'finish', 'Trộn đậu phộng rang và hoàn thiện', 'Thả 70 g đậu phộng rang giòn và phần hành lá tươi còn lại vào chảo, xóc nhanh tay 5 giây cho quyện đều rồi tắt bếp ngay. Bày ra đĩa, có thể rưới thêm 8 ml dầu ớt Tứ Xuyên lên mặt và dùng nóng cùng cơm trắng.', 'Chỉ cho đậu phộng rang vào ngay trước khi tắt bếp để giữ trọn độ giòn bùi, tránh bị ỉu do hơi ẩm.', NULL),
('imp-f5abd36e99d48d94_v4_step_1', 'imp-f5abd36e99d48d94', 1, 'prep', 'Sơ chế nguyên liệu và pha bột bắp', 'Cắt 350 g đậu phụ non thành từng khối vuông cạnh 2,5 cm thật gọn. Băm nhuyễn 20 g gừng tươi và 0,75 củ tỏi khô; thái nhỏ 0,5 bó hành lá tươi; cắt khúc ớt khô đỏ và thái lát mỏng ớt hiểm tươi. Hòa tan 5 g bột bắp với 45 ml nước lọc trong chén nhỏ; giữ riêng 1/2 muỗng cà phê bột hoa tiêu Tứ Xuyên để trang trí.', NULL, NULL),
('imp-f5abd36e99d48d94_v4_step_2', 'imp-f5abd36e99d48d94', 2, 'cook', 'Phi dầu ớt thơm từ ớt tươi và ớt khô', 'Đặt chảo sâu lòng lên lửa nhỏ, làm nóng 30 ml dầu ăn thực vật rồi cho hỗn hợp ớt hiểm tươi thái lát và ớt khô đỏ cắt khúc vào đảo đều trong 4–5 phút đến khi dầu thấm màu cam đỏ và dậy mùi cay thơm nhưng ớt tuyệt đối không bị cháy đen. Tắt bếp và trút toàn bộ dầu lẫn ớt ra chén riêng.', 'Phi dầu ớt trên lửa nhỏ giúp chiết xuất tinh dầu cay thơm mà không làm ớt bị khét đắng.', 5),
('imp-f5abd36e99d48d94_v4_step_3', 'imp-f5abd36e99d48d94', 3, 'cook', 'Phi gừng tỏi và xào săn thịt heo xay', 'Cho 30 ml dầu ăn thực vật còn lại vào chảo, bật lửa vừa, phi thơm gừng băm 1 phút rồi cho tỏi băm vào đảo thêm 1 phút. Tăng lửa lớn, trút 170 g thịt heo xay vào dùng sạn dằm tơi và xào đều khoảng 3 phút cho thịt săn ráo và chín hoàn toàn.', NULL, 5),
('imp-f5abd36e99d48d94_v4_step_4', 'imp-f5abd36e99d48d94', 4, 'cook', 'Xào hoa tiêu, tương đậu bản và nấu sốt', 'Hạ lửa vừa, cho phần bột hoa tiêu Tứ Xuyên còn lại vào đảo nhanh 20 giây cho dậy mùi tê thơm, rồi thêm 28 g tương ớt đậu bản Doubanjiang vào xào đều 1 phút đến khi thịt quyện màu đỏ đẹp. Đổ 120 ml nước dùng gà vào, khuấy đều và đun sôi liu riu 1 phút.', 'Cho bột hoa tiêu vào sau khi thịt đã chín săn giúp gia vị thơm nồng mà không bị cháy đắng.', 2),
('imp-f5abd36e99d48d94_v4_step_5', 'imp-f5abd36e99d48d94', 5, 'cook', 'Sánh sốt và om đậu phụ thấm dầu ớt', 'Khuấy lại chén bột bắp rồi rót vào chảo, đảo đều 1–2 phút đến khi sốt sánh mượt vừa phải để bám miếng đậu. Tiếp theo, trút phần dầu ớt đã phi cùng đậu phụ non vào chảo, dùng lưng sạn hất đẩy nhẹ nhàng để sốt bao đều từng khối đậu và om mở nắp 4 phút cho đậu ngấm đẫm gia vị.', 'Sốt cần đủ sánh để bám đều mặt đậu phụ non nhưng vẫn giữ chút nước sốt đỏ để chan cơm nóng.', 5),
('imp-f5abd36e99d48d94_v4_step_6', 'imp-f5abd36e99d48d94', 6, 'finish', 'Rưới dầu mè, hành lá và hoàn thiện', 'Thêm 3 ml dầu mè thơm, 2 g đường cát trắng (nếu dùng) và hành lá thái nhỏ vào, đẩy nhẹ 30 giây đến khi hành vừa héo xanh. Tắt bếp, trút ra đĩa sâu lòng, rắc phần bột hoa tiêu Tứ Xuyên giữ riêng lên mặt và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-242fd73cebd63651_v4_step_1', 'imp-242fd73cebd63651', 1, 'prep', 'Chần sạch sườn non heo và sơ chế rau quả', 'Đun sôi 800 ml nước lọc trong nồi, thả 600 g sườn non heo chặt khúc vào chần 6–8 phút cho tiết hết bọt bẩn, vớt ra xả sạch dưới vòi nước lạnh rồi để ráo. Dứa chín cắt miếng tam giác vừa ăn; cà chua chín bổ múi cau; tỏi khô đập dập; gừng tươi thái lát mỏng.', 'Chần sườn qua nước sôi và rửa sạch lại giúp nước sốt om trong bóng và loại bỏ hoàn toàn mùi hôi.', 7),
('imp-242fd73cebd63651_v4_step_2', 'imp-242fd73cebd63651', 2, 'sauce', 'Pha hỗn hợp sốt chua ngọt', 'Cho vào tô lớn 40 ml tương cà chua, 30 ml giấm gạo trắng, 20 g đường cát trắng, 15 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml rượu Thiệu Hưng và 300 ml nước lọc còn lại. Khuấy đều tay đến khi đường tan hết.', NULL, NULL),
('imp-242fd73cebd63651_v4_step_3', 'imp-242fd73cebd63651', 3, 'cook', 'Phi thơm gừng tỏi và áp xém sườn non', 'Đun nóng 15 ml dầu ăn thực vật trong nồi đáy dày hoặc chảo sâu lòng trên lửa vừa, cho tỏi đập dập và gừng thái lát vào phi thơm 30 giây. Trút sườn non đã ráo vào áp xém các mặt khoảng 5 phút cho bề mặt sườn săn vàng thơm.', 'Áp xém sườn trước khi om giúp miếng thịt giữ nước ngọt bên trong và dễ bám sốt đẹp mắt.', 5),
('imp-242fd73cebd63651_v4_step_4', 'imp-242fd73cebd63651', 4, 'cook', 'Om mềm sườn trong nước sốt', 'Đổ toàn bộ tô nước sốt chua ngọt đã pha vào nồi ngập sườn, đun sôi bùng trên lửa lớn rồi hạ lửa nhỏ nhất, đậy nắp kín om liu riu trong 25–30 phút đến khi thịt sườn mềm róc xương và ngấm vị; cứ mỗi 10 phút mở nắp đảo một lần cho đều màu.', NULL, 28),
('imp-242fd73cebd63651_v4_step_5', 'imp-242fd73cebd63651', 5, 'cook', 'Thả dứa cà chua và cô sánh nước sốt', 'Mở nắp nồi, cho dứa chín và cà chua bổ múi cau vào nấu trên lửa vừa 4 phút cho dứa cà vừa chín mềm mà vẫn giữ hình dáng. Tiếp tục tăng lửa lớn, mở nắp hoàn toàn và đảo liên tục khoảng 3 phút cho nước sốt cô cạn sánh keo, ôm bóng quanh từng khúc sườn.', 'Cho dứa và cà chua vào giai đoạn cuối giúp giữ độ tươi ngon và vị chua ngọt thanh sáng cho món ăn.', 7),
('imp-242fd73cebd63651_v4_step_6', 'imp-242fd73cebd63651', 6, 'finish', 'Nêm muối cân vị và hoàn thiện', 'Nêm thêm 3 g muối ăn (tùy khẩu vị) để cân bằng vị chua ngọt, đảo nhẹ một vòng cho đều vị rồi tắt bếp. Bày sườn cùng dứa cà chua ra đĩa lớn, rưới hết phần sốt keo bóng lên mặt và dùng nóng với cơm trắng.', NULL, NULL),
('imp-34f3eb2438125614_v4_step_1', 'imp-34f3eb2438125614', 1, 'prep', 'Xé tay bắp cải, thái cà rốt và để thật ráo', 'Tách rời từng lá bắp cải xanh, loại bỏ phần gân lá dày cứng rồi dùng tay xé thành miếng vừa ăn. Thái lát mỏng cà rốt tươi; rửa nhẹ cả hai loại rau rồi vẩy thật ráo nước. Đập dập cắt đôi tỏi khô, thái sợi gừng tươi, bỏ hạt cắt khúc ớt khô đỏ, cắt khúc 5 cm hành lá tươi và thái lát mỏng thịt ba chỉ heo (nếu dùng).', 'Rau phải thật ráo nước trước khi cho vào chảo nóng để tránh làm hạ nhiệt, khiến bắp cải bị ra nước và mất độ giòn.', NULL),
('imp-34f3eb2438125614_v4_step_2', 'imp-34f3eb2438125614', 2, 'cook', 'Áp chảo thịt ba chỉ lấy mỡ thơm', 'Làm nóng chảo sâu lòng trên lửa lớn đến khi hơi bốc khói, cho 22 ml dầu ăn thực vật tráng đều lòng chảo. Nếu dùng thịt ba chỉ heo, cho thịt vào áp chảo 2 phút cho hai mặt xém vàng và tiết bớt mỡ thơm rồi gạt sang mép chảo hoặc gắp ra riêng.', NULL, 2),
('imp-34f3eb2438125614_v4_step_3', 'imp-34f3eb2438125614', 3, 'cook', 'Phi thơm ớt khô, tỏi và gừng', 'Hạ lửa vừa, cho ớt khô đỏ cắt khúc vào đảo khoảng 20 giây cho dậy mùi cay nhẹ, tiếp tục thả tỏi khô và gừng tươi thái sợi vào phi thơm thêm 40 giây đến khi tỏi hơi ngả vàng thơm mà không bị cháy đắng.', 'Luôn để mắt tới tỏi phi ở lửa vừa vì tỏi cháy sẽ làm món rau xào bị đắng và sậm màu.', 1),
('imp-34f3eb2438125614_v4_step_4', 'imp-34f3eb2438125614', 4, 'cook', 'Xào lửa lớn bắp cải và cà rốt', 'Vặn lửa lớn nhất, trút toàn bộ bắp cải xanh và cà rốt vào chảo đảo nhanh tay trong 1 phút. Rưới 10 ml rượu Thiệu Hưng quanh thành chảo cho bốc hơi thơm, thêm 15 ml xì dầu nhạt, 2 g đường cát trắng và 15 ml nước lọc, đảo đều rồi đậy nắp om nhanh 1–2 phút cho bắp cải vừa chín tới.', NULL, 2),
('imp-34f3eb2438125614_v4_step_5', 'imp-34f3eb2438125614', 5, 'cook', 'Thêm giấm đen và nêm muối cân vị', 'Mở nắp, trút thịt ba chỉ heo trở lại chảo (nếu dùng), rưới 5 ml giấm đen Trấn Giang và nêm 3 g muối ăn, đảo nhanh tay 30 giây trên lửa lớn đến khi nước hơi cạn ráo và mép lá bắp cải xém nhẹ đẹp mắt.', 'Cho giấm đen vào công đoạn cuối giúp giữ nguyên vị chua thanh dịu và hương thơm đặc trưng mà không bị bay hơi hết.', NULL),
('imp-34f3eb2438125614_v4_step_6', 'imp-34f3eb2438125614', 6, 'finish', 'Thêm hành lá và hoàn thiện', 'Thả hành lá tươi cắt khúc vào đảo nhanh 20–30 giây cho hành vừa chín tái giữ màu xanh tươi rồi tắt bếp ngay. Múc ra đĩa và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-2d508cd359edb61c_v4_step_1', 'imp-2d508cd359edb61c', 1, 'prep', 'Thấm khô và băm nhuyễn chả tôm', 'Tôm tươi bóc vỏ rút sạch chỉ đen, dùng khăn giấy thấm thật khô từng con rồi dùng dao băm nhuyễn bằng tay để thịt tôm giữ được độ dai giòn tự nhiên, không bị bở nát. Gừng tươi băm nhuyễn; hành lá tươi tách phần đầu trắng thái lát mỏng và phần lá xanh thái nhỏ.', 'Thấm thật khô tôm và băm bằng dao thay vì xay máy sẽ giúp chả tôm dẻo quánh, giòn sần sật khi hấp.', NULL),
('imp-2d508cd359edb61c_v4_step_2', 'imp-2d508cd359edb61c', 2, 'marinate', 'Quết dẻo chả tôm với gừng hành', 'Cho thịt tôm băm vào tô cùng 8 ml rượu Thiệu Hưng, 2 g bột bắp, 4 ml dầu mè thơm, 1,5 g muối ăn và một nửa lượng tiêu trắng xay. Dùng muỗng quết mạnh tay theo một chiều trong 4 phút đến khi chả tôm dẻo dính có độ đàn hồi. Sau đó trộn thêm gừng băm, đầu hành trắng và lòng trắng trứng gà (nếu dùng) vào quyện đều.', NULL, 4),
('imp-2d508cd359edb61c_v4_step_3', 'imp-2d508cd359edb61c', 3, 'prep', 'Xếp đậu phụ trứng và tạo hình tôm hấp', 'Cắt ống đậu phụ trứng thành 12 khoanh tròn dày đều nhau khoảng 2 cm, xếp gọn lên đĩa sâu lòng chịu nhiệt. Dùng muỗng múc khoảng 1 muỗng canh chả tôm đắp lên bề mặt mỗi khoanh đậu phụ và ấn nhẹ ở giữa cho chả bám chắc vào miếng đậu.', NULL, NULL),
('imp-2d508cd359edb61c_v4_step_4', 'imp-2d508cd359edb61c', 4, 'cook', 'Hấp chín đậu phụ tôm trong xửng nóng', 'Đun sôi nước trong xửng hấp trên lửa lớn, đặt đĩa đậu phụ tôm vào xửng, đậy kín nắp và hấp liên tục trong 10 phút cho đến khi chả tôm chuyển màu hồng cam tươi, săn chắc chín hoàn toàn bên trong và đậu phụ trứng nóng đều.', 'Chỉ đặt đĩa vào khi nước trong xửng đã sôi mạnh để chả tôm se mặt nhanh, giữ trọn vị ngọt và tránh đọng quá nhiều nước.', 10),
('imp-2d508cd359edb61c_v4_step_5', 'imp-2d508cd359edb61c', 5, 'sauce', 'Nấu sốt xì dầu dầu hào sánh mượt', 'Trong lúc chờ hấp, khuấy đều trong chén nhỏ 120 ml nước lọc, 10 ml xì dầu nhạt, 6 ml dầu hào, 3 g bột bắp còn lại, 2 g đường cát trắng và phần tiêu trắng xay còn lại. Đổ hỗn hợp vào chảo nhỏ, đun lửa vừa và khuấy liên tục 2 phút đến khi sốt trong bóng, sánh nhẹ thì tắt bếp và khuấy thêm 4 ml dầu mè thơm.', NULL, 2),
('imp-2d508cd359edb61c_v4_step_6', 'imp-2d508cd359edb61c', 6, 'finish', 'Chắt nước hấp, rưới sốt và thưởng thức', 'Lấy đĩa đậu phụ hấp tôm ra khỏi xửng, nhẹ tay nghiêng đĩa chắt bỏ phần nước tiết ra khi hấp để món ăn không bị loãng vị. Rưới đều phần sốt nóng sánh bóng lên từng khoanh đậu phụ tôm, rắc lá hành xanh thái nhỏ lên mặt và dùng nóng ngay với cơm trắng.', 'Chắt sạch nước tiết ra sau khi hấp giúp lớp sốt rưới bám đậm đà và giữ trọn vị béo thơm của đậu phụ trứng.', NULL),
('imp-6eaf6ed6d417c52c_v4_step_1', 'imp-6eaf6ed6d417c52c', 1, 'prep', 'Sơ chế mực tươi và ướp khử tanh', 'Làm sạch 450 g mực ống tươi, cắt khoanh hoặc miếng vừa ăn và khía vằn nhẹ mặt trong. Có thể ướp mực với 15 ml rượu Thiệu Hưng trong 10 phút rồi dùng khăn giấy thấm thật khô ráo bề mặt mực. Băm nhuyễn tỏi khô, gừng tươi và ớt hiểm cùng ớt sừng đỏ; thái nhỏ hành lá tươi.', 'Thấm thật khô mực trước khi nhúng bột là yếu tố quyết định giúp lớp vỏ bám chắc và không bị bắn dầu khi chiên.', 10),
('imp-6eaf6ed6d417c52c_v4_step_2', 'imp-6eaf6ed6d417c52c', 2, 'prep', 'Pha bột ướt và trộn lớp bột khô', 'Trong tô vừa, khuấy tan 50 g bột mì đa dụng với 70 ml nước lọc, 2 g muối ăn và 1 g tiêu đen xay thành hỗn hợp bột ướt sánh mịn. Trong đĩa rộng khác, trộn đều 35 g bột mì đa dụng còn lại cùng 35 g bột bắp và 1,5 g bột nở Baking soda.', NULL, NULL),
('imp-6eaf6ed6d417c52c_v4_step_3', 'imp-6eaf6ed6d417c52c', 3, 'prep', 'Áo hai lớp bột cho từng miếng mực', 'Trút mực đã thấm khô vào tô bột ướt đảo đều cho bột áo mỏng khắp bề mặt, sau đó gắp từng miếng mực lăn kỹ qua đĩa bột khô để tạo lớp áo tơi mịn. Xếp thưa các miếng mực đã áo bột ra khay phẳng, tránh chồng lên nhau gây bết dính.', 'Áo bột từng mẻ và xếp thưa nhau giúp lớp bột khô tơi xốp khi tiếp xúc với dầu nóng.', NULL),
('imp-6eaf6ed6d417c52c_v4_step_4', 'imp-6eaf6ed6d417c52c', 4, 'cook', 'Chiên ngập dầu mực vàng giòn', 'Đun nóng 500 ml dầu ăn thực vật trong chảo sâu lòng đến khoảng 180°C (thả đầu đũa thấy sủi tăm mạnh). Chia mực thành 2–3 mẻ nhỏ rồi thả vào chiên lửa vừa lớn khoảng 2–3 phút mỗi mẻ đến khi lớp vỏ phồng vàng giòn và thịt mực chín trắng săn bên trong. Vớt mực ra giá lưới cho ráo dầu.', 'Không cho quá nhiều mực vào chiên cùng lúc để tránh làm tụt nhiệt độ dầu khiến lớp vỏ bị ngấm dầu và mềm ỉu.', 3),
('imp-6eaf6ed6d417c52c_v4_step_5', 'imp-6eaf6ed6d417c52c', 5, 'cook', 'Phi thơm tỏi, gừng và ớt băm', 'Chắt hết dầu chiên ra tô riêng, chỉ chừa lại khoảng 1 muỗng canh dầu nóng tráng mặt chảo. Hạ lửa vừa, cho tỏi băm, gừng băm và ớt băm vào đảo nhanh khoảng 1 phút cho dậy mùi thơm lừng mà không để tỏi cháy sậm.', NULL, 1),
('imp-6eaf6ed6d417c52c_v4_step_6', 'imp-6eaf6ed6d417c52c', 6, 'finish', 'Xóc mực với muối tiêu, hành lá và dọn nóng', 'Trút toàn bộ mực chiên giòn và hành lá tươi thái nhỏ vào chảo, rắc 1 g muối ăn và 1 g tiêu đen xay còn lại rồi xóc đảo nhanh tay trong 20–30 giây cho tỏi ớt và muối tiêu bám đều khắp miếng mực. Tắt bếp, bày ngay ra đĩa và dùng nóng giòn.', NULL, NULL),
('imp-d90dc5bbe2891a12_v4_step_1', 'imp-d90dc5bbe2891a12', 1, 'prep', 'Rang sơ gạo và sơ chế gừng hành', 'Vo sạch 220 g gạo tẻ thơm rồi để thật ráo nước. Cho gạo vào chảo khô rang trên lửa vừa khoảng 5 phút đến khi hạt gạo săn lại, đục đều và hơi thơm nhẹ. Trong lúc đó, gọt vỏ gừng tươi thái sợi chỉ mỏng, thái lát mỏng hành tím khô và thái nhỏ hành lá tươi.', 'Rang gạo trước khi nấu giúp hạt gạo nhanh nở bung đều và nước cháo sánh mịn thơm ngon hơn mà không bị vữa.', 5),
('imp-d90dc5bbe2891a12_v4_step_2', 'imp-d90dc5bbe2891a12', 2, 'marinate', 'Ướp thịt heo xay mềm tơi', 'Cho 200 g thịt heo xay vào tô, ướp cùng 15 ml xì dầu, 3 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn thực vật. Trộn đều rồi để ướp trong 15 phút cho thịt ngấm vị và giữ được độ mềm ẩm.', NULL, 15),
('imp-d90dc5bbe2891a12_v4_step_3', 'imp-d90dc5bbe2891a12', 3, 'cook', 'Ninh gạo với hành tím đến khi cháo sánh nhừ', 'Đun sôi 1800 ml nước lọc trong nồi lớn, đổ gạo đã rang và hành tím khô thái lát vào khuấy đều. Khi nước sôi lại, hạ lửa nhỏ, đậy vung hé và ninh liu riu khoảng 30 phút cho đến khi hạt gạo nở bung mềm mịn; thỉnh thoảng khuấy đều đáy nồi để cháo không bị khét.', 'Có thể châm thêm 100–150 ml nước sôi nếu thấy cháo sánh đặc hơn sở thích trong quá trình ninh.', 30),
('imp-d90dc5bbe2891a12_v4_step_4', 'imp-d90dc5bbe2891a12', 4, 'cook', 'Thả thịt heo xay và nấu chín kỹ', 'Khi cháo đã đạt độ sánh mịn, cho từng ít thịt heo xay đã ướp vào nồi đồng thời dùng vá khuấy liên tục để thịt rã tơi đều, không bị vón cục. Nấu tiếp trên lửa nhỏ 8–10 phút đến khi thịt chín kỹ hoàn toàn và quyện ngọt vào nước cháo.', 'Cho thịt bằm vào từng ít một kết hợp khuấy đều tay ngay lập tức là cách giúp thịt tơi mịn hoàn toàn trong nồi cháo.', 9),
('imp-d90dc5bbe2891a12_v4_step_5', 'imp-d90dc5bbe2891a12', 5, 'cook', 'Nêm gia vị và tạo vân trứng gà mượt', 'Nêm vào nồi cháo 10 ml xì dầu còn lại, 3 g muối ăn và 3 g hạt nêm còn lại, khuấy đều rồi nếm lại vừa miệng. Đánh tan 2 quả trứng gà trong chén, giữ nồi cháo sôi lăn tăn rồi rót trứng từ từ theo dòng mỏng đồng thời khuấy nhẹ một chiều khoảng 1–2 phút để tạo vân trứng mịn đẹp và chín đều.', NULL, 2),
('imp-d90dc5bbe2891a12_v4_step_6', 'imp-d90dc5bbe2891a12', 6, 'finish', 'Chia tô cùng gừng sợi và thưởng thức nóng', 'Tắt bếp. Xếp gừng tươi thái sợi chỉ vào đáy từng tô trước rồi múc cháo nóng hổi phủ lên trên để gừng dậy mùi cay ấm tự nhiên. Rắc hành lá thái nhỏ, 1 g tiêu đen xay còn lại và rưới 5 ml dầu mè thơm lên mặt, trộn đều ăn nóng ngay.', NULL, NULL),
('imp-b23ab24915e52866_v4_step_1', 'imp-b23ab24915e52866', 1, 'prep', 'Sơ chế nhân tôm thịt, lạp xưởng và rau củ', 'Ướp 150 g tôm tươi bóc vỏ thái hạt lựu với 1 g muối ăn, 1 g đường cát trắng và 0,5 g tiêu đen xay; ướp 100 g thịt heo xay với 2 g hạt nêm và 0,5 g tiêu đen xay trong 10 phút. Luộc chín 60 g lạp xưởng Quảng Đông trong 5 phút rồi để nguội, thái hạt lựu. Cà rốt và đậu cô ve thái hạt lựu, luộc sơ với 2 g muối ăn trong 2 phút rồi vớt ngâm nước lạnh và để ráo.', NULL, 10),
('imp-b23ab24915e52866_v4_step_2', 'imp-b23ab24915e52866', 2, 'prep', 'Trộn cơm vàng và tráng trứng cắt hạt lựu', 'Đánh tơi 600 g cơm trắng nguội. Tách 1 lòng đỏ trứng gà trộn đều vào cơm cùng 5 ml xì dầu nhạt và 1 g hạt nêm cho từng hạt cơm ánh vàng. Phần trứng gà còn lại đánh tan với 1 g hạt nêm, tráng chín vàng hai mặt trên chảo với 10 ml dầu ăn thực vật trong 3 phút rồi gắp ra thái hạt lựu.', 'Trộn lòng đỏ trứng vào cơm nguội trước khi chiên giúp từng hạt cơm tơi rời và lên màu vàng óng đều rất đẹp.', 3),
('imp-b23ab24915e52866_v4_step_3', 'imp-b23ab24915e52866', 3, 'cook', 'Xào chín tôm, thịt bằm và lạp xưởng', 'Làm nóng 10 ml dầu ăn thực vật trong chảo lớn, phi thơm một nửa tỏi khô băm rồi cho tôm vào xào nhanh lửa lớn 2 phút đến khi tôm chuyển hồng săn chắc hoàn toàn, trút ra đĩa. Tiếp tục cho thịt heo xay vào đảo tơi 2 phút cho chín đều, thả lạp xưởng thái hạt lựu vào đảo thêm 1 phút cho dậy mùi rồi trút chung ra đĩa.', 'Xào riêng từng nguyên liệu rồi mới trộn chung ở cuối giúp tôm giữ độ giòn ngọt và lạp xưởng không bị cháy xém.', 5),
('imp-b23ab24915e52866_v4_step_4', 'imp-b23ab24915e52866', 4, 'cook', 'Rang cơm tơi săn trên lửa lớn', 'Làm nóng 20 ml dầu ăn thực vật còn lại, phi thơm phần tỏi băm còn lại rồi cho cà rốt và đậu cô ve vào đảo 1 phút. Trút toàn bộ cơm đã trộn trứng vào chảo, đảo đều liên tục trên lửa lớn khoảng 5 phút cho đến khi hạt cơm nóng săn, tơi ráo và hơi nhảy nhẹ trên mặt chảo.', 'Giữ lửa lớn và đảo đều tay liên tục giúp cơm tơi giòn bên ngoài mà bên trong vẫn giữ được độ dẻo mềm.', 5),
('imp-b23ab24915e52866_v4_step_5', 'imp-b23ab24915e52866', 5, 'cook', 'Trộn quyện nhân thập cẩm và nêm gia vị', 'Cho toàn bộ tôm, thịt heo xay, lạp xưởng và trứng chiên cắt hạt lựu trở lại chảo cơm. Nêm 10 ml xì dầu nhạt còn lại, 2 g hạt nêm còn lại, 3 g đường cát trắng và phần tiêu đen xay còn lại, đảo đều thêm 2 phút cho mọi nguyên liệu quyện nóng đậm đà.', NULL, 2),
('imp-b23ab24915e52866_v4_step_6', 'imp-b23ab24915e52866', 6, 'finish', 'Rắc hành lá và trình bày nóng', 'Rắc hành lá tươi thái nhỏ vào chảo cơm, đảo nhanh thêm 20 giây cho hành dậy mùi thơm rồi tắt bếp. Múc cơm chiên Dương Châu ra đĩa, rắc thêm chút tiêu xay nếu thích và dùng nóng ngay.', NULL, NULL),
('imp-e83f58ebb9b02fbd_v4_step_1', 'imp-e83f58ebb9b02fbd', 1, 'prep', 'Rang giã hoa tiêu và sơ chế nguyên liệu', 'Rang khô 2 g hoa tiêu Tứ Xuyên trên chảo lửa nhỏ khoảng 2–3 phút đến khi dậy hương thơm rồi giã nhuyễn thành bột mịn. Băm thật nhuyễn tỏi khô; thái nhỏ hành lá tươi; giã dập 20 g đậu phộng rang; rửa sạch cải thìa tươi và chẻ đôi gốc.', NULL, 3),
('imp-e83f58ebb9b02fbd_v4_step_2', 'imp-e83f58ebb9b02fbd', 2, 'sauce', 'Pha sốt trộn Đan Đan vào 2 tô', 'Chia đều vào 2 tô ăn mì các gia vị gồm: 15 g sốt tương mè Tahini, 15 ml xì dầu nhạt, 2 g đường cát trắng, 1 g ngũ vị hương, bột hoa tiêu Tứ Xuyên vừa giã, 20 ml dầu ớt Tứ Xuyên, 6 ml dầu mè thơm, 10 ml giấm đen Trấn Giang, tỏi băm và một nửa hành lá thái nhỏ.', 'Pha sốt trực tiếp ở đáy tô giúp sợi mì nóng khi vớt vào sẽ dễ dàng quyện đều gia vị từ dưới lên.', NULL),
('imp-e83f58ebb9b02fbd_v4_step_3', 'imp-e83f58ebb9b02fbd', 3, 'cook', 'Xào thịt heo băm khô săn đậm vị', 'Đun nóng 10 ml dầu ăn thực vật trong chảo trên lửa vừa, trút 120 g thịt heo xay vào dùng sạn dằm tơi và xào khoảng 4–5 phút đến khi thịt săn vàng đều. Nêm 15 ml rượu Thiệu Hưng, 5 ml xì dầu đặc, 10 ml xì dầu nhạt còn lại và 2 g đường cát trắng còn lại, tiếp tục đảo 3 phút cho đến khi nước cạn ráo và thịt chín khô thơm. Tắt bếp để riêng.', 'Xào thịt đến khi cạn ráo hoàn toàn chất lỏng giúp thịt tơi giòn, dậy mùi xì dầu cháy cạnh đặc trưng cho mì Đan Đan.', 7),
('imp-e83f58ebb9b02fbd_v4_step_4', 'imp-e83f58ebb9b02fbd', 4, 'cook', 'Luộc mì và chần xanh cải thìa', 'Đun sôi 800 ml nước lọc trong nồi lớn, thả 200 g mì sợi lúa mì khô vào luộc khoảng 3–4 phút (hoặc theo hướng dẫn bao bì) đến khi sợi mì vừa chín dai. Trong 45 giây cuối, thả toàn bộ cải thìa tươi vào chần chung cho chín xanh giòn. Trước khi vớt, múc giữ lại 60 ml nước luộc mì nóng.', NULL, 4),
('imp-e83f58ebb9b02fbd_v4_step_5', 'imp-e83f58ebb9b02fbd', 5, 'finish', 'Hòa loãng sốt và xếp mì vào tô', 'Rót 30 ml nước luộc mì nóng vào mỗi tô sốt, khuấy kỹ cho sốt tương mè Tahini tan sánh mượt. Vớt mì cho vào tô, xếp cải thìa chần lên cạnh bên và múc thịt heo xào thơm phủ lên trên.', 'Nước luộc mì nóng giúp tương mè tan mịn ngay lập tức và tạo độ bóng mượt cho nước trộn.', NULL),
('imp-e83f58ebb9b02fbd_v4_step_6', 'imp-e83f58ebb9b02fbd', 6, 'finish', 'Rắc đậu phộng, hành lá và trộn đều thưởng thức', 'Rắc đậu phộng rang giã dập và phần hành lá tươi còn lại lên mặt mỗi tô mì. Dùng đũa trộn thật đều từ đáy tô trước khi thưởng thức nóng.', NULL, NULL),
('imp-04d477399e49fe8e_v4_step_1', 'imp-04d477399e49fe8e', 1, 'marinate', 'Thái lát và ướp mềm thịt bò kiểu Quảng Đông', 'Thấm khô 300 g thịt bò thăn, thái lát mỏng 2–3 mm ngang thớ thịt. Trộn đều thịt bò với 2 g Baking soda, 10 ml xì dầu nhạt, 10 g bột bắp, 1 g tiêu trắng xay, 10 ml dầu ăn thực vật và 15 ml nước lọc; để ướp 20 phút cho thịt mềm mọng. Pha sẵn chén sốt gồm 15 ml xì dầu nhạt còn lại, 8 ml xì dầu đặc, 20 ml dầu hào, 15 ml rượu Thiệu Hưng, 6 g đường cát trắng, 1 g tiêu trắng xay còn lại và 30 ml nước lọc.', 'Thái ngang thớ kết hợp ướp baking soda và bột bắp là bí quyết giúp thịt bò mềm mượt như ngoài hàng.', 20),
('imp-04d477399e49fe8e_v4_step_2', 'imp-04d477399e49fe8e', 2, 'prep', 'Sơ chế rau và luộc trụng mì trứng', 'Rửa sạch để ráo giá đỗ tươi và đậu Hà Lan quả ngọt đã tước xơ; cắt khúc 5 cm hành lá tươi tách riêng đầu trắng và lá xanh; băm nhỏ tỏi khô. Đun sôi 1000 ml nước lọc với 2 g muối ăn, thả 300 g mì trứng sợi dai vào luộc 2–3 phút đến khi vừa chín tới còn độ dai, vớt ra xả ráo rồi trộn ngay với 5 ml dầu ăn thực vật cho tơi sợi.', NULL, 3),
('imp-04d477399e49fe8e_v4_step_3', 'imp-04d477399e49fe8e', 3, 'cook', 'Áp chảo xém vàng sợi mì trứng', 'Làm nóng chảo sâu lòng trên lửa lớn đến khi hơi bốc khói, tráng 10 ml dầu ăn thực vật rồi dàn đều mì trứng thành lớp mỏng, áp chảo khoảng 2 phút mỗi mặt đến khi sợi mì săn ráo và hơi xém vàng thơm, sau đó gắp mì ra đĩa riêng.', 'Áp chảo sơ giúp sợi mì săn chắc, không bị nát và dậy mùi thơm chảo nóng khi trộn sốt.', 4),
('imp-04d477399e49fe8e_v4_step_4', 'imp-04d477399e49fe8e', 4, 'cook', 'Xào nhanh thịt bò chín tái trên lửa lớn', 'Thêm 5 ml dầu ăn thực vật vào chảo đang nóng già, dàn đều thịt bò đã ướp vào giữ yên 20 giây rồi đảo nhanh tay trên lửa lớn 1–2 phút đến khi thịt bò săn tái khoảng 80%, lập tức trút ra đĩa riêng.', 'Chỉ xào bò vừa tái khoảng 80% rồi trút ra ngay để giữ độ mềm mọng, bò sẽ chín hoàn hảo khi đảo lại ở bước cuối.', 2),
('imp-04d477399e49fe8e_v4_step_5', 'imp-04d477399e49fe8e', 5, 'cook', 'Xào rau giòn và trộn quyện mì với sốt', 'Cho 5 ml dầu ăn thực vật còn lại vào chảo, phi thơm tỏi băm và đầu hành trắng 15 giây, thả đậu Hà Lan quả ngọt và giá đỗ tươi vào đảo nhanh lửa lớn 1 phút cho rau vừa chín giữ độ giòn. Trút mì trứng trở lại chảo, rưới đều chén sốt đã pha và đảo nhanh 1–2 phút cho mì ngấm đều màu nâu bóng.', NULL, 2),
('imp-04d477399e49fe8e_v4_step_6', 'imp-04d477399e49fe8e', 6, 'finish', 'Trộn thịt bò, hành lá và hoàn thiện', 'Cho thịt bò xào và phần lá hành xanh vào chảo, đảo đều thêm 30 giây trên lửa lớn để thịt bò chín hoàn toàn và nóng quyện cùng sợi mì. Tắt bếp, rưới 5 ml dầu mè thơm lên trên, đảo một lượt cuối và dọn nóng ra đĩa.', NULL, NULL),
('imp-a22f9257b0fd7a46_v4_step_1', 'imp-a22f9257b0fd7a46', 1, 'prep', 'Chần sơ nguyên tảng thịt ba chỉ', 'Cạo sạch phần bì của 800 g thịt ba chỉ heo nguyên tảng. Đun sôi 1000 ml nước lọc trong nồi lớn, thả nguyên tảng thịt vào chần nhanh trong 2 phút để loại bỏ tạp chất và giúp khối thịt săn chắc dễ cắt. Vớt ra xả sạch dưới vòi nước lạnh rồi thấm khô.', 'Chần nguyên tảng trước khi cắt giúp các khối thịt vuông vắn, không bị co méo lệch lạc.', 2),
('imp-a22f9257b0fd7a46_v4_step_2', 'imp-a22f9257b0fd7a46', 2, 'prep', 'Cắt khối vuông và buộc dây giữ dáng', 'Cắt tảng thịt thành 5–6 khối vuông kích thước khoảng 6–7 cm. Dùng dây lạt hoặc chỉ buộc thực phẩm quấn chữ thập chắc tay quanh từng khối thịt để thịt không bị vỡ nát trong suốt quá trình om lâu.', NULL, NULL),
('imp-a22f9257b0fd7a46_v4_step_3', 'imp-a22f9257b0fd7a46', 3, 'prep', 'Lót đáy nồi với hành lá và gừng lát', 'Xếp toàn bộ hành lá tươi cắt khúc lót kín đều khắp đáy nồi đất hoặc nồi gang thành dày, rải đều 40 g gừng tươi thái lát lên trên. Đặt từng khối thịt ba chỉ với mặt bì úp xuống dưới xếp khít nhau trên lớp hành gừng.', 'Lớp hành lá dày dưới đáy vừa chống cháy khét phần bì suốt nhiều giờ om, vừa giúp phần thịt thấm hương thơm ngọt tự nhiên.', NULL),
('imp-a22f9257b0fd7a46_v4_step_4', 'imp-a22f9257b0fd7a46', 4, 'cook', 'Đổ rượu xì dầu và om liu riu lần một', 'Rưới đều 360 ml rượu Thiệu Hưng, 150 ml xì dầu nhạt và 35 ml xì dầu đặc lên thịt, thả 80 g đường phèn cùng hoa hồi khô, quế thanh khô và lá nguyệt quế khô (nếu dùng) vào. Đậy nắp kín, đun lửa vừa lớn cho đến khi sôi rồi lập tức hạ lửa nhỏ nhất, om liu riu 90 phút.', NULL, 90),
('imp-a22f9257b0fd7a46_v4_step_5', 'imp-a22f9257b0fd7a46', 5, 'cook', 'Lật mặt bì ngửa lên và om mềm tan', 'Mở nắp, nhẹ tay lật từng khối thịt cho mặt bì hướng lên trên để mặt bì bóng đẹp không bị bở. Đậy nắp kín lại và tiếp tục om lửa nhỏ thêm 75–90 phút nữa đến khi phần mỡ trong như thạch và xiên đũa qua thịt dễ dàng; nếu nước kho cạn quá nửa thì châm thêm ít nước lọc đun sôi.', 'Tuyệt đối chỉ châm thêm nước sôi nếu nước kho cạn, vì nước lạnh sẽ làm thớ thịt bị co cứng lại.', 80),
('imp-a22f9257b0fd7a46_v4_step_6', 'imp-a22f9257b0fd7a46', 6, 'finish', 'Cô sánh nước sốt và hoàn thiện', 'Nhẹ nhàng gắp các khối thịt ra đĩa sâu lòng, dùng kéo cắt bỏ dây buộc. Lọc phần nước kho trong nồi qua rây bỏ xác hành gừng, vớt bỏ thật sạch lớp mỡ tiết ra nổi trên mặt; trích khoảng một nửa lượng nước kho (phần nước kho mặn còn lại chắt bỏ hoặc giữ riêng làm nước nền) đun sôi trên lửa vừa khoảng 5 phút cho cô sánh lại vừa đủ phủ bóng mặt muỗng rồi rưới đều lên các khối thịt. Dùng nóng với cơm trắng.', NULL, 5),
('imp-5f8d0890bd6d0a76_v4_step_1', 'imp-5f8d0890bd6d0a76', 1, 'prep', 'Sơ chế củ năng, cải thảo và gừng hành', 'Đập dập rồi băm nhuyễn 100 g củ năng tươi (hoặc đóng hộp) để giữ độ giòn sần sật. Rửa sạch cải thảo tươi, cắt khúc dài 5–6 cm. Gọt vỏ 20 g gừng tươi: băm nhuyễn 10 g để trộn thịt và thái lát mỏng 10 g còn lại; hành lá tươi băm nhuyễn 1/3 để trộn thịt, phần còn lại cắt khúc 5 cm tách riêng đầu trắng và lá xanh.', NULL, NULL),
('imp-5f8d0890bd6d0a76_v4_step_2', 'imp-5f8d0890bd6d0a76', 2, 'marinate', 'Quết dẻo thịt heo với gia vị và củ năng', 'Trộn 450 g thịt heo xay với gừng băm, hành lá băm, 1 quả trứng gà, 25 g bột chiên xù khô, 15 ml rượu Thiệu Hưng, 15 ml xì dầu nhạt, 12 ml dầu hào, 1,5 g tiêu trắng xay, 1 g ngũ vị hương (nếu dùng), 5 g bột bắp và 60 ml nước lọc. Dùng tay quết mạnh theo một chiều khoảng 10 phút đến khi thịt dẻo quánh nhạt màu rồi trộn tiếp củ năng băm thêm 3 phút.', 'Quết thịt thật kỹ theo một chiều giúp viên thịt cỡ lớn có độ đàn hồi chắc chắn mà bên trong vẫn mềm xốp.', 13),
('imp-5f8d0890bd6d0a76_v4_step_3', 'imp-5f8d0890bd6d0a76', 3, 'cook', 'Vo 4 viên lớn và chiên vàng định hình', 'Thoa chút dầu ăn thực vật lên tay, chia thịt thành 4 phần đều nhau và vo thành 4 viên tròn lớn láng mịn. Đun nóng khoảng 385 ml dầu ăn thực vật trong nồi nhỏ đến 175°C, thả từng viên thịt vào chiên lửa vừa lớn khoảng 3 phút đến khi bề mặt vàng đều định hình chắc chắn thì vớt ra để ráo dầu.', 'Chiên nhanh ở nhiệt độ cao chỉ để tạo lớp vỏ vàng định hình, giúp viên thịt giữ nguyên dáng tròn đẹp khi kho lâu.', 3),
('imp-5f8d0890bd6d0a76_v4_step_4', 'imp-5f8d0890bd6d0a76', 4, 'cook', 'Phi thơm gừng hành và nấu nước kho', 'Làm nóng 15 ml dầu ăn thực vật trong chảo trên lửa nhỏ, phi thơm 10 g gừng thái lát và đầu hành trắng 1 phút, thả 10 g đường phèn vào đảo nhẹ đến khi đường tan hết. Đổ vào 15 ml rượu Thiệu Hưng, 20 ml xì dầu nhạt, 3 ml xì dầu đặc, 13 ml dầu hào, 1,5 g muối ăn (tùy khẩu vị) và 350 ml nước dùng gà, đun sôi nhẹ.', NULL, 3),
('imp-5f8d0890bd6d0a76_v4_step_5', 'imp-5f8d0890bd6d0a76', 5, 'cook', 'Kho mềm viên thịt trên lớp cải thảo', 'Xếp toàn bộ cải thảo tươi cắt khúc lót xuống đáy nồi đất hoặc nồi dày, đặt 4 viên thịt lên trên rồi chan toàn bộ nước kho nóng vào nồi. Đậy nắp kín, kho liu riu trên lửa nhỏ trong 18–20 phút (lật nhẹ viên thịt một lần giữa chừng) cho đến khi viên thịt chín mềm hoàn toàn bên trong và cải thảo ngấm ngọt.', 'Giữ lửa nhỏ sôi liu riu giúp cải thảo chín mềm mà không bị nhũn nát và viên thịt thấm sâu vị kho.', 18),
('imp-5f8d0890bd6d0a76_v4_step_6', 'imp-5f8d0890bd6d0a76', 6, 'finish', 'Sánh nước sốt, rưới dầu mè và hoàn thiện', 'Gắp cải thảo và 4 viên Sư Tử Đầu ra đĩa sâu lòng. Hòa tan 3 g bột bắp còn lại với 15 ml nước lọc, rót vào phần nước kho trong nồi và khuấy 2–3 phút trên lửa vừa đến khi sốt sánh bóng bám lưng muỗng. Tắt bếp, khuấy 3 ml dầu mè thơm và phần lá hành xanh vào rồi rưới đều sốt lên các viên thịt, dùng nóng với cơm trắng.', NULL, 3),
('imp-ece7da4660b63e9d_v4_step_1', 'imp-ece7da4660b63e9d', 1, 'prep', 'Thái thịt bò và sơ chế cà chua cùng gia vị thơm', 'Thấm thật khô thịt bò thăn bằng khăn giấy rồi thái lát mỏng ngang thớ dày khoảng 5–6 mm. Cà chua chín đỏ rửa sạch, bỏ cuống, bổ múi cau vừa ăn. Tỏi bóc vỏ băm nhỏ; gừng tươi thái lát mỏng; hành tím thái lát mỏng; hành lá cắt khúc 5 cm, tách riêng phần đầu trắng và phần lá xanh.', 'Thái thịt bò ngang thớ và giữ lát thịt đều độ dày giúp thịt chín đồng đều trong vài chục giây mà không bị dai.', NULL),
('imp-ece7da4660b63e9d_v4_step_2', 'imp-ece7da4660b63e9d', 2, 'marinate', 'Ướp mềm thịt bò theo kỹ thuật giữ ẩm', 'Cho thịt bò vào tô cùng 15 ml nước lọc, 6 g bột bắp và 1,2 g baking soda, trộn đều tay cho đến khi thịt hút hết nước. Tiếp tục thêm 10 ml dầu hào và 5 ml dầu ăn để khóa ẩm, trộn đều rồi ướp tối thiểu 20–30 phút trong ngăn mát tủ lạnh.', 'Kết hợp baking soda với nước và bột bắp giúp phá nhẹ cấu trúc sợi cơ và tạo lớp màng giữ nước, giữ thịt bò mềm mượt sau khi xào lửa lớn.', 25),
('imp-ece7da4660b63e9d_v4_step_3', 'imp-ece7da4660b63e9d', 3, 'sauce', 'Pha sẵn nước sốt và hỗn hợp bột bắp làm sánh', 'Trộn đều 22 ml xì dầu nhạt, 4 g đường cát trắng, 2,5 ml dầu mè và 0,5 g tiêu trắng xay trong một chén nhỏ cho tan hết gia vị. Ở chén khác, hòa tan 3 g bột bắp còn lại với 15 ml nước lọc rồi để sẵn cạnh bếp.', NULL, NULL),
('imp-ece7da4660b63e9d_v4_step_4', 'imp-ece7da4660b63e9d', 4, 'cook', 'Áp chảo sơ thịt bò trên lửa lớn', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn đến khi dầu nóng già và hơi gợn khói. Dàn thịt bò thành một lớp mỏng đều khắp mặt chảo, áp chảo khoảng 1 phút cho mặt thịt săn tái rồi đảo nhanh thêm 20 giây đến khi bò chín khoảng 80%, lập tức trút ra tô để riêng.', 'Không xào thịt bò chín kỹ ở bước này vì thịt sẽ tiếp tục chín khi đảo chung với sốt cà chua ở cuối.', 2),
('imp-ece7da4660b63e9d_v4_step_5', 'imp-ece7da4660b63e9d', 5, 'cook', 'Phi thơm gừng, tỏi, hành và xào nền cà chua', 'Cho 15 ml dầu ăn còn lại vào chảo trên lửa vừa, thả gừng tươi vào phi 10 giây cho xém cạnh thơm lừng. Tăng lên lửa lớn, cho tỏi băm, hành tím và đầu hành trắng vào đảo nhanh 10 giây, tiếp tục cho 22 ml tương cà (và 15 g cà chua cô đặc nếu dùng) vào xào 30 giây cho dậy màu đỏ đẹp. Thả cà chua múi cau vào đảo 15 giây rồi rưới 10 ml rượu Thiệu Hưng quanh thành chảo nóng.', NULL, 2),
('imp-ece7da4660b63e9d_v4_step_6', 'imp-ece7da4660b63e9d', 6, 'finish', 'Hòa sốt, đảo quyện thịt bò và làm sánh hoàn thiện', 'Gạt nhẹ cà chua sang một bên chảo, đổ chén nước sốt đã pha vào khoảng trống, đun sôi lăn tăn cho vị hòa quyện. Trút thịt bò (kèm cả nước tiết ra trong tô) trở lại chảo, đảo đều trên lửa lớn khoảng 30 giây cho thịt bò chín hẳn bên trong nhưng vẫn mềm mọng. Cho phần lá xanh hành lá vào, khuấy đều chén bột bắp rồi rưới từ từ vào chảo đến khi sốt sánh bóng bám đều miếng thịt, đun thêm 15 giây cho bột chín, nêm thêm 1,5 g muối ăn vừa miệng rồi dọn nóng ngay.', 'Đảo nhẹ tay ở bước cuối để miếng cà chua vẫn giữ nguyên múi đẹp mắt và không bị nát nhừ.', NULL),
('imp-b9d222a8c523b8e4_v4_step_1', 'imp-b9d222a8c523b8e4', 1, 'prep', 'Đập dập và cắt miếng dưa leo', 'Rửa sạch 3 quả dưa leo tươi, lau khô vỏ bằng khăn sạch rồi cắt bỏ hai đầu. Đặt mặt phẳng bản dao lớn nằm ngang lên từng quả dưa, dùng lòng bàn tay ấn vỗ dứt khoát cho thân dưa nứt tách làm 4 dải dài nhưng không bị nát vụn. Dựng các dải dưa lên rồi cắt chéo góc 45 độ thành miếng vừa ăn dài khoảng 3 cm.', 'Đập dập tạo các mép vỡ gồ ghề giúp nước sốt bám sâu vào thịt dưa hơn hẳn so với cách thái lát phẳng thông thường.', NULL),
('imp-b9d222a8c523b8e4_v4_step_2', 'imp-b9d222a8c523b8e4', 2, 'marinate', 'Ướp muối rút bớt nước giúp dưa giòn lâu', 'Cho dưa leo vào tô lớn, rắc đều 6 g muối ăn vào xóc nhẹ rồi để yên 15–20 phút cho dưa tiết bớt nước hăng. Sau khi ướp, chắt bỏ toàn bộ phần nước muối đã tiết ra và vắt nhẹ tay để miếng dưa ráo hẳn.', 'Nếu thử thấy miếng dưa hơi đậm vị muối, có thể tráng thật nhanh qua nước đun sôi để nguội rồi thấm khô trước khi trộn sốt.', 20),
('imp-b9d222a8c523b8e4_v4_step_3', 'imp-b9d222a8c523b8e4', 3, 'prep', 'Băm tỏi, thái ớt và rang thơm mè trắng', 'Trong lúc chờ ướp dưa, băm nhuyễn tỏi khô và thái lát mỏng ớt hiểm đỏ. Bắc chảo khô lên bếp lửa nhỏ, cho hạt mè trắng vào đảo đều khoảng 2 phút đến khi mè ngả vàng thơm thì trút ra chén để nguội. Nếu dùng tiêu Tứ Xuyên, rang cùng mè khoảng 30 giây cho dậy mùi rồi giã dập.', NULL, 3),
('imp-b9d222a8c523b8e4_v4_step_4', 'imp-b9d222a8c523b8e4', 4, 'sauce', 'Pha hỗn hợp nước sốt giấm đen Tứ Xuyên', 'Trong một chén vừa, hòa tan 20 ml xì dầu nhạt, 30 ml giấm đen Trấn Giang và 12 g đường cát trắng, khuấy đều tay cho đến khi đường tan hoàn toàn. Tiếp tục rót 15 ml dầu mè và 15 ml dầu ớt Tứ Xuyên vào khuấy hòa quyện.', 'Khuấy tan hết đường trước khi trộn vào dưa giúp vị chua, ngọt, mặn phân bố đồng đều trên từng miếng dưa leo.', NULL),
('imp-b9d222a8c523b8e4_v4_step_5', 'imp-b9d222a8c523b8e4', 5, 'cook', 'Trộn dưa leo với tỏi ớt và nước sốt', 'Cho tỏi băm, ớt hiểm thái lát và tiêu Tứ Xuyên giã dập (nếu dùng) vào tô dưa leo đã ráo nước. Rưới toàn bộ chén nước sốt lên trên, dùng đũa hoặc tay đeo găng trộn nhẹ nhàng từ dưới lên trong 1 phút cho từng miếng dưa áo đều gia vị.', NULL, NULL),
('imp-b9d222a8c523b8e4_v4_step_6', 'imp-b9d222a8c523b8e4', 6, 'finish', 'Ướp lạnh ngắn, rắc mè rang và thưởng thức', 'Đậy kín tô dưa rồi ướp trong ngăn mát tủ lạnh khoảng 10–15 phút cho dưa ngấm sốt và giòn mát. Gắp dưa ra đĩa, rưới thêm phần nước sốt dưới đáy tô, rắc hạt mè trắng rang và ngò rí thái khúc lên trên rồi dùng ngay.', 'Không nên trộn sốt trước quá lâu vì muối và giấm sẽ tiếp tục làm dưa ra nước khiến món ăn bị nhũn và loãng vị.', NULL),
('imp-51f6c12eefee914d_v4_step_1', 'imp-51f6c12eefee914d', 1, 'prep', 'Sơ chế bắp cải, nấm kim châm và cắt đậu phụ', 'Tách rời lá bắp cải trắng, cắt miếng vuông vừa ăn, rửa sạch rồi để ráo hoàn toàn. Nấm kim châm cắt bỏ phần gốc rễ, tách thành từng cụm nhỏ, rửa nhẹ tay và để ráo. Đậu phụ trắng thấm khô bề mặt, cắt thành miếng vuông dày khoảng 3–4 cm. Tỏi băm nhỏ, hành lá cắt khúc 2–3 cm.', 'Thấm thật khô miếng đậu phụ trước khi chiên để không bị bắn dầu và giúp lớp vỏ ngoài nhanh vàng giòn.', NULL),
('imp-51f6c12eefee914d_v4_step_2', 'imp-51f6c12eefee914d', 2, 'cook', 'Chiên vàng các mặt đậu phụ', 'Đun nóng 40 ml dầu ăn trong chảo chống dính trên lửa vừa. Nhẹ nhàng xếp từng miếng đậu phụ vào chảo, chiên mỗi mặt khoảng 2–3 phút đến khi vàng giòn đều các mặt thì gắp ra đĩa lót giấy thấm dầu, chắt bớt phần dầu dư trong chảo chỉ chừa lại khoảng 1 muỗng canh.', 'Chiên vàng mặt đậu trước khi kho tạo lớp vỏ dai nhẹ, giúp đậu giữ nguyên miếng không bị nát và hút nước kho tốt hơn.', 6),
('imp-51f6c12eefee914d_v4_step_3', 'imp-51f6c12eefee914d', 3, 'cook', 'Phi thơm tỏi và xào sơ nấm cùng bắp cải', 'Sử dụng phần dầu còn lại trong chảo trên lửa vừa, cho tỏi băm vào phi khoảng 30 giây cho dậy mùi thơm vàng. Thả nấm kim châm vào đảo nhanh 1 phút cho săn lại, tiếp tục cho bắp cải vào đảo đều thêm 2 phút trên lửa lớn để rau áo lớp dầu thơm.', NULL, 3),
('imp-51f6c12eefee914d_v4_step_4', 'imp-51f6c12eefee914d', 4, 'sauce', 'Nêm gia vị và om mềm bắp cải', 'Cho 25 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml dầu hào chay, 5 g đường cát trắng, 3 g muối ăn, 4 g hạt nêm chay và 150 ml nước lọc vào chảo. Đảo đều cho gia vị hòa tan, đậy nắp và hạ lửa nhỏ đun khoảng 6–8 phút cho bắp cải chín mềm và tiết nước ngọt.', 'Không nên đổ quá nhiều nước ngay từ đầu vì bắp cải và nấm kim châm sẽ tiết thêm nước trong quá trình đun.', 7),
('imp-51f6c12eefee914d_v4_step_5', 'imp-51f6c12eefee914d', 5, 'cook', 'Kho đậu phụ thấm đẫm nước sốt', 'Xếp phần đậu phụ đã chiên vàng vào chảo bắp cải, dùng vá nhẹ nhàng đảo đều để đậu ngập trong phần nước kho. Tiếp tục kho liu riu thêm 4–5 phút cho đậu phụ phồng mềm và thấm sâu hương vị nước tương.', NULL, 5),
('imp-51f6c12eefee914d_v4_step_6', 'imp-51f6c12eefee914d', 6, 'finish', 'Hoàn thiện với tiêu đen, dầu mè và hành lá', 'Nêm nếm lại nước kho cho vừa khẩu vị, rưới 5 ml dầu mè thơm, rắc 1 g tiêu đen xay và hành lá cắt khúc lên mặt chảo rồi tắt bếp. Dọn món ăn ra đĩa sâu lòng và dùng nóng với cơm trắng.', NULL, NULL),
('imp-6d3fa354c64cf8b1_v4_step_1', 'imp-6d3fa354c64cf8b1', 1, 'prep', 'Thấm thật khô cá, khía mình và phủ bột bắp mỏng', 'Làm sạch hoàn toàn vảy, mang và màng đen trong bụng cá rô phi. Dùng khăn giấy thấm thật khô cả bên ngoài lẫn trong bụng cá, dùng dao sắc khía 3 đường chéo song song trên mỗi bên thân cá. Nếu thích, xát nhẹ 1,5 g muối ăn và 1 g tiêu trắng xay vào mình cá rồi phủ một lớp 6 g bột bắp thật mỏng đều khắp hai mặt.', 'Thấm cá thật khô và chỉ phủ lớp bột bắp thật mỏng là bí quyết giúp da cá vàng giòn, không bị dính và tróc da khi áp chảo.', NULL),
('imp-6d3fa354c64cf8b1_v4_step_2', 'imp-6d3fa354c64cf8b1', 2, 'cook', 'Phi thơm gừng tươi chống dính chảo', 'Làm nóng chảo sâu lòng lớn trên lửa lớn đến khi mặt chảo hơi bốc khói, đổ 45 ml dầu ăn và thả 6 lát gừng tươi vào rồi hạ xuống lửa vừa. Phi gừng khoảng 1 phút cho dậy mùi thơm và các lát gừng chuyển vàng nhẹ thì gắp gừng ra chén để riêng.', 'Chà nhẹ mặt chảo bằng gừng và dầu nóng giúp tạo lớp chống dính tự nhiên, rất hiệu quả khi chiên cá nguyên con.', NULL),
('imp-6d3fa354c64cf8b1_v4_step_3', 'imp-6d3fa354c64cf8b1', 3, 'cook', 'Áp chảo mặt thứ nhất của cá không đảo lật sớm', 'Nhẹ nhàng đặt con cá vào chảo dầu nóng trên lửa vừa. Giữ nguyên vị trí cá, tuyệt đối không đẩy hay lật cá trong 5 phút đầu tiên; chỉ thỉnh thoảng nghiêng nhẹ chảo cho dầu láng đều quanh thân cá để mặt dưới chín vàng giòn.', 'Nếu xê dịch cá khi da chưa chín giòn, lớp da rất dễ bám chặt vào đáy chảo và bị rách.', 5),
('imp-6d3fa354c64cf8b1_v4_step_4', 'imp-6d3fa354c64cf8b1', 4, 'cook', 'Lật mặt và áp chảo vàng đều mặt còn lại', 'Sau 5 phút, lắc nhẹ chảo để kiểm tra cá đã tự róc khỏi đáy. Dùng hai xẻng rộng bản nhẹ nhàng lật cá sang mặt còn lại và tiếp tục áp chảo trên lửa vừa thêm 5 phút nữa đến khi hai mặt da cá vàng đều đẹp mắt.', NULL, 5),
('imp-6d3fa354c64cf8b1_v4_step_5', 'imp-6d3fa354c64cf8b1', 5, 'sauce', 'Rưới rượu Thiệu Hưng, giấm đen và nước tương kho cá', 'Cho gừng đã phi trở lại chảo cùng hành lá cắt khúc (thêm tỏi thái lát và ớt hiểm đỏ nếu dùng). Rưới đều 120 ml rượu Thiệu Hưng, 35 ml giấm đen Trấn Giang, 15 ml xì dầu đặc, 15 ml xì dầu nhạt và 25 g đường cát trắng quanh mình cá, giữ lửa vừa cho hỗn hợp sôi bùng lên rồi hạ lửa vừa-nhỏ.', NULL, NULL),
('imp-6d3fa354c64cf8b1_v4_step_6', 'imp-6d3fa354c64cf8b1', 6, 'finish', 'Om sánh sốt, rưới đều hai mặt và dọn nóng', 'Liên tục dùng muôi múc nước sốt rưới đều lên thân cá, kho mỗi mặt khoảng 4–5 phút đến khi nước sốt cạn sánh lại gần như siro và thịt cá ở phần dày nhất tách róc dễ dàng khỏi xương. Nhẹ nhàng gắp cá ra đĩa lớn, rưới toàn bộ phần sốt nâu đỏ óng ánh lên trên và dùng nóng với cơm trắng.', 'Tránh lật trở cá quá nhiều lần khi kho để giữ nguyên hình dáng đẹp mắt; thay vào đó hãy múc nước sốt rưới liên tục lên thân cá.', 9),
('imp-03577e7fa7667ab8_v4_step_1', 'imp-03577e7fa7667ab8', 1, 'prep', 'Sơ chế đậu phụ, nấm đùi gà, cà rốt và đánh tan trứng', 'Cắt đậu phụ trắng thành miếng vuông hoặc thanh mảnh cỡ 1,5 cm; thái sợi mỏng nấm đùi gà và cà rốt. Gừng tươi thái sợi chỉ, tỏi băm nhỏ, ớt hiểm đỏ thái lát và hành lá thái nhỏ. Đập 2 quả trứng gà vào chén, đánh tan đều. Hòa tan 20 g bột bắp với 60 ml nước lọc lạnh để sẵn.', NULL, NULL),
('imp-03577e7fa7667ab8_v4_step_2', 'imp-03577e7fa7667ab8', 2, 'sauce', 'Pha chén gia vị giấm đen và tiêu trắng', 'Trong một chén nhỏ, trộn đều 45 ml giấm đen Trấn Giang, 15 ml xì dầu, 5 g đường cát trắng, 4 g muối ăn và 3 g tiêu trắng xay; khuấy kỹ cho đường và muối tan hoàn toàn, để riêng cho bước hoàn thiện.', 'Chuẩn bị sẵn hỗn hợp gia vị và chỉ cho giấm vào lúc tắt bếp giúp giữ nguyên vị chua thanh và mùi thơm đặc trưng của giấm đen.', NULL),
('imp-03577e7fa7667ab8_v4_step_3', 'imp-03577e7fa7667ab8', 3, 'cook', 'Nấu sôi nước dùng gà với gừng, tỏi, nấm và cà rốt', 'Đổ 1,2 lít nước dùng gà vào nồi lớn, đun sôi trên lửa lớn rồi thả gừng sợi và tỏi băm vào nấu 2 phút cho thơm. Tiếp tục cho cà rốt và nấm đùi gà thái sợi vào, hạ lửa vừa nấu thêm 5 phút cho rau nấm chín mềm và tiết vị ngọt.', NULL, 7),
('imp-03577e7fa7667ab8_v4_step_4', 'imp-03577e7fa7667ab8', 4, 'cook', 'Thả đậu phụ và tạo độ sánh mượt cho súp', 'Nhẹ nhàng thả đậu phụ trắng vào nồi súp, nấu thêm 3 phút trên lửa vừa và tránh khuấy mạnh làm vỡ đậu. Khuấy đều lại chén bột bắp rồi rót từ từ từng chút vào nồi, vừa rót vừa khuấy nhẹ theo vòng tròn đến khi nước súp sánh mượt vừa ý.', 'Khuấy đều lại chén bột bắp ngay trước khi rót vào nồi để tinh bột không bị lắng cặn làm súp bị vón.', 3),
('imp-03577e7fa7667ab8_v4_step_5', 'imp-03577e7fa7667ab8', 5, 'cook', 'Kéo vân trứng gà tơ mềm trong nước sôi mạnh', 'Tăng lên lửa lớn cho nồi súp sôi bùng trở lại. Đưa chén trứng gà đánh tan lên cao, rót thành dòng thật mỏng vào nồi trong khi tay còn lại khuấy nhẹ theo một chiều để tạo thành những dải vân trứng tơ mỏng đẹp mắt.', 'Nước súp phải đang sôi mạnh mới giúp trứng định hình ngay thành từng sợi mảnh thay vì bị đục nước hay vón cục lớn.', NULL),
('imp-03577e7fa7667ab8_v4_step_6', 'imp-03577e7fa7667ab8', 6, 'finish', 'Tắt bếp, nêm giấm đen và hoàn thiện tô canh', 'Tắt bếp ngay sau khi kéo vân trứng, đổ chén hỗn hợp giấm đen gia vị vào khuấy nhẹ cho hòa quyện. Thêm 5 ml dầu mè thơm và ớt hiểm đỏ thái lát, nếm lại để cân bằng vị chua cay mặn ngọt, múc ra tô lớn rồi rắc hành lá lên trên để dùng nóng.', NULL, NULL),
('imp-62ebe8dd18b15b5e_v4_step_1', 'imp-62ebe8dd18b15b5e', 1, 'prep', 'Làm sạch, khía hoa mực và sơ chế gừng hành', 'Rút bỏ phần đầu, túi mực, mắt, răng và lột sạch lớp màng tím ngoài ống mực ống tươi rồi rửa sạch. Mở phẳng thân mực, dùng dao nghiêng lưỡi khía ca-rô mặt trong không đứt da rồi cắt miếng chữ nhật 3x4 cm; phần râu cắt khúc vừa ăn. Gừng chia 10 g thái lát, 20 g thái sợi; hành lá cắt khúc tách trắng và xanh; tỏi băm nhỏ; cà rốt thái sợi nếu dùng.', 'Lột sạch lớp màng tím giúp mực sau khi xào trắng đẹp, giòn ngọt và hoàn toàn không bị tanh.', NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-62ebe8dd18b15b5e_v4_step_2', 'imp-62ebe8dd18b15b5e', 2, 'cook', 'Chần sơ mực với nước gừng sôi để giữ độ giòn', 'Đun sôi một nồi nước nhỏ, thả 10 g gừng thái lát vào trước rồi trút toàn bộ mực vào chần nhanh đúng 15–20 giây đến khi từng miếng mực vừa cuộn cong lại. Vớt ngay mực ra ngâm nhanh vào nước lạnh hoặc để ráo hoàn toàn trên rổ.', 'Chỉ chần mực thật nhanh để mực cuộn hoa và rút bớt nước, tránh chần lâu khiến mực bị ra nước và dai khi xào tiếp.', 1),
('imp-62ebe8dd18b15b5e_v4_step_3', 'imp-62ebe8dd18b15b5e', 3, 'sauce', 'Pha sẵn chén nước sốt dầu hào bột bắp', 'Trộn đều 22 ml rượu Thiệu Hưng, 22 ml xì dầu nhạt, 22 ml dầu hào, 5 ml xì dầu đặc, 6 g đường cát trắng, 2,3 g tiêu đen xay, 5 g bột bắp và 25 ml nước lọc (thêm 4 g hạt nêm và 1,5 g muối ăn nếu muốn đậm vị). Khuấy kỹ đến khi đường và bột bắp tan hoàn toàn.', NULL, NULL),
('imp-62ebe8dd18b15b5e_v4_step_4', 'imp-62ebe8dd18b15b5e', 4, 'cook', 'Phi thơm gừng sợi, tỏi và xào nhanh rau củ', 'Đặt chảo sâu lòng lên bếp lửa lớn nhất, đổ 30 ml dầu ăn vào đun đến khi dầu nóng già hơi bốc khói nhẹ. Thả 20 g gừng thái sợi, tỏi băm và phần đầu hành trắng vào phi thơm khoảng 20 giây, tiếp tục cho cà rốt thái sợi (nếu dùng) vào đảo nhanh 1 phút cho vừa chín giòn.', NULL, 1),
('imp-62ebe8dd18b15b5e_v4_step_5', 'imp-62ebe8dd18b15b5e', 5, 'cook', 'Xào nhanh mực trên lửa lớn với nước sốt', 'Trút mực đã ráo nước vào chảo, đảo đều tay trên lửa lớn nhất khoảng 45–60 giây cho đến khi thịt mực săn trắng hoàn toàn và chín đều. Khuấy đều lại chén sốt rồi rưới thẳng vào chảo, đảo liên tục trong 20 giây cho đến khi sốt sánh bóng bám đều lên từng miếng mực.', 'Luôn giữ lửa lớn và khuấy lại chén sốt ngay trước khi rưới để bột bắp không bị lắng cặn dưới đáy chén.', 1),
('imp-62ebe8dd18b15b5e_v4_step_6', 'imp-62ebe8dd18b15b5e', 6, 'finish', 'Thêm phần xanh hành lá và dọn nóng', 'Thả phần lá xanh hành lá vào chảo, đảo nhanh thêm 10 giây cho hành vừa chín tái giữ màu xanh mướt rồi tắt bếp ngay. Trút mực xào gừng hành ra đĩa và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-d283a9225d6ece09_v4_step_1', 'imp-d283a9225d6ece09', 1, 'prep', 'Ngâm giòn hành tây thái mỏng và chuẩn bị cơm ấm', 'Xới 360 g cơm gạo Nhật nấu chín ra đĩa rộng khoảng 5 phút cho thoát bớt hơi nóng, giữ cơm ở trạng thái hơi ấm dịu. Thái 1/2 củ hành tây thành lát ngang mỏng 2 mm, ngâm ngay vào bát nước lạnh 15 phút cho hết vị hăng rồi vớt ra vắt thật kiệt nước.', 'Cơm còn quá nóng sẽ làm cá hồi sống bị tái chín mất độ béo mượt; để cơm hơi ấm và lót lớp hành tây ở giữa là bí quyết chuẩn Nhật.', 15),
('imp-d283a9225d6ece09_v4_step_2', 'imp-d283a9225d6ece09', 2, 'prep', 'Thái lát phi lê cá hồi tươi chuẩn sashimi', 'Thấm thật khô 280 g phi lê cá hồi tươi bằng khăn giấy, kiểm tra kỹ và rút sạch xương dăm nếu có. Dùng dao sắc kéo dứt khoát một đường cắt cá thành những lát sashimi dày khoảng 5–7 mm để mặt cắt láng mịn không bị nát thớ.', 'Nên chọn cá hồi tươi đạt chuẩn ăn sống và dùng dao thật sắc kéo một đường dài dứt khoát để không làm dập thớ thịt cá.', NULL),
('imp-d283a9225d6ece09_v4_step_3', 'imp-d283a9225d6ece09', 3, 'sauce', 'Pha nước sốt Zuke và ướp lạnh cá hồi', 'Đun sôi nhanh 30 ml rượu ngọt Mirin trên lửa nhỏ khoảng 30 giây rồi để nguội hẳn. Trộn đều phần Mirin đã nguội với 45 ml nước tương Nhật, 10 ml dầu mè rang và 6 g gừng tươi mài nhuyễn trong tô thủy tinh. Xếp cá hồi vào đảo nhẹ cho phủ đều sốt, bọc kín màng thực phẩm và ướp trong ngăn mát 25–30 phút.', 'Ướp cá đủ thời gian trong ngăn mát giúp lát cá săn nhẹ và thấm đều vị xì dầu dầu mè mà vẫn giữ trọn độ tươi béo.', 25),
('imp-d283a9225d6ece09_v4_step_4', 'imp-d283a9225d6ece09', 4, 'prep', 'Chuẩn bị hành lá và rong biển Nori rắc mặt', 'Trong lúc chờ ướp cá, thái nhỏ 1/2 bó hành lá tươi và dùng kéo cắt 3 g rong biển khô Nori thành sợi mảnh khoảng 3 mm để riêng ra đĩa sạch.', NULL, NULL),
('imp-d283a9225d6ece09_v4_step_5', 'imp-d283a9225d6ece09', 5, 'finish', 'Xếp lớp hành tây, cá hồi lên cơm ấm', 'Chia đều 360 g cơm gạo Nhật hơi ấm vào hai tô donburi, trải kín lớp hành tây đã vắt thật ráo lên mặt cơm. Lần lượt xếp các lát cá hồi đã ướp tương phủ chồng nhẹ lên nhau thành hình cánh hoa đẹp mắt, rưới thêm 1–2 muỗng nước sốt ướp còn lại tùy khẩu vị.', NULL, NULL),
('imp-d283a9225d6ece09_v4_step_6', 'imp-d283a9225d6ece09', 6, 'finish', 'Rắc hành lá, mè rang và thưởng thức ngay', 'Rắc rong biển khô Nori cắt sợi, hành lá thái nhỏ và hạt mè trắng rang lên bề mặt tô cá hồi. Dọn thưởng thức ngay khi cá còn mát lạnh và cơm vẫn ấm dẻo.', NULL, NULL),
('imp-7ed24282981e96f6_v4_step_1', 'imp-7ed24282981e96f6', 1, 'prep', 'Bào sợi bắp cải ngâm giòn và sơ chế nguyên liệu', 'Cắt bỏ phần lõi cứng của 1/2 bắp cải xanh, dùng dao sắc hoặc bàn bào bào thành sợi thật mảnh rồi ngâm nước đá lạnh 5 phút cho giòn, sau đó vẩy thật ráo nước. Cắt 340 g thịt ba chỉ thái mỏng thành miếng vừa ăn và chia làm 2 mẻ; thái lát mỏng 1 bó hành lá tươi và mài nhuyễn 25 g gừng tươi lấy cả nước.', 'Quay hoặc vẩy thật ráo nước bắp cải sợi sẽ giúp đĩa thịt sốt gừng không bị loãng nước khi bày chung.', 5),
('imp-7ed24282981e96f6_v4_step_2', 'imp-7ed24282981e96f6', 2, 'sauce', 'Pha sẵn nước sốt gừng Shogayaki', 'Trộn đều 45 ml nước tương Nhật, 45 ml rượu Sake nấu ăn, 45 ml rượu ngọt Mirin và 10 g đường cát trắng trong bát đến khi đường tan hết. Chia hỗn hợp sốt làm 2 phần đều nhau tương ứng với 2 mẻ chiên thịt.', NULL, NULL),
('imp-7ed24282981e96f6_v4_step_3', 'imp-7ed24282981e96f6', 3, 'cook', 'Áp chảo mẻ thịt ba chỉ thứ nhất với lửa vừa cao', 'Làm nóng chảo rộng trên lửa vừa cao, phết 5 ml dầu ăn thực vật rồi xếp phẳng mẻ thịt ba chỉ thứ nhất thành một lớp không chồng chéo. Áp chảo khoảng 2 phút cho thịt xém vàng nhẹ các mép và tiết bớt mỡ thơm thì trở mặt.', 'Chia thịt chiên thành 2 mẻ vừa vặn mặt chảo giúp thịt áp chảo xém thơm thay vì bị ra nước và hấp mềm.', 2),
('imp-7ed24282981e96f6_v4_step_4', 'imp-7ed24282981e96f6', 4, 'cook', 'Áo sốt gừng và hành lá cho mẻ thịt thứ nhất', 'Đổ 1/2 bát nước sốt đã pha vào chảo cùng một nửa lượng gừng tươi mài nhuyễn và hành lá thái mỏng. Đảo nhanh tay trên lửa vừa khoảng 2 phút đến khi thịt heo chín kỹ hoàn toàn, nước sốt sôi sủi bọt hơi sánh lại bám bóng đều từng lát thịt thì gắp ra đĩa đã lót bắp cải sợi.', 'Cho gừng tươi mài cả nước vào cùng lúc với sốt giúp hương gừng quyện thơm nồng mà không bị cháy đắng.', 2),
('imp-7ed24282981e96f6_v4_step_5', 'imp-7ed24282981e96f6', 5, 'cook', 'Áp chảo và hoàn thiện mẻ thịt ba chỉ thứ hai', 'Lau nhẹ chảo bằng khăn giấy, phết 5 ml dầu ăn thực vật còn lại và lặp lại quy trình áp chảo với mẻ thịt ba chỉ thứ hai cùng phần nước sốt, gừng tươi và hành lá còn lại trong 4 phút đến khi thịt chín đều và sốt keo sánh.', NULL, 4),
('imp-7ed24282981e96f6_v4_step_6', 'imp-7ed24282981e96f6', 6, 'finish', 'Trình bày đĩa Shogayaki nóng hổi và dùng kèm cơm', 'Xếp phần thịt ba chỉ còn lại lên đĩa bên cạnh bắp cải xanh bào sợi, rưới toàn bộ nước sốt gừng sánh thơm trong chảo lên trên mặt thịt và thưởng thức ngay cùng cơm trắng nóng.', NULL, NULL),
('imp-c6e706b483805e44_v4_step_1', 'imp-c6e706b483805e44', 1, 'prep', 'Sơ chế thịt ba chỉ, gừng và hành lá', 'Cắt 750 g thịt ba chỉ heo thành các dải lớn vừa chiều rộng lòng nồi để thịt giữ phom trong quá trình hầm lâu. Thái lát mỏng 50 g gừng tươi và chia làm hai phần bằng nhau; tách 2 bó hành lá riêng phần lá xanh cắt khúc 5 cm và phần thân trắng thái sợi mảnh ngâm nước đá trang trí.', NULL, NULL),
('imp-c6e706b483805e44_v4_step_2', 'imp-c6e706b483805e44', 2, 'cook', 'Áp chảo xém vàng rút bớt mỡ thừa của thịt', 'Làm nóng nồi gang hoặc chảo đáy dày trên lửa vừa cao với 10 ml dầu ăn trung tính. Đặt từng dải thịt ba chỉ mặt mỡ xuống trước, áp chảo vàng đều tất cả các mặt khoảng 8–10 phút để khóa hương thịt và rút bớt phần mỡ béo dư thừa.', NULL, 10),
('imp-c6e706b483805e44_v4_step_3', 'imp-c6e706b483805e44', 3, 'cook', 'Ninh mềm thịt ba chỉ lần một trong nước gừng hành', 'Xếp thịt đã áp chảo thành một lớp vào nồi lớn, đổ 2000 ml nước lọc ngập mặt thịt cùng 75 ml rượu Sake nấu ăn, một nửa lượng gừng thái lát và phần lá xanh hành lá. Đun sôi trên lửa vừa, hớt sạch bọt và váng mỡ, phủ một tờ giấy nến khoét lỗ sát mặt thịt rồi hạ lửa nhỏ nhất ninh liu riu không đậy vung khoảng 90 phút đến khi thịt mềm rục.', 'Ninh mở nắp ở lửa nhỏ liu riu giúp mùi hôi thịt bay hơi hết và thịt mềm tơi từng thớ mà không bị nát vụn.', 90),
('imp-c6e706b483805e44_v4_step_4', 'imp-c6e706b483805e44', 4, 'cook', 'Luộc trứng gà lòng đào và chần đậu xanh ăn kèm', 'Trong lúc ninh thịt, đun sôi một nồi nước khác, nhẹ nhàng thả 5 quả trứng gà lạnh vào luộc đúng 7 phút rồi vớt ngay sang tô nước đá 10 phút và bóc sạch vỏ. Dùng lại nồi nước sôi chần 80 g đậu cô ve trong 2 phút cho chín giòn xanh mướt rồi vớt ra đĩa.', NULL, 7),
('imp-c6e706b483805e44_v4_step_5', 'imp-c6e706b483805e44', 5, 'cook', 'Cắt khối vuông và kho chậm trong nước dùng Dashi', 'Vớt thịt ba chỉ ra thớt, bỏ phần nước ninh cùng xác hành gừng cũ, nhẹ tay cắt thịt thành các khối vuông cạnh 5 cm rồi xếp gọn vào nồi vừa khít. Đổ 750 ml nước dùng Dashi, 75 ml rượu Sake nấu ăn còn lại, 75 ml rượu ngọt Mirin, 55 g đường cát trắng, phần gừng lát còn lại và 1 quả ớt khô nguyên quả vào, đậy nắp giấy kho lửa nhỏ liu riu trong 30 phút.', 'Chưa cho nước tương ngay từ đầu giúp đường và mirin thấm vào làm mềm thịt trước, tránh thịt bị mặn gắt bên ngoài.', 30),
('imp-c6e706b483805e44_v4_step_6', 'imp-c6e706b483805e44', 6, 'cook', 'Nêm nước tương Nhật và om cùng trứng lòng đào', 'Sau 30 phút kho, rót 75 ml nước tương Nhật vào nồi cùng 5 quả trứng gà đã bóc vỏ. Tiếp tục đậy nắp giấy om liu riu lửa nhỏ thêm 30 phút nữa, thỉnh thoảng lắc nhẹ nồi hoặc múc nước kho rưới lên trứng và thịt đến khi nước sốt sánh bóng đậm đà và thịt mềm tan khi xiên đũa qua.', 'Tắt bếp để thịt và trứng nguội tự nhiên trong nồi nước kho vài giờ rồi hâm lại sẽ giúp món Kakuni thấm vị đậm sâu hơn nhiều.', 30),
('imp-c6e706b483805e44_v4_step_7', 'imp-c6e706b483805e44', 7, 'finish', 'Trình bày bát thịt hầm Kakuni và thưởng thức', 'Gắp các khối thịt ba chỉ hầm, trứng lòng đào cắt đôi và đậu cô ve chần ra bát sâu lòng, chan nước kho bóng mượt lên trên. Vẩy ráo phần đầu hành trắng thái sợi ngâm đá đặt lên mặt thịt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-324e0ea2e2f068bf_v4_step_1', 'imp-324e0ea2e2f068bf', 1, 'prep', 'Ngâm tảo bẹ Kombu lấy nền nước dùng Dashi', 'Dùng khăn ẩm lau nhẹ lớp phấn trắng tự nhiên trên 8 g tảo bẹ Kombu khô (không rửa trôi vị ngọt), cho vào nồi cùng 750 ml nước lọc lạnh ngâm khoảng 20 phút để tảo tiết hết vị thanh ngọt.', NULL, 20),
('imp-324e0ea2e2f068bf_v4_step_2', 'imp-324e0ea2e2f068bf', 2, 'prep', 'Ngâm nở rong biển Wakame và thái đậu phụ, nấm', 'Ngâm 5 g rong biển Wakame khô trong bát nước mát khoảng 5 phút cho nở mềm hoàn toàn rồi vớt ra vắt nhẹ. Thái lát mỏng 120 g nấm đùi gà tươi; nhẹ tay cắt 200 g đậu phụ non thành khối vuông 2 cm và thái khoanh mỏng 1/2 bó hành lá tươi.', NULL, 5),
('imp-324e0ea2e2f068bf_v4_step_3', 'imp-324e0ea2e2f068bf', 3, 'cook', 'Đun nước dùng Kombu và nấu chín mềm nấm', 'Đặt nồi nước ngâm tảo bẹ lên bếp lửa vừa, khi đáy nồi vừa xuất hiện bọt lăn tăn chuẩn bị sôi thì lập tức vớt bỏ lá tảo bẹ Kombu ra ngoài. Thả toàn bộ nấm thái lát vào nồi nấu khoảng 3–4 phút trên lửa vừa cho nấm chín mềm và ra vị ngọt.', 'Vớt tảo bẹ Kombu ngay trước lúc nước sôi bùng giúp nước canh trong veo, thơm thanh mà không bị đắng chát hay nhớt.', 4),
('imp-324e0ea2e2f068bf_v4_step_4', 'imp-324e0ea2e2f068bf', 4, 'cook', 'Thả đậu phụ non và rong biển Wakame làm nóng', 'Nhẹ nhàng trượt 200 g đậu phụ non cắt khối cùng rong biển Wakame đã vắt ráo vào nồi canh. Đun thêm 1–2 phút trên lửa nhỏ cho đậu phụ nóng đều từ trong ra ngoài, chỉ lắc nhẹ nồi chứ không dùng muôi khuấy mạnh làm vỡ đậu, sau đó tắt bếp hoàn toàn.', 'Chỉ đun lửa nhỏ làm nóng đậu phụ trong 1–2 phút giúp miếng đậu giữ nguyên khối vuông đẹp mắt và không bị rỗ xốp.', 2),
('imp-324e0ea2e2f068bf_v4_step_5', 'imp-324e0ea2e2f068bf', 5, 'sauce', 'Hòa tan tương Miso khi nồi đã tắt bếp', 'Múc một muôi nước canh nóng ra bát nhỏ, cho 60 g tương Miso Nhật vào dùng đũa hoặc phới lồng khuấy tan mịn hoàn toàn rồi từ từ rót trở lại vào nồi canh, khuấy nhẹ cho đồng nhất và tuyệt đối không bật bếp đun sôi lại.', 'Tắt bếp rồi mới hòa tan tương Miso giúp giữ trọn vẹn hương thơm đậu nành lên men tinh tế và bảo toàn lợi khuẩn tự nhiên.', NULL),
('imp-324e0ea2e2f068bf_v4_step_6', 'imp-324e0ea2e2f068bf', 6, 'finish', 'Múc canh ra chén, rắc hành lá và dùng nóng', 'Múc canh Miso chia đều vào 3 chén nhỏ sao cho mỗi chén có đủ đậu phụ non, nấm và rong biển, rắc hành lá thái khoanh lên trên và thưởng thức ngay khi canh còn ấm nóng.', NULL, NULL),
('imp-5507103398040565_v4_step_1', 'imp-5507103398040565', 1, 'sauce', 'Pha nước sốt Yakisoba chua ngọt đậm đà', 'Trộn đều 50 ml sốt Worcestershire Nhật, 20 ml dầu hào, 20 ml tương cà, 10 ml nước tương Nhật và 8 g đường cát trắng trong bát nhỏ đến khi đường tan hoàn toàn. Nếm thử độ chua ngọt để điều chỉnh nếu cần.', NULL, NULL),
('imp-5507103398040565_v4_step_2', 'imp-5507103398040565', 2, 'prep', 'Sơ chế rau củ, thịt ba chỉ và luộc tơi sợi mì', 'Thái lát mỏng 180 g thịt ba chỉ heo; cắt miếng vuông 2,5 cm phần 0,25 bắp cải xanh; thái sợi 1 củ cà rốt và 0,5 quả ớt chuông xanh; thái mỏng 0,5 củ hành tây và 50 g nấm hương tươi; rửa ráo 100 g giá đỗ và cắt khúc 1 bó hành lá tươi. Luộc 240 g mì Yakisoba khô trong nồi nước sôi 2–3 phút cho sợi vừa chín tới còn độ dai nhẹ rồi vớt ra xả nhanh nước mát và vẩy thật ráo.', 'Không luộc mì quá nhừ vì sợi mì sẽ còn đảo trên chảo nóng với nước sốt Yakisoba.', NULL),
('imp-5507103398040565_v4_step_3', 'imp-5507103398040565', 3, 'cook', 'Xào thịt ba chỉ vàng thơm với tiêu đen', 'Làm nóng chảo sâu lòng trên lửa vừa cao với 20 ml dầu ăn thực vật. Cho thịt ba chỉ heo vào xào, rắc 2 g tiêu đen xay và đảo đều khoảng 3–4 phút cho đến khi thịt chuyển vàng xém nhẹ, chín hoàn toàn và tiết mỡ thơm.', 'Xào thịt ba chỉ trước cho săn vàng giúp dầu quyện mùi thơm thịt và rau củ khi cho vào sau sẽ bóng ngon hơn.', 4),
('imp-5507103398040565_v4_step_4', 'imp-5507103398040565', 4, 'cook', 'Xào thơm hành tây, đầu hành lá và rau củ', 'Thả hành tây thái lát cùng phần đầu trắng hành lá vào chảo xào 2 phút đến khi hành trong thơm. Tiếp tục cho bắp cải xanh, cà rốt, nấm hương tươi và ớt chuông xanh vào đảo đều tay trên lửa lớn thêm 3 phút cho rau củ vừa chín mềm mà vẫn giữ độ giòn.', NULL, 5),
('imp-5507103398040565_v4_step_5', 'imp-5507103398040565', 5, 'cook', 'Thêm giá đỗ và xào quyện mì với sốt Yakisoba', 'Cho 100 g giá đỗ tươi vào đảo nhanh 1 phút, sau đó trút mì Yakisoba vào chảo cùng toàn bộ bát nước sốt Yakisoba đã pha. Dùng kẹp hoặc hai chiếc đũa đảo đều tay trên lửa lớn 2–3 phút để sốt phủ bóng và thấm quyện từng sợi mì rồi cho phần lá hành xanh vào đảo tắt bếp.', 'Cho giá đỗ và hành lá xanh vào giai đoạn cuối giúp giữ nguyên độ giòn ngọt và sắc xanh tươi bắt mắt.', 4),
('imp-5507103398040565_v4_step_6', 'imp-5507103398040565', 6, 'finish', 'Bày đĩa Yakisoba và rắc rong biển Nori', 'Gắp mì Yakisoba xào thịt rau củ chia ra ba đĩa nóng, rắc rong biển khô Nori vụn lên mặt mì và thưởng thức ngay khi còn nóng hổi.', NULL, NULL),
('imp-710fd476f2dddd56_v4_step_1', 'imp-710fd476f2dddd56', 1, 'prep', 'Sơ chế thịt gà, hành tây, đậu xanh và làm ráo cơm', 'Trải 300 g cơm gạo Nhật nấu chín ra đĩa rộng cho thoát hơi ẩm. Thái hạt lựu nhỏ 0,5 củ hành tây và 120 g thịt đùi gà lọc xương (cạnh 1,5 cm); chần nhanh 30 g đậu xanh cắt nhỏ trong nước sôi 2 phút rồi vớt ra để ráo.', 'Cơm nguội hoặc cơm mới nấu được quạt ráo hơi nước sẽ giúp từng hạt cơm tơi bóng, không bị vón cục hay nhão bết khi trộn sốt cà chua.', 2),
('imp-710fd476f2dddd56_v4_step_2', 'imp-710fd476f2dddd56', 2, 'cook', 'Xào thơm hành tây và thịt đùi gà với bơ lạt', 'Đun chảy 15 g bơ lạt trong chảo rộng trên lửa vừa, cho hành tây hạt lựu vào xào khoảng 3 phút cho trong thơm. Tiếp tục thả thịt đùi gà vào xào cùng 1 g muối ăn và 1 g tiêu đen xay thêm 4–5 phút đến khi thịt gà săn chắc, chín trắng đều không còn sắc hồng.', NULL, 8),
('imp-710fd476f2dddd56_v4_step_3', 'imp-710fd476f2dddd56', 3, 'cook', 'Cô sánh tương cà và chiên cơm gà đỏ bóng', 'Hạ lửa vừa nhỏ, đổ 60 ml tương cà và 5 ml sốt Worcestershire vào chảo gà hành, đảo đều 2 phút cho nước sốt bay bớt hơi ẩm và dịu vị chua gắt. Trút 300 g cơm vào dùng sạn ép tán nhẹ cho tơi hạt rồi đảo cùng đậu xanh thêm 3 phút cho cơm thấm đều màu đỏ cam, chia ra hai phần bằng nhau.', 'Cô đặc nhẹ tương cà trước khi cho cơm vào giúp loại bỏ nước dư, giữ hạt cơm săn ráo và dậy mùi thơm bơ cà chua nồng nàn.', 5),
('imp-710fd476f2dddd56_v4_step_4', 'imp-710fd476f2dddd56', 4, 'prep', 'Đánh trứng và lọc qua rây cho vỏ trứng mịn lụa', 'Làm từng suất một: đập 2 quả trứng gà vào bát với 0,5 g muối ăn, dùng đũa đánh tan đều theo đường zíc zắc rồi lọc qua rây lưới mịn vào ca nhỏ để loại bỏ dây chằng lòng trắng. Lặp lại tương tự cho 2 quả trứng của suất thứ hai.', NULL, NULL),
('imp-710fd476f2dddd56_v4_step_5', 'imp-710fd476f2dddd56', 5, 'cook', 'Tráng lớp trứng nửa chín mềm mịn trên chảo chống dính', 'Đun chảy 10 g bơ lạt trong chảo chống dính nhỏ đường kính 20 cm trên lửa vừa, xoay tráng đều mặt chảo. Đổ bát trứng thứ nhất vào, vừa dùng đầu đũa khuấy nhanh theo vòng tròn ở giữa chảo vừa lắc nhẹ chảo khoảng 1 phút cho đến khi trứng tạo vân mịn, mặt trên vẫn còn hơi ướt thì tắt bếp và đặt đáy chảo lên khăn ẩm 5 giây.', 'Đặt chảo lên khăn ẩm giúp hạ nhiệt tức thì để lớp trứng không bị khô cháy trong lúc tạo hình bọc cơm.', 1),
('imp-710fd476f2dddd56_v4_step_6', 'imp-710fd476f2dddd56', 6, 'finish', 'Bọc cơm gà, tạo hình oval và rưới tương cà', 'Đặt một phần cơm gà sốt cà chua vào giữa mặt trứng theo chiều thuôn dài, nhẹ tay gấp hai mép trứng phủ ôm lấy cơm rồi kê sát đĩa vào thành chảo úp ngược lại cho mặt láng hướng lên trên. Dùng khăn giấy nắn nhẹ thành khối oval đẹp mắt, làm tương tự suất thứ hai, rưới 15 ml tương cà còn lại thành đường zíc zắc và dùng nóng.', NULL, NULL),
('imp-14c8ef999fe47b8f_v4_step_1', 'imp-14c8ef999fe47b8f', 1, 'prep', 'Đánh nhẹ hỗn hợp trứng sữa gia vị và lọc rây', 'Thái nhỏ mịn 0,5 bó hành lá tươi. Đập 4 quả trứng gà vào bát lớn, thêm 20 ml sữa tươi không đường, 10 ml nước tương Nhật, 10 ml rượu ngọt Mirin, 6 g đường cát trắng và 1 g muối ăn. Dùng đũa khuấy nhẹ tay theo đường zíc zắc để đường tan và trứng quyện đều mà không tạo bọt, lọc qua rây mịn rồi trộn hành lá vào.', 'Khuấy trứng bằng đũa theo đường zíc zắc thay vì đánh bông giúp cắt đứt dây lòng trắng mà không tạo bọt khí gây rỗ mặt cuộn trứng.', NULL),
('imp-14c8ef999fe47b8f_v4_step_2', 'imp-14c8ef999fe47b8f', 2, 'cook', 'Làm nóng chảo và tráng cuộn lớp trứng đầu tiên', 'Đặt chảo chữ nhật chuyên dụng (hoặc chảo chống dính nhỏ 18 cm) lên bếp lửa vừa nhỏ, dùng khăn giấy thấm dầu ăn trung tính thoa một lớp thật mỏng đều mặt chảo. Đổ 1/3 bát trứng vào tráng mỏng khắp chảo, đun khoảng 2 phút đến khi mặt trứng vừa se lại nhưng vẫn còn hơi ẩm ướt thì dùng đũa và xẻng cuộn tròn từ mép xa về sát mép gần rồi đẩy cuộn trứng về góc xa.', NULL, 2),
('imp-14c8ef999fe47b8f_v4_step_3', 'imp-14c8ef999fe47b8f', 3, 'cook', 'Tráng và cuộn nối tiếp lớp trứng thứ hai', 'Thấm thêm một lớp dầu ăn trung tính thật mỏng vào khoảng trống trên mặt chảo, đổ tiếp 1/3 hỗn hợp trứng thứ hai vào, dùng đũa khẽ nhấc cuộn trứng lên cho trứng mới chảy đều xuống dưới đáy cuộn. Chờ khoảng 2 phút cho mặt trứng se chín còn hơi ẩm rồi cuộn ngược chồng tiếp lên lớp cũ và đẩy về mép chảo.', 'Cuộn ngay khi mặt trên trứng vừa se nhưng còn độ ẩm dính nhẹ sẽ giúp các lớp kết nối liền mạch không bị tách rời khi cắt.', 2),
('imp-14c8ef999fe47b8f_v4_step_4', 'imp-14c8ef999fe47b8f', 4, 'cook', 'Hoàn tất lớp trứng thứ ba và ép vuông khối trứng', 'Thoa dầu ăn mỏng lên chảo một lần nữa, rót nốt 1/3 hỗn hợp trứng cuối cùng vào nâng nhẹ cuộn trứng cho chảy đều xuống dưới. Đun thêm 2 phút trên lửa vừa nhỏ cho chín đều, cuộn tròn lại rồi dùng xẻng ép nhẹ các cạnh sát thành chảo khoảng 20 giây để khối trứng định hình vuông vức vàng đều.', NULL, 2),
('imp-14c8ef999fe47b8f_v4_step_5', 'imp-14c8ef999fe47b8f', 5, 'finish', 'Để nghỉ định hình khối trứng cuộn', 'Tắt bếp, nhẹ nhàng gắp cuộn trứng ra thớt hoặc cuộn chặt trong mành tre sạch để nghỉ khoảng 4 phút cho khối trứng nguội bớt, săn chắc và giữ nguyên phom chữ nhật đẹp mắt.', 'Chờ trứng nghỉ vài phút cho se mặt trước khi cắt sẽ giúp khoanh trứng phẳng mịn, không bị chảy xô lệch giữa các lớp.', 4),
('imp-14c8ef999fe47b8f_v4_step_6', 'imp-14c8ef999fe47b8f', 6, 'finish', 'Cắt khoanh Tamagoyaki vừa ăn và trình bày', 'Dùng dao sắc cắt cuộn trứng thành 6–8 khoanh dày khoảng 2 cm lộ rõ từng vòng xoắn vàng ươm xen sắc xanh hành lá, xếp ra đĩa và thưởng thức.', NULL, NULL),
('imp-0841a517e823e3b6_v4_step_1', 'imp-0841a517e823e3b6', 1, 'sauce', 'Pha hỗn hợp sốt Teriyaki hương gừng tỏi', 'Trong bát chịu nhiệt, trộn đều 45 ml nước tương Nhật, 45 ml rượu ngọt Mirin, 45 ml rượu Sake nấu ăn, 18 g đường cát trắng cùng 15 g gừng tươi thái lát (hoặc mài nhuyễn) và 0,5 củ tỏi khô băm nhỏ. Khuấy đều hoặc quay ấm 30 giây cho đường tan hoàn toàn.', NULL, NULL),
('imp-0841a517e823e3b6_v4_step_2', 'imp-0841a517e823e3b6', 2, 'prep', 'Khía thịt đùi gà đều độ dày và ướp muối tiêu', 'Đặt 600 g thịt đùi gà lọc xương còn da lên thớt với mặt thịt hướng lên trên, dùng mũi dao khía nhẹ các đường song song ở phần thịt dày và ấn phẳng cho cả miếng gà có độ dày đồng đều. Châm vài lỗ nhỏ trên mặt da, thấm khô rồi rắc đều 1,5 g muối ăn và 1 g tiêu đen xay lên hai mặt.', 'Khía nhẹ phần thịt dày thay vì dùng búa đập giúp miếng gà chín đều từ trong ra ngoài mà vẫn giữ được thớ thịt mọng nước.', NULL),
('imp-0841a517e823e3b6_v4_step_3', 'imp-0841a517e823e3b6', 3, 'cook', 'Áp chảo mặt da gà vàng giòn', 'Làm nóng chảo rộng trên lửa vừa với 15 ml dầu ăn trung tính, đặt từng miếng đùi gà mặt da úp xuống đáy chảo. Dùng xẻng ấn nhẹ trong 10 giây đầu để mặt da phẳng sát chảo rồi chiên khoảng 5 phút không lật đến khi da gà vàng giòn rụm và chuyển sang màu nâu cánh gián đẹp mắt.', NULL, 5),
('imp-0841a517e823e3b6_v4_step_4', 'imp-0841a517e823e3b6', 4, 'cook', 'Lật mặt và hấp chín đều lõi thịt gà', 'Lật mặt thịt gà xuống dưới, hạ lửa xuống mức nhỏ và đậy kín vung chảo hấp tiếp 3–4 phút cho lõi thịt đùi gà chín trắng hoàn toàn, không còn nước đỏ khi xiên thử. Mở nắp, dùng khăn giấy thấm sạch lượng mỡ gà chảy ra dư thừa trong chảo.', 'Thấm bỏ phần mỡ tiết ra trước khi rưới sốt giúp sốt Teriyaki bám trực tiếp lên thịt và trong bóng đẹp mắt hơn.', 4),
('imp-0841a517e823e3b6_v4_step_5', 'imp-0841a517e823e3b6', 5, 'cook', 'Rưới sốt Teriyaki và rim cô bóng mặt gà', 'Bật lại lửa vừa, đổ toàn bộ bát sốt Teriyaki vào chảo, vớt bỏ xác lát gừng nếu muốn sốt mịn và liên tục nghiêng chảo múc sốt rưới đều lên hai mặt gà khoảng 3 phút cho đến khi cồn bay hơi, sốt sánh keo lại và phủ lớp men nâu bóng đẹp lên từng miếng gà.', 'Không cần pha thêm bột năng; đường và rượu ngọt Mirin trong sốt sẽ tự caramel hóa tạo độ sánh bóng mượt khi cô đặc.', 3),
('imp-0841a517e823e3b6_v4_step_6', 'imp-0841a517e823e3b6', 6, 'finish', 'Thái miếng vừa ăn, rưới sốt và thưởng thức nóng', 'Gắp gà ra thớt nghỉ 2 phút cho ổn định nước thịt rồi thái thành từng lát dày 1,5–2 cm. Xếp ra đĩa hoặc lên bát cơm nóng, rưới phần sốt Teriyaki sánh bóng còn lại trong chảo lên trên và dùng nóng ngay.', NULL, NULL),
('imp-6ae7feae7ec0d517_v4_step_1', 'imp-6ae7feae7ec0d517', 1, 'prep', 'Ngâm que tre và nấu cô đặc nước sốt Tare', 'Ngâm 9 que xiên tre ngập trong khay nước lạnh ít nhất 30 phút để que không cháy sém khi nướng. Cho 90 ml nước tương Nhật, 90 ml rượu ngọt Mirin, 45 ml rượu Sake nấu ăn, 45 ml nước lọc, 10 g đường nâu cùng phần lá xanh của 2 bó hành lá vào nồi nhỏ, đun sôi rồi hạ lửa nhỏ đun mở nắp khoảng 25 phút đến khi sốt còn 1/3 lượng ban đầu và hơi sánh bóng thì vớt bỏ lá hành, để nguội hẳn.', 'Tách riêng 1/3 lượng sốt tare nguội ra chén sạch để chấm hoặc quét sau khi nướng xong, tránh nhiễm chéo từ cọ đã quét thịt sống.', 25),
('imp-6ae7feae7ec0d517_v4_step_2', 'imp-6ae7feae7ec0d517', 2, 'prep', 'Thái gà, hành lá và xiên xen kẽ khít tay', 'Cắt 450 g thịt đùi gà lọc xương thành các miếng vuông cạnh 3 cm và cắt phần thân trắng hành lá thành các khúc dài 3 cm tương ứng. Xiên lần lượt thịt gà xen kẽ hành lá vào 9 que tre (mỗi xiên khoảng 3–4 miếng gà và 2–3 khúc hành), xếp các miếng sát khít nhau che kín phần que gỗ ở giữa.', 'Xiên thịt và hành thật khít nhau đồng thời bọc giấy bạc vào phần đuôi que tre sẽ ngăn que bị cháy gãy trong lò nướng.', NULL),
('imp-6ae7feae7ec0d517_v4_step_3', 'imp-6ae7feae7ec0d517', 3, 'cook', 'Làm nóng lò và nướng xiên gà lần đầu cho se mặt', 'Làm nóng trước lò nướng chế độ lửa trên ở mức cao (hoặc chuẩn bị bếp than hồng) trong 5 phút. Lót giấy bạc dưới khay, đặt vỉ lên trên, quét 10 ml dầu ăn trung tính chống dính rồi xếp các xiên gà lên vỉ, nướng 6 phút cho mặt thịt săn lại và bắt đầu chín tới.', NULL, 6),
('imp-6ae7feae7ec0d517_v4_step_4', 'imp-6ae7feae7ec0d517', 4, 'cook', 'Quét sốt Tare và nướng lật mặt cho xém cạnh', 'Lấy khay xiên ra khỏi lò, dùng cọ quét đều lớp sốt tare sánh lên cả hai mặt thịt gà và hành lá, cho lại vào lò nướng thêm 4 phút đến khi lớp sốt sủi bọt thơm lừng và các cạnh gà hơi xém nâu.', 'Canh sát ở những phút cuối sau khi quét sốt vì lượng đường trong sốt tare dễ bị cháy sém nhanh dưới thanh nhiệt lò.', 4),
('imp-6ae7feae7ec0d517_v4_step_5', 'imp-6ae7feae7ec0d517', 5, 'cook', 'Quét lớp sốt Tare thứ hai tạo màu bóng đẹp', 'Lật mặt đẹp của các xiên gà hướng lên trên, quét thêm một lớp sốt tare mỏng nữa rồi nướng thêm 2 phút cuối đến khi thịt gà chín hoàn toàn bên trong, mặt ngoài bóng mượt xém cạnh thơm nức.', NULL, 2),
('imp-6ae7feae7ec0d517_v4_step_6', 'imp-6ae7feae7ec0d517', 6, 'finish', 'Quét sốt sạch, rắc Shichimi và thưởng thức nóng', 'Gắp các xiên gà Yakitori ra đĩa, dùng cọ sạch quét thêm một lớp mỏng phần sốt tare đã chừa riêng, rắc chút bột ớt 7 vị Nhật Shichimi lên trên và dùng nóng ngay.', NULL, NULL),
('imp-7facaaeafc40dac2_v4_step_1', 'imp-7facaaeafc40dac2', 1, 'prep', 'Làm sạch xương dăm, vảy cá và xoa rượu Sake', 'Miết dọc thớ thịt 340 g phi lê cá hồi còn da để tìm và nhổ hết xương dăm bằng nhíp, cạo sạch phần vảy còn sót trên mặt da. Rưới đều 15 ml rượu Sake nấu ăn lên cả hai mặt cá, để nghỉ 5 phút rồi dùng khăn giấy thấm khô nhẹ.', NULL, 5),
('imp-7facaaeafc40dac2_v4_step_2', 'imp-7facaaeafc40dac2', 2, 'marinate', 'Ướp muối hạt lạnh giúp thịt cá săn ngọt', 'Đặt cá lên vỉ thoáng đặt trên khay, rắc đều 12 g muối hạt phủ khắp hai mặt miếng cá hồi. Đặt khay cá không đậy nắp vào ngăn mát tủ lạnh khoảng 45 phút để muối rút bớt độ ẩm thừa và giúp vị đậm thấm sâu vào thớ cá.', 'Ướp muối rồi để hở trong tủ lạnh giúp bề mặt cá khô ráo, khi nướng thịt cá săn chắc và da rất dễ giòn.', 45),
('imp-7facaaeafc40dac2_v4_step_3', 'imp-7facaaeafc40dac2', 3, 'prep', 'Rửa sạch muối thừa, thấm khô và mài củ cải trắng', 'Lấy cá ra khỏi tủ lạnh, xả nhanh dưới vòi nước lạnh để rửa trôi hoàn toàn lớp muối mặn bên ngoài rồi dùng khăn giấy thấm thật khô cả phần thịt lẫn mặt da. Gọt vỏ 80 g củ cải trắng, mài nhuyễn mịn và vắt nhẹ cho ráo bớt nước; cắt múi cau 1 quả chanh tươi và thái nhỏ 0,5 bó hành lá.', 'Rửa sạch muối thừa sau khi ướp giúp cá thấm vị mặn dịu hài hòa từ bên trong mà không bị mặn gắt trên bề mặt.', NULL),
('imp-7facaaeafc40dac2_v4_step_4', 'imp-7facaaeafc40dac2', 4, 'cook', 'Làm nóng lò nướng hoặc nồi chiên không dầu', 'Làm nóng trước lò nướng chế độ lửa trên ở 220°C trong 5 phút (kê khay cách thanh nhiệt khoảng 10 cm). Lót giấy bạc lên khay nướng, thoa đều 10 ml dầu ăn trung tính chống dính rồi xếp hai miếng cá hồi lên khay.', NULL, 5),
('imp-7facaaeafc40dac2_v4_step_5', 'imp-7facaaeafc40dac2', 5, 'cook', 'Nướng cá hồi xém vàng và giòn mặt da', 'Cho khay cá vào nướng ở 220°C khoảng 6–8 phút (xoay khay một lần giữa chừng nếu cần) đến khi phần da giòn phồng nhẹ, bề mặt thịt cá hơi xém vàng các cạnh và phần thịt bên trong chuyển màu hồng nhạt đục tách thớ nhẹ là vừa chín tới.', 'Nướng ở nhiệt cao trong thời gian ngắn giúp da cá hồi giòn rụm mà phần thịt bên trong vẫn giữ được độ béo ẩm tự nhiên.', 7),
('imp-7facaaeafc40dac2_v4_step_6', 'imp-7facaaeafc40dac2', 6, 'finish', 'Bày cá nướng cùng củ cải mài, chanh tươi và hành lá', 'Chuyển cá hồi nướng Shioyaki ra đĩa, đặt ụ củ cải trắng mài và múi chanh tươi bên cạnh, rắc thêm hành lá thái nhỏ. Vắt nước cốt chanh trực tiếp lên mặt cá và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-70379b3f30b48438_v4_step_1', 'imp-70379b3f30b48438', 1, 'prep', 'Thái mỏng và ướp muối làm giòn dưa leo', 'Rửa sạch 2 quả dưa leo tươi, cắt bỏ hai đầu, có thể bào vỏ sọc xen kẽ cho đẹp rồi thái thành những lát tròn thật mỏng khoảng 2 mm. Cho dưa leo vào tô, rắc 5 g muối ăn lên bóp nhẹ đều tay rồi để yên 10 phút cho dưa ra hết nước chát.', 'Ướp muối trước khi trộn giúp lát dưa leo giòn sần sật và không tiết thêm nước làm loãng sốt giấm về sau.', 10),
('imp-70379b3f30b48438_v4_step_2', 'imp-70379b3f30b48438', 2, 'cook', 'Sơ chế và luộc chín tới tôm tươi', 'Rửa sạch 220 g tôm tươi, bóc bỏ vỏ, rút sạch chỉ đen trên sống lưng. Đun sôi nồi nước nhỏ trên lửa vừa, thả tôm vào luộc khoảng 3 phút cho đến khi tôm cong tròn, chuyển sang màu hồng cam đục và chín kỹ hoàn toàn thì vớt ngay ra để nguội ráo.', NULL, 3),
('imp-70379b3f30b48438_v4_step_3', 'imp-70379b3f30b48438', 3, 'prep', 'Vắt thật kiệt nước dưa leo đã ướp muối', 'Dùng hai tay nắm từng nắm dưa leo bóp vắt thật kiệt phần nước muối tiết ra (nếu thấy hơi mặn có thể tráng nhanh qua nước lọc lạnh rồi vắt lại), thấm thêm bằng khăn giấy cho dưa khô ráo hoàn toàn.', 'Dưa leo càng được vắt ráo nước thì khi trộn sẽ càng giòn lâu và thấm đều vị nước sốt giấm ngọt.', NULL),
('imp-70379b3f30b48438_v4_step_4', 'imp-70379b3f30b48438', 4, 'sauce', 'Pha nước sốt giấm gạo chua ngọt', 'Trong bát nhỏ, khuấy tan 35 ml giấm gạo Nhật, 12 g đường cát trắng, 15 ml nước tương Nhật, 5 ml dầu mè rang cùng 1 g ớt vảy khô đến khi hạt đường hòa quyện hoàn toàn vào dung dịch giấm.', NULL, NULL),
('imp-70379b3f30b48438_v4_step_5', 'imp-70379b3f30b48438', 5, 'finish', 'Trộn nhẹ gỏi dưa leo tôm và ướp lạnh', 'Cho dưa leo đã vắt ráo, tôm luộc đã nguội (có thể chẻ đôi con lớn) và 0,5 bó hành lá thái nhỏ vào tô sạch. Rưới đều bát nước sốt giấm gạo lên trên, đảo trộn nhẹ tay cho dưa không bị dập, rắc 8 g hạt mè trắng rang vào trộn thêm lần nữa rồi đậy kín để ngăn mát tủ lạnh 15 phút cho thấm vị.', 'Ướp lạnh khoảng 15–20 phút trước khi ăn giúp món gỏi Sunomono mát sâu, giòn ngọt và các hương vị hòa quyện thanh tao nhất.', 15),
('imp-70379b3f30b48438_v4_step_6', 'imp-70379b3f30b48438', 6, 'finish', 'Trình bày gỏi Sunomono ra chén và dùng mát', 'Chia gỏi dưa leo tôm ra ba chén nhỏ gọn đẹp, rưới thêm chút nước sốt dưới đáy tô lên trên và thưởng thức lạnh như món khai vị thanh mát.', NULL, NULL),
('imp-49262ac40836045a_v4_step_1', 'imp-49262ac40836045a', 1, 'marinate', 'Thái nhỏ và ướp thịt ức gà với rượu Sake', 'Thái 100 g thịt ức gà phi lê thành từng miếng vuông nhỏ khoảng 1 cm cho nhanh chín đều. Trộn thịt gà với 15 ml rượu Sake nấu ăn trong bát nhỏ, ướp khoảng 10 phút cho thịt mềm ẩm và hết mùi tanh. Song song, thái lát mỏng 60 g nấm đùi gà tươi, 40 g chả cá Nhật và thái nhỏ 0,5 bó hành lá tươi.', NULL, 10),
('imp-49262ac40836045a_v4_step_2', 'imp-49262ac40836045a', 2, 'sauce', 'Pha hỗn hợp trứng và nước dùng Dashi nguội', 'Đập 3 quả trứng gà vào bát, dùng đũa khuấy nhẹ sát đáy theo đường zíc zắc cho lòng đỏ và lòng trắng hòa quyện mà không nổi bọt. Rót từ từ 360 ml nước dùng Dashi đã nguội hoàn toàn cùng 10 ml rượu ngọt Mirin, 10 ml nước tương Nhật và 2 g muối ăn vào khuấy tan đều.', 'Nước dùng Dashi phải nguội về nhiệt độ phòng; dùng nước dashi nóng sẽ làm trứng bị vón lợn cợn ngay khi pha.', NULL),
('imp-49262ac40836045a_v4_step_3', 'imp-49262ac40836045a', 3, 'prep', 'Lọc rây hỗn hợp trứng và xếp nhân vào ba chén sứ', 'Lọc hỗn hợp trứng dashi qua rây lưới mịn 2 lần vào ca có miệng rót để loại bỏ hoàn toàn dây lòng trắng. Chia đều thịt ức gà đã ướp và nấm đùi gà thái lát xuống đáy ba chén sứ chịu nhiệt, đặt các lát chả cá Nhật lên trên rồi rót từ từ hỗn hợp trứng vào đầy 80% chén, hớt sạch bọt khí mặt trên và đậy kín nắp chén (hoặc bọc màng giấy bạc).', 'Lọc hỗn hợp trứng qua rây mịn và hớt sạch bọt khí trên mặt chén giúp thành phẩm custard mịn mướt không bị rỗ.', NULL),
('imp-49262ac40836045a_v4_step_4', 'imp-49262ac40836045a', 4, 'cook', 'Đun nồi nước hấp và hạ lửa nhỏ nhất', 'Đổ nước vào nồi hấp sâu lòng sao cho mực nước ngập khoảng một nửa chiều cao chén sứ, đun sôi mạnh trên lửa lớn rồi hạ ngay xuống mức lửa nhỏ nhất để mặt nước lắng êm chỉ còn hơi nóng nhẹ ở khoảng 85–90°C.', NULL, NULL),
('imp-49262ac40836045a_v4_step_5', 'imp-49262ac40836045a', 5, 'cook', 'Hấp cách thủy trứng lửa nhỏ trong 22–25 phút', 'Nhẹ nhàng đặt ba chén trứng vào nồi nước nóng (không để nước sôi bùng), đậy nắp nồi hơi hé khe nhỏ thoát bớt áp suất và hấp liu riu ở lửa nhỏ nhất trong 22–25 phút cho đến khi trứng đông đặc mượt mà và thịt gà chín kỹ hoàn toàn bên trong.', 'Hấp ở nhiệt độ ổn định dưới mức sôi và hé nhẹ nắp nồi là bí quyết giúp mặt chén trứng Chawanmushi láng bóng như lụa, không bị rỗ bọt khí.', 23),
('imp-49262ac40836045a_v4_step_6', 'imp-49262ac40836045a', 6, 'finish', 'Kiểm tra độ chín, rắc hành lá và thưởng thức nóng', 'Xiên nhẹ đầu que tre vào chính giữa chén trứng, thấy nước chảy ra trong veo không còn đục là đạt. Rắc hành lá thái nhỏ lên mặt từng chén, đậy nắp ủ thêm 1 phút rồi dọn nóng dùng bằng thìa nhỏ.', NULL, NULL),
('imp-e26d04bf95bcede8_v4_step_1', 'imp-e26d04bf95bcede8', 1, 'cook', 'Hầm nước dùng xương heo và rau củ thơm', 'Cho 400 g xương ống heo, 3500 ml nước lọc, 0,5 củ hành tây, 0,5 củ tỏi khô nguyên vỏ và 25 g gừng tươi thái lát vào nồi cao lớn. Đun sôi trên lửa lớn không đậy nắp, dùng vợt lưới mịn hớt thật sạch toàn bộ bọt và váng bẩn nổi lên rồi buộc chặt 450 g thịt ba chỉ heo bằng dây dù thực phẩm thả vào hầm chung.', 'Hớt bọt thật kỹ trong 20 phút đầu sôi là chìa khóa giúp nước dùng Ramen trong veo, thơm thanh mà không có mùi hôi xương.', 25),
('imp-e26d04bf95bcede8_v4_step_2', 'imp-e26d04bf95bcede8', 2, 'cook', 'Ninh mềm thịt ba chỉ và thêm mỡ béo vào nước dùng', 'Tiếp tục đun sôi lăn tăn mở nắp khoảng 90 phút cho thịt ba chỉ chín mềm. Múc khoảng 240 ml nước dùng nóng sang nồi nhỏ để chuẩn bị om Chashu; đồng thời thả 30 g mỡ heo thắng cùng phần lá xanh của 1,5 bó hành lá tươi vào nồi nước dùng chính tiếp tục ninh lửa vừa nhỏ thêm 60 phút cho ngọt sâu.', NULL, 90),
('imp-e26d04bf95bcede8_v4_step_3', 'imp-e26d04bf95bcede8', 3, 'cook', 'Om thịt ba chỉ Chashu và cô nước sốt Shoyu Tare', 'Pha vào nồi nhỏ chứa 240 ml nước dùng nóng: 155 ml nước tương Nhật, 30 ml rượu Sake nấu ăn và 30 ml rượu ngọt Mirin. Vớt tảng thịt ba chỉ từ nồi xương sang nồi sốt này, phủ giấy nến khoét lỗ sát mặt thịt và om liu riu lửa nhỏ khoảng 60 phút, thỉnh thoảng rưới sốt lên mặt thịt. Sau đó vớt thịt ra để nguội hẳn rồi bọc kín ướp lạnh cho săn chắc để dễ thái lát mỏng 3 mm; phần nước sốt lọc sạch mỡ chính là Shoyu Tare.', 'Làm lạnh thịt Chashu trước khi cắt giúp lát thịt tròn đẹp, mỡ kết dính không bị nát vụn.', 60),
('imp-e26d04bf95bcede8_v4_step_4', 'imp-e26d04bf95bcede8', 4, 'marinate', 'Luộc trứng lòng đào và ngâm tương Ajitama', 'Đun sôi nồi nước nhỏ, thả 4 quả trứng gà lạnh từ tủ mát vào luộc đúng 7 phút rồi vớt ngay sang tô nước đá 15 phút và bóc sạch vỏ. Đun sôi nhẹ 45 ml nước tương Nhật, 45 ml rượu Sake nấu ăn, 30 ml rượu ngọt Mirin và 12 g đường cát trắng trong 1 phút cho tan đường rồi để nguội hẳn, cho trứng vào ngâm kín trong tủ mát ít nhất 2 giờ cho ngấm màu nâu đẹp.', 'Luộc trứng ngay từ lúc lấy ở tủ mát rồi ngâm nước đá lạnh giúp lòng trắng săn mịn, dễ bóc vỏ và lòng đỏ dẻo sánh.', 7),
('imp-e26d04bf95bcede8_v4_step_5', 'imp-e26d04bf95bcede8', 5, 'cook', 'Lọc trong nước dùng và luộc nhanh mì Ramen', 'Lọc bỏ hết xương ống và xác rau củ khỏi nồi nước dùng chính, đun nóng sôi lăn tăn trở lại. Chuẩn bị sẵn thịt ba chỉ Chashu thái lát 3 mm, trứng lòng đào cắt đôi và hành lá thái nhỏ. Đun sôi mạnh một nồi nước lớn khác, thả 320 g mì Ramen khô vào khuấy tơi luộc khoảng 3 phút cho sợi vừa chín dai rồi vớt ra rổ lắc thật ráo nước.', 'Vẩy thật kiệt nước sau khi luộc mì để không làm loãng hương vị đậm đà của tô nước dùng Ramen.', 3),
('imp-e26d04bf95bcede8_v4_step_6', 'imp-e26d04bf95bcede8', 6, 'finish', 'Hoàn thiện tô Shoyu Ramen nóng hổi và thưởng thức', 'Cho vào mỗi tô 1,5 muỗng canh nước sốt Shoyu Tare và chút hành lá thái nhỏ, chan 350 ml nước dùng đang sôi nóng vào, thả mì Ramen vào gắp gọn sang một bên. Xếp vài lát thịt Chashu, hai nửa trứng lòng đào Ajitama, hành lá thái nhỏ và cắm miếng rong biển khô Nori bên thành tô rồi dùng nóng ngay.', NULL, NULL),
('imp-b808fb03d1e8ede6_v4_step_1', 'imp-b808fb03d1e8ede6', 1, 'prep', 'Vo ngâm gạo và nấu cơm trắng Nhật', 'Vo nhẹ 300 g gạo hạt ngắn Nhật 2–3 lần đến khi nước khá trong, cho vào nồi cơm điện cùng 430 ml nước lọc và ngâm 20 phút trước khi bật nấu. Khi cơm chín, để nồi ở chế độ giữ ấm thêm 10 phút rồi mở nắp xới tơi hạt cơm.', 'Ngâm gạo trước khi bật nút nấu giúp hạt gạo ngậm đủ nước, chín dẻo bóng và không bị sượng lõi.', 30),
('imp-b808fb03d1e8ede6_v4_step_2', 'imp-b808fb03d1e8ede6', 2, 'marinate', 'Cắt và ướp thịt đùi gà cùng sơ chế rau củ', 'Cắt 450 g đùi gà lọc xương thành miếng vuông khoảng 2,5 cm rồi ướp đều với 1,5 g muối ăn trong 10 phút. Khoai tây gọt vỏ cắt khối 2 cm và ngâm ngay vào thau nước lạnh 15 phút cho ra bớt tinh bột, sau đó vớt ra để ráo; cà rốt cắt khoanh xéo dày 1,5 cm; hành tây thái múi mỏng; tỏi băm nhuyễn và gừng tươi mài mịn.', 'Ngâm khoai tây vào nước lạnh trước khi nấu giúp mặt khoai săn lại, không bị bở nát làm đục nồi cà ri.', 15),
('imp-b808fb03d1e8ede6_v4_step_3', 'imp-b808fb03d1e8ede6', 3, 'cook', 'Xào hành tây nâu vàng và phi thơm gừng tỏi', 'Làm nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn thực vật, cho toàn bộ hành tây thái mỏng cùng 0,5 g muối ăn còn lại vào đảo đều khoảng 8 phút đến khi hành mềm rũ, chuyển màu nâu vàng và dậy mùi thơm ngọt. Thêm tỏi băm và gừng tươi mài vào đảo nhanh 30 giây cho dậy hương thơm.', 'Xào hành tây đến khi ngả màu nâu vàng chứ không chỉ chín trong là bí quyết tạo vị ngọt sâu cho sốt cà ri.', 8),
('imp-b808fb03d1e8ede6_v4_step_4', 'imp-b808fb03d1e8ede6', 4, 'cook', 'Xào săn thịt gà và ninh mềm khoai tây, cà rốt', 'Cho phần đùi gà đã ướp vào nồi xào trên lửa vừa khoảng 3 phút cho thịt săn bề mặt và không còn màu hồng bên ngoài. Tiếp tục thả khoai tây và cà rốt vào đảo đều 1 phút, đổ 300 ml nước dùng gà cùng 350 ml nước lọc vào đun sôi trên lửa lớn rồi hạ xuống lửa nhỏ, đậy hờ nắp ninh liu riu 18–20 phút đến khi xiên đũa qua khoai và cà rốt thấy mềm bùi.', 'Luôn giữ lửa nhỏ sôi lăn tăn và vớt bọt nhẹ để nước dùng trong, rau củ chín đều mà không bị vỡ cạnh.', 20),
('imp-b808fb03d1e8ede6_v4_step_5', 'imp-b808fb03d1e8ede6', 5, 'sauce', 'Hòa tan viên cà ri Nhật và nêm sốt sánh mịn', 'Tắt bếp hoặc hạ lửa xuống mức nhỏ nhất, bẻ nhỏ 110 g viên cà ri Nhật thả từ từ vào nồi, dùng muôi gỗ khuấy nhẹ liên tục khoảng 1–2 phút cho viên cà ri tan hoàn toàn, không còn vón cục. Bật lại lửa nhỏ, thêm 10 ml xì dầu Nhật và 5 ml sốt Worcestershire vào khuấy đều, đun liu riu thêm 4 phút cho sốt sánh bóng và thịt gà chín kỹ hoàn toàn.', 'Tắt bếp khi thả viên cà ri giúp bột roux tan đều mượt mà, tránh bị vón cục hoặc bén đáy nồi.', 4),
('imp-b808fb03d1e8ede6_v4_step_6', 'imp-b808fb03d1e8ede6', 6, 'finish', 'Trình bày đĩa cơm cà ri và hoàn thiện món ăn', 'Xới cơm trắng nóng ra một nửa đĩa sâu lòng, múc cà ri gà cùng khoai tây và cà rốt chan vào nửa đĩa còn lại. Rắc hành lá thái xéo lên trên và xếp củ cải muối đỏ Fukujinzuke bên cạnh đĩa rồi thưởng thức ngay khi sốt còn nóng sánh.', NULL, NULL),
('imp-46c2a1c4cc7a8bb5_v4_step_1', 'imp-46c2a1c4cc7a8bb5', 1, 'prep', 'Sơ chế thịt bò, hành tây, gừng và hành lá', 'Thịt bò thái lát mỏng cắt miếng dài 4–5 cm vừa gắp. Hành tây bóc vỏ thái lát mỏng dọc củ, gừng tươi thái sợi mảnh, hành lá rửa sạch thái xéo mỏng để riêng.', 'Thịt bò thái lát mỏng ngang thớ hoặc dùng loại thịt bò nhúng lẩu sẽ giúp thịt mềm ngọt, không bị dai khi nấu nhanh.', NULL),
('imp-46c2a1c4cc7a8bb5_v4_step_2', 'imp-46c2a1c4cc7a8bb5', 2, 'cook', 'Nấu và nêm nồi nước dùng Dashi nóng', 'Đổ 600 ml nước dùng Dashi cùng 300 ml nước lọc vào nồi, đun sôi nhẹ trên lửa vừa rồi nêm 25 ml xì dầu Nhật, 20 ml rượu Mirin và 6 g đường cát trắng. Khuấy tan hoàn toàn, nếm thử vị mặn ngọt thanh vừa miệng rồi tắt bếp, đậy nắp giữ nóng.', 'Pha thêm nước lọc giúp nước dùng Dashi vừa vị thanh tao khi kết hợp cùng xì dầu mà không bị mặn gắt.', 4),
('imp-46c2a1c4cc7a8bb5_v4_step_3', 'imp-46c2a1c4cc7a8bb5', 3, 'cook', 'Áp chảo thịt bò với gừng và hành tây', 'Làm nóng chảo rộng trên lửa vừa với 10 ml dầu ăn thực vật, dàn đều 300 g thịt bò thành một lớp mỏng và đảo nhanh khoảng 1–2 phút đến khi thịt vừa chuyển màu hết đỏ tái. Thêm gừng thái sợi và hành tây vào đảo chung thêm 2 phút cho hành mềm trong và dậy mùi thơm.', 'Dùng chảo rộng để thịt bò áp chảo nhanh thay vì bị ra nước hấp hơi, giữ được độ mềm ngọt tự nhiên.', 4),
('imp-46c2a1c4cc7a8bb5_v4_step_4', 'imp-46c2a1c4cc7a8bb5', 4, 'sauce', 'Rim thịt bò thấm sốt mặn ngọt kiểu Nhật', 'Cho 30 ml xì dầu Nhật còn lại, 30 ml rượu Mirin còn lại, 45 ml rượu Sake nấu ăn, 14 g đường cát trắng còn lại và 45 ml nước lọc vào chảo thịt bò, đảo đều trên lửa vừa khoảng 2–3 phút đến khi nước sốt sôi lăn tăn, hơi sánh lại và bám đều quanh từng lát thịt bò thì tắt bếp.', 'Không nấu thịt bò quá lâu sau khi thịt đã chín tới để tránh làm thịt bị khô xơ.', 3),
('imp-46c2a1c4cc7a8bb5_v4_step_5', 'imp-46c2a1c4cc7a8bb5', 5, 'cook', 'Trụng mì Udon trong nước sôi', 'Đun sôi một nồi nước riêng trên lửa lớn, thả 3 gói mì Udon vào trụng nhanh khoảng 1–2 phút, dùng đũa khuấy nhẹ cho từng sợi mì tơi rời, trong bóng và mềm dai thì vớt ngay ra rổ, xóc thật ráo nước.', 'Trụng mì Udon thật ráo nước giúp tô nước dùng không bị loãng và giữ trọn vị đậm đà của Dashi.', 2),
('imp-46c2a1c4cc7a8bb5_v4_step_6', 'imp-46c2a1c4cc7a8bb5', 6, 'finish', 'Trình bày tô mì Udon bò hành nóng hổi', 'Chia mì Udon đã ráo nước vào 3 tô lớn, đun sôi lại nồi nước dùng Dashi rồi chan ngập mặt mì. Xếp phần thịt bò xào hành tây cùng chút nước sốt lên trên, rắc hành lá thái xéo và thêm bột ớt 7 vị Nhật Shichimi tùy thích rồi dùng ngay khi còn nóng.', NULL, NULL),
('imp-38fb8569664d1f3b_v4_step_1', 'imp-38fb8569664d1f3b', 1, 'marinate', 'Thấm khô, ướp gia vị và áo bột cá hồi', 'Kiểm tra và nhổ sạch xương dăm trên 280 g cá hồi phi lê còn da, dùng khăn giấy thấm thật khô cả mặt thịt và mặt da. Rắc đều 2 g muối ăn và 1 g tiêu đen xay lên hai mặt cá, để thấm 10 phút cho thịt cá săn nhẹ.', 'Thấm thật khô nước trên bề mặt cá hồi là điều kiện quan trọng nhất để da cá áp chảo giòn rụm, không bị bắn dầu.', 10),
('imp-38fb8569664d1f3b_v4_step_2', 'imp-38fb8569664d1f3b', 2, 'prep', 'Áo bột gạo mỏng và chuẩn bị nguyên liệu làm sốt', 'Rây 5 g bột gạo áo thành một lớp thật mỏng lên cả hai mặt miếng cá hồi rồi giũ nhẹ cho rơi hết phần bột thừa. Băm nhỏ tỏi khô, vắt nửa quả chanh tươi lấy nước cốt bỏ hạt và thái nhỏ hành lá để sẵn.', 'Lớp bột gạo cực mỏng giúp mặt cá lên màu vàng đẹp kiểu Meunière và giữ ẩm cho thớ thịt bên trong.', NULL),
('imp-38fb8569664d1f3b_v4_step_3', 'imp-38fb8569664d1f3b', 3, 'cook', 'Áp chảo mặt da cá hồi vàng giòn', 'Làm nóng chảo chống dính trên lửa vừa lớn với 10 ml dầu ăn trung tính tráng đều đáy chảo. Đặt miếng cá hồi úp mặt da xuống chảo, dùng xẻng ấn nhẹ khoảng 20 giây đầu để da phẳng tiếp xúc đều mặt chảo, sau đó để yên áp chảo khoảng 4 phút đến khi thấy phần da chuyển vàng giòn và thịt cá chín trắng lên khoảng 2/3 chiều dày miếng cá.', 'Không di chuyển hoặc lật cá sớm trong 4 phút đầu để lớp da giòn bám chắc và tách mặt chảo tự nhiên.', 4),
('imp-38fb8569664d1f3b_v4_step_4', 'imp-38fb8569664d1f3b', 4, 'cook', 'Áp chín mặt còn lại và cho cá ra đĩa', 'Lật nhẹ miếng cá hồi sang mặt thịt, hạ xuống lửa vừa và áp thêm khoảng 2 phút cho cá vừa chín tới (phần lõi giữa còn mềm ẩm, không bị khô bở) rồi gắp cá ra đĩa giữ ấm.', NULL, 2),
('imp-38fb8569664d1f3b_v4_step_5', 'imp-38fb8569664d1f3b', 5, 'sauce', 'Phi tỏi và nấu sốt bơ chanh xì dầu', 'Hạ lửa thật nhỏ trên cùng chiếc chảo đó, cho tỏi băm vào phi khoảng 30 giây đến khi dậy mùi thơm dịu mà không bị cháy vàng. Rót 5 ml xì dầu Nhật, 5 ml rượu Mirin và nước cốt chanh tươi vào khuấy đều cho sôi lăn tăn nhẹ.', 'Giữ lửa nhỏ khi phi tỏi để tỏi thơm dịu; nếu chảo quá nóng có thể nhấc chảo khỏi bếp vài giây.', NULL),
('imp-38fb8569664d1f3b_v4_step_6', 'imp-38fb8569664d1f3b', 6, 'finish', 'Đánh tan bơ lạt và rưới sốt lên cá hồi', 'Nhấc chảo khỏi bếp, thả 20 g bơ lạt lạnh vào và xoay nhẹ chảo cho bơ tan chảy từ từ quyện với nước cốt chanh tạo thành sốt sánh bóng mịn màng. Rưới đều sốt bơ chanh lên 2 miếng cá hồi, rắc hành lá thái nhỏ rồi dùng nóng ngay.', NULL, NULL),
('imp-eae128801c2c7f96_v4_step_1', 'imp-eae128801c2c7f96', 1, 'prep', 'Sơ chế rau bina và chuẩn bị nước chần', 'Nhặt sạch 300 g rau bina, rửa kỹ từng kẽ gốc dưới vòi nước lạnh cho sạch cát rồi để nguyên cọng. Đun sôi 1000 ml nước lọc trong nồi lớn trên lửa lớn, đồng thời chuẩn bị sẵn một tô lớn nước lọc lạnh có thả vài viên đá.', 'Giữ nguyên cọng rau khi chần giúp dễ cầm nhúng phần cuống trước và vắt ráo nước sạch hơn sau khi luộc.', NULL),
('imp-eae128801c2c7f96_v4_step_2', 'imp-eae128801c2c7f96', 2, 'sauce', 'Rang thơm và giã dập hạt mè trắng', 'Cho 35 g hạt mè trắng vào chảo khô trên lửa vừa, đảo và lắc chảo liên tục khoảng 2–3 phút đến khi hạt mè nở phồng, chuyển màu vàng nhạt và tỏa mùi thơm béo thì trút ngay ra bát cho nguội bớt. Chừa lại 1 muỗng cà phê hạt mè nguyên để trang trí, phần còn lại cho vào cối giã dập khoảng 70% để tiết dầu thơm.', 'Giã mè khi còn hơi ấm giúp dầu mè tiết ra thơm hơn nhiều, không giã nát nhuyễn hết mà để lẫn ít hạt dập tạo độ bùi.', 3),
('imp-eae128801c2c7f96_v4_step_3', 'imp-eae128801c2c7f96', 3, 'sauce', 'Pha sốt mè xì dầu ngọt mặn cân bằng', 'Cho 15 ml xì dầu Nhật, 12 g đường cát trắng, 5 ml rượu Mirin và 8 ml dầu mè thơm vào bát mè vừa giã, khuấy đều tay đến khi đường tan hết và hỗn hợp sánh thơm đồng nhất.', 'Nêm sốt hơi đậm nhẹ một chút vì khi trộn vào rau bina vẫn còn độ ẩm tự nhiên sẽ vừa miệng.', NULL),
('imp-eae128801c2c7f96_v4_step_4', 'imp-eae128801c2c7f96', 4, 'cook', 'Chần nhanh rau bina giữ màu xanh mướt', 'Khi nồi nước sôi bùng, thả 5 g muối ăn vào khuấy tan. Cầm phần ngọn lá, nhúng phần cuống rau bina vào nước sôi trước trong 15 giây cho cuống mềm bớt, sau đó nhấn chìm toàn bộ lá rau xuống nước sôi chần tiếp 35 giây rồi vớt ra ngay.', 'Chần phần cuống cứng trước phần lá giúp cả cọng rau chín đồng đều mà lá không bị nhũn nát.', 1),
('imp-eae128801c2c7f96_v4_step_5', 'imp-eae128801c2c7f96', 5, 'prep', 'Ngâm lạnh, vắt kiệt nước và cắt khúc rau', 'Thả ngay rau bina vừa chần vào tô nước lạnh khoảng 1 phút để hãm nhiệt và giữ màu xanh tươi, sau đó vớt ra nắm chặt tay vắt thật kiệt nước. Đặt bó rau lên thớt, cắt thành từng khúc dài khoảng 3 cm rồi tơi nhẹ các cọng rau.', 'Vắt thật ráo nước là bước quyết định món Goma-ae ngon chuẩn vị, không bị đọng nước làm loãng sốt mè.', 1),
('imp-eae128801c2c7f96_v4_step_6', 'imp-eae128801c2c7f96', 6, 'finish', 'Trộn rau bina với sốt mè và trình bày', 'Cho rau bina đã cắt khúc vào tô sốt mè, dùng đũa hoặc tay đeo găng đảo nhẹ nhàng để từng cọng rau áo đều lớp sốt mè sánh thơm. Bày ra đĩa nhỏ, rắc phần hạt mè rang nguyên hạt chừa lại lên trên rồi thưởng thức.', NULL, NULL),
('imp-56ec9eae817af509_v4_step_1', 'imp-56ec9eae817af509', 1, 'prep', 'Thái sợi mảnh bắp cải và cà rốt', 'Tách bỏ lá già ngoài cùng và lõi cứng của 480 g bắp cải xanh, rửa sạch rồi thái sợi mỏng đều tay. Cà rốt gọt vỏ, thái sợi mảnh có kích cỡ tương đương sợi bắp cải để khi hấp chín đồng đều và đẹp mắt.', 'Thái sợi bắp cải và cà rốt đều nhau giúp rau chín cùng lúc, không bị sợi nhũn sợi sống.', NULL),
('imp-56ec9eae817af509_v4_step_2', 'imp-56ec9eae817af509', 2, 'cook', 'Hấp nhanh bắp cải và cà rốt bằng ít nước', 'Cho toàn bộ bắp cải và cà rốt thái sợi vào nồi, đổ 60 ml nước lọc vào rồi đậy kín nắp, đun trên lửa vừa khoảng 4–5 phút đến khi rau vừa chín tới, xẹp xuống nhưng vẫn giữ độ giòn ngọt tự nhiên. Tắt bếp, trút rau ra rổ cho nguội nhanh.', 'Chỉ dùng 60 ml nước và đậy nắp kín giúp rau chín bằng hơi nước, giữ lại tối đa vị ngọt và vitamin.', 5),
('imp-56ec9eae817af509_v4_step_3', 'imp-56ec9eae817af509', 3, 'prep', 'Vắt ráo kiệt nước phần rau đã hấp', 'Khi bắp cải và cà rốt đã nguội hẳn, dùng tay sạch bóp nhẹ hoặc vắt kỹ cho ra hết nước thừa đọng trong rau rồi tơi nhẹ ra tô lớn.', 'Vắt thật ráo nước trước khi trộn giúp sốt mè bám chặt vào từng sợi bắp cải, món ăn đậm vị mà không bị chảy nước.', NULL),
('imp-56ec9eae817af509_v4_step_4', 'imp-56ec9eae817af509', 4, 'sauce', 'Rang vàng và giã dập hạt mè trắng', 'Cho 35 g hạt mè trắng vào chảo khô trên lửa vừa nhỏ, đảo đều tay khoảng 3 phút cho mè vàng thơm lừng rồi trút ra. Giữ lại 1 muỗng cà phê hạt nguyên, phần còn lại cho vào cối giã dập đến khi hơi sánh thơm.', NULL, 3),
('imp-56ec9eae817af509_v4_step_5', 'imp-56ec9eae817af509', 5, 'sauce', 'Pha sốt mè xì dầu giấm gạo', 'Trộn đều phần mè giã dập với 18 ml xì dầu Nhật, 12 g đường cát trắng, 10 ml giấm gạo và 10 ml dầu mè thơm đến khi đường tan hết thành hỗn hợp sốt sệt mịn.', 'Thêm chút giấm gạo vào sốt mè kiểu Nhật giúp vị béo bùi trở nên thanh nhẹ, rất hợp ăn lạnh vào ngày nóng.', NULL),
('imp-56ec9eae817af509_v4_step_6', 'imp-56ec9eae817af509', 6, 'finish', 'Trộn đều, ủ lạnh và hoàn thiện món ăn', 'Rưới sốt mè lên tô bắp cải và cà rốt đã vắt ráo, trộn đều tay cho từng sợi rau áo đều sốt. Đậy kín tô rau, cho vào ngăn mát tủ lạnh khoảng 20–30 phút cho thấm vị và mát lạnh rồi bày ra đĩa, rắc hành lá thái nhỏ và hạt mè nguyên lên trên.', NULL, 20),
('imp-44b1338a7a49098d_v4_step_1', 'imp-44b1338a7a49098d', 1, 'prep', 'Sơ chế kim chi, thịt ba chỉ và đậu phụ', 'Cắt 420 g kim chi cải thảo ủ chua thành khúc dài 3–4 cm và giữ lại khoảng 60 ml nước kim chi. Thái miếng thịt ba chỉ heo dày 0,5 cm, thái lát hành tây, thái lát đậu phụ trắng dày 1,5 cm và thái vát hành lá tươi.', NULL, NULL),
('imp-44b1338a7a49098d_v4_step_2', 'imp-44b1338a7a49098d', 2, 'cook', 'Xào thịt ba chỉ và kim chi dậy mùi thơm', 'Làm nóng nồi sâu lòng trên lửa vừa với 15 ml dầu thực vật, cho thịt ba chỉ heo vào đảo 3 phút đến khi thịt săn mặt và hơi xém cạnh. Thêm tỏi khô băm nhuyễn và kim chi cải thảo vào xào chung 4 phút để kim chi mềm lại và quyện vị béo từ thịt.', 'Xào kim chi khoảng 4 phút trước khi cho nước dùng giúp hương vị canh đậm sâu và thơm hơn hẳn.', 7),
('imp-44b1338a7a49098d_v4_step_3', 'imp-44b1338a7a49098d', 3, 'cook', 'Hòa gia vị và đổ nước dùng cá cơm tảo bẹ', 'Rắc 5 g ớt bột Hàn Quốc (Gochugaru), 18 g tương ớt Hàn Quốc (Gochujang), 8 g đường cát trắng và phần nước kim chi vào nồi đảo đều 30 giây. Rót 500 ml nước dùng cá cơm tảo bẹ vào, khuấy nhẹ cho tan gia vị rồi đun sôi trên lửa lớn.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-44b1338a7a49098d_v4_step_4', 'imp-44b1338a7a49098d', 4, 'cook', 'Hầm canh cùng hành tây cho ngọt nước', 'Khi nồi canh sôi bùng, thả hành tây thái lát vào, hớt bọt nổi và hạ xuống lửa vừa-nhỏ, đậy nắp hầm 12 phút để thịt ba chỉ chín mềm hoàn toàn và hành tây tiết vị ngọt thanh. Nêm thêm 4 g muối ăn cho vừa khẩu vị.', 'Nêm muối sau khi đã hầm khoảng 10 phút giúp bạn kiểm soát độ mặn chính xác vì kim chi đã có sẵn vị mặn.', 12),
('imp-44b1338a7a49098d_v4_step_5', 'imp-44b1338a7a49098d', 5, 'cook', 'Thả đậu phụ trắng vào nồi canh', 'Xếp nhẹ từng lát đậu phụ trắng lên mặt nồi canh, dùng muỗng múc nước canh rưới lên mặt đậu và nấu tiếp 4 phút trên lửa vừa cho đậu nóng thấm vị mà vẫn giữ nguyên miếng.', NULL, 4),
('imp-44b1338a7a49098d_v4_step_6', 'imp-44b1338a7a49098d', 6, 'finish', 'Rắc hành lá, rưới dầu mè và dọn nóng', 'Rắc hành lá tươi thái vát lên mặt nồi canh, tắt bếp rồi rưới 5 ml dầu mè rang quanh nồi cho thơm lừng và dọn nóng dùng ngay với cơm trắng.', 'Dọn canh trực tiếp bằng nồi giữ nhiệt sẽ giúp đậu phụ và nước canh ấm nóng đến cuối bữa.', NULL),
('imp-a24a701c584d3ef3_v4_step_1', 'imp-a24a701c584d3ef3', 1, 'marinate', 'Ướp thịt bò và pha sốt Bibimbap', 'Ướp 240 g thịt bò thăn thái sợi với 25 ml nước tương, 6 g đường cát trắng, 10 ml rượu ngọt Mirin, 1/3 lượng tỏi khô băm nhuyễn, 1/2 lượng hành lá thái nhỏ và 8 ml dầu mè rang trong 15 phút. Ở chén nhỏ, trộn đều 75 g tương ớt Hàn Quốc (Gochujang), 10 ml nước tương, 10 g đường cát trắng, 6 ml dầu mè rang, 3 g hạt mè trắng rang và chút tỏi băm thành sốt trộn.', 'Nếu sốt Gochujang hơi đặc, có thể hòa thêm 1–2 muỗng canh nước ấm để dễ rưới và trộn đều cơm.', 15),
('imp-a24a701c584d3ef3_v4_step_2', 'imp-a24a701c584d3ef3', 2, 'prep', 'Chần giá đỗ, rau chân vịt và ướp dưa leo', 'Bóp nhẹ dưa leo thái sợi với 1,5 g muối ăn để 10 phút rồi vắt ráo cho giòn. Đun sôi 1,2 lít nước lọc, chần giá đỗ tươi 2 phút rồi vớt ra để ráo, trộn với 1,5 g muối ăn, 1/3 tỏi băm, 6 ml dầu mè rang và 4 g hạt mè trắng rang. Tiếp tục tận dụng nước sôi chần rau chân vịt 45 giây, xả nước lạnh, vắt kiệt và trộn với 1 g muối ăn, 5 ml dầu mè rang, chút tỏi băm và 4 g hạt mè trắng rang.', NULL, 5),
('imp-a24a701c584d3ef3_v4_step_3', 'imp-a24a701c584d3ef3', 3, 'cook', 'Xào riêng cà rốt, bí ngòi và nấm đùi gà', 'Dùng chảo sạch trên lửa vừa, lần lượt cho mỗi lần 4 ml dầu thực vật để xào riêng từng loại rau khoảng 2 phút mỗi loại: cà rốt thái sợi nêm 1 g muối ăn; bí ngòi xanh nêm 1 g muối ăn cùng chút tỏi băm; nấm đùi gà tươi xào với 10 ml nước tương còn lại cho thơm đậm rồi trút riêng ra khay.', 'Xào riêng từng loại rau giúp giữ nguyên màu sắc tươi tắn, mùi vị đặc trưng và độ giòn của từng nguyên liệu.', 6),
('imp-a24a701c584d3ef3_v4_step_4', 'imp-a24a701c584d3ef3', 4, 'cook', 'Xào chín thịt bò thăn trên lửa lớn', 'Làm nóng chảo với 5 ml dầu thực vật trên lửa lớn, cho toàn bộ thịt bò thăn đã ướp vào đảo nhanh tay 3–4 phút cho đến khi thịt chín săn đều và hơi xém cạnh thơm phức rồi trút ra đĩa.', NULL, 4),
('imp-a24a701c584d3ef3_v4_step_5', 'imp-a24a701c584d3ef3', 5, 'cook', 'Chiên 4 trứng ốp la lòng đào', 'Đun nóng chảo chống dính với 8 ml dầu thực vật còn lại trên lửa vừa, đập 4 quả trứng gà tươi vào chiên khoảng 3 phút cho lòng trắng chín hoàn toàn còn lòng đỏ vẫn sánh mềm lòng đào.', NULL, 3),
('imp-a24a701c584d3ef3_v4_step_6', 'imp-a24a701c584d3ef3', 6, 'finish', 'Xếp tô cơm trộn Bibimbap và hoàn thiện', 'Xới 720 g cơm trắng dẻo nóng chia đều vào 4 tô lớn. Xếp các loại giá đỗ, rau chân vịt, cà rốt, bí ngòi, dưa leo, nấm đùi gà và thịt bò theo hình quạt quanh thành tô. Đặt trứng ốp la vào chính giữa, rưới 5 ml dầu mè rang còn lại, rắc nốt phần hạt mè trắng rang cùng hành lá rồi dọn kèm sốt Gochujang để trộn đều khi ăn.', 'Làm ấm tô đựng cơm trước khi xếp nguyên liệu giúp Bibimbap giữ nóng lâu và dậy mùi dầu mè hơn khi trộn.', NULL),
('imp-52b5963c6cecfb96_v4_step_1', 'imp-52b5963c6cecfb96', 1, 'prep', 'Thái mỏng thịt bò và chuẩn bị hành tây, cà rốt', 'Thái 480 g thịt bò thăn ngoại thành lát mỏng 2–3 mm ngang thớ. Bào nhuyễn một nửa củ hành tây lấy cả nước lẫn xác để ướp mềm thịt, nửa củ còn lại thái lát mỏng. Thái lát mỏng cà rốt và cắt khúc 4 cm hành lá tươi.', 'Nước hành tây bào chứa enzyme tự nhiên giúp sợi cơ thịt bò mềm ra mà không bị bở.', NULL),
('imp-52b5963c6cecfb96_v4_step_2', 'imp-52b5963c6cecfb96', 2, 'marinate', 'Ướp thịt bò Bulgogi với mật ong và xì dầu', 'Khuấy tan 50 ml nước tương, 24 g đường nâu, 15 ml mật ong nguyên chất, 15 ml rượu ngọt Mirin, 10 ml dầu mè rang, tỏi khô băm nhuyễn, gừng tươi băm nhuyễn, phần hành tây bào nhuyễn và 1 g tiêu đen xay. Cho thịt bò thái lát, hành tây thái lát và cà rốt vào trộn đều, bọc kín ướp 30 phút trong ngăn mát.', 'Nếu có thời gian, ướp thịt qua đêm trong tủ lạnh sẽ giúp từng lát bò thấm đẫm hương vị hơn.', 30),
('imp-52b5963c6cecfb96_v4_step_3', 'imp-52b5963c6cecfb96', 3, 'cook', 'Làm nóng chảo gang và nướng mẻ thịt đầu tiên', 'Làm nóng chảo gang hoặc chảo đáy dày trên lửa lớn với 8 ml dầu thực vật đến khi chảo thật nóng. Gắp một nửa lượng thịt bò cùng rau củ trải thành một lớp mỏng đều, áp chảo mỗi mặt khoảng 2 phút cho đến khi thịt chín và cháy xém nhẹ ở rìa.', NULL, 4),
('imp-52b5963c6cecfb96_v4_step_4', 'imp-52b5963c6cecfb96', 4, 'cook', 'Nướng nốt mẻ thịt bò Bulgogi thứ hai', 'Trút mẻ đầu ra đĩa, thêm 7 ml dầu thực vật còn lại vào chảo, dàn nốt phần thịt bò và rau củ còn lại nướng trên lửa lớn thêm 4 phút đến khi thịt chín đều, phần sốt ướp hơi keo lại bám bóng lên từng lát thịt.', 'Chia làm 2 mẻ nướng giúp nhiệt độ chảo không bị tụt, thịt nướng cháy cạnh thơm chứ không bị luộc trong nước.', 4),
('imp-52b5963c6cecfb96_v4_step_5', 'imp-52b5963c6cecfb96', 5, 'cook', 'Đảo nhanh hành lá trên chảo nóng', 'Cho lại mẻ thịt đầu vào chảo cùng hành lá tươi cắt khúc, đảo nhanh tay 30–45 giây trên lửa lớn cho hành vừa chín tái dậy mùi thơm và thịt nóng đều.', NULL, NULL),
('imp-52b5963c6cecfb96_v4_step_6', 'imp-52b5963c6cecfb96', 6, 'finish', 'Rưới dầu mè, rắc mè rang và thưởng thức', 'Tắt bếp, rưới 5 ml dầu mè rang còn lại lên mặt thịt, bày ra đĩa lớn và rắc 5 g hạt mè trắng rang lên trên; dọn nóng ăn kèm cơm trắng hoặc cuốn rau sống.', NULL, NULL),
('imp-51b6559bf09bc980_v4_step_1', 'imp-51b6559bf09bc980', 1, 'prep', 'Sơ chế bí đỏ, rau thơm và làm sạch tôm', 'Gọt sạch vỏ 0,625 quả bí đỏ, bỏ hết phần ruột và hạt, rửa sạch rồi thái miếng vuông cạnh 2–3 cm. Lột vỏ 300 g tôm tươi, bỏ đầu, rạch nhẹ lưng rút sạch chỉ đen, rửa qua nước lạnh rồi thấm ráo. Băm nhỏ 12,5 g tỏi khô, thái sợi mảnh 8 g gừng tươi, thái nhỏ hành lá và ngò rí.', 'Chọn miếng bí đỏ có vỏ sẫm màu và ruột vàng cam rực sẽ cho thành phẩm dẻo bùi và ngọt nước hơn.', NULL),
('imp-51b6559bf09bc980_v4_step_2', 'imp-51b6559bf09bc980', 2, 'marinate', 'Ướp tôm tươi cho săn chắc đậm đà', 'Cho thịt tôm đã làm sạch vào tô, ướp cùng 4 g hạt nêm, 3 g muối ăn và 1 g tiêu đen xay. Trộn đều rồi để nghỉ khoảng 12 phút cho thịt tôm săn nhẹ và thấm đều gia vị.', NULL, 12),
('imp-51b6559bf09bc980_v4_step_3', 'imp-51b6559bf09bc980', 3, 'cook', 'Phi thơm tỏi gừng và xào săn tôm tươi', 'Làm nóng nồi đáy dày với 15 ml dầu ăn trên lửa vừa, cho tỏi băm và gừng thái sợi vào phi thơm dậy mùi. Trút tôm đã ướp vào đảo nhanh tay 2 phút đến khi tôm vừa săn lại và chuyển màu hồng cam thì tắt nhẹ lửa, gắp tôm ra chén riêng.', 'Gắp tôm ra riêng sau khi xào săn để tránh tôm bị ninh chung 15 phút với bí đỏ sẽ mất độ giòn ngọt.', 2),
('imp-51b6559bf09bc980_v4_step_4', 'imp-51b6559bf09bc980', 4, 'cook', 'Ninh bí đỏ chín bở dẻo trên lửa nhỏ', 'Đổ 1,2 lít nước lọc vào nồi vừa xào tôm, bật lửa lớn đun sôi bùng và hớt sạch bọt nếu có. Thả toàn bộ bí đỏ cắt miếng vào, hạ xuống lửa nhỏ và ninh khoảng 15 phút đến khi dùng đũa xiên thử thấy bí chín mềm bở dẻo.', 'Hầm bí đỏ trên lửa nhỏ giúp miếng bí chín bở dẻo từ từ và tiết vị ngọt sánh tự nhiên mà không bị đục nước.', 15),
('imp-51b6559bf09bc980_v4_step_5', 'imp-51b6559bf09bc980', 5, 'cook', 'Cho tôm trở lại và nêm nếm vị ngọt thanh', 'Trút phần tôm đã xào vào nồi bí đỏ, nêm 3 g muối còn lại, 4 g hạt nêm, 5 g đường cát trắng và 10 ml nước mắm ngon. Khuấy nhẹ cho gia vị hòa tan rồi đun sôi lăn tăn thêm 2 phút cho tôm chín kỹ hoàn toàn và hòa quyện với nước bí.', NULL, 2),
('imp-51b6559bf09bc980_v4_step_6', 'imp-51b6559bf09bc980', 6, 'finish', 'Rắc hành ngò, tiêu xay và dùng nóng', 'Nếm lại cho vừa khẩu vị rồi tắt bếp, rắc hành lá, ngò rí thái nhỏ và 1 g tiêu đen xay còn lại lên mặt nồi. Múc canh ra tô dùng nóng với cơm trắng.', NULL, NULL),
('imp-81a203668e5e4c1a_v4_step_1', 'imp-81a203668e5e4c1a', 1, 'prep', 'Làm sạch nấm kim châm, cà chua và đánh trứng', 'Cắt bỏ phần gốc rễ của 200 g nấm kim châm, tách tơi từng cụm nhỏ rồi rửa sạch và ngâm nước pha 2 g muối ăn khoảng 5 phút cho hết mùi hăng, vớt ra rổ để thật ráo. Bổ múi cau 2 quả cà chua; băm nhỏ 20 g hành tím và 10 g tỏi khô; thái nhỏ hành lá. Đập 3 quả trứng gà vào tô cùng 3 ml nước mắm rồi đánh tan đều.', 'Chỉ ngâm rửa nấm kim châm khi sắp nấu và để thật ráo để nấm không bị nhũn hay mất vị ngọt tự nhiên.', 5),
('imp-81a203668e5e4c1a_v4_step_2', 'imp-81a203668e5e4c1a', 2, 'cook', 'Phi thơm hành tỏi và xào cà chua tạo màu nền', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và tỏi băm vào phi thơm vàng nhạt. Thả cà chua bổ múi cau vào đảo đều khoảng 3 phút cho cà chua mềm nhẹ và tiết màu đỏ tự nhiên.', NULL, 3),
('imp-81a203668e5e4c1a_v4_step_3', 'imp-81a203668e5e4c1a', 3, 'cook', 'Đun sôi nước dùng và nấu chín nấm kim châm', 'Đổ 1,1 lít nước lọc vào nồi cà chua, đun lửa lớn đến khi sôi bùng rồi thả toàn bộ nấm kim châm vào nấu trên lửa vừa đúng 3–4 phút cho nấm vừa chín tới, vẫn giữ được độ giòn sần sật và tiết vị ngọt vào nước canh.', 'Không nấu nấm kim châm quá 5 phút để sợi nấm không bị dai nhũn và giữ trọn vị ngọt thanh.', 4),
('imp-81a203668e5e4c1a_v4_step_4', 'imp-81a203668e5e4c1a', 4, 'cook', 'Rưới trứng gà tạo vân mịn bồng bềnh', 'Hạ xuống lửa nhỏ để nước canh chỉ sôi lăn tăn nhẹ, rồi rót từ từ chén trứng đã đánh tan theo vòng tròn quanh nồi, đồng thời dùng đũa khuấy nhẹ nhàng theo một chiều để trứng tạo thành các sợi vân vàng mỏng mịn và không bị vón cục.', 'Rót trứng chậm theo dòng mảnh khi lửa nhỏ và khuấy nhẹ một chiều sẽ tạo vân trứng tơi mềm như mây.', 2),
('imp-81a203668e5e4c1a_v4_step_5', 'imp-81a203668e5e4c1a', 5, 'cook', 'Nêm gia vị và nấu chín kỹ trứng gà', 'Nêm 3 g muối ăn còn lại, 6 g hạt nêm và 12 ml nước mắm còn lại vào nồi, khuấy nhẹ tay và giữ lửa nhỏ đun thêm 1–2 phút cho các dải trứng chín hoàn toàn mà vẫn mềm mịn.', NULL, 2),
('imp-81a203668e5e4c1a_v4_step_6', 'imp-81a203668e5e4c1a', 6, 'finish', 'Rắc hành lá, tiêu xay và dùng nóng', 'Nếm lại nước canh lần cuối cho vừa miệng rồi tắt bếp ngay để vân trứng giữ độ mềm béo. Múc canh ra tô lớn, rắc hành lá thái nhỏ và 1 g tiêu đen xay lên trên, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-6c20dba60d77bdfd_v4_step_1', 'imp-6c20dba60d77bdfd', 1, 'prep', 'Chần sạch sườn non khử mùi hôi', 'Rửa sạch 500 g sườn non đã chặt khúc dài 3–4 cm. Đun sôi một nồi nước riêng pha 3 g muối ăn, thả sườn vào chần khoảng 3 phút trên lửa lớn cho ra hết bọt bẩn và tạp chất, sau đó vớt ra xả sạch lại dưới vòi nước lạnh, để ráo.', 'Chần sơ sườn với chút muối rồi rửa sạch lại là bí quyết giúp nước canh sau khi ninh trong veo và thơm ngọt.', 3),
('imp-6c20dba60d77bdfd_v4_step_2', 'imp-6c20dba60d77bdfd', 2, 'cook', 'Ninh sườn non cùng hành khô cho mềm ngọt', 'Cho sườn non đã chần vào nồi cùng 1,4 lít nước lọc và 20 g hành tím khô đập dập. Đun sôi trên lửa lớn, hớt sạch lớp bọt nổi trên mặt rồi hạ xuống lửa nhỏ liu riu, mở hé nắp và hầm trong 32–35 phút cho đến khi thịt sườn mềm róc xương và nước dùng ngọt đậm; dùng vá vớt bỏ xác hành tím khô.', 'Hầm sườn ở lửa nhỏ liu riu và không nêm mắm muối quá sớm giúp thịt sườn mềm tơi và nước hầm thật trong.', 35),
('imp-6c20dba60d77bdfd_v4_step_3', 'imp-6c20dba60d77bdfd', 3, 'prep', 'Sơ chế su su non, cà rốt và rau thơm', 'Trong lúc hầm sườn, gọt vỏ 3 quả su su non dưới vòi nước chảy nhẹ cho trôi sạch nhựa mủ không dính tay, bổ miếng cau vừa ăn rồi ngâm ngay vào chậu nước pha 2 g muối ăn khoảng 5 phút cho su su trắng giòn, sau đó vớt ra để ráo. Gọt vỏ 0,75 củ cà rốt thái miếng dày 1 cm; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('imp-6c20dba60d77bdfd_v4_step_4', 'imp-6c20dba60d77bdfd', 4, 'cook', 'Nấu chín cà rốt và su su non giòn ngọt', 'Vặn lửa vừa cho nồi nước hầm sườn sôi lại, thả cà rốt vào nấu trước 3 phút. Tiếp theo thả toàn bộ su su non vào nồi và nấu thêm 5 phút đến khi su su và cà rốt vừa chín tới, xiên nhẹ thấy mềm nhưng miếng su su vẫn giữ nguyên dáng và độ giòn ngọt.', 'Không nấu su su quá lâu kẻo rau bị nhũn nát và mất đi vị thanh mát tự nhiên.', 8),
('imp-6c20dba60d77bdfd_v4_step_5', 'imp-6c20dba60d77bdfd', 5, 'cook', 'Nêm gia vị và nước mắm sau cùng', 'Nêm 3 g muối ăn còn lại và 10 g hạt nêm vào nồi canh, khuấy nhẹ cho tan đều rồi nếm thử lại cho vừa miệng. Cuối cùng rưới 15 ml nước mắm ngon vào khuấy nhẹ một lượt cho dậy mùi thơm rồi tắt bếp.', NULL, NULL),
('imp-6c20dba60d77bdfd_v4_step_6', 'imp-6c20dba60d77bdfd', 6, 'finish', 'Rắc hành ngò, tiêu xay và dọn nóng', 'Thả hành lá và ngò rí thái nhỏ vào nồi canh đang nóng, múc ra tô lớn, rắc 2 g tiêu đen xay lên mặt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-734cc9acf8620c69_v4_step_1', 'imp-734cc9acf8620c69', 1, 'prep', 'Sơ chế đậu phụ non, cà chua và rau thơm', 'Nhẹ nhàng lấy 300 g đậu phụ non ra khỏi hộp, tráng qua nước lọc cho ráo rồi cắt khối vuông cạnh khoảng 2 cm. Rửa sạch 2 quả cà chua chín đỏ, bỏ cuống, cắt múi cau (giữ 1 quả thái miếng vừa ăn, 1 quả cắt hạt lựu nhỏ để xào nhanh tạo màu). Bóc vỏ và băm nhỏ 20 g hành tím; rửa sạch 1/2 bó hành lá và 10 g ngò rí rồi thái nhỏ.', 'Đậu phụ non rất mềm và dễ vỡ, nên đặt trên thớt phẳng dùng dao sắc cắt dứt khoát và giữ nguyên trên thớt hoặc đĩa đến khi cho vào nồi.', NULL),
('imp-734cc9acf8620c69_v4_step_2', 'imp-734cc9acf8620c69', 2, 'prep', 'Đánh tan trứng gà với chút tiêu', 'Đập 2 quả trứng gà ta vào bát sạch, thêm khoảng 0,5 g tiêu đen xay rồi dùng đũa đánh đều tay khoảng 30 giây cho lòng đỏ và lòng trắng hòa quyện hoàn toàn, không còn vón sợi đặc.', NULL, NULL),
('imp-734cc9acf8620c69_v4_step_3', 'imp-734cc9acf8620c69', 3, 'cook', 'Phi thơm hành tím và xào cà chua tạo màu', 'Đặt nồi lên bếp ở lửa vừa, cho 15 ml dầu ăn vào làm nóng rồi thả hành tím băm và phần đầu hành lá vào phi khoảng 1 phút đến khi dậy mùi thơm vàng nhẹ. Cho phần cà chua cắt hạt lựu cùng 3 g muối ăn vào xào đều tay 3 phút đến khi cà chua nhuyễn mềm, tiết nước sốt đỏ cam óng ả.', 'Thêm muối khi xào giúp cà chua nhanh ra nước và lên màu đỏ đẹp hơn mà không bị khô cháy.', 3),
('imp-734cc9acf8620c69_v4_step_4', 'imp-734cc9acf8620c69', 4, 'cook', 'Đun sôi nước dùng và nêm gia vị', 'Đổ 1200 ml nước lọc vào nồi cà chua xào, tăng lên lửa lớn đun sôi bùng khoảng 4 phút rồi dùng muỗng hớt sạch bọt nổi để nước canh trong. Cho phần cà chua bổ múi cau còn lại vào, nêm 5 g hạt nêm, 3 g đường cát trắng và 15 ml nước mắm ngon, khuấy nhẹ cho gia vị tan đều.', NULL, 4),
('imp-734cc9acf8620c69_v4_step_5', 'imp-734cc9acf8620c69', 5, 'cook', 'Thả đậu phụ non và rưới trứng tạo vân hoa', 'Hạ xuống lửa nhỏ để nước chỉ sôi lăn tăn, trượt nhẹ từng miếng đậu phụ non vào nồi nấu 3 phút cho đậu nóng đều và thấm vị. Giữ nước sôi nhẹ, khuấy nước canh theo một chiều tạo xoáy nhẹ rồi từ từ rót bát trứng gà đã đánh tan qua đầu đũa theo vòng tròn, đợi 1 phút cho sợi trứng chín nổi bồng bềnh thành vân hoa vàng.', 'Rót trứng từ từ theo dòng nhỏ trong khi nước đang sôi lăn tăn và khuấy nhẹ một chiều sẽ tạo sợi vân trứng tơ mịn, không bị vón cục hay đục nước.', 3),
('imp-734cc9acf8620c69_v4_step_6', 'imp-734cc9acf8620c69', 6, 'finish', 'Thêm hành ngò và hoàn thiện món canh', 'Kiểm tra trứng gà và đậu phụ đã chín nóng hoàn toàn thì tắt bếp ngay, rắc phần hành lá thái nhỏ và ngò rí vào nồi rồi lắc nhẹ nồi thay vì khuấy mạnh. Múc canh ra tô lớn, rắc thêm 1 g tiêu đen xay còn lại lên mặt để dậy hương thơm trước khi dọn cơm.', NULL, NULL),
('imp-095cff5e61d32fd9_v4_step_1', 'imp-095cff5e61d32fd9', 1, 'prep', 'Thái mỏng và ướp thịt bò thăn', 'Thấm thật khô 350 g thịt bò thăn, thái lát mỏng ngang thớ để khi nấu thịt mềm không bị dai. Cho thịt bò vào tô, ướp với một nửa lượng hành tím băm (12 g), 5 ml nước tương, 5 ml dầu hào, 2,5 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay, trộn đều rồi để nghỉ 15 phút cho thấm vị.', 'Có thể đặt miếng thịt bò vào ngăn đá khoảng 20–30 phút cho bề mặt hơi se cứng trước khi thái sẽ dễ cắt được lát mỏng đều đẹp.', 15),
('imp-095cff5e61d32fd9_v4_step_2', 'imp-095cff5e61d32fd9', 2, 'prep', 'Sơ chế cà chua và các loại rau thơm', 'Rửa sạch 4 quả cà chua chín đỏ, bỏ cuống, bổ múi cau (riêng 1 quả thái hạt lựu để xào tạo màu, 3 quả giữ nguyên múi). Rửa sạch 3/4 bó hành lá, 20 g rau răm và 10 g ngò gai; đầu hành băm nhỏ, lá hành cắt khúc 1,5 cm, rau răm và ngò gai thái rối.', NULL, NULL),
('imp-095cff5e61d32fd9_v4_step_3', 'imp-095cff5e61d32fd9', 3, 'cook', 'Phi thơm hành tím và xào cà chua ra màu', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn, cho phần hành tím băm còn lại cùng đầu hành lá vào phi khoảng 1 phút cho vàng thơm. Trút phần cà chua thái hạt lựu vào xào đều 3 phút đến khi cà chua mềm nhuyễn, ra màu đỏ cam tự nhiên.', 'Không để hành tím cháy sậm vì sẽ làm nước canh bị ngả màu tối và có vị đắng nhẹ.', 3),
('imp-095cff5e61d32fd9_v4_step_4', 'imp-095cff5e61d32fd9', 4, 'cook', 'Nấu nước dùng cà chua chua ngọt', 'Đổ 1500 ml nước lọc vào nồi, bật lửa lớn đun sôi khoảng 5 phút rồi hớt sạch bọt nổi. Thả 3 quả cà chua bổ múi cau vào nấu thêm 2 phút trên lửa vừa, nêm 3 g muối ăn, 2,5 g hạt nêm còn lại và 4 g đường cát trắng sao cho nước dùng có vị chua dịu ngọt thanh hài hòa.', NULL, 5),
('imp-095cff5e61d32fd9_v4_step_5', 'imp-095cff5e61d32fd9', 5, 'cook', 'Trụng chín nhanh thịt bò trong nước sôi', 'Đẩy nhẹ lửa lên mức lớn cho nước canh sôi bùng, thả từng phần thịt bò đã ướp vào nồi và dùng đũa đảo tơi ngay để thịt không dính cục. Nấu nhanh khoảng 40–60 giây đến khi miếng thịt bò vừa chuyển màu chín đều, hết sắc đỏ sống nhưng vẫn mềm mọng thì tắt bếp lập tức.', 'Thịt bò thăn chín rất nhanh; nấu quá 2 phút thịt sẽ bị ra nước, co cứng và dai, làm mất độ ngọt tự nhiên.', NULL),
('imp-095cff5e61d32fd9_v4_step_6', 'imp-095cff5e61d32fd9', 6, 'finish', 'Hoàn thiện với rau răm, ngò gai và tiêu', 'Cho hành lá cắt khúc, rau răm và ngò gai vào nồi canh nóng, đảo nhẹ một lượt cho rau thơm vừa chín tái dậy mùi đặc trưng. Múc canh ra tô lớn, rắc 0,5 g tiêu đen xay còn lại lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-a4822c0a1187e4d7_v4_step_1', 'imp-a4822c0a1187e4d7', 1, 'prep', 'Làm sạch, chần sơ và khía nhẹ sườn non', 'Rửa sạch 800 g sườn non với 4 g muối hạt, chặt khúc vừa ăn cỡ 4–5 cm rồi chần qua nồi nước sôi pha 4 g muối trong 3 phút để khử mùi hôi và làm sạch bọt bẩn. Vớt sườn ra rửa lại nước lạnh, thấm thật khô và khía nhẹ vài đường trên mặt thịt để nhanh thấm gia vị.', 'Chần sơ sườn giúp loại bỏ tạp chất và giữ phần thịt bên trong mềm ẩm hơn khi nướng ở nhiệt độ cao.', 3),
('imp-a4822c0a1187e4d7_v4_step_2', 'imp-a4822c0a1187e4d7', 2, 'marinate', 'Giã muối ớt và ướp sườn thấm vị', 'Giã nhuyễn 4 g muối hạt còn lại cùng 3 quả ớt hiểm, tỏi khô và hành tím băm nhỏ. Trộn hỗn hợp muối ớt này với 20 ml nước mắm, 15 g đường cát trắng, 2 g tiêu đen xay và 15 ml dầu ăn cho tan đều, xoa khắp từng khúc sườn, bọc kín ướp ít nhất 40 phút.', 'Ướp thêm 15 ml dầu ăn trực tiếp vào sườn giúp bề mặt thịt giữ ẩm, không bị khô cứng khi nướng.', 40),
('imp-a4822c0a1187e4d7_v4_step_3', 'imp-a4822c0a1187e4d7', 3, 'sauce', 'Pha nước chấm chanh ớt tiêu ăn kèm', 'Trong lúc chờ sườn ngấm, khuấy tan 20 g đường cát trắng với 30 ml nước lọc ấm và nước cốt của 1 quả chanh tươi (chừa lại một ít để vắt lên sườn nếu thích). Cho tiếp 15 ml nước mắm ngon, 1 quả ớt hiểm băm nhỏ và 1 g tiêu đen xay vào khuấy đều.', NULL, NULL),
('imp-a4822c0a1187e4d7_v4_step_4', 'imp-a4822c0a1187e4d7', 4, 'cook', 'Làm nóng lò và nướng sườn mặt thứ nhất', 'Làm nóng lò nướng hoặc nồi chiên không dầu ở 200°C trước 10 phút. Xếp sườn lên vỉ nướng có lót giấy bạc hứng mỡ bên dưới, phết nhẹ một lớp dầu ăn trong phần 10 ml dầu còn lại và nướng 15 phút.', NULL, 15),
('imp-a4822c0a1187e4d7_v4_step_5', 'imp-a4822c0a1187e4d7', 5, 'cook', 'Lật mặt, phết sốt và nướng vàng cháy cạnh', 'Mở lò lật mặt sườn, phết phần dầu ăn còn lại cùng lớp nước ướp sườn mỏng lên bề mặt rồi nướng tiếp 12–15 phút ở 200°C cho đến khi hai mặt sườn vàng ruộm, xém cạnh thơm lừng và phần thịt sát xương chín hoàn toàn không còn đỏ.', 'Canh kỹ 5 phút cuối và trở đều mặt giúp lớp gia vị muối ớt bám thơm mà không bị cháy đen đắng.', 15),
('imp-a4822c0a1187e4d7_v4_step_6', 'imp-a4822c0a1187e4d7', 6, 'finish', 'Để sườn nghỉ giữ ngọt và dọn thưởng thức', 'Lấy sườn nướng ra khỏi lò, để nghỉ 5 phút trên đĩa cho nước thịt ổn định lại bên trong trước khi xếp ra bàn. Dọn sườn nướng muối ớt dùng nóng kèm chén nước chấm chua cay vừa pha và cơm trắng.', NULL, NULL),
('imp-04514fa34052d242_v4_step_1', 'imp-04514fa34052d242', 1, 'prep', 'Ngâm nấm hương khô và sơ chế gà, nấm đùi gà', 'Ngâm 30 g nấm hương khô vào 100 ml nước lọc ấm trong 25 phút cho nở mềm, vớt ra cắt bỏ chân cứng rồi thái đôi và giữ lại phần nước ngâm sạch cặn. Chà xát 700 g đùi gà với 5 g muối hạt, rửa sạch để ráo rồi chặt miếng vừa ăn. Nấm đùi gà thái lát dày 0,8 cm; tỏi băm nhỏ, gừng thái lát; hành lá và cần tây cắt khúc 3 cm, ớt sừng thái lát.', 'Giữ lại phần nước ngâm nấm hương đã lắng cặn để chế vào nồi kho giúp món ăn thơm ngọt tự nhiên gấp bội.', 25),
('imp-04514fa34052d242_v4_step_2', 'imp-04514fa34052d242', 2, 'marinate', 'Ướp đùi gà với nước tương và nước mắm', 'Cho thịt gà vào tô, ướp cùng 15 ml nước tương, 5 ml xì dầu đặc và 10 ml nước mắm ngon. Trộn đều rồi ướp trong 25 phút cho miếng thịt ngấm gia vị và lên màu nhạt.', 'Khứa nhẹ vài đường trên mặt thịt đùi gà trước khi ướp giúp nước tương thấm sâu vào bên trong thớ thịt.', 25),
('imp-04514fa34052d242_v4_step_3', 'imp-04514fa34052d242', 3, 'cook', 'Áp chảo xém vàng hai mặt thịt gà', 'Làm nóng chảo đáy rộng với 15 ml dầu ăn trên lửa vừa lớn, xếp các miếng gà đã ướp vào áp chảo khoảng 4 phút mỗi mặt đến khi da gà vàng giòn và thịt săn lại rồi gắp ra đĩa riêng.', 'Áp chảo xém mặt giúp khóa chặt nước ngọt bên trong miếng gà và làm phần mỡ dưới da tiết bớt, món kho không bị ngấy.', 5),
('imp-04514fa34052d242_v4_step_4', 'imp-04514fa34052d242', 4, 'cook', 'Phi thơm gừng tỏi bằng dầu mè và đảo nấm', 'Chắt bớt dầu thừa trong chảo, cho 20 ml dầu mè vào đun nóng trên lửa vừa rồi phi thơm gừng thái lát và tỏi băm trong 1 phút. Thả nấm đùi gà và nấm hương đã ngâm vào đảo đều 3 phút cho nấm thấm dầu mè thơm bóng.', NULL, 4),
('imp-04514fa34052d242_v4_step_5', 'imp-04514fa34052d242', 5, 'cook', 'Kho nhỏ lửa cho gà và nấm thấm sốt sánh', 'Trút phần gà đã áp chảo trở lại chảo nấm, nêm 15 ml nước tương còn lại, 10 ml xì dầu đặc, 20 ml dầu hào, 12 g đường phèn và rưới phần nước ngâm nấm cùng 80 ml nước lọc vào xâm xấp. Đậy nắp kho lửa nhỏ trong 12 phút đến khi đường phèn tan hết, thịt gà chín kỹ và nước kho sánh đậm.', NULL, 12),
('imp-04514fa34052d242_v4_step_6', 'imp-04514fa34052d242', 6, 'finish', 'Thêm cần tây, hành lá và ớt hoàn thiện', 'Mở nắp, nêm lại vừa khẩu vị rồi thả cần tây, hành lá cắt khúc và ớt sừng thái lát vào đảo nhanh 30 giây trên lửa vừa đến khi rau vừa chín tái giữ màu xanh mướt. Tắt bếp và dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-695f59248dbf4895_v4_step_1', 'imp-695f59248dbf4895', 1, 'prep', 'Làm sạch nhớt và ướp muối cho cá săn chắc', 'Đánh vảy, bỏ ruột và màng đen trong bụng 750 g cá lóc, chà xát đều với 4 g muối hạt rồi rửa sạch nước lạnh và thấm khô, cắt khoanh dày 2–2,5 cm. Xóc nhẹ cá với 3 g muối hạt còn lại và ướp trong 25 phút cho thớ thịt cá săn chắc.', 'Ướp trước với chút muối giúp thịt cá cứng cáp khi chiên và thấm vị mặn đậm đà từ bên trong.', 25),
('imp-695f59248dbf4895_v4_step_2', 'imp-695f59248dbf4895', 2, 'prep', 'Giã gừng, băm sả, hành tím và ớt', 'Giã nhuyễn 50 g gừng tươi trong cối để tinh dầu gừng tiết ra tối đa. Băm thật nhuyễn 3 cây sả cùng 1 quả ớt hiểm; hành tím băm nhỏ; 2 quả ớt còn lại cắt khoanh xéo và hành lá thái nhỏ.', NULL, NULL),
('imp-695f59248dbf4895_v4_step_3', 'imp-695f59248dbf4895', 3, 'cook', 'Chiên sơ hai mặt khứa cá lóc cho săn vàng', 'Làm nóng chảo với 25 ml dầu ăn trên lửa vừa, thả từng khoanh cá vào chiên sơ khoảng 2 phút mỗi mặt cho bề mặt cá se vàng nhẹ rồi gắp ra đĩa có lót giấy thấm dầu.', 'Chiên sơ giúp khóa lớp thịt cá bên ngoài để khi kho lâu với nước sôi miếng cá vẫn giữ nguyên khoanh đẹp mắt.', 4),
('imp-695f59248dbf4895_v4_step_4', 'imp-695f59248dbf4895', 4, 'cook', 'Phi thơm hành tím, gừng sả và ớt bột', 'Dùng nồi đất hoặc nồi đáy dày, đun nóng 15 ml dầu ăn còn lại và 15 g đường cát trắng trên lửa nhỏ đến khi đường chuyển màu nâu cánh gián. Cho hành tím băm, gừng giã nhuyễn, sả băm và 2 g ớt bột khô vào xào đều trong 3 phút cho dậy mùi thơm nồng.', NULL, 3),
('imp-695f59248dbf4895_v4_step_5', 'imp-695f59248dbf4895', 5, 'cook', 'Xếp cá vào nồi và kho liu riu với nước sôi', 'Xếp từng khoanh cá đã chiên sơ lên lớp sả gừng thơm, rưới 45 ml nước mắm ngon và 10 g đường cát trắng còn lại lên mặt cá rồi đậy kín nắp 2 phút cho thấm hương. Chế 250 ml nước lọc sôi vào xâm xấp mặt cá, đun sôi lại rồi hạ lửa nhỏ kho liu riu trong 22 phút, thỉnh thoảng nghiêng nhẹ nồi cho nước kho áo đều.', 'Luôn dùng nước đang sôi chế vào nồi cá kho để cá không bị tanh và nước kho giữ được độ nóng ổn định.', 22),
('imp-695f59248dbf4895_v4_step_6', 'imp-695f59248dbf4895', 6, 'finish', 'Thả ớt khoanh, nêm lại và rắc hành lá', 'Khi nước kho rút còn khoảng một nửa và hơi sánh sệt, thả ớt cắt khoanh vào kho mở nắp thêm 3 phút cho nước keo đẹp, nêm lại vừa ăn rồi tắt bếp. Múc cá kho gừng sả ra đĩa và rắc hành lá thái nhỏ lên trên.', NULL, NULL),
('imp-208386f834b8da43_v4_step_1', 'imp-208386f834b8da43', 1, 'prep', 'Luộc trứng với giấm muối và bóc vỏ', 'Cho 8 quả trứng gà vào nồi nước lạnh ngập mặt cùng 5 g muối ăn và 15 ml giấm gạo, bật lửa vừa đến khi nước sôi thì hạ lửa nhỏ luộc thêm 7 phút cho trứng chín hoàn toàn. Vớt trứng ngâm ngay vào tô nước lạnh 3 phút rồi bóc sạch vỏ và dùng tăm xăm nhẹ vài lỗ quanh lòng trắng.', 'Thêm chút muối và giấm vào nồi nước lạnh khi luộc giúp vỏ trứng không bị nứt và tách khỏi màng lụa cực kỳ dễ dàng.', 7),
('imp-208386f834b8da43_v4_step_2', 'imp-208386f834b8da43', 2, 'prep', 'Sơ chế hành tỏi, rau thơm và pha chén sốt kho', 'Thái lát mỏng hành tím, tỏi khô và ớt tươi; cắt khúc phần đầu hành lá, thái nhỏ lá hành và ngò rí. Trong chén riêng, khuấy tan 55 ml nước tương, 15 ml xì dầu đặc, 10 ml tương ớt, 12 g đường cát trắng, 1 g bột ngũ vị hương và 100 ml nước lọc.', NULL, NULL),
('imp-208386f834b8da43_v4_step_3', 'imp-208386f834b8da43', 3, 'cook', 'Chiên sơ trứng cho vàng săn lớp vỏ ngoài', 'Thấm thật khô bề mặt trứng đã bóc vỏ. Làm nóng chảo chống dính với 15 ml dầu ăn trên lửa vừa, thả trứng vào lăn nhẹ đều tay trong 3 phút cho lớp lòng trắng bên ngoài se vàng nhẹ rồi vớt ra đĩa.', 'Thấm khô trứng trước khi chiên và đảo nhẹ liên tục giúp trứng không bị bắn dầu và có lớp vỏ dai ngon khi kho.', 3),
('imp-208386f834b8da43_v4_step_4', 'imp-208386f834b8da43', 4, 'cook', 'Phi thơm đầu hành, hành tím, tỏi và ớt', 'Chắt bớt dầu nếu còn nhiều, thêm 10 ml dầu ăn vào chảo trên lửa vừa nhỏ, phi thơm đầu hành lá, hành tím, tỏi và ớt thái lát trong 1 phút cho đến khi vừa dậy mùi và ngả vàng nhẹ thì tạm nhấc khỏi bếp để không cháy.', NULL, NULL),
('imp-208386f834b8da43_v4_step_5', 'imp-208386f834b8da43', 5, 'cook', 'Kho liu riu cho trứng áo màu nâu bóng', 'Đổ chén hỗn hợp sốt nước tương đã pha vào chảo, đặt lại lên bếp đun sôi nhẹ rồi thả toàn bộ trứng gà vào. Kho liu riu ở lửa vừa nhỏ trong 8–10 phút, thỉnh thoảng nghiêng chảo hoặc múc sốt rưới đều lên trứng cho đến khi nước kho sánh keo bóng đẹp.', 'Kho lửa nhỏ và đảo nhẹ tay giúp màu nâu của xì dầu đặc áo đều quanh từng quả trứng mà không làm nát lòng trắng.', 9),
('imp-208386f834b8da43_v4_step_6', 'imp-208386f834b8da43', 6, 'finish', 'Rắc hành lá, ngò rí và tiêu đen thưởng thức', 'Khi nước sốt đã keo sánh và trứng lên màu nâu óng ả, tắt bếp, gắp trứng ra đĩa sâu lòng và rưới phần sốt keo còn lại lên trên. Rắc hành lá, ngò rí thái nhỏ và 1,5 g tiêu đen xay rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-d1f8ab89051a6336_v4_step_1', 'imp-d1f8ab89051a6336', 1, 'marinate', 'Sơ chế và ướp tôm tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch lưng rút bỏ chỉ đen rồi rửa sạch và thấm ráo. Cho tôm vào tô ướp với 3 g hạt nêm trong 10 phút để tôm thấm vị đậm nhẹ.', NULL, 10),
('imp-d1f8ab89051a6336_v4_step_2', 'imp-d1f8ab89051a6336', 2, 'prep', 'Chần sơ bông cải xanh, cà rốt và ngâm nước lạnh', 'Tách bông cải xanh thành nhánh vừa ăn; cà rốt gọt vỏ thái lát mỏng; hành tây thái múi cau; tỏi khô băm nhỏ. Đun sôi nồi nước với 6 g muối ăn, thả cà rốt vào chần 40 giây rồi cho bông cải xanh vào chần chung thêm 1 phút, vớt ngay ra tô nước đá lạnh ngâm 3 phút rồi vớt ra để thật ráo. Hòa tan 4 g bột bắp với 30 ml nước lọc.', 'Ngâm nước đá ngay sau khi chần giúp bông cải xanh và cà rốt giữ sắc màu rực rỡ cùng độ giòn sần sật.', 3),
('imp-d1f8ab89051a6336_v4_step_3', 'imp-d1f8ab89051a6336', 3, 'cook', 'Xào săn tôm tươi trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, đun nóng 15 ml dầu ăn rồi trút tôm đã ướp vào đảo nhanh tay 1,5 phút cho đến khi tôm săn lại, chuyển màu đỏ cam đều và chín hoàn toàn thì gắp ra đĩa riêng.', 'Đảo tôm trên lửa lớn thật nhanh giúp tôm xém nhẹ thơm ngon mà không bị ra nước hay khô thịt.', 2),
('imp-d1f8ab89051a6336_v4_step_4', 'imp-d1f8ab89051a6336', 4, 'cook', 'Xào bông cải xanh và cà rốt với tỏi hành tây', 'Dùng lại chảo, thêm 10 ml dầu ăn vào đun nóng ở lửa vừa rồi phi thơm tỏi băm và hành tây trong 30 giây. Tăng lên lửa lớn, cho bông cải xanh và cà rốt đã ráo nước vào đảo đều, nêm 5 g hạt nêm còn lại và 2 g muối ăn trong khoảng 2 phút.', NULL, NULL),
('imp-d1f8ab89051a6336_v4_step_5', 'imp-d1f8ab89051a6336', 5, 'cook', 'Rưới nước bột bắp và đảo đều cùng tôm', 'Trút tôm đã xào trở lại chảo rau củ. Khuấy đều chén nước bột bắp rồi rưới từ từ vào chảo, đảo đều tay khoảng 1 phút cho lớp sốt sánh bóng áo đều quanh tôm và bông cải, thêm 5 ml nước mắm ngon nếu thích đậm vị hơn.', 'Rưới từ từ nước bột bắp và đảo liên tục để sốt sánh mịn đều, không bị vón cục.', NULL),
('imp-d1f8ab89051a6336_v4_step_6', 'imp-d1f8ab89051a6336', 6, 'finish', 'Rưới dầu mè và rắc mè trắng rang hoàn thiện', 'Rưới 3 ml dầu mè thơm vào đảo nhanh một lượt rồi tắt bếp. Bày bông cải xào tôm tươi ra đĩa, rắc tiêu đen xay và mè trắng rang lên trên, dùng nóng với cơm trắng.', NULL, NULL),
('imp-03c5e6e31e01088d_v4_step_1', 'imp-03c5e6e31e01088d', 1, 'prep', 'Cắt đậu phụ và băm nhỏ sả, tỏi, ớt', 'Đậu phụ rửa nhẹ, dùng khăn giấy thấm thật khô bề mặt rồi cắt thành từng miếng vuông dày khoảng 1,5 cm. Sả tươi bóc bỏ vỏ già, đập dập rồi băm nhuyễn phần củ non; tỏi khô băm nhuyễn; ớt chia một quả băm nhỏ và một quả thái lát xéo.', 'Băm sả thật nhuyễn giúp sả dậy mùi thơm nồng nhanh chóng và dễ bám đều lên từng miếng đậu phụ.', NULL),
('imp-03c5e6e31e01088d_v4_step_2', 'imp-03c5e6e31e01088d', 2, 'sauce', 'Pha chén sốt nước tương dầu hào chay sả ớt', 'Cho vào chén 15 ml nước tương (xì dầu), 15 ml dầu hào chay nấm đông cô, 15 ml tương ớt, 5 g đường cát trắng và 30 ml nước lọc, khuấy thật đều cho đường tan hoàn toàn.', NULL, NULL),
('imp-03c5e6e31e01088d_v4_step_3', 'imp-03c5e6e31e01088d', 3, 'cook', 'Chiên vàng giòn các mặt đậu phụ', 'Đun nóng 70 ml dầu ăn trên lửa vừa, thả nhẹ từng miếng đậu phụ vào chiên khoảng 4–5 phút mỗi mặt đến khi vỏ đậu vàng đều, hơi giòn cạnh thì vớt ra đĩa có lót giấy thấm dầu.', 'Không lật trở đậu quá sớm khi mặt dưới chưa se vàng để giữ từng miếng đậu vuông vắn đẹp mắt.', 5),
('imp-03c5e6e31e01088d_v4_step_4', 'imp-03c5e6e31e01088d', 4, 'cook', 'Phi thơm sả băm, tỏi và ớt', 'Chắt bớt dầu thừa ra ngoài, chỉ giữ lại khoảng 15 ml dầu ăn trong chảo. Hạ lửa vừa, cho sả băm, tỏi băm và ớt băm vào đảo đều tay khoảng 2 phút đến khi sả chuyển màu vàng thơm lừng.', NULL, 2),
('imp-03c5e6e31e01088d_v4_step_5', 'imp-03c5e6e31e01088d', 5, 'cook', 'Đun sánh sốt và đảo quyện đậu phụ', 'Khuấy lại chén sốt rồi rót vào chảo sả ớt, đun sôi lăn tăn khoảng 1 phút cho sốt hơi sánh lại. Trút toàn bộ đậu phụ đã chiên vào chảo, hạ lửa nhỏ và đảo nhẹ tay khoảng 4 phút để sốt sả ớt áo bám đều quanh từng miếng đậu.', 'Rim đậu phụ trên lửa nhỏ giúp lớp vỏ đậu thấm sâu nước sốt mà vẫn giữ độ dai giòn nhẹ bên ngoài.', 4),
('imp-03c5e6e31e01088d_v4_step_6', 'imp-03c5e6e31e01088d', 6, 'finish', 'Hoàn thiện với ớt lát và tiêu đen xay', 'Nêm nếm lại cho vừa khẩu vị, thả vài lát ớt thái xéo và rắc 1,5 g tiêu đen xay vào đảo nhẹ rồi tắt bếp. Bày đậu phụ xào sả ớt ra đĩa, dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-2862e7aa0ae0d8fe_v4_step_1', 'imp-2862e7aa0ae0d8fe', 1, 'marinate', 'Thái lát và ướp thịt bò đậm đà', 'Thấm thật khô thịt thăn bò rồi thái lát mỏng ngang thớ. Cho thịt vào tô ướp cùng một nửa lượng tỏi băm, 12 ml nước mắm ngon, 15 ml dầu hào, 10 g đường cát trắng, 5 g hạt nêm, 3 g muối ăn, 1 g tiêu đen xay và 5 ml dầu ăn; trộn đều và để ngấm 15 phút.', 'Không ướp chung thịt bò với dứa sống trước khi xào vì enzyme trong dứa sẽ làm thịt bò bị bở nát.', 15),
('imp-2862e7aa0ae0d8fe_v4_step_2', 'imp-2862e7aa0ae0d8fe', 2, 'prep', 'Sơ chế dứa chín, hành tây và hành lá', 'Dứa chín gọt sạch vỏ và mắt, bổ dọc bỏ phần lõi cứng ở giữa rồi thái lát dày khoảng 0,5 cm vừa ăn. Hành tây bóc vỏ bổ múi cau; hành lá rửa sạch cắt khúc 3 cm; phần tỏi còn lại băm nhỏ.', 'Bỏ sạch phần lõi cứng của quả dứa giúp món xào ngọt thơm mà không bị rát lưỡi khi ăn.', NULL),
('imp-2862e7aa0ae0d8fe_v4_step_3', 'imp-2862e7aa0ae0d8fe', 3, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Làm nóng 15 ml dầu ăn trong chảo trên lửa lớn, cho một nửa phần tỏi băm còn lại vào phi thơm. Trút thịt bò đã ướp vào đảo nhanh tay liên tục khoảng 1,5–2 phút đến khi thịt vừa chín tái 80% thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-2862e7aa0ae0d8fe_v4_step_4', 'imp-2862e7aa0ae0d8fe', 4, 'cook', 'Xào dứa chín và hành tây dậy mùi chua ngọt', 'Dùng lại chảo vừa xào bò, thêm 10 ml dầu ăn đun nóng rồi phi thơm nốt phần tỏi băm. Cho dứa và hành tây vào xào trên lửa lớn khoảng 2 phút, rưới thêm 8 ml nước mắm ngon còn lại để dứa tiết vị chua ngọt đậm đà và hành tây vừa chín trong.', 'Xào dứa trên lửa lớn giúp dứa se mặt thơm lừng mà không bị tiết quá nhiều nước.', 2),
('imp-2862e7aa0ae0d8fe_v4_step_5', 'imp-2862e7aa0ae0d8fe', 5, 'cook', 'Đảo chung thịt bò quyện sốt dứa', 'Trút đĩa thịt bò cùng nước thịt tiết ra trở lại chảo dứa hành tây, bật lửa lớn và đảo nhanh tay khoảng 1 phút cho thịt bò chín hoàn toàn và thấm đều sốt chua ngọt.', NULL, NULL),
('imp-2862e7aa0ae0d8fe_v4_step_6', 'imp-2862e7aa0ae0d8fe', 6, 'finish', 'Thêm hành lá và dọn đĩa ăn nóng', 'Thả hành lá cắt khúc vào đảo nhanh 15 giây rồi tắt bếp. Bày bò xào dứa chua ngọt ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-aa94e2f8bdf3985f_v4_step_1', 'imp-aa94e2f8bdf3985f', 1, 'prep', 'Làm sạch tôm sú và sơ chế sả, gừng, lá chanh', 'Cắt gọn râu và chân tôm sú, dùng kéo nhọn rạch nhẹ dọc sống lưng rút sạch chỉ đen rồi rửa lại bằng nước sạch, để thật ráo. Bóc bẹ già 3 cây sả: đập dập cắt khúc 2 cây và thái lát mỏng 1 cây; gừng cạo vỏ thái lát mỏng; lá chanh rửa sạch giữ một nửa nguyên lá và thái chỉ phần còn lại; 1 quả ớt hiểm thái lát, 1 quả băm nhỏ.', 'Chọn tôm sú còn sống nhảy khỏe, vỏ bóng chắc và đầu dính chặt vào thân để món hấp giữ được độ giòn ngọt tự nhiên nhất.', NULL),
('imp-aa94e2f8bdf3985f_v4_step_2', 'imp-aa94e2f8bdf3985f', 2, 'marinate', 'Ướp tôm sú cho thịt săn và đậm vị', 'Cho tôm vào tô lớn cùng 4 g muối hạt, 4 g hạt nêm và 1 g tiêu đen xay, xóc nhẹ đều tay để gia vị bám quanh vỏ và khe lưng tôm rồi ướp 15 phút.', NULL, 15),
('imp-aa94e2f8bdf3985f_v4_step_3', 'imp-aa94e2f8bdf3985f', 3, 'cook', 'Xếp xửng và hấp tôm với rượu trắng trên lửa lớn', 'Đổ 500 ml nước lọc vào đáy nồi hấp. Lót sả đập dập, gừng thái lát và lá chanh nguyên xuống mặt xửng hoặc đĩa chịu nhiệt, xếp tôm đều lên trên rồi rắc nốt sả thái lát và lá chanh thái chỉ phủ mặt. Rưới đều 45 ml rượu trắng nấu ăn lên tôm, đậy kín nắp và hấp lửa lớn 7 phút đến khi vỏ tôm đỏ au, thân cong chắc là chín tới.', 'Rưới rượu trắng ngay trước khi đậy nắp hấp trên lửa lớn giúp hơi cồn bốc qua thân tôm, khử hoàn toàn mùi tanh mà thịt tôm vẫn giữ trọn độ ngọt.', 7),
('imp-aa94e2f8bdf3985f_v4_step_4', 'imp-aa94e2f8bdf3985f', 4, 'sauce', 'Phi tỏi vàng giòn thơm lừng', 'Trong lúc chờ tôm chín, làm nóng 15 ml dầu ăn trên chảo nhỏ ở lửa vừa, cho tỏi băm nhuyễn vào đảo đều tay khoảng 2 phút đến khi tỏi vừa chuyển màu vàng nhạt thơm nức thì tắt bếp ngay, giữ cả dầu lẫn tỏi phi sang chén nhỏ.', 'Tắt bếp ngay khi tỏi vừa ngả vàng sáng để lượng dầu nóng còn lại tự làm tỏi giòn đều mà không bị đắng khét.', 2),
('imp-aa94e2f8bdf3985f_v4_step_5', 'imp-aa94e2f8bdf3985f', 5, 'sauce', 'Pha muối tiêu chanh ớt chấm tôm', 'Cho 8 g muối hạt còn lại, 1 g tiêu đen xay và 1 quả ớt hiểm băm nhỏ vào chén sạch, vắt nước cốt 1 quả chanh tươi vào rồi dùng thìa dằm nhẹ cho muối tan bớt.', NULL, NULL),
('imp-aa94e2f8bdf3985f_v4_step_6', 'imp-aa94e2f8bdf3985f', 6, 'finish', 'Rưới tỏi phi và thưởng thức tôm hấp nóng', 'Gắp tôm hấp xếp đều ra đĩa lớn, rưới phần dầu tỏi phi vàng giòn lên dọc thân từng con tôm, điểm thêm vài lát ớt hiểm và cọng sả cho bắt mắt rồi ăn nóng ngay cùng chén muối tiêu chanh ớt.', NULL, NULL),
('imp-b55451e6e46a4c13_v4_step_1', 'imp-b55451e6e46a4c13', 1, 'prep', 'Ngâm mộc nhĩ và sơ chế cà rốt, tỏi, hành lá', 'Ngâm 15 g mộc nhĩ khô trong nước ấm khoảng 15 phút cho nở mềm, cắt bỏ chân cứng, rửa sạch rồi băm nhỏ. Gọt vỏ 1/2 củ cà rốt băm hạt lựu thật nhỏ; bóc vỏ tỏi băm nhuyễn. Rửa sạch hành lá, chọn riêng 10–12 cọng lá xanh dài để buộc cuộn, phần đầu và lá còn lại thái nhỏ.', NULL, 15),
('imp-b55451e6e46a4c13_v4_step_2', 'imp-b55451e6e46a4c13', 2, 'marinate', 'Trộn và ướp dẻo nhân thịt heo xay', 'Cho 300 g thịt heo xay vào tô lớn cùng mộc nhĩ băm, cà rốt băm nhỏ, tỏi băm và phần hành lá thái nhỏ. Nêm 15 ml nước mắm, 4 g hạt nêm và 1,5 g tiêu đen xay, trộn quết đều tay 2 phút cho hỗn hợp dẻo quyện rồi để ướp 15 phút.', 'Quết nhân thịt kỹ một chiều khoảng 2 phút giúp thịt kết dính dẻo dai, không bị rời rạc hay chảy nhiều nước khi hấp.', 15),
('imp-b55451e6e46a4c13_v4_step_3', 'imp-b55451e6e46a4c13', 3, 'prep', 'Chần mềm lá bắp cải và cọng hành buộc', 'Tách nhẹ 10–12 lá bắp cải nguyên vẹn, rửa sạch rồi dùng dao lạng mỏng bớt phần sống gân trắng cứng ở gốc lá. Đun sôi 800 ml nước lọc với 4 g muối ăn, thả từng lá bắp cải vào chần nhanh 1 phút cho vừa mềm dẻo rồi vớt ngay ra thau nước mát để giữ màu xanh; tiếp tục chần cọng hành lá khoảng 20 giây rồi vớt ra để ráo.', 'Lạng mỏng phần sống gân dày và nhúng ngay lá qua nước lạnh sau khi chần giúp lá bắp cải dẻo dai, dễ cuộn chặt mà không bị rách hay ngả màu.', 2),
('imp-b55451e6e46a4c13_v4_step_4', 'imp-b55451e6e46a4c13', 4, 'prep', 'Gói cuộn bắp cải nhân thịt chắc tay', 'Trải phẳng từng lá bắp cải lên thớt sạch, đặt khoảng 1 muỗng canh đầy nhân thịt vào phần đầu lá gần gốc. Gấp hai mép lá hai bên vào trong rồi cuộn tròn đều tay như cuốn nem, dùng một cọng hành lá đã chần buộc nhẹ quanh thân cuộn để cố định.', NULL, NULL),
('imp-b55451e6e46a4c13_v4_step_5', 'imp-b55451e6e46a4c13', 5, 'cook', 'Hấp cách thủy bắp cải cuộn thịt chín đều', 'Đổ 600 ml nước lọc vào đáy nồi hấp, đun sôi mạnh. Xếp các cuộn bắp cải ngay ngắn vào đĩa sâu lòng hoặc trực tiếp lên xửng hấp sao cho không chồng đè quá dày, đậy kín nắp và hấp trên lửa vừa khoảng 20 phút đến khi lá bắp cải chín mềm và nhân thịt bên trong chín hẳn, không còn màu hồng.', 'Xếp cuộn bắp cải với mép gấp úp xuống dưới giúp các cuộn giữ dáng tròn đẹp mà không bị bung khi gặp hơi nóng.', 20),
('imp-b55451e6e46a4c13_v4_step_6', 'imp-b55451e6e46a4c13', 6, 'finish', 'Trình bày và dọn ăn nóng với nước chấm', 'Gắp các cuộn bắp cải hấp ra đĩa lớn, rưới thêm vài muỗng nước ngọt thanh tiết ra trong đĩa hấp lên trên và rắc 0,5 g tiêu đen xay còn lại; dọn dùng nóng kèm cơm trắng và chén nước tương ớt hoặc nước mắm chanh tỏi ớt.', NULL, NULL),
('imp-500644420438efd3_v4_step_1', 'imp-500644420438efd3', 1, 'prep', 'Sơ chế đậu phụ trắng, sả, hành lá và ớt', 'Rửa nhẹ 3 bìa đậu phụ dưới vòi nước mát, để thật ráo rồi cắt thành từng miếng vuông dày khoảng 1,5 cm. Bóc vỏ già 3 cây sả: băm nhuyễn 2 cây, đập dập cắt khúc 4 cm với 1 cây còn lại. Rửa sạch hành lá thái nhỏ và thái lát mỏng 2 quả ớt tươi.', 'Chọn bìa đậu phụ mới làm có mùi thơm nhẹ, cầm mềm mại và đàn hồi để khi hấp đậu giữ được vị béo mịn tự nhiên.', NULL),
('imp-500644420438efd3_v4_step_2', 'imp-500644420438efd3', 2, 'marinate', 'Ướp đậu phụ với xì dầu, đường và hạt nêm chay', 'Xếp các miếng đậu phụ vào đĩa sâu lòng chịu nhiệt (lót sả đập dập bên dưới). Hòa tan 25 ml xì dầu, 6 g hạt nêm chay nấm hương và 3 g đường cát trắng rồi rưới đều lên mặt các miếng đậu, để nghỉ 10 phút cho gia vị thấm nhẹ vào thớ đậu.', NULL, 10),
('imp-500644420438efd3_v4_step_3', 'imp-500644420438efd3', 3, 'cook', 'Xào sả băm dậy mùi thơm vàng nhẹ', 'Làm nóng 15 ml dầu ăn trên chảo nhỏ ở lửa vừa, cho phần sả băm nhuyễn vào đảo đều tay khoảng 2 phút đến khi sả săn lại, ngả vàng nhẹ và dậy mùi thơm nồng thì tắt bếp.', 'Xào chín thơm sả băm trước khi hấp giúp tinh dầu sả tiết ra quyện vào nước xì dầu, khử bớt vị hăng sống của sả.', 2),
('imp-500644420438efd3_v4_step_4', 'imp-500644420438efd3', 4, 'cook', 'Hấp cách thủy đậu phụ thấm hương sả ớt', 'Rải đều phần sả băm đã xào thơm cùng ớt tươi thái lát lên mặt từng miếng đậu phụ. Đun sôi 500 ml nước lọc trong nồi hấp, đặt đĩa đậu vào xửng, đậy kín nắp và hấp ở lửa vừa trong 12 phút cho đậu nóng mềm và thấm đẫm hương sả.', 'Không hấp đậu phụ ở lửa quá lớn quá lâu vì hơi nước sôi mạnh dễ làm mặt đậu bị rỗ bọt khí.', 12),
('imp-500644420438efd3_v4_step_5', 'imp-500644420438efd3', 5, 'cook', 'Rắc hành lá giữ sắc xanh tươi', 'Mở nắp nồi hấp, rắc đều phần hành lá thái nhỏ lên trên mặt các miếng đậu phụ rồi đậy nắp hấp thêm khoảng 30 giây cho hành vừa chín tái xanh mướt, sau đó tắt bếp.', NULL, NULL),
('imp-500644420438efd3_v4_step_6', 'imp-500644420438efd3', 6, 'finish', 'Rưới dầu mè thơm và dọn dùng nóng', 'Nhấc đĩa đậu phụ ra khỏi xửng hấp cẩn thận, rưới đều 5 ml dầu mè thơm lên trên mặt đĩa cho dậy mùi và bóng đẹp, dọn ăn nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-47cbfe72125b811d_v4_step_1', 'imp-47cbfe72125b811d', 1, 'marinate', 'Thái mỏng và ướp thấm thịt bò thăn', 'Thái thịt bò thăn thành lát thật mỏng ngang thớ. Cho thịt bò vào tô, ướp với 5 g hạt nêm, 1 g muối ăn, 2 g tiêu đen xay, 5 ml dầu ăn và một ít tỏi băm trong 20 phút cho thấm đều và mềm thịt.', 'Thái thịt bò ngang thớ khi thịt còn hơi se lạnh giúp lát bò mỏng đều và không bị dai khi xào.', 20),
('imp-47cbfe72125b811d_v4_step_2', 'imp-47cbfe72125b811d', 2, 'prep', 'Sơ chế dưa leo, cà rốt và ngâm giòn hành tây', 'Rửa sạch dưa leo, chà nhẹ hai đầu khử nhựa, bỏ ruột và thái lát xéo mỏng. Cà rốt gọt vỏ bào sợi, trộn 4 g đường cát trắng để 10 phút rồi vắt ráo. Hành tây thái lát mỏng, ngâm nước lạnh 10 phút rồi trộn 3 g muối ăn, 4 g đường cát trắng và 10 ml giấm gạo trong 10 phút nữa trước khi vắt ráo.', 'Bỏ ruột dưa leo và vắt ráo cà rốt, hành tây giúp đĩa gỏi khô ráo, giữ độ giòn lâu.', 10),
('imp-47cbfe72125b811d_v4_step_3', 'imp-47cbfe72125b811d', 3, 'prep', 'Rang giã đậu phộng và cắt nhỏ rau thơm', 'Rang chín vàng đậu phộng trên lửa nhỏ, xát sạch vỏ lụa và giã dập vừa. Nhặt rửa sạch ngò rí, rau húng bạc hà và hành lá rồi cắt nhỏ. Chuẩn bị phần tỏi băm còn lại và ớt hiểm thái lát, băm nhuyễn.', NULL, NULL),
('imp-47cbfe72125b811d_v4_step_4', 'imp-47cbfe72125b811d', 4, 'cook', 'Xào nhanh thịt bò trên lửa lớn', 'Đun nóng chảo trên lửa lớn với 20 ml dầu ăn, cho nửa phần tỏi băm vào phi thơm. Trút thịt bò đã ướp vào đảo thật nhanh tay khoảng 2 phút đến khi thịt bò vừa chín đều mềm mọng, không còn màu đỏ sống và không tiết nước thì trút ngay ra đĩa.', 'Xào bò ở lửa lớn trong thời gian ngắn giúp thịt chín mềm ngọt mà không bị ra nước hay dai cứng.', 2),
('imp-47cbfe72125b811d_v4_step_5', 'imp-47cbfe72125b811d', 5, 'sauce', 'Pha nước trộn gỏi mắm chanh chua ngọt', 'Khuấy tan 45 ml nước mắm ngon với 30 g đường cát trắng, nước cốt 2 quả chanh tươi và 5 ml giấm gạo còn lại, thêm phần tỏi băm và 1 quả ớt hiểm băm nhuyễn vào đảo đều đến khi sánh thơm.', NULL, NULL),
('imp-47cbfe72125b811d_v4_step_6', 'imp-47cbfe72125b811d', 6, 'finish', 'Trộn gỏi bò thấm vị và trình bày ra đĩa', 'Cho thịt bò xào, dưa leo, cà rốt và hành tây đã vắt ráo vào âu lớn, rưới đều nước trộn vào đảo nhẹ tay và để 5 phút cho ngấm vị. Tiếp tục trộn ngò rí, rau húng bạc hà, hành lá và một nửa lượng đậu phộng rang giã dập. Bày gỏi ra đĩa, rắc phần đậu phộng còn lại cùng vài lát ớt hiểm lên trên.', NULL, NULL),
('imp-403a1693ea9b3cf8_v4_step_1', 'imp-403a1693ea9b3cf8', 1, 'prep', 'Chần và hầm xương ống heo lấy nước dùng', 'Rửa sạch xương ống heo, chần qua 400 ml nước sôi với 4 g muối ăn trong 5 phút rồi xả sạch dưới vòi nước lạnh. Cho xương vào nồi với 1,9 lít nước lọc, đun sôi rồi hạ lửa nhỏ hầm khoảng 45 phút, thường xuyên hớt bọt rồi lọc bỏ xương giữ phần nước dùng trong.', NULL, 45),
('imp-403a1693ea9b3cf8_v4_step_2', 'imp-403a1693ea9b3cf8', 2, 'prep', 'Sơ chế tôm tươi, rau muống chẻ và lọc me', 'Tôm tươi bóc vỏ, giữ lại phần đầu tôm riêng và rút sạch chỉ đen thân tôm; ướp thân tôm với 2 g hạt nêm và 1 g tiêu đen xay trong 10 phút. Ngâm 40 g me chín với 100 ml nước ấm trong 5 phút rồi dằm lọc bỏ hạt lấy nước cốt. Chẻ sợi rau muống ngâm nước cho giòn; thái lát cà chua, dứa, đập dập sả cây và băm hành tím, tỏi khô.', 'Giữ lại đầu tôm để phi xào trước khi nấu giúp nước dùng có vị ngọt đậm và màu gạch tôm tự nhiên.', 10),
('imp-403a1693ea9b3cf8_v4_step_3', 'imp-403a1693ea9b3cf8', 3, 'cook', 'Phi hành giòn và xào đầu tôm cùng cà chua dứa', 'Đun nóng 30 ml dầu ăn trên chảo lửa vừa, phi vàng giòn 15 g hành tím thái lát rồi vớt ra giấy thấm dầu. Dùng phần dầu còn lại phi thơm 30 g hành tím băm và tỏi băm, cho đầu tôm vào đảo nhanh 2 phút cho dậy mùi gạch đỏ rồi gắp bỏ đầu tôm. Tiếp tục cho cà chua, dứa và sả đập dập vào xào 4 phút với 10 ml nước mắm và 10 g đường cát trắng.', 'Phi hành trước rồi tận dụng dầu thơm để xào đầu tôm và cà chua giúp nước dùng không bị ngấy dầu mà cực kỳ dậy mùi.', 6),
('imp-403a1693ea9b3cf8_v4_step_4', 'imp-403a1693ea9b3cf8', 4, 'cook', 'Nấu nước dùng chua cay và luộc chín tôm', 'Trút phần cà chua, dứa và sả đã xào vào nồi nước dùng xương, đổ nước cốt me vào đun sôi. Nêm 40 ml nước mắm ngon, 25 g đường cát trắng, 6 g muối ăn còn lại, 4 g hạt nêm, 20 ml sa tế ớt, 2 quả ớt đập dập và 10 ml dầu màu điều cho vị chua cay mặn ngọt hài hòa. Khi nước sôi bùng, thả thân tôm đã ướp vào nấu khoảng 3 phút đến khi tôm chuyển màu hồng cam uốn cong chín kỹ thì vớt ra ngay.', 'Vớt tôm ngay sau 3 phút nấu chín tới giúp thịt tôm giòn ngọt, không bị bở hoặc teo nhỏ.', 5),
('imp-403a1693ea9b3cf8_v4_step_5', 'imp-403a1693ea9b3cf8', 5, 'prep', 'Trụng bún tươi và xếp rau muống ra tô', 'Đun sôi một nồi nước khác, trụng nhanh bún gạo tươi khoảng 1 phút cho sợi bún nóng tơi rồi vớt ra để ráo. Chia đều bún vào 4 tô lớn, xếp phần rau muống chẻ giòn và tôm tươi đã nấu chín lên trên mặt bún.', NULL, NULL),
('imp-403a1693ea9b3cf8_v4_step_6', 'imp-403a1693ea9b3cf8', 6, 'finish', 'Chan nước dùng nóng và thưởng thức', 'Chan nước dùng bún tôm chua cay đang sôi sùng sục ngập mặt bún, rắc hành lá, ngò rí, hành phi và 1 g tiêu đen xay còn lại lên trên. Dọn nóng ngay kèm chanh tươi cắt múi và ớt tươi thái lát để điều chỉnh vị chua cay.', NULL, NULL),
('imp-c039dac37b31acdb_v4_step_1', 'imp-c039dac37b31acdb', 1, 'marinate', 'Sơ chế và ướp thịt gà ta với nghệ', 'Chà xát gà ta với 5 g muối ăn rồi rửa sạch, thấm khô. Lọc lấy phần thịt gà chặt miếng vừa ăn; giữ riêng xương, cổ và cánh gà để ninh nước dùng. Ướp thịt gà với 30 g hành tím giã nhỏ, 10 g tỏi khô băm, 1 quả ớt tươi băm, 5 g bột nghệ, 20 ml nước mắm ngon, 5 g muối ăn, 10 g đường cát trắng, 10 g hạt nêm và 2 g tiêu đen xay trong 20 phút cho ngấm sâu.', 'Tách riêng phần thịt và xương gà giúp thịt gà xào chín mềm ngọt mà vẫn có nồi nước dùng xương đậm đà.', 20),
('imp-c039dac37b31acdb_v4_step_2', 'imp-c039dac37b31acdb', 2, 'cook', 'Hầm xương gà lấy nước dùng trong', 'Cho phần xương, cổ và cánh gà vào nồi với 1,2 lít nước lọc, đun sôi trên lửa lớn, hớt sạch bọt rồi hạ lửa nhỏ ninh khoảng 35 phút cho ngọt nước; vớt bỏ xác xương để thu khoảng 900 ml nước dùng gà.', NULL, 35),
('imp-c039dac37b31acdb_v4_step_3', 'imp-c039dac37b31acdb', 3, 'cook', 'Phi thơm gia vị và nấu nước nhân gà ta', 'Đun nóng 25 ml dầu ăn trong nồi rộng ở lửa vừa, cho 3 g ớt bột màu vào đảo nhanh 10 giây rồi phi thơm 30 g hành tím băm còn lại và sả cây băm. Trút thịt gà đã ướp vào xào săn đều các mặt trong 4 phút, sau đó chế 900 ml nước dùng gà vào đun sôi và hạ lửa nhỏ rim 18 phút đến khi gà chín mềm thấm đẫm gia vị. Nêm thêm 15 ml nước mắm ngon và 15 ml dầu màu điều, thả đầu hành lá vào rồi tắt bếp.', 'Nước nhân Mì Quảng chuẩn vị cần đậm đà hơn nước phở bún thông thường vì khi chan chỉ ngập xâm xấp mặt mì.', 22),
('imp-c039dac37b31acdb_v4_step_4', 'imp-c039dac37b31acdb', 4, 'prep', 'Sơ chế rau sống, đậu phộng và pha nước chấm', 'Rửa sạch xà lách, giá đỗ, rau húng lủi; ngâm bắp chuối bào với nước có vắt ít nước cốt chanh tươi để giữ màu trắng giòn. Giã dập đậu phộng rang và thái nhỏ hành lá. Giã nhuyễn 5 g tỏi khô, 1 quả ớt tươi và 10 g đường cát trắng rồi khuấy đều với 15 ml nước mắm ngon và nước cốt 1/2 quả chanh thành chén nước mắm chấm.', NULL, NULL),
('imp-c039dac37b31acdb_v4_step_5', 'imp-c039dac37b31acdb', 5, 'prep', 'Trụng sợi mì Quảng tươi', 'Đun sôi một nồi nước khác, trụng sợi mì Quảng tươi khoảng 1 phút cho sợi mềm dẻo nóng đều rồi vớt ra rổ để thật ráo nước.', NULL, NULL),
('imp-c039dac37b31acdb_v4_step_6', 'imp-c039dac37b31acdb', 6, 'finish', 'Xếp tô Mì Quảng gà ta và thưởng thức', 'Lót hỗn hợp rau sống xà lách, giá đỗ, húng lủi và bắp chuối bào dưới đáy 4 tô, xếp sợi mì Quảng lên trên, gắp các miếng thịt gà ta vàng ươm và chan nước nhân nóng vừa xâm xấp mặt mì. Rắc hành lá, đậu phộng rang giã dập lên trên và dọn kèm bánh đa nướng bẻ miếng cùng chén nước mắm ớt chanh.', 'Chan nước nhân vừa xâm xấp đáy tô chứ không chan đầy ngập để giữ đúng tinh thần Mì Quảng đậm vị.', NULL),
('imp-875e99916a13d031_v4_step_1', 'imp-875e99916a13d031', 1, 'prep', 'Sơ chế rau củ và nướng hành tây, gừng', 'Gọt vỏ cà rốt và củ cải trắng rồi cắt khúc dày 3 cm. Bổ đôi hành tây, cắt lát dày gừng tươi rồi nướng trực tiếp trên chảo khô hoặc bếp đến khi mặt ngoài cháy xém thơm lừng, cạo sạch lớp cháy đen.', NULL, 8);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-875e99916a13d031_v4_step_2', 'imp-875e99916a13d031', 2, 'cook', 'Ninh nước dùng rau củ và rang thảo mộc phở', 'Cho 2,8 lít nước lọc vào nồi cùng cà rốt, củ cải trắng, hành tây nướng và gừng nướng, đun sôi rồi hạ lửa nhỏ ninh 40 phút để rau củ tiết hết vị ngọt tự nhiên. Rang hoa hồi khô, quế thanh khô và thảo quả khô trên chảo khô ở lửa nhỏ 2–3 phút đến khi dậy hương thì cho vào túi lọc, thả vào nồi nước dùng ninh thêm 10 phút cuối rồi vớt bỏ toàn bộ xác rau củ và túi gia vị.', 'Chỉ thả túi hoa hồi, quế, thảo quả vào 10 phút cuối để nước phở dậy hương thơm dịu mà không bị nồng gắt hoặc sậm màu.', 50),
('imp-875e99916a13d031_v4_step_3', 'imp-875e99916a13d031', 3, 'cook', 'Chiên vàng đậu phụ và xào nấm đùi gà đậm đà', 'Thấm khô đậu phụ trắng rồi chiên áp chảo với 20 ml dầu ăn trên lửa vừa khoảng 6 phút cho vàng giòn các mặt, gắp ra giấy thấm dầu. Dùng chảo đó đun nóng 10 ml dầu ăn còn lại, phi thơm đầu hành lá băm rồi cho nấm đùi gà thái lát vào xào 3 phút trên lửa lớn. Trút đậu phụ chiên vào đảo cùng 15 ml xì dầu, 2 g muối ăn, 3 g hạt nêm chay nấm hương, 2 g bột ngũ vị hương và 1 g tiêu đen xay thêm 4 phút cho thấm vị.', 'Xào nấm đùi gà trên lửa lớn trước giúp nấm săn giòn, không bị ra nước trước khi đảo chung với đậu phụ.', 10),
('imp-875e99916a13d031_v4_step_4', 'imp-875e99916a13d031', 4, 'cook', 'Nêm nước dùng phở chay thanh ngọt', 'Nêm vào nồi nước dùng trong 10 g muối ăn còn lại, 20 g đường phèn và 7 g hạt nêm chay nấm hương, khuấy tan và đun sôi trở lại cho vị thanh ngọt hài hòa rồi giữ nóng trên bếp.', 'Dùng đường phèn kết hợp cùng hạt nêm chay nấm hương giúp vị ngọt nước dùng thanh nhẹ và sâu hậu hơn đường cát.', NULL),
('imp-875e99916a13d031_v4_step_5', 'imp-875e99916a13d031', 5, 'prep', 'Trụng bánh phở, giá đỗ và chuẩn bị rau thơm', 'Trụng nhanh bánh phở tươi qua nước sôi cho mềm tơi rồi vẩy thật ráo; trụng sơ giá đỗ qua nước sôi khoảng 30 giây. Thái nhỏ phần lá hành lá và ngò gai; rửa sạch húng quế và cắt múi chanh tươi.', NULL, NULL),
('imp-875e99916a13d031_v4_step_6', 'imp-875e99916a13d031', 6, 'finish', 'Xếp tô phở chay nấm đậu và thưởng thức', 'Chia bánh phở vào 4 tô, xếp giá đỗ trụng, nấm đùi gà và đậu phụ chiên xào lên trên, rắc hành lá và ngò gai. Chan ngập nước dùng chay đang sôi nóng vào tô và dọn ăn ngay kèm húng quế, chanh tươi cùng tương đen.', NULL, NULL),
('imp-389f525ea854b373_v4_step_1', 'imp-389f525ea854b373', 1, 'prep', 'Lọc nước cốt me và sơ chế rau củ, đậu phụ', 'Ngâm 45 g me chín với 100 ml nước ấm trong 5 phút rồi dằm nhuyễn, lọc qua rây lấy phần nước cốt sánh bỏ hạt. Đậu phụ trắng cắt miếng vuông cạnh 2,5 cm; dứa gọt vỏ, bỏ mắt, thái lát xéo 0,5 cm; cà chua bổ múi cau; đậu bắp thái lát xéo; giá đỗ rửa ráo. Tước vỏ dọc mùng, thái lát xéo, bóp nhẹ với 2 g muối ăn rồi xả thật sạch, vắt ráo; hành boa-rô băm nhỏ; ngò gai và rau ngổ cắt khúc.', 'Bóp dọc mùng với chút muối rồi xả sạch nhiều lần giúp loại bỏ nhựa gây ngứa họng mà vẫn giữ độ giòn.', 5),
('imp-389f525ea854b373_v4_step_2', 'imp-389f525ea854b373', 2, 'cook', 'Phi thơm hành boa-rô và xào sơ cà chua, dứa', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, phi thơm hành boa-rô băm khoảng 30 giây. Cho một nửa lượng cà chua và toàn bộ dứa thái lát vào xào đều 2 phút cho cà chua tiết màu đỏ cam tự nhiên và dứa dậy hương chua ngọt.', 'Xào sơ cà chua và dứa với chút dầu trước khi đổ nước giúp mặt canh có màu đỏ vàng bắt mắt mà không cần phẩm màu.', 2),
('imp-389f525ea854b373_v4_step_3', 'imp-389f525ea854b373', 3, 'cook', 'Đun nước dùng và nêm vị chua ngọt', 'Đổ 1300 ml nước lọc còn lại vào nồi, bật lửa lớn đun sôi bùng rồi hạ lửa vừa. Rót từ từ nước cốt me đã lọc vào nồi, nêm 20 g đường cát trắng, 4 g muối ăn và 8 g hạt nêm chay, khuấy đều đến khi gia vị tan và đạt độ chua mặn ngọt hài hòa.', NULL, 5),
('imp-389f525ea854b373_v4_step_4', 'imp-389f525ea854b373', 4, 'cook', 'Nấu chín đậu bắp và thả đậu phụ', 'Cho đậu bắp và phần cà chua múi cau còn lại vào nấu trên lửa vừa khoảng 3 phút cho đậu bắp chuyển màu xanh tươi. Hạ xuống lửa nhỏ rồi nhẹ nhàng thả đậu phụ trắng vào nấu thêm 3 phút để đậu nóng đều và thấm nước canh mà không bị nát.', 'Thả đậu phụ sau khi hạ nhỏ lửa và tránh khuấy mạnh tay để từng miếng đậu giữ nguyên vuông vức.', 6),
('imp-389f525ea854b373_v4_step_5', 'imp-389f525ea854b373', 5, 'cook', 'Chần chín tới dọc mùng và giá đỗ', 'Đưa dọc mùng đã vắt ráo vào nồi nấu sôi nhẹ khoảng 1 phút cho vừa chín giòn. Cuối cùng thả giá đỗ vào đảo thật nhẹ rồi tắt bếp ngay để giá không bị nhũn.', NULL, NULL),
('imp-389f525ea854b373_v4_step_6', 'imp-389f525ea854b373', 6, 'finish', 'Rắc rau thơm và dọn canh chua chay nóng', 'Múc canh chua chay dứa đậu phụ ra tô lớn, rắc đều ngò gai và rau ngổ thái khúc lên mặt để dậy hương thơm đặc trưng Nam Bộ. Dùng nóng cùng cơm trắng hoặc bún tươi.', NULL, NULL),
('imp-8301ed8c884fb619_v4_step_1', 'imp-8301ed8c884fb619', 1, 'prep', 'Sơ chế bắp cải, nấm đùi gà, lá hẹ và gia vị', 'Tách từng lá bắp cải, cắt bỏ lõi cứng rồi thái miếng vuông vừa ăn, rửa sạch và để ráo. Nấm đùi gà cắt bỏ gốc, rửa nhanh rồi thái lát chéo mỏng khoảng 0,5 cm. Hẹ lá rửa sạch cắt khúc 2–3 cm; tỏi khô băm nhuyễn; ớt hiểm thái lát mỏng.', 'Thái nấm đùi gà thành lát chéo mỏng giúp nấm nhanh chín đều, thấm gia vị và giữ được độ giòn sần sật.', NULL),
('imp-8301ed8c884fb619_v4_step_2', 'imp-8301ed8c884fb619', 2, 'cook', 'Chần sơ bắp cải trong nước sôi muối', 'Đun sôi nồi nước vừa đủ ngập rau cùng 3 g muối ăn, thả bắp cải vào chần nhanh trong 2 phút rồi vớt ngay ra rổ để thật ráo nước.', 'Chần sơ bắp cải giúp lá cải giữ được độ giòn ngọt, màu sắc tươi sáng và không bị ra nhiều nước khi xào.', 2),
('imp-8301ed8c884fb619_v4_step_3', 'imp-8301ed8c884fb619', 3, 'cook', 'Phi thơm tỏi và xào săn nấm đùi gà', 'Làm nóng chảo với 25 ml dầu ăn trên lửa vừa, thả tỏi băm vào phi khoảng 20 giây đến khi thơm nhẹ. Trút nấm đùi gà vào xào trên lửa lớn khoảng 3 phút cho đến khi lát nấm săn lại, rưới 15 ml rượu gạo nấu ăn dọc thành chảo để dậy hương.', NULL, 3),
('imp-8301ed8c884fb619_v4_step_4', 'imp-8301ed8c884fb619', 4, 'cook', 'Xào nhanh bắp cải trên lửa lớn', 'Cho bắp cải đã ráo nước vào chảo nấm, duy trì lửa lớn và đảo nhanh tay đều liên tục trong 3 phút để bắp cải nóng đều, quyện mùi thơm mà vẫn giữ trọn độ giòn ngọt.', 'Xào nhanh tay trên lửa lớn là bí quyết giúp bắp cải chín tới giòn ngon thay vì bị mềm nhũn.', 3),
('imp-8301ed8c884fb619_v4_step_5', 'imp-8301ed8c884fb619', 5, 'cook', 'Nêm gia vị xì dầu, hạt nêm chay và đảo hẹ', 'Nêm vào chảo 20 ml nước tương, 3 g muối ăn còn lại, 5 g hạt nêm chay và 5 g đường cát trắng, đảo đều 1 phút cho gia vị thấm phủ khắp rau nấm. Thả hẹ lá cắt khúc và ớt hiểm thái lát vào đảo thêm 30 giây rồi tắt bếp ngay.', NULL, NULL),
('imp-8301ed8c884fb619_v4_step_6', 'imp-8301ed8c884fb619', 6, 'finish', 'Hoàn thiện đĩa bắp cải xào nấm nóng', 'Rắc 1,5 g tiêu đen xay vào đảo nhẹ thêm một lượt rồi trút ra đĩa lớn, dùng nóng ngay với cơm trắng hoặc chấm thêm chút nước tương ớt.', NULL, NULL),
('imp-327ffa644fbe1a7d_v4_step_1', 'imp-327ffa644fbe1a7d', 1, 'prep', 'Rang thơm gạo tẻ và gạo nếp', 'Vo sạch 150 g gạo tẻ và 25 g gạo nếp qua 2 nước, chắt thật ráo. Làm nóng nồi đáy dày không dầu trên lửa nhỏ, cho hỗn hợp gạo vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và thoảng mùi thơm nhẹ.', 'Rang gạo trước khi nấu giúp hạt gạo săn nở đều, tạo độ sánh tự nhiên mà không bị vữa nước.', 6),
('imp-327ffa644fbe1a7d_v4_step_2', 'imp-327ffa644fbe1a7d', 2, 'cook', 'Ninh cháo nở bung sánh mịn', 'Đổ 1,5 lít nước lọc sôi vào nồi gạo vừa rang, khuấy đều đáy nồi rồi đậy hé nắp. Đun sôi bùng sau đó hạ lửa nhỏ ninh khoảng 22 phút, thỉnh thoảng khuấy sát đáy nồi để cháo sánh mịn không bị bén khét.', NULL, 22),
('imp-327ffa644fbe1a7d_v4_step_3', 'imp-327ffa644fbe1a7d', 3, 'marinate', 'Sơ chế, ướp tôm tươi và thái nấm đùi gà', 'Trong lúc ninh cháo, bóc vỏ 220 g tôm tươi, rút sạch chỉ lưng rồi cắt miếng nhỏ vừa ăn; ướp tôm với một nửa lượng hành tím băm, 5 ml nước mắm ngon và một nửa lượng tiêu đen xay trong 10 phút. Nấm đùi gà làm sạch, thái hạt lựu vừa; gừng tươi thái sợi chỉ; hành lá và ngò rí thái nhỏ.', 'Thái tôm và nấm đùi gà kích thước nhỏ tương đương nhau giúp từng muỗng cháo đều có đủ cả tôm ngọt và nấm giòn.', NULL),
('imp-327ffa644fbe1a7d_v4_step_4', 'imp-327ffa644fbe1a7d', 4, 'cook', 'Phi thơm hành tím và xào chín tôm nấm', 'Làm nóng 15 ml dầu ăn trong chảo trên lửa vừa, phi thơm phần hành tím băm còn lại. Cho tôm vào xào nhanh 2 phút đến khi tôm chuyển màu đỏ hồng săn chắc thì trút nấm đùi gà cùng 2 g hạt nêm vào đảo chung thêm 2 phút trên lửa lớn cho nấm chín ngọt mà không ra nhiều nước.', 'Xào nấm trên lửa lớn trong thời gian ngắn giúp nấm đùi gà giữ độ giòn sần sật và không tiết nhiều nước loãng.', 4),
('imp-327ffa644fbe1a7d_v4_step_5', 'imp-327ffa644fbe1a7d', 5, 'cook', 'Nêm gia vị và hòa quyện tôm nấm vào nồi cháo', 'Nêm 10 ml nước mắm ngon còn lại, 3 g hạt nêm và 3 g muối ăn vào nồi cháo đã nhừ, khuấy đều. Trút khoảng 2/3 phần tôm nấm xào và một nửa lượng gừng thái chỉ vào nồi cháo, đun sôi lăn tăn thêm 2 phút cho vị ngọt tiết ra quyện đều rồi tắt bếp.', NULL, NULL),
('imp-327ffa644fbe1a7d_v4_step_6', 'imp-327ffa644fbe1a7d', 6, 'finish', 'Múc cháo ra tô và trang trí nóng', 'Múc cháo tôm nấm nóng hổi ra 4 tô, xếp phần tôm nấm xào còn lại lên mặt cùng hành lá, ngò rí, phần gừng tươi thái chỉ còn lại và tiêu đen xay. Thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-9aed26098f07c061_v4_step_1', 'imp-9aed26098f07c061', 1, 'marinate', 'Sơ chế hành lá, hành tím và ướp thịt heo xay', 'Băm nhuyễn 20 g hành tím khô; rửa sạch hành lá rồi thái thật nhỏ. Cho 200 g thịt heo nạc vai xay vào tô, ướp với một nửa lượng hành tím băm, 5 ml nước mắm ngon, 2 g hạt nêm và 1 g tiêu đen xay, trộn đều và để nghỉ 10 phút cho thịt ngấm vị.', NULL, 10),
('imp-9aed26098f07c061_v4_step_2', 'imp-9aed26098f07c061', 2, 'cook', 'Xào chín tơi thịt heo xay với hành tím', 'Làm nóng 10 ml dầu ăn trong chảo chống dính trên lửa vừa, cho phần hành tím băm còn lại vào phi thơm. Trút toàn bộ thịt heo xay đã ướp vào đảo tơi đều tay khoảng 4 phút đến khi thịt săn chín hoàn toàn và tơi rời không vón cục, tắt bếp để nguội bớt rồi chắt bỏ nước mỡ thừa nếu có.', 'Xào chín thịt băm trước khi trộn với trứng giúp nhân thịt chín kỹ 100%, thơm hơn và không bị ra nước làm nhão khối trứng khi chiên.', 4),
('imp-9aed26098f07c061_v4_step_3', 'imp-9aed26098f07c061', 3, 'prep', 'Đánh tan trứng gà và trộn đều nhân thịt hành lá', 'Đập 6 quả trứng gà vào tô lớn, thêm 10 ml nước mắm ngon còn lại, 2 g hạt nêm, 2 g muối ăn và 0,5 g tiêu đen xay, dùng phới hoặc đũa đánh tan nhẹ nhàng cho hòa quyện. Trút phần thịt xay đã nguội bớt và toàn bộ hành lá thái nhỏ vào tô trứng, khuấy đều.', 'Để thịt xào nguội bớt trước khi cho vào tô trứng để tránh làm trứng bị chín lợn cợn ngay trong tô.', NULL),
('imp-9aed26098f07c061_v4_step_4', 'imp-9aed26098f07c061', 4, 'cook', 'Chiên đúc mặt dưới ở lửa nhỏ có nắp đậy', 'Bắc chảo chống dính đáy dày (đường kính khoảng 20–22 cm) lên bếp với 15 ml dầu ăn còn lại, láng đều mặt chảo trên lửa vừa rồi hạ xuống lửa nhỏ nhất. Đổ toàn bộ hỗn hợp trứng thịt vào chảo, dàn đều nhân thịt, đậy kín nắp và chiên liu riu khoảng 6 phút cho mặt dưới vàng thơm và phần mặt trên gần đông đặc.', 'Giữ lửa thật nhỏ và đậy kín nắp giúp khối trứng dày chín đều từ dưới lên trên mà mặt đáy không bị cháy sém.', 6),
('imp-9aed26098f07c061_v4_step_5', 'imp-9aed26098f07c061', 5, 'cook', 'Úp lật và chiên vàng mặt còn lại', 'Khi mặt trên trứng đã se đặc, đặt một chiếc đĩa phẳng to hơn miệng chảo lên trên, dứt khoát lật ngược chảo để trút miếng trứng ra đĩa rồi nhẹ nhàng trượt mặt còn lại xuống chảo. Chiên tiếp không đậy nắp trên lửa nhỏ thêm 3 phút cho mặt kia vàng đều và chín chắc hoàn toàn.', NULL, 3),
('imp-9aed26098f07c061_v4_step_6', 'imp-9aed26098f07c061', 6, 'finish', 'Cắt miếng vừa ăn và thưởng thức nóng', 'Trút miếng trứng đúc thịt ra thớt hoặc đĩa lớn, rắc nốt 0,5 g tiêu đen xay còn lại lên mặt rồi dùng dao sắc cắt thành 8 miếng tam giác hoặc miếng vuông gọn đẹp. Dọn ăn ngay khi còn nóng.', NULL, NULL),
('imp-24e75cbb2ba569f4_v4_step_1', 'imp-24e75cbb2ba569f4', 1, 'prep', 'Cắt sợi bánh tráng và bào mỏng bắp cải, cà rốt', 'Dùng kéo cắt 100 g bánh tráng gạo thành những sợi dài rộng khoảng 1–1,5 cm rồi tách nhẹ cho rời nhau. Bào sợi thật mỏng 160 g bắp cải trắng và 110 g cà rốt đã rửa sạch để thật ráo nước. Rau răm thái rối, ớt hiểm thái lát mỏng và giã dập 35 g đậu phộng rang.', 'Rau củ và rau răm phải vẩy thật ráo nước trước khi trộn để bánh tráng không bị ướt nhũn nhanh.', NULL),
('imp-24e75cbb2ba569f4_v4_step_2', 'imp-24e75cbb2ba569f4', 2, 'cook', 'Làm mỡ hành thơm béo chống dính bánh tráng', 'Cho hành lá thái nhuyễn cùng 1 g muối ăn vào chén chịu nhiệt. Đun nóng 15 ml dầu ăn trong chảo nhỏ khoảng 1 phút đến khi thấy hơi gợn sóng nóng thì đổ trực tiếp vào chén hành, trộn đều cho hành chín xanh thơm dậy mùi.', 'Thêm một chút mỡ hành vào bánh tráng giúp các sợi bánh tách rời nhau, mềm bóng mà không bị vón cục.', 1),
('imp-24e75cbb2ba569f4_v4_step_3', 'imp-24e75cbb2ba569f4', 3, 'sauce', 'Pha nước sốt xì dầu chanh chua ngọt', 'Vắt 1,5 quả chanh tươi lấy nước cốt bỏ hạt. Cho 10 ml xì dầu, 10 g đường cát trắng, 1 g muối ăn còn lại, 15 ml nước lọc và một nửa lượng nước cốt chanh vào chén, khuấy đều tay đến khi đường tan hoàn toàn.', NULL, NULL),
('imp-24e75cbb2ba569f4_v4_step_4', 'imp-24e75cbb2ba569f4', 4, 'cook', 'Áo mỡ hành cho bánh tráng trước khi trộn rau', 'Cho toàn bộ bánh tráng cắt sợi vào thau lớn, rưới đều chén mỡ hành vào và dùng tay sạch (đeo găng) xóc nhẹ 1 phút cho từng sợi bánh tráng áo lớp dầu hành mỏng thơm đều.', NULL, 1),
('imp-24e75cbb2ba569f4_v4_step_5', 'imp-24e75cbb2ba569f4', 5, 'cook', 'Trộn đều bánh tráng với rau củ và nước sốt', 'Cho bắp cải, cà rốt bào sợi, rau răm thái rối, ớt hiểm thái lát và một nửa lượng đậu phộng rang vào thau bánh tráng. Rưới đều nước sốt xì dầu đã pha và phần nước cốt chanh còn lại lên trên, trộn nhẹ tay đều từ dưới lên trong 1 phút cho nguyên liệu thấm đều vị chua cay mặn ngọt.', 'Không bóp quá mạnh tay khi trộn để sợi bánh tráng giữ độ dai dẻo và bắp cải vẫn giòn ngon.', NULL),
('imp-24e75cbb2ba569f4_v4_step_6', 'imp-24e75cbb2ba569f4', 6, 'finish', 'Bày đĩa, rắc đậu phộng rang và thưởng thức ngay', 'Chia bánh tráng trộn rau củ ra đĩa, rắc nốt phần đậu phộng rang giã dập lên mặt và thưởng thức ngay lúc bánh tráng còn dai giòn.', NULL, NULL),
('imp-0bd4954058454e92_v4_step_1', 'imp-0bd4954058454e92', 1, 'prep', 'Làm sạch khử mùi và ướp thịt đùi gà', 'Chà xát 800 g đùi gà ta với 3 g muối hạt và 10 g gừng tươi đập dập trong 2 phút để hết mùi hôi, rửa sạch để ráo rồi chặt miếng 3,5 cm. Ướp thịt gà với 10 ml nước mắm ngon, 4 g hạt nêm, 1 g tiêu đen xay, một nửa tỏi băm và đầu hành lá băm trong 15 phút.', NULL, 15),
('imp-0bd4954058454e92_v4_step_2', 'imp-0bd4954058454e92', 2, 'prep', 'Sơ chế nấm hương, nấm đùi gà và rau nhúng', 'Gọt sạch gốc 150 g nấm hương tươi và 200 g nấm đùi gà tươi, rửa sạch nhẹ tay để ráo; khía chữ thập trên mũ nấm hương và thái lát xéo nấm đùi gà. Rửa sạch bắp cải trắng cắt miếng 4 cm, rau muống cắt khúc; bổ múi cau 1 quả cà chua; thái sợi 15 g gừng tươi còn lại, đập dập 2 cây sả và băm nhỏ hành tím.', 'Khía nhẹ chữ thập lên mũ nấm hương tươi không chỉ giúp tô lẩu đẹp mắt hơn mà còn giúp nấm nhanh thấm vị ngọt của nước dùng.', NULL),
('imp-0bd4954058454e92_v4_step_3', 'imp-0bd4954058454e92', 3, 'cook', 'Phi thơm gừng hành tỏi và xào săn đùi gà', 'Làm nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn, cho hành tím băm, tỏi băm còn lại, gừng thái sợi và sả đập dập vào phi thơm 1 phút. Trút thịt gà đã ướp vào đảo săn khoảng 4 phút đến khi da gà căng bóng và thịt hơi ngả màu vàng nhẹ.', NULL, 5),
('imp-0bd4954058454e92_v4_step_4', 'imp-0bd4954058454e92', 4, 'cook', 'Ninh gà cùng nấm hương tươi và cà chua', 'Đổ 2000 ml nước lọc vào nồi, bật lửa lớn đun sôi bùng rồi hớt thật sạch lớp bọt nổi. Hạ lửa vừa nhỏ, thả nấm hương tươi, cà chua bổ múi cau và 1 quả ớt đập dập vào ninh thêm 18 phút đến khi thịt gà chín mềm hoàn toàn không còn sắc đỏ bên trong xương và nước lẩu vàng óng ngọt thơm.', 'Hớt bọt kỹ ngay khi nước mới sôi bùng và ninh lửa vừa nhỏ sẽ giữ nước lẩu gà trong veo, thơm dịu mùi gừng sả.', 18),
('imp-0bd4954058454e92_v4_step_5', 'imp-0bd4954058454e92', 5, 'cook', 'Nêm gia vị thanh đậm hài hòa', 'Nêm 15 ml nước mắm ngon, 4 g hạt nêm, 3 g muối hạt còn lại và 8 g đường cát trắng vào nồi lẩu, khuấy nhẹ và đun thêm 2 phút cho gia vị thấm đều vào từng miếng gà và nấm hương.', 'Vào ngày thời tiết se lạnh, bạn có thể tăng nhẹ lượng gừng thái sợi hoặc tiêu xay để tăng cảm giác ấm bụng khi thưởng thức.', NULL),
('imp-0bd4954058454e92_v4_step_6', 'imp-0bd4954058454e92', 6, 'finish', 'Dọn nồi lẩu ra bàn và nhúng nấm, rau dùng với bún', 'Chuyển nồi lẩu ra bếp giữa bàn giữ sôi lăn tăn, thả nấm đùi gà và hành lá cắt khúc vào nấu 3 phút cho nấm chín giòn ngọt rồi rắc 0,5 g tiêu đen xay lên mặt. Lần lượt nhúng bắp cải và rau muống ăn nóng kèm bún tươi cùng 1 quả ớt thái lát chấm nước mắm.', NULL, NULL),
('imp-7fa36d5f0187a86e_v4_step_1', 'imp-7fa36d5f0187a86e', 1, 'prep', 'Thái hạt lự thịt ba chỉ và làm tơi cơm nguội', 'Thấm thật khô 200 g thịt ba chỉ heo rồi thái hạt lự nhỏ đều cạnh 0,8 cm. Băm nhỏ 1 củ tỏi khô; rửa sạch hành lá, tách riêng đầu hành trắng băm nhỏ và lá xanh thái nhuyễn. Đánh tơi 540 g cơm nguội với 2 g muối ăn trong tô lớn.', 'Cắt thịt ba chỉ hạt lự đều nhau giúp thịt nhanh ra mỡ và cháy cạnh giòn đều khắp từng miếng.', NULL),
('imp-7fa36d5f0187a86e_v4_step_2', 'imp-7fa36d5f0187a86e', 2, 'cook', 'Áp chảo thịt ba chỉ ra mỡ vàng giòn cạnh', 'Tráng 10 ml dầu ăn vào chảo lớn trên lửa vừa, cho thịt ba chỉ cắt hạt lự vào đảo đều khoảng 5 phút đến khi thịt tiết ra mỡ béo và các cạnh xém vàng giòn nhẹ. Rưới 5 ml xì dầu lên thịt đảo nhanh 20 giây cho thơm rồi vớt phần thịt ra chén riêng, giữ lại khoảng 2 muỗng canh mỡ thơm trong chảo.', 'Vớt thịt ba chỉ ra trước rồi mới rang cơm giúp thịt giữ được độ giòn cạnh mà không bị dai cứng.', 5),
('imp-7fa36d5f0187a86e_v4_step_3', 'imp-7fa36d5f0187a86e', 3, 'cook', 'Phi thơm tỏi và đầu hành trắng với mỡ ba chỉ', 'Làm nóng phần mỡ ba chỉ vừa giữ lại trên lửa vừa, cho tỏi băm và đầu hành trắng băm nhỏ vào phi nhanh khoảng 30 giây đến khi dậy mùi thơm nức và hơi ngả vàng.', NULL, NULL),
('imp-7fa36d5f0187a86e_v4_step_4', 'imp-7fa36d5f0187a86e', 4, 'cook', 'Rang cơm lửa lớn cho săn hạt thấm mỡ thơm', 'Trút toàn bộ cơm nguội vào chảo, tăng lên lửa lớn và đảo liên tục trong 4 phút để từng hạt cơm áo đều lớp mỡ ba chỉ thơm tỏi, trở nên săn chắc, tơi rời và nhảy nhẹ trên mặt chảo.', NULL, 4),
('imp-7fa36d5f0187a86e_v4_step_5', 'imp-7fa36d5f0187a86e', 5, 'cook', 'Nêm xì dầu quanh chảo và trộn ba chỉ giòn', 'Rưới 15 ml xì dầu còn lại dọc quanh thành chảo nóng, thêm 4 g hạt nêm và 3 g đường cát trắng vào đảo đều tay 1 phút cho dậy hương thơm đặc trưng và hạt cơm lên màu nâu vàng đẹp mắt. Trút đĩa thịt ba chỉ cháy cạnh vào đảo đều thêm 1 phút.', 'Rưới xì dầu vào mép chảo nóng giúp nước tương bốc hương thơm nồng mà không làm ướt nhão hạt cơm.', NULL),
('imp-7fa36d5f0187a86e_v4_step_6', 'imp-7fa36d5f0187a86e', 6, 'finish', 'Rắc nhiều hành lá xanh, tiêu xay và dọn nóng', 'Tắt bếp, rắc toàn bộ phần lá hành xanh thái nhuyễn và 1,5 g tiêu đen xay vào chảo cơm, đảo nhẹ 2–3 lượt cho hành vừa chín tái xanh mướt. Múc cơm chiên ba chỉ hành ra đĩa và thưởng thức nóng ngay.', NULL, NULL),
('imp-fcf23c737f51ef13_v4_step_1', 'imp-fcf23c737f51ef13', 1, 'prep', 'Tơi cơm nguội và chuẩn bị trứng, cà chua', 'Dùng tay sạch bóp nhẹ 700 g cơm nguội để lạnh sao cho từng hạt cơm tách rời hoàn toàn, không còn vón cục. Đập 6 quả trứng gà vào tô đánh tan đều. Cà chua chín bỏ bớt phần hạt nước rồi cắt hạt lựu nhỏ; tỏi băm nhuyễn; hành lá thái nhỏ tách riêng đầu trắng và lá xanh.', 'Dùng cơm nguội để lạnh qua đêm và bỏ bớt nước hạt cà chua là hai bí quyết giúp hạt cơm chiên săn tơi, không bị nhão dính.', NULL),
('imp-fcf23c737f51ef13_v4_step_2', 'imp-fcf23c737f51ef13', 2, 'cook', 'Chiên trứng bác mềm ẩm rồi trút ra riêng', 'Làm nóng chảo sâu lòng với 15 ml dầu ăn trên lửa vừa-lớn. Đổ trứng gà đã đánh vào, đảo nhẹ tay theo vòng tròn khoảng 1–2 phút cho đến khi trứng vừa đông thành từng mảng bông mềm, bề mặt còn hơi ẩm bóng thì lập tức múc ra đĩa để riêng.', 'Không chiên trứng quá khô ở bước này vì trứng sẽ chín tiếp khi trộn chung với cơm nóng ở cuối.', 2),
('imp-fcf23c737f51ef13_v4_step_3', 'imp-fcf23c737f51ef13', 3, 'cook', 'Phi thơm hành tỏi và xào cạn nước cà chua', 'Cho 30 ml dầu ăn còn lại vào chảo trên lửa vừa, cho đầu hành trắng vào phi thơm 15 giây rồi thả tỏi băm và cà chua hạt lựu vào. Đảo đều khoảng 3 phút cho đến khi cà chua mềm nhừ và phần nước tiết ra bay hơi gần hết, tạo thành lớp nền sệt.', 'Phải đợi nước cà chua rút cạn gần hết mới cho cơm vào để cơm giữ được độ tơi ráo hoàn hảo.', 3),
('imp-fcf23c737f51ef13_v4_step_4', 'imp-fcf23c737f51ef13', 4, 'cook', 'Chiên tơi cơm nguội trên lửa vừa-lớn', 'Trút toàn bộ cơm nguội đã tơi vào chảo, tăng lửa vừa-lớn và đảo đều tay liên tục khoảng 3 phút cho hạt cơm nóng đều, săn lại và quyện lớp xốt cà chua đỏ cam.', NULL, 3),
('imp-fcf23c737f51ef13_v4_step_5', 'imp-fcf23c737f51ef13', 5, 'sauce', 'Rưới tương cà, dầu hào, xì dầu đặc áo đều hạt cơm', 'Rưới 45 ml tương cà, 22 ml dầu hào và 22 ml xì dầu đặc quanh mặt cơm, tiếp tục đảo nhanh tay thêm 2 phút trên lửa lớn cho đến khi từng hạt cơm đều lên màu nâu đỏ bóng bẩy, không còn đọng sốt ở đáy chảo.', NULL, 2),
('imp-fcf23c737f51ef13_v4_step_6', 'imp-fcf23c737f51ef13', 6, 'finish', 'Trộn trứng bác, rưới dầu mè và hoàn thiện', 'Cho trứng gà bác trở lại chảo, rưới 7,5 ml dầu mè thơm và dùng xẻng nhẹ nhàng đảo tơi cùng cơm trong 1 phút cho trứng chín hẳn và hòa quyện. Nếm thử và điều chỉnh thêm 3 g đường cát trắng, 3 g muối ăn hoặc 1 g tiêu trắng xay nếu thích, rắc phần lá xanh hành lá lên trên rồi dọn nóng ngay.', NULL, NULL),
('imp-a5148e527a9ce9cf_v4_step_1', 'imp-a5148e527a9ce9cf', 1, 'prep', 'Sơ chế thịt gà, hành tây và gia vị thơm', 'Thấm thật khô đùi gà rút xương không da rồi cắt miếng vuông cỡ 3–4 cm. Hành tây bổ múi cau, tách nhẹ các lớp; hành lá cắt khúc 3 cm, tách riêng phần đầu trắng và phần lá xanh; tỏi khô băm nhỏ; gừng non chia 10 g nạo nhuyễn và 5 g thái lát mỏng.', 'Chọn đùi gà rút xương thay vì ức gà giúp từng miếng thịt sau khi xào và om sốt vẫn mềm mọng, không bị khô xơ.', NULL),
('imp-a5148e527a9ce9cf_v4_step_2', 'imp-a5148e527a9ce9cf', 2, 'sauce', 'Pha sẵn nước sốt gừng và hỗn hợp bột bắp', 'Trong tô vừa, khuấy đều 200 ml nước lọc với 10 g gừng nạo, 15 ml dầu hào, 30 ml xì dầu nhạt, 7,5 ml xì dầu đặc, 3 g đường cát trắng, 0,5 g tiêu trắng xay và 15 ml rượu Thiệu Hưng (nếu dùng) cho tan hết gia vị. Ở chén khác, hòa tan 4 g bột bắp với 30 ml nước lọc.', NULL, NULL),
('imp-a5148e527a9ce9cf_v4_step_3', 'imp-a5148e527a9ce9cf', 3, 'cook', 'Phi thơm gừng lát, tỏi và hành tây trên lửa lớn', 'Đun nóng 15 ml dầu ăn trong chảo sâu lòng trên lửa lớn đến khi dầu nóng già. Cho 5 g gừng thái lát vào phi thơm 15 giây, tiếp tục thả tỏi băm, đầu hành trắng và hành tây múi cau vào đảo nhanh tay khoảng 30 giây cho dậy hương thơm nồng.', NULL, NULL),
('imp-a5148e527a9ce9cf_v4_step_4', 'imp-a5148e527a9ce9cf', 4, 'cook', 'Xào săn vàng các mặt thịt đùi gà', 'Trút thịt đùi gà vào chảo, dàn đều một lớp và xào nhanh tay trên lửa lớn khoảng 4–5 phút đến khi thịt săn chắc, mặt ngoài hơi xém vàng và không còn màu hồng sống.', 'Giữ lửa lớn khi áp chảo gà để bề mặt thịt nhanh se lại, khóa nước ngọt bên trong và không bị ra nước lênh láng.', 5),
('imp-a5148e527a9ce9cf_v4_step_5', 'imp-a5148e527a9ce9cf', 5, 'cook', 'Om thịt gà thấm sốt gừng và hành lá', 'Đổ toàn bộ tô nước sốt gừng đã pha vào chảo, đảo đều và đun sôi trở lại. Thả phần lá xanh hành lá vào, hạ xuống lửa vừa nấu thêm 3 phút cho thịt gà chín kỹ hoàn toàn bên trong, thấm đẫm sốt thơm và hành lá vừa chín tới.', NULL, 3),
('imp-a5148e527a9ce9cf_v4_step_6', 'imp-a5148e527a9ce9cf', 6, 'finish', 'Làm sánh nước sốt và dọn nóng', 'Khuấy đều lại chén bột bắp pha nước rồi rưới từ từ vào chảo, vừa rưới vừa đảo đều khoảng 30 giây cho nước sốt sánh bóng bám đều lên từng miếng thịt gà và hành tây. Nếm lại cho vừa miệng, tắt bếp và dọn nóng ra đĩa dùng ngay với cơm trắng.', 'Rưới nước bột bắp từng chút một để kiểm soát độ sánh vừa phải, tránh làm sốt đặc quánh quá mức.', NULL),
('imp-b3d9ecb751b0a043_v4_step_1', 'imp-b3d9ecb751b0a043', 1, 'prep', 'Làm sạch, thấm khô và thái mỏng thịt bò ngang thớ', 'Rửa nhanh thịt bò thăn qua nước pha 2 g muối ăn để khử mùi rồi thấm thật khô bằng khăn giấy. Dùng dao sắc thái thịt thành từng lát mỏng ngang thớ để khi xào thịt nhanh chín và không bị dai.', 'Thấm thật khô miếng thịt trước khi ướp và xào giúp thịt áp chảo săn mặt thơm ngon thay vì bị ra nhiều nước.', NULL),
('imp-b3d9ecb751b0a043_v4_step_2', 'imp-b3d9ecb751b0a043', 2, 'marinate', 'Ướp thịt bò thấm gia vị và khóa ẩm bằng dầu ăn', 'Cho thịt bò vào tô cùng 15 ml xì dầu, 15 ml dầu hào, 2 g đường cát trắng, 1 g muối ăn, một nửa lượng tiêu đen xay và 5 ml dầu ăn. Trộn đều tay rồi ướp khoảng 15–20 phút cho thịt ngấm gia vị và mềm mượt.', 'Cho một chút dầu ăn vào ướp cùng giúp bao bọc bề mặt lát bò, giữ độ ẩm và giúp thịt tách rời dễ dàng khi cho vào chảo nóng.', 15),
('imp-b3d9ecb751b0a043_v4_step_3', 'imp-b3d9ecb751b0a043', 3, 'prep', 'Sơ chế hành tây, tỏi, ớt hiểm và gừng tươi', 'Hành tây bóc vỏ, bổ múi cau vừa ăn rồi tách nhẹ các cánh hành. Tỏi khô băm nhỏ; ớt hiểm đỏ thái lát vát xéo; nếu dùng gừng tươi thì cạo sạch vỏ rồi thái sợi thật mảnh hoặc băm nhỏ.', NULL, NULL),
('imp-b3d9ecb751b0a043_v4_step_4', 'imp-b3d9ecb751b0a043', 4, 'cook', 'Phi thơm tỏi, ớt hiểm và gừng tươi', 'Làm nóng chảo trên lửa vừa với 25 ml dầu ăn còn lại, cho tỏi băm vào phi 20 giây cho dậy mùi thơm vàng nhẹ rồi thả ớt hiểm (và gừng tươi nếu dùng) vào đảo chung thêm 20 giây.', NULL, NULL),
('imp-b3d9ecb751b0a043_v4_step_5', 'imp-b3d9ecb751b0a043', 5, 'cook', 'Xào hành tây giữ độ giòn ngọt', 'Tăng lên lửa lớn, cho hành tây múi cau vào đảo nhanh tay khoảng 1–2 phút đến khi hành tây hơi trong ở viền cánh nhưng vẫn giữ nguyên độ giòn ngọt tự nhiên.', NULL, 2),
('imp-b3d9ecb751b0a043_v4_step_6', 'imp-b3d9ecb751b0a043', 6, 'finish', 'Xào nhanh thịt bò chín tới và dọn nóng', 'Trút toàn bộ thịt bò đã ướp vào chảo hành tây, giữ lửa lớn nhất đảo thật nhanh tay khoảng 1–2 phút đến khi thịt bò vừa chuyển màu chín tới và nước sốt áo bóng quanh từng lát thịt. Nêm thêm 4 g hạt nêm cho vừa miệng, tắt bếp, rắc phần tiêu đen xay còn lại lên trên và dọn nóng với cơm trắng.', 'Không xào thịt bò quá 2–3 phút vì thịt thăn thái mỏng chín rất nhanh; xào quá lửa thịt sẽ bị khô và dai.', 2),
('imp-835a527c81a79e9c_v4_step_1', 'imp-835a527c81a79e9c', 1, 'prep', 'Sơ chế cải thảo, cà rốt, gừng và hành lá', 'Tách từng lá cải thảo rửa sạch, để ráo rồi cắt khúc dài 3–4 cm, tách riêng phần cọng trắng cứng và phần lá xanh mềm ra hai rổ. Gọt vỏ cà rốt thái lát mỏng (nếu dùng). Gừng tươi chia một nửa băm nhỏ, một nửa thái lát mỏng; hành lá thái nhỏ tách riêng đầu trắng và lá xanh.', 'Tách riêng cọng trắng và lá xanh cải thảo vì phần cọng cần nấu lâu hơn, giúp cả hai phần chín đồng đều mà lá không bị nhũn.', NULL),
('imp-835a527c81a79e9c_v4_step_2', 'imp-835a527c81a79e9c', 2, 'marinate', 'Ướp và quết dẻo thịt heo xay', 'Cho 250 g thịt heo xay vào tô cùng gừng băm, 5 ml xì dầu nhạt, 2 g muối ăn, 0,6 g tiêu trắng xay, 3 g bột bắp, 15 ml rượu Thiệu Hưng và 15 ml nước lọc. Dùng đũa khuấy đều theo một chiều khoảng 1 phút cho thịt ngấm nước và dẻo mịn, để nghỉ 10 phút.', 'Quết thịt heo xay theo một chiều với chút nước lọc và bột bắp giúp thịt mềm ẩm, không bị khô xác khi nấu canh.', 10),
('imp-835a527c81a79e9c_v4_step_3', 'imp-835a527c81a79e9c', 3, 'cook', 'Phi thơm gừng hành và xào săn thịt bằm', 'Đặt nồi lên bếp lửa vừa, làm nóng 15 ml dầu ăn rồi cho gừng thái lát và đầu hành trắng vào phi thơm 30 giây. Trút thịt heo xay đã ướp vào, dùng đũa đảo tơi liên tục khoảng 3–4 phút đến khi thịt săn rời hoàn toàn và không còn màu hồng sống.', 'Xào săn thịt trước giúp nước canh thơm đậm đà và giữ được độ trong, ít bọt hơn so với thả thịt sống vào nước.', 4),
('imp-835a527c81a79e9c_v4_step_4', 'imp-835a527c81a79e9c', 4, 'cook', 'Nấu sôi nước dùng gà và hầm phần cọng cải thảo', 'Đổ 500 ml nước dùng gà và 500 ml nước lọc còn lại vào nồi thịt, bật lửa lớn đun sôi rồi hớt sạch bọt nổi. Thả phần cọng trắng cải thảo (và cà rốt thái lát nếu dùng) vào, hạ lửa vừa nấu khoảng 5 phút cho cọng cải vừa mềm ngọt.', NULL, 5),
('imp-835a527c81a79e9c_v4_step_5', 'imp-835a527c81a79e9c', 5, 'cook', 'Nấu phần lá cải thảo và nêm gia vị', 'Cho phần lá xanh cải thảo vào nồi, nấu thêm 3 phút trên lửa vừa đến khi lá vừa chín tới và giữ được màu xanh tươi. Nêm 15 ml xì dầu nhạt còn lại và 4 g muối ăn vào khuấy đều, nếm thử và điều chỉnh cho vừa khẩu vị.', NULL, 3),
('imp-835a527c81a79e9c_v4_step_6', 'imp-835a527c81a79e9c', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Tắt bếp ngay để lá cải thảo không bị quá mềm. Nhỏ 5 ml dầu mè thơm (nếu dùng) và rắc phần lá xanh hành lá lên mặt nồi canh, múc ra tô lớn và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-1dc0835c31b06d5e_v4_step_1', 'imp-1dc0835c31b06d5e', 1, 'marinate', 'Thấm khô và ướp tôm với gia vị', 'Thấm thật khô tôm tươi bằng khăn giấy. Cho tôm vào tô cùng 2 g muối ăn, 3 g ớt bột Paprika ngọt, 1,2 g tiêu đen xay và 15 ml dầu ăn, trộn đều tay rồi để nghỉ 10 phút cho tôm thấm vị.', 'Thấm khô tôm trước khi ướp giúp tôm nhanh săn và không tiết nước làm loãng sốt khi xào lửa lớn.', 10),
('imp-1dc0835c31b06d5e_v4_step_2', 'imp-1dc0835c31b06d5e', 2, 'prep', 'Sơ chế bông cải xanh và băm tỏi gừng', 'Cắt tách bông cải xanh thành từng nhánh nhỏ vừa ăn, rửa sạch và để ráo nước. Tỏi khô và gừng tươi băm nhỏ; ớt hiểm đỏ cắt khúc ngắn nếu dùng.', NULL, NULL),
('imp-1dc0835c31b06d5e_v4_step_3', 'imp-1dc0835c31b06d5e', 3, 'sauce', 'Pha sẵn hỗn hợp nước sốt dầu hào Hoisin', 'Trong tô vừa, khuấy đều 180 ml nước lọc, 3 g đường cát trắng, 22 ml dầu hào, 22 ml xì dầu nhạt, 7,5 ml xì dầu đặc, 10 ml tương đen Hoisin và 8 g bột bắp cho đến khi bột bắp và đường tan hoàn toàn.', 'Khuấy đều lại chén sốt ngay trước khi đổ vào chảo vì bột bắp rất nhanh lắng xuống đáy.', NULL),
('imp-1dc0835c31b06d5e_v4_step_4', 'imp-1dc0835c31b06d5e', 4, 'cook', 'Áp chảo nhanh tôm trên lửa lớn', 'Làm nóng chảo sâu lòng trên lửa lớn đến khi hơi bốc khói, đổ 35 ml dầu ăn còn lại vào láng đều đáy chảo. Thả tôm vào đảo nhanh tay khoảng 2 phút đến khi vỏ ngoài chuyển màu cam hồng và thịt tôm vừa săn tái thì vớt tôm ra đĩa, giữ lại toàn bộ phần dầu thơm trong chảo.', 'Không xào tôm chín kỹ ở bước này vì tôm sẽ tiếp tục chín hoàn toàn khi đảo lại với nước sốt ở cuối.', 2),
('imp-1dc0835c31b06d5e_v4_step_5', 'imp-1dc0835c31b06d5e', 5, 'cook', 'Xào thơm tỏi gừng và ủ hơi bông cải xanh', 'Hạ xuống lửa vừa, cho tỏi băm, gừng băm, ớt hiểm (nếu dùng) và bông cải xanh vào chảo dầu đảo đều 1–2 phút. Rưới 45 ml nước lọc quanh thành chảo rồi đậy kín nắp lại, ủ hơi khoảng 2 phút cho bông cải xanh chín tới giòn mướt.', 'Kỹ thuật ủ hơi nhanh bằng nắp vung giúp bông cải giữ trọn màu xanh tươi và độ ngọt tự nhiên tốt hơn so với chần nước.', 3),
('imp-1dc0835c31b06d5e_v4_step_6', 'imp-1dc0835c31b06d5e', 6, 'finish', 'Đảo quyện tôm với sốt sánh bóng và dọn nóng', 'Mở nắp, khuấy đều chén sốt rồi đổ vào chảo, trút tôm trở lại và đảo đều trên lửa lớn khoảng 1–2 phút đến khi thịt tôm chín đục hoàn toàn và nước sốt sánh bóng bám đều từng nhánh bông cải. Tắt bếp, trút ra đĩa và dùng nóng với cơm trắng.', NULL, 2),
('imp-57b4406be05661c7_v4_step_1', 'imp-57b4406be05661c7', 1, 'marinate', 'Thái dải và ướp thịt ba chỉ thấm gia vị', 'Thái thịt ba chỉ heo thành các dải dày khoảng 5 mm. Cho thịt vào tô ướp cùng 22 ml rượu Thiệu Hưng, 0,8 g tiêu trắng xay, 10 ml xì dầu nhạt và 5 ml xì dầu đặc; trộn đều rồi để thấm khoảng 10–15 phút trong lúc sơ chế rau củ.', NULL, 15),
('imp-57b4406be05661c7_v4_step_2', 'imp-57b4406be05661c7', 2, 'prep', 'Sơ chế rau củ và băm nhỏ tương đậu', 'Ớt chuông đỏ cắt sợi dày, hành tây thái lát dày, tỏi khô băm nhỏ, hành lá cắt khúc tách riêng đầu trắng và lá xanh, gừng thái sợi và ớt hiểm thái lát nếu dùng. Băm nhỏ 30 g tương ớt đậu bản Doubanjiang cùng 13 g đậu tương đen lên men Douchi trên thớt.', 'Băm nhỏ hai loại tương đậu giúp gia vị tan đều trong dầu nóng và không bị cắn trúng miếng tương mặn gắt.', NULL),
('imp-57b4406be05661c7_v4_step_3', 'imp-57b4406be05661c7', 3, 'cook', 'Áp chảo vàng giòn hai mặt thịt ba chỉ', 'Làm nóng chảo sâu lòng lớn trên lửa vừa-lớn, tráng đều 10 ml dầu ăn. Xếp các dải thịt ba chỉ thành một lớp phẳng không chồng lên nhau, áp chảo mỗi mặt khoảng 2–3 phút cho thịt tiết bớt mỡ, xém vàng cạnh và chín kỹ hoàn toàn bên trong. Gắp thịt ra thớt cắt miếng dài 4–5 cm vừa ăn; chắt bỏ bớt phần mỡ thừa tiết ra trong chảo, chỉ chừa lại khoảng 1 muỗng canh mỡ thơm để phi tương đậu.', NULL, 6),
('imp-57b4406be05661c7_v4_step_4', 'imp-57b4406be05661c7', 4, 'cook', 'Xào thơm tương đậu trên lửa nhỏ tạo dầu đỏ', 'Hạ bếp xuống lửa nhỏ, cho tương ớt đậu bản và đậu tương đen băm vào phần mỡ thịt trong chảo, đảo đều tay khoảng 1 phút cho đến khi hỗn hợp dậy mùi thơm nồng và phần dầu chuyển màu đỏ cam óng ánh.', 'Luôn xào tương đậu trên lửa nhỏ để tương ra màu đỏ đẹp mà không bị cháy khét gây đắng.', 1),
('imp-57b4406be05661c7_v4_step_5', 'imp-57b4406be05661c7', 5, 'cook', 'Xào tỏi, hành và rau củ giữ độ giòn', 'Cho tỏi băm và phần đầu hành trắng (thêm gừng sợi, ớt hiểm nếu dùng) vào đảo 1 phút cho thơm. Tăng lên lửa lớn, thả hành tây và ớt chuông đỏ vào xào nhanh tay khoảng 30–45 giây cho rau vừa chín tái vẫn giữ độ giòn ngọt.', NULL, 1),
('imp-57b4406be05661c7_v4_step_6', 'imp-57b4406be05661c7', 6, 'finish', 'Đảo quyện thịt ba chỉ, rưới rượu và hoàn thiện', 'Trút thịt ba chỉ đã cắt miếng trở lại chảo, đảo đều 30 giây trên lửa lớn. Rưới 8 ml rượu Thiệu Hưng còn lại cùng 5 ml xì dầu nhạt quanh thành chảo nóng, rắc 6 g đường cát trắng và phần lá xanh hành lá vào đảo nhanh một lượt rồi tắt bếp ngay. Dọn nóng dùng kèm cơm trắng.', 'Không cần nêm thêm muối rời vì tương đậu bản, đậu đen muối và xì dầu đã đủ độ mặn đậm đà.', NULL),
('imp-3774a1f0fda5cce1_v4_step_1', 'imp-3774a1f0fda5cce1', 1, 'marinate', 'Cắt khối và ướp giữ ẩm thịt ức gà', 'Cắt ức gà lọc xương không da thành miếng vuông đều cỡ 2,5 cm. Trộn gà trong tô cùng 30 ml nước lọc, 1 g bột tỏi, 4 ml dầu mè thơm, 0,6 g tiêu trắng xay và 3 g muối ăn; đảo đều cho thịt hút hết nước gia vị rồi ướp 10 phút.', 'Ướp thêm chút nước giúp miếng ức gà giữ độ ẩm mọng bên trong khi chiên ngập dầu mà không bị khô.', 10),
('imp-3774a1f0fda5cce1_v4_step_2', 'imp-3774a1f0fda5cce1', 2, 'prep', 'Pha bột chiên giòn và sơ chế rau củ, dứa chín', 'Trộn đều 120 g bột mì đa dụng, 10 g bột bắp và 2 g baking soda trong tô. Rót 200 ml nước lọc thật lạnh vào khuấy thành hỗn hợp bột sánh mịn rồi thêm 15 ml dầu ăn khuấy đều. Cắt miếng vuông 2,5 cm hành tây tím và ớt chuông; thái miếng vừa ăn dứa chín; băm nhỏ tỏi khô.', 'Dùng nước thật lạnh pha bột giúp hạn chế tạo gluten, làm lớp vỏ chiên nhẹ và giòn xốp lâu hơn.', NULL),
('imp-3774a1f0fda5cce1_v4_step_3', 'imp-3774a1f0fda5cce1', 3, 'sauce', 'Pha sẵn nước sốt chua ngọt và hỗn hợp bột bắp', 'Hòa tan 180 ml nước lọc ấm với 2 g muối ăn còn lại, 36 g đường cát trắng và 25 ml tương cà cho tan hết đường muối, sau đó khuấy đều thêm 60 ml giấm gạo. Ở chén khác, hòa tan 16 g bột bắp còn lại với 30 ml nước lọc.', NULL, NULL),
('imp-3774a1f0fda5cce1_v4_step_4', 'imp-3774a1f0fda5cce1', 4, 'cook', 'Chiên gà lần một cho chín đều và định hình vỏ', 'Đun nóng 500 ml dầu ăn trong nồi sâu lòng đến khoảng 170°C. Nhúng từng mẻ 5–6 miếng gà vào tô bột, thả chậm từng miếng vào dầu nóng để bột không dính đáy. Chiên mỗi mẻ khoảng 3 phút cho vỏ vàng nhạt và thịt gà chín kỹ bên trong rồi vớt ra rổ thưa cho ráo dầu.', 'Chia nhỏ từng mẻ chiên để nhiệt độ dầu không bị giảm đột ngột, giúp lớp bột se giòn mà không ngấm dầu.', 6),
('imp-3774a1f0fda5cce1_v4_step_5', 'imp-3774a1f0fda5cce1', 5, 'cook', 'Xào rau củ, nấu sánh sốt chua ngọt và chiên lại gà lần hai', 'Đun nóng 15 ml dầu ăn trong chảo lớn trên lửa vừa-lớn, cho tỏi băm, hành tây tím và ớt chuông vào xào nhanh 30 giây. Đổ tô nước sốt chua ngọt vào đun sôi rồi hạ lửa vừa, vừa khuấy vừa rưới từ từ hỗn hợp bột bắp pha nước đến khi sốt sánh bóng bám thìa, thả dứa chín vào đảo nóng. Song song đó, đun nóng lại nồi dầu chiên lên 175°C rồi thả toàn bộ gà vào chiên nhanh thêm 45 giây cho vỏ vàng giòn rụm, vớt ra để ráo.', 'Chiên lại lần hai ngay trước khi trộn sốt là bí quyết giúp miếng gà giòn tan và giữ được độ giòn khi áo sốt.', 3),
('imp-3774a1f0fda5cce1_v4_step_6', 'imp-3774a1f0fda5cce1', 6, 'finish', 'Xóc nhanh gà với sốt chua ngọt và dọn nóng', 'Cho toàn bộ gà chiên giòn vào chảo sốt chua ngọt, dùng xẻng đảo nhẹ và nhanh tay khoảng 3–4 lượt cho từng miếng gà áo đều lớp sốt đỏ óng cùng dứa và ớt chuông. Trút ngay ra đĩa và thưởng thức nóng khi lớp vỏ còn giòn rụm.', NULL, NULL),
('imp-49ca1819d60ffec8_v4_step_1', 'imp-49ca1819d60ffec8', 1, 'prep', 'Làm khô và cắt khúc dài hành lá', 'Rửa sạch hành lá tươi, dùng khăn giấy thấm thật khô từng cọng hành để khi phi không bị bắn dầu. Cắt bỏ rễ, cắt hành thành từng khúc dài khoảng 5 cm và chẻ đôi phần gốc trắng theo chiều dọc.', 'Không nên thái hành quá nhỏ và phải thấm thật khô để hành không bị cháy nhanh trước khi kịp tiết hết tinh dầu thơm.', NULL),
('imp-49ca1819d60ffec8_v4_step_2', 'imp-49ca1819d60ffec8', 2, 'cook', 'Phi chậm hành lá từ dầu nguội cho vàng thơm', 'Cho 30 ml dầu ăn và toàn bộ hành lá vào chảo từ lúc dầu còn nguội, sau đó mới bật lửa nhỏ. Đảo nhẹ và đều tay khoảng 6 phút đến khi phần gốc hành chuyển màu vàng nâu đẹp mắt, giòn thơm thì vớt hết xác hành ra đĩa để riêng, giữ lại toàn bộ phần dầu hành trong chảo.', 'Bắt đầu phi từ dầu nguội giúp tinh dầu hành chiết xuất chậm và sâu hơn, đồng thời kiểm soát nhiệt độ tránh làm hành bị cháy đắng.', 6),
('imp-49ca1819d60ffec8_v4_step_3', 'imp-49ca1819d60ffec8', 3, 'sauce', 'Nấu hòa tan hỗn hợp sốt xì dầu dầu hành', 'Tắt bếp, chờ dầu hành nguội bớt khoảng 1 phút rồi đổ 15 ml xì dầu nhạt, 15 ml xì dầu đặc và 4 g đường cát trắng vào chảo. Khuấy đều đến khi hỗn hợp sủi lăn tăn nhẹ từ nhiệt dư và đường tan hoàn toàn; nếu dầu nguội quá, bật lại lửa nhỏ khoảng 20 giây cho sốt hòa quyện.', NULL, NULL),
('imp-49ca1819d60ffec8_v4_step_4', 'imp-49ca1819d60ffec8', 4, 'cook', 'Đun sôi nước và luộc chín sợi mì trứng', 'Đun sôi 1 lít nước lọc trong nồi lớn cùng 6 g muối ăn. Thả 200 g mì trứng sợi khô vào luộc theo hướng dẫn trên bao bì khoảng 4–5 phút đến khi sợi mì chín mềm nhưng vẫn giữ được độ dai nhẹ ở lõi.', 'Có thể luộc mì song song trong lúc phi hành để hoàn thành món ăn chỉ trong vòng 10–12 phút.', 5),
('imp-49ca1819d60ffec8_v4_step_5', 'imp-49ca1819d60ffec8', 5, 'cook', 'Vớt ráo mì và trộn đều cùng sốt dầu hành ấm', 'Vớt mì ra rổ, xóc thật kỹ cho ráo hết nước rồi trút ngay vào chảo sốt dầu hành còn ấm. Dùng đũa trộn đều nhẹ tay khoảng 1 phút cho từng sợi mì áo đều lớp sốt nâu bóng thơm lừng.', 'Mì phải thật ráo nước để lớp sốt dầu hành bám chặt quanh sợi mì mà không bị loãng nhạt.', NULL),
('imp-49ca1819d60ffec8_v4_step_6', 'imp-49ca1819d60ffec8', 6, 'finish', 'Trình bày tô mì, rắc hành phi giòn và thưởng thức', 'Gắp mì ra hai tô vừa, rưới thêm phần sốt còn đọng dưới chảo lên trên. Xếp phần hành lá phi vàng giòn lên mặt, rắc thêm 5 g hạt mè trắng rang (nếu dùng) và thưởng thức nóng ngay.', NULL, NULL),
('imp-2b5b79ba1b622db1_v4_step_1', 'imp-2b5b79ba1b622db1', 1, 'prep', 'Ngâm mềm tôm khô và sơ chế cải thảo, gừng hành', 'Rửa sạch 45 g tôm khô qua nước lạnh rồi ngâm trong nước ấm khoảng 15 phút cho tôm nở mềm, vớt ra để ráo. Cải thảo tách từng bẹ, rửa sạch, cắt khúc dài 5–6 cm và để riêng phần bẹ trắng cứng với phần lá xanh mềm. Gừng tươi thái lát mỏng; hành lá thái nhỏ.', 'Ngâm tôm khô trước giúp tôm nhanh tiết vị ngọt umami vào nước dùng và thịt tôm mềm ngọt dễ ăn hơn.', 15),
('imp-2b5b79ba1b622db1_v4_step_2', 'imp-2b5b79ba1b622db1', 2, 'cook', 'Xào thơm gừng và tôm khô làm nền nước canh', 'Đặt nồi lên bếp lửa vừa, làm nóng 10 ml dầu ăn rồi cho gừng tươi thái lát và tôm khô đã ngâm vào đảo đều khoảng 1 phút cho dậy mùi thơm đặc trưng.', NULL, NULL),
('imp-2b5b79ba1b622db1_v4_step_3', 'imp-2b5b79ba1b622db1', 3, 'cook', 'Ninh ngọt nước dùng gà với tôm khô', 'Đổ 500 ml nước dùng gà và 500 ml nước lọc vào nồi tôm khô, bật lửa lớn đun sôi rồi hớt sạch bọt nổi. Hạ xuống lửa vừa, đậy hé nắp và nấu liu riu khoảng 8–10 phút cho tôm khô tiết trọn vị ngọt tự nhiên.', NULL, 10),
('imp-2b5b79ba1b622db1_v4_step_4', 'imp-2b5b79ba1b622db1', 4, 'cook', 'Nấu mềm phần bẹ trắng cải thảo', 'Thả phần bẹ trắng cải thảo vào nồi nước dùng đang sôi, nấu trên lửa vừa khoảng 5 phút cho bẹ cải vừa chín mềm trong nhẹ.', 'Cho phần bẹ trắng vào nấu trước 5 phút giúp bẹ và lá chín đồng đều, không bị tình trạng lá nhũn nát mà bẹ vẫn sượng.', 5),
('imp-2b5b79ba1b622db1_v4_step_5', 'imp-2b5b79ba1b622db1', 5, 'cook', 'Nấu chín phần lá xanh và nêm gia vị vừa miệng', 'Tiếp tục cho phần lá xanh cải thảo vào nồi, nấu thêm 2–3 phút đến khi lá vừa chín mềm vẫn giữ màu xanh tươi. Nêm 4 g muối ăn và 1 g tiêu trắng xay vào khuấy nhẹ cho tan đều rồi nếm thử điều chỉnh.', 'Luôn nêm muối ở bước cuối để dễ kiểm soát độ mặn vì tôm khô đã có sẵn vị mặn tự nhiên.', 3),
('imp-2b5b79ba1b622db1_v4_step_6', 'imp-2b5b79ba1b622db1', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Tắt bếp ngay sau khi nêm vừa miệng, rưới 5 ml dầu mè thơm và rắc hành lá thái nhỏ lên mặt nồi canh. Múc canh ra tô lớn và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-ee5bc076d722f397_v4_step_1', 'imp-ee5bc076d722f397', 1, 'prep', 'Ngâm nở và sơ chế nấm hương khô', 'Rửa sạch bụi trên 30 g nấm hương khô rồi ngâm trong nước ấm khoảng 30 phút (hoặc ngâm nước lạnh vài giờ) cho nấm nở mềm hoàn toàn. Vớt nấm ra, vắt nhẹ bớt nước, dùng kéo cắt bỏ phần chân nấm dai cứng rồi bổ đôi các tai nấm to.', 'Nên dùng nấm hương khô ngâm nở thay cho nấm tươi vì nấm khô giữ được hương thơm umami đậm đà đặc trưng khi hấp cùng gà.', 30),
('imp-ee5bc076d722f397_v4_step_2', 'imp-ee5bc076d722f397', 2, 'marinate', 'Thái miếng và ướp gà với gia vị giữ ẩm', 'Cắt đùi gà rút xương không da thành miếng vừa ăn cỡ 3–4 cm, cho vào tô lớn. Thêm 40 g gừng tươi thái lát, 5 ml xì dầu nhạt, 3 ml xì dầu đặc, 8 ml dầu hào, 5 ml rượu Thiệu Hưng, 2 ml dầu mè thơm, 0,5 g tiêu trắng xay và 3 g bột bắp. Trộn thật đều tay rồi ướp khoảng 10–15 phút cho thịt ngấm vị.', NULL, 10),
('imp-ee5bc076d722f397_v4_step_3', 'imp-ee5bc076d722f397', 3, 'prep', 'Trộn gà với nấm đông cô và chuẩn bị ớt, hành lá', 'Cho toàn bộ nấm hương khô đã ngâm mềm vào tô thịt gà ướp cùng ớt hiểm đỏ băm nhỏ (nếu dùng), trộn đều lại một lượt. Hành lá rửa sạch thái nhỏ; kỷ tử khô (nếu dùng) rửa nhanh qua nước sạch rồi để ráo.', NULL, NULL),
('imp-ee5bc076d722f397_v4_step_4', 'imp-ee5bc076d722f397', 4, 'prep', 'Dàn đều gà và nấm lên đĩa sâu lòng', 'Chuyển toàn bộ hỗn hợp gà, gừng và nấm sang một chiếc đĩa sứ sâu lòng chịu nhiệt, dàn đều thành một lớp phẳng không chồng chất quá dày, rải kỷ tử khô (nếu dùng) lên trên.', 'Chọn đĩa sâu lòng thay vì tô sâu giúp thịt gà tiếp xúc đều với hơi nóng để chín nhanh, đồng thời hứng trọn được phần nước ngọt tiết ra.', NULL),
('imp-ee5bc076d722f397_v4_step_5', 'imp-ee5bc076d722f397', 5, 'cook', 'Hấp cách thủy lửa vừa đến khi gà chín hoàn toàn', 'Đun sôi mạnh nước trong nồi xửng lớn, đặt đĩa gà lên giá hấp, đậy kín nắp và hấp trên lửa vừa khoảng 20 phút tính từ lúc nước sôi mạnh. Kiểm tra phần thịt gà dày nhất không còn màu hồng đỏ và nước thịt tiết ra trong hoàn toàn là đạt.', 'Chỉ đặt đĩa gà vào xửng khi nước đã sôi mạnh để hơi nóng bao bọc đều ngay từ đầu, giúp thịt gà giữ trọn nước ngọt.', 20),
('imp-ee5bc076d722f397_v4_step_6', 'imp-ee5bc076d722f397', 6, 'finish', 'Rắc hành lá và dọn nóng cùng nước hấp ngọt', 'Cẩn thận nhấc đĩa gà ra khỏi xửng hấp, rắc hành lá thái nhỏ lên mặt khi đĩa gà còn bốc khói nghi ngút. Dọn nóng ngay và thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-aac2c265c3845ec4_v4_step_1', 'imp-aac2c265c3845ec4', 1, 'prep', 'Làm sạch và ướp nhẹ tôm sú khử mùi tanh', 'Cắt râu và phần gai nhọn trên đầu tôm sú tươi, dùng tăm khéo léo rút bỏ chỉ đen dọc sống lưng rồi rửa sạch, để ráo. Cho tôm vào tô cùng 5 ml rượu Thiệu Hưng và một nửa lượng tiêu trắng xay (0,25 g), trộn nhẹ và ướp 10 phút cho tôm thơm.', 'Giữ nguyên vỏ khi hấp giúp khóa ẩm tự nhiên, làm thịt tôm sau khi chín vẫn giòn ngọt và mọng nước.', 10),
('imp-aac2c265c3845ec4_v4_step_2', 'imp-aac2c265c3845ec4', 2, 'prep', 'Thái sợi gừng tươi và chuẩn bị hành lá', 'Gừng tươi gọt vỏ, thái lát mỏng rồi cắt thành sợi thật mảnh. Hành lá tách 1/3 cắt khúc dài 5 cm để lót đĩa hấp, phần 2/3 còn lại thái khoanh mỏng để rắc sau khi hấp xong.', NULL, NULL),
('imp-aac2c265c3845ec4_v4_step_3', 'imp-aac2c265c3845ec4', 3, 'sauce', 'Pha sẵn nước sốt xì dầu gừng hành', 'Trong một chén nhỏ, trộn đều 25 ml xì dầu nhạt, 10 ml rượu Thiệu Hưng còn lại, 20 ml nước lọc, 4 g đường cát trắng, 2 ml dầu mè thơm, 0,25 g tiêu trắng xay còn lại và 10 ml dầu ăn thực vật. Khuấy kỹ đến khi đường tan hoàn toàn.', 'Pha thêm nước lọc vào xì dầu giúp vị sốt dịu thanh, tôn lên độ ngọt biển tự nhiên của tôm tươi.', NULL),
('imp-aac2c265c3845ec4_v4_step_4', 'imp-aac2c265c3845ec4', 4, 'cook', 'Xếp tôm thành một lớp trên đĩa lót hành và gừng', 'Đun sôi mạnh nước trong nồi xửng hấp. Lót các khúc hành lá 5 cm dưới đáy đĩa chịu nhiệt, xếp tôm sú thành một lớp phẳng không chồng lên nhau và rải một nửa lượng gừng sợi lên mặt tôm.', NULL, NULL),
('imp-aac2c265c3845ec4_v4_step_5', 'imp-aac2c265c3845ec4', 5, 'cook', 'Hấp tôm lửa lớn vừa chín hồng tới', 'Khi nước trong nồi đã sôi bùng nhiều hơi, đặt đĩa tôm vào xửng, đậy kín nắp và hấp trên lửa lớn khoảng 5–6 phút đến khi vỏ tôm chuyển đỏ cam đồng đều, thân tôm uốn cong và thịt tôm chuyển trắng đục hoàn toàn.', 'Không hấp tôm quá 6 phút vì tôm chín quá lửa sẽ bị khô cứng và teo nhỏ.', 6),
('imp-aac2c265c3845ec4_v4_step_6', 'imp-aac2c265c3845ec4', 6, 'finish', 'Chắt bỏ nước hấp đục, rưới sốt và dọn nóng', 'Nhấc đĩa tôm ra khỏi nồi, nhẹ nhàng nghiêng đĩa chắt bỏ hết phần nước hấp đục tiết ra. Rưới đều chén nước sốt xì dầu lên khắp mình tôm, rắc phần gừng sợi còn lại và hành lá thái khoanh lên trên rồi thưởng thức nóng ngay.', 'Chắt bỏ phần nước đọng sau khi hấp giúp nước sốt xì dầu giữ nguyên độ đậm đà thanh sạch.', NULL),
('imp-55201e4225342ca3_v4_step_1', 'imp-55201e4225342ca3', 1, 'marinate', 'Thấm khô, ướp cá phi lê với lòng trắng trứng và áo bột bắp', 'Thấm thật khô 700 g phi lê cá thịt trắng rồi cắt miếng vuông cỡ 3–4 cm. Ướp cá với 5 g muối ăn, 0,6 g tiêu trắng xay và lòng trắng của 1 quả trứng gà, trộn đều để nghỉ 15 phút. Trước khi chiên, rắc đều 30 g bột bắp vào xóc nhẹ cho bột phủ kín mỏng từng miếng cá.', 'Thấm thật khô cá trước khi ướp giúp lớp bột bắp bám chắc và lên vỏ giòn rụm, không bị nhão khi thả vào dầu nóng.', 15),
('imp-55201e4225342ca3_v4_step_2', 'imp-55201e4225342ca3', 2, 'sauce', 'Pha sẵn nước sốt chua ngọt và sơ chế rau củ', 'Hòa tan 70 ml tương cà, 30 ml giấm gạo, 25 g đường cát trắng, 15 ml xì dầu nhạt và 100 ml nước lọc trong bát cho tan hết đường. Hòa tan riêng 12 g bột bắp còn lại với 45 ml nước lọc. Thái vuông 2 cm hành tây và ớt chuông; bổ múi cau cà chua; cắt miếng vừa ăn dứa chín; băm nhỏ tỏi, thái lát gừng và cắt khúc 3 cm hành lá.', NULL, NULL),
('imp-55201e4225342ca3_v4_step_3', 'imp-55201e4225342ca3', 3, 'cook', 'Chiên ngập dầu từng mẻ cá phi lê vàng giòn', 'Đun nóng 500 ml dầu ăn trong chảo sâu lòng đến khoảng 180–190°C. Thả từng miếng cá đã áo bột vào chiên thành nhiều mẻ vừa phải, không nhồi chảo; chiên mỗi mẻ 3–4 phút đến khi lớp vỏ vàng giòn và thịt cá chín trắng hoàn toàn bên trong thì vớt ra giấy thấm dầu.', 'Chiên từng mẻ nhỏ giữ nhiệt dầu ổn định để cá giòn rụm; nếu cá hơi mềm trước khi trộn sốt, có thể chiên lại nhanh 30 giây trong dầu nóng già.', 4),
('imp-55201e4225342ca3_v4_step_4', 'imp-55201e4225342ca3', 4, 'cook', 'Phi thơm tỏi gừng và xào dậy màu tương cà cùng rau củ', 'Chắt bớt dầu chiên ra hũ riêng, giữ lại khoảng 15 ml dầu ăn trong chảo trên lửa vừa. Cho tỏi băm và gừng thái lát (nếu dùng) vào phi thơm 30 giây, cho hành tây, ớt chuông, cà chua và dứa chín vào đảo nhanh tay khoảng 1 phút cho rau củ vừa chín giòn.', NULL, 1),
('imp-55201e4225342ca3_v4_step_5', 'imp-55201e4225342ca3', 5, 'sauce', 'Nấu sôi và làm sánh nước sốt chua ngọt', 'Đổ chén nước sốt chua ngọt đã pha vào chảo rau củ, đun sôi nhẹ trên lửa vừa khoảng 2 phút cho các vị hòa quyện. Khuấy đều lại chén bột bắp pha nước rồi rưới từ từ vào chảo, vừa rưới vừa khuấy đều tay đến khi nước sốt sánh bóng vừa đủ bám mặt muỗng.', NULL, 2),
('imp-55201e4225342ca3_v4_step_6', 'imp-55201e4225342ca3', 6, 'finish', 'Xóc nhanh cá chiên với sốt nóng và dọn ngay', 'Trút toàn bộ cá phi lê chiên giòn và hành lá cắt khúc vào chảo sốt, dùng xẻng nhẹ nhàng xúc gập 3–4 lượt cho sốt chua ngọt áo đều từng miếng cá mà không làm nát thịt cá. Tắt bếp và dọn nóng ngay ra đĩa dùng kèm cơm trắng.', 'Chỉ đảo nhanh vài lượt rồi dọn ngay để lớp vỏ cá giữ được độ giòn ngon khi thưởng thức.', NULL),
('imp-6771c725aa163703_v4_step_1', 'imp-6771c725aa163703', 1, 'prep', 'Thấm ráo đậu phụ non', 'Nhẹ tay mở hộp và lấy 450 g đậu phụ non ra ngoài, đặt lên đĩa có lót hai lớp khăn giấy sạch trong 10 phút để hút bớt nước dư, giúp đậu giữ được kết cấu mịn mà không bị loãng sốt.', 'Đậu phụ non rất dễ vỡ, hãy úp nhẹ hộp ra đĩa phẳng thay vì dùng dao nạy từng miếng.', 10),
('imp-6771c725aa163703_v4_step_2', 'imp-6771c725aa163703', 2, 'prep', 'Sơ chế hành lá, tỏi và ớt', 'Rửa sạch hành lá, tách riêng phần đầu hành trắng thái nhỏ và phần lá xanh thái khoanh mỏng (giữ lại một phần nhỏ lá xanh để rắc mặt). Bóc vỏ tỏi rồi băm nhuyễn; ớt hiểm bỏ cuống, bỏ bớt hạt và băm nhỏ.', NULL, NULL),
('imp-6771c725aa163703_v4_step_3', 'imp-6771c725aa163703', 3, 'sauce', 'Trộn nền sốt xì dầu giấm gạo', 'Cho vào chảo nhỏ lúc bếp còn nguội gồm phần đầu hành trắng thái nhỏ, tỏi băm, ớt hiểm băm, 45 ml xì dầu nhạt, 15 ml giấm gạo, 8 g đường nâu và một nửa lượng hạt mè trắng rang, khuấy đều cho đường hòa quyện.', 'Cho toàn bộ nguyên liệu sốt vào chảo nguội ngay từ đầu giúp tỏi và hành tiết hương từ từ mà không bị cháy xém.', NULL),
('imp-6771c725aa163703_v4_step_4', 'imp-6771c725aa163703', 4, 'cook', 'Đun sánh nước sốt thơm nồng', 'Bật bếp lửa vừa, vừa đun vừa khuấy nhẹ đến khi hỗn hợp sôi lăn tăn thì hạ lửa nhỏ, đun liu riu 2 phút cho đường tan hoàn toàn, sốt hơi sánh lại và bay bớt mùi hăng của tỏi sống.', 'Không đun sốt quá lâu khiến nước bốc hơi nhiều làm sốt bị mặn gắt.', 2),
('imp-6771c725aa163703_v4_step_5', 'imp-6771c725aa163703', 5, 'cook', 'Thêm lá hành và dầu mè thơm', 'Cho phần lớn lá hành xanh thái khoanh vào chảo sốt, đảo nhanh tay 30 giây rồi tắt bếp ngay để hành giữ màu xanh mướt. Rưới 10 ml dầu mè thơm vào chảo, khuấy đều khi sốt còn ấm.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-6771c725aa163703_v4_step_6', 'imp-6771c725aa163703', 6, 'finish', 'Cắt đậu, rưới sốt và làm mát', 'Cắt đậu phụ non thành từng khối vuông vừa ăn khoảng 2,5 cm hoặc khía nhẹ thành lát đều trên đĩa sâu lòng. Chan đều nước sốt ấm lên mặt đậu, rắc phần lá hành xanh để riêng cùng số hạt mè trắng rang còn lại, ủ ngăn mát 15 phút trước khi dọn lạnh.', NULL, 15),
('imp-5eb2769876646aae_v4_step_1', 'imp-5eb2769876646aae', 1, 'prep', 'Ép ráo nước và áo bột đậu phụ', 'Bọc 3 bìa đậu phụ cứng trong khăn bếp sạch, đặt vật nặng lên trên ép 20 phút cho ra bớt nước để khi chiên không bị bắn dầu. Cắt đậu thành khối vuông 2 cm, cho vào tô rắc đều 10 g bột bắp cùng 2 g ngũ vị hương rồi xóc nhẹ cho bột phủ thành lớp mỏng.', 'Đậu phụ càng ráo nước thì lớp áo bột bắp càng bám chặt và giữ độ giòn lâu sau khi chiên.', 20),
('imp-5eb2769876646aae_v4_step_2', 'imp-5eb2769876646aae', 2, 'cook', 'Chiên vàng giòn các khối đậu phụ', 'Đun nóng khoảng 135 ml dầu ăn trong chảo sâu lòng trên lửa vừa lớn đến khi đầu đũa sủi tăm. Xếp từng khối đậu phụ thành một lớp không chồng lấn, chiên 8 phút và trở đều các mặt đến khi vỏ ngoài vàng giòn rụm thì vớt ra giá thưa cho ráo dầu.', 'Tuyệt đối không trộn đậu phụ vào mì quá sớm vì hơi ẩm từ sốt sẽ làm lớp vỏ giòn bị ỉu nhanh.', 8),
('imp-5eb2769876646aae_v4_step_3', 'imp-5eb2769876646aae', 3, 'prep', 'Băm tỏi, ớt và pha bát sốt cay', 'Băm nhuyễn tỏi và ớt hiểm; hành lá tách riêng đầu trắng thái nhỏ và lá xanh thái khoanh để riêng. Chắt bớt dầu trong chảo chỉ chừa lại 15 ml, phi thơm đầu hành trắng, tỏi băm và ớt hiểm trong 30 giây trên lửa vừa, rồi trút toàn bộ vào âu lớn cùng 40 ml xì dầu nhạt, 20 ml xì dầu đặc, 20 ml dầu ớt Tứ Xuyên, 8 g đường cát trắng, 10 ml giấm gạo và 5 ml dầu mè thơm, khuấy tan đường.', NULL, NULL),
('imp-5eb2769876646aae_v4_step_4', 'imp-5eb2769876646aae', 4, 'cook', 'Luộc chín tới và giữ nước luộc mì', 'Đun sôi nồi nước lớn với 6 g muối ăn, thả 400 g mì sợi vào luộc 3 phút trên lửa lớn đến khi sợi mì chín tới vẫn còn độ dai nhẹ. Trước khi vớt mì, múc giữ lại 120 ml nước luộc mì nóng, rồi vớt mì ra rổ xả nhanh nước lạnh hoặc xóc ráo cho sợi tơi.', NULL, 3),
('imp-5eb2769876646aae_v4_step_5', 'imp-5eb2769876646aae', 5, 'sauce', 'Trộn mì nóng thấm đều sốt cay', 'Cho mì vừa ráo nước vào âu sốt cay khi mì còn ấm, dùng đũa trộn nhanh tay để từng sợi mì áo đều màu nâu đỏ bóng mượt. Rót từ từ từng muỗng nước luộc mì nóng vào trộn cùng cho đến khi sốt sánh mượt bám sợi.', NULL, NULL),
('imp-5eb2769876646aae_v4_step_6', 'imp-5eb2769876646aae', 6, 'finish', 'Trình bày và thưởng thức giòn ngon', 'Chia mì trộn sốt ra 3 tô, xếp đậu phụ chiên giòn lên trên bề mặt, rắc phần lá hành xanh thái nhỏ và thêm chút dầu ớt nếu thích cay hơn. Dùng nóng hoặc nguội mát đều rất ngon miệng.', 'Giữ phần đậu phụ nằm riêng trên mặt tô giúp người ăn cảm nhận rõ sự tương phản giữa mì mềm đậm đà và đậu giòn rụm.', NULL),
('imp-87adca15ad4c1369_v4_step_1', 'imp-87adca15ad4c1369', 1, 'prep', 'Sơ chế khoai tây, cà rốt, hành tây và đùi gà', 'Khoai tây gọt vỏ, cắt khối cỡ 3–4 cm và tỉa sơ cạnh sắc rồi ngâm ngay vào thau nước lạnh 10 phút cho ra bớt tinh bột, sau đó vớt ráo. Cà rốt cắt vát xoay thành miếng vừa ăn; hành tây bổ múi cau; đùi gà lọc xương còn da cắt miếng cỡ 3–4 cm và hành lá thái nhỏ.', 'Gọt sơ các cạnh sắc của khoai tây (kỹ thuật Mentori) giúp khoai không bị vỡ nát cạnh trong quá trình ninh hầm.', 10),
('imp-87adca15ad4c1369_v4_step_2', 'imp-87adca15ad4c1369', 2, 'cook', 'Xào sơ thịt gà với dầu ăn cho săn thơm', 'Làm nóng nồi rộng đáy dày trên lửa vừa với 10 ml dầu ăn thực vật, cho 350 g đùi gà vào xào khoảng 3 phút đến khi mặt da hơi xém vàng nhẹ và thịt gà săn bên ngoài thì gắp tạm ra đĩa.', 'Xào áp mặt da gà trước giúp tiết bớt mỡ thơm và giữ thịt gà không bị nát khi hầm chung rau củ.', 3),
('imp-87adca15ad4c1369_v4_step_3', 'imp-87adca15ad4c1369', 3, 'cook', 'Xếp rau củ và đun sôi nước hầm Dashi gia vị', 'Xếp hành tây xuống đáy nồi, tiếp đến là cà rốt và cuối cùng đặt khoai tây lên trên cùng. Đổ 500 ml nước dùng Dashi vào nồi cùng 60 ml xì dầu Nhật, 30 ml rượu Mirin, 30 ml rượu Sake nấu ăn và 12 g đường cát trắng, bật lửa lớn đun đến khi nước sôi bùng.', 'Xếp hành tây và cà rốt ở dưới, khoai tây ở lớp trên giúp khoai ít bị va đập và giữ nguyên hình dáng đẹp mắt.', NULL),
('imp-87adca15ad4c1369_v4_step_4', 'imp-87adca15ad4c1369', 4, 'cook', 'Hầm rau củ mềm thấm bằng nắp thả', 'Khi nước dùng sôi, hớt sạch bọt nổi, hạ lửa xuống mức vừa nhỏ, đặt một tờ giấy bạc chọc vài lỗ nhỏ lên sát mặt nguyên liệu (làm nắp thả Otoshibuta) rồi đậy hờ nắp nồi, hầm liu riu 15 phút cho khoai tây và cà rốt gần chín mềm.', 'Nắp thả giúp nước hầm sôi tuần hoàn phủ đều lên bề mặt khoai tây dù lượng nước không quá ngập.', 15),
('imp-87adca15ad4c1369_v4_step_5', 'imp-87adca15ad4c1369', 5, 'cook', 'Cho gà vào hầm chín kỹ và ủ thấm vị', 'Nhấc nắp thả ra, xếp phần đùi gà đã xào sơ vào nồi, rưới nước hầm lên trên và tiếp tục đun liu riu thêm 6–8 phút đến khi thịt gà chín hoàn toàn (không còn màu hồng bên trong) và xiên đũa xuyên qua khoai tây dễ dàng. Tắt bếp, đậy nắp để nồi nghỉ 15 phút cho khoai và thịt thấm sâu gia vị.', 'Để nồi Nikujaga nghỉ nguội bớt 15–20 phút sau khi tắt bếp là bí quyết giúp khoai tây hút trọn vị ngọt mặn từ nước hầm.', 20),
('imp-87adca15ad4c1369_v4_step_6', 'imp-87adca15ad4c1369', 6, 'finish', 'Trình bày bát Nikujaga gà nóng cùng cơm trắng', 'Múc gà hầm cùng khoai tây, cà rốt, hành tây và một ít nước hầm sánh ngọt ra bát sâu lòng, rắc hành lá thái nhỏ lên trên rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-62d95da722597187_v4_step_1', 'imp-62d95da722597187', 1, 'sauce', 'Pha sốt xì dầu dầu mè giấm gạo và rang mè', 'Cho 60 ml xì dầu Nhật, 25 ml dầu mè rang, 20 ml giấm gạo, 8 g đường cát trắng, 8 g gừng tươi mài nhuyễn và 1 g tiêu đen xay vào bát, khuấy tan đều đường. Đồng thời cho 20 g hạt mè trắng vào chảo khô rang trên lửa vừa khoảng 2 phút đến khi vàng thơm rồi trút ra chén riêng.', 'Khuấy sốt cho tan đường trước khi nấu giúp các gia vị quyện đều ngay khi tiếp xúc với mì nóng.', 2),
('imp-62d95da722597187_v4_step_2', 'imp-62d95da722597187', 2, 'cook', 'Luộc và xả lạnh sợi mì Soba giữ độ dai', 'Đun sôi 1500 ml nước lọc trên lửa lớn, thả 210 g mì Soba kiều mạch vào luộc khoảng 4–5 phút, đảo nhẹ bằng đũa cho sợi mì không dính chùm. Khi mì vừa chín tới (còn hơi dai ở lõi), vớt ngay ra rổ xả dưới vòi nước lạnh kết hợp chà nhẹ cho sạch nhớt bột rồi xóc thật ráo nước.', 'Không luộc mì Soba quá lâu kẻo sợi bị bở đứt; xả nước lạnh ngay giúp mì săn dai.', 5),
('imp-62d95da722597187_v4_step_3', 'imp-62d95da722597187', 3, 'prep', 'Sơ chế nấm đùi gà, hành tím và hành lá', 'Cắt bỏ phần gốc cứng của 350 g nấm đùi gà tươi, dùng khăn ẩm lau sạch bụi bẩn mà không ngâm nước, thái lát dày khoảng 5 mm. Hành tím bóc vỏ băm nhỏ; hành lá thái lát xéo mỏng và chia làm 2 phần.', 'Lau nấm bằng khăn ẩm thay vì rửa ngập nước giúp nấm không bị sũng nước khi áp chảo, lên màu vàng ngon hơn.', NULL),
('imp-62d95da722597187_v4_step_4', 'imp-62d95da722597187', 4, 'cook', 'Áp chảo xào thơm nấm đùi gà cùng hành tím', 'Làm nóng chảo lớn trên lửa vừa lớn với 10 ml dầu ăn thực vật, cho hành tím băm vào phi khoảng 45 giây cho dậy mùi thơm rồi thả nấm đùi gà cùng 1/2 lượng hành lá vào đảo nhanh tay 3–4 phút đến khi nấm xém cạnh vàng nhẹ và chín mềm.', 'Xào nấm trên lửa lớn giúp bề mặt nấm săn vàng và giữ độ giòn ngọt thay vì bị ra nhiều nước.', 4),
('imp-62d95da722597187_v4_step_5', 'imp-62d95da722597187', 5, 'cook', 'Rim nhẹ nước sốt cùng nấm và đảo đều với mì Soba', 'Rót toàn bộ bát sốt đã pha vào chảo nấm, đảo đều khoảng 30 giây cho sốt sôi lăn tăn và áo quanh từng lát nấm. Cho mì Soba đã ráo nước vào chảo, đảo đều nhẹ tay trên lửa nhỏ khoảng 1 phút để sợi mì hút trọn hương vị sốt nấm, thêm 1/2 lượng hạt mè rang và phần hành lá còn lại vào đảo lần cuối rồi tắt bếp.', NULL, NULL),
('imp-62d95da722597187_v4_step_6', 'imp-62d95da722597187', 6, 'finish', 'Trình bày đĩa mì Soba trộn nấm mè', 'Gắp mì Soba trộn nấm ra 3 đĩa hoặc bát nông, rắc nốt phần hạt mè rang còn lại lên trên mặt và thưởng thức ngay khi mì còn ấm thơm hoặc để nguội mát như món mì trộn lạnh.', NULL, NULL),
('imp-d2ab8a9e07388289_v4_step_1', 'imp-d2ab8a9e07388289', 1, 'prep', 'Làm sạch, chần nhanh và khứa vằn thân mực ống', 'Rút bỏ phần nội tạng, túi mực, xương sống trong suốt, bỏ mắt và răng cứng rồi lột sạch lớp màng mỏng bên ngoài 650 g mực ống tươi, giữ nguyên thân và phần râu rồi rửa sạch. Đun sôi nồi nước lọc khoảng 470 ml trên lửa lớn, thả mực vào chần nhanh đúng 15 giây cho thân mực vừa co săn lại thì vớt ngay ra thấm thật khô nước. Dùng dao sắc khứa ngang thân mực các đường cách nhau 1,5 cm sâu khoảng nửa thân mà không cắt đứt rời.', 'Chần nhanh mực trước khi ướp giúp mực không bị chảy nước khi nướng và giữ trọn lớp gừng tỏi ướp ngay trên bề mặt.', NULL),
('imp-d2ab8a9e07388289_v4_step_2', 'imp-d2ab8a9e07388289', 2, 'marinate', 'Ướp gừng tỏi nhẹ lên mực đã chần ráo', 'Trộn đều phần thân và râu mực đã thấm khô với 10 g gừng tươi bào nhuyễn, tỏi băm nhuyễn và 1 g muối ăn, ướp khoảng 10 phút cho mực dậy mùi thơm khử tanh mà không bị mặn gắt trước khi phết sốt Teriyaki.', 'Không ướp quá nhiều muối vì lớp sốt Teriyaki nấu từ xì dầu đã đậm đà sẵn.', 10),
('imp-d2ab8a9e07388289_v4_step_3', 'imp-d2ab8a9e07388289', 3, 'sauce', 'Nấu sốt Teriyaki sánh bóng', 'Cho 60 ml xì dầu Nhật, 60 ml rượu Sake nấu ăn, 40 ml rượu Mirin và 20 g đường nâu vào nồi nhỏ, đun lửa nhỏ và khuấy đều cho đường tan hoàn toàn. Hòa tan 4 g bột bắp với 30 ml nước lọc rồi rót từ từ vào nồi, vừa rót vừa khuấy đều đến khi sốt sôi nhẹ và sánh bóng như lớp siro mỏng thì tắt bếp.', NULL, 5),
('imp-d2ab8a9e07388289_v4_step_4', 'imp-d2ab8a9e07388289', 4, 'cook', 'Làm nóng lò nướng và nướng lượt đầu với sốt', 'Làm nóng trước lò nướng hoặc bếp nướng ở mức 180°C trong 10 phút, lót giấy bạc lên khay nướng rồi phết đều 15 ml dầu ăn thực vật chống dính. Phết một nửa lượng sốt Teriyaki phủ đều lên thân và râu mực, xếp lên khay và nướng trong 5 phút.', 'Phết dầu lên giấy bạc hoặc vỉ nướng giúp lớp sốt đường trên mực không bị dính cháy vào khay.', 5),
('imp-d2ab8a9e07388289_v4_step_5', 'imp-d2ab8a9e07388289', 5, 'cook', 'Phết thêm sốt và nướng xém cạnh hoàn chỉnh', 'Kéo khay mực ra, lật mặt và phết thêm một lớp sốt Teriyaki nữa phủ đều thân mực rồi nướng tiếp 4–5 phút đến khi thịt mực chuyển trắng đục hoàn toàn, mặt ngoài bóng sốt và hơi xém cạnh thơm lừng.', 'Không nướng mực quá 10 phút tổng thời gian vì mực chín quá lửa sẽ bị khô cứng và dai.', 5),
('imp-d2ab8a9e07388289_v4_step_6', 'imp-d2ab8a9e07388289', 6, 'finish', 'Thái khoanh mực nướng và dọn nóng', 'Đặt mực nướng Teriyaki ra thớt cắt thân mực thành từng khoanh tròn dày 1,5 cm, xếp ra đĩa cùng râu mực, rưới phần sốt Teriyaki còn lại lên trên và rắc hành lá thái nhỏ rồi dùng nóng ngay.', NULL, NULL),
('imp-81ff926a5557c059_v4_step_1', 'imp-81ff926a5557c059', 1, 'prep', 'Sơ chế và chia phần cá hồi phi lê', 'Dùng tay miết dọc thớ thịt 510 g cá hồi phi lê để tìm xương dăm và nhổ sạch bằng nhíp, cạo sạch vảy còn sót trên mặt da rồi rửa nhanh và thấm thật khô. Chia cá thành 3 miếng đều nhau khoảng 170 g/miếng để cá chín đồng đều.', 'Giữ nguyên lớp da cá giúp miếng cá giữ dáng đẹp khi nướng và phần thịt sát da thêm béo mềm.', NULL),
('imp-81ff926a5557c059_v4_step_2', 'imp-81ff926a5557c059', 2, 'sauce', 'Trộn hỗn hợp sốt ướp tương Miso trắng', 'Cho 50 g tương Miso trắng Nhật, 25 ml rượu Sake nấu ăn, 25 ml rượu Mirin, 20 ml xì dầu Nhật và 5 ml dầu mè rang vào tô nông, khuấy thật đều tay đến khi tương Miso tan mịn hoàn toàn thành hỗn hợp sốt sệt đồng nhất.', NULL, NULL),
('imp-81ff926a5557c059_v4_step_3', 'imp-81ff926a5557c059', 3, 'marinate', 'Phết sốt Miso và ướp lạnh cá hồi', 'Đặt 3 miếng cá hồi vào khay nông, phết đều hỗn hợp sốt Miso phủ kín cả mặt thịt, hai bên cạnh và mặt da cá. Bọc kín khay bằng màng bọc thực phẩm và ướp trong ngăn mát tủ lạnh từ 1 đến 2 giờ cho thịt cá thấm vị dịu nhẹ.', 'Không nên ướp cá hồi với Miso quá 3 giờ hoặc qua đêm vì độ mặn của tương Miso sẽ làm thịt cá bị gắt và ra nước.', 90),
('imp-81ff926a5557c059_v4_step_4', 'imp-81ff926a5557c059', 4, 'prep', 'Làm nóng lò nướng và gạt sạch sốt Miso thừa', 'Bật lò nướng chế độ lửa trên ở mức 220°C (hoặc làm nóng nồi chiên không dầu 200°C) trước 5 phút, lót giấy bạc lên khay và phết đều 5 ml dầu ăn thực vật chống dính. Lấy cá hồi ra khỏi tủ lạnh, dùng phới dẹt gạt sạch toàn bộ lớp sốt Miso bám trên mặt cá chỉ giữ lại hương vị đã thấm.', 'Gạt sạch sốt Miso thừa trước khi nướng là bước then chốt giúp mặt cá vàng xém hấp dẫn mà không bị cháy đen đắng.', 5),
('imp-81ff926a5557c059_v4_step_5', 'imp-81ff926a5557c059', 5, 'cook', 'Nướng cá hồi vàng xém cạnh và chín mọng', 'Xếp cá hồi lên khay nướng với mặt da úp xuống dưới, đặt khay ở rãnh giữa lò và nướng khoảng 10–12 phút (không cần lật mặt) đến khi thịt cá chuyển màu hồng đục hoàn toàn, mặt trên vàng xém nhẹ và dùng nĩa tách thớ dễ dàng.', 'Cá hồi chín tới sẽ giữ được độ béo mọng bên trong; tránh nướng quá lâu làm thớ cá bị khô xác.', 11),
('imp-81ff926a5557c059_v4_step_6', 'imp-81ff926a5557c059', 6, 'finish', 'Trình bày cá hồi nướng Miso cùng mè rang và hành lá', 'Dùng xẻng nhẹ nhàng gắp cá hồi ra đĩa, rắc hạt mè trắng rang và hành lá thái lát xéo mỏng lên trên, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-8c6abf9194ba8c45_v4_step_1', 'imp-8c6abf9194ba8c45', 1, 'prep', 'Sơ chế đùi gà, giá đỗ và tỏi băm', 'Thấm thật khô 450 g đùi gà lọc xương còn da, cắt miếng vuông cỡ 3 cm rồi xóc đều với 1 g muối ăn. Giá đỗ tươi rửa sạch, vớt ra rổ xóc kỹ cho thật ráo nước; tỏi khô mài nhuyễn hoặc băm mịn và hành lá thái nhỏ để riêng.', 'Giá đỗ phải để thật ráo nước trước khi cho vào chảo để tránh tiết nước làm món xào bị ướt nhũn.', NULL),
('imp-8c6abf9194ba8c45_v4_step_2', 'imp-8c6abf9194ba8c45', 2, 'cook', 'Áp chảo mặt da đùi gà chín vàng giòn', 'Làm nóng chảo rộng trên lửa vừa với 10 ml dầu mè thơm, xếp các miếng đùi gà úp mặt da xuống chảo không chồng lên nhau, đậy nắp áp chảo khoảng 3 phút cho mặt da vàng giòn và tiết mỡ thơm.', 'Đậy nắp khi áp mặt da giúp hơi nóng làm thịt gà chín đều bên trong mà phần da vẫn giòn đẹp.', 3),
('imp-8c6abf9194ba8c45_v4_step_3', 'imp-8c6abf9194ba8c45', 3, 'cook', 'Lật mặt áp chín gà hoàn toàn', 'Mở nắp, lật mặt thịt gà xuống và áp thêm khoảng 3 phút đến khi gà chín hoàn toàn bên trong, mặt ngoài vàng đều không còn nước đỏ thì gắp gà ra tô riêng, giữ nguyên phần mỡ gà thơm trong chảo.', NULL, 3),
('imp-8c6abf9194ba8c45_v4_step_4', 'imp-8c6abf9194ba8c45', 4, 'marinate', 'Trộn thịt gà nóng với sốt xì dầu và tỏi mài', 'Cho 35 ml xì dầu Nhật và tỏi băm nhuyễn vào tô thịt gà đang còn nóng, đảo trộn đều tay và để yên 2 phút cho từng miếng thịt gà hút đậm hương vị tỏi xì dầu.', 'Trộn sốt xì dầu tỏi vào gà ngay khi gà còn nóng giúp thịt thấm vị sâu mà không làm cháy tỏi trong chảo.', 2),
('imp-8c6abf9194ba8c45_v4_step_5', 'imp-8c6abf9194ba8c45', 5, 'cook', 'Xào nhanh giá đỗ trên lửa lớn giữ độ giòn', 'Bật lửa lớn làm nóng lại phần mỡ gà trong chảo, trút toàn bộ 300 g giá đỗ vào cùng 4 g hạt nêm gà, đảo nhanh tay khoảng 1–2 phút đến khi giá vừa hơi trong nhẹ mà vẫn giữ nguyên độ giòn sần sật.', 'Chỉ xào giá đỗ trên lửa lớn trong thời gian ngắn; xào quá 2 phút giá sẽ mềm nhũn và ra nước.', NULL),
('imp-8c6abf9194ba8c45_v4_step_6', 'imp-8c6abf9194ba8c45', 6, 'finish', 'Đảo quyện gà với giá đỗ và dọn nóng', 'Trút thịt gà cùng toàn bộ nước sốt tỏi xì dầu trở lại chảo giá đỗ, đảo nhanh tay 30 giây cho sốt áo đều gà và giá rồi tắt bếp ngay. Múc ra đĩa, rắc hành lá thái nhỏ cùng tiêu đen xay lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-b33750551f6ea7fe_v4_step_1', 'imp-b33750551f6ea7fe', 1, 'prep', 'Lau sạch và thái khoanh khía caro nấm đùi gà', 'Cắt bỏ phần gốc cứng của 300 g nấm đùi gà tươi, dùng khăn ẩm lau sạch bụi đất mà không ngâm nước. Thái thân nấm thành từng khoanh tròn dày khoảng 1,5–2 cm, dùng mũi dao khía nhẹ hình mắt lưới caro lên một mặt khoanh nấm và thái nhỏ hành lá để riêng.', 'Thái nấm thành khoanh dày và không rửa ngập nước giúp nấm giữ được độ giòn sần sật như sò điệp áp chảo.', NULL),
('imp-b33750551f6ea7fe_v4_step_2', 'imp-b33750551f6ea7fe', 2, 'cook', 'Làm tan chảy bơ với dầu ăn trên chảo nóng', 'Làm nóng chảo rộng trên lửa vừa, cho 8 ml dầu ăn thực vật và 25 g bơ lạt vào, lắc nhẹ chảo đến khi bơ tan chảy hoàn toàn và bắt đầu sủi bọt lăn tăn thơm béo.', 'Pha thêm một chút dầu ăn cùng bơ lạt giúp nâng điểm khói, tránh làm bơ chuyển màu cháy đen khi áp chảo.', NULL),
('imp-b33750551f6ea7fe_v4_step_3', 'imp-b33750551f6ea7fe', 3, 'cook', 'Áp chảo mặt khía caro của nấm vàng nâu', 'Xếp các khoanh nấm thành một lớp đều trên chảo (mặt khía caro úp xuống), không xếp chồng lên nhau, chiên yên trên lửa vừa khoảng 3 phút đến khi mặt nấm chuyển màu vàng nâu đẹp mắt và hơi xém cạnh.', 'Không đảo nấm liên tục và không xếp chồng để nấm được áp chảo trực tiếp thay vì bị hấp hơi chảy nước.', 3),
('imp-b33750551f6ea7fe_v4_step_4', 'imp-b33750551f6ea7fe', 4, 'cook', 'Lật mặt nấm áp vàng và nêm muối tiêu', 'Lật ngược các khoanh nấm sang mặt còn lại, áp chảo thêm khoảng 2–3 phút đến khi hai mặt đều vàng nâu hấp dẫn rồi rắc đều 1,5 g muối ăn và 1 g tiêu đen xay lên mặt nấm.', NULL, 3),
('imp-b33750551f6ea7fe_v4_step_5', 'imp-b33750551f6ea7fe', 5, 'sauce', 'Rưới xì dầu quanh mép chảo tạo hương Shoyu thơm lừng', 'Rưới 10 ml xì dầu Nhật chạy dọc theo thành chảo nóng để xì dầu bốc hơi thơm nức, lập tức nghiêng và lắc nhẹ chảo trong 15 giây cho phần sốt bơ xì dầu áo bóng đều quanh từng khoanh nấm.', 'Rưới xì dầu vào mép chảo nóng thay vì đổ thẳng lên nấm giúp bốc mùi thơm cháy cạnh đặc trưng của món Nhật.', NULL),
('imp-b33750551f6ea7fe_v4_step_6', 'imp-b33750551f6ea7fe', 6, 'finish', 'Trộn hành lá và dọn đĩa nấm nướng bơ Shoyu nóng', 'Cho hành lá thái nhỏ vào đảo nhanh 5 giây rồi tắt bếp ngay. Gắp nấm ra đĩa ấm, rưới hết phần bơ xì dầu trong chảo lên trên và thưởng thức nóng kèm cơm trắng hoặc làm món khai vị.', NULL, NULL),
('imp-e9562581c7d79169_v4_step_1', 'imp-e9562581c7d79169', 1, 'prep', 'Vo gạo và pha nước gia vị nấu cơm Nhật', 'Vo nhẹ 300 g gạo hạt ngắn Nhật 2–3 lần nước cho sạch rồi để ráo, cho vào lòng nồi cơm điện. Đổ 360 ml nước lọc cùng 18 ml xì dầu Nhật, 15 ml rượu Sake nấu ăn và 5 g hạt nêm gà vào khuấy nhẹ cho gia vị tan đều, ngâm 15 phút.', 'Bớt nhẹ một chút nước lọc so với nấu cơm trắng thông thường vì đã có thêm xì dầu và rượu Sake, giúp hạt cơm chín tơi ráo.', 15),
('imp-e9562581c7d79169_v4_step_2', 'imp-e9562581c7d79169', 2, 'cook', 'Bật nấu cơm chín dẻo thơm vị nước dùng', 'Đậy nắp nồi cơm điện, bật chế độ nấu cơm tiêu chuẩn và nấu khoảng 30–35 phút cho đến khi nồi chuyển sang chế độ giữ ấm.', NULL, 35),
('imp-e9562581c7d79169_v4_step_3', 'imp-e9562581c7d79169', 3, 'prep', 'Xé tơi thịt cua, thái hành lá và đánh trứng Mayonnaise', 'Trong lúc chờ cơm chín, kiểm tra nhặt sạch mảnh vỏ cứng còn sót trong 200 g thịt cua tươi và xé tơi nhẹ dọc thớ thịt, rửa sạch và thái nhỏ hành lá. Đập 2 quả trứng gà ra bát, cho 8 g sốt Mayonnaise vào đánh tan đều cho đến khi hòa quyện mịn.', 'Trộn thêm chút sốt Mayonnaise vào trứng giúp trứng khi hấp trên cơm nóng sẽ bông xốp và giữ độ mềm ẩm rất ngon.', NULL),
('imp-e9562581c7d79169_v4_step_4', 'imp-e9562581c7d79169', 4, 'cook', 'Trộn thịt cua, hành lá và dầu mè vào cơm nóng', 'Ngay khi cơm vừa chín tới còn đang bốc hơi nóng, mở nắp nồi và rải toàn bộ thịt cua tươi, 2/3 lượng hành lá thái nhỏ cùng 12 ml dầu mè thơm vào, dùng muôi xới nhẹ từ dưới lên cho đều.', 'Thực hiện thao tác nhanh tay để giữ nhiệt độ nóng hổi trong nồi cho bước hấp chín hoàn toàn thịt cua và trứng tiếp theo.', NULL),
('imp-e9562581c7d79169_v4_step_5', 'imp-e9562581c7d79169', 5, 'cook', 'Hấp chín kỹ thịt cua và hỗn hợp trứng gà', 'Rưới đều bát trứng gà đánh Mayonnaise phủ khắp bề mặt cơm và cua đang nóng, lập tức đậy kín nắp nồi và bật lại chế độ nấu thêm 3 phút rồi để ủ kín thêm 4–5 phút cho đến khi thịt cua chín thơm nóng đều và trứng chín hẳn, đông tơi mềm mịn.', 'Đảm bảo thịt cua và trứng gà được hấp chín kỹ hoàn toàn bằng hơi nóng trước khi mở nắp trộn cơm.', 8),
('imp-e9562581c7d79169_v4_step_6', 'imp-e9562581c7d79169', 6, 'finish', 'Nêm muối tiêu, xới tơi và dọn cơm cua Kanimeshi', 'Mở nắp nồi, rắc 2 g muối ăn và 0,5 g tiêu đen xay vào rồi xới tơi nhẹ nhàng cho cơm, thịt cua và trứng chín quyện đều. Múc ra 3 bát, rắc nốt phần hành lá thái nhỏ còn lại lên trên và dùng nóng ngay.', NULL, NULL),
('imp-ee7ca138c67f4f24_v4_step_1', 'imp-ee7ca138c67f4f24', 1, 'marinate', 'Sơ chế và ướp thịt bò áo tinh bột khoai tây', 'Cắt 250 g thịt bò thái lát mỏng thành miếng vừa ăn khoảng 4 cm. Cho thịt bò vào tô cùng 15 ml rượu Sake nấu ăn, 1 g muối ăn, 1 g tiêu đen xay và 4 g tinh bột khoai tây, dùng tay bóp trộn nhẹ cho gia vị và lớp tinh bột áo đều quanh từng lát thịt, để thấm 10 phút.', 'Lớp tinh bột khoai tây mỏng giúp khóa độ ẩm bên trong thớ thịt bò, đồng thời làm nước sốt tự nhiên sánh nhẹ khi xào.', 10),
('imp-ee7ca138c67f4f24_v4_step_2', 'imp-ee7ca138c67f4f24', 2, 'prep', 'Chuẩn bị hành tây, gừng tươi hai kiểu và hành lá', 'Hành tây bóc vỏ, bổ múi cau dày 1,5 cm. Gừng tươi cạo thật mỏng lớp vỏ ngoài; chia 30 g gừng làm hai phần, một nửa thái sợi mảnh và một nửa mài nhuyễn; hành lá rửa sạch thái nhỏ để riêng.', 'Gọt vỏ gừng thật mỏng giúp giữ lại phần tinh dầu thơm nhất nằm ngay dưới lớp vỏ.', NULL),
('imp-ee7ca138c67f4f24_v4_step_3', 'imp-ee7ca138c67f4f24', 3, 'sauce', 'Pha bát nước sốt Sake Mirin xì dầu cân bằng', 'Cho 30 ml xì dầu Nhật, 30 ml rượu Mirin, 30 ml rượu Sake nấu ăn còn lại và 4 g đường cát trắng vào chén, khuấy đều đến khi đường tan hoàn toàn.', 'Pha sẵn nước sốt trước khi bật bếp giúp thao tác xào diễn ra liên tục nhanh gọn, thịt bò không bị quá lửa.', NULL),
('imp-ee7ca138c67f4f24_v4_step_4', 'imp-ee7ca138c67f4f24', 4, 'cook', 'Xào nhanh thịt bò với dầu mè rồi hấp mềm hành tây', 'Làm nóng chảo trên lửa vừa với 10 ml dầu mè thơm, cho thịt bò đã ướp vào đảo nhanh khoảng 1–2 phút đến khi thịt vừa đổi màu hết đỏ tái. Lập tức thả hành tây bổ múi cau vào đảo đều, đậy nắp chảo và hạ lửa nhỏ hấp-xào khoảng 3 phút cho hành tây mềm dịu và tiết vị ngọt.', 'Đậy nắp hạ lửa nhỏ giúp hành tây chín mềm ngọt nhanh mà không làm thịt bò bị khô xơ.', 3),
('imp-ee7ca138c67f4f24_v4_step_5', 'imp-ee7ca138c67f4f24', 5, 'cook', 'Đảo quyện nước sốt gừng sánh bóng', 'Mở nắp chảo, vặn lên lửa vừa lớn, rót toàn bộ bát nước sốt đã pha cùng cả phần gừng thái sợi và gừng mài nhuyễn vào chảo. Đảo nhanh tay khoảng 1–2 phút đến khi nước sốt sôi sệt lại, bám bóng đều quanh thịt bò và hành tây thì tắt bếp.', NULL, 2),
('imp-ee7ca138c67f4f24_v4_step_6', 'imp-ee7ca138c67f4f24', 6, 'finish', 'Trình bày đĩa bò xào gừng Itame dùng nóng', 'Múc bò xào gừng hành tây ra đĩa nóng, rắc hành lá thái nhỏ lên trên rồi dùng ngay với cơm trắng nóng hổi.', NULL, NULL),
('imp-57a8ece15d731efb_v4_step_1', 'imp-57a8ece15d731efb', 1, 'prep', 'Sơ chế bắp cải, nấm đùi gà và ngâm rong biển Wakame', 'Rửa sạch 240 g bắp cải xanh, bỏ phần lõi cứng và cắt thành miếng vuông cỡ 2 cm (để riêng phần cọng dày nếu có). Nấm đùi gà lau sạch, cắt lát dày 5 mm; rong biển Wakame khô ngâm nước lạnh 5 phút cho nở mềm rồi vắt ráo; hành lá thái lát xéo mỏng.', 'Tách riêng phần cọng bắp cải dày để cho vào nồi trước giúp cả cọng và lá chín mềm đồng đều.', 5),
('imp-57a8ece15d731efb_v4_step_2', 'imp-57a8ece15d731efb', 2, 'cook', 'Đun sôi nước dùng Dashi và nấu mềm bắp cải cùng nấm', 'Đổ 650 ml nước dùng Dashi vào nồi vừa, đậy nắp đun sôi trên lửa vừa. Khi nước vừa sôi lăn tăn, hạ lửa vừa nhỏ rồi thả bắp cải (cho phần cọng vào trước 1 phút) và nấm đùi gà vào nồi, đậy nắp nấu liu riu khoảng 4–5 phút cho đến khi bắp cải chín mềm ngọt và nấm chín đều.', 'Nấu bắp cải và nấm ở mức sôi liu riu giữ cho nước dùng trong veo và rau củ giữ trọn vị ngọt tự nhiên.', 5),
('imp-57a8ece15d731efb_v4_step_3', 'imp-57a8ece15d731efb', 3, 'cook', 'Thả rong biển Wakame vào nồi canh', 'Mở nắp nồi, thả phần rong biển Wakame đã ngâm nở vào khuấy nhẹ khoảng 30 giây cho rong biển nóng đều rồi tắt bếp ngay.', 'Không đun rong biển Wakame quá lâu trên lửa để tránh rong biển bị nhũn và mất màu xanh đẹp.', NULL),
('imp-57a8ece15d731efb_v4_step_4', 'imp-57a8ece15d731efb', 4, 'sauce', 'Hòa tan tương Miso sau khi tắt bếp', 'Đặt rây lọc nhỏ (hoặc vá múc canh) chạm mặt nước dùng đang nóng trong nồi, cho 55 g tương Miso Nhật vào và dùng đũa hoặc thìa tán nhẹ cho tương Miso tan mịn hoàn toàn vào nước canh mà không bị vón cục.', 'Luôn tắt bếp trước khi hòa tương Miso và không đun sôi lại nồi súp để giữ nguyên lợi khuẩn và hương thơm tinh tế của Miso.', NULL),
('imp-57a8ece15d731efb_v4_step_5', 'imp-57a8ece15d731efb', 5, 'sauce', 'Nếm chỉnh vị canh với xì dầu Nhật', 'Khuấy nhẹ nồi súp Miso rồi nếm thử; nếu thích vị đậm đà hơn có thể thêm 5 ml xì dầu Nhật (tránh nêm mặn quá vì tương Miso vốn đã có vị mặn dịu).', NULL, NULL),
('imp-57a8ece15d731efb_v4_step_6', 'imp-57a8ece15d731efb', 6, 'finish', 'Múc súp Miso ra bát và hoàn thiện', 'Múc súp Miso bắp cải nấm ra 3 bát, rắc hành lá thái lát xéo lên trên và nhỏ nhẹ 5 ml dầu mè thơm chia đều vào các bát, dùng nóng ngay.', NULL, NULL),
('imp-23a82881883d70fb_v4_step_1', 'imp-23a82881883d70fb', 1, 'prep', 'Ngâm tảo bẹ Kombu và nấm hương khô lấy vị Dashi', 'Lau nhẹ 6 g tảo bẹ Kombu khô bằng khăn ẩm sạch, rửa nhanh 25 g nấm hương khô rồi cho cả hai vào nồi với 900 ml nước lọc lạnh, ngâm tối thiểu 30 phút để Kombu và nấm hương tiết ra vị ngọt umami tự nhiên.', 'Ngâm lạnh trước khi đun giúp tảo bẹ Kombu tiết tối đa vị ngọt thanh mà không cần nấu sôi lâu.', 30),
('imp-23a82881883d70fb_v4_step_2', 'imp-23a82881883d70fb', 2, 'cook', 'Nấu nước dùng Dashi chay và vớt tảo bẹ Kombu', 'Bắc nồi nước ngâm lên bếp lửa vừa, canh ngay khi mặt nước bắt đầu sủi tăm nhẹ chuẩn bị sôi thì vớt bỏ miếng tảo bẹ Kombu ra ngoài. Tiếp tục đun sôi liu riu trên lửa nhỏ 10 phút cho nấm hương mềm ngọt, sau đó vớt nấm hương ra thái lát mỏng để lại vào tô.', 'Vớt tảo bẹ Kombu trước khi nước sôi bùng giúp nước dùng Dashi trong veo và không bị nhớt hoặc đắng.', 10),
('imp-23a82881883d70fb_v4_step_3', 'imp-23a82881883d70fb', 3, 'prep', 'Sơ chế nấm đùi gà, đậu phụ chiên và hành lá', 'Trong lúc nấu nước dùng, lau sạch 200 g nấm đùi gà tươi rồi thái lát dày 5 mm. Đậu phụ chiên sẵn cắt miếng vuông vừa ăn dày 1,5 cm (có thể dội qua chút nước sôi cho bớt dầu); hành lá thái khoanh mỏng để riêng.', 'Thái lát nấm đùi gà dày 5 mm giúp nấm giữ được độ giòn ngọt sần sật khi nấu trong nước dùng.', NULL),
('imp-23a82881883d70fb_v4_step_4', 'imp-23a82881883d70fb', 4, 'cook', 'Nêm nước dùng Dashi chay và nấu nấm đùi gà, đậu phụ', 'Nêm vào nồi nước dùng 22 ml xì dầu Nhật, 22 ml rượu Mirin, 6 g đường cát trắng và 2 g muối ăn, khuấy tan rồi nếm lại vừa miệng. Thả nấm đùi gà và đậu phụ chiên vào nồi nước dùng sôi nhẹ, nấu lửa vừa 4 phút cho nấm chín mềm và đậu phụ thấm vị ngọt thanh.', NULL, 4),
('imp-23a82881883d70fb_v4_step_5', 'imp-23a82881883d70fb', 5, 'cook', 'Luộc riêng mì Udon trong nước sôi', 'Đun sôi 600 ml nước lọc còn lại trong một nồi riêng trên lửa lớn, thả 3 gói mì Udon vào luộc khoảng 2–3 phút, dùng đũa khuấy nhẹ cho sợi mì tơi rời, trong dai rồi vớt ra xả nhanh qua nước ấm và xóc thật ráo nước.', 'Luôn luộc mì Udon ở nồi riêng thay vì luộc thẳng vào nước dùng để nước Dashi chay giữ được độ trong thanh.', 3),
('imp-23a82881883d70fb_v4_step_6', 'imp-23a82881883d70fb', 6, 'finish', 'Trình bày tô mì Udon nấm đậu nóng hổi', 'Chia mì Udon đã ráo nước ra 3 tô lớn, xếp nấm hương thái lát, nấm đùi gà và đậu phụ chiên lên mặt mì, chan ngập nước dùng Dashi đang nóng sôi rồi rắc hành lá thái khoanh lên trên và dùng ngay.', NULL, NULL),
('imp-85a3d8b84fc0bc05_v4_step_1', 'imp-85a3d8b84fc0bc05', 1, 'prep', 'Sơ chế kim chi, hành tỏi và phô mai', 'Thái nhỏ 160 g kim chi cải thảo ủ chua và chắt riêng khoảng 50 ml nước kim chi. Thái lát hành tím khô, băm nhỏ tỏi khô, thái nhỏ hành lá tươi (tách riêng đầu trắng và lá xanh), chuẩn bị sẵn 50 g phô mai Cheddar bào sợi.', NULL, NULL),
('imp-85a3d8b84fc0bc05_v4_step_2', 'imp-85a3d8b84fc0bc05', 2, 'cook', 'Phi thơm hành tỏi và xào kim chi', 'Làm nóng nồi trên lửa vừa với 10 ml dầu thực vật và 10 ml dầu mè rang, cho hành tím khô thái lát, tỏi khô băm nhỏ và đầu hành trắng vào phi thơm 1 phút. Tiếp tục cho kim chi cải thảo cùng 3 g ớt bột Hàn Quốc (Gochugaru) vào đảo đều 2 phút cho kim chi dậy mùi thơm nồng.', 'Xào kim chi với chút dầu mè trước khi đổ nước giúp nước dùng mì có mùi thơm sâu và màu sắc hấp dẫn.', 3),
('imp-85a3d8b84fc0bc05_v4_step_3', 'imp-85a3d8b84fc0bc05', 3, 'cook', 'Nấu sôi nước dùng kim chi đậm vị', 'Rót 800 ml nước lọc cùng phần nước kim chi vào nồi, nêm 6 g hạt nêm vị gà và 3 g đường cát trắng, khuấy đều và đun trên lửa lớn khoảng 3–4 phút cho đến khi nước dùng sôi bùng.', NULL, 4),
('imp-85a3d8b84fc0bc05_v4_step_4', 'imp-85a3d8b84fc0bc05', 4, 'cook', 'Nấu mì ramen vừa chín dai', 'Thả 200 g mì ramen Hàn Quốc (2 vắt mì) vào nồi nước dùng đang sôi, nấu khoảng 2 phút trên lửa vừa đồng thời dùng đũa tách nhẹ cho sợi mì tơi ra nhưng vẫn giữ độ dai giòn.', 'Chỉ nấu mì khoảng 2 phút trước khi cho trứng để tổng thời gian nấu không làm mì bị nhũn nát.', 2),
('imp-85a3d8b84fc0bc05_v4_step_5', 'imp-85a3d8b84fc0bc05', 5, 'cook', 'Đập trứng gà và phủ phô mai Cheddar', 'Hạ lửa nhỏ, gạt nhẹ mì sang hai bên để tạo hai khoảng trống rồi đập 2 quả trứng gà tươi vào nồi, đậy nắp nấu thêm 2 phút cho lòng trắng chín đông còn lòng đỏ sánh lòng đào. Mở nắp, rải đều 50 g phô mai Cheddar bào sợi lên mặt mì rồi đậy nắp thêm 30 giây cho phô mai tan chảy.', 'Phủ phô mai ở bước cuối trên lửa thật nhỏ giúp phô mai tan mịn quyện vào sợi mì mà không bị tách dầu.', 2),
('imp-85a3d8b84fc0bc05_v4_step_6', 'imp-85a3d8b84fc0bc05', 6, 'finish', 'Rưới dầu mè, rắc hành lá và thưởng thức', 'Tắt bếp, rưới 5 ml dầu mè rang còn lại và rắc phần hành lá xanh thái khoanh lên mặt nồi mì; dùng nóng ngay để cảm nhận trọn vẹn vị cay ấm hòa cùng phô mai béo ngậy.', NULL, NULL),
('imp-9d28abab0b8e5619_v4_step_1', 'imp-9d28abab0b8e5619', 1, 'prep', 'Sơ chế đùi gà, kim chi và rau củ', 'Rửa sạch 750 g đùi gà có xương chặt miếng, để ráo và khứa nhẹ vài đường trên thịt để nhanh thấm sốt. Cắt đôi theo chiều dọc 500 g kim chi cải thảo ủ chua kỹ và chắt giữ khoảng 60 ml nước kim chi. Thái múi cau hành tây, cắt khúc 4 cm hành lá tươi.', 'Giữ nguyên bẹ kim chi dài hoặc chỉ cắt làm đôi giúp kim chi khi hầm 30 phút vẫn còn độ mềm dai chứ không bị vụn.', NULL),
('imp-9d28abab0b8e5619_v4_step_2', 'imp-9d28abab0b8e5619', 2, 'sauce', 'Pha hỗn hợp sốt om Gochujang đậm đà', 'Trong tô vừa, khuấy đều 36 g tương ớt Hàn Quốc (Gochujang), 7 g ớt bột Hàn Quốc (Gochugaru), 30 ml nước tương, 15 ml nước mắm cá cơm, 12 g đường cát trắng, 15 ml rượu nấu ăn, 1 g tiêu đen xay, tỏi khô băm nhuyễn và phần nước kim chi cho hòa quyện hoàn toàn.', NULL, NULL),
('imp-9d28abab0b8e5619_v4_step_3', 'imp-9d28abab0b8e5619', 3, 'cook', 'Xếp kim chi, thịt gà và đun sôi nồi hầm', 'Lót một lớp kim chi cải thảo xuống đáy nồi rộng, xếp các miếng đùi gà và hành tây lên trên rồi phủ phần kim chi còn lại xung quanh. Rưới đều tô sốt Gochujang và rót 450 ml nước lọc vào nồi, đậy nắp đun lửa lớn 5 phút đến khi sôi bùng.', 'Xếp kim chi lót đáy nồi vừa giúp thịt gà không bị bén đáy, vừa để kim chi thấm mỡ gà tiết ra rất ngọt.', 5),
('imp-9d28abab0b8e5619_v4_step_4', 'imp-9d28abab0b8e5619', 4, 'cook', 'Hầm liu riu cho đùi gà chín mềm thấm sốt', 'Hạ lửa vừa-nhỏ, đậy nắp hầm 25 phút cho đến khi thịt đùi gà chín mềm hoàn toàn sát xương (không còn nước hồng khi xăm đũa) và kim chi dịu vị chua. Trong quá trình hầm, thỉnh thoảng mở nắp múc nước sốt rưới đều lên mặt thịt gà.', NULL, 25),
('imp-9d28abab0b8e5619_v4_step_5', 'imp-9d28abab0b8e5619', 5, 'cook', 'Cô sánh nước sốt và thêm hành lá', 'Mở nắp nồi, tăng lên lửa vừa nấu thêm 5 phút để phần nước sốt rút bớt, sánh đỏ bóng mượt áo đều lên từng miếng gà và kim chi. Thả hành lá tươi cắt khúc vào đảo nhẹ cho vừa chín tới.', 'Canh độ sánh của sốt theo sở thích: nếu thích chan nhiều nước sốt ăn cơm thì có thể tắt bếp sớm hơn 2 phút.', 5),
('imp-9d28abab0b8e5619_v4_step_6', 'imp-9d28abab0b8e5619', 6, 'finish', 'Rưới dầu mè và dọn nóng', 'Tắt bếp, rưới 10 ml dầu mè rang lên khắp bề mặt nồi gà hầm kim chi, dọn nóng ngay ra bàn cùng cơm trắng nóng hổi.', NULL, NULL),
('imp-2842fe1b767de23d_v4_step_1', 'imp-2842fe1b767de23d', 1, 'prep', 'Băm nhuyễn cà rốt, hành lá và đánh mịn trứng', 'Thái hạt lựu thật nhỏ 27,5 g cà rốt (khoảng 2 mm) và thái nhuyễn 20 g hành lá tươi. Đập 4 quả trứng gà tươi vào tô, thêm 15 ml sữa tươi không đường, 2 g muối ăn và 0,5 g tiêu đen xay rồi đánh tan đều tay. Nên lọc hỗn hợp trứng qua rây rồi mới trộn cà rốt và hành lá vào.', 'Lọc trứng qua rây trước khi trộn rau giúp loại bỏ lợn cợn lòng trắng, bề mặt cuộn trứng láng mịn và dễ cuộn hơn.', NULL),
('imp-2842fe1b767de23d_v4_step_2', 'imp-2842fe1b767de23d', 2, 'cook', 'Đổ và cuộn lớp trứng đầu tiên', 'Làm nóng chảo chống dính đáy phẳng trên lửa nhỏ, dùng giấy thấm phết một lớp mỏng dầu thực vật (khoảng 3 ml). Khuấy đều tô trứng để cà rốt không lắng đáy, rót 1/3 lượng trứng láng kín mặt chảo. Đợi khoảng 1,5 phút khi mặt dưới chín vàng nhẹ còn mặt trên hơi ướt thì nhẹ nhàng cuộn tròn từ một mép chảo sang mép đối diện.', 'Luôn giữ lửa nhỏ trong suốt quá trình tráng để trứng chín từ từ mà không bị cháy sạm hay rỗ mặt.', 2),
('imp-2842fe1b767de23d_v4_step_3', 'imp-2842fe1b767de23d', 3, 'cook', 'Nối thêm lớp trứng thứ hai dày đều', 'Đẩy cuộn trứng về sát mép chảo, phết thêm 3 ml dầu thực vật lên phần mặt chảo trống. Rót tiếp 1/3 lượng trứng vào, nghiêng nhẹ chảo cho trứng chảy vào phần mép dưới cuộn đầu tiên để kết dính. Chờ 1,5 phút cho lớp mới chín tới rồi cuộn ngược lại ôm trọn lớp cũ.', NULL, 2),
('imp-2842fe1b767de23d_v4_step_4', 'imp-2842fe1b767de23d', 4, 'cook', 'Cuộn lớp trứng cuối và ép tạo dáng bầu dục', 'Phết nốt 4 ml dầu thực vật lên phần chảo trống, rót 1/3 lượng trứng còn lại vào nối mép và chiên 1,5 phút rồi cuộn tiếp thành khối trứng dày chắc. Ép nhẹ bốn mặt cuộn trứng vào thành chảo khoảng 30 giây mỗi mặt để định hình dáng chữ nhật hoặc bầu dục gọn đẹp và trứng chín hoàn toàn bên trong.', NULL, 2),
('imp-2842fe1b767de23d_v4_step_5', 'imp-2842fe1b767de23d', 5, 'prep', 'Ủ nguội nhẹ cho khối trứng định hình', 'Gắp cuộn trứng ra thớt hoặc mành tre, cuộn nhẹ giữ dáng trong 3 phút cho hơi nóng tản bớt và kết cấu trứng ổn định chắc chắn trước khi cắt.', 'Để trứng nghỉ 3 phút sau khi chiên giúp lát cắt sắc gọn, các lớp trứng không bị tách rời.', NULL),
('imp-2842fe1b767de23d_v4_step_6', 'imp-2842fe1b767de23d', 6, 'finish', 'Cắt khoanh vừa ăn và dọn kèm xì dầu', 'Dùng dao sắc cắt cuộn trứng Gyeran Mari thành từng khoanh dày khoảng 2 cm, xếp nghiêng đẹp mắt lên đĩa và dọn kèm chén nước tương chấm nhẹ hoặc ăn cùng cơm nóng.', NULL, NULL),
('imp-412960b58d00d211_v4_step_1', 'imp-412960b58d00d211', 1, 'prep', 'Sơ chế tôm tươi, nấm đùi gà và rau gia vị', 'Bóc vỏ, bỏ đầu và rút sạch chỉ đen lưng 350 g tôm tươi, rửa nhanh nước muối loãng rồi để ráo. Thái hạt lựu nhỏ hành tây, thái lát mỏng nấm đùi gà tươi, băm nhuyễn tỏi khô và đầu hành trắng; phần lá xanh hành lá tươi thái khoanh, ớt hiểm đỏ thái lát chéo.', NULL, NULL),
('imp-412960b58d00d211_v4_step_2', 'imp-412960b58d00d211', 2, 'cook', 'Chưng dầu ớt Gochugaru thơm không khét', 'Làm nóng nồi đất hoặc nồi đáy dày trên lửa nhỏ với 15 ml dầu thực vật và 15 ml dầu mè rang, cho đầu hành trắng, tỏi khô băm nhuyễn và hành tây vào đảo 2 phút cho thơm mềm. Tắt hoặc hạ lửa thật nhỏ, cho 24 g ớt bột Hàn Quốc (Gochugaru) vào đảo đều 1 phút thành hỗn hợp dầu ớt đỏ sẫm thơm lừng.', 'Chưng ớt bột Gochugaru ở lửa thật nhỏ để chiết xuất màu đỏ đẹp mà không bị cháy khét gây vị đắng.', 3),
('imp-412960b58d00d211_v4_step_3', 'imp-412960b58d00d211', 3, 'cook', 'Xào tôm và nấu nước dùng cá cơm tảo bẹ', 'Tăng lên lửa vừa, cho tôm tươi và nấm đùi gà tươi vào đảo nhanh 1–2 phút cho tôm vừa chuyển sắc hồng nhẹ, sau đó rót 700 ml nước dùng cá cơm tảo bẹ vào nồi. Nêm 30 ml nước mắm cá cơm và 1 g tiêu đen xay, đun sôi trên lửa lớn.', NULL, 4),
('imp-412960b58d00d211_v4_step_4', 'imp-412960b58d00d211', 4, 'cook', 'Thả đậu phụ non thành từng khối lớn', 'Khi nồi canh sôi bùng và tôm đã chín săn chuyển đỏ đều, nhẹ nhàng múc từng muỗng lớn 600 g đậu phụ non Hàn Quốc (Sundubu) thả vào nồi. Hạ lửa vừa-nhỏ, nấu liu riu khoảng 4 phút cho đậu phụ nóng xuyên tâm và ngấm nước dùng cay thơm.', 'Không khuấy mạnh sau khi cho đậu phụ non để giữ từng mảng đậu to mềm mượt, tan nhẹ khi múc.', 4),
('imp-412960b58d00d211_v4_step_5', 'imp-412960b58d00d211', 5, 'cook', 'Đập trứng gà tươi trực tiếp vào nồi canh', 'Đập nhẹ 3 quả trứng gà tươi vào các khoảng trống trên mặt nồi canh, đậy nắp nấu thêm 2 phút trên lửa nhỏ để lòng trắng chín đông còn lòng đỏ sánh lòng đào (hoặc nấu thêm 1 phút nếu muốn trứng chín kỹ hơn).', NULL, 2),
('imp-412960b58d00d211_v4_step_6', 'imp-412960b58d00d211', 6, 'finish', 'Rắc hành lá, ớt hiểm và thưởng thức nóng', 'Tắt bếp, rắc hành lá tươi thái khoanh cùng ớt hiểm đỏ thái lát lên mặt nồi canh Sundubu Jjigae đang sôi nhẹ; dọn nóng ngay ăn kèm cơm trắng.', 'Khi ăn có thể đánh tan lòng đỏ trứng hòa trực tiếp vào nước canh nóng để tăng độ béo mượt và dịu vị cay.', NULL),
('imp-80976e834de46c34_v4_step_1', 'imp-80976e834de46c34', 1, 'prep', 'Ngâm miến khoai lang, nấm hương và ướp thịt bò', 'Ngâm 15 g nấm hương khô trong 300 ml nước ấm 20 phút cho nở mềm rồi vắt ráo, bỏ chân và thái lát mỏng. Song song, ngâm 160 g miến khoai lang Hàn Quốc (Dangmyeon) trong nước ấm cho mềm dẻo. Ướp chung thịt bò thăn thái sợi và nấm hương với 15 ml nước tương, 6 g đường cát trắng, 2/3 lượng tỏi khô băm nhuyễn, 5 ml dầu mè rang và 1 g tiêu đen xay trong 15 phút.', NULL, 20),
('imp-80976e834de46c34_v4_step_2', 'imp-80976e834de46c34', 2, 'prep', 'Chần rau chân vịt và tráng trứng thái sợi', 'Đun sôi 1,2 lít nước lọc, chần 150 g rau chân vịt 45 giây rồi vớt ra xả nước lạnh, vắt kiệt và trộn với 1 g muối ăn, 1/3 lượng tỏi khô băm nhuyễn cùng 5 ml dầu mè rang. Trên chảo chống dính với 3 ml dầu thực vật ở lửa nhỏ, tráng mỏng 1 quả trứng gà tươi rồi để nguội, thái sợi dài.', 'Tận dụng ngay nồi nước sôi sau khi chần rau chân vịt để luộc miến giúp tiết kiệm thời gian và giữ màu xanh của rau.', NULL),
('imp-80976e834de46c34_v4_step_3', 'imp-80976e834de46c34', 3, 'cook', 'Xào riêng từng loại rau củ giữ màu và độ giòn', 'Làm nóng chảo trên lửa vừa với tổng cộng 15 ml dầu thực vật chia làm nhiều lần để xào riêng từng nguyên liệu trong 1,5–2 phút mỗi loại rồi trút vào tô lớn: hành tây với 0,5 g muối ăn; cà rốt và ớt chuông đỏ với 0,5 g muối ăn; nấm đùi gà tươi với 0,5 g muối ăn; hành lá tươi với 0,5 g muối ăn.', 'Xào riêng từ nguyên liệu nhạt màu trước sang đậm màu sau giúp giữ chảo sạch và rau củ luôn tươi giòn.', 6),
('imp-80976e834de46c34_v4_step_4', 'imp-80976e834de46c34', 4, 'cook', 'Xào chín thịt bò và nấm hương đã ướp', 'Cho 7 ml dầu thực vật còn lại vào chảo đun lửa lớn, trút thịt bò thăn và nấm hương đã ướp vào đảo nhanh tay 3 phút cho đến khi thịt bò chín săn đều, dậy mùi thơm lừng rồi trút chung vào tô rau củ.', NULL, 3),
('imp-80976e834de46c34_v4_step_5', 'imp-80976e834de46c34', 5, 'cook', 'Luộc chín và xào thấm sợi miến khoai lang', 'Luộc miến khoai lang trong nồi nước sôi khoảng 6 phút đến khi sợi miến trong suốt và mềm dai vừa tới (không nhũn), vớt ra xả nhanh nước lạnh, để ráo và cắt bớt cho vừa ăn. Cho miến vào chảo cùng 30 ml nước tương còn lại, 14 g đường cát trắng và 10 ml dầu mè rang, đảo đều trên lửa vừa 2 phút cho miến hút trọn gia vị bóng đẹp.', 'Xào sơ miến với nước tương, đường và dầu mè trước khi trộn rau giúp từng sợi miến thấm đậm vị và không bị dính chùm.', 8),
('imp-80976e834de46c34_v4_step_6', 'imp-80976e834de46c34', 6, 'finish', 'Trộn đều Japchae và trang trí trứng sợi', 'Trút phần miến còn ấm vào tô lớn đựng thịt bò và rau củ, rưới nốt 10 ml dầu mè rang còn lại, rắc 1 g tiêu đen xay và 9 g hạt mè trắng rang rồi dùng tay đeo găng trộn nhẹ nhàng cho tất cả hòa quyện. Bày ra đĩa, xếp trứng gà thái sợi lên trên và thưởng thức.', NULL, NULL),
('imp-8608afb7fee8ebc3_v4_step_1', 'imp-8608afb7fee8ebc3', 1, 'prep', 'Chuẩn bị rau cuốn, hành lá sợi và thịt ba chỉ', 'Rửa sạch xà lách tươi và lá tía tô tươi rồi vẩy thật ráo nước. Thái lát 1 củ tỏi khô để nướng, băm nhuyễn 0,5 củ tỏi khô còn lại để pha sốt, thái lát mỏng 3 quả ớt xanh sừng. Tước sợi dọc hành lá tươi ngâm nước lạnh 5 phút rồi vớt ráo, trộn với 5 ml dầu mè rang. Thấm thật khô các dải thịt ba chỉ heo cắt dày.', 'Thấm thật khô thịt ba chỉ trước khi đặt lên chảo gang giúp bề mặt thịt cháy cạnh vàng giòn nhanh và hạn chế bắn mỡ.', NULL),
('imp-8608afb7fee8ebc3_v4_step_2', 'imp-8608afb7fee8ebc3', 2, 'sauce', 'Pha sốt chấm Ssamjang và chén dầu mè muối tiêu', 'Trong chén thứ nhất, trộn đều 45 g tương đậu Hàn Quốc (Doenjang), 18 g tương ớt Hàn Quốc (Gochujang), 15 ml rượu ngọt Mirin, 5 g đường cát trắng, 15 ml dầu mè rang, tỏi khô băm nhuyễn và 5 g hạt mè trắng rang thành sốt Ssamjang sánh mịn. Ở chén thứ hai, khuấy 15 ml dầu mè rang còn lại với 4 g muối hạt mịn và 0,5 g tiêu đen xay.', 'Chuẩn bị đủ cả hai loại nước chấm Ssamjang và dầu mè muối tiêu giúp thực khách đổi vị linh hoạt theo kiểu ăn truyền thống Hàn Quốc.', NULL),
('imp-8608afb7fee8ebc3_v4_step_3', 'imp-8608afb7fee8ebc3', 3, 'cook', 'Nướng áp chảo ba chỉ heo vàng ruộm hai mặt', 'Làm nóng chảo gang hoặc vỉ nướng trên lửa vừa-lớn (không cần thêm dầu vì thịt ba chỉ sẽ tự tiết mỡ), đặt các dải thịt ba chỉ heo lên chảo, rắc nhẹ 2 g muối hạt mịn và 0,5 g tiêu đen xay. Áp chảo khoảng 4 phút mỗi mặt đến khi thịt chín vàng ruộm giòn cạnh.', NULL, 8),
('imp-8608afb7fee8ebc3_v4_step_4', 'imp-8608afb7fee8ebc3', 4, 'cook', 'Cắt miếng thịt và nướng kèm tỏi lát, kim chi', 'Dùng kéo bếp cắt thịt ba chỉ thành từng miếng dày vừa ăn khoảng 1,5 cm ngay trên chảo. Gạt thịt sang một bên chảo, tận dụng phần mỡ thịt nóng đặt tỏi khô thái lát và kim chi cải thảo vào áp chảo thêm 3–4 phút cho tỏi vàng thơm, kim chi xém cạnh và thịt chín hoàn toàn.', 'Nướng kim chi trực tiếp bằng mỡ tiết ra từ thịt ba chỉ giúp kim chi béo thơm dịu chua và làm phần thịt đỡ ngấy.', 4),
('imp-8608afb7fee8ebc3_v4_step_5', 'imp-8608afb7fee8ebc3', 5, 'cook', 'Giữ nóng thịt ở lửa thật nhỏ', 'Hạ bếp xuống lửa thật nhỏ để thịt ba chỉ, kim chi và tỏi nướng luôn ấm nóng, đồng thời thấm bớt lượng mỡ dư trên chảo bằng một miếng giấy thấm nếu cần.', NULL, NULL),
('imp-8608afb7fee8ebc3_v4_step_6', 'imp-8608afb7fee8ebc3', 6, 'finish', 'Cuốn rau Ssam cùng Ssamjang và thưởng thức', 'Bày đĩa thịt ba chỉ nướng Samgyeopsal cùng kim chi và tỏi nướng ra bàn kèm rổ xà lách tươi, lá tía tô tươi, hành lá sợi, ớt xanh sừng và hai chén nước chấm. Khi ăn chấm miếng thịt vào dầu mè muối tiêu, đặt lên lá xà lách và lá tía tô cùng kim chi, tỏi nướng, chút Ssamjang rồi gói gọn thưởng thức.', NULL, NULL),
('imp-97ba5787e2d4113b_v4_step_1', 'imp-97ba5787e2d4113b', 1, 'prep', 'Sơ chế rau chân vịt, nấm đùi gà và đậu phụ', 'Rửa sạch 150 g rau chân vịt rồi cắt khúc 4 cm. Thái lát vát nấm đùi gà tươi dày 0,5 cm, cắt vuông hành tây 1,5 cm, cắt khối vuông đậu phụ trắng mềm cỡ 2 cm, băm nhuyễn tỏi khô và thái khúc hành lá tươi.', NULL, NULL),
('imp-97ba5787e2d4113b_v4_step_2', 'imp-97ba5787e2d4113b', 2, 'cook', 'Đun sôi nước dùng và đánh tan tương đậu Doenjang', 'Đổ 800 ml nước dùng cá cơm tảo bẹ vào nồi đất hoặc nồi đáy dày, đun sôi trên lửa lớn. Đặt rây lọc lên miệng nồi, cho 36 g tương đậu Hàn Quốc (Doenjang) vào rây rồi dùng muỗng dằm nhẹ cho tương tan đều vào nước dùng đang sôi.', 'Đánh tan Doenjang qua rây giúp nước canh mượt mịn, giữ lại phần xác đậu thô nếu thích hoặc hòa tan hoàn toàn đều ngon.', 4),
('imp-97ba5787e2d4113b_v4_step_3', 'imp-97ba5787e2d4113b', 3, 'cook', 'Nấu hành tây và nấm đùi gà cho ngọt nước', 'Cho hành tây thái vuông, nấm đùi gà tươi và 2 g ớt bột Hàn Quốc (Gochugaru) vào nồi, hạ lửa vừa và nấu liu riu khoảng 5 phút cho hành tây chín trong và nấm tiết vị ngọt thanh.', NULL, 5),
('imp-97ba5787e2d4113b_v4_step_4', 'imp-97ba5787e2d4113b', 4, 'cook', 'Thả đậu phụ trắng và tỏi băm vào nồi canh', 'Nhẹ nhàng thả các khối đậu phụ trắng mềm cùng tỏi khô băm nhuyễn vào nồi canh, nấu thêm 3 phút trên lửa vừa để đậu phụ nóng thấm hương tương đậu lên men mà không bị nát.', 'Cho tỏi băm vào ở công đoạn sau giúp giữ mùi thơm đặc trưng rõ nét của món canh Doenjang.', 3),
('imp-97ba5787e2d4113b_v4_step_5', 'imp-97ba5787e2d4113b', 5, 'cook', 'Chần chín rau chân vịt trong nước canh nóng', 'Cho toàn bộ rau chân vịt cắt khúc vào nồi canh, nhấn nhẹ cho rau ngập nước và nấu thêm 1–2 phút đến khi rau vừa chín mềm vẫn giữ màu xanh mướt.', 'Không nấu rau chân vịt quá lâu để giữ trọn độ giòn ngọt và màu xanh tươi mắt.', NULL),
('imp-97ba5787e2d4113b_v4_step_6', 'imp-97ba5787e2d4113b', 6, 'finish', 'Rắc hành lá, ớt lát và dọn nóng', 'Rắc hành lá tươi và ớt hiểm đỏ thái lát lên mặt nồi canh, tắt bếp rồi dọn nóng ngay ra bàn cùng cơm trắng.', NULL, NULL),
('imp-96d226a7f4d12156_v4_step_1', 'imp-96d226a7f4d12156', 1, 'marinate', 'Ướp thịt ức gà và áo lớp bột bắp khô', 'Trộn đều 500 g ức gà phi lê cắt miếng với 2 g muối ăn, 1 g tiêu đen xay, 1/3 lượng tỏi khô băm nhuyễn, 1/3 lượng gừng tươi băm nhuyễn và 15 ml rượu ngọt Mirin, ướp 15 phút cho thấm vị. Trước khi chiên, cho từng miếng gà vào tô chứa 50 g bột bắp lăn áo thật đều và rũ nhẹ phần bột thừa.', 'Rũ bỏ bột bắp thừa trước khi thả vào chảo dầu giúp dầu chiên sạch, không bị cháy cặn và vỏ gà mỏng giòn.', 15),
('imp-96d226a7f4d12156_v4_step_2', 'imp-96d226a7f4d12156', 2, 'cook', 'Chiên gà lần một ở lửa vừa cho chín bên trong', 'Đun nóng 400 ml dầu thực vật trong nồi sâu lòng trên lửa vừa đến khi nhúng đầu đũa vào thấy sủi tăm đều (khoảng 170°C). Chia gà thành 2 mẻ chiên khoảng 4 phút mỗi mẻ cho đến khi thịt gà chín đều bên trong và lớp bột chuyển màu vàng nhạt, vớt ra giá lưới nghỉ 5 phút.', NULL, 8),
('imp-96d226a7f4d12156_v4_step_3', 'imp-96d226a7f4d12156', 3, 'cook', 'Chiên gà lần hai ở lửa lớn cho vỏ giòn rụm', 'Tăng lửa lớn đun dầu nóng già hơn (khoảng 190°C), thả toàn bộ gà đã chiên lần một vào chiên nhanh thêm 2 phút cho đến khi lớp vỏ phồng giòn rụm và có màu vàng nâu đẹp mắt rồi vớt ra giấy thấm dầu.', 'Kỹ thuật chiên hai lần giúp đẩy hết hơi ẩm ra khỏi lớp vỏ, giữ gà giòn tan ngay cả sau khi áo sốt.', 2),
('imp-96d226a7f4d12156_v4_step_4', 'imp-96d226a7f4d12156', 4, 'sauce', 'Nấu keo sốt cay ngọt mật ong Gochujang', 'Trong chảo rộng sạch trên lửa vừa, cho 20 g tương ớt Hàn Quốc (Gochujang), 50 ml mật ong nguyên chất, 25 g đường nâu, 20 ml nước tương, 20 ml rượu ngọt Mirin còn lại, 25 ml giấm gạo, 1 g tiêu đen xay cùng phần tỏi khô và gừng tươi băm nhuyễn còn lại vào khuấy tan. Đun sôi nhẹ khoảng 3 phút cho hỗn hợp nổi bọt li ti và hơi sánh keo, tắt bếp rồi khuấy thêm 10 ml dầu mè rang.', 'Không đun sốt quá cạn kiệt trên bếp vì mật ong và đường nâu sẽ tiếp tục đặc lại khi nguội bớt.', 3),
('imp-96d226a7f4d12156_v4_step_5', 'imp-96d226a7f4d12156', 5, 'cook', 'Xóc nhanh gà chiên với nước sốt cay ngọt', 'Trút toàn bộ gà chiên giòn vào chảo sốt còn ấm nóng, đảo và xóc nhanh tay trong 30–45 giây cho từng miếng gà áo đều một lớp sốt đỏ cam bóng mượt mà không bị ỉu vỏ.', NULL, NULL),
('imp-96d226a7f4d12156_v4_step_6', 'imp-96d226a7f4d12156', 6, 'finish', 'Rắc đậu phộng, mè rang và thưởng thức nóng', 'Bày gà chiên sốt Dakgangjeong ra đĩa, rắc 20 g đậu phộng rang giã dập, 5 g hạt mè trắng rang và hành lá tươi thái nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-ba1871f088d9a522_v4_step_1', 'imp-ba1871f088d9a522', 1, 'marinate', 'Ướp thịt bò Bulgogi và ngâm miến khoai lang', 'Ngâm 85 g miến khoai lang Hàn Quốc (Dangmyeon) vào tô nước ấm khoảng 20 phút cho sợi mềm dẻo rồi vớt ra để ráo. Trộn 450 g thịt bò thăn thái lát mỏng với 40 ml nước tương, 12 g đường cát trắng, 15 ml mật ong nguyên chất, 15 ml rượu ngọt Mirin, 15 ml dầu mè rang, tỏi khô băm nhuyễn và 1 g tiêu đen xay, ướp 20 phút.', 'Thịt bò thái lát mỏng ngang thớ ướp cùng mật ong và dầu mè sẽ giữ được độ mềm ngọt ngay cả khi nấu trong nước lẩu.', 20),
('imp-ba1871f088d9a522_v4_step_2', 'imp-ba1871f088d9a522', 2, 'prep', 'Sơ chế rau cải thảo, nấm đùi gà và củ cải trắng', 'Cắt khúc 4 cm cải thảo tươi, thái lát dọc dày 0,5 cm nấm đùi gà tươi, thái múi cau hành tây, thái lát mỏng cà rốt và củ cải trắng, cắt khúc 5 cm hành lá tươi và thái lát ớt sừng đỏ.', NULL, NULL),
('imp-ba1871f088d9a522_v4_step_3', 'imp-ba1871f088d9a522', 3, 'cook', 'Nấu ngọt nền nước lẩu cùng củ cải trắng', 'Đổ 1,1 lít nước dùng cá cơm tảo bẹ và thả 90 g củ cải trắng thái lát vào nồi nấu lẩu, đun sôi trên lửa lớn rồi hạ lửa vừa ninh 8 phút cho củ cải tiết vị ngọt thanh. Nêm 15 ml nước tương còn lại và 10 ml nước mắm cá cơm, nếm thử và chỉ thêm tối đa 1 g muối ăn nếu cần cho vừa miệng.', NULL, 8),
('imp-ba1871f088d9a522_v4_step_4', 'imp-ba1871f088d9a522', 4, 'cook', 'Xếp rau nấm, miến và thịt bò vào nồi lẩu', 'Tắt tạm bếp hoặc xếp gọn gàng cải thảo tươi, nấm đùi gà tươi, hành tây, cà rốt và miến khoai lang thành từng cụm xung quanh lòng nồi lẩu nông đáy, đặt thịt bò thăn đã ướp vào phần giữa nồi rồi chan nước dùng nóng ngập khoảng 2/3 nguyên liệu.', 'Xếp từng loại nguyên liệu theo nhóm màu sắc xung quanh thành nồi tạo dáng trình bày đẹp mắt đúng chuẩn lẩu Jeongol.', NULL),
('imp-ba1871f088d9a522_v4_step_5', 'imp-ba1871f088d9a522', 5, 'cook', 'Đun sôi cho thịt bò và rau nấm vừa chín tới', 'Bật bếp vừa-lớn đun sôi lại nồi lẩu khoảng 5 phút, dùng đũa tách nhẹ phần thịt bò để thịt chín đều chuyển màu nâu nhạt, nấm chín giòn và miến trong dai quyện vị ngọt từ thịt.', 'Không đun sôi quá lâu sau khi thịt bò đã chín tới để thịt giữ độ mềm mọng và nước lẩu không bị đục.', 5),
('imp-ba1871f088d9a522_v4_step_6', 'imp-ba1871f088d9a522', 6, 'finish', 'Thêm hành lá, ớt lát và thưởng thức nóng tại bàn', 'Rắc hành lá tươi cắt khúc và ớt sừng đỏ thái lát lên mặt nồi lẩu, giữ bếp ở mức lửa liu riu để thưởng thức nóng hổi cùng cơm trắng hoặc kim chi.', NULL, NULL),
('imp-24fc3ac5cd3ff445_v4_step_1', 'imp-24fc3ac5cd3ff445', 1, 'prep', 'Sơ chế kim chi ủ chua và chuẩn bị cơm nguội', 'Vắt nhẹ 200 g kim chi cải thảo ủ chua kỹ để chắt lấy khoảng 60 ml nước kim chi vào chén, phần cái thái nhỏ cỡ 1 cm. Thái nhỏ hành lá tươi (để riêng đầu hành trắng và lá xanh). Bóp nhẹ hoặc dùng thìa dằm tơi 500 g cơm trắng nấu chín để nguội.', 'Kim chi càng ủ chua kỹ thì khi xào lên càng thơm nồng và không cần nêm thêm giấm hay đường.', NULL),
('imp-24fc3ac5cd3ff445_v4_step_2', 'imp-24fc3ac5cd3ff445', 2, 'sauce', 'Khuấy đều sốt Gochujang và nước kim chi', 'Cho 35 g tương ớt Hàn Quốc (Gochujang), 15 ml nước tương và 60 ml nước kim chi vừa chắt vào chén, khuấy tan đều thành hỗn hợp sốt đỏ sánh mượt để dễ áo đều lên cơm.', NULL, NULL),
('imp-24fc3ac5cd3ff445_v4_step_3', 'imp-24fc3ac5cd3ff445', 3, 'cook', 'Xào săn kim chi với đầu hành trắng', 'Làm nóng chảo rộng trên lửa vừa-lớn với 5 ml dầu thực vật, cho đầu hành trắng vào phi thơm 30 giây rồi trút kim chi cải thảo thái nhỏ vào xào đều tay 3 phút cho kim chi săn ráo bớt nước và dậy mùi thơm.', NULL, 3);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-24fc3ac5cd3ff445_v4_step_4', 'imp-24fc3ac5cd3ff445', 4, 'cook', 'Rang cơm tơi và áo sốt Gochujang', 'Tăng lửa lớn, trút 500 g cơm trắng nguội vào chảo, đảo đều và dàn cơm ép nhẹ xuống mặt chảo khoảng 3 phút cho hạt cơm nóng ráo, săn lại. Rưới đều chén sốt Gochujang vào chảo, đảo nhanh tay thêm 2 phút đến khi cơm nhuộm màu đỏ cam đều đẹp và hơi cháy cạnh thơm lừng.', 'Giữ lửa lớn khi cho cơm và sốt giúp phần nước thừa bay hơi nhanh, hạt cơm tơi bóng mà không bị nhão.', 5),
('imp-24fc3ac5cd3ff445_v4_step_5', 'imp-24fc3ac5cd3ff445', 5, 'cook', 'Chiên 3 trứng gà ốp la lòng đào', 'Trong chảo chống dính nhỏ với 5 ml dầu thực vật còn lại trên lửa vừa, chiên 3 quả trứng gà tươi khoảng 3 phút cho lòng trắng đông chín hoàn toàn còn lòng đỏ sánh lòng đào.', 'Đậy nắp chảo 30 giây cuối nếu thích bề mặt lòng trắng se ráo nhanh mà vẫn giữ được lòng đỏ chảy dẻo.', 3),
('imp-24fc3ac5cd3ff445_v4_step_6', 'imp-24fc3ac5cd3ff445', 6, 'finish', 'Trộn dầu mè rang và bày đĩa cơm chiên', 'Tắt bếp chảo cơm, rưới 15 ml dầu mè rang, rắc phần hành lá xanh và một nửa lượng hạt mè trắng rang vào đảo đều. Xới cơm ra 3 đĩa, đặt trứng ốp la lên trên, rắc nốt phần hạt mè trắng rang cùng rong biển lá khô xé nhỏ rồi thưởng thức ngay khi nóng.', NULL, NULL),
('imp-46962ad0d6f6e63b_v4_step_1', 'imp-46962ad0d6f6e63b', 1, 'prep', 'Băm gà, sơ chế rau thơm và pha sẵn nước sốt', 'Băm nhỏ 450 g ức gà phi lê bằng dao để giữ thớ thịt mềm ngọt. Băm nhỏ 3/4 củ tỏi cùng 3 quả ớt hiểm, thái lát 1 quả ớt sừng đỏ, thái nhỏ 50 g đậu que, cắt khúc 1/2 bó hành lá và nhặt rửa ráo 30 g lá húng quế Thái. Khuấy đều trong chén gồm 22 ml dầu hào, 15 ml xì dầu nhạt, 5 ml xì dầu đen đặc Thái, 15 ml nước mắm ngon và 8 g đường cát trắng.', 'Tự băm thịt ức gà bằng dao thay vì xay nhuyễn giúp món gà xào có độ sần giòn tự nhiên và không bị bở.', NULL),
('imp-46962ad0d6f6e63b_v4_step_2', 'imp-46962ad0d6f6e63b', 2, 'cook', 'Phi thơm tỏi ớt và xào chín tơi thịt gà băm', 'Làm nóng chảo sâu lòng trên lửa vừa lớn với 20 ml dầu ăn, cho tỏi và ớt hiểm băm vào đảo nhanh 20 giây đến khi dậy mùi thơm. Trút toàn bộ ức gà băm vào chảo, dùng xẻng dằm tơi đều tay và xào liên tục 4 phút trên lửa lớn cho đến khi thịt gà chuyển trắng hoàn toàn và săn rời.', 'Xào tơi trên lửa lớn giúp thịt ức gà băm ráo nước nhanh, giữ được độ ngọt mọng bên trong mà không bị khô bã.', 4),
('imp-46962ad0d6f6e63b_v4_step_3', 'imp-46962ad0d6f6e63b', 3, 'cook', 'Xào đậu que và áo sốt đậm đà', 'Thêm đậu que cắt nhỏ và ớt sừng đỏ thái lát vào đảo 1 phút. Rưới hết chén sốt đã pha vào chảo, đảo đều trên lửa lớn thêm 2 phút để sốt sôi quyện bóng đều vào thịt gà và đậu que vừa chín giòn.', 'Để đậu que vào gần cuối giúp đậu giữ màu xanh mướt và độ giòn nhẹ khi ăn cùng cơm nóng.', 3),
('imp-46962ad0d6f6e63b_v4_step_4', 'imp-46962ad0d6f6e63b', 4, 'finish', 'Tắt bếp đảo lá húng quế và hành lá', 'Nhấc chảo khỏi bếp, cho toàn bộ 30 g lá húng quế Thái và hành lá cắt khúc vào đảo nhanh 15 giây cho lá vừa héo thơm nức rồi trút ra đĩa.', 'Đảo húng quế ngay khi tắt bếp giúp lá giữ màu xanh đẹp mà không bị thâm đen hay bay mất tinh dầu.', NULL),
('imp-46962ad0d6f6e63b_v4_step_5', 'imp-46962ad0d6f6e63b', 5, 'cook', 'Chiên 3 quả trứng gà ốp la viền giòn', 'Đun nóng 25 ml dầu ăn còn lại trong chảo nhỏ trên lửa vừa lớn đến khi dầu thật nóng già, đập lần lượt 3 quả trứng gà vào chiên khoảng 2 phút cho viền lòng trắng phồng giòn vàng rụm và lòng đỏ còn sánh dẻo, vớt ra đĩa lót giấy thấm dầu.', NULL, 2),
('imp-46962ad0d6f6e63b_v4_step_6', 'imp-46962ad0d6f6e63b', 6, 'finish', 'Trình bày 3 phần cơm gà Pad Krapow', 'Chia 450 g cơm trắng nóng ra 3 đĩa, múc thịt gà băm xào húng quế vào bên cạnh cơm rồi đặt lên trên mỗi đĩa 1 quả trứng ốp la nóng giòn và thưởng thức ngay.', NULL, NULL),
('imp-f8fc539b7aa359ac_v4_step_1', 'imp-f8fc539b7aa359ac', 1, 'prep', 'Chuẩn bị cơm nguội, tôm, dứa và cà chua', 'Đánh tơi 500 g cơm trắng nguội để hạt cơm rời hẳn không vón cục. Thấm thật khô 250 g tôm tươi đã bóc vỏ rút chỉ lưng. Thái vuông 1/2 quả dứa chín và để ráo nước trên rây; thái hạt lựu 3/4 củ hành tây và 1,5 quả cà chua bỏ ruột; thái nhỏ 1 bó hành lá.', 'Dùng cơm nấu ráo để nguội qua đêm giúp hạt cơm săn chắc, không bị nhão nát khi đảo với dứa tươi.', NULL),
('imp-f8fc539b7aa359ac_v4_step_2', 'imp-f8fc539b7aa359ac', 2, 'sauce', 'Trộn sẵn gia vị khô cà ri và gia vị ướt', 'Trộn đều trong chén gia vị khô gồm 5 g bột cà ri vàng, 8 g đường cát trắng, 2 g muối ăn và 2 g tiêu trắng xay để bột cà ri tơi không vón cục. Pha riêng chén gia vị ướt gồm 15 ml xì dầu và 15 ml nước mắm ngon đặt sẵn cạnh bếp.', 'Pha tách biệt gia vị khô và ướt giúp bạn rắc tơi bột cà ri đều từng hạt cơm rồi mới rưới nước mắm tạo hương thơm bùng vị.', NULL),
('imp-f8fc539b7aa359ac_v4_step_3', 'imp-f8fc539b7aa359ac', 3, 'cook', 'Áp chảo tôm vàng thơm và giữ riêng', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, xếp tôm tươi vào áp chảo mỗi mặt khoảng 1 phút đến khi tôm chuyển màu hồng cam, cạnh hơi xém thơm và chín hoàn toàn bên trong thì gắp ra đĩa riêng, giữ lại dầu thơm trong chảo.', NULL, 2),
('imp-f8fc539b7aa359ac_v4_step_4', 'imp-f8fc539b7aa359ac', 4, 'cook', 'Chiên trứng tơi và đảo cơm cùng hành tây', 'Thêm 25 ml dầu ăn vào chảo trên lửa vừa lớn, đổ 3 quả trứng gà vào đảo nhanh tay đến khi trứng vừa se chín 90% thành từng mảng nhỏ thì trút ngay cơm nguội và hành tây thái hạt lựu vào đảo đều 3 phút cho hạt cơm nóng tơi và áo trứng vàng đều.', NULL, 3),
('imp-f8fc539b7aa359ac_v4_step_5', 'imp-f8fc539b7aa359ac', 5, 'cook', 'Nêm gia vị cà ri và rang cháy cạnh với dứa', 'Rắc toàn bộ chén gia vị khô chứa bột cà ri và rưới đều chén xì dầu nước mắm quanh thành chảo, đảo liên tục 2 phút trên lửa lớn cho hạt cơm thấm vàng óng đều màu. Cho dứa chín vào đảo cùng 2 phút cho dứa nóng thơm, thỉnh thoảng dàn phẳng cơm nghỉ 15 giây rồi đảo tiếp để hạt cơm săn ráo và thơm nhẹ mùi chảo.', 'Rưới nước mắm và xì dầu dọc thành chảo đang nóng sẽ tạo hương thơm dậy mùi mà không làm cơm bị ướt.', 4),
('imp-f8fc539b7aa359ac_v4_step_6', 'imp-f8fc539b7aa359ac', 6, 'finish', 'Trộn tôm, hạt điều, cà chua và hành lá', 'Trút tôm áp chảo vào đảo đều 30 giây rồi tắt bếp. Thêm ngay 75 g hạt điều rang, cà chua thái hạt lựu và hành lá thái nhỏ vào trộn nhanh tay cho giữ trọn độ giòn bùi của hạt điều và màu tươi của rau củ, múc ra đĩa dùng nóng.', NULL, NULL),
('imp-e28e249efceacac7_v4_step_1', 'imp-e28e249efceacac7', 1, 'prep', 'Sơ chế rau thơm, hành tím và rau ăn kèm', 'Thái lát mỏng 40 g hành tím tươi, thái chỉ thật mảnh 3 g lá chanh Thái bỏ gân, nhặt rửa ráo 15 g lá húng lủi, thái khúc 15 g ngò rí và thái nhỏ 1/2 bó hành lá. Tách lá 1/4 bắp cải trắng và thái lát 1 quả dưa leo xếp sẵn ra đĩa. Vắt 2 quả chanh tươi lọc bỏ hạt.', 'Ngâm bắp cải và dưa leo trong nước lạnh vài phút rồi vẩy ráo giúp rau sống giòn ngọt khi ăn kèm thịt bằm chua cay.', NULL),
('imp-e28e249efceacac7_v4_step_2', 'imp-e28e249efceacac7', 2, 'marinate', 'Đánh tơi thịt heo xay với nước mắm', 'Cho 320 g thịt heo xay vào tô, rưới 10 ml nước mắm ngon rồi dùng nĩa trộn bóp nhẹ để các thớ thịt tơi rời hẳn, không bị dính thành mảng dài khi nấu.', NULL, NULL),
('imp-e28e249efceacac7_v4_step_3', 'imp-e28e249efceacac7', 3, 'cook', 'Xào chín mềm thịt heo bằm không dầu mỡ', 'Đun sôi lăn tăn 40 ml nước lọc trong nồi hoặc chảo sâu lòng trên lửa vừa, trút toàn bộ thịt heo xay vào đảo và dằm liên tục khoảng 4 phút đến khi thịt chín trắng hoàn toàn, không còn màu hồng và nước trong thịt tiết ra vừa cạn sánh thì tắt bếp.', 'Nấu chín thịt heo với chút nước lọc thay vì xào dầu giúp món Larb giữ độ ẩm ngọt thanh nhẹ và đậm nước thịt tự nhiên.', 4),
('imp-e28e249efceacac7_v4_step_4', 'imp-e28e249efceacac7', 4, 'sauce', 'Trộn hành tím và lá chanh khi thịt còn ấm', 'Ngay khi vừa tắt bếp lúc thịt còn ấm nóng, cho toàn bộ hành tím thái lát và lá chanh Thái thái chỉ vào đảo đều 1 phút để hơi nóng làm hành tím dịu vị hăng và tỏa hương thơm dịu.', NULL, 1),
('imp-e28e249efceacac7_v4_step_5', 'imp-e28e249efceacac7', 5, 'sauce', 'Nêm nước cốt chanh, ớt bột và thính gạo rang', 'Chờ thêm 2 phút cho thịt nguội bớt không còn bốc hơi nóng gắt rồi rưới 20 ml nước mắm còn lại, nước cốt 2 quả chanh, 3 g đường cát trắng, 3 g ớt bột và 20 g thính gạo rang vào trộn đều tay cho gia vị quyện sánh.', 'Cho nước cốt chanh và thính gạo vào lúc thịt chỉ còn ấm vừa giúp thính không bị vón nhão và giữ vị chua sáng tươi.', 2),
('imp-e28e249efceacac7_v4_step_6', 'imp-e28e249efceacac7', 6, 'finish', 'Trộn rau thơm và dọn kèm rau sống giòn', 'Nếm lại cho vừa vị chua cay mặn ngọt hài hòa rồi thả lá húng lủi, ngò rí và hành lá vào trộn nhẹ tay cho rau không bị dập. Múc gỏi thịt heo bằm ra đĩa, ăn kèm bắp cải tách lá và dưa leo thái lát.', NULL, NULL),
('imp-90fc2e140739a7d7_v4_step_1', 'imp-90fc2e140739a7d7', 1, 'prep', 'Sơ chế phi lê cá và thảo mộc Thái', 'Cắt 500 g phi lê cá thịt trắng thành miếng vuông 3–4 cm để ráo. Thái lát 200 g nấm đùi gà, bổ múi cau 1 quả cà chua. Đập dập và cắt khúc 5 cm phần 2,5 cây sả, thái lát mỏng 30 g củ riềng, xé bỏ gân 5 g lá chanh Thái, đập dập 4 quả ớt hiểm, bổ đôi 30 g hành tím. Cắt khúc 1/2 bó hành lá và thái nhỏ 15 g ngò rí.', 'Cắt phi lê cá thành miếng vuông dày vừa phải giúp cá không bị vỡ vụn khi nấu trong nước dùng nóng.', NULL),
('imp-90fc2e140739a7d7_v4_step_2', 'imp-90fc2e140739a7d7', 2, 'cook', 'Nấu nước dùng thảo mộc thơm nồng', 'Đun sôi 900 ml nước lọc trong nồi trên lửa lớn, thả toàn bộ sả, riềng, lá chanh Thái, hành tím và ớt hiểm vào rồi hạ lửa vừa, nấu liu riu 5 phút cho các loại thảo mộc tiết hết tinh dầu thơm vào nước dùng.', 'Có thể vớt bớt xác sả và riềng ra sau khi nấu thơm nếu muốn tô canh gọn gàng dễ múc.', 5),
('imp-90fc2e140739a7d7_v4_step_3', 'imp-90fc2e140739a7d7', 3, 'cook', 'Nêm vị nền và nấu nấm, cà chua', 'Nêm 45 ml nước mắm ngon cùng 12 g đường thốt nốt vào nồi khuấy tan. Cho 200 g nấm đùi gà và cà chua bổ múi cau vào nấu sôi vừa khoảng 3 phút cho nấm chín mềm ngọt và cà chua tiết màu nhẹ.', NULL, 3),
('imp-90fc2e140739a7d7_v4_step_4', 'imp-90fc2e140739a7d7', 4, 'cook', 'Thả phi lê cá nấu chín nhẹ nhàng', 'Hạ lửa xuống mức vừa để mặt nước chỉ sôi lăn tăn, thả nhẹ từng miếng phi lê cá vào nồi và nấu khoảng 3 phút đến khi thịt cá chuyển trắng đục, săn chắc chín hoàn toàn mà không đảo mạnh tay làm nát miếng cá.', 'Giữ nước sôi lăn tăn và không khuấy đảo sau khi thả cá là bí quyết giữ từng miếng cá nguyên vẹn và nước canh trong veo.', 3),
('imp-90fc2e140739a7d7_v4_step_5', 'imp-90fc2e140739a7d7', 5, 'finish', 'Tắt bếp vắt nước cốt chanh cân vị', 'Tắt bếp chờ nước canh ngừng sôi hẳn mới rưới nước cốt từ 2 quả chanh tươi vào khuấy thật nhẹ tay để giữ trọn hương thơm tươi mát và vị chua thanh mà không bị đắng.', NULL, NULL),
('imp-90fc2e140739a7d7_v4_step_6', 'imp-90fc2e140739a7d7', 6, 'finish', 'Thêm hành ngò và dọn canh Tom Yum nóng', 'Nếm lại cho đạt vị chua cay mặn ngọt cân bằng, thả hành lá cắt khúc vào nồi đảo nhẹ rồi múc canh ra tô, rắc ngò rí thái nhỏ lên trên và dùng nóng ngay.', NULL, NULL),
('imp-8ebb3021c30c48f8_v4_step_1', 'imp-8ebb3021c30c48f8', 1, 'marinate', 'Thái ướp ức gà và pha sốt xào xì dầu', 'Thái lát mỏng 340 g ức gà phi lê rồi bóp đều cùng 10 ml xì dầu nhạt, 2 g đường cát trắng và 15 ml nước lọc, ướp nghỉ 12 phút cho thịt ngậm nước mềm mọng. Pha sẵn hỗn hợp sốt gồm 25 ml dầu hào, 15 ml xì dầu nhạt còn lại và 15 ml xì dầu đen đặc Thái, chia đều thành 3 phần.', NULL, 12),
('imp-8ebb3021c30c48f8_v4_step_2', 'imp-8ebb3021c30c48f8', 2, 'prep', 'Gỡ tơi bánh phở và sơ chế cải thìa', 'Gỡ tơi nhẹ tay 600 g bánh phở tươi thành 3 phần (~200 g/phần) để khi xào áp chảo từng suất không bị dồn cục. Rửa sạch 225 g cải thìa, thái xéo phần cọng và cắt khúc phần lá; băm nhỏ 3/4 củ tỏi khô; chuẩn bị sẵn 3 quả trứng gà bên bếp.', 'Xào Pad See Ew từng phần 1 suất ăn trên chảo rộng giúp sợi phở tiếp xúc mặt chảo nóng, xém cạnh thơm khói mà không bị đứt nát.', NULL),
('imp-8ebb3021c30c48f8_v4_step_3', 'imp-8ebb3021c30c48f8', 3, 'cook', 'Áp chảo chín thơm thịt ức gà', 'Làm nóng chảo đáy rộng trên lửa lớn với 15 ml dầu ăn, dàn đều thịt ức gà đã ướp thành một lớp mỏng và áp chảo khoảng 3 phút đến khi hai mặt hơi xém vàng, thịt chín trắng hoàn toàn thì trút ra đĩa riêng.', 'Áp chảo thịt ức gà thành một lớp mỏng trên lửa lớn giúp thịt săn chín nhanh và giữ được độ mọng nước bên trong.', 3),
('imp-8ebb3021c30c48f8_v4_step_4', 'imp-8ebb3021c30c48f8', 4, 'cook', 'Phi tỏi, đánh trứng tơi và xào cải thìa', 'Cho khoảng 13 ml dầu ăn cùng 1/3 lượng tỏi băm vào chảo xào thơm trên lửa vừa lớn trong 20 giây, đập 1 quả trứng gà vào đánh vỡ lòng đỏ chờ đông một nửa rồi đảo tơi. Cho ngay 1/3 lượng cải thìa vào đảo nhanh tay 15 giây cho rau xanh bóng.', NULL, NULL),
('imp-8ebb3021c30c48f8_v4_step_5', 'imp-8ebb3021c30c48f8', 5, 'cook', 'Áp chảo xém bánh phở cùng sốt xì dầu', 'Cho 1 phần bánh phở (200 g), 1 phần nước sốt xì dầu và 1/3 phần đường cát trắng còn lại (~7 g) vào chảo, tăng lửa lớn và đảo hất nhẹ nhàng cho sợi phở áo đều màu nâu bóng. Dàn phẳng mặt phở để yên 20 giây cho hơi xém cạnh thơm mùi khói chảo rồi lật áp xém thêm 20 giây nữa.', 'Dùng thao tác hất chảo hoặc xẻng lùa từ dưới đáy thay vì chọc thẳng vào sợi phở sẽ giữ sợi bánh nguyên đẹp.', 2),
('imp-8ebb3021c30c48f8_v4_step_6', 'imp-8ebb3021c30c48f8', 6, 'finish', 'Trộn thịt gà và lặp lại cho các phần còn lại', 'Trút 1/3 phần ức gà đã xào vào chảo (chừa lại nước thừa dưới đĩa), đảo nhanh 15 giây cho quyện đều rồi múc ra đĩa. Lau nhanh mặt chảo bằng khăn giấy và lặp lại bước 4–6 cho 2 phần còn lại; rắc 2 g tiêu trắng xay lên trên và dùng nóng.', NULL, NULL),
('imp-8e2f2113f406a7d8_v4_step_1', 'imp-8e2f2113f406a7d8', 1, 'prep', 'Ngâm que tre và xay nhuyễn sốt ướp sả', 'Ngâm que tre vào nước lạnh trước ít nhất 30 phút để que không bị cháy khi nướng. Cho 6 cây sả thái lát mỏng, 1 củ tỏi bóc vỏ và 15 g rễ ngò rí vào máy xay nhuyễn mịn; tiếp tục thêm 45 ml nước cốt dừa, lòng trắng của 1 quả trứng gà, 8 g bột bắp, 15 ml xì dầu nhạt, 20 ml dầu hào, 8 g đường cát trắng, 4 g muối ăn, 2 g tiêu đen xay và 10 ml dầu ăn vào xay quyện thành hỗn hợp sốt ướp sệt thơm.', 'Ngâm ngập que tre trong nước đủ 30 phút sẽ giúp đầu que không bị bén lửa hay đen sạm trên chảo nóng.', 30),
('imp-8e2f2113f406a7d8_v4_step_2', 'imp-8e2f2113f406a7d8', 2, 'marinate', 'Thái dải và ướp thịt đùi gà thấm vị', 'Cắt 600 g thịt đùi gà rút xương thành từng dải dài dày khoảng 1 cm, cho vào tô lớn đổ toàn bộ hỗn hợp sốt sả vừa xay vào bóp trộn đều. Bọc kín tô để ướp trong ngăn mát tối thiểu 30 phút cho gia vị thấm sâu.', NULL, 30),
('imp-8e2f2113f406a7d8_v4_step_3', 'imp-8e2f2113f406a7d8', 3, 'prep', 'Xiên thịt gà vào que tre gọn đẹp', 'Luồn từng dải thịt gà dọc theo chiều dài que tre đã ngâm nước, dàn phẳng nhẹ để miếng thịt áp đều và chừa lại khoảng 1/3 đuôi que trống làm tay cầm tiện lợi.', 'Xiên dải thịt gà theo chiều dọc ôm sát que tre giúp thịt chín đều cả hai mặt khi áp chảo.', NULL),
('imp-8e2f2113f406a7d8_v4_step_4', 'imp-8e2f2113f406a7d8', 4, 'cook', 'Áp chảo mặt đầu và phết nước cốt dừa', 'Làm nóng chảo gang rộng hoặc vỉ nướng trên lửa vừa lớn với 10 ml dầu ăn còn lại, xếp các xiên gà vào áp chảo mặt đầu khoảng 4 phút đến khi xém vàng thơm lừng. Dùng cọ sạch phết nhẹ 15 ml nước cốt dừa giữ riêng lên mặt trên các xiên gà.', 'Chỉ dùng nước cốt dừa sạch chưa chạm thịt sống để phết lên xiên khi nướng nhằm đảm bảo an toàn vệ sinh thực phẩm.', 4),
('imp-8e2f2113f406a7d8_v4_step_5', 'imp-8e2f2113f406a7d8', 5, 'cook', 'Lật mặt nướng chín hoàn toàn các xiên gà', 'Lật đều các xiên gà sang mặt còn lại và nướng tiếp khoảng 5 phút nữa trên lửa vừa đến khi hai mặt xém vàng đều, thịt gà chín kỹ hoàn toàn bên trong không còn màu hồng và nước thịt chảy ra trong.', NULL, 5),
('imp-8e2f2113f406a7d8_v4_step_6', 'imp-8e2f2113f406a7d8', 6, 'finish', 'Nghỉ thịt và dọn kèm chanh tươi', 'Gắp các xiên gà nướng ra đĩa để nghỉ 2 phút cho nước thịt ổn định mọng mềm, xếp 1 quả chanh tươi cắt múi cau bên cạnh và dọn nóng.', NULL, NULL),
('imp-574963de4a60d466_v4_step_1', 'imp-574963de4a60d466', 1, 'prep', 'Làm sạch, khứa mình cá và chuẩn bị xửng hấp', 'Thấm thật khô 650 g cá chẽm đã làm sạch, dùng dao sắc khứa 3 đường chéo sâu tới sát xương trên mỗi mặt mình cá để hơi nóng thấm đều nhanh chín. Đập dập 2 cây sả cắt khúc, nhồi một nửa vào bụng cá và lót phần còn lại dưới đáy đĩa chịu nhiệt rồi đặt cá lên trên.', 'Thấm khô mình cá và lót sả bên dưới giúp cá không bị dính đĩa và khử sạch mùi tanh khi hấp.', NULL),
('imp-574963de4a60d466_v4_step_2', 'imp-574963de4a60d466', 2, 'cook', 'Hấp cá chín mềm giữ trọn vị ngọt', 'Đun sôi mạnh nồi nước hấp trên lửa lớn rồi đặt đĩa cá vào xửng, đậy kín nắp và hấp liên tục 11 phút đến khi mắt cá đục trắng hẳn và dùng đũa tách nhẹ phần thịt dày nhất thấy chín trắng róc xương hoàn toàn.', 'Chỉ đặt cá vào xửng khi nước đã sôi bùng để thịt cá săn nhanh bên ngoài và giữ được vị ngọt mọng bên trong.', 11),
('imp-574963de4a60d466_v4_step_3', 'imp-574963de4a60d466', 3, 'prep', 'Sơ chế tỏi, ớt hiểm và rau thơm ăn kèm', 'Trong lúc hấp cá, băm thật nhỏ 1 củ tỏi khô và 4 quả ớt hiểm tươi, thái lát xéo 1 quả ớt hiểm còn lại để trang trí. Rửa sạch 30 g cần tàu cắt khúc 4 cm và thái nhỏ 15 g ngò rí; vắt lấy nước cốt 2,5 quả chanh tươi lọc bỏ hạt.', NULL, NULL),
('imp-574963de4a60d466_v4_step_4', 'imp-574963de4a60d466', 4, 'sauce', 'Nấu tan đường và pha sốt chanh tỏi ớt', 'Đun sôi 100 ml nước dùng gà với 12 g đường thốt nốt băm nhỏ trong nồi nhỏ khoảng 2 phút đến khi đường tan hoàn toàn rồi tắt bếp, đổ ra tô. Cho tỏi băm, ớt hiểm băm nhỏ, 35 ml nước mắm ngon và nước cốt chanh tươi vào khuấy đều nếm vừa vị chua cay nổi bật.', 'Cho nước cốt chanh và tỏi ớt vào tô nước dùng ấm thay vì đun sôi trực tiếp giúp tỏi giữ mùi thơm cay nồng và chanh không bị đắng.', 2),
('imp-574963de4a60d466_v4_step_5', 'imp-574963de4a60d466', 5, 'finish', 'Chuyển cá sang đĩa sạch và xếp cần tàu', 'Cẩn thận nhấc cá vừa hấp chín sang đĩa bầu dục sâu lòng, bỏ phần nước hấp cá đọng dưới đĩa cũ để món ăn không bị tanh, sau đó xếp phần lớn cần tàu cắt khúc quanh mình cá.', NULL, NULL),
('imp-574963de4a60d466_v4_step_6', 'imp-574963de4a60d466', 6, 'finish', 'Chan sốt nóng và hoàn thiện món cá hấp', 'Trộn 15 g ngò rí thái nhỏ vào tô sốt, khuấy đều rồi rưới toàn bộ sốt chanh tỏi ớt lên khắp mình cá, trang trí thêm vài lá cần tàu và ớt thái lát lên trên rồi dọn nóng ngay.', NULL, NULL),
('imp-295e7045e644d2ca_v4_step_1', 'imp-295e7045e644d2ca', 1, 'prep', 'Ngâm miến, tôm khô và thái mực cùng rau thơm', 'Ngâm 150 g miến khô trong nước lạnh 10 phút cho mềm đều; đồng thời ngâm 15 g tôm khô vào chút nước ấm 10 phút rồi vớt ráo. Thái khoanh 250 g mực ống làm sạch. Thái lát thật mỏng 2 cây sả và 25 g hành tím, cắt khúc 3/4 bó hành lá và 15 g ngò rí, nhặt 10 g lá bạc hà, thái lát 1 quả ớt hiểm.', 'Thái sả thật mỏng theo khoanh tròn để khi trộn gỏi không bị xơ cứng và tỏa mùi thơm dịu.', 10),
('imp-295e7045e644d2ca_v4_step_2', 'imp-295e7045e644d2ca', 2, 'cook', 'Luộc miến dai trong và xả nước lạnh', 'Đun sôi 1000 ml nước lọc trên lửa lớn, thả miến vào luộc nhanh 2 phút đến khi sợi miến chuyển trong mềm thì vớt ra xả ngay dưới vòi nước lạnh cho dai tơi, để thật ráo rồi dùng kéo cắt ngắn khoảng 10 cm.', 'Xả lạnh ngay sau khi luộc giúp sợi miến dong không bị dính bết và giữ được độ dai giòn.', 2),
('imp-295e7045e644d2ca_v4_step_3', 'imp-295e7045e644d2ca', 3, 'cook', 'Chần mực giòn ngọt vừa chín tới', 'Dùng tiếp nồi nước sôi đó chần 250 g mực trong 2 phút đến khi khoanh mực cuộn tròn trắng đục và chín hoàn toàn thì vớt ra ngâm nhanh tô nước nguội rồi để thật ráo nước.', NULL, 2),
('imp-295e7045e644d2ca_v4_step_4', 'imp-295e7045e644d2ca', 4, 'sauce', 'Giã tôm khô tỏi ớt và pha nước trộn gỏi', 'Cho tôm khô đã ngâm mềm cùng 1/2 củ tỏi và 2 quả ớt hiểm vào cối giã dập nhuyễn vừa để dậy vị ngọt thơm cay nồng. Khuấy tan 20 g đường thốt nốt băm nhỏ với 40 ml nước mắm ngon và nước cốt của 2 quả chanh tươi thành hỗn hợp sốt chua mặn ngọt hài hòa.', 'Giã tôm khô cùng tỏi ớt giúp nước trộn gỏi có vị ngọt umami đậm đà và mùi thơm quyện tự nhiên.', NULL),
('imp-295e7045e644d2ca_v4_step_5', 'imp-295e7045e644d2ca', 5, 'finish', 'Trộn miến, mực cùng các loại rau thơm', 'Cho miến đã ráo nước vào âu lớn, rưới nước trộn gỏi vào đảo đều cho từng sợi miến thấm gia vị. Tiếp tục cho mực chần, hỗn hợp tôm khô tỏi ớt giã, sả thái lát, hành tím, hành lá, ngò rí và lá bạc hà vào trộn nhẹ tay cho hòa quyện.', NULL, NULL),
('imp-295e7045e644d2ca_v4_step_6', 'imp-295e7045e644d2ca', 6, 'finish', 'Trình bày và rắc mè rang vàng', 'Nếm lại cho vừa vị chua cay mặn ngọt đặc trưng rồi bày gỏi miến mực ra đĩa sâu lòng, rắc 5 g mè trắng rang vàng cùng ớt thái lát lên trên và dùng ngay.', NULL, NULL),
('imp-5e0a488541baee5e_v4_step_1', 'imp-5e0a488541baee5e', 1, 'prep', 'Thái hành lá, ớt hiểm và chuẩn bị giấy thấm dầu', 'Thái nhỏ 3/4 bó hành lá gồm cả đầu trắng và lá xanh, thái lát mỏng 2 quả ớt hiểm đỏ và nhặt rửa sạch 10 g lá ngò rí để ráo. Lót sẵn 2 lớp giấy thấm dầu lên đĩa rộng và rót 20 ml tương ớt ra chén chấm.', NULL, NULL),
('imp-5e0a488541baee5e_v4_step_2', 'imp-5e0a488541baee5e', 2, 'prep', 'Đánh bông nhẹ trứng gà với nước mắm và chanh', 'Đập 3 quả trứng gà vào tô vừa, thêm 10 ml nước mắm ngon cùng vài giọt nước cốt từ 1/2 quả chanh tươi. Dùng nĩa hoặc phới đánh mạnh tay khoảng 1 phút cho lòng trắng và lòng đỏ hòa đều và nổi lớp bọt mịn trên mặt, sau đó khuấy hành lá cùng ớt hiểm thái lát vào.', 'Đánh trứng nổi bọt khí và thêm vài giọt chanh giúp cấu trúc trứng nhẹ xốp, phồng cao ngay khi gặp dầu nóng.', 1),
('imp-5e0a488541baee5e_v4_step_3', 'imp-5e0a488541baee5e', 3, 'cook', 'Đun nóng già dầu ăn trong chảo nhỏ sâu lòng', 'Đổ 100 ml dầu ăn vào chảo nhỏ sâu lòng hoặc nồi nhỏ đáy dày, đun trên lửa vừa lớn khoảng 2 phút đến khi dầu thật nóng già, lăn tăn gợn sóng. Nhỏ thử 1 giọt trứng vào kiểm tra: nếu trứng sủi bọt và nổi phồng ngay lập tức là đạt nhiệt độ chuẩn.', 'Dùng chảo đường kính nhỏ (~18 cm) giúp lượng dầu sâu hơn và gom miếng trứng dày phồng đẹp mắt.', 2),
('imp-5e0a488541baee5e_v4_step_4', 'imp-5e0a488541baee5e', 4, 'cook', 'Rót trứng từ trên cao và chiên giòn mặt dưới', 'Khuấy nhanh lại tô trứng rồi rót từ độ cao khoảng 15–20 cm theo vòng xoắn ốc vào giữa chảo dầu nóng để trứng tự sủi bọt tạo lớp ren viền giòn xốp. Giữ lửa vừa lớn và chiên yên khoảng 1–2 phút đến khi mặt dưới chuyển vàng nâu giòn rụm và mép trứng phồng giòn.', 'Rót trứng từ trên cao theo dòng nhỏ giúp không khí hòa vào dầu sôi, tạo viền trứng xốp giòn đặc trưng kiểu Thái.', 2),
('imp-5e0a488541baee5e_v4_step_5', 'imp-5e0a488541baee5e', 5, 'cook', 'Lật mặt chiên vàng đều cả hai bên', 'Dùng xẻng bản rộng nhẹ nhàng lật ngửa miếng trứng sang mặt còn lại, chiên tiếp khoảng 30–45 giây cho mặt kia vàng giòn đều mà phần lõi bên trong vẫn giữ được độ mềm béo ẩm mượt.', NULL, NULL),
('imp-5e0a488541baee5e_v4_step_6', 'imp-5e0a488541baee5e', 6, 'finish', 'Thấm ráo dầu thừa và dọn nóng với tương ớt', 'Vớt trứng ra đĩa đã lót sẵn giấy thấm dầu, chấm nhẹ mặt trên để hút bớt dầu thừa rồi chuyển sang đĩa sạch, rắc lá ngò rí tươi lên mặt và dọn nóng cùng chén tương ớt.', NULL, NULL),
('imp-bcc430e4b54c1e65_v4_step_1', 'imp-bcc430e4b54c1e65', 1, 'prep', 'Sơ chế tôm tươi và các loại rau củ', 'Rửa sạch 300 g tôm tươi đã bóc vỏ rút chỉ lưng, để ráo nước. Cắt miếng vuông 3–4 cm phần 1/2 bắp cải trắng, bổ múi cau 2 quả cà chua chín, băm nhỏ 1/2 củ tỏi khô, thái nhỏ đầu hành trắng và cắt khúc 2 cm phần lá xanh của 1 bó hành lá cùng 15 g ngò rí.', NULL, NULL),
('imp-bcc430e4b54c1e65_v4_step_2', 'imp-bcc430e4b54c1e65', 2, 'cook', 'Phi thơm tỏi hành và xào săn tôm tươi', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn, cho tỏi băm và đầu hành trắng vào phi thơm 30 giây đến khi vừa ngả vàng dịu. Trút 300 g tôm tươi vào đảo nhanh tay khoảng 2 phút đến khi bề mặt tôm săn lại và chuyển sắc hồng cam.', 'Xào sơ tôm với tỏi phi trước khi đổ nước giúp thịt tôm thơm ngon hơn và nước canh có độ ngọt béo tự nhiên.', 2),
('imp-bcc430e4b54c1e65_v4_step_3', 'imp-bcc430e4b54c1e65', 3, 'cook', 'Đổ nước lọc đun sôi và hớt sạch bọt', 'Rót 1400 ml nước lọc vào nồi tôm, tăng lửa lớn đun sôi bùng rồi hạ lửa vừa, dùng vá hớt thật sạch lớp bọt nổi trên mặt để nước canh trong vắt đẹp mắt.', NULL, 4),
('imp-bcc430e4b54c1e65_v4_step_4', 'imp-bcc430e4b54c1e65', 4, 'cook', 'Nấu cà chua và bắp cải vừa chín tới', 'Thả cà chua bổ múi cau vào nồi nấu 2 phút cho cà chua hơi mềm và tiết vị ngọt chua thanh. Tiếp tục cho bắp cải vào nấu sôi vừa thêm 4 phút đến khi bắp cải vừa chín mềm trong mà vẫn còn độ giòn ngọt, không bị nhũn nát.', 'Không đun bắp cải quá lâu để giữ trọn độ giòn ngọt tự nhiên và màu xanh trắng tươi sáng của rau.', 6),
('imp-bcc430e4b54c1e65_v4_step_5', 'imp-bcc430e4b54c1e65', 5, 'cook', 'Nêm gia vị xì dầu thanh dịu vừa miệng', 'Nêm vào nồi canh 30 ml xì dầu, 4 g muối ăn và 4 g đường cát trắng, khuấy nhẹ cho gia vị tan đều rồi đun sôi lăn tăn thêm 1 phút, nếm chỉnh lại độ mặn ngọt hài hòa.', NULL, NULL),
('imp-bcc430e4b54c1e65_v4_step_6', 'imp-bcc430e4b54c1e65', 6, 'finish', 'Hoàn thiện với hành ngò và tiêu đen xay', 'Tắt bếp ngay rồi thả phần lá xanh của hành lá và ngò rí cắt khúc vào nồi đảo nhẹ, múc canh ra tô lớn, rắc 2 g tiêu đen xay lên trên và dùng nóng.', 'Cho tiêu đen và hành ngò sau cùng khi tắt bếp giúp giữ được mùi thơm dịu ấm đặc trưng của món canh Tom Chuet.', NULL),
('imp-103ea67cd56c9c96_v4_step_1', 'imp-103ea67cd56c9c96', 1, 'prep', 'Thái ba chỉ và đánh hỗn hợp sốt trứng phô mai', 'Thái 150 g thịt ba chỉ muối xông khói Pancetta thành sợi dày 1 cm. Đập 4 quả trứng gà tươi (ưu tiên lấy lòng đỏ hoặc 1 quả nguyên kèm 3 lòng đỏ cho sốt sánh đậm), cho vào tô cùng 50 g phô mai Pecorino Romano bào mịn và 3 g tiêu đen xay, dùng phới lồng đánh đều thành hỗn hợp sánh mịn.', 'Dùng chủ yếu lòng đỏ trứng giúp sốt Carbonara có màu vàng óng và độ sánh kem mượt mà không bị tanh.', NULL),
('imp-103ea67cd56c9c96_v4_step_2', 'imp-103ea67cd56c9c96', 2, 'cook', 'Áp chảo ba chỉ muối ra mỡ vàng giòn', 'Cho thịt ba chỉ muối vào chảo chống dính khô (không cần thêm dầu), bật lửa vừa-lớn áp chảo khoảng 8–10 phút đến khi thịt tiết mỡ và các cạnh vàng giòn. Có thể thêm tỏi tươi đập dập (nếu dùng) đảo 1 phút cho thơm rồi gắp bỏ tỏi. Vớt thịt ra bát riêng, giữ nguyên phần mỡ nóng trong chảo.', 'Canh lửa vừa để thịt ba chỉ muối tiết mỡ từ từ và giòn đều mà không bị cháy khét gây đắng.', 9),
('imp-103ea67cd56c9c96_v4_step_3', 'imp-103ea67cd56c9c96', 3, 'cook', 'Luộc mì Ý Spaghetti và giữ nước tinh bột', 'Trong lúc áp chảo thịt, đun sôi mạnh nồi lớn với 3 lít nước lọc và 15 g muối hạt. Cho 320 g mì Ý Spaghetti khô vào luộc khoảng 8 phút đến độ al dente. Trước khi vớt mì, múc giữ lại khoảng 100 ml nước luộc mì nóng.', NULL, 8),
('imp-103ea67cd56c9c96_v4_step_4', 'imp-103ea67cd56c9c96', 4, 'sauce', 'Áo mì qua nền mỡ ba chỉ và nước luộc', 'Tắt bếp chảo mỡ ba chỉ để chảo nguội bớt 1 phút. Rưới khoảng 50 ml nước luộc mì vào chảo mỡ, trút mì Ý đã vớt sang chảo rồi đảo nhanh tay cho sợi mì thấm đều lớp nhũ tương mỡ thịt nóng ấm.', NULL, NULL),
('imp-103ea67cd56c9c96_v4_step_5', 'imp-103ea67cd56c9c96', 5, 'cook', 'Trộn sốt trứng phô mai ngoài bếp lửa', 'Nhấc hẳn chảo mì khỏi bếp để tránh quá nhiệt, đổ từ từ hỗn hợp trứng và phô mai Pecorino vào, vừa đổ vừa đảo và xóc liên tục 1–2 phút. Thêm từng muỗng nước luộc mì còn lại nếu sốt quá đặc đến khi tạo thành lớp kem bóng mượt bám đều sợi mì.', 'Tuyệt đối tắt bếp và nhấc chảo khỏi nguồn nhiệt trước khi đổ trứng để nhiệt dư chỉ làm chín mượt sốt mà không biến thành trứng bác lợn cợn.', 2),
('imp-103ea67cd56c9c96_v4_step_6', 'imp-103ea67cd56c9c96', 6, 'finish', 'Trộn ba chỉ giòn và dọn nóng ngay', 'Trút phần lớn thịt ba chỉ giòn trở lại chảo đảo đều lần cuối. Chia mì ra 4 đĩa sâu lòng, rắc phần thịt giòn còn lại cùng 10 g phô mai Pecorino Romano bào và 1 g tiêu đen xay lên trên, thưởng thức nóng ngay.', NULL, NULL),
('imp-34505f9722b38fc1_v4_step_1', 'imp-34505f9722b38fc1', 1, 'prep', 'Băm nhuyễn rau củ soffritto và thái ba chỉ', 'Gọt vỏ cà rốt, rửa sạch cần tây và bóc vỏ hành tây vàng, băm thật nhuyễn cả ba loại (cùng 2 tép tỏi tươi băm nếu dùng) để rau tan quyện vào sốt khi hầm. Thái 100 g thịt ba chỉ muối Pancetta thành hạt lựu nhỏ 5 mm.', NULL, NULL),
('imp-34505f9722b38fc1_v4_step_2', 'imp-34505f9722b38fc1', 2, 'cook', 'Áp chảo thịt ba chỉ, thịt bò và thịt heo xay', 'Đun nóng 25 ml dầu ô liu nguyên chất và 20 g bơ lạt trong nồi đáy dày ở lửa vừa, cho thịt ba chỉ muối vào đảo 4 phút cho ra mỡ và hơi xém cạnh. Trút 300 g thịt bò xay và 150 g thịt heo xay vào dàn mỏng, để yên 2 phút cho mặt dưới xém vàng rồi dằm tơi, đảo thêm 6 phút đến khi thịt chín săn hết màu hồng. Nêm 3 g muối ăn và 2 g tiêu đen xay.', 'Để thịt áp chảo xém vàng nhẹ trước khi đảo tơi giúp kích hoạt hương thơm đậm đà đặc trưng cho Ragù.', 10),
('imp-34505f9722b38fc1_v4_step_3', 'imp-34505f9722b38fc1', 3, 'cook', 'Xào mềm rau củ và khử rượu vang đỏ', 'Cho hỗn hợp cà rốt, cần tây, hành tây (và tỏi băm nếu dùng) vào nồi thịt, đảo đều khoảng 6 phút ở lửa vừa đến khi rau củ mềm trong. Tăng lửa lớn, đổ 100 ml rượu vang đỏ nấu ăn vào khuấy đều 3 phút đến khi bay hết mùi cồn.', NULL, 9),
('imp-34505f9722b38fc1_v4_step_4', 'imp-34505f9722b38fc1', 4, 'sauce', 'Hầm chậm sốt cà chua Ragù sánh đậm', 'Thêm 300 g cà chua nghiền nhuyễn Passata và 30 g cà chua cô đặc (nếu dùng) cùng 2 g muối ăn còn lại vào nồi, đảo đều đun sôi nhẹ. Hạ lửa thật nhỏ, đậy vung hờ và hầm ít nhất 60 phút, mỗi 15 phút khuấy một lần và châm từng ít nước dùng bò (nếu dùng) khi thấy sốt đặc khô.', 'Sốt Ragù đạt chuẩn khi thịt mềm nhừ, nước sốt sánh quyện và có lớp mỡ đỏ óng nổi nhẹ trên mặt.', 60),
('imp-34505f9722b38fc1_v4_step_5', 'imp-34505f9722b38fc1', 5, 'cook', 'Luộc mì Ý Spaghetti độ al dente', 'Khi sốt gần hầm xong, đun sôi mạnh nồi với 3 lít nước lọc và 10 g muối ăn. Thả 320 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút để mì đạt độ dai vừa tới, giữ lại 100 ml nước luộc mì trước khi vớt.', 'Nên chừa lại khoảng 100 ml nước luộc mì giàu tinh bột để làm bóng và kết nối sốt thịt vào sợi mì.', 9),
('imp-34505f9722b38fc1_v4_step_6', 'imp-34505f9722b38fc1', 6, 'finish', 'Trộn mì quyện sốt và rắc phô mai Parmesan', 'Trút mì Ý vào nồi sốt Ragù cùng 2–3 muỗng canh nước luộc mì, đảo đều tay 2 phút trên lửa vừa để sốt bám đều từng sợi mì. Nếm lại cho vừa miệng, chia ra 4 đĩa sâu lòng và rắc 40 g phô mai Parmesan bào lên trên nếu thích.', NULL, NULL),
('imp-266d7af134d7286a_v4_step_1', 'imp-266d7af134d7286a', 1, 'prep', 'Sơ chế nấm đùi gà, tỏi và ngò tây', 'Dùng khăn ẩm lau sạch 225 g nấm đùi gà tươi (không rửa ngập nước để nấm khỏi nhũn), cắt bỏ phần gốc già rồi thái lát dày 0,5 cm. Bóc vỏ, băm nhỏ 3 tép tỏi tươi; rửa sạch và thái nhỏ 10 g ngò tây tươi.', NULL, NULL),
('imp-266d7af134d7286a_v4_step_2', 'imp-266d7af134d7286a', 2, 'cook', 'Luộc mì Ý Spaghetti giữ lại nước tinh bột', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc và 8 g muối ăn. Thả 255 g mì Ý Spaghetti khô vào luộc khoảng 8 phút (ít hơn 1 phút so với hướng dẫn bao bì) để đạt độ al dente. Múc giữ lại 150 ml nước luộc mì rồi vớt mì ra.', NULL, 8),
('imp-266d7af134d7286a_v4_step_3', 'imp-266d7af134d7286a', 3, 'cook', 'Xào vàng nấm đùi gà với bơ tỏi', 'Làm nóng chảo lớn trên lửa vừa với 20 g bơ lạt và 15 ml dầu ô liu. Cho tỏi băm vào phi thơm 30 giây, sau đó trút nấm đùi gà vào xào khoảng 7 phút đến khi nấm ra hết nước, săn lại và vàng đều hai mặt. Nêm 4 g muối ăn và 1,5 g tiêu đen xay.', 'Không đảo nấm liên tục trong 3 phút đầu để bề mặt nấm tiếp xúc nhiệt tốt và lên màu vàng nâu hấp dẫn.', 7),
('imp-266d7af134d7286a_v4_step_4', 'imp-266d7af134d7286a', 4, 'sauce', 'Nấu sốt kem tươi và sữa tươi sánh nhẹ', 'Hạ lửa nhỏ, rót 150 ml kem tươi và 100 ml sữa tươi không đường vào chảo nấm, khuấy nhẹ cho hòa quyện. Đun liu riu khoảng 3 phút cho sốt hơi sánh lại mà không để sôi bùng tránh tách béo.', 'Giữ sốt kem sôi lăn tăn nhẹ thay vì sôi mạnh để kết cấu kem sữa mịn mượt và không bị tách váng.', 3),
('imp-266d7af134d7286a_v4_step_5', 'imp-266d7af134d7286a', 5, 'cook', 'Trộn mì Ý và làm tan phô mai Parmesan', 'Cho mì Ý Spaghetti đã vớt vào chảo sốt, đảo đều 2 phút trên lửa nhỏ-vừa để từng sợi mì thấm kem; thêm dần từng muỗng nước luộc mì nếu sốt đặc. Tắt bếp rồi rắc 25 g phô mai Parmesan bào vào đảo nhanh đến khi phô mai tan mượt.', 'Chỉ cho phô mai vào khi đã tắt bếp hoặc lửa thật nhỏ để phô mai tan đều mịn, không bị vón sợi.', 2),
('imp-266d7af134d7286a_v4_step_6', 'imp-266d7af134d7286a', 6, 'finish', 'Hoàn thiện với ngò tây và dọn nóng', 'Nếm lại gia vị, rắc 10 g ngò tây tươi thái nhỏ vào đảo nhẹ. Chia mì ra 3 đĩa sâu lòng, rắc thêm 10 g phô mai Parmesan bào còn lại cùng 0,5 g tiêu đen xay lên trên và thưởng thức nóng ngay.', NULL, NULL),
('imp-8b2c852ba59f2143_v4_step_1', 'imp-8b2c852ba59f2143', 1, 'prep', 'Đun nóng nước dùng và sơ chế nấm, rau bina', 'Đun sôi lăn tăn 1 lít nước dùng rau củ trên bếp nhỏ để giữ nóng liên tục. Lau sạch 280 g nấm đùi gà tươi bằng khăn ẩm rồi thái lát dày 0,5 cm. Rửa sạch và để ráo 100 g rau bina tươi; băm nhỏ hành tây và tỏi tươi.', NULL, NULL),
('imp-8b2c852ba59f2143_v4_step_2', 'imp-8b2c852ba59f2143', 2, 'cook', 'Xào thơm hành tỏi và áp chảo nấm vàng cạnh', 'Làm nóng nồi đáy dày trên lửa vừa với 20 ml dầu ô liu nguyên chất và 15 g bơ lạt, cho hành tây vào xào 4 phút đến khi mềm trong rồi thêm tỏi băm đảo 1 phút. Tăng lửa lớn, cho nấm đùi gà vào xào khoảng 5 phút đến khi nấm xém vàng và thơm, nêm 2 g muối ăn.', 'Xào nấm trên lửa lớn giúp nước nấm bay hơi nhanh, giữ được độ giòn ngọt mà không bị sũng nước.', 9),
('imp-8b2c852ba59f2143_v4_step_3', 'imp-8b2c852ba59f2143', 3, 'cook', 'Rang gạo Arborio và khử rượu vang trắng', 'Hạ về lửa vừa, đổ 250 g gạo Ý Arborio vào đảo đều 2 phút cho từng hạt gạo áo dầu và trong mờ ở viền. Rót 80 ml rượu vang trắng khô vào khuấy liên tục 2 phút đến khi rượu bay hơi gần hết.', NULL, 4),
('imp-8b2c852ba59f2143_v4_step_4', 'imp-8b2c852ba59f2143', 4, 'cook', 'Om cơm Risotto từng vá nước dùng nóng', 'Múc từng vá nước dùng rau củ nóng (~120 ml) chế vào nồi gạo, khuấy đều tay để tinh bột gạo tiết ra sánh mịn; đợi nước rút gần hết mới châm vá kế tiếp. Lặp lại thao tác này khoảng 18 phút đến khi hạt gạo chín mềm ngoài, hơi dai nhẹ ở lõi.', 'Không đổ nước dùng ồ ạt một lần vì gạo sẽ bị luộc nhão mà mất đi độ sánh kem đặc trưng.', 18),
('imp-8b2c852ba59f2143_v4_step_5', 'imp-8b2c852ba59f2143', 5, 'cook', 'Trộn rau bina tươi giữ màu xanh mướt', 'Khi cơm đã gần đạt độ chín mong muốn, thả 100 g rau bina tươi vào nồi, đảo nhanh tay khoảng 2 phút cho lá vừa héo mềm và hòa quyện đều vào cơm mà vẫn giữ được màu xanh tươi.', NULL, 2),
('imp-8b2c852ba59f2143_v4_step_6', 'imp-8b2c852ba59f2143', 6, 'finish', 'Đánh bóng bơ phô mai và dọn nóng', 'Tắt bếp, cho 15 g bơ lạt lạnh còn lại cùng 30 g phô mai Parmesan bào mịn vào đánh mạnh tay 1 phút đến khi cơm bóng mượt. Đậy nắp nghỉ 1 phút, nêm lại 2 g muối ăn còn lại và 1,5 g tiêu đen xay rồi múc ra 3 đĩa sâu lòng dùng nóng ngay.', 'Dùng bơ lạt thật lạnh cho bước đánh bóng cuối khi đã tắt bếp giúp Risotto đạt độ sánh kem óng mượt.', NULL),
('imp-de5ce12092f4f0aa_v4_step_1', 'imp-de5ce12092f4f0aa', 1, 'prep', 'Làm xẹp và vắt ráo rau bina tươi', 'Rửa sạch 250 g rau bina tươi qua nhiều lần nước cho hết cát, nhặt bỏ cuống già. Cho rau vào chảo khô trên lửa vừa (không thêm dầu hay nước), đảo khoảng 2 phút cho rau xẹp hết rồi trút ra rổ để nguội bớt, dùng tay vắt thật ráo nước và thái thô.', 'Vắt thật kiệt nước ở rau bina là bước quan trọng nhất để món Frittata không bị chảy nước hay nhão.', 2),
('imp-de5ce12092f4f0aa_v4_step_2', 'imp-de5ce12092f4f0aa', 2, 'cook', 'Phi thơm hành tây, tỏi và xào lại rau bina', 'Làm sạch chảo, cho 12 ml dầu ô liu vào đun lửa vừa. Cho hành tây thái hạt lựu vào phi 3 phút đến khi mềm trong, thêm tỏi băm (nếu dùng) đảo 30 giây. Trút rau bina đã vắt ráo vào đảo 1 phút cùng 1 g muối ăn và 0,5 g tiêu đen xay, tắt bếp để nguội 4 phút.', NULL, 4),
('imp-de5ce12092f4f0aa_v4_step_3', 'imp-de5ce12092f4f0aa', 3, 'prep', 'Đánh bông trứng gà với hai loại phô mai', 'Đập 6 quả trứng gà tươi ra tô lớn, đánh mạnh tay bằng phới lồng khoảng 1 phút cho trứng bông nhẹ. Thêm 40 g phô mai Parmesan bào, 60 g phô mai Mozzarella bào sợi, 30 ml sữa tươi không đường (nếu dùng), 3 g muối ăn và 1 g tiêu đen xay vào khuấy đều. Trút hỗn hợp rau đã nguội bớt vào trộn đều.', 'Phải đợi rau nguội bớt mới trộn vào trứng để tránh làm trứng bị chín vón lợn cợn trước khi chiên.', NULL),
('imp-de5ce12092f4f0aa_v4_step_4', 'imp-de5ce12092f4f0aa', 4, 'cook', 'Chiên chậm Frittata ở lửa nhỏ và đậy vung', 'Lau sạch chảo chống dính đường kính 24 cm, tráng 13 ml dầu ô liu còn lại trên lửa nhỏ-vừa rồi đổ hỗn hợp trứng rau vào dàn đều mặt. Để yên 2 phút cho mép trứng se lại, dùng phới đẩy nhẹ mép vào giữa và nghiêng chảo cho trứng lỏng chảy xuống đáy lặp lại trong 6 phút, sau đó đậy nắp nấu thêm 2 phút cho mặt trên se đặc.', NULL, 8),
('imp-de5ce12092f4f0aa_v4_step_5', 'imp-de5ce12092f4f0aa', 5, 'cook', 'Lật mặt áp vàng hai bên khối Frittata', 'Úp một chiếc đĩa phẳng lớn lên miệng chảo, dứt khoát lật ngược khối Frittata ra đĩa rồi nhẹ nhàng trượt mặt còn lại xuống chảo. Áp chảo thêm khoảng 3 phút trên lửa nhỏ đến khi cả hai mặt đều vàng đẹp và phần lõi trứng chín chắc hoàn toàn.', 'Chiên ở lửa nhỏ giúp khối trứng dày chín đều vào tận lõi mà mặt đáy không bị cháy khét.', 3),
('imp-de5ce12092f4f0aa_v4_step_6', 'imp-de5ce12092f4f0aa', 6, 'finish', 'Nghỉ ngắn, cắt múi tam giác và thưởng thức', 'Trượt Frittata ra đĩa lớn, để nghỉ 2 phút cho kết cấu định hình chắc rồi cắt thành 6 múi tam giác đều nhau, thưởng thức khi còn ấm nóng hoặc ở nhiệt độ phòng.', NULL, NULL),
('imp-b8d2cb0b37dbdb81_v4_step_1', 'imp-b8d2cb0b37dbdb81', 1, 'prep', 'Sơ chế ức gà và vắt nước cốt chanh vàng', 'Rửa sạch 450 g ức gà phi lê, thấm thật khô bằng khăn giấy rồi cắt thành các miếng đều nhau dày khoảng 1,5 cm. Bào lấy vỏ vàng của 1,5 quả chanh vàng tươi (tránh phần cùi trắng đắng) và vắt lấy khoảng 70 ml nước cốt; băm nhỏ tỏi tươi và lá hương thảo.', NULL, NULL),
('imp-b8d2cb0b37dbdb81_v4_step_2', 'imp-b8d2cb0b37dbdb81', 2, 'prep', 'Áo lớp bột mì mỏng lên từng miếng gà', 'Cho 20 g bột mì đa dụng ra đĩa rộng, lăn đều hai mặt từng miếng ức gà qua bột rồi giũ nhẹ tay cho rớt bớt phần bột thừa để chỉ còn lại lớp áo thật mỏng.', 'Lớp bột mì mỏng giúp miếng gà giữ ẩm bên trong khi áp chảo và tự động làm sánh mượt nước sốt chanh ở bước sau.', NULL),
('imp-b8d2cb0b37dbdb81_v4_step_3', 'imp-b8d2cb0b37dbdb81', 3, 'cook', 'Áp chảo ức gà vàng đều hai mặt', 'Làm nóng chảo lớn trên lửa vừa với 25 ml dầu ô liu nguyên chất và 20 g bơ lạt. Khi bơ tan sủi bọt, xếp gà thành một lớp phẳng không chồng lên nhau, áp chảo khoảng 3–4 phút mỗi mặt đến khi vàng đều hai bên rồi gắp gà ra đĩa giữ ấm.', 'Không đảo lật gà quá sớm trong 3 phút đầu để lớp vỏ bột áp chảo xém vàng đẹp và không bị bong.', 7),
('imp-b8d2cb0b37dbdb81_v4_step_4', 'imp-b8d2cb0b37dbdb81', 4, 'sauce', 'Phi tỏi hương thảo và cạo đáy chảo làm sốt', 'Hạ lửa vừa-nhỏ trên cùng chảo đó, cho tỏi băm và lá hương thảo vào phi nhanh 30 giây cho thơm (không để tỏi cháy). Đổ 100 ml nước lọc và nước cốt chanh vàng vào, dùng muỗng gỗ cạo sạch phần cháy xém ngon dưới đáy chảo.', NULL, 2),
('imp-b8d2cb0b37dbdb81_v4_step_5', 'imp-b8d2cb0b37dbdb81', 5, 'cook', 'Rim gà thấm sốt chanh đến khi chín thấu', 'Trút ức gà trở lại chảo cùng vỏ chanh vàng bào, nêm 5 g muối ăn và 1,5 g tiêu đen xay. Rim liu riu khoảng 4 phút, trở mặt nhẹ nhàng cho thịt gà chín hoàn toàn hết phần lõi hồng và sốt hơi sánh ôm quanh miếng thịt.', NULL, 4),
('imp-b8d2cb0b37dbdb81_v4_step_6', 'imp-b8d2cb0b37dbdb81', 6, 'finish', 'Đánh bóng sốt với bơ lạnh và dọn nóng', 'Tắt bếp hoàn toàn, thả 15 g bơ lạt lạnh cắt nhỏ vào chảo rồi lắc nhẹ và đảo đều đến khi bơ tan chảy tạo lớp sốt chanh bơ bóng mượt. Xếp gà ra đĩa, rưới sốt lên trên và rắc ngò tây tươi (nếu dùng) rồi thưởng thức nóng ngay.', 'Đánh tan bơ lạnh ngoài bếp lửa giúp sốt chanh bơ sánh óng ánh mà không bị tách nước hay ngấy dầu.', NULL),
('imp-a4d02f2246e0e115_v4_step_1', 'imp-a4d02f2246e0e115', 1, 'prep', 'Thấm khô, ướp gia vị và áo bột đùi gà', 'Rửa sạch 750 g đùi gà có da có xương, thấm thật khô bằng khăn giấy. Xoa đều 3 g muối ăn và 1 g tiêu đen xay lên các mặt gà rồi rắc 16 g bột mì đa dụng áo thành lớp mỏng, giũ bỏ bột thừa. Chuẩn bị sẵn nấm đùi gà thái lát, cà chua chín băm nhỏ, hành tây thái lát, cần tây và tỏi băm.', 'Thấm thật khô da gà giúp khi áp chảo gà nhanh vàng giòn và không làm dầu bị bắn.', NULL),
('imp-a4d02f2246e0e115_v4_step_2', 'imp-a4d02f2246e0e115', 2, 'cook', 'Áp chảo đùi gà vàng đều các mặt', 'Đun nóng chảo lớn sâu lòng trên lửa vừa-cao với 30 ml dầu ô liu nguyên chất. Đặt gà mặt da úp xuống áp chảo tổng cộng khoảng 8–10 phút, trở đều các mặt đến khi da gà vàng nâu đẹp mắt thì gắp gà ra đĩa, giữ lại ít mỡ thơm trong chảo.', NULL, 9),
('imp-a4d02f2246e0e115_v4_step_3', 'imp-a4d02f2246e0e115', 3, 'cook', 'Xào mềm hành tây, cần tây và nấm đùi gà', 'Cho hành tây vào chảo đậy nắp xào 2 phút ở lửa vừa cho bắt đầu mềm. Mở nắp, thêm nấm đùi gà thái lát, cần tây, tỏi băm, lá hương thảo và Oregano khô cùng 2 lá nguyệt quế khô vào đảo đều khoảng 5 phút đến khi nấm cạn nước và dậy mùi thơm.', NULL, 7),
('imp-a4d02f2246e0e115_v4_step_4', 'imp-a4d02f2246e0e115', 4, 'sauce', 'Khử rượu vang trắng và nấu nền cà chua', 'Đổ 120 ml rượu vang trắng khô vào chảo, đun sôi 2 phút đồng thời dùng muỗng gỗ cạo sạch phần cháy xém dưới đáy chảo cho đến khi bay hết mùi cồn. Trút cà chua chín băm nhỏ, ớt vảy khô (nếu dùng), nước dùng gà (nếu cần), 3 g muối ăn và 0,5 g tiêu đen xay còn lại vào đảo đều.', 'Cạo sạch phần xém vàng dưới đáy chảo khi khử rượu vang sẽ mang lại chiều sâu hương vị cho nước sốt om.', 2),
('imp-a4d02f2246e0e115_v4_step_5', 'imp-a4d02f2246e0e115', 5, 'cook', 'Om chậm đùi gà thấm sốt cà chua', 'Xếp đùi gà trở lại chảo, múc sốt rưới phủ lên mặt thịt. Đậy nắp hờ, hạ lửa nhỏ và om liu riu khoảng 25 phút đến khi thịt gà chín mềm, xiên vào sát xương không còn nước hồng và nước sốt sánh đỏ đậm.', 'Nếu sốt còn hơi loãng sau khi gà chín, gắp gà ra đĩa rồi đun sôi sốt 2–3 phút cho cô sánh lại trước khi rưới lên gà.', 25),
('imp-a4d02f2246e0e115_v4_step_6', 'imp-a4d02f2246e0e115', 6, 'finish', 'Vớt lá nguyệt quế, rắc ngò tây và dọn nóng', 'Vớt bỏ lá nguyệt quế khô ra khỏi chảo, nếm lại gia vị cho vừa miệng. Để món ăn nghỉ 10 phút cho hương vị hòa quyện sâu hơn, rắc 15 g ngò tây tươi thái nhỏ lên trên rồi dọn nóng.', NULL, NULL),
('imp-a60814a4aca4143b_v4_step_1', 'imp-a60814a4aca4143b', 1, 'prep', 'Chuẩn bị vụn ruột bánh mì và trộn thịt bò', 'Cắt bỏ phần vỏ cứng của 3 lát ruột bánh mì gối tươi, xé nhỏ hoặc xay vụn mịn (trộn với 60 ml sữa tươi nếu dùng). Cho 500 g thịt bò xay, vụn bánh mì, 50 g phô mai Parmesan bào, 50 g phô mai Pecorino bào, 2 quả trứng gà tươi, 10 g ngò tây tươi băm, 0,5 g nhục đậu khấu xay, 4 g muối ăn và 2 g tiêu đen xay vào tô lớn, nhào vừa đủ quyện đều.', 'Dùng ruột bánh mì tươi thay vụn khô giúp viên thịt bò giữ ẩm và mềm xốp sau khi om.', NULL),
('imp-a60814a4aca4143b_v4_step_2', 'imp-a60814a4aca4143b', 2, 'marinate', 'Ướp lạnh hỗn hợp thịt và vo viên vừa ăn', 'Bọc kín tô thịt, cho vào ngăn mát tủ lạnh nghỉ khoảng 30 phút để vụn bánh mì hút ẩm đều giúp hỗn hợp kết dính chắc. Sau đó chia hỗn hợp thành các phần nhỏ đều nhau (~20 g mỗi phần) và vo tròn bằng hai lòng bàn tay.', NULL, 30),
('imp-a60814a4aca4143b_v4_step_3', 'imp-a60814a4aca4143b', 3, 'sauce', 'Xào chậm hành tây tỏi làm nền sốt cà chua', 'Bắc nồi rộng đáy lên bếp ở lửa nhỏ với 45 ml dầu ô liu nguyên chất. Cho hành tây băm và tỏi băm vào xào chậm khoảng 10–12 phút, đảo thường xuyên đến khi hành mềm trong suốt và ngọt dịu mà không để cháy vàng.', 'Xào chậm hành tây trên lửa nhỏ giúp sốt cà chua có vị ngọt thanh tự nhiên mà không cần thêm đường.', 10),
('imp-a60814a4aca4143b_v4_step_4', 'imp-a60814a4aca4143b', 4, 'sauce', 'Đun sôi nhẹ sốt cà chua Passata', 'Đổ 800 g cà chua xay nhuyễn Passata vào nồi hành tỏi, nêm 3 g muối ăn còn lại, khuấy đều và đun đến khi sốt sôi lăn tăn nhẹ.', NULL, NULL),
('imp-a60814a4aca4143b_v4_step_5', 'imp-a60814a4aca4143b', 5, 'cook', 'Thả viên thịt om chín mềm trong sốt cà chua', 'Nhẹ nhàng thả từng viên thịt bò vào nồi sốt đang sôi lăn tăn, lắc nhẹ tay cầm nồi để các viên xếp đều mà không dùng muỗng khuấy mạnh tránh vỡ viên. Đậy nắp, hạ lửa nhỏ và om liu riu khoảng 25 phút đến khi viên thịt chín kỹ hoàn toàn bên trong và sốt sánh mịn.', 'Chỉ lắc nhẹ nồi trong 10 phút đầu để viên thịt định hình chắc chắn trước khi đảo nhẹ.', 25),
('imp-a60814a4aca4143b_v4_step_6', 'imp-a60814a4aca4143b', 6, 'finish', 'Thêm lá húng quế tươi và dọn nóng', 'Thả 6 g lá húng quế Tây tươi vào nồi, đun thêm 5 phút ở lửa nhỏ cho dậy hương thơm tươi mát rồi tắt bếp. Nếm lại sốt cho vừa miệng, múc thịt viên cùng nhiều sốt nóng ra đĩa và thưởng thức ngay.', NULL, 5),
('imp-5504378372dc989b_v4_step_1', 'imp-5504378372dc989b', 1, 'prep', 'Thái hạt lựu toàn bộ rau củ và bó lá thơm', 'Rửa sạch và cắt hạt lựu đều cỡ 1 cm đối với bí đỏ, khoai tây, bí ngòi và cà chua chín; tách bông nhỏ súp lơ trắng; thái miếng vừa ăn bắp cải; thái khoanh mỏng tỏi tây; băm nhỏ hành tây tím, cà rốt, cần tây và tỏi tươi; chuẩn bị sẵn đậu trắng Borlotti và đậu Hà Lan. Buộc nhánh hương thảo cùng 2 lá nguyệt quế khô bằng chỉ bếp thành bó thơm.', 'Thái rau củ kích thước đồng đều giúp các nguyên liệu chín mềm cùng lúc mà không bị nát.', NULL),
('imp-5504378372dc989b_v4_step_2', 'imp-5504378372dc989b', 2, 'cook', 'Xào chậm rau củ nền dậy hương ngọt', 'Làm nóng nồi lớn trên lửa vừa với 40 ml dầu ô liu nguyên chất. Cho hành tây tím, cà rốt, cần tây, tỏi tây và tỏi tươi vào xào chậm khoảng 8 phút, đảo đều tay đến khi rau mềm thơm mà không bị cháy cạnh.', NULL, 8),
('imp-5504378372dc989b_v4_step_3', 'imp-5504378372dc989b', 3, 'cook', 'Nấu lần lượt đậu, bí đỏ, khoai tây và súp lơ', 'Cho bó thơm cùng đậu trắng Borlotti vào nồi, chế khoảng 600 ml nước lọc ngập mặt rau rồi đun sôi 2 phút. Lần lượt cho bí đỏ, khoai tây rồi súp lơ trắng vào theo cách tương tự, mỗi đợt châm thêm chút nước lọc vừa ngập mặt và nấu sôi 2 phút trước khi cho loại tiếp theo.', 'Kỹ thuật cho rau cứng vào trước theo từng đợt giúp khoai tây và bí đỏ chín bùi mà vẫn giữ nguyên khối đẹp mắt.', 8),
('imp-5504378372dc989b_v4_step_4', 'imp-5504378372dc989b', 4, 'cook', 'Ninh súp mềm ngọt trong 20 phút', 'Châm phần nước lọc còn lại vào nồi cho ngập hết rau củ, đậy nắp, đun sôi rồi hạ lửa nhỏ ninh liu riu khoảng 20 phút để nước dùng ngọt thanh tự nhiên.', NULL, 20),
('imp-5504378372dc989b_v4_step_5', 'imp-5504378372dc989b', 5, 'cook', 'Thả rau mềm và nui Ý vào nấu chín tới', 'Mở nắp, cho bí ngòi, đậu Hà Lan, cà chua chín và bắp cải vào nồi cùng 8 g muối ăn và 1,5 g tiêu đen xay, nấu sôi lại 3 phút. Tiếp theo thả 100 g nui Ý ngắn Ditalini vào (nếu dùng) nấu thêm khoảng 7 phút cho nui chín dai vừa tới.', 'Chỉ cho nui Ý vào khi sắp dọn ăn để tránh nui hút cạn nước và nở bở.', 10),
('imp-5504378372dc989b_v4_step_6', 'imp-5504378372dc989b', 6, 'finish', 'Vớt bó thơm, rưới dầu ô liu và dọn nóng', 'Vớt bỏ bó lá hương thảo và nguyệt quế, nêm nếm lại độ mặn vừa miệng rồi tắt bếp. Múc súp Minestrone ra 5 bát sâu lòng, rưới 10 ml dầu ô liu nguyên chất còn lại cùng 0,5 g tiêu đen xay lên trên và thưởng thức nóng.', NULL, NULL),
('imp-b6496331f7aa0ee9_v4_step_1', 'imp-b6496331f7aa0ee9', 1, 'prep', 'Sơ chế tôm tươi, chanh vàng và tỏi băm', 'Bóc vỏ 400 g tôm tươi, rút sạch chỉ đen dọc sống lưng, rửa nhanh nước lạnh rồi thấm thật khô bằng giấy bếp. Bào lấy vỏ vàng của 1 quả chanh vàng tươi và vắt lấy khoảng 30 ml nước cốt; băm nhuyễn tỏi tươi, thái nhỏ ngò tây và bào sẵn 60 g phô mai Parmesan.', 'Thấm thật ráo nước trên thân tôm giúp nước sốt kem chanh không bị loãng khi nấu tôm.', NULL),
('imp-b6496331f7aa0ee9_v4_step_2', 'imp-b6496331f7aa0ee9', 2, 'cook', 'Luộc mì Ý Spaghetti và giữ nước tinh bột', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 9 g muối ăn. Cho 200 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút cho đến độ al dente. Múc giữ lại 60 ml nước luộc mì rồi vớt mì ra.', NULL, 9),
('imp-b6496331f7aa0ee9_v4_step_3', 'imp-b6496331f7aa0ee9', 3, 'sauce', 'Nấu nền sốt kem bơ chanh và rượu vang', 'Trong lúc luộc mì, đặt chảo lớn lên bếp lửa vừa, cho 30 g bơ lạt vào đun tan. Thêm tỏi băm, vỏ chanh vàng bào, nước cốt chanh, 90 ml rượu vang trắng khô và 180 ml kem tươi vào khuấy đều, đun sôi lăn tăn khoảng 4 phút cho rượu bay bớt mùi cồn.', NULL, 4),
('imp-b6496331f7aa0ee9_v4_step_4', 'imp-b6496331f7aa0ee9', 4, 'sauce', 'Làm sánh sốt với bột mì và phô mai Parmesan', 'Rắc từ từ 5 g bột mì đa dụng vào chảo, vừa rắc vừa khuấy liên tục bằng phới để sốt sánh mịn không vón cục. Tiếp tục cho 60 g phô mai Parmesan bào vào khuấy tan hoàn toàn, nêm 3 g muối ăn và 1,5 g tiêu đen xay.', 'Khuấy liên tục khi cho bột mì và phô mai ở lửa nhỏ giúp sốt kem mịn mượt và không bị tách dầu.', 2),
('imp-b6496331f7aa0ee9_v4_step_5', 'imp-b6496331f7aa0ee9', 5, 'cook', 'Nấu chín tôm tươi trong sốt kem chanh', 'Thả tôm tươi đã sơ chế vào chảo sốt đang sôi liu riu, đảo đều và nấu khoảng 4–5 phút đến khi tôm chuyển màu hồng cam, cong tròn săn chắc và chín hoàn toàn bên trong. Không nấu quá lâu để giữ thịt tôm giòn ngọt.', 'Chỉ nấu tôm vừa chuyển hồng cam và săn lại trong 4–5 phút để thịt tôm ngọt giòn mà không bị bở hay dai.', 5),
('imp-b6496331f7aa0ee9_v4_step_6', 'imp-b6496331f7aa0ee9', 6, 'finish', 'Trộn mì Ý với sốt tôm và dọn nóng', 'Cho mì Ý Spaghetti vào chảo sốt tôm cùng 1–2 muỗng canh nước luộc mì đã giữ lại, đảo đều tay 1 phút cho từng sợi mì phủ đều sốt. Tắt bếp, chia ra 3 đĩa sâu lòng, rắc ngò tây tươi (nếu dùng) lên trên và thưởng thức nóng ngay.', NULL, NULL),
('imp-d6f7b2ef8f347338_v4_step_1', 'imp-d6f7b2ef8f347338', 1, 'prep', 'Chần sạch và ướp gia vị cho sườn non', 'Chặt 500 g sườn non heo thành khúc dài 3–4 cm, chà xát với 4 g muối ăn rồi rửa sạch. Đun sôi một nồi nước phụ, thả sườn vào chần 3 phút trên lửa lớn cho ra hết tạp chất rồi vớt ra xả sạch dưới vòi nước lạnh, để ráo. Ướp sườn với 10 ml nước mắm, 3 g hạt nêm, một nửa hành tím băm, đầu hành băm và 0,5 g tiêu đen xay trong 15 phút.', 'Chần sườn rồi rửa lại dưới vòi nước lạnh trước khi ướp là bí quyết giúp nước canh sườn trong veo, không có mùi hôi và ít bọt đục.', 15),
('imp-d6f7b2ef8f347338_v4_step_2', 'imp-d6f7b2ef8f347338', 2, 'prep', 'Sơ chế dứa chín, cà chua, me và rau thơm', 'Gọt sạch vỏ và mắt 1/2 quả dứa chín, bỏ lõi rồi thái lát xéo dày 0,8 cm. Rửa sạch 2 quả cà chua, bổ múi cau. Ngâm 20 g cơm me chín với 50 ml nước nóng lấy từ phần nước lọc, dằm nhuyễn rồi lọc qua rây lấy nước cốt. Rửa sạch và thái khúc hành lá, ngò gai.', NULL, NULL),
('imp-d6f7b2ef8f347338_v4_step_3', 'imp-d6f7b2ef8f347338', 3, 'cook', 'Xào săn sườn non rồi hầm mềm ngọt nước', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, phi thơm phần hành tím băm còn lại rồi cho sườn non đã ướp vào đảo săn 3 phút cho thịt bên ngoài hơi se lại. Đổ 1450 ml nước lọc vào nồi, đun sôi bùng rồi hạ lửa nhỏ liu riu, đậy hé vung hầm 25 phút và thường xuyên hớt bọt để sườn mềm rục và nước dùng ngọt trong.', 'Giữ lửa nhỏ liu riu khi hầm sườn để thịt tiết chất ngọt từ từ vào nước dùng mà nước không bị đục và không cạn nhanh.', 25);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-d6f7b2ef8f347338_v4_step_4', 'imp-d6f7b2ef8f347338', 4, 'cook', 'Xào sơ cà chua dứa và nấu hòa quyện', 'Trong chảo nhỏ, làm nóng 5 ml dầu ăn còn lại trên lửa vừa, cho dứa thái lát và cà chua bổ múi cau vào đảo nhẹ 2 phút cho cà chua lên màu đẹp rồi trút toàn bộ vào nồi sườn đang hầm. Tiếp tục nấu thêm 5 phút trên lửa vừa để vị chua ngọt tự nhiên của dứa và cà chua tiết vào nước canh.', NULL, 5),
('imp-d6f7b2ef8f347338_v4_step_5', 'imp-d6f7b2ef8f347338', 5, 'cook', 'Nêm nếm chua ngọt cân bằng', 'Từ từ rót nước cốt me đã lọc vào nồi tùy khẩu vị chua mong muốn, nêm tiếp 20 ml nước mắm ngon, 5 g hạt nêm còn lại, 4 g muối ăn và 6 g đường cát trắng. Khuấy nhẹ và nấu thêm 2 phút cho gia vị thấm đều vào từng miếng sườn non, đảm bảo sườn chín mềm rời xương nhẹ.', 'Nêm nước cốt me từng chút một và nếm thử lại vì độ chua tự nhiên của dứa chín và cà chua sẽ khác nhau theo mùa.', NULL),
('imp-d6f7b2ef8f347338_v4_step_6', 'imp-d6f7b2ef8f347338', 6, 'finish', 'Rắc hành ngò và dọn canh nóng', 'Tắt bếp, thả hành lá cắt khúc và ngò gai vào nồi canh cho dậy mùi thơm đặc trưng miền Nam. Múc canh ra tô lớn, rắc nốt 0,5 g tiêu đen xay lên mặt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-5e0564249085d9c1_v4_step_1', 'imp-5e0564249085d9c1', 1, 'prep', 'Sơ chế tôm tươi và ướp gia vị khử tanh', 'Bóc bỏ vỏ và đầu 250 g tôm tươi, rút sạch chỉ đen dọc sống lưng, rửa sạch với nước lạnh rồi để ráo (có thể băm dập 1/3 lượng tôm để nước canh đậm ngọt hơn, phần còn lại để nguyên con). Ướp tôm với 6 ml nước mắm, 2 g hạt nêm, 1/3 lượng tỏi băm, đầu hành băm nhỏ và 0,5 g tiêu đen xay trong 10 phút.', 'Nếu muốn giữ nước canh thật ngọt tự nhiên, bạn có thể rửa sạch phần đầu và vỏ tôm rồi giã lọc lấy nước cốt nấu canh trước khi cho bông cải vào.', 10),
('imp-5e0564249085d9c1_v4_step_2', 'imp-5e0564249085d9c1', 2, 'prep', 'Tách nhánh và làm sạch bông cải xanh', 'Tách 1 bông cải xanh thành từng nhánh nhỏ vừa miệng, phần thân cọng non tước bỏ lớp vỏ xơ ngoài rồi thái lát vát dày 0,5 cm. Ngâm bông cải vào thau nước pha loãng 2 g muối ăn trong 5 phút cho sạch kẽ hoa, vớt ra xả lại nước sạch và để ráo. Thái nhỏ hành lá và ngò rí.', NULL, 5),
('imp-5e0564249085d9c1_v4_step_3', 'imp-5e0564249085d9c1', 3, 'cook', 'Phi thơm tỏi và xào săn tôm tươi', 'Đặt nồi lên bếp ở lửa vừa với 15 ml dầu ăn, cho phần tỏi băm còn lại vào phi 30 giây đến khi dậy mùi thơm vàng nhẹ. Trút tôm đã ướp vào đảo nhanh 2 phút đến khi tôm chuyển sang màu đỏ cam săn lại và chín tới thì vớt riêng phần tôm nguyên con ra đĩa để không bị dai khi nấu lâu.', 'Vớt tôm xào săn ra riêng trước khi nấu bông cải giúp giữ thịt tôm săn ngọt, không bị teo nhỏ và dai xác.', 2),
('imp-5e0564249085d9c1_v4_step_4', 'imp-5e0564249085d9c1', 4, 'cook', 'Nấu sôi nước canh và làm chín bông cải xanh', 'Đổ 1100 ml nước lọc vào nồi vừa xào tôm, bật lửa lớn đun sôi bùng rồi hớt sạch bọt nổi. Thả phần cọng bông cải vào nấu trước 2 phút, sau đó cho toàn bộ nhánh bông cải xanh vào nấu thêm 3 phút trên lửa vừa đến khi bông cải chuyển màu xanh mướt và chín giòn vừa tới.', 'Không đậy nắp kín khi nấu bông cải xanh để rau giữ được màu xanh tươi bắt mắt và không bị nồng mùi.', 3),
('imp-5e0564249085d9c1_v4_step_5', 'imp-5e0564249085d9c1', 5, 'cook', 'Thả tôm trở lại nồi và nêm gia vị thanh ngọt', 'Nêm 12 ml nước mắm ngon, 3 g hạt nêm và 3 g muối ăn vào nồi canh, khuấy nhẹ cho tan đều. Trút đĩa tôm đã xào vào đun sôi trở lại khoảng 1 phút cho tôm chín kỹ hoàn toàn và hòa quyện vị ngọt vào nước canh.', NULL, NULL),
('imp-5e0564249085d9c1_v4_step_6', 'imp-5e0564249085d9c1', 6, 'finish', 'Hoàn thiện tô canh với hành ngò và tiêu', 'Tắt bếp ngay khi canh sôi lại để bông cải không bị nhũn, thả hành lá và ngò rí thái nhỏ vào. Múc canh ra tô, rắc 0,5 g tiêu đen xay còn lại lên trên rồi dọn ăn nóng với cơm trắng.', NULL, NULL),
('imp-9daae727e7894587_v4_step_1', 'imp-9daae727e7894587', 1, 'prep', 'Làm sạch khử mùi và ướp thịt đùi gà', 'Chà xát 550 g đùi gà với 2 g muối ăn và vài lát gừng tươi đập dập trong 2 phút để khử mùi hôi, xả sạch với nước lạnh rồi chặt miếng vừa ăn 3–4 cm, để ráo. Ướp thịt gà với 8 ml nước mắm, 3 g hạt nêm, một nửa hành tím băm, phần gừng băm còn lại, đầu hành băm và 0,5 g tiêu đen xay trong 15 phút.', 'Chà xát da gà bằng muối ăn kết hợp gừng đập dập rồi rửa lại nước sạch sẽ khử hoàn toàn mùi hôi đặc trưng của gia cầm.', 15),
('imp-9daae727e7894587_v4_step_2', 'imp-9daae727e7894587', 2, 'prep', 'Sơ chế bắp cải, cà rốt và hành lá', 'Tách từng lá 1/2 bắp cải trắng, rửa sạch dưới vòi nước rồi cắt miếng vuông cạnh 4 cm cho dễ gắp. Gọt vỏ 1 củ cà rốt, thái khoanh tròn dày 0,5 cm. Rửa sạch phần lá xanh hành lá rồi thái khúc dài 2 cm.', NULL, NULL),
('imp-9daae727e7894587_v4_step_3', 'imp-9daae727e7894587', 3, 'cook', 'Phi thơm hành tím và xào săn thịt gà', 'Bắc nồi lên bếp ở lửa vừa với 15 ml dầu ăn, cho phần hành tím băm còn lại và vài sợi gừng tươi vào phi thơm 30 giây. Trút toàn bộ thịt gà đã ướp vào đảo đều khoảng 4 phút đến khi bề mặt da và thịt gà săn lại, dậy mùi thơm hấp dẫn.', 'Xào săn thịt gà trước khi đổ nước giúp phần thịt bên ngoài se lại, giữ nước ngọt bên trong và làm nước canh thơm đậm hơn.', 4),
('imp-9daae727e7894587_v4_step_4', 'imp-9daae727e7894587', 4, 'cook', 'Hầm gà lấy nước dùng ngọt trong', 'Đổ 1500 ml nước lọc vào nồi gà, bật lửa lớn đun sôi bùng rồi dùng vá hớt thật sạch lớp bọt nổi. Hạ xuống lửa vừa nhỏ, đậy hé vung ninh gà khoảng 15 phút cho thịt gà chín mềm hoàn toàn và nước dùng ngọt thanh.', 'Ninh gà với lửa vừa nhỏ và mở hé vung giúp nước canh giữ độ trong veo, không bị đục váng mỡ.', 15),
('imp-9daae727e7894587_v4_step_5', 'imp-9daae727e7894587', 5, 'cook', 'Nấu chín cà rốt, bắp cải và nêm gia vị', 'Thả cà rốt thái khoanh vào nồi nấu 5 phút trước, sau đó cho toàn bộ bắp cải vào nấu thêm 5 phút trên lửa vừa đến khi bắp cải chín mềm ngọt nhưng vẫn giữ độ giòn nhẹ. Nêm 12 ml nước mắm còn lại, 3 g hạt nêm, 4 g muối ăn và 4 g đường cát trắng cho vừa khẩu vị gia đình.', NULL, 10),
('imp-9daae727e7894587_v4_step_6', 'imp-9daae727e7894587', 6, 'finish', 'Thêm hành lá, tiêu xay và dọn canh', 'Kiểm tra thịt gà chín mềm không còn sắc hồng bên trong xương và rau củ vừa độ chín tới thì tắt bếp. Thả hành lá thái khúc vào nồi đảo nhẹ, múc canh ra tô lớn và rắc 0,5 g tiêu đen xay lên mặt trước khi dùng nóng.', NULL, NULL),
('imp-20123919cd3164a8_v4_step_1', 'imp-20123919cd3164a8', 1, 'prep', 'Sơ chế và ướp cá hồi khử mùi tanh', 'Thấm khô 350 g cá hồi tươi rồi cắt miếng vuông dày 3–4 cm để cá không bị nát khi nấu. Ướp cá với 8 ml nước mắm, 2 g hạt nêm, 1 g tiêu đen xay và đầu hành lá băm nhỏ trong 10 phút cho thịt cá săn và đậm vị.', 'Không ướp cá hồi với nước cốt chanh quá sớm vì axit sẽ làm thịt cá bị tái chín bề mặt và dễ bở khi nấu.', 10),
('imp-20123919cd3164a8_v4_step_2', 'imp-20123919cd3164a8', 2, 'prep', 'Xử lý măng chua, dọc mùng và sơ chế rau quả', 'Luộc kỹ 120 g măng chua trong nước sôi 3–5 phút rồi chắt bỏ nước luộc, xả sạch vắt ráo để loại bỏ độc tố và mùi hăng. Tước vỏ xơ 100 g dọc mùng, thái lát xéo, bóp nhẹ với 2 g muối ăn rồi rửa nhiều lần cho hết ngứa. Thái múi cau 3 quả cà chua, thái lát 1/3 quả dứa chín; rửa sạch giá đỗ, hành lá, rau ngổ, ớt tươi và băm nhỏ hành tím, tỏi khô.', NULL, 2),
('imp-20123919cd3164a8_v4_step_3', 'imp-20123919cd3164a8', 3, 'cook', 'Phi thơm hành tỏi và xào cà chua dứa măng', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, phi thơm hành tím và tỏi khô băm trong 1 phút. Cho một nửa lượng cà chua bổ múi cau, dứa thái lát và măng chua vào xào đều 3 phút để cà chua tiết màu đỏ cam óng đẹp và măng thấm dầu thơm.', NULL, 3),
('imp-20123919cd3164a8_v4_step_4', 'imp-20123919cd3164a8', 4, 'cook', 'Đun sôi nước dùng và nấu chín cá hồi', 'Đổ 1200 ml nước lọc vào nồi, bật lửa lớn đun sôi bùng rồi hớt sạch bọt nổi. Hạ xuống lửa vừa, thả nhẹ từng miếng cá hồi đã ướp cùng phần cà chua còn lại vào nồi nấu khoảng 4–5 phút đến khi thịt cá chuyển hồng cam đục đều, chín tới hoàn toàn mà không bị khô bở.', 'Hạn chế đảo mạnh sau khi thả cá hồi; chỉ dùng vá nhấn nhẹ cá ngập trong nước sôi lăn tăn để giữ miếng cá nguyên vẹn.', 4),
('imp-20123919cd3164a8_v4_step_5', 'imp-20123919cd3164a8', 5, 'cook', 'Nêm gia vị và chần nhanh dọc mùng, giá đỗ', 'Nêm 17 ml nước mắm ngon, 3 g hạt nêm, 2 g muối ăn và 12 g đường cát trắng vào nồi. Thả dọc mùng vào nấu thêm 1 phút cho vừa chín tới rồi thả giá đỗ vào, tắt bếp ngay để giá vẫn giữ được độ giòn ngọt.', NULL, NULL),
('imp-20123919cd3164a8_v4_step_6', 'imp-20123919cd3164a8', 6, 'finish', 'Vắt nước cốt chanh và hoàn thiện với rau ngổ', 'Khi nồi canh đã tắt bếp và bớt sôi sùng sục, từ từ rưới nước cốt 1 quả chanh tươi vào để tạo vị chua thanh mà không bị đắng. Rắc hành lá, rau ngổ và ớt tươi thái lát lên mặt, múc canh nóng ra tô dùng kèm cơm trắng.', 'Luôn vắt nước cốt chanh sau khi tắt bếp để giữ trọn hương thơm tinh dầu chanh và tránh làm nước canh bị đắng.', NULL),
('imp-d500b08871587628_v4_step_1', 'imp-d500b08871587628', 1, 'prep', 'Sơ chế tôm tươi, dứa chín và gia vị thơm', 'Rửa sạch 350 g tôm tươi, cắt bỏ đầu và râu, bóc vỏ chừa lại phần đuôi rồi khều sạch chỉ đen ở lưng và để thật ráo nước. Gọt sạch vỏ bỏ mắt 1/2 quả dứa chín, thái lát mỏng 0,5 cm; băm nhỏ hành tím và tỏi khô chia làm hai phần; thái lát ớt hiểm và cắt nhỏ hành lá.', 'Chọn dứa chín vàng có mùi thơm dịu sẽ giúp món tôm kho có vị chua thanh tự nhiên mà không bị chua gắt.', NULL),
('imp-d500b08871587628_v4_step_2', 'imp-d500b08871587628', 2, 'marinate', 'Ướp tôm thấm vị trước khi kho', 'Trộn đều tôm trong tô với một nửa phần hành tím và tỏi băm, 18 ml nước mắm ngon, 6 g đường cát trắng và nửa lượng tiêu đen xay. Ướp khoảng 15 phút để thịt tôm săn chắc và đậm vị.', NULL, 15),
('imp-d500b08871587628_v4_step_3', 'imp-d500b08871587628', 3, 'cook', 'Phi thơm hành tỏi ớt và xào săn tôm', 'Làm nóng chảo sâu lòng với 20 ml dầu ăn trên lửa vừa, phi thơm phần hành tím, tỏi băm còn lại cùng ớt hiểm thái lát trong 1 phút. Trút toàn bộ tôm đã ướp vào đảo đều trên lửa vừa lớn khoảng 3 phút cho đến khi tôm cong lại và chuyển màu đỏ cam đều.', 'Đảo nhẹ tay và không xào quá lâu ở bước đầu để giữ tôm nguyên con mọng nước, không bị khô teo.', 3),
('imp-d500b08871587628_v4_step_4', 'imp-d500b08871587628', 4, 'cook', 'Thêm dứa chín và gia vị vào chảo tôm', 'Cho dứa cắt lát vào đảo nhẹ cùng tôm 1 phút, sau đó rưới 100 ml nước lọc vào xâm xấp mặt tôm, nêm tiếp 12 ml nước mắm còn lại, 9 g đường cát trắng và 4 g hạt nêm.', NULL, NULL),
('imp-d500b08871587628_v4_step_5', 'imp-d500b08871587628', 5, 'cook', 'Kho mở nắp cho nước sốt sánh keo bóng', 'Đợi nước trong chảo sôi lên thì hạ lửa nhỏ, kho mở nắp liu riu khoảng 8–10 phút, thỉnh thoảng đảo nhẹ cho dứa tiết nước ngọt và nước kho rút cạn sánh keo bóng mượt bám đều quanh thân tôm và lát dứa.', 'Không cho quá nhiều nước từ đầu vì bản thân dứa chín cũng sẽ tiết thêm nước ngọt trong khi kho.', 9),
('imp-d500b08871587628_v4_step_6', 'imp-d500b08871587628', 6, 'finish', 'Nêm lại, rắc hành lá và tiêu thưởng thức', 'Nếm thử xem vị mặn ngọt chua hài hòa đã vừa miệng chưa rồi tắt bếp. Rắc hành lá thái nhỏ và phần tiêu đen xay còn lại lên trên, đảo nhẹ và dọn tôm kho dứa dùng nóng với cơm trắng.', NULL, NULL),
('imp-c7e40140f9ee9591_v4_step_1', 'imp-c7e40140f9ee9591', 1, 'prep', 'Làm sạch đùi gà và băm nhuyễn sả ớt', 'Chà xát 700 g đùi gà với 4 g muối hạt cho hết mùi hôi, rửa sạch lại nhiều lần với nước rồi để ráo, chặt miếng vừa ăn cỡ 3,5–4 cm. Lột vỏ già của 5 cây sả tươi, đập dập rồi băm nhuyễn; băm nhỏ 3 quả ớt hiểm đỏ, tỏi và hành tím; thái lát quả ớt còn lại và cắt khúc hành lá.', 'Dùng sả non phần củ trắng bên dưới để băm sẽ giúp thịt gà thơm ngọt và không bị xơ cứng khi ăn.', NULL),
('imp-c7e40140f9ee9591_v4_step_2', 'imp-c7e40140f9ee9591', 2, 'marinate', 'Ướp thịt gà với sả ớt đỏ và dầu ăn', 'Trộn thịt gà trong tô lớn cùng toàn bộ sả băm, 3 quả ớt hiểm băm, hành tím và tỏi băm, 20 ml nước mắm, 8 g đường cát trắng, 5 g hạt nêm, 3 g muối, 1 g tiêu đen xay và 12 ml dầu ăn. Trộn đều và ướp trong 25 phút cho thấm sâu.', 'Trộn thêm chút dầu ăn vào lúc ướp giúp bề mặt thịt gà mềm mọng, không bị khô xơ trong suốt quá trình kho.', 25),
('imp-c7e40140f9ee9591_v4_step_3', 'imp-c7e40140f9ee9591', 3, 'sauce', 'Thắng nước màu cánh gián bóng đẹp', 'Làm nóng nồi đáy dày với 8 ml dầu ăn còn lại và 20 g đường cát trắng trên lửa nhỏ. Đun đến khi đường tan hết và chuyển màu nâu cánh gián thì nhanh tay rót 30 ml nước lọc ấm vào khuấy đều rồi tắt bếp tạm trong vài giây.', 'Hãm nước màu bằng nước ấm ngay khi vừa đạt màu cánh gián để đường không cháy đen gây vị đắng gắt.', NULL),
('imp-c7e40140f9ee9591_v4_step_4', 'imp-c7e40140f9ee9591', 4, 'cook', 'Xào săn thịt gà trong nồi nước màu', 'Bật bếp lại ở lửa vừa lớn, cho toàn bộ thịt gà đã ướp vào nồi nước màu và đảo đều tay trong 5 phút đến khi thịt săn chắc, da gà hơi xém vàng và dậy mùi sả ớt thơm nức.', NULL, 5),
('imp-c7e40140f9ee9591_v4_step_5', 'imp-c7e40140f9ee9591', 5, 'cook', 'Kho nhỏ lửa cho gà chín kỹ thấm sốt', 'Rót 100 ml nước lọc ấm cùng 10 ml nước mắm còn lại vào xâm xấp mặt thịt, đợi nước sôi thì đậy nắp, hạ lửa nhỏ kho liu riu 20 phút và đảo nhẹ vài lần cho gà chín hoàn toàn tận xương.', NULL, 20),
('imp-c7e40140f9ee9591_v4_step_6', 'imp-c7e40140f9ee9591', 6, 'finish', 'Sánh sốt, rắc hành lá và trình bày', 'Mở nắp kho thêm 3–4 phút trên lửa vừa nhỏ đến khi nước sốt cạn sánh sệt, áo bóng quanh từng miếng gà. Nêm lại vừa ăn, tắt bếp rồi rắc hành lá cắt khúc, ớt thái lát và 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng.', NULL, NULL),
('imp-ebbd704089d9c62a_v4_step_1', 'imp-ebbd704089d9c62a', 1, 'prep', 'Sơ chế thịt đùi gà và các loại hành, sả, tỏi', 'Thịt đùi gà rút xương rửa sạch, thấm khô rồi cắt miếng vừa ăn dày khoảng 2 cm. Hành tây bóc vỏ, cắt múi cau; sả tươi và hành tím khô băm thật nhuyễn; tỏi khô băm nhỏ và chia làm hai phần.', NULL, NULL),
('imp-ebbd704089d9c62a_v4_step_2', 'imp-ebbd704089d9c62a', 2, 'marinate', 'Ướp thịt đùi gà thấm sốt dầu hào sả tỏi', 'Cho thịt đùi gà vào tô cùng sả băm, hành tím băm, một nửa lượng tỏi băm, 15 ml dầu hào, 10 ml nước mắm ngon, 10 ml nước tương (xì dầu), 10 g đường cát trắng, 6 g hạt nêm, 3 g muối ăn và 1 g tiêu đen xay. Trộn thật đều và ướp 20–25 phút cho gà ngấm sâu gia vị.', 'Ướp đủ thời gian giúp sả, dầu hào và nước tương thấm vào từng thớ thịt đùi gà mềm ngọt.', 20),
('imp-ebbd704089d9c62a_v4_step_3', 'imp-ebbd704089d9c62a', 3, 'cook', 'Phi thơm tỏi và xào săn thịt gà', 'Đặt chảo lên bếp lửa lớn, đun nóng 25 ml dầu ăn rồi cho phần tỏi băm còn lại vào phi thơm vàng nhẹ. Trút toàn bộ thịt đùi gà đã ướp vào đảo nhanh tay trong 4 phút đến khi thịt săn chắc và vàng cạnh.', NULL, 4),
('imp-ebbd704089d9c62a_v4_step_4', 'imp-ebbd704089d9c62a', 4, 'cook', 'Om chín kỹ thịt đùi gà với nước lọc', 'Hạ xuống lửa vừa-nhỏ, rót 40 ml nước lọc vào chảo rồi đậy nắp om khoảng 8 phút cho thịt đùi gà chín hoàn toàn tận lõi (không còn dịch hồng bên trong) và phần sốt hơi sánh lại.', 'Om với lượng nước nhỏ giúp thịt đùi gà chín mềm mọng nước mà gia vị không bị cháy đáy chảo.', 8),
('imp-ebbd704089d9c62a_v4_step_5', 'imp-ebbd704089d9c62a', 5, 'cook', 'Xào nhanh hành tây giữ độ giòn ngọt', 'Mở nắp, tăng lên lửa lớn và thả toàn bộ hành tây cắt múi cau vào đảo đều tay trong khoảng 2–3 phút đến khi hành tây vừa chín tới, chuyển màu hơi trong nhưng vẫn giữ được độ giòn ngọt.', 'Chỉ cho hành tây vào sau khi gà đã chín kỹ để hành không bị nhũn nát và vẫn giữ vị ngọt tự nhiên.', 3),
('imp-ebbd704089d9c62a_v4_step_6', 'imp-ebbd704089d9c62a', 6, 'finish', 'Nêm lại và dọn nóng', 'Nêm nếm lại sốt cho vừa khẩu vị rồi tắt bếp. Bày gà xào hành tây sốt dầu hào ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-b7ae5824ff7e6a74_v4_step_1', 'imp-b7ae5824ff7e6a74', 1, 'prep', 'Gọt vỏ và ngâm nước muối loại bỏ nhựa su su', 'Ngâm 3 quả su su non trong nước sạch 2 phút hoặc gọt vỏ trực tiếp dưới vòi nước để không bị dính nhựa. Chẻ đôi bỏ hạt rồi thái lát mỏng vừa ăn dày khoảng 0,3 cm. Ngâm lát su su trong thau nước pha 2 g muối ăn khoảng 5 phút để sạch nhựa và giữ sắc xanh rồi xả sạch, để thật ráo.', 'Ngâm nhanh qua nước muối loãng rồi để ráo giúp lát su su giòn thanh và không bị thâm sẫm.', 5),
('imp-b7ae5824ff7e6a74_v4_step_2', 'imp-b7ae5824ff7e6a74', 2, 'prep', 'Chuẩn bị tỏi đập dập, hành lá và ớt', 'Tỏi khô bóc vỏ, đập dập rồi băm nhỏ, chia thành hai phần bằng nhau. Hành lá rửa sạch cắt khúc 3 cm; ớt sừng đỏ thái lát xéo mỏng.', NULL, NULL),
('imp-b7ae5824ff7e6a74_v4_step_3', 'imp-b7ae5824ff7e6a74', 3, 'cook', 'Phi thơm phần tỏi ban đầu', 'Làm nóng 25 ml dầu ăn trong chảo trên lửa vừa, cho một nửa lượng tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi ngả vàng nhẹ và tỏa hương thơm nồng.', 'Không phi tỏi quá sẫm màu vì tỏi cháy sẽ tạo vị đắng cho đĩa rau thanh nhẹ.', NULL),
('imp-b7ae5824ff7e6a74_v4_step_4', 'imp-b7ae5824ff7e6a74', 4, 'cook', 'Xào nhanh su su trên lửa lớn', 'Tăng bếp lên lửa lớn, trút toàn bộ su su đã để ráo vào chảo dầu tỏi và đảo nhanh tay liên tục khoảng 3 phút. Nêm 5 g hạt nêm, 2 g muối ăn còn lại và 8 ml nước mắm ngon, đảo đều thêm 1,5 phút cho lát su su hơi trong và chín giòn.', 'Giữ lửa lớn suốt quá trình xào giúp su su chín nhanh bên ngoài mà vẫn giòn sần sật, không bị ra nhiều nước.', 4),
('imp-b7ae5824ff7e6a74_v4_step_5', 'imp-b7ae5824ff7e6a74', 5, 'cook', 'Thêm phần tỏi cuối, hành lá và ớt lát', 'Khi su su vừa chín tới, rắc nốt một nửa lượng tỏi băm còn lại cùng hành lá cắt khúc và ớt sừng đỏ thái lát vào chảo, đảo đều thêm 30 giây cho dậy mùi tỏi tươi rồi tắt bếp ngay.', NULL, NULL),
('imp-b7ae5824ff7e6a74_v4_step_6', 'imp-b7ae5824ff7e6a74', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Bày su su xào tỏi ra đĩa, rắc 1,5 g tiêu đen xay lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-30c2038c8737538c_v4_step_1', 'imp-30c2038c8737538c', 1, 'marinate', 'Thái lát và ướp thịt bò mềm với dầu hào', 'Thấm khô thịt thăn bò rồi thái lát mỏng ngang thớ. Cho thịt vào tô ướp cùng một nửa lượng tỏi băm, 15 ml dầu hào, 3 g muối ăn, 2 g bột ngọt, 1 g tiêu đen xay và 10 ml dầu ăn; trộn đều và để thấm 15 phút.', 'Ướp dầu ăn và dầu hào giúp từng lát thịt bò mềm bóng, giữ ẩm tốt khi xào lửa lớn.', 15),
('imp-30c2038c8737538c_v4_step_2', 'imp-30c2038c8737538c', 2, 'prep', 'Sơ chế nấm đùi gà và hành ngò', 'Nấm đùi gà cắt bỏ phần gốc dính đất, rửa nhanh với nước muối loãng rồi vớt ra để thật ráo nước, thái lát vát dày khoảng 0,5 cm vừa ăn. Phần tỏi còn lại băm nhỏ; hành lá và ngò rí rửa sạch cắt khúc.', 'Không ngâm nấm đùi gà quá lâu trong nước vì nấm sẽ hút nước và tiết ra nhiều nước khi xào.', NULL),
('imp-30c2038c8737538c_v4_step_3', 'imp-30c2038c8737538c', 3, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Đun nóng 15 ml dầu ăn trong chảo trên lửa lớn, phi thơm phần tỏi băm còn lại rồi trút thịt bò đã ướp vào đảo nhanh tay 1,5–2 phút đến khi thịt vừa chín tái 80% thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-30c2038c8737538c_v4_step_4', 'imp-30c2038c8737538c', 4, 'cook', 'Xào nấm đùi gà lửa lớn cho săn giòn', 'Dùng lại chảo, thêm 10 ml dầu ăn đun nóng rồi cho nấm đùi gà vào xào trên lửa lớn khoảng 3–4 phút. Nêm 5 g hạt nêm, đảo đều đến khi miếng nấm hơi xém vàng cạnh và chín săn giòn.', 'Xào nấm trên lửa lớn giúp bề mặt nấm săn thơm và không bị ra nước lênh láng.', 4),
('imp-30c2038c8737538c_v4_step_5', 'imp-30c2038c8737538c', 5, 'cook', 'Đảo quyện thịt bò và nấm đùi gà', 'Trút toàn bộ thịt bò đã xào tái cùng nước thịt trong đĩa trở lại chảo nấm đùi gà, đảo nhanh tay trên lửa lớn 45–60 giây để nấm hút trọn vị ngọt của thịt bò và thịt bò chín hoàn toàn.', NULL, NULL),
('imp-30c2038c8737538c_v4_step_6', 'imp-30c2038c8737538c', 6, 'finish', 'Thêm hành lá, ngò rí và dọn nóng', 'Cho hành lá và ngò rí vào đảo nhanh 15 giây rồi tắt bếp. Bày bò xào nấm đùi gà ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-019bbf517408a529_v4_step_1', 'imp-019bbf517408a529', 1, 'marinate', 'Thấm khô và ướp khúc cá với muối tiêu', 'Thấm thật khô 4 khúc cá thu bằng khăn giấy sạch, xoa đều 3 g muối ăn và 0,7 g tiêu đen xay lên các mặt cá rồi để ướp 10 phút cho thịt cá săn chắc và đậm vị hơn khi chiên.', 'Thấm thật khô hai mặt khúc cá bằng khăn giấy trước khi ướp giúp thịt cá săn chắc và không bị nát khi trở mặt.', 10),
('imp-019bbf517408a529_v4_step_2', 'imp-019bbf517408a529', 2, 'prep', 'Sơ chế cà chua, hành tím, tỏi và hành lá', 'Cà chua chín đỏ rửa sạch, bỏ cuống rồi thái hạt lựu nhỏ để sốt nhanh nhừ mịn. Hành tím và tỏi khô bóc vỏ băm nhỏ; ớt hiểm thái lát; hành lá cắt khúc ngắn 2 cm.', NULL, NULL),
('imp-019bbf517408a529_v4_step_3', 'imp-019bbf517408a529', 3, 'cook', 'Chiên cá vàng đều hai mặt', 'Làm nóng 40 ml dầu ăn trong chảo chống dính trên lửa vừa, đặt các khúc cá vào chiên khoảng 4 phút mỗi mặt đến khi hai mặt vàng xém săn chắc và thịt cá gần chín hoàn toàn thì gắp ra đĩa để ráo bớt dầu.', 'Lau cá thật khô và chờ dầu nóng già mới thả cá vào sẽ giúp cá không bị sát chảo và ít bắn dầu.', 8),
('imp-019bbf517408a529_v4_step_4', 'imp-019bbf517408a529', 4, 'sauce', 'Phi thơm hành tỏi và xào nhừ sốt cà chua', 'Chắt bớt dầu cũ, làm nóng 20 ml dầu ăn sạch trong chảo trên lửa vừa rồi phi thơm hành tím băm và tỏi băm 1 phút. Cho toàn bộ cà chua vào xào đảo 3 phút đến khi mềm nhuyễn, rót thêm 120 ml nước lọc vào đun sôi nhẹ và nêm 30 ml nước mắm ngon, 8 ml dầu hào cùng 12 g đường cát trắng khuấy đều.', 'Xào cà chua thật nhừ thành sốt sánh mịn trước khi thả cá vào sẽ giúp màu đỏ đẹp và sốt bám đều quanh từng khúc cá.', 4),
('imp-019bbf517408a529_v4_step_5', 'imp-019bbf517408a529', 5, 'cook', 'Rim cá thấm sốt cà chua trên lửa nhỏ', 'Xếp nhẹ nhàng các khúc cá đã chiên vào chảo sốt, hạ lửa nhỏ và rim khoảng 8 phút (có thể lật nhẹ một lần hoặc dùng thìa rưới sốt lên mặt trên) cho sốt sánh sệt lại, thịt cá chín kỹ hoàn toàn và thấm đẫm vị chua ngọt.', 'Rim cá trên lửa nhỏ và chỉ trở nhẹ một lần giúp khúc cá nguyên vẹn, thấm sâu vị sốt cà chua đậm đà.', 8),
('imp-019bbf517408a529_v4_step_6', 'imp-019bbf517408a529', 6, 'finish', 'Rắc hành lá, ớt và dọn dùng nóng', 'Thả hành lá cắt khúc và ớt hiểm thái lát (nếu ăn cay) vào chảo, đảo nhẹ 30 giây rồi tắt bếp. Gắp cá ra đĩa, rưới đều sốt cà chua lên mặt, rắc nốt phần tiêu đen xay còn lại và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-d7836b7d1a4d90b3_v4_step_1', 'imp-d7836b7d1a4d90b3', 1, 'prep', 'Chần sơ và xé dải nấm đùi gà thật ráo', 'Cắt bỏ phần gốc nấm đùi gà, rửa sạch rồi thả vào 800 ml nước lọc đang sôi chần nhanh 2 phút. Vớt nấm ra để nguội, dùng khăn giấy ép thấm thật khô ráo nước rồi cắt hoặc xé thành dải dài dọc theo thân nấm dày khoảng 1 cm.', 'Chần sơ rồi thấm thật khô giúp nấm bớt tiết nước khi chiên, giữ được độ dai ngọt và không làm ỉu lớp vỏ bột.', 2),
('imp-d7836b7d1a4d90b3_v4_step_2', 'imp-d7836b7d1a4d90b3', 2, 'marinate', 'Ướp nấm và chuẩn bị trứng áo bột năng', 'Ướp các dải nấm với 4 g muối ăn và 2 g tiêu đen xay trong 10 phút cho ngấm vị. Trong tô, đánh tan 1 quả trứng gà với 10 g bột năng; đổ 90 g bột năng khô còn lại ra đĩa phẳng. Lá húng quế rửa sạch vẩy ráo hoàn toàn, hành lá thái nhỏ nếu dùng.', NULL, 10),
('imp-d7836b7d1a4d90b3_v4_step_3', 'imp-d7836b7d1a4d90b3', 3, 'prep', 'Nhúng trứng và áo đều bột năng quanh nấm', 'Lần lượt nhúng từng dải nấm qua chén trứng bột cho ướt đều rồi lăn ngay qua đĩa bột năng khô, lắc nhẹ tay cho bột phủ đều và rơi bớt phần bột thừa.', 'Không để nấm nhúng trứng nằm chờ quá lâu trước khi chiên để lớp bột khô không bị vón ẩm.', NULL),
('imp-d7836b7d1a4d90b3_v4_step_4', 'imp-d7836b7d1a4d90b3', 4, 'cook', 'Chiên nấm hai lần lửa cho vỏ giòn lâu', 'Đun nóng 450 ml dầu ăn trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm. Thả nấm vào chiên lần 1 khoảng 4 phút cho vỏ vừa se vàng nhạt và nấm chín kỹ thì vớt ra giá. Sau đó đun dầu nóng già ở lửa lớn rồi thả nấm vào chiên nhanh lần 2 thêm 1 phút cho vỏ vàng giòn rụm, vớt ra giấy thấm dầu.', 'Chiên 2 lần lửa là kỹ thuật giúp món nấm chiên giữ độ giòn xốp lâu hơn hẳn và đẩy bớt dầu thừa ra ngoài.', 5),
('imp-d7836b7d1a4d90b3_v4_step_5', 'imp-d7836b7d1a4d90b3', 5, 'cook', 'Chiên giòn nhanh lá húng quế ăn kèm', 'Tắt bớt hoặc hạ lửa nhỏ, nhúng nhanh nắm lá húng quế khô ráo vào phần trứng bột còn lại (hoặc thả trực tiếp) chiên khoảng 20–30 giây đến khi lá vừa giòn tan xanh sậm thì vớt ngay ra giấy thấm dầu để không bị cháy đắng.', NULL, 1),
('imp-d7836b7d1a4d90b3_v4_step_6', 'imp-d7836b7d1a4d90b3', 6, 'finish', 'Bày nấm chiên giòn và thưởng thức nóng', 'Xếp nấm đùi gà chiên giòn xen kẽ lá húng quế chiên ra đĩa, rắc thêm hành lá thái nhỏ (nếu dùng) và dùng nóng ngay với tương ớt.', NULL, NULL),
('imp-9d527dacd46efc67_v4_step_1', 'imp-9d527dacd46efc67', 1, 'prep', 'Thấm khô đậu phụ và băm nhuyễn sả tỏi ớt', 'Rửa nhẹ đậu phụ trắng, thấm thật khô hai mặt rồi cắt miếng vuông dày khoảng 2 cm để khi chiên không bị bắn dầu. Sả tươi băm thật nhuyễn; tỏi khô (nếu dùng) băm nhỏ; 2 quả ớt hiểm băm nhỏ và 1 quả thái lát; ngò rí cắt khúc 3 cm; hành lá thái nhỏ; dưa leo thái lát mỏng xếp sẵn quanh viền đĩa.', 'Thấm khô kỹ bề mặt đậu phụ trước khi chiên là bí quyết để dầu không bắn tung tóe và đậu lên màu vàng giòn.', NULL),
('imp-9d527dacd46efc67_v4_step_2', 'imp-9d527dacd46efc67', 2, 'cook', 'Chiên đậu phụ vàng giòn đều các mặt', 'Đun nóng 225 ml dầu ăn trong chảo trên lửa vừa đến khi đầu đũa sủi bọt mạnh. Thả từng miếng đậu phụ vào chiên thành 2 mẻ khoảng 4–5 phút mỗi mẻ đến khi các mặt phồng vàng giòn rụm, vớt ra đĩa có lót giấy thấm dầu.', 'Không xếp đậu quá khít trong chảo để nhiệt độ dầu không bị tụt, giúp vỏ đậu giòn đều mà không ngấm dầu.', 9),
('imp-9d527dacd46efc67_v4_step_3', 'imp-9d527dacd46efc67', 3, 'sauce', 'Phi thơm sả băm, tỏi và ớt hiểm', 'Chắt bớt dầu thừa trong chảo, giữ lại 25 ml dầu ăn sạch rồi phi thơm tỏi băm (nếu dùng) ở lửa vừa trong 30 giây, sau đó cho toàn bộ sả băm và 2 quả ớt băm vào đảo đều tay khoảng 2 phút cho sả chuyển màu vàng nhạt và dậy mùi thơm lừng.', 'Đảo liên tục trên lửa vừa để sả vàng giòn đều mà không bị cháy khét ở phần cạnh chảo.', 2),
('imp-9d527dacd46efc67_v4_step_4', 'imp-9d527dacd46efc67', 4, 'sauce', 'Nêm gia vị chay vào chảo sả ớt', 'Hạ lửa nhỏ, cho 15 ml nước tương, 6 g hạt nêm chay nấm hương, 2 g đường cát trắng và 1,5 g tiêu đen xay vào chảo sả ớt, đảo nhanh 30 giây cho gia vị tan đều thấm vào từng vụn sả.', NULL, NULL),
('imp-9d527dacd46efc67_v4_step_5', 'imp-9d527dacd46efc67', 5, 'cook', 'Xóc đều đậu phụ chiên bám sả ớt thơm', 'Trút toàn bộ đậu phụ đã chiên giòn vào chảo sả ớt, tăng nhẹ lên lửa vừa và đảo xóc nhẹ nhàng bằng đũa trong khoảng 2 phút để lớp sả ớt đậm đà bám đều quanh từng miếng đậu mà không làm vỡ nát.', 'Dùng đũa đảo nhẹ tay khi xóc đậu phụ với sả ớt để giữ nguyên khối miếng đậu vàng giòn không bị vỡ nát.', 2),
('imp-9d527dacd46efc67_v4_step_6', 'imp-9d527dacd46efc67', 6, 'finish', 'Pha nước chấm xì dầu và bày đĩa thưởng thức', 'Trộn 25 ml nước tương còn lại với 2 g đường và ớt thái lát làm nước chấm. Xếp đậu phụ chiên sả ớt vào giữa đĩa đã viền lát dưa leo, rắc ngò rí và hành lá thái nhỏ (nếu dùng) lên trên rồi dọn nóng với cơm trắng.', NULL, NULL),
('imp-236e3b84d403909e_v4_step_1', 'imp-236e3b84d403909e', 1, 'prep', 'Làm sạch khử mùi đùi gà và sơ chế hành gừng', 'Nhặt sạch lông tơ còn sót trên 4 chiếc đùi gà, chà xát đều 6 g muối hạt và nước cốt 1 quả chanh tươi lên bề mặt da trong 2 phút rồi xả sạch dưới vòi nước lạnh, để ráo. Đập dập 40 g gừng và 30 g hành tím; rửa sạch hành lá cắt khúc 1 bó và thái nhỏ 1 bó; lá chanh thái sợi chỉ mảnh.', 'Chà xát muối hạt cùng nước cốt chanh giúp làm sạch hoàn toàn chất nhờn và mùi hôi trên da gà mà vẫn giữ được độ căng mịn.', NULL),
('imp-236e3b84d403909e_v4_step_2', 'imp-236e3b84d403909e', 2, 'cook', 'Luộc đùi gà từ nước lạnh và hớt bọt trong', 'Xếp đùi gà vào nồi rộng, đổ 2 lít nước lọc lạnh ngập mặt thịt rồi thêm gừng đập dập, hành tím đập dập, 1 bó hành lá cắt khúc, 6 g muối hạt và 5 g hạt nêm. Bật lửa vừa đun khoảng 8 phút đến khi nước bắt đầu sôi thì hớt sạch bọt nổi cho nước dùng trong veo.', 'Cho gà vào từ nước lạnh và chỉ đun lửa vừa giúp nhiệt truyền vào tận xương mà da gà không bị co rút nứt rách.', 8),
('imp-236e3b84d403909e_v4_step_3', 'imp-236e3b84d403909e', 3, 'cook', 'Sôi lăn tăn rồi tắt bếp ủ chín mềm mọng', 'Hạ nhỏ lửa để nồi nước chỉ sôi lăn tăn nhẹ trong 6 phút, sau đó tắt bếp, đậy kín nắp vung và ủ gà trong nồi thêm 20 phút cho thịt chín ngấm từ từ đến tận xương mà vẫn giữ nguyên độ ẩm ngọt.', 'Phương pháp luộc kết hợp ủ nhiệt giúp thịt đùi gà mềm mọng đều, không bị khô bã ở phần ngoài hay còn đỏ máu ở khớp xương.', 26),
('imp-236e3b84d403909e_v4_step_4', 'imp-236e3b84d403909e', 4, 'cook', 'Ngâm nước lạnh làm giòn da và tạo màu vàng óng', 'Dùng tăm xiên vào phần thịt dày nhất của đùi gà thấy nước ứa ra trong suốt không còn màu hồng là đã chín. Vớt gà ra ngâm ngay vào thau nước lạnh sạch khoảng 5 phút cho da săn giòn, rồi vớt ra rổ để ráo. Hòa 2 g bột nghệ với 1 muỗng canh nước luộc gà quét thật mỏng lên mặt da để lên màu vàng ươm bắt mắt.', NULL, 5),
('imp-236e3b84d403909e_v4_step_5', 'imp-236e3b84d403909e', 5, 'sauce', 'Pha muối tiêu chanh ớt chấm thịt gà', 'Trộn 6 g muối hạt còn lại với 2 g tiêu đen xay và vài lát ớt tươi trong chén nhỏ, vắt nước cốt 1 quả chanh tươi còn lại vào khuấy nhẹ cho dậy mùi thơm.', NULL, NULL),
('imp-236e3b84d403909e_v4_step_6', 'imp-236e3b84d403909e', 6, 'finish', 'Chặt gà xếp đĩa và rắc hành lá, lá chanh', 'Đợi đùi gà ráo mặt, dùng dao sắc chặt thành từng miếng vừa ăn xếp ngay ngắn ra đĩa. Rắc đều phần hành lá thái nhỏ và lá chanh thái chỉ lên trên, dọn dùng ngay cùng chén muối tiêu chanh ớt.', NULL, NULL),
('imp-df7571988423623f_v4_step_1', 'imp-df7571988423623f', 1, 'prep', 'Làm sạch mực tươi và cắt khoanh vừa ăn', 'Kéo nhẹ đầu mực tách khỏi thân, rút bỏ túi mực, nang sống lưng và nội tạng, cắt bỏ mắt và răng mực rồi lột lớp da ngoài. Rửa mực 2–3 lần dưới vòi nước lạnh cho thật sạch nhớt, để ráo; mực nhỏ để nguyên con, mực to cắt khoanh dày 2 cm.', 'Lột bỏ lớp màng da sẫm bên ngoài giúp miếng mực sau khi hấp có màu trắng đẹp mắt, ăn giòn ngọt và giảm hẳn mùi tanh.', NULL),
('imp-df7571988423623f_v4_step_2', 'imp-df7571988423623f', 2, 'marinate', 'Ướp mực với nước mắm, đường và tiêu xay', 'Cho mực vào tô sạch cùng 15 ml nước mắm ngon, 4 g đường cát trắng và 1 g tiêu đen xay, trộn nhẹ cho gia vị bám đều rồi để ướp 15 phút cho thịt mực săn và đậm đà.', 'Ướp mực trước với chút nước mắm giúp mực khi hấp ra ít nước hơn và giữ được vị ngọt đậm tự nhiên.', 15),
('imp-df7571988423623f_v4_step_3', 'imp-df7571988423623f', 3, 'prep', 'Sơ chế sả, gừng, ớt hiểm và hành lá', 'Bóc bỏ bẹ già 3 cây sả, đập dập rồi cắt khúc dài 5 cm. Cạo vỏ 20 g gừng thái lát mỏng. Thái lát vát 1 quả ớt hiểm để hấp và băm nhỏ 1 quả làm nước chấm. Rửa sạch hành lá, cắt khúc 4 cm.', NULL, NULL),
('imp-df7571988423623f_v4_step_4', 'imp-df7571988423623f', 4, 'sauce', 'Pha chén nước mắm chanh ớt chấm mực', 'Khuấy tan 15 ml nước mắm ngon còn lại với 4 g đường cát trắng, vắt nước cốt 1 quả chanh tươi cùng 1 g tiêu đen xay và 1 quả ớt hiểm băm nhỏ tạo thành chén nước chấm chua ngọt cay nồng.', NULL, NULL),
('imp-df7571988423623f_v4_step_5', 'imp-df7571988423623f', 5, 'cook', 'Hấp mực nhanh trên lửa lớn cùng sả ớt', 'Đổ 500 ml nước lọc vào nồi hấp đun sôi bùng trên lửa lớn. Xếp sả đập dập và gừng thái lát xuống đáy đĩa sâu lòng, đặt mực đã ướp lên trên rồi rải ớt hiểm thái lát và hành lá cắt khúc phủ mặt. Cho đĩa vào xửng đậy kín vung và hấp lửa lớn 7 phút đến khi mực chuyển trắng đục và cong săn lại.', 'Hấp mực ở lửa lớn vừa đủ 6–8 phút; mực vừa chín tới sẽ giòn sần sật, nếu kéo dài thời gian mực sẽ bị teo dai.', 7),
('imp-df7571988423623f_v4_step_6', 'imp-df7571988423623f', 6, 'finish', 'Ủ ngắn và dọn đĩa mực hấp nóng hổi', 'Tắt bếp, giữ nguyên đĩa mực trong nồi thêm 1 phút rồi nhấc ra, gạn rưới phần nước hấp thơm sả ớt đều lên thân mực và dọn ăn nóng ngay cùng chén nước mắm chanh ớt.', NULL, NULL),
('imp-2b88b3e83b941e80_v4_step_1', 'imp-2b88b3e83b941e80', 1, 'prep', 'Sơ chế khử nhựa và bào sợi su su, cà rốt', 'Khứa nhẹ vài đường quanh quả su su và ngâm nước lạnh 5 phút cho chảy bớt nhựa rồi gọt vỏ, bổ đôi bỏ hạt và bào sợi mảnh. Cà rốt gọt vỏ bào sợi tương tự. Trộn su su với 4 g muối ăn, cà rốt với 2 g muối ăn trong hai tô riêng, để yên 10 phút cho ra bớt nước rồi dùng tay sạch vắt thật ráo.', 'Khứa vỏ su su ngâm nước trước khi gọt giúp tránh dính nhựa tay và giữ sợi su su giòn trắng không chát.', 10),
('imp-2b88b3e83b941e80_v4_step_2', 'imp-2b88b3e83b941e80', 2, 'cook', 'Luộc chín tôm tươi và chẻ đôi', 'Đun sôi 500 ml nước lọc trên lửa lớn, thả tôm tươi đã rửa sạch rút chỉ đen vào luộc khoảng 3 phút đến khi tôm chuyển màu đỏ cam đều, thịt săn chín hoàn toàn. Vớt tôm ra để nguội, bóc sạch vỏ và chẻ đôi theo chiều dọc.', NULL, 3),
('imp-2b88b3e83b941e80_v4_step_3', 'imp-2b88b3e83b941e80', 3, 'cook', 'Rang lạc, phi hành tím và chuẩn bị rau thơm', 'Rang chín vàng lạc trên lửa nhỏ, xát sạch vỏ lụa và giã dập vừa. Bắc chảo nhỏ với 15 ml dầu ăn ở lửa nhỏ, phi hành tím thái lát đến khi vừa ngả vàng giòn thì vớt ngay ra giấy thấm dầu. Nhặt rửa sạch rau răm và ngò rí, cắt khúc; băm nhỏ tỏi và 1 quả ớt hiểm, quả còn lại thái lát.', NULL, NULL),
('imp-2b88b3e83b941e80_v4_step_4', 'imp-2b88b3e83b941e80', 4, 'sauce', 'Pha nước trộn gỏi chua ngọt hài hòa', 'Khuấy tan 35 ml nước mắm ngon với 30 g đường cát trắng, 15 ml giấm gạo và nước cốt 1,5 quả chanh tươi đến khi tan hết đường, sau đó cho tỏi băm và ớt hiểm băm vào đảo đều.', NULL, NULL),
('imp-2b88b3e83b941e80_v4_step_5', 'imp-2b88b3e83b941e80', 5, 'prep', 'Trộn thấm hai lượt su su, cà rốt và tôm', 'Cho su su và cà rốt đã vắt ráo vào âu lớn, rưới 2/3 lượng nước trộn vào đảo đều và để 5 phút cho thấm. Tiếp tục thêm tôm chẻ đôi, rau răm và một nửa lượng lạc rang cùng phần nước trộn còn lại vào trộn nhẹ tay.', 'Su su và cà rốt đã ướp muối trước nên có sẵn vị mặn nhẹ, hãy rưới nước trộn từ từ và nếm lại trước khi hoàn thiện.', 5),
('imp-2b88b3e83b941e80_v4_step_6', 'imp-2b88b3e83b941e80', 6, 'finish', 'Hoàn thiện đĩa gỏi su su tôm giòn mát', 'Bày gỏi ra đĩa, rắc phần lạc rang giã dập còn lại, ngò rí, hành tím phi giòn và vài lát ớt hiểm lên trên; dọn ăn ngay kèm bánh phồng tôm.', 'Rắc phần lạc rang và hành tím phi còn lại lên mặt đĩa ngay lúc dọn sẽ giữ trọn độ giòn thơm khi xúc cùng bánh phồng tôm.', NULL),
('imp-0b34a73de8ccab71_v4_step_1', 'imp-0b34a73de8ccab71', 1, 'prep', 'Bóp muối vắt khô dưa leo và cà rốt', 'Rửa sạch dưa leo, gọt vỏ, xẻ dọc bỏ hết phần ruột hạt rồi thái lát mỏng vừa ăn. Cà rốt cạo vỏ, thái lát mỏng tương tự. Trộn dưa leo và cà rốt với 5 g muối ăn, để yên 5 phút cho ra nước rồi dùng khăn sạch vắt thật khô ráo.', 'Thấm và vắt thật khô dưa leo cà rốt trước khi trộn sẽ giúp món gỏi giữ được độ giòn và không làm ỉu đậu phụ chiên.', 5),
('imp-0b34a73de8ccab71_v4_step_2', 'imp-0b34a73de8ccab71', 2, 'cook', 'Chiên vàng giòn đậu phụ rồi thái miếng vừa ăn', 'Thấm thật ráo nước bề mặt 3 bìa đậu phụ trắng. Làm nóng chảo trên lửa vừa với 40 ml dầu ăn, thả đậu vào chiên khoảng 6 phút, lật đều các mặt đến khi lớp vỏ chuyển vàng giòn ruộm thì vớt ra giấy thấm dầu, để nguội bớt rồi thái lát mỏng hoặc sợi to vừa gắp.', 'Chiên nguyên bìa đậu phụ cho vàng giòn trước rồi mới thái mỏng giúp miếng đậu giữ form đẹp và không bị vỡ nát khi trộn.', 6),
('imp-0b34a73de8ccab71_v4_step_3', 'imp-0b34a73de8ccab71', 3, 'cook', 'Rang giã đậu phộng và sơ chế rau thơm', 'Rang chín vàng đậu phộng trên lửa nhỏ trong 5 phút, để nguội xát sạch vỏ lụa rồi giã dập vừa. Nhặt rửa sạch rau răm, rau húng quế và hành lá, để ráo rồi thái nhỏ. Băm nhuyễn tỏi khô, 1 quả ớt hiểm băm nhỏ và 1 quả thái lát.', NULL, 5),
('imp-0b34a73de8ccab71_v4_step_4', 'imp-0b34a73de8ccab71', 4, 'sauce', 'Pha nước mắm chay chua ngọt', 'Cho 30 ml nước mắm chay, 20 g đường cát trắng và nước cốt 1,5 quả chanh tươi vào bát, khuấy kỹ cho đường tan hết rồi thêm tỏi băm và ớt hiểm băm nhuyễn vào đảo đều.', NULL, NULL),
('imp-0b34a73de8ccab71_v4_step_5', 'imp-0b34a73de8ccab71', 5, 'prep', 'Trộn thấm dưa leo, cà rốt và đậu phụ chiên', 'Cho dưa leo, cà rốt đã vắt khô cùng đậu phụ chiên thái mỏng vào tô lớn, rưới đều bát nước mắm chay lên trên, trộn thật nhẹ tay để đậu phụ không nát và để nghỉ 5 phút cho ngấm vị.', NULL, 5),
('imp-0b34a73de8ccab71_v4_step_6', 'imp-0b34a73de8ccab71', 6, 'finish', 'Thêm rau thơm, đậu phộng và bày đĩa', 'Cho rau răm, rau húng quế thái nhỏ cùng một nửa lượng đậu phộng rang giã dập vào tô gỏi, đảo nhẹ lần cuối. Bày gỏi ra đĩa, rắc hành lá cắt nhỏ, phần đậu phộng còn lại và vài lát ớt hiểm lên trên rồi thưởng thức ngay.', 'Chỉ rắc phần đậu phộng rang còn lại và hành lá lên trên ngay khi chuẩn bị dọn để đậu không bị mềm ỉu.', NULL),
('imp-0ea0e53318af9de9_v4_step_1', 'imp-0ea0e53318af9de9', 1, 'prep', 'Phi giòn hành tím và sơ chế rau củ', 'Đun nóng 45 ml dầu ăn trên chảo ở lửa vừa, thả hành tím khô thái lát mỏng vào đảo đều tay đến khi vừa ngả màu vàng rơm thì vớt ngay ra giấy thấm dầu để hành giòn rụm (giữ lại 15 ml dầu hành). Rửa sạch xà lách, húng quế, ngò rí rồi thái vừa ăn; bào sợi cà rốt; thái lát dưa leo; thái múi cau mỏng hành tây và cắt nhỏ hành lá.', 'Vớt hành phi khi vừa vàng nhạt vì lượng nhiệt giữ trong lát hành sẽ giúp hành tiếp tục chín vàng giòn mà không bị đắng.', 5),
('imp-0ea0e53318af9de9_v4_step_2', 'imp-0ea0e53318af9de9', 2, 'marinate', 'Thái mỏng và ướp thịt bò thấm gia vị', 'Thịt bò thăn thái lát mỏng ngang thớ, ướp cùng 15 ml xì dầu, 15 ml dầu hào, 5 g hạt nêm, 2 g tiêu đen xay, 1/2 lượng sả cây băm và 10 g tỏi khô băm, thêm 5 ml dầu hành phi rồi trộn đều và ướp 15 phút cho thịt ngấm mềm.', NULL, 15),
('imp-0ea0e53318af9de9_v4_step_3', 'imp-0ea0e53318af9de9', 3, 'sauce', 'Pha nước mắm chua ngọt chan bún', 'Khuấy tan 20 g đường cát trắng trong 100 ml nước lọc với 45 ml nước mắm ngon và nước cốt của 1,5 quả chanh tươi; sau đó thả 15 g tỏi khô băm còn lại và ớt tươi băm vào để tỏi ớt nổi đều trên mặt chén.', 'Đợi đường tan hoàn toàn trước khi thả tỏi ớt băm sẽ giúp tỏi ớt nổi đều đẹp mắt trên mặt nước chấm.', NULL),
('imp-0ea0e53318af9de9_v4_step_4', 'imp-0ea0e53318af9de9', 4, 'prep', 'Trụng bún tươi và chần sơ giá đỗ', 'Đun sôi nồi nước lớn, trụng nhanh bún gạo tươi khoảng 1 phút cho tơi mềm rồi vớt ra rổ để thật ráo nước; tiếp tục chần giá đỗ khoảng 30 giây cho vừa chín tới vẫn giữ độ giòn.', NULL, 2),
('imp-0ea0e53318af9de9_v4_step_5', 'imp-0ea0e53318af9de9', 5, 'cook', 'Xào nhanh thịt bò cùng sả tỏi và hành tây', 'Làm nóng chảo trên lửa lớn với 15 ml dầu ăn còn lại và 10 ml dầu hành phi, cho phần sả băm và 10 g tỏi băm còn lại vào đảo thơm 15 giây. Trút thịt bò đã ướp vào đảo thật nhanh tay 1–2 phút, thêm hành tây thái lát vào xào chung thêm 45 giây đến khi thịt bò vừa chín tới mềm ngọt thì tắt bếp ngay.', 'Xào thịt bò ở lửa thật lớn trong thời gian ngắn giúp thịt chín mềm mọng mà không bị ra nước hoặc dai.', 3),
('imp-0ea0e53318af9de9_v4_step_6', 'imp-0ea0e53318af9de9', 6, 'finish', 'Xếp tô bún bò Nam Bộ và trộn đều thưởng thức', 'Chia bún tươi ra 4 tô, xếp xà lách, húng quế, ngò rí, giá đỗ chần, cà rốt bào sợi và dưa leo xung quanh, đặt thịt bò xào hành tây nóng hổi lên trên cùng. Rắc đậu phộng rang giã dập, hành tím phi giòn và hành lá thái nhỏ rồi chan nước mắm chua ngọt trộn đều trước khi ăn.', NULL, NULL),
('imp-1fa2a5a65ec5a26d_v4_step_1', 'imp-1fa2a5a65ec5a26d', 1, 'prep', 'Sơ chế, giã và lọc nước cua đồng', 'Ngâm cua đồng tươi 1 giờ cho nhả hết bùn đất rồi rửa sạch. Tách mai, bỏ yếm và dùng thìa khều phần gạch cua ra chén, ướp với 2 g hạt nêm và 2 g tiêu đen xay. Giã nhuyễn thân cua cùng 3 g muối ăn, sau đó hòa với 2 lít nước lọc chia làm 3 lần bóp nhẹ và gạn lọc qua rây để lấy phần nước thịt cua, bỏ xác vỏ cứng.', 'Gạn lọc qua nhiều lần với nước nguội giúp lấy hết phần thịt cua mịn mà không lẫn cặn vỏ cứng.', 10),
('imp-1fa2a5a65ec5a26d_v4_step_2', 'imp-1fa2a5a65ec5a26d', 2, 'cook', 'Chưng riêu cua kết tảng xốp mịn', 'Hòa 6 g muối ăn, 4 g hạt nêm và 2 g đường cát trắng vào nồi nước cua, đặt lên bếp đun ở lửa vừa và khuấy nhẹ đáy nồi theo một chiều trong 3 phút đầu. Khi nước nóng lên và riêu cua bắt đầu kết mảng nổi dần lên mặt thì ngưng khuấy, hạ lửa nhỏ đợi riêu đóng tảng dày rồi nhẹ tay vớt riêng ra tô.', 'Hạ lửa nhỏ và không để nước sôi sùng sục sau khi riêu nổi sẽ giữ được mảng riêu nguyên vẹn, xốp mềm.', 8),
('imp-1fa2a5a65ec5a26d_v4_step_3', 'imp-1fa2a5a65ec5a26d', 3, 'cook', 'Chiên vàng đậu phụ và xào gạch cua, cà chua', 'Đun nóng 85 ml dầu ăn trên chảo lửa vừa, thả đậu phụ trắng cắt vuông vào chiên vàng giòn các mặt khoảng 6 phút rồi vớt ra giấy thấm dầu. Trên chảo khác, đun nóng 15 ml dầu ăn và 15 ml dầu màu điều, phi thơm một nửa hành tím khô thái lát rồi trút gạch cua đã ướp vào đảo nhanh 1 phút thành phần nước gạch đỏ óng trút ra chén; tiếp tục phi thơm phần hành tím còn lại và xào cà chua múi cau với 3 g đường cát trắng trong 3 phút.', NULL, 10),
('imp-1fa2a5a65ec5a26d_v4_step_4', 'imp-1fa2a5a65ec5a26d', 4, 'cook', 'Hoàn thiện nồi nước dùng bún riêu chua thanh', 'Trút cà chua xào, đậu phụ chiên và phần nước gạch cua vào nồi nước cua, nêm 10 g mắm tôm Bắc và 20 ml nước mắm ngon rồi đun sôi nhẹ 5 phút cho đậu ngấm vị. Trước khi tắt bếp, rót từ từ 60 ml giấm bỗng vào nồi, khuấy nhẹ rồi nếm lại vị chua thanh mặn ngọt vừa miệng.', 'Cho giấm bỗng ở bước cuối cùng giúp giữ trọn hương thơm đặc trưng của rượu nếp mà không bị bay mất mùi.', 5),
('imp-1fa2a5a65ec5a26d_v4_step_5', 'imp-1fa2a5a65ec5a26d', 5, 'prep', 'Sơ chế rau sống và trụng bún tươi', 'Rửa sạch xà lách, rau kinh giới với 3 g muối ăn pha loãng rồi vẩy ráo; chẻ sợi rau muống ngâm nước cho xoăn giòn; ngâm hoa chuối bào trong nước có vắt 1/2 quả chanh tươi cho trắng giòn. Thái khúc hành lá, thái lát ớt tươi và cắt múi 1/2 quả chanh còn lại. Trụng nhanh bún tươi qua nước sôi cho nóng tơi rồi chia vào 4 tô.', NULL, NULL),
('imp-1fa2a5a65ec5a26d_v4_step_6', 'imp-1fa2a5a65ec5a26d', 6, 'finish', 'Bày tô bún riêu cua đậu và thưởng thức', 'Gắp tảng riêu cua đặt lên trên tô bún, chan ngập nước dùng nóng cùng đậu phụ chiên và cà chua, rắc hành lá thái nhỏ. Dọn nóng ngay kèm đĩa rau sống, chén 10 g mắm tôm Bắc còn lại, chanh tươi và ớt tươi.', NULL, NULL),
('imp-ff6d8fe6659e4976_v4_step_1', 'imp-ff6d8fe6659e4976', 1, 'prep', 'Sơ chế thịt, vắt cốt hành sả và thắng nước hàng', 'Chà rửa thịt ba chỉ heo với 3 g muối ăn rồi xả sạch, thấm ráo và thái lát mỏng 0,5 cm. Xay nhuyễn sả tươi và hành tím khô với 20 ml nước lọc rồi vắt lấy nước cốt thơm, bỏ bã. Thắng 8 g đường vàng với chút nước lọc trên chảo nhỏ đến màu cánh gián tạo nước hàng.', NULL, 8),
('imp-ff6d8fe6659e4976_v4_step_2', 'imp-ff6d8fe6659e4976', 2, 'marinate', 'Ướp thịt ba chỉ và thịt nạc vai xay', 'Trộn đều nước cốt sả hành, nước hàng vừa thắng, 5 ml nước mắm ngon, 4 g mắm tôm, 8 g đường cát trắng, 6 g hạt nêm, 4 g muối ăn và 3 g tiêu đen xay. Chia đôi hỗn hợp ướp đều vào thịt ba chỉ và thịt nạc vai heo xay, bọc kín để ngăn mát tủ lạnh ít nhất 1 giờ. Trước khi nướng 15 phút, trộn thêm 1/2 muỗng cà phê nước cốt chanh tươi vào cả hai phần thịt.', 'Thêm chút nước cốt chanh trước khi nướng giúp thớ thịt mềm ẩm và dậy mùi thơm hơn khi gặp nhiệt cao.', 60),
('imp-ff6d8fe6659e4976_v4_step_3', 'imp-ff6d8fe6659e4976', 3, 'prep', 'Làm dưa góp đu đủ xanh và cà rốt', 'Thái lát mỏng đu đủ xanh và cà rốt, bóp nhẹ với 2 g muối ăn trong 5 phút rồi rửa sạch, vắt ráo nước. Trộn dưa góp với 6 g đường cát trắng, 10 ml giấm gạo, 1 g muối ăn còn lại và 1 quả ớt hiểm tươi băm, ướp mát 20 phút cho giòn thấm vị.', NULL, 20),
('imp-ff6d8fe6659e4976_v4_step_4', 'imp-ff6d8fe6659e4976', 4, 'cook', 'Nướng chả miếng và chả viên trong lò nướng', 'Làm nóng lò nướng ở 200°C trước 10 phút. Nặn thịt nạc vai xay thành viên dẹt tròn vừa ăn rồi xếp cùng thịt ba chỉ lên khay vỉ nướng có lót khay hứng mỡ bên dưới. Nướng ở 200°C khoảng 12–15 phút, giữa chừng lật mặt thịt và phết nhẹ 15 ml dầu ăn lên bề mặt để chả chín kỹ hoàn toàn, vàng óng xém cạnh mà không bị khô.', 'Đặt khay hứng có chút nước bên dưới vỉ nướng giúp lò không bị khói và chả giữ được độ ẩm mềm.', 15),
('imp-ff6d8fe6659e4976_v4_step_5', 'imp-ff6d8fe6659e4976', 5, 'sauce', 'Pha nước mắm ấm chấm bún chả', 'Hòa tan 220 ml nước lọc còn lại với 80 ml nước mắm ngon, 56 g đường cát trắng, 15 ml giấm gạo và nước cốt chanh tươi còn lại. Đun trên lửa nhỏ đến khi đường tan hết và nước chấm ấm nóng (không đun sôi), tắt bếp rồi cho tỏi khô băm và 1 quả ớt hiểm tươi băm vào.', 'Giữ nước chấm ở độ ấm nóng vừa phải giúp mỡ chả không bị đông và hòa quyện hương thơm tỏi ớt chanh.', NULL),
('imp-ff6d8fe6659e4976_v4_step_6', 'imp-ff6d8fe6659e4976', 6, 'finish', 'Bày biện bún, rau sống và thưởng thức', 'Rửa sạch xà lách tươi, lá tía tô cùng rau kinh giới và húng lủi, vẩy ráo nước. Múc nước chấm ấm ra 4 bát, thả chả miếng, chả viên nướng nóng và dưa góp đu đủ cà rốt vào bát; ăn kèm đĩa bún gạo tươi và rổ rau sống.', NULL, NULL),
('imp-675a6c1cea0b604e_v4_step_1', 'imp-675a6c1cea0b604e', 1, 'prep', 'Sơ chế cơm nguội và cắt hạt lựu rau củ, đậu nấm', 'Bóp tơi nhẹ 550 g cơm trắng để nguội cho các hạt cơm rời nhau. Nấm đùi gà cắt gốc, rửa nhanh để ráo rồi thái hạt lựu cạnh 0,8 cm; cà rốt gọt vỏ thái hạt lựu nhỏ 0,5 cm; đậu phụ thấm khô thái hạt lựu cạnh 1 cm; tỏi khô băm nhuyễn; hành lá thái nhỏ.', 'Cơm nguội hong ráo hoặc để ngăn mát 30 phút trước khi rang sẽ giúp từng hạt cơm săn tơi, không bị bết dính.', NULL),
('imp-675a6c1cea0b604e_v4_step_2', 'imp-675a6c1cea0b604e', 2, 'cook', 'Phi thơm tỏi và xào chín nấm đùi gà, cà rốt', 'Làm nóng chảo rộng đáy trên lửa vừa với 15 ml dầu ăn, cho tỏi băm vào phi thơm trong 30 giây. Trút nấm đùi gà và cà rốt thái hạt lựu vào đảo đều 3 phút đến khi cà rốt vừa chín tới và nấm săn ráo nước.', NULL, 3),
('imp-675a6c1cea0b604e_v4_step_3', 'imp-675a6c1cea0b604e', 3, 'cook', 'Xào nhẹ đậu phụ cùng nhân nấm cà rốt', 'Nêm vào chảo nhân 4 g hạt nêm chay và 4 g đường cát trắng, đảo đều. Tiếp theo thả đậu phụ cắt hạt lựu vào đảo nhẹ tay khoảng 2 phút cho đậu se mặt và ngấm gia vị mà không bị vỡ nát, sau đó trút phần nhân ra đĩa riêng.', 'Đảo nhẹ đậu phụ hạt lựu bằng xẻng bản rộng giúp giữ khối vuông đẹp mắt.', 2),
('imp-675a6c1cea0b604e_v4_step_4', 'imp-675a6c1cea0b604e', 4, 'cook', 'Rang tơi hạt cơm nguội trên chảo nóng', 'Lau sạch chảo, thêm 15 ml dầu ăn còn lại làm nóng trên lửa vừa rồi đổ cơm nguội vào. Dùng muôi gỗ dàn đều và đảo liên tục trong 4 phút để hạt cơm nóng đều, tách rời từng hạt tơi ráo và hơi săn bóng.', NULL, 4),
('imp-675a6c1cea0b604e_v4_step_5', 'imp-675a6c1cea0b604e', 5, 'cook', 'Trộn nhân đậu nấm và nêm xì dầu dậy hương', 'Trút đĩa nhân nấm, cà rốt và đậu phụ trở lại chảo cơm, bật lửa lớn. Rưới 25 ml nước tương dọc theo thành chảo cho dậy mùi thơm cùng 3 g muối ăn, đảo đều tay thêm 3 phút cho hạt cơm thấm vị và quyện đều với phần nhân.', 'Rưới nước tương quanh thành chảo đang nóng giúp nước tương bốc hương thơm lừng mà không làm ướt nhão cơm.', 3),
('imp-675a6c1cea0b604e_v4_step_6', 'imp-675a6c1cea0b604e', 6, 'finish', 'Hoàn thiện với hành lá và tiêu đen xay', 'Nêm lại cho vừa khẩu vị, rắc hành lá thái nhỏ và 1,5 g tiêu đen xay vào đảo nhanh 15 giây rồi tắt bếp. Múc cơm rang ra đĩa và thưởng thức nóng.', NULL, NULL),
('imp-4dbcf05ec1f88763_v4_step_1', 'imp-4dbcf05ec1f88763', 1, 'prep', 'Sơ chế nấm đùi gà, sả, ớt và hành tỏi', 'Cắt bỏ phần gốc nấm đùi gà, rửa sạch nhanh dưới vòi nước rồi để thật ráo và thái dọc thành lát dày 0,8–1 cm. Sả tươi bóc bỏ bẹ già, băm nhuyễn; tỏi khô băm nhuyễn; ớt hiểm băm nhỏ hoặc thái lát; hành lá tách đầu hành đập dập và phần lá thái nhỏ; ngò rí thái nhỏ.', 'Thái nấm dọc thân dày khoảng 0,8–1 cm giúp nấm giữ được độ giòn dai mà không bị teo vụn khi xào lửa lớn.', NULL),
('imp-4dbcf05ec1f88763_v4_step_2', 'imp-4dbcf05ec1f88763', 2, 'marinate', 'Ướp nấm đùi gà thấm gia vị sả tỏi', 'Cho nấm đùi gà vào tô cùng 30 ml nước tương, 12 g đường cát trắng, 2 g muối ăn, 1 g bột ngọt cùng một nửa lượng sả băm và một nửa lượng tỏi băm. Trộn nhẹ tay cho gia vị phủ đều và ướp trong 15 phút để nấm ngấm đậm vị.', NULL, 15),
('imp-4dbcf05ec1f88763_v4_step_3', 'imp-4dbcf05ec1f88763', 3, 'cook', 'Phi thơm sả, tỏi, ớt và đầu hành lá', 'Làm nóng chảo với 20 ml dầu ăn trên lửa vừa, thả phần sả băm và tỏi băm còn lại cùng đầu hành lá đập dập và ớt hiểm vào phi khoảng 1–2 phút đến khi sả ngả vàng nhẹ và dậy mùi thơm nồng.', 'Chia sả tỏi làm hai phần để vừa ướp thấm vào thớ nấm, vừa phi thơm tạo lớp áo thơm giòn bên ngoài.', 2),
('imp-4dbcf05ec1f88763_v4_step_4', 'imp-4dbcf05ec1f88763', 4, 'cook', 'Xào săn nấm đùi gà trên lửa vừa', 'Trút toàn bộ tô nấm đã ướp cùng phần nước ướp vào chảo, giữ lửa vừa và đảo nhẹ nhàng khoảng 4 phút cho nấm tiết nước ngọt tự nhiên và thấm đều hương sả phi.', 'Xào nấm trên lửa vừa ở giai đoạn đầu giúp nấm chín đều từ trong ra ngoài mà không bị cháy sả tỏi.', 4),
('imp-4dbcf05ec1f88763_v4_step_5', 'imp-4dbcf05ec1f88763', 5, 'cook', 'Xào ráo se cạnh và nêm hạt nêm chay', 'Khi nước trong chảo cạn dần, nêm thêm 3 g hạt nêm chay vào đảo đều và tăng nhẹ lên lửa vừa lớn trong 3 phút đến khi từng lát nấm săn chắc, se mặt và ngả màu vàng nâu óng ả.', NULL, 3),
('imp-4dbcf05ec1f88763_v4_step_6', 'imp-4dbcf05ec1f88763', 6, 'finish', 'Hoàn thiện với hành lá, mè rang và ngò rí', 'Thả phần lá xanh hành lá vào đảo nhanh 15 giây rồi tắt bếp. Gắp nấm đùi gà xào sả ớt ra đĩa, rắc mè trắng rang vàng và ngò rí lên trên rồi dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-b88c09328fa3f33a_v4_step_1', 'imp-b88c09328fa3f33a', 1, 'prep', 'Sơ chế rau sống, cà rốt, dưa leo và giá đỗ', 'Nhặt xà lách, rau húng quế và hẹ lá, ngâm nước muối pha 1,5 g muối ăn trong 10 phút rồi rửa sạch, vẩy thật ráo nước. Cà rốt bào sợi dài, chần trong nồi nước sôi có 1,5 g muối khoảng 2 phút rồi vớt ra để ráo. Giá đỗ trụng nhanh 15 giây, dưa leo bỏ ruột thái sợi dài.', 'Rau sống, bún và giá đỗ phải để thật ráo nước thì gỏi cuốn mới không bị nhão ướt hay rách bánh tráng.', 2),
('imp-b88c09328fa3f33a_v4_step_2', 'imp-b88c09328fa3f33a', 2, 'cook', 'Chiên vàng đậu phụ và xào nấm đùi gà', 'Đun nóng 15 ml dầu ăn trên lửa vừa, chiên vàng đều hai mặt đậu phụ trắng trong 6 phút rồi vớt ra, thái thanh dài và rưới ngay 15 ml nước tương lên khi đậu còn nóng để thấm vị. Dùng chảo với 10 ml dầu ăn còn lại xào nấm đùi gà thái sợi cùng 4 g hạt nêm chay trên lửa lớn khoảng 3 phút cho nấm vừa chín săn, để riêng.', 'Tẩm nước tương ngay lúc đậu phụ vừa chiên còn nóng giúp từng thanh đậu thấm đậm đà hơn.', 6),
('imp-b88c09328fa3f33a_v4_step_3', 'imp-b88c09328fa3f33a', 3, 'cook', 'Trụng tơi bún gạo tươi', 'Đun sôi nồi nước, thả nhanh 300 g bún gạo tươi vào trụng khoảng 30 giây cho sợi bún mềm tơi, sau đó đổ ra rổ xả ngay dưới vòi nước lạnh và để thật ráo nước.', NULL, NULL),
('imp-b88c09328fa3f33a_v4_step_4', 'imp-b88c09328fa3f33a', 4, 'sauce', 'Pha nước chấm nước tương chanh ớt mè rang', 'Cho vào chén 35 ml nước tương còn lại, 20 g đường cát trắng, 20 ml giấm gạo và nước cốt 1 quả chanh tươi, khuấy đều đến khi đường tan hoàn toàn. Cuối cùng thêm 2 g ớt bột và 9 g mè trắng rang vàng vào khuấy đều.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-b88c09328fa3f33a_v4_step_5', 'imp-b88c09328fa3f33a', 5, 'finish', 'Làm mềm bánh tráng và cuốn gỏi chay chặt tay', 'Nhúng nhanh từng lá bánh tráng cuốn gỏi qua nước sạch rồi trải lên thớt phẳng. Lót 1–2 lá xà lách lên 1/3 miếng bánh tráng, xếp bún gạo tươi, nấm đùi gà xào, thanh đậu phụ, cà rốt, dưa leo, giá đỗ và rau húng quế lên trên; gấp hai mép bánh vào trong, đặt 1 cọng hẹ lá ở mép ngoài rồi cuộn tròn thật chắc tay đến hết 12 cuốn.', 'Chỉ lướt nhanh bánh tráng qua nước chứ không ngâm lâu vì bánh sẽ tiếp tục hút ẩm mềm ra trong lúc xếp nhân.', NULL),
('imp-b88c09328fa3f33a_v4_step_6', 'imp-b88c09328fa3f33a', 6, 'finish', 'Trình bày và thưởng thức gỏi cuốn chay', 'Xếp các cuốn gỏi chay ngay ngắn ra đĩa lớn, có thể cắt đôi chéo cho đẹp mắt rồi dọn kèm chén nước chấm nước tương mè rang để thưởng thức ngay khi rau còn tươi giòn.', NULL, NULL),
('imp-66711b78b6c12643_v4_step_1', 'imp-66711b78b6c12643', 1, 'marinate', 'Dần mềm và ướp sườn cốt lết với sữa tươi mật ong', 'Thấm khô 640 g sườn cốt lết, cắt nhẹ viền mỡ gân để miếng thịt không cong khi nướng và dùng sống dao dần nhẹ hai mặt. Giã lấy nước cốt từ 15 g tỏi và 25 g hành tím khô. Trộn đều sườn với nước cốt hành tỏi, 30 ml nước mắm ngon, 20 ml dầu hào, 20 ml mật ong, 60 ml sữa tươi không đường, 10 g đường cát trắng và 1,5 g tiêu đen xay, ướp ít nhất 20 phút trong ngăn mát.', 'Chỉ dùng nước cốt hành tỏi thay vì xác băm khi ướp sẽ giúp miếng sườn nướng lên màu vàng cánh gián đẹp mắt mà không bị cháy đen.', 20),
('imp-66711b78b6c12643_v4_step_2', 'imp-66711b78b6c12643', 2, 'prep', 'Làm đồ chua củ cải cà rốt và nấu cơm tấm', 'Trộn sợi cà rốt và củ cải trắng với 2 g muối ăn trong 5 phút rồi vắt ráo, ngâm vào hỗn hợp 25 ml giấm gạo, 15 g đường cát trắng và 150 ml nước lọc ấm. Vo nhẹ 320 g gạo tấm qua 1 nước, cho vào nồi cơm điện cùng 420 ml nước lọc nấu chín tơi dẻo trong 20 phút.', NULL, 20),
('imp-66711b78b6c12643_v4_step_3', 'imp-66711b78b6c12643', 3, 'sauce', 'Nấu nước mắm kẹo và làm mỡ hành xanh thơm', 'Đun sôi nhẹ 30 ml nước mắm ngon còn lại với 20 g đường cát trắng và 80 ml nước lọc trong 3 phút cho hơi sánh rồi để nguội, thêm 10 ml giấm gạo, 10 g tỏi băm nhuyễn và 2 quả ớt hiểm băm. Đun nóng 20 ml dầu ăn rồi dội thẳng vào chén hành lá thái nhỏ trộn 1 g muối ăn để làm mỡ hành xanh mướt.', 'Nấu sôi nhẹ nước mắm đường rồi để nguội hoàn toàn trước khi cho tỏi ớt băm giúp tỏi ớt nổi đẹp và nước chấm sánh dịu đúng vị cơm tấm.', 3),
('imp-66711b78b6c12643_v4_step_4', 'imp-66711b78b6c12643', 4, 'cook', 'Nướng sườn cốt lết vàng xém thơm lừng', 'Làm nóng lò nướng hoặc nồi chiên không dầu ở 190°C. Xếp 4 miếng sườn lên vỉ, phết nhẹ phần nước sốt ướp pha 10 ml dầu ăn lên mặt thịt. Nướng 10 phút rồi lật mặt, phết thêm lớp sốt ướp và nướng tiếp 8 phút đến khi sườn xém vàng hai mặt, chín mọng nước bên trong.', 'Phết thêm sốt ướp giữa chừng khi lật mặt giúp miếng sườn bóng mọng và đậm hương mật ong mà không bị khô.', 18),
('imp-66711b78b6c12643_v4_step_5', 'imp-66711b78b6c12643', 5, 'cook', 'Chiên 4 quả trứng gà ốp la ăn kèm', 'Làm nóng 5 ml dầu ăn trên chảo chống dính với lửa nhỏ vừa, đập 4 quả trứng gà vào ốp la khoảng 2 phút cho lòng trắng đông chín trắng và lòng đỏ sánh dẻo, rắc nốt 1 g muối ăn và 0,5 g tiêu đen xay còn lại lên mặt trứng.', NULL, NULL),
('imp-66711b78b6c12643_v4_step_6', 'imp-66711b78b6c12643', 6, 'finish', 'Trình bày đĩa cơm tấm sườn nướng hoàn chỉnh', 'Xới cơm tấm nóng tơi ra 4 đĩa, rưới đều mỡ hành béo thơm lên mặt cơm và đặt miếng sườn nướng nóng hổi cùng 1 quả trứng ốp la bên cạnh. Xếp thêm đồ chua củ cải cà rốt vắt ráo rồi dọn ăn nóng kèm chén nước mắm tỏi ớt chua ngọt.', NULL, NULL),
('imp-6a3a83f38e6d3f9c_v4_step_1', 'imp-6a3a83f38e6d3f9c', 1, 'prep', 'Rang thơm gạo tẻ và gạo nếp', 'Trộn 180 g gạo tẻ với 30 g gạo nếp, vo nhẹ 2 nước rồi để thật ráo. Bắc nồi đáy dày lên bếp không dầu, cho gạo vào rang đều tay trên lửa nhỏ khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy mùi thơm nhẹ.', 'Rang gạo trước khi ninh giúp hạt gạo nở đều thành cháo sánh mượt mà vẫn giữ độ dẻo thơm.', 6),
('imp-6a3a83f38e6d3f9c_v4_step_2', 'imp-6a3a83f38e6d3f9c', 2, 'cook', 'Ninh cháo trắng sánh nhừ trên lửa nhỏ', 'Đổ 1,6 lít nước lọc sôi vào nồi gạo rang, khuấy đều một lượt rồi đậy hé nắp. Đun sôi bùng sau đó hạ lửa nhỏ ninh khoảng 22 phút, thỉnh thoảng khuấy sát đáy nồi để cháo không bị bén khét.', NULL, 22),
('imp-6a3a83f38e6d3f9c_v4_step_3', 'imp-6a3a83f38e6d3f9c', 3, 'marinate', 'Thái mỏng và ướp mềm thịt bò thăn', 'Trong lúc ninh cháo, thái 300 g thịt bò thăn thành lát thật mỏng ngang thớ. Ướp bò với 15 g gừng băm nhuyễn, 1/2 củ tỏi băm, 5 ml nước mắm ngon, 3 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn trong 12 phút để thịt thơm mềm không bị khô.', 'Thái thịt bò thật mỏng ngang thớ và trộn chút dầu ăn giúp thịt chín tái nhanh trong cháo nóng mà vẫn mềm ngọt.', NULL),
('imp-6a3a83f38e6d3f9c_v4_step_4', 'imp-6a3a83f38e6d3f9c', 4, 'cook', 'Phi vàng hành tím và sơ chế rau thơm', 'Làm nóng 10 ml dầu ăn trên chảo nhỏ với lửa vừa, cho 25 g hành tím thái lát mỏng vào phi đều tay khoảng 2 phút đến khi vàng giòn thì vớt ra giấy thấm dầu. Thái sợi chỉ 20 g gừng tươi còn lại; rửa sạch hành lá và lá tía tô rồi thái nhỏ.', NULL, NULL),
('imp-6a3a83f38e6d3f9c_v4_step_5', 'imp-6a3a83f38e6d3f9c', 5, 'cook', 'Nêm cháo và làm chín tới thịt bò trong nồi', 'Khi cháo đã nhừ sánh, nêm 15 ml nước mắm ngon còn lại, 3 g hạt nêm và 5 g muối ăn vào nồi khuấy đều. Tăng lửa vừa cho cháo sôi bùng lăn tăn, thả toàn bộ thịt bò đã ướp cùng một nửa lượng gừng thái chỉ vào khuấy nhanh 1 phút cho thịt bò vừa chín hồng đều thì tắt bếp ngay.', 'Chỉ đun thịt bò trong cháo sôi khoảng 1 phút rồi tắt bếp ngay để thịt giữ trọn độ mềm mọng, tránh đun lâu làm bò bị dai.', NULL),
('imp-6a3a83f38e6d3f9c_v4_step_6', 'imp-6a3a83f38e6d3f9c', 6, 'finish', 'Chan cháo nóng lên lá tía tô và thưởng thức', 'Lót lá tía tô và hành lá thái nhỏ dưới đáy 4 tô sứ, múc cháo bò nóng hổi chan đều lên trên. Rắc phần gừng thái chỉ còn lại, hành tím phi vàng giòn và 1 g tiêu đen xay rồi dùng nóng ngay.', NULL, NULL),
('imp-b1dcb812f8671a49_v4_step_1', 'imp-b1dcb812f8671a49', 1, 'prep', 'Sơ chế hành lá, xúc xích, ớt và đánh trứng', 'Thái lát mỏng 20 g hành tím khô; rửa sạch hành lá thái nhỏ và ớt hiểm thái lát mỏng. Thái lát mỏng đều 45 g xúc xích. Đập 3 quả trứng gà vào tô cùng 1,5 g muối ăn, đánh tan nhẹ vừa đủ cho hòa quyện.', 'Thái xúc xích thật mỏng sẽ giúp nhân bám chặt vào lớp trứng phô mai và nóng thơm nhanh hơn khi nướng trên chảo.', NULL),
('imp-b1dcb812f8671a49_v4_step_2', 'imp-b1dcb812f8671a49', 2, 'cook', 'Phi vàng giòn hành tím và áp sơ xúc xích', 'Làm nóng 15 ml dầu ăn trong chảo nhỏ trên lửa vừa, cho hành tím thái lát vào phi đều tay khoảng 2 phút đến khi vừa chuyển vàng nhạt thì vớt ra giấy thấm dầu, giữ lại phần dầu hành thơm. Đảo nhanh xúc xích trên chảo nóng 30 giây cho hơi xém thơm rồi gắp ra chén.', NULL, 2),
('imp-b1dcb812f8671a49_v4_step_3', 'imp-b1dcb812f8671a49', 3, 'cook', 'Làm nóng đế bánh tráng và phết trứng hành lá', 'Đặt chảo chống dính đáy rộng lên bếp với lửa nhỏ nhất, đặt 1 chiếc bánh tráng gạo vào làm nóng 20 giây cho hơi phẳng. Phết nhẹ 1 lớp mỏng dầu hành lên mặt bánh rồi múc 1/3 lượng trứng đánh tan cùng 1/3 hành lá thái nhỏ vào, dùng lưng muỗng dàn đều khắp mặt bánh.', 'Luôn nướng bánh tráng ở mức lửa nhỏ nhất để phần trứng và phô mai kịp chín tan trong khi đế bánh giòn vàng mà không bị khét.', NULL),
('imp-b1dcb812f8671a49_v4_step_4', 'imp-b1dcb812f8671a49', 4, 'cook', 'Phủ phô mai Mozzarella, xúc xích và nướng giòn đế', 'Khi mặt trứng hơi se lại, rắc đều 25 g phô mai Mozzarella bào sợi, 1/3 lượng xúc xích và vài lát ớt hiểm lên trên. Tiếp tục nướng liu riu khoảng 2 phút đến khi phô mai tan chảy hoàn toàn, mép bánh tráng giòn cứng và hơi cong nhẹ.', 'Có thể đậy hé nắp chảo khoảng 30 giây cuối nếu muốn phô mai tan chảy nhanh và kéo sợi mượt hơn.', 2),
('imp-b1dcb812f8671a49_v4_step_5', 'imp-b1dcb812f8671a49', 5, 'cook', 'Lặp lại thao tác với 2 chiếc bánh còn lại', 'Gắp chiếc bánh đầu tiên ra thớt hoặc đĩa, tiếp tục nướng lần lượt 2 chiếc bánh tráng gạo còn lại với phần trứng, hành lá, phô mai Mozzarella, xúc xích và ớt hiểm theo đúng trình tự trên.', NULL, NULL),
('imp-b1dcb812f8671a49_v4_step_6', 'imp-b1dcb812f8671a49', 6, 'finish', 'Rưới tương ớt, Mayonnaise, rắc hành phi và gấp bánh', 'Rưới đều tương ớt và sốt Mayonnaise theo đường ziczac lên mặt cả 3 chiếc bánh nóng, rắc thêm hành tím phi vàng giòn lên trên. Gấp đôi bánh hoặc cắt miếng tam giác vừa ăn và thưởng thức ngay lúc giòn rụm.', NULL, NULL),
('imp-8f24a253602fc9be_v4_step_1', 'imp-8f24a253602fc9be', 1, 'prep', 'Làm sạch khử tanh và ướp nhẹ cá diêu hồng', 'Đánh sạch vảy, bỏ mang, cạo màng đen trong bụng 1000 g cá diêu hồng tươi rồi chà xát với 3 g muối hạt trong 2 phút, xả thật sạch và thấm khô. Cắt cá thành khúc dày 2,5 cm, ướp với 10 ml nước mắm ngon, 3 g hạt nêm và một nửa gừng thái sợi trong 15 phút để thịt cá săn chắc đậm vị.', 'Cạo sạch lớp màng đen trong khoang bụng cá diêu hồng là bước quan trọng nhất để loại bỏ hoàn toàn mùi tanh bùn.', 15),
('imp-8f24a253602fc9be_v4_step_2', 'imp-8f24a253602fc9be', 2, 'prep', 'Xử lý dọc mùng, dứa và rau nhúng lẩu', 'Tước bỏ vỏ xơ 150 g dọc mùng, thái lát xéo dày 0,5 cm, bóp với 2 g muối hạt rồi xả nhiều lần nước sạch và vắt ráo để không gây ngứa. Thái lát 1/2 quả dứa chín, bổ múi cau 2 quả cà chua và băm nhỏ 1 quả. Rửa sạch nấm đùi gà thái lát, rau muống cắt khúc, ngò gai, rau ngổ, hành lá; băm nhỏ hành tím, tỏi, 1 cây sả, đập dập 2 cây sả và vắt nước cốt 2 quả chanh tươi.', NULL, NULL),
('imp-8f24a253602fc9be_v4_step_3', 'imp-8f24a253602fc9be', 3, 'cook', 'Phi thơm sả gừng và xào nền cà chua dứa', 'Làm nóng nồi trên lửa vừa với 20 ml dầu ăn, cho hành tím, tỏi, sả băm, sả cây đập dập và gừng thái sợi còn lại vào phi thơm 1 phút. Trút cà chua băm và một nửa lượng dứa thái lát vào xào 3 phút cho cà chua mềm nhuyễn ra màu, thêm 15 ml sa tế ớt đảo đều.', NULL, 4),
('imp-8f24a253602fc9be_v4_step_4', 'imp-8f24a253602fc9be', 4, 'cook', 'Nấu nước lẩu chua ngọt và làm chín cá diêu hồng', 'Đổ 2000 ml nước lọc vào nồi, đun sôi bùng trên lửa lớn rồi hớt sạch bọt. Thả phần dứa còn lại, cà chua bổ múi cau và 1 quả ớt tươi đập dập vào nấu 5 phút cho tiết vị ngọt chua tự nhiên, nêm 25 ml nước mắm ngon, 7 g hạt nêm, 5 g muối hạt và 20 g đường cát trắng. Nhẹ nhàng thả cá diêu hồng vào nấu sôi lăn tăn 6 phút đến khi mắt cá đục trắng và thịt cá chín chắc hoàn toàn.', 'Giữ lửa vừa sôi lăn tăn khi nấu cá diêu hồng và không đảo mạnh tay sẽ giữ nguyên từng khúc cá đẹp mắt, không bị vỡ nát.', 11),
('imp-8f24a253602fc9be_v4_step_5', 'imp-8f24a253602fc9be', 5, 'sauce', 'Pha chén mắm gừng chấm cá và rưới nước cốt chanh', 'Hạ nhỏ lửa tối đa hoặc tắt bếp nồi lẩu rồi rưới từ từ nước cốt chanh tươi vào khuấy nhẹ, nếm lại vị chua ngọt thanh dịu. Pha 10 ml nước mắm ngon còn lại cùng 10 g gừng băm nhuyễn và 1 quả ớt tươi thái lát làm chén nước chấm thịt cá.', 'Chỉ rưới nước cốt chanh sau khi cá đã chín và hạ nhỏ lửa để giữ hương thơm tinh dầu chanh tươi mà không bị đắng.', NULL),
('imp-8f24a253602fc9be_v4_step_6', 'imp-8f24a253602fc9be', 6, 'finish', 'Chuyển nồi lẩu ra bàn và nhúng rau xanh ăn với bún', 'Chuyển nồi lẩu sang bếp giữa bàn giữ sôi nhẹ, thả nấm đùi gà, hành lá, ngò gai và rau ngổ vào. Khi ăn, nhúng dọc mùng và rau muống vừa chín tới giữ độ giòn xanh, gắp thưởng thức nóng cùng thịt cá diêu hồng chấm mắm gừng và bún tươi.', NULL, NULL),
('imp-cd86ce166f002f60_v4_step_1', 'imp-cd86ce166f002f60', 1, 'prep', 'Rửa sạch tàu xì và thấm khô sườn non', 'Rửa nhanh 20 g đậu tương đen lên men dưới vòi nước sạch để loại bỏ bớt muối mặn bên ngoài, vớt ra để ráo rồi băm thô. Sườn non rửa sạch, chặt miếng vừa ăn 3 cm rồi dùng khăn giấy thấm thật khô từng miếng; băm nhỏ tỏi, gừng tươi và thái nhỏ hành lá.', 'Đậu tương đen lên men (tàu xì) có lớp muối bảo quản khá gắt nên cần xả nhanh qua nước sạch rồi băm thô để dậy mùi đều.', NULL),
('imp-cd86ce166f002f60_v4_step_2', 'imp-cd86ce166f002f60', 2, 'cook', 'Áp chảo xém vàng hai mặt sườn', 'Đun nóng 25 ml dầu ăn trong nồi đáy dày trên lửa lớn, xếp sườn non vào áp chảo 5 phút, lật đều các mặt cho thịt săn lại và xém vàng cạnh để giữ trọn vị ngọt bên trong rồi gắp sườn ra đĩa riêng.', 'Áp chảo khô mặt sườn trước giúp món hầm dậy mùi thơm và nước sốt không bị đục.', 5),
('imp-cd86ce166f002f60_v4_step_3', 'imp-cd86ce166f002f60', 3, 'cook', 'Phi thơm đậu đen lên men cùng gừng tỏi', 'Hạ xuống lửa vừa, tận dụng phần dầu nóng trong nồi cho tỏi băm, gừng băm, đậu tương đen lên men băm thô và một nửa phần hành lá vào đảo đều 1 phút cho dậy hương thơm đặc trưng.', NULL, 1),
('imp-cd86ce166f002f60_v4_step_4', 'imp-cd86ce166f002f60', 4, 'sauce', 'Hòa xì dầu và áo sốt lên sườn', 'Khuấy đều 15 ml xì dầu nhạt, 30 ml xì dầu đặc với 5 g đường cát trắng trong chén nhỏ rồi đổ vào nồi gia vị, đảo nhanh 15 giây cho quyện mùi. Trút đĩa sườn đã áp chảo trở lại nồi, xóc đều cho sườn áo lớp sốt đen bóng.', NULL, NULL),
('imp-cd86ce166f002f60_v4_step_5', 'imp-cd86ce166f002f60', 5, 'cook', 'Hầm lửa nhỏ cho sườn mềm tách xương', 'Rưới 30 ml rượu Thiệu Hưng quanh thành nồi rồi đổ 300 ml nước lọc xâm xấp mặt sườn. Đun sôi bùng lên thì hạ lửa nhỏ liu riu, đậy nắp kín và hầm 50 phút; thỉnh thoảng mở nắp đảo nhẹ để sườn ngấm đều và không bén đáy.', 'Nếu nước cạn trước khi sườn mềm, hãy châm thêm từng chút nước sôi để giữ nhiệt độ nồi ổn định.', 50),
('imp-cd86ce166f002f60_v4_step_6', 'imp-cd86ce166f002f60', 6, 'finish', 'Cô sánh sốt và hoàn thiện món hầm', 'Khi sườn đã mềm tơi dễ tách xương, mở nắp tăng lên lửa vừa đun thêm 5 phút đến khi nước sốt sánh lại ôm trọn từng khúc sườn. Nếm thử vị mặn ngọt, chỉ bổ sung muối ăn nếu thấy nhạt rồi tắt bếp, rắc phần hành lá còn lại lên trên và dọn nóng.', NULL, 5),
('imp-3e8e08fb584de7f3_v4_step_1', 'imp-3e8e08fb584de7f3', 1, 'prep', 'Chần thịt bò khử mùi với gừng hành rượu', 'Cho 900 g thịt bò cắt khối 5 cm vào nồi nước lạnh ngập mặt cùng 20 g gừng thái lát, 2 cây hành lá cắt khúc và 15 ml rượu Thiệu Hưng. Đun sôi trên lửa lớn rồi hạ lửa vừa chần 8 phút và hớt sạch bọt nổi, sau đó vớt thịt ra rửa lại nước mát, thấm thật khô (bỏ phần nước chần và gừng hành).', 'Bắt đầu chần từ nước lạnh giúp máu dư và tạp chất tiết ra triệt để, nước hầm sau cùng sẽ trong và thơm sạch.', 8),
('imp-3e8e08fb584de7f3_v4_step_2', 'imp-3e8e08fb584de7f3', 2, 'cook', 'Áp chảo vàng cạnh thịt bò', 'Đun nóng 15 ml dầu ăn trong nồi gang hoặc nồi đáy dày trên lửa vừa lớn, thả thịt bò đã thấm khô vào áp chảo 3 phút, trở đều các mặt đến khi thịt xém vàng nâu nhẹ.', NULL, 3),
('imp-3e8e08fb584de7f3_v4_step_3', 'imp-3e8e08fb584de7f3', 3, 'cook', 'Xào thơm hành tây, tỏi, gừng và gia vị tương', 'Hạ xuống lửa vừa, cho hành tây thái lát vào đảo 3 phút đến khi mềm thơm, tiếp tục thêm tỏi đập dập và 40 g gừng thái lát còn lại đảo 30 giây. Cho tương cà, tương ớt đậu bản Tứ Xuyên, 35 ml xì dầu nhạt, 15 ml xì dầu đặc và 15 g đường phèn vào đảo đều 2 phút cho thịt áo màu nâu đỏ.', NULL, 5),
('imp-3e8e08fb584de7f3_v4_step_4', 'imp-3e8e08fb584de7f3', 4, 'cook', 'Hầm lửa nhỏ cho thịt bò mềm rục', 'Rót 500 ml nước dùng bò, 500 ml nước lọc cùng 15 ml rượu Thiệu Hưng còn lại vào nồi cho ngập thịt, thả 3 g hoa hồi khô và 1 g lá nguyệt quế khô vào. Đun sôi lên rồi hạ lửa thật nhỏ, đậy nắp hầm liu riu 100 phút đến khi xiên đũa qua miếng bò dễ dàng.', 'Cắt thịt khối lớn 5 cm giúp từng miếng bò giữ nguyên thớ mọng nước dù hầm gần 2 giờ.', 100),
('imp-3e8e08fb584de7f3_v4_step_5', 'imp-3e8e08fb584de7f3', 5, 'cook', 'Thả cà rốt nấu mềm ngọt tự nhiên', 'Cho 2,5 củ cà rốt cắt khúc vào nồi thịt bò, đậy nắp hầm tiếp 20 phút trên lửa nhỏ cho cà rốt chín mềm ngọt mà vẫn giữ nguyên khối đẹp mắt.', 'Cho cà rốt vào cuối giai đoạn hầm giúp rau củ không bị nát nhừ và nước hầm vẫn giữ độ sánh trong.', 20),
('imp-3e8e08fb584de7f3_v4_step_6', 'imp-3e8e08fb584de7f3', 6, 'finish', 'Làm sánh sốt, nêm nếm và hoàn thiện', 'Hòa 8 g bột bắp với 2 muỗng canh nước lạnh (nếu muốn nước sốt sánh đặc), rót từ từ vào nồi đang sôi nhẹ và khuấy đều 1 phút. Nêm thử, chỉ bổ sung 2 g muối ăn nếu thấy nhạt rồi vớt bỏ hoa hồi và lá nguyệt quế, múc ra tô và rắc phần hành lá còn lại thái nhỏ lên trên.', NULL, NULL),
('imp-abcc9b72400680cf_v4_step_1', 'imp-abcc9b72400680cf', 1, 'prep', 'Thái hành lá và đánh mịn hỗn hợp trứng', 'Hành lá rửa sạch, thấm khô rồi thái thật nhỏ. Đập 5 quả trứng gà vào tô lớn, thêm 4 g muối ăn, 1 g tiêu trắng xay và 2 g đường cát trắng. Hòa 3 g bột bắp với 10 ml rượu Thiệu Hưng cho tan mịn rồi đổ vào tô cùng hành lá, dùng đũa đánh đều tay đến khi lòng trắng và lòng đỏ quyện hoàn toàn.', 'Sau khi nêm muối vào trứng nên đem tráng ngay, tránh để lâu khiến trứng bị tách nước và kém xốp mịn.', NULL),
('imp-abcc9b72400680cf_v4_step_2', 'imp-abcc9b72400680cf', 2, 'cook', 'Làm nóng chảo và tráng lớp trứng mỏng', 'Đặt chảo chống dính lên bếp lửa vừa, tráng một lớp mỏng dầu ăn (khoảng 1/3 lượng dầu) khắp lòng chảo. Múc 1/3 lượng hỗn hợp trứng đổ vào chảo, nghiêng nhẹ chảo xoay tròn để trứng trải thành lớp mỏng đều.', 'Sử dụng chảo chống dính phẳng đáy giúp lớp trứng mỏng đều và không bị rách mép khi cuộn.', NULL),
('imp-abcc9b72400680cf_v4_step_3', 'imp-abcc9b72400680cf', 3, 'cook', 'Chiên chín tới và cuộn trứng khi còn nóng', 'Hạ xuống lửa vừa nhỏ, chiên khoảng 2 phút đến khi mặt dưới chín vàng nhạt và mặt trên vừa se lại nhưng vẫn còn hơi ẩm bóng. Dùng xẻng mềm hoặc đũa cuộn tròn tấm trứng từ mép ngoài vào trong ngay trên chảo, nhẹ nhàng gắp cuộn trứng ra đĩa.', 'Không chiên khô quá vì mặt trứng hơi ẩm sẽ giúp các lớp cuộn dính chặt vào nhau và không bị nứt gãy.', 2),
('imp-abcc9b72400680cf_v4_step_4', 'imp-abcc9b72400680cf', 4, 'cook', 'Tráng và cuộn nốt hai mẻ trứng còn lại', 'Dùng giấy thấm dầu hoặc cọ tráng thêm một lớp mỏng dầu ăn lên chảo giữa mỗi mẻ, tiếp tục đổ 2 phần trứng còn lại tráng và cuộn tương tự cho đến khi hết hỗn hợp.', NULL, 4),
('imp-abcc9b72400680cf_v4_step_5', 'imp-abcc9b72400680cf', 5, 'prep', 'Để định hình và cắt khoanh vừa ăn', 'Để các cuộn trứng nghỉ trên thớt sạch khoảng 2 phút cho bớt nóng và định hình chắc tay, rồi dùng dao sắc cắt thành từng khúc dài khoảng 3–4 cm thật gọn đẹp.', NULL, 2),
('imp-abcc9b72400680cf_v4_step_6', 'imp-abcc9b72400680cf', 6, 'finish', 'Rưới xì dầu nhạt và dọn nóng', 'Xếp các khúc trứng cuộn hành lá ra đĩa phẳng, rưới đều 15 ml xì dầu nhạt lên bề mặt (hoặc chừa lại ra chén nhỏ làm nước chấm) và thưởng thức ngay khi trứng còn nóng mềm.', NULL, NULL),
('imp-26359a897d4be366_v4_step_1', 'imp-26359a897d4be366', 1, 'marinate', 'Làm sạch và ướp khử tanh tôm tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch nhẹ lưng rút sạch chỉ đen rồi rửa nước lạnh và thấm ráo. Ướp tôm trong tô với 15 ml rượu Thiệu Hưng và 1 g muối ăn trong 10 phút cho thịt tôm săn và thơm ngọt.', 'Ướp chút rượu Thiệu Hưng giúp khử hoàn toàn mùi tanh hải sản mà vẫn giữ vị ngọt tự nhiên của tôm.', 10),
('imp-26359a897d4be366_v4_step_2', 'imp-26359a897d4be366', 2, 'prep', 'Thái lát nấm đùi gà và rau gia vị', 'Dùng khăn ẩm lau sạch 200 g nấm đùi gà, cắt bỏ phần gốc già rồi thái lát dày 0,5 cm. Gừng tươi thái lát mỏng, tỏi thái lát, hành lá tách riêng phần đầu trắng thái khúc và phần lá xanh thái nhỏ.', NULL, NULL),
('imp-26359a897d4be366_v4_step_3', 'imp-26359a897d4be366', 3, 'cook', 'Phi thơm gừng tỏi và đun nước dùng gà', 'Đun nóng 15 ml dầu ăn trong nồi trên lửa vừa, thả gừng thái lát, tỏi thái lát và đầu hành trắng vào phi thơm nhanh 20 giây đến khi dậy mùi (không để tỏi xém cháy). Đổ 1200 ml nước dùng gà vào nồi và đun lửa lớn đến khi sôi.', NULL, NULL),
('imp-26359a897d4be366_v4_step_4', 'imp-26359a897d4be366', 4, 'cook', 'Nấu chín nấm đùi gà và nêm vị thanh', 'Khi nước dùng sôi, thả nấm đùi gà thái lát vào nấu 3 phút trên lửa vừa để nấm tiết vị ngọt. Nêm thêm 15 ml xì dầu nhạt và 4 g muối ăn, khuấy đều và hớt bọt nếu có.', 'Cắt nấm đùi gà độ dày 0,5 cm giúp nấm chín nhanh trong 3 phút mà vẫn giữ được độ giòn sần sật.', 3),
('imp-26359a897d4be366_v4_step_5', 'imp-26359a897d4be366', 5, 'cook', 'Thả tôm nấu chín hồng vừa tới', 'Thả toàn bộ tôm đã ướp vào nồi súp đang sôi nhẹ, nấu thêm đúng 3 phút đến khi thân tôm uốn cong, chuyển màu hồng đục đều và chín hoàn toàn bên trong thì tắt bếp ngay.', 'Không nấu tôm quá lâu sau khi thân tôm đã chuyển hồng săn chắc vì tôm sẽ bị bở hoặc dai khô.', 3),
('imp-26359a897d4be366_v4_step_6', 'imp-26359a897d4be366', 6, 'finish', 'Rắc tiêu trắng, rưới dầu mè và dùng nóng', 'Khuấy nhẹ 1 g tiêu trắng xay vào nồi súp, múc ra 4 tô sâu lòng, rưới đều 5 ml dầu mè thơm và rắc phần lá hành xanh thái nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-00e0b1417e11b291_v4_step_1', 'imp-00e0b1417e11b291', 1, 'prep', 'Thấm khô và lăn bột bắp cho đậu phụ', 'Dùng khăn giấy sạch thấm thật khô bề mặt 3,5 bìa đậu phụ cứng rồi cắt thành khối vuông 2,5 cm. Cho 38 g bột bắp ra đĩa rộng, lăn nhẹ từng miếng đậu cho bột bám một lớp áo mỏng đều xung quanh; hòa tan 7 g bột bắp còn lại với 120 ml nước lọc ấm trong chén nhỏ để sẵn.', 'Thấm thật ráo nước và chỉ áo lớp bột mỏng giúp đậu chiên giòn lâu mà không bị bết bột.', NULL),
('imp-00e0b1417e11b291_v4_step_2', 'imp-00e0b1417e11b291', 2, 'cook', 'Chiên vàng giòn các mặt đậu phụ', 'Đun nóng 75 ml dầu ăn trong chảo chống dính hoặc chảo gang trên lửa vừa. Xếp từng miếng đậu phụ cách nhau vào chảo, chiên 8 phút kết hợp lật đều đến khi tất cả các mặt vàng giòn thì vớt ra đĩa riêng.', 'Xếp các khối đậu có khoảng hở đều nhau để hơi nóng lưu thông, tránh các mặt đậu dính chặt vào nhau khi chiên.', 8),
('imp-00e0b1417e11b291_v4_step_3', 'imp-00e0b1417e11b291', 3, 'cook', 'Phi thơm gừng tỏi và xào mềm hành tây', 'Chắt bớt dầu thừa trong chảo chỉ chừa lại khoảng 1 muỗng canh. Băm nhỏ tỏi khô rồi cho cùng gừng tươi nạo nhuyễn vào phi thơm 1 phút trên lửa vừa, sau đó thả hành tây thái lát vào xào đều 3 phút đến khi hành chuyển trong mềm mà vẫn giữ độ giòn ngọt tự nhiên.', NULL, 4),
('imp-00e0b1417e11b291_v4_step_4', 'imp-00e0b1417e11b291', 4, 'sauce', 'Nấu sôi hỗn hợp gia vị sốt', 'Rót 20 ml rượu Thiệu Hưng quanh thành chảo cho dậy mùi thơm, tiếp tục thêm 30 ml xì dầu nhạt, 10 ml xì dầu đặc, 16 g đường nâu và 5 ml dầu mè thơm trực tiếp vào chảo hành tây, đảo đều và đun sôi lăn tăn 2 phút cho đường tan hết.', NULL, 2),
('imp-00e0b1417e11b291_v4_step_5', 'imp-00e0b1417e11b291', 5, 'cook', 'Áo sốt sánh mịn quanh đậu phụ', 'Khuấy đều lại chén nước bột bắp rồi rót vào chảo cùng toàn bộ đậu phụ đã chiên giòn. Dùng xẻng nhẹ tay đảo đều 1 phút trên lửa vừa cho nước sốt sánh lại, bám bóng mượt quanh từng khối đậu mà không làm vỡ miếng đậu.', 'Đảo hất nhẹ từ đáy chảo lên thay vì dầm trực tiếp vào miếng đậu phụ.', 1),
('imp-00e0b1417e11b291_v4_step_6', 'imp-00e0b1417e11b291', 6, 'finish', 'Hoàn thiện với hành lá và mè rang', 'Rắc hành lá thái nhỏ vào chảo đảo thêm vài giây cho dậy hương rồi tắt bếp. Dọn đậu phụ xào hành tây nóng hổi ra đĩa, rắc thêm hạt mè trắng rang lên mặt và dùng kèm cơm trắng.', NULL, NULL),
('imp-45274582db71eb9f_v4_step_1', 'imp-45274582db71eb9f', 1, 'prep', 'Sơ chế tôm, rau củ và pha chén sốt', 'Tôm tươi bóc vỏ, rút chỉ lưng, rửa sạch rồi thấm thật khô; bắp cải thái sợi mỏng, giá đỗ rửa ráo, hành lá cắt khúc 4–5 cm và tỏi băm nhuyễn. Trong chén nhỏ, khuấy tan 22 ml dầu hào, 22 ml xì dầu, 15 g đường cát trắng, 5 ml dầu mè thơm, 2 g muối ăn cùng 70 ml nước lọc.', 'Pha sẵn chén sốt trước khi bật bếp giúp quá trình xào lửa lớn diễn ra liên tục mà không bị cháy chảo.', NULL),
('imp-45274582db71eb9f_v4_step_2', 'imp-45274582db71eb9f', 2, 'cook', 'Trụng tơi sợi mì trứng chống dính', 'Đun sôi nồi nước lớn, thả 300 g mì trứng vào trụng 2 phút vừa chín mềm. Vớt mì ra xả ngay qua nước lạnh cho sợi săn dai, để thật ráo nước rồi xóc đều với 5 ml dầu ăn để sợi mì tơi bóng không dính nhau.', 'Xả nước lạnh ngay sau khi trụng giúp sợi mì săn lại, không bị bở nát khi đảo trên chảo lửa lớn.', 2),
('imp-45274582db71eb9f_v4_step_3', 'imp-45274582db71eb9f', 3, 'cook', 'Xào nhanh tôm tươi trên lửa lớn', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, cho tỏi băm vào phi thơm 15 giây rồi thả tôm vào đảo nhanh tay 2 phút đến khi tôm vừa chuyển hồng đục thì trút ra đĩa riêng.', 'Xào tôm vừa chín tới rồi vớt ra giúp tôm giữ độ giòn ngọt và không bị dai khi đảo chung với mì ở bước cuối.', 2),
('imp-45274582db71eb9f_v4_step_4', 'imp-45274582db71eb9f', 4, 'cook', 'Xào bắp cải và đảo mì thấm sốt', 'Thêm 10 ml dầu ăn vào chảo nóng, thả bắp cải thái sợi vào xào 2 phút cho vừa mềm giòn. Rưới 10 ml dầu ăn còn lại quanh chảo rồi trút mì trứng vào cùng toàn bộ chén sốt đã pha, đảo hất đều tay 1 phút trên lửa lớn nhất cho từng sợi mì thấm đều sốt bóng đẹp.', NULL, 3),
('imp-45274582db71eb9f_v4_step_5', 'imp-45274582db71eb9f', 5, 'cook', 'Kết hợp tôm và giá đỗ giòn ngọt', 'Đổ đĩa tôm đã xào trở lại chảo cùng 150 g giá đỗ tươi, đảo đều tay 1 phút đến khi giá vừa chín tới và tôm chín hoàn toàn.', NULL, 1),
('imp-45274582db71eb9f_v4_step_6', 'imp-45274582db71eb9f', 6, 'finish', 'Thêm hành lá và dọn mì xào nóng', 'Thả hành lá cắt khúc vào chảo, đảo thêm 15 giây giữ màu xanh tươi rồi tắt bếp ngay. Gắp mì xào tôm ra đĩa lớn và thưởng thức nóng.', NULL, NULL),
('imp-3d2e5735cbfe9654_v4_step_1', 'imp-3d2e5735cbfe9654', 1, 'prep', 'Rang và giã bột muối tiêu Tứ Xuyên', 'Cho 6 g hạt tiêu Tứ Xuyên vào chảo khô rang trên lửa vừa nhỏ 3 phút đến khi dậy mùi thơm nồng (tránh để cháy đắng), trút ra cối để nguội hoàn toàn rồi giã thành bột mịn. Tiếp tục cho 6 g muối biển vào chảo khô rang 2 phút đến khi hạt muối khô ráo hơi ngả vàng, trộn đều với bột tiêu để được hỗn hợp bột muối tiêu.', 'Rang riêng tiêu và muối trên chảo khô giúp bột muối tiêu thơm nồng và không bị vón ẩm.', 5),
('imp-3d2e5735cbfe9654_v4_step_2', 'imp-3d2e5735cbfe9654', 2, 'marinate', 'Làm sạch, ướp gừng và áo bột bắp cho tôm', 'Tôm cắt râu, giữ nguyên vỏ, rút sạch chỉ lưng rồi thấm thật khô. Ướp tôm với 3 g muối biển và 15 g gừng tươi đập dập trong 15 phút cho ngấm vị, sau đó gạt bỏ hết xác gừng và thấm lại nếu tôm còn ẩm. Lăn từng con tôm qua 25 g bột bắp, giũ thật kỹ cho rơi hết bột thừa để chỉ còn một lớp áo mỏng.', NULL, 15),
('imp-3d2e5735cbfe9654_v4_step_3', 'imp-3d2e5735cbfe9654', 3, 'cook', 'Chiên giòn vàng từng mẻ tôm nguyên vỏ', 'Đun nóng 150 ml dầu ăn trong chảo sâu lòng trên lửa vừa lớn đến khi mặt dầu gợn sóng nóng già (khoảng 180°C). Chia tôm thành 2–3 mẻ nhỏ chiên mỗi mặt khoảng 1–1,5 phút cho đến khi vỏ tôm phồng giòn rụm, chuyển màu đỏ cam đẹp mắt và thịt tôm bên trong săn chắc, chuyển trắng đục hoàn toàn, sau đó vớt ra giấy thấm dầu và rắc ngay một chút bột muối tiêu lên khi tôm còn nóng.', 'Chiên từng mẻ nhỏ giúp nhiệt độ dầu không bị tụt, nhờ đó vỏ tôm giòn tan mà không hút dầu.', 3),
('imp-3d2e5735cbfe9654_v4_step_4', 'imp-3d2e5735cbfe9654', 4, 'cook', 'Phi vàng giòn tỏi băm với ít dầu', 'Chắt bớt dầu chiên ra ngoài, chỉ để lại khoảng 1 muỗng canh dầu trong chảo. Hạ lửa vừa, cho tỏi băm vào phi đều tay 1–2 phút đến khi vừa ngả vàng thơm thì nhanh tay vớt riêng tỏi phi ra giấy thấm dầu để không bị cháy đắng.', 'Nhiệt dư sau khi vớt vẫn làm tỏi tiếp tục sẫm màu, nên hãy vớt ngay khi tỏi vừa chuyển vàng nhạt.', 2),
('imp-3d2e5735cbfe9654_v4_step_5', 'imp-3d2e5735cbfe9654', 5, 'cook', 'Xóc nhanh tôm với tỏi phi, ớt và muối tiêu', 'Cho ớt hiểm thái lát và hành lá cắt khúc vào chảo đang nóng đảo nhanh 15 giây cho dậy hương. Tắt bếp, trút tỏi phi vàng và toàn bộ tôm chiên giòn vào chảo cùng phần bột muối tiêu vừa miệng (khoảng 2/3 lượng đã làm), xóc nhanh tay 10 giây cho gia vị bám đều khô ráo.', NULL, NULL),
('imp-3d2e5735cbfe9654_v4_step_6', 'imp-3d2e5735cbfe9654', 6, 'finish', 'Bày đĩa và thưởng thức nóng giòn', 'Trút tôm rang muối tiêu ra đĩa rộng, rắc thêm chút bột muối tiêu còn lại lên mặt để tăng hương vị và dùng nóng ngay khi vỏ tôm còn giòn rụm.', NULL, NULL),
('imp-73568e9a99d0ccdf_v4_step_1', 'imp-73568e9a99d0ccdf', 1, 'prep', 'Sơ chế hành tây và đánh bông trứng gà', 'Hành tây lột vỏ, thái sợi thô 0,5 cm rồi tách rời các múi để hành chín đồng đều; hành lá rửa sạch thái nhỏ. Đập 4 quả trứng gà vào tô lớn, thêm 15 ml sữa tươi không đường, 7 g sốt Mayonnaise và 1 g muối ăn rồi đánh tan đều tay đến khi hỗn hợp mịn mượt đồng nhất.', 'Thêm một chút sữa tươi và mayonnaise vào trứng trước khi đánh giúp thành phẩm cực kỳ mềm ẩm, xốp mịn.', NULL),
('imp-73568e9a99d0ccdf_v4_step_2', 'imp-73568e9a99d0ccdf', 2, 'cook', 'Xào bông mềm trứng gà trước rồi vớt riêng', 'Đặt chảo chống dính lên bếp lửa vừa lớn với 20 ml dầu ăn, khi dầu nóng già thì đổ hỗn hợp trứng vào. Chờ 10 giây cho rìa trứng bắt đầu đông lại rồi dùng xẻng nhẹ nhàng đẩy thành từng mảng lớn còn hơi ẩm bóng (khoảng 2 phút), lập tức trút ra đĩa riêng.', 'Xào trứng vừa chín tới 80% rồi trút ra ngay giúp trứng giữ độ ẩm mềm, không bị khô xác khi đảo lại cùng hành.', 2),
('imp-73568e9a99d0ccdf_v4_step_3', 'imp-73568e9a99d0ccdf', 3, 'cook', 'Xào chín trong và làm mềm ngọt hành tây', 'Dùng chính chảo đó, thêm 15 ml dầu ăn còn lại rồi cho hành tây vào xào đều tay 2 phút trên lửa lớn. Khi hành bắt đầu chuyển trong, rưới 30 ml nước lọc vào đảo thêm 1 phút để hành chín mềm ngọt mà không bị cháy xém.', 'Thêm 2 muỗng canh nước lọc giúp hơi nước làm hành tây chín mọng và giữ độ ẩm mượt cho toàn bộ đĩa trứng xào.', 3),
('imp-73568e9a99d0ccdf_v4_step_4', 'imp-73568e9a99d0ccdf', 4, 'sauce', 'Nêm gia vị vào phần hành tây', 'Rắc 2 g muối ăn còn lại, 3 g hạt nêm gà và 1 g tiêu đen xay vào chảo hành tây, đảo đều 20 giây cho gia vị tan đều và thấm vào hành trước khi cho trứng vào.', NULL, NULL),
('imp-73568e9a99d0ccdf_v4_step_5', 'imp-73568e9a99d0ccdf', 5, 'cook', 'Trộn nhẹ trứng gà trở lại chảo hành', 'Trút đĩa trứng gà đã xào vào chảo hành tây, dùng xẻng đảo nhẹ tay 1 phút trên lửa vừa để các mảng trứng nóng lại và quyện đều gia vị với hành mà không bị nát vụn.', NULL, 1),
('imp-73568e9a99d0ccdf_v4_step_6', 'imp-73568e9a99d0ccdf', 6, 'finish', 'Rắc hành lá và dọn nóng với cơm', 'Rắc phần hành lá thái nhỏ vào chảo, đảo thêm 15 giây cho dậy hương rồi tắt bếp ngay. Múc trứng xào hành tây ra đĩa và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-a17f5a86a1bc891c_v4_step_1', 'imp-a17f5a86a1bc891c', 1, 'cook', 'Luộc liu riu tảng ba chỉ với thảo mộc', 'Cho 450 g thịt ba chỉ nguyên tảng vào nồi cùng 1400 ml nước lạnh ngập mặt, thêm 25 g gừng thái lát, hoa hồi khô, 30 ml rượu Thiệu Hưng, 2 cây hành lá và 2 g tiêu Tứ Xuyên nguyên hạt. Đun sôi trên lửa lớn rồi lập tức hạ lửa nhỏ, đậy nắp luộc liu riu 35 phút cho thịt chín mềm mọng (xiên đũa qua dễ dàng không còn nước hồng).', 'Luộc thịt từ nước lạnh trên lửa nhỏ liu riu giúp thớ thịt chín đều, giữ trọn vị ngọt mà không bị co cứng.', 35),
('imp-a17f5a86a1bc891c_v4_step_2', 'imp-a17f5a86a1bc891c', 2, 'prep', 'Ủ nguội tảng thịt và giữ nước luộc', 'Vớt tảng thịt ba chỉ ra đĩa sâu, úp một chiếc đĩa hoặc nắp vung kín lên trên 15 phút để thịt nguội hoàn toàn mà mặt bì không bị khô thâm. Múc giữ lại khoảng 80 ml nước luộc thịt trong.', 'Thịt ba chỉ nguội hẳn mới dễ thái lát thật mỏng và giữ nguyên khoanh thịt đẹp mắt.', 15),
('imp-a17f5a86a1bc891c_v4_step_3', 'imp-a17f5a86a1bc891c', 3, 'sauce', 'Rưới dầu nóng lên gia vị tạo dầu ớt tỏi', 'Băm thật nhuyễn tỏi khô, 15 g gừng tươi còn lại và phần đầu trắng của 1 cây hành lá, cho vào tô chịu nhiệt cùng 10 g ớt bột khô và 2 g bột tiêu Tứ Xuyên. Đun nóng 45 ml dầu ăn đến khi sủi tăm nhẹ (khoảng 110°C) rồi rưới từ từ lên tô gia vị, khuấy nhanh cho dậy mùi thơm và lên màu đỏ đẹp.', 'Không đun dầu bốc khói quá nóng vì sẽ làm ớt bột và tỏi bị cháy đắng.', NULL),
('imp-a17f5a86a1bc891c_v4_step_4', 'imp-a17f5a86a1bc891c', 4, 'sauce', 'Hoàn thiện nước sốt xì dầu giấm đen', 'Thêm 50 ml xì dầu nhạt, 15 ml giấm đen Trấn Giang, 12 g đường cát trắng, 5 ml dầu mè thơm và 15 g sốt tương mè vào tô dầu ớt tỏi, khuấy đều đến khi đường và tương mè tan mịn rồi nếm lại cho vừa vị chua cay mặn ngọt cân bằng.', NULL, NULL),
('imp-a17f5a86a1bc891c_v4_step_5', 'imp-a17f5a86a1bc891c', 5, 'prep', 'Thái lát mỏng ba chỉ và lót dưa leo', 'Thái sợi mỏng 3/4 quả dưa leo xếp đều lót kín đáy đĩa lớn. Dùng dao sắc thái tảng thịt ba chỉ đã nguội hẳn thành những lát thật mỏng đều nhau và xếp ngay ngắn lên lớp dưa leo.', NULL, NULL),
('imp-a17f5a86a1bc891c_v4_step_6', 'imp-a17f5a86a1bc891c', 6, 'finish', 'Pha nước luộc vào sốt và rưới hoàn thiện', 'Hòa 80 ml nước luộc thịt giữ lại cùng 9 g hạt mè trắng rang vào tô sốt, khuấy đều rồi chan khắp mặt đĩa thịt ba chỉ, rắc phần lá hành xanh thái nhỏ lên trên và dùng ngay.', NULL, NULL),
('imp-fbbe89a1039604fc_v4_step_1', 'imp-fbbe89a1039604fc', 1, 'prep', 'Lau sạch, thái khoanh và khía caro nấm đùi gà', 'Dùng khăn giấy ẩm lau sạch 400 g nấm đùi gà (tránh rửa trực tiếp dưới nước làm nấm hút ẩm mất độ giòn). Cắt bỏ phần chân cứng, cắt nấm thành khoanh dày 1,5 cm rồi khía các đường caro nông hai mặt; băm nhuyễn tỏi khô, thái khúc 3 cm hành lá và thái lát ớt hiểm.', 'Chỉ dùng khăn ẩm lau sạch nấm giúp giữ trọn kết cấu dai giòn tự nhiên, không bị chảy nước khi áp chảo.', NULL),
('imp-fbbe89a1039604fc_v4_step_2', 'imp-fbbe89a1039604fc', 2, 'cook', 'Áp chảo xém vàng hai mặt từng khoanh nấm', 'Tráng 15 ml dầu ăn lên chảo rộng trên lửa vừa lớn, xếp các khoanh nấm thành một lớp đều, áp chảo 4 phút và lật mặt đến khi hai mặt nấm hơi xém vàng cạnh săn giòn thì gắp ra đĩa riêng.', 'Khía caro giúp nấm nhanh chín đều bên trong và giữ sốt bám chặt quanh từng khoanh nấm.', 4),
('imp-fbbe89a1039604fc_v4_step_3', 'imp-fbbe89a1039604fc', 3, 'cook', 'Phi thơm phần lớn tỏi băm trên lửa vừa', 'Thêm 15 ml dầu ăn còn lại vào chảo, hạ lửa vừa rồi cho 3/4 lượng tỏi băm vào phi 1 phút đến khi vừa chuyển vàng nhạt và dậy hương thơm nồng.', 'Không phi tỏi quá vàng đậm vì tỏi sẽ bị đắng khi kết hợp cùng xì dầu.', 1),
('imp-fbbe89a1039604fc_v4_step_4', 'imp-fbbe89a1039604fc', 4, 'sauce', 'Hòa tỏi sống và gia vị thành sốt thơm', 'Cho 1/4 lượng tỏi băm sống còn lại vào chảo cùng 2 g muối ăn, 2 g đường cát trắng, 15 ml xì dầu nhạt và 8 ml dầu hào, đảo nhanh 15 giây cho gia vị hòa quyện sôi nhẹ.', 'Kết hợp cả tỏi phi vàng lẫn chút tỏi sống giúp món nấm dậy tầng hương thơm nồng nàn đặc trưng.', NULL),
('imp-fbbe89a1039604fc_v4_step_5', 'imp-fbbe89a1039604fc', 5, 'cook', 'Đảo nấm đùi gà thấm đều sốt tỏi', 'Trút đĩa nấm đùi gà đã áp chảo trở lại chảo, tăng lửa vừa lớn đảo nhanh tay 2 phút cho các khoanh nấm áo đều lớp sốt bóng đẹp.', NULL, 2),
('imp-fbbe89a1039604fc_v4_step_6', 'imp-fbbe89a1039604fc', 6, 'finish', 'Thêm hành lá, ớt và dọn nóng', 'Thả hành lá cắt khúc và ớt hiểm thái lát vào chảo đảo thêm 30 giây giữ màu tươi rồi tắt bếp, trút ra đĩa thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-3ee45f761eb0b78d_v4_step_1', 'imp-3ee45f761eb0b78d', 1, 'cook', 'Luộc và ủ chín mềm mọng ức gà', 'Đun sôi nồi nước vừa ngập mặt thịt cùng 10 g gừng thái lát và 2 cây hành lá cắt khúc. Thả 450 g ức gà vào nồi, đợi nước sôi lăn tăn trở lại khoảng 2 phút thì đậy kín nắp, tắt bếp ngay và để ủ yên 20 phút cho gà chín đều hoàn toàn bên trong mà vẫn giữ trọn độ mềm mọng.', 'Kỹ thuật tắt bếp ủ kín giúp thịt ức gà trắng mềm, mọng nước và không bị bã khô.', 20),
('imp-3ee45f761eb0b78d_v4_step_2', 'imp-3ee45f761eb0b78d', 2, 'prep', 'Làm nguội và xé sợi thịt ức gà', 'Vớt ức gà ra đĩa để nguội hoàn toàn (kiểm tra thớ giữa đã trắng chín hoàn toàn, không còn màu hồng), sau đó dùng tay xé dọc thớ thành những sợi tơi vừa ăn, bỏ phần gừng hành luộc.', 'Xé gà bằng tay theo chiều thớ thịt giúp từng sợi gà tơi tự nhiên và bám nước sốt tương mè ngon hơn thái dao.', NULL),
('imp-3ee45f761eb0b78d_v4_step_3', 'imp-3ee45f761eb0b78d', 3, 'sauce', 'Pha sánh mịn nước sốt tương mè Tứ Xuyên', 'Cho 45 g sốt tương mè, 45 ml xì dầu nhạt, 30 ml giấm đen Trấn Giang, 20 ml dầu ớt Tứ Xuyên, 25 ml dầu mè thơm, tỏi băm nhuyễn, 25 g đường cát trắng, 1 g tiêu Tứ Xuyên xay và 3 g muối ăn vào tô. Khuấy kỹ (có thể thêm 1–2 muỗng canh nước ấm nếu tương mè đặc) đến khi hỗn hợp hòa quyện sánh mịn.', 'Để nước sốt nghỉ 15 phút trong lúc luộc mì giúp tỏi và tiêu Tứ Xuyên ngấm sâu vào sốt.', NULL),
('imp-3ee45f761eb0b78d_v4_step_4', 'imp-3ee45f761eb0b78d', 4, 'cook', 'Luộc chín tới và xả lạnh sợi mì dai', 'Đun sôi nồi nước lớn, cho 350 g mì sợi vào luộc 3 phút đến khi vừa chín tới còn độ dai nhẹ. Vớt mì xả ngay dưới vòi nước mát, để thật ráo nước rồi trộn đều với 5 ml dầu ăn cho sợi mì tơi bóng không dính.', NULL, 3),
('imp-3ee45f761eb0b78d_v4_step_5', 'imp-3ee45f761eb0b78d', 5, 'prep', 'Thái sợi dưa leo giòn mát', 'Rửa sạch 1,2 quả dưa leo, gọt bỏ bớt phần ruột hạt mềm nếu cần rồi thái sợi mỏng đều tay, để riêng cùng 1 cây hành lá còn lại thái nhỏ.', NULL, NULL),
('imp-3ee45f761eb0b78d_v4_step_6', 'imp-3ee45f761eb0b78d', 6, 'finish', 'Xếp tô, chan sốt mè và thưởng thức', 'Chia mì nguội vào 3 tô sâu lòng, xếp dưa leo thái sợi và gà xé tơi lên trên. Chan đều nước sốt tương mè Tứ Xuyên, rắc đậu phộng rang giã dập, hạt mè trắng rang và hành lá thái nhỏ lên mặt, trộn đều ngay trước khi ăn.', NULL, NULL),
('imp-cbb5635bfe848a49_v4_step_1', 'imp-cbb5635bfe848a49', 1, 'prep', 'Thấm khô đùi gà và sơ chế gia vị thơm', 'Rửa sạch 1400 g đùi gà có xương và thấm thật khô mặt da bằng khăn giấy để khi áp chảo vàng giòn không bắn dầu. Thái lát mỏng 40 g gừng tươi, đập dập tỏi, cắt khúc 5 cm hành lá (tách riêng đầu trắng và lá xanh).', NULL, NULL),
('imp-cbb5635bfe848a49_v4_step_2', 'imp-cbb5635bfe848a49', 2, 'cook', 'Phi thơm gừng, tỏi và đầu hành trắng', 'Làm nóng 15 ml dầu ăn trong nồi đáy dày trên lửa vừa, cho gừng thái lát, tỏi đập dập và phần đầu hành trắng vào phi thơm 2 phút đến khi dậy hương dịu và tỏi vừa ngả vàng nhẹ (không để cháy đắng).', NULL, 2),
('imp-cbb5635bfe848a49_v4_step_3', 'imp-cbb5635bfe848a49', 3, 'cook', 'Áp chảo xém vàng hai mặt đùi gà', 'Xếp các miếng đùi gà thành một lớp phẳng không chồng lấn (ưu tiên úp mặt da xuống trước), áp chảo 8 phút trên lửa vừa đến khi hai mặt săn lại và da gà lên màu vàng nhạt đẹp mắt.', 'Áp chảo trước giúp phần mỡ dưới da tiết bớt và giữ thịt gà săn chắc trong suốt quá trình om.', 8),
('imp-cbb5635bfe848a49_v4_step_4', 'imp-cbb5635bfe848a49', 4, 'sauce', 'Đổ hỗn hợp xì dầu, rượu và thảo mộc', 'Rót 90 ml xì dầu nhạt, 40 ml xì dầu đặc, 60 ml rượu Thiệu Hưng, 15 ml dầu mè thơm, 50 g đường nâu và 160 ml nước lọc vào nồi. Khuấy nhẹ cho đường tan rồi thả hoa hồi khô và lá nguyệt quế khô vào cùng.', 'Kết hợp xì dầu nhạt để lấy vị mặn thanh và xì dầu đặc để tạo màu nâu cánh gián óng mượt cho thịt gà.', NULL),
('imp-cbb5635bfe848a49_v4_step_5', 'imp-cbb5635bfe848a49', 5, 'cook', 'Om liu riu cho gà chín mềm thấm sốt', 'Đun nồi sốt sôi bùng lên rồi lập tức hạ xuống lửa nhỏ nhất, đậy nắp kín om liu riu 35 phút cho thịt gà chín mềm tận xương và thấm đẫm nước sốt. Ở phút thứ 15, mở nắp lật trở mặt gà một lần cho ngấm đều hai phía.', 'Giữ lửa thật nhỏ khi om để nước sốt xì dầu không bị trào hoặc cô cạn quá nhanh gây mặn cháy.', 35),
('imp-cbb5635bfe848a49_v4_step_6', 'imp-cbb5635bfe848a49', 6, 'finish', 'Cô sánh sốt, nêm vị và hoàn thiện', 'Mở nắp nồi, đun thêm 5 phút trên lửa vừa cho nước sốt sánh bóng ôm đều miếng gà rồi rắc tiêu trắng xay vào đảo nhẹ. Thả phần lá hành xanh vào đảo đều rồi tắt bếp, vớt bỏ hoa hồi, lá nguyệt quế, gắp gà ra đĩa và chỉ rưới một lớp nước sốt bóng mượt vừa đủ lên trên (không chan hết phần nước om đậm vị dưới đáy nồi), dọn nóng cùng cơm trắng.', NULL, 5),
('imp-7bf9327b2c48f2d4_v4_step_1', 'imp-7bf9327b2c48f2d4', 1, 'marinate', 'Pha sốt tương ngũ vị và ướp sườn qua đêm', 'Thấm thật khô 1200 g sườn non. Trộn đều trong tô lớn gồm 45 ml xì dầu nhạt, tỏi băm nhuyễn, 25 g đường cát trắng, 6 g muối ăn, 1,5 g tiêu trắng xay, 1,5 g ngũ vị hương, 15 ml rượu Thiệu Hưng, 5 ml dầu mè thơm và 15 ml tương đen Hoisin. Chừa lại 1/3 lượng sốt để phết khi nướng, phần còn lại xoa đều lên khắp các dẻ sườn, bọc kín ướp ngăn mát tối thiểu 2 giờ.', 'Trước khi nướng 30 phút, lấy sườn ra khỏi tủ lạnh để thịt về nhiệt độ phòng giúp sườn chín đều từ trong ra ngoài.', 120),
('imp-7bf9327b2c48f2d4_v4_step_2', 'imp-7bf9327b2c48f2d4', 2, 'prep', 'Làm nóng lò và chuẩn bị khay nước giữ ẩm', 'Làm nóng lò nướng ở 200°C trước 10 phút. Lót giấy bạc vào khay nướng hứng bên dưới, đặt vỉ nướng thưa lên trên rồi rót 240 ml nước lọc vào khay đáy giúp hơi nước giữ sườn mềm mọng và tránh mỡ nhỏ xuống bốc khói.', 'Đặt khay nước bên dưới vỉ nướng giúp sườn không bị khô bề mặt trong suốt quá trình nướng và dễ vệ sinh khay lò.', NULL),
('imp-7bf9327b2c48f2d4_v4_step_3', 'imp-7bf9327b2c48f2d4', 3, 'cook', 'Nướng chín mềm sườn lần một ở 200°C', 'Xếp các dẻ sườn lên vỉ nướng (không chồng lên nhau), đưa vào rãnh giữa lò nướng 30 phút ở 200°C cho thịt sườn chín mềm và săn bề mặt.', NULL, 30),
('imp-7bf9327b2c48f2d4_v4_step_4', 'imp-7bf9327b2c48f2d4', 4, 'cook', 'Quét sốt ướp và nướng tiếp mặt còn lại', 'Kéo khay sườn ra, dùng cọ phết đều phần sốt ướp giữ lại lên khắp bề mặt sườn, lật mặt sườn rồi cho lại vào lò nướng thêm 20 phút ở 200°C cho gia vị thấm sâu và xém nhẹ cạnh.', NULL, 20),
('imp-7bf9327b2c48f2d4_v4_step_5', 'imp-7bf9327b2c48f2d4', 5, 'cook', 'Phết mật ong nướng xém bóng caramel', 'Quét một lớp mỏng 15 ml mật ong nguyên chất lên bề mặt sườn, chuyển khay lên rãnh trên cùng của lò và tăng nhiệt lên 220°C (chế độ lửa trên) nướng thêm 5 phút cho đến khi mặt sườn óng ánh và xém cạnh thơm lừng.', 'Canh sát lò trong 5 phút cuối vì mật ong lên màu rất nhanh và dễ bị cháy đắng.', 5),
('imp-7bf9327b2c48f2d4_v4_step_6', 'imp-7bf9327b2c48f2d4', 6, 'finish', 'Nghỉ thịt, chặt khúc và rắc hành lá', 'Lấy sườn ra để nghỉ 5 phút trên thớt cho nước thịt ổn định lại, rồi dùng dao sắc chặt thành từng miếng vừa ăn. Xếp sườn ra đĩa, rắc hành lá thái nhỏ lên trên và dùng nóng.', NULL, NULL),
('imp-bbfdcf2e3b277fed_v4_step_1', 'imp-bbfdcf2e3b277fed', 1, 'prep', 'Ngâm Kombu và sơ chế gà, hành boa-rô, gừng', 'Ngâm 15 g tảo bẹ Kombu khô trong 1000 ml nước lọc lạnh ít nhất 30 phút. Trong lúc chờ, cắt 300 g đùi gà còn da thành miếng vừa ăn, xóc đều với 1 g muối ăn để 10 phút; hành boa-rô cắt khúc dài 5 cm; gừng tươi gọt vỏ mài nhuyễn để riêng.', 'Giữ nguyên lớp da gà giúp khi áp chảo tiết ra mỡ gà thơm béo tự nhiên làm hành boa-rô cháy cạnh ngọt đậm.', 30),
('imp-bbfdcf2e3b277fed_v4_step_2', 'imp-bbfdcf2e3b277fed', 2, 'cook', 'Nấu và lọc nước dùng Dashi từ Kombu và cá bào', 'Bắc nồi nước ngâm Kombu lên bếp lửa vừa, đun đến khi sủi tăm sắp sôi thì vớt ngay miếng Kombu ra. Thả 30 g cá bào khô Katsuobushi vào đun liu riu 30 giây rồi tắt bếp, ngâm yên 10 phút cho cá bào chìm xuống đáy, sau đó lọc qua rây lót khăn giấy lấy khoảng 950 ml nước dùng Dashi trong veo.', 'Ngâm cá bào sau khi tắt bếp đủ 10 phút giúp nước dùng rút trọn vị ngọt umami mà không bị đục hay tanh.', 10),
('imp-bbfdcf2e3b277fed_v4_step_3', 'imp-bbfdcf2e3b277fed', 3, 'cook', 'Áp chảo gà da vàng giòn và hành boa-rô xém cạnh', 'Làm nóng chảo rộng trên lửa vừa với 8 ml dầu ăn thực vật, xếp đùi gà mặt da xuống và đặt các khúc hành boa-rô xen vào khoảng trống. Áp chảo yên khoảng 4–5 phút đến khi da gà vàng giòn và mặt cắt hành boa-rô chuyển màu hổ phách trong thì lật mặt áp tiếp 2–3 phút.', 'Không đảo gà và hành quá sớm để mặt cắt hành boa-rô áp xém vàng ngọt mà không bị cháy đen đắng.', 7),
('imp-bbfdcf2e3b277fed_v4_step_4', 'imp-bbfdcf2e3b277fed', 4, 'cook', 'Nêm nước dùng Dashi và nấu chín kỹ thịt gà', 'Rót toàn bộ nước dùng Dashi đã lọc vào chảo gà và hành boa-rô, đun sôi rồi hạ lửa nhỏ. Nêm 22 ml rượu Sake nấu ăn, 45 ml rượu Mirin, 40 ml xì dầu Nhật và 1 g muối ăn còn lại, hớt sạch bọt rồi đun liu riu 4–5 phút đến khi thịt gà chín hoàn toàn bên trong.', NULL, 5),
('imp-bbfdcf2e3b277fed_v4_step_5', 'imp-bbfdcf2e3b277fed', 5, 'cook', 'Luộc, xả lạnh và trụng nóng lại mì Soba', 'Đun sôi 600 ml nước lọc trong nồi riêng, thả 270 g mì Soba kiều mạch vào luộc khoảng 3–4 phút cho vừa chín tới rồi vớt ra xả ngay dưới vòi nước lạnh kết hợp chà nhẹ cho sạch lớp tinh bột nhớt. Trước khi chan nước dùng, nhúng nhanh mì Soba vào nước sôi 5 giây cho nóng rồi xóc thật ráo.', 'Xả lạnh giúp sợi Soba săn dai, sau đó nhúng nhanh qua nước nóng trước khi xếp vào tô giúp giữ nhiệt cho cả tô mì.', 4),
('imp-bbfdcf2e3b277fed_v4_step_6', 'imp-bbfdcf2e3b277fed', 6, 'finish', 'Trình bày tô mì Soba nóng thịt gà', 'Chia mì Soba ra 3 tô lớn, chan ngập nước dùng Dashi đang sôi cùng các miếng thịt gà và hành boa-rô lên trên, đặt chút gừng tươi mài nhuyễn và rắc bột ớt 7 vị Nhật Shichimi tùy thích rồi dùng nóng ngay.', NULL, NULL),
('imp-f2334219f33e48d0_v4_step_1', 'imp-f2334219f33e48d0', 1, 'prep', 'Sơ chế tôm sú sạch chỉ lưng và cắt râu', 'Rửa sạch 400 g tôm sú tươi nguyên vỏ dưới vòi nước lạnh, dùng kéo cắt gọn phần râu dài, chóp nhọn ở đầu và chân tôm, dùng tăm nhọn khéo léo rút chỉ đen dọc lưng tôm mà không làm rách vỏ. Rửa lại rồi thấm khô.', 'Giữ nguyên vỏ tôm khi nướng giúp khóa chặt độ ẩm và vị ngọt của thịt tôm bên trong.', NULL),
('imp-f2334219f33e48d0_v4_step_2', 'imp-f2334219f33e48d0', 2, 'marinate', 'Ướp tôm với rượu Sake khử tanh rồi thấm thật khô', 'Xếp tôm vào khay nông, rưới đều 45 ml rượu Sake nấu ăn lên mình tôm và để yên 5 phút cho khử mùi tanh hải sản. Sau đó vớt tôm ra, dùng khăn giấy thấm thật khô cả hai mặt vỏ tôm.', 'Thấm thật khô mặt vỏ tôm trước khi nướng giúp vỏ tôm lên màu đỏ đẹp và hơi xém giòn thay vì bị hấp hơi.', 5),
('imp-f2334219f33e48d0_v4_step_3', 'imp-f2334219f33e48d0', 3, 'prep', 'Xiên que giữ dáng tôm thẳng và rắc muối hạt biển', 'Dùng que tre đã ngâm nước lạnh xiên dọc từ đuôi lên sát đầu tôm để tôm giữ dáng thẳng đẹp khi gặp nhiệt. Rắc đều 10 g muối hạt biển phủ lên cả hai mặt vỏ tôm.', 'Ngâm que tre vào nước 10 phút trước khi xiên giúp đầu que không bị cháy sém khi nướng trên lửa lớn.', NULL),
('imp-f2334219f33e48d0_v4_step_4', 'imp-f2334219f33e48d0', 4, 'cook', 'Làm nóng vỉ nướng và phết dầu chống dính', 'Làm nóng lò nướng chế độ lửa trên 220°C (hoặc bếp nướng than/vỉ nướng) trước 5 phút, lót giấy bạc gấp mép lên khay và phết đều 8 ml dầu ăn thực vật lên bề mặt tiếp xúc.', NULL, 5),
('imp-f2334219f33e48d0_v4_step_5', 'imp-f2334219f33e48d0', 5, 'cook', 'Nướng tôm đỏ au xém cạnh hai mặt', 'Xếp tôm lên khay nướng, nướng mặt đầu tiên khoảng 4–5 phút đến khi vỏ tôm chuyển sang màu đỏ cam tươi và hơi xém nhẹ thì lật mặt, nướng tiếp 2–3 phút nữa đến khi thịt tôm chín trắng đục hoàn toàn và săn chắc.', 'Không nướng tôm quá lâu kẻo thịt tôm bị khô xác và mất đi độ ngọt mọng tự nhiên.', 7),
('imp-f2334219f33e48d0_v4_step_6', 'imp-f2334219f33e48d0', 6, 'finish', 'Trình bày đĩa tôm nướng muối cùng chanh tươi và hành lá', 'Nhẹ nhàng rút bỏ que tre, xếp tôm nướng muối ra đĩa cùng các múi chanh tươi cắt sẵn, rắc hành lá thái nhỏ và chuẩn bị thêm chút tiêu đen xay bên cạnh; khi ăn bóc bỏ lớp vỏ muối và vắt chanh lên thịt tôm nóng hổi.', NULL, NULL),
('imp-8f6eeb8b34b7cd65_v4_step_1', 'imp-8f6eeb8b34b7cd65', 1, 'prep', 'Vo ngâm gạo và nấu cơm trắng Nhật', 'Vo nhẹ 300 g gạo hạt ngắn Nhật 2–3 lần cho trong nước rồi cho vào nồi cơm điện cùng 360 ml nước lọc, ngâm 15 phút trước khi bật nấu khoảng 30 phút cho cơm chín dẻo thơm.', 'Nấu cơm trước vì cơm cần thời gian nấu và ủ hơi, trong lúc đó có thể hoàn tất khâu sơ chế và nướng mực.', 30),
('imp-8f6eeb8b34b7cd65_v4_step_2', 'imp-8f6eeb8b34b7cd65', 2, 'prep', 'Làm sạch, khứa vằn thân mực và chuẩn bị sốt', 'Rút bỏ đầu, râu và nội tạng khỏi thân 450 g mực ống tươi; rút xương sống trong suốt, bỏ mắt và răng cứng ở phần đầu râu rồi rửa sạch dưới vòi nước lạnh. Dùng khăn giấy thấm thật khô cả thân và râu mực, khứa nhẹ các đường song song cách 1 cm lên thân mực mà không cắt đứt. Trộn đều 30 ml xì dầu Nhật, 30 ml rượu Sake nấu ăn, 15 ml rượu Mirin, 24 g đường cát trắng và 10 g gừng tươi mài nhuyễn trong chén nhỏ; thái nhỏ hành lá.', 'Thấm mực thật khô và khứa nhẹ thân mực giúp mực không bị bắn nước khi áp chảo và giữ thân phẳng đẹp.', NULL),
('imp-8f6eeb8b34b7cd65_v4_step_3', 'imp-8f6eeb8b34b7cd65', 3, 'cook', 'Áp chảo thân mực xém cạnh hai mặt', 'Làm nóng chảo rộng trên lửa vừa lớn với 10 ml dầu ăn thực vật, xếp 3 thân mực vào áp chảo mỗi mặt khoảng 2 phút đến khi thân mực săn phồng, chuyển màu trắng đục và hơi cháy xém cạnh thơm lừng.', 'Áp chảo nhanh trên lửa vừa lớn giúp mực giữ độ giòn ngọt mà không bị dai như cao su.', 4),
('imp-8f6eeb8b34b7cd65_v4_step_4', 'imp-8f6eeb8b34b7cd65', 4, 'sauce', 'Áo sốt Teriyaki gừng sánh bóng cho thân mực', 'Đổ toàn bộ chén nước sốt xì dầu Sake Mirin gừng đã pha vào chảo thân mực, liên tục lật trở mực khoảng 2 phút trên lửa vừa đến khi nước sốt sôi sệt lại, bám bóng đều quanh thân mực thì gắp thân mực ra thớt.', NULL, 2),
('imp-8f6eeb8b34b7cd65_v4_step_5', 'imp-8f6eeb8b34b7cd65', 5, 'cook', 'Đảo chín phần râu mực với nước sốt còn lại', 'Thả phần râu mực vào chảo cùng lượng sốt Teriyaki sánh còn lại, đảo nhanh trên lửa vừa khoảng 1–2 phút cho râu mực săn chín hoàn toàn và thấm đẫm sốt thơm ngon rồi tắt bếp.', NULL, 2),
('imp-8f6eeb8b34b7cd65_v4_step_6', 'imp-8f6eeb8b34b7cd65', 6, 'finish', 'Thái khoanh mực, xếp lên cơm nóng và thưởng thức', 'Thái thân mực thành từng khoanh tròn dày 1,5 cm. Xới cơm nóng ra 3 bát, xếp các khoanh mực và râu mực nướng lên trên, rưới đều phần sốt còn lại trong chảo, rắc hành lá thái nhỏ và dùng nóng ngay.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_v4_step_1', 'imp-9e4ad3e4074d2a1c', 1, 'prep', 'Sơ chế tôm sú và luộc chín giữ độ giòn ngọt', 'Bóc vỏ, bỏ đầu, rạch nhẹ lưng rút chỉ đen 250 g tôm sú tươi rồi rửa nhanh với 1 g muối ăn và xả lại nước lạnh. Đun sôi 350 ml nước lọc cùng 1 g muối ăn còn lại, thả tôm vào luộc khoảng 2–3 phút đến khi tôm cong tròn, chuyển màu hồng đỏ đục và chín hoàn toàn thì vớt ra để nguội, cắt miếng vừa ăn.', 'Không luộc tôm quá 3 phút để thịt tôm giữ được độ giòn ngọt mà không bị khô bở.', 3),
('imp-9e4ad3e4074d2a1c_v4_step_2', 'imp-9e4ad3e4074d2a1c', 2, 'prep', 'Thái sợi bắp cải, cà rốt và ngâm hành tây hết hăng', 'Bắp cải xanh thái sợi thật mỏng, cà rốt gọt vỏ thái sợi mảnh. Hành tây thái lát thật mỏng, cho vào tô 250 ml nước lọc lạnh ngâm khoảng 8 phút (có thể thả bắp cải vào ngâm cùng 3 phút cuối cho giòn) rồi vớt tất cả ra rổ, vắt và vẩy thật ráo nước.', 'Ngâm hành tây trong nước lạnh giúp khử vị hăng nồng và giữ độ giòn, nhớ vẩy thật ráo nước để sốt không bị loãng.', 8),
('imp-9e4ad3e4074d2a1c_v4_step_3', 'imp-9e4ad3e4074d2a1c', 3, 'sauce', 'Pha sốt Mayonnaise mật ong giấm chanh hài hòa', 'Cho 45 g sốt Mayonnaise, 15 ml mật ong, 12 ml giấm gạo, nước cốt của nửa quả chanh tươi và 5 ml xì dầu Nhật vào chén, dùng phới lồng nhỏ khuấy đều đến khi hỗn hợp sốt quyện mịn bóng mượt.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_v4_step_4', 'imp-9e4ad3e4074d2a1c', 4, 'cook', 'Trộn nhẹ tay rau củ và tôm với nước sốt', 'Cho bắp cải, cà rốt, hành tây đã ráo nước cùng tôm sú luộc cắt miếng vào tô trộn lớn. Rưới đều phần sốt đã pha lên trên và dùng hai chiếc thìa lớn đảo nhẹ tay để sốt áo mỏng đều mà không làm nát tôm.', 'Trộn salad ngay sau khi ráo nước giúp phần sốt Mayonnaise bám đều từng sợi bắp cải.', NULL),
('imp-9e4ad3e4074d2a1c_v4_step_5', 'imp-9e4ad3e4074d2a1c', 5, 'prep', 'Làm mát salad trong tủ lạnh trước khi dọn', 'Bọc kín tô salad và cho vào ngăn mát tủ lạnh khoảng 15 phút cho các nguyên liệu mát giòn và quyện vị thơm ngon hơn.', NULL, 15),
('imp-9e4ad3e4074d2a1c_v4_step_6', 'imp-9e4ad3e4074d2a1c', 6, 'finish', 'Trình bày đĩa salad bắp cải tôm Nhật mát lạnh', 'Múc salad bắp cải tôm ra đĩa sâu lòng, rắc hành lá thái nhỏ lên trên để tăng màu sắc tươi mát rồi thưởng thức ngay.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-4023e971948407f6_v4_step_1', 'imp-4023e971948407f6', 1, 'marinate', 'Thấm khô và ướp gia vị cho cá hồi', 'Rửa nhanh cá hồi phi lê với nước lạnh rồi dùng khăn giấy thấm thật khô bề mặt, cắt thành 3 miếng vừa ăn khoảng 100 g mỗi miếng. Rắc đều 2 g muối ăn và 1/2 lượng tiêu đen xay lên cả hai mặt cá, để nghỉ 10 phút cho thịt cá săn và thấm gia vị.', 'Thấm thật khô cá trước khi ướp và áo bột giúp cá không bị bắn dầu khi áp chảo và giữ được lớp bề mặt vàng đẹp.', 10),
('imp-4023e971948407f6_v4_step_2', 'imp-4023e971948407f6', 2, 'prep', 'Chần bóc vỏ cà chua và sơ chế rau củ', 'Khía hình chữ thập nhẹ ở đáy 3 quả cà chua chín, thả vào nồi nước sôi chần khoảng 30 giây đến khi mép vỏ hơi tách rồi vớt ra ngâm nước lạnh, bóc sạch vỏ, bỏ hạt và thái hạt lựu. Bóc vỏ hành tây và thái múi cau mỏng, băm nhuyễn tỏi tươi, thái lát nấm đùi gà dày 0,5 cm và cắt khúc hành lá dài 2–3 cm.', 'Chần bỏ vỏ và hạt cà chua giúp nước sốt om sau khi nấu mịn mượt, không bị lợn cợn xác vỏ.', NULL),
('imp-4023e971948407f6_v4_step_3', 'imp-4023e971948407f6', 3, 'prep', 'Áo một lớp bột mì mỏng lên miếng cá', 'Rắc đều 12 g bột mì đa dụng lên hai mặt từng miếng cá hồi đã ướp, dùng tay vỗ và giũ nhẹ cho phần bột thừa rơi bớt, chỉ giữ lại lớp áo thật mỏng phủ đều quanh cá.', NULL, NULL),
('imp-4023e971948407f6_v4_step_4', 'imp-4023e971948407f6', 4, 'cook', 'Áp chảo sơ cho cá hồi vàng nhẹ hai mặt', 'Đun nóng 8 ml dầu ô liu trong chảo rộng trên lửa vừa, đặt từng miếng cá hồi vào áp chảo mỗi mặt khoảng 2 phút đến khi bề mặt chuyển vàng nhạt và se cạnh thì nhẹ nhàng gắp ra đĩa riêng. Không chiên chín kỹ ở bước này vì cá sẽ tiếp tục được om trong sốt.', 'Áp chảo lửa vừa trong thời gian ngắn giúp khóa ẩm bên trong thớ thịt cá hồi, tránh bị khô bở khi om tiếp.', 4),
('imp-4023e971948407f6_v4_step_5', 'imp-4023e971948407f6', 5, 'cook', 'Xào thơm tỏi, hành tây và nấm đùi gà', 'Vẫn dùng chảo đó, thêm 7 ml dầu ô liu còn lại trên lửa vừa, cho tỏi băm vào phi khoảng 20 giây đến khi dậy mùi thơm dịu (không để cháy xém). Tiếp tục cho hành tây và nấm đùi gà vào đảo đều khoảng 3 phút đến khi hành tây hơi trong và nấm mềm tỏa hương ngọt.', NULL, 3),
('imp-4023e971948407f6_v4_step_6', 'imp-4023e971948407f6', 6, 'sauce', 'Nấu nhừ cà chua thành sốt mặn ngọt', 'Trút toàn bộ cà chua thái hạt lựu vào chảo cùng 25 ml xì dầu Nhật Bản, 15 ml rượu ngọt Mirin và 5 g đường cát trắng. Đảo đều và đun sôi trên lửa vừa, sau đó hạ nhỏ lửa om khoảng 5 phút đến khi cà chua nhừ ra sốt đỏ cam sánh nhẹ; nếu chảo hơi khô thì thêm từ từ 60 ml nước lọc.', 'Nêm thử phần sốt cà chua trước khi thả cá vào; vị đạt là chua dịu tự nhiên, hài hòa giữa mặn của xì dầu và ngọt thanh từ Mirin.', 5),
('imp-4023e971948407f6_v4_step_7', 'imp-4023e971948407f6', 7, 'cook', 'Om cá hồi thấm đẫm sốt cà chua', 'Xếp nhẹ các miếng cá hồi đã áp chảo trở lại chảo sốt, dùng thìa rưới đều nước sốt lên mặt cá. Đậy nắp và om trên lửa nhỏ khoảng 5 phút cho đến khi thịt cá chuyển màu hồng cam đục đồng nhất, chín tới hoàn toàn ở phần lõi mà vẫn mềm ẩm.', NULL, 5),
('imp-4023e971948407f6_v4_step_8', 'imp-4023e971948407f6', 8, 'finish', 'Chỉnh gia vị và hoàn thiện đĩa cá om', 'Mở nắp chảo, rắc 1 g muối ăn còn lại cùng phần tiêu đen xay còn lại nếu cần điều chỉnh độ đậm, lắc nhẹ chảo cho sốt hòa quyện. Rắc hành lá thái khúc lên trên, tắt bếp và dọn nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-76ddca35768468fe_v4_step_1', 'imp-76ddca35768468fe', 1, 'prep', 'Băm hành lá và chuẩn bị chanh vàng', 'Rửa sạch 2 bó hành lá tươi, vẩy ráo rồi thấm thật khô bằng khăn giấy, sau đó băm thật nhỏ cả phần đầu trắng lẫn lá xanh. Bào nhuyễn tỏi tươi, cắt đôi quả chanh vàng để vắt lấy 15 ml nước cốt, phần còn lại cắt thành 4–6 múi cau xếp ra đĩa riêng.', 'Thấm thật khô hành lá trước khi băm giúp sốt Negi-shio sánh quyện vào dầu mè mà không bị chảy nhiều nước loãng.', NULL),
('imp-76ddca35768468fe_v4_step_2', 'imp-76ddca35768468fe', 2, 'sauce', 'Pha sốt hành lá Negi-shio thơm béo', 'Cho toàn bộ hành lá băm vào tô nhỏ, thêm 15 ml dầu mè thơm, 15 ml nước cốt chanh vàng, 15 ml rượu Sake, tỏi bào nhuyễn, 3 g muối ăn, 1 g tiêu đen xay và 6 g hạt mè trắng rang. Trộn thật đều và để sốt nghỉ tối thiểu 5 phút cho hành lá dịu vị hăng và tiết nước quyện đều gia vị.', NULL, 5),
('imp-76ddca35768468fe_v4_step_3', 'imp-76ddca35768468fe', 3, 'prep', 'Để thịt bò hồi nhiệt và thấm khô bề mặt', 'Xếp 360 g thịt bò thăn thái lát mỏng ra đĩa lớn, để ở nhiệt độ phòng khoảng 10 phút cho thịt bớt lạnh, dùng khăn giấy thấm khô nhẹ bề mặt từng lát thịt.', 'Thịt bò lạnh đặt thẳng lên vỉ dễ bị tiết nước làm hấp thịt thay vì xém cạnh; để hồi nhiệt nhẹ giúp bò nướng mềm ngọt hơn.', 10),
('imp-76ddca35768468fe_v4_step_4', 'imp-76ddca35768468fe', 4, 'cook', 'Làm nóng vỉ nướng hoặc chảo gang', 'Làm nóng vỉ nướng điện, bếp than hoặc chảo gang rãnh trên lửa lớn khoảng 3 phút cho đến khi mặt vỉ thật nóng và bốc hơi nhẹ.', NULL, NULL),
('imp-76ddca35768468fe_v4_step_5', 'imp-76ddca35768468fe', 5, 'cook', 'Nướng thịt bò nhanh tay trên lửa lớn', 'Xếp từng lát thịt bò lên mặt vỉ nóng thành một lớp thoáng, không chồng lên nhau. Nướng lửa lớn khoảng 45–60 giây cho mặt dưới xém nâu cạnh, rắc một phần muối ăn (trong số 3 g còn lại) và tiêu đen xay lên mặt trên rồi lật mặt nướng tiếp 30–45 giây đến khi thịt chín đều không còn màu đỏ sống.', 'Lát bò Yakiniku mỏng chín rất nhanh; lật ngay khi thấy mặt dưới xém cạnh để thịt giữ độ mọng nước, tránh nướng quá kỹ gây dai.', 2),
('imp-76ddca35768468fe_v4_step_6', 'imp-76ddca35768468fe', 6, 'finish', 'Vắt chanh tươi và thưởng thức cùng sốt Negi-shio', 'Gắp thịt bò vừa nướng xong ra đĩa nóng, vắt vài giọt chanh vàng từ múi cau lên thịt để dậy hương thanh mát, đặt một ít sốt hành lá Negi-shio lên trên từng miếng bò hoặc chấm trực tiếp vào chén sốt và dùng ngay khi nóng.', NULL, NULL),
('imp-1bbb2341036dd966_v4_step_1', 'imp-1bbb2341036dd966', 1, 'prep', 'Sơ chế bông cải xanh và hành lá', 'Rửa sạch bông cải xanh dưới vòi nước, tách thành các nhánh nhỏ đều cỡ 3–4 cm và gọt bỏ phần xơ cứng quanh cuống để rau chín đồng đều. Rửa sạch hành lá tươi, thấm khô và thái khoanh thật nhỏ.', NULL, NULL),
('imp-1bbb2341036dd966_v4_step_2', 'imp-1bbb2341036dd966', 2, 'prep', 'Rang thơm và giã dập hạt mè trắng', 'Cho 27 g hạt mè trắng vào chảo khô, rang trên lửa nhỏ khoảng 3 phút và đảo liên tục đến khi mè chuyển vàng nhạt, dậy mùi thơm bùi thì trút ra ngay kẻo cháy. Đợi nguội bớt, cho 2/3 lượng mè vào cối giã dập cho tiết dầu thơm, giữ lại 1/3 nguyên hạt để rắc mặt.', 'Giã dập 2/3 lượng mè giúp tinh dầu mè tiết ra quyện sốt béo ngậy, trong khi phần mè nguyên hạt tạo điểm nhấn giòn bùi khi ăn.', 3),
('imp-1bbb2341036dd966_v4_step_3', 'imp-1bbb2341036dd966', 3, 'cook', 'Luộc nhanh bông cải xanh giữ độ giòn', 'Đun sôi 1000 ml nước lọc với 5 g muối ăn trên lửa lớn. Thả các nhánh bông cải xanh vào luộc khoảng 2–3 phút đến khi rau vừa chín tới, cuống còn giòn nhẹ và giữ nguyên màu xanh ngọc tươi sáng.', 'Không luộc bông cải quá mềm nhũn vì rau sẽ ngậm nhiều nước, làm loãng sốt mè và mất độ giòn đặc trưng.', 3),
('imp-1bbb2341036dd966_v4_step_4', 'imp-1bbb2341036dd966', 4, 'prep', 'Xả nguội và vắt thật ráo bông cải', 'Vớt bông cải xanh ra rổ ngay khi đạt độ chín, xả nhanh qua nước lọc mát (hoặc quạt nguội trên mâm thưa) để chặn nhiệt giữ màu xanh, sau đó để thật ráo nước và dùng khăn sạch thấm nhẹ cho bề mặt rau khô ráo hoàn toàn.', NULL, NULL),
('imp-1bbb2341036dd966_v4_step_5', 'imp-1bbb2341036dd966', 5, 'sauce', 'Khuấy sốt mè trộn kiểu Nhật', 'Trong tô trộn lớn, khuấy đều 24 ml xì dầu Nhật Bản, 15 ml rượu Sake, 8 ml mật ong nguyên chất và 30 ml nước dùng Dashi đến khi mật ong tan hoàn toàn, sau đó cho toàn bộ phần hạt mè trắng đã giã dập vào trộn sánh mịn.', 'Nếm nhẹ phần sốt trước khi trộn rau; nếu thích vị ngọt dịu hơn có thể thêm vài giọt mật ong, thích đậm hơn thêm chút xì dầu.', NULL),
('imp-1bbb2341036dd966_v4_step_6', 'imp-1bbb2341036dd966', 6, 'finish', 'Trộn đều bông cải với sốt mè và hoàn thiện', 'Cho bông cải xanh đã ráo nước vào tô sốt mè, dùng đũa hoặc phới trộn nhẹ tay từ dưới lên cho sốt áo đều từng nhánh rau, để yên 2 phút cho thấm. Bày ra đĩa, rắc phần mè trắng nguyên hạt còn lại cùng hành lá thái nhỏ lên trên và thưởng thức.', NULL, NULL),
('imp-5ed977305ac677b6_v4_step_1', 'imp-5ed977305ac677b6', 1, 'prep', 'Chuẩn bị hành lá và các loại topping', 'Rửa sạch hành lá tươi, thấm thật khô rồi thái khoanh mỏng. Cắt rong biển lá khô Nori thành sợi mảnh, bóp tơi nhẹ cá bào khô Katsuobushi và chuẩn bị sẵn hạt mè trắng rang cùng 2 viên bơ lạt (14 g mỗi viên).', NULL, NULL),
('imp-5ed977305ac677b6_v4_step_2', 'imp-5ed977305ac677b6', 2, 'prep', 'Xới cơm thật nóng ra hai tô', 'Đảm bảo cơm trắng hạt ngắn Nhật vừa nấu chín hoặc đã hâm nóng bốc hơi. Xới đều 360 g cơm ra 2 tô (180 g/tô), dùng muỗng ấn nhẹ tạo một hõm nhỏ ở chính giữa mỗi tô cơm.', 'Cơm phải đủ nóng bốc hơi mới giúp viên bơ tan chảy hoàn toàn và giải phóng hương thơm đặc trưng.', NULL),
('imp-5ed977305ac677b6_v4_step_3', 'imp-5ed977305ac677b6', 3, 'cook', 'Đặt bơ lạt vào hõm cơm để tan chảy', 'Đặt mỗi tô cơm một viên bơ lạt 14 g vào giữa hõm cơm nóng, chờ khoảng 1 phút cho hơi nóng làm bơ mềm và bắt đầu tan chảy thấm xuống lớp cơm bên dưới.', 'Có thể phủ nhẹ một lớp cơm mỏng lên viên bơ trong 30 giây đầu để giữ nhiệt giúp bơ chảy đều nhanh hơn.', 1),
('imp-5ed977305ac677b6_v4_step_4', 'imp-5ed977305ac677b6', 4, 'sauce', 'Rưới xì dầu Nhật Bản quanh viên bơ', 'Rưới từ từ 7,5 ml xì dầu Nhật Bản lên phần bơ đang tan của mỗi tô (tổng 15 ml cho 2 tô). Không rưới quá nhiều một lúc để giữ cân bằng vị béo của bơ và vị mặn thanh của xì dầu.', 'Nên giữ tỷ lệ vừa phải giữa bơ và xì dầu để món cơm không bị mặn gắt mà vẫn nổi bật mùi thơm bơ sữa.', NULL),
('imp-5ed977305ac677b6_v4_step_5', 'imp-5ed977305ac677b6', 5, 'finish', 'Rắc hành lá, cá bào, rong biển và mè rang', 'Rắc đều hành lá thái mỏng, cá bào khô Katsuobushi, rong biển lá khô Nori cắt sợi, hạt mè trắng rang và một ít tiêu đen xay lên mặt mỗi tô cơm.', NULL, NULL),
('imp-5ed977305ac677b6_v4_step_6', 'imp-5ed977305ac677b6', 6, 'finish', 'Trộn đều cơm bơ xì dầu và thưởng thức nóng', 'Dùng đũa trộn thật đều khoảng 1 phút ngay trước khi ăn cho từng hạt cơm áo bóng bơ lạt tan chảy, xì dầu Nhật Bản và các loại topping thơm lừng, dùng nóng ngay.', NULL, 1),
('imp-57294c4da3e61e24_v4_step_1', 'imp-57294c4da3e61e24', 1, 'prep', 'Sơ chế tôm tươi, nấm đùi gà và rong biển', 'Rửa sạch tôm tươi dưới vòi nước lạnh, cắt bỏ râu và chân dài, tách nhẹ đầu tôm và rạch lưng rút bỏ chỉ đen, giữ nguyên đầu vỏ để nấu nước dùng ngọt thanh. Lau sạch nấm đùi gà và thái lát dày 0,5 cm. Ngâm rong biển Wakame khô trong nước lạnh khoảng 3 phút cho nở mềm rồi vắt ráo; thái khoanh mỏng hành lá tươi.', 'Nấu nguyên đầu và vỏ tôm giúp tiết ra vị ngọt hải sản tự nhiên, hòa quyện rất hợp với nước dùng Dashi và Miso.', 3),
('imp-57294c4da3e61e24_v4_step_2', 'imp-57294c4da3e61e24', 2, 'cook', 'Đun sôi nước dùng với rượu Sake', 'Đổ 550 ml nước lọc và 100 ml nước dùng Dashi cùng 15 ml rượu Sake vào nồi, đặt lên bếp đun trên lửa vừa đến khi nước dùng sôi lăn tăn.', NULL, NULL),
('imp-57294c4da3e61e24_v4_step_3', 'imp-57294c4da3e61e24', 3, 'cook', 'Nấu chín tôm tươi và vớt bọt trong nước', 'Thả tôm tươi vào nồi nước dùng đang sôi, đun trên lửa vừa khoảng 2–3 phút đến khi vỏ tôm chuyển màu đỏ cam rực và thịt tôm săn đục chín hoàn toàn; dùng muôi hớt sạch bọt nổi để nước súp thật trong.', NULL, 3),
('imp-57294c4da3e61e24_v4_step_4', 'imp-57294c4da3e61e24', 4, 'cook', 'Nấu nấm đùi gà và rong biển Wakame', 'Cho nấm đùi gà thái lát vào nồi, hạ lửa vừa nhỏ nấu sôi liu riu thêm 3 phút cho nấm chín mềm tiết vị ngọt. Tiếp tục thả rong biển Wakame đã nở ráo và hành lá thái khoanh vào nồi nấu khoảng 1 phút.', 'Không nấu nấm và rong biển quá lâu để nấm giữ được độ giòn nhẹ còn rong biển không bị nhũn nát.', 3),
('imp-57294c4da3e61e24_v4_step_5', 'imp-57294c4da3e61e24', 5, 'sauce', 'Tắt bếp và hòa tan tương Miso Nhật Bản', 'Tắt bếp hoàn toàn để nước súp ngừng sôi. Cho 54 g tương Miso Nhật Bản vào chén hoặc rây lọc, múc một vá nước dùng nóng từ nồi khuấy cho Miso tan mịn hoàn toàn rồi đổ ngược vào nồi súp, khuấy nhẹ đều tay.', 'Tuyệt đối không đun sôi lại nồi súp sau khi đã cho tương Miso vì nhiệt sôi mạnh sẽ làm bay mất hương thơm lên men đặc trưng.', NULL),
('imp-57294c4da3e61e24_v4_step_6', 'imp-57294c4da3e61e24', 6, 'finish', 'Nêm chỉnh vị và múc súp dùng nóng', 'Nếm thử độ mặn của nước dùng, nếu cần tăng nhẹ độ đậm có thể thêm 5 ml xì dầu Nhật Bản tùy khẩu vị. Múc súp Miso ra 3 bát, chia đều tôm, nấm đùi gà và rong biển rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_v4_step_1', 'imp-ea9ba867b7d2c6ad', 1, 'prep', 'Sơ chế ức gà, bắp cải và gừng hành', 'Rửa sạch 320 g ức gà không da không xương, thấm khô bằng khăn giấy và khứa vài đường nông trên bề mặt cho nhanh chín. Rửa sạch bắp cải tươi, để ráo và cắt miếng vuông vừa ăn khoảng 4 cm. Chia 20 g gừng tươi: 10 g thái lát mỏng, 10 g bào thật nhuyễn; hành lá chia phần đầu lót hấp và phần lá xanh thái nhỏ.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_v4_step_2', 'imp-ea9ba867b7d2c6ad', 2, 'marinate', 'Ướp ức gà với muối và rượu Sake', 'Xát đều 2 g muối ăn lên hai mặt ức gà, rưới 25 ml rượu Sake Nhật Bản lên thịt và ướp khoảng 10 phút cho thịt gà thấm vị, khử mùi và giữ được độ mềm ẩm khi hấp.', 'Hấp nguyên miếng ức gà rồi mới xé sợi sau giúp khóa nước ngọt bên trong thớ thịt, tránh làm ức gà bị khô xơ.', 10),
('imp-ea9ba867b7d2c6ad_v4_step_3', 'imp-ea9ba867b7d2c6ad', 3, 'cook', 'Lót bắp cải và hấp chín ức gà', 'Đổ 400 ml nước lọc vào nồi hấp và đun sôi trên lửa lớn. Trải đều bắp cải vào đĩa sâu lòng chịu nhiệt, xếp đầu hành lá và 10 g gừng thái lát lên trên rồi đặt miếng ức gà cùng toàn bộ nước ướp lên mặt. Cho đĩa vào xửng, đậy nắp kín và hấp trên lửa vừa khoảng 14–15 phút đến khi thịt gà chuyển màu trắng đục hoàn toàn và nước chảy ra trong khi xiên thử.', 'Không hấp quá lâu sau khi gà đã chín tới để phần ức gà giữ được kết cấu mềm mọng và bắp cải vẫn còn vị giòn ngọt.', 15),
('imp-ea9ba867b7d2c6ad_v4_step_4', 'imp-ea9ba867b7d2c6ad', 4, 'sauce', 'Pha sốt nước tương Ponzu gừng dầu mè', 'Trong lúc chờ hấp, pha sốt trong chén nhỏ gồm 50 ml nước tương Ponzu chanh Nhật, 10 ml dầu mè thơm và 10 g gừng tươi bào nhuyễn; khuấy thật đều tay cho gia vị hòa quyện.', 'Nếu thích món có thêm chút nước ngọt thanh, có thể chắt 2 muỗng canh nước hấp gà trong đĩa hòa chung vào chén sốt Ponzu.', NULL),
('imp-ea9ba867b7d2c6ad_v4_step_5', 'imp-ea9ba867b7d2c6ad', 5, 'prep', 'Để gà nghỉ và xé sợi vừa ăn', 'Nhấc đĩa gà hấp ra khỏi xửng, gắp ức gà để nghỉ khoảng 3 phút cho nguội bớt và ổn định nước thịt, sau đó dùng tay xé thành từng sợi vừa ăn theo thớ thịt. Chắt bớt nếu nước hấp trong đĩa quá nhiều để sốt không bị loãng.', NULL, 3),
('imp-ea9ba867b7d2c6ad_v4_step_6', 'imp-ea9ba867b7d2c6ad', 6, 'finish', 'Trộn sốt, rắc mè và hành lá hoàn thiện', 'Xếp gà xé trở lại lên lớp bắp cải hấp chín mềm trong đĩa, rưới đều toàn bộ sốt nước tương Ponzu gừng dầu mè lên trên, rắc 10 g hạt mè trắng rang cùng phần hành lá thái nhỏ và thưởng thức ngay.', NULL, NULL),
('imp-7d764feba948bce3_v4_step_1', 'imp-7d764feba948bce3', 1, 'prep', 'Sơ chế kim chi, đậu phụ và rau củ', 'Cắt 320 g cải kim chi thành khúc dài khoảng 3 cm, giữ riêng 80 g nước kim chi. Thái lát đậu phụ trắng dày khoảng 1,2 cm, đặt lên đĩa có lót khăn giấy cho ráo bớt nước. Thái lát hành tây dày 0,5 cm, băm nhỏ 4 tép tỏi và thái vát hành lá.', 'Kim chi càng lên men chua kỹ thì nước canh càng đậm đà, dậy vị chua thanh tự nhiên mà không cần dùng thêm giấm.', NULL),
('imp-7d764feba948bce3_v4_step_2', 'imp-7d764feba948bce3', 2, 'prep', 'Cắt khúc và thấm khô cá hồi', 'Rửa nhanh 400 g phi lê cá hồi dưới vòi nước lạnh, dùng khăn giấy thấm thật khô cả hai mặt rồi cắt khúc vuông khoảng 3–4 cm để khi nấu thịt cá giữ nguyên miếng không bị bở nát.', 'Thấm thật khô bề mặt cá hồi trước khi nấu giúp cá săn thớ và giảm đáng kể mùi tanh đặc trưng của hải sản.', NULL),
('imp-7d764feba948bce3_v4_step_3', 'imp-7d764feba948bce3', 3, 'cook', 'Xào kim chi cùng tỏi và ớt bột Hàn', 'Làm nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn thực vật, cho tỏi băm, phần cải kim chi đã cắt khúc và 6 g ớt bột Hàn Quốc vào đảo đều trong 5 phút đến khi lá kim chi hơi trong, mềm dịu và tiết ra màu đỏ cam thơm nồng.', 'Xào kỹ kim chi trước khi đổ nước giúp giảm vị chua gắt và giải phóng hương thơm đặc trưng của ớt bột Hàn.', 5),
('imp-7d764feba948bce3_v4_step_4', 'imp-7d764feba948bce3', 4, 'cook', 'Hầm nền nước dùng kim chi đậm vị', 'Đổ phần nước kim chi giữ lại cùng 750 ml nước lọc vào nồi. Bật lửa lớn đun sôi bùng, sau đó đậy nắp và hạ về lửa vừa, nấu liu riu trong 10 phút cho kim chi ra hết vị ngọt chua vào nước dùng.', NULL, 10),
('imp-7d764feba948bce3_v4_step_5', 'imp-7d764feba948bce3', 5, 'cook', 'Nấu chín cá hồi và hành tây', 'Thả nhẹ từng khúc cá hồi và hành tây thái lát vào nồi nước đang sôi lăn tăn, nấu trên lửa vừa khoảng 7 phút đến khi thớ cá hồi chuyển màu hồng nhạt đục đều và chín hẳn từ bên trong, chú ý không khuấy mạnh làm vỡ cá.', 'Kiểm tra lát cá ở phút thứ 7: chỉ cần thịt cá tách múi dễ dàng và không còn lõi trong sống là đạt, tránh nấu quá lâu khiến cá bị khô.', 7),
('imp-7d764feba948bce3_v4_step_6', 'imp-7d764feba948bce3', 6, 'finish', 'Thả đậu phụ, nêm gia vị và hoàn thiện', 'Xếp nhẹ đậu phụ trắng lên mặt nồi canh, nêm 15 ml nước tương, 8 g đường cát trắng, 1 g tiêu đen xay và nếm thử trước khi thêm từ từ 3 g muối ăn cho vừa khẩu vị. Rưới 10 ml dầu mè rang, đun sôi nhẹ thêm 3 phút cho đậu phụ nóng đều, rắc hành lá lên trên rồi tắt bếp.', NULL, 3),
('imp-a24e0f07380bfdc2_v4_step_1', 'imp-a24e0f07380bfdc2', 1, 'prep', 'Ngâm nấm hương và ngâm sườn loại bỏ máu thừa', 'Ngâm 35 g nấm hương khô vào 500 ml nước lọc lạnh khoảng 40 phút cho nở mềm; vớt nấm ra cắt bỏ chân và thái miếng vừa ăn, lọc giữ lại phần nước ngâm nấm trong sạch. Rửa sườn bò, ngâm trong nước lạnh 30 phút và thay nước 2 lần cho ra hết máu thừa.', 'Ngâm sườn đủ thời gian giúp loại bỏ mùi hôi của bò và giữ cho nước sốt hầm sau này thật trong, thanh vị.', 35),
('imp-a24e0f07380bfdc2_v4_step_2', 'imp-a24e0f07380bfdc2', 2, 'prep', 'Chần sơ sườn bò cho sạch tạp chất', 'Đun sôi 1000 ml nước lọc trong nồi lớn trên lửa lớn, thả toàn bộ sườn bò vào chần trong 5 phút, đảo nhẹ để tiết bọt bẩn. Vớt sườn ra rửa lại kỹ dưới vòi nước lạnh cho sạch cặn vụn xương rồi rửa sạch lòng nồi.', 'Rửa sạch nồi sau khi chần giúp nước hầm không bị đục và không bám cặn đen vào mặt thịt.', 5),
('imp-a24e0f07380bfdc2_v4_step_3', 'imp-a24e0f07380bfdc2', 3, 'sauce', 'Pha sốt hầm sườn và sơ chế rau củ', 'Xay nhuyễn 1/2 củ hành tây rồi trộn đều với 90 ml nước tương Hàn Quốc, 120 ml rượu ngọt Mirin Nhật, 50 g đường cát trắng, tỏi băm, gừng băm, 2 g tiêu đen xay và 450 ml nước ngâm nấm hương cho tan đường. Gọt vỏ củ cải trắng và cà rốt, cắt khối 3,5–4 cm và tỉa tròn nhẹ góc cạnh; bổ múi cau nửa hành tây còn lại; bổ đôi táo đỏ khô bỏ hạt; cắt khúc hành lá.', 'Tỉa tròn góc cạnh củ cải và cà rốt giúp rau củ giữ nguyên khối đẹp mắt, không bị sứt vỡ khi hầm lâu.', NULL),
('imp-a24e0f07380bfdc2_v4_step_4', 'imp-a24e0f07380bfdc2', 4, 'cook', 'Hầm sườn giai đoạn đầu trên lửa vừa', 'Xếp sườn bò đã chần vào nồi sạch, đổ toàn bộ hỗn hợp sốt vừa pha cùng nửa củ hành tây bổ múi cau vào, đậy nắp kín và đun lửa vừa trong 20 phút cho sườn thấm đều gia vị và bắt đầu mềm thớ.', NULL, 20),
('imp-a24e0f07380bfdc2_v4_step_5', 'imp-a24e0f07380bfdc2', 5, 'cook', 'Hầm tiếp cùng củ cải, cà rốt và nấm hương', 'Cho nấm hương, củ cải trắng và cà rốt vào nồi, đảo nhẹ để rau củ ngập trong nước sốt. Đậy nắp, hạ xuống lửa nhỏ và hầm liu riu thêm 55 phút, thỉnh thoảng mở nắp múc sốt rưới lên trên và kiểm tra lượng nước để không bị bén đáy.', 'Nếu nước cạn nhanh trong lúc hầm, châm thêm 100–150 ml nước lọc nóng và giữ lửa nhỏ liu riu.', 55),
('imp-a24e0f07380bfdc2_v4_step_6', 'imp-a24e0f07380bfdc2', 6, 'cook', 'Thêm táo đỏ, siro gạo và làm bóng sốt', 'Khi dùng xiên tre xiên qua thịt sườn thấy mềm dễ dàng, cho táo đỏ khô và 30 ml siro gạo vào đảo nhẹ, đậy nắp rim lửa nhỏ thêm 10 phút. Sau đó mở nắp, tăng lửa vừa-lớn khoảng 5 phút, liên tục múc nước sốt dưới đáy rưới đều lên thịt và rau củ đến khi sốt sánh quyện bóng đẹp.', NULL, 15),
('imp-a24e0f07380bfdc2_v4_step_7', 'imp-a24e0f07380bfdc2', 7, 'finish', 'Hoàn thiện hương mè và hành lá trước khi dọn', 'Tắt bếp, rưới đều 15 ml dầu mè rang Hàn Quốc và thả hành lá cắt khúc vào đảo nhẹ một lượt rồi dọn sườn cùng rau củ ra đĩa sâu lòng thưởng thức nóng.', NULL, NULL),
('imp-706c3678abea88b4_v4_step_1', 'imp-706c3678abea88b4', 1, 'prep', 'Đánh tan trứng với hành lá và gia vị', 'Rửa sạch hành lá, để thật ráo nước rồi thái nhỏ khoảng 0,5 cm. Đập 4 quả trứng gà vào tô, dùng đũa đánh tan thật kỹ đến khi lòng đỏ và lòng trắng hòa quyện hoàn toàn. Cho hành lá, 2 g muối ăn và 0,5 g tiêu đen xay vào khuấy đều.', 'Hành lá phải thật ráo nước để không làm loãng trứng và tránh bắn dầu khi chiên; đánh kỹ giúp mặt trứng mịn đẹp không bị đốm trắng.', NULL),
('imp-706c3678abea88b4_v4_step_2', 'imp-706c3678abea88b4', 2, 'sauce', 'Pha nước chấm tương giấm mè', 'Khuấy tan 25 ml nước tương với 5 ml giấm gạo và 2 g đường cát trắng trong chén nhỏ, thêm một nửa lượng hạt mè trắng rang lên trên để dùng chấm kèm trứng.', NULL, NULL),
('imp-706c3678abea88b4_v4_step_3', 'imp-706c3678abea88b4', 3, 'cook', 'Chiên chiếc trứng tròn đầu tiên', 'Đặt chảo chống dính đường kính 20–22 cm lên bếp lửa vừa, tráng đều 7,5 ml dầu ăn thực vật. Khi dầu nóng già, đổ một nửa hỗn hợp trứng vào, nghiêng nhẹ chảo cho trứng dàn tròn đều rồi chiên khoảng 2 phút đến khi mặt dưới vàng nâu và viền trứng hơi giòn se lại.', 'Chia làm 2 mẻ chiên thay vì 1 mẻ lớn giúp bánh trứng tròn đẹp, dễ lật và chín đều mà không bị sống lõi.', 2),
('imp-706c3678abea88b4_v4_step_4', 'imp-706c3678abea88b4', 4, 'cook', 'Lật mặt và chiên chín vàng đều hai mặt', 'Dùng xẻng bản rộng lật nhẹ miếng trứng sang mặt còn lại, hạ lửa vừa-nhỏ chiên thêm 2 phút đến khi mặt dưới vàng ruộm và phần giữa chín hoàn toàn không còn ướt rồi trút ra đĩa.', 'Chỉ lật đúng một lần khi mép trứng đã se chắc; nếu mặt trên còn hơi ướt thì chờ thêm 20–30 giây trước khi lật để trứng không bị vỡ.', 2),
('imp-706c3678abea88b4_v4_step_5', 'imp-706c3678abea88b4', 5, 'cook', 'Chiên nốt mẻ trứng thứ hai', 'Lau nhanh mặt chảo bằng khăn giấy sạch nếu có vụn trứng cháy, cho nốt 7,5 ml dầu ăn thực vật vào tráng đều rồi đổ phần hỗn hợp trứng còn lại vào chiên vàng đều hai mặt tương tự (khoảng 2 phút mỗi mặt).', NULL, 4),
('imp-706c3678abea88b4_v4_step_6', 'imp-706c3678abea88b4', 6, 'finish', 'Cắt miếng và trình bày đĩa trứng chiên', 'Để trứng nghỉ trên thớt khoảng 2 phút cho định hình chắc tay rồi cắt mỗi chiếc thành 6 miếng tam giác vừa ăn, rắc phần hạt mè trắng rang còn lại lên mặt và dọn nóng cùng chén nước tương pha.', NULL, NULL),
('imp-d88e008b28a31151_v4_step_1', 'imp-d88e008b28a31151', 1, 'prep', 'Làm sạch, khứa caro và thấm khô mực', 'Tách đầu mực khỏi thân, bỏ túi nội tạng, mắt, mỏ cứng và rút thanh mai trong suốt. Rửa sạch mực dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô. Khứa mặt trong thân mực theo đường caro nông, thái miếng vừa ăn và cắt râu thành khúc 4 cm.', 'Khứa caro giúp mực cong đẹp mắt, nhanh chín và thấm đều sốt cay; thấm thật khô để mực không tiết nhiều nước khi vào chảo.', NULL),
('imp-d88e008b28a31151_v4_step_2', 'imp-d88e008b28a31151', 2, 'sauce', 'Sơ chế rau củ và pha sẵn sốt cay', 'Thái nhỏ 200 g kim chi cải thảo, thái múi cau hành tây, thái lát mỏng cà rốt và cắt khúc hành lá. Trong chén nhỏ, khuấy đều 45 g tương ớt Hàn Quốc, 15 g ớt bột Hàn Quốc, 35 ml nước tương, tỏi băm nhuyễn và 2 g tiêu đen xay thành hỗn hợp sốt sệt.', 'Chuẩn bị sẵn toàn bộ nguyên liệu và sốt trước khi bật bếp vì món xào lửa lớn diễn ra liên tục chỉ trong vài phút.', NULL),
('imp-d88e008b28a31151_v4_step_3', 'imp-d88e008b28a31151', 3, 'cook', 'Phi thơm hành lá và xào sơ rau củ', 'Làm nóng chảo lớn trên lửa lớn với 30 ml dầu ăn thực vật, cho đầu hành lá vào đảo khoảng 45 giây đến khi thơm và hơi xém cạnh. Thêm hành tây và cà rốt vào xào nhanh 1 phút cho rau vừa dịu.', NULL, 2),
('imp-d88e008b28a31151_v4_step_4', 'imp-d88e008b28a31151', 4, 'cook', 'Xào săn kim chi cho dậy hương', 'Thả kim chi cải thảo đã thái nhỏ vào chảo, đảo đều trên lửa lớn trong 2 phút cho kim chi săn lại, quyện dầu hành và tỏa mùi thơm cay nồng.', NULL, 2),
('imp-d88e008b28a31151_v4_step_5', 'imp-d88e008b28a31151', 5, 'cook', 'Xào mực với đường và cô đặc sốt một góc chảo', 'Cho toàn bộ mực vào chảo, rắc đều 15 g đường cát trắng lên trên và đảo nhanh tay khoảng 1 phút đến khi mực bắt đầu cong lại và chuyển màu trắng đục. Gạt mực và rau sang một bên chảo, đổ chén sốt cay vào khoảng trống còn lại, đun sôi sùng sục 30 giây cho sốt hơi sánh lại.', 'Rắc đường lên mực trước khi gặp nước tương mặn giúp mực giữ được độ mềm ngọt, đồng thời cô sốt riêng một góc giúp tránh loãng nước.', 2),
('imp-d88e008b28a31151_v4_step_6', 'imp-d88e008b28a31151', 6, 'finish', 'Trộn đều áo sốt và rưới dầu mè hoàn thiện', 'Đảo đều toàn bộ mực, kim chi và phần lá xanh hành lá với sốt thêm khoảng 30 giây trên lửa lớn đến khi mực chín đều, săn giòn và áo sốt đỏ bóng. Tắt bếp ngay, rưới 10 ml dầu mè rang, rắc hạt mè trắng rang lên trên rồi trút ra đĩa thưởng thức nóng.', NULL, NULL),
('imp-3ec4d8a534fc8861_v4_step_1', 'imp-3ec4d8a534fc8861', 1, 'prep', 'Sơ chế và khứa nhẹ thịt đùi gà', 'Rửa sạch 600 g thịt đùi gà dưới vòi nước lạnh, thấm thật khô bằng khăn giấy. Dùng dao khứa 2–3 đường chéo sâu khoảng 1 cm trên phần thịt dày để nước ướp thấm nhanh và thịt không bị co rút khi gặp nhiệt cao.', NULL, NULL),
('imp-3ec4d8a534fc8861_v4_step_2', 'imp-3ec4d8a534fc8861', 2, 'marinate', 'Pha sốt bulgogi và ướp gà thấm vị', 'Trong tô lớn, khuấy tan 45 ml nước tương Hàn Quốc, 20 g đường nâu, 15 ml mật ong nguyên chất, 15 ml rượu ngọt Mirin Nhật, 10 ml dầu mè rang, tỏi băm, gừng băm, đầu hành lá băm và 1,5 g tiêu đen xay. Cho thịt gà và hành tây thái mỏng vào bóp đều cho phủ kín sốt, đậy kín ướp ít nhất 30 phút (hoặc 2–4 giờ trong ngăn mát cho đậm đà).', 'Đảm bảo đường nâu tan hết trong hỗn hợp ướp để sốt bám đều vào thớ gà, tránh bị cháy cục bộ khi nướng.', 30),
('imp-3ec4d8a534fc8861_v4_step_3', 'imp-3ec4d8a534fc8861', 3, 'cook', 'Làm nóng chảo gang hoặc lò nướng', 'Nếu ướp lạnh, lấy gà ra ngoài khoảng 15 phút cho bớt lạnh. Làm nóng chảo gang hoặc vỉ nướng ở lửa vừa-cao (hoặc làm nóng lò nướng ở 200°C), phết đều 10 ml dầu ăn thực vật lên bề mặt chảo/vỉ để chống dính.', 'Để thịt về gần nhiệt độ phòng trước khi nướng giúp gà chín đều từ trong ra ngoài mà bề mặt không bị cháy khét.', NULL),
('imp-3ec4d8a534fc8861_v4_step_4', 'imp-3ec4d8a534fc8861', 4, 'cook', 'Nướng gà chín vàng xém cạnh hai mặt', 'Gạt bớt phần hành tây bám trên thịt (giữ lại nước ướp), đặt gà lên vỉ hoặc chảo nóng nướng khoảng 6 phút mỗi mặt đến khi bề mặt xém vàng bóng đẹp. Kiểm tra phần thịt dày nhất đạt độ chín hoàn toàn, cắt thử không còn màu hồng và nước thịt chảy ra trong.', 'Trở mặt khi mặt dưới đã lên màu nâu cánh gián; vì sốt có đường và mật ong nên cần canh lửa vừa-cao, tránh lửa quá gắt.', 12),
('imp-3ec4d8a534fc8861_v4_step_5', 'imp-3ec4d8a534fc8861', 5, 'sauce', 'Đun sôi sánh phần nước ướp làm sốt rưới', 'Đổ toàn bộ nước ướp còn dư cùng hành tây thái lát vào chảo nhỏ, đun sôi mạnh rồi hạ lửa vừa-nhỏ nấu thêm 3 phút cho hành tây chín mềm và nước sốt sánh nhẹ lại, đảm bảo tiệt trùng an toàn trước khi dùng làm sốt rưới.', 'Luôn đun sôi kỹ phần nước ướp từng tiếp xúc với thịt gà sống ít nhất 2–3 phút trước khi rưới lên thành phẩm.', 3),
('imp-3ec4d8a534fc8861_v4_step_6', 'imp-3ec4d8a534fc8861', 6, 'finish', 'Thái miếng, rưới sốt và rắc mè hoàn thiện', 'Cho gà nướng nghỉ 4 phút trên thớt để giữ trọn nước ngọt bên trong, thái miếng vừa ăn rồi xếp ra đĩa. Rưới nước sốt bulgogi sánh bóng cùng hành tây lên trên, rắc lá xanh hành lá thái nhỏ và hạt mè trắng rang rồi dùng nóng.', NULL, NULL),
('imp-750cef719bf5f2f6_v4_step_1', 'imp-750cef719bf5f2f6', 1, 'prep', 'Vo gạo và chuẩn bị kim chi, hành tỏi', 'Vo sạch 150 g gạo tẻ thơm, ngâm nước lạnh 15 phút rồi vớt ra để ráo. Thái nhỏ 170 g cải kim chi cỡ 1 cm, giữ lại 50 g nước kim chi. Băm nhỏ tỏi và thái nhỏ hành lá.', NULL, NULL),
('imp-750cef719bf5f2f6_v4_step_2', 'imp-750cef719bf5f2f6', 2, 'cook', 'Xào mềm kim chi với dầu mè và tỏi', 'Cho 15 ml dầu mè rang vào nồi đáy dày khi bếp còn nguội, thêm tỏi băm, cải kim chi, nước kim chi, 10 g đường cát trắng và 5 ml nước mắm. Bật lửa vừa, đảo đều trong 4 phút đến khi kim chi mềm thấm gia vị và dậy mùi thơm.', 'Cho dầu mè vào từ lúc nồi còn nguội rồi mới bật lửa vừa giúp dầu mè không bị cháy khét hay mất mùi thơm.', 4),
('imp-750cef719bf5f2f6_v4_step_3', 'imp-750cef719bf5f2f6', 3, 'cook', 'Rang sơ gạo và đổ nước ninh cháo sánh mịn', 'Trút gạo đã ngâm ráo vào nồi đảo cùng kim chi 1 phút cho hạt gạo áo dầu thơm. Đổ 1100 ml nước lọc vào, bật lửa lớn đun sôi bùng rồi hạ về lửa nhỏ, đậy hờ nắp ninh liu riu 18 phút, thỉnh thoảng khuấy nhẹ đáy nồi để hạt gạo nở bung sánh mịn và không bén đáy.', 'Nếu thích cháo loãng hơn hoặc cháo đặc nhanh khi gần chín, có thể châm thêm 50–100 ml nước nóng.', 18),
('imp-750cef719bf5f2f6_v4_step_4', 'imp-750cef719bf5f2f6', 4, 'cook', 'Nêm vị cháo và thả một nửa hành lá', 'Nêm 15 ml nước tương, 5 ml nước mắm còn lại cùng 1/2 lượng hành lá thái nhỏ vào nồi cháo, khuấy đều và nếm lại sao cho đạt vị chua dịu, mặn ngọt hài hòa.', NULL, NULL),
('imp-750cef719bf5f2f6_v4_step_5', 'imp-750cef719bf5f2f6', 5, 'cook', 'Cho trứng gà vào ủ chín mềm trong nồi cháo', 'Hạ lửa thật nhỏ, đập nhẹ 3 quả trứng gà vào bề mặt nồi cháo (hoặc đánh tan rưới vòng tròn nếu thích dạng vân trứng), đậy kín nắp ủ khoảng 3 phút cho lòng trắng đông chín hoàn toàn và lòng đỏ chín mềm theo ý muốn.', 'Ủ đúng 3 phút trên lửa nhỏ giúp trứng chín mềm mịn mà không bị khô xác hay làm đục màu cháo.', 3),
('imp-750cef719bf5f2f6_v4_step_6', 'imp-750cef719bf5f2f6', 6, 'finish', 'Múc cháo ra tô và rắc rong biển hoàn thiện', 'Tắt bếp, múc cháo nóng cùng trứng ra tô. Rưới nốt 5 ml dầu mè rang, rắc phần hành lá còn lại, rong biển khô cắt vụn, 4 g ớt bột Hàn Quốc và hạt mè trắng rang lên mặt rồi thưởng thức ngay.', NULL, NULL),
('imp-28d20ebe44b82a22_v4_step_1', 'imp-28d20ebe44b82a22', 1, 'prep', 'Thái nấm đùi gà và sơ chế ớt, hành tỏi', 'Cắt bỏ phần gốc cứng của 350 g nấm đùi gà tươi, rửa nhanh rồi thấm ráo nước, thái lát vát dày 0,6–0,8 cm để khi xào nấm ngót lại vẫn giữ độ dai giòn. Thái lát xéo ớt sừng đỏ, băm nhỏ tỏi và cắt khúc hành lá.', 'Không ngâm nấm trong nước quá lâu vì nấm hút nước sẽ làm chảo xào bị nhão và mất độ giòn sần sật.', NULL),
('imp-28d20ebe44b82a22_v4_step_2', 'imp-28d20ebe44b82a22', 2, 'sauce', 'Pha sẵn hỗn hợp sốt tương dầu hào', 'Trộn đều 25 ml nước tương, 20 ml dầu hào, 8 g đường cát trắng và 1 g tiêu đen xay trong chén nhỏ, khuấy kỹ đến khi đường tan hoàn toàn.', NULL, NULL),
('imp-28d20ebe44b82a22_v4_step_3', 'imp-28d20ebe44b82a22', 3, 'cook', 'Phi thơm tỏi trên chảo nóng', 'Đun nóng chảo trên lửa vừa với 25 ml dầu ăn thực vật, cho tỏi băm vào phi khoảng 1–2 phút đến khi tỏi dậy mùi thơm và vừa ngả vàng nhẹ.', 'Canh lửa vừa và đảo đều để tỏi không bị cháy sém gây vị đắng cho nấm.', 2),
('imp-28d20ebe44b82a22_v4_step_4', 'imp-28d20ebe44b82a22', 4, 'cook', 'Xào săn nấm đùi gà và ớt sừng', 'Cho toàn bộ nấm đùi gà và ớt sừng đỏ thái lát vào chảo, tăng lửa vừa-cao xào đều tay khoảng 4 phút cho nấm tiết bớt nước ngọt, săn cạnh và chín mềm dẻo.', NULL, 4),
('imp-28d20ebe44b82a22_v4_step_5', 'imp-28d20ebe44b82a22', 5, 'cook', 'Rưới sốt và đảo bóng đều nấm', 'Rưới hỗn hợp sốt tương dầu hào đã pha vào chảo, đảo liên tục trên lửa vừa khoảng 2–3 phút đến khi phần sốt sánh quyện lại, bám đều một lớp nâu óng mượt quanh từng miếng nấm.', 'Đảo liên tục khi nước sốt cạn dần để sốt phủ đều khắp mặt nấm mà không bị cháy khét đáy chảo.', 3),
('imp-28d20ebe44b82a22_v4_step_6', 'imp-28d20ebe44b82a22', 6, 'finish', 'Rưới dầu mè và rắc hành lá, mè rang', 'Tắt bếp, rưới 10 ml dầu mè rang Hàn Quốc và thêm hành lá cắt khúc vào đảo nhanh một lượt. Trút nấm ra đĩa, rắc hạt mè trắng rang lên trên rồi dọn ăn kèm cơm nóng.', NULL, NULL),
('imp-922028bd2fb07eb8_v4_step_1', 'imp-922028bd2fb07eb8', 1, 'prep', 'Thấm khô, cắt lát đậu phụ và pha sốt tương', 'Dùng khăn giấy thấm thật khô 4 miếng đậu phụ chắc rồi thái lát chữ nhật dày khoảng 1 cm. Thái nhỏ hành lá và băm nhuyễn tỏi. Trong chén nhỏ, hòa đều 35 ml nước tương Hàn Quốc, 15 ml siro ngô, 4 g ớt bột Hàn Quốc và 30 ml nước lọc.', 'Thấm khô đậu phụ kỹ trước khi chiên giúp mặt đậu nhanh vàng giòn, không bị bắn dầu và không vỡ nát khi lật.', NULL),
('imp-922028bd2fb07eb8_v4_step_2', 'imp-922028bd2fb07eb8', 2, 'cook', 'Áp chảo mặt đầu đậu phụ vàng đều', 'Làm nóng chảo chống dính với 30 ml dầu ăn thực vật trên lửa vừa-nhỏ, xếp từng miếng đậu phụ vào chảo sao cho không chồng lên nhau. Áp chảo yên trong 5 phút đến khi mặt dưới chuyển vàng nâu và cứng cạnh.', 'Không lật đậu sớm khi mặt dưới chưa vàng giòn vì miếng đậu mềm dễ bị dính và vỡ.', 5),
('imp-922028bd2fb07eb8_v4_step_3', 'imp-922028bd2fb07eb8', 3, 'cook', 'Lật nhẹ tay chiên vàng mặt còn lại', 'Dùng xẻng mỏng lật nhẹ từng miếng đậu phụ sang mặt còn lại, tiếp tục áp chảo thêm 4 phút trên lửa vừa-nhỏ cho hai mặt vàng giòn đều nhau.', NULL, 4),
('imp-922028bd2fb07eb8_v4_step_4', 'imp-922028bd2fb07eb8', 4, 'cook', 'Phi thơm tỏi trực tiếp trong chảo đậu', 'Gạt nhẹ các miếng đậu sang xung quanh, cho tỏi băm vào khoảng trống giữa chảo và đảo nhanh 30 giây trên lửa nhỏ cho tỏi dậy mùi thơm vàng nhẹ mà không bị cháy đắng.', 'Cho tỏi vào sau khi đậu đã chiên vàng giúp tỏi thơm dậy mùi mà không bị cháy khét suốt thời gian áp chảo đậu.', NULL),
('imp-922028bd2fb07eb8_v4_step_5', 'imp-922028bd2fb07eb8', 5, 'cook', 'Rưới sốt tương và rim sánh bóng', 'Rưới đều chén sốt tương đã pha lên khắp mặt đậu phụ, lắc nhẹ chảo cho sốt tràn đều dưới đáy. Hạ lửa vừa-nhỏ rim khoảng 3 phút, thả hành lá thái nhỏ vào đảo nhẹ cho hành mềm dịu và sốt sánh quyện bám quanh từng lát đậu.', NULL, 3),
('imp-922028bd2fb07eb8_v4_step_6', 'imp-922028bd2fb07eb8', 6, 'finish', 'Rưới dầu mè và rắc mè rang hoàn thiện', 'Tắt bếp, rưới 10 ml dầu mè rang Hàn Quốc lên mặt đậu, gắp xếp gọn gàng ra đĩa, chan phần nước sốt hành còn trong chảo và rắc hạt mè trắng rang lên trên rồi thưởng thức.', NULL, NULL),
('imp-b575db6fcd68a387_v4_step_1', 'imp-b575db6fcd68a387', 1, 'prep', 'Đánh tan trứng gà và sơ chế hành tỏi', 'Đập 4 quả trứng gà vào tô lớn, dùng đũa đánh tan thật đều đến khi không còn sợi lòng trắng. Thái nhỏ hành lá, băm thật nhuyễn tỏi và dùng khăn khô lau nhẹ miếng tảo bẹ khô.', NULL, NULL),
('imp-b575db6fcd68a387_v4_step_2', 'imp-b575db6fcd68a387', 2, 'cook', 'Nấu nước dùng tảo bẹ ngọt thanh', 'Cho 750 ml nước lọc và 8 g tảo bẹ khô vào nồi, đun lửa vừa trong 5 phút đến khi nước vừa sôi lăn tăn quanh mép nồi thì gắp bỏ miếng tảo bẹ ra ngay để nước dùng trong và không bị nhớt.', 'Không đun tảo bẹ sôi sùng sục quá lâu vì chất nhầy trong tảo tiết ra sẽ làm đục nước canh.', 5),
('imp-b575db6fcd68a387_v4_step_3', 'imp-b575db6fcd68a387', 3, 'cook', 'Nêm gia vị tạo nền nước canh đậm đà', 'Cho tỏi băm, 15 ml nước tương, 5 ml nước mắm ngon và 2,5 g muối ăn vào nồi nước dùng, khuấy đều và đun sôi bùng trở lại trên lửa vừa.', NULL, NULL),
('imp-b575db6fcd68a387_v4_step_4', 'imp-b575db6fcd68a387', 4, 'cook', 'Rưới trứng theo dòng mảnh tạo vân mềm mịn', 'Khi nước canh đang sôi nhẹ, cầm tô trứng rót từ từ theo dòng thật mảnh theo vòng tròn quanh nồi. Để yên tuyệt đối không khuấy trong 10 giây để trứng tự định hình thành sợi tơ mềm mượt.', 'Không khuấy ngay lúc mới đổ trứng vì sẽ làm trứng tan vụn và khiến nước canh bị đục.', NULL),
('imp-b575db6fcd68a387_v4_step_5', 'imp-b575db6fcd68a387', 5, 'cook', 'Khuấy nhẹ và nấu chín hoàn toàn vân trứng', 'Dùng đũa khua nhẹ một vòng dưới đáy cho các dải trứng tơi đều nhau, đun thêm 1 phút trên lửa vừa đến khi trứng chín phồng nhẹ và nổi đều trong nồi canh.', NULL, 1),
('imp-b575db6fcd68a387_v4_step_6', 'imp-b575db6fcd68a387', 6, 'finish', 'Thả hành lá, rắc tiêu và nhỏ dầu mè', 'Thả hành lá thái nhỏ và 1 g tiêu đen xay vào nồi, nêm nếm lại cho vừa miệng rồi tắt bếp. Múc canh nóng ra tô, rưới nhẹ 5 ml dầu mè rang lên trên và dùng nóng với cơm trắng.', 'Nếu thích vị cay nhẹ giải cảm, có thể rắc thêm một chút ớt bột mịn hoặc ớt tươi thái lát mỏng lên mặt tô canh.', NULL),
('imp-53933600fa3853f3_v4_step_1', 'imp-53933600fa3853f3', 1, 'prep', 'Thái mỏng thịt bò ngang thớ', 'Làm sạch 400 g thịt thăn bò, thấm khô bề mặt rồi thái lát mỏng khoảng 3 mm theo chiều ngang thớ để thịt mềm ngọt và không bị dai khi xào nhanh.', 'Đặt miếng bò vào ngăn đá khoảng 15 phút trước khi thái giúp thớ thịt hơi se cứng lại, rất dễ thái lát mỏng đều tay.', NULL),
('imp-53933600fa3853f3_v4_step_2', 'imp-53933600fa3853f3', 2, 'marinate', 'Pha sốt bulgogi và ướp thịt bò', 'Trong tô lớn, khuấy tan 35 ml nước tương Hàn Quốc, 20 g đường cát trắng, 10 ml dầu mè rang, tỏi băm nhuyễn và 1,5 g tiêu đen xay. Cho thịt bò vào bóp nhẹ cho từng lát thấm đều sốt, đậy kín ướp 15–20 phút.', NULL, 15),
('imp-53933600fa3853f3_v4_step_3', 'imp-53933600fa3853f3', 3, 'prep', 'Thái dọc nấm đùi gà và sơ chế hành', 'Trong lúc chờ ướp thịt, thái dọc 200 g nấm đùi gà thành lát dày 3–4 mm, thái múi cau mỏng hành tây và cắt khúc hành lá dài khoảng 5–6 cm.', 'Thái nấm dọc theo chiều dài thân nấm giúp miếng nấm giữ độ dai sần sật và không bị nát vụn khi đảo cùng thịt.', NULL),
('imp-53933600fa3853f3_v4_step_4', 'imp-53933600fa3853f3', 4, 'cook', 'Xào thơm nấm đùi gà, hành tây và hành lá', 'Làm nóng chảo sâu lòng trên lửa vừa-cao với 25 ml dầu ăn thực vật. Cho nấm đùi gà, hành tây và phần lớn hành lá (giữ lại ít lá xanh rắc mặt) vào đảo nhanh tay trong 2 phút đến khi hành hơi xém cạnh và nấm dịu mềm.', NULL, 2),
('imp-53933600fa3853f3_v4_step_5', 'imp-53933600fa3853f3', 5, 'cook', 'Xào nhanh thịt bò chín mềm quyện sốt', 'Dàn đều toàn bộ thịt bò cùng nước ướp vào chảo, giữ lửa lớn-vừa đảo đều tay khoảng 4 phút đến khi thịt bò chuyển màu nâu chín đều, nước sốt rút sánh lại bám bóng quanh thịt, nấm và hành.', 'Thịt bò thái mỏng chín rất nhanh, chỉ cần xào vừa chuyển màu hoàn toàn là đạt; đảo quá lâu thịt sẽ khô và ra nước.', 4),
('imp-53933600fa3853f3_v4_step_6', 'imp-53933600fa3853f3', 6, 'finish', 'Rưới dầu mè, rắc mè rang và thưởng thức', 'Nêm nếm lại vừa khẩu vị, tắt bếp rồi rưới nốt 5 ml dầu mè rang còn lại vào đảo đều. Trút ra đĩa, rắc phần hành lá xanh và hạt mè trắng rang lên trên rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-81fc284c0bafa826_v4_step_1', 'imp-81fc284c0bafa826', 1, 'prep', 'Sơ chế tôm, băm sả tỏi ớt và thái lá chanh', 'Thấm thật khô 400 g tôm tươi đã bóc vỏ chừa đuôi rút chỉ lưng. Băm thật nhuyễn phần gốc non của 3 cây sả cùng 3/4 củ tỏi khô; băm nhỏ 3 quả ớt hiểm và thái lát xéo 2 quả còn lại; tước bỏ gân giữa 4 g lá chanh Thái rồi thái sợi.', 'Băm sả thật nhỏ và thấm khô tôm trước khi xào giúp sả bám chặt lên thân tôm mà không bị bắn dầu.', NULL),
('imp-81fc284c0bafa826_v4_step_2', 'imp-81fc284c0bafa826', 2, 'sauce', 'Pha sẵn nước sốt dầu hào đường thốt nốt', 'Khuấy tan hoàn toàn trong chén nhỏ gồm 10 g đường thốt nốt băm nhỏ, 20 ml xì dầu nhạt, 5 ml xì dầu đen đặc Thái, 25 ml dầu hào, 6 ml nước mắm ngon và 30 ml nước lọc để sẵn cạnh bếp.', NULL, NULL),
('imp-81fc284c0bafa826_v4_step_3', 'imp-81fc284c0bafa826', 3, 'cook', 'Phi thơm sả, tỏi, ớt hiểm cùng bột nghệ', 'Làm nóng chảo sâu lòng trên lửa vừa với 25 ml dầu ăn, cho sả băm, tỏi băm và ớt hiểm băm vào đảo đều 2 phút đến khi sả tỏi dậy hương thơm nồng và hơi vàng cạnh. Tiếp tục thêm lá chanh Thái và 2 g bột nghệ vàng vào đảo nhanh 30 giây.', 'Phi sả trên lửa vừa trước để sả chín thơm và dịu mùi hăng mà không làm cháy khét tỏi.', 2),
('imp-81fc284c0bafa826_v4_step_4', 'imp-81fc284c0bafa826', 4, 'cook', 'Xào tôm lửa lớn vừa chuyển hồng săn', 'Tăng lên lửa lớn, trút toàn bộ 400 g tôm tươi cùng ớt hiểm thái lát vào chảo, đảo đều tay khoảng 2 phút đến khi tôm bắt đầu chuyển màu đỏ cam và săn chắc các cạnh.', NULL, 2),
('imp-81fc284c0bafa826_v4_step_5', 'imp-81fc284c0bafa826', 5, 'cook', 'Rưới nước sốt và đảo keo bóng quanh tôm', 'Khuấy đều chén sốt đã pha rồi rưới hết vào chảo tôm, tiếp tục đảo nhanh tay trên lửa lớn thêm 1–2 phút đến khi tôm cuộn cong chín hoàn toàn bên trong và nước sốt sôi sệt lại, áo bóng đều quanh từng con tôm cùng sả ớt.', 'Chỉ xào tôm tổng cộng khoảng 3–4 phút trên lửa lớn để thịt tôm giòn ngọt mà không bị khô bở.', NULL),
('imp-81fc284c0bafa826_v4_step_6', 'imp-81fc284c0bafa826', 6, 'finish', 'Nếm chỉnh vị và trình bày ra đĩa nóng', 'Nếm lại nước sốt cho vừa khẩu vị mặn ngọt cay thơm rồi tắt bếp, gắp tôm ra đĩa, rưới toàn bộ phần sốt sả ớt trong chảo lên trên và dọn nóng với cơm trắng.', NULL, NULL),
('imp-15e4185437e9198c_v4_step_1', 'imp-15e4185437e9198c', 1, 'prep', 'Ngâm mềm bánh phở khô đúng chuẩn', 'Ngâm 180 g bánh phở khô trong nước ở nhiệt độ phòng ít nhất 60 phút cho đến khi sợi phở mềm dẻo có thể quấn quanh ngón tay mà không gãy, vớt ra để ráo hoàn toàn và cắt đôi những sợi quá dài.', 'Nếu cần làm nhanh, bạn có thể trụng bánh phở trong nước vừa sôi đúng 3 phút rồi xả ngay nước lạnh để không bị bở nát.', 60),
('imp-15e4185437e9198c_v4_step_2', 'imp-15e4185437e9198c', 2, 'prep', 'Sơ chế đồng bộ toàn bộ nguyên liệu', 'Ngâm 60 g me chín với 80 ml nước ấm rồi dằm lọc bỏ hạt lấy nước cốt. Băm thô 20 g tôm khô, băm nhỏ 55 g hành tím và 1/2 củ tỏi, thái nhỏ 1 miếng đậu phụ ép, cắt khúc 5 cm phần 90 g hẹ lá, rửa ráo 180 g giá đỗ, giã thô 50 g đậu phộng rang và cắt múi cau 1,5 quả chanh tươi.', NULL, NULL),
('imp-15e4185437e9198c_v4_step_3', 'imp-15e4185437e9198c', 3, 'sauce', 'Thắng caramen đường thốt nốt nấu sốt me', 'Cho 50 g đường thốt nốt băm nhỏ vào nồi nhỏ đun lửa vừa, đảo liên tục 3 phút đến khi đường tan chảy và ngả màu nâu sậm thơm dịu. Tắt bếp rồi cẩn thận rót nước cốt me đã lọc cùng 40 ml nước mắm ngon vào khuấy đều đến khi sốt sánh quyện bóng mượt.', 'Đường có thể hơi vón lại khi gặp nước cốt me nguội, chỉ cần khuấy nhẹ hoặc để yên vài phút sẽ tự tan hết.', 3),
('imp-15e4185437e9198c_v4_step_4', 'imp-15e4185437e9198c', 4, 'cook', 'Áp chảo tôm chín vàng và giữ riêng', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, xếp 300 g tôm tươi vào áp chảo mỗi mặt 1 phút đến khi tôm chuyển màu hồng cam, săn chắc chín hoàn toàn thì gắp ra đĩa riêng.', NULL, 2),
('imp-15e4185437e9198c_v4_step_5', 'imp-15e4185437e9198c', 5, 'cook', 'Xào thơm đậu phụ, tôm khô và hành tỏi', 'Thêm 20 ml dầu ăn vào chảo trên lửa vừa, cho đậu phụ thái nhỏ, hành tím, tỏi, tôm khô băm và 2 g ớt bột vào đảo đều 3 phút đến khi hành tỏi thơm vàng nhẹ và đậu phụ săn cạnh.', NULL, 3),
('imp-15e4185437e9198c_v4_step_6', 'imp-15e4185437e9198c', 6, 'cook', 'Xào bánh phở ngấm sốt và đánh tơi trứng', 'Tăng lửa lớn, trút bánh phở đã ráo cùng toàn bộ nước sốt me vào đảo đều 3 phút đến khi sợi phở hút cạn nước sốt, tơi bóng và mềm dai vừa ăn. Gạt mì sang một bên chảo, thêm 10 ml dầu ăn còn lại, đập 3 quả trứng gà vào đánh vỡ lòng đỏ, gạt mì phủ lên trên chờ 25 giây cho trứng se chín rồi đảo tơi quyện đều.', 'Phủ bánh phở lên trên lớp trứng vừa đánh vỡ giúp trứng chín mềm ẩm và bám quyện thành từng sợi tơi quanh bánh phở.', 3),
('imp-15e4185437e9198c_v4_step_7', 'imp-15e4185437e9198c', 7, 'finish', 'Trộn giá hẹ và trình bày Pad Thai nóng', 'Tắt bếp ngay, cho tôm áp chảo, một nửa lượng đậu phộng rang giã dập, 120 g giá đỗ và phần lớn hẹ cắt khúc vào đảo nhanh 15 giây cho giá hẹ vừa chín tái giòn ngọt. Chia ra 3 đĩa, rắc phần đậu phộng còn lại và dọn kèm giá sống, hẹ tươi cùng múi chanh.', NULL, NULL),
('imp-cc62ea4de6a7436b_v4_step_1', 'imp-cc62ea4de6a7436b', 1, 'prep', 'Sơ chế tôm, dứa chín và rau thơm', 'Rửa sạch 300 g tôm tươi đã bóc vỏ rút chỉ lưng. Gọt vỏ, bỏ sạch mắt và lõi cứng 3/4 quả dứa chín rồi thái miếng vuông cạnh 1,5 cm. Thái lát thật mỏng 40 g hành tím, thái nhỏ 1/2 bó hành lá, thái lát mỏng 4 quả ớt hiểm, xắt rối 12 g lá bạc hà tươi và giã dập 45 g đậu phộng rang.', 'Chọn dứa chín tới có độ giòn ngọt vừa phải để khi trộn gỏi không bị nát và tiết quá nhiều nước.', NULL),
('imp-cc62ea4de6a7436b_v4_step_2', 'imp-cc62ea4de6a7436b', 2, 'cook', 'Luộc chín tôm giữ độ giòn ngọt', 'Đun sôi mạnh 600 ml nước lọc trong nồi nhỏ trên lửa lớn, thả 300 g tôm vào luộc khoảng 2 phút đến khi tôm cuộn cong, chuyển màu đỏ cam đều và thịt chín chắc hoàn toàn thì vớt ra ngay, để thật ráo và nguội hẳn.', 'Không luộc tôm quá lâu và để tôm nguội ráo trước khi trộn sẽ giúp thịt tôm giòn ngọt mà không làm ỉu gỏi.', 2),
('imp-cc62ea4de6a7436b_v4_step_3', 'imp-cc62ea4de6a7436b', 3, 'sauce', 'Pha nước trộn gỏi chua cay mặn ngọt', 'Vắt nước cốt từ 1,5 quả chanh tươi lọc bỏ hạt cho vào chén, thêm 30 ml nước mắm ngon và 12 g đường cát trắng, khuấy đều tay đến khi đường tan hết hoàn toàn tạo hỗn hợp nước trộn sánh thơm.', NULL, NULL),
('imp-cc62ea4de6a7436b_v4_step_4', 'imp-cc62ea4de6a7436b', 4, 'cook', 'Trộn nhẹ tay dứa, tôm cùng hành ớt', 'Cho dứa cắt miếng, tôm luộc đã nguội, hành tím thái lát, hành lá và ớt hiểm vào tô lớn. Rưới đều toàn bộ chén nước trộn gỏi lên trên, đảo nhẹ tay từ dưới lên để tất cả nguyên liệu áo đều gia vị.', NULL, NULL),
('imp-cc62ea4de6a7436b_v4_step_5', 'imp-cc62ea4de6a7436b', 5, 'finish', 'Để gỏi nghỉ ngấm vị trong 5 phút', 'Để tô gỏi nghỉ 5 phút cho miếng dứa và tôm thấm sâu vị chua mặn ngọt cay hài hòa rồi nếm thử lại một lần, điều chỉnh thêm nước cốt chanh hoặc nước mắm nếu cần.', 'Chỉ nên cho đậu phộng rang và lá bạc hà vào ngay trước lúc ăn để đậu không bị ỉu và lá rau không bị thâm.', 5),
('imp-cc62ea4de6a7436b_v4_step_6', 'imp-cc62ea4de6a7436b', 6, 'finish', 'Rắc đậu phộng rang, bạc hà và dọn mát', 'Gắp gỏi dứa tôm ra đĩa (chắt bớt nước đọng đáy tô nếu nhiều), rắc 45 g đậu phộng rang giã dập và lá bạc hà xắt rối lên trên rồi thưởng thức ngay khi còn tươi mát.', NULL, NULL),
('imp-3d7573766352454e_v4_step_1', 'imp-3d7573766352454e', 1, 'prep', 'Sơ chế thịt gà, nấm và nhóm thảo mộc', 'Cắt 380 g thịt đùi gà rút xương thành miếng vuông 2,5–3 cm. Thái lát dày 0,5 cm phần 200 g nấm đùi gà, bổ múi cau nhỏ 1 quả cà chua và thái nhỏ 3/4 bó hành lá. Đập dập cắt khúc 5 cm phần 3 cây sả, thái lát mỏng 30 g củ riềng, vò nhẹ xé bỏ gân 6 g lá chanh Thái, đập dập 1/2 củ tỏi và 4 quả ớt hiểm. Ngâm 30 g me chín với chút nước ấm lọc bỏ hạt lấy nước cốt.', NULL, NULL),
('imp-3d7573766352454e_v4_step_2', 'imp-3d7573766352454e', 2, 'cook', 'Áp chảo xém cạnh hành tím tạo hương thơm khói', 'Bổ đôi 35 g hành tím theo chiều dọc, đặt úp mặt cắt xuống nồi hoặc chảo khô nóng trên lửa vừa khoảng 3 phút đến khi mặt cắt hành xém nâu nhẹ và tỏa mùi thơm ngọt đặc trưng.', 'Áp chảo hành tím cho xém cạnh trước khi hầm giúp nước dùng canh gà có chiều sâu hương vị thơm dịu rất riêng.', 3),
('imp-3d7573766352454e_v4_step_3', 'imp-3d7573766352454e', 3, 'cook', 'Hầm mềm thịt đùi gà với nước dùng gà', 'Đổ 960 ml nước dùng gà vào nồi đun sôi lăn tăn, thả thịt đùi gà cùng 30 ml nước mắm ngon vào hạ lửa nhỏ vừa, hầm khoảng 12 phút và hớt bọt thường xuyên cho thịt gà chín mềm hoàn toàn và nước dùng trong ngọt.', NULL, 12),
('imp-3d7573766352454e_v4_step_4', 'imp-3d7573766352454e', 4, 'cook', 'Nấu thảo mộc thơm nồng cùng hành tím nướng', 'Thả hành tím áp chảo, sả, củ riềng, lá chanh Thái, tỏi và ớt hiểm đập dập vào nồi canh đang sôi lăn tăn, nấu tiếp 5 phút cho các loại thảo mộc tiết hết tinh dầu thơm vào nước dùng.', 'Giữ lửa sôi nhẹ để tinh dầu sả, riềng và lá chanh lan tỏa từ từ mà không làm đục nước canh.', 5),
('imp-3d7573766352454e_v4_step_5', 'imp-3d7573766352454e', 5, 'cook', 'Nấu nấm đùi gà, cà chua và nước cốt me', 'Rót nước cốt me đã lọc cùng 200 g nấm đùi gà, cà chua bổ múi cau, 15 ml nước mắm ngon còn lại và 5 g đường cát trắng vào nồi. Đun sôi nhẹ thêm 4 phút đến khi nấm chín giòn ngọt và cà chua vừa mềm mà chưa nát.', NULL, 4),
('imp-3d7573766352454e_v4_step_6', 'imp-3d7573766352454e', 6, 'finish', 'Tắt bếp thêm nước cốt chanh và hành lá', 'Tắt bếp chờ nước canh ngừng sôi hẳn mới rót nước cốt từ 1,5 quả chanh tươi vào khuấy đều, nếm chỉnh vị chua cay mặn ngọt cân bằng rồi múc ra tô, rắc hành lá thái nhỏ lên trên và dùng nóng.', 'Kết hợp vị chua trầm của me chín và vị chua sáng của chanh tươi sau khi tắt bếp giúp canh thơm thanh mà không bị gắt.', NULL),
('imp-88fc351665d5e9fc_v4_step_1', 'imp-88fc351665d5e9fc', 1, 'prep', 'Sơ chế thịt thăn bò và ngâm nở mộc nhĩ', 'Ngâm 15 g mộc nhĩ khô trong nước ấm khoảng 15 phút cho nở mềm, cắt bỏ chân nấm rồi thái miếng vừa ăn. Thấm khô 300 g thịt thăn bò bằng khăn giấy, dùng dao sắc thái lát mỏng 2–3 mm ngang thớ để thịt mềm không bị dai.', 'Đặt miếng thịt bò vào ngăn đá tủ lạnh khoảng 20 phút cho hơi se cứng trước khi thái sẽ giúp cắt được những lát thịt mỏng đều rất dễ dàng.', 15),
('imp-88fc351665d5e9fc_v4_step_2', 'imp-88fc351665d5e9fc', 2, 'prep', 'Cắt thái rau củ và chuẩn bị hương liệu', 'Rửa sạch ớt chuông, bỏ hạt và thái miếng xéo vừa ăn. Hành tây bóc vỏ bổ múi cau mỏng; ớt hiểm rửa sạch, bỏ cuống rồi thái lát xéo; tỏi khô bóc vỏ băm nhỏ; hành lá rửa sạch cắt khúc 3–4 cm để riêng.', NULL, NULL),
('imp-88fc351665d5e9fc_v4_step_3', 'imp-88fc351665d5e9fc', 3, 'sauce', 'Pha chén sốt dầu hào và nước bột bắp', 'Trong chén nhỏ, hòa tan hoàn toàn 8 g bột bắp với 45 ml nước lọc cho hết vón cục. Ở một chén khác, trộn đều 30 ml dầu hào, 15 ml xì dầu nhạt, 5 ml xì dầu đặc, 5 ml nước mắm, 5 g đường cát trắng và 1,5 g tiêu trắng xay.', 'Pha sẵn nước bột bắp và chén sốt gia vị trước khi bật bếp vì thao tác xào lửa lớn diễn ra rất nhanh, tránh để thịt bị quá lửa.', NULL),
('imp-88fc351665d5e9fc_v4_step_4', 'imp-88fc351665d5e9fc', 4, 'cook', 'Áp chảo xém mặt thịt bò trên lửa lớn', 'Đặt chảo đáy rộng lên bếp, đun nóng 20 ml dầu ăn trên lửa lớn đến khi dầu hơi gợn sóng. Dàn đều thịt thăn bò thành một lớp mỏng, áp chảo khoảng 2 phút cho hai mặt xém nâu nhẹ và thịt gần chín tới thì gắp nhanh ra đĩa.', 'Không đổ dồn quá nhiều thịt chồng lên nhau khiến nhiệt chảo giảm đột ngột, thịt dễ bị ra nước và dai thay vì cháy cạnh thơm ngon.', 2),
('imp-88fc351665d5e9fc_v4_step_5', 'imp-88fc351665d5e9fc', 5, 'cook', 'Phi thơm tỏi ớt và nấu sánh phần sốt', 'Hạ lửa vừa, thêm 10 ml dầu ăn còn lại vào chảo, cho tỏi băm và ớt hiểm vào đảo thơm 30 giây đến khi tỏi dậy mùi vàng nhẹ. Khuấy đều chén nước bột bắp rồi rưới vào cùng hỗn hợp dầu hào, xì dầu nhạt, xì dầu đặc, nước mắm, đường và tiêu trắng, đun sôi nhẹ 1 phút cho sốt sánh bóng.', NULL, 1),
('imp-88fc351665d5e9fc_v4_step_6', 'imp-88fc351665d5e9fc', 6, 'cook', 'Xào nhanh rau củ và đảo quyện thịt bò', 'Vặn lại lửa lớn, cho ớt chuông, hành tây và mộc nhĩ vào đảo nhanh tay 1–2 phút đến khi rau củ vừa chín tới vẫn giữ được độ giòn ngọt. Nếu sốt quá đặc, rưới thêm 60 ml nước dùng gà để điều chỉnh độ sánh vừa ý, rồi trút thịt bò vào đảo đều 30 giây cho thịt chín hoàn toàn và áo bóng sốt.', NULL, NULL),
('imp-88fc351665d5e9fc_v4_step_7', 'imp-88fc351665d5e9fc', 7, 'finish', 'Rắc hành lá và trình bày ra đĩa', 'Thả hành lá cắt khúc vào chảo, đảo thêm 15 giây cho hành vừa chín xanh mướt rồi tắt bếp ngay. Múc bò xào ớt ra đĩa sâu lòng cùng phần sốt sánh đậm và thưởng thức ngay khi còn nóng với cơm trắng.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-4ec49419e966f676_v4_step_1', 'imp-4ec49419e966f676', 1, 'prep', 'Làm sạch cá giữ nguyên vảy và thấm thật khô', 'Giữ nguyên lớp vảy ngoài của 2 con cá diêu hồng và chỉ móc bỏ ruột, mang qua đường mang cá để bụng cá kín hoàn toàn. Rửa sạch máu đọng bên trong dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô cả trong bụng lẫn ngoài da cá.', 'Việc giữ nguyên vảy và không mổ phanh bụng giúp lớp muối không thấm mặn vào thịt cá mà chỉ tạo lớp vỏ giữ ẩm kín hơi khi nướng.', NULL),
('imp-4ec49419e966f676_v4_step_2', 'imp-4ec49419e966f676', 2, 'prep', 'Nhồi sả và lá chanh Kaffir vào bụng cá', 'Dùng sống dao đập dập 5 cây sả tươi cho dập tơi sợi, gập đôi lại. Vò nhẹ 10 g lá chanh Kaffir cho dậy tinh dầu thơm rồi nhồi đều sả và lá chanh qua miệng vào bên trong bụng cả 2 con cá, nhồi vừa tay tránh làm rách thịt cá.', NULL, NULL),
('imp-4ec49419e966f676_v4_step_3', 'imp-4ec49419e966f676', 3, 'marinate', 'Trộn vữa muối bột mì và trát kín thân cá', 'Cho 250 g muối hạt vào tô lớn cùng 16 g bột mì đa dụng và 15 ml nước lọc, bóp trộn đều đến khi muối hơi ẩm kết dính như cát ướt. Đặt từng con cá lên mặt phẳng rồi dùng tay trát và miết đều hỗn hợp muối phủ kín hai mặt thân cá từ đầu đến đuôi.', 'Bột mì và một chút nước giúp các hạt muối bám chắc thành lớp áo dày, không bị rơi rụng khi lật cá trên vỉ nướng.', NULL),
('imp-4ec49419e966f676_v4_step_4', 'imp-4ec49419e966f676', 4, 'cook', 'Nướng cá trên lửa than hồng hoặc lò nướng 200°C', 'Nhóm bếp than hoa lửa vừa ổn định (hoặc làm nóng trước lò nướng/nồi chiên ở 200°C). Đặt cá lên vỉ nướng khoảng 20 phút cho mặt dưới se khô hẳn lớp muối rồi nhẹ nhàng lật sang mặt còn lại nướng thêm 20 phút đến khi lớp vỏ muối khô cứng ngả vàng xém và thịt cá chín trắng hoàn toàn tận xương.', 'Nên đợi ít nhất 15–20 phút cho lớp vỏ muối mặt dưới khô cứng hẳn mới lật để tránh da cá dính vào vỉ gây rách lớp muối.', 40),
('imp-4ec49419e966f676_v4_step_5', 'imp-4ec49419e966f676', 5, 'sauce', 'Giã tỏi ớt và pha sốt chấm hải sản Thái', 'Trong lúc chờ cá chín, cho 3 g muối còn lại cùng tỏi bóc vỏ và ớt hiểm vào cối giã nhuyễn vừa. Trút ra chén, thêm nước cốt của 2 quả chanh tươi, 30 ml nước mắm, 12 g đường cát trắng và 45 ml nước lọc, khuấy tan đường để có chén sốt chua cay mặn ngọt hài hòa.', NULL, 5),
('imp-4ec49419e966f676_v4_step_6', 'imp-4ec49419e966f676', 6, 'finish', 'Lột bỏ vỏ muối và dọn cá nóng cùng sốt chấm', 'Gắp cá nướng muối sả ra đĩa lớn, dùng mũi dao rạch nhẹ một đường dọc sống lưng rồi nhẹ nhàng lật bỏ toàn bộ lớp da bọc muối cứng bên ngoài để lộ phần thịt cá trắng mọng bốc khói thơm lừng mùi sả lá chanh. Dọn ăn nóng ngay kèm chén sốt chấm hải sản.', NULL, NULL),
('imp-e47b2f01ee81031a_v4_step_1', 'imp-e47b2f01ee81031a', 1, 'prep', 'Ngâm mềm sợi hủ tiếu khô và ướp tôm tươi', 'Ngâm 180 g hủ tiếu khô trong nước lạnh khoảng 30 phút đến khi sợi dẻo mềm nhưng vẫn còn độ dai nhẹ bên trong, vớt ra rổ để thật ráo. Tôm tươi bóc vỏ, rút chỉ đen, ướp với nước cốt của nửa quả chanh tươi trong 10 phút cho thịt săn và sạch mùi.', 'Ngâm sợi hủ tiếu bằng nước lạnh thay vì nước sôi giúp sợi giữ được độ dai đặc trưng, không bị nát vụn khi đảo trên chảo nóng.', 30),
('imp-e47b2f01ee81031a_v4_step_2', 'imp-e47b2f01ee81031a', 2, 'sauce', 'Lọc nước cốt me và pha sốt xào chua ngọt', 'Dằm 40 g me chín với 180 ml nước lọc ấm rồi lọc qua rây bỏ hạt lấy phần nước cốt me. Hòa vào chén nước me này 20 ml nước mắm, 20 ml xì dầu, 20 g đường cát trắng và 3 g muối ăn, khuấy tan đều đường.', NULL, NULL),
('imp-e47b2f01ee81031a_v4_step_3', 'imp-e47b2f01ee81031a', 3, 'prep', 'Sơ chế dứa, giá đỗ, hành tỏi và đậu phộng', 'Cắt dứa chín thành miếng tam giác vừa ăn; rửa giá đỗ và để ráo; băm nhỏ tỏi và phần đầu hành lá; thái khúc 2 cm phần lá xanh; giã dập 50 g đậu phộng rang; đánh tan 2 quả trứng gà trong chén.', NULL, NULL),
('imp-e47b2f01ee81031a_v4_step_4', 'imp-e47b2f01ee81031a', 4, 'cook', 'Phi thơm hành tỏi và xào săn tôm tươi', 'Làm nóng chảo rộng trên lửa vừa-lớn với 15 ml dầu ăn, cho tỏi băm và đầu hành lá vào phi thơm 30 giây. Trút tôm vào xào nhanh 2 phút đến khi tôm chuyển màu đỏ hồng săn chắc hoàn toàn thì trút riêng ra đĩa.', 'Xào tôm riêng và lấy ra trước giúp tôm chín ngọt, không bị teo dai trong lúc xào mì.', 2),
('imp-e47b2f01ee81031a_v4_step_5', 'imp-e47b2f01ee81031a', 5, 'cook', 'Xào tơi trứng gà và om mì thấm sốt me', 'Thêm 20 ml dầu ăn còn lại vào chảo, đổ trứng gà đã đánh tan vào đảo nhẹ cho trứng chín tơi thành miếng vừa. Cho hủ tiếu đã ráo và toàn bộ chén sốt me vào, đảo đều tay 3 phút trên lửa vừa đến khi sợi mì hút hết sốt và mềm dẻo bóng đẹp.', NULL, 3),
('imp-e47b2f01ee81031a_v4_step_6', 'imp-e47b2f01ee81031a', 6, 'cook', 'Đảo nhanh tôm, dứa và giá đỗ giữ độ giòn', 'Trút tôm đã xào trở lại chảo cùng dứa chín và giá đỗ, tăng lửa lớn đảo đều tay 1–2 phút cho các nguyên liệu nóng quyện đều mà dứa không bị nát ra nước, giá đỗ vẫn giòn ngọt.', 'Chỉ cho dứa và giá đỗ ở phút cuối ngay trước khi tắt bếp để giữ trọn hương thơm tươi mát và độ giòn tự nhiên.', NULL),
('imp-e47b2f01ee81031a_v4_step_7', 'imp-e47b2f01ee81031a', 7, 'finish', 'Rắc đậu phộng, hành lá và hoàn thiện món ăn', 'Tắt bếp, rắc phần hành lá xanh lên đảo nhanh một lượt rồi gắp mì ra đĩa. Phủ đậu phộng rang giã dập lên mặt, bày thêm nửa quả chanh tươi cắt múi và ít ớt bột khô bên cạnh rồi dùng nóng ngay.', NULL, NULL),
('imp-192973f6e1b702b5_v4_step_1', 'imp-192973f6e1b702b5', 1, 'prep', 'Ép ráo nước và cắt miếng đậu phụ', 'Đặt 4,5 bìa đậu phụ lên khăn sạch hoặc rổ có lót giấy thấm, chèn đĩa phẳng hoặc vật nặng nhẹ lên trên để ép bớt nước trong 15 phút. Sau đó thấm khô bề mặt rồi cắt đậu thành khối vuông cạnh khoảng 3 cm.', 'Ép đậu ráo nước giúp miếng đậu săn chắc, chiên nhanh giòn lâu và không bị nổ bắn dầu.', 15),
('imp-192973f6e1b702b5_v4_step_2', 'imp-192973f6e1b702b5', 2, 'prep', 'Sơ chế tỏi ớt, rau củ và áo bột bắp cho đậu', 'Băm nhuyễn tỏi, thái hạt lựu nhỏ hành tây, bào sợi mảnh cà rốt, thái lát ớt hiểm, cắt nhỏ ngò rí và hành lá. Cho các viên đậu phụ vào hộp lớn, rắc đều 45 g bột bắp và xóc nhẹ tay cho lớp bột mỏng bám đều quanh từng miếng đậu.', NULL, NULL),
('imp-192973f6e1b702b5_v4_step_3', 'imp-192973f6e1b702b5', 3, 'sauce', 'Phi thơm tỏi và pha nước sốt chua cay Thái', 'Trong chảo nhỏ, đun nóng 10 ml dầu ăn trên lửa vừa, phi thơm tỏi băm khoảng 30 giây rồi tắt bếp trút ra chén. Hòa tan 35 g đường thốt nốt bào nhỏ cùng 30 ml tương ớt, 35 ml xì dầu và nước cốt của 1,5 quả chanh tươi; thêm tỏi phi, hành tây, cà rốt sợi và ớt hiểm vào khuấy đều.', 'Nếm thử chén sốt để cân chỉnh vị chua cay mặn ngọt hơi đậm một chút vì đậu phụ chiên có vị nhạt thanh.', NULL),
('imp-192973f6e1b702b5_v4_step_4', 'imp-192973f6e1b702b5', 4, 'cook', 'Đun nóng dầu ăn đạt chuẩn nhiệt độ chiên', 'Đổ khoảng 390 ml dầu ăn còn lại vào chảo sâu lòng, đun trên lửa vừa-lớn đến khoảng 180°C. Thử nhiệt bằng cách nhúng đầu đũa gỗ xuống đáy chảo, thấy bọt khí nhỏ sủi đều quanh đầu đũa là dầu đã sẵn sàng.', NULL, NULL),
('imp-192973f6e1b702b5_v4_step_5', 'imp-192973f6e1b702b5', 5, 'cook', 'Chiên ngập dầu đậu phụ thành hai mẻ vàng giòn', 'Thả nhẹ từng viên đậu phụ đã áo bột bắp vào chảo dầu nóng, chia làm 2 mẻ để đậu không dính vào nhau. Chiên khoảng 4–5 phút mỗi mẻ đến khi lớp vỏ phồng nhẹ và vàng giòn đều các mặt thì vớt ra rổ lót giấy thấm dầu.', 'Không cho quá nhiều đậu cùng lúc làm tụt nhiệt độ dầu, khiến vỏ đậu hút dầu và bị ỉu nhanh.', 5),
('imp-192973f6e1b702b5_v4_step_6', 'imp-192973f6e1b702b5', 6, 'finish', 'Xếp đĩa, rưới sốt cay và rắc rau thơm', 'Xếp các khối đậu phụ chiên giòn nóng hổi lên đĩa, rưới đều phần sốt chua cay lên mặt (hoặc để sốt chấm riêng nếu muốn giữ vỏ giòn tối đa). Rắc ngò rí và hành lá cắt nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-2a705e2ff35573b1_v4_step_1', 'imp-2a705e2ff35573b1', 1, 'prep', 'Ngâm ớt khô, lọc nước cốt me và sơ chế tôm rau', 'Ngâm 8 g ớt khô trong nước ấm khoảng 10 phút cho mềm, vớt ráo bỏ hạt. Dằm 60 g me chín với 100 ml nước dùng gà ấm rồi rây bỏ hạt thu nước cốt me. Tôm tươi bóc vỏ, rút chỉ đen; cà chua bổ múi cau; nấm đùi gà thái lát dày 0,5 cm; hành lá thái nhỏ.', NULL, 10),
('imp-2a705e2ff35573b1_v4_step_2', 'imp-2a705e2ff35573b1', 2, 'prep', 'Giã nhuyễn cốt gia vị ớt hành tỏi và mắm tôm', 'Cho ớt khô đã ngâm mềm cùng 2 g muối ăn vào cối giã thật mịn, sau đó cho mắm tôm, hành tím và tỏi khô vào giã tiếp thành hỗn hợp cốt gia vị sánh nhuyễn đồng nhất.', 'Giã ớt với muối hạt trước sẽ giúp vỏ ớt nhanh nát mịn mà không bị bắn ra ngoài cối.', NULL),
('imp-2a705e2ff35573b1_v4_step_3', 'imp-2a705e2ff35573b1', 3, 'cook', 'Luộc cá phi lê và nghiền mịn tạo độ sánh nước dùng', 'Đun sôi 500 ml nước dùng gà còn lại cùng 600 ml nước lọc trong nồi, thả 80 g phi lê cá thịt trắng vào luộc khoảng 4 phút cho chín hoàn toàn. Vớt cá ra chén, dùng nĩa hoặc chày nghiền thật nhuyễn mịn rồi khuấy trở lại nồi nước dùng.', 'Nghiền mịn thịt cá vào nước dùng là bí quyết truyền thống giúp nước canh Gaeng Som có độ sánh mượt tự nhiên và vị ngọt thanh đậm đà.', 4),
('imp-2a705e2ff35573b1_v4_step_4', 'imp-2a705e2ff35573b1', 4, 'cook', 'Hòa cốt gia vị và nêm vị chua mặn ngọt cân bằng', 'Cho toàn bộ hỗn hợp cốt ớt hành tỏi đã giã vào nồi nước dùng khuấy tan đều, đun sôi nhẹ trên lửa vừa. Tiếp theo trút nước cốt me, 20 ml nước mắm và 24 g đường thốt nốt vào khuấy tan hết đường, nếm để vị chua dẫn đầu, tiếp đến mặn vừa và hậu ngọt dịu.', NULL, NULL),
('imp-2a705e2ff35573b1_v4_step_5', 'imp-2a705e2ff35573b1', 5, 'cook', 'Nấu cà chua, nấm đùi gà và thả tôm tươi', 'Thả cà chua bổ múi cau và nấm đùi gà thái lát vào nồi canh nấu sôi liu riu 4 phút cho nấm vừa chín ngọt nước. Tăng lửa vừa-lớn rồi thả tôm tươi vào nấu khoảng 1–2 phút đến khi tôm chuyển màu đỏ hồng, cong mình chín tới thì tắt bếp ngay.', 'Không đun tôm quá 2 phút sau khi nước sôi trở lại để thịt tôm giữ được độ giòn ngọt, không bị bã hay teo cứng.', 5),
('imp-2a705e2ff35573b1_v4_step_6', 'imp-2a705e2ff35573b1', 6, 'finish', 'Vắt chanh tươi, rắc hành lá ớt lát và dọn nóng', 'Vắt nước cốt của 1 quả chanh tươi vào nồi canh đã tắt bếp để dậy hương chua thanh tươi mát. Múc canh chua me tôm ra tô lớn, rắc hành lá và vài lát ớt hiểm tươi lên trên rồi dọn dùng nóng với cơm trắng.', NULL, NULL),
('imp-f050984a2c4deb91_v4_step_1', 'imp-f050984a2c4deb91', 1, 'prep', 'Sơ chế các loại nấm tươi sạch sẽ', 'Rửa nhanh 200 g nấm đùi gà và 100 g nấm mỡ qua nước muối loãng rồi thấm ráo, cắt dọc nấm đùi gà thành miếng dài vừa ăn và bổ đôi nấm mỡ. Cắt bỏ phần gốc rễ của 150 g nấm kim châm, tách thành từng chùm nhỏ vừa gắp và rửa sạch để ráo.', 'Không ngâm nấm quá lâu trong nước vì nấm sẽ hút ẩm làm giảm độ giòn ngọt khi chần và trộn gỏi.', NULL),
('imp-f050984a2c4deb91_v4_step_2', 'imp-f050984a2c4deb91', 2, 'prep', 'Thái mỏng rau củ và giã dập đậu phộng rang', 'Bóc vỏ hành tây tím và hành tây trắng, thái lát thật mỏng theo chiều ngang (có thể ngâm nước đá 5 phút rồi vắt ráo để giảm vị hăng). Rửa sạch cà chua bi bổ đôi, cần tây và hành lá cắt khúc dài 3 cm; giã dập thô 55 g đậu phộng rang.', NULL, NULL),
('imp-f050984a2c4deb91_v4_step_3', 'imp-f050984a2c4deb91', 3, 'sauce', 'Pha nước trộn gỏi chua cay mặn ngọt', 'Cho tỏi băm nhuyễn và ớt hiểm băm nhỏ vào chén, thêm 45 ml xì dầu, nước cốt của 1,5 quả chanh tươi và 15 g đường cát trắng. Khuấy đều tay đến khi đường tan hoàn toàn rồi nếm lại để đạt vị chua cay mặn ngọt cân bằng.', 'Nên pha nước trộn đậm đà hơn khẩu vị thường một chút vì nấm và cà chua sẽ tiết thêm chút nước khi trộn.', NULL),
('imp-f050984a2c4deb91_v4_step_4', 'imp-f050984a2c4deb91', 4, 'cook', 'Chần chín tới từng loại nấm trong nước muối sôi', 'Đun sôi 1000 ml nước lọc cùng 5 g muối ăn trên lửa lớn. Lần lượt chần riêng nấm mỡ khoảng 1 phút, tiếp đến nấm đùi gà 1 phút và cuối cùng là nấm kim châm 45 giây cho từng loại vừa chín tới; vớt ngay ra rổ để thật ráo và nguội hẳn.', 'Chần riêng từng loại với thời gian ngắn giúp nấm không bị nhũn nát mà vẫn giữ được độ giòn sần sật và vị ngọt tự nhiên.', 3),
('imp-f050984a2c4deb91_v4_step_5', 'imp-f050984a2c4deb91', 5, 'cook', 'Vắt nhẹ nấm và trộn cùng rau củ tươi', 'Khi nấm đã nguội và ráo hẳn nước, dùng tay bóp nhẹ cho hết nước đọng rồi cho vào tô trộn lớn cùng hành tây tím, hành tây trắng, cà chua bi, cần tây và hành lá cắt khúc, đảo sơ cho các nguyên liệu tơi đều.', NULL, 5),
('imp-f050984a2c4deb91_v4_step_6', 'imp-f050984a2c4deb91', 6, 'finish', 'Rưới nước trộn gỏi, đảo đều và rắc đậu phộng', 'Rưới từ từ chén nước trộn chua cay vào tô nấm, dùng tay đeo găng hoặc đũa trộn nhẹ nhàng để nguyên liệu thấm đều mà cà chua không bị dập. Bày gỏi ra đĩa, rắc đều 55 g đậu phộng rang giã dập lên trên và thưởng thức ngay.', 'Chỉ rưới nước trộn và đậu phộng ngay trước khi dọn lên bàn ăn để đậu phộng giữ trọn độ giòn bùi và gỏi không bị ra nước.', NULL),
('imp-8b874d97e90e00f0_v4_step_1', 'imp-8b874d97e90e00f0', 1, 'prep', 'Sơ chế đùi gà và giã tơi sả thành sợi bông', 'Rửa sạch 600 g thịt đùi gà lọc xương (xát nhẹ với 1 g muối rồi rửa lại), dùng khăn giấy thấm thật khô và cắt miếng vuông 4–5 cm. Cắt khúc phần gốc trắng của 4 cây sả tươi, đập dập rồi dùng chày giã liên tục trong cối đến khi sả tơi nhẹ thành từng sợi mảnh như bông.', 'Giã sả cho tơi sợi giúp khi chiên sả chín giòn như ruốc và bám đều quanh miếng gà thay vì bị cứng sượng.', NULL),
('imp-8b874d97e90e00f0_v4_step_2', 'imp-8b874d97e90e00f0', 2, 'marinate', 'Giã cốt gia vị ướp gà thấm đều', 'Giã nhuyễn tỏi, rễ ngò rí và 5 g tiêu đen xay thành hỗn hợp sệt thơm. Cho thịt gà vào tô lớn cùng phần sả đã giã tơi, hỗn hợp tỏi tiêu rễ ngò, 30 ml dầu hào, 15 ml nước mắm, 5 g đường cát trắng và 1 g muối còn lại; dùng tay bóp trộn đều và ướp trong ngăn mát ít nhất 30 phút.', NULL, 30),
('imp-8b874d97e90e00f0_v4_step_3', 'imp-8b874d97e90e00f0', 3, 'prep', 'Áo bột bắp và chuẩn bị lá chanh Kaffir thái chỉ', 'Rửa sạch 5 g lá chanh Kaffir, bỏ gân giữa và thái chỉ thật mảnh. Trước khi chiên, rắc đều 20 g bột bắp vào tô gà đã ướp, trộn nhẹ để lớp bột mỏng áo đều các miếng gà và sợi sả.', NULL, NULL),
('imp-8b874d97e90e00f0_v4_step_4', 'imp-8b874d97e90e00f0', 4, 'cook', 'Làm nóng dầu chiên ở nhiệt độ vừa 165°C', 'Đổ 450 ml dầu ăn vào nồi hoặc chảo sâu lòng, đun trên lửa vừa đến khi đạt khoảng 165°C (nhúng đầu đũa gỗ thấy sủi bọt lăn tăn nhẹ xung quanh). Không để dầu quá nóng bốc khói vì sả và đường trong gia vị ướp sẽ nhanh cháy sậm màu.', NULL, NULL),
('imp-8b874d97e90e00f0_v4_step_5', 'imp-8b874d97e90e00f0', 5, 'cook', 'Chiên gà cùng sợi sả vàng giòn chín đều', 'Thả gà vào chiên thành 2 mẻ vừa phải trên lửa vừa trong khoảng 5–6 phút, thỉnh thoảng đảo nhẹ để từng miếng gà chín tận lõi (không còn nước hồng khi xăm thử) và áo màu vàng nâu giòn rụm. Vớt gà và các sợi sả vàng giòn ra giá lưới cho ráo dầu.', 'Các sợi sả tơi thường chín vàng nhanh hơn thịt gà, hãy dùng vợt lưới vớt riêng những sợi sả vàng ruộm trước để tránh bị cháy đắng.', 6),
('imp-8b874d97e90e00f0_v4_step_6', 'imp-8b874d97e90e00f0', 6, 'finish', 'Xóc gà với lá chanh Kaffir và dọn kèm tương ớt', 'Cho toàn bộ gà chiên và sả chiên giòn vào tô khô, rắc lá chanh Kaffir thái chỉ vào xóc đều vài lượt để hơi nóng làm lá dậy hương thơm dịu. Bày ra đĩa, dọn nóng cùng chén tương ớt chua ngọt Thái và cơm hoặc xôi nếp.', 'Chỉ xóc lá chanh Kaffir thái chỉ sau khi vớt gà ra khỏi chảo dầu nóng để giữ được màu xanh tươi và hương thơm thanh mát.', NULL),
('imp-b95544e75512c4e8_v4_step_1', 'imp-b95544e75512c4e8', 1, 'prep', 'Chuẩn bị tỏi lát, ớt sừng và ngò tây', 'Bóc vỏ 2–3 tép tỏi tươi, bổ đôi lấy bỏ lõi xanh ở giữa cho dịu vị hăng rồi thái lát mỏng đều nhau. Rửa sạch 2 quả ớt sừng đỏ tươi, bỏ hạt nếu muốn giảm cay rồi thái lát mỏng; nhặt lá ngò tây tươi rửa sạch, thấm khô và thái nhỏ.', NULL, NULL),
('imp-b95544e75512c4e8_v4_step_2', 'imp-b95544e75512c4e8', 2, 'cook', 'Đun nước muối và luộc mì Ý non độ al dente', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 13 g muối hạt. Thả 240 g mì Ý Spaghetti khô vào luộc khoảng 7–8 phút (ít hơn 2 phút so với thời gian trên bao bì) để sợi mì còn chín tiếp khi xóc chảo. Múc giữ lại khoảng 150 ml nước luộc mì.', NULL, 8),
('imp-b95544e75512c4e8_v4_step_3', 'imp-b95544e75512c4e8', 3, 'sauce', 'Phi tỏi ớt trên lửa nhỏ với dầu ô liu', 'Đổ 45 ml dầu ô liu nguyên chất vào chảo rộng trên lửa thật nhỏ. Thả tỏi thái lát và ớt sừng vào phi từ từ khoảng 2 phút đến khi tỏi dậy mùi thơm và vừa ngả màu vàng nhạt thì nhấc chảo khỏi bếp ngay để tỏi không bị cháy đắng.', 'Có thể nghiêng nhẹ chảo cho dầu dồn về một góc để tỏi và ớt ngập đều dầu và chín vàng đồng loạt.', 2),
('imp-b95544e75512c4e8_v4_step_4', 'imp-b95544e75512c4e8', 4, 'sauce', 'Tạo nền nhũ tương dầu với nước luộc mì', 'Đặt chảo dầu tỏi ớt lên lại bếp ở lửa vừa, múc khoảng 60 ml nước luộc mì đang sôi vào chảo, đảo nhẹ để dầu và nước tinh bột sủi bọt hòa quyện bước đầu.', NULL, NULL),
('imp-b95544e75512c4e8_v4_step_5', 'imp-b95544e75512c4e8', 5, 'cook', 'Xóc mì Ý quyện sốt sánh bóng', 'Dùng kẹp gắp thẳng mì Ý Spaghetti từ nồi cho vào chảo, thêm từng ít nước luộc mì còn lại và xóc đảo liên tục trong 2 phút trên lửa vừa đến khi sợi mì chín tới hoàn toàn và được phủ lớp sốt óng mượt.', 'Gắp mì trực tiếp từ nồi sang chảo giúp tận dụng lượng nước tinh bột bám sẵn trên sợi mì để sốt sánh nhanh hơn.', 2),
('imp-b95544e75512c4e8_v4_step_6', 'imp-b95544e75512c4e8', 6, 'finish', 'Nêm lại muối, rắc ngò tây và dùng nóng', 'Nếm thử và rắc thêm phần muối hạt còn lại (khoảng 2 g) nếu cần, tắt bếp. Rắc ngò tây tươi thái nhỏ (nếu dùng) vào đảo đều lần cuối, chia mì ra 3 đĩa sâu lòng và thưởng thức ngay khi còn nóng hổi.', 'Rắc ngò tây tươi sau khi đã tắt bếp giúp giữ trọn sắc xanh tươi và hương thơm thanh mát cho đĩa mì.', NULL),
('imp-5ae4665cc17ff036_v4_step_1', 'imp-5ae4665cc17ff036', 1, 'prep', 'Sơ chế ngò tây, ớt tươi và dằm cà chua', 'Rửa sạch 12 g ngò tây tươi, thấm khô và thái nhỏ để riêng. Bỏ cuống 2 quả ớt tươi rồi thái khoanh mỏng (bỏ bớt hạt nếu ăn cay vừa); bóc vỏ 2 tép tỏi tươi, đập dập nhẹ. Trút 320 g cà chua lột vỏ đóng hộp ra tô và dùng nĩa dằm nát.', NULL, NULL),
('imp-5ae4665cc17ff036_v4_step_2', 'imp-5ae4665cc17ff036', 2, 'sauce', 'Phi thơm tỏi và ớt với dầu ô liu lửa nhỏ', 'Đặt chảo lớn lên bếp ở lửa nhỏ với 30 ml dầu ô liu nguyên chất, cho tỏi tươi và ớt tươi cắt khoanh vào đảo nhẹ khoảng 3 phút cho dầu dậy mùi cay thơm nồng mà không để tỏi cháy nâu.', 'Giữ lửa nhỏ khi phi tỏi ớt giúp tinh dầu ớt hòa tan sâu vào dầu ô liu mà không bị khét đắng.', 3),
('imp-5ae4665cc17ff036_v4_step_3', 'imp-5ae4665cc17ff036', 3, 'sauce', 'Ninh sánh sốt cà chua cay Arrabbiata', 'Trút toàn bộ cà chua dằm vào chảo, nêm 2 g muối ăn và đảo đều. Đun trên lửa vừa khoảng 15–18 phút, thỉnh thoảng khuấy đều cho sốt sánh đặc, không còn loãng nước; sau đó gắp bỏ tép tỏi ra ngoài.', 'Vớt bỏ tép tỏi sau khi sốt đã dậy hương giúp sốt Arrabbiata thanh vị và mịn đẹp.', 16),
('imp-5ae4665cc17ff036_v4_step_4', 'imp-5ae4665cc17ff036', 4, 'cook', 'Luộc mì Ý Penne đạt độ dai al dente', 'Khi sốt ninh được khoảng 10 phút, đun sôi mạnh nồi với 2,5 lít nước lọc cùng 12 g muối ăn. Thả 240 g mì Ý Penne rigate vào luộc khoảng 9–10 phút đến độ al dente, giữ lại 80 ml nước luộc mì trước khi vớt.', NULL, 10),
('imp-5ae4665cc17ff036_v4_step_5', 'imp-5ae4665cc17ff036', 5, 'cook', 'Xóc mì Penne quyện đều sốt cay', 'Cho mì Penne đã vớt thẳng vào chảo sốt cà chua cay, thêm 1–2 muỗng canh nước luộc mì nếu sốt đặc rồi xóc đảo đều tay khoảng 1–2 phút trên lửa vừa để từng ống mì bám đều sốt đỏ bóng.', 'Thêm một ít nước luộc mì giàu tinh bột giúp sốt cà chua cay bám mượt bên trong lẫn bên ngoài ống mì Penne.', 2),
('imp-5ae4665cc17ff036_v4_step_6', 'imp-5ae4665cc17ff036', 6, 'finish', 'Rắc ngò tây, phô mai Pecorino và dọn nóng', 'Tắt bếp, rắc phần lớn ngò tây tươi thái nhỏ vào đảo đều. Múc mì ra 3 đĩa sâu lòng, rắc phần ngò tây còn lại và 30 g phô mai Pecorino Romano bào lên trên nếu thích rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-9c48616208fff232_v4_step_1', 'imp-9c48616208fff232', 1, 'prep', 'Tách bông cải xanh và rang thơm hạnh nhân', 'Rửa sạch 450 g bông cải xanh tươi, chỉ tách lấy phần bông nhỏ vừa ăn (bông lớn chẻ đôi cho đều), bỏ phần cuống già. Rang 40 g hạnh nhân bóc vỏ trên chảo khô lửa vừa khoảng 1–2 phút đến khi dậy mùi thơm nhẹ rồi trút ra để riêng.', 'Rang hạnh nhân rất nhanh trên lửa vừa để giữ vị bùi ngọt mà không bị cháy đắng.', 2),
('imp-9c48616208fff232_v4_step_2', 'imp-9c48616208fff232', 2, 'cook', 'Phi tỏi và om mềm bông cải xanh', 'Cho 30 ml dầu ô liu nguyên chất vào chảo lớn, phi thơm tỏi tươi đập dập khoảng 1 phút rồi cho toàn bộ bông cải xanh vào đảo lửa lớn 2 phút cho xém cạnh nhẹ. Rót 150 ml nước lọc vào chảo, nêm 3 g muối ăn, đậy nắp om lửa nhỏ khoảng 12–15 phút đến khi bông cải chín mềm.', NULL, 14),
('imp-9c48616208fff232_v4_step_3', 'imp-9c48616208fff232', 3, 'cook', 'Luộc mì Ý Spaghetti và giữ nước tinh bột', 'Trong lúc om bông cải, đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 11 g muối ăn. Cho 240 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút đạt độ al dente; múc giữ lại 100 ml nước luộc mì trước khi vớt.', NULL, 9),
('imp-9c48616208fff232_v4_step_4', 'imp-9c48616208fff232', 4, 'sauce', 'Xay mịn sốt kem bông cải xanh hạnh nhân', 'Gắp bỏ tép tỏi ra khỏi chảo bông cải, dùng nĩa dằm nhẹ vài bông trong chảo. Múc một nửa lượng bông cải đã om cùng một nửa lượng hạnh nhân rang cho vào máy xay với 25 g phô mai Parmesan bào và 2–3 muỗng canh nước luộc mì, xay thành sốt kem xanh mịn.', 'Chia đôi bông cải giúp món mì vừa có lớp sốt kem xanh mịn bám sợi vừa còn nguyên các bông giòn mềm.', NULL),
('imp-9c48616208fff232_v4_step_5', 'imp-9c48616208fff232', 5, 'cook', 'Trộn mì Ý với sốt bông cải và bơ lạt', 'Trút mì Ý Spaghetti vào chảo bông cải, đổ toàn bộ phần sốt kem bông cải xanh vừa xay vào rồi đảo đều tay 2 phút trên lửa vừa, thêm chút nước luộc mì nếu cần cho sốt bám mượt. Tắt bếp và đảo tan 15 g bơ lạt (nếu dùng).', 'Đảo tan bơ lạt sau khi tắt bếp giúp lớp sốt rau củ thêm bóng mượt và dậy mùi thơm béo dịu.', 2),
('imp-9c48616208fff232_v4_step_6', 'imp-9c48616208fff232', 6, 'finish', 'Rắc hạnh nhân rang, ớt tươi và dọn nóng', 'Chia mì ra 3 đĩa sâu lòng, rắc phần hạnh nhân rang còn lại (đập dập nhẹ), 10 g phô mai Parmesan bào và 1 quả ớt tươi thái lát (nếu dùng) lên trên, thưởng thức nóng ngay.', NULL, NULL),
('imp-b5571547ad5d2cec_v4_step_1', 'imp-b5571547ad5d2cec', 1, 'prep', 'Sơ chế cá hồi, hành tím và chanh vàng', 'Thấm thật khô 250 g phi lê cá hồi tươi rồi cắt khối vừa ăn cỡ 2 cm. Bóc vỏ và băm nhỏ 45 g hành tím; rửa sạch và băm nhỏ 10 g ngò tây tươi; bào lấy 1 muỗng cà phê vỏ vàng chanh vàng tươi và vắt lấy khoảng 25 ml nước cốt.', NULL, NULL),
('imp-b5571547ad5d2cec_v4_step_2', 'imp-b5571547ad5d2cec', 2, 'cook', 'Luộc mì Ý và giữ nước luộc giàu tinh bột', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 10 g muối ăn. Thả 240 g mì Ý Penne vào luộc khoảng 8–9 phút (bớt 1–2 phút so với hướng dẫn bao bì) để đạt độ al dente; múc giữ lại 120 ml nước luộc mì trước khi vớt.', NULL, 9),
('imp-b5571547ad5d2cec_v4_step_3', 'imp-b5571547ad5d2cec', 3, 'sauce', 'Phi thơm hành tím và áp săn cá hồi', 'Đặt chảo lớn lên bếp ở lửa nhỏ với 30 ml dầu ô liu nguyên chất, cho hành tím băm và một nửa lượng ngò tây tươi vào đảo 3 phút đến khi hành mềm trong mà không cháy. Tăng lên lửa vừa, thả cá hồi vào đảo nhẹ tay khoảng 3 phút cho các mặt săn lại và chín đều.', 'Không đảo mạnh tay hay nấu cá hồi quá lâu để từng miếng cá giữ nguyên khối mềm ngọt.', 6),
('imp-b5571547ad5d2cec_v4_step_4', 'imp-b5571547ad5d2cec', 4, 'sauce', 'Khử rượu vang trắng và thêm nước cốt chanh', 'Rót 75 ml rượu vang trắng khô vào chảo cá hồi, đun liu riu 2 phút cho bay hơi hết mùi cồn. Tiếp theo rưới nước cốt chanh vàng cùng 2 g muối ăn và 1 g tiêu đen xay vào đảo nhẹ cho sốt hòa quyện.', 'Đun cho cồn rượu vang bay hơi hoàn toàn trước khi vắt chanh để sốt giữ được vị chua thanh dịu nhẹ.', 2),
('imp-b5571547ad5d2cec_v4_step_5', 'imp-b5571547ad5d2cec', 5, 'cook', 'Xóc mì Ý trong sốt cá hồi và đánh bóng bơ', 'Cho mì Ý đã vớt vào chảo cá hồi, rưới dần từng ít nước luộc mì và xóc đảo nhẹ tay 2 phút trên lửa vừa cho mì ngấm sốt. Tắt bếp hoàn toàn, thả 30 g bơ lạt cắt nhỏ vào đảo nhanh đến khi bơ tan chảy tạo lớp sốt sánh bóng.', 'Cho bơ lạt lạnh vào sau khi đã tắt bếp giúp sốt bơ chanh bám mượt quanh sợi mì mà không tách dầu.', 2),
('imp-b5571547ad5d2cec_v4_step_6', 'imp-b5571547ad5d2cec', 6, 'finish', 'Rắc vỏ chanh bào, ngò tây và thưởng thức nóng', 'Nếm lại gia vị cho vừa miệng, chia mì cá hồi ra 3 đĩa sâu lòng rồi rắc vỏ chanh vàng bào, phần ngò tây tươi còn lại và 0,5 g tiêu đen xay lên trên, dùng nóng ngay.', NULL, NULL),
('imp-7b5f0d33681ea7d2_v4_step_1', 'imp-7b5f0d33681ea7d2', 1, 'sauce', 'Nấu sốt cà chua húng quế sánh mịn', 'Đun nóng 30 ml dầu ô liu trong nồi nhỏ trên lửa vừa-nhỏ, cho 1 củ tỏi đập dập vào phi thơm trong 30 giây, đảo liên tục để tỏi không bị cháy đắng. Đổ 600 g cà chua nghiền đóng hộp Ý vào nồi, xé tay 10 g lá húng quế Tây thả vào, nêm 3 g muối ăn và 1 g tiêu đen xay. Đậy nắp hờ, hạ lửa nhỏ và om liu riu khoảng 20 phút cho sốt sánh dịu lại.', 'Xé lá húng quế bằng tay thay vì cắt dao giúp tinh dầu thơm giữ nguyên trong lá, đồng thời không để tỏi chuyển nâu vì sẽ làm đắng cả nồi sốt.', 20),
('imp-7b5f0d33681ea7d2_v4_step_2', 'imp-7b5f0d33681ea7d2', 2, 'prep', 'Dần mỏng và ướp ức gà', 'Rửa sạch 600 g ức gà phi lê, thấm thật khô bằng khăn giấy. Xẻ ngang mỗi miếng ức gà thành 2–3 lát dày đều nhau, đặt giữa hai lớp màng bọc thực phẩm hoặc giấy nến rồi dùng búa dần thịt đập nhẹ đến độ dày khoảng 0,5 cm. Rắc đều 3 g muối ăn và 1 g tiêu đen xay lên cả hai mặt lát gà.', 'Dần đều độ dày giúp các miếng gà chín đồng thời khi chiên, giữ được độ mọng nước bên trong mà lớp vỏ không bị cháy.', NULL),
('imp-7b5f0d33681ea7d2_v4_step_3', 'imp-7b5f0d33681ea7d2', 3, 'prep', 'Chuẩn bị ba đĩa áo bột tẩm gà', 'Bày sẵn 3 đĩa sâu lòng: đĩa thứ nhất đựng 100 g bột mì đa dụng; đĩa thứ hai đập 2 quả trứng gà đánh tan đều cùng nước cốt 1/2 quả chanh vàng; đĩa thứ ba trộn đều 120 g bột chiên xù với 40 g phô mai Pecorino Romano bào mịn và một nửa lượng ngò tây băm (5 g). Lần lượt áo từng lát gà qua bột mì rồi giũ sạch bột thừa, nhúng qua trứng rồi lăn đều vào đĩa bột chiên xù, ấn nhẹ tay cho bột bám chặt hai mặt.', 'Để phần trứng thừa rỏ bớt trước khi đặt vào đĩa bột chiên xù giúp lớp áo bám khít, không bị vón cục và bong tróc khi chiên.', NULL),
('imp-7b5f0d33681ea7d2_v4_step_4', 'imp-7b5f0d33681ea7d2', 4, 'cook', 'Chiên vàng giòn từng lát gà', 'Đổ 100 ml dầu ăn vào chảo rộng đáy dày, đun nóng trên lửa vừa đến khi thả thử vài vụn bột chiên xù thấy sủi bọt xèo mạnh. Đặt các lát gà đã tẩm bột vào chiên mỗi mặt khoảng 2 phút đến khi lớp vỏ chuyển màu vàng ruộm giòn tan và thịt gà bên trong chín trắng hoàn toàn (nhiệt tâm đạt 74°C). Gắp gà ra đĩa có lót giấy thấm dầu và đặt thêm tờ giấy lên mặt để hút bớt dầu thừa.', 'Chỉ lật gà đúng một lần trong quá trình chiên và để gà nghỉ trên giấy thấm dầu 2 phút để lớp vỏ giữ được độ giòn rụm tối đa.', 4),
('imp-7b5f0d33681ea7d2_v4_step_5', 'imp-7b5f0d33681ea7d2', 5, 'cook', 'Xếp gà cùng sốt cà chua và phô mai Mozzarella', 'Làm nóng lò nướng trước ở chế độ lửa trên 220°C. Múc 2 muôi sốt cà chua đã nấu trải đều xuống đáy khay nướng chịu nhiệt, xếp các lát gà chiên giòn lên trên, tiếp tục múc thêm sốt cà chua phủ đều mặt từng miếng gà. Xé 250 g phô mai Mozzarella tươi đã thấm ráo nước phủ kín lên trên và rắc phần ngò tây băm còn lại (5 g).', 'Nhớ thấm ráo nước của phô mai Mozzarella tươi trước khi xếp lên khay để nước phô mai không chảy ra làm ướt lớp vỏ giòn hay cháy khét thành khay.', NULL),
('imp-7b5f0d33681ea7d2_v4_step_6', 'imp-7b5f0d33681ea7d2', 6, 'finish', 'Nướng chảy phô mai và dọn nóng', 'Đặt khay gà vào rãnh trên của lò nướng trong khoảng 3–4 phút ở 220°C đến khi phô mai Mozzarella tan chảy hoàn toàn, sủi bọt nhẹ và hơi xém vàng ở mép. Lấy khay ra, nghỉ 2 phút rồi dọn nóng ngay ra đĩa ấm.', NULL, 4),
('imp-e3df53f1154592bc_v4_step_1', 'imp-e3df53f1154592bc', 1, 'prep', 'Làm nóng lò và sơ chế phi lê cá', 'Bật lò nướng làm nóng trước ở 200°C chế độ hai lửa trên-dưới trong 10 phút. Rửa nhanh 600 g phi lê cá thịt trắng dưới vòi nước lạnh, dùng nhíp kiểm tra gắp hết xương dăm dọc thớ thịt rồi thấm thật khô bề mặt cá bằng khăn giấy.', 'Thấm thật khô miếng cá giúp nước ướp và lớp vụn bánh mì bám chắc, đồng thời mặt cá khi nướng lên màu vàng đẹp mà không bị ra nước đục.', 10),
('imp-e3df53f1154592bc_v4_step_2', 'imp-e3df53f1154592bc', 2, 'marinate', 'Pha nước sốt chanh tỏi và ướp cá', 'Trong chén nhỏ, khuấy đều 30 ml dầu ô liu, nước cốt 1/2 quả chanh vàng, 1/2 lượng tỏi băm nhuyễn, 6 g ngò tây băm, 3 g muối ăn và 1 g tiêu đen xay. Xếp 4 miếng cá vào đĩa sâu, phết đều hỗn hợp lên hai mặt và để ướp khoảng 15 phút ở nhiệt độ phòng cho thấm vị.', 'Không ướp cá với nước cốt chanh quá 20 phút vì lượng axit tự nhiên có thể làm bề mặt thịt cá bị tái bở trước khi nướng.', 15),
('imp-e3df53f1154592bc_v4_step_3', 'imp-e3df53f1154592bc', 3, 'prep', 'Chuẩn bị cà chua và hỗn hợp vụn bánh mì thảo mộc', 'Cà chua chín rửa sạch, bổ đôi hoặc bổ múi cau vừa ăn; nửa quả chanh vàng còn lại thái lát mỏng. Trong bát riêng, trộn tơi 30 g bột chiên xù cùng phần tỏi băm còn lại, 6 g ngò tây băm và 15 ml dầu ô liu.', NULL, NULL),
('imp-e3df53f1154592bc_v4_step_4', 'imp-e3df53f1154592bc', 4, 'cook', 'Xếp cá cùng cà chua lên khay nướng', 'Phết đều 10 ml dầu ô liu còn lại lên đáy khay nướng chống dính (hoặc lót giấy nến). Đặt 4 khúc cá đã ướp vào giữa khay, xếp cà chua xen kẽ xung quanh, rắc 3 g muối ăn và 1 g tiêu đen xay còn lại lên cá và cà chua. Phủ đều hỗn hợp bột chiên xù thảo mộc lên kín mặt trên từng miếng cá.', NULL, NULL),
('imp-e3df53f1154592bc_v4_step_5', 'imp-e3df53f1154592bc', 5, 'cook', 'Nướng lò đến khi cá chín mọng, mặt vàng giòn', 'Đặt khay vào ngăn giữa lò nướng ở 200°C, nướng khoảng 15–18 phút. Khoảng 5 phút cuối, đặt thêm các lát chanh vàng mỏng lên mặt cá và nướng tiếp đến khi lớp vụn bánh mì chuyển vàng giòn, cà chua mềm nhừ tiết nước ngọt và thớ cá chuyển trắng đục hoàn toàn, dễ tách nhẹ bằng nĩa.', 'Canh chừng trong 5 phút cuối để cá vừa chín tới giữ độ mọng nước ngọt thịt, tránh nướng quá lâu làm phi lê cá bị khô xác.', 18),
('imp-e3df53f1154592bc_v4_step_6', 'imp-e3df53f1154592bc', 6, 'finish', 'Nghỉ cá và rưới nước sốt cà chua', 'Lấy khay cá ra khỏi lò, để cá nghỉ 3 phút cho phần nước ngọt ổn định bên trong thớ thịt. Chuyển cá và cà chua ra đĩa ấm, rưới phần nước sốt cà chua đọng dưới khay lên trên và rắc nốt 4 g ngò tây tươi băm nhỏ để hoàn thiện.', NULL, NULL),
('imp-a0ed6c762f7dceba_v4_step_1', 'imp-a0ed6c762f7dceba', 1, 'prep', 'Dần mỏng và thấm khô thịt thăn bò', 'Dùng mũi dao khía vài đường ngắn dọc viền gân mỡ để các lát thịt thăn bò không bị cong rút khi nấu. Đặt 500 g thịt bò thái lát lên một tờ giấy nến, phủ thêm tờ giấy nữa lên trên rồi dần nhẹ tay đến khi thịt đạt độ dày đều khoảng 3–4 mm mà không bị rách nát; thấm khô bề mặt thịt.', 'Không ướp muối trực tiếp lên thịt bò sống trước khi cho vào sốt vì muối sẽ kéo nước ra làm thịt dễ bị dai và sậm màu.', NULL),
('imp-a0ed6c762f7dceba_v4_step_2', 'imp-a0ed6c762f7dceba', 2, 'sauce', 'Phi thơm tỏi với dầu ô liu', 'Bóc vỏ, đập dập 3 tép tỏi. Đun nóng 30 ml dầu ô liu trong chảo rộng trên lửa vừa, thả tỏi đập dập vào phi khoảng 2 phút đến khi dậy mùi thơm dịu và tỏi vừa chuyển vàng nhẹ.', 'Giữ nhiệt vừa và đảo liên tục để tỏi không bị cháy khét vì tỏi cháy sẽ làm đắng toàn bộ phần sốt cà chua.', 2),
('imp-a0ed6c762f7dceba_v4_step_3', 'imp-a0ed6c762f7dceba', 3, 'sauce', 'Ninh sốt cà chua sánh vị', 'Đổ 350 g cà chua nghiền đóng hộp Ý vào chảo, dùng 50 ml nước lọc tráng sạch phần cà chua còn sót rồi rót vào cùng. Đun sôi nhẹ rồi hạ lửa nhỏ, om liu riu khoảng 15 phút và thỉnh thoảng khuấy đều cho sốt bay bớt hơi nước, sánh mịn và dịu vị chua.', NULL, 15),
('imp-a0ed6c762f7dceba_v4_step_4', 'imp-a0ed6c762f7dceba', 4, 'sauce', 'Nêm gia vị và lá Oregano', 'Khi sốt đã cạn sánh vừa ý, rắc 2 g lá Oregano khô, 5 g muối ăn và 2 g tiêu đen xay vào chảo, khuấy đều cho gia vị tan hoàn toàn rồi gắp bỏ các tép tỏi đã phi thơm.', 'Nêm lá Oregano vào bước sốt đã sánh giúp tinh dầu thảo mộc không bị bay hơi mất mùi và giữ được hương vị hài hòa, không át mất vị ngọt của thịt bò.', NULL),
('imp-a0ed6c762f7dceba_v4_step_5', 'imp-a0ed6c762f7dceba', 5, 'cook', 'Om nhanh các lát thịt bò trong sốt nóng', 'Xếp từng lát thịt bò đã dần mỏng vào chảo sao cho mặt thịt ngập đều trong lớp sốt (nếu lát quá lớn có thể cắt đôi). Giữ sốt sôi liu riu ở lửa vừa, nấu mỗi mặt khoảng 2 phút rồi lật mặt còn lại nấu thêm 2 phút đến khi thịt bò chín mềm vừa đủ và thấm đẫm sốt.', 'Do lát thịt đã được dần mỏng 3–4 mm nên thịt chín rất nhanh; tránh đun quá lâu hoặc để lửa quá lớn khiến thớ thịt bò bị co rút và dai.', 4),
('imp-a0ed6c762f7dceba_v4_step_6', 'imp-a0ed6c762f7dceba', 6, 'finish', 'Hoàn thiện và thưởng thức nóng', 'Kiểm tra thịt bò đã chín đều, nêm nếm lại sốt một lần cuối cho vừa miệng rồi tắt bếp. Xếp thịt ra đĩa sâu lòng, rưới đẫm phần sốt cà chua sánh đỏ lên trên và trang trí bằng vài lá húng quế Tây tươi trước khi dọn nóng.', NULL, NULL),
('imp-2865ee57783628d7_v4_step_1', 'imp-2865ee57783628d7', 1, 'cook', 'Luộc mì xoắn Fusilli chín tới và làm nguội', 'Đun sôi mạnh 2000 ml nước lọc cùng 12 g muối ăn, thả 200 g mì Ý xoắn vào luộc khoảng 8–9 phút theo hướng dẫn bao bì để sợi mì đạt độ chín vừa tới (al dente). Vớt mì ra rổ, xả ngay dưới vòi nước lạnh cho nguội hoàn toàn và để ráo nước trong 5 phút.', 'Không luộc mì quá mềm vì sau khi trộn nước sốt mì sẽ tiếp tục hút ẩm; phải để mì thật ráo nước để nước sốt không bị loãng nhạt.', 9),
('imp-2865ee57783628d7_v4_step_2', 'imp-2865ee57783628d7', 2, 'prep', 'Sơ chế rau củ và phô mai Feta', 'Cà chua rửa sạch, bổ đôi hoặc cắt miếng hạt lựu; dưa leo tươi bổ dọc, dùng thìa nạo bỏ phần ruột mềm để salad không bị chảy nước rồi cắt hạt lựu 1 cm. Hành tây tím thái lát thật mỏng, lá húng quế Tây xé nhỏ và phô mai Feta cắt khối vuông 1,5 cm.', 'Nạo bỏ ruột dưa leo và thái hành tây tím thật mỏng giúp món salad giữ được độ giòn tươi lâu và không bị hăng gắt.', NULL),
('imp-2865ee57783628d7_v4_step_3', 'imp-2865ee57783628d7', 3, 'sauce', 'Pha nước sốt dầu ô liu chanh vàng', 'Cho 25 ml dầu ô liu, nước cốt 1/2 quả chanh vàng, 2 g lá Oregano khô, 3 g muối ăn còn lại và 1 g tiêu đen xay vào chén nhỏ. Dùng nĩa hoặc phới lồng nhỏ đánh đều tay khoảng 30 giây đến khi hỗn hợp hơi sánh quyện.', NULL, NULL),
('imp-2865ee57783628d7_v4_step_4', 'imp-2865ee57783628d7', 4, 'finish', 'Trộn mì với nước sốt và rau củ', 'Cho toàn bộ mì Ý xoắn đã ráo hẳn nước vào tô trộn lớn, rưới đều nước sốt dầu ô liu chanh vàng lên trên và trộn kỹ để từng vòng xoắn mì áo đều gia vị. Tiếp tục cho cà chua, dưa leo tươi và hành tây tím vào đảo nhẹ nhàng.', NULL, NULL),
('imp-2865ee57783628d7_v4_step_5', 'imp-2865ee57783628d7', 5, 'finish', 'Thêm phô mai Feta và ủ mát', 'Nhẹ tay cho 150 g phô mai Feta cắt khối cùng một nửa lượng lá húng quế Tây (5 g) vào tô, đảo thật nhẹ để khối phô mai giữ nguyên hình dáng. Đậy kín tô và đặt vào ngăn mát tủ lạnh khoảng 30 phút cho salad thấm vị mát lạnh.', 'Phô mai Feta vốn có vị mặn sẵn nên hãy nếm thử sau khi trộn rồi mới điều chỉnh thêm muối hoặc nước cốt chanh nếu cần.', 30),
('imp-2865ee57783628d7_v4_step_6', 'imp-2865ee57783628d7', 6, 'finish', 'Trình bày và thưởng thức lạnh', 'Lấy tô salad ra khỏi tủ lạnh, đảo nhẹ lại một lượt, chia ra đĩa và rắc nốt 5 g lá húng quế Tây còn lại lên trên mặt trước khi dọn lạnh.', NULL, NULL),
('imp-f9481ae10c0cc62a_v4_step_1', 'imp-f9481ae10c0cc62a', 1, 'cook', 'Nấu mềm cà chua cùng bơ và húng quế', 'Rửa sạch 6 quả cà chua chín đỏ, bổ múi cau. Đun chảy 15 g bơ lạt trong nồi ở lửa vừa, cho cà chua cùng 6 g lá húng quế Tây vào đảo đều, hạ lửa nhỏ và nấu khoảng 10 phút đến khi cà chua mềm rục, tiết hết nước ngọt.', NULL, 10),
('imp-f9481ae10c0cc62a_v4_step_2', 'imp-f9481ae10c0cc62a', 2, 'cook', 'Xào hành tây và làm nền bột sánh', 'Trong nồi súp chính, đun chảy 20 g bơ lạt còn lại cùng 15 ml dầu ô liu ở lửa nhỏ. Cho 1 củ hành tây băm nhỏ vào xào 8 phút đến khi hành mềm trong, thêm 2 tép tỏi băm đảo thêm 1 phút cho thơm. Rắc 16 g bột mì đa dụng vào đảo đều liên tục 2 phút cho bột chín thơm mà không bị sậm màu.', 'Cho tỏi băm vào sau cùng khi hành tây gần chín mềm giúp tỏi giữ mùi thơm ngọt mà không bị cháy đắng.', 11),
('imp-f9481ae10c0cc62a_v4_step_3', 'imp-f9481ae10c0cc62a', 3, 'cook', 'Nấu sốt sữa và ninh cùng cà chua', 'Rót từ từ 450 ml sữa tươi không đường thành từng đợt nhỏ vào nồi hành tây bột mì, vừa rót vừa khuấy đều tay bằng phới lồng để hỗn hợp sánh mịn không vón cục, đun lửa vừa 5 phút. Tiếp theo đổ 500 ml nước dùng rau củ, 4 g đường cát trắng, 6 g muối ăn, 1,5 g tiêu đen xay và toàn bộ nồi cà chua đã nấu mềm vào, hạ lửa nhỏ đun liu riu thêm 12 phút.', 'Rót sữa từ từ từng chút một và khuấy đều ngay từ đầu là bí quyết để hỗn hợp bột mì tan mượt hoàn toàn.', 17),
('imp-f9481ae10c0cc62a_v4_step_4', 'imp-f9481ae10c0cc62a', 4, 'cook', 'Xay nhuyễn, lọc rây và hòa kem tươi', 'Tắt bếp, để súp nguội bớt 3 phút rồi dùng máy xay cầm tay xay thật nhuyễn, sau đó lọc hỗn hợp qua rây mịn để loại bỏ hoàn toàn vỏ và hạt cà chua. Đổ súp trở lại nồi, thêm 100 ml kem tươi nấu ăn vào khuấy đều rồi hâm ấm lại ở lửa thật nhỏ trong 2 phút, tuyệt đối không để sôi bùng.', 'Lọc súp qua rây giúp kết cấu súp sánh mịn mượt mà chuẩn nhà hàng, còn việc không đun sôi sau khi cho kem tươi giúp súp không bị tách béo lợn cợn.', NULL),
('imp-f9481ae10c0cc62a_v4_step_5', 'imp-f9481ae10c0cc62a', 5, 'cook', 'Áp chảo bánh mì hạt lựu giòn rụm', 'Cắt 2 lát bánh mì thành khối vuông nhỏ khoảng 1 cm. Làm nóng 10 ml dầu ô liu còn lại trên chảo chống dính ở lửa vừa, cho bánh mì vào đảo đều tay 4–5 phút đến khi các cạnh vàng giòn đều thì trút ra đĩa lót giấy thấm.', NULL, 5),
('imp-f9481ae10c0cc62a_v4_step_6', 'imp-f9481ae10c0cc62a', 6, 'finish', 'Múc súp nóng và trang trí', 'Nêm nếm lại súp lần cuối cho vừa miệng, múc nóng ra 4 bát sâu lòng, rắc 20 g phô mai Parmesan bào mịn lên trên và đặt các viên bánh mì áp chảo giòn cạnh bên để dùng kèm ngay khi súp còn nóng.', NULL, NULL),
('imp-e39ba043b6d1f19d_v4_step_1', 'imp-e39ba043b6d1f19d', 1, 'prep', 'Làm nóng lò và sơ chế bông cải xanh', 'Làm nóng lò nướng trước ở 200°C chế độ hai lửa trên-dưới trong 10 phút và lót giấy nến lên khay nướng rộng. Bông cải xanh tách thành từng bông vừa ăn cỡ 3–4 cm, giữ phần cuống non gọt sơ vỏ xơ rồi thái lát vừa; rửa sạch và vẩy thật ráo nước trên rổ.', 'Bông cải xanh cần thật ráo nước trước khi trộn dầu; rau còn ướt sẽ bị hấp mềm trong lò thay vì nướng xém cạnh caramel.', 10),
('imp-e39ba043b6d1f19d_v4_step_2', 'imp-e39ba043b6d1f19d', 2, 'prep', 'Thái cà rốt, hành tây và chuẩn bị tỏi', 'Cà rốt tươi gọt vỏ, thái khoanh chéo dày đều khoảng 1 cm để chín đồng bộ cùng bông cải. Hành tây bóc vỏ, bổ múi cau dày giữ nguyên chút gốc cho đỡ rời cánh; bóc vỏ 3–4 tép tỏi khô và đập dập nhẹ.', 'Để nguyên tép tỏi đập dập thay vì băm nhuyễn giúp tỏi nướng chín mềm ngọt dịu mà không bị cháy khét ở nhiệt độ cao.', NULL),
('imp-e39ba043b6d1f19d_v4_step_3', 'imp-e39ba043b6d1f19d', 3, 'marinate', 'Pha sốt dầu ô liu giấm Balsamic thảo mộc và trộn rau', 'Trong chén nhỏ, khuấy đều 45 ml dầu ô liu, 15 ml giấm Balsamic Ý, 3 g lá Oregano và hương thảo khô, 4,5 g muối ăn và 1 g tiêu đen xay. Cho toàn bộ bông cải xanh, cà rốt, hành tây và tỏi vào âu lớn, rưới sốt lên rồi dùng tay trộn đều để gia vị bám đều khắp các mặt rau củ.', NULL, NULL),
('imp-e39ba043b6d1f19d_v4_step_4', 'imp-e39ba043b6d1f19d', 4, 'cook', 'Xếp rau một lớp đều trên khay nướng', 'Trút toàn bộ rau củ đã trộn sốt ra khay có lót giấy nến, dàn đều thành một lớp duy nhất với khoảng cách thoáng giữa các miếng rau để hơi nóng lưu thông dễ dàng.', 'Không xếp rau chồng chéo lên nhau vì hơi nước tích tụ sẽ làm rau bị sũng nước thay vì chín xém giòn cạnh.', NULL),
('imp-e39ba043b6d1f19d_v4_step_5', 'imp-e39ba043b6d1f19d', 5, 'cook', 'Nướng rau ở 200°C và đảo mặt giữa chừng', 'Đặt khay vào ngăn giữa lò nướng ở 200°C trong khoảng 25–30 phút. Sau 15 phút đầu, kéo khay ra đảo nhẹ một lượt để các mặt rau vàng đều rồi nướng tiếp đến khi cà rốt mềm bùi, hành tây ngọt trong và viền bông cải xém caramel.', NULL, 28),
('imp-e39ba043b6d1f19d_v4_step_6', 'imp-e39ba043b6d1f19d', 6, 'finish', 'Rưới giấm Balsamic cuối và dọn nóng', 'Lấy khay rau nướng ra, rưới nốt 5 ml giấm Balsamic Ý còn lại lên rau khi còn nóng hổi để dậy hương chua ngọt dịu thanh, gắp rau củ ra đĩa và dọn dùng nóng hoặc ấm.', NULL, NULL),
('imp-f50c115d909f97f2_v4_step_1', 'imp-f50c115d909f97f2', 1, 'prep', 'Làm sạch và cắt thái hai loại nấm tươi', 'Cắt bỏ phần gốc bám đất của 200 g nấm đùi gà tươi và 150 g nấm rơm, ngâm nhanh trong thau nước pha 2 g muối ăn khoảng 3 phút rồi rửa lại nước sạch và vắt nhẹ cho ráo. Thái lát xéo nấm đùi gà dày 0,5 cm, bổ đôi nấm rơm để khi nấu giữ độ giòn sần sật.', 'Không ngâm nấm quá lâu trong nước vì nấm sẽ hút nhiều nước, bị nhũn và mất đi vị ngọt tự nhiên.', 3),
('imp-f50c115d909f97f2_v4_step_2', 'imp-f50c115d909f97f2', 2, 'prep', 'Sơ chế cà chua và các gia vị thơm', 'Rửa sạch 3 quả cà chua chín đỏ, bỏ cuống; thái hạt lựu 1 quả để xào lấy màu đỏ cam, 2 quả còn lại bổ múi cau. Bóc vỏ và băm nhỏ 15 g hành tím, 1/2 củ tỏi khô; thái sợi mỏng 10 g gừng tươi và cắt khúc 1,5 cm 1/2 bó hành lá (riêng đầu hành băm nhỏ).', NULL, NULL),
('imp-f50c115d909f97f2_v4_step_3', 'imp-f50c115d909f97f2', 3, 'cook', 'Phi thơm hành tỏi và xào cà chua tạo màu', 'Làm nóng nồi trên lửa vừa với 25 ml dầu ăn, cho hành tím, tỏi khô, đầu hành băm và gừng thái sợi vào phi thơm khoảng 1 phút. Trút phần cà chua thái hạt lựu cùng 1 g muối ăn vào xào đều 3 phút đến khi cà chua mềm nhuyễn, tiết nước sốt màu đỏ cam sánh nhẹ.', 'Xào kỹ phần cà chua băm trước giúp nước canh có màu đỏ tự nhiên bắt mắt mà vẫn giữ được những múi cà chua nguyên đẹp thả vào sau.', 3),
('imp-f50c115d909f97f2_v4_step_4', 'imp-f50c115d909f97f2', 4, 'cook', 'Xào săn nấm tươi dậy hương ngọt', 'Tăng nhẹ lên lửa vừa lớn, cho toàn bộ nấm đùi gà và nấm rơm vào nồi đảo đều tay khoảng 2 phút cùng cà chua xào để nấm săn bề mặt và dậy mùi thơm đặc trưng.', NULL, 2),
('imp-f50c115d909f97f2_v4_step_5', 'imp-f50c115d909f97f2', 5, 'cook', 'Đổ nước nấu sôi và nêm vị chua thanh', 'Đổ 1300 ml nước lọc vào nồi, đun lửa lớn đến khi sôi bùng rồi hạ lửa vừa, hớt sạch bọt nổi. Thả 2 quả cà chua bổ múi cau vào nấu thêm 3 phút cho nấm chín ngọt hoàn toàn. Nêm 25 ml nước mắm ngon, 2 g muối ăn còn lại, 8 g đường cát trắng và 5 ml giấm gạo cho đạt vị chua thanh ngọt dịu.', 'Nếu muốn dùng làm món canh chay thuần, bạn có thể thay nước mắm bằng nước tương ngon hoặc nước mắm chay với lượng tương đương.', 3),
('imp-f50c115d909f97f2_v4_step_6', 'imp-f50c115d909f97f2', 6, 'finish', 'Rắc hành lá, tiêu xay và dùng nóng', 'Khi cà chua múi cau vừa chín mềm không bị nát, tắt bếp ngay và thả hành lá cắt khúc vào nồi đảo nhẹ. Múc canh ra tô lớn, rắc 1 g tiêu đen xay lên mặt rồi dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-ae5b053b8361f807_v4_step_1', 'imp-ae5b053b8361f807', 1, 'prep', 'Làm sạch tôm tươi và ướp nhẹ gia vị', 'Bóc vỏ, bỏ đầu và rút sạch chỉ đen dọc lưng 350 g tôm tươi, rửa sạch rồi để ráo. Ướp tôm với 10 ml nước mắm, 2 g muối ăn, 1 g tiêu đen xay và phần đầu hành lá băm nhỏ trong 10 phút để thịt tôm săn đậm vị.', NULL, 10),
('imp-ae5b053b8361f807_v4_step_2', 'imp-ae5b053b8361f807', 2, 'prep', 'Sơ chế sả tươi, cà chua, chanh và ớt hiểm', 'Rửa sạch 3 cây sả tươi; lấy 1 cây băm thật nhuyễn, 2 cây còn lại đập dập rồi cắt khúc 5 cm. Rửa sạch 3 quả cà chua chín đỏ, bổ múi cau. Đập dập 1 quả ớt hiểm, thái lát 1 quả còn lại; vắt lấy nước cốt 1 quả chanh tươi và bỏ hết hạt; hành lá thái khúc 1,5 cm.', NULL, NULL),
('imp-ae5b053b8361f807_v4_step_3', 'imp-ae5b053b8361f807', 3, 'cook', 'Phi thơm sả băm và xào sơ cà chua', 'Đặt nồi lên bếp ở lửa vừa với 15 ml dầu ăn, cho sả băm và sả cây đập dập vào phi khoảng 1 phút đến khi dậy hương thơm nồng đặc trưng. Thêm một nửa số cà chua bổ múi cau vào đảo 2 phút cho cà hơi mềm và tiết sắc đỏ cam nhẹ.', 'Xào nhanh sả đập dập trong dầu nóng trước khi đổ nước sẽ giúp tinh dầu sả tiết ra tối đa, làm nước canh thơm lừng.', 2),
('imp-ae5b053b8361f807_v4_step_4', 'imp-ae5b053b8361f807', 4, 'cook', 'Nấu sôi nước dùng sả thơm lừng', 'Đổ 1250 ml nước lọc vào nồi, thêm 1 quả ớt hiểm đập dập rồi đun lửa lớn đến khi sôi bùng. Hạ lửa vừa nấu thêm 4 phút cho sả và ớt tiết hết hương thơm vào nước dùng, hớt sạch bọt nổi để nước canh trong veo.', 'Không đun sả quá lâu ở lửa lớn vì nước dễ bị đục; giữ sôi vừa khoảng 4 phút là đủ để nước ngấm vị sả thơm.', 4),
('imp-ae5b053b8361f807_v4_step_5', 'imp-ae5b053b8361f807', 5, 'cook', 'Thả cà chua còn lại và nấu chín tôm tươi', 'Cho nốt phần cà chua múi cau còn lại vào nồi, nêm 25 ml nước mắm ngon, 3 g muối ăn và 10 g đường cát trắng. Khi nước sôi trở lại, thả toàn bộ tôm tươi đã ướp vào nấu trên lửa vừa khoảng 3 phút đến khi tôm cong tròn, chuyển màu đỏ cam đều và thịt chín chắc hoàn toàn.', NULL, 3),
('imp-ae5b053b8361f807_v4_step_6', 'imp-ae5b053b8361f807', 6, 'finish', 'Vắt chanh tươi sau khi tắt bếp và dọn canh', 'Tắt bếp để nồi canh ngừng sôi hẳn rồi từ từ rưới nước cốt chanh tươi vào khuấy nhẹ, nếm lại vị chua cay mặn ngọt hài hòa. Thả hành lá cắt khúc và ớt hiểm thái lát lên mặt, múc canh nóng ra tô thưởng thức cùng cơm trắng.', 'Chỉ rưới nước cốt chanh khi đã tắt bếp để tránh nhiệt độ cao làm tinh dầu vỏ chanh tiết vị đắng và mất mùi thơm thanh mát.', NULL),
('imp-ac77ed3af015efd7_v4_step_1', 'imp-ac77ed3af015efd7', 1, 'prep', 'Thái lát mỏng và ướp thịt bò thăn', 'Thấm thật khô 300 g thịt bò thăn bằng khăn giấy rồi thái lát mỏng ngang thớ. Cho thịt bò vào tô, ướp với 1/2 lượng tỏi băm, đầu hành lá băm, 2 g hạt nêm, 2 g muối ăn, 1 g tiêu đen xay và 5 ml dầu ăn trong 15 phút cho thịt ngấm vị và mềm ẩm.', 'Trộn thêm chút dầu ăn vào bước ướp giúp bề mặt lát bò mềm mượt, không bị khô xơ khi gặp nước sôi.', 15),
('imp-ac77ed3af015efd7_v4_step_2', 'imp-ac77ed3af015efd7', 2, 'prep', 'Sơ chế bắp cải, cà chua và rau thơm', 'Tách rời từng lá 1/2 bắp cải trắng, rửa sạch dưới vòi nước rồi cắt miếng vuông cạnh 4 cm vừa ăn. Rửa sạch 1 quả cà chua chín, bổ múi cau; nhặt rửa sạch ngò rí và phần lá xanh hành lá rồi cắt khúc 2 cm.', NULL, NULL),
('imp-ac77ed3af015efd7_v4_step_3', 'imp-ac77ed3af015efd7', 3, 'cook', 'Phi thơm tỏi và xào tái nhanh thịt bò', 'Làm nóng nồi trên lửa lớn vừa với 10 ml dầu ăn còn lại, phi thơm phần tỏi băm còn lại khoảng 30 giây. Cho thịt bò đã ướp vào đảo nhanh tay 1 phút đến khi thịt vừa chín tái khoảng 70% thì trút ngay ra đĩa riêng.', 'Xào tái nhanh trên lửa lớn rồi vớt ra đĩa riêng giúp thịt bò thơm mùi tỏi phi mà không bị nấu quá lửa gây dai.', 1),
('imp-ac77ed3af015efd7_v4_step_4', 'imp-ac77ed3af015efd7', 4, 'cook', 'Nấu nước dùng bắp cải ngọt thanh', 'Dùng luôn nồi vừa xào thịt, cho cà chua bổ múi cau vào đảo sơ 1 phút rồi đổ 1400 ml nước lọc vào đun lửa lớn đến khi sôi bùng. Hớt sạch bọt nổi, thả toàn bộ bắp cải vào nấu trên lửa vừa khoảng 6 phút đến khi cọng bắp cải chuyển màu trong và chín mềm ngọt.', NULL, 6),
('imp-ac77ed3af015efd7_v4_step_5', 'imp-ac77ed3af015efd7', 5, 'cook', 'Nêm gia vị và thả thịt bò chín tới', 'Nêm 18 ml nước mắm ngon, 3 g hạt nêm và 4 g muối ăn vào nồi canh, khuấy nhẹ cho tan đều. Trút đĩa thịt bò xào tái cùng phần nước tiết ra vào nồi, đun sôi trở lại khoảng 30–40 giây cho thịt bò chín hoàn toàn rồi tắt bếp ngay.', 'Đổ cả phần nước ngọt tiết ra trên đĩa thịt bò vào nồi canh sẽ giúp nước dùng tăng thêm độ ngọt tự nhiên.', NULL),
('imp-ac77ed3af015efd7_v4_step_6', 'imp-ac77ed3af015efd7', 6, 'finish', 'Thêm hành ngò, tiêu xay và dùng nóng', 'Thả hành lá và ngò rí cắt khúc vào nồi đảo nhẹ một lượt, múc canh nóng ra tô lớn và rắc 0,5 g tiêu đen xay lên mặt trước khi dọn cơm.', NULL, NULL),
('imp-4ec35a6c12daa33d_v4_step_1', 'imp-4ec35a6c12daa33d', 1, 'prep', 'Làm sạch khử tanh và trụng sơ mực tươi', 'Rút bỏ túi mực, nội tạng, mắt và răng ở đầu 450 g mực tươi, lột bỏ lớp da ngoài nếu thích rồi ngâm mực với nước pha 15 ml rượu trắng trong 8 phút để khử mùi tanh, rửa sạch và khứa vảy rồng, cắt miếng vừa ăn. Trụng nhanh mực qua nồi nước sôi 1 phút rồi vớt ra để thật ráo.', 'Trụng nhanh qua nước sôi giúp mực săn giòn và hạn chế tiết quá nhiều nước loãng khi kho.', 8),
('imp-4ec35a6c12daa33d_v4_step_2', 'imp-4ec35a6c12daa33d', 2, 'marinate', 'Ướp mực cùng nước mắm và tiêu đen xay', 'Cho mực đã ráo vào tô, ướp với 25 ml nước mắm ngon, 4 g đường cát trắng, 4 g hạt nêm, 1,5 g tiêu đen xay và 1 quả ớt hiểm thái lát. Trộn đều và để 15 phút cho mực thấm gia vị.', NULL, 15),
('imp-4ec35a6c12daa33d_v4_step_3', 'imp-4ec35a6c12daa33d', 3, 'sauce', 'Thắng nước màu và phi thơm hành tỏi', 'Làm nóng nồi đất hoặc chảo với 30 ml dầu ăn và 8 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan và chuyển màu nâu cánh gián. Rót nhanh 20 ml nước lọc khuấy đều rồi cho hành tím và tỏi băm vào phi thơm 1 phút.', 'Phi hành tỏi trên lửa nhỏ sau khi hãm nước màu để hành tỏi thơm vàng mà không bị cháy đắng.', NULL),
('imp-4ec35a6c12daa33d_v4_step_4', 'imp-4ec35a6c12daa33d', 4, 'cook', 'Đảo săn mực trên lửa lớn', 'Vặn lửa lớn, trút toàn bộ mực đã ướp vào nồi đảo nhanh tay trong 3 phút cho bề mặt mực săn lại và áo đều nước màu cánh gián.', NULL, 3),
('imp-4ec35a6c12daa33d_v4_step_5', 'imp-4ec35a6c12daa33d', 5, 'cook', 'Kho liu riu đến khi nước sốt sánh sệt', 'Thêm 30 ml nước lọc còn lại vào nồi, hạ lửa nhỏ kho liu riu không đậy nắp trong 7 phút cho đến khi mực chín trắng đục hoàn toàn và nước kho rút cạn sánh bóng bám quanh từng miếng mực.', 'Không kho mực quá 10 phút vì thịt mực sẽ bị teo nhỏ, dai cứng và mất đi độ giòn ngọt tự nhiên.', 7),
('imp-4ec35a6c12daa33d_v4_step_6', 'imp-4ec35a6c12daa33d', 6, 'finish', 'Rắc hành lá, tiêu đen và dọn dùng nóng', 'Nêm lại vừa miệng, thả hành lá cắt khúc, quả ớt hiểm thái lát còn lại và 1,5 g tiêu đen xay vào đảo nhẹ rồi tắt bếp. Múc mực kho tiêu ra đĩa và dùng nóng với cơm trắng.', NULL, NULL),
('imp-01121ea953ffed76_v4_step_1', 'imp-01121ea953ffed76', 1, 'prep', 'Chần sơ sườn non và luộc bóc vỏ trứng cút', 'Rửa sạch 600 g sườn non với 2 g muối, chặt miếng vừa ăn rồi chần qua nồi nước sôi pha 3 g muối trong 3 phút để sạch bọt bẩn, vớt ra rửa lại nước lạnh và để ráo. Luộc 15 quả trứng cút trong nước sôi 7 phút rồi ngâm ngay vào thau nước lạnh 5 phút trước khi bóc sạch vỏ.', 'Ngâm trứng cút vào nước lạnh ngay sau khi luộc giúp vỏ tách dễ dàng và lòng đỏ không bị thâm xanh.', 7),
('imp-01121ea953ffed76_v4_step_2', 'imp-01121ea953ffed76', 2, 'marinate', 'Ướp sườn non với gia vị và hành tỏi băm', 'Băm nhuyễn hành tím, tỏi khô và 1 quả ớt hiểm. Cho sườn vào tô lớn, ướp cùng một nửa lượng hành tỏi băm, ớt băm, 25 ml nước mắm ngon, 10 g đường cát trắng, 3 g muối và 1 g tiêu đen xay. Trộn đều và ướp 30 phút cho sườn thấm sâu.', NULL, 30),
('imp-01121ea953ffed76_v4_step_3', 'imp-01121ea953ffed76', 3, 'sauce', 'Thắng nước màu cánh gián và xào săn sườn', 'Đun nóng 10 ml dầu ăn với 15 g đường cát trắng còn lại trong nồi đáy dày trên lửa nhỏ đến khi đường tan chuyển màu nâu cánh gián, rót nhanh 30 ml nước lọc ấm vào khuấy đều. Thêm 20 ml dầu ăn và phi thơm phần hành tím tỏi băm còn lại, rồi trút sườn vào xào săn trên lửa vừa 4 phút.', NULL, 4);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-01121ea953ffed76_v4_step_4', 'imp-01121ea953ffed76', 4, 'cook', 'Đảo nhẹ trứng cút và đổ nước dừa tươi', 'Thả 15 quả trứng cút đã bóc vỏ và 2 quả ớt hiểm nguyên trái vào nồi sườn, đảo nhẹ tay 2 phút cho trứng áo đều lớp nước màu đẹp. Rót 500 ml nước dừa tươi vào ngập mặt sườn, đun sôi bùng và hớt sạch bọt nổi.', 'Đảo nhẹ tay bằng muỗng gỗ hoặc lắc nồi khi có trứng cút để giữ trứng tròn nguyên không bị sứt mẻ.', NULL),
('imp-01121ea953ffed76_v4_step_5', 'imp-01121ea953ffed76', 5, 'cook', 'Kho liu riu cho sườn mềm và nước sánh lại', 'Hạ lửa nhỏ, đậy hé vung kho liu riu trong 30 phút cho thịt sườn mềm rệu (thêm 70 ml nước lọc ấm nếu nước dừa cạn nhanh). Mở nắp tăng lên lửa vừa kho tiếp 5 phút cùng 10 ml nước mắm còn lại đến khi nước kho rút còn khoảng một phần ba và sánh bóng.', 'Chừa lại phần nước kho sánh vừa phải ở đáy nồi để chan cơm nóng hoặc chấm rau luộc sẽ đậm vị hơn.', 30),
('imp-01121ea953ffed76_v4_step_6', 'imp-01121ea953ffed76', 6, 'finish', 'Rắc hành lá, tiêu xay và hoàn thiện món ăn', 'Nêm lại gia vị vừa khẩu vị rồi tắt bếp. Múc sườn non và trứng cút ra đĩa sâu lòng, rưới nước kho óng ả và rắc hành lá cắt nhỏ cùng 1 g tiêu đen xay còn lại lên trên để dùng nóng với cơm trắng.', NULL, NULL),
('imp-296b724137581830_v4_step_1', 'imp-296b724137581830', 1, 'prep', 'Thấm khô, cắt miếng đậu phụ và băm tỏi', 'Rửa nhẹ 4 bìa đậu phụ trắng qua nước sạch, thấm thật ráo rồi cắt thành các miếng vuông vừa ăn cỡ 3x3 cm. Bóc vỏ tỏi khô băm nhuyễn; hành lá rửa sạch thái nhỏ; ớt tươi thái lát mỏng.', 'Thấm thật khô đậu phụ trước khi cho vào chảo dầu nóng giúp đậu nhanh vàng giòn, không bị bắn dầu và không dính chảo.', NULL),
('imp-296b724137581830_v4_step_2', 'imp-296b724137581830', 2, 'cook', 'Chiên vàng đều hai mặt đậu phụ', 'Làm nóng chảo chống dính với 25 ml dầu ăn trên lửa vừa, xếp từng miếng đậu phụ vào chiên khoảng 4 phút mỗi mặt đến khi lớp vỏ ngoài phồng nhẹ và vàng đều các mặt thì gắp ra đĩa có lót giấy thấm dầu.', NULL, 8),
('imp-296b724137581830_v4_step_3', 'imp-296b724137581830', 3, 'sauce', 'Pha chén sốt nước tương tiêu đen', 'Trong chén riêng, khuấy tan 35 ml nước tương, 12 g đường cát trắng, 4 g hạt nêm chay nấm hương, 1 g tiêu đen xay và 80 ml nước lọc cho đến khi đường và hạt nêm tan hoàn toàn.', 'Pha tan trước hỗn hợp gia vị trong chén giúp khi đổ vào chảo nóng không bị vón cục và thấm đều từng miếng đậu.', NULL),
('imp-296b724137581830_v4_step_4', 'imp-296b724137581830', 4, 'cook', 'Phi thơm tỏi băm và đun sôi sốt kho', 'Chắt bớt dầu thừa trong chảo, giữ lại khoảng 10 ml dầu ăn phi thơm tỏi băm trên lửa vừa khoảng 1 phút đến khi vừa ngả vàng thơm. Đổ chén nước sốt nước tương vào chảo đun sôi nhẹ 1 phút cho gia vị hòa quyện.', NULL, NULL),
('imp-296b724137581830_v4_step_5', 'imp-296b724137581830', 5, 'cook', 'Kho nhỏ lửa cho đậu phụ ngấm sốt sánh keo', 'Xếp nhẹ nhàng đậu phụ đã chiên vàng vào chảo sốt, hạ lửa nhỏ kho liu riu trong 8 phút. Thỉnh thoảng lắc nhẹ chảo hoặc lật mặt từng miếng đậu thật nhẹ tay để đậu thấm đều gia vị và nước kho rút sánh keo lại.', 'Hạn chế dùng đũa khuấy mạnh để giữ nguyên vẹn các miếng đậu vàng giòn ngấm sốt.', 8),
('imp-296b724137581830_v4_step_6', 'imp-296b724137581830', 6, 'finish', 'Rắc tiêu đen, hành lá và dọn nóng', 'Khi nước kho đã sệt sánh bóng quanh miếng đậu, rắc 1,5 g tiêu đen xay còn lại, hành lá thái nhỏ và ớt tươi cắt lát vào đảo nhẹ rồi tắt bếp. Bày đậu phụ kho tiêu ra đĩa và ăn nóng với cơm trắng.', NULL, NULL),
('imp-54c8037962551d6b_v4_step_1', 'imp-54c8037962551d6b', 1, 'prep', 'Nhặt rửa và làm ráo hoàn toàn giá đỗ', 'Nhặt bỏ phần rễ dài và vỏ đậu đen còn sót trên giá đỗ, rửa nhẹ tay 2 lần nước sạch rồi vớt ra rổ thưa, vẩy thật ráo nước để khi xào giá không bị ra nước và nát dập.', 'Để giá đỗ thật khô ráo trước khi xào giúp món ăn giòn sần sật và không bị sũng nước dưới đáy đĩa.', NULL),
('imp-54c8037962551d6b_v4_step_2', 'imp-54c8037962551d6b', 2, 'prep', 'Chuẩn bị tỏi băm và hành lá', 'Tỏi khô bóc vỏ, đập dập rồi băm nhỏ. Hành lá rửa sạch, bỏ gốc già và cắt khúc dài khoảng 4 cm để chung một chén.', NULL, NULL),
('imp-54c8037962551d6b_v4_step_3', 'imp-54c8037962551d6b', 3, 'cook', 'Phi thơm vàng tỏi băm', 'Đặt chảo rộng lên bếp lửa vừa-lớn, đun nóng 25 ml dầu ăn rồi cho tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi vừa ngả vàng nhẹ và tỏa mùi thơm lừng.', 'Không phi tỏi quá cháy sẫm vì tỏi khét sẽ làm mất vị ngọt thanh của giá đỗ.', NULL),
('imp-54c8037962551d6b_v4_step_4', 'imp-54c8037962551d6b', 4, 'cook', 'Xào giá đỗ chớp nhoáng trên lửa lớn', 'Vặn bếp lên lửa lớn nhất, trút toàn bộ giá đỗ vào chảo dầu tỏi và đảo nhanh tay liên tục khoảng 1 phút. Rắc 5 g hạt nêm, 3 g muối ăn và rưới 8 ml nước mắm ngon, tiếp tục đảo đều thêm 1 phút cho cọng giá vừa chín tới vẫn còn căng giòn.', 'Tổng thời gian xào giá trên chảo chỉ nên từ 1,5 đến 2 phút để giữ trọn độ giòn mọng.', 2),
('imp-54c8037962551d6b_v4_step_5', 'imp-54c8037962551d6b', 5, 'cook', 'Thêm hành lá và tiêu đen xay', 'Thả hành lá cắt khúc và 1,5 g tiêu đen xay vào chảo giá đỗ, đảo nhanh tay thêm 15–20 giây cho hành vừa chín xanh rồi tắt bếp ngay.', NULL, 1),
('imp-54c8037962551d6b_v4_step_6', 'imp-54c8037962551d6b', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Gắp ngay giá đỗ xào tỏi ra đĩa phẳng để tránh hơi nóng trong chảo làm giá tiếp tục chín mềm, rưới chút nước xào thơm mùi tỏi lên mặt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-e75e90d847daa628_v4_step_1', 'imp-e75e90d847daa628', 1, 'marinate', 'Làm sạch và ướp tôm, mực tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch lưng rút chỉ đen rồi rửa sạch. Mực ống rút bỏ túi mực và nội tạng, rửa sạch và thái khoanh dày 1 cm. Cho tôm và mực vào tô ướp cùng 3 g hạt nêm, 3 g đường cát trắng và 1 g tiêu đen xay trong 15 phút.', NULL, 15),
('imp-e75e90d847daa628_v4_step_2', 'imp-e75e90d847daa628', 2, 'prep', 'Sơ chế rau củ và trụng mì trứng dai tơi', 'Cải thìa tách lá rửa sạch, cắt khúc 5 cm; cà rốt thái lát mỏng; ớt chuông bỏ hạt thái sợi; hành tây bổ múi cau; hành tím và tỏi khô băm nhỏ; hành lá và ngò rí cắt khúc. Ngâm mì trứng khô trong nước lạnh 5 phút cho mềm rồi trụng qua nước sôi 45 giây, vớt ngay ra xả nước lạnh, để thật ráo rồi trộn với 5 ml dầu ăn để sợi mì tơi bóng.', 'Xả nước lạnh ngay sau khi trụng mì và xóc với chút dầu ăn giúp sợi mì giữ độ dai và không bị bết dính khi xào.', 5),
('imp-e75e90d847daa628_v4_step_3', 'imp-e75e90d847daa628', 3, 'cook', 'Xào chín tôm và mực trên lửa lớn', 'Làm nóng 15 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa lượng tỏi và hành tím băm. Trút tôm mực đã ướp vào đảo nhanh tay 2–3 phút đến khi tôm chuyển màu đỏ cam và mực săn cuộn chín hoàn toàn thì trút riêng ra đĩa.', 'Xào riêng hải sản trên lửa lớn giúp tôm mực chín giòn ngọt mà không tiết nước làm nhão mì.', 3),
('imp-e75e90d847daa628_v4_step_4', 'imp-e75e90d847daa628', 4, 'cook', 'Xào chín tới cà rốt, ớt chuông và cải thìa', 'Dùng lại chảo, đun nóng 20 ml dầu ăn còn lại rồi phi thơm nốt hành tím và tỏi băm. Cho cà rốt và ớt chuông vào xào trước với 40 ml nước lọc, nêm 3 g hạt nêm, 3 g đường cát trắng và 2 g muối ăn khoảng 2 phút trên lửa vừa-lớn; sau đó thêm cải thìa và hành tây đảo thêm 1,5 phút cho rau vừa chín tới.', NULL, 3),
('imp-e75e90d847daa628_v4_step_5', 'imp-e75e90d847daa628', 5, 'cook', 'Đảo mì trứng quyện sốt dầu hào và hải sản', 'Cho toàn bộ mì trứng đã ráo vào chảo rau củ, rưới 15 ml dầu hào và 15 ml nước tương (xì dầu), đảo đều tay trên lửa lớn khoảng 1,5 phút cho sợi mì thấm sốt nâu bóng. Tiếp theo trút đĩa tôm mực trở lại chảo, đảo đều thêm 1 phút cho quyện đều.', 'Dùng hai chiếc đũa đảo tơi mì cùng rau và hải sản giúp sợi mì không bị đứt gãy.', NULL),
('imp-e75e90d847daa628_v4_step_6', 'imp-e75e90d847daa628', 6, 'finish', 'Thêm hành lá, ngò rí và dùng nóng', 'Thả hành lá và ngò rí cắt khúc vào đảo nhanh 15 giây rồi tắt bếp. Bày mì xào hải sản ra đĩa rộng, rắc 1 g tiêu đen xay còn lại lên trên và dùng nóng ngay.', NULL, NULL),
('imp-1e6d5d1750d3aa51_v4_step_1', 'imp-1e6d5d1750d3aa51', 1, 'marinate', 'Sơ chế và ướp thịt đùi gà với xì dầu', 'Thịt đùi gà lọc xương rửa sạch, thấm khô rồi cắt miếng vuông dày khoảng 2 cm. Cho thịt gà vào tô ướp cùng một nửa lượng tỏi băm, 15 ml nước tương (xì dầu), 3 g muối ăn, 3 g đường cát trắng và một nửa lượng tiêu đen xay, trộn đều và để thấm 15 phút.', NULL, 15),
('imp-1e6d5d1750d3aa51_v4_step_2', 'imp-1e6d5d1750d3aa51', 2, 'prep', 'Bổ múi cà chua, hành tây và cắt hành lá', 'Cà chua chín rửa sạch, bỏ cuống rồi bổ mỗi quả thành 6–8 múi cau. Hành tây bóc vỏ cắt múi cau vừa ăn. Hành lá rửa sạch, tách đầu hành trắng băm nhỏ, phần lá xanh cắt khúc 3 cm; phần tỏi còn lại băm nhỏ.', NULL, NULL),
('imp-1e6d5d1750d3aa51_v4_step_3', 'imp-1e6d5d1750d3aa51', 3, 'cook', 'Áp chảo săn vàng thịt đùi gà', 'Đun nóng 25 ml dầu ăn trong chảo rộng trên lửa vừa, phi thơm đầu hành trắng và phần tỏi băm còn lại. Trút thịt gà đã ướp vào dàn đều một lớp, tăng lên lửa lớn và xào khoảng 4–5 phút đến khi các miếng gà săn chắc và xém vàng hai mặt.', 'Dàn đều thịt gà thành một lớp để miếng gà xém vàng thơm mà không bị tiết nước hấp luộc.', 5),
('imp-1e6d5d1750d3aa51_v4_step_4', 'imp-1e6d5d1750d3aa51', 4, 'cook', 'Om thịt gà chín kỹ cùng sốt cà chua', 'Hạ xuống lửa vừa, cho toàn bộ cà chua bổ múi vào chảo đảo nhẹ 1 phút. Rót 100 ml nước lọc và 5 ml nước mắm ngon vào, đậy vung om khoảng 9–10 phút cho đến khi cà chua mềm nhừ tạo thành sốt đỏ sánh và thịt gà chín hoàn toàn tận lõi (không còn màu hồng).', 'Không om quá 12 phút để thịt đùi gà giữ độ mọng mềm và múi cà chua vẫn còn giữ dáng đẹp mắt.', 10),
('imp-1e6d5d1750d3aa51_v4_step_5', 'imp-1e6d5d1750d3aa51', 5, 'cook', 'Thêm hành tây giòn ngọt và cân chỉnh sốt', 'Mở vung, thả hành tây cắt múi cau vào đảo đều trên lửa vừa-lớn khoảng 2 phút cho hành vừa chín tái giòn ngọt. Nêm thêm 5 ml nước tương (xì dầu) và 3 g đường cát trắng còn lại sao cho sốt đạt vị chua dịu, mặn ngọt hài hòa.', 'Cho hành tây vào bước cuối giúp hành giữ được độ giòn ngọt và màu sắc tươi sáng.', NULL),
('imp-1e6d5d1750d3aa51_v4_step_6', 'imp-1e6d5d1750d3aa51', 6, 'finish', 'Hoàn thiện với hành lá và dọn nóng', 'Thả hành lá cắt khúc và phần tiêu đen xay còn lại vào chảo, đảo nhanh tay 15 giây rồi tắt bếp. Bày gà xào cà chua ra đĩa sâu lòng, rưới sốt lên trên và ăn nóng cùng cơm trắng.', NULL, NULL),
('imp-ce3c9df133ba1cd4_v4_step_1', 'imp-ce3c9df133ba1cd4', 1, 'prep', 'Sơ chế hành lá, rau răm, ớt và đánh trứng', 'Hành lá rửa sạch để ráo rồi thái nhỏ; rau răm thái rối; ớt hiểm băm nhỏ. Nếu tự làm hành phi, phi vàng giòn 20 g hành tím thái lát với 10 ml dầu ăn rồi vớt ra để riêng. Đập 3 quả trứng gà vào tô, thêm 1,5 g muối ăn và 1 g tiêu đen xay rồi đánh tan nhẹ tay cho hòa quyện.', 'Đánh trứng vừa tay, không đánh nổi bọt quá nhiều để giữ độ mềm béo tự nhiên khi áp nhiệt.', NULL),
('imp-ce3c9df133ba1cd4_v4_step_2', 'imp-ce3c9df133ba1cd4', 2, 'cook', 'Làm nóng chảo và áp giòn mặt bánh tráng', 'Đặt chảo chống dính rộng lên bếp ở lửa vừa, cho khoảng 8–10 ml dầu ăn vào tráng đều đáy chảo. Đặt 1 lá bánh tráng mỏng vào chảo, dùng xẻng ép nhẹ cho mặt bánh tiếp xúc đều với dầu nóng trong khoảng 20 giây đến khi bánh bắt đầu phồng giòn nhẹ.', NULL, NULL),
('imp-ce3c9df133ba1cd4_v4_step_3', 'imp-ce3c9df133ba1cd4', 3, 'cook', 'Trải đều trứng gà lên mặt bánh tráng nóng', 'Nhanh tay múc khoảng 1/4 phần trứng gà đã đánh đổ lên giữa bánh tráng rồi nghiêng hoặc dùng lưng muỗng dàn đều khắp bề mặt trước khi trứng kịp đông hẳn.', 'Thao tác dàn trứng cần nhanh và dứt khoát ngay khi bánh vừa ấm phồng để trứng bám chặt vào bề mặt bánh tráng.', NULL),
('imp-ce3c9df133ba1cd4_v4_step_4', 'imp-ce3c9df133ba1cd4', 4, 'cook', 'Rắc ruốc sấy, hành lá, rau răm và chiên chín trứng', 'Hạ xuống lửa nhỏ, rắc đều lên mặt trứng một phần muối ăn (hoặc muối tôm) còn lại, hành lá thái nhỏ, ruốc sấy, hành phi (nếu dùng), ớt hiểm băm và rau răm. Chiên khoảng 2–3 phút cho trứng chín đông hoàn toàn và mặt bánh dưới vàng giòn đều.', NULL, 3),
('imp-ce3c9df133ba1cd4_v4_step_5', 'imp-ce3c9df133ba1cd4', 5, 'cook', 'Gập đôi bánh và lặp lại với các lá còn lại', 'Gập đôi chiếc bánh tráng lại (hoặc giữ nguyên hình tròn tùy thích), áp thêm 30 giây cho giòn đều hai mép rồi gắp ra đặt trên giá thoáng hơi. Lặp lại thao tác với phần bánh tráng, dầu ăn và nguyên liệu còn lại.', 'Không xếp chồng các miếng bánh nóng lên nhau vì hơi nước bốc lên sẽ làm vỏ bánh tráng nhanh bị ỉu mềm.', 3),
('imp-ce3c9df133ba1cd4_v4_step_6', 'imp-ce3c9df133ba1cd4', 6, 'finish', 'Cắt miếng và thưởng thức nóng với tương ớt', 'Dùng kéo cắt bánh tráng chiên trứng thành từng miếng tam giác vừa ăn, rưới thêm tương ớt lên trên hoặc bày chén tương ớt bên cạnh và ăn ngay khi còn giòn rụm.', NULL, NULL),
('imp-1d4d9422e7f81e97_v4_step_1', 'imp-1d4d9422e7f81e97', 1, 'prep', 'Làm ngất và chà rửa sạch cua thịt nguyên con', 'Giữ nguyên dây buộc, ngâm 4 con cua thịt tươi sống vào thau nước đá lạnh khoảng 15 phút cho cua ngất hoàn toàn để không bị rụng càng khi hấp. Tháo dây buộc, dùng bàn chải chà sạch kỹ toàn bộ mai, càng, các kẽ chân và phần yếm cua dưới vòi nước chảy rồi để ráo.', 'Ngâm nước đá lạnh làm cua ngủ yên giúp tháo dây dễ dàng, giữ trọn vẹn càng chân đẹp mắt và không làm mất nước ngọt bên trong cua.', 15),
('imp-1d4d9422e7f81e97_v4_step_2', 'imp-1d4d9422e7f81e97', 2, 'prep', 'Sơ chế sả, gừng, hành tây, hành lá, ớt và rau răm', 'Bóc bẹ già 4 cây sả, đập dập cắt khúc 5 cm. Cạo vỏ 30 g gừng thái lát mỏng; hành tây bóc vỏ bổ múi cau; hành lá cắt khúc 5 cm. Thái lát xéo 2 quả ớt hiểm và băm nhỏ 1 quả còn lại; nhặt rửa sạch rau răm để ráo; cắt vài lát chanh trang trí và chuẩn bị phần chanh vắt nước cốt.', NULL, NULL),
('imp-1d4d9422e7f81e97_v4_step_3', 'imp-1d4d9422e7f81e97', 3, 'cook', 'Xếp cua ngửa bụng và hấp chín đỏ au', 'Đổ 500 ml nước lọc vào đáy nồi hấp sao cho mặt nước thấp hơn vỉ. Xếp hành tây bổ múi, sả đập dập và gừng thái lát lên mặt vỉ, đặt 4 con cua ngửa phần yếm lên trên để giữ trọn gạch và nước ngọt. Rải hành lá, 2 quả ớt hiểm thái lát cùng 6 g muối hạt lên mình cua, đậy kín nắp đun sôi rồi hạ lửa vừa hấp 18 phút.', 'Luôn đặt cua nằm ngửa bụng lên trên khi hấp để phần gạch cua và nước ngọt tự nhiên đọng lại trong mai không bị chảy xuống nồi.', 18),
('imp-1d4d9422e7f81e97_v4_step_4', 'imp-1d4d9422e7f81e97', 4, 'sauce', 'Pha muối tiêu chanh ớt chấm thịt cua', 'Trong lúc chờ cua chín, trộn đều 6 g muối hạt còn lại, 2 g tiêu đen xay, 5 g đường cát trắng và 1 quả ớt hiểm băm nhỏ trong chén, vắt nước cốt 1,5 quả chanh tươi vào khuấy tan tạo thành chén muối chấm sánh thơm.', NULL, NULL),
('imp-1d4d9422e7f81e97_v4_step_5', 'imp-1d4d9422e7f81e97', 5, 'cook', 'Kiểm tra độ chín an toàn của cua hấp', 'Mở nắp kiểm tra thấy toàn bộ vỏ mai, càng và chân cua đã chuyển màu đỏ cam tươi đều, tách thử phần yếm thấy gạch đặc sánh và thịt trắng đục chắc nịch không còn trong sống là đạt; nếu cua lớn dày mình có thể hấp thêm 3 phút cho chín hẳn.', 'Tuyệt đối không dùng cua đã chết trước khi hấp vì thịt dễ bị bở, mất vị ngọt và tiềm ẩn nguy cơ mất an toàn thực phẩm.', NULL),
('imp-1d4d9422e7f81e97_v4_step_6', 'imp-1d4d9422e7f81e97', 6, 'finish', 'Bày mâm cua hấp nóng kèm rau răm và muối chấm', 'Gắp cua ra mâm lớn, để ráo hơi nóng khoảng 2 phút cho mặt vỏ khô se, xếp kèm rau răm tươi và vài lát chanh tươi xung quanh; thưởng thức nóng ngay cùng chén muối tiêu chanh ớt.', NULL, NULL),
('imp-d3972d88e860aba9_v4_step_1', 'imp-d3972d88e860aba9', 1, 'prep', 'Làm sạch khử tanh mực ống tươi', 'Rút bỏ nang mực, túi mực và mắt, bóc sạch lớp da ngoài rồi chà rửa mực với 3 g muối ăn, xả sạch lại bằng nước lạnh và để thật ráo.', 'Chọn mực ống thân trắng bóng, thịt săn đàn hồi và không có mùi lạ để món gỏi giòn ngọt tự nhiên.', NULL),
('imp-d3972d88e860aba9_v4_step_2', 'imp-d3972d88e860aba9', 2, 'cook', 'Luộc mực vừa chín tới với gừng và thái khoanh', 'Đun sôi 800 ml nước lọc trên lửa lớn cùng 15 g gừng tươi đập dập và 2 g muối ăn. Thả mực vào luộc khoảng 3 phút đến khi thân mực săn lại, chuyển màu trắng đục chín hoàn toàn thì vớt ra ngâm nhanh vào nước nguội sạch rồi vớt ráo, thái khoanh tròn dày khoảng 1 cm.', 'Không luộc mực quá lâu vì thịt mực sẽ bị teo và dai; vớt ra ngay khi mực vừa chuyển trắng đục và săn đều.', 3),
('imp-d3972d88e860aba9_v4_step_3', 'imp-d3972d88e860aba9', 3, 'cook', 'Chần sơ hành lá và chuẩn bị rau thơm', 'Tận dụng nồi nước sôi vừa luộc mực, nhúng nhanh hành lá vào chần 15 giây rồi vớt ra ngâm nước lạnh cho giữ màu xanh và giảm vị hăng, để ráo và cắt khúc 3 cm. Nhặt rửa sạch rau răm rồi thái nhỏ, băm nhuyễn tỏi khô và 1 quả ớt hiểm, quả ớt còn lại thái lát.', NULL, NULL),
('imp-d3972d88e860aba9_v4_step_4', 'imp-d3972d88e860aba9', 4, 'sauce', 'Pha nước trộn gỏi mắm chanh tỏi ớt', 'Cho 40 ml nước mắm ngon, 25 g đường cát trắng và nước cốt 2 quả chanh tươi vào bát, khuấy tan hoàn toàn đường rồi thêm tỏi băm và ớt hiểm băm nhuyễn vào đảo đều.', NULL, NULL),
('imp-d3972d88e860aba9_v4_step_5', 'imp-d3972d88e860aba9', 5, 'prep', 'Trộn thấm khoanh mực lần đầu', 'Cho toàn bộ mực thái khoanh vào tô lớn, rưới một nửa bát nước trộn mắm chanh vào đảo đều và để yên 5 phút cho từng khoanh mực ngấm vị chua ngọt.', NULL, 5),
('imp-d3972d88e860aba9_v4_step_6', 'imp-d3972d88e860aba9', 6, 'finish', 'Trộn hành lá, rau răm và dọn ăn kèm bánh phồng', 'Cho hành lá chần cắt khúc và rau răm thái nhỏ vào tô mực, rưới nốt phần nước trộn còn lại rồi trộn nhẹ tay cho đều vị. Bày gỏi ra đĩa, trang trí vài lát ớt hiểm lên trên và dọn ăn ngay kèm bánh phồng tôm giòn rụm.', 'Chanh tươi có độ chua khác nhau tùy quả nên hãy nếm thử sau khi trộn để gia giảm nhẹ đường hoặc nước cốt chanh cho vừa miệng.', NULL),
('imp-68184b07a3c61cff_v4_step_1', 'imp-68184b07a3c61cff', 1, 'prep', 'Ngâm nấu cháo gạo nếp và sơ chế đồ chua', 'Vo sạch 50 g gạo nếp, ngâm nước 2 giờ (hoặc qua đêm) cho nở mềm rồi cho vào nồi nấu với nước khoảng 15 phút trên lửa nhỏ đến khi hạt nếp nở bung thành cháo, để nguội bớt và xay thật nhuyễn mịn. Cà rốt bào sợi, trộn với 60 ml giấm gạo và 10 g đường cát trắng, cất ngăn mát 30 phút làm đồ chua.', NULL, 15),
('imp-68184b07a3c61cff_v4_step_2', 'imp-68184b07a3c61cff', 2, 'marinate', 'Quết dẻo nhân nem nướng và ướp thấm', 'Thái hạt lựu 80 g thịt mỡ ba chỉ đã rửa sạch nước ấm. Trộn đều thịt mỡ, 150 g giò sống và 300 g thịt heo xay với 16 g bột năng, 12 ml dầu hào, 4 g đường cát trắng, 6 ml nước mắm, 1/2 lượng tỏi băm, 1/2 lượng hành tím băm, 2 g tiêu đen xay và 10 ml dầu màu điều. Quết mạnh tay 5 phút cho khối thịt dẻo dính, bọc kín ướp ngăn mát 45 phút.', 'Quết thịt thật kỹ và ướp lạnh trước khi nặn giúp nem nướng săn chắc, có độ giòn dai tự nhiên mà không bị bở.', 45),
('imp-68184b07a3c61cff_v4_step_3', 'imp-68184b07a3c61cff', 3, 'cook', 'Bọc thịt quanh sả và nướng chín vàng thơm', 'Cắt sả cây dài 15 cm, đập dập phần đầu. Chia thịt thành từng nắm vừa tay, nặn bọc chặt quanh đầu cây sả. Xếp các que nem vào nồi chiên không dầu hoặc lò nướng ở 180°C nướng 12 phút, trở mặt nướng thêm 5 phút đến khi nem chín kỹ hoàn toàn bên trong và vàng xém cạnh thơm lừng.', 'Làm nóng nồi chiên không dầu trước 5 phút giúp nem lên màu vàng đều và giữ độ mọng nước bên trong.', 17),
('imp-68184b07a3c61cff_v4_step_4', 'imp-68184b07a3c61cff', 4, 'sauce', 'Xào tôm thịt gan nấu sốt chấm sánh bùi', 'Băm thật nhuyễn 80 g tôm tươi lột vỏ, 50 g thịt heo xay còn lại và 50 g gan heo đã rửa sạch. Bắc chảo với 15 ml dầu ăn ở lửa vừa, phi thơm phần hành tím và tỏi băm còn lại cùng 5 ml dầu màu điều rồi cho hỗn hợp tôm thịt gan vào xào chín 3 phút, sau đó xay nhuyễn. Đổ phần thịt xay và cháo nếp xay vào nồi, nêm 36 ml nước mắm, 6 ml nước tương và 6 g đường cát trắng, khuấy đều trên lửa nhỏ đến khi sốt sôi sánh sệt.', 'Khuấy liên tục khi đun sôi lại phần sốt gạo nếp để tránh bén đáy nồi.', NULL),
('imp-68184b07a3c61cff_v4_step_5', 'imp-68184b07a3c61cff', 5, 'prep', 'Chuẩn bị rau sống, dưa leo và đậu phộng rang', 'Rửa sạch xà lách rau sống và giá đỗ, để thật ráo nước. Thái thanh dài dưa leo bỏ ruột. Rang chín vàng đậu phộng trên lửa nhỏ, xát sạch vỏ lụa rồi giã dập vừa.', NULL, NULL),
('imp-68184b07a3c61cff_v4_step_6', 'imp-68184b07a3c61cff', 6, 'finish', 'Trình bày nem nướng cuốn bánh tráng và thưởng thức', 'Xếp nem nướng nóng ra đĩa cùng bánh tráng cuốn, đĩa rau sống, giá đỗ, dưa leo và đồ chua cà rốt. Múc sốt chấm nóng ra chén và rắc đậu phộng rang giã dập lên trên. Khi ăn, cuốn nem cùng rau củ trong bánh tráng và chấm đẫm sốt.', NULL, NULL),
('imp-ed9f34ecd475d031_v4_step_1', 'imp-ed9f34ecd475d031', 1, 'prep', 'Sơ chế rau sống, dưa leo và cắt bún lá', 'Nhặt rửa sạch lá tía tô, rau kinh giới và xà lách, ngâm nước muối loãng 15 phút (dùng 3 g muối ăn) rồi vớt ra vẩy thật ráo nước. Dưa leo rửa sạch thái lát xéo vừa ăn. Bún lá cắt thành từng miếng vuông đều cỡ 3–4 cm.', NULL, 15),
('imp-ed9f34ecd475d031_v4_step_2', 'imp-ed9f34ecd475d031', 2, 'cook', 'Luộc chín mềm và thái lát thịt ba chỉ', 'Rửa sạch thịt ba chỉ heo rồi cho vào nồi cùng 1,5 lít nước lọc, 5 g muối ăn và 20 g gừng tươi đập dập. Luộc ở lửa vừa khoảng 25 phút đến khi xiên đũa qua thấy thịt chín mềm không còn nước hồng chảy ra, vớt ra ngâm nhanh vào nước nguội cho trắng giòn rồi để ráo, thái lát mỏng vừa ăn.', 'Luộc thịt cùng gừng đập dập và ngâm nước nguội ngay khi vớt ra giúp miếng thịt trắng đẹp và không bị thâm khô.', 25),
('imp-ed9f34ecd475d031_v4_step_3', 'imp-ed9f34ecd475d031', 3, 'cook', 'Chiên giòn đậu phụ mơ và chả cốm', 'Đun nóng 250 ml dầu ăn trong chảo sâu lòng trên lửa vừa, thả từng miếng đậu phụ mơ trắng đã thấm khô vào chiên khoảng 6–8 phút cho vàng phồng giòn đều các mặt rồi vớt ra rổ thưa cho ráo dầu. Tiếp tục chiên chả cốm khoảng 3–4 phút cho vàng giòn hai mặt, vớt ra để ráo.', 'Chiên đậu ở lửa vừa cho dầu ngập mặt giúp lớp vỏ ngoài giòn rụm mà bên trong vẫn mềm béo.', 10),
('imp-ed9f34ecd475d031_v4_step_4', 'imp-ed9f34ecd475d031', 4, 'sauce', 'Pha mắm tôm đánh bông thơm béo', 'Cho 60 g mắm tôm ngon vào bát sạch cùng 15 g đường cát trắng và 5 ml rượu trắng. Múc 25 ml dầu ăn đang nóng già từ chảo vừa chiên đậu rưới trực tiếp vào bát mắm để khử mùi nồng và làm dậy hương béo thơm. Vắt nước cốt của 2 quả quất (hoặc chanh tươi) vào rồi dùng đũa đánh nhanh tay đến khi mắm tôm sủi bọt trắng mịn, thêm ớt hiểm tươi thái lát.', 'Rưới dầu nóng vào mắm tôm rồi mới vắt nước cốt quất đánh đều sẽ giúp mắm tôm dậy mùi thơm dịu và nổi bọt bông lâu tan.', NULL),
('imp-ed9f34ecd475d031_v4_step_5', 'imp-ed9f34ecd475d031', 5, 'prep', 'Cắt miếng chả cốm và sắp xếp rau', 'Cắt chả cốm chiên nóng thành từng lát xéo vừa gắp; xếp gọn rau tía tô, kinh giới, xà lách và dưa leo lên một góc mẹt.', NULL, NULL),
('imp-ed9f34ecd475d031_v4_step_6', 'imp-ed9f34ecd475d031', 6, 'finish', 'Bày mẹt bún đậu mắm tôm và thưởng thức', 'Xếp bún lá cắt miếng, đậu phụ chiên giòn nóng, thịt ba chỉ thái lát và chả cốm quanh mẹt, đặt bát mắm tôm đánh bông ở chính giữa và thưởng thức ngay khi đậu phụ còn nóng giòn.', NULL, NULL),
('imp-a744a977e7e4b165_v4_step_1', 'imp-a744a977e7e4b165', 1, 'prep', 'Chần xương heo và chuẩn bị nguyên liệu hầm', 'Chần xương ống heo trong 400 ml nước sôi với 3 g muối ăn khoảng 4 phút rồi rửa sạch dưới vòi nước lạnh. Ngâm tôm khô 15 phút cho mềm; nướng khô mực trên lửa nhỏ 2 phút cho thơm; nướng sém hành tây và 25 g hành tím khô rồi cạo sạch lớp cháy; cắt khúc củ cải trắng.', NULL, 15),
('imp-a744a977e7e4b165_v4_step_2', 'imp-a744a977e7e4b165', 2, 'cook', 'Hầm nước lèo xương heo và hải sản khô', 'Cho xương ống heo, tôm khô, khô mực nướng, củ cải trắng, hành tây nướng và 25 g hành tím nướng vào nồi với 1,6 lít nước lọc lạnh cùng 5 g muối ăn. Đun sôi nhẹ rồi hạ lửa nhỏ hầm khoảng 50 phút, hớt bọt thường xuyên cho nước lèo thật trong. Vớt bỏ xác xương và rau củ rồi nêm 5 g muối ăn còn lại, 15 g đường phèn và 30 ml nước mắm ngon cho vừa miệng.', 'Hầm xương ở lửa liu riu và hớt bọt kỹ ngay từ đầu giúp nước lèo hủ tiếu mực trong veo, ngọt thanh.', 50),
('imp-a744a977e7e4b165_v4_step_3', 'imp-a744a977e7e4b165', 3, 'cook', 'Phi hành tỏi giòn và xào thịt heo xay', 'Đun nóng 25 ml dầu ăn trên chảo lửa vừa, phi vàng giòn 15 g hành tím thái lát và tỏi khô băm rồi vớt phần xác phi ra giấy thấm dầu. Dùng phần dầu thơm trong chảo xào chín tơi thịt heo xay khoảng 4 phút cùng 2 g muối ăn và 1 g tiêu đen xay rồi trút ra chén riêng.', 'Vớt hành tỏi phi ra khi vừa chuyển màu vàng nhạt để phần phi giòn thơm mà không bị đắng khét.', 5),
('imp-a744a977e7e4b165_v4_step_4', 'imp-a744a977e7e4b165', 4, 'cook', 'Làm sạch và chần nhanh mực ống tươi', 'Làm sạch mực ống tươi, cắt khoanh dày 1,5 cm. Đun sôi một nồi nước khác rồi thả mực vào chần nhanh khoảng 45–60 giây đến khi khoanh mực vừa săn cong trắng đục chín đều thì vớt ngay ra đĩa.', 'Chần mực nhanh trong nước thật sôi không quá 1 phút để giữ độ giòn sần sật và vị ngọt tự nhiên.', 2),
('imp-a744a977e7e4b165_v4_step_5', 'imp-a744a977e7e4b165', 5, 'prep', 'Trụng hủ tiếu, giá đỗ và cắt rau thơm', 'Trụng nhanh sợi hủ tiếu tươi qua nước sôi khoảng 30 giây cho mềm nóng rồi chia vào 4 tô; trụng sơ giá đỗ qua nước sôi đặt vào tô cùng hẹ lá cắt khúc, cần tây và thái lát ớt tươi.', NULL, NULL),
('imp-a744a977e7e4b165_v4_step_6', 'imp-a744a977e7e4b165', 6, 'finish', 'Xếp mực, thịt băm và chan nước lèo nóng', 'Xếp mực ống chần và thịt heo xay xào lên trên mặt tô hủ tiếu, chan ngập nước lèo đang sôi nóng, rắc hành tỏi phi vàng, 1 g tiêu đen xay còn lại và dọn nóng cùng ớt tươi thái lát.', NULL, NULL),
('imp-c67f536bef1c38d6_v4_step_1', 'imp-c67f536bef1c38d6', 1, 'prep', 'Sơ chế bắp cải, nấm đùi gà, cà rốt và đậu phụ chiên', 'Bắp cải tách lá, bỏ phần gân quá cứng, rửa sạch rồi cắt miếng vuông khoảng 4 cm và để ráo. Nấm đùi gà cắt gốc, rửa nhanh trong nước sạch để ráo rồi thái lát dày 0,6 cm. Cà rốt gọt vỏ thái khoanh dày 0,5 cm; đậu phụ chiên sẵn cắt miếng vuông cạnh 2,5 cm; hành boa-rô băm nhuyễn; hành lá thái nhỏ.', 'Cắt bắp cải miếng hơi to vừa phải để sau khi kho chín mềm lá cải vẫn giữ hình dáng đẹp mà không bị nhũn nát.', NULL),
('imp-c67f536bef1c38d6_v4_step_2', 'imp-c67f536bef1c38d6', 2, 'cook', 'Phi thơm hành boa-rô và xào săn nấm đùi gà', 'Làm nóng nồi đáy dày với 15 ml dầu ăn trên lửa vừa, thả hành boa-rô băm vào phi khoảng 40 giây cho dậy hương thơm. Trút nấm đùi gà vào xào nhanh tay 2 phút đến khi lát nấm săn lại.', 'Xào săn nấm trước khi cho rau củ và nước giúp nấm đậm đà và không tiết nhiều nước làm loãng vị kho.', 2),
('imp-c67f536bef1c38d6_v4_step_3', 'imp-c67f536bef1c38d6', 3, 'sauce', 'Trộn bắp cải, cà rốt, đậu phụ với sốt nước tương', 'Cho bắp cải, cà rốt và đậu phụ chiên sẵn vào nồi nấm. Nêm 45 ml nước tương, 12 g đường cát trắng, 4 g hạt nêm chay, 2 g muối ăn và rót 200 ml nước lọc vào nồi, đảo nhẹ tay cho gia vị hòa tan đều.', NULL, NULL),
('imp-c67f536bef1c38d6_v4_step_4', 'imp-c67f536bef1c38d6', 4, 'cook', 'Kho nhỏ lửa cho bắp cải mềm và thấm đều gia vị', 'Đun sôi nồi kho trên lửa lớn rồi hạ xuống lửa vừa nhỏ, đậy nắp kho trong 15 phút cho bắp cải và cà rốt chín mềm, nước kho rút bớt thấm sâu vào đậu phụ chiên và nấm.', NULL, 15),
('imp-c67f536bef1c38d6_v4_step_5', 'imp-c67f536bef1c38d6', 5, 'cook', 'Mở nắp rim nhẹ cho nước kho sánh lại', 'Mở nắp nồi, tiếp tục kho thêm 4 phút trên lửa vừa để nước kho hơi sánh lại, thỉnh thoảng lắc nhẹ quai nồi cho gia vị phủ đều mà không dùng đũa khuấy mạnh làm nát đậu và cải.', 'Lắc nhẹ nồi thay vì dùng đũa đảo giúp giữ trọn miếng bắp cải mềm nguyên và đậu phụ không bị vỡ.', 4),
('imp-c67f536bef1c38d6_v4_step_6', 'imp-c67f536bef1c38d6', 6, 'finish', 'Hoàn thiện món bắp cải kho nấm nóng hổi', 'Nêm nếm lại nước kho cho vừa khẩu vị ăn cơm, tắt bếp rồi rắc hành lá thái nhỏ và 1,5 g tiêu đen xay lên mặt nồi. Múc ra đĩa sâu lòng và dùng nóng với cơm trắng.', NULL, NULL),
('imp-35deaaa123c7470d_v4_step_1', 'imp-35deaaa123c7470d', 1, 'prep', 'Chần nhanh giá đỗ và hành lá giữ độ giòn', 'Nhặt sạch giá đỗ và rửa kỹ rồi để ráo. Đun sôi nồi nước nhỏ, thả giá đỗ cùng hành lá cắt khúc 3–4 cm vào chần thật nhanh trong 10 giây, vớt ngay ra ngâm vào tô nước lạnh 1 phút rồi đổ ra rổ để thật ráo nước.', 'Chần giá đỗ rất nhanh qua nước sôi rồi sốc lạnh giúp giá hết mùi hăng ngái mà vẫn giữ độ giòn trắng.', 2),
('imp-35deaaa123c7470d_v4_step_2', 'imp-35deaaa123c7470d', 2, 'prep', 'Bóp giòn cà rốt bào sợi', 'Cà rốt gọt vỏ, bào sợi mỏng đều rồi trộn nhẹ với 3 g muối ăn và 3 g đường cát trắng trong 3 phút để rút bớt nước hăng. Sau đó xả nhanh qua nước đun sôi để nguội, vắt nhẹ tay cho ráo nước.', 'Ướp muối đường nhẹ rồi vắt ráo trước khi trộn giúp sợi cà rốt giòn sần sật và không tiết nước làm loãng nộm.', 3),
('imp-35deaaa123c7470d_v4_step_3', 'imp-35deaaa123c7470d', 3, 'sauce', 'Pha nước trộn nộm chay chua cay mặn ngọt', 'Vắt chanh tươi lấy nước cốt bỏ hạt; băm thật nhuyễn tỏi khô và ớt hiểm. Khuấy đều trong chén 30 ml nước mắm chay, 22 g đường cát trắng còn lại, 15 ml giấm gạo và nước cốt chanh cho đường tan hoàn toàn rồi thả tỏi ớt băm vào trộn đều.', 'Nêm thử hỗn hợp nước trộn đạt vị chua cay mặn ngọt hơi đậm một chút để khi áo vào giá và cà rốt là vừa miệng.', NULL),
('imp-35deaaa123c7470d_v4_step_4', 'imp-35deaaa123c7470d', 4, 'cook', 'Trộn đều giá đỗ, cà rốt và hành lá thấm vị', 'Cho giá đỗ đã ráo, cà rốt bào sợi và hành lá vào âu lớn. Rưới từ từ phần nước trộn nộm vào âu, dùng tay đeo găng bóp trộn thật nhẹ nhàng cho gia vị phủ đều rồi để nghỉ 5 phút cho nguyên liệu ngấm vị.', NULL, 5),
('imp-35deaaa123c7470d_v4_step_5', 'imp-35deaaa123c7470d', 5, 'cook', 'Thêm rau húng quế và chắt nước thừa', 'Nghiêng nhẹ âu để chắt bỏ phần nước dư nếu rau có tiết thêm nước, sau đó thả rau húng quế thái rối vào đảo đều nhẹ tay thêm một lượt để nộm dậy mùi thơm mát.', NULL, NULL),
('imp-35deaaa123c7470d_v4_step_6', 'imp-35deaaa123c7470d', 6, 'finish', 'Rắc đậu phộng rang và thưởng thức ngay', 'Gắp nộm giá đỗ chua cay ra đĩa, rắc đều 30 g đậu phộng rang giã dập lên mặt đĩa và thưởng thức ngay khi rau củ còn giòn mát.', NULL, NULL),
('imp-94b6bce7403fedc6_v4_step_1', 'imp-94b6bce7403fedc6', 1, 'prep', 'Rang thơm hỗn hợp gạo tẻ và gạo nếp', 'Trộn 160 g gạo tẻ với 40 g gạo nếp, vo nhẹ 2 nước rồi chắt thật ráo. Làm nóng nồi đáy dày không dầu trên lửa nhỏ, cho gạo vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy hương thơm dịu.', 'Rang gạo trước giúp hạt gạo săn đều, khi nấu thành cháo chay vẫn có độ sánh béo tự nhiên rất ngon miệng.', 6),
('imp-94b6bce7403fedc6_v4_step_2', 'imp-94b6bce7403fedc6', 2, 'cook', 'Ninh nhừ cháo trắng trên lửa nhỏ', 'Đổ 1,8 lít nước lọc sôi vào nồi gạo rang, khuấy đều đáy nồi một lượt rồi đậy hé nắp. Đun sôi bùng sau đó hạ lửa nhỏ ninh khoảng 22 phút, thỉnh thoảng khuấy đều sát đáy nồi cho hạt gạo nở bung mềm mịn.', NULL, 22),
('imp-94b6bce7403fedc6_v4_step_3', 'imp-94b6bce7403fedc6', 3, 'prep', 'Sơ chế nấm đùi gà, đậu phụ và rau thơm', 'Nấm đùi gà làm sạch rồi thái hạt lựu vừa ăn. Cắt 300 g đậu phụ trắng thành các khối vuông nhỏ cạnh 1,5 cm. Gừng tươi cạo vỏ thái sợi chỉ mảnh; băm nhỏ 20 g hành tím khô; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('imp-94b6bce7403fedc6_v4_step_4', 'imp-94b6bce7403fedc6', 4, 'cook', 'Phi thơm hành tím và xào đậm đà nấm đùi gà', 'Làm nóng 15 ml dầu ăn trong chảo trên lửa vừa, cho hành tím băm vào phi thơm vàng nhẹ. Trút nấm đùi gà vào đảo nhanh trên lửa lớn khoảng 3 phút, nêm 10 ml xì dầu và 2 g hạt nêm chay nấm hương cho nấm săn ngọt, dậy mùi thơm rồi tắt bếp.', 'Xào nấm đùi gà với xì dầu trên lửa lớn giúp nấm săn giòn, không ra nước và tạo vị ngọt umami đậm đà cho nồi cháo chay.', 3),
('imp-94b6bce7403fedc6_v4_step_5', 'imp-94b6bce7403fedc6', 5, 'cook', 'Cho nấm và đậu phụ vào nồi cháo nấu chín quyện', 'Nêm 15 ml xì dầu còn lại, 4 g hạt nêm chay và 4 g muối ăn vào nồi cháo đã nhừ, khuấy đều. Trút phần nấm đùi gà xào, một nửa lượng gừng thái chỉ và nhẹ tay thả các khối đậu phụ trắng vào nồi, nấu sôi lăn tăn nhẹ thêm 3 phút rồi tắt bếp.', 'Thả đậu phụ vào sau cùng và khuấy thật nhẹ tay quanh thành nồi để giữ từng miếng đậu vuông vắn không bị vỡ nát.', NULL),
('imp-94b6bce7403fedc6_v4_step_6', 'imp-94b6bce7403fedc6', 6, 'finish', 'Múc cháo nấm đậu phụ ra tô và thưởng thức nóng', 'Múc cháo nấm đậu phụ nóng hổi ra 4 tô sứ, rắc hành lá thái nhỏ, ngò rí, phần gừng tươi thái chỉ còn lại và 1,5 g tiêu đen xay lên trên rồi thưởng thức ngay.', NULL, NULL),
('imp-4f7a2cd919912ac9_v4_step_1', 'imp-4f7a2cd919912ac9', 1, 'prep', 'Sơ chế hành lá, hành tím và pha sốt trộn mì', 'Thái lát mỏng 20 g hành tím khô; rửa sạch hành lá, thái nhuyễn phần lá xanh và cắt khúc ngắn đầu hành trắng rồi cho chung vào tô chịu nhiệt. Trong một chén khác, khuấy tan 25 ml xì dầu, 10 ml nước mắm ngon, 4 g đường cát trắng, 10 ml giấm gạo và 5 ml dầu mè thơm.', NULL, NULL),
('imp-4f7a2cd919912ac9_v4_step_2', 'imp-4f7a2cd919912ac9', 2, 'cook', 'Phi vàng hành tím làm dầu hành thơm nức', 'Đun nóng 15 ml dầu ăn trong chảo nhỏ trên lửa vừa, cho hành tím thái lát vào phi vàng giòn khoảng 2 phút rồi trút cả phần dầu nóng lẫn hành phi thẳng vào tô hành lá, đảo nhẹ cho hành chín xanh thơm lừng và giữ lại phần hành phi giòn.', 'Dội dầu hành phi đang sôi trực tiếp lên hành lá thái nhỏ vừa làm hành chín tái giữ màu xanh, vừa tạo ra thứ dầu hành thơm nức cho món mì trộn.', 2),
('imp-4f7a2cd919912ac9_v4_step_3', 'imp-4f7a2cd919912ac9', 3, 'cook', 'Chiên 2 quả trứng gà ốp la lòng đào', 'Dùng lại chảo nhỏ với 10 ml dầu ăn còn lại trên lửa vừa, đập 2 quả trứng gà vào chiên ốp la khoảng 2 phút đến khi lòng trắng đông chắc viền hơi vàng giòn và lòng đỏ sánh dẻo (hoặc chiên chín hẳn tùy khẩu vị), gắp ra đĩa riêng.', NULL, 2),
('imp-4f7a2cd919912ac9_v4_step_4', 'imp-4f7a2cd919912ac9', 4, 'cook', 'Trụng chín tới và làm săn sợi mì', 'Đun sôi 800 ml nước lọc, thả 2 vắt mì vào trụng khoảng 90 giây đến khi sợi mì vừa chín mềm vẫn còn độ dai. Vớt mì ra xả nhanh dưới vòi nước lạnh hoặc xóc ráo thật kỹ để sợi mì tơi rời không bị nhũn.', 'Không trụng mì quá lâu và phải xóc thật ráo nước trước khi trộn để nước sốt bám đặc đều từng sợi mì.', NULL),
('imp-4f7a2cd919912ac9_v4_step_5', 'imp-4f7a2cd919912ac9', 5, 'cook', 'Trộn đều mì với sốt xì dầu và dầu hành', 'Cho mì đã ráo nước vào tô lớn, rưới toàn bộ dầu hành phi và nước sốt xì dầu, dầu mè đã pha lên trên. Dùng đũa trộn đều tay trong 1 phút cho từng sợi mì bóng mượt, lên màu nâu óng đẹp mắt và thấm đều gia vị.', 'Trộn mì ngay khi còn ấm để hương thơm của dầu mè, xì dầu và hành phi quyện chặt vào từng sợi mì.', NULL),
('imp-4f7a2cd919912ac9_v4_step_6', 'imp-4f7a2cd919912ac9', 6, 'finish', 'Bày đĩa mì trộn trứng hành và rắc mè rang', 'Chia mì trộn ra 2 tô hoặc đĩa sâu lòng, đặt trứng gà ốp la lên trên, rắc 5 g mè trắng rang chín và 1 g tiêu đen xay rồi thưởng thức nóng ngay.', NULL, NULL),
('imp-edac077a60dfa8b5_v4_step_1', 'imp-edac077a60dfa8b5', 1, 'sauce', 'Nấu và để nguội nước kho ngũ vị', 'Cho gừng tươi thái lát, 3 g hoa hồi khô, 3 g quế thanh, 1 g lá nguyệt quế khô, 2 g tiêu Tứ Xuyên, 30 ml xì dầu nhạt, 15 ml xì dầu đặc, 4 g đường cát trắng, 8 g muối ăn, 20 ml rượu Thiệu Hưng và 700 ml nước lọc vào nồi (nếu có sẵn 10 g lá trà đen khô, cho thêm vào túi lọc để tạo hương trà truyền thống). Đun sôi rồi hạ lửa nhỏ đậy nắp om 10 phút cho thảo mộc tiết hương, sau đó tắt bếp mở nắp để nguội hoàn toàn.', 'Để nước kho nguội hẳn trước khi thả trứng vào ngâm sẽ giữ lòng đỏ mềm dẻo mà không bị chín quá cứng.', 10),
('imp-edac077a60dfa8b5_v4_step_2', 'imp-edac077a60dfa8b5', 2, 'cook', 'Luộc trứng gà chín lòng đào hoặc chín kỹ', 'Đun một nồi nước khác cho sôi mạnh, dùng muôi lớn nhẹ nhàng thả 8 quả trứng gà ở nhiệt độ phòng vào nước sôi (tránh va đập vỡ vỏ). Luộc đúng 7 phút cho lòng đỏ dẻo mềm hoặc 9 phút nếu thích lòng đỏ chín bở.', NULL, 7),
('imp-edac077a60dfa8b5_v4_step_3', 'imp-edac077a60dfa8b5', 3, 'prep', 'Ngâm nước đá làm nguội trứng nhanh', 'Vớt trứng ra thả ngay vào thau nước lạnh có đá viên trong 5 phút để dừng quá trình chín và giúp màng trứng dễ bong hơn khi bóc.', NULL, 5),
('imp-edac077a60dfa8b5_v4_step_4', 'imp-edac077a60dfa8b5', 4, 'prep', 'Gõ tạo mạng vết nứt vân đá trên vỏ trứng', 'Dùng lưng muỗng nhỏ gõ nhẹ đều khắp vỏ từng quả trứng để tạo mạng lưới vết nứt mịn đan xen nhau nhưng tuyệt đối không bóc vỏ ra.', 'Gõ lực vừa phải để nước kho thấm qua tạo hoa văn vân đá đều đẹp mà không làm vỡ nát phần lòng trắng mềm bên trong.', NULL),
('imp-edac077a60dfa8b5_v4_step_5', 'imp-edac077a60dfa8b5', 5, 'marinate', 'Ngâm ủ trứng trong nước kho gia vị', 'Xếp toàn bộ trứng đã gõ rạn vỏ vào nồi nước kho ngũ vị đã nguội hoàn toàn, đảm bảo nước ngập hết trứng. Đậy kín nắp và đặt vào ngăn mát tủ lạnh ngâm ít nhất 8 giờ cho vân màu đậm nét và thấm sâu vào tận lòng đỏ.', 'Ngâm từ 8 đến 24 giờ trong ngăn mát giúp đường vân đá hiện rõ nét và hương ngũ vị ngấm sâu đều khắp quả trứng.', 480),
('imp-edac077a60dfa8b5_v4_step_6', 'imp-edac077a60dfa8b5', 6, 'finish', 'Bóc vỏ lộ vân đá và thưởng thức', 'Lấy trứng ra bóc nhẹ vỏ dưới vòi nước sạch để lộ hoa văn vân đá nâu óng tự nhiên. Có thể dùng mát trực tiếp, cắt đôi xếp lên bát mì nóng hoặc hâm ấm nhẹ trong nước kho trước khi ăn.', NULL, NULL),
('imp-0efe9204d9dbdb3e_v4_step_1', 'imp-0efe9204d9dbdb3e', 1, 'prep', 'Ngâm mềm ớt khô tránh cháy đắng', 'Cắt 40 g ớt khô thành từng đoạn ngắn 1,5 cm (có thể giảm lượng ớt nếu ăn cay nhẹ), giũ bỏ bớt hạt rồi ngâm vào nước sạch 15 phút, sau đó vớt ra vẩy thật ráo nước.', 'Ngâm nước trước giúp ớt khô không bị cháy đen khi phi trên chảo nóng mà vẫn tiết ra màu đỏ và hương thơm nồng.', 15),
('imp-0efe9204d9dbdb3e_v4_step_2', 'imp-0efe9204d9dbdb3e', 2, 'marinate', 'Cắt khối và ướp mềm thịt đùi gà', 'Thái 450 g thịt đùi gà rút xương thành khối vuông nhỏ 2 cm. Trộn đều gà trong tô với 15 ml xì dầu, 15 ml rượu Thiệu Hưng, 1 g tiêu trắng xay, 1 g muối ăn và 6 g bột bắp, ướp 10 phút cho thịt ngấm vị và săn mềm.', NULL, 10),
('imp-0efe9204d9dbdb3e_v4_step_3', 'imp-0efe9204d9dbdb3e', 3, 'cook', 'Chiên nông từng mẻ gà vàng giòn rụm', 'Đun nóng 235 ml dầu ăn trong chảo sâu lòng trên lửa lớn đến khi đầu đũa sủi tăm mạnh. Chia gà thành 2 mẻ chiên nông 4–5 phút (giữ yên 1 phút đầu cho se vỏ rồi mới đảo đều mặt) đến khi từng miếng gà chín hoàn toàn bên trong, vỏ ngoài vàng giòn thì vớt ra giấy thấm dầu.', 'Chiên từng mẻ không chen chúc giúp mặt gà tiếp xúc tốt với đáy chảo, giòn rụm nhanh mà không bị ra nước.', NULL),
('imp-0efe9204d9dbdb3e_v4_step_4', 'imp-0efe9204d9dbdb3e', 4, 'cook', 'Phi ớt khô và hoa tiêu trên lửa nhỏ nhất', 'Dùng chảo sạch làm nóng 15 ml dầu ăn còn lại trên lửa nhỏ nhất, thả ớt khô đã ráo nước vào đảo đều 2 phút đến khi ớt dậy mùi thơm và chuyển màu đỏ sẫm. Tiếp tục cho 8 g hoa tiêu Tứ Xuyên vào đảo thêm 1 phút trên lửa nhỏ để tạo vị tê thơm mà không làm cháy đắng.', 'Luôn giữ lửa nhỏ nhất khi phi ớt khô và hoa tiêu để gia vị tiết tinh dầu thơm nồng mà không bị đắng khét.', 3),
('imp-0efe9204d9dbdb3e_v4_step_5', 'imp-0efe9204d9dbdb3e', 5, 'cook', 'Phi thơm gừng, tỏi và đầu hành trắng', 'Gạt ớt khô và hoa tiêu sang một bên chảo, cho gừng tươi thái lát, tỏi thái lát và đầu hành trắng vào khoảng trống giữa chảo phi thơm 30 giây cho dậy mùi.', NULL, NULL),
('imp-0efe9204d9dbdb3e_v4_step_6', 'imp-0efe9204d9dbdb3e', 6, 'finish', 'Xóc đều gà giòn với mè rang và hành lá', 'Trút toàn bộ gà chiên giòn trở lại chảo, rắc 9 g hạt mè trắng rang, 4 g đường cát trắng, 1 g muối ăn còn lại và phần lá hành xanh cắt khúc. Đảo nhanh tay 30 giây trên lửa vừa cho gia vị bám đều rồi trút ra đĩa thưởng thức nóng ngay.', NULL, NULL),
('imp-0a1f8e0bd042cbfd_v4_step_1', 'imp-0a1f8e0bd042cbfd', 1, 'prep', 'Thái lát mỏng ba chỉ và xé ráo bắp cải', 'Thấm khô 300 g thịt ba chỉ rồi thái lát mỏng đều tay. Tách 1/2 bắp cải trắng rửa sạch, để thật ráo nước rồi xé miếng vừa ăn khoảng 4 cm; thái lát tỏi, thái sợi gừng, thái khoanh ớt hiểm và cắt khúc hành lá (tách riêng đầu trắng và lá xanh).', 'Bắp cải phải thật ráo nước trước khi vào chảo để khi xào không bị chảy nước và giữ được độ giòn ngọt.', NULL),
('imp-0a1f8e0bd042cbfd_v4_step_2', 'imp-0a1f8e0bd042cbfd', 2, 'cook', 'Áp chảo thịt ba chỉ xém cạnh tươm mỡ', 'Làm nóng chảo sâu lòng trên lửa vừa lớn với 15 ml dầu ăn tráng mặt chảo, xếp các lát thịt ba chỉ vào áp chảo 5 phút (trở đều mặt sau mỗi 1–2 phút) đến khi thịt ra bớt mỡ thơm và xém vàng các cạnh.', NULL, 5),
('imp-0a1f8e0bd042cbfd_v4_step_3', 'imp-0a1f8e0bd042cbfd', 3, 'cook', 'Rưới rượu Thiệu Hưng và phi thơm gia vị', 'Gạt nhẹ thịt ba chỉ sang một bên chảo, rưới 15 ml rượu Thiệu Hưng vào phần chảo nóng đảo 20 giây cho bay hơi thơm nồng. Tiếp tục thả đầu hành trắng, tỏi thái lát, gừng thái sợi và ớt hiểm vào phi thơm 30 giây trên lửa vừa.', NULL, NULL),
('imp-0a1f8e0bd042cbfd_v4_step_4', 'imp-0a1f8e0bd042cbfd', 4, 'cook', 'Xào nhanh bắp cải trên lửa lớn giữ độ giòn', 'Tăng lên lửa lớn nhất, trút toàn bộ bắp cải vào đảo nhanh tay liên tục trong 3 phút đến khi lá bắp cải vừa mềm trong nhẹ mà phần cuống vẫn giữ độ giòn sần sật.', 'Xào lửa thật lớn và đảo liên tục giúp bắp cải chín nhanh, bóng mỡ thơm mà không bị ra nước nhũn.', 3),
('imp-0a1f8e0bd042cbfd_v4_step_5', 'imp-0a1f8e0bd042cbfd', 5, 'sauce', 'Rưới xì dầu quanh thành chảo và nêm vị', 'Rưới đều 45 ml xì dầu nhạt dọc theo thành chảo nóng cho bốc mùi thơm, thêm 4 g muối ăn và 6 g đường cát trắng rồi đảo đều 30 giây cho thịt và bắp cải thấm gia vị đậm đà.', 'Rưới xì dầu dọc theo thành chảo nóng giúp nước tương xèo nhẹ, dậy mùi thơm đặc trưng hơn so với đổ thẳng lên rau.', NULL),
('imp-0a1f8e0bd042cbfd_v4_step_6', 'imp-0a1f8e0bd042cbfd', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Rưới 15 ml dầu mè thơm và thả phần lá hành xanh vào chảo, đảo thêm 15 giây rồi tắt bếp ngay. Múc ra đĩa và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-ae6d3af49ade8384_v4_step_1', 'imp-ae6d3af49ade8384', 1, 'prep', 'Làm lạnh và sơ chế sạch cua biển', 'Cho cua biển tươi vào ngăn mát tủ lạnh khoảng 10 phút cho cua chậm lại dễ cầm, tháo dây buộc rồi lật ngửa bóc bỏ yếm. Tách phần mai, bỏ sạch mang xám hai bên và túi dạ dày sau miệng, rửa kỹ dưới vòi nước lạnh cho hết cát rồi chặt thân cua thành 4 đến 6 miếng, bổ đôi mai và dùng sống dao đập nhẹ vỏ càng cho dễ ngấm vị.', 'Thấm thật khô từng miếng cua bằng khăn giấy trước khi áo bột để cua không bị bắn dầu khi chiên và giữ được độ ngọt tự nhiên bên trong.', 10),
('imp-ae6d3af49ade8384_v4_step_2', 'imp-ae6d3af49ade8384', 2, 'prep', 'Thái gừng hành và pha sẵn chén sốt', 'Thái lát mỏng 30 g gừng tươi, băm nhỏ 4 tép tỏi khô và cắt khúc 5 cm phần hành lá tươi, tách riêng đầu hành trắng với phần lá xanh. Trong một chén nhỏ, khuấy tan 15 ml dầu hào, 10 ml xì dầu nhạt, 4 g đường cát trắng, 1 g tiêu trắng xay, 5 ml dầu mè thơm, 5 g bột bắp và 90 ml nước lọc rồi đặt sẵn cạnh bếp.', 'Pha sẵn nước sốt trước khi bật bếp giúp thao tác ở giai đoạn xào lửa lớn diễn ra liên tục, tránh làm cua bị chín quá mất độ mọng.', NULL),
('imp-ae6d3af49ade8384_v4_step_3', 'imp-ae6d3af49ade8384', 3, 'cook', 'Áo bột bắp và chiên sơ cua khóa ngọt', 'Cho cua đã thấm khô vào tô lớn, rắc đều 25 g bột bắp còn lại vào xóc nhẹ tạo lớp áo mỏng quanh mặt thịt. Đun nóng khoảng 400 ml dầu ăn thực vật trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm mạnh, thả từng mẻ cua vào chiên khoảng 3 phút đến khi vỏ cua vừa chuyển màu đỏ cam thì vớt ra rổ để ráo dầu.', 'Chỉ chiên cua vừa chuyển đỏ rồi vớt ra ngay, không chiên quá lâu vì thịt cua còn được đảo tiếp với sốt sẽ dễ bị khô bã.', 3),
('imp-ae6d3af49ade8384_v4_step_4', 'imp-ae6d3af49ade8384', 4, 'cook', 'Phi thơm gừng, tỏi và đầu hành trắng', 'Chắt bớt phần dầu chiên ra hũ riêng, chỉ giữ lại khoảng 15 ml dầu ăn trong chảo. Bật lửa vừa, cho gừng thái lát vào đảo khoảng 30 giây đến khi cạnh gừng hơi săn thơm, tiếp tục thêm tỏi băm và phần đầu hành lá trắng vào phi thêm 20 giây cho dậy mùi thơm nồng mà không cháy xém.', NULL, NULL),
('imp-ae6d3af49ade8384_v4_step_5', 'imp-ae6d3af49ade8384', 5, 'cook', 'Xào cua với rượu Thiệu Hưng và sốt dầu hào', 'Tăng lên lửa lớn, trút toàn bộ cua đã chiên vào chảo đảo nhanh vài lượt cho áo đều dầu gừng. Rưới 15 ml rượu Thiệu Hưng quanh thành chảo cho bốc hơi thơm lừng, khuấy lại chén sốt bột bắp cho không lắng đáy rồi rưới đều lên cua, đảo liên tục khoảng 2 phút đến khi thịt cua chín trắng hoàn toàn.', NULL, 2),
('imp-ae6d3af49ade8384_v4_step_6', 'imp-ae6d3af49ade8384', 6, 'finish', 'Thêm hành lá xanh và hoàn thiện đĩa cua', 'Khi nước sốt sôi nhẹ và bắt đầu sánh bóng bám đều quanh từng miếng cua, cho toàn bộ phần lá xanh của hành lá vào đảo đều thêm 30 giây cho hành vừa chín tái xanh mướt rồi tắt bếp. Xếp cua ra đĩa lớn, rưới phần sốt gừng hành còn lại trong chảo lên trên và dọn nóng.', NULL, NULL),
('imp-122b920eba3f2e50_v4_step_1', 'imp-122b920eba3f2e50', 1, 'prep', 'Ép ráo đậu phụ và sơ chế rau củ', 'Đặt 3 bìa đậu phụ trắng lên khăn giấy sạch, ép nhẹ khoảng 5 phút cho thoát bớt nước rồi cắt thành khối vuông cạnh 2,5 cm. Rửa sạch cải thảo và cà rốt; cải thảo thái miếng vừa ăn tách riêng phần cọng trắng với lá xanh, cà rốt bào sợi mỏng, hành lá cắt khúc 4 cm, còn gừng tươi và tỏi khô băm nhuyễn.', 'Ép ráo đậu phụ trước khi áp chảo giúp mặt đậu nhanh vàng giòn, không bị bắn dầu và không nát vỡ khi đảo cùng mì.', NULL),
('imp-122b920eba3f2e50_v4_step_2', 'imp-122b920eba3f2e50', 2, 'sauce', 'Pha hỗn hợp sốt tương đen Hoisin', 'Cho vào bát nhỏ 25 ml xì dầu, 20 ml tương đen Hoisin, 15 ml rượu Thiệu Hưng, 10 ml dầu mè thơm, 8 g bột bắp, 6 g đường cát trắng, gừng băm, tỏi băm và 50 ml nước lọc. Khuấy đều tay đến khi bột bắp và đường tan hoàn toàn rồi đặt sẵn bên cạnh bếp.', 'Pha sẵn chén sốt trước khi xào giúp bạn chủ động tốc độ trên lửa lớn, tránh tình trạng rau chín nhũn trong lúc nêm từng loại gia vị.', NULL),
('imp-122b920eba3f2e50_v4_step_3', 'imp-122b920eba3f2e50', 3, 'cook', 'Trụng tơi mì Udon lúa mì', 'Đun sôi khoảng 1150 ml nước lọc trong nồi vừa, thả 2 gói mì Udon lúa mì tươi vào trụng khoảng 1 đến 2 phút trên lửa lớn, dùng đũa khuấy nhẹ cho các sợi mì tách tơi hoàn toàn mà không bị nát. Vớt mì ra rổ cho ráo hết nước.', NULL, 2),
('imp-122b920eba3f2e50_v4_step_4', 'imp-122b920eba3f2e50', 4, 'cook', 'Áp chảo đậu phụ vàng giòn các mặt', 'Làm nóng chảo chống dính lớn trên lửa vừa với 15 ml dầu ăn thực vật, xếp đều các khối đậu phụ vào thành một lớp thưa. Áp chảo khoảng 8 phút, lật đều các mặt đến khi đậu phụ vàng nâu giòn cạnh thì gắp riêng ra đĩa.', 'Không lật đậu phụ quá sớm; hãy đợi mặt dưới se vàng hẳn mới trở mặt để đậu giữ nguyên khối vuông đẹp mắt.', 8),
('imp-122b920eba3f2e50_v4_step_5', 'imp-122b920eba3f2e50', 5, 'cook', 'Xào nhanh cà rốt và cải thảo lửa lớn', 'Cho 10 ml dầu ăn còn lại vào chảo, tăng lên lửa lớn. Thả cà rốt thái sợi và phần cọng trắng cải thảo vào đảo nhanh 1 phút cho dậy mùi thơm, sau đó thêm phần lá xanh cải thảo vào xào tiếp khoảng 45 giây đến khi rau vừa chín tới, vẫn giữ độ giòn.', NULL, 2),
('imp-122b920eba3f2e50_v4_step_6', 'imp-122b920eba3f2e50', 6, 'finish', 'Đảo mì quyện sốt đậu phụ và dọn nóng', 'Trút mì Udon đã ráo nước, đậu phụ áp chảo, hành lá cắt khúc và khuấy lại chén sốt tương đen Hoisin rưới đều vào chảo. Xóc và đảo nhẹ tay trên lửa lớn khoảng 1 phút cho nước sốt sánh bóng áo đều từng sợi mì và rau củ rồi tắt bếp, dọn ngay khi còn nóng.', NULL, NULL),
('imp-01ae566db4a7feab_v4_step_1', 'imp-01ae566db4a7feab', 1, 'prep', 'Thái ngang thớ và ướp mềm thịt bò', 'Thấm khô 400 g thịt thăn bò bằng khăn giấy, thái lát mỏng 2 đến 3 mm theo chiều ngang thớ để thịt không bị dai. Cho bò vào tô ướp cùng 15 ml xì dầu nhạt, 5 ml dầu mè thơm và 1 g tiêu trắng xay, trộn đều rồi để thấm trong 15 phút.', 'Không cho muối vào lúc ướp thịt bò sống vì muối làm thịt tiết nước và bị săn cứng khi nấu nhanh.', 15),
('imp-01ae566db4a7feab_v4_step_2', 'imp-01ae566db4a7feab', 2, 'prep', 'Sơ chế nấm đùi gà và các nguyên liệu thơm', 'Rửa sạch nấm đùi gà tươi, cắt bỏ gốc già rồi thái lát dọc dày khoảng 0,5 cm vừa ăn. Gừng tươi thái lát mỏng, tỏi khô đập dập; hành lá tách phần đầu trắng đập dập để nấu nước dùng, còn phần lá xanh thái nhỏ để riêng.', NULL, NULL),
('imp-01ae566db4a7feab_v4_step_3', 'imp-01ae566db4a7feab', 3, 'cook', 'Nấu nước dùng bò thơm gừng hành', 'Cho 1000 ml nước dùng bò cùng 260 ml nước lọc vào nồi sâu lòng, thả gừng thái lát, tỏi đập dập và đầu hành trắng vào đun sôi trên lửa lớn. Khi nước sôi bùng, hạ xuống lửa vừa đun thêm 5 phút cho nước dùng dậy hương thơm rồi vớt bỏ bã gừng tỏi và đầu hành để nước súp trong đẹp.', NULL, 5),
('imp-01ae566db4a7feab_v4_step_4', 'imp-01ae566db4a7feab', 4, 'cook', 'Nấu chín nấm đùi gà ngọt nước', 'Cho toàn bộ nấm đùi gà thái lát vào nồi nước dùng đang sôi nhẹ trên lửa vừa, nấu khoảng 8 phút đến khi nấm chín mềm, ngấm vị và tiết ra độ ngọt tự nhiên cho nước súp. Hớt sạch bọt nổi nếu có.', 'Nấu nấm trước giúp nước súp ngọt thanh mà không làm thịt bò bị chín quá kỹ.', 8),
('imp-01ae566db4a7feab_v4_step_5', 'imp-01ae566db4a7feab', 5, 'cook', 'Trụng nhanh thịt bò và nêm gia vị', 'Giữ nồi súp sôi lăn tăn ở lửa vừa, thả từng lượt thịt bò đã ướp vào khuấy nhẹ cho tơi miếng, nấu khoảng 2 đến 3 phút đến khi thịt bò vừa chín đều không còn sắc đỏ sống. Nêm thêm 10 ml xì dầu nhạt còn lại, 5 g muối ăn và 1 g tiêu trắng xay cho vừa miệng.', 'Không đun sôi sục quá lâu sau khi thả bò để lát thịt giữ được độ mềm mọng và ngọt tự nhiên.', 3),
('imp-01ae566db4a7feab_v4_step_6', 'imp-01ae566db4a7feab', 6, 'finish', 'Tạo độ sánh nhẹ và hoàn thiện tô súp', 'Hòa tan 12 g bột bắp với 40 ml nước lọc còn lại, vừa khuấy nhẹ nồi súp theo một chiều vừa rót từ từ nước bột bắp vào đến khi nước súp có độ sánh mượt nhẹ rồi đun thêm 30 giây cho chín bột. Tắt bếp, múc súp ra tô, rắc hành lá xanh thái nhỏ và dùng ngay khi còn nóng.', NULL, NULL),
('imp-296dbce4d9098a2e_v4_step_1', 'imp-296dbce4d9098a2e', 1, 'prep', 'Làm nóng lò và sơ chế phi lê cá', 'Làm nóng trước lò nướng ở 180°C trong khoảng 10 phút. Rửa nhanh 700 g phi lê cá chẽm dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô hai mặt. Xoa đều 10 ml dầu ăn thực vật, 3 g muối ăn và 2 g tiêu đen xay lên cả hai mặt từng miếng cá.', 'Thấm thật khô mặt cá trước khi thoa dầu và muối tiêu giúp gia vị bám đều và hạn chế mùi tanh khi nướng kín.', NULL),
('imp-296dbce4d9098a2e_v4_step_2', 'imp-296dbce4d9098a2e', 2, 'prep', 'Thái gừng hành và pha chén sốt xì dầu', 'Thái 25 g gừng tươi thành sợi chỉ, cắt khúc 5 cm phần hành lá tươi và băm nhỏ 4 tép tỏi khô. Trong chén nhỏ, khuấy tan hoàn toàn 6 g đường cát trắng với 50 ml xì dầu nhạt và 60 ml nước lọc.', NULL, NULL),
('imp-296dbce4d9098a2e_v4_step_3', 'imp-296dbce4d9098a2e', 3, 'cook', 'Xếp cá vào khay lót gừng hành và rưới sốt', 'Lót một nửa lượng gừng thái sợi và một nửa hành lá cắt khúc xuống đáy khay nướng vừa kích thước, xếp 4 miếng phi lê cá lên trên thành một lớp không chồng chéo. Rưới đều hỗn hợp xì dầu nhạt đã pha lên mặt cá rồi rắc nốt phần gừng và hành lá còn lại lên trên (chừa lại ít để phi dầu mè).', 'Lớp gừng hành lót bên dưới vừa giúp cá không dính đáy khay vừa truyền hương thơm đều từ mặt dưới lên.', NULL),
('imp-296dbce4d9098a2e_v4_step_4', 'imp-296dbce4d9098a2e', 4, 'cook', 'Bọc kín giấy bạc và nướng chín cá', 'Đậy kín miệng khay bằng giấy bạc sao cho hơi nước không thoát ra ngoài, cho vào rãnh giữa lò nướng ở 180°C trong 15 phút. Sau đó mở hé giấy bạc kiểm tra thấy thịt cá chuyển trắng đục hoàn toàn và dễ tách thớ khi khều nhẹ bằng nĩa là cá đã chín tới.', 'Nướng kín bằng giấy bạc giữ trọn nước ngọt của phi lê cá; tránh nướng quá lâu làm thớ cá bị khô bở.', 15);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-296dbce4d9098a2e_v4_step_5', 'imp-296dbce4d9098a2e', 5, 'cook', 'Phi thơm tỏi, gừng và hành với dầu mè', 'Trong lúc chờ cá nướng gần xong, đun nóng 15 ml dầu mè thơm trong chảo nhỏ trên lửa vừa, cho tỏi băm vào phi thơm khoảng 30 giây đến khi vừa vàng nhạt rồi cho phần hành lá và gừng sợi còn lại vào đảo nhanh 1 phút cho dậy hương thơm thì tắt bếp.', NULL, 2),
('imp-296dbce4d9098a2e_v4_step_6', 'imp-296dbce4d9098a2e', 6, 'finish', 'Trình bày và rưới dầu mè hành gừng nóng', 'Cẩn thận mở giấy bạc tránh bỏng hơi nóng, nhẹ nhàng chuyển từng miếng phi lê cá ra đĩa sâu lòng. Chan phần nước sốt xì dầu ấm trong khay nướng lên cá, sau đó rưới hỗn hợp hành gừng tỏi phi dầu mè thơm phức lên mặt và dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-0a43bfa1d02fa497_v4_step_1', 'imp-0a43bfa1d02fa497', 1, 'prep', 'Rửa sạch cải bó xôi và băm tỏi', 'Nhặt bỏ phần lá úa và rễ già của 350 g cải bó xôi, tách nhánh rửa kỹ nhiều lượt trong thau nước lạnh cho sạch hoàn toàn đất cát bám ở gốc, vẩy ráo rồi cắt khúc dài 8 đến 10 cm. Tỏi khô bóc vỏ, băm thật nhuyễn để riêng.', 'Giữ lại phần gốc hồng non của cải bó xôi sau khi rửa sạch vì phần này rất giòn và ngọt tự nhiên.', NULL),
('imp-0a43bfa1d02fa497_v4_step_2', 'imp-0a43bfa1d02fa497', 2, 'sauce', 'Pha sẵn nước sốt trộn tỏi giấm đen', 'Cho vào bát nhỏ tỏi băm nhuyễn, 15 ml xì dầu nhạt, 15 ml giấm đen Trấn Giang, 10 ml dầu hào chay nấm đông cô, 10 ml dầu mè thơm, 1 g tiêu trắng xay, 2 g muối ăn và 4 g đường cát trắng. Khuấy đều tay đến khi muối đường tan hoàn toàn.', NULL, NULL),
('imp-0a43bfa1d02fa497_v4_step_3', 'imp-0a43bfa1d02fa497', 3, 'cook', 'Chần nhanh cải bó xôi giữ màu xanh mướt', 'Đun sôi 1200 ml nước lọc trong nồi lớn trên lửa lớn, đồng thời chuẩn bị sẵn một thau nước lạnh có thả đá viên. Khi nước sôi bùng, cho 5 ml dầu ăn thực vật vào nồi và thả một nửa số cải bó xôi vào chần khoảng 40 giây đến khi lá vừa chín mềm vẫn còn xanh tươi.', 'Chia rau thành 2 mẻ chần giúp nhiệt độ nước không tụt đột ngột, nhờ đó rau chín đều và không bị sậm màu.', 1),
('imp-0a43bfa1d02fa497_v4_step_4', 'imp-0a43bfa1d02fa497', 4, 'cook', 'Ngâm sốc nhiệt nước lạnh và chần mẻ tiếp theo', 'Vớt ngay mẻ rau đầu tiên thả vào thau nước đá lạnh để hãm nhiệt. Cho nốt 5 ml dầu ăn thực vật vào nồi nước đang sôi và chần phần cải bó xôi còn lại thêm 40 giây rồi vớt ra ngâm chung vào nước đá đến khi rau nguội hẳn.', NULL, NULL),
('imp-0a43bfa1d02fa497_v4_step_5', 'imp-0a43bfa1d02fa497', 5, 'prep', 'Vắt ráo kiệt nước rau đã chần', 'Vớt cải bó xôi khỏi thau nước lạnh, chia từng nắm nhỏ rồi dùng hai tay bóp vắt nhẹ nhàng nhưng thật kiệt nước để rau không bị nát mà vẫn ráo hoàn toàn, sau đó tách tơi cho vào tô trộn lớn.', 'Rau vắt càng ráo nước thì nước sốt càng bám đều vào từng cọng rau mà không bị chảy loãng ra đáy đĩa.', NULL),
('imp-0a43bfa1d02fa497_v4_step_6', 'imp-0a43bfa1d02fa497', 6, 'finish', 'Trộn đều sốt, ướp mát và rắc mè rang', 'Khuấy đều lại bát sốt rồi rưới lên tô cải bó xôi, trộn nhẹ tay cho gia vị phủ đều khắp cọng rau, nếm thử và chỉnh lại độ chua mặn vừa miệng. Có thể đậy kín để tủ lạnh 10 phút cho mát rồi gắp ra đĩa, rắc hạt mè trắng rang lên trên và thưởng thức.', NULL, 10),
('imp-329f0579ddc26919_v4_step_1', 'imp-329f0579ddc26919', 1, 'prep', 'Khía vỏ và chần bóc vỏ cà chua', 'Chọn 4 quả cà chua chín đỏ nhưng còn cầm chắc tay, rửa sạch rồi dùng mũi dao khía nhẹ hình chữ thập ở phần đáy quả. Đun sôi 1000 ml nước lọc trên lửa lớn, thả cà chua vào chần đúng 30 giây rồi vớt ngay sang thau nước lạnh, lột sạch lớp vỏ mỏng bên ngoài.', 'Chọn cà chua vừa chín tới và chần nhanh không quá 30 giây giúp cà chua dễ bóc vỏ mà ruột vẫn săn, không bị nhũn nát khi trộn.', 1),
('imp-329f0579ddc26919_v4_step_2', 'imp-329f0579ddc26919', 2, 'prep', 'Cắt múi cau cà chua và băm tỏi hành', 'Cắt bỏ cuống cà chua đã bóc vỏ rồi bổ mỗi quả thành 6 đến 8 múi cau vừa ăn, xếp nhẹ vào tô lớn. Băm thật nhuyễn 6 tép tỏi khô, thái nhỏ 30 g hành lá tươi (tách riêng đầu trắng và lá xanh) cùng 10 g ngò rí cắt khúc ngắn.', NULL, NULL),
('imp-329f0579ddc26919_v4_step_3', 'imp-329f0579ddc26919', 3, 'cook', 'Phi thơm một nửa tỏi băm tạo dầu tỏi', 'Làm nóng chảo nhỏ với 10 ml dầu ăn thực vật trên lửa vừa, cho một nửa lượng tỏi băm vào đảo nhanh khoảng 30 giây đến khi tỏi vừa ngả vàng nhạt và dậy mùi thơm thì tắt bếp ngay, để nguội bớt.', 'Kết hợp nửa tỏi phi thơm và nửa tỏi tươi giúp món trộn vừa thơm dịu mùi dầu tỏi vừa giữ nét cay nồng đặc trưng.', NULL),
('imp-329f0579ddc26919_v4_step_4', 'imp-329f0579ddc26919', 4, 'sauce', 'Pha nước sốt chua ngọt xì dầu giấm gạo', 'Trong bát nhỏ, khuấy tan hoàn toàn 25 ml xì dầu nhạt, 15 ml giấm gạo, 10 g đường cát trắng và 2 g muối ăn. Sau đó trộn thêm phần tỏi tươi băm còn lại, đầu hành trắng thái nhỏ và phần dầu tỏi phi vừa nguội vào khuấy đều.', 'Khuấy tan hoàn toàn đường và muối trước khi rưới giúp nước sốt thấm đều vào từng múi cà chua mà không bị lắng cặn dưới đáy tô.', NULL),
('imp-329f0579ddc26919_v4_step_5', 'imp-329f0579ddc26919', 5, 'marinate', 'Trộn nhẹ cà chua và ướp lạnh cho thấm', 'Rưới đều bát nước sốt lên tô cà chua múi cau, dùng thìa lớn đảo thật nhẹ tay từ dưới lên để nước sốt áo đều từng miếng cà chua mà không làm dập nát. Bọc kín tô bằng màng bọc thực phẩm, đặt vào ngăn mát tủ lạnh khoảng 30 phút cho cà chua thấm vị và mát lạnh.', 'Ướp lạnh tối thiểu 30 phút giúp cà chua tiết ra nước ngọt tự nhiên hòa quyện với sốt xì dầu giấm gạo rất thanh mát.', 30),
('imp-329f0579ddc26919_v4_step_6', 'imp-329f0579ddc26919', 6, 'finish', 'Rưới dầu mè thơm và hoàn thiện món trộn', 'Lấy tô cà chua khỏi tủ lạnh, rưới 15 ml dầu mè thơm lên trên rồi trộn nhẹ thêm một lượt cho nước sốt hòa quyện. Gắp cà chua ra đĩa sâu lòng, chan hết phần nước sốt chua ngọt, rắc lá hành xanh và ngò rí lên mặt rồi dùng lạnh ngay.', NULL, NULL),
('imp-59f5760d6349d284_v4_step_1', 'imp-59f5760d6349d284', 1, 'prep', 'Sơ chế và khía mặt nấm đùi gà', 'Rửa sạch 450 g nấm đùi gà tươi, cắt bỏ phần gốc già rồi bổ đôi từng cây theo chiều dọc, dùng mũi dao khía nhẹ hình caro lên mặt cắt bên trong và thấm thật khô bằng khăn giấy. Hành lá tươi thái nhỏ (chừa lại ít lá xanh để rắc mặt), gừng tươi băm nhuyễn.', 'Khía nhẹ mặt cắt của nấm và thấm khô hoàn toàn giúp lớp bột bắp và nhân thịt bám chặt, không bị bung rời khi hấp.', NULL),
('imp-59f5760d6349d284_v4_step_2', 'imp-59f5760d6349d284', 2, 'marinate', 'Quết dẻo nhân thịt heo xay với gia vị', 'Cho 400 g thịt heo xay vào tô lớn cùng trứng gà đánh tan, gừng băm, hành lá thái nhỏ, 15 ml xì dầu nhạt, 15 ml dầu hào, 15 ml rượu Thiệu Hưng, 6 g bột bắp, 5 ml dầu mè thơm, 4 g đường cát trắng, 3 g muối ăn và 1,5 g tiêu trắng xay. Dùng thìa quết mạnh theo một chiều đến khi nhân thành khối dẻo mịn rồi để nghỉ 10 phút.', NULL, 10),
('imp-59f5760d6349d284_v4_step_3', 'imp-59f5760d6349d284', 3, 'prep', 'Áo bột bắp và nhồi nhân lên miếng nấm', 'Rắc mỏng khoảng 2 g bột bắp lên mặt khía của từng miếng nấm đùi gà, sau đó múc từng phần nhân thịt đặt lên trên, dùng thìa ấn và miết nhẹ quanh mép để nhân ôm sát vào thớ nấm. Xếp nấm nhồi vào đĩa sâu lòng chịu nhiệt, hướng mặt nhân lên trên.', 'Lớp bột bắp mỏng đóng vai trò như chất kết dính tự nhiên giữa bề mặt nấm trơn và khối nhân thịt.', NULL),
('imp-59f5760d6349d284_v4_step_4', 'imp-59f5760d6349d284', 4, 'cook', 'Hấp chín nấm nhồi thịt trên lửa lớn', 'Đun sôi mạnh nước trong nồi xửng, đặt đĩa nấm vào hấp ở lửa lớn trong 15 phút. Kiểm tra bằng cách xiên nhẹ tăm vào phần nhân dày nhất: thấy nước chảy ra trong suốt, thịt chín trắng chắc hoàn toàn không còn màu hồng sống và nấm mềm ngọt là đạt.', 'Xếp các miếng nấm hơi thưa nhau để hơi nước lưu thông đều, giúp nhân thịt chín đồng nhất mà nấm không bị nhũn nước.', 15),
('imp-59f5760d6349d284_v4_step_5', 'imp-59f5760d6349d284', 5, 'sauce', 'Tận dụng nước hấp nấu sốt dầu hào sánh mịn', 'Nhấc đĩa nấm ra khỏi xửng, chắt toàn bộ phần nước ngọt tiết ra trên đĩa vào chảo nhỏ và đậy nắp giữ ấm đĩa nấm. Thêm phần nước lọc còn lại (chừa 15 ml hòa tan 4 g bột bắp) sao cho đủ khoảng 100 ml lỏng, cho tiếp 10 ml xì dầu nhạt, 15 ml dầu hào, 4 g đường cát trắng và 5 ml giấm gạo vào đun sôi nhẹ trên lửa nhỏ rồi rót nước bột bắp vào khuấy khoảng 2 phút đến khi sốt sánh bóng.', NULL, 2),
('imp-59f5760d6349d284_v4_step_6', 'imp-59f5760d6349d284', 6, 'finish', 'Rưới sốt nóng và hoàn thiện đĩa nấm hấp', 'Rưới đều phần nước sốt dầu hào xì dầu còn nóng hổi lên từng miếng nấm nhồi thịt, rắc nốt phần hành lá xanh thái nhỏ lên trên và dọn ăn ngay khi còn nóng cùng cơm trắng.', NULL, NULL),
('imp-d8001a64eeaa9150_v4_step_1', 'imp-d8001a64eeaa9150', 1, 'prep', 'Chuẩn bị cơm nóng và các topping khô', 'Chuẩn bị sẵn 360 g cơm trắng hạt ngắn Nhật thật nóng bốc hơi. Rửa sạch hành lá tươi, thấm khô rồi thái khoanh thật mỏng; bóp tơi cá bào khô Katsuobushi và cắt rong biển lá khô Nori thành sợi mảnh.', 'Chỉ sử dụng trứng gà tươi sạch từ nguồn uy tín hoặc trứng đã tiệt trùng để đảm bảo an toàn thực phẩm khi ăn kiểu Tamago Kake Gohan.', NULL),
('imp-d8001a64eeaa9150_v4_step_2', 'imp-d8001a64eeaa9150', 2, 'prep', 'Tách riêng lòng trắng và lòng đỏ trứng gà', 'Đập 2 quả trứng gà tươi, khéo léo tách riêng 2 lòng trắng và 2 lòng đỏ ra từng chén nhỏ để giúp kết cấu cơm trộn bông mịn như sốt kem.', NULL, NULL),
('imp-d8001a64eeaa9150_v4_step_3', 'imp-d8001a64eeaa9150', 3, 'sauce', 'Đánh lòng trắng trứng với xì dầu Nhật', 'Cho 20 ml xì dầu Nhật Bản (và 5 ml rượu ngọt Mirin nếu dùng) vào chén lòng trắng trứng, dùng đũa đánh nhanh tay khoảng 30 giây cho đến khi lòng trắng hơi nổi bọt mịn và hòa đều gia vị.', 'Đánh lòng trắng với xì dầu trước giúp gia vị phân bổ đều khắp hạt cơm và tránh làm lòng trắng còn lợn cợn khi trộn.', NULL),
('imp-d8001a64eeaa9150_v4_step_4', 'imp-d8001a64eeaa9150', 4, 'cook', 'Trộn lòng trắng trứng vào cơm nóng bốc hơi', 'Xới cơm trắng nóng ra 2 tô (180 g/tô), tạo một hõm nhỏ ở giữa rồi chia đều hỗn hợp lòng trắng trứng xì dầu đổ vào từng tô. Dùng đũa trộn thật nhanh và đều tay khoảng 1 phút cho hơi nóng làm lòng trắng sánh lại thành lớp kem mịn phủ quanh từng hạt cơm.', NULL, 1),
('imp-d8001a64eeaa9150_v4_step_5', 'imp-d8001a64eeaa9150', 5, 'finish', 'Phủ cá bào, rong biển và đặt lòng đỏ lên trên', 'Rắc đều cá bào khô Katsuobushi, rong biển lá khô Nori cắt sợi, hạt mè trắng rang và hành lá thái mỏng lên mặt hai tô cơm, sau đó nhẹ nhàng đặt 1 lòng đỏ trứng vào chính giữa mỗi tô.', NULL, NULL),
('imp-d8001a64eeaa9150_v4_step_6', 'imp-d8001a64eeaa9150', 6, 'finish', 'Trộn đều lần cuối và thưởng thức nóng', 'Khi ăn, chọc vỡ lòng đỏ và dùng đũa đảo đều mạnh tay khoảng 1 phút đến khi toàn bộ tô cơm chuyển màu vàng óng mượt mà và bùi béo thì dùng nóng ngay.', 'Không cho quá nhiều xì dầu cùng lúc vì vị mặn gắt sẽ át mất hương béo ngọt tự nhiên của lòng đỏ trứng gà.', 1),
('imp-e420d7a0eed8a0d6_v4_step_1', 'imp-e420d7a0eed8a0d6', 1, 'prep', 'Làm sạch tôm bằng bột năng và sơ chế gia vị', 'Cho 350 g tôm tươi đã bóc vỏ, rút chỉ lưng vào tô, rắc 10 g bột năng vào bóp nhẹ 30 giây để hút sạch nhớt và mùi tanh, sau đó rửa kỹ lại dưới vòi nước lạnh và thấm thật khô bằng khăn giấy. Băm thật nhuyễn gừng tươi và tỏi tươi; hành lá tách riêng phần đầu trắng băm nhỏ và phần lá xanh thái khoanh.', 'Chà tôm với một chút bột năng rồi xả sạch là mẹo giúp thịt tôm giòn săn tự nhiên và hoàn toàn hết mùi tanh.', NULL),
('imp-e420d7a0eed8a0d6_v4_step_2', 'imp-e420d7a0eed8a0d6', 2, 'marinate', 'Ướp tôm với Sake, gia vị và lớp áo bột mỏng', 'Ướp tôm đã thấm khô với 2 g muối ăn, 1 g tiêu trắng xay và 15 ml rượu Sake Nhật Bản, trộn đều rồi tiếp tục rắc thêm 10 g bột năng áo đều quanh từng con tôm; để nghỉ 10 phút cho thấm vị.', NULL, 10),
('imp-e420d7a0eed8a0d6_v4_step_3', 'imp-e420d7a0eed8a0d6', 3, 'cook', 'Áp chảo sơ tôm trên lửa vừa lớn', 'Đun nóng 12 ml dầu ăn thực vật trong chảo rộng trên lửa vừa lớn, xếp tôm thành một lớp thoáng và áp chảo mỗi mặt khoảng 1 phút đến khi mặt ngoài tôm vừa chuyển màu hồng cam và lớp bột se nhẹ thì gắp ngay ra đĩa riêng. Lau sạch cặn cháy nhẹ trong chảo bằng khăn giấy.', 'Không xào tôm chín kỹ ở bước này vì tôm sẽ tiếp tục được đảo cùng sốt nóng; áp chảo vừa chuyển màu giúp tôm giữ được độ giòn mọng.', 2),
('imp-e420d7a0eed8a0d6_v4_step_4', 'imp-e420d7a0eed8a0d6', 4, 'sauce', 'Phi thơm gừng tỏi và xào tương Doubanjiang', 'Cho 13 ml dầu ăn thực vật còn lại vào chảo trên lửa vừa, thả gừng tươi và tỏi băm vào phi khoảng 30 giây đến khi thơm dịu thì hạ lửa nhỏ, thêm 18 g tương ớt đậu bản Doubanjiang vào đảo đều 30 giây cho dậy màu dầu đỏ và hương thơm nồng.', NULL, NULL),
('imp-e420d7a0eed8a0d6_v4_step_5', 'imp-e420d7a0eed8a0d6', 5, 'sauce', 'Đun hòa quyện nền sốt cà cay ngọt', 'Đổ vào chảo 45 ml tương cà Ketchup, 150 ml nước dùng gà, 20 ml rượu Sake còn lại, 15 ml xì dầu Nhật Bản và 8 g đường cát trắng. Khuấy đều và đun sôi liu riu trên lửa vừa khoảng 3 phút cho các gia vị hòa quyện.', NULL, 3),
('imp-e420d7a0eed8a0d6_v4_step_6', 'imp-e420d7a0eed8a0d6', 6, 'cook', 'Nấu chín tôm trong sốt và tạo độ sánh bóng', 'Trút toàn bộ tôm đã áp chảo cùng phần đầu trắng hành lá vào chảo sốt, đảo nhẹ tay khoảng 2 phút đến khi tôm cong tròn, thịt chín đục hoàn toàn. Hòa tan 10 g bột năng còn lại với 45 ml nước lọc rồi rót từ từ vào chảo vừa khuấy đều đến khi sốt sánh bóng bám đều từng con tôm.', 'Rót nước bột năng từ từ từng chút một và khuấy liên tục trên lửa vừa để sốt sánh mượt đều, không bị vón cục.', 2),
('imp-e420d7a0eed8a0d6_v4_step_7', 'imp-e420d7a0eed8a0d6', 7, 'finish', 'Rưới dầu mè thơm và hoàn thiện đĩa tôm', 'Tắt bếp ngay khi sốt sánh đạt độ bóng đẹp, rưới 7 ml dầu mè thơm vào đảo nhanh một vòng để giữ trọn hương thơm. Múc tôm sốt cay ra đĩa nóng, rắc phần lá xanh hành lá thái nhỏ lên trên và dùng kèm cơm trắng.', NULL, NULL),
('imp-2138056075abd874_v4_step_1', 'imp-2138056075abd874', 1, 'prep', 'Ép ráo nước đậu phụ trắng', 'Lấy 300 g đậu phụ trắng loại chắc ra khỏi hộp, bọc kín bằng 2–3 lớp khăn giấy thấm nước rồi đặt lên đĩa phẳng và chèn một vật nặng vừa phải (như thớt nhỏ) lên trên. Để ép khoảng 15 phút cho đậu ráo bớt nước thừa.', 'Ép ráo đậu phụ trước khi trộn giúp miếng đậu săn chắc giữ nguyên khối vuông đẹp mắt và không làm loãng nước sốt salad.', 15),
('imp-2138056075abd874_v4_step_2', 'imp-2138056075abd874', 2, 'prep', 'Cắt khối dưa leo, đậu phụ và thái hành lá', 'Rửa sạch dưa leo tươi, lau thật khô, bổ dọc làm đôi và dùng thìa nạo nhẹ bỏ phần ruột hạt nhiều nước rồi cắt khối vuông cạnh 1,5 cm. Gỡ bỏ khăn giấy quanh đậu phụ và cắt khối vuông 1,5 cm đồng kích thước với dưa leo; hành lá thái khoanh thật mỏng.', NULL, NULL),
('imp-2138056075abd874_v4_step_3', 'imp-2138056075abd874', 3, 'sauce', 'Đánh sốt Miso giấm gạo dầu ô liu', 'Cho 30 g tương Miso trắng Nhật Bản, 40 ml giấm gạo Nhật, 30 ml xì dầu Nhật Bản và 4 g đường cát trắng vào tô nhỏ, dùng phới lồng khuấy tan mịn hoàn toàn. Vừa khuấy đều vừa rót từ từ 30 ml dầu ô liu nguyên chất vào cho sốt quyện sánh, sau đó trộn thêm 15 g hạt mè trắng rang.', 'Phải đánh tan hoàn toàn tương Miso với giấm và xì dầu trước khi rót dầu ô liu để sốt nhũ hóa mịn mượt, không bị vón cục.', NULL),
('imp-2138056075abd874_v4_step_4', 'imp-2138056075abd874', 4, 'prep', 'Trộn nhẹ nhàng đậu phụ và dưa leo với sốt', 'Cho đậu phụ cắt khối, dưa leo và hành lá thái mỏng vào tô trộn rộng, rưới đều toàn bộ phần sốt Miso mè rang lên trên. Dùng thìa dẹt hất nhẹ từ đáy tô lên để sốt phủ đều khắp mặt mà không làm vỡ nát miếng đậu phụ.', 'Dùng tô rộng và hất nhẹ từ đáy lên giúp các khối đậu phụ giữ nguyên hình dạng vuông vức, không bị nát vụn.', NULL),
('imp-2138056075abd874_v4_step_5', 'imp-2138056075abd874', 5, 'prep', 'Làm lạnh salad cho thấm vị', 'Bọc kín miệng tô bằng màng bọc thực phẩm và đặt vào ngăn mát tủ lạnh khoảng 10 phút cho các nguyên liệu mát giòn và ngấm đều hương vị sốt.', NULL, 10),
('imp-2138056075abd874_v4_step_6', 'imp-2138056075abd874', 6, 'finish', 'Bày đĩa, rắc mè rang và thưởng thức', 'Lấy salad đậu phụ dưa leo ra khỏi tủ lạnh, múc nhẹ nhàng vào đĩa sâu lòng, rắc 5 g hạt mè trắng rang còn lại lên mặt và dùng lạnh ngay.', NULL, NULL),
('imp-ff9fd0fdcdd85b79_v4_step_1', 'imp-ff9fd0fdcdd85b79', 1, 'prep', 'Cắt miếng bắp cải và sơ chế tỏi, hành lá', 'Bóc bỏ lá già ngoài cùng của 400 g bắp cải tươi, rửa sạch và để thật ráo nước. Bổ bắp cải thành miếng to cỡ 4–5 cm sao cho các lớp lá vẫn bám với nhau (phần lõi cứng thái lát mỏng hơn cho nhanh chín). Thái lát mỏng tỏi tươi và thái khoanh nhỏ hành lá.', 'Để bắp cải thật ráo nước trước khi áp chảo giúp lá rau nhanh xém vàng thơm mà không bị tiết nước hấp nhũn.', NULL),
('imp-ff9fd0fdcdd85b79_v4_step_2', 'imp-ff9fd0fdcdd85b79', 2, 'cook', 'Áp chảo mặt đầu bắp cải không đảo', 'Làm nóng chảo rộng trên lửa vừa với 10 ml dầu ăn thực vật. Xếp các miếng bắp cải thành một lớp phẳng xuống đáy chảo và giữ yên không đảo trong 3 phút cho mặt dưới xém vàng nâu nhẹ và dậy mùi ngọt tự nhiên.', 'Không đảo liên tục trong 3 phút đầu là bí quyết giúp bắp cải cháy cạnh thơm lừng như nướng vỉ thay vì ra nước như món xào.', 3),
('imp-ff9fd0fdcdd85b79_v4_step_3', 'imp-ff9fd0fdcdd85b79', 3, 'cook', 'Lật mặt áp tiếp cho bắp cải chín mềm', 'Dùng kẹp hoặc xẻng lật nhẹ nhàng từng miếng bắp cải sang mặt còn lại, áp tiếp trên lửa vừa khoảng 3 phút đến khi mặt thứ hai cũng hơi xém cạnh và phần lá bắt đầu mềm dịu.', NULL, 3),
('imp-ff9fd0fdcdd85b79_v4_step_4', 'imp-ff9fd0fdcdd85b79', 4, 'cook', 'Đậy nắp hấp nhanh làm mềm phần lõi', 'Đậy nắp chảo và hạ lửa vừa nhỏ thêm khoảng 2 phút để hơi ẩm tự nhiên trong bắp cải làm chín mềm phần cuống dày bên trong.', NULL, 2),
('imp-ff9fd0fdcdd85b79_v4_step_5', 'imp-ff9fd0fdcdd85b79', 5, 'sauce', 'Làm tan chảy bơ lạt với tỏi và xì dầu Nhật', 'Mở nắp, hạ lửa nhỏ rồi thả 25 g bơ lạt cùng tỏi thái lát vào chảo, nghiêng nhẹ cho bơ tan chảy quyện mùi tỏi thơm trong 1 phút. Rưới 15 ml xì dầu Nhật Bản dọc theo mép chảo nóng, rắc 2 g muối ăn và 1 g tiêu đen xay rồi đảo nhanh tay cho bơ xì dầu áo bóng từng miếng bắp cải.', 'Rưới xì dầu vào thành chảo nóng giúp tạo hương thơm xì dầu cháy đặc trưng mà không làm bắp cải bị mặn cục bộ.', 1),
('imp-ff9fd0fdcdd85b79_v4_step_6', 'imp-ff9fd0fdcdd85b79', 6, 'finish', 'Rắc hành lá, cá bào và thưởng thức nóng', 'Tắt bếp, gắp bắp cải áp chảo ra đĩa nóng và rưới phần bơ xì dầu còn lại trong chảo lên trên, rắc hành lá thái nhỏ cùng cá bào khô Katsuobushi (nếu dùng) và ăn ngay khi còn nóng.', NULL, NULL),
('imp-d6e35b3fa19080de_v4_step_1', 'imp-d6e35b3fa19080de', 1, 'prep', 'Sơ chế nấm đùi gà, hành lá và đánh trứng', 'Lau sạch 200 g nấm đùi gà tươi, cắt bỏ phần gốc cứng rồi thái lát mỏng dày khoảng 0,5 cm. Rửa sạch hành lá tươi và thái khoanh mỏng. Đập 5 quả trứng gà tươi ra tô, dùng đũa đánh tan đều lòng đỏ và lòng trắng nhưng không đánh nổi bọt.', 'Chỉ đánh nhẹ cho lòng trắng và lòng đỏ hòa đều thành dòng mịn; đánh quá mạnh tạo nhiều bọt khí sẽ khiến trứng om bị rỗ mặt.', NULL),
('imp-d6e35b3fa19080de_v4_step_2', 'imp-d6e35b3fa19080de', 2, 'sauce', 'Pha và đun sôi nước dùng om kiểu Nhật', 'Cho 300 ml nước dùng Dashi vào nồi nông hoặc chảo sâu lòng, thêm 18 ml xì dầu nhạt Nhật Bản, 15 ml rượu ngọt Mirin, 10 ml rượu Sake, 8 g đường cát trắng và 1,5 g muối ăn. Khuấy tan gia vị rồi đun trên lửa vừa khoảng 3 phút cho đến khi nước om sôi lăn tăn.', NULL, 3),
('imp-d6e35b3fa19080de_v4_step_3', 'imp-d6e35b3fa19080de', 3, 'cook', 'Om chín mềm nấm đùi gà trong nước dùng', 'Thả toàn bộ nấm đùi gà thái lát vào nồi nước om đang sôi, dàn đều và nấu trên lửa vừa khoảng 3 phút cho nấm chín mềm, giữ độ giòn nhẹ và tiết vị ngọt vào nước dùng.', NULL, 3),
('imp-d6e35b3fa19080de_v4_step_4', 'imp-d6e35b3fa19080de', 4, 'cook', 'Rưới trứng gà đánh tan và rắc hành lá', 'Hạ nhỏ lửa xuống mức thấp để nước chỉ lăn tăn nhẹ. Rưới từ từ tô trứng gà đánh tan theo vòng xoắn ốc phủ đều lên khắp mặt nấm, sau đó rắc đều phần hành lá thái khoanh lên trên.', 'Rưới trứng thành dòng mảnh theo vòng tròn từ ngoài vào trong giúp trứng chín đều thành mảng mềm mịn ôm lấy từng lát nấm.', NULL),
('imp-d6e35b3fa19080de_v4_step_5', 'imp-d6e35b3fa19080de', 5, 'cook', 'Đậy nắp om chín tới cho trứng mềm mượt', 'Đậy nắp nồi và om trên lửa nhỏ khoảng 2 phút cho đến khi phần lòng trắng chín đông hoàn toàn và trứng đạt độ mềm ẩm mượt mà thì tắt bếp ngay, tránh nấu quá lâu làm trứng khô cứng.', 'Tắt bếp ngay khi trứng vừa se mặt vì lượng nhiệt dư trong nồi sẽ tiếp tục làm trứng chín mịn hoàn hảo.', 2),
('imp-d6e35b3fa19080de_v4_step_6', 'imp-d6e35b3fa19080de', 6, 'finish', 'Múc ra tô và rắc tiêu thưởng thức nóng', 'Nhẹ nhàng xắn chia trứng om nấm ra 3 tô cùng nước dùng trong nồi, rắc thêm chút tiêu đen xay nếu thích và dùng nóng ngay với cơm trắng hoặc mì.', NULL, NULL),
('imp-cc88c6bd94df496e_v4_step_1', 'imp-cc88c6bd94df496e', 1, 'prep', 'Sơ chế thịt cua, nấm đùi gà và hành lá', 'Kiểm tra và nhặt sạch vụn vỏ nếu có trong 200 g thịt cua hấp chín gỡ sẵn, tách nhẹ thành thớ vừa ăn. Lau sạch 150 g nấm đùi gà tươi, bỏ gốc rồi thái lát mỏng dài 3 cm; rửa sạch hành lá tươi và thái khoanh mỏng.', NULL, NULL),
('imp-cc88c6bd94df496e_v4_step_2', 'imp-cc88c6bd94df496e', 2, 'cook', 'Đun sôi nhẹ nước dùng Dashi', 'Đổ 450 ml nước lọc và 150 ml nước dùng Dashi vào nồi, đun trên lửa vừa đến khi nước dùng sôi lăn tăn nhẹ nhàng.', 'Không đun sôi bùng quá mạnh để giữ hương thơm tinh tế của Dashi và giúp nước canh trong vắt.', NULL),
('imp-cc88c6bd94df496e_v4_step_3', 'imp-cc88c6bd94df496e', 3, 'cook', 'Nấu chín mềm nấm đùi gà', 'Thả toàn bộ nấm đùi gà thái lát vào nồi nước dùng, hạ lửa vừa nhỏ và nấu khoảng 3 phút cho đến khi nấm chín mềm và tiết vị ngọt tự nhiên.', NULL, 3),
('imp-cc88c6bd94df496e_v4_step_4', 'imp-cc88c6bd94df496e', 4, 'sauce', 'Nêm Sake, xì dầu nhạt và muối thanh nhẹ', 'Thêm 15 ml rượu Sake Nhật Bản, 10 ml xì dầu nhạt Nhật Bản và 2,5 g muối ăn vào nồi canh, khuấy nhẹ cho tan đều rồi nếm thử để điều chỉnh độ mặn thanh hài hòa.', 'Canh trong kiểu Nhật đề cao vị thanh dịu tự nhiên nên chỉ nêm xì dầu nhạt vừa đủ dậy hương, tránh làm sẫm màu nước canh.', NULL),
('imp-cc88c6bd94df496e_v4_step_5', 'imp-cc88c6bd94df496e', 5, 'cook', 'Thả thịt cua làm nóng nhanh và hớt bọt', 'Nhẹ nhàng cho 200 g thịt cua vào nồi canh, đun lửa nhỏ khoảng 2 phút cho nước vừa sôi lăn tăn trở lại và thịt cua nóng đều tận lõi; dùng muôi hớt sạch bọt mỏng nổi trên mặt nếu có.', 'Thịt cua đã hấp chín sẵn nên chỉ nấu nhanh 2 phút để làm nóng và quyện vị, tránh đun lâu làm thịt cua bị bở xác.', 2),
('imp-cc88c6bd94df496e_v4_step_6', 'imp-cc88c6bd94df496e', 6, 'finish', 'Tắt bếp, rắc hành lá và dọn nóng', 'Tắt bếp ngay, múc canh cua nấm ra 3 bát, chia đều thịt cua và nấm đùi gà rồi rắc hành lá thái nhỏ lên mặt để giữ màu xanh tươi và thưởng thức nóng.', NULL, NULL),
('imp-df7a6429150724b1_v4_step_1', 'imp-df7a6429150724b1', 1, 'prep', 'Sơ chế tôm tươi, cà chua và hành tỏi', 'Rửa sạch 300 g tôm tươi đã bóc vỏ, rút chỉ đen, thấm thật khô bằng khăn giấy. Cà chua chín bỏ cuống, cắt miếng nhỏ vừa ăn; hành tây bóc vỏ thái lát mỏng; tỏi tươi băm nhuyễn và hành lá thái khoanh mỏng.', NULL, NULL),
('imp-df7a6429150724b1_v4_step_2', 'imp-df7a6429150724b1', 2, 'cook', 'Phi tỏi và áp chảo sơ tôm cho săn ngọt', 'Đun nóng 15 ml dầu ô liu trong chảo sâu lòng trên lửa vừa, cho tỏi băm vào phi khoảng 20 giây đến khi thơm nhẹ rồi trút tôm vào đảo nhanh tay với 1 g muối ăn trong khoảng 2 phút đến khi tôm vừa chuyển màu hồng thì gắp ngay ra đĩa riêng.', 'Xào sơ tôm rồi lấy ra trước khi om cà chua giúp tôm giữ độ giòn ngọt, không bị dai hay teo nhỏ do om lâu.', 2),
('imp-df7a6429150724b1_v4_step_3', 'imp-df7a6429150724b1', 3, 'cook', 'Xào hành tây mềm ngọt', 'Vẫn dùng chảo đó trên lửa vừa, cho toàn bộ hành tây thái lát vào đảo đều khoảng 3 phút đến khi hành tây chuyển trong và tỏa mùi thơm ngọt tự nhiên.', NULL, 3),
('imp-df7a6429150724b1_v4_step_4', 'imp-df7a6429150724b1', 4, 'sauce', 'Om cà chua với xì dầu, tương cà và Sake', 'Cho cà chua cắt miếng vào chảo cùng 18 ml xì dầu Nhật Bản, 15 ml tương cà Ketchup, 22 ml rượu Sake Nhật Bản, 5 g đường cát trắng, 1 g muối ăn còn lại và 100 ml nước lọc. Đảo đều, đun sôi rồi hạ lửa nhỏ, đậy nắp om khoảng 6 phút cho cà chua nhừ ra sốt đỏ sánh.', 'Nếm thử sốt cà chua ở bước này; tùy độ chua ngọt của cà chua mà có thể gia giảm thêm một chút đường cho hài hòa.', 6),
('imp-df7a6429150724b1_v4_step_5', 'imp-df7a6429150724b1', 5, 'cook', 'Thả tôm vào om thấm sốt cà chua', 'Mở nắp, trút toàn bộ tôm đã áp chảo trở lại chảo sốt, đảo nhẹ cho sốt phủ đều và om trên lửa vừa thêm 2–3 phút đến khi tôm cong tròn, thịt chín đục hoàn toàn và nước sốt sánh quyện.', 'Quan sát thân tôm vừa cuộn tròn hình chữ C và chuyển màu đỏ hồng đồng nhất là đạt, không om quá lâu để tránh tôm bị khô xác.', 3),
('imp-df7a6429150724b1_v4_step_6', 'imp-df7a6429150724b1', 6, 'finish', 'Rắc tiêu, hành lá và dọn ăn nóng', 'Tắt bếp, rắc 1 g tiêu đen xay cùng hành lá thái khoanh lên trên, đảo nhẹ một vòng rồi múc ra đĩa sâu lòng dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-9157234945e6ff01_v4_step_1', 'imp-9157234945e6ff01', 1, 'prep', 'Ngâm miến khoai lang và sơ chế gà, rau củ', 'Ngâm 100 g miến khoai lang Hàn Quốc trong nước lạnh ít nhất 35 phút cho mềm. Trộn 800 g đùi gà chặt miếng với 2 g muối ăn và 1 g tiêu đen xay để nghỉ 15 phút. Thái miếng khoai tây dày 1,5 cm, thái vát cà rốt và nấm đùi gà, bổ múi cau hành tây, thái lát dưa leo, cắt khúc ớt tươi và thái sợi hành lá ngâm nước lạnh.', 'Ngâm đủ thời gian giúp sợi miến khoai lang hút nước từ từ, khi cho vào chảo hầm sẽ chín trong và dai ngon mà không hút cạn hết nước sốt.', 35),
('imp-9157234945e6ff01_v4_step_2', 'imp-9157234945e6ff01', 2, 'sauce', 'Pha hỗn hợp sốt tương đen Andong', 'Trong tô vừa, khuấy tan đều 60 ml nước tương Hàn Quốc, 30 ml dầu hào, 50 ml siro ngô, 15 g tương đen Hàn Quốc (Chunjang), tỏi băm nhuyễn và gừng băm nhuyễn đến khi sốt mịn đồng nhất.', 'Một lượng nhỏ tương đen Chunjang tạo màu nâu sẫm bóng đẹp và vị mặn ngọt dịu đặc trưng mà không cần dùng nhiều đường thắng.', NULL),
('imp-9157234945e6ff01_v4_step_3', 'imp-9157234945e6ff01', 3, 'cook', 'Áp chảo săn vàng hai mặt đùi gà', 'Đun nóng chảo sâu lòng trên lửa vừa-cao với 30 ml dầu ăn thực vật, xếp đùi gà vào áp chảo 3 phút mỗi mặt cho lớp da và thịt se săn vàng nhẹ, giúp thịt gà chắc thơm và không bị bở khi hầm.', NULL, 6),
('imp-9157234945e6ff01_v4_step_4', 'imp-9157234945e6ff01', 4, 'cook', 'Hầm gà cùng khoai tây và hành tây', 'Đổ hỗn hợp sốt đã pha cùng 500 ml nước lọc, khoai tây và hành tây vào chảo gà. Đảo đều cho sốt hòa tan, đậy nắp và nấu lửa vừa-cao trong 12 phút đến khi khoai tây gần chín bở và thịt gà chín mềm từ bên trong.', NULL, 12),
('imp-9157234945e6ff01_v4_step_5', 'imp-9157234945e6ff01', 5, 'cook', 'Cho miến, nấm, cà rốt và ớt vào om thấm sốt', 'Vớt miến khoai lang ra để ráo rồi thả vào chảo cùng cà rốt, nấm đùi gà và ớt tươi. Đảo đều bằng đũa gỗ trên lửa vừa trong 5 phút đến khi sợi miến chuyển trong suốt, dẻo dai, rau củ chín tới và nước sốt còn sệt vừa phải.', 'Nếu nước sốt cạn nhanh trước khi miến trong, châm thêm 50–80 ml nước lọc nóng và hạ nhỏ lửa.', 5),
('imp-9157234945e6ff01_v4_step_6', 'imp-9157234945e6ff01', 6, 'finish', 'Trộn dưa leo, rưới dầu mè và bày biện', 'Tắt bếp ngay, thả dưa leo thái lát, 1 g tiêu đen xay còn lại và 10 ml dầu mè rang vào đảo nhanh một lượt cho dưa leo giữ độ giòn mát. Vớt hành lá thái sợi ra để ráo đặt lên giữa mặt chảo, rắc hạt mè trắng rang rồi dọn nóng.', NULL, NULL),
('imp-aedcf1c5c1d05d04_v4_step_1', 'imp-aedcf1c5c1d05d04', 1, 'prep', 'Làm sạch và ướp sơ tôm tươi', 'Tôm tươi bóc vỏ, rút sạch chỉ đen dọc lưng, rửa qua nước muối loãng rồi dùng khăn giấy thấm thật ráo. Ướp tôm với 1 g muối ăn và 1 g tiêu đen xay trong 10 phút cho thịt tôm săn chắc. Thái lát mỏng hành tây, cắt khúc hành lá (tách riêng đầu trắng và lá xanh), băm nhỏ tỏi.', 'Thấm thật ráo nước giúp tôm xào săn giòn và bắt sốt nhanh mà không bị tiết nước đọng đáy chảo.', 10),
('imp-aedcf1c5c1d05d04_v4_step_2', 'imp-aedcf1c5c1d05d04', 2, 'sauce', 'Hòa sẵn hỗn hợp sốt tương Mirin', 'Trong chén nhỏ, khuấy tan 25 ml nước tương, 15 ml rượu ngọt Mirin Nhật và 6 g đường cát trắng để khi xào tôm chỉ việc rưới ngay vào chảo.', NULL, NULL),
('imp-aedcf1c5c1d05d04_v4_step_3', 'imp-aedcf1c5c1d05d04', 3, 'cook', 'Phi thơm tỏi cùng bơ và dầu ăn', 'Làm nóng chảo trên lửa vừa với 15 ml dầu ăn thực vật và 12 g bơ lạt. Khi bơ vừa tan sủi bọt, cho tỏi băm vào phi khoảng 30 giây đến khi dậy mùi thơm dịu mà tỏi chưa bị cháy vàng sậm.', 'Kết hợp dầu ăn cùng bơ giúp nâng điểm bốc khói, giữ bơ thơm béo mà không bị cháy khét.', NULL),
('imp-aedcf1c5c1d05d04_v4_step_4', 'imp-aedcf1c5c1d05d04', 4, 'cook', 'Xào lửa lớn cho tôm cong hồng chín săn', 'Tăng lên lửa lớn, trút toàn bộ tôm đã ướp vào chảo xào nhanh tay khoảng 2–3 phút đến khi thân tôm uốn cong, chuyển màu đỏ hồng đục đều và chín hoàn toàn.', 'Xào tôm nhanh trên lửa lớn giúp thịt tôm săn giòn giữ được vị ngọt, không đảo quá 3 phút kẻo tôm bị khô xác.', 3),
('imp-aedcf1c5c1d05d04_v4_step_5', 'imp-aedcf1c5c1d05d04', 5, 'cook', 'Rưới sốt tương và xào cùng hành tây, đầu hành', 'Rưới hỗn hợp sốt tương Mirin vào chảo, thêm hành tây thái lát và phần đầu trắng hành lá, đảo đều trên lửa lớn thêm 2 phút cho hành vừa chín tới giòn ngọt và nước sốt rút sánh quyện quanh từng con tôm.', NULL, 2),
('imp-aedcf1c5c1d05d04_v4_step_6', 'imp-aedcf1c5c1d05d04', 6, 'finish', 'Thả lá hành, rưới dầu mè và rắc mè rang', 'Cho phần lá xanh hành lá vào đảo nhanh một lượt rồi tắt bếp, rưới 5 ml dầu mè rang lên trên. Trút tôm ra đĩa, xoa nhẹ hạt mè trắng rang rắc đều lên mặt và dùng nóng với cơm trắng.', NULL, NULL),
('imp-e39a1be406f9e1ea_v4_step_1', 'imp-e39a1be406f9e1ea', 1, 'prep', 'Pha gia vị ướp hành lá và đánh tan trứng', 'Thái nhỏ hành lá. Trộn 2/3 lượng hành lá với 10 ml nước mắm ngon, 5 ml nước tương, 3 g đường cát trắng, 4 ml dầu mè rang và 0,5 g tiêu đen xay trong chén nhỏ, để nghỉ 2 phút cho thấm. Đập 5 quả trứng gà vào tô lớn đánh thật tan, rồi đổ 220 ml nước lọc cùng chén hành lá gia vị vào khuấy đều.', 'Tỉ lệ nước gần tương đương thể tích trứng giúp kết cấu trứng hấp mềm ẩm và nở phồng xốp đẹp mắt.', NULL),
('imp-e39a1be406f9e1ea_v4_step_2', 'imp-e39a1be406f9e1ea', 2, 'cook', 'Nấu trứng giai đoạn đầu trong nồi đất đậy nắp', 'Đổ hỗn hợp trứng vào nồi đất Hàn Quốc hoặc nồi inox đáy dày cỡ nhỏ (nên dùng nồi sâu lòng sao cho trứng chiếm khoảng 2/3 chiều cao nồi). Đậy nắp kín, nấu trên lửa vừa khoảng 7 phút.', 'Không đổ trứng quá đầy miệng nồi để chừa không gian cho trứng nở phồng lên khi gặp hơi nóng.', 7),
('imp-e39a1be406f9e1ea_v4_step_3', 'imp-e39a1be406f9e1ea', 3, 'cook', 'Khuấy nhẹ giữa chừng giúp trứng chín xốp đều', 'Mở nắp nồi: lúc này phần rìa và đáy trứng đã bắt đầu đông đặc còn phần giữa vẫn sánh loãng. Dùng thìa khuấy nhẹ nhàng từ đáy lên trên trong vài giây cho hỗn hợp hòa đều và không bị cháy đáy, sau đó đậy nắp lại ngay.', 'Bước khuấy nhẹ giữa chừng giúp nhiệt phân bổ đều khắp khối trứng, tạo độ bông xốp tơi nhẹ chứ không bị chai cứng đáy.', NULL),
('imp-e39a1be406f9e1ea_v4_step_4', 'imp-e39a1be406f9e1ea', 4, 'cook', 'Hạ lửa nhỏ ủ cho trứng phồng xốp hoàn toàn', 'Hạ xuống lửa nhỏ, tiếp tục nấu kín nắp thêm 4 phút đến khi khối trứng nở phồng cao lên sát nắp, mặt trứng se mịn và chín hẳn ở tâm.', NULL, 4),
('imp-e39a1be406f9e1ea_v4_step_5', 'imp-e39a1be406f9e1ea', 5, 'cook', 'Ủ thêm hơi nóng trong 1 phút tạo mùi thơm đáy nồi', 'Giữ nguyên nắp đậy và hạ lửa thật nhỏ thêm 1 phút để phần đáy có lớp xém vàng thơm nhẹ (không để quá lâu kẻo khét đắng) rồi tắt bếp.', NULL, 1),
('imp-e39a1be406f9e1ea_v4_step_6', 'imp-e39a1be406f9e1ea', 6, 'finish', 'Rắc hành lá, tiêu, ớt bột và dầu mè dọn nóng', 'Mở nắp nồi, nhanh tay rắc phần hành lá còn lại, 0,5 g tiêu đen xay, 2 g ớt bột Hàn Quốc, hạt mè trắng rang và rưới nốt 4 ml dầu mè rang lên mặt trứng đang phồng xốp rồi thưởng thức ngay.', NULL, NULL),
('imp-da5a134e2654eeb5_v4_step_1', 'imp-da5a134e2654eeb5', 1, 'prep', 'Sơ chế và ướp ngấm kim chi với gia vị', 'Cắt 280 g kim chi cải thảo thành miếng vừa ăn, thái mỏng hành tây, cắt khúc hành lá (chừa ít lá xanh để rắc mặt), băm nhuyễn tỏi và gừng. Cho kim chi, hành tây, phần lớn hành lá, tỏi băm, gừng băm, 30 g tương ớt Hàn Quốc, 15 ml nước tương, 12 g đường cát trắng, 10 ml dầu mè rang và 1 g tiêu đen xay vào tô trộn đều, để 10 phút cho thấm vị.', 'Ướp kim chi trước với đường và gia vị giúp giảm vị chua gắt và khiến kim chi thấm đều hương vị khi lên chảo.', 10),
('imp-da5a134e2654eeb5_v4_step_2', 'imp-da5a134e2654eeb5', 2, 'cook', 'Luộc làm mềm đậu phụ trắng', 'Đun sôi 800 ml nước lọc trong nồi trên lửa lớn, hạ về lửa vừa rồi thả nhẹ 4 miếng đậu phụ trắng vào luộc khoảng 5 phút cho đậu nóng đều từ trong ra ngoài và có kết cấu mềm mịn.', 'Luộc đậu ở mức sôi lăn tăn lửa vừa giúp miếng đậu nóng mềm đồng đều mà không bị rỗ mặt hoặc vỡ cạnh.', 5),
('imp-da5a134e2654eeb5_v4_step_3', 'imp-da5a134e2654eeb5', 3, 'prep', 'Vớt đậu phụ để ráo và thái lát', 'Dùng vá lỗ nhẹ nhàng vớt đậu phụ ra rổ cho ráo hơi nước trong 2 phút, sau đó đặt lên thớt thái từng miếng thành lát dày khoảng 1,2 cm thật nhẹ tay để không làm vỡ mép đậu.', NULL, NULL),
('imp-da5a134e2654eeb5_v4_step_4', 'imp-da5a134e2654eeb5', 4, 'cook', 'Xào săn kim chi cho dậy mùi cay thơm', 'Làm nóng chảo trên lửa vừa-cao với 10 ml dầu ăn thực vật, đổ toàn bộ tô kim chi đã ướp vào xào đều tay trong 5 phút đến khi lá kim chi mềm dịu, hành tây trong lại và phần nước tiết ra bay hơi sệt bóng.', 'Xào đến khi nước kim chi rút sệt lại để khi xếp lên đĩa không bị chảy nước làm nhão phần đậu phụ.', 5),
('imp-da5a134e2654eeb5_v4_step_5', 'imp-da5a134e2654eeb5', 5, 'cook', 'Điều chỉnh gia vị và rưới dầu mè', 'Nếm thử phần kim chi xào (nếu quá chua có thể thêm chút đường, thích đậm hơn thêm chút nước tương), tắt bếp và rưới nốt 5 ml dầu mè rang còn lại vào đảo đều.', NULL, NULL),
('imp-da5a134e2654eeb5_v4_step_6', 'imp-da5a134e2654eeb5', 6, 'finish', 'Bày đĩa đậu phụ kẹp kim chi xào', 'Xếp các lát đậu phụ trắng luộc ấm thành vòng tròn quanh mép đĩa, múc phần kim chi xào nóng vào chính giữa (hoặc rắc đều lên mặt đậu), rắc hành lá xanh thái nhỏ và hạt mè trắng rang lên trên rồi thưởng thức.', NULL, NULL),
('imp-8cd9bb1abdd63a9e_v4_step_1', 'imp-8cd9bb1abdd63a9e', 1, 'cook', 'Hầm nước dùng bò trong và luộc mềm thịt nạm', 'Lau sạch máu trên 225 g thịt nạm bò bằng khăn sạch rồi cho vào nồi cùng 1100 ml nước lọc. Đun lửa lớn cho sôi và hớt thật sạch bọt, sau đó hạ lửa nhỏ hầm trong 35 phút. Thêm hành lá và tỏi đập dập vào hầm tiếp 15 phút cho nước dùng ngọt thơm rồi vớt thịt bò ra để nguội, lọc bỏ xác hành tỏi.', 'Hớt sạch bọt và lọc qua rây mịn giúp nước dùng naengmyeon thật trong, không bị váng đục khi làm lạnh.', 50),
('imp-8cd9bb1abdd63a9e_v4_step_2', 'imp-8cd9bb1abdd63a9e', 2, 'sauce', 'Pha nước dùng chua ngọt và làm lạnh dăm đá', 'Để nước dùng bò nguội hẳn rồi hớt sạch lớp mỡ nổi trên mặt. Hòa tan 15 ml nước tương, 30 ml giấm gạo trắng, 20 g đường cát trắng, 6 g muối ăn và 5 g mù tạt vàng vào nước dùng, nêm lại vị chua ngọt dịu vừa miệng rồi cho vào ngăn đá 2–3 giờ đến khi mặt nước bắt đầu đóng lớp dăm đá mỏng.', 'Vị nước dùng khi nguội lạnh sẽ nhạt hơn lúc còn ấm một chút, vì vậy có thể pha đậm nhẹ trước khi cho vào ngăn đá.', NULL),
('imp-8cd9bb1abdd63a9e_v4_step_3', 'imp-8cd9bb1abdd63a9e', 3, 'prep', 'Muối nhanh củ cải, dưa leo và luộc trứng', 'Thái lát mỏng củ cải trắng, trộn đều với 15 ml giấm gạo, 10 g đường cát trắng, 1,5 g muối ăn và 2 g ớt bột Hàn Quốc, ướp 20 phút. Thái chéo mỏng dưa leo, ướp 1,5 g muối ăn trong 15 phút rồi vắt nhẹ cho ráo giòn. Luộc 2 quả trứng gà với 3 g muối ăn trong 10 phút, ngâm nước lạnh rồi bóc vỏ bổ đôi. Thái lát mỏng thịt bò luộc nguội.', NULL, 20),
('imp-8cd9bb1abdd63a9e_v4_step_4', 'imp-8cd9bb1abdd63a9e', 4, 'cook', 'Luộc chín mì kiều mạch và xả nước đá thật dai', 'Đun sôi nồi nước lớn (khoảng 900 ml trở lên), thả 300 g mì kiều mạch vào đảo nhẹ cho tơi sợi và luộc khoảng 3 phút đến khi lõi mì vừa chín tới nhưng vẫn giữ độ dai. Lập tức vớt mì ra xả mạnh dưới vòi nước lạnh, dùng tay vò nhẹ cho sạch hết nhớt tinh bột rồi ngâm nhanh trong thau nước đá và vắt ráo.', 'Xả thật sạch lớp nhớt ngoài sợi mì rồi chần nước đá là bí quyết giúp sợi naengmyeon dai sần sật và giữ nước dùng trong veo.', 3),
('imp-8cd9bb1abdd63a9e_v4_step_5', 'imp-8cd9bb1abdd63a9e', 5, 'finish', 'Xếp mì, chan nước dùng dăm đá và bày topping', 'Cuộn mì thành từng vắt gọn đặt vào 3 tô sâu lòng. Khuấy đều phần nước dùng dăm đá rồi chan nhẹ men theo thành tô. Xếp thịt bò thái lát, củ cải trộn chua ngọt, dưa leo giòn và nửa quả trứng luộc lên mặt, rắc hạt mè trắng rang và ớt sừng đỏ thái sợi rồi thưởng thức ngay.', NULL, NULL),
('imp-8cd9bb1abdd63a9e_v4_step_6', 'imp-8cd9bb1abdd63a9e', 6, 'finish', 'Thưởng thức và gia giảm thêm tại bàn', 'Dọn mì lạnh kèm giấm gạo trắng và mù tạt vàng ở bên cạnh để từng người tự gia giảm thêm độ chua cay theo khẩu vị, dùng đũa và kéo cắt ngắn sợi mì nếu cần trước khi ăn.', NULL, NULL),
('imp-a631650d667191b4_v4_step_1', 'imp-a631650d667191b4', 1, 'prep', 'Chà muối làm sạch nhớt và khứa caro thân mực', 'Tách bỏ nội tạng, mắt, mỏ cứng và thanh mai trong thân 500 g mực tươi. Dùng 15 g muối hạt chà xát kỹ thân và các giác hút râu mực cho hết nhớt rồi xả sạch nhiều lần dưới vòi nước lạnh và thấm khô. Kê hai chiếc đũa hai bên thân mực để khứa caro nông mặt trong mà không cắt thủng.', 'Chà muối hạt giúp làm sạch cát bám trên râu mực rất hiệu quả và giúp bóc màng da mực dễ dàng hơn.', NULL),
('imp-a631650d667191b4_v4_step_2', 'imp-a631650d667191b4', 2, 'marinate', 'Pha sốt cay Gochujang và ướp mực 20 phút', 'Khuấy đều 45 g tương ớt Hàn Quốc, 8 g ớt bột Hàn Quốc, 30 ml siro ngô, 15 ml nước tương, 8 g đường cát trắng, 15 ml rượu ngọt Mirin Nhật, tỏi băm, gừng băm, 5 g mù tạt vàng, 1 g tiêu đen xay, 5 ml dầu mè rang và 1/2 lượng hành lá thái nhỏ. Trộn mực thấm đều sốt và ướp trong ngăn mát 20 phút.', 'Chỉ nên ướp mực khoảng 20–30 phút để mực thấm vị bên ngoài mà giữ nguyên độ giòn sần sật, tránh ướp qua đêm làm thịt mực bị bở.', 20),
('imp-a631650d667191b4_v4_step_3', 'imp-a631650d667191b4', 3, 'cook', 'Làm nóng vỉ nướng hoặc chảo gang trên lửa lớn', 'Đun thật nóng chảo gang hoặc vỉ nướng than trên lửa lớn, phết đều 5 ml dầu ăn thực vật lên bề mặt để mực không bị dính sát khi gặp sốt đường.', 'Làm nóng chảo thật kỹ trước khi đặt mực lên giúp bề mặt mực săn nhanh ngay lập tức, giữ trọn vị ngọt và không bị ra nước.', NULL),
('imp-a631650d667191b4_v4_step_4', 'imp-a631650d667191b4', 4, 'cook', 'Nướng xém mặt đầu thân và râu mực', 'Đặt thân và râu mực lên mặt chảo hoặc vỉ nóng (để mặt khía caro ngửa lên trên), nướng yên trong 2 phút trên lửa lớn đến khi mặt dưới săn đục và bắt đầu xém vàng nhẹ.', NULL, 2),
('imp-a631650d667191b4_v4_step_5', 'imp-a631650d667191b4', 5, 'cook', 'Lật mặt và phết sốt cay nướng bóng đều', 'Lật mặt mực, dùng cọ phết thêm phần sốt ướp còn lại và nướng tiếp 2 phút; lật lại một lần nữa phết nốt sốt và nướng thêm 1 phút đến khi mực chín săn hoàn toàn, sốt keo đỏ bóng xém cạnh thơm lừng.', 'Tổng thời gian nướng chỉ khoảng 4–5 phút trên lửa lớn để mực chín giòn ngọt; nướng quá lâu mực sẽ dai và mất nước.', 3),
('imp-a631650d667191b4_v4_step_6', 'imp-a631650d667191b4', 6, 'finish', 'Bày đĩa cùng lá tía tô và cắt khoanh nóng hổi', 'Lót lá tía tô thái sợi ra đĩa, đặt mực nướng nóng lên trên. Rắc nốt 1/2 lượng hành lá thái nhỏ và hạt mè trắng rang, rưới 5 ml dầu mè rang còn lại, vắt nước cốt từ 1/2 quả chanh vàng tươi rồi dùng kéo cắt mực thành từng khoanh vừa ăn.', NULL, NULL),
('imp-2a958e709ba9cb7c_v4_step_1', 'imp-2a958e709ba9cb7c', 1, 'prep', 'Thấm khô đậu phụ và pha sốt xào kim chi', 'Thấm thật khô 3 miếng đậu phụ chắc rồi cắt lát dày khoảng 1,5 cm. Cắt khúc 280 g kim chi cải thảo, thái miếng hành tây, cắt khúc hành lá, thái lát xéo ớt sừng đỏ và băm nhỏ tỏi. Trộn đều 25 g tương ớt Hàn Quốc, 6 g ớt bột Hàn Quốc, 15 ml nước tương, 12 g đường cát trắng, 1 g tiêu đen xay và 30 ml nước lọc trong chén.', NULL, NULL),
('imp-2a958e709ba9cb7c_v4_step_2', 'imp-2a958e709ba9cb7c', 2, 'cook', 'Áp chảo vàng giòn hai mặt đậu phụ', 'Làm nóng chảo chống dính trên lửa vừa-cao với 15 ml dầu ăn thực vật, xếp đậu phụ vào áp chảo khoảng 3–4 phút mỗi mặt đến khi hai mặt vàng ruộm giòn cạnh rồi gắp riêng ra đĩa.', 'Chiên vàng đậu phụ trước rồi tận dụng luôn chảo đó để xào kim chi giúp tiết kiệm thời gian mà đậu vẫn giữ được độ giòn mặt ngoài.', 7),
('imp-2a958e709ba9cb7c_v4_step_3', 'imp-2a958e709ba9cb7c', 3, 'cook', 'Phi thơm hành tây và tỏi băm', 'Thêm 5 ml dầu ăn thực vật còn lại vào cùng chảo, cho hành tây và tỏi băm vào đảo đều 1 phút trên lửa vừa đến khi tỏi dậy mùi thơm và hành hơi trong lại.', NULL, 1),
('imp-2a958e709ba9cb7c_v4_step_4', 'imp-2a958e709ba9cb7c', 4, 'cook', 'Xào mềm kim chi cùng hỗn hợp sốt cay', 'Trút kim chi cải thảo vào chảo xào 4 phút trên lửa vừa cho lá kim chi mềm săn lại, sau đó đổ chén sốt tương ớt đã pha vào đảo đều thêm 2 phút cho sốt thấm quyện đỏ bóng.', 'Xào kỹ kim chi trước khi đổ chén sốt giúp dịu độ chua gắt và giải phóng vị ngọt tự nhiên của cải thảo lên men.', 6),
('imp-2a958e709ba9cb7c_v4_step_5', 'imp-2a958e709ba9cb7c', 5, 'cook', 'Thêm ớt sừng, hành lá và rưới dầu mè', 'Thả ớt sừng đỏ thái lát và phần lớn hành lá cắt khúc vào chảo kim chi xào thêm 1 phút cho hành vừa chín tới rồi tắt bếp. Rưới 8 ml dầu mè rang lên trên và đảo nhẹ một lượt.', 'Tắt bếp rồi mới rưới dầu mè rang giúp giữ trọn hương thơm bùi béo mà không bị bay mùi ở nhiệt độ cao.', NULL),
('imp-2a958e709ba9cb7c_v4_step_6', 'imp-2a958e709ba9cb7c', 6, 'finish', 'Bày đậu phụ cạnh kim chi xào nóng', 'Xếp các lát đậu phụ áp chảo vàng giòn ra một bên đĩa, múc phần kim chi xào cay nóng cạnh bên, rắc phần hành lá thái nhỏ còn lại và hạt mè trắng rang lên trên rồi dùng nóng.', NULL, NULL),
('imp-1f3a7df71f4cbc77_v4_step_1', 'imp-1f3a7df71f4cbc77', 1, 'prep', 'Ngâm sạch vụn xương và máu thừa trên sườn bò', 'Cắt bỏ phần mỡ thừa ở viền 1200 g sườn bò cắt ngang kiểu LA, ngâm sườn trong thau nước lạnh khoảng 15 phút cho ra bớt máu thừa, sau đó tráng sạch nhiều lần dưới vòi nước lạnh để loại bỏ hoàn toàn vụn xương nhỏ rồi để thật ráo.', 'Rửa kỹ từng dẻ sườn cắt ngang giúp loại bỏ vụn xương li ti từ máy cưa thịt và giúp món nướng không bị hôi.', 15),
('imp-1f3a7df71f4cbc77_v4_step_2', 'imp-1f3a7df71f4cbc77', 2, 'marinate', 'Xay nhuyễn gia vị thơm và pha sốt ướp Galbi', 'Xay thật nhuyễn mịn hành tây, 6 tép tỏi, gừng tươi cùng 120 ml nước lọc thành hỗn hợp sánh mượt. Đổ ra tô lớn, khuấy tan với 100 ml nước tương Hàn Quốc, 40 g đường cát trắng, 25 ml mật ong, 60 ml rượu ngọt Mirin Nhật, 25 ml dầu mè rang, 2/3 lượng hành lá thái nhỏ và 2 g tiêu đen xay.', 'Xay thật mịn hành tây và gừng tỏi giúp nước ướp bám đều vào từng dẻ sườn và không để lại xác hành bị cháy đen trên vỉ nướng.', NULL),
('imp-1f3a7df71f4cbc77_v4_step_3', 'imp-1f3a7df71f4cbc77', 3, 'marinate', 'Ướp sườn thấm đều trong ngăn mát', 'Xếp sườn bò vào hộp kín hoặc túi lớn, đổ nước sốt ướp vào bóp nhẹ cho từng miếng sườn phủ đều sốt. Bọc kín, cho vào ngăn mát ướp tối thiểu 4 giờ (ướp qua đêm sẽ mềm ngọt và đậm vị nhất), giữa chừng trở mặt sườn một lần.', NULL, 240),
('imp-1f3a7df71f4cbc77_v4_step_4', 'imp-1f3a7df71f4cbc77', 4, 'sauce', 'Pha sốt chấm Ssamjang và rửa sạch rau cuốn', 'Trong chén nhỏ, trộn đều 30 g tương đậu tương Hàn Quốc (Doenjang), 18 g tương ớt Hàn Quốc (Gochujang), 1–2 tép tỏi băm còn lại, 1/3 lượng hành lá thái nhỏ, 5 ml mật ong, 5 ml dầu mè rang và một nửa lượng hạt mè trắng rang. Rửa sạch rau xà lách và lá tía tô rồi vẩy thật ráo.', NULL, NULL),
('imp-1f3a7df71f4cbc77_v4_step_5', 'imp-1f3a7df71f4cbc77', 5, 'cook', 'Nướng sườn xém vàng cạnh trên lửa vừa-cao', 'Làm nóng vỉ nướng than hoa hoặc chảo gang ở lửa vừa-cao, xếp từng dẻ sườn đã ráo nước ướp lên nướng khoảng 2–3 phút mỗi mặt. Vì sườn cắt mỏng nên thịt chín rất nhanh; canh trở đều tay đến khi hai mặt xém vàng nâu óng đẹp và thịt săn chín hoàn toàn thì gắp ra.', 'Sốt ướp chứa nhiều đường và mật ong nên dễ cháy xém; hãy trở mặt đều và giữ lửa vừa-cao thay vì lửa quá lớn.', 6),
('imp-1f3a7df71f4cbc77_v4_step_6', 'imp-1f3a7df71f4cbc77', 6, 'finish', 'Cắt miếng sườn và cuốn rau chấm Ssamjang', 'Dùng kéo bếp cắt thịt sườn tách khỏi phần xương thành miếng vừa ăn, xếp ra đĩa rắc phần hạt mè trắng rang còn lại lên trên; cuốn thịt sườn với lá xà lách, lá tía tô và chấm sốt ssamjang thưởng thức nóng.', NULL, NULL),
('imp-328b6c9769e256eb_v4_step_1', 'imp-328b6c9769e256eb', 1, 'prep', 'Làm sạch chỉ lưng tôm và thấm thật ráo vỏ', 'Dùng kéo cắt gọn râu, chân và phần gai nhọn đầu 500 g tôm tươi nguyên vỏ. Dùng tăm xiên qua đốt lưng thứ 2–3 khều bỏ sạch chỉ đen, rửa nhanh rồi dùng khăn giấy thấm thật khô lớp vỏ ngoài để muối không bám dính gây mặn gắt.', 'Thấm thật khô vỏ tôm là bước rất quan trọng giúp muối hạt chỉ truyền nhiệt khô mà không tan chảy thấm mặn vào thịt tôm.', NULL),
('imp-328b6c9769e256eb_v4_step_2', 'imp-328b6c9769e256eb', 2, 'sauce', 'Pha sốt Gochujang chanh tỏi ớt và chén dầu mè hành', 'Trong chén thứ nhất, khuấy tan 54 g tương ớt Hàn Quốc với nước cốt 1 quả chanh tươi, 10 ml mật ong, tỏi băm nhuyễn, ớt hiểm đỏ băm nhỏ và một nửa hạt mè trắng rang cho đạt vị chua cay ngọt hài hòa. Ở chén nhỏ còn lại, pha 10 ml dầu mè rang với một ít hành lá thái nhỏ để chấm thêm cho béo thơm.', NULL, NULL),
('imp-328b6c9769e256eb_v4_step_3', 'imp-328b6c9769e256eb', 3, 'cook', 'Lót giấy bạc, rải muối hạt to và làm nóng chảo', 'Lót một lớp giấy bạc chịu nhiệt vào lòng chảo đáy dày (chọn chảo cũ hoặc chảo gang), đổ 250 g muối biển hạt to dàn thành lớp phẳng dày đều khắp đáy chảo. Đậy nắp và đun lửa vừa-nhỏ khoảng 5 phút cho lớp muối nóng đều.', 'Bắt buộc dùng muối biển hạt to thay cho muối tinh mịn vì muối mịn sẽ bám chặt vào vỏ khiến thịt tôm bị mặn chát.', 5),
('imp-328b6c9769e256eb_v4_step_4', 'imp-328b6c9769e256eb', 4, 'cook', 'Nướng tôm mặt thứ nhất trên lớp muối nóng', 'Mở nắp, nhanh tay xếp tôm thành một lớp rời nhau lên trên mặt muối đang nóng (không xếp chồng lên nhau). Đậy kín nắp chảo và giữ lửa vừa-nhỏ nướng trong 5 phút cho hơi nóng muối làm chín đều mặt dưới.', NULL, 5),
('imp-328b6c9769e256eb_v4_step_5', 'imp-328b6c9769e256eb', 5, 'cook', 'Trở mặt nướng chín đỏ giòn vỏ tôm', 'Mở nắp, dùng kẹp trở lật toàn bộ tôm sang mặt còn lại, đậy nắp nướng thêm 3 phút đến khi vỏ tôm chuyển đỏ rực, hơi giòn cạnh, thân tôm uốn cong săn chắc và chín hoàn toàn bên trong.', 'Tổng thời gian nướng khoảng 8 phút tùy kích cỡ tôm; thấy thân tôm chuyển đục săn chắc và vỏ đỏ thơm là đạt, không nướng quá lâu làm tôm bị khô bở.', 3),
('imp-328b6c9769e256eb_v4_step_6', 'imp-328b6c9769e256eb', 6, 'finish', 'Gạt sạch muối và thưởng thức nóng cùng hai loại sốt', 'Gắp tôm ra đĩa (gạt nhẹ những hạt muối còn bám trên vỏ), rắc phần hành lá thái nhỏ và hạt mè trắng rang còn lại lên trên rồi dọn ăn nóng ngay cùng bát nước chấm gochujang chanh ớt và chén dầu mè hành.', NULL, NULL),
('imp-5dbb6aa38dae701d_v4_step_1', 'imp-5dbb6aa38dae701d', 1, 'prep', 'Luộc mì ramen vừa chín tới và làm tơi sợi', 'Đun sôi khoảng 1.470 ml nước lọc trong nồi lớn, thả 240 g mì ramen khô vào luộc trong 3 phút đến khi sợi mì vừa tách tơi nhưng vẫn còn độ dai ở lõi (không dùng gói gia vị đi kèm). Vớt mì ra rổ, xả nhanh dưới vòi nước lạnh, xóc thật ráo rồi trộn đều với 5 ml dầu ăn để sợi mì không bết dính.', 'Xả nước lạnh ngay sau khi luộc và áo một lớp dầu mỏng giúp sợi mì săn bóng, khi xào trên lửa lớn không bị nát vụn.', 3),
('imp-5dbb6aa38dae701d_v4_step_2', 'imp-5dbb6aa38dae701d', 2, 'sauce', 'Sơ chế rau củ và pha sẵn hỗn hợp sốt xào', 'Cắt kim chi cải thảo chua thành miếng dài 2–3 cm (giữ lại phần nước kim chi). Băm nhuyễn tỏi khô, thái lát mỏng hành tây và chia hành lá thành 2 phần. Trong chén nhỏ, khuấy tan 15 g tương ớt Hàn Quốc (Gochujang), 25 ml xì dầu, 6 g đường cát trắng cùng 30 ml nước lọc đến khi hỗn hợp sánh mịn.', NULL, NULL),
('imp-5dbb6aa38dae701d_v4_step_3', 'imp-5dbb6aa38dae701d', 3, 'cook', 'Chiên trứng ốp la lòng đào ăn kèm', 'Làm nóng chảo chống dính trên lửa vừa với 5 ml dầu ăn, đập từng quả trong 3 quả trứng gà vào chiên khoảng 2–3 phút đến khi lòng trắng chín đục hoàn toàn và mép dưới hơi giòn, lòng đỏ vẫn dẻo sánh (hoặc chiên chín kỹ tùy khẩu vị). Nhẹ nhàng gắp trứng ra đĩa riêng giữ ấm.', NULL, 3),
('imp-5dbb6aa38dae701d_v4_step_4', 'imp-5dbb6aa38dae701d', 4, 'cook', 'Phi thơm bơ tỏi cùng hành tây và xào kim chi', 'Vẫn dùng chảo lớn trên lửa vừa, cho 10 ml dầu ăn còn lại và 15 g bơ lạt vào đun tan chảy. Cho tỏi băm vào phi thơm 20 giây rồi trút hành tây và 2/3 lượng hành lá vào đảo 2 phút cho hành mềm trong. Tiếp theo, thả kim chi vào xào mạnh tay trên lửa lớn 2 phút đến khi kim chi săn ráo và dậy mùi chua cay thơm nồng.', 'Kết hợp dầu ăn với bơ lạt giúp món ăn có độ béo thơm của bơ mà không bị cháy khét khi xào ở nhiệt độ cao.', 4),
('imp-5dbb6aa38dae701d_v4_step_5', 'imp-5dbb6aa38dae701d', 5, 'cook', 'Xào mì ramen thấm đều sốt cay ngọt', 'Trút toàn bộ mì ramen đã luộc và bát sốt tương ớt Gochujang vào chảo kim chi, tăng lên lửa lớn và đảo đều tay liên tục trong 2 phút để từng sợi mì áo đều màu đỏ cam bóng đẹp và xém cạnh nhẹ.', NULL, 2),
('imp-5dbb6aa38dae701d_v4_step_6', 'imp-5dbb6aa38dae701d', 6, 'finish', 'Rưới dầu mè, bày đĩa cùng trứng và rong biển', 'Tắt bếp ngay rồi rưới 8 ml dầu mè rang và 1/3 lượng hành lá còn lại vào chảo, đảo thêm vài lượt cho dậy mùi thơm. Chia mì ra 3 đĩa, đặt mỗi đĩa một quả trứng ốp la lên trên và rắc rong biển lá khô cắt vụn tùy thích để thưởng thức ngay khi còn nóng.', 'Chỉ rưới dầu mè sau khi đã tắt bếp để giữ trọn hương thơm đặc trưng và tránh làm dầu mè bị đắng do nhiệt cao.', NULL),
('imp-b7f8a716b25a7072_v4_step_1', 'imp-b7f8a716b25a7072', 1, 'marinate', 'Thái lát và ướp thịt bò thấm gia vị', 'Thái thịt bò thăn thành lát mỏng ngang thớ cỡ 3–4 cm để khi nấu không bị dai. Ướp thịt trong tô với 15 ml xì dầu nhạt, 1/2 lượng tỏi băm, 10 ml dầu mè rang và 1 g tiêu đen xay, trộn đều rồi để nghỉ 10 phút trong lúc sơ chế rau.', 'Ướp thịt bò với xì dầu nấu canh và dầu mè trước khi xào là bí quyết tạo nước dùng ngọt đậm nhanh mà không cần ninh xương lâu.', 10),
('imp-b7f8a716b25a7072_v4_step_2', 'imp-b7f8a716b25a7072', 2, 'prep', 'Rửa sạch và cắt khúc cải thảo, hành lá', 'Tách rời từng lá cải thảo, rửa sạch từng bẹ dưới vòi nước rồi để ráo, cắt khúc dài khoảng 4–5 cm (phần cuống trắng dày có thể chẻ dọc làm đôi để chín đều cùng lá). Hành lá rửa sạch, cắt khúc 3–4 cm.', NULL, NULL),
('imp-b7f8a716b25a7072_v4_step_3', 'imp-b7f8a716b25a7072', 3, 'cook', 'Xào săn thịt bò dậy hương dầu mè', 'Đặt nồi đáy dày lên bếp ở lửa lớn, cho toàn bộ thịt bò đã ướp vào xào nhanh tay khoảng 3 phút đến khi các mặt thịt chuyển màu nâu xém nhẹ, săn lại và không còn đỏ hồng.', 'Không cần thêm dầu ăn khi xào vì trong phần ướp thịt đã có đủ dầu mè giúp thịt dậy mùi thơm mà nước canh vẫn thanh nhẹ.', 3),
('imp-b7f8a716b25a7072_v4_step_4', 'imp-b7f8a716b25a7072', 4, 'cook', 'Ninh nước dùng bò và hớt bọt làm trong canh', 'Đổ 1.400 ml nước lọc vào nồi thịt bò, đun sôi mạnh trên lửa lớn rồi dùng muỗng hớt sạch lớp bọt nâu nổi trên mặt. Đậy nắp, hạ xuống lửa vừa và đun liu riu khoảng 10 phút để nước dùng chiết ra vị ngọt thịt.', NULL, 10);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-b7f8a716b25a7072_v4_step_5', 'imp-b7f8a716b25a7072', 5, 'cook', 'Nấu chín mềm cải thảo và nêm nước canh', 'Cho cải thảo cắt khúc vào nồi canh, đun sôi lại rồi hạ lửa vừa, đậy nắp nấu thêm 10 phút cho cọng cải chín mềm trong và tiết vị ngọt tự nhiên. Nêm nốt 15 ml xì dầu nhạt còn lại, 1/2 lượng tỏi băm còn lại, 4 g muối ăn và hành lá vào nồi, khuấy nhẹ và đun thêm 2 phút cho hòa vị.', 'Dùng xì dầu nhạt (xì dầu nấu canh) và muối tinh giúp nước canh giữ được màu vàng trong đẹp mắt thay vì bị sẫm đen.', 10),
('imp-b7f8a716b25a7072_v4_step_6', 'imp-b7f8a716b25a7072', 6, 'finish', 'Hoàn thiện tô canh và dọn nóng', 'Kiểm tra lại độ vừa miệng, rắc 1 g tiêu đen xay còn lại rồi tắt bếp. Múc canh bò cải thảo nóng hổi ra tô, rắc thêm hạt mè trắng rang tùy thích và thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-7d38862afc164a8d_v4_step_1', 'imp-7d38862afc164a8d', 1, 'prep', 'Làm sạch mực tươi và cắt khoanh đều tay', 'Rút nhẹ phần đầu mực để loại bỏ túi mực, nội tạng và thanh mai trong suốt ở lưng. Rửa sạch thân và râu mực dưới vòi nước lạnh rồi thấm thật ráo nước. Cắt thân mực thành từng khoanh tròn dày khoảng 1 cm và cắt rời phần râu thành miếng vừa ăn.', 'Thấm thật khô mực sau khi rửa giúp mực không bị tiết quá nhiều nước làm loãng sốt khi xào.', NULL),
('imp-7d38862afc164a8d_v4_step_2', 'imp-7d38862afc164a8d', 2, 'prep', 'Thái rau củ và pha chén sốt xì dầu dầu hào', 'Thái hành tây thành múi cau mỏng, cắt ớt chuông đỏ thành sợi dày 0,8 cm; chia hành lá thành 1/3 phần đầu hành thái nhỏ và 2/3 phần lá cắt khúc 4 cm, tỏi khô băm nhuyễn. Khuấy tan 35 ml xì dầu đặc, 20 ml dầu hào cùng 10 g đường cát trắng trong chén nhỏ.', NULL, NULL),
('imp-7d38862afc164a8d_v4_step_3', 'imp-7d38862afc164a8d', 3, 'cook', 'Phi thơm hành tỏi và xào hành tây vừa chín trong', 'Làm nóng chảo rộng với 30 ml dầu ăn trên lửa vừa, cho tỏi băm và phần đầu hành lá thái nhỏ vào phi nhanh khoảng 20 giây cho dậy mùi thơm mà không bị cháy. Thả hành tây vào đảo đều trong 2 phút đến khi mép hành hơi trong lại.', NULL, 2),
('imp-7d38862afc164a8d_v4_step_4', 'imp-7d38862afc164a8d', 4, 'cook', 'Xào nhanh mực và ớt chuông trên lửa lớn', 'Tăng bếp lên lửa lớn, trút mực tươi, ớt chuông đỏ và toàn bộ chén sốt xì dầu dầu hào đã pha vào chảo. Đảo liên tục và nhanh tay trong 3 phút đến khi khoanh mực săn tròn, chuyển màu trắng đục chín đều và nước sốt sánh nhẹ bám quanh thân mực.', 'Xào mực dứt khoát trên lửa lớn trong 2–3 phút là bí quyết giữ mực giòn ngọt; xào lâu hơn mực sẽ dai và ra nước.', 3),
('imp-7d38862afc164a8d_v4_step_5', 'imp-7d38862afc164a8d', 5, 'cook', 'Cô sánh sốt nếu chảo còn nhiều nước', 'Quan sát đáy chảo, nếu mực tiết nhiều nước, giữ lửa lớn đảo thêm 30–60 giây cho nước cạn bớt và phần sốt áo bóng đẹp vào từng miếng mực và ớt chuông.', NULL, NULL),
('imp-7d38862afc164a8d_v4_step_6', 'imp-7d38862afc164a8d', 6, 'finish', 'Thêm hành lá, dầu mè và mè rang hoàn thiện món', 'Tắt bếp rồi thả phần hành lá cắt khúc 4 cm vào đảo nhanh 30 giây cho vừa tái xanh, sau đó rưới 15 ml dầu mè rang, rắc 6 g hạt mè trắng rang và trộn đều một lượt trước khi bày ra đĩa dùng nóng với cơm trắng.', 'Rưới dầu mè rang sau khi tắt bếp giúp giữ trọn hương thơm béo đặc trưng mà không bị đắng khét.', NULL),
('imp-c78c4d4ca35484d3_v4_step_1', 'imp-c78c4d4ca35484d3', 1, 'prep', 'Vo ngâm gạo tẻ và nấu nước dùng nấm tảo bẹ', 'Vo sạch 400 g gạo tẻ hạt ngắn 2–3 lần nước, ngâm trong nước lạnh khoảng 30 phút rồi vớt ra rổ để thật ráo. Cho 820 ml nước lọc vào nồi cùng 8 g tảo bẹ Kombu khô và phần gốc cuống nấm đùi gà đã rửa sạch, đun sôi rồi hạ lửa nhỏ ninh liu riu 15 phút cho ngọt nước. Vớt bỏ xác tảo bẹ và cuống nấm, đong lấy khoảng 650 ml nước dùng nóng.', 'Ngâm gạo trước khi nấu giúp hạt cơm chín đều từ lõi và tạo độ dẻo bóng; không nấu tảo bẹ quá lâu ở lửa lớn để tránh nước dùng bị nhớt.', 15),
('imp-c78c4d4ca35484d3_v4_step_2', 'imp-c78c4d4ca35484d3', 2, 'prep', 'Cắt lát nấm đùi gà, xé nấm bào ngư và tách nấm kim châm', 'Nấm đùi gà thái lát dày 0,8 cm (cắt hơi dày vì nấm sẽ ngót lại khi chín). Nấm bào ngư dùng tay xé dọc thành sợi vừa ăn để không bị nát, còn nấm kim châm tươi cắt bỏ gốc, tách thành từng chùm nhỏ để riêng.', NULL, NULL),
('imp-c78c4d4ca35484d3_v4_step_3', 'imp-c78c4d4ca35484d3', 3, 'cook', 'Rang sơ gạo và nấu cơm cùng nấm đùi gà, bào ngư', 'Làm nóng nồi gang đáy dày trên lửa vừa với 15 ml dầu ăn thực vật, trút gạo đã ráo vào đảo đều tay khoảng 3 phút đến khi hạt gạo hơi trong lại. Hạ lửa vừa, chế từ từ 650 ml nước dùng tảo bẹ vào vừa ngập mặt gạo rồi xếp đều nấm đùi gà và nấm bào ngư lên trên. Đậy kín nắp, nấu lửa vừa 5 phút rồi hạ lửa nhỏ nấu thêm 15 phút.', NULL, 20),
('imp-c78c4d4ca35484d3_v4_step_4', 'imp-c78c4d4ca35484d3', 4, 'sauce', 'Pha chén sốt xì dầu hành lá dầu mè', 'Trong lúc chờ cơm chín, cho hành lá thái nhuyễn vào chén trộn đều với 10 ml dầu mè rang trước để giữ màu xanh tươi. Tiếp tục thêm 30 ml xì dầu, 30 ml nước lọc còn lại và 4 g hạt mè trắng rang, khuấy đều cho gia vị hòa quyện.', 'Áo hành lá với dầu mè trước khi thêm xì dầu giúp hành giữ độ giòn tươi, không bị héo sẫm màu.', NULL),
('imp-c78c4d4ca35484d3_v4_step_5', 'imp-c78c4d4ca35484d3', 5, 'cook', 'Nấu cạn hơi và ủ kín nồi cơm nấm', 'Sau 15 phút nấu lửa nhỏ, hạ về mức lửa nhỏ nhất nấu tiếp 8 phút đến khi không còn hơi nước thoát mạnh ở mép nắp. Tắt bếp và giữ nguyên nắp đậy kín để ủ cơm thêm 5 phút cho hạt cơm chín ráo hoàn toàn.', 'Tuyệt đối không mở nắp trong suốt 5 phút ủ cơm để giữ trọn hơi nóng làm nấm và hạt cơm dẻo thơm đồng đều.', 5),
('imp-c78c4d4ca35484d3_v4_step_6', 'imp-c78c4d4ca35484d3', 6, 'finish', 'Xếp nấm kim châm hấp hơi và dọn cơm nóng', 'Mở nắp nồi, trải đều 100 g nấm kim châm lên bề mặt cơm nóng và đậy nắp lại 1 phút cho nấm chín mềm bằng hơi nóng tự nhiên. Dùng muôi xới nhẹ từ dưới lên cho cơm tơi đều với ba loại nấm, múc ra chén và dọn kèm sốt xì dầu hành lá để chan trực tiếp khi ăn.', NULL, NULL),
('imp-97c4b38c79bf9f39_v4_step_1', 'imp-97c4b38c79bf9f39', 1, 'prep', 'Sơ chế tôm tươi, kim chi và đậu phụ non', 'Tôm tươi bóc sạch vỏ, rút chỉ đen dọc sống lưng rồi rửa nhẹ qua nước lạnh và để ráo. Kim chi cải thảo chua cắt miếng dài 3–4 cm và giữ lại khoảng 60 ml nước kim chi trong hũ. Đậu phụ non nhẹ nhàng cắt lát dày 1,5 cm; hành tây thái múi cau, tỏi khô băm nhuyễn và tách riêng phần đầu trắng, lá xanh của hành lá.', NULL, NULL),
('imp-97c4b38c79bf9f39_v4_step_2', 'imp-97c4b38c79bf9f39', 2, 'cook', 'Xào thơm tỏi và kim chi cho dậy màu đỏ đẹp', 'Đun nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn, cho tỏi băm vào phi thơm 30 giây rồi trút kim chi cùng 60 ml nước kim chi vào xào liên tục trong 4 phút đến khi kim chi săn mềm và tiết ra mùi thơm chua cay đặc trưng.', 'Xào kim chi với dầu ăn trước khi chế nước giúp loại bỏ vị chua gắt, đồng thời làm nước canh có độ sánh bóng và đậm đà hơn.', 4),
('imp-97c4b38c79bf9f39_v4_step_3', 'imp-97c4b38c79bf9f39', 3, 'cook', 'Ninh kim chi cùng nước dùng cá cơm tảo bẹ', 'Đổ 1.200 ml nước dùng cá cơm tảo bẹ Hàn vào nồi kim chi, nêm 14 g ớt bột Hàn Quốc (Gochugaru), 18 g tương ớt Hàn Quốc (Gochujang), 15 ml xì dầu và 8 g đường cát trắng. Khuấy tan đều gia vị, đun sôi bùng rồi hạ lửa vừa, đậy nắp ninh liu riu 12 phút để kim chi mềm nhừ và nước canh ngọt sâu.', NULL, 12),
('imp-97c4b38c79bf9f39_v4_step_4', 'imp-97c4b38c79bf9f39', 4, 'cook', 'Nấu hành tây và thả tôm tươi chín tới', 'Cho hành tây và phần đầu trắng hành lá vào nấu tiếp 3 phút trên lửa vừa. Sau đó tăng lên lửa lớn cho nước canh sôi mạnh, thả toàn bộ tôm tươi vào nấu khoảng 2–3 phút đến khi tôm cong tròn, chuyển màu hồng cam tươi và phần thịt đục chín hoàn toàn.', 'Không nấu tôm quá lâu sau khi thịt tôm đã chuyển hồng đục vì tôm sẽ bị co cứng và mất độ ngọt tự nhiên.', 3),
('imp-97c4b38c79bf9f39_v4_step_5', 'imp-97c4b38c79bf9f39', 5, 'cook', 'Xếp đậu phụ non và nêm lại độ mặn thanh', 'Hạ lửa nhỏ, nhẹ nhàng đặt từng miếng đậu phụ non lên bề mặt nồi canh và nấu thêm 4 phút cho đậu nóng đều và thấm vị mà không bị vỡ nát. Nếm thử nước canh và chỉ thêm tối đa 1 g muối ăn nếu cần theo độ mặn chua của mẻ kim chi.', 'Hạn chế dùng vá khuấy mạnh sau khi đã thả đậu phụ non; chỉ nghiêng nhẹ hoặc múc nước chan lên mặt đậu.', 4),
('imp-97c4b38c79bf9f39_v4_step_6', 'imp-97c4b38c79bf9f39', 6, 'finish', 'Rưới dầu mè, rắc hành lá và thưởng thức nóng', 'Rưới 5 ml dầu mè rang cùng phần lá xanh hành lá lên mặt nồi canh rồi tắt bếp. Dọn canh kim chi tôm đậu phụ còn nóng hổi ra bàn để thưởng thức ngay cùng cơm trắng.', NULL, NULL),
('imp-b855b6ba4a9a3be8_v4_step_1', 'imp-b855b6ba4a9a3be8', 1, 'prep', 'Lột vỏ tôm giữ đầu và rút sạch chỉ đen', 'Rửa sạch 450 g tôm sú tươi, bóc bỏ vỏ và ngắt phần đầu để riêng vào tô (không bỏ đi vì phần gạch và vỏ giúp nước dùng ngọt đậm). Rút sạch chỉ đen dọc sống lưng thịt tôm, rửa lại nhanh rồi để ráo.', NULL, NULL),
('imp-b855b6ba4a9a3be8_v4_step_2', 'imp-b855b6ba4a9a3be8', 2, 'cook', 'Xào gạch đầu tôm và ninh nước dùng ngọt thanh', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa-lớn, cho toàn bộ đầu và vỏ tôm vào đảo đều tay khoảng 3 phút, dùng muôi ấn nhẹ phần đầu cho gạch tôm tiết ra màu đỏ cam thơm nức. Đổ 1050 ml nước lọc vào đun sôi rồi hạ lửa nhỏ liu riu 5 phút, vớt bỏ hết vỏ và đầu tôm để thu nước dùng trong ngọt.', 'Không ninh vỏ tôm quá lâu hơn 5–7 phút vì nước dùng dễ bị đục và mất vị ngọt thanh tự nhiên.', 8),
('imp-b855b6ba4a9a3be8_v4_step_3', 'imp-b855b6ba4a9a3be8', 3, 'prep', 'Sơ chế bộ ba thảo mộc Thái và nấm đùi gà', 'Đập dập sả tươi cắt khúc 5 cm; thái lát mỏng củ riềng tươi; vò nhẹ và xé bỏ gân giữa lá chanh Kaffir; đập dập ớt hiểm; cắt nấm đùi gà thành lát hoặc miếng vừa ăn; thái nhỏ hành lá và ngò gai.', NULL, NULL),
('imp-b855b6ba4a9a3be8_v4_step_4', 'imp-b855b6ba4a9a3be8', 4, 'cook', 'Nấu thơm thảo mộc cùng nấm đùi gà', 'Cho sả, riềng, lá chanh Kaffir, ớt hiểm và nấm đùi gà vào nồi nước dùng tôm, đun sôi rồi hạ lửa vừa nấu liu riu 5 phút cho thảo mộc tiết hết tinh dầu thơm và nấm chín ngọt.', NULL, 5),
('imp-b855b6ba4a9a3be8_v4_step_5', 'imp-b855b6ba4a9a3be8', 5, 'cook', 'Hòa tương ớt xào Thái, nêm nước mắm và nấu tôm', 'Múc một ít nước dùng nóng ra chén hòa tan 50 g tương ớt xào Thái cho mịn rồi trút ngược vào nồi, nêm thêm 40 ml nước mắm. Bật lửa lớn cho canh sôi bùng trở lại, thả thịt tôm vào nấu khoảng 1 phút đến khi tôm vừa chuyển đỏ hồng cong mình chín hoàn toàn thì tắt bếp ngay.', 'Chỉ thả tôm khi nước sôi bùng và tắt bếp ngay sau 1 phút để thịt tôm chín ngọt, giòn săn mà không bị dai bã.', 1),
('imp-b855b6ba4a9a3be8_v4_step_6', 'imp-b855b6ba4a9a3be8', 6, 'finish', 'Vắt nước cốt chanh tươi và dọn canh nóng', 'Khi nồi canh đã tắt bếp và bớt sôi sục, rót nước cốt của 2,5 quả chanh tươi vào cùng 5 g đường cát trắng, khuấy nhẹ và nếm chỉnh vị chua cay mặn ngọt hài hòa. Múc ra tô, rắc hành lá và ngò gai lên trên rồi thưởng thức nóng (nhắc người ăn không nhai sả, riềng, lá chanh).', 'Cho nước cốt chanh sau khi tắt bếp giúp giữ trọn hương thơm tươi mát của tinh dầu chanh và tránh làm nước canh bị đắng.', NULL),
('imp-2b514b564c702ff1_v4_step_1', 'imp-2b514b564c702ff1', 1, 'prep', 'Ngâm xiên tre, làm sạch tôm và ướp muối nhẹ', 'Ngâm 6–8 que xiên tre vào nước lạnh ít nhất 20 phút để không bị cháy khi nướng. Làm sạch 500 g tôm tươi, bóc vỏ thân giữ lại đuôi, rút chỉ đen và thấm thật khô bằng khăn giấy. Rắc đều 2 g muối ăn và 15 ml dầu ăn vào tôm trộn đều.', 'Ngâm xiên tre trước giúp que không bị cháy đen và thấm khô tôm giúp lớp sốt phết bám đều lên thịt tôm.', 20),
('imp-2b514b564c702ff1_v4_step_2', 'imp-2b514b564c702ff1', 2, 'sauce', 'Pha chén sốt chanh tỏi ớt chua cay đậm đà', 'Trong chén nhỏ, hòa tan 15 g đường cát trắng với 35 ml nước mắm và toàn bộ nước cốt của 2 quả chanh tươi đến khi đường tan hết. Thêm tỏi băm nhuyễn và ớt hiểm băm nhỏ vào khuấy đều.', NULL, NULL),
('imp-2b514b564c702ff1_v4_step_3', 'imp-2b514b564c702ff1', 3, 'marinate', 'Phết lớp sốt mỏng lên tôm và xiên que', 'Múc 1/3 lượng sốt chanh ớt vừa pha rưới nhẹ trộn đều với tôm, để thấm khoảng 10 phút (giữ lại 2/3 phần sốt còn lại để phết khi nướng và lúc dọn). Lần lượt xiên 4–5 con tôm vào mỗi que tre theo chiều dọc thân tôm.', 'Không ướp tôm với nước cốt chanh quá 15 phút vì axit trong chanh sẽ làm chín tái bề mặt khiến thịt tôm bị bở khi nướng.', 10),
('imp-2b514b564c702ff1_v4_step_4', 'imp-2b514b564c702ff1', 4, 'cook', 'Làm nóng vỉ nướng và phết lớp dầu chống dính', 'Làm nóng bếp than hoa hoặc chảo gang rãnh nướng ở lửa lớn đến khi vỉ thật nóng, dùng cọ quét 5 ml dầu ăn còn lại lên mặt vỉ để tôm không bị dính sát.', NULL, NULL),
('imp-2b514b564c702ff1_v4_step_5', 'imp-2b514b564c702ff1', 5, 'cook', 'Nướng tôm lửa lớn hai mặt và phết sốt bóng đẹp', 'Đặt các xiên tôm lên vỉ nóng, nướng khoảng 2–3 phút cho mặt dưới chuyển đỏ hồng xém nhẹ thì lật mặt. Phết thêm 1/3 lượng sốt lên mặt tôm đã lật và nướng tiếp 2–3 phút cho đến khi tôm săn cong hoàn toàn và hai mặt hơi cháy cạnh thơm lừng.', 'Nướng nhanh trên lửa lớn trong 4–6 phút giúp tôm vừa chín tới mọng nước, tránh nướng lâu làm thịt tôm khô xác.', 5),
('imp-2b514b564c702ff1_v4_step_6', 'imp-2b514b564c702ff1', 6, 'finish', 'Phết nốt phần sốt tươi, rắc hành lá và thưởng thức', 'Gắp các xiên tôm nướng ra đĩa lớn, dùng cọ phết nốt 1/3 lượng sốt chanh ớt tươi còn lại lên trên khi tôm đang nóng hổi để tạo lớp áo bóng thơm. Rắc hành lá thái nhỏ lên mặt và dọn ăn ngay.', NULL, NULL),
('imp-119da2ec6738c17e_v4_step_1', 'imp-119da2ec6738c17e', 1, 'prep', 'Sơ chế đùi gà và xay nhuyễn hỗn hợp thảo mộc', 'Chà xát 750 g đùi gà với 2 g muối ăn rồi rửa sạch lại nước lạnh, thấm ráo và chặt miếng vừa ăn hoặc khứa sâu 2 đường. Cho sả thái lát, củ riềng tươi, lá chanh Kaffir và 15 g phần rễ ngò rí vào cối xay hoặc giã nhuyễn thành hỗn hợp thảo mộc thơm mịn.', 'Khứa nhẹ vài đường trên mặt thịt đùi gà giúp hỗn hợp thảo mộc thấm sâu và gà chín đều nhanh hơn khi hấp.', NULL),
('imp-119da2ec6738c17e_v4_step_2', 'imp-119da2ec6738c17e', 2, 'marinate', 'Ướp gà đậm đà với thảo mộc và gia vị', 'Cho thịt gà vào tô lớn cùng hỗn hợp thảo mộc vừa xay, 25 ml dầu hào, 20 ml xì dầu và 1 g muối ăn còn lại. Dùng tay bóp trộn kỹ cho gia vị thấm sâu vào từng thớ thịt, đậy kín ướp ít nhất 15–20 phút.', NULL, 20),
('imp-119da2ec6738c17e_v4_step_3', 'imp-119da2ec6738c17e', 3, 'cook', 'Xếp gà vào đĩa sâu lòng và hấp cách thủy', 'Xếp gà đã ướp cùng phần sốt vào đĩa sâu lòng có thành cao để hứng trọn phần nước ngọt tiết ra. Đun sôi nước trong xửng, đặt đĩa gà vào hấp lửa vừa khoảng 15 phút cho thịt bắt đầu săn lại và tỏa hương thơm.', 'Dùng đĩa sâu lòng hứng phần nước ngọt tiết ra khi hấp để hòa vào nước chấm giúp hương vị đậm đà hơn hẳn.', 15),
('imp-119da2ec6738c17e_v4_step_4', 'imp-119da2ec6738c17e', 4, 'cook', 'Thêm lá húng quế Thái và hấp chín mềm hoàn toàn', 'Ở phút thứ 15, mở nắp xửng rải nhanh 20 g lá húng quế Thái lên mặt gà rồi đậy kín hấp tiếp thêm 25 phút trên lửa vừa đến khi xăm đũa vào phần thịt dày nhất thấy nước chảy ra trong suốt không còn đỏ hồng.', NULL, 25),
('imp-119da2ec6738c17e_v4_step_5', 'imp-119da2ec6738c17e', 5, 'sauce', 'Giã tỏi ớt và pha nước chấm chanh Thái', 'Trong lúc chờ gà chín, cho tỏi bóc vỏ và ớt hiểm vào cối giã nhuyễn. Trút ra chén, thêm nước cốt của 3 quả chanh tươi, 30 ml nước mắm, 30 g đường cát trắng và 60 ml nước lọc, khuấy tan hết đường rồi thả 10 g lá ngò rí thái nhỏ vào.', 'Cân chỉnh độ chua cay mặn ngọt của chén nước chấm theo khẩu vị, giữ độ hơi đậm để khi hòa thêm nước hấp gà sẽ vừa miệng.', NULL),
('imp-119da2ec6738c17e_v4_step_6', 'imp-119da2ec6738c17e', 6, 'finish', 'Hòa nước hấp gà vào nước chấm và trình bày', 'Nhấc đĩa gà hấp chín ra khỏi xửng, múc khoảng 3–4 muỗng canh nước ngọt trong đĩa hấp hòa vào chén nước chấm cho dậy vị béo thơm, phần còn lại rưới lên gà, rắc hành lá thái nhỏ rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_1', 'imp-2fb85e79ab43b8bc', 1, 'marinate', 'Pha sốt ướp và ướp miếng thăn bò nguyên khối', 'Khuấy tan 12 ml dầu hào, 8 ml xì dầu, 4 g đường cát trắng, 1,5 g tiêu đen xay và 15 ml dầu ăn. Xoa đều hỗn hợp này lên khắp miếng thịt thăn bò 350 g, bọc kín ướp trong ngăn mát ít nhất 60 phút, sau đó lấy ra để nhiệt độ phòng 20 phút trước khi nướng.', 'Để thịt bò về nhiệt độ phòng trước khi đặt lên vỉ giúp nhiệt độ chín đều từ ngoài vào trong và giữ phần lõi thịt hồng mọng.', 60),
('imp-2fb85e79ab43b8bc_v4_step_2', 'imp-2fb85e79ab43b8bc', 2, 'prep', 'Sơ chế mỏng sả, hành tím và các loại rau thơm', 'Thái thật mỏng phần gốc non của 2 cây sả và 45 g hành tím khô; nhặt lá bạc hà (húng lủi), thái khúc 2 cm ngò rí và hành lá, để tất cả thật ráo nước.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_3', 'imp-2fb85e79ab43b8bc', 3, 'cook', 'Nướng bò chín vừa và giữ lại nước thịt ngọt', 'Làm nóng chảo gang hoặc vỉ nướng ở lửa vừa-lớn. Đặt miếng thăn bò lên nướng tổng 6–8 phút, trở mặt mỗi 2 phút đến khi hai mặt xém nâu đẹp và thịt đạt độ chín vừa (nhiệt độ lõi khoảng 60°C). Gắp ra đĩa sâu lòng để thịt nghỉ 5 phút và giữ lại toàn bộ nước thịt tiết ra.', 'Không cắt thịt ngay khi vừa nhấc khỏi chảo vì nước thịt sẽ chảy ra hết làm miếng bò khô xác; thời gian nghỉ 5 phút giúp thớ thịt giữ trọn độ mọng.', 8),
('imp-2fb85e79ab43b8bc_v4_step_4', 'imp-2fb85e79ab43b8bc', 4, 'prep', 'Thái lát bò ngược thớ và giữ lại nước thịt', 'Sau khi thịt bò đã nghỉ đủ thời gian, dùng dao sắc thái thành từng lát mỏng ngang thớ dày 3–4 mm rồi cho vào tô trộn cùng toàn bộ phần nước thịt ngọt tiết ra trên đĩa.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_5', 'imp-2fb85e79ab43b8bc', 5, 'sauce', 'Pha nước trộn gỏi chua mặn cay cùng nước thịt', 'Thêm vào tô thịt bò 20 ml nước mắm, nước cốt của 1,5 quả chanh tươi, 4 g đường cát trắng còn lại, 3 g ớt bột vảy rang và 35 ml nước dùng gà, trộn đều cho đường tan hoàn toàn và thịt ngấm vị đậm đà.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_6', 'imp-2fb85e79ab43b8bc', 6, 'finish', 'Trộn thính gạo rang, rau thơm và dọn ăn ngay', 'Rắc 30 g thính gạo rang vào tô thịt bò đảo đều cho thính bám thơm quyện sốt, nếm lại cho vừa vị chua mặn cay hài hòa. Cuối cùng cho sả thái mỏng, hành tím, lá bạc hà, ngò rí và hành lá vào đảo nhẹ tay rồi bày ra đĩa dùng ngay.', 'Chỉ trộn thính gạo và rau thơm ngay sát lúc dọn bàn ăn để thính giữ được hương rang bùi thơm và rau thơm tươi xanh.', NULL),
('imp-3f14cf8e63967712_v4_step_1', 'imp-3f14cf8e63967712', 1, 'prep', 'Làm sạch mực, khía vảy rồng và thấm thật khô', 'Làm sạch 450 g mực ống tươi, bỏ nang cứng, túi mực và mắt. Lật mặt trong thân mực khía các đường chéo đan xen tạo hình vảy rồng, cắt miếng chữ nhật 2x4 cm, râu mực cắt khúc vừa ăn rồi dùng khăn giấy thấm thật khô toàn bộ mực.', 'Thấm thật khô mực trước khi xào là bước quan trọng giúp mực săn giòn ngay khi chạm chảo nóng và không tiết ra nhiều nước.', NULL),
('imp-3f14cf8e63967712_v4_step_2', 'imp-3f14cf8e63967712', 2, 'prep', 'Giã thô tỏi ớt và cắt khúc hành lá', 'Cho tỏi bóc vỏ và ớt hiểm vào cối đá giã dập thô (không cần nhuyễn mịn) để tỏi ớt tiết hết tinh dầu thơm. Hành lá rửa sạch cắt khúc 3 cm.', 'Giã tỏi ớt bằng cối thay vì băm sẽ giúp hương thơm tỏa ra mạnh mẽ hơn hẳn khi phi nhanh trên chảo nóng.', NULL),
('imp-3f14cf8e63967712_v4_step_3', 'imp-3f14cf8e63967712', 3, 'sauce', 'Pha sẵn chén sốt gia vị xào mực', 'Khuấy tan 25 ml dầu hào, 15 ml nước mắm, 5 ml xì dầu đặc, 5 g đường cát trắng và 4 g hạt nêm trong chén nhỏ để sẵn bên cạnh bếp.', NULL, NULL),
('imp-3f14cf8e63967712_v4_step_4', 'imp-3f14cf8e63967712', 4, 'cook', 'Phi thơm tỏi ớt giã trong chảo nóng', 'Đun nóng chảo rộng với 30 ml dầu ăn trên lửa vừa-lớn, cho hỗn hợp tỏi ớt giã vào đảo nhanh khoảng 20–30 giây đến khi dậy mùi cay thơm nồng và tỏi vừa ngả vàng nhạt (tránh để tỏi cháy đắng).', NULL, 1),
('imp-3f14cf8e63967712_v4_step_5', 'imp-3f14cf8e63967712', 5, 'cook', 'Xào mực lửa lớn săn giòn và rưới sốt áo đều', 'Tăng lửa lên mức lớn nhất, trút toàn bộ mực vào đảo nhanh tay khoảng 2 phút đến khi các đường khía bung nở cong đều và thịt mực chuyển màu trắng đục săn chắc. Rưới đều chén sốt đã pha vào đảo mạnh thêm 45 giây cho sốt bám bóng vào từng miếng mực.', 'Món mực xào lửa lớn chỉ mất khoảng 2–3 phút; xào quá lâu sẽ làm mực ra nước và bị dai cứng như cao su.', 2),
('imp-3f14cf8e63967712_v4_step_6', 'imp-3f14cf8e63967712', 6, 'finish', 'Đảo nhanh hành lá và dọn mực xào nóng', 'Thả hành lá cắt khúc vào chảo, đảo đều thêm 15 giây rồi tắt bếp ngay để hành giữ màu xanh tươi giòn ngọt. Trút mực xào tỏi ớt ra đĩa và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-244640181aff1fb6_v4_step_1', 'imp-244640181aff1fb6', 1, 'prep', 'Luộc sơ nấm đùi gà, thái khoanh và khứa mặt', 'Đun sôi 500 ml nước lọc, cho 380 g nấm đùi gà đã rửa sạch vào luộc sơ đúng 2 phút để nấm sạch và hết mùi hăng, vớt ra để nguội bớt rồi thái khoanh dày 1 cm. Dùng dao khứa nhẹ vài đường chéo trên hai mặt mỗi khoanh nấm để gia vị thấm sâu.', 'Luộc sơ 2 phút trước khi ướp giúp nấm mềm dẻo không gãy nát, ra bớt nước khi nướng và thấm gia vị nhanh gấp đôi.', 2),
('imp-244640181aff1fb6_v4_step_2', 'imp-244640181aff1fb6', 2, 'prep', 'Băm nhuyễn sả tỏi và thái lát hành tím', 'Băm thật nhuyễn phần gốc non của 3 cây sả tươi và tỏi khô; thái lát mỏng 45 g hành tím khô; thái nhỏ hành lá tươi để riêng một ít rắc mặt sau khi nướng.', NULL, NULL),
('imp-244640181aff1fb6_v4_step_3', 'imp-244640181aff1fb6', 3, 'marinate', 'Pha sốt dầu hào chay và ướp thấm khoanh nấm', 'Khuấy tan 20 ml xì dầu, 30 ml dầu hào chay, 8 g đường cát trắng, 10 ml tương ớt, 1,5 g tiêu đen xay, 12 ml dầu mè, 20 ml dầu ăn và 15 ml nước lọc còn lại. Trộn nhẹ khoanh nấm với phần sốt này cùng sả băm, tỏi băm, hành tím thái lát và phần lớn hành lá; ướp 15 phút.', 'Giữa thời gian ướp nên đảo trở mặt các khoanh nấm một lần để hai mặt ngấm đều sả và gia vị.', 15),
('imp-244640181aff1fb6_v4_step_4', 'imp-244640181aff1fb6', 4, 'cook', 'Xếp nấm thành một lớp đều lên khay nướng', 'Làm nóng trước nồi chiên không dầu hoặc lò nướng ở 200°C trong 3 phút. Lót giấy bạc vào khay, xếp từng khoanh nấm đã ướp thành một lớp thưa đều nhau rồi rưới hết phần sốt ướp còn lại lên mặt nấm.', 'Không xếp chồng nấm lên nhau để luồng khí nóng lưu thông đều, giúp các khoanh nấm xém cạnh đẹp mắt thay vì bị hấp ướt.', NULL),
('imp-244640181aff1fb6_v4_step_5', 'imp-244640181aff1fb6', 5, 'cook', 'Nướng nấm ở 200°C đến khi xém vàng thơm lừng', 'Đưa khay nấm vào nướng ở nhiệt độ 200°C trong 8–10 phút đến khi mặt nấm se ráo, cạnh xém vàng nhẹ và dậy mùi thơm nồng của sả nướng cùng dầu mè.', NULL, 9),
('imp-244640181aff1fb6_v4_step_6', 'imp-244640181aff1fb6', 6, 'finish', 'Rắc mè rang, hành lá và thưởng thức nóng', 'Gắp nấm nướng sả ra đĩa, chan nhẹ phần sốt còn đọng trong khay lên mặt nấm. Rắc hạt mè trắng rang vàng cùng chút hành lá tươi còn lại lên trên rồi dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-f494a9f384ce66a4_v4_step_1', 'imp-f494a9f384ce66a4', 1, 'prep', 'Kiểm tra thịt cua và sơ chế rau củ gia vị', 'Dàn nhẹ 400 g thịt cua biển ra đĩa, rà kỹ bằng tay để nhặt bỏ hết mảnh vỏ hoặc sụn cua còn lẫn và để ráo. Rửa sạch ớt chuông xanh, bỏ hạt thái miếng vuông 2,5 cm; tỏi bóc vỏ băm nhỏ; ớt hiểm băm nhỏ (chừa 1 quả thái lát); hành lá cắt khúc 3 cm.', 'Kiểm tra kỹ thịt cua bóc sẵn giúp loại bỏ hoàn toàn mảnh sụn nhỏ mà vẫn giữ được các thớ thịt cua nguyên tảng đẹp mắt.', NULL),
('imp-f494a9f384ce66a4_v4_step_2', 'imp-f494a9f384ce66a4', 2, 'sauce', 'Pha sẵn chén sốt dầu hào và nước dùng gà', 'Trộn đều trong chén 45 ml dầu hào, 10 ml xì dầu nhạt, 5 g đường cát trắng, 1,5 g tiêu đen xay và 100 ml nước dùng gà, khuấy tan đường để phần sốt có vị mặn ngọt hài hòa.', 'Pha sẵn toàn bộ chén sốt trước khi bật bếp giúp món xào hải sản diễn ra nhanh gọn và thịt cua không bị chín quá lửa.', NULL),
('imp-f494a9f384ce66a4_v4_step_3', 'imp-f494a9f384ce66a4', 3, 'cook', 'Phi thơm tỏi ớt trên lửa vừa không để cháy', 'Đun nóng chảo rộng với 45 ml dầu ăn trên lửa vừa, cho tỏi băm và ớt hiểm băm vào phi khoảng 40 giây đến khi tỏi dậy mùi thơm cay nồng và vừa ngả vàng nhẹ.', NULL, 1),
('imp-f494a9f384ce66a4_v4_step_4', 'imp-f494a9f384ce66a4', 4, 'cook', 'Xào nhanh ớt chuông xanh giữ độ giòn tươi', 'Vặn lửa lớn, cho toàn bộ ớt chuông xanh thái miếng vuông vào chảo đảo nhanh tay khoảng 1 phút cho ớt vừa chín tới, dậy mùi thơm mà vẫn giữ được độ giòn ngọt và màu xanh mướt.', NULL, 1),
('imp-f494a9f384ce66a4_v4_step_5', 'imp-f494a9f384ce66a4', 5, 'cook', 'Đun sôi nhẹ sốt và đảo đều thịt cua', 'Rưới toàn bộ chén sốt dầu hào đã pha vào chảo đun sôi nhẹ 1 phút cho nước sốt hơi sánh lại. Nhẹ nhàng trút 400 g thịt cua vào chảo, dùng muôi gỗ đảo nhẹ tay từ dưới lên trong 2 phút cho thịt cua nóng đều tận trong và áo bóng sốt mà không bị nát vụn.', 'Thịt cua đã hấp chín sẵn nên chỉ cần đảo nhẹ 1–2 phút trong nước sốt sôi lăn tăn cho ngấm vị, tránh đảo mạnh tay làm cua bị vụn.', 3),
('imp-f494a9f384ce66a4_v4_step_6', 'imp-f494a9f384ce66a4', 6, 'finish', 'Thêm hành lá và thưởng thức nóng với cơm trắng', 'Thả hành lá cắt khúc vào chảo đảo nhẹ 15 giây rồi tắt bếp ngay. Múc cua xào cay ra đĩa, rắc thêm vài lát ớt hiểm lên trên và dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-0ec0d1db60dbdc1e_v4_step_1', 'imp-0ec0d1db60dbdc1e', 1, 'prep', 'Làm sạch gà, lạng mỡ gà và nấu nước dùng nền', 'Rửa sạch con gà ta 1300 g, lạng riêng phần mỡ quanh cổ và phao câu để thắng lấy mỡ; chặt đầu, cổ, cánh cho vào nồi lớn cùng củ cải trắng cắt khúc, hành tây bổ đôi, 4 tép tỏi đập dập, 3 lát gừng tươi, 10 g rễ ngò rí và 2 g tiêu trắng xay. Đổ 1800 ml nước lọc vào đun sôi rồi hạ lửa nhỏ ninh 15 phút.', NULL, 15),
('imp-0ec0d1db60dbdc1e_v4_step_2', 'imp-0ec0d1db60dbdc1e', 2, 'cook', 'Luộc gà lửa liu riu cho thịt chín mọng không nát', 'Vớt sạch bọt trong nồi nước dùng, nêm 12 g muối ăn rồi nhẹ nhàng thả nguyên con gà vào sao cho nước ngập thân gà. Hạ lửa nhỏ giữ nước chỉ sôi lăn tăn nhẹ (không sôi bùng) và luộc khoảng 35 phút đến khi xăm phần đùi dày nhất thấy nước chảy ra trong suốt không còn đỏ hồng; vớt gà ra để nguội bớt mới chặt.', 'Luộc gà ở nhiệt độ sôi lăn tăn nhẹ và để gà nguội hoàn toàn mới chặt sẽ giúp da gà căng bóng không rách và thớ thịt giữ trọn nước ngọt.', 35),
('imp-0ec0d1db60dbdc1e_v4_step_3', 'imp-0ec0d1db60dbdc1e', 3, 'cook', 'Thắng mỡ gà, phi thơm tỏi và xào gạo nấu cơm', 'Trong chảo nóng trên lửa vừa, cho 15 ml dầu ăn thực vật cùng phần mỡ da gà đã lạng vào rán chảy lấy nước mỡ gà thơm trong rồi vớt bỏ phần tóp mỡ. Cho 4 tép tỏi băm vào phi thơm 30 giây rồi trút 360 g gạo tẻ thơm vo sạch vào đảo đều 3 phút cho hạt gạo săn bóng mỡ thơm; chuyển vào nồi cơm điện, múc 650 ml nước luộc gà nóng chan vào và bật nấu chín.', 'Rang gạo cùng mỡ gà và tỏi phi trước khi nấu giúp hạt cơm bóng đẹp, tơi ráo và dậy hương béo thơm đặc trưng.', 20),
('imp-0ec0d1db60dbdc1e_v4_step_4', 'imp-0ec0d1db60dbdc1e', 4, 'sauce', 'Pha chén sốt tương đậu nành Taojiew gừng tỏi ớt', 'Giã nhuyễn 20 g gừng tươi còn lại cùng 4 tép tỏi và ớt hiểm. Cho hỗn hợp này vào chén cùng 35 g tương đậu nành lên men, 15 ml xì dầu đặc, 20 ml xì dầu thường, 5 ml giấm gạo, 20 g đường cát trắng và nước cốt của 1 quả chanh tươi, khuấy tan hết đường.', 'Tương đậu nành lên men Taojiew có độ mặn dịu đặc trưng; hãy nếm thử chén sốt và cân chỉnh thêm chút nước luộc gà nếu thích vị thanh nhẹ hơn.', NULL),
('imp-0ec0d1db60dbdc1e_v4_step_5', 'imp-0ec0d1db60dbdc1e', 5, 'prep', 'Chặt thịt gà đã nguội và thái dưa leo ăn kèm', 'Khi gà đã nguội hẳn, dùng dao sắc lọc và chặt thịt gà thành từng miếng vừa ăn giữ nguyên da bóng đẹp; rửa sạch dưa leo tươi và thái lát xéo dày 0,5 cm để xếp kèm đĩa cơm.', NULL, NULL),
('imp-0ec0d1db60dbdc1e_v4_step_6', 'imp-0ec0d1db60dbdc1e', 6, 'finish', 'Xới cơm tơi và hoàn thiện đĩa cơm gà nóng hổi', 'Khi cơm chín bật nút, xới tơi hạt cơm bóng thơm ra đĩa, xếp thịt gà chặt miếng cùng dưa leo thái lát bên cạnh. Múc bát nước luộc gà nóng rắc 15 g lá ngò rí thái nhỏ ăn kèm và chấm thịt gà đẫm sốt tương đậu gừng tỏi ớt.', NULL, NULL),
('imp-4316659025be0f91_v4_step_1', 'imp-4316659025be0f91', 1, 'marinate', 'Ướp thịt thăn bò mềm mọng và ngâm sợi hủ tiếu', 'Ngâm 240 g hủ tiếu khô bản rộng trong nước lạnh 30 phút cho sợi mềm dẻo rồi vớt ra rổ để thật ráo. Thịt thăn bò thái lát mỏng ngang thớ, ướp cùng 10 ml xì dầu, 2 g đường cát trắng và 20 ml nước lọc trong 15 phút để thịt ngấm vị và giữ ẩm.', 'Không ngâm hủ tiếu khô bằng nước sôi vì sợi sẽ nhanh nhũn và dễ đứt gãy khi đảo mạnh trên chảo.', 30),
('imp-4316659025be0f91_v4_step_2', 'imp-4316659025be0f91', 2, 'prep', 'Giã tỏi ớt, pha sốt xào và cắt thái rau củ', 'Giã dập thô tỏi khô và ớt hiểm trong cối. Trong chén nhỏ, khuấy đều 25 ml dầu hào, 15 ml xì dầu còn lại, 5 ml xì dầu đặc và 5 ml nước mắm. Thái sợi cà rốt, thái xéo ớt chuông đỏ, tách riêng cọng và lá cải rổ, nhặt lá húng quế Thái để ráo.', NULL, NULL),
('imp-4316659025be0f91_v4_step_3', 'imp-4316659025be0f91', 3, 'cook', 'Áp chảo thịt bò chín tới trên lửa lớn', 'Đun nóng chảo rộng với 15 ml dầu ăn trên lửa lớn, dàn đều thịt bò đã ướp thành một lớp và áp chảo nhanh 2 phút đến khi hai mặt xém nâu nhẹ, thịt chín tái vừa tới thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-4316659025be0f91_v4_step_4', 'imp-4316659025be0f91', 4, 'cook', 'Phi tỏi ớt giã và xào nhanh rau củ cứng', 'Hạ lửa vừa, thêm 25 ml dầu ăn còn lại vào chảo phi thơm hỗn hợp tỏi ớt giã khoảng 30 giây (tránh cháy). Bật lửa lớn, cho cà rốt, ớt chuông đỏ và phần cọng cải rổ vào xào nhanh 45 giây cho vừa chín giòn.', NULL, NULL),
('imp-4316659025be0f91_v4_step_5', 'imp-4316659025be0f91', 5, 'cook', 'Đảo mì thấm sốt và áp chảo xém cạnh tạo mùi khói', 'Cho hủ tiếu đã ráo vào chảo, rưới đều chén sốt đã pha và rắc 16 g đường cát trắng còn lại lên mặt mì. Đảo nhanh 2 phút cho sợi mì thấm bóng sốt, sau đó dàn phẳng mặt chảo giữ yên 20 giây cho sợi mì hơi xém cạnh thơm mùi khói chảo rồi lật đảo lại.', 'Để yên sợi mì tiếp xúc đáy chảo nóng 15–20 giây không đảo sẽ tạo lớp xém nhẹ caramel đặc trưng của Pad Kee Mao.', 3),
('imp-4316659025be0f91_v4_step_6', 'imp-4316659025be0f91', 6, 'finish', 'Trộn thịt bò, lá húng quế Thái và dọn nóng', 'Trút thịt bò đã áp chảo (gạn bỏ nước thịt đọng để mì không nhão) trở lại chảo cùng phần lá cải rổ, đảo đều 30 giây cho thịt bò chín hoàn toàn. Tắt bếp, thả ngay 50 g lá húng quế Thái và hành lá vào đảo vài lượt cho lá vừa héo dậy mùi thơm nồng rồi bày ra đĩa dùng nóng.', 'Chỉ cho lá húng quế Thái vào sau khi tắt bếp để hơi nóng còn lại làm héo nhẹ mà lá không bị thâm đen hay mất hương thơm.', NULL),
('imp-0e30c82a4c77802e_v4_step_1', 'imp-0e30c82a4c77802e', 1, 'prep', 'Ướp lạnh đậu phụ non và rang thơm hạt mè', 'Đặt hộp 450 g đậu phụ non vào ngăn mát tủ lạnh ít nhất 2 giờ để đậu mát sâu và săn mịn. Rang khô 10 g hạt mè trên chảo nhỏ lửa nhỏ khoảng 2 phút đến khi mè dậy mùi thơm bùi thì trút ra chén để nguội.', 'Đậu phụ non càng mát lạnh khi ăn cùng nước trộn chua cay mặn ngọt sẽ càng thanh mát và giữ khối đẹp hơn.', 5),
('imp-0e30c82a4c77802e_v4_step_2', 'imp-0e30c82a4c77802e', 2, 'prep', 'Băm nhuyễn sả non và thái hạt lựu rau củ', 'Băm thật nhuyễn lõi non của 1,5 cây sả tươi và 4 quả ớt hiểm. Thái hạt lựu nhỏ 20 g hành tím, dưa leo bỏ ruột và ớt chuông đỏ; thái nhỏ hành lá, ngò rí và lá bạc hà (húng lủi).', 'Phần sả dùng ăn sống nên chỉ lấy lõi non trắng mềm nhất và băm thật mịn để không bị xơ cứng khi nhai.', NULL),
('imp-0e30c82a4c77802e_v4_step_3', 'imp-0e30c82a4c77802e', 3, 'sauce', 'Pha nước trộn đường thốt nốt hòa tan kỹ', 'Cho 20 g đường thốt nốt bào vụn vào tô cùng 35 ml xì dầu nhạt, nước cốt của 1,5 quả chanh tươi và ớt hiểm băm, khuấy kỹ khoảng 2 phút đến khi đường tan hoàn toàn thành hỗn hợp sánh thơm.', NULL, NULL),
('imp-0e30c82a4c77802e_v4_step_4', 'imp-0e30c82a4c77802e', 4, 'sauce', 'Trộn thấm các loại rau củ và rau thơm', 'Cho hành tím, sả băm, dưa leo, ớt chuông đỏ, hành lá, ngò rí và lá bạc hà vào tô nước trộn vừa pha, đảo nhẹ đều tay và để nghỉ 5 phút cho rau củ ngấm đều vị chua cay mặn ngọt.', NULL, 5),
('imp-0e30c82a4c77802e_v4_step_5', 'imp-0e30c82a4c77802e', 5, 'prep', 'Cắt khối đậu phụ non xếp ngay ngắn ra đĩa sâu lòng', 'Nhẹ nhàng lấy đậu phụ non ra khỏi hộp, chắt bỏ hết nước, dùng dao mỏng sắc cắt thành khối vuông lớn cạnh 4 cm rồi xếp ngay ngắn vào đĩa sâu lòng để hứng nước trộn.', NULL, NULL),
('imp-0e30c82a4c77802e_v4_step_6', 'imp-0e30c82a4c77802e', 6, 'finish', 'Phủ rau trộn, rưới sốt đáy đĩa và rắc mè rang', 'Múc phần rau củ trộn đặt gọn lên mặt từng miếng đậu phụ non, rưới nước trộn còn lại xung quanh đáy đĩa và rắc hạt mè rang thơm lên trên để thưởng thức ngay khi đậu còn mát lạnh.', 'Đặt rau trộn lên mặt và rưới nước sốt xung quanh đáy đĩa thay vì trộn đảo chung để các khối đậu phụ non không bị vỡ nát.', NULL),
('imp-d005aca18d138bfe_v4_step_1', 'imp-d005aca18d138bfe', 1, 'prep', 'Làm sạch tôm, giã tỏi ớt và nhặt lá húng quế', 'Rửa sạch 350 g tôm tươi, bóc vỏ, bỏ đầu và rút sạch chỉ đen sống lưng, để thật ráo. Giã thô tỏi bóc vỏ cùng ớt hiểm trong cối cho dậy mùi tinh dầu. Nhặt lá húng quế Thái rửa ráo; thái múi cau hành tây và cắt khúc hành lá.', 'Giã thô tỏi và ớt bằng cối đá giúp giải phóng nhiều tinh dầu thơm nồng hơn so với băm nhỏ bằng dao.', NULL),
('imp-d005aca18d138bfe_v4_step_2', 'imp-d005aca18d138bfe', 2, 'sauce', 'Pha sẵn chén sốt Pad Krapao đậm vị', 'Khuấy tan hoàn toàn 30 ml dầu hào, 15 ml xì dầu nhạt, 15 ml nước mắm, 8 g đường cát trắng và 15 ml nước lọc trong chén nhỏ để sẵn bên bếp.', NULL, NULL),
('imp-d005aca18d138bfe_v4_step_3', 'imp-d005aca18d138bfe', 3, 'cook', 'Phi thơm tỏi ớt giã trên chảo dầu nóng', 'Đun nóng chảo rộng với 35 ml dầu ăn trên lửa vừa-lớn, cho hỗn hợp tỏi ớt giã vào phi thơm khoảng 30 giây đến khi tỏi vừa ngả vàng thơm nồng và dậy mùi cay.', 'Canh chảo thật nóng và đảo liên tục khi phi tỏi ớt để tỏi thơm vàng mà không bị cháy khét gây đắng.', NULL),
('imp-d005aca18d138bfe_v4_step_4', 'imp-d005aca18d138bfe', 4, 'cook', 'Xào săn tôm nhanh trên lửa lớn', 'Tăng lửa lên mức lớn nhất, trút toàn bộ tôm tươi đã ráo nước vào chảo đảo nhanh tay khoảng 2 phút đến khi tôm chuyển màu đỏ hồng cong đều và săn bề mặt.', NULL, 2),
('imp-d005aca18d138bfe_v4_step_5', 'imp-d005aca18d138bfe', 5, 'cook', 'Om nhanh tôm trong sốt và xào hành tây chín giòn', 'Rưới đều chén sốt đã pha vào chảo tôm, đảo đều khoảng 1 phút cho sốt sôi sánh bám quanh thân tôm. Nếu dùng hành tây, thả hành tây thái lát vào đảo tiếp 1 phút cho hành vừa chín trong và tôm chín hoàn toàn.', NULL, 2),
('imp-d005aca18d138bfe_v4_step_6', 'imp-d005aca18d138bfe', 6, 'finish', 'Đảo lá húng quế Thái khi tắt bếp và dọn nóng', 'Tắt bếp ngay, thả toàn bộ 30 g lá húng quế Thái và hành lá cắt khúc vào chảo đảo nhanh 3–4 lượt để hơi nóng làm lá vừa héo dậy hương thơm nồng đặc trưng mà vẫn giữ màu xanh mướt. Trút ra đĩa dùng nóng với cơm trắng.', 'Chỉ cho lá húng quế vào sau khi đã tắt bếp để tránh lá bị thâm đen và bay mất tinh dầu thơm.', NULL),
('imp-a9710414682c8521_v4_step_1', 'imp-a9710414682c8521', 1, 'marinate', 'Ướp thịt bò mềm đậm và pha sẵn sốt xì dầu', 'Thái 300 g thịt thăn bò thành lát mỏng ngang thớ, ướp cùng 10 ml xì dầu, 2 g đường cát trắng và 5 ml dầu ăn trong 20 phút cho thịt thấm vị và tơi mềm. Trong chén nhỏ, khuấy tan 15 ml xì dầu còn lại, 20 ml dầu hào, 10 ml xì dầu đặc và 13 g đường cát trắng.', NULL, 20),
('imp-a9710414682c8521_v4_step_2', 'imp-a9710414682c8521', 2, 'prep', 'Luộc mì trứng vừa chín tới và sơ chế rau củ', 'Đun sôi 1500 ml nước lọc, cho 270 g mì trứng khô vào luộc khoảng 3–4 phút cho sợi vừa mềm tới (vẫn còn độ dai lõi), vớt ra xả ngay nước lạnh, để ráo và trộn 5 ml dầu ăn cho sợi tơi không dính. Thái sợi bắp cải, băm nhỏ tỏi, cắt khúc hành lá và đánh tan 2 quả trứng gà.', 'Không luộc mì quá mềm vì sợi mì còn tiếp tục chín và thấm sốt trong chảo nóng ở bước xào.', 4),
('imp-a9710414682c8521_v4_step_3', 'imp-a9710414682c8521', 3, 'cook', 'Xào nhanh thịt bò trên lửa lớn rồi trút riêng', 'Làm nóng chảo rộng với 15 ml dầu ăn trên lửa lớn nhất, cho thịt bò đã ướp vào đảo nhanh tay 2 phút đến khi thịt vừa chín tái tới thì trút ngay ra đĩa riêng (không xào lâu kẻo thịt dai).', NULL, 2),
('imp-a9710414682c8521_v4_step_4', 'imp-a9710414682c8521', 4, 'cook', 'Phi thơm tỏi, đánh tơi trứng và xào bắp cải giòn ngọt', 'Thêm 10 ml dầu ăn còn lại vào chảo trên lửa vừa, phi thơm tỏi băm 30 giây. Đổ trứng gà đánh tan vào để yên 15 giây cho se mặt rồi đảo tơi thành miếng vừa. Cho bắp cải vào xào lửa lớn 2 phút (thêm 30 ml nước lọc nếu chảo hơi khô) đến khi bắp cải vừa chín giòn.', NULL, NULL),
('imp-a9710414682c8521_v4_step_5', 'imp-a9710414682c8521', 5, 'cook', 'Xào mì thấm sốt xì dầu và áp chảo xém cạnh', 'Cho mì trứng đã luộc vào chảo, rưới toàn bộ chén sốt xì dầu dầu hào vào đảo đều 2 phút cho sợi mì thấm màu nâu bóng đẹp. Dàn phẳng mì ra mặt chảo giữ yên 20 giây cho một mặt hơi xém thơm mùi khói rồi lật đảo thêm một lượt.', 'Áp chảo để sợi mì hơi xém nâu nhẹ giúp món Pad See Ew dậy hương vị thơm bùi đặc trưng khó cưỡng.', NULL),
('imp-a9710414682c8521_v4_step_6', 'imp-a9710414682c8521', 6, 'finish', 'Trộn lại thịt bò, rắc tiêu hành và dọn nóng', 'Cho thịt bò đã xào (gạn bỏ phần nước thịt đọng) trở lại chảo cùng hành lá cắt khúc, đảo nhanh 30 giây cho thịt bò chín hoàn toàn và quyện đều với mì. Tắt bếp, rắc 1,5 g tiêu đen xay lên trên rồi gắp ra đĩa dùng nóng.', 'Gạn bỏ phần nước thịt bò đọng lại trên đĩa trước khi trút vào chảo để sợi mì luôn ráo bóng và không bị nhão.', NULL),
('imp-c64c83ef34771b5a_v4_step_1', 'imp-c64c83ef34771b5a', 1, 'prep', 'Sơ chế thảo mộc tạo hương Thái', 'Bóc bỏ lớp bẹ già bên ngoài của 2 cây sả tươi, dùng sống dao đập dập phần gốc rồi cắt khúc dài khoảng 8 cm. Củ riềng tươi cạo vỏ, thái 4 lát mỏng. Lá chanh Thái rửa sạch rồi dùng tay xé đôi bỏ gân cứng; ớt hiểm đỏ đập dập nhẹ. Vắt 1,5 quả chanh tươi lấy khoảng 30 ml nước cốt để riêng.', 'Đập dập sả và xé rách lá chanh Thái ngay trước khi nấu giúp tinh dầu thơm thoát ra mạnh mẽ nhất mà không làm đắng nước dùng.', NULL),
('imp-c64c83ef34771b5a_v4_step_2', 'imp-c64c83ef34771b5a', 2, 'prep', 'Chuẩn bị nấm đùi gà, đậu phụ và rau thơm', 'Dùng khăn ẩm lau sạch 350 g nấm đùi gà rồi cắt bỏ chân nấm, thái lát vát dày 0,5 cm cho vừa miệng. Cà chua rửa sạch, bổ 8 múi cau. Đậu phụ non cắt khối vuông cạnh 2 cm đặt riêng ra đĩa. Hành lá và ngò rí rửa sạch, để ráo rồi thái nhỏ.', 'Tránh ngâm nấm đùi gà quá lâu trong nước vì nấm hút nước sẽ nhão và giảm vị ngọt tự nhiên khi nấu.', NULL),
('imp-c64c83ef34771b5a_v4_step_3', 'imp-c64c83ef34771b5a', 3, 'cook', 'Xào sơ cà chua và nấm dậy vị ngọt', 'Đặt nồi lên bếp ở lửa vừa, làm nóng 10 ml dầu ăn thực vật rồi cho một nửa phần cà chua bổ múi cùng nấm đùi gà vào đảo nhanh trong 2 phút đến khi nấm hơi săn mặt và dậy mùi thơm nhẹ.', NULL, 2),
('imp-c64c83ef34771b5a_v4_step_4', 'imp-c64c83ef34771b5a', 4, 'cook', 'Ninh nước dùng sả riềng lá chanh', 'Đổ 950 ml nước lọc vào nồi nấm, thả sả tươi đập dập, riềng tươi thái lát và lá chanh Thái vào đun lửa lớn đến khi sôi bùng. Hạ lửa vừa và nấu sôi lăn riu trong 5 phút cho tinh dầu thảo mộc hòa quyện vào nước dùng, hớt bỏ bọt nếu có.', 'Thời gian ninh 5 phút giúp nước dùng chuyển hơi ánh xanh dịu và thơm nồng mùi sả riềng mà lá chanh không bị nồng hắc.', 5),
('imp-c64c83ef34771b5a_v4_step_5', 'imp-c64c83ef34771b5a', 5, 'cook', 'Nấu chín nấm, đậu phụ non và cà chua', 'Thả nhẹ phần cà chua còn lại, ớt hiểm đỏ và đậu phụ non vào nồi. Nêm 8 g hạt nêm chay nấm hương và 8 g đường cát trắng, khuấy thật nhẹ tay theo thành nồi trong 3 phút ở lửa vừa để đậu phụ nóng đều mà không bị vỡ nát, nấm chín mềm ngọt.', NULL, 3),
('imp-c64c83ef34771b5a_v4_step_6', 'imp-c64c83ef34771b5a', 6, 'finish', 'Tắt bếp nêm chanh, nước mắm chay và hoàn thiện', 'Tắt bếp rồi mới rót 30 ml nước mắm chay và 30 ml nước cốt chanh tươi vào khuấy nhẹ cho hòa vị chua thanh dịu. Vớt bỏ bớt xác sả, riềng và lá chanh Thái, múc canh ra tô, rắc hành lá và ngò rí lên trên rồi dùng nóng.', 'Luôn tắt bếp trước khi cho nước cốt chanh tươi để giữ trọn vị chua thanh mát và tránh làm tinh dầu vỏ chanh gây vị đắng.', NULL),
('imp-a71f6ef791b463ea_v4_step_1', 'imp-a71f6ef791b463ea', 1, 'prep', 'Làm sạch tôm và sơ chế rau gia vị', 'Tôm sú rửa sạch, bóc bỏ đầu và vỏ thân nhưng giữ lại chóp đuôi cho đẹp, dùng dao khía nhẹ sống lưng rút sạch chỉ đen. Bóc vỏ già của 3 cây sả tươi: lấy 1 cây đập dập để nấu nước chần, 2 cây còn lại thái lát vát thật mỏng phần thân trắng non. Bóc vỏ hành tím thái lát mỏng, băm nhuyễn tỏi khô và 2 quả ớt hiểm đỏ; thái sợi 1 quả ớt còn lại. Rửa sạch ngò gai, lá bạc hà và hành lá rồi để thật ráo.', 'Thái sả tươi càng mỏng theo lát chéo thì khi trộn gỏi sẽ thơm dịu, giòn mềm và không bị xơ cứng khi nhai.', NULL),
('imp-a71f6ef791b463ea_v4_step_2', 'imp-a71f6ef791b463ea', 2, 'cook', 'Chần chín tôm với nước sả thơm', 'Đun sôi 400 ml nước lọc cùng cây sả đập dập trên lửa lớn. Khi nước sôi bùng, thả toàn bộ 500 g tôm sú vào chần trong 2 phút đến khi tôm chuyển màu đỏ cam đều, thân cong tròn và thịt trắng đục chín hoàn toàn.', 'Không luộc tôm quá lâu làm thịt tôm mất nước và bị bở; vừa thấy thân tôm cong săn và chuyển màu đỏ hồng hoàn toàn là vớt ngay.', 2),
('imp-a71f6ef791b463ea_v4_step_3', 'imp-a71f6ef791b463ea', 3, 'prep', 'Ngâm tôm lạnh giữ độ giòn sần sật', 'Vớt tôm vừa chần chín thả ngay vào tô 200 ml nước lọc lạnh có đá trong 3 phút để hãm nhiệt giúp thịt tôm giòn chắc, đồng thời ngâm chung hành tím thái lát cho bớt vị hăng. Sau đó vớt tôm và hành tím ra rổ, dùng khăn giấy thấm thật ráo nước.', NULL, 3),
('imp-a71f6ef791b463ea_v4_step_4', 'imp-a71f6ef791b463ea', 4, 'sauce', 'Pha nước sốt trộn gỏi chua cay Thái', 'Trong chén nhỏ, hòa tan 30 ml nước mắm ngon, 20 g đường cát trắng, 20 ml tương ớt Thái và 45 ml nước cốt chanh tươi đến khi đường tan hết. Cho toàn bộ tỏi băm và 2 quả ớt hiểm băm vào khuấy đều để tạo hỗn hợp sốt sánh thơm đủ vị chua, cay, mặn, ngọt.', 'Nếm thử nước sốt sao cho vị hơi đậm đà một chút vì khi trộn với tôm và rau thơm sẽ dịu lại vừa miệng.', NULL),
('imp-a71f6ef791b463ea_v4_step_5', 'imp-a71f6ef791b463ea', 5, 'finish', 'Trộn gỏi tôm sả chanh nhẹ tay', 'Cho tôm đã ráo nước vào âu trộn lớn cùng sả non thái mỏng, hành tím, ngò gai và hành lá. Rưới từ từ nước sốt đã pha lên, đảo nhẹ tay trong 1 phút cho từng con tôm và lát sả áo đều lớp sốt bóng đẹp.', NULL, NULL),
('imp-a71f6ef791b463ea_v4_step_6', 'imp-a71f6ef791b463ea', 6, 'finish', 'Hoàn thiện với lá bạc hà và thưởng thức ngay', 'Cho gỏi tôm ra đĩa sâu lòng, rắc lá bạc hà tươi và ớt sợi lên trên cùng để giữ màu xanh tươi mát không bị thâm. Dọn dùng ngay khi gỏi còn mát lạnh và giòn ngọt.', NULL, NULL),
('imp-9236740e2b55e8a1_v4_step_1', 'imp-9236740e2b55e8a1', 1, 'prep', 'Sơ chế thịt gà, cơm nguội và pha mắm ớt Thái', 'Thịt đùi gà lọc xương thái hạt lựu 1,5 cm, ướp nhanh trong 5 phút với 5 ml xì dầu nhạt và 1 g tiêu trắng xay. Đánh tơi 450 g cơm nguội bằng tay cho các hạt tách rời. Thái hạt lựu cà rốt; băm nhỏ tỏi và hành tím; thái khoanh hành lá, ngò rí; thái lát dưa leo và cắt múi cau chanh. Pha chén nước mắm ớt Prik Nam Pla với 20 ml nước mắm ngon, 3 quả ớt hiểm thái lát, 1/3 lượng tỏi băm và vắt vài giọt nước cốt chanh.', 'Dùng cơm nguội để tủ mát qua đêm giúp hạt cơm khô bề mặt, khi rang không bị bết dính và bắt gia vị rất đều.', 5),
('imp-9236740e2b55e8a1_v4_step_2', 'imp-9236740e2b55e8a1', 2, 'cook', 'Phi thơm tỏi hành và xào chín thịt đùi gà', 'Đun nóng chảo sâu lòng trên lửa vừa-lớn với 15 ml dầu ăn thực vật. Cho 2/3 phần tỏi băm và hành tím băm vào phi khoảng 45 giây đến khi dậy mùi thơm, tiếp tục cho thịt đùi gà và cà rốt vào đảo đều 3–4 phút cho đến khi thịt gà chuyển trắng đục, săn cạnh và chín hoàn toàn bên trong.', NULL, 4),
('imp-9236740e2b55e8a1_v4_step_3', 'imp-9236740e2b55e8a1', 3, 'cook', 'Chiên tơi trứng gà ngay trong chảo', 'Gạt thịt gà và cà rốt sang một bên chảo, thêm 10 ml dầu ăn thực vật vào khoảng trống còn lại, đập 2 quả trứng gà vào. Chờ khoảng 20 giây cho lòng trắng hơi se mặt rồi dùng muôi đánh tơi thành từng mảng trứng mềm xốp trước khi trộn chung với thịt gà.', NULL, NULL),
('imp-9236740e2b55e8a1_v4_step_4', 'imp-9236740e2b55e8a1', 4, 'cook', 'Rang cơm nguội trên lửa lớn cho tơi hạt', 'Trút toàn bộ 450 g cơm nguội vào chảo, tăng lên lửa lớn và đảo tơi liên tục khoảng 3 phút cho hạt cơm nóng đều, săn lại và quyện cùng trứng, thịt gà. Thỉnh thoảng để cơm yên 10 giây rồi mới đảo để tạo mùi thơm xém chảo nhẹ.', 'Giữ lửa lớn và không đè nát hạt cơm giúp đĩa Khao Pad tơi bóng và có hương thơm đặc trưng như ngoài hàng.', 3),
('imp-9236740e2b55e8a1_v4_step_5', 'imp-9236740e2b55e8a1', 5, 'cook', 'Nêm xì dầu, nước mắm và đường cho cơm thấm vị', 'Rưới 15 ml xì dầu nhạt và 15 ml nước mắm ngon quanh thành chảo nóng để gia vị bốc mùi thơm, rắc 8 g đường cát trắng và 1 g tiêu trắng xay còn lại. Đảo nhanh tay thêm 2 phút cho hạt cơm lên màu vàng nhạt óng ả và thấm đều gia vị.', 'Rưới xì dầu nhạt và nước mắm men theo thành chảo nóng thay vì đổ trực tiếp vào giữa cơm giúp gia vị bốc hương thơm chảo wok và bám đều từng hạt.', 2),
('imp-9236740e2b55e8a1_v4_step_6', 'imp-9236740e2b55e8a1', 6, 'finish', 'Tắt bếp trộn hành lá và bày đĩa ăn kèm', 'Tắt bếp ngay rồi cho hành lá và ngò rí vào đảo nhanh 10 giây cho vừa dậy mùi thơm mà vẫn giữ màu xanh tươi. Xới cơm chiên gà ra đĩa, xếp dưa leo thái lát, múi chanh tươi bên cạnh và dọn nóng cùng chén nước mắm ớt Prik Nam Pla.', NULL, NULL),
('imp-a1904f60d9f4f10e_v4_step_1', 'imp-a1904f60d9f4f10e', 1, 'prep', 'Chuẩn bị tỏi thái lát, ngò tây và phô mai', 'Bóc vỏ 1 củ tỏi khô rồi thái thành các lát mỏng đều nhau. Rửa sạch 12 g ngò tây tươi, thấm khô và thái nhỏ phần lá. Bào mịn sẵn 35 g phô mai Parmesan và chuẩn bị sẵn 70 g bơ lạt chia làm hai phần bằng nhau.', 'Thái tỏi thành lát mỏng đều giúp tỏi tiết hương thơm ngọt từ từ trong bơ mà không dễ bị cháy xém như tỏi băm nhuyễn.', NULL),
('imp-a1904f60d9f4f10e_v4_step_2', 'imp-a1904f60d9f4f10e', 2, 'cook', 'Đun nước muối sôi và luộc mì Spaghetti', 'Đun sôi mạnh 2500 ml nước lọc trong nồi lớn, hòa tan 15 g muối ăn rồi thả 300 g mì Ý Spaghetti khô vào luộc khoảng 8 phút (ít hơn 1 phút so với hướng dẫn bao bì để mì còn độ dai al dente). Trước khi vớt mì, múc giữ lại khoảng 120 ml nước luộc mì.', 'Không nên dùng quá nhiều nước khi luộc mì để giữ nồng độ tinh bột cao trong nước luộc, giúp sốt bơ nhanh chóng sánh bóng khi nhũ hóa.', 8),
('imp-a1904f60d9f4f10e_v4_step_3', 'imp-a1904f60d9f4f10e', 3, 'sauce', 'Phi thơm tỏi lát và ớt vảy trong bơ lạt', 'Trong lúc luộc mì, đặt chảo lớn lên bếp ở lửa nhỏ, cho 35 g bơ lạt vào đun tan chảy nhẹ. Thả tỏi thái lát cùng 1 g ớt vảy khô vào đảo đều khoảng 1 phút đến khi tỏi sủi bọt nhẹ, dậy mùi thơm và vừa ngả vàng nhạt.', 'Tuyệt đối giữ lửa nhỏ để tỏi chỉ ngả vàng nhạt; nếu để tỏi chuyển nâu sậm, vị đắng sẽ làm hỏng cả chảo sốt bơ.', 1),
('imp-a1904f60d9f4f10e_v4_step_4', 'imp-a1904f60d9f4f10e', 4, 'cook', 'Nhũ hóa mì cùng bơ và nước luộc mì', 'Dùng kẹp gắp trực tiếp mì Spaghetti vừa luộc sang chảo bơ tỏi, rót vào khoảng 60 ml nước luộc mì giữ lại. Bật lửa vừa, đảo và xóc chảo liên tục trong 1–2 phút cho tinh bột trong nước luộc quyện cùng bơ thành lớp sốt sánh bóng bám đều sợi mì; thêm chút nước luộc nếu thấy khô.', NULL, 2),
('imp-a1904f60d9f4f10e_v4_step_5', 'imp-a1904f60d9f4f10e', 5, 'finish', 'Đánh bóng bơ lạnh và trộn phô mai Parmesan', 'Cho nốt 35 g bơ lạt còn lại vào chảo đảo tan đều, sau đó tắt hẳn bếp và nhấc chảo khỏi nguồn nhiệt. Thêm 25 g phô mai Parmesan bào mịn, 3 g muối ăn (nêm từ từ theo khẩu vị), 1 g tiêu đen xay và 2/3 lượng ngò tây tươi thái nhỏ, đảo nhanh tay cho phô mai tan quyện mượt mà.', 'Luôn tắt bếp trước khi cho phô mai Parmesan để nhiệt độ dịu xuống, giúp phô mai tan quyện thành kem mịn mà không bị vón cục tách dầu.', NULL),
('imp-a1904f60d9f4f10e_v4_step_6', 'imp-a1904f60d9f4f10e', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Gắp mì xoắn gọn ra 3 đĩa sâu lòng khi còn nóng hổi, rưới hết phần sốt bơ tỏi trong chảo lên trên rồi rắc nốt 10 g phô mai Parmesan bào cùng phần ngò tây tươi còn lại.', NULL, NULL),
('imp-cc5f58548e934d9e_v4_step_1', 'imp-cc5f58548e934d9e', 1, 'prep', 'Sơ chế tôm tươi và các loại gia vị thơm', 'Bóc vỏ 400 g tôm tươi, bỏ đầu và rút sạch chỉ đen dọc sống lưng, rửa nhanh rồi thấm thật khô bằng khăn giấy. Ướp nhẹ tôm với 1 g muối ăn và 0,5 g tiêu đen xay. Thái lát mỏng 3–4 tép tỏi khô, bỏ hạt thái lát 1 quả ớt hiểm tươi, băm nhỏ 15 g ngò tây tươi và bào lấy phần vỏ vàng của 1/2 quả chanh vàng.', 'Thấm thật khô thịt tôm giúp tôm khi áp chảo nhanh săn chín, lên mùi thơm mà không bị tiết nước làm loãng dầu ô liu.', NULL),
('imp-cc5f58548e934d9e_v4_step_2', 'imp-cc5f58548e934d9e', 2, 'cook', 'Luộc mì Ý trong nước muối sôi già', 'Đun sôi mạnh 2500 ml nước lọc cùng 15 g muối ăn, cho 250 g mì Ý Spaghetti vào luộc khoảng 8 phút (ít hơn hướng dẫn bao bì 1 phút) để mì vừa đạt độ al dente. Trước khi vớt, múc giữ lại 120 ml nước luộc mì giàu tinh bột.', NULL, 8),
('imp-cc5f58548e934d9e_v4_step_3', 'imp-cc5f58548e934d9e', 3, 'sauce', 'Phi tỏi ớt và xào chín nhanh thịt tôm', 'Làm nóng chảo rộng trên lửa vừa với 45 ml dầu ô liu và 15 g bơ lạt. Cho tỏi thái lát và ớt hiểm vào phi thơm khoảng 1–2 phút đến khi tỏi vừa ngả vàng nhạt. Tăng lên lửa lớn, thả tôm đã ướp vào đảo đều khoảng 2–3 phút đến khi tôm cong chữ C và chuyển màu hồng đỏ chín hoàn toàn thì trút tôm ra đĩa riêng.', 'Vớt tôm ra ngay khi vừa chuyển hồng chín tới giúp thịt tôm giữ được độ giòn ngọt, không bị khô dai khi đảo chung với mì.', 3),
('imp-cc5f58548e934d9e_v4_step_4', 'imp-cc5f58548e934d9e', 4, 'cook', 'Đảo mì cùng nước luộc tạo sốt sánh nhẹ', 'Hạ chảo về lửa vừa, gắp mì Ý đã luộc cùng thịt tôm trở lại chảo dầu tỏi ớt. Rót thêm khoảng 60 ml nước luộc mì vào, xóc đều tay trong 1–2 phút để nước luộc tinh bột và dầu ô liu nhũ hóa thành lớp sốt sánh nhẹ bám đều từng sợi mì.', NULL, 2),
('imp-cc5f58548e934d9e_v4_step_5', 'imp-cc5f58548e934d9e', 5, 'finish', 'Hoàn thiện hương chanh vàng và phô mai', 'Tắt bếp và nhấc chảo ra ngoài. Thêm 20 g bơ lạt còn lại, 15 g phô mai Parmesan bào mịn, phần vỏ bào cùng vài giọt nước cốt chanh vàng, 15 g ngò tây băm và 0,5 g tiêu đen xay còn lại vào đảo nhanh tay đến khi bơ tan bóng mượt.', 'Bào vỏ chanh vàng chỉ lấy lớp tinh dầu bên ngoài, tránh cùi trắng vì sẽ gây vị đắng; cho vào sau khi tắt bếp giúp giữ trọn hương thơm tươi mát.', NULL),
('imp-cc5f58548e934d9e_v4_step_6', 'imp-cc5f58548e934d9e', 6, 'finish', 'Trình bày ra đĩa và dùng nóng ngay', 'Chia mì và tôm ra 3 đĩa sâu lòng khi còn nóng hổi, rưới hết phần sốt dầu tỏi thơm dưới chảo lên trên và thưởng thức ngay.', NULL, NULL),
('imp-8fdcddab058d5f65_v4_step_1', 'imp-8fdcddab058d5f65', 1, 'prep', 'Sơ chế cà chua tươi, tỏi và húng quế Tây', 'Rửa sạch 3,5 quả cà chua chín mọng, bỏ cuống rồi cắt miếng nhỏ cỡ 1,5 cm (nếu dùng cà chua bi chỉ cần bổ đôi). Bóc vỏ và đập dập 2–3 tép tỏi khô; rửa nhẹ 8 g lá húng quế Tây để thật ráo nước.', NULL, NULL),
('imp-8fdcddab058d5f65_v4_step_2', 'imp-8fdcddab058d5f65', 2, 'cook', 'Luộc mì Ý đạt độ dai al dente', 'Đun sôi mạnh 2500 ml nước lọc cùng 14 g muối ăn, thả 260 g mì Ý Spaghetti vào luộc khoảng 8 phút (ít hơn hướng dẫn bao bì 1 phút) để sợi mì giữ lõi hơi dai. Trước khi vớt mì, múc giữ lại 100 ml nước luộc mì.', 'Luộc mì ít hơn hướng dẫn bao bì 1 phút vì sợi mì còn tiếp tục chín trong chảo sốt nóng, giữ được độ dai chuẩn al dente.', 8);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-8fdcddab058d5f65_v4_step_3', 'imp-8fdcddab058d5f65', 3, 'sauce', 'Phi thơm tỏi và xào cà chua tươi', 'Đun nóng 35 ml dầu ô liu trong chảo lớn ở lửa vừa-nhỏ, cho tỏi đập dập vào phi thơm khoảng 1–2 phút mà không để tỏi chuyển nâu. Tăng lên lửa lớn, trút toàn bộ cà chua cắt nhỏ cùng 4 g muối ăn vào đảo đều 4 phút cho cà chua mềm xẹp và tiết nước ngọt.', 'Xào nhanh cà chua tươi trên lửa lớn giúp giữ trọn hương vị tươi mát và độ ngọt thanh tự nhiên, không bị nhừ nát quá mức.', 4),
('imp-8fdcddab058d5f65_v4_step_4', 'imp-8fdcddab058d5f65', 4, 'sauce', 'Nấu sánh sốt cùng cà chua cô đặc và húng quế', 'Thêm 10 g cà chua cô đặc vào chảo đảo tan đều, hạ lửa vừa và đun liu riu thêm 5 phút đến khi nước sốt hơi sánh quyện. Tắt bếp, xé nhỏ 5 g lá húng quế Tây cho vào cùng 1 g tiêu đen xay rồi đảo đều (có thể gắp bỏ xác tỏi nếu thích vị nhẹ).', 'Thêm lá húng quế Tây vào giai đoạn cuối giúp giữ nguyên mùi thơm dịu đặc trưng không bị bay hơi.', 5),
('imp-8fdcddab058d5f65_v4_step_5', 'imp-8fdcddab058d5f65', 5, 'cook', 'Xóc mì trực tiếp trong chảo sốt', 'Bật bếp lại ở lửa vừa, gắp mì Spaghetti vừa luộc vào thẳng chảo sốt cà chua. Đảo và xóc đều tay khoảng 1 phút, thêm từng chút nước luộc mì giữ lại nếu thấy khô để sốt bám bóng mượt vào từng sợi mì.', NULL, 1),
('imp-8fdcddab058d5f65_v4_step_6', 'imp-8fdcddab058d5f65', 6, 'finish', 'Trình bày và dọn nóng', 'Gắp mì ra 3 đĩa sâu lòng khi còn nóng hổi, rắc nốt 3 g lá húng quế Tây xé nhỏ và 25 g phô mai Parmesan bào mịn lên trên trước khi thưởng thức.', NULL, NULL),
('imp-d4d1de72f13e8f30_v4_step_1', 'imp-d4d1de72f13e8f30', 1, 'prep', 'Băm nhuyễn rau củ nền và thịt xông khói', 'Gọt vỏ cà rốt, rửa sạch cần tây, bóc vỏ hành tây rồi băm thật nhuyễn cả ba loại để tạo nền hương vị ngọt thanh. Thái nhỏ 150 g thịt ba chỉ xông khói và đun ấm sẵn 260 ml nước dùng rau củ trên bếp nhỏ.', 'Rau củ băm càng nhỏ mịn thì khi ninh lâu sẽ tan quyện vào sốt Ragù tạo độ sánh ngọt tự nhiên.', NULL),
('imp-d4d1de72f13e8f30_v4_step_2', 'imp-d4d1de72f13e8f30', 2, 'cook', 'Xào rau củ và áp chảo vàng thịt bò xay', 'Đun nóng 40 ml dầu ô liu trong nồi đế dày trên lửa vừa, cho thịt ba chỉ xông khói vào đảo 3–4 phút cho tươm mỡ vàng nhẹ. Thêm cà rốt, cần tây và hành tây băm vào xào 6 phút cho mềm trong. Tiếp theo cho 500 g thịt bò xay vào, tăng lửa lớn, dằm tơi và đảo khoảng 8–10 phút đến khi thịt săn vàng xém cạnh.', 'Phải áp chảo trên lửa lớn cho thịt bò xay săn vàng xém mặt thay vì xám nước để sốt Ragù có vị đậm đà thơm nức.', 18),
('imp-d4d1de72f13e8f30_v4_step_3', 'imp-d4d1de72f13e8f30', 3, 'sauce', 'Khử rượu vang và ninh chậm sốt bò bằm Ragù', 'Rót 80 ml rượu vang đỏ vào nồi thịt bò, cạo sạch lớp cháy thơm dưới đáy nồi và đun sôi khoảng 3 phút cho bay hết mùi cồn. Khuấy vào 300 g cà chua nghiền đóng hộp Ý, 25 g cà chua cô đặc, 5 g muối ăn, 2 g tiêu đen xay và 1 vá nước dùng rau củ nóng. Đậy nắp hé, hạ lửa thật nhỏ và ninh liu riu ít nhất 60–90 phút, thỉnh thoảng đảo và châm thêm nước dùng nóng khi cạn.', NULL, 75),
('imp-d4d1de72f13e8f30_v4_step_4', 'imp-d4d1de72f13e8f30', 4, 'sauce', 'Nấu sốt sữa trắng Béchamel sánh mịn', 'Đun nóng già 600 ml sữa tươi không đường (không để sôi trào). Trong nồi khác trên lửa vừa, làm tan chảy 38 g bơ lạt, đổ 38 g bột mì đa dụng vào khuấy liên tục 2 phút thành hỗn hợp roux vàng nhạt. Rót sữa nóng vào làm 3 đợt, mỗi lần vừa rót vừa khuấy mạnh bằng phới lồng cho tan mịn rồi đun 5 phút đến khi sốt sánh phủ lưng muỗng; nêm 3 g muối ăn và 1 g nhục đậu khấu xay.', 'Đổ sữa nóng từng phần nhỏ vào hỗn hợp bơ bột và khuấy liên tục giúp sốt Béchamel mịn mượt tuyệt đối, không bị vón cục.', 8),
('imp-d4d1de72f13e8f30_v4_step_5', 'imp-d4d1de72f13e8f30', 5, 'prep', 'Làm nóng lò và chuẩn bị lá mì Lasagna', 'Bật lò nướng làm nóng trước ở 175°C chế độ hai lửa trên-dưới. Nếu dùng lá mì Lasagna loại cần luộc trước, đun sôi 1500 ml nước lọc với 2 g muối ăn, chần từng lá mì khoảng 30–40 giây rồi trải phẳng lên khăn sạch (không xếp chồng); nếu dùng loại nướng trực tiếp thì bỏ qua bước chần.', NULL, NULL),
('imp-d4d1de72f13e8f30_v4_step_6', 'imp-d4d1de72f13e8f30', 6, 'cook', 'Xếp xen kẽ 5 tầng sốt và lá mì vào khuôn', 'Phết đều 4 g bơ lạt xuống đáy và thành khuôn nướng chữ nhật khoảng 30×20 cm. Trải một lớp mỏng sốt Béchamel và sốt Ragù xuống đáy khuôn, đặt một lớp lá mì Lasagna phủ kín, rồi lần lượt phết sốt Ragù, sốt Béchamel và rắc một phần phô mai Parmesan bào mịn. Lặp lại quy trình đến tầng thứ 5, trên cùng phủ sốt Ragù, sốt Béchamel, rắc dày phần phô mai Parmesan còn lại và rải vụn 3 g bơ lạt.', NULL, NULL),
('imp-d4d1de72f13e8f30_v4_step_7', 'imp-d4d1de72f13e8f30', 7, 'finish', 'Nướng vàng phồng và để nghỉ trước khi cắt', 'Đặt khuôn Lasagna vào ngăn giữa lò nướng ở 175°C trong khoảng 35–40 phút đến khi mặt phô mai vàng ruộm và phần sốt ở mép khuôn sôi sủi bọt (có thể che nhẹ giấy bạc trong 15 phút đầu nếu mặt vàng quá nhanh). Lấy khay ra để nghỉ 10 phút cho các lớp định hình chắc chắn rồi cắt miếng vuông dùng nóng.', NULL, 40),
('imp-3fd9eb5a7c40c3c0_v4_step_1', 'imp-3fd9eb5a7c40c3c0', 1, 'prep', 'Sơ chế gà, hành tây và hâm nóng nước dùng gà', 'Thấm thật khô 300 g ức gà phi lê rồi cắt thành khối hạt lựu 2 cm. Băm nhỏ 1 củ hành tây, băm nhuyễn 2 tép tỏi khô và băm nhỏ 10 g ngò tây tươi. Đổ 1200 ml nước dùng gà vào nồi riêng, đun sôi nhẹ rồi giữ nóng liu riu trên bếp phụ suốt quá trình nấu.', 'Nước dùng gà phải luôn giữ nóng; nếu châm nước nguội vào chảo gạo đang sôi sẽ làm hạt gạo sốc nhiệt và chín sượng không đều.', NULL),
('imp-3fd9eb5a7c40c3c0_v4_step_2', 'imp-3fd9eb5a7c40c3c0', 2, 'cook', 'Áp chảo chín vàng hạt lựu ức gà', 'Đun nóng 25 g bơ lạt cùng 15 ml dầu ô liu trong chảo sâu lòng trên lửa vừa-lớn. Thả ức gà vào áp chảo khoảng 5 phút, nêm 2 g muối ăn và 1 g tiêu đen xay, đảo đều đến khi các mặt thịt gà vàng thơm và chín hoàn toàn bên trong rồi gắp ra đĩa riêng.', NULL, 5),
('imp-3fd9eb5a7c40c3c0_v4_step_3', 'imp-3fd9eb5a7c40c3c0', 3, 'cook', 'Xào hành tây và rang hạt gạo Arborio', 'Cùng chiếc chảo đó, thêm 10 ml dầu ô liu ở lửa vừa, cho hành tây và tỏi băm vào xào 4 phút đến khi hành mềm trong. Trút toàn bộ 320 g gạo Ý Arborio (không vo rửa) vào đảo đều liên tục khoảng 2 phút đến khi viền hạt gạo hơi trong lại và tỏa mùi thơm bùi.', 'Không vo gạo Arborio và rang khô nhẹ 2 phút giúp hạt gạo săn lớp vỏ ngoài, giữ độ dẻo dai mà không bị nát bấy khi khuấy.', 6),
('imp-3fd9eb5a7c40c3c0_v4_step_4', 'imp-3fd9eb5a7c40c3c0', 4, 'cook', 'Châm rượu vang và nấu chậm cùng nước dùng gà', 'Rót 100 ml rượu vang trắng khô vào chảo gạo, khuấy đều 1–2 phút đến khi bay hết mùi cồn. Tiếp tục múc từng muôi nước dùng gà nóng châm vào xấp mặt gạo, khuấy nhẹ đều tay đến khi gạo hút gần cạn nước mới châm muôi tiếp theo. Lặp lại quá trình này trong khoảng 18 phút đến khi hạt gạo mềm dẻo bên ngoài và còn lõi hơi sần nhẹ.', NULL, 18),
('imp-3fd9eb5a7c40c3c0_v4_step_5', 'imp-3fd9eb5a7c40c3c0', 5, 'cook', 'Trộn thịt gà và nêm gia vị', 'Khi gạo gần chín tới (khoảng 3–4 phút cuối), trút toàn bộ ức gà đã áp chảo vào chảo cơm, châm thêm chút nước dùng gà nóng nếu thấy đặc và đảo nhẹ 3 phút cho thịt gà hòa vị cùng cơm. Nếm thử rồi nêm thêm khoảng 3 g muối ăn và 1 g tiêu đen xay cho vừa miệng.', NULL, NULL),
('imp-3fd9eb5a7c40c3c0_v4_step_6', 'imp-3fd9eb5a7c40c3c0', 6, 'finish', 'Đánh bóng bơ phô mai (Mantecatura) và dọn nóng', 'Tắt hẳn bếp, cho 25 g bơ lạt còn lại và 40 g phô mai Parmesan bào mịn vào chảo cơm, khuấy nhanh tay đến khi bơ và phô mai tan quyện thành lớp sốt kem bóng mượt bao đều từng hạt gạo. Múc ra 4 đĩa sâu lòng, rắc 10 g phô mai Parmesan còn lại cùng ngò tây băm lên trên và dùng nóng ngay.', 'Đánh bóng bơ và phô mai sau khi tắt bếp là kỹ thuật chuẩn Ý giúp Risotto sánh kem mịn màng thay vì bị tách dầu.', NULL),
('imp-4c5955ef4919d61a_v4_step_1', 'imp-4c5955ef4919d61a', 1, 'prep', 'Kiểm tra thịt cua và sơ chế gia vị thơm', 'Dùng tay kiểm tra nhẹ nhàng 250 g thịt cua biển gỡ sẵn để loại bỏ sạch các mảnh vỏ hay sụn cứng còn sót. Bóc vỏ đập dập 2–3 tép tỏi khô, bỏ hạt thái lát 2 quả ớt tươi, băm thật nhuyễn 12 g ngò tây tươi và bào lấy phần vỏ vàng thơm của 1 quả chanh vàng (tránh phần cùi trắng) rồi vắt sẵn 15 ml nước cốt.', NULL, NULL),
('imp-4c5955ef4919d61a_v4_step_2', 'imp-4c5955ef4919d61a', 2, 'cook', 'Luộc mì Spaghetti và giữ lại nước luộc', 'Đun sôi mạnh 3000 ml nước lọc cùng 15 g muối ăn, cho 360 g mì Ý Spaghetti vào luộc khoảng 8 phút (ít hơn hướng dẫn bao bì 1 phút) để sợi mì đạt độ dai al dente. Trước khi vớt mì, múc giữ lại 150 ml nước luộc mì.', 'Múc nước luộc mì ngay trước khi vớt để giữ phần tinh bột tự nhiên, giúp sốt dầu ô liu nhanh chóng nhũ hóa sánh mượt.', 8),
('imp-4c5955ef4919d61a_v4_step_3', 'imp-4c5955ef4919d61a', 3, 'sauce', 'Phi thơm nhẹ tỏi ớt và làm nóng thịt cua', 'Đặt chảo rộng lên bếp, cho 35 ml dầu ô liu, tỏi đập dập và ớt thái lát vào chảo ngay từ khi dầu còn nguội rồi bật lửa nhỏ. Phi từ từ 2–3 phút cho dầu dậy mùi thơm mà tỏi không bị vàng cháy, sau đó gắp bỏ xác tỏi. Cho 250 g thịt cua biển vào chảo đảo thật nhẹ tay khoảng 1–2 phút cho cua nóng đều và thấm dầu thơm.', 'Phi tỏi từ dầu nguội trên lửa nhỏ và gắp bỏ tỏi trước khi chuyển vàng giúp dầu thơm dịu mà không bị đắng; đồng thời không đảo mạnh làm nát thớ thịt cua.', 3),
('imp-4c5955ef4919d61a_v4_step_4', 'imp-4c5955ef4919d61a', 4, 'sauce', 'Nhũ hóa sốt trắng từ nước luộc mì', 'Múc khoảng 80 ml nước luộc mì đang nóng rót vào chảo thịt cua, nêm 3 g muối ăn rồi lắc nhẹ chảo trên lửa vừa khoảng 1 phút cho dầu ô liu và tinh bột trong nước luộc nhũ hóa thành lớp sốt hơi sánh bao quanh thịt cua.', NULL, NULL),
('imp-4c5955ef4919d61a_v4_step_5', 'imp-4c5955ef4919d61a', 5, 'cook', 'Xóc mì Spaghetti trong chảo sốt cua', 'Vớt mì Ý Spaghetti đang al dente cho thẳng vào chảo sốt cua, đảo và xóc chảo trên lửa vừa khoảng 1 phút để từng sợi mì hút trọn vị ngọt của cua và nước sốt. Nếu thấy khô, châm thêm từng chút nước luộc mì còn lại đến khi sốt bóng đều.', NULL, 1),
('imp-4c5955ef4919d61a_v4_step_6', 'imp-4c5955ef4919d61a', 6, 'finish', 'Trộn vỏ chanh vàng, ngò tây và dọn nóng', 'Tắt bếp, rắc phần vỏ chanh vàng bào mịn, vài giọt nước cốt chanh vàng và 12 g ngò tây băm nhỏ vào chảo, rưới thêm 10 ml dầu ô liu còn lại rồi trộn đều một lượt. Chia mì ra 4 đĩa sâu lòng và dùng nóng ngay.', 'Cho vỏ chanh và ngò tây sau khi tắt bếp để nhiệt dư làm dậy hương tươi mát mà không làm mất mùi tinh dầu tự nhiên.', NULL),
('imp-c398c169dc196c4e_v4_step_1', 'imp-c398c169dc196c4e', 1, 'prep', 'Rạch lưng rút chỉ tôm và sơ chế gia vị', 'Rửa sạch 600 g tôm sú hoặc tôm thẻ lớn dưới vòi nước lạnh, giữ nguyên vỏ để chống khô thịt khi nướng. Dùng kéo hoặc mũi dao nhọn xẻ một đường dọc sống lưng vỏ tôm, rút bỏ chỉ đen rồi thấm khô. Băm thật nhuyễn 2–3 tép tỏi khô, băm nhỏ 12 g ngò tây tươi và 1 quả ớt tươi bỏ hạt; bào lấy phần vỏ vàng thơm của 1 quả chanh vàng rồi vắt lấy nước cốt, 1/2 quả còn lại cắt múi.', 'Giữ nguyên lớp vỏ ngoài của tôm khi nướng trên lửa lớn giúp giữ trọn độ ẩm ngọt bên trong và tránh thịt tôm bị cháy sém.', NULL),
('imp-c398c169dc196c4e_v4_step_2', 'imp-c398c169dc196c4e', 2, 'marinate', 'Pha sốt dầu chanh tỏi và chia hai phần', 'Trong tô nhỏ, đánh đều 50 ml dầu ô liu, nước cốt và vỏ bào của 1 quả chanh vàng, tỏi băm, 8 g ngò tây băm, ớt tươi băm, 5 g muối ăn và 1,5 g tiêu đen xay. Trích riêng khoảng 2 muỗng canh hỗn hợp sạch này sang chén nhỏ để làm sốt rưới hoàn thiện.', NULL, NULL),
('imp-c398c169dc196c4e_v4_step_3', 'imp-c398c169dc196c4e', 3, 'marinate', 'Ướp thấm gia vị trong thời gian ngắn', 'Cho tôm đã thấm khô vào tô phần sốt ướp còn lại, xóc đều cho gia vị bám vào khe lưng và lớp vỏ tôm. Đậy kín và ướp trong ngăn mát tủ lạnh khoảng 20 phút.', 'Không ướp tôm cùng nước cốt chanh quá 30 phút vì axit chanh sẽ làm biến tính thịt tôm sống khiến tôm mất độ giòn sần.', 20),
('imp-c398c169dc196c4e_v4_step_4', 'imp-c398c169dc196c4e', 4, 'prep', 'Làm nóng vỉ nướng hoặc chảo gang rãnh', 'Làm nóng vỉ nướng hoặc chảo gang rãnh trên lửa lớn đến khi thật nóng rồi dùng cọ phết 10 ml dầu ô liu còn lại lên bề mặt vỉ để chống dính.', NULL, NULL),
('imp-c398c169dc196c4e_v4_step_5', 'imp-c398c169dc196c4e', 5, 'cook', 'Nướng tôm nhanh trên lửa lớn hai mặt', 'Xếp đều tôm lên vỉ hoặc chảo nóng, nướng mỗi mặt khoảng 3–4 phút trên lửa lớn đến khi vỏ tôm chuyển màu cam hồng rực, hơi xém cạnh thơm lừng, phần thịt bên trong chuyển trắng đục hoàn toàn và thân tôm uốn cong hình chữ C.', 'Tránh nướng quá lâu đến khi thân tôm cuộn tròn thành hình chữ O vì lúc đó thịt tôm đã quá chín và bị dai xác.', 7),
('imp-c398c169dc196c4e_v4_step_6', 'imp-c398c169dc196c4e', 6, 'finish', 'Rưới sốt chanh tỏi sạch và dọn nóng', 'Gắp tôm ra đĩa rộng khi còn nóng hổi, rưới đều chén sốt dầu ô liu chanh tỏi sạch đã trích riêng lên trên, rắc nốt 4 g ngò tây băm cùng vài múi chanh vàng tươi bên cạnh và dùng ngay.', NULL, NULL),
('imp-8fcc592ab7250a38_v4_step_1', 'imp-8fcc592ab7250a38', 1, 'prep', 'Thái sợi bắp cải và chuẩn bị hành tỏi', 'Tách bỏ lớp lá già bên ngoài của 1 bắp cải tươi, bổ tư theo chiều dọc rồi cắt bỏ phần lõi cứng, sau đó thái ngang thành sợi dày khoảng 1 cm, rửa sạch và vẩy ráo. Thái hạt lựu nhỏ 3/4 củ hành tây, bóc vỏ và đập dập nhẹ 2 tép tỏi khô.', NULL, NULL),
('imp-8fcc592ab7250a38_v4_step_2', 'imp-8fcc592ab7250a38', 2, 'cook', 'Phi thơm hành tây và tỏi với dầu ô liu', 'Làm nóng 45 ml dầu ô liu trong chảo sâu lòng hoặc nồi đế dày trên lửa vừa. Cho hành tây thái nhỏ vào xào 4 phút đến khi mềm trong, tiếp tục thả tỏi đập dập vào đảo thêm 1 phút cho dậy mùi thơm dịu rồi gắp bỏ xác tỏi ra ngoài.', 'Vớt bỏ tép tỏi ngay khi vừa thơm giúp món om có hương tỏi thoang thoảng dễ chịu mà không bị đắng nếu tỏi quá lửa.', 5),
('imp-8fcc592ab7250a38_v4_step_3', 'imp-8fcc592ab7250a38', 3, 'cook', 'Xào xẹp bắp cải với muối và tiêu', 'Cho toàn bộ bắp cải thái sợi vào nồi, nêm 6 g muối ăn và 1,5 g tiêu đen xay. Xào mở nắp trên lửa vừa khoảng 4–5 phút, đảo đều tay để từng sợi cải thấm lớp dầu thơm và bắt đầu xẹp bớt thể tích.', NULL, 5),
('imp-8fcc592ab7250a38_v4_step_4', 'imp-8fcc592ab7250a38', 4, 'sauce', 'Đảo quyện cùng cà chua nghiền đóng hộp', 'Đổ 300 g cà chua nghiền đóng hộp Ý vào nồi bắp cải, đảo đều tay và đun mở nắp trong 3 phút để nước sốt cà chua hơi cô lại và bám đều lên từng sợi cải.', 'Đun mở nắp cùng cà chua nghiền trong vài phút đầu giúp sốt cô lại và bám đều lên từng sợi bắp cải trước khi om.', 3),
('imp-8fcc592ab7250a38_v4_step_5', 'imp-8fcc592ab7250a38', 5, 'cook', 'Om nhỏ lửa đến khi bắp cải chín mềm ngọt', 'Rót 200 ml nước dùng rau củ vào xấp mặt cải, đậy kín nắp, hạ lửa nhỏ và om liu riu trong khoảng 20–22 phút đến khi bắp cải chín mềm ngọt hoàn toàn.', 'Nếu thích sợi bắp cải còn giữ chút độ giòn nhẹ có thể rút ngắn thời gian om xuống khoảng 15 phút.', 20),
('imp-8fcc592ab7250a38_v4_step_6', 'imp-8fcc592ab7250a38', 6, 'finish', 'Cô sánh sốt và dọn nóng', 'Mở nắp kiểm tra độ mềm của bắp cải; nếu nước còn loãng, bật lửa lớn đun thêm 2–3 phút cho nước sốt sánh bóng quyện vào cải. Nêm nếm lại vừa miệng rồi trút ra đĩa dùng nóng.', NULL, NULL),
('imp-da0c2dea539000e5_v4_step_1', 'imp-da0c2dea539000e5', 1, 'prep', 'Lau sạch nấm đùi gà và sơ chế ngò tây, tỏi', 'Dùng khăn ẩm lau sạch 300 g nấm đùi gà tươi (không ngâm ngập nước để nấm không hút ẩm), cắt bỏ phần gốc già và thái lát dày 0,5 cm. Rửa sạch 15 g ngò tây tươi, thấm khô và băm nhỏ; bóc vỏ băm nhuyễn 2 tép tỏi khô.', NULL, NULL),
('imp-da0c2dea539000e5_v4_step_2', 'imp-da0c2dea539000e5', 2, 'cook', 'Xào chín vàng nấm đùi gà và để nguội bớt', 'Đun nóng 15 ml dầu ô liu trong chảo chống dính đường kính khoảng 24 cm trên lửa vừa, cho tỏi băm và 0,5 g ớt vảy khô vào đảo nhanh 30 giây cho thơm. Tăng lên lửa lớn, thả nấm đùi gà vào xào mở nắp khoảng 6 phút cùng 1 g muối ăn đến khi nấm ra hết nước và xém vàng cạnh; trút nấm ra đĩa để nguội bớt 3 phút.', 'Xào nấm mở nắp ở lửa lớn và để nấm nguội bớt trước khi trộn vào trứng giúp nấm không tiết nước làm loãng trứng và không làm trứng bị chín vón cục.', 7),
('imp-da0c2dea539000e5_v4_step_3', 'imp-da0c2dea539000e5', 3, 'prep', 'Đánh tan trứng gà với phô mai Parmesan', 'Đập 6 quả trứng gà tươi vào tô lớn, thêm 40 g phô mai Parmesan bào mịn, 2 g muối ăn và 1 g tiêu đen xay. Dùng phới lồng đánh đều cho lòng đỏ, lòng trắng và phô mai hòa quyện hoàn toàn, sau đó trút phần nấm đùi gà xào đã nguội bớt vào trộn đều.', 'Phô mai Parmesan vốn có vị mặn đậm nên chỉ cần nêm lượng muối vừa phải để tránh món trứng bị gắt mặn.', NULL),
('imp-da0c2dea539000e5_v4_step_4', 'imp-da0c2dea539000e5', 4, 'cook', 'Đổ hỗn hợp trứng và gom mép chín đều', 'Lau sạch chảo, thêm 15 ml dầu ô liu còn lại đun nóng nhẹ trên lửa nhỏ. Rót hỗn hợp trứng nấm vào chảo, rắc 2/3 phần ngò tây băm lên mặt. Để yên 1 phút cho đáy se lại rồi dùng phới silicon kéo nhẹ trứng từ mép vào giữa để phần trứng lỏng chảy xuống đáy, lặp lại thao tác này trong khoảng 4 phút đến khi phần đáy và viền thành hình.', 'Thao tác gom mép trứng từ ngoài vào giữa trong vài phút đầu giúp khối trứng chín đều từ đáy lên mà không bị khô cứng.', 5),
('imp-da0c2dea539000e5_v4_step_5', 'imp-da0c2dea539000e5', 5, 'cook', 'Đậy nắp om nhỏ lửa cho trứng chín mặt trên', 'Đậy nắp vung kín chảo, hạ lửa thật nhỏ và nấu thêm khoảng 8 phút đến khi toàn bộ khối trứng phồng nhẹ, bề mặt trên se chín đặc lại chỉ còn hơi ẩm nhẹ ở tâm.', NULL, 8),
('imp-da0c2dea539000e5_v4_step_6', 'imp-da0c2dea539000e5', 6, 'finish', 'Lật áp chảo mặt trên và cắt múi tam giác', 'Úp một chiếc đĩa phẳng rộng lên miệng chảo, lật dứt khoát ổ Frittata ra đĩa rồi trượt nhẹ trở lại chảo áp mặt còn lại thêm 2 phút trên lửa nhỏ cho vàng đều cả hai mặt. Trút ra thớt hoặc đĩa lớn, rắc nốt phần ngò tây tươi còn lại, nghỉ 2 phút rồi cắt thành 6 miếng tam giác dùng nóng hoặc ấm.', NULL, NULL),
('imp-e427b91ce9f574c3_v4_step_1', 'imp-e427b91ce9f574c3', 1, 'prep', 'Lau sạch và phân chia nấm đùi gà, rau thơm', 'Dùng khăn ẩm lau sạch 400 g nấm đùi gà tươi (tránh rửa ngập nước), cắt bỏ phần gốc già. Chọn 2 cây nấm đẹp thái dọc thành các lát mỏng khoảng 0,4 cm để riêng làm phần trang trí, phần nấm còn lại thái miếng vuông vừa. Thái hạt lựu nhỏ 1 củ hành tây, bóc vỏ 2 tép tỏi khô và băm nhỏ 10 g ngò tây tươi.', NULL, NULL),
('imp-e427b91ce9f574c3_v4_step_2', 'imp-e427b91ce9f574c3', 2, 'cook', 'Xào thơm nấm đùi gà cùng tỏi và hành tây', 'Đun nóng 25 ml dầu ô liu trong chảo lớn ở lửa vừa, cho tỏi khô nguyên tép và phần nấm thái miếng vuông vào cùng 2 g muối ăn, xào mở nắp khoảng 8–10 phút đến khi nấm ra nước và hơi vàng thơm. Gắp bỏ tép tỏi để súp không bị hăng, tiếp tục cho hành tây vào đảo thêm 3–4 phút cho hành mềm trong.', 'Vớt bỏ tép tỏi trước khi xay súp giúp giữ trọn hương thơm dịu mà không bị mùi hăng nồng lấn át vị ngọt thanh của nấm.', 12),
('imp-e427b91ce9f574c3_v4_step_3', 'imp-e427b91ce9f574c3', 3, 'sauce', 'Nấu nền sốt sữa bơ bột mì', 'Trong nồi súp chính trên lửa nhỏ, đun chảy 30 g bơ lạt, trút 30 g bột mì đa dụng vào khuấy đều liên tục 2 phút cho bột chín thơm màu vàng nhạt. Rót từ từ 250 ml sữa tươi không đường vào nồi, vừa rót vừa đánh liên tục bằng phới lồng đến khi sốt sôi nhẹ và sánh mịn không vón cục.', 'Rót sữa tươi từ từ từng chút một và khuấy đều tay ngay từ đầu là bí quyết giúp nền bột mì tan mượt hoàn toàn không vón cục.', 5),
('imp-e427b91ce9f574c3_v4_step_4', 'imp-e427b91ce9f574c3', 4, 'cook', 'Ninh súp nấm với nước dùng rau củ và xay nhuyễn', 'Trút toàn bộ nấm và hành tây đã xào vào nồi sốt sữa, đổ thêm 500 ml nước dùng rau củ, 3 g muối ăn và 1 g tiêu đen xay. Hạ lửa nhỏ ninh liu riu khoảng 12 phút cho nấm chín mềm ngọt, sau đó dùng máy xay cầm tay xay thật nhuyễn mịn ngay trong nồi. Rót thêm 100 ml kem tươi nấu ăn vào khuấy đều, giữ ấm trên lửa thật nhỏ mà không để sôi bùng.', 'Nếu thích súp loãng nhẹ hơn có thể pha thêm chút nước dùng rau củ nóng, đồng thời không đun sôi sau khi cho kem tươi để giữ kết cấu súp mượt mà.', 12),
('imp-e427b91ce9f574c3_v4_step_5', 'imp-e427b91ce9f574c3', 5, 'cook', 'Áp chảo lát nấm trang trí và nướng giòn bánh mì', 'Làm nóng 10 ml dầu ô liu còn lại trên chảo nhỏ, xếp các lát nấm mỏng để riêng vào áp chảo mỗi mặt 1–2 phút cho vàng thơm, rắc 1 g muối ăn, 0,5 g tiêu đen xay và một nửa lượng ngò tây băm (5 g). Đồng thời nướng giòn hoặc áp chảo vàng 4 lát bánh mì hai mặt để ăn kèm.', NULL, NULL),
('imp-e427b91ce9f574c3_v4_step_6', 'imp-e427b91ce9f574c3', 6, 'finish', 'Múc súp nóng và trang trí hoàn thiện', 'Múc súp nấm kem nóng hổi ra 4 bát sâu lòng, xếp các lát nấm áp chảo lên trên mặt, rắc nốt 5 g ngò tây tươi băm còn lại rồi dọn ngay cùng bánh mì nướng giòn.', NULL, NULL),
('imp-f3eb85959cb62d3e_v4_step_1', 'imp-f3eb85959cb62d3e', 1, 'prep', 'Sơ chế rau củ thái hạt lựu và ức gà', 'Gọt vỏ cà rốt và khoai tây rồi thái hạt lựu đều cỡ 1,5 cm (ngâm khoai tây vào nước lạnh cho khỏi thâm rồi vớt ráo). Băm nhỏ hành tây, thái lát mỏng cần tây, băm nhuyễn tỏi khô và thái nhỏ 12 g ngò tây tươi. Rửa sạch 500 g ức gà phi lê dưới vòi nước lạnh.', 'Thái cà rốt và khoai tây kích thước đồng đều giúp hai loại củ chín mềm cùng lúc mà không bị nát.', NULL),
('imp-f3eb85959cb62d3e_v4_step_2', 'imp-f3eb85959cb62d3e', 2, 'cook', 'Luộc ức gà lấy nước dùng trong ngọt', 'Đặt 500 g ức gà vào nồi cùng 2 lá nguyệt quế khô và 4 g muối ăn, đổ 1000 ml nước lọc lạnh ngập gà rồi đun sôi. Khi nước sôi, hớt sạch bọt nổi để nước dùng thật trong, hạ lửa nhỏ đậy nắp và luộc liu riu 20 phút cho thịt gà chín mềm hoàn toàn.', 'Bắt đầu luộc gà từ nước lạnh và hớt bọt kỹ giúp chất ngọt từ thịt tiết ra từ từ và nồi nước dùng trong veo.', 20),
('imp-f3eb85959cb62d3e_v4_step_3', 'imp-f3eb85959cb62d3e', 3, 'cook', 'Xào thơm rau củ nền với dầu ô liu', 'Trong lúc chờ gà chín, làm nóng 40 ml dầu ô liu trong nồi súp lớn ở lửa vừa. Cho hành tây băm vào xào 2 phút cho trong, sau đó thêm cà rốt, cần tây và tỏi băm vào đảo đều tay thêm 5 phút cho rau củ dậy mùi thơm và hơi dịu mềm.', NULL, 7),
('imp-f3eb85959cb62d3e_v4_step_4', 'imp-f3eb85959cb62d3e', 4, 'prep', 'Lọc nước dùng và xé nhỏ thịt ức gà', 'Vớt ức gà ra đĩa để nguội bớt rồi dùng tay xé sợi hoặc cắt miếng nhỏ vừa ăn. Lọc toàn bộ phần nước luộc gà qua rây mịn để loại bỏ cặn bọt và lá nguyệt quế.', NULL, NULL),
('imp-f3eb85959cb62d3e_v4_step_5', 'imp-f3eb85959cb62d3e', 5, 'cook', 'Ninh mềm khoai tây, cà rốt và thịt gà', 'Rót phần nước luộc gà đã lọc cùng 500 ml nước lọc còn lại vào nồi rau củ đã xào. Thêm khoai tây cắt hạt lựu, 15 g cà chua cô đặc, 4 g muối ăn còn lại và 1,5 g tiêu đen xay. Đun sôi nhẹ rồi hạ lửa nhỏ đậy nắp nấu 18 phút đến khi khoai tây và cà rốt chín bùi, sau đó thả thịt gà xé vào nấu thêm 5 phút cho hòa vị.', 'Thả thịt gà xé vào ở 5 phút cuối giúp thịt thấm vị súp rau củ mà vẫn giữ được độ mềm ngọt, không bị bã xơ.', 23),
('imp-f3eb85959cb62d3e_v4_step_6', 'imp-f3eb85959cb62d3e', 6, 'finish', 'Nêm lại và múc súp nóng rắc ngò tây', 'Nêm nếm lại muối và tiêu đen cho vừa khẩu vị gia đình, múc súp ra 4 tô sâu lòng khi còn nóng hổi rồi rắc ngò tây tươi thái nhỏ cùng 0,5 g tiêu đen xay lên mặt trước khi thưởng thức.', NULL, NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_1', 'imp-f4c5afa7ccc2a9ed', 1, 'prep', 'Làm nóng lò, khoét ruột và làm ráo cà chua', 'Bật lò nướng làm nóng trước ở 180°C chế độ hai lửa trên-dưới và phết 15 ml dầu ô liu đều xuống đáy khay nướng. Rửa sạch 6 quả cà chua chín to chắc tay, lau khô, cắt ngang phần chóp trên làm nắp đậy. Dùng thìa nhỏ cẩn thận nạo sạch ruột cà chua ra bát riêng sao cho không làm rách vỏ. Rắc 2 g muối ăn vào lòng từng quả cà chua rồi úp ngược xuống rổ 10 phút để chảy bớt nước.', 'Rắc chút muối và úp ngược vỏ cà chua trong 10 phút giúp rút bớt lượng nước thừa, giữ thành quả cà chua chắc chắn và nhân thịt không bị nhão khi nướng.', 10),
('imp-f4c5afa7ccc2a9ed_v4_step_2', 'imp-f4c5afa7ccc2a9ed', 2, 'prep', 'Băm nhỏ nguyên liệu thơm và phần ruột cà chua', 'Bóc vỏ băm thật nhuyễn 2–3 tép tỏi khô và băm nhuyễn 15 g ngò tây tươi. Chắt bỏ bớt hạt và nước loãng trong bát ruột cà chua, cắt nhỏ phần thịt ruột cà chua để trộn nhân.', NULL, NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_3', 'imp-f4c5afa7ccc2a9ed', 3, 'prep', 'Trộn nhân thịt heo xay cùng phô mai và gia vị', 'Cho 300 g thịt heo xay vào tô lớn cùng 1 quả trứng gà, 50 g bột chiên xù, 25 g phô mai Parmesan bào mịn, tỏi băm, ngò tây băm, phần ruột cà chua cắt nhỏ, 4 g muối ăn còn lại và 1,5 g tiêu đen xay. Trộn thật đều tay đến khi hỗn hợp nhân thịt hòa quyện dẻo mịn.', 'Trộn phần ruột cà chua cùng bột chiên xù giúp nhân giữ được độ mọng ẩm tự nhiên suốt quá trình nướng lò mà không bị khô cứng.', NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_4', 'imp-f4c5afa7ccc2a9ed', 4, 'cook', 'Nhồi nhân vào cà chua và xếp lên khay', 'Dùng giấy thấm khô bên trong lòng 6 quả cà chua đã ráo nước. Múc nhân thịt nhồi đầy vào từng quả (chỉ ấn nhẹ vừa tay, không nén quá chặt để nhân còn độ nở tơi), rắc nốt 15 g phô mai Parmesan bào mịn lên mặt nhân rồi đậy nắp cà chua lên trên. Xếp đứng gọn các quả vào khay nướng đã phết dầu và rưới đều 25 ml dầu ô liu còn lại lên bề mặt.', NULL, NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_5', 'imp-f4c5afa7ccc2a9ed', 5, 'cook', 'Nướng cà chua ở 180°C đến khi nhân chín hẳn', 'Đặt khay vào ngăn giữa lò nướng ở 180°C trong khoảng 30–35 phút đến khi thịt heo bên trong chín hoàn toàn (xiên tăm vào tâm nhân thấy nước chảy ra trong, không còn màu hồng), vỏ cà chua mềm nhăn nhẹ mà vẫn giữ nguyên dáng và phô mai hơi xém vàng.', 'Nếu phần nắp cà chua có dấu hiệu sậm màu nhanh ở 10 phút cuối, có thể phủ hờ một tờ giấy bạc lên trên để nhân bên trong chín kỹ hoàn toàn.', 35),
('imp-f4c5afa7ccc2a9ed_v4_step_6', 'imp-f4c5afa7ccc2a9ed', 6, 'finish', 'Để nghỉ định hình và trình bày ra đĩa', 'Lấy khay cà chua ra khỏi lò và để nghỉ 5 phút cho phần nhân ổn định kết cấu. Chuyển cà chua ra đĩa sâu lòng, rưới phần nước sốt tiết ra dưới đáy khay, trang trí thêm vài lá húng quế Tây tươi lên trên và dùng nóng hoặc ấm.', NULL, NULL),
('imp-0d54a1288223d8ac_v4_step_1', 'imp-0d54a1288223d8ac', 1, 'prep', 'Làm nóng lò và thấm khô đùi gà', 'Làm nóng lò nướng ở 200°C trước 15 phút và lót giấy nến lên khay nướng. Rửa sạch 900 g đùi gà dưới vòi nước lạnh, sau đó dùng khăn giấy thấm thật khô cả mặt da lẫn mặt thịt để khi nướng da lên màu vàng giòn đều.', 'Da gà càng ráo nước thì khi gặp nhiệt cao càng nhanh giòn rụm và không bị ra nước hấp hơi.', NULL),
('imp-0d54a1288223d8ac_v4_step_2', 'imp-0d54a1288223d8ac', 2, 'marinate', 'Xát hỗn hợp gia vị khô lên thịt gà', 'Trộn đều 3 g bột tỏi, 3 g ớt bột paprika ngọt, 2 g thảo mộc Ý khô, 6 g muối ăn và 2 g tiêu đen xay trong chén nhỏ. Xát đều hỗn hợp gia vị này lên cả hai mặt của từng chiếc đùi gà, ấn nhẹ để gia vị bám chắc vào da và thịt.', NULL, NULL),
('imp-0d54a1288223d8ac_v4_step_3', 'imp-0d54a1288223d8ac', 3, 'sauce', 'Đun chảy bơ lạt và phi thơm tỏi tươi', 'Đặt chảo nhỏ lên lửa nhỏ, cho 45 g bơ lạt vào đun tan chảy hoàn toàn rồi cho toàn bộ tỏi tươi băm nhuyễn vào đảo nhanh tay khoảng 45 giây đến khi dậy mùi thơm dịu thì tắt bếp ngay, giữ cho tỏi không bị chuyển nâu.', 'Chỉ đun tỏi vừa dậy hương trên lửa nhỏ rồi nhấc chảo ra khỏi bếp để tỏi không bị cháy đắng khi vào lò nướng.', 1),
('imp-0d54a1288223d8ac_v4_step_4', 'imp-0d54a1288223d8ac', 4, 'marinate', 'Phết sốt bơ tỏi và xếp gà lên khay', 'Xếp các miếng đùi gà lên khay nướng đã lót giấy nến sao cho mặt da hướng lên trên và các miếng cách nhau khoảng 2 cm. Dùng cọ phết đều phần lớn hỗn hợp bơ tỏi lên mặt gà, phần bơ còn lại rưới nhẹ quanh khay để thịt luôn ẩm mềm.', NULL, NULL),
('imp-0d54a1288223d8ac_v4_step_5', 'imp-0d54a1288223d8ac', 5, 'cook', 'Nướng gà ở 200°C và rưới bơ giữa chừng', 'Đưa khay gà vào rãnh giữa của lò nướng ở 200°C trong 35 phút. Đến phút thứ 20, mở lò kéo nhẹ khay ra và dùng muỗng múc phần nước bơ tỏi chảy ra dưới khay rưới đều lại một lượt lên mặt da gà rồi nướng tiếp.', NULL, 35),
('imp-0d54a1288223d8ac_v4_step_6', 'imp-0d54a1288223d8ac', 6, 'cook', 'Tăng nhiệt làm giòn da và kiểm tra độ chín', 'Tăng nhiệt lò lên 220°C hoặc bật chế độ lửa trên nướng thêm 4–5 phút đến khi da gà vàng giòn và hơi xém cạnh đẹp mắt. Dùng que xiên vào phần thịt sát xương không thấy nước hồng chảy ra (nhiệt độ lõi đạt ít nhất 75°C) là gà chín hoàn toàn.', 'Quan sát kỹ 2 phút cuối khi bật lửa trên vì gia vị paprika và tỏi có thể sậm màu nhanh ở nhiệt cao.', 5),
('imp-0d54a1288223d8ac_v4_step_7', 'imp-0d54a1288223d8ac', 7, 'finish', 'Nghỉ thịt, rắc ngò tây và dọn nóng', 'Lấy khay gà ra khỏi lò, để thịt nghỉ 5 phút cho nước ngọt ổn định bên trong thớ thịt. Xếp đùi gà ra đĩa, rưới thêm nước sốt bơ tỏi từ khay và rắc ngò tây tươi thái nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-70e5e19dd4073b76_v4_step_1', 'imp-70e5e19dd4073b76', 1, 'prep', 'Thái khối thịt bò và áo lớp bột mỏng', 'Thấm thật khô 1,1 kg thịt bò bằng khăn giấy rồi cắt thành các khối vuông đều cỡ 3,5–4 cm. Cho thịt vào tô lớn, rắc đều 35 g bột mì đa dụng, xóc nhẹ cho bột phủ một lớp mỏng rồi giũ bớt phần bột thừa ra ngoài.', 'Chỉ áo lớp bột rất mỏng và giũ sạch phần dư để nước sốt hầm sánh mịn tự nhiên mà không bị lợn cợn vón cục.', NULL),
('imp-70e5e19dd4073b76_v4_step_2', 'imp-70e5e19dd4073b76', 2, 'prep', 'Chuẩn bị nền rau củ và đun nóng nước dùng', 'Băm hạt lựu nhỏ hành tây vàng, cà rốt tươi và cần tây tươi để làm nền rau củ kiểu Ý. Đồng thời đặt 1 lít nước dùng bò lên một bếp khác đun nóng già và giữ ấm trên lửa nhỏ.', 'Luôn dùng nước dùng thật nóng khi châm vào thịt đang áp chảo để thớ bò không bị co cứng do sốc nhiệt.', NULL),
('imp-70e5e19dd4073b76_v4_step_3', 'imp-70e5e19dd4073b76', 3, 'cook', 'Xào thơm nền rau củ với bơ và dầu ô liu', 'Đặt nồi gang hoặc nồi đáy dày lên lửa vừa, cho 40 ml dầu ô liu nguyên chất và 35 g bơ lạt vào đun chảy. Thả hành tây, cà rốt và cần tây vào xào khoảng 5 phút đến khi rau củ mềm dịu và dậy mùi ngọt thơm.', NULL, 5),
('imp-70e5e19dd4073b76_v4_step_4', 'imp-70e5e19dd4073b76', 4, 'cook', 'Áp chảo xém vàng đều các khối thịt bò', 'Tăng lên lửa vừa-lớn, cho thịt bò đã áo bột vào nồi cùng rau củ (chia 2 mẻ nếu đáy nồi nhỏ) và áp chảo khoảng 8 phút đến khi các mặt thịt chuyển màu nâu vàng đẹp mắt. Thêm 3 g thảo mộc Ý khô vào đảo đều 30 giây cho dậy hương.', NULL, 8),
('imp-70e5e19dd4073b76_v4_step_5', 'imp-70e5e19dd4073b76', 5, 'cook', 'Khử cặn đáy nồi với rượu vang đỏ', 'Vặn lửa lớn, rót 150 ml rượu vang đỏ nấu ăn vào nồi. Dùng muỗng gỗ cạo nhẹ toàn bộ phần cháy xém thơm ngon bám ở đáy nồi hòa tan vào rượu, đun sôi khoảng 3 phút cho mùi cồn bay hơi hoàn toàn.', NULL, 3),
('imp-70e5e19dd4073b76_v4_step_6', 'imp-70e5e19dd4073b76', 6, 'cook', 'Thêm cà chua nghiền và hầm liu riu 90 phút', 'Đổ 300 g cà chua nghiền nhuyễn (passata) vào nồi, khuấy đều rồi rót tiếp 1 lít nước dùng bò nóng vào ngập mặt thịt. Nêm 8 g muối ăn và 3 g tiêu đen xay, đậy nắp kín, hạ xuống lửa thật nhỏ và hầm liu riu ít nhất 90 phút đến khi thịt bò mềm tơi, dùng nĩa xiên qua dễ dàng.', 'Thỉnh thoảng mở nắp đảo nhẹ đáy nồi và châm thêm chút nước nóng nếu thấy sốt cạn quá nhanh trước khi thịt kịp mềm.', 90),
('imp-70e5e19dd4073b76_v4_step_7', 'imp-70e5e19dd4073b76', 7, 'finish', 'Cô sánh sốt và hoàn thiện món bò hầm', 'Mở nắp kiểm tra: nếu nước sốt còn hơi loãng, vặn lửa vừa-lớn đun thêm 5–8 phút không đậy nắp để sốt rút bớt và sánh bóng lại. Nếm lại gia vị cho vừa miệng, tắt bếp rồi múc bò hầm nóng ra đĩa sâu lòng để thưởng thức.', NULL, NULL),
('imp-500ffbf4fd05f9da_v4_step_1', 'imp-500ffbf4fd05f9da', 1, 'prep', 'Sơ chế mực ống và rau thơm', 'Làm sạch kỹ 450 g mực ống tươi, rút bỏ túi mực, mai và phần răng cứng ở gốc râu rồi rửa sạch, cắt thân thành khoanh dày 1 cm và thấm thật khô bằng khăn giấy. Cà chua bi bổ đôi, tỏi tươi băm nhỏ, ớt tươi thái lát, 15 g ngò tây tươi thái nhỏ và hẹ lá cắt khúc ngắn.', 'Mực được thấm ráo nước trước khi vào chảo nóng sẽ xém cạnh thơm lừng thay vì tiết nước bị luộc dai.', NULL),
('imp-500ffbf4fd05f9da_v4_step_2', 'imp-500ffbf4fd05f9da', 2, 'cook', 'Áp chảo nhanh mực ống trên lửa lớn', 'Làm nóng chảo sâu lòng với 30 ml dầu ô liu nguyên chất trên lửa lớn đến khi dầu thật nóng. Thả mực vào áp chảo nhanh khoảng 4–5 phút, đảo vài lần cho đến khi mực săn cong và hơi xém vàng ở viền.', NULL, 5),
('imp-500ffbf4fd05f9da_v4_step_3', 'imp-500ffbf4fd05f9da', 3, 'cook', 'Phi tỏi ớt và om mực cùng cà chua bi', 'Hạ xuống lửa vừa, cho tỏi băm và ớt tươi vào đảo thơm 30 giây, sau đó thêm cà chua bi bổ đôi và rót 60 ml rượu vang trắng khô vào, cạo nhẹ đáy chảo cho tan phần cháy thơm. Nêm 3 g muối ăn và 1 g tiêu đen xay, đậy nắp om trên lửa nhỏ khoảng 15 phút đến khi cà chua nát quyện thành sốt đỏ sánh và mực chín mềm.', 'Mực cần được om đủ thời gian trên lửa liu riu để thớ thịt chuyển từ dai sang mềm ngọt và hòa quyện với nước cà chua.', 15),
('imp-500ffbf4fd05f9da_v4_step_4', 'imp-500ffbf4fd05f9da', 4, 'cook', 'Luộc mì Ý al dente song song khi om sốt', 'Trong lúc om sốt mực ở những phút cuối, đun sôi 2 lít nước lọc với 7 g muối ăn trong nồi lớn. Thả 320 g mì Ý spaghetti vào luộc khoảng 8–9 phút (ít hơn hướng dẫn bao bì 1 phút) đến độ chín dai vừa phải, giữ lại khoảng 100 ml nước luộc mì trước khi vớt mì ra.', NULL, 9),
('imp-500ffbf4fd05f9da_v4_step_5', 'imp-500ffbf4fd05f9da', 5, 'cook', 'Trộn hẹ, ngò tây và xóc mì quyện sốt', 'Mở nắp chảo sốt mực, cho phần lớn hẹ lá tươi và một nửa lượng ngò tây tươi vào đảo 1 phút cho vừa héo dậy mùi. Đổ mì Ý đã ráo vào chảo, thêm 15 ml dầu ô liu nguyên chất còn lại cùng từng muỗng nước luộc mì và xóc đều trên lửa lớn 1 phút để sốt bám bóng từng sợi mì.', 'Tinh bột trong nước luộc mì giúp kết dính dầu ô liu và nước cà chua thành lớp sốt mượt bám đều lên sợi spaghetti.', 2),
('imp-500ffbf4fd05f9da_v4_step_6', 'imp-500ffbf4fd05f9da', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Chia mì mực sốt cà chua ra 4 đĩa sâu lòng, rưới phần sốt mực còn lại lên trên mặt mì. Rắc nốt phần ngò tây tươi, hẹ lá tươi và 1 g tiêu đen xay còn lại rồi dọn thưởng thức ngay khi còn nóng hổi.', NULL, NULL),
('imp-ebc8bf739393ac91_v4_step_1', 'imp-ebc8bf739393ac91', 1, 'prep', 'Sơ chế tôm tươi, đậu phụ và cà chua', 'Bóc vỏ, bỏ đầu và rút sạch chỉ đen lưng 250 g tôm tươi, rửa sạch để ráo rồi cắt làm đôi theo chiều ngang (hoặc giã dập nhẹ 1/3 lượng tôm để nước ngọt hơn). Ướp tôm với 5 ml nước mắm, 2 g hạt nêm, 0,5 g tiêu đen xay và đầu hành lá băm nhỏ trong 10 phút. Cắt khối vuông 2 cm 2 bìa đậu phụ trắng; bổ múi cau 2 quả cà chua và băm nhỏ 1 quả.', NULL, 10),
('imp-ebc8bf739393ac91_v4_step_2', 'imp-ebc8bf739393ac91', 2, 'prep', 'Chuẩn bị gừng, hành lá và ngò rí', 'Cạo vỏ 10 g gừng tươi rồi thái sợi thật mảnh. Rửa sạch phần lá xanh hành lá và 10 g ngò rí, để ráo rồi thái khúc ngắn 1,5 cm.', NULL, NULL),
('imp-ebc8bf739393ac91_v4_step_3', 'imp-ebc8bf739393ac91', 3, 'cook', 'Phi thơm gừng hành và xào cà chua tạo màu', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn, cho gừng thái sợi vào đảo 20 giây cho thơm rồi trút phần cà chua băm nhỏ cùng 1 g muối ăn vào xào đều 3 phút đến khi cà chua nhuyễn mềm ra màu đỏ cam đẹp.', 'Xào cà chua với chút muối trước khi cho tôm vào giúp tạo nền màu óng đẹp và giảm độ chua gắt của cà chua sống.', 3),
('imp-ebc8bf739393ac91_v4_step_4', 'imp-ebc8bf739393ac91', 4, 'cook', 'Xào săn tôm tươi và nấu sôi nước canh', 'Cho tôm đã ướp vào nồi đảo nhanh 1–2 phút đến khi tôm chuyển màu đỏ cam săn lại, sau đó đổ 1300 ml nước lọc vào đun lửa lớn đến khi sôi bùng rồi dùng vá hớt sạch bọt nổi để nước canh trong.', NULL, 3),
('imp-ebc8bf739393ac91_v4_step_5', 'imp-ebc8bf739393ac91', 5, 'cook', 'Thả đậu phụ và nêm gia vị thanh ngọt', 'Hạ xuống lửa vừa để nước sôi lăn tăn, trượt nhẹ 2 bìa đậu phụ cắt khối cùng 2 quả cà chua bổ múi cau vào nồi nấu khoảng 4 phút cho đậu phụ nóng mềm thấm vị và tôm chín chắc hoàn toàn. Nêm 15 ml nước mắm ngon, 3 g hạt nêm và 3 g muối ăn còn lại cho vừa khẩu vị.', 'Không khuấy mạnh sau khi đã thả đậu phụ vào nồi để các khối đậu trắng giữ nguyên hình dáng vuông đẹp.', 4),
('imp-ebc8bf739393ac91_v4_step_6', 'imp-ebc8bf739393ac91', 6, 'finish', 'Thêm hành ngò và tiêu xay hoàn thiện', 'Khi cà chua múi cau vừa mềm chín tới, tắt bếp và thả hành lá, ngò rí thái khúc vào lắc nhẹ nồi. Múc canh ra tô lớn, rắc 0,5 g tiêu đen xay lên trên rồi thưởng thức nóng cùng cơm trắng.', 'Thả hành ngò ngay lúc vừa tắt bếp sẽ giữ được màu xanh mướt và mùi thơm tươi mới cho bát canh.', NULL),
('imp-3446b3924b05eb7b_v4_step_1', 'imp-3446b3924b05eb7b', 1, 'prep', 'Thái lát mỏng và ướp thịt bò thăn', 'Thấm khô 300 g thịt bò thăn, thái lát mỏng ngang thớ để khi nấu thịt mềm dễ ăn. Ướp bò với 1/2 lượng tỏi khô băm, đầu hành lá băm nhỏ, 2 g hạt nêm, 2 g muối ăn, 1 g tiêu đen xay và 5 ml dầu ăn trong 15 phút.', 'Thái thịt bò ngang thớ thật mỏng và ướp thêm 1 muỗng cà phê dầu ăn sẽ giữ từng lát thịt mềm ngọt sau khi trụng nước sôi.', 15),
('imp-3446b3924b05eb7b_v4_step_2', 'imp-3446b3924b05eb7b', 2, 'prep', 'Sơ chế cà rốt, bắp cải và hành lá', 'Gọt vỏ 1 củ cà rốt, rửa sạch rồi thái khoanh tròn dày 0,4 cm cho nhanh chín. Tách lá 1/2 bắp cải trắng, rửa sạch và cắt miếng vuông 4 cm. Rửa sạch phần lá xanh hành lá rồi cắt khúc dài 2 cm.', NULL, NULL),
('imp-3446b3924b05eb7b_v4_step_3', 'imp-3446b3924b05eb7b', 3, 'cook', 'Phi thơm tỏi và xào tái thịt bò', 'Làm nóng nồi trên lửa lớn vừa với 10 ml dầu ăn còn lại, phi thơm phần tỏi băm còn lại trong 30 giây. Cho thịt bò đã ướp vào đảo nhanh 1 phút đến khi thịt săn nhẹ và vừa chuyển tái thì trút ngay ra đĩa riêng.', NULL, 1),
('imp-3446b3924b05eb7b_v4_step_4', 'imp-3446b3924b05eb7b', 4, 'cook', 'Nấu chín cà rốt và bắp cải lấy nước ngọt', 'Đổ 1400 ml nước lọc vào nồi vừa xào thịt, bật lửa lớn đun sôi bùng rồi hớt bọt. Thả cà rốt thái khoanh vào nấu 5 phút trên lửa vừa, tiếp theo cho toàn bộ bắp cải vào nấu thêm 5 phút đến khi cả hai loại rau củ chín mềm ngọt.', 'Cho cà rốt vào nấu trước bắp cải 5 phút để hai loại rau củ chín đồng đều cùng lúc mà bắp cải không bị nhũn nát.', 10),
('imp-3446b3924b05eb7b_v4_step_5', 'imp-3446b3924b05eb7b', 5, 'cook', 'Nêm gia vị và làm chín thịt bò', 'Nêm 18 ml nước mắm ngon, 3 g hạt nêm, 4 g muối ăn và 3 g đường cát trắng vào nồi canh, khuấy nhẹ cho tan đều. Đổ đĩa thịt bò xào tái cùng nước tiết vào nồi, đun sôi bùng lại khoảng 30 giây đến khi thịt bò chín tới hoàn toàn rồi tắt bếp ngay.', 'Không đun sôi lâu sau khi thả thịt bò trở lại vì nhiệt kéo dài sẽ làm thịt bò bị dai xác.', NULL),
('imp-3446b3924b05eb7b_v4_step_6', 'imp-3446b3924b05eb7b', 6, 'finish', 'Rắc hành lá, tiêu xay và hoàn thiện', 'Thả hành lá cắt khúc vào nồi đảo nhẹ một lượt, múc canh ra tô lớn và rắc 0,5 g tiêu đen xay lên trên trước khi dùng nóng với cơm trắng.', NULL, NULL),
('imp-6e3eb737c7d88a2c_v4_step_1', 'imp-6e3eb737c7d88a2c', 1, 'prep', 'Làm sạch gà và luộc bóc vỏ trứng gà', 'Chà xát 750 g đùi gà với 4 g muối hạt và 15 g gừng đập dập để khử mùi tanh, rửa lại nước lạnh rồi để ráo, chặt miếng vừa ăn. Luộc 8 quả trứng gà trong nồi nước sôi 7 phút cho vừa chín tới, vớt ra ngâm nước lạnh 3 phút rồi bóc sạch vỏ.', 'Dùng muối kết hợp gừng đập dập chà xát da gà là cách làm sạch mùi hôi hiệu quả nhất trước khi chặt miếng.', 7),
('imp-6e3eb737c7d88a2c_v4_step_2', 'imp-6e3eb737c7d88a2c', 2, 'marinate', 'Giã gia vị thơm và ướp thịt gà', 'Cho hành tím, tỏi khô, đầu hành lá và 1 quả ớt sừng đỏ vào cối giã thật nhuyễn. Trộn hỗn hợp này với 35 ml nước mắm ngon, 10 g đường cát trắng, 4 g hạt nêm và 1 g tiêu đen xay rồi xoa đều lên thịt gà, ướp 30 phút cho ngấm sâu.', NULL, 30),
('imp-6e3eb737c7d88a2c_v4_step_3', 'imp-6e3eb737c7d88a2c', 3, 'sauce', 'Thắng nước màu cánh gián và xào săn gà', 'Làm nóng nồi đáy dày với 15 ml dầu ăn và 15 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan và chuyển màu nâu cánh gián. Tắt bếp tạm 5 giây rồi bật lại lửa lớn, cho toàn bộ thịt gà đã ướp vào đảo săn 5 phút đến khi thịt đổi màu vàng nâu đẹp mắt.', 'Xào săn gà trên lửa lớn ngay trong nồi nước màu giúp miếng gà áo đều màu nâu cánh gián bóng đẹp từ bên ngoài.', 5),
('imp-6e3eb737c7d88a2c_v4_step_4', 'imp-6e3eb737c7d88a2c', 4, 'cook', 'Đổ nước ngập gà và thả trứng vào kho', 'Rót 450 ml nước lọc vào nồi xâm xấp mặt thịt gà, đun sôi bùng và hớt sạch bọt nổi để nước kho được trong. Nhẹ nhàng thả 8 quả trứng gà đã bóc vỏ vào nồi rồi hạ lửa nhỏ.', NULL, NULL),
('imp-6e3eb737c7d88a2c_v4_step_5', 'imp-6e3eb737c7d88a2c', 5, 'cook', 'Kho nhỏ lửa cho gà mềm và trứng thấm màu', 'Đậy hé vung và kho liu riu trong 25 phút, cứ mỗi 10 phút đảo nhẹ tay một lần để thịt gà chín mềm đều, nước kho rút sánh nhẹ và trứng lên màu nâu đậm vị.', 'Đảo nhẹ tay hoặc múc nước kho rưới lên mặt trứng tránh làm rách lòng trắng trứng gà.', 25),
('imp-6e3eb737c7d88a2c_v4_step_6', 'imp-6e3eb737c7d88a2c', 6, 'finish', 'Nêm lại, rắc hành lá và tiêu thưởng thức', 'Mở nắp nêm nếm lại độ mặn ngọt vừa miệng rồi tắt bếp. Múc gà kho trứng ra tô sâu lòng, rắc phần lá hành thái nhỏ và 1 g tiêu đen xay còn lại lên trên rồi ăn nóng với cơm trắng.', NULL, NULL),
('imp-6251f57b97918111_v4_step_1', 'imp-6251f57b97918111', 1, 'prep', 'Làm sạch tôm tươi và băm nhuyễn hành tỏi', 'Rửa sạch 500 g tôm tươi, cắt bỏ râu và chân, dùng tăm rút sạch chỉ đen dọc sống lưng (nếu dùng tôm càng có thể tách riêng phần gạch đầu tôm để chưng riêng) rồi để thật ráo nước. Hành tím và tỏi khô băm nhuyễn chia làm hai phần; hành lá rửa sạch thái nhỏ.', 'Để tôm thật ráo nước sau khi rửa giúp phần nước sốt bám chặt vào vỏ tôm khi đảo trên lửa lớn.', NULL),
('imp-6251f57b97918111_v4_step_2', 'imp-6251f57b97918111', 2, 'sauce', 'Pha nước sốt nước tương và ướp tôm', 'Trong chén riêng, khuấy tan 25 ml nước tương, 20 ml dầu hào, 10 g đường cát trắng và 20 ml rượu nấu ăn. Trộn tôm trong tô với một nửa phần hành tím tỏi băm, 15 ml nước mắm ngon, nửa lượng tiêu đen xay và hỗn hợp nước sốt vừa pha, ướp 15 phút cho thấm vị.', NULL, 15),
('imp-6251f57b97918111_v4_step_3', 'imp-6251f57b97918111', 3, 'cook', 'Phi thơm hành tỏi với dầu ăn và dầu màu điều', 'Làm nóng nồi đất hoặc chảo với 20 ml dầu ăn và 10 ml dầu màu điều trên lửa vừa, cho phần hành tím và tỏi băm còn lại vào phi thơm khoảng 1 phút cho dậy mùi và lên màu đỏ cam đẹp mắt.', 'Nếu dùng tôm càng có gạch, có thể xào nhanh phần gạch tôm với chút hành tỏi phi trước rồi múc riêng ra chén để rưới lên mặt khi hoàn thành.', NULL),
('imp-6251f57b97918111_v4_step_4', 'imp-6251f57b97918111', 4, 'cook', 'Đảo săn tôm trên lửa vừa lớn', 'Trút toàn bộ tôm cùng phần nước ướp vào nồi, tăng lên lửa vừa lớn và đảo đều tay trong 3 phút cho đến khi vỏ tôm chuyển màu đỏ cam rực rỡ và thân tôm săn cong lại.', NULL, 3),
('imp-6251f57b97918111_v4_step_5', 'imp-6251f57b97918111', 5, 'cook', 'Kho liu riu cho tôm thấm đẫm sốt sánh', 'Rót 40 ml nước lọc vào nồi, hạ lửa nhỏ kho mở nắp liu riu trong 6–7 phút, lật nhẹ hai mặt tôm cho chín đều hoàn toàn và nước sốt rút sánh bóng ôm quanh từng con tôm.', 'Chừa lại một lượng nước sốt sánh sệt vừa đủ dưới đáy nồi để chan cùng cơm nóng sẽ rất đậm vị.', 7),
('imp-6251f57b97918111_v4_step_6', 'imp-6251f57b97918111', 6, 'finish', 'Rắc hành lá, tiêu đen và thưởng thức', 'Nêm nếm lại vừa khẩu vị rồi tắt bếp. Gắp tôm kho nước tương ra đĩa, rưới phần sốt sánh cùng hành lá thái nhỏ và nửa lượng tiêu đen xay còn lại lên trên rồi dọn ăn nóng.', NULL, NULL),
('imp-977a3409383d743f_v4_step_1', 'imp-977a3409383d743f', 1, 'prep', 'Làm sạch khử tanh mực bằng giấm gạo', 'Cắt bỏ mắt, răng, túi mực, nội tạng và rút thanh nang trắng bên trong thân mực ống. Rửa mực qua nước pha 2 g muối ăn, sau đó ngâm 5 phút trong thau nước lạnh có pha 15 ml giấm gạo để khử sạch mùi tanh, xả lại thật sạch dưới vòi nước rồi thái khoanh tròn vừa ăn và để ráo.', 'Ngâm nhanh mực với nước pha giấm gạo giúp khử tanh hiệu quả mà thịt mực vẫn giữ được độ trắng giòn.', 5),
('imp-977a3409383d743f_v4_step_2', 'imp-977a3409383d743f', 2, 'marinate', 'Ướp mực và sơ chế bông cải xanh', 'Ướp mực đã ráo nước với 20 g hành tím khô thái lát mỏng, 4 g muối ăn, 8 g đường cát trắng, 5 g hạt nêm và 1 g tiêu đen xay trong 15 phút. Trong lúc chờ, tách bông cải xanh thành từng nhánh vừa ăn, rửa sạch; băm nhỏ 10 g hành tím còn lại cùng tỏi khô; cắt khúc hành lá.', NULL, 15),
('imp-977a3409383d743f_v4_step_3', 'imp-977a3409383d743f', 3, 'prep', 'Chần sơ bông cải xanh giữ màu tươi', 'Đun sôi nồi nước với 2 g muối ăn còn lại, thả bông cải xanh vào chần nhanh trong khoảng 1 phút cho vừa chuyển sắc xanh mướt rồi vớt ra rổ để thật ráo nước.', 'Chỉ chần bông cải xanh đúng 1 phút để bông cải giữ độ giòn sần sật khi xào chung với mực.', NULL),
('imp-977a3409383d743f_v4_step_4', 'imp-977a3409383d743f', 4, 'cook', 'Phi thơm hành tỏi và xào nóng bông cải', 'Làm nóng 25 ml dầu ăn trong chảo rộng trên lửa vừa, phi thơm hành tím băm và tỏi băm. Trút bông cải xanh đã ráo vào đảo đều khoảng 1,5 phút cho thấm dầu tỏi thơm.', NULL, NULL),
('imp-977a3409383d743f_v4_step_5', 'imp-977a3409383d743f', 5, 'cook', 'Xào lửa lớn cho mực săn giòn quyện xì dầu', 'Tăng lên lửa lớn nhất, trút toàn bộ mực đã ướp vào chảo bông cải xanh và đảo nhanh tay liên tục khoảng 3 phút cho đến khi khoanh mực săn chắc, chuyển màu trắng đục viền hồng và chín hoàn toàn. Rưới 15 ml nước tương (xì dầu) vào đảo đều thêm 30 giây, nêm nếm lại cho vừa miệng.', 'Giữ lửa lớn khi cho mực vào giúp mực chín nhanh, giữ độ giòn ngọt mà không bị ra nhiều nước.', 3),
('imp-977a3409383d743f_v4_step_6', 'imp-977a3409383d743f', 6, 'finish', 'Hoàn thiện với hành lá, ớt bột và tiêu', 'Thả hành lá cắt khúc và 1,5 g ớt bột (nếu thích cay) vào đảo nhanh 15 giây rồi tắt bếp. Bày mực xào bông cải xanh ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-a4ff266c02427746_v4_step_1', 'imp-a4ff266c02427746', 1, 'prep', 'Sơ chế bông cải xanh và băm nhuyễn tỏi', 'Tách bông cải xanh thành các nhánh nhỏ vừa ăn, gọt bỏ lớp vỏ xơ ở phần cuống rồi ngâm nước muối loãng 5 phút và rửa sạch 2–3 lần nước, để ráo. Tỏi khô bóc vỏ, đập dập và băm nhuyễn.', 'Cắt các nhánh bông cải xanh đều kích thước để khi chần và xào chín đồng đều cùng lúc.', NULL),
('imp-a4ff266c02427746_v4_step_2', 'imp-a4ff266c02427746', 2, 'prep', 'Chần bông cải xanh và ngâm nước đá lạnh', 'Đun sôi nồi nước trên lửa lớn với 6 g muối ăn, thả bông cải xanh vào chần khoảng 1,5–2 phút cho đến khi bông cải vừa chuyển màu xanh ngọc tươi thì vớt ngay ra ngâm vào tô nước đá lạnh 3 phút, sau đó vớt ra rổ để thật ráo nước.', 'Sốc nhiệt bằng nước đá lạnh sau khi chần giữ bông cải giòn sần sật và không bị ngả vàng.', 3),
('imp-a4ff266c02427746_v4_step_3', 'imp-a4ff266c02427746', 3, 'cook', 'Phi thơm vàng tỏi băm', 'Làm nóng 30 ml dầu ăn trong chảo trên lửa vừa, cho toàn bộ tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi chuyển vàng nhẹ và tỏa mùi thơm nức.', 'Đảo liên tục khi phi tỏi để tỏi vàng đều mà không bị cháy đắng.', NULL),
('imp-a4ff266c02427746_v4_step_4', 'imp-a4ff266c02427746', 4, 'cook', 'Xào bông cải xanh thấm dầu tỏi', 'Tăng lên lửa lớn, trút bông cải xanh đã để ráo vào chảo dầu tỏi và đảo đều tay khoảng 1 phút cho các nhánh bông cải áo lớp dầu bóng mịn.', NULL, NULL),
('imp-a4ff266c02427746_v4_step_5', 'imp-a4ff266c02427746', 5, 'cook', 'Nêm gia vị và đảo nhanh cho thấm đều', 'Rắc 8 g hạt nêm, 2 g muối ăn còn lại, 2 g bột ngọt, rưới 8 ml nước tương (xì dầu) và 60 ml nước lọc vào chảo. Tiếp tục đảo đều trên lửa lớn khoảng 1,5–2 phút cho nước gia vị cạn bám đều quanh bông cải xanh mà rau vẫn giòn ngọt.', NULL, 2),
('imp-a4ff266c02427746_v4_step_6', 'imp-a4ff266c02427746', 6, 'finish', 'Nêm lại và dọn nóng', 'Nêm nếm lại cho vừa khẩu vị rồi tắt bếp ngay. Gắp bông cải xanh xào tỏi ra đĩa phẳng, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-f9f08651bc712e93_v4_step_1', 'imp-f9f08651bc712e93', 1, 'prep', 'Làm sạch khử nhớt cá và lọc mịn cơm mẻ', 'Chà xát phi lê cá lăng với 3 g muối ăn, gừng tươi đập dập và 1/2 quả chanh tươi trong 2 phút cho hết nhớt tanh rồi rửa lại nước lạnh, thấm thật khô và cắt miếng vuông dày khoảng 1,5–2 cm. Cho 40 g cơm mẻ qua rây miết lấy phần nước mịn, bỏ bã.', 'Rửa cá lăng với muối, gừng và chanh giúp loại bỏ hoàn toàn chất nhớt và mùi tanh đặc trưng của cá da trơn.', NULL),
('imp-f9f08651bc712e93_v4_step_2', 'imp-f9f08651bc712e93', 2, 'marinate', 'Ướp cá thấm gia vị riềng mẻ nghệ mắm tôm', 'Trộn đều cá với riềng giã nhuyễn, nước mẻ lọc mịn, 5 g bột nghệ, 10 g mắm tôm, 12 g đường cát trắng, 10 ml nước mắm ngon, 2 g muối ăn, 2 g tiêu đen xay, tỏi băm, hành tím băm và 15 ml dầu ăn. Bọc kín đặt ngăn mát tủ lạnh ướp ít nhất 30 phút cho thịt cá săn và thấm vàng đều.', 'Lọc bỏ bã mẻ và bã riềng thô giúp miếng chả cá khi áp chảo không bị cháy đen bề mặt.', 30),
('imp-f9f08651bc712e93_v4_step_3', 'imp-f9f08651bc712e93', 3, 'prep', 'Sơ chế thì là, hành lá, lạc rang và bún tươi', 'Trong lúc chờ ướp cá, rửa sạch thì là và hành lá để thật ráo nước; phần củ hành trắng chẻ đôi, phần lá xanh và thì là cắt khúc 4 cm. Nhặt rửa rau húng láng để ráo; giã dập đậu phộng rang; chuẩn bị sẵn 400 g bún tươi và ớt tươi thái lát.', NULL, NULL),
('imp-f9f08651bc712e93_v4_step_4', 'imp-f9f08651bc712e93', 4, 'cook', 'Áp chảo cá vàng ươm hai mặt trên lửa vừa', 'Làm nóng 20 ml dầu ăn trong chảo chống dính hoặc chảo gang trên lửa vừa, xếp từng miếng cá đã ướp (gạt bớt xác riềng bám ngoài) vào áp chảo khoảng 4 phút mỗi mặt đến khi hai mặt vàng nghệ xém cạnh và thịt cá chín trắng đục hoàn toàn, gắp nhẹ ra đĩa.', 'Không lật cá liên tục trong 3 phút đầu để bề mặt cá se vàng đẹp và không bị vỡ nát.', 8),
('imp-f9f08651bc712e93_v4_step_5', 'imp-f9f08651bc712e93', 5, 'sauce', 'Pha mắm tôm đánh bông sủi bọt', 'Cho 25 g mắm tôm còn lại, 6 g đường cát trắng, 1 g bột ngọt (nếu dùng) và nước cốt của 1/2 quả chanh tươi vào chén nhỏ, dùng đũa đánh mạnh liên tục 1 phút đến khi mắm tôm chuyển màu tím nhạt sủi bọt bông mịn rồi thêm vài lát ớt tươi.', 'Đánh mắm tôm cùng nước cốt chanh và đường thật đều tay đến khi nổi bọt trắng mịn sẽ giúp dậy hương thơm đặc trưng và dịu vị.', NULL),
('imp-f9f08651bc712e93_v4_step_6', 'imp-f9f08651bc712e93', 6, 'finish', 'Đảo nóng cá cùng hành lá, thì là và dọn ăn', 'Thêm 10 ml dầu ăn vào chảo nóng, thả phần đầu hành trắng vào đảo nhanh 30 giây rồi cho cá đã áp chảo, hành lá xanh và thì là vào đảo nhẹ tay khoảng 1 phút cho rau vừa chín tới còn xanh mướt thì tắt bếp. Rắc đậu phộng rang giã dập lên mặt và ăn nóng ngay cùng bún tươi, húng láng và mắm tôm.', NULL, 2),
('imp-0d6c454ae1073ef6_v4_step_1', 'imp-0d6c454ae1073ef6', 1, 'prep', 'Gọt vỏ khử nhựa và cắt miếng su su non', 'Ngâm 3 quả su su non vào thau nước sạch hoặc đeo găng tay khi gọt bỏ lớp vỏ ngoài để tránh nhựa dính tay. Bổ đôi từng quả theo chiều dọc, khoét bỏ phần hạt trắng mềm ở giữa, rửa sạch lại rồi thái thành những miếng dài cỡ ngón tay út cho nhanh chín đều.', 'Gọt vỏ su su trực tiếp dưới chậu nước mát giúp nhựa mủ trôi sạch ngay, tay không bị rít mà miếng su su vẫn trắng xanh đẹp mắt.', NULL),
('imp-0d6c454ae1073ef6_v4_step_2', 'imp-0d6c454ae1073ef6', 2, 'prep', 'Sơ chế tỏi băm và hành lá thái nhỏ', 'Bóc vỏ 1 củ tỏi khô, đập dập rồi băm vừa (không băm quá nát để tỏi phi giòn thơm). Rửa sạch hành lá tươi, để ráo rồi thái nhỏ để sẵn sàng hoàn thiện món ăn.', NULL, NULL),
('imp-0d6c454ae1073ef6_v4_step_3', 'imp-0d6c454ae1073ef6', 3, 'cook', 'Hấp su su vừa chín tới giữ độ giòn ngọt', 'Đun sôi 500 ml nước lọc trong nồi hấp ở lửa lớn. Trộn nhẹ su su với 2 g muối ăn rồi xếp đều vào xửng hấp không chồng quá dày, đậy kín nắp và hấp trong 10 phút đến khi dùng đũa xiên nhẹ thấy miếng su su vừa chín mềm trong nhẹ nhưng vẫn giữ độ giòn.', 'Chỉ hấp su su khoảng 10 phút tính từ lúc nước sôi để miếng rau giữ màu xanh ngọc tươi và độ ngọt giòn, tránh hấp nhừ.', 10);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-0d6c454ae1073ef6_v4_step_4', 'imp-0d6c454ae1073ef6', 4, 'sauce', 'Phi tỏi vàng thơm và pha sốt mắm rưới', 'Trong lúc chờ hấp su su, làm nóng 20 ml dầu ăn trên chảo nhỏ ở lửa vừa, cho tỏi băm vào phi khoảng 2 phút đến khi vàng thơm thì tắt bếp. Rót vào chảo dầu tỏi đang ấm 15 ml nước mắm ngon, 15 ml xì dầu và 5 g đường cát trắng, khuấy đều cho đường tan hoàn toàn.', 'Tắt bếp ngay khi tỏi vừa ngả vàng sáng rồi mới rót nước mắm đường vào để tránh bắn dầu và giữ hương tỏi thơm nồng.', 2),
('imp-0d6c454ae1073ef6_v4_step_5', 'imp-0d6c454ae1073ef6', 5, 'cook', 'Rắc hành lá giữ màu xanh mướt trên xửng', 'Gắp su su chín ra đĩa sâu lòng, rắc đều hành lá thái nhỏ lên trên mặt su su khi còn đang bốc hơi nóng để hành dịu bớt vị hăng nhưng vẫn giữ sắc xanh tươi.', NULL, NULL),
('imp-0d6c454ae1073ef6_v4_step_6', 'imp-0d6c454ae1073ef6', 6, 'finish', 'Rưới nước mắm dầu tỏi và dọn ăn nóng', 'Rưới đều toàn bộ phần nước mắm dầu tỏi phi vàng lên khắp các miếng su su và hành lá, đảo nhẹ cho sốt áo đều rồi dọn thưởng thức nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-4d81607829384874_v4_step_1', 'imp-4d81607829384874', 1, 'prep', 'Làm sạch khử mùi và khứa đùi gà', 'Làm sạch lông tơ trên 4 chiếc đùi gà, dùng 4 g muối hạt và 15 g gừng đập dập chà xát khắp mặt da và thịt trong 2 phút để khử mùi hôi, sau đó xả sạch lại với nước mát và thấm khô. Dùng dao sắc khứa 2–3 đường chéo trên phần thịt dày để gà thấm gia vị và chín nhanh hơn.', NULL, NULL),
('imp-4d81607829384874_v4_step_2', 'imp-4d81607829384874', 2, 'marinate', 'Sơ chế gừng hành và ướp đùi gà thấm vị', 'Thái sợi chỉ 45 g gừng còn lại; hành tím thái lát mỏng; hành lá cắt khúc dài 5 cm; ớt tươi thái sợi. Trộn ướp đùi gà với 4 g muối hạt, 5 g hạt nêm, 1 g tiêu đen xay, 15 ml xì dầu (nếu dùng) và 25 g gừng thái sợi, xoa kỹ vào các đường khứa rồi ướp 20 phút.', 'Xoa gia vị vào sâu bên trong các đường khứa giúp phần thịt sát xương đậm đà mà không cần ướp quá mặn bên ngoài.', 20),
('imp-4d81607829384874_v4_step_3', 'imp-4d81607829384874', 3, 'cook', 'Xếp đĩa hấp gà cách thủy lửa vừa', 'Trải một nửa lượng hành lá cắt khúc, hành tím thái lát và ít gừng sợi xuống đáy đĩa sâu lòng chịu nhiệt, đặt đùi gà đã ướp lên trên. Đun sôi 700 ml nước lọc trong nồi hấp, cho đĩa gà vào xửng, đậy kín vung và hấp trên lửa vừa trong 22 phút.', 'Lót hành lá và hành tím dưới đáy đĩa giúp ngăn da gà dính vào đĩa và tạo hơi thơm ngấm ngược vào thịt.', 22),
('imp-4d81607829384874_v4_step_4', 'imp-4d81607829384874', 4, 'cook', 'Thêm hành lá, gừng sợi hấp chín tới', 'Mở nắp xửng, rải phần hành lá cắt khúc và 20 g gừng thái sợi còn lại phủ lên mặt đùi gà rồi đậy nắp hấp tiếp thêm 5 phút. Dùng tăm xiên vào phần thịt dày nhất gần khớp xương thấy nước tiết ra trong suốt không còn màu hồng là gà đã chín hoàn toàn.', 'Thêm hành lá và lớp gừng sợi mới vào 5 phút cuối giúp rau giữ được sắc xanh tươi và hương thơm cay ấm nổi bật khi dọn.', 5),
('imp-4d81607829384874_v4_step_5', 'imp-4d81607829384874', 5, 'sauce', 'Pha chén muối tiêu chanh chấm gà', 'Trộn 4 g muối hạt còn lại với 1 g tiêu đen xay trong chén nhỏ, vắt nước cốt 1 quả chanh tươi vào khuấy nhẹ cho muối tan bớt.', NULL, NULL),
('imp-4d81607829384874_v4_step_6', 'imp-4d81607829384874', 6, 'finish', 'Rưới dầu mè và trình bày đĩa gà hấp nóng', 'Nhấc đĩa gà ra khỏi xửng, rưới 5 ml dầu mè thơm đều lên mặt da gà và rắc ớt tươi thái sợi trang trí; chặt miếng vừa ăn hoặc để nguyên đùi dọn nóng cùng chén muối tiêu chanh.', NULL, NULL),
('imp-1b518ba2f068f3ab_v4_step_1', 'imp-1b518ba2f068f3ab', 1, 'prep', 'Gọt thái dứa chín và ngâm đá giòn cà rốt', 'Gọt sạch vỏ và mắt quả dứa chín vàng, rửa sơ để ráo rồi thái miếng dày khoảng 0,5 cm, dài 3–4 cm vừa gắp. Cà rốt gọt vỏ bào sợi mảnh, ngâm vào tô nước đá lạnh trong 10 phút cho sợi giòn cứng rồi vớt ra để thật ráo nước.', 'Chọn quả dứa chín vàng đều, mùi thơm ngọt dịu để nộm đậm hương vị tự nhiên mà không bị gắt chua.', 10),
('imp-1b518ba2f068f3ab_v4_step_2', 'imp-1b518ba2f068f3ab', 2, 'cook', 'Rang giã đậu phộng và sơ chế rau gia vị', 'Cho đậu phộng vào chảo rang trên lửa nhỏ khoảng 8 phút đến khi chín vàng thơm đều, để nguội xát sạch vỏ lụa và giã dập vừa giữ độ giòn bùi. Rửa sạch hành lá cắt khúc 3 cm; băm thật nhuyễn tỏi khô và 1 quả ớt hiểm, quả ớt còn lại thái vát mỏng.', NULL, 8),
('imp-1b518ba2f068f3ab_v4_step_3', 'imp-1b518ba2f068f3ab', 3, 'sauce', 'Pha nước trộn nộm chua cay hài hòa', 'Hòa tan 35 ml nước mắm ngon, 25 g đường cát trắng, 22 ml giấm gạo và 60 ml nước lọc trong chén đến khi đường tan hết. Thêm nước cốt 2 quả chanh tươi, tỏi băm và ớt hiểm băm vào khuấy đều, nêm thêm 2 g muối ăn nếu thích đậm vị hơn.', 'Cho tỏi ớt vào sau khi đường đã tan hết giúp hương thơm dậy đều và màu sắc bát nước trộn bắt mắt.', NULL),
('imp-1b518ba2f068f3ab_v4_step_4', 'imp-1b518ba2f068f3ab', 4, 'prep', 'Trộn thấm dứa và cà rốt lượt đầu', 'Cho dứa thái lát và cà rốt bào sợi đã ráo nước vào âu lớn. Rưới 2/3 lượng nước trộn nộm vào, đảo nhẹ nhàng cho miếng dứa không bị dập nát rồi để yên khoảng 8 phút cho ngấm vị.', NULL, 8),
('imp-1b518ba2f068f3ab_v4_step_5', 'imp-1b518ba2f068f3ab', 5, 'prep', 'Trộn hành lá và điều chỉnh vị cuối', 'Cho hành lá cắt khúc vào âu nộm cùng 1/3 lượng nước trộn còn lại, đảo đều nhẹ tay thêm một lượt để hành lá giữ nguyên màu xanh tươi và độ giòn.', NULL, NULL),
('imp-1b518ba2f068f3ab_v4_step_6', 'imp-1b518ba2f068f3ab', 6, 'finish', 'Bày đĩa, rắc đậu phộng và thưởng thức mát', 'Gắp nộm dứa ra đĩa sâu lòng, rắc toàn bộ đậu phộng rang giã dập và vài lát ớt hiểm lên trên mặt. Dọn thưởng thức ngay khi nộm còn tươi giòn và mát lành.', 'Chỉ rắc đậu phộng rang ngay trước khi ăn để hạt đậu giữ được độ giòn bùi, không bị ỉu do hút ẩm.', NULL),
('imp-0f336e8735d9ce75_v4_step_1', 'imp-0f336e8735d9ce75', 1, 'cook', 'Làm sạch và trụng mực ống vừa chín tới', 'Làm sạch túi mực, nang và mắt mực ống, rửa kỹ với nước pha 1 g muối ăn rồi xả sạch. Đun sôi 680 ml nước lọc trên lửa lớn cùng 1 g muối ăn, thả mực vào trụng nhanh khoảng 3 phút đến khi thịt mực săn trắng đục chín hoàn toàn thì vớt ngay ra ngâm nước nguội cho giòn rồi để ráo, thái khoanh dày 1 cm.', 'Trụng nhanh mực trong nước sôi rồi làm nguội ngay giúp khoanh mực giòn sần sật, không bị dai cứng.', 3),
('imp-0f336e8735d9ce75_v4_step_2', 'imp-0f336e8735d9ce75', 2, 'prep', 'Ướp muối và vắt thật ráo dưa leo, cà rốt', 'Bổ đôi dưa leo, nạo bỏ hết phần ruột hạt rồi thái lát mỏng; cà rốt gọt vỏ bào sợi mảnh. Trộn đều dưa leo và cà rốt với 3 g muối ăn trong 10 phút cho ra bớt nước rồi dùng tay hoặc khăn sạch vắt thật ráo.', 'Loại bỏ ruột dưa leo và vắt thật ráo rau củ là bước quyết định giúp món gỏi giòn lâu và không bị lõng bõng nước.', 10),
('imp-0f336e8735d9ce75_v4_step_3', 'imp-0f336e8735d9ce75', 3, 'cook', 'Phi thơm tỏi băm và sơ chế sả, rau thơm', 'Phi thơm tỏi băm với 12 ml dầu ăn trên lửa nhỏ đến khi vừa vàng giòn thì vớt ra giấy thấm dầu. Thái khoanh thật mỏng cây sả; nhặt rửa sạch rau răm, rau húng quế và cần tây rồi cắt nhỏ. Băm nhỏ 1 quả ớt tươi và thái lát quả còn lại.', NULL, NULL),
('imp-0f336e8735d9ce75_v4_step_4', 'imp-0f336e8735d9ce75', 4, 'sauce', 'Pha nước mắm đường trộn gỏi', 'Khuấy tan 25 ml nước mắm ngon với 18 g đường cát trắng và 20 ml nước lọc đến khi đường tan hoàn toàn thành bát nước trộn đậm dịu.', NULL, NULL),
('imp-0f336e8735d9ce75_v4_step_5', 'imp-0f336e8735d9ce75', 5, 'prep', 'Trộn thấm mực, rau củ cùng sả và ớt bột', 'Cho mực thái khoanh, dưa leo, cà rốt đã vắt ráo, sả thái khoanh, 2 g ớt bột khô, ớt băm, rau răm, rau húng quế và cần tây vào thố lớn. Rưới bát nước mắm đường vào đảo đều nhẹ tay cho các nguyên liệu ngấm gia vị.', NULL, NULL),
('imp-0f336e8735d9ce75_v4_step_6', 'imp-0f336e8735d9ce75', 6, 'finish', 'Thêm nước cốt chanh, rắc tỏi phi và thưởng thức', 'Vắt nước cốt 1,5 quả chanh tươi rưới đều lên thố gỏi, trộn nhẹ lần cuối và để thấm 5 phút cho vị chua cay mặn ngọt hài hòa. Bày gỏi ra đĩa, rắc tỏi phi vàng giòn cùng vài lát ớt tươi lên trên và dọn ăn ngay kèm bánh phồng tôm.', 'Cho nước cốt chanh vào bước cuối giúp giữ nguyên hương thơm tươi mát của chanh và độ giòn của dưa leo.', 5),
('imp-f93013fb234d39d0_v4_step_1', 'imp-f93013fb234d39d0', 1, 'prep', 'Sơ chế nấm đùi gà, bắp cải, cà rốt và trụng bún', 'Nấm đùi gà cắt bỏ gốc, rửa nhanh trong nước pha 2 g muối ăn rồi xả sạch, để ráo và thái lát mỏng. Bắp cải rửa sạch, thái sợi; cà rốt gọt vỏ thái sợi mỏng; tỏi khô băm nhỏ; hành lá cắt khúc 3 cm. Đun sôi nồi nước, trụng nhanh 400 g bún gạo tươi khoảng 1 phút rồi vớt ra rổ để thật ráo và trộn nhẹ với 10 ml dầu ăn cho sợi tơi.', 'Trộn nhẹ bún ráo nước với một chút dầu ăn giúp từng sợi bún tơi rời, không dính chảo và không bị nát khi đảo.', 2),
('imp-f93013fb234d39d0_v4_step_2', 'imp-f93013fb234d39d0', 2, 'cook', 'Phi thơm tỏi và xào cà rốt, bắp cải', 'Làm nóng chảo rộng với 20 ml dầu ăn còn lại trên lửa vừa, cho tỏi băm vào phi 30 giây đến khi thơm vàng nhẹ. Bật lửa lớn, cho cà rốt và bắp cải thái sợi vào đảo đều tay 3 phút đến khi rau hơi mềm mà vẫn giữ độ giòn.', NULL, 3),
('imp-f93013fb234d39d0_v4_step_3', 'imp-f93013fb234d39d0', 3, 'cook', 'Xào chín nấm đùi gà cùng rau củ', 'Cho nấm đùi gà thái lát vào chảo rau củ, tiếp tục đảo đều trên lửa lớn trong 3 phút cho nấm chín mềm và tiết nước ngọt tự nhiên hòa vào rau.', 'Xào cà rốt và bắp cải trước rồi mới thêm nấm đùi gà thái lát mỏng giúp cả ba nguyên liệu chín tới đồng đều.', 3),
('imp-f93013fb234d39d0_v4_step_4', 'imp-f93013fb234d39d0', 4, 'sauce', 'Nêm gia vị đậm đà cho hỗn hợp rau nấm', 'Nêm vào chảo 25 ml nước tương, 4 g hạt nêm chay, 3 g muối ăn còn lại và 8 g đường cát trắng, đảo đều tay 1 phút cho đường tan hết và rau nấm thấm đẫm gia vị.', NULL, NULL),
('imp-f93013fb234d39d0_v4_step_5', 'imp-f93013fb234d39d0', 5, 'cook', 'Đảo tơi bún gạo tươi quyện đều rau nấm', 'Hạ xuống lửa vừa, trút bún gạo tươi đã ráo vào chảo, dùng đũa xới đảo nhẹ tay cho sợi bún hòa quyện với rau nấm. Rưới thêm 15 ml nước tương còn lại vào bún và đảo đều thêm 2 phút cho sợi bún thấm màu vàng nâu nhẹ đẹp mắt.', 'Dùng hai chiếc đũa đảo hất nhẹ từ dưới lên thay vì xẻng đè mạnh để sợi bún không bị gãy vụn.', 2),
('imp-f93013fb234d39d0_v4_step_6', 'imp-f93013fb234d39d0', 6, 'finish', 'Thêm hành lá, tiêu xay và dọn bún xào nóng', 'Nêm nếm lại vừa miệng rồi cho hành lá cắt khúc vào đảo nhanh 15 giây, tắt bếp. Gắp bún xào chay ra đĩa, rắc 1 g tiêu đen xay lên trên và thưởng thức nóng kèm chén nước tương ớt.', NULL, NULL),
('imp-6af3e18fdac79061_v4_step_1', 'imp-6af3e18fdac79061', 1, 'cook', 'Luộc chín thịt đùi gà với gừng tươi', 'Chà rửa thịt đùi gà với 4 g muối ăn rồi xả sạch. Cho gà vào nồi cùng 1,2 lít nước lọc, gừng tươi thái lát, 2 g muối ăn và 3 g hạt nêm, đun sôi rồi hạ lửa vừa luộc khoảng 18–20 phút. Xiên đũa vào phần thịt dày nhất thấy không chảy nước hồng là gà chín kỹ.', NULL, 20),
('imp-6af3e18fdac79061_v4_step_2', 'imp-6af3e18fdac79061', 2, 'prep', 'Ngâm lạnh thịt gà và thái lát vừa ăn', 'Vớt thịt đùi gà ra ngâm ngay vào tô nước lọc nguội mát trong 5 phút cho phần da săn giòn và thịt không bị khô thâm, sau đó vớt ráo, lọc xương và thái lát mỏng vừa ăn.', 'Ngâm gà vừa luộc vào nước nguội giúp thịt săn chắc, dễ thái lát đẹp mắt mà không bị nát.', 5),
('imp-6af3e18fdac79061_v4_step_3', 'imp-6af3e18fdac79061', 3, 'cook', 'Chần giá đỗ và miến dong trong nước luộc gà', 'Vớt bỏ lát gừng trong nồi nước luộc gà, đun sôi trở lại rồi thả giá đỗ vào chần nhanh 30 giây và vớt ra ngay cho giữ độ giòn. Tiếp theo thả miến dong khô đã rửa sơ vào nồi nước dùng gà đang sôi chần khoảng 1 phút cho sợi miến chín mềm dai vừa tới, vớt ra xóc thật ráo nước và cắt ngắn nếu cần.', 'Chần miến trực tiếp bằng nước luộc gà đang sôi giúp sợi miến ngọt thơm tự nhiên và không bị nhạt.', 2),
('imp-6af3e18fdac79061_v4_step_4', 'imp-6af3e18fdac79061', 4, 'prep', 'Sơ chế rau thơm và giã dập lạc rang', 'Rửa sạch rau húng bạc hà, ngò gai, rau răm và hành lá rồi vẩy ráo nước và thái nhỏ. Giã dập lạc rang cho vỡ làm đôi, làm ba; băm thật nhuyễn tỏi khô và ớt hiểm tươi.', NULL, NULL),
('imp-6af3e18fdac79061_v4_step_5', 'imp-6af3e18fdac79061', 5, 'sauce', 'Pha nước trộn miến nước tương chua ngọt', 'Cho vào chén 30 ml nước mắm ngon, 25 ml nước tương, 8 g đường cát trắng, 15 ml giấm gạo và vắt thêm nước cốt của 1/2 quả chanh tươi, khuấy tan hoàn toàn đường rồi mới thả tỏi khô và ớt hiểm băm vào.', 'Kết hợp cả nước mắm ngon và nước tương giúp nước trộn có chiều sâu hương vị mà màu miến trộn bóng đẹp hơn.', NULL),
('imp-6af3e18fdac79061_v4_step_6', 'imp-6af3e18fdac79061', 6, 'finish', 'Trộn đều miến gà và thưởng thức ngay', 'Chia miến dong ra 3 tô, xếp giá đỗ chần, thịt đùi gà thái lát, rau húng bạc hà, ngò gai, rau răm và hành lá lên trên. Rưới đều nước trộn đã pha vào tô, trộn đều tay cho sợi miến thấm vị rồi rắc lạc rang giã dập lên trên cùng và thưởng thức ngay.', NULL, NULL),
('imp-2e39be75d8f72249_v4_step_1', 'imp-2e39be75d8f72249', 1, 'prep', 'Sơ chế nấm đùi gà, cà chua và hành tỏi', 'Nấm đùi gà cắt bỏ gốc, rửa nhanh qua nước sạch rồi thấm thật ráo, thái lát xéo dày 0,5 cm. Cà chua chín bỏ cuống, bổ múi cau; tỏi khô băm nhỏ; hành lá rửa sạch, tách riêng đầu hành cắt khúc 2 cm và phần lá xanh thái nhỏ.', 'Thấm thật ráo nước nấm đùi gà trước khi xào giúp lát nấm nhanh xém cạnh và giữ độ dai giòn thay vì bị luộc trong nước nấm.', NULL),
('imp-2e39be75d8f72249_v4_step_2', 'imp-2e39be75d8f72249', 2, 'sauce', 'Pha chén nước sốt nước tương và bột năng', 'Cho vào chén 15 ml nước tương, 8 ml dầu hào chay, 5 g đường cát trắng, 4 g bột năng và 35 ml nước lọc. Khuấy đều tay cho đường và bột năng tan hoàn toàn để sẵn bên cạnh bếp.', 'Pha sẵn bột năng cùng nước tương và đường giúp khi rưới vào chảo sốt sánh đều ngay lập tức mà không bị vón cục.', NULL),
('imp-2e39be75d8f72249_v4_step_3', 'imp-2e39be75d8f72249', 3, 'cook', 'Phi thơm tỏi và xào xém cạnh nấm đùi gà', 'Làm nóng chảo với 25 ml dầu ăn trên lửa vừa, thả tỏi băm vào phi khoảng 40 giây đến khi vàng thơm. Bật lửa lớn, cho nấm đùi gà vào đảo đều 4 phút đến khi lát nấm săn chắc và hơi xém vàng hai mặt.', 'Đợi chảo nóng và xào nấm ở lửa lớn giúp nấm giữ được độ giòn ngọt và màu xém cạnh hấp dẫn.', 4),
('imp-2e39be75d8f72249_v4_step_4', 'imp-2e39be75d8f72249', 4, 'cook', 'Xào mềm cà chua tiết nước sốt đỏ tự nhiên', 'Đưa cà chua bổ múi cau vào chảo nấm, hạ xuống lửa vừa và đảo nhẹ tay trong 3 phút để cà chua chín mềm, tiết ra phần nước đỏ cam hòa quyện quanh nấm mà múi cà vẫn giữ được dáng.', NULL, 3),
('imp-2e39be75d8f72249_v4_step_5', 'imp-2e39be75d8f72249', 5, 'cook', 'Rưới chén sốt làm sánh bóng và nêm vừa vị', 'Khuấy đều lại chén sốt rồi đổ vào chảo, thêm 3 g muối ăn và đảo nhẹ trong 2 phút đến khi sốt sôi nhẹ, sánh bóng bao phủ đều từng lát nấm và múi cà chua.', NULL, 2),
('imp-2e39be75d8f72249_v4_step_6', 'imp-2e39be75d8f72249', 6, 'finish', 'Hoàn thiện với đầu hành và lá hành xanh', 'Thả phần đầu hành lá cắt khúc vào đảo nhanh 30 giây rồi tắt bếp. Múc cà chua xào nấm ra đĩa sâu lòng, rắc phần lá hành xanh thái nhỏ lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-11b65c6b18266849_v4_step_1', 'imp-11b65c6b18266849', 1, 'prep', 'Sơ chế đậu phụ, dứa chín và pha sốt kho', 'Đậu phụ trắng thấm thật khô bằng khăn giấy rồi cắt miếng vuông dày 1,5 cm. Dứa chín gọt sạch vỏ và mắt, cắt lát tam giác dày 0,8 cm. Băm nhỏ tỏi khô và hành tím; hành lá chẻ đầu hành để riêng, lá xanh cắt khúc; ớt sừng thái lát. Khuấy tan trong tô 45 ml nước tương, 15 ml dầu hào chay, 8 g đường cát trắng, 3 g muối ăn và 100 ml nước lọc; hòa riêng 8 g bột năng với 30 ml nước lọc còn lại.', 'Thấm thật khô đậu phụ trước khi rán giúp dầu không bị bắn và lớp vỏ ngoài vàng giòn chắc chắn hơn.', NULL),
('imp-11b65c6b18266849_v4_step_2', 'imp-11b65c6b18266849', 2, 'cook', 'Rán vàng giòn đều các mặt đậu phụ', 'Làm nóng chảo với 40 ml dầu ăn trên lửa vừa đến khi dầu sôi tăm, thả từng miếng đậu phụ vào rán khoảng 7 phút. Lật nhẹ tay cho đến khi các mặt vàng giòn đều thì gắp ra đĩa lót giấy thấm dầu.', 'Chỉ thả đậu vào khi dầu đã nóng già giúp đậu không dính sát đáy chảo và tạo vỏ giòn đều.', 7),
('imp-11b65c6b18266849_v4_step_3', 'imp-11b65c6b18266849', 3, 'cook', 'Phi thơm hành tím, tỏi băm và xào dứa chín', 'Chắt bớt dầu thừa ra khỏi chảo, giữ lại khoảng 15 ml dầu ăn trên lửa vừa rồi cho hành tím băm, tỏi băm và đầu hành trắng vào phi thơm 40 giây. Cho dứa chín thái lát vào đảo đều 4 phút cho dứa hơi mềm và tiết nước chua ngọt thơm lừng.', NULL, 4),
('imp-11b65c6b18266849_v4_step_4', 'imp-11b65c6b18266849', 4, 'cook', 'Kho rim đậu phụ với dứa và nước sốt', 'Xếp nhẹ các miếng đậu phụ đã rán vàng vào chảo dứa, rưới đều tô nước sốt nước tương đã pha vào. Đun sôi nhẹ rồi hạ xuống lửa nhỏ, kho liu riu khoảng 10 phút và nhẹ nhàng trở mặt đậu một lần để đậu thấm đượm vị chua ngọt mặn hài hòa.', 'Kho ở lửa nhỏ và trở nhẹ mặt đậu một lần giúp đậu thấm đều vị chua ngọt mà không bị nát.', 10),
('imp-11b65c6b18266849_v4_step_5', 'imp-11b65c6b18266849', 5, 'sauce', 'Tạo độ sánh mượt cho sốt kho dứa', 'Khuấy đều lại chén nước bột năng rồi rót từ từ vào chảo, nghiêng lắc nhẹ chảo khoảng 1 phút cho đến khi nước sốt sánh bóng quyện quanh từng miếng đậu và dứa thì tắt bếp.', NULL, NULL),
('imp-11b65c6b18266849_v4_step_6', 'imp-11b65c6b18266849', 6, 'finish', 'Hoàn thiện món đậu phụ kho dứa nóng hổi', 'Rắc hành lá xanh cắt khúc, ớt sừng thái lát và 2 g tiêu đen xay lên mặt chảo. Múc đậu phụ kho dứa ra đĩa sâu lòng, chan đều nước sốt sánh vàng lên trên và dùng nóng với cơm trắng.', NULL, NULL),
('imp-2ae4c4cdd97c5d02_v4_step_1', 'imp-2ae4c4cdd97c5d02', 1, 'marinate', 'Thái lát mỏng và ướp mềm thịt bò thăn', 'Thấm khô 300 g thịt bò thăn bằng khăn giấy rồi thái lát mỏng ngang thớ. Cho bò vào tô, ướp với 15 ml xì dầu, 15 ml dầu hào, 2 g hạt nêm, 3 g đường cát trắng, 1 g tiêu đen xay, 1/2 lượng tỏi băm, 10 g gừng băm nhuyễn và 5 ml dầu ăn trong 12 phút cho thấm đều.', 'Thêm 5 ml dầu ăn khi ướp giúp lát thịt bò khóa ẩm, khi xào trên lửa lớn sẽ mềm mượt mà không bị ra nước.', 12),
('imp-2ae4c4cdd97c5d02_v4_step_2', 'imp-2ae4c4cdd97c5d02', 2, 'prep', 'Sơ chế hành tây, hành lá và chuẩn bị cơm nóng', 'Bóc vỏ 1,5 củ hành tây, bổ múi cau mỏng vừa ăn và tách rời từng cánh hành. Rửa sạch hành lá, cắt khúc dài 3 cm. Chuẩn bị sẵn 540 g cơm trắng nấu chín còn nóng hổi.', NULL, NULL),
('imp-2ae4c4cdd97c5d02_v4_step_3', 'imp-2ae4c4cdd97c5d02', 3, 'cook', 'Xào nhanh thịt bò chín tái trên lửa lớn', 'Làm nóng 10 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa phần tỏi băm còn lại. Trút toàn bộ thịt bò đã ướp vào trải đều mặt chảo, đảo nhanh tay khoảng 90 giây đến khi thịt bò vừa chuyển màu chín tái 80% thì trút ngay ra đĩa riêng (kèm phần nước tiết ngọt).', 'Chỉ xào bò vừa chín tái ở bước đầu để khi trộn chung với hành tây ở bước cuối thịt chín tới hoàn toàn mà vẫn mềm mọng.', 2),
('imp-2ae4c4cdd97c5d02_v4_step_4', 'imp-2ae4c4cdd97c5d02', 4, 'cook', 'Xào hành tây giữ độ giòn ngọt tự nhiên', 'Cho 10 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi băm còn lại rồi cho hành tây bổ múi cau vào đảo nhanh trên lửa lớn khoảng 2 phút. Nêm 10 ml xì dầu còn lại và 2 g hạt nêm để hành tây vừa trong cạnh, ngọt thanh mà vẫn còn độ giòn.', 'Xào hành tây trên lửa lớn trong 2 phút giúp hành bớt hăng mà không bị mềm nhũn.', 2),
('imp-2ae4c4cdd97c5d02_v4_step_5', 'imp-2ae4c4cdd97c5d02', 5, 'cook', 'Trộn thịt bò, hành lá vào chảo cho quyện sốt', 'Trút đĩa thịt bò xào (cùng phần nước sốt ngọt) và hành lá cắt khúc vào chảo hành tây, đảo nhanh tay thêm 30 giây trên lửa lớn cho thịt bò chín hoàn toàn và nước sốt sánh nhẹ rồi tắt bếp.', NULL, NULL),
('imp-2ae4c4cdd97c5d02_v4_step_6', 'imp-2ae4c4cdd97c5d02', 6, 'finish', 'Chan bò xào hành tây lên cơm trắng và dùng nóng', 'Xới cơm trắng nóng ra 3 đĩa, múc đều thịt bò xào hành tây kèm nước sốt đậm đà chan lên mặt cơm, rắc 1 g tiêu đen xay còn lại và thưởng thức ngay.', NULL, NULL),
('imp-9a2994a529126adb_v4_step_1', 'imp-9a2994a529126adb', 1, 'prep', 'Trụng tơi sợi mì và sơ chế rau củ, đánh trứng', 'Đun sôi 1,2 lít nước lọc, thả 3 vắt mì vào trụng nhanh khoảng 90 giây cho sợi vừa bung rời, vớt ra xả ngay nước lạnh, để thật ráo rồi trộn với 5 ml dầu ăn chống dính. Thái sợi bắp cải trắng và cà rốt; băm nhỏ tỏi; tách riêng đầu hành trắng băm và lá hành xanh cắt khúc. Đập 3 quả trứng gà đánh tan cùng 2 g muối ăn và 1 g tiêu đen xay.', 'Xả nhanh nước lạnh và trộn chút dầu ăn ngay sau khi trụng giúp sợi mì săn dai và tách rời hoàn toàn lúc xào.', 2),
('imp-9a2994a529126adb_v4_step_2', 'imp-9a2994a529126adb', 2, 'cook', 'Chiên tơi trứng gà vàng xốp để riêng', 'Làm nóng 10 ml dầu ăn trong chảo lớn trên lửa vừa, đổ tô trứng gà vào đảo nhẹ nhàng khoảng 90 giây cho đến khi trứng vừa chín tới thành từng mảng vàng xốp mềm thì trút riêng ra đĩa.', 'Chiên riêng trứng trước rồi mới xào rau mì giúp trứng giữ được màu vàng tươi, xốp mềm mà không bị thâm màu xì dầu.', 2),
('imp-9a2994a529126adb_v4_step_3', 'imp-9a2994a529126adb', 3, 'cook', 'Phi thơm tỏi, đầu hành và xào rau củ giòn ngọt', 'Làm nóng 15 ml dầu ăn còn lại trong chảo trên lửa lớn, phi thơm tỏi băm và đầu hành trắng. Cho cà rốt và bắp cải trắng vào xào nhanh 2 phút cho vừa chín tới giữ độ giòn, nêm 10 ml nước mắm ngon và 3 g hạt nêm rồi gạt gọn sang một bên chảo.', NULL, 2),
('imp-9a2994a529126adb_v4_step_4', 'imp-9a2994a529126adb', 4, 'cook', 'Áp chảo mì thấm sốt xì dầu, dầu hào', 'Trút toàn bộ 225 g mì đã trụng vào phần chảo trống, rưới đều 20 ml xì dầu, 15 ml dầu hào, 5 g đường cát trắng và 2 g hạt nêm còn lại lên mì. Đảo đều cùng rau củ trên lửa lớn khoảng 2 phút đến khi sợi mì khô ráo, săn bóng và lên màu nâu đẹp mắt.', 'Giữ lửa lớn khi đảo mì và rau củ giúp nước sốt bám quyện đều vào sợi mì mà không bị đọng nước dưới đáy chảo.', NULL),
('imp-9a2994a529126adb_v4_step_5', 'imp-9a2994a529126adb', 5, 'cook', 'Trộn lại trứng gà chiên vào chảo mì rau', 'Cho đĩa trứng gà chiên tơi trở lại chảo mì, đảo nhẹ tay thêm 30 giây cho trứng, sợi mì và rau củ hòa quyện đều mà không làm vụn nát mảng trứng rồi tắt bếp.', NULL, NULL),
('imp-9a2994a529126adb_v4_step_6', 'imp-9a2994a529126adb', 6, 'finish', 'Rắc hành lá, tiêu xay và dọn nóng', 'Rắc toàn bộ lá hành xanh cắt khúc và 1 g tiêu đen xay còn lại vào chảo đảo thêm 2 lượt cho hành vừa chín tái xanh mướt. Bày mì xào trứng rau ra 3 đĩa và dùng nóng ngay.', NULL, NULL),
('imp-990934aa20b70964_v4_step_1', 'imp-990934aa20b70964', 1, 'prep', 'Chần xương bò và ninh nước dùng ngọt sâu', 'Chặt nhỏ 500 g xương ống bò, chần nước sôi 4 phút với 2 g muối hạt rồi vớt ra xả sạch bọt bẩn. Cho xương vào nồi cùng 2200 ml nước lọc, 1/2 củ hành tây bổ múi cau và 3 g muối hạt, đun sôi rồi hạ lửa nhỏ liu riu ninh 30 phút và hớt bọt thường xuyên để nước dùng trong ngọt.', 'Chần kỹ xương bò trước khi ninh sẽ loại bỏ hết mùi hôi và cặn đục, giúp nồi nước dùng lẩu trong thanh.', 30),
('imp-990934aa20b70964_v4_step_2', 'imp-990934aa20b70964', 2, 'prep', 'Thái mỏng ướp bò và sơ chế nấm, rau thơm', 'Thái lát mỏng ngang thớ 650 g thịt bò, trộn đều cùng một nửa tỏi băm, 3 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn để thịt mềm thơm, xếp lên đĩa cùng 1/2 củ hành tây thái lát mỏng. Cắt gốc rửa sạch nấm đùi gà thái lát; rửa sạch rau muống, húng quế, ngò rí, hành lá; bổ múi cau 2 quả cà chua, băm nhỏ 1 quả cà chua và vắt nước cốt 2 quả chanh tươi.', 'Trộn 5 ml dầu ăn khi ướp lát thịt bò mỏng giúp miếng thịt giữ độ ẩm mượt và không bị khô xác lúc nhúng vào nước lẩu sôi.', NULL),
('imp-990934aa20b70964_v4_step_3', 'imp-990934aa20b70964', 3, 'cook', 'Phi thơm tỏi và xào nền cà chua tạo màu', 'Làm nóng chảo với 15 ml dầu ăn còn lại trên lửa vừa, phi thơm phần tỏi băm còn lại trong 30 giây. Trút phần cà chua băm nhỏ và cà chua bổ múi cau vào xào đều 3 phút đến khi cà chua mềm và tiết sắc đỏ cam đẹp mắt.', NULL, 3),
('imp-990934aa20b70964_v4_step_4', 'imp-990934aa20b70964', 4, 'cook', 'Nêm nước lẩu bò đậm đà thanh dịu', 'Vớt bỏ xương ống và xác hành tây từ nồi nước ninh cho gọn nồi, đổ hỗn hợp cà chua xào vào nấu sôi 3 phút. Nêm 30 ml nước mắm ngon, 7 g hạt nêm, 2 g muối hạt còn lại và 8 g đường cát trắng sao cho nước dùng đậm đà thanh ngọt.', NULL, 3),
('imp-990934aa20b70964_v4_step_5', 'imp-990934aa20b70964', 5, 'cook', 'Tạo vị chua thanh từ nước cốt chanh tươi', 'Hạ nhỏ lửa nồi nước dùng rồi từ từ rưới nước cốt 2 quả chanh tươi vào khuấy nhẹ, nếm lại vị chua nhẹ hài hòa với vị ngọt từ xương bò.', 'Chỉ rưới nước cốt chanh sau khi nước dùng đã nêm xong và không đun sôi mạnh để giữ mùi thơm thanh mát của chanh tươi.', NULL),
('imp-990934aa20b70964_v4_step_6', 'imp-990934aa20b70964', 6, 'finish', 'Nhúng bò thái lát cùng nấm và rau thơm ăn nóng', 'Chuyển nồi lẩu lên bếp bàn giữ sôi lăn tăn, thả nấm đùi gà, đầu hành lá, hành lá cắt khúc và 1 g tiêu đen xay vào nấu 3 phút cho nấm chín ngọt. Khi ăn, nhúng từng lát thịt bò cùng hành tây thái lát khoảng 20–30 giây cho thịt vừa chín tới tái hồng mềm ngọt, nhúng rau muống, húng quế và ngò rí thưởng thức nóng kèm bún tươi và 15 ml nước mắm ngon còn lại.', NULL, NULL),
('imp-d0569e8ec34b2bfc_v4_step_1', 'imp-d0569e8ec34b2bfc', 1, 'prep', 'Làm ráo giá đỗ và thái hành tỏi', 'Rửa sạch 200 g giá đỗ tươi, nhặt bỏ rễ dài hoặc vỏ đậu xanh rồi trút ra rổ để thật ráo nước. Tỏi khô băm nhỏ, hành lá tươi cắt khúc dài 3 cm. Thịt thăn bò thấm khô bằng khăn giấy, thái lát mỏng ngang thớ cho mềm.', 'Giá đỗ càng ráo nước thì khi xào lửa lớn càng nhanh chín giòn mà không làm loãng nước sốt trong chảo.', NULL),
('imp-d0569e8ec34b2bfc_v4_step_2', 'imp-d0569e8ec34b2bfc', 2, 'marinate', 'Ướp thịt bò thấm gia vị', 'Cho thịt bò thái lát vào tô cùng 1/3 lượng tỏi băm, 15 ml xì dầu, 10 ml dầu hào, 10 ml rượu Thiệu Hưng, 4 g hạt nêm, 3 g đường cát trắng và 1 g tiêu đen xay. Trộn đều rồi ướp trong 15 phút cho thịt mềm thấm vị đậm đà.', 'Không cho muối ăn vào bước ướp thịt bò để tránh muối rút hết nước khiến thịt bị khô cứng khi xào.', 15),
('imp-d0569e8ec34b2bfc_v4_step_3', 'imp-d0569e8ec34b2bfc', 3, 'cook', 'Xào nhanh thịt bò trên lửa lớn', 'Làm nóng chảo rộng với 10 ml dầu ăn thực vật trên lửa vừa, phi thơm 1/3 lượng tỏi băm trong 20 giây. Sau đó tăng lên lửa lớn, trút thịt bò đã ướp vào đảo nhanh tay khoảng 2 phút đến khi thịt bò vừa săn chín tái đều các mặt thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-d0569e8ec34b2bfc_v4_step_4', 'imp-d0569e8ec34b2bfc', 4, 'cook', 'Xào giá đỗ giữ độ giòn tươi', 'Lau nhanh chảo nếu còn nhiều nước, cho 15 ml dầu ăn thực vật còn lại vào đun nóng rồi phi thơm phần tỏi băm cuối cùng. Tăng lửa lớn, đổ toàn bộ giá đỗ vào xào nhanh tay khoảng 2 phút cùng 2 g muối ăn đến khi cọng giá vừa trong nhẹ, hơi xẹp mà vẫn giòn.', NULL, 2),
('imp-d0569e8ec34b2bfc_v4_step_5', 'imp-d0569e8ec34b2bfc', 5, 'cook', 'Đảo quyện thịt bò và giá đỗ', 'Trút ngay đĩa thịt bò vào chảo giá đỗ, rưới thêm 10 ml xì dầu còn lại quanh thành chảo. Đảo đều tay trên lửa lớn thêm khoảng 1 phút cho thịt bò chín hoàn toàn và gia vị quyện đều vào giá đỗ.', 'Tổng thời gian đảo chung không nên quá 1–2 phút để giá không bị chảy nước và thịt bò giữ trọn độ mềm ngọt.', 1),
('imp-d0569e8ec34b2bfc_v4_step_6', 'imp-d0569e8ec34b2bfc', 6, 'finish', 'Thêm hành lá, dầu mè và hoàn thiện món xào', 'Thả hành lá cắt khúc vào chảo đảo nhanh 20 giây cho hành vừa chín xanh mướt rồi tắt bếp ngay. Rưới 5 ml dầu mè thơm và rắc 0,5 g tiêu đen xay còn lại lên trên, đảo nhẹ một lượt rồi múc bò xào giá đỗ ra đĩa dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-531f59c246a56bcb_v4_step_1', 'imp-531f59c246a56bcb', 1, 'marinate', 'Trộn gia vị và quết thịt với nước cho dẻo', 'Cho 500 g thịt heo xay vào tô lớn cùng 20 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml rượu Thiệu Hưng, tỏi băm nhuyễn và gừng băm nhuyễn, trộn đều. Tiếp theo, rót từng muỗng canh trong 45 ml nước lọc vào tô, dùng đũa khuấy và quết mạnh theo một chiều đến khi nước ngấm hết và thịt dẻo quánh rồi mới thêm lượt nước tiếp theo.', 'Quết thịt theo một chiều với từng ít nước giúp cấu trúc protein liên kết chặt, viên thịt chiên xong sẽ dẻo giòn mà không bị khô bở.', 5),
('imp-531f59c246a56bcb_v4_step_2', 'imp-531f59c246a56bcb', 2, 'marinate', 'Ướp gia vị khô và trộn trứng bột năng', 'Thêm 4 g muối ăn, 8 g đường cát trắng, 1,5 g tiêu trắng xay và 1 g ngũ vị hương vào tô thịt trộn đều, ướp khoảng 15 phút cho ngấm vị. Sau đó đánh tan trứng gà rồi đổ vào tô cùng hành lá thái nhỏ và 15 g bột năng, trộn thật đều đến khi hỗn hợp dẻo mịn đồng nhất.', NULL, 15),
('imp-531f59c246a56bcb_v4_step_3', 'imp-531f59c246a56bcb', 3, 'prep', 'Vo tròn từng viên thịt đều nhau', 'Thoa một lớp dầu ăn thật mỏng lên lòng bàn tay để chống dính, múc từng phần thịt vừa ăn rồi nắm và xoay tròn thành những viên đường kính khoảng 2,5 đến 3 cm xếp đều ra đĩa.', 'Vo các viên thịt kích thước đồng đều giúp toàn bộ mẻ chiên chín cùng lúc, không bị viên sống viên cháy.', NULL),
('imp-531f59c246a56bcb_v4_step_4', 'imp-531f59c246a56bcb', 4, 'cook', 'Làm nóng dầu và chiên vàng các viên thịt', 'Đổ 400 ml dầu ăn thực vật vào nồi hoặc chảo sâu lòng, đun trên lửa vừa đến khi thử đầu đũa tre thấy sủi bọt đều quanh đũa (khoảng 175–180°C). Nhẹ nhàng thả từng mẻ viên thịt vào chiên, giữ khoảng cách thoáng để dầu không bị tụt nhiệt, chiên khoảng 3 phút cho mặt dưới se vàng rồi trở mặt.', NULL, 3),
('imp-531f59c246a56bcb_v4_step_5', 'imp-531f59c246a56bcb', 5, 'cook', 'Chiên chín hoàn toàn bên trong viên thịt', 'Tiếp tục chiên lửa vừa thêm khoảng 3 đến 4 phút nữa, đảo nhẹ liên tục để viên thịt vàng nâu giòn đều các mặt. Kiểm tra độ chín bằng cách cắt thử một viên thấy thịt bên trong chín trắng hoàn toàn, không còn màu hồng sống và tứa nước trong là đạt.', 'Không chiên trên lửa quá lớn vì vỏ ngoài sẽ sậm cháy trước khi nhân thịt bên trong kịp chín kỹ.', 4),
('imp-531f59c246a56bcb_v4_step_6', 'imp-531f59c246a56bcb', 6, 'finish', 'Thấm ráo dầu và dọn nóng', 'Vớt toàn bộ thịt viên chiên ra rổ lưới hoặc đĩa có lót sẵn khăn giấy thấm dầu trong 2 phút cho ráo bớt dầu thừa, sau đó xếp ra đĩa sạch và dọn dùng nóng.', NULL, NULL),
('imp-3767b2e36f535b7b_v4_step_1', 'imp-3767b2e36f535b7b', 1, 'prep', 'Thấm khô ức gà và pha xốt ướp ngũ vị', 'Rửa sạch 700 g ức gà phi lê, dùng khăn giấy thấm thật khô rồi khía nhẹ vài đường nông trên mặt thịt để gia vị thấm sâu. Trong tô nhỏ, khuấy đều 35 ml xì dầu đặc, 20 ml xì dầu nhạt, 12 ml mật ong nguyên chất, 2 g bột ngũ vị hương, tỏi băm nhuyễn, gừng băm nhuyễn, 10 ml dầu mè thơm, 15 ml dầu ăn thực vật và 1,5 g tiêu trắng xay; múc tách riêng 1 muỗng canh hỗn hợp xốt sạch ra chén nhỏ để phết gà khi nướng.', 'Thấm khô hoàn toàn mặt ức gà trước khi ướp giúp hỗn hợp xì dầu ngũ vị bám chặt vào thịt mà không bị trôi loãng.', NULL),
('imp-3767b2e36f535b7b_v4_step_2', 'imp-3767b2e36f535b7b', 2, 'marinate', 'Ướp thịt gà ít nhất 60 phút cho đậm vị', 'Đặt ức gà vào tô lớn hoặc túi zip, đổ toàn bộ phần xốt ướp vào xoa bóp đều khắp các mặt thịt. Đậy kín và ướp trong ngăn mát tủ lạnh ít nhất 1 đến 2 giờ (thỉnh thoảng trở mặt cho gà thấm đều), sau đó lấy ra để nhiệt độ phòng khoảng 20 phút trước khi nướng.', 'Để gà bớt lạnh trước khi vào lò giúp miếng ức gà chín đều từ ngoài vào trong mà không bị khô mặt ngoài.', 60),
('imp-3767b2e36f535b7b_v4_step_3', 'imp-3767b2e36f535b7b', 3, 'cook', 'Nướng mặt thứ nhất ở nhiệt độ vừa', 'Làm nóng lò nướng ở 170°C, lót giấy nến hoặc giấy bạc vào khay rồi xếp các miếng ức gà đã rũ nhẹ phần xốt bám trên bề mặt thành một lớp thưa (bỏ phần nước ướp thịt sống còn dư trong tô). Đặt khay ở rãnh giữa lò, nướng trong 20 phút trên lửa vừa để thịt chín từ từ mà xốt xì dầu không bị cháy khét.', NULL, 20),
('imp-3767b2e36f535b7b_v4_step_4', 'imp-3767b2e36f535b7b', 4, 'cook', 'Lật mặt và phết lớp mật ong bóng đẹp', 'Lấy khay gà ra khỏi lò, nhẹ nhàng lật từng miếng gà sang mặt còn lại. Hòa 8 ml mật ong nguyên chất còn lại với 1 muỗng canh xốt xì dầu sạch đã tách riêng từ bước 1 rồi dùng cọ phết đều lên bề mặt thịt gà.', 'Chỉ phết mật ong ở nửa sau quá trình nướng để tạo lớp caramel nâu bóng đẹp mắt mà không làm đường cháy đắng.', NULL),
('imp-3767b2e36f535b7b_v4_step_5', 'imp-3767b2e36f535b7b', 5, 'cook', 'Nướng hoàn tất đến khi gà chín mềm mọng', 'Đưa khay gà trở lại lò ở 170°C nướng thêm 15 đến 20 phút nữa (có thể tăng 200°C ở 3 phút cuối nếu thích cạnh gà xém nhẹ, đứng canh sát). Kiểm tra phần dày nhất của miếng gà thấy thịt chín trắng hoàn toàn, nước tiết ra trong suốt không còn sắc hồng là đạt.', NULL, 18),
('imp-3767b2e36f535b7b_v4_step_6', 'imp-3767b2e36f535b7b', 6, 'finish', 'Để gà nghỉ, thái lát và rắc hành lá', 'Lấy gà ra khỏi lò để nghỉ trên thớt khoảng 5 phút cho nước thịt ổn định lại bên trong, sau đó thái lát xéo dày 1,5 cm xếp ra đĩa. Chan phần nước xốt nóng thơm tiết ra trong khay nướng lên mặt thịt, rắc hành lá tươi thái nhỏ và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-08b08cad387c7c9f_v4_step_1', 'imp-08b08cad387c7c9f', 1, 'prep', 'Rút nước muối và thấm khô đậu phụ', 'Cắt 3,5 bìa đậu phụ trắng thành các miếng chữ nhật hoặc vuông dày khoảng 2 cm xếp ra khay. Rắc đều 5 g muối ăn lên các mặt đậu, để yên 5 phút cho muối rút bớt ẩm, sau đó dùng khăn giấy lau sạch muối thừa và thấm thật khô từng miếng đậu phụ.', 'Đậu phụ được rút bớt nước và lau sạch muối sẽ ít bắn dầu khi chiên và tạo được lớp vỏ giòn lâu hơn.', 5),
('imp-08b08cad387c7c9f_v4_step_2', 'imp-08b08cad387c7c9f', 2, 'prep', 'Áo lớp bột bắp mỏng và chuẩn bị tỏi hành', 'Đổ 25 g bột bắp ra đĩa rộng, lăn nhẹ từng miếng đậu phụ cho bột phủ kín một lớp mỏng đều rồi giũ nhẹ phần bột thừa. Băm nhuyễn 6 tép tỏi khô, thái nhỏ hành lá tươi và thái lát mỏng 1 quả ớt sừng đỏ.', NULL, NULL),
('imp-08b08cad387c7c9f_v4_step_3', 'imp-08b08cad387c7c9f', 3, 'sauce', 'Dội dầu nóng làm sốt tỏi dầu hào chay', 'Cho tỏi băm nhuyễn, hành lá thái nhỏ và 15 g đường cát trắng vào bát sứ chịu nhiệt. Đun nóng 35 ml dầu ăn thực vật trong chảo nhỏ trên lửa lớn đến khi mặt dầu hơi gợn sóng và bốc khói nhẹ thì tắt bếp, lập tức rưới dầu nóng vào bát tỏi nghe tiếng xèo thơm lừng, khuấy đều rồi thêm 20 ml xì dầu nhạt và 30 ml dầu hào chay nấm đông cô trộn tan thành sốt sánh.', 'Dầu phải thật nóng mới làm chín thơm tỏi băm tức thì; dùng bát sứ hoặc thủy tinh chịu nhiệt để đảm bảo an toàn.', NULL),
('imp-08b08cad387c7c9f_v4_step_4', 'imp-08b08cad387c7c9f', 4, 'cook', 'Chiên vàng giòn mặt đầu tiên của đậu phụ', 'Làm nóng chảo chống dính với 45 ml dầu ăn thực vật còn lại trên lửa vừa-lớn, xếp các miếng đậu phụ đã áo bột vào thành một lớp thoáng. Chiên yên khoảng 4 phút đến khi mặt dưới chuyển vàng nâu giòn rụm rồi mới nhẹ nhàng trở mặt.', 'Không xếp đậu phụ quá chật và không đảo liên tục trong 3 phút đầu để lớp bột bắp không bị dính vỡ.', 4),
('imp-08b08cad387c7c9f_v4_step_5', 'imp-08b08cad387c7c9f', 5, 'cook', 'Chiên giòn các mặt còn lại và thấm dầu', 'Tiếp tục chiên mặt còn lại thêm 4 phút nữa trên lửa vừa đến khi tất cả các mặt miếng đậu đều vàng giòn đều mắt. Gắp đậu phụ ra đĩa có lót sẵn khăn giấy thấm bớt dầu thừa.', NULL, 4),
('imp-08b08cad387c7c9f_v4_step_6', 'imp-08b08cad387c7c9f', 6, 'finish', 'Rưới sốt tỏi nóng và trang trí', 'Xếp đậu phụ chiên giòn ra đĩa sạch, khuấy đều lại bát sốt tỏi rồi rưới phủ lên từng miếng đậu nóng. Rắc hạt mè trắng rang và ớt sừng đỏ thái lát lên trên rồi dùng ngay với cơm trắng.', NULL, NULL),
('imp-cbbfa59518b7d47d_v4_step_1', 'imp-cbbfa59518b7d47d', 1, 'prep', 'Sơ chế hành lá chẻ sợi và băm tỏi', 'Rửa sạch 40 g hành lá tươi, dùng khăn giấy lau thật khô nước để khi phi không bị bắn dầu, sau đó cắt khúc 5 cm và chẻ dọc thành sợi mảnh. Tỏi khô bóc vỏ, băm nhỏ đều tay để khi phi chín vàng đồng loạt.', 'Hành lá phải thật khô ráo trước khi cho vào chảo dầu thì hành mới giòn thơm mà không bị nổ dầu.', NULL),
('imp-cbbfa59518b7d47d_v4_step_2', 'imp-cbbfa59518b7d47d', 2, 'cook', 'Luộc mì trứng và giữ lại nước luộc', 'Đun sôi 1500 ml nước lọc cùng 8 g muối ăn trên lửa lớn, thả 180 g mì trứng khô vào luộc khoảng 5 đến 6 phút đến khi sợi mì vừa chín tới còn độ dai nhẹ. Trước khi vớt mì ra rổ để ráo, múc giữ lại khoảng 60 ml nước luộc mì nóng.', NULL, 6),
('imp-cbbfa59518b7d47d_v4_step_3', 'imp-cbbfa59518b7d47d', 3, 'cook', 'Phi giòn hành lá tạo dầu hành thơm', 'Đun nóng 40 ml dầu ăn thực vật trong chảo rộng trên lửa vừa, thả toàn bộ hành lá chẻ sợi vào đảo đều liên tục khoảng 4 đến 5 phút đến khi hành chuyển màu vàng nâu giòn nhẹ thì gắp hành phi ra bát để riêng, giữ lại toàn bộ phần dầu hành thơm trong chảo.', 'Hạ xuống lửa vừa-nhỏ nếu thấy hành chuyển màu quá nhanh để hành giòn đều mà không bị đắng khét.', 5),
('imp-cbbfa59518b7d47d_v4_step_4', 'imp-cbbfa59518b7d47d', 4, 'cook', 'Phi thơm tỏi băm trong dầu hành', 'Cho tỏi băm nhỏ vào chảo dầu hành đang ấm trên lửa vừa-nhỏ, đảo nhanh tay khoảng 1 đến 2 phút đến khi tỏi vừa chuyển màu vàng nhạt và tỏa mùi thơm nức thì hạ ngay lửa nhỏ.', NULL, 2),
('imp-cbbfa59518b7d47d_v4_step_5', 'imp-cbbfa59518b7d47d', 5, 'sauce', 'Nấu sôi nhẹ sốt xì dầu đường cát', 'Rót 25 ml xì dầu nhạt, 12 ml xì dầu đặc và 5 g đường cát trắng vào chảo tỏi, khuấy đều và đun sôi lăn tăn khoảng 1 phút trên lửa nhỏ đến khi đường tan hết và hỗn hợp sốt hơi sánh bóng rồi tắt bếp.', 'Không đun nước sốt quá cạn ở bước này vì sốt nguội sẽ sệt lại nhanh; giữ độ sánh vừa phải giúp dễ trộn đều với mì.', NULL),
('imp-cbbfa59518b7d47d_v4_step_6', 'imp-cbbfa59518b7d47d', 6, 'finish', 'Trộn mì nóng quyện sốt và rắc hành phi', 'Trút ngay mì trứng đã ráo nước vào chảo sốt còn nóng, rưới thêm 5 ml dầu mè thơm và dùng đũa đảo trộn thật đều cho từng sợi mì áo bóng sốt. Nếu thấy mì hơi khô, thêm từng muỗng canh nước luộc mì đã giữ lại vào trộn đến khi vừa mướt, bày ra đĩa rồi rắc hành phi giòn lên trên và dùng nóng ngay.', NULL, NULL),
('imp-266587069d92cb79_v4_step_1', 'imp-266587069d92cb79', 1, 'prep', 'Làm sạch vỏ cua biển và sơ chế gừng hành', 'Làm lạnh cua sống trong ngăn mát 10 phút cho dịu lại rồi dùng bàn chải chà sạch đất cát ở mai, càng và các kẽ chân dưới vòi nước lạnh chảy, để ráo. Gừng tươi thái lát mỏng một nửa lượng (khoảng 18 g) để lót hấp, phần còn lại băm thật nhuyễn; hành lá thái nhỏ để riêng.', NULL, NULL),
('imp-266587069d92cb79_v4_step_2', 'imp-266587069d92cb79', 2, 'sauce', 'Pha nước chấm giấm đen Trấn Giang gừng băm', 'Trong bát vừa, khuấy tan hoàn toàn 10 g đường nâu với 50 ml giấm đen Trấn Giang, 30 ml giấm gạo, 30 ml xì dầu nhạt và 30 ml nước lọc. Sau đó cho toàn bộ gừng băm nhuyễn và một nửa lượng hành lá thái nhỏ vào trộn đều.', 'Pha nước chấm trước giúp hương thơm của gừng tươi kịp tiết ra hòa quyện vào giấm đen và đường nâu.', NULL),
('imp-266587069d92cb79_v4_step_3', 'imp-266587069d92cb79', 3, 'prep', 'Lót gừng và xếp cua vào xửng hấp', 'Đổ khoảng 770 ml nước lọc vào đáy nồi hấp (mực nước thấp hơn vỉ xửng), đun sôi mạnh trên lửa lớn. Xếp các lát gừng tươi phủ lên mặt vỉ hấp rồi đặt cua lên trên theo tư thế ngửa bụng lên (mai úp xuống) để giữ trọn nước ngọt và gạch cua, rưới đều 15 ml rượu Thiệu Hưng lên mình cua.', 'Đặt cua ngửa bụng khi hấp giúp nước ngọt tự nhiên và gạch béo bên trong mai không bị chảy xuống nước nồi.', NULL),
('imp-266587069d92cb79_v4_step_4', 'imp-266587069d92cb79', 4, 'cook', 'Hấp cua trên lửa lớn đến khi chín đỏ', 'Đậy kín nắp nồi, hấp liên tục trên lửa lớn trong khoảng 9 đến 10 phút tính từ lúc nước sôi mạnh (với cua cỡ 250–350 g/con). Quan sát thấy vỏ mai cua chuyển đỏ cam rực rỡ, thân cua chín săn và phần thịt càng chuyển trắng đục hoàn toàn là cua đã chín.', 'Không mở nắp xửng nhiều lần trong lúc hấp để giữ áp suất hơi nóng ổn định giúp cua chín đều và giữ trọn vị ngọt.', 10),
('imp-266587069d92cb79_v4_step_5', 'imp-266587069d92cb79', 5, 'cook', 'Để ráo hơi nước trên mặt cua', 'Tắt bếp, mở hé nắp cho hơi nóng thoát bớt rồi nhấc cua ra đĩa rộng, để nghỉ khoảng 2 phút cho bề mặt vỏ ráo nước và nguội bớt dễ cầm tay hơn.', NULL, 2),
('imp-266587069d92cb79_v4_step_6', 'imp-266587069d92cb79', 6, 'finish', 'Bày đĩa cua hấp và thưởng thức nóng', 'Rắc phần hành lá thái nhỏ còn lại lên đĩa cua cho đẹp mắt, dọn nóng ngay kèm bát nước chấm giấm đen gừng hành. Khi ăn gỡ bỏ yếm và mang xám hai bên mai, chấm thịt cua vào nước chấm chua ngọt ấm vị gừng.', NULL, NULL),
('imp-b02fdf7cecfae119_v4_step_1', 'imp-b02fdf7cecfae119', 1, 'prep', 'Làm sạch khử tanh và cắt khoanh mực ống', 'Nhẹ nhàng rút đầu và nội tạng mực ống ra khỏi thân, gỡ bỏ túi mực đen cẩn thận tránh làm vỡ, bỏ mắt và nang cứng trong thân. Chà xát đều 8 g muối ăn cùng 10 g gừng tươi đập dập lên khắp mình mực khoảng 2 phút để khử sạch mùi tanh và nhớt, sau đó rửa lại nhiều lần với nước lạnh, để ráo rồi cắt khoanh tròn dày 1,5 cm.', 'Không làm vỡ túi mực khi sơ chế và rửa lại thật sạch muối gừng giúp khoanh mực trắng giòn, thơm ngọt.', NULL),
('imp-b02fdf7cecfae119_v4_step_2', 'imp-b02fdf7cecfae119', 2, 'marinate', 'Ướp mực cùng xì dầu, rượu Thiệu Hưng và gừng sợi', 'Thái sợi mảnh 15 g gừng tươi còn lại và cắt khúc 3 cm phần hành lá tươi. Cho mực vào tô ướp cùng 45 ml xì dầu, 10 ml xì dầu đặc, 15 ml rượu Thiệu Hưng, 25 g đường cát trắng, 1 g tiêu đen xay và gừng thái sợi, trộn đều rồi ướp trong 15 phút cho thấm gia vị.', NULL, 15),
('imp-b02fdf7cecfae119_v4_step_3', 'imp-b02fdf7cecfae119', 3, 'cook', 'Xào săn khoanh mực trên lửa vừa-lớn', 'Làm nóng chảo sâu lòng hoặc nồi đáy dày với 30 ml dầu ăn thực vật trên lửa vừa-lớn, trút toàn bộ tô mực cùng nước ướp vào đảo đều khoảng 3 phút đến khi khoanh mực vừa săn lại và chuyển màu trắng đục.', 'Không nên chần mực qua nước sôi trước khi kho vì mực rất dễ bị co rút và dai khi nấu tiếp.', 3),
('imp-b02fdf7cecfae119_v4_step_4', 'imp-b02fdf7cecfae119', 4, 'cook', 'Thêm nước lọc đun sôi đều vị', 'Rót 100 ml nước lọc vào nồi mực sao cho nước xâm xấp mặt nguyên liệu, bật lửa lớn đun sôi bùng và đảo nhẹ cho nước sốt hòa quyện đều.', NULL, NULL),
('imp-b02fdf7cecfae119_v4_step_5', 'imp-b02fdf7cecfae119', 5, 'cook', 'Kho liu riu đến khi nước sốt sánh nâu bóng', 'Hạ xuống lửa vừa-nhỏ, kho liu riu khoảng 10 đến 12 phút không đậy nắp, thỉnh thoảng đảo nhẹ cho các khoanh mực thấm đều nước sốt. Khi nước kho rút cạn chỉ còn độ sánh sệt màu nâu bóng ôm quanh từng khoanh mực, nếm lại thấy vị mặn ngọt hài hòa là đạt.', 'Canh thời gian kho vừa đủ cho nước sánh lại; tránh kho quá lâu trên 20 phút khiến thịt mực bị cứng dai.', 12),
('imp-b02fdf7cecfae119_v4_step_6', 'imp-b02fdf7cecfae119', 6, 'finish', 'Thêm hành lá, dầu mè và dọn nóng', 'Tắt bếp ngay khi sốt đạt độ sánh mong muốn, rưới 5 ml dầu mè thơm vào cùng hành lá tươi cắt khúc và 0,5 g tiêu đen xay còn lại, đảo nhẹ một lượt rồi múc ra đĩa dùng nóng với cơm trắng.', NULL, NULL),
('imp-4693d6520fbd9d49_v4_step_1', 'imp-4693d6520fbd9d49', 1, 'prep', 'Thái lát thịt bò ngang thớ và chuẩn bị tỏi hành', 'Rửa nhanh 450 g thịt thăn bò, thấm thật khô rồi cho vào ngăn đá 20 phút cho hơi se mặt để dễ thái lát mỏng 4 đến 5 mm theo chiều ngang thớ. Bóc vỏ tỏi khô, chia một nửa băm nhỏ và một nửa thái lát mỏng đều 2 mm; rửa sạch hành lá tươi rồi cắt khúc 3 đến 4 cm.', 'Thái tỏi thành lát mỏng đều giúp khi phi tạo thành từng miếng tỏi giòn rụm vàng đều mà không dễ cháy khét như tỏi băm.', NULL),
('imp-4693d6520fbd9d49_v4_step_2', 'imp-4693d6520fbd9d49', 2, 'marinate', 'Ướp thịt bò với xì dầu và dầu hào', 'Cho thịt bò thái lát vào tô lớn cùng phần tỏi băm nhỏ, 30 ml xì dầu, 10 ml dầu hào, 10 ml dầu ăn thực vật, 2,5 g muối ăn và 1 g tiêu đen xay. Trộn nhẹ cho gia vị bám đều khắp mặt thịt, bọc kín ướp trong ngăn mát 20 phút.', NULL, 20),
('imp-4693d6520fbd9d49_v4_step_3', 'imp-4693d6520fbd9d49', 3, 'cook', 'Phi tỏi thái lát vàng giòn rìa', 'Đặt chảo nhỏ lên bếp với 10 ml dầu ăn thực vật trên lửa vừa-nhỏ, cho toàn bộ tỏi thái lát vào đảo nhẹ liên tục khoảng 3 phút đến khi rìa lát tỏi vừa ngả màu vàng nhạt thơm lừng thì vớt ngay ra đĩa lót khăn giấy cho giòn ráo dầu.', 'Phải vớt tỏi phi ngay khi còn màu vàng nhạt vì lượng dầu nóng bám trên lát tỏi sẽ tiếp tục làm tỏi vàng đậm thêm sau khi vớt.', 3),
('imp-4693d6520fbd9d49_v4_step_4', 'imp-4693d6520fbd9d49', 4, 'cook', 'Làm nóng vỉ nướng hoặc chảo gang lửa lớn', 'Làm nóng vỉ nướng than, bếp nướng điện hoặc chảo gang dày trên lửa lớn trong 5 phút cho bề mặt thật nóng, sau đó phết 5 ml dầu ăn thực vật còn lại lên mặt vỉ để chống dính.', NULL, 5),
('imp-4693d6520fbd9d49_v4_step_5', 'imp-4693d6520fbd9d49', 5, 'cook', 'Nướng nhanh thịt bò cháy cạnh hai mặt', 'Xếp các lát thịt bò lên mặt vỉ nóng thành một lớp thưa không chồng chéo, nướng nhanh trên lửa lớn khoảng 2 phút mỗi mặt đến khi thịt xém vàng nhẹ ở rìa và bên trong chín mềm vừa tới (không còn sắc đỏ sống nếu thích ăn chín kỹ). Nếu nhiều thịt hãy chia làm 2 mẻ nướng.', 'Không xếp các lát thịt quá sát nhau khiến hơi nước bốc lên làm thịt bị hấp mềm thay vì cháy cạnh thơm ngon.', 4),
('imp-4693d6520fbd9d49_v4_step_6', 'imp-4693d6520fbd9d49', 6, 'finish', 'Pha muối tiêu và trình bày đĩa bò nướng', 'Trộn đều 2,5 g muối ăn còn lại với 2 g tiêu đen xay ra chén nhỏ làm đồ chấm. Xếp thịt bò nướng nóng ra đĩa, rắc đều tỏi lát phi vàng giòn cùng hành lá tươi cắt khúc lên trên và dọn dùng nóng ngay.', NULL, NULL),
('imp-dd48c08a9b9ed207_v4_step_1', 'imp-dd48c08a9b9ed207', 1, 'prep', 'Làm sạch khử mùi và thấm khô sườn non', 'Chặt 650 g sườn non thành từng khúc dài khoảng 4 đến 5 cm, cho vào thau cùng 6 g muối ăn chà xát kỹ khắp mặt thịt xương trong 2 phút để khử mùi hôi, sau đó rửa lại nhiều lần bằng nước sạch rồi thấm thật khô bằng khăn giấy.', 'Khúc sườn ráo nước hoàn toàn sẽ giúp gia vị ướp bám chặt và lớp bột chiên không bị tuột khi thả vào dầu.', NULL),
('imp-dd48c08a9b9ed207_v4_step_2', 'imp-dd48c08a9b9ed207', 2, 'marinate', 'Ướp sườn non thấm gia vị ngũ vị', 'Cho sườn vào tô lớn cùng tỏi băm nhuyễn, 30 ml xì dầu, 15 ml dầu hào, 5 g đường cát trắng, 2 g tiêu đen xay, 2 g muối ăn còn lại và 1,5 g ngũ vị hương. Trộn xoa đều từng khúc sườn, bọc kín để ướp trong ngăn mát ít nhất 30 phút (hoặc 2 giờ cho đậm vị).', NULL, 30),
('imp-dd48c08a9b9ed207_v4_step_3', 'imp-dd48c08a9b9ed207', 3, 'prep', 'Pha hỗn hợp trứng gà bột chiên giòn', 'Đập 2 quả trứng gà vào tô lớn, đánh tan đều rồi cho 140 g bột chiên giòn cùng 60 ml nước lọc vào khuấy kỹ đến khi thu được hỗn hợp bột sền sệt, mịn mượt không vón cục.', 'Nếu hỗn hợp quá đặc có thể thêm từng muỗng cà phê nước để lớp bột áo vừa đủ mỏng giòn, không bị dày cộp.', NULL),
('imp-dd48c08a9b9ed207_v4_step_4', 'imp-dd48c08a9b9ed207', 4, 'cook', 'Nhúng bột và chiên sườn trên lửa vừa', 'Đổ 350 ml dầu ăn thực vật vào chảo sâu lòng, đun trên lửa vừa đến khi đầu đũa sủi tăm đều (khoảng 170°C). Gắp từng khúc sườn đã ướp (gạt bớt nước ướp thừa) nhúng ngập vào tô bột chiên giòn rồi thả từng mẻ vào chảo dầu, không xếp chồng lên nhau.', NULL, NULL),
('imp-dd48c08a9b9ed207_v4_step_5', 'imp-dd48c08a9b9ed207', 5, 'cook', 'Chiên chín vàng đều bên trong sườn non', 'Chiên sườn trên lửa vừa khoảng 9 đến 10 phút, thỉnh thoảng lật trở đều các mặt đến khi lớp vỏ ngoài chuyển màu vàng nâu giòn rụm và phần thịt sát xương bên trong chín trắng hoàn toàn không còn máu hồng.', 'Giữ nhiệt dầu ở mức vừa phải giúp sườn non có xương chín kỹ từ bên trong trước khi lớp vỏ ngoài bị sậm màu.', 10),
('imp-dd48c08a9b9ed207_v4_step_6', 'imp-dd48c08a9b9ed207', 6, 'finish', 'Thấm ráo dầu thừa và dọn nóng', 'Vớt các khúc sườn ra đĩa có lót sẵn khăn giấy thấm dầu trong 2 phút để giữ độ giòn lâu, sau đó xếp ra đĩa sạch và dọn dùng nóng với cơm trắng hoặc chấm kèm tương ớt.', NULL, NULL),
('imp-b4924a7d33d5acff_v4_step_1', 'imp-b4924a7d33d5acff', 1, 'prep', 'Vo sạch và ngâm gạo tẻ cho nhanh nhừ', 'Vo sạch 150 g gạo tẻ qua 2 đến 3 lần nước, sau đó ngâm gạo trong nước lạnh khoảng 30 đến 60 phút cho hạt gạo hút nước nở mềm rồi chắt ráo bỏ nước ngâm.', 'Ngâm gạo trước giúp hạt gạo nhanh nở bung khi nấu, nồi cháo sánh mịn đều mà không tốn nhiều thời gian ninh.', 30),
('imp-b4924a7d33d5acff_v4_step_2', 'imp-b4924a7d33d5acff', 2, 'cook', 'Ninh gạo tẻ trên lửa liu riu đến khi sánh mịn', 'Cho gạo đã ngâm cùng 1600 ml nước lọc vào nồi đáy dày, đun sôi bùng trên lửa lớn rồi lập tức hạ xuống lửa nhỏ-vừa. Ninh liu riu khoảng 35 phút, thỉnh thoảng khuấy đều đáy nồi để tránh bén khét cho đến khi hạt gạo nở bung mềm nhừ và nước cháo sánh mịn.', 'Khuấy nhẹ sát đáy nồi khoảng mỗi 7–10 phút trong giai đoạn đầu để tinh bột gạo không lắng dính cháy đáy nồi.', 35),
('imp-b4924a7d33d5acff_v4_step_3', 'imp-b4924a7d33d5acff', 3, 'prep', 'Đánh tan trứng gà và thái hành gừng', 'Trong lúc chờ cháo nhừ, đập 3 quả trứng gà vào bát đánh thật tan đều lòng đỏ và lòng trắng. Rửa sạch hành lá tươi thái nhỏ, đồng thời thái sợi chỉ 10 g gừng tươi để riêng.', NULL, NULL),
('imp-b4924a7d33d5acff_v4_step_4', 'imp-b4924a7d33d5acff', 4, 'cook', 'Rưới trứng tạo vân mây và nêm gia vị', 'Khi nồi cháo đã đạt độ sánh mịn, giữ lửa vừa cho cháo sôi lăn tăn, một tay khuấy nhẹ cháo theo một chiều, tay kia rót từ từ bát trứng đánh tan thành dòng thật mảnh vào nồi để tạo thành những sợi vân trứng mềm mượt. Đun thêm 2 phút cho trứng chín hoàn toàn rồi nêm 4 g muối ăn, 2 g tiêu trắng xay và 3 g hạt nêm khuấy đều.', 'Rưới trứng thành dòng thật mảnh kết hợp khuấy chậm một chiều giúp vân trứng tơi mịn như lụa, không bị vón cục to.', 2),
('imp-b4924a7d33d5acff_v4_step_5', 'imp-b4924a7d33d5acff', 5, 'cook', 'Ủ hành lá với dầu ăn cho cháo bóng mượt', 'Cho hành lá thái nhỏ và 5 ml dầu ăn thực vật vào nồi cháo, khuấy nhẹ thêm một lượt rồi tắt bếp, đậy vung ủ 2 phút để hành lá chín tới giữ màu xanh tươi và bề mặt cháo óng mượt.', NULL, 2),
('imp-b4924a7d33d5acff_v4_step_6', 'imp-b4924a7d33d5acff', 6, 'finish', 'Múc cháo ra tô và rưới xì dầu nhạt', 'Múc cháo trứng vân mây nóng hổi ra tô, rắc gừng tươi thái sợi lên trên, rưới nhẹ vài giọt xì dầu nhạt (hoặc dọn chén xì dầu nhạt bên cạnh để tự nêm) rồi thưởng thức ngay.', NULL, NULL),
('imp-4a712c9f5f9913be_v4_step_1', 'imp-4a712c9f5f9913be', 1, 'prep', 'Sơ chế tôm tươi, cải thìa và nấm', 'Rửa sạch 340 g tôm tươi, bóc vỏ bỏ đầu, rút sạch chỉ đen dọc sống lưng rồi thấm ráo nước. Cải thìa tươi rửa sạch cắt khúc 4 cm, nấm mỡ trắng thái lát mỏng 0,5 cm, gừng tươi và tỏi khô băm nhuyễn, còn hành lá tươi thái nhỏ để riêng.', NULL, NULL),
('imp-4a712c9f5f9913be_v4_step_2', 'imp-4a712c9f5f9913be', 2, 'cook', 'Phi thơm gừng tỏi và xào săn tôm', 'Làm nóng nồi sâu lòng với 10 ml dầu ăn thực vật trên lửa vừa, cho gừng băm và tỏi băm vào phi thơm khoảng 40 giây đến khi dậy mùi mà không cháy xém. Tăng lên lửa lớn, thả tôm vào đảo nhanh khoảng 2 phút đến khi tôm chuyển màu hồng cam săn nhẹ thì gắp riêng ra đĩa.', 'Xào sơ tôm rồi vớt ra giúp tôm thơm mùi gừng tỏi mà không bị nấu quá lâu thành dai cứng trong lúc luộc mì.', 2),
('imp-4a712c9f5f9913be_v4_step_3', 'imp-4a712c9f5f9913be', 3, 'cook', 'Đun sôi nước dùng gà và luộc mì trứng', 'Đổ 700 ml nước dùng gà, 700 ml nước lọc cùng 25 ml xì dầu vào nồi vừa xào tôm, đun sôi bùng trên lửa lớn. Khi nước dùng sôi mạnh, thả 180 g mì trứng khô vào nấu khoảng 5 phút, thỉnh thoảng khuấy nhẹ để các sợi mì tơi đều và vừa chín mềm tới.', 'Chỉ luộc mì đến độ dai vừa phải vì mì sẽ tiếp tục hút thêm nước dùng nóng khi nấu tiếp cùng rau và tôm.', 5),
('imp-4a712c9f5f9913be_v4_step_4', 'imp-4a712c9f5f9913be', 4, 'cook', 'Nấu chín cải thìa và nấm thái lát', 'Thả cải thìa tươi và nấm thái lát vào nồi nước dùng, đun tiếp ở lửa vừa-lớn khoảng 2 phút đến khi cọng cải vừa chín tới xanh mướt và nấm chín mềm ngọt.', 'Cho cải thìa vào sau cùng gần lúc tắt bếp giúp rau giữ màu xanh đẹp mắt và độ giòn thanh tự nhiên.', 2);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-4a712c9f5f9913be_v4_step_5', 'imp-4a712c9f5f9913be', 5, 'cook', 'Thả tôm trở lại và nêm nước dùng', 'Trút toàn bộ phần tôm đã xào trở lại nồi đun thêm 1 phút cho tôm nóng đều, chín chắc hoàn toàn bên trong và hòa quyện vị ngọt vào nước dùng. Nêm 3 g muối ăn và 1 g tiêu trắng xay, nếm thử và điều chỉnh lại cho vừa khẩu vị.', NULL, 1),
('imp-4a712c9f5f9913be_v4_step_6', 'imp-4a712c9f5f9913be', 6, 'finish', 'Múc mì ra tô, rưới dầu mè và dùng nóng', 'Chia đều mì trứng, tôm tươi, cải thìa và nấm ra 3 tô lớn, chan ngập nước dùng gà nóng hổi lên trên. Rưới 5 ml dầu mè thơm và rắc hành lá tươi thái nhỏ lên mặt tô mì rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-a27445c786a3fd67_v4_step_1', 'imp-a27445c786a3fd67', 1, 'prep', 'Thái hành tây, hành lá và tách rời thịt bò', 'Bóc vỏ hành tây, bổ đôi rồi thái lát mỏng đều nhau. Rửa sạch hành lá tươi và thái khoanh xéo mỏng; gọt vỏ gừng tươi và thái sợi thật mảnh (nếu dùng). Cắt 340 g thịt bò thái lát mỏng thành đoạn dài 6–7 cm và tách tơi từng lát.', 'Nếu tự thái thịt bò nguyên khối tại nhà, cho thịt vào ngăn đá khoảng 15 phút cho hơi se cứng rồi thái sẽ cho lát mỏng đều đẹp hơn.', NULL),
('imp-a27445c786a3fd67_v4_step_2', 'imp-a27445c786a3fd67', 2, 'sauce', 'Pha nước sốt om vào chảo nguội', 'Đặt chảo rộng còn nguội (chưa bật bếp) lên bàn, cho 180 ml nước dùng Dashi, 45 ml rượu Sake, 45 ml rượu ngọt Mirin, 60 ml xì dầu Nhật Bản và 18 g đường cát trắng vào khuấy đều cho đường tan bớt.', 'Xếp hành tây và thịt bò vào chảo nước sốt lạnh trước khi bật bếp giúp thịt thấm vị từ từ và giữ kết cấu mềm mại không bị co rút đột ngột.', NULL),
('imp-a27445c786a3fd67_v4_step_3', 'imp-a27445c786a3fd67', 3, 'prep', 'Xếp hành tây và thịt bò lên mặt sốt lạnh', 'Tách rời các lát hành tây rải đều xuống lớp đáy nước sốt, sau đó xếp từng lát thịt bò trải phủ thành một lớp đều lên trên hành tây, tránh để thịt vón cục chồng dày vào một chỗ.', NULL, NULL),
('imp-a27445c786a3fd67_v4_step_4', 'imp-a27445c786a3fd67', 4, 'cook', 'Đậy nắp om mềm thịt bò và hành tây', 'Đậy nắp chảo và bật bếp lửa vừa, đun đến khi nước sốt bắt đầu sôi lăn tăn thì hạ xuống lửa nhỏ, tiếp tục om đậy nắp khoảng 4 phút cho hành tây chín mềm ngọt và thịt bò chín đều.', 'Phải đậy nắp suốt lúc om để giữ hơi ẩm, giúp nước sốt không bị cạn gắt mà vẫn đủ phần nước ngon chan cơm.', 4),
('imp-a27445c786a3fd67_v4_step_5', 'imp-a27445c786a3fd67', 5, 'cook', 'Hớt bọt và thêm hành lá vào nồi', 'Mở nắp, dùng muôi lưới hớt sạch lớp bọt và váng mỡ nổi trên mặt nước sốt cho nước trong thanh. Rắc hành lá thái xéo lên trên thịt bò, đậy nắp om thêm 1 phút cho hành chín tới rồi tắt bếp.', NULL, 1),
('imp-a27445c786a3fd67_v4_step_6', 'imp-a27445c786a3fd67', 6, 'finish', 'Xới cơm nóng, phủ bò hành và thưởng thức', 'Xới 600 g cơm trắng hạt ngắn Nhật nóng hổi ra 3 tô lớn (200 g/tô), rưới trước một muỗng nước sốt om lên mặt cơm, sau đó gắp đều thịt bò và hành tây phủ kín lên trên, chan thêm chút sốt tùy thích và đặt ít gừng tươi thái sợi bên cạnh rồi thưởng thức nóng.', NULL, NULL),
('imp-aba623dc468a9569_v4_step_1', 'imp-aba623dc468a9569', 1, 'prep', 'Ngâm tảo bẹ Kombu lấy nước dùng umami', 'Dùng khăn sạch hơi ẩm lau nhẹ bụi trên 10 g tảo bẹ Kombu khô (giữ nguyên lớp phấn trắng tự nhiên trên bề mặt), sau đó thả vào nồi chứa 1200 ml nước lọc ngâm khoảng 20–30 phút cho tảo nở mềm và tiết vị ngọt.', 'Không rửa trực tiếp tảo bẹ Kombu dưới vòi nước mạnh vì sẽ làm trôi lớp phấn trắng tạo vị umami quý giá.', 20),
('imp-aba623dc468a9569_v4_step_2', 'imp-aba623dc468a9569', 2, 'prep', 'Ướp muối khử tanh cá hồi và sơ chế rau nấm', 'Cắt 400 g cá hồi phi lê thành miếng vuông vừa ăn khoảng 3 cm, rắc đều 2,5 g muối ăn lên các mặt cá và để yên 15 phút cho muối rút bớt dịch tanh. Trong lúc chờ, thái lát nấm đùi gà dày 0,5 cm, thái lát mỏng gừng tươi và cắt xéo hành lá.', NULL, 15),
('imp-aba623dc468a9569_v4_step_3', 'imp-aba623dc468a9569', 3, 'prep', 'Chần nhanh cá hồi theo kỹ thuật Shimofuri', 'Đun sôi một nồi nước nhỏ khác, thả nhanh các miếng cá hồi đã ướp muối vào trụng đúng 30 giây cho bề mặt thịt cá vừa se trắng rồi vớt ngay ra thau nước lạnh, rửa sạch nhẹ nhàng phần váng đục bám quanh cá và để ráo.', 'Kỹ thuật chần nhanh Shimofuri giúp loại bỏ hoàn toàn mùi tanh và giữ cho nồi nước canh sau khi nấu trong veo không bị váng đục.', 1),
('imp-aba623dc468a9569_v4_step_4', 'imp-aba623dc468a9569', 4, 'cook', 'Nấu nước dùng Kombu với nấm đùi gà và gừng', 'Đặt nồi nước ngâm tảo bẹ Kombu lên bếp đun trên lửa vừa; ngay khi thấy đáy nồi sủi bọt tăm lăn tăn chuẩn bị sôi thì vớt bỏ miếng tảo bẹ Kombu ra. Thêm 30 ml rượu Sake Nhật Bản, gừng thái lát và nấm đùi gà vào nồi, đun sôi nhẹ 5 phút và hớt bọt nếu có.', 'Vớt tảo bẹ Kombu ra ngay trước khi nước sôi bùng để tránh nước dùng bị nhớt hoặc có vị chát đắng.', 5),
('imp-aba623dc468a9569_v4_step_5', 'imp-aba623dc468a9569', 5, 'cook', 'Thả cá hồi vào nấu chín tới', 'Thả nhẹ từng miếng cá hồi đã chần vào nồi canh đang sôi lăn tăn, hạ lửa nhỏ và nấu khoảng 6 phút đến khi thịt cá hồi chuyển hồng cam đục đồng nhất, chín mềm tận lõi mà không bị nát vụn, đồng thời hớt sạch bọt nổi.', NULL, 6),
('imp-aba623dc468a9569_v4_step_6', 'imp-aba623dc468a9569', 6, 'finish', 'Nêm xì dầu, muối và hoàn thiện tô canh', 'Nêm 30 ml xì dầu Nhật Bản và 2,5 g muối ăn còn lại vào nồi canh, khuấy nhẹ tay và nếm lại cho vừa vị thanh ngọt. Cho hành lá thái xéo vào nồi rồi tắt bếp ngay, múc canh nóng ra 4 bát và thưởng thức.', NULL, NULL),
('imp-4f398ac575200416_v4_step_1', 'imp-4f398ac575200416', 1, 'prep', 'Sơ chế đùi gà, rau củ và bẻ nhỏ viên cà ri', 'Cắt 360 g thịt đùi gà rút xương thành miếng vừa ăn khoảng 2,5 cm. Bóc vỏ hành tây thái lát mỏng, gọt vỏ cà rốt thái lát hình bán nguyệt dày 0,4 cm, rửa sạch hành lá tươi thái khoanh nhỏ và bẻ nhỏ 75 g viên cà ri Nhật để sẵn. Bắc một nồi lớn chứa khoảng 980 ml nước lọc lên bếp chuẩn bị trụng mì.', NULL, NULL),
('imp-4f398ac575200416_v4_step_2', 'imp-4f398ac575200416', 2, 'cook', 'Xào thơm hành tây và thịt đùi gà', 'Làm nóng nồi đáy dày trên lửa vừa với 20 ml dầu ăn thực vật, cho hành tây thái lát vào xào khoảng 3 phút cho đến khi hành mềm trong và dậy mùi ngọt. Tiếp tục cho thịt đùi gà vào đảo đều đến khi mặt ngoài thịt săn trắng thì rưới 22 ml rượu Sake Nhật Bản vào xào thêm 1 phút.', NULL, 3),
('imp-4f398ac575200416_v4_step_3', 'imp-4f398ac575200416', 3, 'cook', 'Ninh cà rốt và đùi gà với nước dùng Dashi', 'Đổ 300 ml nước dùng Dashi, 600 ml nước lọc cùng cà rốt thái lát vào nồi thịt gà, đun sôi rồi hạ lửa vừa nhỏ, đậy nắp nấu khoảng 7 phút cho đến khi thịt gà chín hoàn toàn tận lõi và cà rốt mềm vừa ăn; hớt sạch bọt nổi nếu có.', 'Pha loãng Dashi với nước lọc và hớt bọt giúp nước cà ri Udon thanh mượt, vừa vị khi hòa cùng viên cà ri Nhật.', 7),
('imp-4f398ac575200416_v4_step_4', 'imp-4f398ac575200416', 4, 'cook', 'Trụng chín sợi mì Udon riêng', 'Trong lúc ninh nước dùng, đun sôi nồi nước lọc đã chuẩn bị và thả 3 gói mì Udon lúa mì vào trụng khoảng 2 phút (hoặc theo đúng hướng dẫn trên bao bì) cho sợi mì tơi mềm và nóng đều, sau đó vớt ra để ráo nước và chia vào 3 tô.', 'Trụng mì Udon ở nồi riêng thay vì thả trực tiếp vào nồi cà ri giúp sợi mì không bị nát và giữ độ dai mượt.', 2),
('imp-4f398ac575200416_v4_step_5', 'imp-4f398ac575200416', 5, 'sauce', 'Hòa tan viên cà ri Nhật và nêm xì dầu', 'Tắt bếp hoặc hạ xuống mức lửa nhỏ nhất ở nồi nước dùng, cho 75 g viên cà ri Nhật vào vá múc canh, khuấy tan dần với nước dùng nóng cho tan mịn hoàn toàn rồi hòa đều vào nồi. Bật lại lửa nhỏ, thêm 10 ml xì dầu Nhật Bản, khuấy đều 2 phút đến khi nước cà ri sánh mịn; nếu muốn sánh hơn có thể hòa tan 10 g bột bắp với 20 ml nước lọc rót từ từ vào khuấy nhẹ.', 'Hòa tan viên cà ri khi nước không sôi mạnh giúp ngăn roux chìm xuống đáy nồi và cháy khét.', 2),
('imp-4f398ac575200416_v4_step_6', 'imp-4f398ac575200416', 6, 'finish', 'Chan nước cà ri lên mì Udon và thưởng thức nóng', 'Chan đều nước sốt cà ri gà nóng hổi kèm thịt và cà rốt phủ ngập mì Udon trong từng tô, rắc hành lá thái nhỏ lên mặt và dùng ngay khi còn nóng.', NULL, NULL),
('imp-b8731e057182331b_v4_step_1', 'imp-b8731e057182331b', 1, 'prep', 'Thái sợi bắp cải và hành lá', 'Tách bỏ lá già bên ngoài của 480 g bắp cải tươi, bổ tư cắt bỏ lõi cứng rồi thái thành sợi mỏng đều khoảng 0,5 cm, rửa sạch và vẩy thật ráo. Rửa sạch hành lá tươi, thấm khô và thái khoanh mỏng.', NULL, NULL),
('imp-b8731e057182331b_v4_step_2', 'imp-b8731e057182331b', 2, 'prep', 'Bóp muối nhẹ cho bắp cải dịu giòn và vắt ráo', 'Cho bắp cải thái sợi vào tô lớn, rắc 2 g muối ăn rồi dùng tay bóp nhẹ nhàng khoảng 1 phút cho muối bám đều, để yên 5 phút cho bắp cải ra bớt nước hăng. Sau đó dùng tay vắt nhẹ cho ráo nước nhưng không vắt quá kiệt để bắp cải vẫn giữ độ giòn mát.', 'Vắt bắp cải vừa ráo tay giúp sợi rau giòn ngọt và thấm sốt đậm đà mà không bị dai hay làm loãng sốt trộn.', 5),
('imp-b8731e057182331b_v4_step_3', 'imp-b8731e057182331b', 3, 'prep', 'Rang thơm và giã dập hạt mè trắng', 'Cho 18 g hạt mè trắng vào chảo khô, rang trên lửa nhỏ khoảng 3 phút và đảo đều tay đến khi mè vàng nhạt dậy mùi thơm bùi thì trút ra đĩa cho nguội bớt. Cho 2/3 lượng mè vào cối giã dập thơm dầu, giữ lại 1/3 nguyên hạt để rắc mặt.', 'Đảo liên tục trên lửa nhỏ khi rang vì hạt mè rất nhỏ và dễ cháy khét nếu để chảo quá nóng.', 3),
('imp-b8731e057182331b_v4_step_4', 'imp-b8731e057182331b', 4, 'sauce', 'Pha sốt trộn mè xì dầu giấm gạo', 'Trong tô nhỏ, trộn đều phần hạt mè trắng đã giã dập với 15 ml xì dầu Nhật Bản, 10 g đường cát trắng, 8 ml dầu mè thơm và 10 ml giấm gạo Nhật đến khi đường tan hết tạo thành hỗn hợp sốt sánh thơm.', 'Khuấy kỹ đến khi đường tan hoàn toàn để khi trộn gia vị bám đều lên từng sợi bắp cải.', NULL),
('imp-b8731e057182331b_v4_step_5', 'imp-b8731e057182331b', 5, 'prep', 'Trộn đều bắp cải với hành lá và sốt mè', 'Cho bắp cải đã vắt ráo và hành lá thái mỏng vào tô lớn, rưới đều toàn bộ sốt mè lên trên và trộn đều tay cho sốt phủ kín từng sợi rau.', NULL, NULL),
('imp-b8731e057182331b_v4_step_6', 'imp-b8731e057182331b', 6, 'finish', 'Ủ thấm vị, rắc mè nguyên hạt và bày đĩa', 'Để bắp cải trộn nghỉ khoảng 3 phút cho gia vị thấm sâu rồi đảo nhẹ lại lần cuối, bày ra đĩa, rắc nốt phần hạt mè trắng nguyên hạt lên trên và thưởng thức mát.', NULL, NULL),
('imp-f04b28987d7cd34a_v4_step_1', 'imp-f04b28987d7cd34a', 1, 'prep', 'Xả băng và cắt tách nửa vỏ chân cua', 'Nếu dùng chân cua đông lạnh, xả nhanh dưới vòi nước chảy cho sạch lớp băng bọc ngoài rồi để rã đông hoàn toàn và thấm ráo. Dùng kéo bếp sắc cắt dọc hai bên mép mỗi chân cua, nhẹ nhàng tách bỏ nửa mặt vỏ phía trên để lộ phần thịt cua bên trong và dùng khăn giấy thấm khô nước đọng.', 'Cắt mở sẵn nửa vỏ trước khi nướng giúp người ăn thưởng thức dễ dàng mà không bị bỏng tay khi tách vỏ nóng.', NULL),
('imp-f04b28987d7cd34a_v4_step_2', 'imp-f04b28987d7cd34a', 2, 'marinate', 'Rưới rượu Sake và rắc muối biển thô lên vỏ cua', 'Rưới đều 30 ml rượu Sake Nhật Bản lên phần thịt cua đã lộ mặt để khử mùi tanh hải sản và giữ độ mọng nước. Rắc đều 15 g muối ăn hạt thô lên khắp mặt vỏ và viền cua; đồng thời thái nhỏ hành lá tươi và cắt múi cau quả chanh vàng để sẵn.', 'Rắc muối chủ yếu lên mặt vỏ giúp tạo lớp hương biển thơm mặn tự nhiên mà thịt cua bên trong vẫn ngọt thanh, không bị gắt.', NULL),
('imp-f04b28987d7cd34a_v4_step_3', 'imp-f04b28987d7cd34a', 3, 'cook', 'Làm nóng vỉ nướng than hoặc lò nướng', 'Làm nóng bếp than hoa hoặc vỉ nướng điện ở mức nhiệt vừa lớn trong khoảng 4 phút cho mặt vỉ thật nóng đều.', NULL, NULL),
('imp-f04b28987d7cd34a_v4_step_4', 'imp-f04b28987d7cd34a', 4, 'cook', 'Nướng cua úp mặt vỏ trước trong 5 phút', 'Đặt các chân cua lên vỉ với phần vỏ bên dưới hướng xuống lửa, nướng khoảng 5 phút cho vỏ cua chuyển màu đỏ cam rực, hơi xém cạnh và phần nước ngọt trong vỏ bắt đầu sôi lăn tăn.', NULL, 5),
('imp-f04b28987d7cd34a_v4_step_5', 'imp-f04b28987d7cd34a', 5, 'cook', 'Phết bơ lạt và nướng chín tới thịt cua', 'Lật hoặc giữ nguyên mặt thịt hướng lên tùy độ nóng vỉ, đặt 20 g bơ lạt cắt nhỏ lên mặt thịt cua rồi nướng tiếp trên lửa vừa thêm 4–5 phút đến khi thịt cua chuyển màu trắng đục săn chắc hoàn toàn và bơ tan thơm lừng.', 'Không nướng quá lâu sau khi thịt cua đã đục săn để tránh làm thịt bị khô xơ và mất nước ngọt tự nhiên.', 5),
('imp-f04b28987d7cd34a_v4_step_6', 'imp-f04b28987d7cd34a', 6, 'finish', 'Bày đĩa, rắc hành lá và thưởng thức kèm chanh xì dầu', 'Gắp cua nướng ra đĩa lớn, rắc hành lá thái nhỏ lên mặt thịt cua, xếp các múi chanh vàng xung quanh và dọn kèm chén xì dầu Nhật Bản để vắt chanh chấm thưởng thức nóng.', NULL, NULL),
('imp-bf6c9c4d92b2e04c_v4_step_1', 'imp-bf6c9c4d92b2e04c', 1, 'prep', 'Cắt tỉa và làm sạch tôm tươi với muối', 'Dùng kéo cắt gọn phần râu, chân và gai nhọn ở đuôi của 300 g tôm tươi nguyên con, dùng tăm xiên qua đốt lưng thứ 2 rút bỏ chỉ đen. Xát nhẹ tôm với 5 g muối ăn rồi rửa thật sạch dưới vòi nước lạnh và để ráo.', NULL, NULL),
('imp-bf6c9c4d92b2e04c_v4_step_2', 'imp-bf6c9c4d92b2e04c', 2, 'prep', 'Thái gừng tươi hai kiểu và cắt hành lá', 'Gọt vỏ 45 g gừng tươi: lấy 25 g thái lát mỏng 0,5 cm để om lấy hương, 20 g còn lại thái sợi thật mảnh và ngâm nhanh qua nước mát cho giòn bớt hăng. Rửa sạch hành lá tươi và thái khoanh mỏng.', NULL, NULL),
('imp-bf6c9c4d92b2e04c_v4_step_3', 'imp-bf6c9c4d92b2e04c', 3, 'sauce', 'Đun sôi hỗn hợp nước om Nhật Bản', 'Cho 300 ml nước lọc, 45 ml rượu Sake Nhật Bản, 45 ml rượu ngọt Mirin, 45 ml xì dầu Nhật Bản và 18 g đường cát trắng vào nồi nông rộng đáy, khuấy cho đường tan bớt rồi đun trên lửa vừa đến khi sôi. Thả 25 g gừng thái lát vào nồi nước om.', 'Dùng nồi đáy rộng để xếp tôm thành một lớp phẳng giúp từng con tôm ngập đều trong nước sốt mà không bị dập nát.', NULL),
('imp-bf6c9c4d92b2e04c_v4_step_4', 'imp-bf6c9c4d92b2e04c', 4, 'cook', 'Xếp tôm om thấm vị trong 5 phút', 'Khi nước om sôi đều trở lại, nhẹ nhàng xếp tôm thành một lớp trong nồi, đậy hé vung (hoặc đặt giấy bạc khoét lỗ phủ nhẹ mặt tôm) và om trên lửa vừa khoảng 5 phút cho đến khi vỏ tôm đỏ au, thịt chín đục săn chắc; trong lúc om dùng muôi hớt sạch bọt nổi.', 'Tôm chín nhanh nên chỉ om đúng khoảng 5 phút trên lửa vừa để thịt giữ độ giòn ngọt, tránh om quá lâu làm tôm dai.', 5),
('imp-bf6c9c4d92b2e04c_v4_step_5', 'imp-bf6c9c4d92b2e04c', 5, 'cook', 'Tắt bếp ngâm ủ cho tôm ngấm sâu nước sốt', 'Tắt bếp và giữ nguyên tôm trong nồi nước om ấm khoảng 8–10 phút để tôm từ từ hút ngược hương vị gừng xì dầu ngọt thanh vào tận bên trong thịt.', 'Bước ngâm ủ sau khi tắt bếp là bí quyết của món om Nhật giúp hải sản thấm vị sâu mà thịt không bị co khô do nhiệt.', 8),
('imp-bf6c9c4d92b2e04c_v4_step_6', 'imp-bf6c9c4d92b2e04c', 6, 'finish', 'Bày đĩa, rắc gừng sợi và hành lá thưởng thức', 'Gắp tôm om xếp gọn ra đĩa sâu lòng, rưới 2–3 muỗng canh nước om ấm lên trên, phủ phần gừng tươi thái sợi mảnh cùng hành lá thái nhỏ lên mặt và dùng nóng với cơm trắng.', NULL, NULL),
('imp-92aabff659e3c551_v4_step_1', 'imp-92aabff659e3c551', 1, 'prep', 'Thấm khô thịt đùi gà và trộn hỗn hợp bột áo', 'Dùng khăn giấy thấm thật khô hai mặt 550 g thịt đùi gà rút xương rồi cắt thành miếng vừa ăn cỡ 4 cm. Trong tô lớn, trộn đều 32 g bột bắp, 31 g bột mì đa dụng, 2 g bột tỏi, 2 g muối ăn và 1 g tiêu đen xay. Lăn từng miếng gà qua tô bột khô cho áo một lớp mỏng đều rồi giũ nhẹ cho rơi hết bột thừa.', 'Thịt gà ráo nước và lớp bột áo mỏng vừa phải sẽ giúp gà áp chảo giòn rụm mà không bị bở bột khi gặp sốt.', NULL),
('imp-92aabff659e3c551_v4_step_2', 'imp-92aabff659e3c551', 2, 'sauce', 'Băm nhuyễn tỏi và khuấy sẵn chén sốt mật ong xì dầu', 'Băm nhuyễn 37 g tỏi khô và thái nhỏ hành lá. Trong bát con, khuấy tan đều 50 ml xì dầu đặc, 60 ml nước lọc, 30 ml mật ong nguyên chất, 30 ml giấm gạo, 25 g đường nâu, 5 ml dầu mè rang và 2 g ớt vảy khô đến khi đường tan hết.', NULL, NULL),
('imp-92aabff659e3c551_v4_step_3', 'imp-92aabff659e3c551', 3, 'cook', 'Áp chảo thịt đùi gà vàng giòn và chín hoàn toàn', 'Làm nóng chảo rộng đáy phẳng trên lửa vừa–lớn với 20 ml dầu ăn đến khi dầu hơi gợn sóng. Xếp gà thành một lớp phẳng (mặt da úp xuống trước), áp chảo khoảng 3 phút mỗi mặt đến khi lớp vỏ vàng giòn, thịt bên trong chín trắng hoàn toàn và nước thịt trong (không còn hồng đỏ ở lõi).', 'Không xếp chồng miếng gà quá dày trong chảo vì hơi nước tích tụ sẽ làm lớp bột bị mềm ỉu thay vì giòn.', 6),
('imp-92aabff659e3c551_v4_step_4', 'imp-92aabff659e3c551', 4, 'cook', 'Phi thơm tỏi băm ngay trên chảo nóng', 'Gạt nhẹ các miếng gà sang mép chảo, thả toàn bộ tỏi băm vào phần dầu nóng giữa chảo và đảo nhanh tay khoảng 30 giây đến khi tỏi dậy mùi thơm nức mà chưa kịp chuyển sậm cháy.', 'Tỏi băm rất dễ cháy đắng trên chảo nóng; ngay khi vừa thấy mùi thơm bốc lên hãy đổ bát sốt vào liền.', NULL),
('imp-92aabff659e3c551_v4_step_5', 'imp-92aabff659e3c551', 5, 'cook', 'Rim gà với sốt tỏi mật ong đến khi sánh bóng', 'Đổ chén sốt đã pha vào chảo, hạ xuống lửa vừa và đảo đều liên tục khoảng 4–5 phút đến khi nước sốt sôi nhẹ, keo sánh lại thành lớp men nâu cánh gián bóng mượt bám chặt quanh từng miếng gà.', NULL, 5),
('imp-92aabff659e3c551_v4_step_6', 'imp-92aabff659e3c551', 6, 'finish', 'Bày đĩa, rắc hành lá và hạt mè trang trí', 'Tắt bếp, gắp gà ra đĩa sâu lòng rồi rưới hết phần sốt tỏi sánh trong chảo phủ lên trên. Rắc hành lá thái nhỏ cùng hạt mè trắng rang tùy thích và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-4b592ae31a81a527_v4_step_1', 'imp-4b592ae31a81a527', 1, 'prep', 'Thấm sạch thịt bò và sơ chế nguyên liệu thơm', 'Dùng khăn giấy lau sạch phần nước đỏ trên bề mặt 550 g thịt bò rồi cắt thành khối vuông lớn cỡ 5x5 cm để thịt giữ được thớ dài đẹp mắt sau khi hầm. Bóc vỏ giữ nguyên tép tỏi khô (chia riêng 20 g để hầm nước đầu và 30 g để kho sau), cắt khúc hành lá, thái lát gừng tươi và cắt khúc 2 cm ớt sừng tươi.', 'Cắt thịt bò thành khối lớn trước khi hầm giúp các thớ thịt dài đều, khi xé tay sẽ mềm tơi và không bị vụn nát.', NULL),
('imp-4b592ae31a81a527_v4_step_2', 'imp-4b592ae31a81a527', 2, 'cook', 'Hầm mềm thịt bò với hành lá, gừng và tỏi khử mùi', 'Cho thịt bò và 1.000 ml nước lọc vào nồi sâu lòng, đun lửa lớn 4 phút đến khi sôi mạnh rồi hớt sạch bọt nổi. Hạ xuống lửa vừa, thả hành lá, gừng tươi và 20 g tỏi khô vào hầm đậy nắp 30 phút cho thịt chín mềm. Vớt bỏ toàn bộ hành lá, gừng và 20 g tỏi đã hầm để nước dùng thật trong.', 'Vớt bỏ phần rau củ hầm nước đầu giúp nước kho thanh vị, không bị đắng hay đục khi cô đặc ở bước sau.', 30),
('imp-4b592ae31a81a527_v4_step_3', 'imp-4b592ae31a81a527', 3, 'cook', 'Kho thịt bò với xì dầu và đường đến khi cạn một nửa', 'Rót 110 ml xì dầu và cho 28 g đường cát trắng vào nồi thịt bò đang sôi, khuấy nhẹ cho đường tan hết. Tiếp tục kho trên lửa vừa–nhỏ không đậy nắp trong 30 phút đến khi nước kho cạn còn khoảng một nửa và khối thịt ngấm màu nâu đậm đẹp mắt.', NULL, 30),
('imp-4b592ae31a81a527_v4_step_4', 'imp-4b592ae31a81a527', 4, 'cook', 'Kho tỏi nguyên tép bùi thơm và ớt sừng tươi', 'Thả 30 g tỏi nguyên tép còn lại vào nồi kho thêm 10 phút cho tỏi chín bùi thấm vị tương. Cuối cùng cho ớt sừng tươi cắt khúc và 1 g tiêu đen xay vào đun thêm 3 phút cho dậy hương cay nhẹ rồi tắt bếp.', NULL, 13),
('imp-4b592ae31a81a527_v4_step_5', 'imp-4b592ae31a81a527', 5, 'finish', 'Vớt thịt bò xé dọc thớ và chan nước kho', 'Gắp các khối thịt bò ra đĩa đợi nguội bớt khoảng 5 phút rồi dùng tay xé dọc theo thớ thịt thành từng miếng dày cỡ 1 cm.', 'Xé thịt dọc theo chiều thớ tự nhiên giúp thịt bò kho giữ được độ mềm dai hấp dẫn và dễ thấm nước tương khi chấm.', 5),
('imp-4b592ae31a81a527_v4_step_6', 'imp-4b592ae31a81a527', 6, 'finish', 'Trình bày đĩa thịt bò kho tương Hàn Quốc', 'Xếp thịt bò xé lên đĩa sâu lòng, gắp tỏi kho và ớt sừng bày xung quanh rồi rưới ngập nước kho xì dầu đậm đà lên trên. Dọn ăn cùng cơm trắng nóng.', NULL, NULL),
('imp-72e70eb4e8fba4db_v4_step_1', 'imp-72e70eb4e8fba4db', 1, 'marinate', 'Làm sạch tôm và ướp cùng nước kim chi, tỏi gừng', 'Tôm tươi bóc vỏ, rút sạch chỉ đen dọc lưng, rửa qua nước lạnh rồi thấm thật khô bằng khăn giấy. Cắt kim chi cải thảo thành miếng vừa ăn và chắt riêng 25 ml nước kim chi. Trộn tôm trong tô với tỏi băm, gừng tươi băm nhuyễn, 25 ml nước kim chi và 1 g tiêu đen xay (nếu dùng), ướp trong ngăn mát 15 phút cho thấm vị.', 'Thấm thật khô tôm trước khi ướp và áp chảo giúp tôm xém mặt nhanh, giòn ngọt và không ra nhiều nước.', 15),
('imp-72e70eb4e8fba4db_v4_step_2', 'imp-72e70eb4e8fba4db', 2, 'prep', 'Thái cải thảo, ớt chuông và hành lá', 'Cải thảo rửa sạch, thái sợi bản 1 cm cho nhanh chín; ớt chuông đỏ bỏ lõi hạt, thái sợi dài vừa ăn; hành lá rửa sạch, cắt khúc 3–4 cm để riêng.', NULL, NULL),
('imp-72e70eb4e8fba4db_v4_step_3', 'imp-72e70eb4e8fba4db', 3, 'cook', 'Áp chảo tôm với bơ lạt đến khi chín hồng', 'Làm nóng chảo rộng trên lửa vừa, thả 25 g bơ lạt vào đun tan chảy hoàn toàn. Xếp tôm đã ướp thành một lớp và áp chảo khoảng 2 phút mỗi mặt đến khi tôm chuyển màu hồng cam tươi, thân cong săn lại và phần thịt đục chín hoàn toàn (không còn trong). Gắp tôm ra đĩa riêng, giữ lại phần bơ thơm trong chảo.', 'Vớt tôm ra trước khi xào rau giúp tôm không bị nấu quá lửa dẫn đến dai và mất độ giòn.', 4),
('imp-72e70eb4e8fba4db_v4_step_4', 'imp-72e70eb4e8fba4db', 4, 'cook', 'Xào cải thảo và ớt chuông giữ độ giòn tươi', 'Thêm 10 ml dầu ăn vào chảo bơ, tăng bếp lên lửa vừa–lớn rồi trút cải thảo và ớt chuông đỏ vào đảo nhanh tay khoảng 3 phút cho rau vừa chín tới vẫn giữ màu tươi và độ giòn nhẹ (rắc thêm chút muối ăn nếu thích vị đậm hơn).', NULL, 3),
('imp-72e70eb4e8fba4db_v4_step_5', 'imp-72e70eb4e8fba4db', 5, 'cook', 'Xào kim chi với xì dầu và trộn lại cùng tôm', 'Thả kim chi cải thảo đã cắt khúc cùng 30 ml xì dầu vào chảo rau, đảo đều khoảng 1 phút cho kim chi nóng dậy mùi thơm mà vẫn giữ được độ giòn chua đặc trưng. Tắt bếp rồi trút toàn bộ tôm đã áp chảo trở lại chảo, đảo nhanh tay cho tôm quyện đều sốt.', 'Chỉ cho kim chi vào xào ngắn 1 phút ở cuối để giữ trọn độ giòn và vị chua thanh tươi mới.', 1),
('imp-72e70eb4e8fba4db_v4_step_6', 'imp-72e70eb4e8fba4db', 6, 'finish', 'Rưới dầu mè, rắc hành lá và mè rang hoàn thiện', 'Rưới 8 ml dầu mè rang lên khắp mặt chảo, cho hành lá cắt khúc vào đảo đều lần cuối. Bày tôm xào kim chi ra đĩa, rắc hạt mè trắng rang tùy thích và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-88b58c0233dec53e_v4_step_1', 'imp-88b58c0233dec53e', 1, 'prep', 'Cắt nhỏ kim chi và thái nhuyễn hành lá', 'Gắp 150 g kim chi cải thảo ra thớt, vắt nhẹ lấy khoảng 25 ml nước kim chi để riêng rồi cắt phần cái thành miếng nhỏ cỡ 1,5 cm để dễ hòa quyện với trứng. Hành lá rửa sạch, thái nhuyễn để rắc hoàn thiện.', NULL, NULL),
('imp-88b58c0233dec53e_v4_step_2', 'imp-88b58c0233dec53e', 2, 'prep', 'Đánh tan trứng gà với dầu mè và gia vị', 'Đập 6 quả trứng gà vào tô lớn, thêm 4 ml dầu mè rang, 5 ml xì dầu (tùy chọn), 1,5 g muối ăn và 1 g tiêu đen xay. Dùng đũa hoặc phới lồng đánh đều tay đến khi lòng trắng và lòng đỏ hòa quyện hoàn toàn, nổi bọt nhẹ.', 'Không cho quá nhiều muối vì kim chi và xì dầu đã mặn sẵn; giữ lại phần nước kim chi để rưới hoặc nêm nhẹ sau cùng giúp trứng không bị vón tách nước.', NULL),
('imp-88b58c0233dec53e_v4_step_3', 'imp-88b58c0233dec53e', 3, 'cook', 'Xào thơm kim chi trên chảo chống dính', 'Làm nóng chảo chống dính trên lửa vừa với 20 ml dầu ăn, cho kim chi cắt nhỏ vào xào đều trong 2 phút đến khi kim chi săn ráo và dậy mùi chua cay thơm nồng.', NULL, 2),
('imp-88b58c0233dec53e_v4_step_4', 'imp-88b58c0233dec53e', 4, 'cook', 'Đổ trứng và đảo nhẹ ở lửa nhỏ tạo mảng mềm mịn', 'Hạ bếp xuống lửa nhỏ, rót từ từ tô trứng đã đánh tan vào chảo kim chi rồi rưới nhẹ 25 ml nước kim chi lên trên. Dùng phới silicon gạt nhẹ nhàng từ mép chảo vào giữa theo từng đường chậm rãi trong 3–4 phút cho trứng đông thành từng mảng bông mềm, ẩm mướt.', 'Giữ lửa nhỏ và đảo chậm tay là bí quyết giúp trứng chín mềm mịn như lụa, không bị khô xác hay cháy đáy.', 4),
('imp-88b58c0233dec53e_v4_step_5', 'imp-88b58c0233dec53e', 5, 'finish', 'Tắt bếp sớm tận dụng nhiệt dư', 'Khi mặt trứng vừa se lại nhưng vẫn còn hơi bóng ẩm khoảng 90%, tắt bếp ngay và đảo nhẹ thêm 10 giây để nhiệt dư trong chảo làm trứng chín vừa tới hoàn hảo mà không bị dai.', 'Không đợi trứng khô hẳn trên bếp mới tắt vì hơi nóng của chảo sẽ tiếp tục làm trứng cứng và bớt béo.', NULL),
('imp-88b58c0233dec53e_v4_step_6', 'imp-88b58c0233dec53e', 6, 'finish', 'Bày đĩa, rắc hành lá và mè rang dùng nóng', 'Trút trứng xào kim chi ra đĩa, rắc hành lá thái nhuyễn và hạt mè trắng rang tùy thích lên trên rồi dọn ăn nóng ngay với cơm trắng.', NULL, NULL),
('imp-e5d49dd8dc1449d1_v4_step_1', 'imp-e5d49dd8dc1449d1', 1, 'marinate', 'Sơ chế và ướp thịt ba chỉ khử mùi với Mirin', 'Thịt ba chỉ heo rửa sạch, thấm khô rồi cắt thành từng miếng dày 1,5 cm, dài 6 cm. Cho thịt vào tô ướp cùng 30 ml rượu Mirin Nhật và 1 g tiêu đen xay, trộn đều rồi để nghỉ 10 phút cho thịt thơm và nhanh mềm khi kho.', 'Nên chọn loại kim chi cải thảo đã lên men chua kỹ ít nhất 3–4 tuần thì khi kho cùng thịt ba chỉ mới dậy được vị chua sâu đặc trưng.', 10),
('imp-e5d49dd8dc1449d1_v4_step_2', 'imp-e5d49dd8dc1449d1', 2, 'sauce', 'Pha sốt tương Doenjang ớt bột và thái hành', 'Băm nhuyễn gừng tươi và tỏi khô, trộn đều trong chén nhỏ với 8 g ớt bột Hàn Quốc (Gochugaru), 15 ml xì dầu, 10 g tương đậu tương Hàn (Doenjang) và 6 g đường cát trắng thành hỗn hợp sốt sệt. Thái lát mỏng hành tây, thái vát hành lá và ớt sừng tươi.', NULL, NULL),
('imp-e5d49dd8dc1449d1_v4_step_3', 'imp-e5d49dd8dc1449d1', 3, 'cook', 'Xếp lớp kim chi, thịt ba chỉ và rưới sốt vào nồi kho', 'Xếp toàn bộ 750 g kim chi cải thảo cùng nước kim chi xuống đáy nồi gang hoặc nồi đáy dày, xếp thịt ba chỉ đã ướp lên trên mặt kim chi rồi rải đều hành tây thái lát. Phết hết phần sốt tương đã trộn lên trên thịt và từ từ rót 250 ml nước lọc (hoặc nước vo gạo lần hai) vào quanh thành nồi.', 'Xếp kim chi lót dưới đáy và đặt thịt lên trên giúp mỡ ba chỉ tiết xuống thấm vào từng bẹ kim chi, đồng thời ngăn thịt bị bén cháy đáy nồi.', NULL),
('imp-e5d49dd8dc1449d1_v4_step_4', 'imp-e5d49dd8dc1449d1', 4, 'cook', 'Đun sôi bùng và kho liu riu đến khi thịt mềm tan', 'Đậy kín nắp nồi, đun trên lửa lớn khoảng 5 phút cho nước kho sôi bùng lên. Sau đó hạ xuống lửa nhỏ, tiếp tục kho liu riu đậy nắp trong 55 phút, thỉnh thoảng mở nắp múc nước kho rưới lên mặt thịt cho đến khi thịt ba chỉ chín mềm nhừ hoàn toàn và kim chi chuyển màu trong mướt.', 'Nếu thấy nước cạn nhanh khi kho gần đủ thời gian, có thể châm thêm 50 ml nước nóng để món kho giữ được độ sánh ẩm.', 55),
('imp-e5d49dd8dc1449d1_v4_step_5', 'imp-e5d49dd8dc1449d1', 5, 'finish', 'Cân chỉnh vị cuối và cắt kim chi vừa ăn', 'Mở nắp nếm thử nước kho: nếu kim chi quá chua có thể thêm một chút đường, còn nếu nhạt thì chỉnh thêm ít xì dầu. Dùng kéo bếp và kẹp gắp cắt kim chi trong nồi thành những khúc ngắn vừa gắp.', NULL, NULL),
('imp-e5d49dd8dc1449d1_v4_step_6', 'imp-e5d49dd8dc1449d1', 6, 'finish', 'Rắc hành lá, ớt sừng và dọn nóng cùng cơm', 'Tắt bếp, rắc hành lá và ớt sừng tươi thái lát lên mặt nồi thịt ba chỉ kho kim chi. Dọn nóng trực tiếp hoặc múc ra đĩa sâu lòng để thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-daec3b038c4f43af_v4_step_1', 'imp-daec3b038c4f43af', 1, 'prep', 'Làm sạch, khứa thân và ướp cá thu với muối, rượu', 'Rửa sạch cá thu Nhật cả ngoài da lẫn phần màng đen dọc sống lưng trong bụng cá, dùng khăn giấy thấm thật khô nước. Khứa 3–4 đường chéo sâu vừa phải lên mỗi bên thân cá để cá chín đều và không bị nổ da. Thoa đều 30 ml rượu gạo nấu ăn (nếu dùng) để 10 phút rồi thấm khô lại, sau đó phết 20 ml dầu ăn và rắc đều 4 g muối ăn lên cả hai mặt cá.', 'Thấm thật khô thân cá và phết lớp dầu ăn mỏng lên da cá là bí quyết giúp da cá giòn rụm và không bị dính rách vào vỉ nướng.', 10),
('imp-daec3b038c4f43af_v4_step_2', 'imp-daec3b038c4f43af', 2, 'sauce', 'Pha chén nước tương xì dầu tỏi ớt chanh tươi', 'Băm thật nhuyễn tỏi khô, thái nhỏ hành lá và ngò rí, vắt chanh tươi lấy khoảng 25 ml nước cốt (bỏ hạt). Trong chén, khuấy tan 55 ml xì dầu nhạt, 15 ml nước lọc, nước cốt chanh, tỏi băm, 4 g ớt bột Hàn Quốc (Gochugaru), hành lá thái nhỏ, 10 ml dầu mè rang và 5 g hạt mè trắng rang giã dập.', NULL, NULL),
('imp-daec3b038c4f43af_v4_step_3', 'imp-daec3b038c4f43af', 3, 'cook', 'Làm nóng vỉ nướng và nướng vàng mặt đầu tiên', 'Làm nóng vỉ nướng (hoặc lò nướng chế độ 220°C) và phết 10 ml dầu ăn còn lại lên bề mặt vỉ. Đặt cá thu lên vỉ, nướng ở lửa vừa–lớn khoảng 7 phút cho đến khi lớp da mặt dưới săn vàng giòn và tỏa mùi thơm béo.', 'Chỉ nên lật cá đúng một lần khi mặt dưới đã vàng giòn hẳn để tránh làm nát thịt cá.', 7),
('imp-daec3b038c4f43af_v4_step_4', 'imp-daec3b038c4f43af', 4, 'cook', 'Lật mặt cá nướng chín đều toàn thân', 'Dùng xẻng bản rộng nhẹ nhàng lật cá sang mặt còn lại, tiếp tục nướng thêm 6–7 phút đến khi cả hai mặt da vàng giòn đều và phần thịt ở chỗ dày nhất chuyển trắng đục hoàn toàn, dễ tách khỏi xương.', 'Nếu không có vỉ nướng, có thể áp chảo chống dính lửa vừa mỗi mặt 6–7 phút với nắp hé nhẹ để cá chín đều từ trong ra ngoài.', 7),
('imp-daec3b038c4f43af_v4_step_5', 'imp-daec3b038c4f43af', 5, 'finish', 'Rưới nước tương chấm và rắc ngò rí lên mặt cá', 'Gắp cá thu nướng ra đĩa dài, múc một nửa lượng nước tương tỏi ớt chanh đã pha rưới đều lên thân cá nóng rồi rắc ngò rí thái nhỏ lên trên để tăng hương thơm tươi mát.', NULL, NULL),
('imp-daec3b038c4f43af_v4_step_6', 'imp-daec3b038c4f43af', 6, 'finish', 'Dọn cá nướng nóng kèm chén nước chấm và cơm trắng', 'Đặt phần nước tương chấm còn lại vào chén nhỏ dọn bên cạnh để chấm thêm khi ăn cùng cơm trắng nóng dẻo.', NULL, NULL),
('imp-4ca7d6f55d5b7937_v4_step_1', 'imp-4ca7d6f55d5b7937', 1, 'prep', 'Thái sợi rau củ, thịt bò và pha chén sốt Japchae', 'Thái sợi diêm cà rốt, thái lát mỏng hành tây và nấm hương tươi, cắt khúc 5 cm hành lá và thái thịt thăn bò thành sợi mỏng dài 5 cm. Băm nhuyễn tỏi khô rồi cho vào chén khuấy tan cùng 40 ml xì dầu, 25 g đường nâu, 20 ml dầu mè rang, 4 g hạt mè trắng rang và 1,5 g tiêu đen xay.', 'Dùng đường nâu pha sốt giúp sợi miến lên màu nâu óng ả đẹp mắt và thơm dịu hơn so với đường trắng.', NULL),
('imp-4ca7d6f55d5b7937_v4_step_2', 'imp-4ca7d6f55d5b7937', 2, 'cook', 'Luộc mềm miến khoai lang và chần rau chân vịt', 'Đun sôi 1.200 ml nước lọc trong nồi rộng, thả 150 g miến khoai lang Hàn vào luộc khoảng 7 phút đến khi sợi miến trong suốt và mềm dẻo hoàn toàn. Vớt miến ra rổ xả nước lạnh, để ráo rồi dùng kéo cắt đoạn 15–18 cm, cho vào tô lớn trộn đều với 1/3 lượng sốt đã pha. Tận dụng nồi nước sôi thêm 1 g muối ăn vào chần rau chân vịt 1 phút cho vừa héo, vớt ngay xả nước lạnh, vắt thật kiệt nước rồi cắt làm đôi.', 'Miến khoai lang phải luộc mềm dẻo hoàn toàn thay vì để sượng lõi; đồng thời vắt kiệt nước rau chân vịt để món trộn không bị chảy nước.', 8),
('imp-4ca7d6f55d5b7937_v4_step_3', 'imp-4ca7d6f55d5b7937', 3, 'cook', 'Xào săn sợi miến cho bóng mượt', 'Làm nóng chảo rộng trên lửa vừa với 8 ml dầu ăn, cho phần miến đã trộn sốt vào đảo đều liên tục trong 3 phút cho sợi miến săn bóng và thấm sâu gia vị, sau đó trút lại vào tô lớn.', NULL, 3),
('imp-4ca7d6f55d5b7937_v4_step_4', 'imp-4ca7d6f55d5b7937', 4, 'cook', 'Xào nhanh cà rốt, hành tây và hành lá còn độ giòn', 'Thêm 8 ml dầu ăn vào chảo trên lửa vừa–lớn, cho cà rốt vào xào 1 phút với 2 g muối ăn còn lại, gạt sang một bên rồi thả hành tây vào xào thêm 1 phút đến khi vừa trong và hành lá vào đảo nhanh 30 giây. Trút toàn bộ rau củ vào tô miến.', 'Xào rau trên lửa vừa–lớn trong thời gian ngắn để giữ độ giòn ngọt tự nhiên tương phản với sợi miến mềm dai.', 2),
('imp-4ca7d6f55d5b7937_v4_step_5', 'imp-4ca7d6f55d5b7937', 5, 'cook', 'Xào chín thịt bò và nấm hương tươi', 'Đổ 9 ml dầu ăn còn lại vào chảo nóng, cho thịt thăn bò và nấm hương tươi vào xào cùng 1/3 lượng sốt trên lửa lớn khoảng 3 phút đến khi thịt bò chín đều săn mềm và nấm thấm vị thơm thì trút tất cả vào tô miến.', NULL, 3),
('imp-4ca7d6f55d5b7937_v4_step_6', 'imp-4ca7d6f55d5b7937', 6, 'finish', 'Trộn đều miến Japchae và rắc mè rang thưởng thức', 'Cho rau chân vịt đã vắt ráo và 1/3 lượng sốt còn lại vào tô, dùng tay đeo găng thực phẩm trộn đều nhẹ nhàng để mọi nguyên liệu quyện sốt mà không làm đứt sợi miến. Bày ra đĩa lớn, rắc 2 g hạt mè trắng rang còn lại lên trên và thưởng thức.', NULL, NULL),
('imp-09e07baa201acf28_v4_step_1', 'imp-09e07baa201acf28', 1, 'prep', 'Vo ngâm gạo tẻ và hơ giòn rong biển lá khô', 'Vo sạch 200 g gạo tẻ hạt ngắn 2–3 lần nước rồi ngâm trong nước lạnh 30 phút cho hạt gạo ngậm nước, sau đó vớt ra rổ để thật ráo. Hơ nhanh 2 tờ rong biển lá khô trên lửa nhỏ vài giây đến khi giòn rụm, cho vào túi sạch bóp vụn và giã dập nhẹ 12 g hạt mè trắng rang.', 'Ngâm gạo đủ 30 phút trước khi rang và ninh giúp hạt gạo bung nở đều, cho nồi cháo sánh mịn mà không cần xay nhuyễn.', 30),
('imp-09e07baa201acf28_v4_step_2', 'imp-09e07baa201acf28', 2, 'prep', 'Băm nhỏ tôm tươi và thái hạt lựu rau củ', 'Tôm tươi bóc vỏ, rút chỉ đen sống lưng, rửa sạch và thái hạt lựu nhỏ. Thái hạt lựu nhỏ cà rốt và hành tây, băm nhuyễn tỏi khô, thái nhỏ hành lá và đánh tan 2 quả trứng gà trong chén.', NULL, NULL),
('imp-09e07baa201acf28_v4_step_3', 'imp-09e07baa201acf28', 3, 'cook', 'Phi thơm hành tỏi và rang gạo với dầu mè, tôm tươi', 'Đặt nồi lớn đáy dày lên bếp ở lửa vừa, cho 15 ml dầu mè rang, tỏi băm và hành tây vào đảo đều 2 phút đến khi hành mềm trong. Trút gạo đã ráo vào rang tiếp 2 phút cho hạt gạo hơi trong lại, rồi thả tôm tươi thái nhỏ vào đảo nhanh 1 phút cho tôm chuyển hồng thơm.', 'Rang gạo cùng dầu mè rang giúp hạt gạo săn thơm và tạo độ sánh béo tự nhiên đặc trưng của các món cháo Hàn Quốc.', 5),
('imp-09e07baa201acf28_v4_step_4', 'imp-09e07baa201acf28', 4, 'cook', 'Ninh nhừ gạo cùng cà rốt thành cháo sánh mịn', 'Cho cà rốt thái hạt lựu và 1.800 ml nước lọc vào nồi, khuấy đều tránh bén đáy rồi đậy nắp nấu trên lửa vừa 20 phút (hé nhẹ nắp hoặc khuấy khi sôi để tránh trào). Hạ xuống lửa nhỏ tiếp tục ninh thêm 10 phút nữa đến khi hạt gạo nở bung mềm nhừ và nước cháo sánh quyện.', NULL, 30),
('imp-09e07baa201acf28_v4_step_5', 'imp-09e07baa201acf28', 5, 'cook', 'Tạo vân trứng gà mềm mịn và nêm nước mắm', 'Mở nắp khuấy đều nồi cháo, rắc hành lá vào rồi từ từ rót dòng mỏng trứng gà đã đánh tan lên bề mặt cháo theo vòng tròn. Đậy nắp giữ lửa nhỏ thêm 1 phút cho vân trứng chín mềm rồi mới khuấy nhẹ. Nêm 25 ml nước mắm ngon và 2 g muối ăn cho vừa khẩu vị.', 'Không khuấy mạnh ngay lúc vừa rót trứng vào cháo để tạo được những dải vân trứng vàng đẹp mắt thay vì bị vụn đục.', 1),
('imp-09e07baa201acf28_v4_step_6', 'imp-09e07baa201acf28', 6, 'finish', 'Múc cháo nóng, rắc rong biển và mè rang', 'Tắt bếp, múc cháo tôm nóng hổi ra từng tô, rắc rong biển lá khô bóp vụn và hạt mè trắng rang giã dập lên trên rồi thưởng thức ngay.', NULL, NULL),
('imp-9c2f22829fd3d3f1_v4_step_1', 'imp-9c2f22829fd3d3f1', 1, 'marinate', 'Thái mỏng và ướp thịt bò thấm gia vị', 'Thái 260 g thịt thăn bò thành lát mỏng khoảng 3 mm theo chiều ngang thớ để thịt mềm ngọt. Cho thịt vào tô ướp đều với 1/2 lượng tỏi băm, 5 ml xì dầu, 3 g đường cát trắng, 2 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn, để thấm trong 15 phút.', 'Thái ngang thớ và trộn thêm 5 ml dầu ăn vào tô ướp giúp thịt bò giữ được độ mọng nước và không bị ra nước khi xào.', 15),
('imp-9c2f22829fd3d3f1_v4_step_2', 'imp-9c2f22829fd3d3f1', 2, 'prep', 'Sơ chế kim chi, hành tây và hành lá', 'Cắt kim chi cải thảo thành miếng vừa ăn khoảng 3 cm, hành tây thái múi cau mỏng, hành lá cắt khúc 3 cm và băm nhuyễn 1/2 lượng tỏi khô còn lại.', NULL, NULL),
('imp-9c2f22829fd3d3f1_v4_step_3', 'imp-9c2f22829fd3d3f1', 3, 'cook', 'Xào tái nhanh thịt bò trên lửa lớn', 'Đun nóng chảo rộng trên lửa lớn với 15 ml dầu ăn, cho phần tỏi băm còn lại vào phi thơm 20 giây rồi trút thịt bò đã ướp vào đảo nhanh tay khoảng 2 phút đến khi thịt vừa săn chuyển màu tái chín thì trút ngay ra đĩa riêng.', 'Xào riêng thịt bò trên lửa lớn rồi trút ra sớm giúp thịt không bị chín quá kỹ dẫn đến dai cứng khi xào tiếp với kim chi.', 2),
('imp-9c2f22829fd3d3f1_v4_step_4', 'imp-9c2f22829fd3d3f1', 4, 'cook', 'Xào săn kim chi cho dậy hương thơm', 'Dùng lại chảo nóng đó trên lửa vừa–lớn, cho kim chi cải thảo vào đảo đều khoảng 2 phút đến khi kim chi săn lại, tỏa mùi chua cay thơm nồng và hơi xém cạnh.', NULL, 2),
('imp-9c2f22829fd3d3f1_v4_step_5', 'imp-9c2f22829fd3d3f1', 5, 'cook', 'Xào quyện thịt bò, hành tây với sốt mật ong dầu hào', 'Trút đĩa thịt bò cùng hành tây thái múi cau trở lại chảo kim chi, nêm 15 ml xì dầu còn lại, 8 ml dầu hào và 8 ml mật ong nguyên chất. Đảo nhanh tay trên lửa lớn khoảng 2–3 phút đến khi thịt bò chín hoàn toàn, hành tây vừa chín giòn và nước sốt sánh bóng bám đều.', NULL, 3),
('imp-9c2f22829fd3d3f1_v4_step_6', 'imp-9c2f22829fd3d3f1', 6, 'finish', 'Thêm hành lá, dầu mè và mè rang dọn nóng', 'Thả hành lá cắt khúc vào đảo nhanh 30 giây rồi tắt bếp, rưới 5 ml dầu mè rang lên trên và đảo đều. Trút thịt bò xào kim chi ra đĩa, rắc hạt mè trắng rang tùy thích và dùng nóng ngay với cơm trắng.', 'Chỉ rưới dầu mè rang khi đã tắt bếp để hương thơm béo dịu được giữ trọn vẹn và không bị đắng.', NULL),
('imp-d7b9a40e678c0e29_v4_step_1', 'imp-d7b9a40e678c0e29', 1, 'marinate', 'Xăm da, thấm khô và ướp muối tiêu cho đùi gà', 'Lọc bỏ phần mỡ thừa ở mép 750 g thịt đùi gà rút xương, dùng mũi dao nhọn xăm nhẹ vài lỗ nhỏ trên bề mặt da (tránh đâm sâu vào thịt) và rạch mỏng ở những chỗ thịt quá dày để chín đều. Rắc đều 6 g muối ăn và 2 g tiêu đen xay lên cả hai mặt, để thấm 10 phút rồi dùng khăn giấy thấm thật khô lại mặt da.', 'Muối sẽ kéo bớt nước ra bề mặt thịt, vì vậy hãy thấm khô lại một lần nữa ngay trước khi cho lên chảo để da gà nổ giòn đẹp và không bắn mỡ.', 10),
('imp-d7b9a40e678c0e29_v4_step_2', 'imp-d7b9a40e678c0e29', 2, 'prep', 'Cắt khúc hành lá, chuẩn bị tỏi tép và chén chấm dầu mè', 'Cắt hành lá thành khúc dài 5 cm và bóc vỏ tỏi khô giữ nguyên tép. Trong chén nhỏ, trộn 15 ml dầu mè rang với 1 g muối ăn, 0,5 g tiêu đen xay và 4 g hạt mè trắng rang làm nước chấm. Cắt chanh tươi thành múi cau.', NULL, NULL),
('imp-d7b9a40e678c0e29_v4_step_3', 'imp-d7b9a40e678c0e29', 3, 'cook', 'Áp chảo mặt thịt rồi lật áp giòn mặt da không cần dầu', 'Đặt chảo gang hoặc chảo chống dính khô lên bếp lửa vừa, không cần cho dầu ăn. Đặt từng miếng đùi gà sao cho mặt thịt tiếp xúc với chảo trước khoảng 1 phút cho thịt định hình phẳng, sau đó lật úp mặt da xuống dưới, dùng xẻng ép nhẹ và nướng yên trong 7–8 phút. Thỉnh thoảng nghiêng chảo dùng giấy thấm bớt mỡ tiết ra (chừa lại khoảng 1 muỗng canh mỡ).', 'Áp mặt thịt trước 1 phút giúp miếng gà không bị co rút méo mó; không lật đi lật lại liên tục và thấm bớt mỡ thừa để da gà được nướng giòn thay vì bị ngập mỡ.', 8),
('imp-d7b9a40e678c0e29_v4_step_4', 'imp-d7b9a40e678c0e29', 4, 'cook', 'Chiên chín hoàn toàn mặt thịt và cho gà nghỉ', 'Khi mặt da đã vàng giòn rụm và tự bong khỏi đáy chảo, lật lại áp mặt thịt thêm 2 phút đến khi thịt gà chín trắng hoàn toàn và nước tiết ra trong suốt (nhiệt độ lõi đạt trên 75°C). Gắp gà ra thớt để nghỉ 3 phút trước khi thái miếng vừa ăn.', NULL, 5),
('imp-d7b9a40e678c0e29_v4_step_5', 'imp-d7b9a40e678c0e29', 5, 'cook', 'Nướng xém hành lá và tỏi nguyên tép trong mỡ gà', 'Tận dụng lượng mỡ gà thơm còn lại trong chảo, bật lửa lớn cho hành lá cắt khúc và tỏi nguyên tép vào áp chảo 2 phút, rắc thêm 1 g muối ăn và 0,5 g tiêu đen xay rồi đảo đều đến khi hành lá xém cạnh thơm ngọt và tỏi chuyển vàng bùi.', 'Nướng hành lá cắt khúc dài và tỏi nguyên tép trực tiếp trong mỡ gà giúp dậy hương thơm ngọt tự nhiên và cân bằng vị béo.', 2),
('imp-d7b9a40e678c0e29_v4_step_6', 'imp-d7b9a40e678c0e29', 6, 'finish', 'Bày gà nướng muối kèm chanh tươi và chấm dầu mè', 'Thái gà thành miếng vừa ăn xếp ra đĩa, gắp hành lá và tỏi nướng xém bày lên cạnh cùng múi chanh tươi. Khi thưởng thức hãy vắt vài giọt chanh lên thịt gà nóng và chấm với chén dầu mè muối tiêu.', NULL, NULL),
('imp-2b289d9040d46110_v4_step_1', 'imp-2b289d9040d46110', 1, 'prep', 'Thấm khô, cắt miếng đậu phụ và pha sốt kho', 'Cắt 420 g đậu phụ trắng thành từng miếng chữ nhật dày khoảng 1 cm, đặt lên khăn giấy sạch thấm khô hai mặt khoảng 5 phút để đậu săn và không bị bắn dầu khi chiên. Băm nhỏ gừng tươi, tỏi khô, thái hạt lựu hành tây và thái nhỏ hành lá. Khuấy tan 35 ml xì dầu, 12 g đường cát trắng, 2 g ớt bột Hàn Quốc (nếu dùng) cùng 60 ml nước lọc.', 'Thấm thật ráo nước trên bề mặt miếng đậu phụ trước khi áp chảo giúp tạo lớp vỏ vàng giòn nhanh mà không bị nát khi lật.', 5),
('imp-2b289d9040d46110_v4_step_2', 'imp-2b289d9040d46110', 2, 'cook', 'Áp chảo vàng giòn hai mặt từng miếng đậu phụ', 'Làm nóng chảo chống dính lớn trên lửa vừa với 25 ml dầu ăn, xếp đậu phụ vào áp chảo mỗi mặt 3–4 phút đến khi hai mặt vàng ươm và săn chắc, sau đó gắp ra đĩa riêng.', 'Chờ mặt dưới đậu phụ vàng cứng hẳn rồi mới lật sẽ giữ được miếng đậu nguyên vẹn, vuông vắn đẹp mắt.', 7),
('imp-2b289d9040d46110_v4_step_3', 'imp-2b289d9040d46110', 3, 'cook', 'Phi thơm hành tây, tỏi, gừng tươi và tráng chảo', 'Vẫn dùng chảo đó với lượng dầu thơm còn lại, cho hành tây, tỏi băm, gừng băm và 2/3 lượng hành lá vào xào đều trên lửa vừa khoảng 1 phút cho dậy mùi thơm nồng. Rót 60 ml nước lọc còn lại vào chảo tráng đều để hòa tan lớp hương thơm bám dưới đáy rồi đổ tiếp bát sốt xì dầu đã pha vào đun sôi nhẹ.', NULL, 1),
('imp-2b289d9040d46110_v4_step_4', 'imp-2b289d9040d46110', 4, 'cook', 'Kho thấm đậu phụ và rưới sốt đều hai mặt', 'Xếp đậu phụ đã chiên trở lại chảo nước sốt đang sôi nhẹ, hạ lửa vừa–nhỏ và kho 3 phút đồng thời dùng muỗng múc sốt rưới liên tục lên mặt trên của từng miếng đậu cho thấm đều.', NULL, 3),
('imp-2b289d9040d46110_v4_step_5', 'imp-2b289d9040d46110', 5, 'cook', 'Lật mặt đậu phụ kho đến khi nước sốt keo sánh', 'Nhẹ nhàng lật từng miếng đậu sang mặt còn lại và kho tiếp 2 phút nữa đến khi phần nước sốt cạn còn khoảng 1/3, sánh bóng bám quanh từng miếng đậu (giữ lại một ít sốt sệt để chan cơm).', 'Không kho cạn kiệt nước mà giữ lại lớp sốt sánh nhẹ giúp miếng đậu phụ bóng đẹp và đậm đà hơn khi chan cơm.', 2),
('imp-2b289d9040d46110_v4_step_6', 'imp-2b289d9040d46110', 6, 'finish', 'Rưới dầu mè, rắc mè rang và thưởng thức', 'Tắt bếp ngay, rưới 12 ml dầu mè rang lên khắp mặt chảo và lắc nhẹ cho đều. Xếp đậu phụ kho gừng ra đĩa, rưới hết phần sốt sệt lên trên, rắc 4 g hạt mè trắng rang cùng 1/3 hành lá còn lại rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-7cb7368109956ad5_v4_step_1', 'imp-7cb7368109956ad5', 1, 'prep', 'Rửa sạch giá đỗ và sơ chế kim chi, hành tỏi', 'Nhặt sạch vỏ đậu trên 400 g giá đỗ tươi nhưng giữ nguyên phần rễ vì rễ giá giúp nước canh ngọt và thanh hơn, ngâm nước lạnh 5 phút rồi xả sạch để ráo. Cắt kim chi cải thảo thành miếng vừa ăn (giữ lại 100 ml nước kim chi), băm nhuyễn tỏi khô, thái vát hành lá và thái lát ớt sừng tươi.', 'Giữ nguyên phần rễ giá đỗ khi nấu canh là mẹo truyền thống giúp nước canh ngọt mát và giàu dưỡng chất hơn.', 5),
('imp-7cb7368109956ad5_v4_step_2', 'imp-7cb7368109956ad5', 2, 'cook', 'Xào thơm tỏi và kim chi trên lửa vừa', 'Đun nóng nồi trên lửa vừa với 15 ml dầu ăn, cho tỏi băm vào phi thơm 20 giây rồi thả kim chi cùng 100 ml nước kim chi vào xào đều tay trong 3 phút đến khi kim chi săn lại và dậy mùi thơm.', NULL, 3),
('imp-7cb7368109956ad5_v4_step_3', 'imp-7cb7368109956ad5', 3, 'cook', 'Đun sôi nước dùng cá cơm tảo bẹ và nêm gia vị nền', 'Đổ 1.400 ml nước dùng cá cơm tảo bẹ Hàn vào nồi kim chi, đun sôi mạnh trên lửa lớn rồi nêm 10 ml xì dầu, 15 ml nước mắm ngon, 8 g ớt bột Hàn Quốc (nếu dùng) và ớt sừng tươi thái lát, nấu sôi liu riu 4 phút cho nước canh ra hết vị chua cay nền.', NULL, 4),
('imp-7cb7368109956ad5_v4_step_4', 'imp-7cb7368109956ad5', 4, 'cook', 'Thả giá đỗ và nấu mở nắp giữ độ giòn không hăng', 'Khi nước canh đang sôi mạnh, thả toàn bộ 400 g giá đỗ vào và giữ nguyên trạng thái mở nắp, đun trên lửa lớn khoảng 5–6 phút (thỉnh thoảng đảo nhẹ) cho đến khi hết mùi hăng đậu sống mà thân giá vẫn giòn ngọt.', 'Tuyệt đối mở nắp suốt quá trình nấu giá đỗ để hơi hăng bay thoát hết ra ngoài, giúp tô canh thanh khiết không bị mùi nồng.', 6),
('imp-7cb7368109956ad5_v4_step_5', 'imp-7cb7368109956ad5', 5, 'finish', 'Nêm muối cân chỉnh vị và thêm hành lá, dầu mè', 'Nếm lại nước canh rồi chỉ điều chỉnh thêm tối đa 1 g muối ăn nếu cần (vì nước dùng, kim chi và nước mắm đã có độ mặn sẵn). Thả hành lá thái vát vào nấu sôi bùng lại 30 giây, rưới 5 ml dầu mè rang rồi tắt bếp.', NULL, NULL),
('imp-7cb7368109956ad5_v4_step_6', 'imp-7cb7368109956ad5', 6, 'finish', 'Ủ ấm vài phút rồi múc tô dùng nóng', 'Để nồi canh nghỉ trên bếp khoảng 2 phút cho các vị hòa quyện sâu hơn trước khi múc ra tô, thưởng thức nóng cùng cơm trắng.', 'Cho canh nghỉ 2 phút sau khi tắt bếp giúp nước dùng trong và đậm vị hài hòa hơn hẳn.', 2),
('imp-a3e676be13c4c51c_v4_step_1', 'imp-a3e676be13c4c51c', 1, 'prep', 'Ninh nước dùng tảo bẹ củ cải thanh ngọt', 'Cho 1.200 ml nước lọc, 10 g tảo bẹ Kombu khô, 85 g củ cải trắng cắt khối và 1/4 củ hành tây vào nồi, đun sôi rồi hạ lửa vừa nấu 15 phút. Vớt bỏ toàn bộ tảo bẹ, củ cải trắng và hành tây, sau đó nêm nước dùng với 15 ml xì dầu, 3 g muối ăn và 0,5 g tiêu đen xay rồi giữ ấm.', 'Không đun tảo bẹ quá lâu trên lửa lớn để nước dùng luôn trong trẻo, ngọt thanh mà không bị nhớt hay đắng.', 15),
('imp-a3e676be13c4c51c_v4_step_2', 'imp-a3e676be13c4c51c', 2, 'marinate', 'Thái lát và ướp thịt bò theo kiểu Bulgogi', 'Thái thịt thăn bò thành lát mỏng 3 mm ngang thớ, cho vào tô lớn trộn đều với 50 ml xì dầu, 12 g đường cát trắng, 15 ml mật ong nguyên chất, 15 ml rượu Mirin Nhật, tỏi băm, 15 ml dầu mè rang và 1 g tiêu đen xay. Bóp nhẹ cho gia vị thấm đều rồi ướp 15 phút trong lúc sơ chế rau nấm.', NULL, 15),
('imp-a3e676be13c4c51c_v4_step_3', 'imp-a3e676be13c4c51c', 3, 'prep', 'Sơ chế nấm đùi gà, nấm hương, rau củ và ngâm miến', 'Thái lát dày 1 cm nấm đùi gà và thái lát dày 0,6 cm nấm hương tươi (tránh thái quá mỏng vì nấm sẽ ngót khi hầm). Thái lát mỏng cà rốt và 3/4 củ hành tây còn lại, cắt miếng vừa ăn cải thảo và cắt khúc 5 cm hành lá. Nếu dùng miến khoai lang Hàn, ngâm trong nước ấm 20 phút cho mềm rồi vớt ráo.', NULL, 20),
('imp-a3e676be13c4c51c_v4_step_4', 'imp-a3e676be13c4c51c', 4, 'cook', 'Xếp cụm thịt bò, nấm, rau củ và chế nước dùng', 'Dùng nồi lẩu hoặc nồi gốm nông lòng, lần lượt xếp thịt bò đã ướp, nấm đùi gà, nấm hương tươi, cà rốt, cải thảo, hành tây và miến khoai lang (nếu dùng) thành từng cụm xen kẽ đẹp mắt quanh lòng nồi. Chế khoảng 750 ml nước dùng nóng vào xâm xấp 2/3 nguyên liệu (phần nước dùng còn lại giữ nóng để châm thêm).', 'Xếp từng loại nguyên liệu theo cụm thay vì trộn lẫn giúp món hầm trông hấp dẫn và từng thành phần chín đều đẹp mắt.', NULL),
('imp-a3e676be13c4c51c_v4_step_5', 'imp-a3e676be13c4c51c', 5, 'cook', 'Nấu sôi tách thịt bò và hầm mềm nấm ngọt nước', 'Đặt nồi lên bếp ở lửa lớn đến khi nước dùng sôi bùng khoảng 3 phút, dùng đũa tách nhẹ các lát thịt bò cho khỏi dính chùm. Hạ xuống lửa vừa và nấu thêm 6 phút nữa đến khi thịt bò chín mềm hoàn toàn và các loại nấm thấm đẫm nước sốt ngọt dịu.', 'Thịt bò thái lát mỏng rất nhanh chín nên không hầm quá lâu sau khi nước sôi để giữ thớ thịt mềm ngọt không bị dai.', 6),
('imp-a3e676be13c4c51c_v4_step_6', 'imp-a3e676be13c4c51c', 6, 'finish', 'Rắc hành lá và thưởng thức nóng tại bàn', 'Nêm chỉnh lại nước hầm cho vừa miệng, thả hành lá cắt khúc lên trên rồi tắt bếp hoặc giữ lửa liu riu dùng nóng tại bàn kèm cơm trắng.', NULL, NULL),
('imp-1b54108818405e6a_v4_step_1', 'imp-1b54108818405e6a', 1, 'prep', 'Làm tơi cơm nguội, thái thịt ba chỉ và sơ chế kim chi', 'Dùng tay sạch bóp nhẹ cho 580 g cơm trắng nguội tơi rời từng hạt. Thái 180 g thịt ba chỉ heo thành miếng nhỏ 1,5 cm rồi ướp với 1 g muối ăn và 0,5 g tiêu đen xay. Cắt nhỏ kim chi cải thảo (giữ lại 60 ml nước kim chi), thái hạt lựu hành tây, tách riêng đầu hành trắng và lá xanh hành lá, cắt sợi mảnh rong biển lá khô.', 'Dùng cơm nguội để tủ lạnh qua đêm đã bóp tơi sẽ giúp cơm chiên săn hạt và không bị bết dính chảo.', NULL),
('imp-1b54108818405e6a_v4_step_2', 'imp-1b54108818405e6a', 2, 'cook', 'Áp chảo thịt ba chỉ vàng giòn và tiết mỡ thơm', 'Làm nóng chảo rộng trên lửa vừa với 5 ml dầu ăn, cho thịt ba chỉ đã ướp vào đảo đều khoảng 5–6 phút đến khi thịt chín vàng đều các mặt, xém cạnh giòn và tiết ra mỡ thơm (nếu mỡ tiết ra quá nhiều, chắt bớt chỉ giữ lại khoảng 1,5 muỗng canh mỡ trong chảo).', NULL, 6),
('imp-1b54108818405e6a_v4_step_3', 'imp-1b54108818405e6a', 3, 'cook', 'Phi thơm hành tây và xào kỹ kim chi với Gochujang', 'Cho hành tây thái hạt lựu và phần đầu hành trắng vào chảo mỡ thịt đảo nhanh 30 giây trên lửa lớn cho thơm. Sau đó trút kim chi cải thảo, 60 ml nước kim chi, 20 ml xì dầu và 25 g tương ớt Hàn Quốc (Gochujang) vào xào đều trong 3 phút đến khi kim chi mềm sậm màu và sốt quyện đều.', 'Xào kỹ kim chi cùng tương ớt Gochujang trước khi cho cơm vào giúp vị chua cay thấm sâu và loại bỏ hơi ẩm dư.', 3),
('imp-1b54108818405e6a_v4_step_4', 'imp-1b54108818405e6a', 4, 'cook', 'Rang cơm thấm đều sốt đỏ cam trên lửa vừa rồi tăng lửa lớn', 'Hạ bếp xuống lửa vừa–nhỏ, trút toàn bộ cơm nguội đã bóp tơi vào chảo, dùng muôi tán nhẹ và đảo đều 3 phút cho từng hạt cơm nhuộm màu đỏ cam bóng đẹp. Tiếp theo, tăng lên lửa lớn đảo thưa tay thêm 2 phút cho hạt cơm săn giòn và thơm mùi chảo.', 'Hạ lửa lúc mới trộn để cơm không dính đáy, rồi tăng lửa lớn ở 2 phút cuối giúp hạt cơm săn thơm cháy cạnh nhẹ.', 5),
('imp-1b54108818405e6a_v4_step_5', 'imp-1b54108818405e6a', 5, 'finish', 'Nêm chỉnh vị, rưới dầu mè và chiên trứng ốp la ăn kèm', 'Nếm thử và chỉnh thêm tối đa 1 g muối ăn cùng 0,5 g tiêu đen xay nếu cần, tắt bếp rồi rưới 10 ml dầu mè rang và phần lá xanh hành lá vào đảo đều. Trên một chảo chống dính nhỏ khác, đun nóng 10 ml dầu ăn còn lại và chiên ốp la 3 quả trứng gà đến độ chín mong muốn.', NULL, NULL),
('imp-1b54108818405e6a_v4_step_6', 'imp-1b54108818405e6a', 6, 'finish', 'Trình bày đĩa cơm chiên ba chỉ kim chi nóng hổi', 'Múc cơm chiên ba chỉ kim chi ra từng đĩa hoặc tô, đặt trứng ốp la lên trên, rắc thêm hạt mè trắng rang và rong biển lá khô cắt sợi rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-9328a098d7bd1f6f_v4_step_1', 'imp-9328a098d7bd1f6f', 1, 'prep', 'Làm sạch và khứa đùi gà cho thấm gia vị', 'Xát 3 g muối ăn lên khắp 800 g đùi gà góc tư để khử mùi hôi, rửa lại thật sạch dưới vòi nước lạnh rồi dùng khăn giấy thấm khô hoàn toàn. Dùng dao sắc khứa 2–3 đường sâu tới gần xương trên cả hai mặt đùi gà, sau đó xoa đều 3 g muối còn lại và 3 g tiêu đen xay để 10 phút.', 'Khứa sâu gần sát xương không chỉ giúp gia vị thấm tận lõi thịt mà còn giúp phần thịt dày quanh khớp xương chín kỹ đều khi nướng.', 10),
('imp-9328a098d7bd1f6f_v4_step_2', 'imp-9328a098d7bd1f6f', 2, 'marinate', 'Pha sốt chanh ớt và ướp lạnh đùi gà', 'Băm nhuyễn tỏi khô và 3 quả ớt hiểm đỏ. Trộn đều 30 ml nước cốt chanh tươi, 30 ml nước mắm ngon, 20 g đường cát trắng, 25 ml dầu ăn thực vật cùng tỏi và ớt băm đến khi đường tan hết. Quét kỹ hỗn hợp sốt vào các rãnh khứa và hai mặt đùi gà, bọc kín cho vào ngăn mát tủ lạnh ướp ít nhất 60 phút.', 'Ướp gà trong ngăn mát tủ lạnh vừa đảm bảo an toàn thực phẩm vừa giúp lớp da se khô nhẹ, khi nướng sẽ lên màu vàng giòn hơn.', 60);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-9328a098d7bd1f6f_v4_step_3', 'imp-9328a098d7bd1f6f', 3, 'cook', 'Làm nóng lò và nướng đùi gà lần đầu', 'Làm nóng trước lò nướng hoặc nồi chiên không dầu ở mức 195–200°C trong 10 phút. Xếp đùi gà lên vỉ có lót khay hứng mỡ phía dưới (ngửa mặt da xuống dưới trước), phết thêm một lớp sốt ướp còn dư rồi nướng ở 200°C trong 20 phút.', NULL, 20),
('imp-9328a098d7bd1f6f_v4_step_4', 'imp-9328a098d7bd1f6f', 4, 'cook', 'Lật mặt, phết sốt và nướng vàng giòn lớp da', 'Mở lò, lật mặt da đùi gà lên trên, phết thêm một lớp mỏng sốt ướp còn lại (nếu thấy sốt đặc nhanh cháy thì giảm nhiệt xuống 185°C) và nướng tiếp 15–20 phút nữa. Kiểm tra bằng cách xiên tăm vào phần thịt dày nhất gần xương thấy nước chảy ra trong veo, không còn dịch hồng và da gà vàng cánh gián giòn rụm là gà chín hoàn toàn.', 'Canh kỹ 10 phút cuối để tránh phần đường trong sốt làm xém đen da gà; có thể che giấy bạc lên đầu xương nếu cần.', 18),
('imp-9328a098d7bd1f6f_v4_step_5', 'imp-9328a098d7bd1f6f', 5, 'sauce', 'Để thịt nghỉ giữ nước và pha sốt chấm', 'Lấy đùi gà ra đĩa, để nghỉ 5 phút cho nước thịt ổn định bên trong thớ thịt. Trong lúc chờ, trộn 30 ml tương ớt Thái với 15 ml nước cốt chanh tươi còn lại và 1 quả ớt hiểm thái lát làm chén sốt chấm chua cay.', NULL, 5),
('imp-9328a098d7bd1f6f_v4_step_6', 'imp-9328a098d7bd1f6f', 6, 'finish', 'Chặt miếng, rắc hành lá và dọn nóng', 'Chặt đùi gà thành từng miếng vừa ăn (hoặc bày nguyên chiếc), rắc hành lá thái nhỏ lên bề mặt da giòn và dọn nóng kèm chén tương ớt chanh.', NULL, NULL),
('imp-cc203adb1d5aa11b_v4_step_1', 'imp-cc203adb1d5aa11b', 1, 'prep', 'Khử nhớt cá và sơ chế sả, cà chua', 'Cá tươi đánh sạch vảy, bỏ mang và màng đen trong bụng, xát đều 4 g muối ăn lên mình cá trong 1 phút rồi rửa lại thật sạch bằng nước lạnh, để ráo và cắt khúc dày 2,5 cm. Sả tươi bóc vỏ già, đập dập rồi cắt khúc 6 cm. Cà chua bỏ cuống, bổ 6 múi cau; chanh tươi vắt lấy 40 ml nước cốt; hành lá tách riêng đầu hành đập dập và lá xanh cắt khúc 2 cm, ngò rí cắt khúc.', 'Rửa sạch màng đen trong bụng cá và thấm khô giúp nước canh trong veo, không có mùi tanh.', NULL),
('imp-cc203adb1d5aa11b_v4_step_2', 'imp-cc203adb1d5aa11b', 2, 'cook', 'Xào sơ cà chua và ninh nước sả thơm', 'Đun nóng 10 ml dầu ăn thực vật trong nồi ở lửa vừa, thả đầu hành lá và 1 nửa lượng cà chua vào đảo nhanh 2 phút cho cà chua hơi mềm tiết màu tự nhiên. Chế 1400 ml nước lọc vào cùng 3 cây sả đập dập, bật lửa lớn đun sôi rồi hạ lửa vừa nấu 5 phút cho nước dậy mùi sả thơm nồng.', NULL, 5),
('imp-cc203adb1d5aa11b_v4_step_3', 'imp-cc203adb1d5aa11b', 3, 'cook', 'Nêm nước dùng và nấu chín cá', 'Nêm vào nồi nước sả 35 ml nước mắm ngon, 4 g muối ăn còn lại và 8 g đường cát trắng, khuấy tan. Khi nước đang sôi lăn riu ở lửa vừa, nhẹ nhàng thả từng khúc cá vào nấu khoảng 4 phút cho thịt cá se chắc lại, thường xuyên hớt sạch bọt nổi để nước canh trong.', 'Chỉ thả cá khi nước đang sôi và giữ lửa vừa sôi lăn riu, không dùng đũa đảo mạnh để khúc cá không bị nát.', 4),
('imp-cc203adb1d5aa11b_v4_step_4', 'imp-cc203adb1d5aa11b', 4, 'cook', 'Thêm cà chua còn lại và nấu chín hoàn toàn', 'Cho nốt phần cà chua múi cau còn lại và ớt hiểm đỏ vào nồi nấu thêm 3–4 phút cho đến khi cà chua vừa mềm giữ nguyên vỏ và thịt cá chín trắng đục hoàn toàn, dễ tách khỏi xương.', NULL, 4),
('imp-cc203adb1d5aa11b_v4_step_5', 'imp-cc203adb1d5aa11b', 5, 'finish', 'Tắt bếp nêm nước cốt chanh tươi', 'Tắt bếp rồi từ từ rót 40 ml nước cốt chanh tươi vào nồi, lắc nhẹ hoặc khuấy một vòng thật khẽ để giữ hương thơm thanh mát của chanh không bị bay hơi hay đắng.', 'Cho nước cốt chanh tươi sau khi tắt bếp giữ trọn hương thơm thanh mát và tránh làm nước canh bị đắng do tinh dầu vỏ chanh gặp nhiệt cao.', NULL),
('imp-cc203adb1d5aa11b_v4_step_6', 'imp-cc203adb1d5aa11b', 6, 'finish', 'Rắc rau thơm và dọn canh nóng', 'Thả hành lá thái khúc và ngò rí vào nồi canh, múc cá và nước dùng ra tô lớn (có thể gắp bỏ bớt khúc sả già) rồi thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-7bd81a7e8fb33958_v4_step_1', 'imp-7bd81a7e8fb33958', 1, 'prep', 'Làm sạch và khứa vảy rồng mực tươi', 'Mực ống tươi rút bỏ nội tạng, mai cứng, mắt và miệng mực; rửa sạch dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô cả mặt trong lẫn mặt ngoài. Dùng dao sắc khứa nhẹ mặt trong thân mực theo đường chéo đan lưới rồi cắt miếng cỡ 3×5 cm, râu mực cắt khúc vừa ăn.', 'Thấm thật khô thân mực trước khi hấp giúp mực không tiết ra quá nhiều nước làm nhạt vị sốt và giữ độ giòn ngọt.', NULL),
('imp-7bd81a7e8fb33958_v4_step_2', 'imp-7bd81a7e8fb33958', 2, 'prep', 'Sơ chế sả, tỏi ớt và rau thơm', 'Đập dập 4 cây sả tươi: lấy 2 cây thái lát chéo dày 0,3 cm lót kín đáy đĩa sâu lòng chịu nhiệt, 2 cây còn lại băm thật nhuyễn. Tỏi khô và 4 quả ớt hiểm đỏ băm nhỏ. Hành lá và ngò rí rửa sạch, để ráo, cắt khúc 2 cm (chừa lại ít gốc ngò băm nhỏ). Vắt chanh tươi lấy 50 ml nước cốt.', NULL, NULL),
('imp-7bd81a7e8fb33958_v4_step_3', 'imp-7bd81a7e8fb33958', 3, 'sauce', 'Pha nước om hấp và nước sốt chanh ớt Thái', 'Hòa tan 15 ml nước mắm ngon, 7 g đường cát trắng và 180 ml nước lọc để làm nước om, rưới đều lên mực đã xếp trên lớp sả trong đĩa. Trong chén riêng, khuấy tan 20 ml nước mắm ngon còn lại với 15 g đường cát trắng và 50 ml nước cốt chanh tươi, sau đó thêm sả băm, tỏi băm, ớt hiểm băm và gốc ngò băm vào trộn đều thành nước sốt Nam Jim.', 'Nếm thử chén sốt sao cho vị chua, cay, mặn, ngọt cân bằng rõ nét; nếu thích vị dịu hơn có thể thêm nửa muỗng cà phê đường.', 2),
('imp-7bd81a7e8fb33958_v4_step_4', 'imp-7bd81a7e8fb33958', 4, 'cook', 'Hấp om mực trên lửa lớn đúng thời gian', 'Đun sôi mạnh nước trong nồi hấp rồi đặt đĩa mực vào xửng, đậy kín nắp và hấp lửa lớn trong 4–5 phút. Quan sát thấy các miếng mực cuộn cong đẹp mắt, thịt chuyển trắng đục và săn chắc hoàn toàn là đạt.', 'Tuyệt đối không hấp mực quá 6 phút vì nhiệt cao kéo dài sẽ làm mực tiết hết nước ngọt và trở nên dai cứng.', 5),
('imp-7bd81a7e8fb33958_v4_step_5', 'imp-7bd81a7e8fb33958', 5, 'finish', 'Chắt bớt nước hấp và rưới sốt nóng hổi', 'Nhấc đĩa mực ra khỏi nồi hấp (cẩn thận hơi nóng), chắt bỏ bớt khoảng một nửa phần nước tiết ra trong đĩa để giữ lại độ đậm đà vừa phải, rồi rưới đều toàn bộ chén nước sốt chanh tỏi ớt lên khắp bề mặt mực khi còn đang bốc khói.', NULL, NULL),
('imp-7bd81a7e8fb33958_v4_step_6', 'imp-7bd81a7e8fb33958', 6, 'finish', 'Rắc hành ngò và thưởng thức ngay', 'Rắc hành lá và ngò rí cắt khúc lên trên đĩa mực hấp om sả, trộn nhẹ một lượt rồi dọn dùng nóng ngay với cơm trắng hoặc rau sống.', NULL, NULL),
('imp-0abadc2e606770a7_v4_step_1', 'imp-0abadc2e606770a7', 1, 'prep', 'Làm sạch cua biển và khử mùi tanh', 'Ngâm nguyên con 1800 g cua thịt biển trong thau nước đá lạnh khoảng 10 phút để cua dịu lại, không rụng càng khi hấp. Dùng bàn chải cứng chà sạch bùn đất quanh mai, yếm và kẽ chân cua dưới vòi nước chảy, cắt đôi 1 quả chanh tươi chà xát khắp mình cua để khử tanh rồi rửa lại thật sạch, để ráo.', 'Không tháo dây buộc cua trước khi hấp và giữ cua ngủ lạnh bằng đá giúp càng cua nguyên vẹn, không bị gãy rụng mất nước ngọt.', 10),
('imp-0abadc2e606770a7_v4_step_2', 'imp-0abadc2e606770a7', 2, 'prep', 'Sơ chế sả, gừng và chuẩn bị xửng hấp', 'Bóc bỏ vỏ già bên ngoài của 10 cây sả tươi, đập dập rồi cắt khúc dài 5 cm; gừng tươi cạo vỏ thái lát mỏng. Lót 2/3 lượng sả và một nửa lượng gừng kín đáy xửng hấp, đặt cua ngửa bụng lên trên (để giữ nguyên phần gạch ngọt không bị chảy ra) rồi xếp nốt 1/3 lượng sả và gừng còn lại lên mình cua.', 'Đặt ngửa mai cua xuống dưới giúp hơi nước lưu thông đều và giữ trọn phần gạch béo bùi trong mai.', NULL),
('imp-0abadc2e606770a7_v4_step_3', 'imp-0abadc2e606770a7', 3, 'cook', 'Hấp cua cùng hơi sả và rượu vang trắng', 'Rắc đều 6 g muối ăn và 2 g tiêu đen xay lên mình cua. Đổ 450 ml nước lọc và 120 ml rượu vang trắng nấu ăn vào đáy nồi (đảm bảo mực nước cách mặt xửng ít nhất 3 cm), đun sôi bùng trên lửa lớn rồi đặt xửng cua lên, đậy kín nắp hấp trong 7 phút.', NULL, 7),
('imp-0abadc2e606770a7_v4_step_4', 'imp-0abadc2e606770a7', 4, 'cook', 'Đảo vị trí cua và pha hỗn hợp dầu phết mai', 'Mở nắp nồi, cẩn thận đổi vị trí các con cua giữa lớp trên và lớp dưới cho chín đều, đậy nắp hấp tiếp 5 phút. Trong lúc chờ, khuấy đều 15 ml dầu ăn thực vật với 3 g muối ăn, 4 g hạt nêm và 4 g đường cát trắng thành hỗn hợp sệt.', NULL, 5),
('imp-0abadc2e606770a7_v4_step_5', 'imp-0abadc2e606770a7', 5, 'cook', 'Phết dầu gia vị và hấp hoàn thiện', 'Mở nắp nồi, dùng cọ phết đều hỗn hợp dầu gia vị lên mai và càng cua rồi đậy nắp hấp thêm 2 phút trên lửa lớn. Kiểm tra thấy vỏ cua chuyển màu đỏ cam tươi bóng, thịt ở khớp càng trắng đục săn chắc hoàn toàn là cua đã chín tới.', 'Phết một lớp mỏng dầu gia vị ở 2 phút cuối giúp vỏ cua đỏ bóng đẹp mắt và thơm dậy mùi hơn hẳn.', 2),
('imp-0abadc2e606770a7_v4_step_6', 'imp-0abadc2e606770a7', 6, 'finish', 'Giã muối tiêu chanh ớt và dọn cua nóng', 'Giã nhuyễn 3 quả ớt hiểm đỏ với 3 g muối ăn và 2 g tiêu đen xay còn lại, vắt nước cốt của 1 quả chanh tươi vào khuấy đều làm chén chấm. Gắp cua ra đĩa lớn cùng vài khúc sả hấp, cắt bỏ dây buộc và thưởng thức khi cua còn nóng hổi.', NULL, NULL),
('imp-cc6a0ca585b502d4_v4_step_1', 'imp-cc6a0ca585b502d4', 1, 'prep', 'Băm thịt gà và sơ chế hành tím, rau thơm', 'Kết hợp 300 g ức gà và 150 g thịt đùi gà lọc xương băm nhỏ vừa ăn bằng tay để thịt giữ được độ mọng nước. Băm nhuyễn tỏi khô và 3 quả ớt hiểm đỏ. Thái lát thật mỏng hành tím khô; thái chỉ lá chanh Thái; thái nhỏ hành lá và ngò rí; nhặt lá bạc hà tươi để ráo. Vắt 2 quả chanh tươi lấy 45 ml nước cốt.', 'Phối trộn ức gà cùng thịt đùi gà theo tỉ lệ 2:1 giúp món Larb vừa giàu đạm vừa mềm ngọt, không bị khô xác khi xào không dầu.', NULL),
('imp-cc6a0ca585b502d4_v4_step_2', 'imp-cc6a0ca585b502d4', 2, 'cook', 'Xào nước thịt gà bằm chín tơi mọng', 'Cho 50 ml nước lọc vào chảo rộng đun sôi lăn tăn trên lửa lớn. Trút toàn bộ thịt gà băm, tỏi băm và 5 ml nước mắm ngon vào, dùng muôi dằm và đảo liên tục khoảng 3–4 phút cho đến khi thịt gà tơi rời, chuyển trắng đục và chín hoàn toàn bên trong nhưng vẫn còn ít nước xào ẩm.', 'Tuyệt đối không xào khô cạn nước khiến thịt gà bị xơ; vừa thấy thịt chín hẳn không còn màu hồng là tắt bếp ngay.', 4),
('imp-cc6a0ca585b502d4_v4_step_3', 'imp-cc6a0ca585b502d4', 3, 'sauce', 'Tắt bếp ủ hành tím và nêm nước cốt chanh mắm', 'Tắt bếp rồi cho ngay hành tím thái lát mỏng vào chảo thịt gà còn nóng, đảo nhẹ để hơi ấm làm hành tím dịu bớt mùi hăng mà vẫn giữ độ giòn. Rưới tiếp 30 ml nước mắm ngon còn lại, 45 ml nước cốt chanh tươi và 4 g đường cát trắng vào trộn đều cho hòa vị.', NULL, 2),
('imp-cc6a0ca585b502d4_v4_step_4', 'imp-cc6a0ca585b502d4', 4, 'finish', 'Trộn thính gạo rang và ớt hiểm đỏ', 'Rắc từ từ 25 g thính gạo rang (Khao Khua) cùng ớt hiểm băm và lá chanh Thái thái chỉ vào chảo thịt ấm, đảo đều tay cho hạt thính thấm hút nước thịt quyện thành lớp áo sánh thơm đặc trưng.', 'Chỉ trộn thính gạo rang sau khi đã tắt bếp và ngay trước lúc dọn ăn để giữ mùi thơm bùi và độ sần sật chuẩn vị Isaan.', NULL),
('imp-cc6a0ca585b502d4_v4_step_5', 'imp-cc6a0ca585b502d4', 5, 'finish', 'Trộn hành lá, ngò rí và cân chỉnh vị', 'Thêm hành lá và ngò rí thái nhỏ vào đảo nhẹ một lượt. Nếm lại lần cuối để bảo đảm sự cân bằng giữa vị chua thanh của chanh, mặn thơm nước mắm, cay nồng của ớt và bùi béo của thính gạo.', NULL, NULL),
('imp-cc6a0ca585b502d4_v4_step_6', 'imp-cc6a0ca585b502d4', 6, 'finish', 'Bày đĩa cùng lá bạc hà tươi và dọn ấm', 'Múc larb gà ra đĩa, rắc lá bạc hà tươi lên trên mặt để giữ màu xanh mát không bị thâm nhiệt, dọn dùng ấm với xôi nếp hoặc cơm trắng và rau sống.', NULL, NULL),
('imp-6e4967b3145dee09_v4_step_1', 'imp-6e4967b3145dee09', 1, 'prep', 'Sơ chế nấm đùi gà, húng quế và pha sốt xào chay', 'Lau sạch 500 g nấm đùi gà bằng khăn ẩm, cắt bỏ gốc rồi thái lát vát dày 0,5 cm. Nhặt lá húng quế Thái rửa nhẹ rồi vẩy thật ráo nước. Thái miếng hành tây và ớt chuông đỏ; băm nhuyễn tỏi khô và 4 quả ớt hiểm đỏ; cắt khúc hành lá. Trong chén nhỏ, khuấy tan 30 ml dầu hào chay, 20 ml xì dầu nhạt, 8 ml xì dầu đặc, 15 g đường cát trắng và 20 ml nước lọc.', 'Vẩy thật ráo lá húng quế giúp chảo không bị bắn dầu và nước sốt xào giữ được độ sệt đậm đà không bị loãng.', NULL),
('imp-6e4967b3145dee09_v4_step_2', 'imp-6e4967b3145dee09', 2, 'cook', 'Áp chảo nấm đùi gà cho săn xém cạnh', 'Làm nóng chảo rộng trên lửa lớn với 15 ml dầu ăn thực vật, xếp nấm đùi gà dàn thành một lớp mỏng và để yên 2 phút cho mặt dưới hơi cháy xém vàng rồi mới đảo đều thêm 1 phút đến khi nấm săn lại, gạt nấm sang một bên chảo.', 'Để yên nấm 1–2 phút không đảo liên tục giúp nấm thoát bớt hơi nước và có lớp cháy cạnh thơm bùi thay vì bị ra nước nhũn.', 3),
('imp-6e4967b3145dee09_v4_step_3', 'imp-6e4967b3145dee09', 3, 'cook', 'Phi thơm tỏi ớt và xào rau củ', 'Thêm 10 ml dầu ăn thực vật còn lại vào phần trống trên chảo ở lửa vừa, cho tỏi băm và ớt hiểm băm vào phi khoảng 40 giây đến khi dậy mùi cay thơm nồng thì cho hành tây và ớt chuông đỏ vào đảo nhanh 1–2 phút cho rau củ vừa chín tới vẫn giữ độ giòn.', NULL, 2),
('imp-6e4967b3145dee09_v4_step_4', 'imp-6e4967b3145dee09', 4, 'cook', 'Áo đều sốt dầu hào chay trên lửa lớn', 'Bật lửa lớn, đảo chung nấm với rau củ rồi rưới đều chén sốt đã pha vào chảo. Xóc và đảo nhanh tay liên tục khoảng 2 phút cho đến khi nước sốt sôi sệt bóng mượt, áo bám đều từng lát nấm màu nâu hổ phách.', NULL, 2),
('imp-6e4967b3145dee09_v4_step_5', 'imp-6e4967b3145dee09', 5, 'finish', 'Tắt bếp trộn lá húng quế dậy hương', 'Tắt bếp ngay rồi trút toàn bộ 30 g lá húng quế Thái vào chảo nấm còn nóng, đảo nhanh tay trong 20–30 giây cho lá vừa héo mềm dưới nhiệt dư và dậy mùi thơm đặc trưng.', 'Luôn cho húng quế vào sau khi đã tắt bếp để giữ trọn tinh dầu thơm và màu xanh tươi, tránh bị thâm đen đắng.', NULL),
('imp-6e4967b3145dee09_v4_step_6', 'imp-6e4967b3145dee09', 6, 'finish', 'Trình bày ra đĩa và dùng nóng với cơm', 'Trút nấm xào húng quế ra đĩa, rắc thêm hành lá thái khúc lên trên và dọn dùng nóng ngay cùng cơm trắng dẻo.', NULL, NULL),
('imp-4d9fae75b597d2c5_v4_step_1', 'imp-4d9fae75b597d2c5', 1, 'prep', 'Thái thịt bò ngược thớ và băm nhuyễn sả tỏi', 'Đặt 500 g thịt thăn bò vào ngăn đá khoảng 20 phút cho hơi se cứng bề mặt rồi thái thành các lát mỏng đều khoảng 0,5 cm theo chiều ngang ngược thớ thịt. Bóc bỏ bẹ già của 3 cây sả tươi, lấy phần gốc trắng non băm thật nhuyễn; bóc vỏ tỏi khô rồi giã nhuyễn cùng 3 g tiêu đen xay.', 'Thái thịt bò ngược thớ giúp từng miếng thịt sau khi nướng dễ nhai, mềm ngọt và không bị dai gân.', 20),
('imp-4d9fae75b597d2c5_v4_step_2', 'imp-4d9fae75b597d2c5', 2, 'marinate', 'Trộn sốt sả và ướp lạnh thịt bò', 'Trong tô lớn, hòa tan 20 g đường nâu với 20 ml xì dầu nhạt, 20 ml nước mắm ngon, 15 ml dầu ăn thực vật và 5 ml dầu mè thơm đến khi đường tan hết. Thêm sả băm và hỗn hợp tỏi tiêu vào trộn đều rồi thả thịt bò vào bóp nhẹ cho gia vị áo đều từng lát. Bọc kín tô, ướp trong ngăn mát tủ lạnh ít nhất 30 phút.', 'Ướp thịt bò trong ngăn mát tối thiểu 30 phút (hoặc 2 giờ) giúp thịt ngấm sâu mùi sả tỏi và giữ được độ an toàn vệ sinh.', 30),
('imp-4d9fae75b597d2c5_v4_step_3', 'imp-4d9fae75b597d2c5', 3, 'prep', 'Làm nóng vỉ nướng và xiên que (nếu dùng)', 'Nếu xiên que tre, ngâm que trong nước sạch trước 30 phút để tránh cháy xém rồi xiên từng lát thịt bò dẹt theo dạng sóng. Làm nóng bếp than hoa hoặc vỉ nướng điện ở lửa vừa-lớn rồi phết lớp dầu mỏng lên mặt vỉ. Rũ nhẹ bớt vụn sả thừa bám dày trên thịt và bỏ phần nước ướp sống còn dư.', NULL, NULL),
('imp-4d9fae75b597d2c5_v4_step_4', 'imp-4d9fae75b597d2c5', 4, 'cook', 'Nướng nhanh thịt bò trên lửa vừa-lớn', 'Xếp các lát hoặc xiên thịt bò lên vỉ nóng sao cho không chồng lên nhau. Nướng khoảng 2–3 phút mỗi mặt đến khi bề mặt thịt chuyển nâu xém cạnh, mỡ rìa xèo thơm và thịt vừa chín tới bên trong mà không bị khô xác.', 'Lát thăn bò thái mỏng chín rất nhanh; tránh nướng quá 3 phút mỗi mặt kẻo thịt mất nước ngọt và bị dai.', 5),
('imp-4d9fae75b597d2c5_v4_step_5', 'imp-4d9fae75b597d2c5', 5, 'finish', 'Để thịt nghỉ ổn định nước ngọt', 'Gắp thịt bò nướng ra đĩa ấm, đậy hờ giấy bạc để thịt nghỉ trong 3 phút cho lượng nước ngọt phân bố đều trở lại trong từng thớ thịt.', NULL, 3),
('imp-4d9fae75b597d2c5_v4_step_6', 'imp-4d9fae75b597d2c5', 6, 'finish', 'Bày đĩa cùng chanh múi cau và ớt hiểm', 'Sắp xếp thịt bò nướng sả lên đĩa, đặt chanh tươi cắt múi cau và ớt hiểm đỏ thái lát bên cạnh để vắt thêm vị chua cay khi thưởng thức cùng cơm trắng, xôi nếp hoặc rau sống.', NULL, NULL),
('imp-a97820d3080e47eb_v4_step_1', 'imp-a97820d3080e47eb', 1, 'prep', 'Sơ chế tôm sú và chuẩn bị que xiên sả', 'Rửa sạch 500 g tôm sú tươi, cắt bỏ râu và chân, bóc vỏ phần thân nhưng giữ lại đầu và đuôi cho đẹp mắt; khía nhẹ dọc sống lưng rút sạch chỉ đen rồi thấm thật khô bằng khăn giấy. Lấy 2 cây sả tươi băm thật nhuyễn; 6 cây còn lại bóc lớp vỏ già, cắt khúc dài 15 cm, đập nhẹ phần gốc cho dậy mùi và vót nhọn một đầu làm que xiên.', 'Thấm thật khô con tôm giúp gia vị bám chặt và khi nướng không bị chảy nước làm nhạt thịt.', NULL),
('imp-a97820d3080e47eb_v4_step_2', 'imp-a97820d3080e47eb', 2, 'marinate', 'Ướp tôm với sả băm, dầu hào và nước mắm', 'Băm thật nhuyễn hành tím, tỏi khô và 2 quả ớt hiểm đỏ. Trộn đều tôm với sả băm, hành tỏi ớt băm, 15 ml dầu hào, 15 ml nước mắm ngon, 5 g đường cát trắng, 4 g hạt nêm, 2 g tiêu đen xay và 15 ml dầu ăn thực vật; ướp trong 20 phút cho tôm ngấm đều gia vị.', 'Chỉ dùng một lượng nhỏ đường cát trắng (5 g) để tôm lên màu vàng cam hấp dẫn mà không bị cháy đen bề mặt khi nướng nhiệt cao.', 20),
('imp-a97820d3080e47eb_v4_step_3', 'imp-a97820d3080e47eb', 3, 'prep', 'Xiên dọc thân tôm vào cây sả', 'Lần lượt dùng đầu nhọn của từng que sả xiên thẳng dọc từ phần đuôi xuyên qua thân tôm lên sát đầu để cố định dáng tôm thẳng đẹp và giúp tinh dầu sả tỏa thẳng vào phần thịt bên trong khi gặp nhiệt.', NULL, NULL),
('imp-a97820d3080e47eb_v4_step_4', 'imp-a97820d3080e47eb', 4, 'cook', 'Nướng tôm xiên sả vàng cam thơm lừng', 'Đặt các xiên tôm lên vỉ than hoa (hoặc xếp vào nồi chiên không dầu/lò nướng làm nóng sẵn ở 190°C) sao cho không chồng lên nhau. Nướng tổng cộng 8–10 phút, giữa chừng lật mặt một lần và phết nhẹ phần nước ướp còn lại trong âu lên thân tôm, đến khi vỏ đầu đuôi chuyển đỏ cam bóng đẹp và thịt tôm trắng đục săn chắc hoàn toàn.', 'Không nướng tôm quá lâu qua 10 phút vì thịt tôm sẽ mất nước, bị teo và khô dai.', 9),
('imp-a97820d3080e47eb_v4_step_5', 'imp-a97820d3080e47eb', 5, 'sauce', 'Giã chén muối ớt chanh chấm kèm', 'Trong lúc chờ tôm chín, giã nhuyễn 1 quả ớt hiểm đỏ còn lại với 3 g muối ăn trong cối nhỏ, sau đó vắt nước cốt 1 quả chanh tươi vào khuấy đều để tạo chén muối ớt chanh chua cay mặn hài hòa.', NULL, NULL),
('imp-a97820d3080e47eb_v4_step_6', 'imp-a97820d3080e47eb', 6, 'finish', 'Trình bày xiên tôm nướng và dùng nóng', 'Xếp các xiên tôm nướng sả còn bốc khói ra đĩa, dọn dùng nóng ngay cùng chén muối ớt chanh, xà lách và dưa leo tươi.', NULL, NULL),
('imp-a9d8b4d783b986d1_v4_step_1', 'imp-a9d8b4d783b986d1', 1, 'prep', 'Sơ chế tôm khô ráo, sả non và pha sốt cơm chiên', 'Tôm tươi bóc vỏ, rút chỉ đen, rửa sạch rồi dùng khăn giấy thấm thật khô. Bóc vỏ già 2 cây sả tươi, chỉ lấy phần gốc non thái lát thật mỏng. Tỏi khô băm nhỏ, cà rốt thái hạt lựu, hành lá tách riêng đầu trắng và lá xanh thái nhỏ, ớt hiểm thái lát. Đánh tơi 450 g cơm nguội và đánh tan 2 quả trứng gà. Hòa tan 20 ml xì dầu nhạt, 20 ml dầu hào, 10 ml nước mắm ngon, 5 g đường cát trắng và 20 ml nước lọc trong chén.', 'Chỉ dùng phần gốc non thái mỏng của cây sả giúp bạn ăn trực tiếp cùng cơm mà không bị xơ cứng, đồng thời thấm khô tôm để tôm không ra nước.', NULL),
('imp-a9d8b4d783b986d1_v4_step_2', 'imp-a9d8b4d783b986d1', 2, 'cook', 'Phi thơm sả tỏi và xào săn chín tôm tươi', 'Làm nóng 20 ml dầu ăn thực vật trong chảo lớn ở lửa lớn. Cho sả thái mỏng, đầu hành trắng, tỏi băm và ớt hiểm thái lát vào phi 30 giây đến khi thơm dịu (không để cháy tỏi), trút tôm vào xào nhanh 2–3 phút đến khi tôm cong tròn, chuyển màu hồng đỏ đục và chín hoàn toàn rồi gắp riêng ra đĩa.', 'Áp chảo tôm trước rồi gắp ra riêng giúp tôm giữ độ giòn ngọt và không bị nấu quá lửa dai cứng trong lúc rang cơm.', 3),
('imp-a9d8b4d783b986d1_v4_step_3', 'imp-a9d8b4d783b986d1', 3, 'cook', 'Chiên tơi trứng gà và xào cà rốt', 'Thêm 10 ml dầu ăn thực vật vào chảo đang nóng, đổ trứng gà đánh tan vào đảo nhanh tay cho tơi xốp rồi cho cà rốt vào xào thêm 2 phút trên lửa vừa-lớn đến khi cà rốt hơi mềm.', NULL, 2),
('imp-a9d8b4d783b986d1_v4_step_4', 'imp-a9d8b4d783b986d1', 4, 'cook', 'Rang cơm nguội tơi hạt trên lửa lớn', 'Trút toàn bộ 450 g cơm nguội vào chảo, tăng lửa lớn và đảo đều liên tục khoảng 3 phút cho hạt cơm nóng đều, tơi rời từng hạt và quyện cùng trứng, cà rốt.', NULL, 3),
('imp-a9d8b4d783b986d1_v4_step_5', 'imp-a9d8b4d783b986d1', 5, 'cook', 'Rưới sốt và đảo chung tôm hoàn thiện', 'Rưới đều chén sốt đã pha quanh thành chảo nóng cho bốc mùi thơm, đảo nhanh tay 2 phút đến khi cơm khô ráo thấm đều màu sắc hấp dẫn. Trút đĩa tôm đã xào trở lại chảo cùng tiêu trắng xay, đảo đều thêm 1 phút cho tôm nóng lại.', 'Đổ hỗn hợp sốt quanh thành chảo nóng rồi đảo nhanh tay giúp sốt sánh nhẹ thơm mùi khói chảo mà không làm hạt cơm bị ướt nhão.', 3),
('imp-a9d8b4d783b986d1_v4_step_6', 'imp-a9d8b4d783b986d1', 6, 'finish', 'Tắt bếp trộn hành lá và dọn nóng với chanh', 'Tắt bếp rồi cho phần lá hành xanh thái nhỏ vào đảo nhanh một vòng giữ màu xanh tươi. Xới cơm chiên tôm sả ra đĩa, xếp kèm chanh tươi cắt múi cau để vắt nhẹ và thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-4095c816782acd82_v4_step_1', 'imp-4095c816782acd82', 1, 'prep', 'Sơ chế cà chua, tôm khô và giã đậu phộng rang', 'Cà chua chín rửa sạch, dùng khăn thấm ráo, bỏ cuống rồi bổ 6 múi cau vừa ăn xếp vào âu trộn lớn. Tôm khô ngâm nước ấm 5 phút cho mềm rồi vớt để ráo. Làm nóng chảo khô ở lửa nhỏ, đảo đều 35 g đậu phộng trong 3 phút đến khi vàng giòn thơm, để nguội xát sạch vỏ lụa rồi giã dập thô.', 'Chọn cà chua vừa chín tới, cầm chắc tay để khi trộn múi cà chua không bị nát bấy và giữ được độ giòn mọng.', 3),
('imp-4095c816782acd82_v4_step_2', 'imp-4095c816782acd82', 2, 'prep', 'Chuẩn bị tỏi, ớt hiểm và rau thơm', 'Bóc vỏ tỏi khô rồi giã hoặc băm thật nhuyễn. Ớt hiểm đỏ thái lát mỏng (có thể bỏ bớt hạt nếu muốn giảm độ cay). Rửa sạch hành lá và ngò rí, để ráo nước rồi thái lát vát mỏng phần hành lá và cắt khúc ngắn ngò rí. Vắt 2 quả chanh tươi lấy khoảng 45 ml nước cốt.', NULL, NULL),
('imp-4095c816782acd82_v4_step_3', 'imp-4095c816782acd82', 3, 'sauce', 'Pha nước trộn salad chua cay mặn ngọt Thái', 'Cho 15 g đường thốt nốt, 30 ml nước mắm ngon và 45 ml nước cốt chanh tươi vào chén nhỏ, khuấy kỹ đến khi đường tan hoàn toàn. Thêm tỏi băm và ớt hiểm thái lát vào khuấy đều, nếm thử để chắc chắn vị chua, cay, mặn, ngọt hơi đậm một chút vì cà chua sẽ tiết thêm nước.', 'Dùng đường thốt nốt giúp nước trộn có độ sánh mượt nhẹ và vị ngọt hậu thanh hơn đường trắng thông thường.', NULL),
('imp-4095c816782acd82_v4_step_4', 'imp-4095c816782acd82', 4, 'finish', 'Trộn nhẹ tay cà chua và tôm khô với nước sốt', 'Rắc tôm khô mềm lên âu cà chua rồi rưới đều toàn bộ chén nước trộn lên trên. Dùng hai chiếc muỗng lớn hất trộn nhẹ tay 4–5 lượt cho nước sốt áo đều từng múi cà chua mà không làm dập ruột.', 'Dùng hai chiếc muỗng lớn hất trộn từ dưới lên thay vì khuấy vòng tròn giúp các múi cà chua nguyên vẹn và thấm đều nước trộn.', NULL),
('imp-4095c816782acd82_v4_step_5', 'imp-4095c816782acd82', 5, 'finish', 'Ướp thấm vị ngắn trước khi bày đĩa', 'Để âu salad cà chua nghỉ khoảng 5 phút ở nhiệt độ phòng (hoặc 10 phút trong ngăn mát tủ lạnh) cho cà chua tiết ra nước ngọt tự nhiên hòa quyện vào sốt chua cay.', NULL, 5),
('imp-4095c816782acd82_v4_step_6', 'imp-4095c816782acd82', 6, 'finish', 'Rắc hành lá, ngò rí và đậu phộng rang thưởng thức', 'Trút salad cà chua cùng nước sốt ra đĩa sâu lòng, rắc hành lá, ngò rí và đậu phộng rang giã dập lên trên cùng rồi dùng mát ngay.', NULL, NULL),
('imp-0e9c9740a6232263_v4_step_1', 'imp-0e9c9740a6232263', 1, 'prep', 'Giã tỏi ớt, sơ chế rau và pha sốt xào Thái', 'Cho tỏi khô đã bóc vỏ và 5 quả ớt hiểm đỏ vào cối giã thô (hoặc đập dập băm nhuyễn). Nhặt lá húng quế Thái rửa nhẹ và vẩy thật ráo nước; thái hạt lựu đậu đũa; thái nhỏ hành lá. Trong chén, hòa tan 25 ml dầu hào, 15 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml nước mắm ngon, 10 g đường cát trắng và 30 ml nước lọc.', 'Giã thô tỏi và ớt bằng cối giúp tinh dầu vỡ ra nhiều hơn khi gặp dầu nóng, tạo mùi thơm nồng hơn hẳn so với băm bằng dao.', NULL),
('imp-0e9c9740a6232263_v4_step_2', 'imp-0e9c9740a6232263', 2, 'cook', 'Chiên trứng ốp la viền giòn lòng đào', 'Làm nóng chảo với 15 ml dầu ăn thực vật trên lửa vừa-lớn, đập từng quả trứng gà vào chiên khoảng 2 phút đến khi viền lòng trắng vàng giòn rụm còn lòng đỏ vẫn sánh dẻo, vớt ra đĩa lót giấy thấm dầu.', NULL, 2),
('imp-0e9c9740a6232263_v4_step_3', 'imp-0e9c9740a6232263', 3, 'cook', 'Phi thơm tỏi ớt và xào săn tơi thịt heo xay', 'Gạt bớt dầu thừa nếu cần hoặc dùng 15 ml dầu ăn thực vật còn lại trên lửa vừa-lớn, cho hỗn hợp tỏi ớt giã vào phi thơm 30 giây đến khi hơi vàng cạnh. Trút toàn bộ 450 g thịt heo xay vào, dùng xẻng dằm tơi liên tục trên lửa lớn trong 3 phút đến khi thịt tơi đều, hết màu hồng và chín hoàn toàn.', 'Xào thịt heo xay trên lửa lớn và dằm liên tục để thịt săn ráo tơi hạt, không bị vón cục hay ra nhiều nước đục.', 3),
('imp-0e9c9740a6232263_v4_step_4', 'imp-0e9c9740a6232263', 4, 'cook', 'Xào đậu đũa và rưới sốt áo đều thịt heo', 'Cho đậu đũa thái nhỏ vào đảo nhanh 1 phút cho giòn chín tới, rồi rưới đều toàn bộ chén sốt đã pha vào chảo. Tiếp tục đảo trên lửa lớn thêm 2 phút cho nước sốt sôi sệt, bám màu nâu cánh gián bóng mượt quanh từng hạt thịt và đậu.', NULL, 3),
('imp-0e9c9740a6232263_v4_step_5', 'imp-0e9c9740a6232263', 5, 'finish', 'Tắt bếp trộn lá húng quế Thái giữ hương thơm', 'Tắt bếp ngay rồi cho toàn bộ 30 g lá húng quế Thái vào chảo thịt còn nóng, đảo nhanh 15–20 giây để lá vừa héo mềm giữ nguyên màu xanh thẫm và tỏa hương thơm nồng đặc trưng.', 'Không xào húng quế quá lâu trên bếp đang bật lửa vì lá sẽ chuyển màu đen sẫm và mất mùi thơm tươi.', NULL),
('imp-0e9c9740a6232263_v4_step_6', 'imp-0e9c9740a6232263', 6, 'finish', 'Bày đĩa cùng trứng ốp la và dùng nóng', 'Múc thịt heo xào húng quế cùng phần sốt đọng trong chảo ra đĩa, rắc hành lá thái nhỏ lên trên, đặt bên cạnh cơm trắng nóng và trứng ốp la lòng đào để thưởng thức ngay.', NULL, NULL),
('imp-b6d6788784da6342_v4_step_1', 'imp-b6d6788784da6342', 1, 'prep', 'Làm sạch, khứa thân và ướp gia vị cho cá', 'Cá điêu hồng sau khi đánh vảy, bỏ mang và làm sạch bụng, dùng khăn giấy thấm thật khô cả trong lẫn ngoài rồi khía 3–4 đường chéo sâu trên hai bên thân cá. Xát đều 15 ml nước mắm ngon, 5 g muối ăn và 3 g tiêu trắng xay lên mình cá và vào các rãnh khứa, ướp 15 phút cho thịt cá săn đậm vị.', 'Thấm thật khô con cá trước khi ướp và trước khi áo bột là bước then chốt giúp dầu không bắn và da cá giòn phồng.', 15),
('imp-b6d6788784da6342_v4_step_2', 'imp-b6d6788784da6342', 2, 'prep', 'Áo bột mỏng và chuẩn bị tỏi ớt giã thô', 'Phủ nhẹ 20 g bột mì đa dụng thành lớp thật mỏng khắp hai mặt cá rồi giũ sạch phần bột thừa. Giã hoặc băm thô tỏi khô và 4 quả ớt hiểm đỏ sao cho còn hơi lợn cợn tự nhiên; băm nhỏ đường thốt nốt; vắt chanh tươi lấy 20 ml nước cốt; thái lát mỏng hành lá.', NULL, NULL),
('imp-b6d6788784da6342_v4_step_3', 'imp-b6d6788784da6342', 3, 'cook', 'Chiên cá vàng giòn hai mặt trên lửa vừa', 'Đun nóng 415 ml dầu ăn thực vật trong chảo sâu lòng trên lửa vừa đến khi nhúng đầu đũa thấy sủi tăm mạnh (khoảng 175°C). Cầm đuôi thả nhẹ cá trượt từ thành chảo vào, chiên 6–7 phút mỗi mặt đến khi lớp da chuyển vàng ruộm giòn tan và thịt cá bên trong chín trắng đục hoàn toàn, vớt ra đặt lên giá lưới cho ráo dầu.', 'Không lật cá quá sớm khi mặt dưới chưa đóng vảy giòn để tránh rách da dính chảo.', 14),
('imp-b6d6788784da6342_v4_step_4', 'imp-b6d6788784da6342', 4, 'sauce', 'Phi tỏi ớt và thắng nhẹ đường thốt nốt làm sốt', 'Đun nóng 35 ml dầu ăn thực vật trong chảo sạch ở lửa vừa, cho tỏi ớt giã thô vào phi khoảng 1–2 phút đến khi dậy mùi cay thơm và tỏi vừa chuyển vàng nhạt. Cho 25 g đường thốt nốt vào đảo đều 30 giây cho đường tan chảy hơi caramen nhẹ.', 'Phi tỏi ớt ở lửa vừa để tỏi chín thơm dịu mà không bị cháy đắng trước khi cho đường và nước mắm vào.', 2),
('imp-b6d6788784da6342_v4_step_5', 'imp-b6d6788784da6342', 5, 'sauce', 'Nấu sánh sốt mắm chanh cay ngọt kiểu Thái', 'Rót 25 ml nước mắm ngon còn lại, 60 ml nước lọc và 20 ml nước cốt chanh tươi vào chảo tỏi ớt, hạ lửa nhỏ đun sôi lăn riu và khuấy đều trong 2–3 phút cho đến khi nước sốt sánh sệt óng ả. Nếm lại bảo đảm đủ 4 vị mặn, ngọt, chua, cay cân bằng hài hòa.', NULL, 3),
('imp-b6d6788784da6342_v4_step_6', 'imp-b6d6788784da6342', 6, 'finish', 'Rưới sốt cay nóng lên cá giòn và dọn ăn ngay', 'Đặt cá chiên giòn ra đĩa lớn, rưới đều nước sốt tỏi ớt nóng hổi lên khắp thân cá vào phút cuối ngay trước khi dọn bàn, rắc hành lá thái lát lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-71cac2085659d819_v4_step_1', 'imp-71cac2085659d819', 1, 'prep', 'Ướp đùi gà và sơ chế dứa, rau củ đồng đều', 'Thấm khô 500 g thịt đùi gà lọc xương, cắt miếng vuông 2,5 cm rồi ướp với 2 g muối ăn và 2 g tiêu đen xay trong 10 phút. Dứa gọt vỏ bỏ mắt thái miếng vừa ăn; ớt chuông đỏ và hành tây cắt vuông 2,5 cm; đậu Hà Lan tước xơ cắt đôi; tỏi khô băm nhỏ; hành lá cắt khúc 2 cm; ớt hiểm thái lát.', 'Cắt thịt gà, ớt chuông, hành tây và dứa cùng kích thước vuông khoảng 2,5 cm giúp món xào chín đều và đẹp mắt.', 10),
('imp-71cac2085659d819_v4_step_2', 'imp-71cac2085659d819', 2, 'sauce', 'Pha sẵn nước sốt chua ngọt và nước bột bắp', 'Trong chén lớn, khuấy tan 45 ml giấm gạo, 20 g đường nâu, 15 ml tương ớt ngọt Thái và 15 ml nước mắm ngon. Trong chén nhỏ khác, hòa tan hoàn toàn 6 g bột bắp với 25 ml nước lọc để sẵn.', NULL, NULL),
('imp-71cac2085659d819_v4_step_3', 'imp-71cac2085659d819', 3, 'cook', 'Xào nhanh hành tây và ớt chuông giữ độ giòn', 'Làm nóng 10 ml dầu ăn thực vật trong chảo rộng ở lửa vừa-lớn, cho hành tây, ớt chuông đỏ và tỏi băm vào đảo nhanh khoảng 2 phút đến khi rau củ hơi xém cạnh thơm giòn thì trút riêng ra tô.', 'Xào sơ rau củ trước rồi lấy ra giúp giữ nguyên độ giòn ngọt tự nhiên và màu sắc tươi tắn không bị nhũn khi rim gà.', 2),
('imp-71cac2085659d819_v4_step_4', 'imp-71cac2085659d819', 4, 'cook', 'Áp chảo vàng thịt đùi gà và rim sốt chua ngọt', 'Cho 10 ml dầu ăn thực vật còn lại vào chảo, xếp thịt đùi gà thành một lớp và áp chảo khoảng 4 phút trên lửa vừa-lớn (lật mặt sau 2 phút) đến khi thịt gà xém vàng đều các cạnh. Rưới hỗn hợp sốt giấm đường đã pha vào đảo đều, hạ lửa vừa rim thêm 3 phút cho gà chín hoàn toàn bên trong và thấm vị.', NULL, 7),
('imp-71cac2085659d819_v4_step_5', 'imp-71cac2085659d819', 5, 'cook', 'Trộn dứa, đậu Hà Lan và làm sánh sốt với bột bắp', 'Trút lại tô hành tây, ớt chuông cùng dứa tươi và đậu Hà Lan vào chảo gà, đảo đều 1–2 phút cho đậu vừa chín tới. Khuấy đều chén nước bột bắp rồi rưới từ từ vào chảo, đảo liên tục thêm 1 phút đến khi nước sốt sánh trong óng ánh bám đều lên thịt gà và rau củ.', 'Cho dứa vào ở bước cuối cùng giúp dứa không bị nát và giữ được độ giòn mọng thanh mát.', 3),
('imp-71cac2085659d819_v4_step_6', 'imp-71cac2085659d819', 6, 'finish', 'Nêm lại vị, rắc hành lá và dùng nóng', 'Tắt bếp, nếm thử để bảo đảm vị chua ngọt hài hòa, rắc hành lá cắt khúc và ớt hiểm thái lát lên trên rồi dọn nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-b398545ca76325f1_v4_step_1', 'imp-b398545ca76325f1', 1, 'prep', 'Sơ chế bắp cải, đậu phụ, cà rốt và sả', 'Bắp cải xanh tách từng lá rửa sạch, lược bỏ phần cuống cứng rồi thái hoặc xé miếng vuông cỡ 4 cm để ráo. Cà rốt gọt vỏ, thái lát mỏng 0,3 cm. Đậu phụ trắng cắt khối vuông 2 cm. Sả tươi bóc bẹ già, dùng sống dao đập dập rồi cắt khúc 6 cm. Vắt 1,5 quả chanh tươi lấy 30 ml nước cốt; rửa sạch và thái nhỏ hành lá, ngò rí.', 'Thái bỏ bớt phần gân cứng ở cuống bắp cải giúp lá bắp cải chín đồng đều cùng lúc và giữ độ giòn ngọt.', NULL),
('imp-b398545ca76325f1_v4_step_2', 'imp-b398545ca76325f1', 2, 'cook', 'Xào thơm sả cà rốt và ninh nước dùng sả', 'Đun nóng 10 ml dầu ăn thực vật trong nồi ở lửa vừa, cho sả tươi đập dập và cà rốt thái lát vào đảo sơ 1 phút cho dậy mùi thơm dịu. Đổ 1000 ml nước lọc vào đun lửa lớn đến khi sôi bùng rồi hạ lửa vừa nấu 4 phút cho nước dùng thấm tinh dầu sả và cà rốt bắt đầu mềm.', NULL, 4),
('imp-b398545ca76325f1_v4_step_3', 'imp-b398545ca76325f1', 3, 'cook', 'Nấu bắp cải xanh và nêm gia vị chay', 'Thả toàn bộ bắp cải xanh vào nồi nước sả, nêm 8 g hạt nêm chay nấm hương và 6 g đường cát trắng. Nấu ở lửa vừa khoảng 4–5 phút đến khi lá bắp cải chuyển màu xanh trong, vừa chín mềm mà vẫn còn độ giòn nhẹ.', 'Không đậy nắp quá kín và không nấu bắp cải quá lâu để lá giữ màu xanh tươi đẹp mắt và nước canh không bị nồng.', 5),
('imp-b398545ca76325f1_v4_step_4', 'imp-b398545ca76325f1', 4, 'cook', 'Thả đậu phụ nấu nóng đều', 'Nhẹ nhàng thả các miếng đậu phụ cắt khối vào nồi, đun sôi lăn riu thêm 2 phút trên lửa vừa để đậu phụ nóng đều và thấm vị ngọt thanh của nước canh mà không bị vỡ nát.', NULL, 2),
('imp-b398545ca76325f1_v4_step_5', 'imp-b398545ca76325f1', 5, 'finish', 'Tắt bếp nêm nước mắm chay và nước cốt chanh', 'Tắt bếp rồi rót 25 ml nước mắm chay và 30 ml nước cốt chanh tươi vào nồi canh, khuấy nhẹ một vòng để vị chua thanh của chanh hòa quyện mà không bị bay mất hương tươi.', 'Luôn tắt bếp trước khi cho nước cốt chanh để canh có mùi thơm dịu tự nhiên và không bị đắng.', NULL),
('imp-b398545ca76325f1_v4_step_6', 'imp-b398545ca76325f1', 6, 'finish', 'Hoàn thiện với hành ngò và dùng nóng', 'Gắp bỏ bớt các khúc sả già, múc canh bắp cải sả ra tô lớn, rắc hành lá và ngò rí thái nhỏ lên trên rồi dùng nóng.', NULL, NULL),
('imp-9f9a3f24b4141acb_v4_step_1', 'imp-9f9a3f24b4141acb', 1, 'prep', 'Làm khô cua lột và băm hương liệu Thái', 'Rã đông hoàn toàn nếu dùng cua lột đông lạnh, rửa nhanh rồi cắt mỗi con làm 4 phần vừa ăn, dùng khăn giấy ép thấm thật khô ráo nước. Bóc vỏ 3 củ tỏi khô băm nhỏ (chia 2/3 để chiên vàng trước và 1/3 để xào); băm nhỏ 4 quả ớt hiểm đỏ và phần rễ ngò rí đã rửa sạch; hành lá tách riêng đầu trắng và lá xanh cắt khúc 2 cm, giữ lá ngò rí trang trí.', 'Cua lột phải được thấm thật khô ráo nước trước khi lăn bột thì dầu chiên mới không bắn và vỏ cua mới giữ độ giòn lâu.', NULL),
('imp-9f9a3f24b4141acb_v4_step_2', 'imp-9f9a3f24b4141acb', 2, 'cook', 'Chiên vàng giòn phần tỏi phi rắc mặt', 'Đun nóng 500 ml dầu ăn thực vật trong chảo sâu lòng ở lửa vừa-nhỏ. Thả 2/3 phần tỏi băm vào chiên đảo đều khoảng 2 phút đến khi tỏi vừa chuyển màu vàng sáng thì lập tức vớt ra rây hoặc giấy thấm dầu để nguội cho giòn rụm.', 'Vớt tỏi phi ngay khi màu vàng còn nhạt vì sức nóng dư sẽ tiếp tục làm tỏi vàng sẫm giòn tan mà không bị đắng khét.', 2),
('imp-9f9a3f24b4141acb_v4_step_3', 'imp-9f9a3f24b4141acb', 3, 'prep', 'Áo bột chiên giòn khô quanh miếng cua', 'Trộn đều 120 g bột chiên giòn khô với 2 g muối ăn và 2 g tiêu trắng xay trong tô lớn. Thả từng mẻ cua vào xóc nhẹ cho bột bám một lớp áo mỏng khô đều khắp các chân và thân cua, giũ rơi phần bột thừa.', NULL, NULL),
('imp-9f9a3f24b4141acb_v4_step_4', 'imp-9f9a3f24b4141acb', 4, 'cook', 'Chiên ngập dầu cua lột vàng giòn rụm', 'Tăng lửa vừa-lớn đưa dầu trong chảo lên khoảng 175–180°C. Thả cua đã áo bột vào chiên từng mẻ trong 4–5 phút đến khi vỏ cua chuyển màu vàng cam giòn rụm và thịt cua chín chắc hoàn toàn bên trong, vớt ra đặt lên giấy thấm dầu.', 'Chia cua chiên làm 2 mẻ để nhiệt dầu không bị tụt đột ngột khiến lớp bột bị ngấm dầu và ỉu mềm.', 5),
('imp-9f9a3f24b4141acb_v4_step_5', 'imp-9f9a3f24b4141acb', 5, 'cook', 'Phi thơm rễ ngò rí, tỏi ớt và xóc cua với xì dầu', 'Chắt gạn bớt dầu chiên ra bát riêng, chỉ chừa lại khoảng 15 ml dầu trong chảo ở lửa nhỏ. Phi thơm 1/3 lượng tỏi băm còn lại, rễ ngò rí băm và 2/3 lượng ớt hiểm băm trong 1 phút, sau đó bật lửa lớn cho đầu hành trắng và phần ớt băm còn lại vào đảo nhanh 30 giây. Trút cua chiên vào chảo, nêm 20 ml xì dầu, 3 g muối ăn còn lại và 5 g đường cát trắng rồi xóc đều thật nhanh tay trong 1 phút.', NULL, 2),
('imp-9f9a3f24b4141acb_v4_step_6', 'imp-9f9a3f24b4141acb', 6, 'finish', 'Trộn hành lá, rắc tỏi phi giòn và thưởng thức nóng', 'Cho phần lá hành xanh cắt khúc vào đảo nhanh 1 lượt rồi tắt bếp ngay. Gắp cua ra đĩa, rắc ngập phần tỏi phi vàng giòn lên trên, trang trí lá ngò rí và dùng ngay khi cua còn nóng giòn.', NULL, NULL),
('imp-8fecebfe6dc0f0a2_v4_step_1', 'imp-8fecebfe6dc0f0a2', 1, 'prep', 'Rang thơm hạnh nhân và sơ chế rau bina', 'Đặt chảo khô lên lửa vừa, cho 30 g hạnh nhân lát vào rang khoảng 2–3 phút, đảo liên tục đến khi hạnh nhân vàng nhẹ và dậy mùi thơm bùi thì đổ ra đĩa để nguội. Nhặt và rửa sạch 200 g rau bina tươi dưới vòi nước lạnh.', 'Rang hạnh nhân ở lửa vừa và đảo đều tay để hạt chín thơm từ trong mà không bị cháy sém bên ngoài.', 3),
('imp-8fecebfe6dc0f0a2_v4_step_2', 'imp-8fecebfe6dc0f0a2', 2, 'cook', 'Chần nhanh rau bina và vắt kiệt nước', 'Đun sôi 2 lít nước lọc trong nồi lớn, thả rau bina tươi vào chần khoảng 2 phút cho lá vừa chín xẹp và giữ màu xanh mướt. Vớt ngay rau ra rổ (giữ lại nồi nước trên bếp để luộc mì), để nguội bớt rồi dùng tay vắt thật kiệt nước.', 'Vắt thật ráo nước sau khi chần là bí quyết giúp sốt rau bina đặc mịn, đậm đà và không bị tách nước khi trộn mì.', 2),
('imp-8fecebfe6dc0f0a2_v4_step_3', 'imp-8fecebfe6dc0f0a2', 3, 'sauce', 'Xay nhuyễn sốt kem rau bina với phô mai', 'Cho rau bina đã vắt ráo, 20 g hạnh nhân rang, 60 g phô mai Ricotta tươi, 25 g phô mai Parmesan bào mịn, tỏi tươi bóc vỏ, 2 g muối ăn và 1,5 g tiêu đen xay vào cối xay. Bật máy xay đồng thời rót từ từ 40 ml dầu ô liu nguyên chất vào đến khi thu được hỗn hợp kem xanh sánh mịn.', NULL, NULL),
('imp-8fecebfe6dc0f0a2_v4_step_4', 'imp-8fecebfe6dc0f0a2', 4, 'cook', 'Luộc mì Ý al dente trong nước muối sôi', 'Cho 6 g muối ăn vào nồi nước vừa chần rau, đun sôi già trở lại rồi thả 270 g mì Ý spaghetti vào luộc khoảng 8–9 phút đến độ chín al dente (mềm ngoài, hơi dai nhẹ ở lõi). Trước khi chắt ráo, múc giữ lại 100 ml nước luộc mì nóng.', NULL, 9),
('imp-8fecebfe6dc0f0a2_v4_step_5', 'imp-8fecebfe6dc0f0a2', 5, 'finish', 'Trộn đều mì nóng với sốt rau bina', 'Cho mì Ý vừa vớt còn nóng vào tô trộn lớn cùng toàn bộ sốt kem rau bina. Đảo nhanh tay cho sốt bám đều từng sợi mì; nếu sốt hơi đặc, rưới thêm từng muỗng canh nước luộc mì ấm và trộn tiếp đến khi sốt bóng mượt.', 'Trộn sốt bằng sức nóng dư của sợi mì thay vì đun trực tiếp trên bếp giúp giữ trọn màu xanh ngọc và vị tươi thanh của rau bina.', NULL),
('imp-8fecebfe6dc0f0a2_v4_step_6', 'imp-8fecebfe6dc0f0a2', 6, 'finish', 'Trang trí hạnh nhân, parmesan và dọn ngay', 'Chia mì ra 3 đĩa sâu lòng, rắc 10 g phô mai Parmesan bào mịn và 10 g hạnh nhân rang còn lại lên trên mặt mì rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-20d3992a65cb17fd_v4_step_1', 'imp-20d3992a65cb17fd', 1, 'marinate', 'Sơ chế nguyên liệu và ướp ức gà', 'Ức gà phi lê rửa sạch, thấm khô, cắt miếng vuông cỡ 2 cm rồi ướp với 2 g muối ăn và 1 g tiêu đen xay trong 10 phút. Nấm đùi gà thái lát dày 0,5 cm, cà chua chín thái miếng nhỏ, tỏi tươi băm nhuyễn và ngò tây tươi băm nhỏ.', NULL, 10),
('imp-20d3992a65cb17fd_v4_step_2', 'imp-20d3992a65cb17fd', 2, 'cook', 'Áp chảo vàng đều miếng ức gà', 'Làm nóng 15 ml dầu ô liu nguyên chất trong chảo lớn trên lửa vừa-lớn. Dàn đều thịt ức gà thành một lớp, áp chảo khoảng 6 phút cho đến khi thịt vàng đều các mặt và chín tới hoàn toàn bên trong, rồi gắp gà ra đĩa riêng.', 'Không xếp thịt gà quá dày một lượt trong chảo để thịt không bị ra nước mà giữ được độ xém thơm mềm mọng.', 6),
('imp-20d3992a65cb17fd_v4_step_3', 'imp-20d3992a65cb17fd', 3, 'cook', 'Xào nấm đùi gà lửa lớn và nấu sốt cà chua', 'Vẫn chiếc chảo đó, thêm 20 ml dầu ô liu nguyên chất vào phi thơm tỏi băm trong 45 giây trên lửa vừa. Tăng lửa lớn, cho nấm đùi gà vào xào 5 phút đến khi nấm săn ráo và xém vàng nhẹ cạnh, nêm 2 g muối ăn và 1 g tiêu đen xay. Tiếp tục thả cà chua chín vào đảo 3 phút cho cà chua mềm tiết nước tạo sốt.', 'Xào nấm ở lửa lớn giúp nước nấm bay hơi nhanh, giữ được độ giòn ngọt và hương thơm đặc trưng.', 8),
('imp-20d3992a65cb17fd_v4_step_4', 'imp-20d3992a65cb17fd', 4, 'cook', 'Luộc mì Ý trong nồi nước muối sôi già', 'Trong lúc xào nấm và cà chua, đun sôi 2 lít nước lọc với 6 g muối ăn. Cho 320 g mì Ý spaghetti vào luộc khoảng 8–9 phút đến độ chín al dente, trước khi vớt nhớ múc giữ lại 120 ml nước luộc mì nóng.', 'Luộc mì ít hơn hướng dẫn bao bì 1 phút để sợi mì còn độ dai vừa phải khi đảo tiếp cùng sốt trên chảo.', 9),
('imp-20d3992a65cb17fd_v4_step_5', 'imp-20d3992a65cb17fd', 5, 'cook', 'Xóc mì Ý cùng thịt gà, nấm và nước luộc mì', 'Trút thịt ức gà đã áp chảo trở lại chảo sốt nấm cà chua, cho tiếp mì Ý vừa vớt ráo và khoảng 80–120 ml nước luộc mì vào. Xóc đảo đều tay trên lửa vừa-lớn trong 2 phút để tinh bột quyện sốt thành lớp áo bóng mượt bám quanh từng sợi mì.', NULL, 2),
('imp-20d3992a65cb17fd_v4_step_6', 'imp-20d3992a65cb17fd', 6, 'finish', 'Rắc ngò tây, phô mai Parmesan và dùng nóng', 'Tắt bếp, cho phần ngò tây tươi băm nhỏ vào đảo nhanh một lượt cho giữ màu và hương thơm tươi mát. Chia mì gà nấm ra 4 đĩa sâu lòng, rắc phô mai Parmesan bào (tùy thích) lên mặt rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-38137393c32d70d7_v4_step_1', 'imp-38137393c32d70d7', 1, 'prep', 'Bóc tôm giữ vỏ đầu và sơ chế rau củ', 'Rửa sạch 450 g tôm tươi, tách riêng phần đầu và vỏ tôm để nấu nước dùng. Rút sạch chỉ đen trên lưng tôm; giữ một nửa số thịt tôm nguyên con để áp chảo trang trí, nửa còn lại băm nhỏ. Cà rốt tươi và cần tây tươi cắt khúc to; tách riêng cọng và lá ngò tây tươi.', 'Tôm tươi còn nguyên đầu và vỏ là yếu tố tạo nên phần nước dùng ngọt đậm vị biển mà không cần thêm bột nêm.', NULL),
('imp-38137393c32d70d7_v4_step_2', 'imp-38137393c32d70d7', 2, 'cook', 'Rang vỏ tôm và ninh nước dùng hải sản', 'Làm nóng 10 ml dầu ô liu nguyên chất trong nồi trên lửa vừa, cho vỏ và đầu tôm vào rang đảo khoảng 3 phút đến khi chuyển màu hồng cam và dậy hương thơm. Thêm cà rốt, cần tây, 1 củ hành tím bổ đôi, 1 tép tỏi đập dập và cọng ngò tây vào xào thêm 3 phút. Rót 60 ml rượu vang trắng khô cho bay hơi cồn, đổ 1,5 lít nước lọc cùng 3 g muối ăn vào, đun sôi rồi hạ lửa nhỏ ninh 25 phút; lọc lấy phần nước dùng trong và giữ nóng trên bếp.', NULL, 25),
('imp-38137393c32d70d7_v4_step_3', 'imp-38137393c32d70d7', 3, 'cook', 'Áp chảo nhanh phần tôm nguyên con', 'Trong lúc ninh nước dùng, làm nóng chảo với 10 ml dầu ô liu nguyên chất trên lửa vừa-lớn. Thả phần tôm nguyên con vào áp chảo mỗi mặt 1–1,5 phút đến khi thịt tôm chuyển hồng đục, săn chắc và chín hoàn toàn thì gắp ra đĩa riêng cùng một ít lá ngò tây băm.', NULL, 3),
('imp-38137393c32d70d7_v4_step_4', 'imp-38137393c32d70d7', 4, 'cook', 'Phi hành tỏi và rang hạt gạo Arborio', 'Đun nóng 10 ml dầu ô liu nguyên chất còn lại trong chảo sâu lòng trên lửa vừa, cho phần hành tím và tỏi băm vào phi 4 phút đến khi hành mềm trong. Đổ 320 g gạo Ý Arborio (không vo) vào đảo liên tục 2 phút đến khi hạt gạo nóng ran và viền gạo hơi trong lại.', 'Bước rang gạo giúp lớp ngoài hạt gạo săn chắc, nhờ vậy hạt cơm dẻo sánh bên ngoài mà không bị nát vụn khi châm nước dùng.', 6),
('imp-38137393c32d70d7_v4_step_5', 'imp-38137393c32d70d7', 5, 'cook', 'Châm nước dùng tôm nấu chín cơm từng muôi', 'Rót 80 ml rượu vang trắng khô còn lại vào chảo gạo, đảo đều đến khi rượu bay hơi hết. Sau đó châm từng muôi nước dùng tôm đang nóng sủi tăm vào chảo, khuấy đều tay và đợi gạo hút gần cạn nước mới châm tiếp muôi kế tiếp; tiếp tục nấu khoảng 18 phút đến khi hạt gạo chín mềm sánh nhưng còn sần nhẹ ở lõi.', 'Luôn giữ nước dùng tôm ở trạng thái nóng sủi tăm khi châm vào gạo để quá trình chín diễn ra liên tục và hạt gạo không bị sượng.', 18),
('imp-38137393c32d70d7_v4_step_6', 'imp-38137393c32d70d7', 6, 'cook', 'Nấu chín tôm băm cùng cơm risotto', 'Khi gạo gần đạt độ chín mong muốn, thả phần thịt tôm băm nhỏ vào chảo cơm, đảo nhẹ tay thêm 2–3 phút đến khi tôm chuyển màu hồng đục chín hoàn toàn và hòa quyện vào nền cơm sánh.', NULL, 3),
('imp-38137393c32d70d7_v4_step_7', 'imp-38137393c32d70d7', 7, 'finish', 'Đánh bơ tạo độ bóng kem và trình bày', 'Tắt bếp ngay, thả 30 g bơ lạt lạnh cắt khối cùng phần lá ngò tây tươi băm nhỏ còn lại vào chảo, khuấy nhanh và dứt khoát khoảng 30 giây cho bơ tan nhũ hóa thành lớp kem bóng mượt. Nêm lại với 3 g muối ăn và 2 g tiêu đen xay cho vừa miệng, múc risotto ra đĩa sâu lòng, xếp tôm áp chảo lên trên và thưởng thức nóng.', NULL, NULL),
('imp-e61010e240534690_v4_step_1', 'imp-e61010e240534690', 1, 'prep', 'Làm sạch và cắt khoanh mực ống', 'Rửa sạch 600 g mực ống dưới vòi nước lạnh, rút bỏ túi mực, nội tạng, mai cứng và mắt răng mực. Thái thân mực thành các khoanh tròn dày đều 1 cm, phần râu cắt làm đôi rồi dùng khăn giấy thấm thật khô nước.', 'Thái khoanh mực dày đều nhau giúp mực chín đồng thời, tránh miếng nhỏ bị quắt trong khi miếng dày chưa mềm.', NULL),
('imp-e61010e240534690_v4_step_2', 'imp-e61010e240534690', 2, 'prep', 'Chuẩn bị tỏi, ớt và ngò tây', 'Bóc vỏ tỏi tươi, tách bỏ phần mầm xanh ở giữa rồi băm nhỏ. Ớt tươi rửa sạch, giữ nguyên quả nếu muốn vị cay nhẹ dịu hoặc thái lát nếu thích cay rõ; ngò tây tươi rửa sạch, thấm ráo rồi băm nhuyễn.', NULL, NULL),
('imp-e61010e240534690_v4_step_3', 'imp-e61010e240534690', 3, 'cook', 'Phi thơm tỏi ớt và xào săn mực', 'Đun nóng 30 ml dầu ô liu nguyên chất trong chảo sâu lòng trên lửa vừa. Cho tỏi băm và ớt tươi vào phi thơm khoảng 1 phút cho dậy hương (không để tỏi cháy vàng), rồi thả mực vào đảo nhanh tay 2 phút đến khi mực săn lại và chuyển màu trắng đục.', NULL, 3),
('imp-e61010e240534690_v4_step_4', 'imp-e61010e240534690', 4, 'cook', 'Khử mùi bằng rượu vang trắng khô', 'Vặn lửa lớn, rót 100 ml rượu vang trắng khô vào chảo mực và đun sôi mạnh khoảng 2–3 phút để cồn bay hơi hoàn toàn, đồng thời giữ lại vị ngọt thơm đậm đà.', 'Để lửa lớn ngay khi rót rượu giúp hơi cồn thoát nhanh trong khi hương trái cây thanh nhẹ của vang ngấm vào từng khoanh mực.', 3),
('imp-e61010e240534690_v4_step_5', 'imp-e61010e240534690', 5, 'cook', 'Om mực cùng cà chua pelati trên lửa liu riu', 'Đổ 400 g cà chua lột vỏ đóng hộp (pelati) vào chảo, dùng muỗng gỗ dằm nát phần thịt cà chua, nêm 5 g muối ăn và 1,5 g tiêu đen xay. Hạ xuống lửa nhỏ, đậy nắp kín và om liu riu 12 phút đến khi mực mềm hẳn.', 'Kiểm tra độ mềm bằng nĩa sau 12 phút; nếu mực cỡ lớn hơi dày, có thể om thêm 3–4 phút cho đến khi thớ mực mềm tơi.', 12),
('imp-e61010e240534690_v4_step_6', 'imp-e61010e240534690', 6, 'finish', 'Mở nắp sánh sốt, rắc ngò tây và dọn nóng', 'Mở nắp chảo, tăng lên lửa vừa-lớn đun thêm 3–4 phút cho nước sốt cà chua sánh đặc lại nhưng vẫn đủ độ ẩm để chấm bánh mì. Nếm lại gia vị cho vừa miệng, tắt bếp, rắc ngò tây tươi băm nhỏ lên trên, đảo nhẹ và dọn dùng nóng ngay.', NULL, NULL),
('imp-452ef6d0f8ec0de9_v4_step_1', 'imp-452ef6d0f8ec0de9', 1, 'prep', 'Làm sạch tôm và sơ chế tỏi ớt', 'Rửa sạch 350 g tôm tươi đã bóc vỏ, rạch nhẹ lưng lấy sạch chỉ đen rồi dùng khăn giấy thấm thật khô nước. Băm nhỏ tỏi tươi, thái lát ớt tươi đỏ và rửa sạch lá húng quế Tây để ráo.', 'Thấm khô tôm trước khi thả vào sốt sẽ giúp nước sốt cà chua giữ được độ sánh đậm mà không bị loãng nước.', NULL),
('imp-452ef6d0f8ec0de9_v4_step_2', 'imp-452ef6d0f8ec0de9', 2, 'cook', 'Phi thơm tỏi ớt trong dầu ô liu', 'Làm nóng chảo sâu lòng với 20 ml dầu ô liu nguyên chất trên lửa vừa, thả tỏi băm và ớt tươi vào đảo liên tục khoảng 1 phút cho dậy mùi thơm ấm mà không để tỏi chuyển vàng nâu.', NULL, 1),
('imp-452ef6d0f8ec0de9_v4_step_3', 'imp-452ef6d0f8ec0de9', 3, 'sauce', 'Nấu sánh sốt cà chua passata', 'Đổ 300 g cà chua nghiền nhuyễn (passata) cùng 50 ml nước lọc tráng lọ vào chảo. Nêm 3 g muối ăn và 1 g tiêu đen xay, khuấy đều và đun sôi lăn tăn trên lửa vừa khoảng 3 phút cho sốt hơi sánh lại.', 'Kiểm tra lại độ mặn trước khi cho tôm vào vì tôm biển vốn đã có vị mặn tự nhiên.', 3),
('imp-452ef6d0f8ec0de9_v4_step_4', 'imp-452ef6d0f8ec0de9', 4, 'cook', 'Om chín tới tôm tươi trong sốt cà chua', 'Thả tôm tươi vào chảo sốt đang sôi nhẹ, dàn đều cho tôm ngập trong nước sốt và om trên lửa vừa khoảng 4–5 phút, đảo nhẹ giữa chừng đến khi tôm uốn cong, chuyển màu đỏ cam và thịt săn đục chín hoàn toàn.', 'Không nấu tôm quá lâu vì tôm bóc vỏ chín rất nhanh, nấu quá 6 phút thịt tôm sẽ bị khô và mất độ giòn ngọt.', 5),
('imp-452ef6d0f8ec0de9_v4_step_5', 'imp-452ef6d0f8ec0de9', 5, 'finish', 'Trộn lá húng quế Tây và rưới dầu ô liu', 'Tắt bếp, xé nhỏ lá húng quế Tây tươi thả vào chảo tôm, đảo nhẹ cho lá héo dịu dậy hương. Múc tôm và sốt ra đĩa sâu lòng, rưới 5 ml dầu ô liu nguyên chất còn lại lên trên rồi thưởng thức nóng ngay.', NULL, NULL),
('imp-452ef6d0f8ec0de9_v4_step_6', 'imp-452ef6d0f8ec0de9', 6, 'finish', 'Thưởng thức cùng bánh mì nướng giòn', 'Dọn đĩa tôm om cà chua kèm các lát bánh mì nướng giòn hoặc bánh mì bơ tỏi ngay khi còn nóng ấm để chấm trọn phần nước sốt sánh thơm.', NULL, NULL),
('imp-f44be7e8c88c20d3_v4_step_1', 'imp-f44be7e8c88c20d3', 1, 'prep', 'Sơ chế rau củ và cắt khối cá hồi', 'Gọt vỏ khoai tây tươi và cắt hạt lựu 1,5 cm; cà rốt tươi thái lát mỏng; hành tây vàng băm nhỏ; ngò tây tươi và thì là tươi thái nhỏ. Cá hồi phi lê thấm khô, kiểm tra nhổ sạch xương dăm rồi cắt thành khối vuông 3 cm.', 'Cắt khoai tây kích thước đều nhau giúp khoai chín bở đồng thời, tạo độ sánh mượt tự nhiên cho nước súp.', NULL),
('imp-f44be7e8c88c20d3_v4_step_2', 'imp-f44be7e8c88c20d3', 2, 'cook', 'Xào mềm hành tây và rau củ với bơ lạt', 'Đun chảy 25 g bơ lạt trong nồi đáy dày trên lửa vừa. Thả hành tây băm vào xào dịu khoảng 4 phút cho trong mềm (không để cháy vàng), rồi thêm khoai tây và cà rốt vào đảo đều 2 phút cho rau củ ngấm bơ thơm.', NULL, 6),
('imp-f44be7e8c88c20d3_v4_step_3', 'imp-f44be7e8c88c20d3', 3, 'cook', 'Ninh mềm khoai tây và cà rốt trong nước dùng', 'Rót 900 ml nước dùng rau củ và nêm 3 g muối ăn vào nồi, đun sôi rồi hạ xuống lửa nhỏ, đậy nắp ninh liu riu khoảng 20 phút đến khi dùng nĩa xiên qua miếng khoai tây thấy mềm bở hoàn toàn.', NULL, 20),
('imp-f44be7e8c88c20d3_v4_step_4', 'imp-f44be7e8c88c20d3', 4, 'cook', 'Thả cá hồi nấu chín dịu trên lửa nhỏ', 'Nhẹ nhàng thả các khối cá hồi phi lê vào nồi súp, giữ lửa thật nhỏ và nấu khoảng 7 phút mà không khuấy mạnh tay để cá chín đục hoàn toàn, dễ tách thớ mà vẫn nguyên vẹn từng miếng.', 'Giữ lửa liu riu thay vì đun sôi mạnh sau khi cho cá vào giúp thịt cá hồi mềm mọng và không bị nát vụn trong nồi súp.', 7),
('imp-f44be7e8c88c20d3_v4_step_5', 'imp-f44be7e8c88c20d3', 5, 'sauce', 'Hòa kem tươi và nêm gia vị hoàn thiện', 'Từ từ rót 220 ml kem tươi vào nồi súp, khuấy thật nhẹ tay theo một chiều. Nêm 3 g muối ăn còn lại và 2 g tiêu đen xay, đun ấm thêm 2 phút trên lửa nhỏ rồi tắt bếp ngay khi mép nồi hơi lăn tăn.', 'Không đun sôi bùng sau khi đã cho kem tươi để tránh kem bị tách váng dầu.', 2),
('imp-f44be7e8c88c20d3_v4_step_6', 'imp-f44be7e8c88c20d3', 6, 'finish', 'Ủ ấm 5 phút và dọn súp nóng', 'Đậy nắp cho súp nghỉ 5 phút để hương vị hòa quyện sâu hơn. Múc súp cá hồi kem ra 4 tô sâu lòng, rắc 12 g ngò tây tươi và thì là tươi lên trên rồi dọn nóng cùng bánh mì nướng giòn.', NULL, NULL);
INSERT INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-e748a717f7250188_v4_step_1', 'imp-e748a717f7250188', 1, 'prep', 'Xử lý dưa leo giòn và rau xà lách', 'Dưa leo giòn rửa sạch, bổ đôi dọc rồi thái lát mỏng 0,5 cm. Cho dưa leo vào rổ, rắc 1 g muối ăn xóc nhẹ và để ráo 12 phút cho thoát bớt nước thừa, sau đó vẩy nhẹ cho khô. Xà lách tươi rửa sạch, vẩy thật ráo rồi xé miếng vừa ăn.', 'Xóc muối cho dưa leo ra nước trước khi trộn sẽ giúp đĩa salad giòn rụm và không bị chảy nước lõng bõng.', 12),
('imp-e748a717f7250188_v4_step_2', 'imp-e748a717f7250188', 2, 'marinate', 'Sơ chế và ướp cá hồi phi lê', 'Thấm khô 360 g cá hồi phi lê bằng khăn giấy, nhổ sạch xương dăm rồi cắt miếng dày khoảng 2,5 cm. Ướp đều các mặt cá với 1,5 g muối ăn, 1 g tiêu đen xay và 10 ml dầu ô liu nguyên chất trong 10 phút cho thấm vị.', NULL, 10),
('imp-e748a717f7250188_v4_step_3', 'imp-e748a717f7250188', 3, 'sauce', 'Đánh nhũ tương sốt chanh vàng dầu ô liu', 'Vắt chanh vàng tươi lấy nước cốt lọc bỏ hạt, cho vào chén cùng 30 ml dầu ô liu nguyên chất, 1,5 g muối ăn, 0,5 g tiêu đen xay còn lại và 15 g ngò tây tươi thái nhuyễn. Dùng phới lồng hoặc nĩa đánh đều tay đến khi hỗn hợp hơi sánh quyện thành dạng nhũ tương.', 'Đánh kỹ nước cốt chanh và dầu ô liu thành nhũ tương sánh nhẹ sẽ giúp sốt bám đều lên cá và rau thay vì đọng đáy đĩa.', NULL),
('imp-e748a717f7250188_v4_step_4', 'imp-e748a717f7250188', 4, 'cook', 'Áp chảo cá hồi chín tới và tách miếng', 'Đun nóng chảo chống dính với 5 ml dầu ô liu nguyên chất còn lại trên lửa vừa-lớn. Đặt các miếng cá hồi vào áp chảo mỗi mặt 2,5–3 phút đến khi mặt ngoài xém vàng đẹp và phần lõi thịt chuyển hồng đục chín hoàn toàn. Gắp cá ra đĩa để nguội bớt 5 phút rồi tách thành miếng vừa ăn.', 'Không đảo lật cá quá sớm hoặc nấu quá lâu để cá không bị nát và giữ được độ mềm ẩm tự nhiên.', 6),
('imp-e748a717f7250188_v4_step_5', 'imp-e748a717f7250188', 5, 'finish', 'Trình bày và trộn nhẹ salad cá hồi', 'Lót xà lách tươi xuống đáy đĩa rộng, xếp dưa leo đã ráo nước và các miếng cá hồi áp chảo lên trên. Rưới đều nước sốt chanh vàng dầu ô liu khắp mặt đĩa rồi dùng hai muỗng trộn thật nhẹ tay để rau thấm sốt mà cá không bị vỡ.', NULL, NULL),
('imp-e748a717f7250188_v4_step_6', 'imp-e748a717f7250188', 6, 'finish', 'Trang trí lá bạc hà và thưởng thức mát', 'Rắc thêm vài lá bạc hà tươi xé nhỏ lên trên đĩa salad (tùy thích) và thưởng thức ngay khi rau còn giòn mát, hoặc làm lạnh nhanh 15 phút trong ngăn mát trước khi dọn.', NULL, NULL),
('imp-957396bc647d3798_v4_step_1', 'imp-957396bc647d3798', 1, 'prep', 'Tách nhánh bông cải xanh và sơ chế rau củ', 'Tách 600 g bông cải xanh thành các nhánh nhỏ vừa ăn, gọt sạch lớp vỏ xơ cứng ở cuống rồi rửa sạch. Cà chua bi bổ đôi, tỏi tươi đập dập, ớt tươi thái lát và 10 g ngò tây tươi thái nhỏ.', NULL, NULL),
('imp-957396bc647d3798_v4_step_2', 'imp-957396bc647d3798', 2, 'cook', 'Chần nhanh bông cải giữ màu xanh giòn', 'Đun sôi 1150 ml nước lọc với 4 g muối ăn, thả bông cải xanh vào chần khoảng 3 phút cho vừa chín tới rồi vớt ngay ra rổ để thật ráo nước (có thể xả nhanh qua nước lạnh để giữ màu xanh tươi sáng).', 'Chần sơ trước giúp bông cải chín đều từ thân tới bông mà không bị sậm màu khi om cùng cà chua.', 3),
('imp-957396bc647d3798_v4_step_3', 'imp-957396bc647d3798', 3, 'cook', 'Phi thơm tỏi với dầu ô liu và nấu cà chua', 'Làm nóng 45 ml dầu ô liu nguyên chất trong chảo lớn trên lửa vừa-nhỏ, cho tỏi đập dập vào phi thơm vàng nhẹ khoảng 2 phút. Thêm cà chua bi bổ đôi vào, tăng lên lửa vừa và đảo khoảng 6 phút đến khi cà chua mềm ra nước tạo sốt sánh.', 'Phi tỏi đập dập ở lửa vừa-nhỏ giúp dầu ô liu thấm trọn hương tỏi dịu mà không bị cháy đắng.', 8),
('imp-957396bc647d3798_v4_step_4', 'imp-957396bc647d3798', 4, 'cook', 'Om bông cải xanh thấm sốt cà chua', 'Cho toàn bộ bông cải xanh đã chần vào chảo sốt cà chua, đảo nhẹ cho sốt phủ đều các nhánh bông cải. Rưới thêm 50 ml nước lọc nóng, đậy nắp và om lửa nhỏ khoảng 8 phút đến khi bông cải mềm ngọt và ngấm đậm vị sốt.', 'Chỉ thêm lượng nước vừa đủ giữ ẩm đáy chảo để món om có lớp sốt sánh bám rau chứ không bị loãng thành canh.', 8),
('imp-957396bc647d3798_v4_step_5', 'imp-957396bc647d3798', 5, 'cook', 'Thêm ớt tươi và nêm gia vị', 'Mở nắp chảo, thả ớt tươi thái lát (nếu dùng) vào đảo đều 1 phút. Nêm 2 g muối ăn còn lại và 1,5 g tiêu đen xay cho vừa miệng.', NULL, NULL),
('imp-957396bc647d3798_v4_step_6', 'imp-957396bc647d3798', 6, 'finish', 'Trình bày và dọn ăn nóng', 'Gắp bỏ xác tỏi đập dập nếu muốn, bày bông cải xanh om cà chua ra đĩa sâu lòng, rắc ngò tây tươi thái nhỏ lên trên rồi dùng nóng hoặc ấm kèm món chính.', NULL, NULL),
('imp-c98aa0f1ffe2f469_v4_step_1', 'imp-c98aa0f1ffe2f469', 1, 'prep', 'Thấm khô sườn non và sơ chế rau củ', 'Rửa sạch 1,3 kg sườn non heo, chặt miếng vừa ăn rồi dùng khăn giấy thấm thật khô để sườn dễ xém vàng. Hành tây vàng và cà rốt tươi thái hạt lựu; tỏi tươi bóc vỏ để nguyên tép; lá nguyệt quế khô xé nhẹ bằng tay.', 'Thấm thật ráo nước trên mặt sườn trước khi áp chảo giúp miếng sườn vàng nâu thơm phức thay vì bị hấp hơi ra nước.', NULL),
('imp-c98aa0f1ffe2f469_v4_step_2', 'imp-c98aa0f1ffe2f469', 2, 'cook', 'Phi thơm thảo mộc và áp chảo vàng sườn non', 'Làm nóng 45 ml dầu ô liu nguyên chất trong nồi đáy dày trên lửa vừa, thả tỏi nguyên tép, thảo mộc Ý khô và lá nguyệt quế khô vào phi khoảng 1 phút cho dậy hương rồi gắp bỏ tỏi ra ngoài. Cho sườn non vào áp chảo khoảng 8 phút, trở đều các mặt đến khi sườn săn vàng đẹp.', 'Gắp tỏi ra trước khi áp chảo thịt lâu giúp nồi sốt không bị ám vị đắng do tỏi cháy.', 9),
('imp-c98aa0f1ffe2f469_v4_step_3', 'imp-c98aa0f1ffe2f469', 3, 'cook', 'Xào mềm hành tây, cà rốt và khử vang trắng', 'Thêm hành tây và cà rốt thái hạt lựu vào nồi đảo cùng sườn khoảng 10 phút trên lửa vừa không đậy nắp đến khi hành mềm thơm. Rưới 120 ml rượu vang trắng khô vào, vặn lửa lớn đun 4 phút đồng thời cạo nhẹ đáy nồi cho cồn bay hơi hoàn toàn.', NULL, 14),
('imp-c98aa0f1ffe2f469_v4_step_4', 'imp-c98aa0f1ffe2f469', 4, 'cook', 'Om sườn với cà chua đóng hộp 45 phút', 'Nếu trong nồi còn quá nhiều mỡ tiết ra thì chắt bớt, sau đó đổ 500 g cà chua đóng hộp vào cùng 8 g muối ăn và 2,5 g tiêu đen xay. Đảo đều, hạ xuống lửa nhỏ, đậy nắp kín và om liu riu khoảng 45 phút đến khi thịt sườn chín mềm và dễ dàng tách khỏi xương; thỉnh thoảng đảo và châm chút nước lọc nóng nếu sốt quá đặc.', 'Giữ lửa thật nhỏ và đậy kín nắp giúp hơi nóng tuần hoàn làm sườn mềm róc xương mà sốt cà chua không bị bén cháy đáy nồi.', 45),
('imp-c98aa0f1ffe2f469_v4_step_5', 'imp-c98aa0f1ffe2f469', 5, 'cook', 'Thêm quả ô liu đen và sánh sốt', 'Mở nắp, thả 120 g quả ô liu đen bỏ hạt vào đảo đều và nấu thêm 3 phút trên lửa vừa cho ô liu thấm vị sốt cà chua và nước sốt đạt độ sánh đậm mong muốn.', NULL, 3),
('imp-c98aa0f1ffe2f469_v4_step_6', 'imp-c98aa0f1ffe2f469', 6, 'finish', 'Vớt lá nguyệt quế và thưởng thức nóng', 'Vớt bỏ lá nguyệt quế khô, nêm lại gia vị cho vừa miệng rồi múc sườn om sốt cà chua ra đĩa sâu lòng để dùng nóng cùng bánh mì giòn hoặc cơm trắng.', NULL, NULL),
('imp-a286f8724d79a504_v4_step_1', 'imp-a286f8724d79a504', 1, 'prep', 'Chọn và thái lát cà chua chín mọng', 'Chọn 4 quả cà chua chín mọng để ở nhiệt độ phòng cho giữ trọn mùi thơm, rửa sạch, bỏ phần cuống cứng rồi thái thành các lát tròn ngang dày đều khoảng 0,8 cm.', 'Không dùng cà chua vừa lấy từ tủ lạnh vì hơi lạnh làm cấu trúc thịt cà chua bị bở và giảm hương vị tự nhiên.', NULL),
('imp-a286f8724d79a504_v4_step_2', 'imp-a286f8724d79a504', 2, 'prep', 'Để ráo và cắt lát phô mai Mozzarella tươi', 'Vớt 170 g phô mai Mozzarella tươi ra khỏi nước ngâm, đặt lên rây hoặc khăn giấy sạch để ráo khoảng 5 phút rồi cắt thành từng lát có độ dày tương đương lát cà chua.', NULL, 5),
('imp-a286f8724d79a504_v4_step_3', 'imp-a286f8724d79a504', 3, 'prep', 'Băm nhuyễn tỏi và xé lá húng quế Tây', 'Băm thật nhuyễn tỏi tươi và dùng tay xé nhẹ 12 g lá húng quế Tây tươi thành miếng vừa ăn để giữ mùi thơm tinh dầu mà không làm dập thâm lá.', 'Xé lá húng quế bằng tay thay vì thái dao kim loại giúp lá giữ màu xanh tươi lâu hơn.', NULL),
('imp-a286f8724d79a504_v4_step_4', 'imp-a286f8724d79a504', 4, 'finish', 'Xếp xen kẽ cà chua và phô mai ra đĩa', 'Xếp xen kẽ từng lát cà chua chín mọng với lát phô mai Mozzarella tươi thành vòng tròn hoặc hàng đều đặn trên đĩa phẳng lớn sao cho các lát hơi gối lên nhau.', NULL, NULL),
('imp-a286f8724d79a504_v4_step_5', 'imp-a286f8724d79a504', 5, 'finish', 'Rắc muối, tiêu, tỏi và rưới dầu ô liu', 'Rắc đều 3 g muối ăn và 1 g tiêu đen xay lên mặt cà chua và phô mai, tiếp tục rắc tỏi tươi băm nhuyễn và lá húng quế Tây tươi lên trên. Rưới đều 40 ml dầu ô liu nguyên chất phủ một lớp mỏng bóng mượt.', 'Nêm muối trực tiếp lên cà chua tươi là bước quan trọng giúp kéo vị ngọt dịu tự nhiên của cà chua hòa quyện với độ béo của phô mai.', NULL),
('imp-a286f8724d79a504_v4_step_6', 'imp-a286f8724d79a504', 6, 'finish', 'Hoàn thiện với giấm Balsamic và dùng ngay', 'Rưới thêm 15 ml giấm Balsamic Ý (tùy thích) lên trên mặt đĩa rồi để thấm nhẹ 2–3 phút và thưởng thức ngay ở nhiệt độ phòng.', NULL, 3),
('imp-83ed31fc537569a6_v4_step_1', 'imp-83ed31fc537569a6', 1, 'prep', 'Chần vắt rau bina và xào nhân thơm bơ tỏi', 'Đun sôi 1 lít nước lọc, chần sơ 350 g rau bina tươi trong 1–2 phút rồi vớt ra để nguội và vắt thật kiệt nước. Làm nóng 15 ml dầu ô liu nguyên chất và 15 g bơ lạt trong chảo trên lửa vừa, phi thơm tỏi tươi băm nhỏ, cho 2/3 lượng rau bina đã vắt vào xào 3 phút cùng 2 g muối ăn và 1 g tiêu đen xay rồi trút ra đĩa.', 'Vắt thật khô rau bina sau khi chần giúp phần nhân không bị ra nước làm bung cuộn thịt bò khi áp chảo.', 5),
('imp-83ed31fc537569a6_v4_step_2', 'imp-83ed31fc537569a6', 2, 'prep', 'Sơ chế rau củ và dần mỏng thịt bò', 'Thái hạt lựu cà chua chín tươi, băm nhỏ hành tím; cà rốt tươi chia 1/3 băm nhỏ và 2/3 thái hạt lựu vừa. Trải 8 lát thịt bò thái lát mỏng lên thớt, dùng búa dần nhẹ cho thịt phẳng đều; đặt lên mỗi lát 1 lát phô mai Mozzarella, một ít cà rốt băm nhỏ và phần rau bina đã xào.', NULL, NULL),
('imp-83ed31fc537569a6_v4_step_3', 'imp-83ed31fc537569a6', 3, 'prep', 'Cuộn chặt và cố định cuộn bò involtini', 'Gập nhẹ hai mép bên của lát thịt bò vào trong rồi cuộn tròn thật chắc tay, dùng chỉ nấu ăn buộc gọn hoặc ghim cố định bằng tăm nhọn để nhân phô mai không chảy tràn ra ngoài.', 'Gập hai mép ngang vào trước khi cuộn giúp giữ kín phô mai Mozzarella bên trong khi áp chảo và om.', NULL),
('imp-83ed31fc537569a6_v4_step_4', 'imp-83ed31fc537569a6', 4, 'cook', 'Áp chảo vàng các mặt cuộn bò và khử vang trắng', 'Đun chảy 25 g bơ lạt còn lại cùng 20 ml dầu ô liu nguyên chất trong chảo sâu lòng trên lửa vừa-lớn. Xếp các cuộn thịt bò vào áp chảo khoảng 7 phút, trở đều các mặt cho vàng thơm. Rót 80 ml rượu vang trắng khô vào đun sôi 2 phút cho cồn bay hơi hoàn toàn.', 'Áp chảo phần mép gấp xuống mặt chảo trước tiên giúp khóa kín cuộn thịt bò gọn đẹp.', 9),
('imp-83ed31fc537569a6_v4_step_5', 'imp-83ed31fc537569a6', 5, 'cook', 'Om cuộn bò với cà chua, hành tím và cà rốt', 'Thả hành tím băm và cà chua chín tươi thái hạt lựu vào chảo cùng 3 g muối ăn và 1 g tiêu đen xay còn lại. Đậy nắp, hạ xuống lửa nhỏ và om liu riu 15 phút. Sau đó thêm phần cà rốt thái hạt lựu vào om tiếp 5 phút, rồi thả 1/3 lượng rau bina còn lại vào nấu thêm 3 phút cho sốt sánh đậm và rau chín quyện.', NULL, 23),
('imp-83ed31fc537569a6_v4_step_6', 'imp-83ed31fc537569a6', 6, 'finish', 'Tháo dây buộc, cắt khoanh và dọn nóng', 'Tắt bếp, gắp các cuộn thịt bò ra thớt tháo bỏ dây buộc hoặc tăm, cắt vát làm đôi nếu thích rồi xếp ra đĩa sâu lòng. Chan phần nước sốt cà chua rau củ nóng hổi lên trên và dùng ngay.', NULL, NULL),
('imp-a92103c19952bcf0_v4_step_1', 'imp-a92103c19952bcf0', 1, 'prep', 'Chuẩn bị chanh vàng và sơ chế ức gà', 'Rửa sạch 3 quả chanh vàng tươi, bào mịn lấy khoảng 1 muỗng canh lớp vỏ vàng bên ngoài (tránh phần cùi trắng bị đắng) để riêng, sau đó vắt lấy nước cốt chanh lọc bỏ hạt. Cắt 650 g ức gà phi lê thành các miếng vừa ăn dày khoảng 1,8–2 cm và thấm khô.', 'Cắt miếng ức gà dày đều nhau giúp thịt chín thấu bên trong mà lớp vỏ ngoài không bị cháy.', NULL),
('imp-a92103c19952bcf0_v4_step_2', 'imp-a92103c19952bcf0', 2, 'marinate', 'Ướp thịt gà với nước cốt chanh và thảo mộc', 'Pha nước ướp gồm nước cốt chanh vàng, 50 ml rượu vang trắng khô, tỏi tươi cắt đôi, 3 g thảo mộc Ý khô và 4 g muối ăn. Trộn đều ức gà trong tô nước ướp, bọc kín rồi để ngăn mát tủ lạnh khoảng 60 phút cho thấm hương chanh dịu.', 'Không ướp ức gà trong nước chanh quá 2 giờ vì axit sẽ làm biến tính bề mặt khiến thịt gà bị bở.', 60),
('imp-a92103c19952bcf0_v4_step_3', 'imp-a92103c19952bcf0', 3, 'prep', 'Trộn lớp áo bột chiên xù Parmesan', 'Trộn đều 140 g bột chiên xù, 50 g phô mai Parmesan bào mịn, phần vỏ chanh vàng bào sợi, 10 g ngò tây tươi băm nhỏ, 4 g muối ăn còn lại và 1,5 g tiêu đen xay trong một đĩa trẹt rộng.', NULL, NULL),
('imp-a92103c19952bcf0_v4_step_4', 'imp-a92103c19952bcf0', 4, 'prep', 'Áo bột từng miếng ức gà đã ráo nước ướp', 'Làm nóng trước lò nướng ở 180°C và lót giấy nến lên khay nướng. Gắp từng miếng ức gà ra để ráo bớt nước ướp (không rửa lại), đặt vào đĩa bột chiên xù và ấn nhẹ hai mặt cho lớp bột bám kín đều.', NULL, NULL),
('imp-a92103c19952bcf0_v4_step_5', 'imp-a92103c19952bcf0', 5, 'cook', 'Chiên vàng hai mặt rồi nướng chín thấu trong lò', 'Đun nóng 180 ml dầu ô liu trong chảo lớn trên lửa vừa-lớn. Chiên từng mẻ gà mỗi mặt khoảng 3 phút cho lớp vỏ bột vàng giòn đẹp mắt rồi vớt ra giấy thấm dầu. Xếp gà lên khay nướng và cho vào lò ở 180°C nướng thêm 18–20 phút đến khi thịt gà chín trắng hoàn toàn bên trong, xiên vào không còn nước hồng.', 'Chiên nhanh tạo lớp vỏ giòn rồi nướng lò giúp thịt ức gà chín đều mọng nước và giảm lượng dầu thấm vào thịt.', 24),
('imp-a92103c19952bcf0_v4_step_6', 'imp-a92103c19952bcf0', 6, 'finish', 'Rắc ngò tây tươi và thưởng thức nóng', 'Xếp gà chiên chanh vàng ra đĩa, rắc nốt 5 g ngò tây tươi băm nhỏ còn lại lên trên rồi dọn dùng nóng ngay cùng salad rau xanh.', NULL, NULL),
('imp-afdcd866c1f92192_v4_step_1', 'imp-afdcd866c1f92192', 1, 'marinate', 'Thấm khô và ướp phi lê cá thịt trắng', 'Rửa sạch 600 g phi lê cá thịt trắng dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô. Rắc đều 2,5 g muối ăn và 1,5 g tiêu đen xay lên cả hai mặt miếng cá, để nghỉ 10 phút cho thịt cá săn và thấm gia vị.', 'Thấm thật khô bề mặt cá trước khi ướp muối tiêu giúp thịt cá săn chắc và giữ nguyên thớ đẹp khi om.', 10),
('imp-afdcd866c1f92192_v4_step_2', 'imp-afdcd866c1f92192', 2, 'prep', 'Sơ chế cà chua bi, hành tây và tỏi ớt', 'Cà chua bi rửa sạch, bổ đôi; hành tây vàng thái hạt lựu nhỏ; tỏi tươi thái lát mỏng; ớt tươi đỏ thái lát; ngò tây tươi băm nhỏ và chia làm hai phần.', NULL, NULL),
('imp-afdcd866c1f92192_v4_step_3', 'imp-afdcd866c1f92192', 3, 'cook', 'Phi thơm tỏi hành và nấu mềm cà chua bi', 'Làm nóng 35 ml dầu ô liu nguyên chất trong chảo sâu lòng rộng trên lửa vừa. Cho tỏi thái lát và ớt tươi vào đảo 1–2 phút đến khi vừa dậy mùi thơm (không để tỏi cháy vàng). Thêm hành tây, lá nguyệt quế khô và 2,5 g muối ăn còn lại vào xào 3 phút cho hành mềm trong, rồi cho cà chua bi và quả ô liu đen vào đảo nhẹ thêm 3 phút.', 'Xào tỏi thái lát trên lửa vừa giúp tỏi tiết mùi thơm dịu mà không bị cháy đắng.', 8),
('imp-afdcd866c1f92192_v4_step_4', 'imp-afdcd866c1f92192', 4, 'cook', 'Nấu nước dùng rượu vang trắng cho sôi', 'Rót 60 ml rượu vang trắng khô vào chảo, đun sôi 1 phút cho cồn bay hơi hết. Đổ tiếp 250 ml nước lọc và một nửa lượng ngò tây tươi băm vào chảo, đun sôi trở lại trên lửa vừa.', NULL, 2),
('imp-afdcd866c1f92192_v4_step_5', 'imp-afdcd866c1f92192', 5, 'cook', 'Om dịu phi lê cá chín tới trong nước dùng', 'Nhẹ nhàng xếp 4 miếng phi lê cá thành một lớp vào giữa chảo (mặt da hướng xuống dưới nếu có), gạt rau củ sang xung quanh và múc nước dùng rưới nhẹ lên mặt cá. Hạ xuống lửa nhỏ, đậy nắp om liu riu khoảng 7 phút cho thịt cá chuyển trắng đục hoàn toàn và dễ tách thớ khi ấn nhẹ bằng nĩa.', 'Không đảo lật mạnh miếng cá khi đang om để giữ phi lê nguyên vẹn, đẹp mắt và không bị nát.', 7),
('imp-afdcd866c1f92192_v4_step_6', 'imp-afdcd866c1f92192', 6, 'finish', 'Ủ ấm 3 phút, rắc ngò tây và dùng nóng', 'Tắt bếp, giữ nguyên nắp thêm 3 phút cho cá ngấm vị rồi gắp bỏ lá nguyệt quế khô. Múc cá ra 4 bát sâu lòng, chan nước dùng cà chua ô liu lên trên, rắc phần ngò tây tươi còn lại và dùng nóng kèm bánh mì giòn.', NULL, NULL),
('imp-6d26ce6b0af4fb79_v4_step_1', 'imp-6d26ce6b0af4fb79', 1, 'cook', 'Làm chín rau bina bằng độ ẩm tự nhiên và vắt kiệt nước', 'Nhặt và rửa thật sạch 600 g rau bina tươi dưới vòi nước, không cần vẩy quá khô mà cho thẳng rau còn ướt vào nồi to, đậy nắp đun lửa vừa 4–5 phút đến khi rau xẹp mềm. Vớt rau ra rổ để hơi nguội rồi dùng tay vắt thật kiệt hết nước thừa và thái thô.', 'Vắt kiệt nước rau bina sau khi hấp chín là bước quan trọng nhất để món om giữ độ kem sánh đặc chứ không bị tách nước.', 5),
('imp-6d26ce6b0af4fb79_v4_step_2', 'imp-6d26ce6b0af4fb79', 2, 'cook', 'Xào dịu hành tây và đảo thơm rau bina', 'Làm nóng 15 ml dầu ô liu nguyên chất trong chảo trên lửa thật nhỏ, cho hành tây vàng băm nhuyễn vào xào khoảng 8 phút đến khi hành mềm trong suốt mà không chuyển vàng. Thả rau bina đã vắt kiệt vào đảo nhanh 1 phút cho thấm hương hành rồi tạm tắt bếp.', 'Xào hành tây ở lửa thật nhỏ để hành tiết vị ngọt tự nhiên và trong mềm mà không bị cháy sém làm xỉn màu sốt trắng.', 9),
('imp-6d26ce6b0af4fb79_v4_step_3', 'imp-6d26ce6b0af4fb79', 3, 'sauce', 'Nấu nền bột bơ và khuấy mịn sốt Béchamel', 'Đặt nồi nhỏ lên lửa nhỏ, cho 25 g bơ lạt vào đun chảy hoàn toàn rồi thêm 25 g bột mì đa dụng, khuấy liên tục bằng phới lồng trong 1–2 phút đến khi bột quyện bơ sủi bọt nhẹ mà không ngả nâu. Rót từ từ 250 ml sữa tươi không đường vào, vừa rót vừa khuấy đều tay để hỗn hợp hòa tan hoàn toàn không vón cục.', 'Rót sữa từng ít một ở bước đầu và khuấy liên tục bằng phới lồng giúp sốt Béchamel láng mịn tuyệt đối.', 3),
('imp-6d26ce6b0af4fb79_v4_step_4', 'imp-6d26ce6b0af4fb79', 4, 'sauce', 'Nấu sánh sốt và hòa tan phô mai Parmesan', 'Tiếp tục đun sốt trên lửa nhỏ khoảng 5 phút, khuấy đều tay đến khi sốt sánh mượt phủ đều mặt muỗng. Nêm 4 g muối ăn, 1 g tiêu đen xay và 0,5 g nhục đậu khấu xay, sau đó nhấc nồi khỏi bếp và khuấy tan 30 g phô mai Parmesan bào mịn.', NULL, 5),
('imp-6d26ce6b0af4fb79_v4_step_5', 'imp-6d26ce6b0af4fb79', 5, 'finish', 'Trộn quyện rau bina vào sốt kem Béchamel', 'Cho toàn bộ rau bina xào hành tây vào nồi sốt kem Béchamel, trộn đều nhẹ tay cho từng lá rau phủ kín lớp sốt trắng sánh mịn và nêm lại độ mặn vừa khẩu vị.', NULL, NULL),
('imp-6d26ce6b0af4fb79_v4_step_6', 'imp-6d26ce6b0af4fb79', 6, 'finish', 'Dọn nóng ngay khi sốt còn sánh mượt', 'Múc rau bina om sốt kem ra đĩa sâu lòng và dùng nóng ngay kèm các món thịt nướng hoặc cá áp chảo.', NULL, NULL),
('imp-bd34e8ea2eaa1cd4_v4_step_1', 'imp-bd34e8ea2eaa1cd4', 1, 'prep', 'Sơ chế bắp cải, rau củ và thịt xông khói', 'Thái sợi bắp cải xanh dày 1 cm; hành tây vàng thái lát mỏng; cần tây tươi và cà rốt tươi thái khoanh mỏng; khoai tây tươi cắt hạt lựu 1,5 cm; tỏi tươi băm nhỏ; ngò tây tươi thái nhỏ. Thịt ba chỉ xông khói thái hạt lựu cỡ 1 cm; đậu trắng đóng hộp tráng nước và để ráo.', NULL, NULL),
('imp-bd34e8ea2eaa1cd4_v4_step_2', 'imp-bd34e8ea2eaa1cd4', 2, 'cook', 'Xào thơm thịt xông khói và nền rau củ', 'Đun chảy 30 g bơ lạt cùng 30 ml dầu ô liu nguyên chất trong nồi súp lớn trên lửa vừa. Cho thịt ba chỉ xông khói, hành tây, cần tây, cà rốt, khoai tây và tỏi băm vào xào đảo khoảng 4 phút cho thịt tiết mỡ thơm và rau củ hơi dịu mềm.', 'Xào thịt ba chỉ xông khói cùng rau củ ngay từ đầu giúp hương khói đậm đà thấm đều vào nền nước dùng.', 4),
('imp-bd34e8ea2eaa1cd4_v4_step_3', 'imp-bd34e8ea2eaa1cd4', 3, 'cook', 'Om xẹp bắp cải với ngò tây và thảo mộc', 'Cho bắp cải xanh thái sợi, ngò tây tươi và 2 g thảo mộc Ý khô vào nồi cùng 200 ml nước dùng gà, đậy nắp nấu trên lửa vừa khoảng 5 phút cho bắp cải hơi xẹp xuống và ngấm vị.', NULL, 5),
('imp-bd34e8ea2eaa1cd4_v4_step_4', 'imp-bd34e8ea2eaa1cd4', 4, 'cook', 'Ninh mềm đậu trắng và rau củ 30 phút', 'Đổ đậu trắng đóng hộp và 500 ml nước dùng gà còn lại vào nồi, nêm 2 g muối ăn và 1,5 g tiêu đen xay. Đun sôi rồi hạ xuống lửa nhỏ, đậy nắp ninh liu riu khoảng 30 phút cho khoai tây, bắp cải và đậu trắng chín bở hòa quyện vị ngọt.', 'Nêm muối nhẹ tay lúc đầu và nêm lại cuối cùng vì thịt ba chỉ xông khói và phô mai Parmesan vốn đã có độ mặn.', 30),
('imp-bd34e8ea2eaa1cd4_v4_step_5', 'imp-bd34e8ea2eaa1cd4', 5, 'cook', 'Luộc riêng nui Ý hạt ngắn al dente', 'Trong lúc ninh súp, đun sôi 1 lít nước lọc với 3 g muối ăn trong nồi riêng. Cho 120 g nui Ý hạt ngắn (nếu dùng) vào luộc khoảng 8 phút đến độ chín al dente rồi vớt ra để ráo.', 'Luộc nui ở nồi riêng thay vì thả trực tiếp vào súp giúp nước súp thanh trong và nui không hút cạn nước dùng.', NULL),
('imp-bd34e8ea2eaa1cd4_v4_step_6', 'imp-bd34e8ea2eaa1cd4', 6, 'finish', 'Chia bát, chan súp nóng và rắc Parmesan', 'Nếm lại nồi súp cho vừa miệng. Chia nui Ý ra 4 tô sâu lòng, chan súp bắp cải đậu trắng nóng hổi lên trên, rắc 25 g phô mai Parmesan bào mịn và thưởng thức ngay kèm bánh mì giòn.', NULL, NULL);
